def _loaded_chat_template() -> Optional[str]:
    """Chat template of the currently loaded GGUF model, if any."""
    try:
        return get_llama_cpp_backend().chat_template
    except Exception:
        return None


def _template_raise_message(error_text: str, chat_template: Optional[str]) -> Optional[str]:
    """A chat-template raise_exception message to surface, but only when it appears
    verbatim in chat_template (simple substring check), so we never leak arbitrary
    llama-server text. Anchors on llama.cpp's "Jinja Exception:" prefix."""
    if not chat_template:
        return None
    marker = "Jinja Exception:"
    idx = error_text.find(marker)
    if idx == -1:
        return None
    candidate = error_text[idx + len(marker) :]
    # llama-server appends JSON after the message; cut at the first boundary.
    for stop in ('"', "\n"):
        cut = candidate.find(stop)
        if cut != -1:
            candidate = candidate[:cut]
    candidate = candidate.strip()
    return candidate if candidate and candidate in chat_template else None


_LOST_CONNECTION_MSG = (
    "Lost connection to the model server. It may have crashed -- try reloading the model."
)


_OVERSIZE_TOKENS_RE = _re.compile(
    r"request \((\d+) tokens?\) exceeds the available context size \((\d+) tokens?\)"
)
_LLAMA_CLIENT_ERROR_RE = _re.compile(r"llama-server returned 4\d\d: (.*)", _re.DOTALL)


def _friendly_error(exc: Exception) -> str:
    """Extract a user-friendly message from known llama-server errors."""
    if isinstance(exc, context_refusal.ContextBudgetExceeded):
        return str(exc)
    if isinstance(exc, httpx.ReadTimeout):
        if "stopped producing tokens" in str(exc).lower():
            return (
                "The model stopped producing tokens before the response "
                "completed. Try stopping and retrying, or reduce max tokens."
            )
        raise_limit = (
            "For a local GGUF model, increase the first-token waiting limit in Settings > Chat"
        )
        if _finite_positive_float_env(_OPENAI_COMPAT_FIRST_TOKEN_TIMEOUT_ENV, None) is not None:
            raise_limit += f" (API requests use {_OPENAI_COMPAT_FIRST_TOKEN_TIMEOUT_ENV} instead while it is set)"
        return (
            "The model did not produce a first token within the waiting limit. "
            f"{raise_limit}. Otherwise reduce context length, use more GPU offload, or load a smaller model."
        )
    if isinstance(exc, httpx.TimeoutException):
        return "Timed out communicating with the model server. Try again shortly."
    # Any httpx RequestError means llama-server is unreachable: crashed or still starting.
    if isinstance(exc, httpx.RequestError):
        return _LOST_CONNECTION_MSG
    msg = str(exc)
    m = _OVERSIZE_TOKENS_RE.search(msg)
    if m:
        # llama-server only knows the prompt total; let the fit's diagnosis pick the wording.
        return context_refusal.describe_oversize(int(m.group(1)), int(m.group(2)))
    if "Lost connection to llama-server" in msg:
        return _LOST_CONNECTION_MSG
    template_msg = _template_raise_message(msg, _loaded_chat_template())
    if template_msg:
        return f"An internal error occurred: {template_msg}"
    # After the token-count regex, before the catch-all, so stream failures keep their cause.
    if isinstance(exc, LlamaStreamError):
        return exc.friendly
    client_error = _LLAMA_CLIENT_ERROR_RE.match(msg)
    if client_error:
        body = client_error.group(1)
        try:
            body = error_message_from_chunk(json.loads(body)) or body
        except ValueError:
            pass
        return _friendly_upstream_error(body[:500])
    return "An internal error occurred"


def _friendly_gen_stream_error(value) -> str:
    """Return a client-safe message for typed local generation errors."""
    text = str(value)
    if getattr(value, "public", False):
        return text
    logger.error("Local generation failed: %s", text)
    return safe_error_detail(RuntimeError(text), fallback = "An internal error occurred.")


def _refused_parameter(value) -> Optional[str]:
    param = getattr(value, "openai_param", None)
    return param if getattr(value, "public", False) and param else None


def _friendly_upstream_error(text: str) -> str:
    """Rewrite a grammar compile failure from llama-server into advice; other errors keep their own text."""
    lowered = text.lower()
    if "failed to parse grammar" in lowered:
        return (
            "The model couldn't compile a grammar for this request. A tool or response_format "
            "schema in it carries a constraint llama-server's grammar engine cannot compile, "
            "which does not depend on the model or quant. Update Unsloth, which drops the "
            "constraints known to break it, and report the schemas if it still fails."
        )
    return f"llama-server error: {text}"


def _oversize_counts(text: str):
    """Prose counts first, then the structured n_prompt_tokens and n_ctx, which hold the real totals."""
    m = _OVERSIZE_TOKENS_RE.search(text)
    if m:
        return int(m.group(1)), int(m.group(2))
    return _parse_overflow_counts(text)


def _anthropic_upstream_error(text: str, counts_source: Optional[str] = None) -> str:
    """`text` is what the client is told; `counts_source` is the fuller body it came
    from, used only to recover token counts the message itself does not spell out."""
    # KV starvation means retry, not shorten the conversation.
    if is_kv_starvation(text):
        return KV_STARVATION_MESSAGE
    if _classify_llama_generation_error(Exception(text)):
        counts = _oversize_counts(text)
        if counts is None and counts_source:
            counts = _oversize_counts(counts_source)
        if counts:
            # Anthropic head wording clients key on to compact, plus the fit remedy; not a flat shorten, which cannot help if the latest turn or system prompt overflows.
            return (
                f"Prompt is too long: {counts[0]} tokens > {counts[1]} maximum. "
                + context_refusal.oversize_advice(counts[1])
            )
        return (
            "Prompt is too long. Try increasing the Context Length in Model settings, "
            "or shorten the conversation."
        )
    return _friendly_upstream_error(text)


def _clamp_finish_reason(value) -> str:
    """Unknown finish_reason values, including None, become stop so upstream quirks do not leak."""
    return (
        value
        if value
        in (
            "stop",
            "length",
            "tool_calls",
            "content_filter",
            "function_call",
        )
        else "stop"
    )


def _continue_final_message(payload, *, thought: bool = False) -> bool:
    """Resume the trailing assistant turn, or start a new turn if none is resumable; thought also resumes a reasoning-only turn (llama-server, MLX)."""
    if not getattr(payload, "continue_final_message", None):
        return False
    messages = getattr(payload, "messages", None) or []
    if not messages:
        return False
    last = messages[-1]
    role = last.get("role") if isinstance(last, dict) else getattr(last, "role", None)
    if role != "assistant":
        return False
    tool_calls = (
        last.get("tool_calls") if isinstance(last, dict) else getattr(last, "tool_calls", None)
    )
    if tool_calls:
        return False
    content = last.get("content") if isinstance(last, dict) else getattr(last, "content", None)
    if isinstance(content, str):
        has_text = bool(content)
    elif isinstance(content, list):
        # No resume point inside an image or tool-result part.
        texts = []
        for part in content:
            part_type = part.get("type") if isinstance(part, dict) else getattr(part, "type", None)
            if part_type != "text":
                return False
            texts.append(
                part.get("text") if isinstance(part, dict) else getattr(part, "text", None)
            )
        has_text = any(texts)
    else:
        has_text = False
    if has_text or not thought:
        return has_text
    reasoning = (
        last.get("reasoning_content")
        if isinstance(last, dict)
        else getattr(last, "reasoning_content", None)
    )
    return isinstance(reasoning, str) and bool(reasoning.strip())


def _reject_unresumable_thought(payload, llama_backend, reject) -> None:
    """An older llama-server would treat the thought as finished and answer after it."""
    if (
        _continue_final_message(payload, thought = True)
        and not _continue_final_message(payload)
        and not getattr(llama_backend, "_resumes_thoughts", True)
    ):
        raise reject(
            400,
            "This llama.cpp build cannot resume a response that stopped mid-thought. "
            "Update Unsloth Studio for a newer llama.cpp, or use Retry.",
        )


def _reject_audio_output_continuation(payload) -> None:
    """Audio output re-speaks the newest user text, so there is no partial to resume
    from; refuse rather than return a fresh clip labelled as a continuation."""
    if _continue_final_message(payload):
        raise HTTPException(
            status_code = 400,
            detail = "continue_final_message is not supported with audio output.",
        )


def _normalize_stop_sequences(raw):
    """Empty stop strings are dropped, since an empty sequence would end generation at position 0."""
    if isinstance(raw, str):
        return [raw] if raw else None
    if isinstance(raw, list):
        return [s for s in raw if isinstance(s, str) and s] or None
    return None


def _effective_max_tokens(payload):
    """max_completion_tokens wins over the deprecated max_tokens when both are set."""
    return (
        payload.max_completion_tokens
        if payload.max_completion_tokens is not None
        else payload.max_tokens
    )


# Below this there is no room for speech worth returning, so an over-context prompt is a
# client error rather than a one-token generation.
_MIN_SPEECH_OUTPUT_TOKENS = 64

# Backends wrap the text in codec delimiters, so reserve headroom beyond the estimate.
_TTS_PROMPT_FORMAT_RESERVE = 32
_MINIMAX_MUSIC3_DEFAULT_FRAMES = 750
# audio_cpp_backend caps a clip at 240 seconds; 25 frames per second.
_AUDIO_CPP_MUSIC_MAX_FRAMES = 240 * 25
# 24 GB cards report slightly under 24 GiB free when idle; keep the floor below that.
_MINIMAX_MUSIC3_RESIDENT_GB = 23.0
_MINIMAX_PROMPT_OVERFLOW = _re.compile(r"The assembled prompt has \d+ tokens; the maximum is \d+")


def _tts_max_new_tokens(
    payload,
    prompt: Optional[str] = None,
    *,
    audio_type: Optional[str] = None,
    speech_api_default_max_tokens: bool = False,
) -> int:
    """Cap TTS tokens so the prompt and output share the loaded context without overflowing it."""
    moss_generation = audio_type in ("moss_tts_local", "moss_tts_nano")
    # audio.cpp music reads the budget at MiniMax's 25 fps, so it shares MiniMax's defaults.
    music_generation = audio_type in ("minimax_music3", "audiocpp_music")
    context_length = _monitor_context_length() if moss_generation or prompt else None
    token_ceiling = (
        context_length or MOSS_TTS_MAX_FRAMES
        if moss_generation
        else (
            MINIMAX_MUSIC_MAX_FRAMES
            if audio_type == "minimax_music3"
            else (
                _AUDIO_CPP_MUSIC_MAX_FRAMES
                if audio_type == "audiocpp_music"
                else AUDIO_GENERATION_MAX_TOKENS
            )
        )
    )
    budget = min(
        token_ceiling,
        max(1, int(_effective_max_tokens(payload) or 2048)),
    )
    if speech_api_default_max_tokens and music_generation:
        budget = min(budget, _MINIMAX_MUSIC3_DEFAULT_FRAMES)
    if prompt and context_length:
        budget = min(
            budget,
            context_length - _prompt_token_estimate(prompt) - _TTS_PROMPT_FORMAT_RESERVE,
        )
    # Zero remaining budget would yield one token and a useless clip, so routes reject it up front.
    return max(1, budget)


def _speech_budget_exhausted(context_length: int, prompt_tokens: int) -> bool:
    """Whether *prompt_tokens* leaves a context with no room to speak."""
    return context_length - prompt_tokens - _TTS_PROMPT_FORMAT_RESERVE < _MIN_SPEECH_OUTPUT_TOKENS


def _raise_if_prompt_leaves_no_speech_budget(text: str) -> None:
    """Return 400 when the prompt alone fills the context; the budget floor of one token would hide it."""
    context_length = _monitor_context_length()
    if not context_length:
        return
    if _speech_budget_exhausted(context_length, _prompt_token_estimate(text)):
        raise HTTPException(
            status_code = 400,
            detail = (
                f"Input is too long for the loaded model's {context_length}-token context. "
                "Shorten it, or load the model with a larger context."
            ),
        )


_EXTRA_PROMPT_FIELD_AUDIO_TYPES = ("higgs_tts2", "moss_tts_local")


def _speech_prompt_for_budget(audio_type: Optional[str], budget: dict) -> str:
    text = budget.get("text") or ""
    if audio_type not in _EXTRA_PROMPT_FIELD_AUDIO_TYPES:
        return text
    return _native_tts_prompt_for_budget(
        text, audio_type, budget.get("instructions"), budget.get("language")
    )


def _native_tts_prompt_for_budget(
    text: str, audio_type: Optional[str], instructions: Optional[str], language: Optional[str]
) -> str:
    """User-controlled text fields tokenized by native TTS prompt builders."""
    if audio_type == "higgs_tts2":
        instructions = instructions or "Audio is recorded from a quiet room."
    parts = [instructions]
    if audio_type == "moss_tts_local":
        parts.append(language)
    parts.append(text)
    return "\n".join(str(part) for part in parts if part)


def _prompt_token_estimate(prompt: str) -> int:
    """Prefer the loaded tokenizer; the len//3 guess undercounts CJK and emoji badly."""
    try:
        backend = _peek_inference_backend()
        if backend is not None and backend.active_model_name:
            models = getattr(backend, "models", {}) or {}
            info = models.get(backend.active_model_name, {}) if isinstance(models, dict) else {}
            tokenizer = info.get("tokenizer") if isinstance(info, dict) else None
            if tokenizer is not None and hasattr(tokenizer, "encode"):
                count = len(tokenizer.encode(prompt))
                if count > 0:
                    return count
    except Exception:  # noqa: BLE001 - an estimate must never fail the request
        pass
    return _byte_fallback_prompt_tokens(prompt)


def _byte_fallback_prompt_tokens(prompt: str) -> int:
    # UTF-8 bytes conservatively bound the unreachable subprocess/llama-server tokenizers.
    return max(1, len(prompt.encode("utf-8")))


_OPENAI_COMPAT_STREAM_STALL_TIMEOUT_ENV = "UNSLOTH_OPENAI_COMPAT_STREAM_STALL_TIMEOUT"
_OPENAI_COMPAT_STREAM_KEEPALIVE_ENV = "UNSLOTH_OPENAI_COMPAT_STREAM_KEEPALIVE_INTERVAL"
_OPENAI_COMPAT_FIRST_TOKEN_TIMEOUT_ENV = "UNSLOTH_OPENAI_COMPAT_FIRST_TOKEN_TIMEOUT"


def _positive_float_env(env_name: str, default):
    """Parse a positive float from an env var. A parseable non-positive value
    returns ``None`` (0 disables the guarded feature); only unparseable or unset
    values fall back to ``default``."""
    raw_value = os.environ.get(env_name)
    if raw_value is None or not raw_value.strip():
        return default
    try:
        value = float(raw_value.strip())
    except ValueError:
        return default
    return value if value > 0 else None


def _effective_openai_max_tokens_from_values(max_tokens, max_completion_tokens = None):
    """Prefer max_completion_tokens; None when both are omitted, so the context window default applies."""

    def _validate_explicit(value, param: str):
        if value is None:
            return None
        if isinstance(value, bool) or not isinstance(value, int):
            raise HTTPException(
                status_code = 400,
                detail = openai_error_body(
                    f"'{param}' must be an integer.",
                    status = 400,
                    code = "invalid_type",
                    param = param,
                ),
            )
        # Legacy completions spec allows max_tokens=0; only negatives are rejected.
        if value < 0:
            raise HTTPException(
                status_code = 400,
                detail = openai_error_body(
                    f"'{param}' must be at least 0.",
                    status = 400,
                    code = "invalid_value",
                    param = param,
                ),
            )
        return value

    max_tokens = _validate_explicit(max_tokens, "max_tokens")
    max_completion_tokens = _validate_explicit(max_completion_tokens, "max_completion_tokens")
    return max_completion_tokens if max_completion_tokens is not None else max_tokens


def _effective_openai_max_tokens(payload):
    return _effective_openai_max_tokens_from_values(
        getattr(payload, "max_tokens", None),
        getattr(payload, "max_completion_tokens", None),
    )


def _wants_multiple_choices(payload) -> bool:
    return (payload.n or 1) > 1


def _has_openai_tool_history(messages) -> bool:
    for message in messages or []:
        if isinstance(message, dict):
            if message.get("role") == "tool" or message.get("tool_calls"):
                return True
            continue
        if getattr(message, "role", None) == "tool" or getattr(message, "tool_calls", None):
            return True
    return False


def _raise_unsupported_openai_parameter(param: str, message: str) -> None:
    raise HTTPException(
        status_code = 400,
        detail = openai_error_body(
            message,
            status = 400,
            code = "unsupported_parameter",
            param = param,
        ),
    )


def _choice_seed(
    seed: Optional[int],
    choice_index: int,
    *,
    negative_is_random: bool = False,
) -> Optional[int]:
    """Each choice gets its own seed; every value congruent to LLAMA_DEFAULT_SEED (0xFFFFFFFF, not just -1) is the random sentinel."""
    if seed is None or not choice_index:
        return seed
    if not negative_is_random:
        return seed + choice_index
    if (seed & 0xFFFFFFFF) == 0xFFFFFFFF:
        return seed
    return ((seed & 0xFFFFFFFF) + choice_index) % 0xFFFFFFFF


def _raise_unsupported_n(path_label: str, monitor_id: Optional[str] = None) -> None:
    """Pass monitor_id to fail an open row, or a refused generation keeps being reported."""
    message = f"n > 1 is not supported for {path_label}."
    if monitor_id:
        api_monitor.fail(monitor_id, message)
    _raise_unsupported_openai_parameter("n", message)


def _sse_streaming_response(
    content,
    *,
    unstarted_cleanup = None,
    monitor_id = None,
) -> StreamingResponse:
    """Standard SSE headers (no cache, no proxy buffering, one-shot); uses _SameTaskStreamingResponse so Python 3.13 + httpx avoids cancel-scope errors."""
    return _SameTaskStreamingResponse(
        content,
        media_type = "text/event-stream",
        headers = _monitor_response_headers(
            {
                "Cache-Control": "no-cache",
                "Connection": "close",
                "X-Accel-Buffering": "no",
            },
            monitor_id,
        ),
        unstarted_cleanup = unstarted_cleanup,
    )


def _monitor_response_headers(headers: Optional[dict], monitor_id: Optional[str]) -> dict:
    result = dict(headers or {})
    if monitor_id:
        result["X-Unsloth-Monitor-ID"] = monitor_id
    return result


def _is_prefill_progress_only(data) -> bool:
    if not isinstance(data, dict) or not isinstance(data.get("prompt_progress"), dict):
        return False
    if data.get("usage") or _llama_chunk_has_generated_output(data):
        return False
    choices = data.get("choices")
    return not (
        isinstance(choices, list)
        and any(isinstance(c, dict) and c.get("finish_reason") for c in choices)
    )


class _ProgressKeepalive:
    """Stand in ``: prefill-progress`` for dropped progress: feeds the relay idle timer and the durable lease."""

    def __init__(self, interval_s: Optional[float]):
        self._interval_s = interval_s
        self._due = time.monotonic() + interval_s if interval_s else None

    def due(self) -> bool:
        if self._due is None or time.monotonic() < self._due:
            return False
        self._due = time.monotonic() + self._interval_s
        return True


def _openai_stream_error_chunk(exc) -> dict:
    """Mid-stream error chunk: status is already sent, so overflows get code context_length_exceeded."""
    from core.inference.engine_transport import EngineHTTPError

    if isinstance(exc, EngineHTTPError):
        error = _openai_passthrough_error(exc.status_code, exc.body)
        return (
            error.detail
            if isinstance(error.detail, dict)
            else openai_error_body(str(error.detail), status = error.status_code)
        )
    _cls = _classify_llama_generation_error(exc)
    if _cls:
        return openai_error_body(
            _friendly_error(exc),
            status = 400,
            code = "context_length_exceeded",
        )
    if _cls is False:
        return openai_error_body(_friendly_error(exc), status = 400)
    return openai_error_body(_friendly_error(exc), status = 500)


def _context_budget_http_error(exc) -> "HTTPException":
    """Context refusal as the same 400 llama.cpp returns (raised before any token)."""
    return HTTPException(
        status_code = 400,
        detail = openai_error_body(
            _friendly_error(exc),
            status = 400,
            code = "context_length_exceeded",
            param = "messages",
        ),
    )


def _openai_stream_error_sse(error: dict) -> str:
    # Flag failed so the middleware does not claim a preview-owned model on a failed stream.
    from core.inference.llama_keepwarm import mark_current_response_failed
    mark_current_response_failed()
    return f"data: {json.dumps(error)}\n\ndata: [DONE]\n\n"


def _openai_stream_error_sse_bytes(error: dict) -> bytes:
    return _openai_stream_error_sse(error).encode("utf-8")


def _openai_passthrough_error(status_code, text) -> "HTTPException":
    """Non-200 passthrough error: overflows become 400 context_length_exceeded; grammar errors get
    advice."""
    if _classify_llama_generation_error(Exception(text)):
        return HTTPException(
            status_code = 400,
            detail = openai_error_body(
                _friendly_error(Exception(text)),
                status = 400,
                code = "context_length_exceeded",
                param = "messages",
            ),
        )
    return HTTPException(
        status_code = status_code,
        detail = _friendly_upstream_error(text[:500]),
    )


_OVERFLOW_TRUNCATE_MAX_RETRIES = 3
# Rest is generation headroom so a near-full prompt cannot cut a tool call mid-JSON.
_OVERFLOW_PROMPT_TARGET_FRACTION = 0.75


def _overflow_truncation_policy(payload) -> Optional[str]:
    requested = getattr(payload, "context_overflow", None)
    if requested is not None:
        return requested if requested in ("truncate_middle", "truncate_oldest") else None
    server_default = os.environ.get("UNSLOTH_CONTEXT_OVERFLOW", "").strip().lower()
    return server_default if server_default in ("truncate_middle", "truncate_oldest") else None


def _rolling_context_policy(payload) -> Optional[str]:
    policy = _overflow_truncation_policy(payload)
    return policy if policy == "truncate_oldest" else None


def _request_context_policy(payload) -> Optional[str]:
    requested = getattr(payload, "context_policy", None)
    if isinstance(requested, str):
        value = requested.strip().lower()
        if value in ("checkpoint", "rolling"):
            return value
    return None


def _request_compaction_headroom_ratio(payload) -> Optional[float]:
    from core.inference.context_window import clamp_compaction_headroom_ratio
    return clamp_compaction_headroom_ratio(getattr(payload, "compaction_headroom_ratio", None))


def _overflow_truncation_requested(payload) -> bool:
    """True when the request (or the UNSLOTH_CONTEXT_OVERFLOW server default,
    for clients that cannot send custom fields) opted into truncation."""
    return _overflow_truncation_policy(payload) is not None


def _context_truncated_sse_chunk(completion_id: str, model_name: str, truncation: dict) -> str:
    # Record the fit `_friendly_error` later reads (see `context_refusal`).
    context_refusal.record_fit(truncation)
    data = {
        "id": completion_id,
        "object": "chat.completion.chunk",
        "created": int(time.time()),
        "model": model_name,
        "choices": [],
        "context_truncated": truncation,
    }
    return f"data: {json.dumps(data)}\n\n"


def _quote_cut_sse_chunk(completion_id: str, model_name: str) -> str:
    # Report the warning separately to preserve llama-server's finish reason.
    data = {
        "id": completion_id,
        "object": "chat.completion.chunk",
        "created": int(time.time()),
        "model": model_name,
        "choices": [],
        "quote_cut": True,
    }
    return f"data: {json.dumps(data)}\n\n"


def _accumulate_context_truncation(current: Optional[dict], event: dict) -> dict:
    incoming = {key: value for key, value in event.items() if key != "type"}
    # Per-fit event, not `combined`, which sums counters across a tool loop.
    context_refusal.record_fit(incoming)
    if current is None:
        return incoming
    combined = {**current, **incoming}
    for counter in ("dropped_messages", "archived_messages", "recalled_chunks"):
        if counter in current or counter in incoming:
            combined[counter] = int(current.get(counter) or 0) + int(incoming.get(counter) or 0)
    if current.get("prompt_tokens_before") is not None:
        combined["prompt_tokens_before"] = current["prompt_tokens_before"]
    return combined


def _parse_overflow_counts(err_text: str):
    """(n_prompt_tokens, n_ctx) from an exceed_context_size_error body, or
    None. Tolerates \\" around keys (body may be a re-wrapped JSON string)."""
    m_prompt = _re.search(r'n_prompt_tokens\\?"?\s*:\s*(\d+)', err_text)
    m_ctx = _re.search(r'n_ctx\\?"?\s*:\s*(\d+)', err_text)
    if m_prompt and m_ctx:
        return int(m_prompt.group(1)), int(m_ctx.group(1))
    return None


def _truncate_middle_messages(messages: list, keep_ratio: float):
    """Drop whole turn groups from the middle, never system messages, the first group or trailing groups; tool calls stay paired with results."""
    if not messages or keep_ratio >= 1.0:
        return messages, 0

    head: list = []
    idx = 0
    while idx < len(messages) and messages[idx].get("role") in ("system", "developer"):
        head.append(messages[idx])
        idx += 1

    groups: list[list] = []
    for msg in messages[idx:]:
        role = msg.get("role")
        if role == "tool" and groups:
            groups[-1].append(msg)
        elif role == "tool":
            groups.append([msg])  # orphan tool result; treat as its own group
        else:
            groups.append([msg])

    # Anchor group plus the last 3 groups stay.
    protected_tail = min(3, max(1, len(groups) - 1))
    if len(groups) <= 1 + protected_tail:
        return messages, 0

    estimates = {id(msg): _estimate_message_tokens(msg) for msg in messages}
    total_est = sum(estimates[id(msg)] for msg in messages)
    target_est = int(total_est * keep_ratio)

    anchor = groups[0]
    middle = groups[1:-protected_tail]
    tail = groups[-protected_tail:]

    current_est = total_est
    dropped = 0
    # Cursor over ``middle``, not pop(0), to avoid quadratic shifting.
    first_kept = 0
    while first_kept < len(middle) and current_est > target_est:
        victim = middle[first_kept]
        first_kept += 1
        dropped += len(victim)
        current_est -= sum(estimates[id(msg)] for msg in victim)

    if dropped == 0:
        return messages, 0

    new_messages = head + anchor
    kept = [msg for grp in middle[first_kept:] + tail for msg in grp]
    # Merge the seam: strict templates (e.g. Mistral) reject two user turns in a row.
    if kept and new_messages[-1].get("role") == kept[0].get("role") == "user":
        new_messages[-1] = {
            **new_messages[-1],
            "content": _merge_user_content(new_messages[-1].get("content"), kept[0].get("content")),
        }
        kept = kept[1:]
    new_messages.extend(kept)
    return new_messages, dropped


_CLIP_MARKER = "\n[... truncated by context_overflow=truncate_middle ...]\n"
# Generous head+tail first; cut harder if the estimate still misses the target.
_CLIP_KEEP_CHARS = (1500, 400)


def _clip_reasoning_contents(messages: list, keep: int = _CLIP_KEEP_CHARS[-1]) -> int:
    """Clip assistant reasoning before dropping turns; it can sit outside the groups eviction reaches."""
    clipped = 0
    for msg in messages:
        if msg.get("role") != "assistant":
            continue
        reasoning = msg.get("reasoning_content")
        if not isinstance(reasoning, str) or len(reasoning) <= 2 * keep + len(_CLIP_MARKER):
            continue
        msg["reasoning_content"] = reasoning[:keep] + _CLIP_MARKER + reasoning[-keep:]
        clipped += 1
    return clipped


def _clip_long_contents(messages: list, target_est: int) -> int:
    """Clip middle-out, tool results first, final message last; message count and roles never change."""

    def _candidates():
        tools = [m for m in messages if m.get("role") == "tool"]
        users = [m for m in messages[:-1] if m.get("role") == "user"]
        last = [messages[-1]] if messages else []
        return tools + users + last

    clipped = 0
    for keep in _CLIP_KEEP_CHARS:
        for msg in _candidates():
            if _estimate_messages_tokens(messages) <= target_est:
                return clipped
            content = msg.get("content")
            if not isinstance(content, str) or len(content) <= 2 * keep + len(_CLIP_MARKER):
                continue
            msg["content"] = content[:keep] + _CLIP_MARKER + content[-keep:]
            clipped += 1
    return clipped


def _apply_overflow_truncation(
    body: dict,
    err_text: str,
    policy: str = "truncate_middle",
) -> bool:
    """Shrink a passthrough body after an upstream context overflow: drop
    middle turn-groups, clip still-oversized contents, clamp ``max_tokens``
    to the generation headroom. Returns False when nothing could shrink."""
    counts = _parse_overflow_counts(err_text)
    messages = body.get("messages") or []
    pre_clip_est = _estimate_messages_tokens(messages)
    clipped = 0 if policy == "truncate_oldest" else _clip_reasoning_contents(messages)
    total_est = _estimate_messages_tokens(messages)
    if counts:
        n_prompt, n_ctx = counts
        prompt_target = _OVERFLOW_PROMPT_TARGET_FRACTION * n_ctx
        if clipped:
            # Server counted pre-clip; rescale so the removed trace is not charged again.
            n_prompt = n_prompt * total_est / max(1, pre_clip_est)
        if clipped and n_prompt <= prompt_target:
            keep_ratio = 1.0
        else:
            keep_ratio = min(0.95, prompt_target / max(1.0, n_prompt))
    else:
        n_ctx = None
        keep_ratio = 0.6  # no counts in the error; cut conservatively
    # Scale the server-token target into char-estimate units.
    target_est = int(total_est * keep_ratio)

    truncate = (
        _truncate_oldest_messages if policy == "truncate_oldest" else _truncate_middle_messages
    )
    new_messages, dropped = truncate(messages, keep_ratio)
    if dropped:
        body["messages"] = new_messages
    if (
        policy != "truncate_oldest"
        and _estimate_messages_tokens(body.get("messages") or []) > target_est
    ):
        clipped += _clip_long_contents(body.get("messages") or [], target_est)
    if not dropped and not clipped:
        return False
    if n_ctx:
        headroom = max(1024, int(n_ctx * (1.0 - _OVERFLOW_PROMPT_TARGET_FRACTION)))
        cur_max = body.get("max_tokens")
        body["max_tokens"] = min(cur_max, headroom) if cur_max else headroom
    logger.warning(
        "context_overflow=%s: dropped %d messages, clipped "
        "%d contents (keep_ratio %.2f); retrying within the real window",
        policy,
        dropped,
        clipped,
        keep_ratio,
    )
    return True


def _apply_measured_overflow_truncation(body: dict, err_text: str, policy: str) -> Optional[int]:
    before = len(body.get("messages") or [])
    if not _apply_overflow_truncation(body, err_text, policy):
        return None
    return max(0, before - len(body.get("messages") or []))


def _passthrough_cut_scope(llama_backend, body: dict) -> tuple:
    # A cut measured under another model, window or tool catalogue does not carry over.
    tools = sorted(
        str(((tool or {}).get("function") or {}).get("name")) for tool in body.get("tools") or []
    )
    # getattr, as the rest of this module reads the backend: not every backend object carries both.
    return (
        "passthrough",
        getattr(llama_backend, "model_identifier", None),
        getattr(llama_backend, "context_length", None),
        tuple(tools),
    )


def _replay_passthrough_cut(
    body: dict, policy: Optional[str], context_length: Optional[int], scope
) -> int:
    """Apply this conversation's last cut before sending, while the uncut request would still overflow."""
    if policy != "truncate_oldest" or not context_length:
        return 0
    messages = body.get("messages") or []
    # Tool schemas render into the prompt too, and an agent's can be most of it. Images are media, not prompt text.
    estimate = (
        _estimate_messages_tokens(messages_without_unpriced_media(messages))
        + len(json.dumps(body.get("tools") or [], default = str)) // 4
    )
    if estimate <= _OVERFLOW_PROMPT_TARGET_FRACTION * context_length:
        return 0
    from core.inference import prefix_boundary

    remembered = prefix_boundary.recall(messages, scope)
    if not remembered:
        return 0
    cut, dropped = _truncate_oldest_messages(messages, 1.0, min_dropped = remembered)
    if dropped:
        body["messages"] = cut
    return dropped


def _remember_passthrough_cut(
    original: list, body: dict, policy: Optional[str], dropped: int, scope
) -> None:
    if policy != "truncate_oldest" or dropped <= 0:
        return
    from core.inference import prefix_boundary
    prefix_boundary.remember(original, body.get("messages") or [], dropped, scope)


async def _prepare_passthrough_cut(llama_backend, body: dict, policy: Optional[str]):
    """(uncut messages, cut scope, messages a remembered cut dropped). Only truncate_oldest
    remembers cuts, so every other policy skips the copy, the scope and the thread hop."""
    if policy != "truncate_oldest":
        return None, None, 0
    uncut = list(body.get("messages") or [])
    scope = _passthrough_cut_scope(llama_backend, body)
    # Off the event loop: the history can hold megabytes of images.
    dropped = await asyncio.to_thread(
        _replay_passthrough_cut, body, policy, getattr(llama_backend, "context_length", None), scope
    )
    return uncut, scope, dropped


def _anthropic_stream_error_event(exc, *, force: bool = False):
    """Return an Anthropic in-band stream error event when one is useful."""
    # Flag failed even when returning None: middleware must not claim a preview-owned model.
    from core.inference.llama_keepwarm import mark_current_response_failed

    mark_current_response_failed()
    _cls = _classify_llama_generation_error(exc)
    if _cls is None and not force:
        return None
    status = 400 if _cls is not None else 500
    return build_anthropic_sse_event(
        "error",
        anthropic_error_body(_friendly_error(exc), status = status),
    )


def _json_dumps_safe(value) -> Optional[str]:
    """`json.dumps` for count recovery only; never raises on an odd payload."""
    try:
        return json.dumps(value)
    except (TypeError, ValueError):
        return None


def _anthropic_upstream_stream_error_event(text: str, counts_source: Optional[str] = None):
    """In-band error for a failed 200 stream; oversize refusals keep their wording, not a generic error."""
    from core.inference.llama_keepwarm import mark_current_response_failed

    mark_current_response_failed()
    over = bool(_classify_llama_generation_error(Exception(text)))
    return build_anthropic_sse_event(
        "error",
        anthropic_error_body(
            _anthropic_upstream_error(text, counts_source = counts_source),
            status = 400 if over else 500,
        ),
    )


def _drop_parallel_tool_call_deltas(chunk) -> bool:
    """In-place: drop tool_call deltas whose index >= 1 from a parsed OpenAI
    streaming chunk so only the first tool call survives (parallel_tool_calls=false
    / disable_parallel_tool_use, best-effort). Returns True if anything changed."""
    if not isinstance(chunk, dict):
        return False
    changed = False
    for ch in chunk.get("choices") or []:
        delta = ch.get("delta") or {}
        tcs = delta.get("tool_calls")
        if isinstance(tcs, list):
            kept = [tc for tc in tcs if isinstance(tc, dict) and (tc.get("index") or 0) == 0]
            if len(kept) != len(tcs):
                delta["tool_calls"] = kept
                changed = True
    return changed


def _add_empty_content_to_reasoning_deltas(chunk: dict) -> bool:
    """Strict OpenAI clients drop reasoning-only deltas, so add empty content beside reasoning_content."""
    changed = False
    choices = chunk.get("choices")
    if not isinstance(choices, list):
        return False
    for choice in choices:
        if not isinstance(choice, dict):
            continue
        delta = choice.get("delta")
        if not isinstance(delta, dict):
            continue
        if "reasoning_content" in delta and "content" not in delta:
            delta["content"] = ""
            changed = True
    return changed


def _normalize_openai_passthrough_sse_line(
    raw_line: str, *, cap_parallel_tool_calls: bool = False
) -> str:
    """Relay comments, [DONE] and unparsable lines as-is; re-serialize only when a compat fix applies."""
    return _normalize_openai_passthrough_sse_line_and_data(
        raw_line, cap_parallel_tool_calls = cap_parallel_tool_calls
    )[0]


_SSE_LINE_UNPARSED = object()


def _normalize_openai_passthrough_sse_line_and_data(
    raw_line: str, *, cap_parallel_tool_calls: bool = False
) -> tuple[str, Any]:
    """The normalized line plus its decoded JSON when the check had to parse it, so the relay need not."""
    if not raw_line.startswith("data:"):
        return raw_line, _SSE_LINE_UNPARSED
    # Fast path: skip the JSON parse when neither key appears in the line.
    if '"reasoning_content"' not in raw_line and not (
        cap_parallel_tool_calls and '"tool_calls"' in raw_line
    ):
        return raw_line, _SSE_LINE_UNPARSED
    payload = raw_line[len("data:") :].lstrip()
    if payload.strip() in ("", "[DONE]"):
        return raw_line, _SSE_LINE_UNPARSED
    try:
        obj = json.loads(payload)
    except Exception:
        return raw_line, _SSE_LINE_UNPARSED
    if not isinstance(obj, dict):
        return raw_line, obj
    changed = _add_empty_content_to_reasoning_deltas(obj)
    if cap_parallel_tool_calls and _drop_parallel_tool_call_deltas(obj):
        changed = True
    if not changed:
        return raw_line, obj
    return "data: " + json.dumps(obj, separators = (",", ":"), ensure_ascii = False), obj


def _prompt_tokens_details(upstream):
    """Surface llama-server's real ``cached_tokens`` (KV-cache prompt hits) while
    keeping the full OpenAI ``prompt_tokens_details`` shape. Defaults to zero when
    the upstream usage doesn't carry it, so the field is always present."""
    out = {"cached_tokens": 0, "audio_tokens": 0}
    if isinstance(upstream, dict):
        out.update({k: v for k, v in upstream.items() if v is not None})
    return out


def _wants_stream_usage(payload) -> bool:
    return bool((payload.stream_options or {}).get("include_usage"))


def _is_openai_usage_only_sse(line: str) -> bool:
    """Matches only standalone empty-choices usage chunks; content chunks with inline usage must relay."""
    if not isinstance(line, str) or not line.startswith("data:"):
        return False
    # Hot path: skip the parse unless the line literally contains the usage key.
    if '"usage"' not in line:
        return False
    body = line[len("data:") :].strip()
    if not body or body == "[DONE]":
        return False
    try:
        obj = json.loads(body)
    except Exception:
        return False
    return (
        isinstance(obj, dict)
        and obj.get("usage") is not None
        and isinstance(obj.get("choices"), list)
        and not obj["choices"]
    )


_OPENAI_PASSTHROUGH_TERMINAL_GRACE_S = 2.0
_OPENAI_INTERNAL_USAGE_GRACE_S = 0.25
_SSE_DONE_LINE = "data: [DONE]"
_SSE_DONE_CHUNK = "data: [DONE]\n\n"


def _openai_passthrough_sse_line_terminal_state(raw_line: str) -> Optional[str]:
    """Detect the final chunk so the stream closes, since llama-server may omit the [DONE] sentinel."""
    if not raw_line.startswith("data:"):
        return None
    data_str = raw_line[5:].lstrip()
    if data_str == "[DONE]":
        return "done"
    try:
        data = json.loads(data_str)
    except json.JSONDecodeError:
        return None
    return _openai_passthrough_terminal_state_from_data(data)


def _openai_passthrough_terminal_state_from_data(data) -> Optional[str]:
    """Dict-level core of ``_openai_passthrough_sse_line_terminal_state`` for
    callers that already parsed the chunk (avoids a re-parse per relayed line)."""
    if not isinstance(data, dict):
        return None
    if _monitor_openai_error_message(data):
        return "error"
    choices = data.get("choices")
    if isinstance(choices, list):
        if not choices and isinstance(data.get("usage"), dict):
            return "usage"
        for choice in choices:
            if isinstance(choice, dict) and choice.get("finish_reason") is not None:
                return "finish"
    elif isinstance(data.get("usage"), dict):
        return "usage"
    return None


def _openai_stream_usage_chunk(
    payload, completion_id, created, model_name, stream_usage, stream_timings
):
    """Build the final OpenAI-standard usage chunk (choices=[], usage populated)
    for a chat stream. Returns the SSE ``data:`` line, or None when the client
    did not opt in via ``stream_options.include_usage`` (or no usage exists)."""
    if not _wants_stream_usage(payload):
        return None
    if not (stream_usage or stream_timings):
        return None
    _usage = stream_usage or {}
    _prompt_tokens = _usage.get("prompt_tokens") or 0
    _completion_tokens = _usage.get("completion_tokens") or 0
    _total_tokens = _usage.get("total_tokens") or (_prompt_tokens + _completion_tokens)
    usage_chunk = ChatCompletionChunk(
        id = completion_id,
        created = created,
        model = model_name,
        choices = [],
        usage = CompletionUsage(
            prompt_tokens = _prompt_tokens,
            completion_tokens = _completion_tokens,
            total_tokens = _total_tokens,
            prompt_tokens_details = _prompt_tokens_details(_usage.get("prompt_tokens_details")),
            context_tokens = _usage.get("context_tokens"),
        ),
        timings = stream_timings,
    )
    return f"data: {usage_chunk.model_dump_json(exclude_none = True)}\n\n"


def _chat_chunk_sse(completion_id, created, model_name, *, delta, finish_reason) -> str:
    """One ``ChatCompletionChunk`` as an SSE ``data:`` line. The role / content /
    final chunks every in-process streamer emits differ only in their ``delta``
    and ``finish_reason``."""
    chunk = ChatCompletionChunk(
        id = completion_id,
        created = created,
        model = model_name,
        choices = [ChunkChoice(delta = delta, finish_reason = finish_reason)],
    )
    return f"data: {chunk.model_dump_json(exclude_none = True)}\n\n"


def _chat_role_chunk(completion_id, created, model_name) -> str:
    """Opening assistant-role chunk for a chat stream."""
    return _chat_chunk_sse(
        completion_id,
        created,
        model_name,
        delta = ChoiceDelta(role = "assistant"),
        finish_reason = None,
    )


def _chat_content_chunk(completion_id, created, model_name, text) -> str:
    """A content-delta chunk carrying ``text``."""
    return _chat_chunk_sse(
        completion_id,
        created,
        model_name,
        delta = ChoiceDelta(content = text),
        finish_reason = None,
    )


def _chat_reasoning_chunk(completion_id, created, model_name, text) -> str:
    """Reasoning delta with empty content alongside, so strict OpenAI adapters do not drop it."""
    return _chat_chunk_sse(
        completion_id,
        created,
        model_name,
        delta = ChoiceDelta(content = "", reasoning_content = text),
        finish_reason = None,
    )


def _chat_final_chunk(completion_id, created, model_name, finish_reason) -> str:
    """Terminal stop chunk (empty delta) carrying the finish reason."""
    return _chat_chunk_sse(
        completion_id,
        created,
        model_name,
        delta = ChoiceDelta(),
        finish_reason = finish_reason,
    )


def _stats_finish_reason(
    stats,
    default: str = "stop",
    *,
    token_budget: int | None = None,
) -> str:
    """Trust the backend finish_reason; a count at the cap cannot tell stop from exhaustion. Callers whose backend says stop at cap may pass the budget."""
    if not isinstance(stats, dict):
        return default
    if stats.get("finish_reason") in ("stop", "length"):
        return stats["finish_reason"]
    if stats.get("truncated"):
        return "length"
    usage = stats.get("usage")
    completion_tokens = usage.get("completion_tokens") if isinstance(usage, dict) else None
    if (
        token_budget is not None
        and isinstance(completion_tokens, int)
        and not isinstance(completion_tokens, bool)
        and completion_tokens >= token_budget
    ):
        return "length"
    return default


def _safetensors_finish_reason(stats, payload, *, is_mlx: bool, durable_run: bool) -> str:
    """Normalize MLX's stop-at-cap only for server-owned Studio runs."""
    token_budget = _effective_openai_max_tokens(payload) if is_mlx and durable_run else None
    return _stats_finish_reason(stats, token_budget = token_budget)


def _chat_tool_calls_chunk(completion_id, created, model_name, tool_calls) -> str:
    """Delta chunk carrying OpenAI tool-call deltas (sibling of ``_chat_content_chunk``)."""
    return _chat_chunk_sse(
        completion_id,
        created,
        model_name,
        delta = ChoiceDelta(tool_calls = tool_calls),
        finish_reason = None,
    )


def _sf_heal_events_to_sse(
    events,
    completion_id,
    created,
    model_name,
    state,
    parallel_tool_calls,
    monitor_id = None,
):
    """parallel_tool_calls False caps promotion at one call; the monitor never sees healed-away markup."""
    lines = []
    for kind, value in events:
        if kind == "text":
            if value:
                lines.append(_chat_content_chunk(completion_id, created, model_name, value))
                api_monitor.append_reply(monitor_id, value)
            continue
        if parallel_tool_calls is False and state["idx"] >= 1:
            continue
        lines.append(
            _chat_tool_calls_chunk(
                completion_id,
                created,
                model_name,
                [
                    {
                        "index": state["idx"],
                        "id": value["id"],
                        "type": "function",
                        "function": value["function"],
                    }
                ],
            )
        )
        _fn = value.get("function") or {}
        api_monitor.append_reply(
            monitor_id,
            ("[tool_calls] " if state["idx"] == 0 else "; ")
            + f"{_fn.get('name', '')}({_fn.get('arguments', '')})",
        )
        state["idx"] += 1
    return lines


def _rewrite_cmpl_id(raw: bytes) -> bytes:
    """Rewrite llama-server's chat-style ``chatcmpl-`` ids to the ``cmpl-``
    prefix OpenAI's legacy /v1/completions use. Anchored on the ``"id":`` key
    (both spacing variants) so the rest of the body stays byte-exact."""
    return raw.replace(b'"id":"chatcmpl-', b'"id":"cmpl-').replace(
        b'"id": "chatcmpl-', b'"id": "cmpl-'
    )


def _cmpl_stream_event_out(event: bytes, include_usage: bool) -> Optional[bytes]:
    """Rewrite chatcmpl- ids to cmpl-; strip usage unless include_usage was requested, even when inline."""
    if include_usage:
        return _rewrite_cmpl_id(event)
    lines = event.split(b"\n")
    changed = False
    for i, ln in enumerate(lines):
        if not ln.startswith(b"data:"):
            continue
        payload = ln[len(b"data:") :].strip()
        if not payload or payload == b"[DONE]":
            continue
        try:
            obj = json.loads(payload)
        except Exception:
            continue
        if not isinstance(obj, dict) or obj.get("usage") is None:
            continue
        # Standalone usage-only chunk (chat-style) -> drop the whole event.
        if obj.get("choices") == []:
            return None
        # Usage on a content/finish chunk (completions-style) -> strip it.
        obj.pop("usage", None)
        lines[i] = b"data: " + json.dumps(obj, separators = (",", ":")).encode("utf-8")
        changed = True
    return _rewrite_cmpl_id(b"\n".join(lines) if changed else event)


def _classify_llama_generation_error(exc: Exception) -> Optional[bool]:
    """Checked before the substring test: KV starvation says context window but is no overflow; clients would compact a conversation that was never too long."""
    if isinstance(exc, context_refusal.ContextBudgetExceeded):
        return True
    if isinstance(exc, LlamaStreamError):
        # Only oversize is an overflow; others stay None (500) so clients retry.
        return True if exc.context_oversize else None
    msg = str(exc)
    msg_l = msg.lower()
    # Raw upstream KV starvation text trips the substring test below while meaning the opposite.
    if is_kv_starvation(msg):
        return None
    if "n_ctx" in msg_l or (
        "context" in msg_l and any(t in msg_l for t in ("exceed", "length", "window", "too long"))
    ):
        return True
    if _re.search(r"llama-server returned (4\d\d)", msg):
        return False
    return None


