def _llama_non_streaming_generation_timeout() -> httpx.Timeout:
    return httpx.Timeout(
        _DEFAULT_FIRST_TOKEN_TIMEOUT_S,
        read = socket_timeout(_first_token_timeout_s(whole_reply = True)),
    )


def _llama_streaming_generation_timeout() -> httpx.Timeout:
    return httpx.Timeout(
        _DEFAULT_FIRST_TOKEN_TIMEOUT_S, read = socket_timeout(_first_token_timeout_s())
    )


def _set_stream_response_read_timeout(
    response: httpx.Response, read_timeout_s: Optional[float] = _DEFAULT_STREAM_STALL_TIMEOUT_S
) -> None:
    # read_timeout_s=None (stall guard off) waits indefinitely, so no stale first-token deadline fires.
    try:
        timeout_ext = response.request.extensions.get("timeout")
        if isinstance(timeout_ext, dict):
            timeout_ext["read"] = read_timeout_s
    except Exception:
        pass


_STREAM_DISCONNECT_POLL_TIMEOUT_S = 0.25
_OPENAI_PASSTHROUGH_PREHEADER_STATUS_WINDOW_S = 0.1
_OPENAI_PASSTHROUGH_PENDING_RESPONSE_KEEPALIVE_S = 5.0
_OPENAI_PASSTHROUGH_SSE_KEEPALIVE = ": keep-alive\n\n"
# Whole comment frame incl. blank line: a bare line glues onto the next frame and is dropped; blank line yields empty events only if upstream sends id.


class _LlamaStreamKeepalive:
    """Pump wake-up, translated per call site and never treated as an upstream
    item (no stream state, healer or monitor). An object, not the comment
    string: every site filters relayed lines on ``startswith("data:")``."""

    __slots__ = ()

    def __repr__(self) -> str:
        return "<llama-stream-keepalive>"


_LLAMA_STREAM_KEEPALIVE = _LlamaStreamKeepalive()
# Lets a client tell "queued" from "backend silent"; SSE comments, so readers ignore both.
_OPENAI_ADMISSION_SSE_WAIT = ": admission-wait\n\n"
# Paired with the above: the slot is ours, so a suspended client clock starts now.
_OPENAI_ADMISSION_SSE_DONE = ": admission-done\n\n"
# A server-side tool still running, unlike a stall keep-alive: durable runs renew their lease on it.
_OPENAI_TOOL_HEARTBEAT_SSE = ": tool-heartbeat\n\n"
# Prefill advancing with nothing to stream; renews the lease like the tool heartbeat.
_OPENAI_PREFILL_PROGRESS_SSE = ": prefill-progress\n\n"
_OPENAI_LLAMA_ADMISSION_POLL_S = 0.25
# Request.is_disconnected() can swallow cancel(), so teardown abandons the task after this.
_TEARDOWN_TASK_STOP_TIMEOUT_S = 5.0
_TEARDOWN_TASK_RECANCEL_S = 0.01
# Keeps proxies alive during idle tool-loop gaps (Cloudflare drops idle at ~100s).
_LOCAL_TOOL_STREAM_STALL_KEEPALIVE_S = 15.0
# How often a UI stream looks for new prefill progress while the generator is silent.
_LIVE_PROGRESS_POLL_S = 0.25
# Minimum gap between two live decode frames: the client only redraws one line of text.
_LIVE_DECODE_FRAME_INTERVAL_S = 1.0
_APPROVAL_CACHE_RECLAIM_POLL_S = 0.25


def _openai_llama_admission_capacity(request: Optional[Request], llama_backend = None) -> int:
    """Slots from the loaded backend, which may lower --parallel at load; app state is only a fallback."""
    slots = _positive_int_or_none(getattr(llama_backend, "effective_parallel_slots", None))
    if slots is not None:
        return slots
    try:
        slots = getattr(request.app.state, "llama_parallel_slots", None)
    except Exception:
        slots = None
    return _positive_int_or_none(slots) or 1


def _openai_llama_admission_budget(llama_backend) -> Optional[int]:
    """Prefer aggregate KV total (context_length is per-slot after read-back, undercounts N-fold); else context_length; None means slot-only admission."""
    total = _positive_int_or_none(getattr(llama_backend, "_kv_cache_context_total", None))
    return total or _positive_int_or_none(getattr(llama_backend, "context_length", None))


def _openai_llama_admission_can_yield(llama_backend) -> bool:
    """Yield only where llama-server clears idle slot KV; under kv-unified without cache-idle-slots cells stay, so yielding would double-promise capacity."""
    return bool(getattr(llama_backend, "idle_slot_clearing_active", False))


def _openai_llama_admission_extra_prompt_tokens(payload) -> int:
    """Count system, tools and instructions outside messages; JSON schemas use the dense token rate."""
    extra = 0
    for attribute in ("system", "tools", "tool_choice", "instructions"):
        value = getattr(payload, attribute, None)
        if value is None or isinstance(value, (bool, int, float)):
            continue
        try:
            text = value if isinstance(value, str) else json.dumps(value, default = str)
        except Exception:
            continue
        if text:
            extra += estimate_messages_tokens_dense([{"role": "system", "content": text}])
    return extra


# Default per-image upper bound (llama.cpp Qwen-VL); a load may raise it (_openai_llama_admission_image_tokens); under-reserving overcommits KV.
_OPENAI_LLAMA_ADMISSION_IMAGE_EMBEDDING_CAP = 4096
_OPENAI_LLAMA_ADMISSION_IMAGE_WRAPPER_TOKENS = 128
_OPENAI_LLAMA_ADMISSION_IMAGE_TOKENS = (
    _OPENAI_LLAMA_ADMISSION_IMAGE_EMBEDDING_CAP + _OPENAI_LLAMA_ADMISSION_IMAGE_WRAPPER_TOKENS
)

# Upper bound: no mtmd audio projector emits over 25 embeddings per second.
# 30 s: Whisper-style preprocessing appends 30 s of silence before cutting 30 s windows.
_OPENAI_LLAMA_ADMISSION_AUDIO_TOKENS_PER_SECOND = 25
_OPENAI_LLAMA_ADMISSION_AUDIO_WINDOW_SECONDS = 30

# An estimate, not a bound: an uncapped plain chat can still overrun a full cache.
_OPENAI_LLAMA_ADMISSION_UNSTATED_OUTPUT_TOKENS = (
    _positive_int_or_none(os.environ.get("UNSLOTH_LLAMA_ADMISSION_UNSTATED_OUTPUT_TOKENS")) or 1024
)


def _openai_llama_admission_context_window(llama_backend) -> Optional[int]:
    """One slot, which under ``--no-kv-unified`` is 1/N of the aggregate budget."""
    return _positive_int_or_none(getattr(llama_backend, "context_length", None))


def _openai_llama_admission_output_allowance(
    cap: Optional[int],
    *,
    budget: int,
    prompt_tokens: int,
    context_window: Optional[int] = None,
    share: Optional[int] = None,
) -> int:
    """Cap at or above the window means unstated; charging the window serialises the queue, so cost at most the fair share when one is known."""
    window = context_window or budget
    if cap is not None and cap < window:
        return cap
    # Clamped to the WINDOW: a request cannot occupy more KV than its own slot holds.
    allowance = min(_OPENAI_LLAMA_ADMISSION_UNSTATED_OUTPUT_TOKENS, max(0, window - prompt_tokens))
    if share is not None and share > prompt_tokens:
        allowance = min(allowance, share - prompt_tokens)
    return allowance


def _extra_args_image_max_tokens(extra_args) -> Optional[int]:
    """Return the effective ``--image-max-tokens`` value."""
    from core.inference.llama_server_args import extra_args_image_max_tokens
    return extra_args_image_max_tokens(extra_args)


# Per-projector image caps from llama.cpp set_limit_image_tokens (keys: clip.projector_type); no universal default, absent families use the default.
_MMPROJ_IMAGE_TOKEN_MAX = {
    "qwen2vl_merger": 4096,
    "qwen2.5vl_merger": 4096,
    "qwen3vl_merger": 4096,
    "glm4v": 4096,
    "kimik25": 4096,
    "muse-glimmer": 4096,
    "youtuvl": 62500,
    "hunyuanvl": 16384,
    "pixtral": 1024,
    "lightonocr": 1024,
    "kimivl": 1024,
    "minimax_m3": 576,
    "gemma4v": 280,
    "gemma4uv": 280,
    "lfm2": 256,
}


def _openai_llama_admission_image_tokens(llama_backend) -> int:
    """Per-image KV cost: the larger of projector figure and --image-max-tokens, since llama-server ignores the flag on fixed-resolution projectors."""
    if getattr(llama_backend, "is_vision", True) is False:
        return 0
    projector = getattr(llama_backend, "_mmproj_projector_type", None)
    known = _MMPROJ_IMAGE_TOKEN_MAX.get(str(projector).strip().lower()) if projector else None
    cap = max(
        known or _OPENAI_LLAMA_ADMISSION_IMAGE_EMBEDDING_CAP,
        _extra_args_image_max_tokens(getattr(llama_backend, "_extra_args", None)) or 0,
    )
    return cap + _OPENAI_LLAMA_ADMISSION_IMAGE_WRAPPER_TOKENS


_ADMISSION_IMAGE_PART_TYPES = ("image_url", "image")
# Both spellings: tool-loop recost runs after _translate_video_parts renames the part; video_url alone would price base64 video as prompt text.
_ADMISSION_VIDEO_PART_TYPES = ("video_url", "input_video")


def _openai_llama_admission_compact_image_part(part: dict) -> dict:
    """Swap image base64 for a marker but keep the wrapper; that JSON is real prompt text."""
    if part.get("type") == "image":
        source = part.get("source")
        compact_source = {"type": "base64", "data": "[image]"}
        if isinstance(source, dict) and source.get("media_type") is not None:
            compact_source["media_type"] = source["media_type"]
        return {"type": "image", "source": compact_source}

    image_url = part.get("image_url")
    compact_image_url = {"url": "[image]"}
    if isinstance(image_url, dict) and image_url.get("detail") is not None:
        compact_image_url["detail"] = image_url["detail"]
    return {"type": "image_url", "image_url": compact_image_url}


def _openai_llama_admission_messages_for_estimate(
    messages, *, vision: bool = True
) -> tuple[list[dict], int]:
    """Strip image bytes before estimating text; mtmd token counts follow the model, not base64 size."""
    estimate_messages = []
    image_parts = 0
    # Envelope images charged separately so attachments beyond promote_history's cap still count.
    envelope_image_parts = 0
    # Unnamed results tied to non-MCP calls are never promoted, so do not charge them.
    _resolved = _mcp_resolve_tool_names(messages)
    for _index, message in enumerate(messages):
        # exclude_none, or unset optionals serialise as null and get priced as prompt text.
        message_dict = (
            message if isinstance(message, dict) else message.model_dump(exclude_none = True)
        )
        estimate_message = dict(message_dict)
        content = message_dict.get("content")
        if message_dict.get("role") == "tool" and isinstance(content, str):
            # MCP envelope becomes projector images later: strip the base64 and charge images instead.
            head, envelope_images = split_mcp_images(content)
            if envelope_images:
                # Generation strips the suffix for everyone, so it is never priced
                # as prompt text.
                estimate_message["content"] = head
                # Charge only images actually sent: not for text-only models or non-MCP results.
                _correlated = _resolved.get(_index)
                _non_mcp = _names_a_non_mcp_tool(message_dict) or (
                    isinstance(_correlated, str)
                    and bool(_correlated)
                    and not is_image_tool(_correlated)
                )
                if vision and not _non_mcp:
                    # Only Pillow-readable entries; promotion drops the rest.
                    envelope_image_parts += min(
                        _mcp_count_probably_decodable(envelope_images),
                        _MCP_MAX_MODEL_IMAGES,
                    )
            estimate_messages.append(estimate_message)
            continue
        if isinstance(content, list):
            estimate_content = []
            for part in content:
                if not isinstance(part, dict):
                    estimate_content.append(part)
                    continue

                part_type = part.get("type")
                if reference := anthropic_reference_block_text(part):
                    estimate_content.append({"type": "text", "text": reference})
                    continue

                # Match the native tool-result conversion: only the blocks it renders reach the wire.
                if part_type == "tool_result" and isinstance(part.get("content"), list):
                    part = dict(part)
                    tool_content = []
                    for block in part["content"]:
                        if not isinstance(block, dict):
                            continue
                        if block.get("type") == "text":
                            tool_content.append(block)
                        elif reference := anthropic_reference_block_text(block):
                            tool_content.append({"type": "text", "text": reference})
                        elif block.get("type") == "image":
                            image_parts += 1
                            tool_content.append(_openai_llama_admission_compact_image_part(block))
                    part["content"] = tool_content
                    estimate_content.append(part)
                    continue

                # Priced by its own byte allowance, not as an image and not as prompt text.
                if part_type in _ADMISSION_VIDEO_PART_TYPES:
                    estimate_content.append({"type": part_type, part_type: {"url": "[video]"}})
                    continue

                # The recording is charged by duration from ``audio_base64``.
                if part_type == "input_audio":
                    estimate_content.append({"type": part_type, part_type: {"data": "[audio]"}})
                    continue

                if part_type not in _ADMISSION_IMAGE_PART_TYPES:
                    estimate_content.append(part)
                    continue

                image_parts += 1
                estimate_content.append(_openai_llama_admission_compact_image_part(part))
            estimate_message["content"] = estimate_content
        estimate_messages.append(estimate_message)
    # Cap replay images separately from caller attachments, matching GGUF promotion.
    return estimate_messages, image_parts + min(envelope_image_parts, _MCP_MAX_TOTAL_MODEL_IMAGES)


def _conversation_video_clips(messages) -> list[str]:
    """Find video clips in both spellings, since the loop recosts after the video part has been renamed."""
    clips: list[str] = []
    for msg in messages or []:
        content = msg.get("content") if isinstance(msg, dict) else getattr(msg, "content", None)
        if not isinstance(content, list):
            continue
        for part in content:
            if not isinstance(part, dict):
                continue
            media = part.get(part.get("type") or "")
            if part.get("type") not in _ADMISSION_VIDEO_PART_TYPES or not isinstance(media, dict):
                continue
            value = media.get("data") or media.get("url") or ""
            if isinstance(value, str) and value:
                clips.append(value)
    return clips


def _openai_llama_admission_audio_tokens(b64: str) -> int:
    fallback = max(1, len(b64) // 4)
    if b64.startswith("data:"):
        b64 = b64.split(",", 1)[1] if "," in b64 else ""
    try:
        raw = base64.b64decode(b64)
    except Exception:
        return fallback
    container = _sniff_audio_container(raw)
    seconds = _passthrough_audio_seconds(raw, container, _MAX_AUDIO_SECONDS) if container else None
    if seconds is None:
        return fallback
    return (
        math.ceil(
            _OPENAI_LLAMA_ADMISSION_AUDIO_TOKENS_PER_SECOND
            * (seconds + _OPENAI_LLAMA_ADMISSION_AUDIO_WINDOW_SECONDS)
        )
        + _OPENAI_LLAMA_ADMISSION_IMAGE_WRAPPER_TOKENS
    )


def _openai_llama_admission_media_tokens(
    payload,
    *,
    message_image_parts: int = 0,
    image_tokens: int = _OPENAI_LLAMA_ADMISSION_IMAGE_TOKENS,
    message_video_clips: Optional[list[str]] = None,
    legacy_image_in_messages: bool = False,
) -> int:
    """Charge the legacy top-level image only when the messages do not already carry it: no double count."""
    extra = 0
    extra += max(0, message_image_parts) * image_tokens
    if not legacy_image_in_messages and _legacy_image_is_distinct(payload):
        extra += image_tokens
    for audio in _request_audio_clips(payload):
        if isinstance(audio, str) and audio:
            extra += _openai_llama_admission_audio_tokens(audio)
    # _inject_video_part already spliced the legacy clip in, so do not charge it twice.
    if message_video_clips is None:
        value = getattr(payload, "video_base64", None)
        if isinstance(value, str) and value:
            extra += max(1, len(value) // 4)
    # Use the current conversation so evicted clips stop being charged.
    clips = (
        message_video_clips
        if message_video_clips is not None
        else _message_video_urls(getattr(payload, "messages", None))
    )
    for clip in clips:
        extra += max(1, len(clip) // 4)
    return extra


def _openai_llama_admission_injected_tool_tokens(injected_tools) -> int:
    """Price the tool catalogue Unsloth injects itself; the message list cannot see it, about 1250
    tokens."""
    if not injected_tools:
        return 0
    try:
        text = json.dumps(injected_tools, default = str)
    except Exception:
        return 0
    if not text:
        return 0
    return estimate_messages_tokens_dense([{"role": "system", "content": text}])


def _openai_llama_admission_tokens(
    payload,
    *,
    budget: Optional[int],
    capacity: int,
    tool_loop: bool = False,
    image_tokens: int = _OPENAI_LLAMA_ADMISSION_IMAGE_TOKENS,
    injected_tools = None,
    context_window: Optional[int] = None,
    counted_prompt_tokens: Optional[int] = None,
    vision: bool = True,
    messages_override = None,
) -> Optional[int]:
    """Dense estimator (plain one undercounts CJK ~2x); equal cache share when there are no messages."""
    if not budget:
        return None
    # Use translated messages: raw Anthropic blocks bypass envelope handling and misprice.
    messages = (
        messages_override if messages_override is not None else getattr(payload, "messages", None)
    )
    if counted_prompt_tokens is not None:
        prompt_tokens = counted_prompt_tokens
    elif isinstance(messages, list) and messages:
        try:
            estimate_messages, message_image_parts = _openai_llama_admission_messages_for_estimate(
                messages, vision = vision
            )
            prompt_tokens = estimate_messages_tokens_dense(estimate_messages)
            prompt_tokens += _openai_llama_admission_extra_prompt_tokens(payload)
            prompt_tokens += _openai_llama_admission_injected_tool_tokens(injected_tools)
            prompt_tokens += _openai_llama_admission_media_tokens(
                payload,
                message_image_parts = message_image_parts,
                image_tokens = image_tokens,
            )
        except Exception:
            prompt_tokens = None
    else:
        prompt_tokens = None
    if prompt_tokens is None:
        return max(1, budget // max(1, capacity))
    # Honour max_completion_tokens too, not just the deprecated max_tokens.
    cap = _positive_int_or_none(
        _effective_openai_max_tokens_from_values(
            getattr(payload, "max_tokens", None),
            getattr(payload, "max_completion_tokens", None),
        )
    )
    # Reserving the rest of the budget for either made concurrency 1 for the default chat.
    output_tokens = _openai_llama_admission_output_allowance(
        cap,
        budget = budget,
        prompt_tokens = prompt_tokens,
        context_window = context_window,
        share = max(1, budget // max(1, capacity)),
    )
    # Keyed on resolved path, not payload.tools: Unsloth's own loops run without a client tools array.
    if tool_loop:
        # Not clamped to the share: a first round may use its full output before any re-cost.
        share = max(1, budget // max(1, capacity))
        return max(1, min(budget, max(share, prompt_tokens + output_tokens)))
    # Clamped so an oversized request is admitted alone and llama-server refuses it clearly.
    return max(1, min(budget, prompt_tokens + output_tokens))


def _openai_llama_admission_estimate(
    *,
    request: Optional[Request],
    llama_backend,
    payload,
    tool_loop: bool = False,
    injected_tools = None,
    messages_override = None,
):
    """The token estimate a reservation is sized by. Split from the reservation so a
    caller on the event loop can compute it in a worker: it strips every replayed
    envelope, which json-loads a permitted 12 MB array per result."""
    capacity = _openai_llama_admission_capacity(request, llama_backend)
    budget = _openai_llama_admission_budget(llama_backend)
    return _openai_llama_admission_tokens(
        payload,
        budget = budget,
        capacity = capacity,
        tool_loop = tool_loop,
        image_tokens = _openai_llama_admission_image_tokens(llama_backend),
        injected_tools = injected_tools,
        context_window = _openai_llama_admission_context_window(llama_backend),
        vision = bool(getattr(llama_backend, "is_vision", False)),
        messages_override = messages_override,
    )


_TOKENS_UNSET = object()


def _openai_llama_admission_reserve(
    *,
    request: Optional[Request],
    llama_backend,
    payload = None,
    tool_loop: bool = False,
    injected_tools = None,
    counted_prompt_tokens: Optional[int] = None,
    messages_override = None,
    tokens = _TOKENS_UNSET,
) -> tuple[LlamaAdmissionReservation, LlamaAdmissionConfig]:
    config = llama_admission_config_from_env()
    capacity = _openai_llama_admission_capacity(request, llama_backend)
    key = str(getattr(llama_backend, "base_url", "llama-server"))
    budget = _openai_llama_admission_budget(llama_backend)
    if counted_prompt_tokens is not None:
        tokens = _openai_llama_admission_tokens(
            payload,
            counted_prompt_tokens = counted_prompt_tokens,
            budget = budget,
            capacity = capacity,
            tool_loop = tool_loop,
            context_window = _openai_llama_admission_context_window(llama_backend),
        )
    elif tokens is _TOKENS_UNSET:
        tokens = (
            _openai_llama_admission_estimate(
                request = request,
                llama_backend = llama_backend,
                payload = payload,
                tool_loop = tool_loop,
                injected_tools = injected_tools,
                messages_override = messages_override,
            )
            if payload is not None
            else None
        )
    # reserve() binds a waiter to the running loop, so it must stay on the loop.
    reservation = get_llama_admission_queue(key).reserve(
        capacity = capacity,
        config = config,
        budget = budget,
        tokens = tokens,
    )
    return reservation, config


def _preserve_probe_pending(llama_backend) -> bool:
    """Whether resolving preserve_thinking may still make the one-off template probe (HTTP)."""
    if not getattr(llama_backend, "_supports_preserve_thinking", False):
        return False
    cached = getattr(llama_backend, "_empty_think_preserve_probe", None)
    key = getattr(llama_backend, "_empty_think_probe_key", None)
    return key is not None and (cached is None or cached[0] != key())


def _replay_preserve_thinking(llama_backend, payload, messages):
    """The preserve_thinking generation will render with, so counts price the same prompt."""
    resolver = getattr(llama_backend, "_replay_preserve_thinking", None)
    # An Anthropic recount: conversion dropped replayed thinking the resolver would miss.
    if resolver is None or _anthropic_history_has_thinking(payload):
        return payload.preserve_thinking
    return resolver(
        payload.preserve_thinking, messages, payload.enable_thinking, payload.reasoning_effort
    )


def _count_gguf_admission_prompt(
    llama_backend,
    payload,
    messages,
    tools = None,
    cancel_event = None,
    *,
    prepared_body = None,
) -> int:
    """Exact prompt count plus media allowance; the whole pool if counting fails
    (the character estimate undercounts numeric text, #10671)."""
    from core.inference.chat_template_helpers import trailing_assistant_resume_kind

    budget = _openai_llama_admission_budget(llama_backend) or 0
    try:
        text_messages, images = _openai_llama_admission_messages_for_estimate(
            messages, vision = bool(getattr(llama_backend, "is_vision", False))
        )
        if prepared_body is None:
            template_kwargs = llama_backend._request_reasoning_kwargs(
                payload.enable_thinking,
                payload.reasoning_effort,
                _replay_preserve_thinking(llama_backend, payload, messages),
            )
            continue_final = (
                _continue_final_message(payload, thought = True)
                and trailing_assistant_resume_kind(messages) is not None
            )
        else:
            template_kwargs = prepared_body.get("chat_template_kwargs")
            continue_final = bool(prepared_body.get("continue_final_message"))
        count = llama_backend.count_chat_tokens(
            messages_without_unpriced_media(text_messages),
            tools = tools,
            strict = True,
            prefer_native = images == 0,
            chat_template_kwargs = template_kwargs,
            continue_final_message = continue_final,
            **({"template_options": prepared_body} if prepared_body is not None else {}),
            **({"should_abort": cancel_event.is_set} if cancel_event is not None else {}),
        )
        if type(count) is not int or count <= 0:
            raise ValueError("Invalid prompt token count")
        return count + _openai_llama_admission_media_tokens(
            payload,
            message_image_parts = images,
            image_tokens = _openai_llama_admission_image_tokens(llama_backend),
            message_video_clips = _conversation_video_clips(messages),
            legacy_image_in_messages = prepared_body is not None,
        )
    except Exception:
        logger.debug("Prompt count unavailable; reserving the context pool", exc_info = True)
        return budget


async def _reserve_counted_gguf_chat(
    *,
    request,
    llama_backend,
    payload,
    messages,
    injected_tools = None,
    tool_loop: bool = False,
    prepared_body = None,
):
    config = llama_admission_config_from_env()
    if not (config.enabled and config.kv_budget):
        return await _openai_llama_admission_reserve_async(
            request = request,
            llama_backend = llama_backend,
            payload = payload,
            tool_loop = tool_loop,
            injected_tools = injected_tools,
        )
    identity = (
        getattr(llama_backend, "base_url", None),
        _openai_llama_admission_budget(llama_backend),
    )
    counted = await asyncio.to_thread(
        _count_gguf_admission_prompt,
        llama_backend,
        payload,
        messages,
        injected_tools,
        **({"prepared_body": prepared_body} if prepared_body is not None else {}),
    )
    if identity != (
        getattr(llama_backend, "base_url", None),
        _openai_llama_admission_budget(llama_backend),
    ):
        counted = _openai_llama_admission_budget(llama_backend)
    return _openai_llama_admission_reserve(
        request = request,
        llama_backend = llama_backend,
        payload = payload,
        tool_loop = tool_loop,
        injected_tools = injected_tools,
        counted_prompt_tokens = counted,
    )


async def _reserve_counted_gguf_passthrough(
    *,
    request,
    llama_backend,
    payload,
    body = None,
):
    # Price the same prepared messages, tool schemas and template options that
    # generation sends. A character estimate misses numeric text and tool wrappers.
    if body is None:
        body = await _build_openai_passthrough_body_async(
            payload, backend_ctx = llama_backend.context_length, llama_backend = llama_backend
        )
    reservation, config = await _reserve_counted_gguf_chat(
        request = request,
        llama_backend = llama_backend,
        payload = payload,
        messages = body["messages"],
        injected_tools = body.get("tools"),
        prepared_body = body,
    )
    return reservation, config, body


async def _openai_llama_admission_reserve_async(
    *,
    request: Optional[Request],
    llama_backend,
    payload = None,
    tool_loop: bool = False,
    injected_tools = None,
    messages_override = None,
) -> tuple[LlamaAdmissionReservation, LlamaAdmissionConfig]:
    """The same reservation, with the estimate off the loop when a replayed envelope
    would make it parse one, or a recording would make it decode one."""
    tokens = _TOKENS_UNSET
    if payload is not None and (
        getattr(payload, "audio_base64", None)
        or _messages_mention_mcp_images(
            messages_override if messages_override is not None else payload.messages
        )
    ):
        tokens = await asyncio.to_thread(
            _openai_llama_admission_estimate,
            request = request,
            llama_backend = llama_backend,
            payload = payload,
            tool_loop = tool_loop,
            injected_tools = injected_tools,
            messages_override = messages_override,
        )
    return _openai_llama_admission_reserve(
        request = request,
        llama_backend = llama_backend,
        payload = payload,
        tool_loop = tool_loop,
        injected_tools = injected_tools,
        messages_override = messages_override,
        tokens = tokens,
    )


def _openai_llama_admission_recost(
    reservation,
    conversation,
    *,
    request: Optional[Request],
    llama_backend,
    payload = None,
    output_tokens: Optional[int] = None,
    cancel_event = None,
    injected_tools = None,
    count_prepared_prompt: bool = False,
    prepared_body = None,
    cache_is_empty: bool = False,
) -> None:
    """Re-cost each round; growth that does not fit waits; yield gated on _openai_llama_admission_can_yield."""
    if reservation is None or (cancel_event is not None and cancel_event.is_set()):
        return
    config = llama_admission_config_from_env()
    if not (config.enabled and config.kv_budget):
        return
    try:
        lease = reservation.lease_nowait()
        if lease is None:
            return
        budget = _openai_llama_admission_budget(llama_backend)
        if not budget:
            return
        capacity = _openai_llama_admission_capacity(request, llama_backend)
        if count_prepared_prompt:
            prompt_tokens = _count_gguf_admission_prompt(
                llama_backend,
                payload,
                conversation,
                injected_tools,
                cancel_event = cancel_event,
                **({"prepared_body": prepared_body} if prepared_body is not None else {}),
            )
            if cancel_event is not None and cancel_event.is_set():
                return
        else:
            # Charge every term the opening reservation did, or the lease shrinks at round zero.
            estimate_messages, message_image_parts = _openai_llama_admission_messages_for_estimate(
                conversation,
                vision = bool(getattr(llama_backend, "is_vision", False)),
            )
            prompt_tokens = estimate_messages_tokens_dense(estimate_messages)
            prompt_tokens += _openai_llama_admission_injected_tool_tokens(injected_tools)
            # Anthropic keeps `system` and `tools` outside the message list.
            prompt_tokens += _openai_llama_admission_extra_prompt_tokens(payload)
            # mtmd embeddings: image parts compact to "[image]" in the text estimate.
            prompt_tokens += _openai_llama_admission_media_tokens(
                payload,
                message_image_parts = message_image_parts,
                image_tokens = _openai_llama_admission_image_tokens(llama_backend),
                message_video_clips = _conversation_video_clips(conversation),
            )
        # Reading 'Max' literally would put the run back on the whole cache at its first round.
        share = max(1, budget // max(1, capacity))
        output_tokens = _openai_llama_admission_output_allowance(
            output_tokens,
            budget = budget,
            prompt_tokens = prompt_tokens,
            context_window = _openai_llama_admission_context_window(llama_backend),
            share = share,
        )
        want = max(1, min(budget, max(share, prompt_tokens + max(0, output_tokens))))
        lease.recost_waiting(
            want,
            cancel_event = cancel_event,
            allow_yield = cache_is_empty or _openai_llama_admission_can_yield(llama_backend),
        )
    except Exception:  # pragma: no cover - accounting must not break a live run
        logger.debug("llama admission recost failed", exc_info = True)


def _openai_admission_request_path(request: Optional[Request]) -> Optional[str]:
    try:
        return str(request.url.path) if request is not None else None
    except Exception:
        return None


def _llama_admission_log(
    event: str,
    reservation: Optional[LlamaAdmissionReservation] = None,
    *,
    snapshot = None,
    request: Optional[Request],
    mode: str,
    wait_started_at: Optional[float] = None,
    completion_id: Optional[str] = None,
    level: str = "debug",
) -> None:
    if snapshot is None and reservation is not None:
        snapshot = reservation.snapshot_now()
    wait_ms = None
    if wait_started_at is not None:
        wait_ms = int(max(0.0, time.monotonic() - wait_started_at) * 1000)
    log = getattr(logger, level, logger.debug)
    log(
        "llama admission %s: mode=%s path=%s completion_id=%s "
        "pool=%s/%s free=%s queued=%s wait_ms=%s",
        event,
        mode,
        _openai_admission_request_path(request),
        completion_id,
        getattr(snapshot, "active", None),
        getattr(snapshot, "capacity", None),
        getattr(snapshot, "free", None),
        getattr(snapshot, "queued", None),
        wait_ms,
    )


def _openai_admission_error_body(exc: Exception, *, status_code: int) -> dict:
    snapshot = getattr(exc, "snapshot", None)
    message = str(exc)
    if snapshot is not None:
        message = (
            f"{message} "
            f"(active={snapshot.active}, queued={snapshot.queued}, capacity={snapshot.capacity})"
        )
    return openai_error_body(message, status = status_code)


def _openai_admission_http_exception(exc: Exception, *, status_code: int) -> HTTPException:
    return HTTPException(
        status_code = status_code,
        detail = _openai_admission_error_body(exc, status_code = status_code),
    )


def _anthropic_admission_http_exception(exc: Exception, *, status_code: int) -> HTTPException:
    """Anthropic-shaped error for an admission reject/timeout/cancel (429/503/499)."""
    snapshot = getattr(exc, "snapshot", None)
    message = str(exc)
    if snapshot is not None:
        message = (
            f"{message} "
            f"(active={snapshot.active}, queued={snapshot.queued}, capacity={snapshot.capacity})"
        )
    # 429 -> rate_limit_error (SDKs back off on it); overloaded_error is reserved for 529.
    return HTTPException(
        status_code = status_code,
        detail = anthropic_error_body(message, status = status_code),
    )


def _openai_admission_timeout_error(
    reservation: LlamaAdmissionReservation,
) -> LlamaAdmissionTimeout:
    return LlamaAdmissionTimeout(
        "Timed out waiting for an available local llama-server generation slot",
        snapshot = reservation.snapshot_now(),
    )


def _openai_admission_cancelled_error(
    reservation: LlamaAdmissionReservation,
) -> LlamaAdmissionCancelled:
    return LlamaAdmissionCancelled(
        "Client disconnected before an upstream llama-server generation slot was available",
        snapshot = reservation.snapshot_now(),
    )


async def _raise_if_openai_admission_cancelled(
    reservation: LlamaAdmissionReservation, *, request: Optional[Request], cancel_event
) -> None:
    # Cancelled before leasing an upstream, so the model was never used. A streaming caller
    # has flushed the 200 headers and its `except LlamaAdmissionCancelled` just returns, so
    # flag failed: the middleware must not treat that empty 200 as a successful generation and
    # claim a preview-owned slot. Harmless for non-streaming callers (they surface a non-2xx).
    from core.inference.llama_keepwarm import mark_current_response_failed
    if reservation.is_cancelled:
        mark_current_response_failed()
        raise _openai_admission_cancelled_error(reservation)
    if await _preheader_cancelled(cancel_event, request):
        reservation.cancel()
        mark_current_response_failed()
        raise _openai_admission_cancelled_error(reservation)


async def _wait_for_openai_admission_non_streaming(
    reservation: LlamaAdmissionReservation,
    config: LlamaAdmissionConfig,
    *,
    request: Optional[Request],
    cancel_event,
) -> LlamaAdmissionLease:
    lease = reservation.lease_nowait()
    if lease is not None:
        try:
            await _raise_if_openai_admission_cancelled(
                reservation,
                request = request,
                cancel_event = cancel_event,
            )
        except asyncio.CancelledError:
            lease.release()
            raise
        except LlamaAdmissionCancelled:
            lease.release()
            raise
        return lease
    await _raise_if_openai_admission_cancelled(
        reservation,
        request = request,
        cancel_event = cancel_event,
    )
    deadline = None if config.queue_timeout_s is None else time.monotonic() + config.queue_timeout_s
    try:
        while True:
            await _raise_if_openai_admission_cancelled(
                reservation,
                request = request,
                cancel_event = cancel_event,
            )
            lease = reservation.lease_nowait()
            if lease is not None:
                try:
                    await _raise_if_openai_admission_cancelled(
                        reservation,
                        request = request,
                        cancel_event = cancel_event,
                    )
                except asyncio.CancelledError:
                    lease.release()
                    raise
                except LlamaAdmissionCancelled:
                    lease.release()
                    raise
                return lease
            wait_s = _OPENAI_LLAMA_ADMISSION_POLL_S
            if deadline is not None:
                remaining_s = deadline - time.monotonic()
                if remaining_s <= 0:
                    reservation.cancel()
                    raise _openai_admission_timeout_error(reservation)
                wait_s = min(wait_s, max(remaining_s, 0.001))
            try:
                lease = await reservation.wait(wait_s)
            except asyncio.TimeoutError:
                continue
            if lease is not None:
                return lease
            await _raise_if_openai_admission_cancelled(
                reservation,
                request = request,
                cancel_event = cancel_event,
            )
    except asyncio.CancelledError:
        reservation.cancel()
        raise


async def _openai_admission_wait_stream_chunks(
    reservation: LlamaAdmissionReservation,
    config: LlamaAdmissionConfig,
    *,
    request: Optional[Request],
    cancel_event,
):
    lease = reservation.lease_nowait()
    if lease is not None:
        yield lease
        return

    await _raise_if_openai_admission_cancelled(
        reservation,
        request = request,
        cancel_event = cancel_event,
    )
    deadline = None if config.queue_timeout_s is None else time.monotonic() + config.queue_timeout_s
    keepalive_interval_s = max(0.001, config.keepalive_interval_s)
    # At once, not after a full interval: a caller must not wait one out to learn it queued.
    yield _OPENAI_ADMISSION_SSE_WAIT
    next_keepalive_at = time.monotonic() + keepalive_interval_s
    try:
        while True:
            await _raise_if_openai_admission_cancelled(
                reservation,
                request = request,
                cancel_event = cancel_event,
            )
            lease = reservation.lease_nowait()
            if lease is not None:
                yield _OPENAI_ADMISSION_SSE_DONE
                yield lease
                return

            now = time.monotonic()
            wait_s = min(_OPENAI_LLAMA_ADMISSION_POLL_S, max(next_keepalive_at - now, 0.001))
            if deadline is not None:
                remaining_s = deadline - now
                if remaining_s <= 0:
                    reservation.cancel()
                    raise _openai_admission_timeout_error(reservation)
                wait_s = min(wait_s, max(remaining_s, 0.001))
            try:
                lease = await reservation.wait(wait_s)
            except asyncio.TimeoutError:
                lease = None
            if lease is not None:
                yield _OPENAI_ADMISSION_SSE_DONE
                yield lease
                return
            await _raise_if_openai_admission_cancelled(
                reservation,
                request = request,
                cancel_event = cancel_event,
            )
            now = time.monotonic()
            if now >= next_keepalive_at:
                next_keepalive_at = now + keepalive_interval_s
                yield _OPENAI_ADMISSION_SSE_WAIT
    except asyncio.CancelledError:
        reservation.cancel()
        raise


async def _close_openai_admitted_stream_iterator(iterator, *, cancelled: bool) -> None:
    if iterator is None:
        return
    if cancelled:
        athrow = getattr(iterator, "athrow", None)
        if athrow is not None:
            try:
                await athrow(asyncio.CancelledError())
            except (asyncio.CancelledError, StopAsyncIteration, RuntimeError):
                return
    aclose = getattr(iterator, "aclose", None)
    if aclose is not None:
        await aclose()


def _openai_compat_stream_stall_timeout():
    """Silent gap allowed after SSE data; defaults to the backend stall timeout, and 0 disables it."""
    return _positive_float_env(
        _OPENAI_COMPAT_STREAM_STALL_TIMEOUT_ENV,
        _DEFAULT_STREAM_STALL_TIMEOUT_S,
    )


def _finite_positive_float_env(env_name: str, default):
    """Float env value that rejects inf and NaN: an infinite deadline never fires, so the default
    applies."""
    value = _positive_float_env(env_name, default)
    if isinstance(value, float) and not math.isfinite(value):
        return default
    return value


def _first_token_timeout_s(*, whole_reply: bool = False) -> float:
    """The saved wait limit; a positive UNSLOTH_OPENAI_COMPAT_FIRST_TOKEN_TIMEOUT wins.

    ``whole_reply`` is for a read that spans an entire non-streamed generation, which a
    limit shortened below the default must not cut.
    """
    default = configured_first_token_timeout_s()
    if whole_reply:
        default = max(default, _DEFAULT_FIRST_TOKEN_TIMEOUT_S)
    value = _finite_positive_float_env(_OPENAI_COMPAT_FIRST_TOKEN_TIMEOUT_ENV, default)
    return default if value is None else value


def _openai_passthrough_stream_keepalive_interval():
    """Keepalive gap; llama-server is silent through prefill and undici aborts at 300s; 0 disables."""
    return _finite_positive_float_env(
        _OPENAI_COMPAT_STREAM_KEEPALIVE_ENV,
        _OPENAI_PASSTHROUGH_PENDING_RESPONSE_KEEPALIVE_S,
    )


def _openai_passthrough_upstream_headers(*, llama_backend = None) -> dict:
    headers = {}
    auth_headers = getattr(llama_backend, "_auth_headers", None)
    if isinstance(auth_headers, dict):
        headers.update(auth_headers)
    headers["Connection"] = "close"
    return headers


class _SameTaskStreamingResponse(StreamingResponse):
    """StreamingResponse without Starlette's legacy AnyIO task-group wrapper."""

    def __init__(
        self,
        *args,
        unstarted_cleanup = None,
        **kwargs,
    ) -> None:
        super().__init__(*args, **kwargs)
        # Run if the client disconnects before the body iterator starts (its finally never runs).
        self._unstarted_cleanup = unstarted_cleanup

    async def __call__(self, scope, receive, send) -> None:
        # No body message means the generator never entered its try/finally.
        body_started = False

        async def _tracking_send(message) -> None:
            nonlocal body_started
            if message.get("type") == "http.response.body":
                body_started = True
            await send(message)

        try:
            await self.stream_response(_tracking_send)
        except OSError:  # client disconnected mid-send
            if body_started:
                # CancelledError, not GeneratorExit, so its handler finishes the api_monitor entry.
                athrow = getattr(self.body_iterator, "athrow", None)
                if athrow is not None:
                    try:
                        await athrow(asyncio.CancelledError())
                    except (asyncio.CancelledError, StopAsyncIteration, RuntimeError):
                        pass
                else:
                    aclose = getattr(self.body_iterator, "aclose", None)
                    if aclose is not None:
                        await aclose()
            else:
                # Never started: aclose/athrow are no-ops, so release eager resources via the hook.
                # getattr: tests may build this via __new__ without __init__.
                aclose = getattr(self.body_iterator, "aclose", None)
                if aclose is not None:
                    await aclose()
                cleanup = getattr(self, "_unstarted_cleanup", None)
                if cleanup is not None:
                    try:
                        await cleanup()
                    except Exception:
                        pass
            raise ClientDisconnect()
        if self.background is not None:
            await self.background()


async def _release_unstarted_anthropic_stream(iterator, prior_cleanup) -> None:
    """aclose() skips an unstarted generator's finally, so the pre-start hook must release eager state."""
    aclose = getattr(iterator, "aclose", None)
    if aclose is not None:
        try:
            await aclose()
        except Exception:
            pass
    if prior_cleanup is not None:
        try:
            await prior_cleanup()
        except Exception:
            pass


def _tracked_cancel_unstarted_cleanup(tracker):
    """unstarted_cleanup that exits ``tracker`` on a pre-start disconnect, when
    the generator's finally (which normally exits it) never runs."""

    async def _cleanup() -> None:
        tracker.__exit__(None, None, None)

    return _cleanup


# Cloudflare quick tunnels drop a request with no body bytes for ~100s; pad with whitespace
# (leading whitespace is legal JSON, so clients parse the body as-is).
_TUNNEL_KEEPALIVE_AFTER_S = 15.0
_TUNNEL_KEEPALIVE_EVERY_S = 20.0

# Underscored so it cannot collide with a real field or the OpenAI ``error`` envelope.
_DEFERRED_ERROR_KEY = "_deferred_error"


# Headers a padded error keeps in its body: the status line and headers were already sent.
_DEFERRED_ERROR_HEADERS = ("x-unsloth-refusal", "retry-after")


def _deferred_error_body(
    status_code: int,
    detail,
    headers: Optional[dict] = None,
) -> bytes:
    body = {_DEFERRED_ERROR_KEY: {"status_code": status_code, "detail": detail}}
    kept = {
        name.lower(): value
        for name, value in (headers or {}).items()
        if name.lower() in _DEFERRED_ERROR_HEADERS
    }
    if kept:
        body[_DEFERRED_ERROR_KEY]["headers"] = kept
    return json.dumps(body).encode()


def _handle_restored_http_exception(exc: HTTPException) -> HTTPException:
    """A new exception rather than a mutated one, so status code and headers stay as raised."""
    from hub.utils.host_paths import restore_inventory_handles

    detail = restore_inventory_handles(exc.detail)
    if detail == exc.detail:
        return exc
    return HTTPException(status_code = exc.status_code, detail = detail, headers = exc.headers)


async def _tunnel_safe_json(coro, *, label: str):
    """Pad a slow call's body; early failures keep their status; a disconnect does not cancel the work."""
    from hub.utils.host_paths import restore_inventory_handles

    task = asyncio.ensure_future(coro)
    # Retrieve the exception to avoid 'never retrieved' logs; result() below still raises.
    task.add_done_callback(lambda t: t.cancelled() or t.exception())
    done, _ = await asyncio.wait({task}, timeout = _TUNNEL_KEEPALIVE_AFTER_S)
    if done:
        # Here rather than at each `return LoadResponse`: the one funnel every answer passes.
        try:
            return restore_inventory_handles(task.result())
        except HTTPException as exc:
            raise _handle_restored_http_exception(exc) from None

    logger.info(
        f"{label} exceeded {_TUNNEL_KEEPALIVE_AFTER_S:.0f}s; "
        "padding the response so a proxy cannot time it out"
    )

    async def _body():
        while True:
            finished, _ = await asyncio.wait({task}, timeout = _TUNNEL_KEEPALIVE_EVERY_S)
            if not finished:
                yield b" "
                continue
            try:
                payload = task.result()
            except HTTPException as exc:
                logger.info(f"{label} failed with {exc.status_code} after the response committed")
                yield _deferred_error_body(
                    exc.status_code, restore_inventory_handles(exc.detail), exc.headers
                )
            except Exception as exc:
                logger.exception(f"{label} failed after the response was committed")
                # Exception text may quote a host path; map it back to inventory handles.
                yield _deferred_error_body(
                    500, restore_inventory_handles(f"{type(exc).__name__}: {exc}")
                )
            else:
                yield json.dumps(jsonable_encoder(restore_inventory_handles(payload))).encode()
            return

    return _SameTaskStreamingResponse(
        _body(),
        media_type = "application/json",
        headers = {"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )


async def _aclose_stream_resources(
    *,
    watchers = (),
    items = None,
    iterator = None,
    resp = None,
    client = None,
) -> None:
    """Cancel watchers, then aclose pump, iterator, response, client; CancelledError re-raises last."""
    live = [w for w in watchers if w is not None]
    if live:
        # Cancel before the first await, else a cancel here leaves watchers never cancelled.
        for watcher in live:
            watcher.cancel()
        try:
            await asyncio.gather(
                *(_stop_local_disconnect_cancel_watcher(w) for w in live),
                return_exceptions = True,
            )
        except (asyncio.CancelledError, Exception):
            pass
    close_cancelled = False
    # Await the pump first: the iterator stays ag_running until the pump's finally returns.
    if items is not None:
        try:
            await items.aclose()
        except asyncio.CancelledError:
            close_cancelled = True
        except Exception:
            pass
    if iterator is not None:
        try:
            await iterator.aclose()
        except asyncio.CancelledError:
            close_cancelled = True
        except Exception:
            pass
    if resp is not None:
        try:
            await resp.aclose()
        except asyncio.CancelledError:
            close_cancelled = True
        except Exception:
            pass
    if client is not None:
        try:
            await client.aclose()
        except asyncio.CancelledError:
            close_cancelled = True
        except Exception:
            pass
    if close_cancelled:
        raise asyncio.CancelledError()


# The loop holds only weak refs to tasks; keep a strong ref until done.
_LATE_CLOSE_TASKS: set = set()


async def _aclose_quietly(obj) -> None:
    try:
        await obj.aclose()
    except Exception:
        pass


def _discard_task_outcome(task: asyncio.Task) -> None:
    """Done callback; never raises, and closes a late response the send opens after client close."""
    try:
        if task.cancelled():
            return
        if task.exception() is not None:
            return
        result = task.result()
    except Exception:
        return
    if result is not None and hasattr(result, "aclose") and not getattr(result, "is_closed", False):
        try:
            closing = asyncio.ensure_future(_aclose_quietly(result))
        except RuntimeError:
            return
        _LATE_CLOSE_TASKS.add(closing)
        closing.add_done_callback(_LATE_CLOSE_TASKS.discard)


async def _aclose_send_task(task: Optional[asyncio.Task[Optional[httpx.Response]]]) -> None:
    if task is None:
        return
    if not task.done():
        task.cancel()
    # Bound cancellation swallowed by Request.is_disconnected(); close late responses too. #7617
    done, _pending = await asyncio.wait({task}, timeout = _TEARDOWN_TASK_STOP_TIMEOUT_S)
    if not done:
        task.add_done_callback(_discard_task_outcome)
        return
    try:
        task_resp = task.result()
        if task_resp is not None:
            await task_resp.aclose()
    except (asyncio.CancelledError, Exception):
        pass


def _release_admission(admission_lease = None, tracker = None) -> None:
    """Release only after the upstream response closes, or llama-server admits a request past --parallel."""
    try:
        if admission_lease is not None:
            admission_lease.release()
    finally:
        if tracker is not None:
            tracker.__exit__(None, None, None)


async def _preheader_cancelled(cancel_event = None, request: Optional[Request] = None) -> bool:
    if cancel_event is not None and cancel_event.is_set():
        return True
    if request is not None and await request.is_disconnected():
        if cancel_event is not None:
            cancel_event.set()
        return True
    return False


def _mark_cancelled_json_response_failed(request: Request, cancel_event: threading.Event) -> None:
    """Keep a partial JSON response from claiming a preview-owned resident model."""
    if cancel_event.is_set():
        from core.inference.llama_keepwarm import mark_response_failed
        mark_response_failed(getattr(request, "scope", None))


async def _wait_preheader_cancel(cancel_event = None, request: Optional[Request] = None) -> None:
    while not await _preheader_cancelled(cancel_event, request):
        await asyncio.sleep(0.05)


async def _send_stream_with_preheader_cancel(
    client: httpx.AsyncClient,
    req: httpx.Request,
    cancel_event = None,
    request: Optional[Request] = None,
    mark_cancel_on_cancel: bool = True,
) -> Optional[httpx.Response]:
    if cancel_event is None and request is None:
        return await client.send(req, stream = True)
    from core.inference.llama_keepwarm import mark_response_failed

    def _mark_preheader_cancel() -> None:
        # Cancelled before the upstream response started: the caller ends its 200
        # stream without serving tokens, so flag it failed or the middleware claims
        # a preview-owned slot for a request that never used the model.
        mark_response_failed(getattr(request, "scope", None))

    if await _preheader_cancelled(cancel_event, request):
        _mark_preheader_cancel()
        return None

    send_task = asyncio.create_task(client.send(req, stream = True))
    cancel_task = asyncio.create_task(_wait_preheader_cancel(cancel_event, request))

    async def _stop_send_task() -> None:
        try:
            await client.aclose()
        except Exception:
            pass
        # Bounded: the client is already closed, so an abandoned send owns nothing.
        send_task.cancel()
        done, _pending = await asyncio.wait({send_task}, timeout = _TEARDOWN_TASK_STOP_TIMEOUT_S)
        if not done:
            send_task.add_done_callback(_discard_task_outcome)
            return
        try:
            # The aclose() above does not close a response the send produced during it.
            sent = send_task.result()
            if sent is not None:
                await _aclose_quietly(sent)
        except (asyncio.CancelledError, Exception):
            pass

    try:
        done, _pending = await asyncio.wait(
            {send_task, cancel_task},
            return_when = asyncio.FIRST_COMPLETED,
        )
        if send_task in done:
            return await send_task

        await _stop_send_task()
        _mark_preheader_cancel()
        return None
    except asyncio.CancelledError:
        if mark_cancel_on_cancel and cancel_event is not None:
            cancel_event.set()
        await _stop_send_task()
        raise
    finally:
        # Bounded: is_disconnected() can swallow cancel(), and this also runs on the success path.
        try:
            await _stop_local_disconnect_cancel_watcher(cancel_task)
        except (asyncio.CancelledError, Exception):
            pass


def _ceiling_for_first_read(
    first_token_deadline: float, post_first_item_read_timeout_s: Optional[float]
) -> Optional[float]:
    """None when the operator disabled the stall guard, so nothing bounds the socket read."""
    if post_first_item_read_timeout_s is None:
        return None
    return socket_timeout(
        max(first_token_deadline - time.monotonic(), post_first_item_read_timeout_s)
    )


async def _aiter_llama_stream_items(
    async_iter,
    *,
    cancel_event = None,
    request: Optional[Request] = None,
    first_token_deadline: Optional[float] = None,
    response: Optional[httpx.Response] = None,
    track_prefill_progress: bool = False,
    post_first_item_read_timeout_s: Optional[
        Union[float, Callable[[], Optional[float]]]
    ] = _DEFAULT_STREAM_STALL_TIMEOUT_S,
    keepalive_interval_s: Optional[float] = None,
):
    """Keepalives use asyncio.wait, never cancel the read: httpcore closes the body on any stream error."""
    if first_token_deadline is None:
        first_token_deadline = start_first_token_wait(_first_token_timeout_s())
    last_item_at: Optional[float] = None
    last_prefill_progress: Optional[float] = None
    prefill_buffer = b""
    item_task: Optional[asyncio.Future] = None
    if track_prefill_progress:
        from core.inference.llama_cpp import LlamaCppBackend

    def _post_first_timeout_s() -> Optional[float]:
        if callable(post_first_item_read_timeout_s):
            return post_first_item_read_timeout_s()
        return post_first_item_read_timeout_s

    try:
        while True:
            if cancel_event is not None and cancel_event.is_set():
                return
            if request is not None and await request.is_disconnected():
                if cancel_event is not None:
                    cancel_event.set()
                return
            waiting_first_item = last_item_at is None
            if item_task is None:
                if response is not None:
                    # httpcore latches the first read timeout as the ceiling for later reads; a callable bound does not.
                    if waiting_first_item:
                        # progress renews the prefill deadline beyond the initially latched socket ceiling.
                        ceiling = (
                            None
                            if track_prefill_progress or callable(post_first_item_read_timeout_s)
                            else _ceiling_for_first_read(
                                first_token_deadline, post_first_item_read_timeout_s
                            )
                        )
                    else:
                        ceiling = _post_first_timeout_s()
                    _set_stream_response_read_timeout(response, ceiling)
                item_task = asyncio.ensure_future(async_iter.__anext__())

            if waiting_first_item:
                hard_deadline = first_token_deadline
            else:
                stall_timeout_s = _post_first_timeout_s()
                hard_deadline = None if stall_timeout_s is None else last_item_at + stall_timeout_s
            timed_out_message = (
                "The model did not produce a first token in time."
                if waiting_first_item
                else "The model stopped producing tokens mid-response."
            )

            remaining_s = (
                None
                if hard_deadline is None
                else socket_timeout(max(hard_deadline - time.monotonic(), 0.0))
            )
            if keepalive_interval_s:
                wait_s = (
                    keepalive_interval_s
                    if remaining_s is None
                    else min(keepalive_interval_s, remaining_s)
                )
            else:
                wait_s = remaining_s

            if not item_task.done():
                # Yield once before waiting: buffered reads finish here without timer overhead.
                await asyncio.sleep(0)
            if not item_task.done():
                done, _pending = await asyncio.wait({item_task}, timeout = wait_s)
                if not done:
                    # Only on an EMPTY `done`: a read that landed while suspended outranks an expired clock.
                    if hard_deadline is not None and time.monotonic() >= hard_deadline:
                        raise httpx.ReadTimeout(timed_out_message)
                    # Must not advance last_item_at, or the stall guard never fires.
                    if keepalive_interval_s:
                        yield _LLAMA_STREAM_KEEPALIVE
                    continue
            try:
                item = item_task.result()
            except StopAsyncIteration:
                return
            except (httpx.ReadTimeout, asyncio.TimeoutError) as exc:
                raise httpx.ReadTimeout(timed_out_message) from exc
            finally:
                item_task = None
            if track_prefill_progress and last_item_at is None:
                if isinstance(item, bytes):
                    prefill_buffer += item
                    events = re.split(rb"\r\n\r\n|\n\n|\r\r", prefill_buffer)
                    prefill_buffer = events.pop()
                    events = [event.decode("utf-8", "replace") for event in events]
                else:
                    events = [item]
                starts_output = False
                for event in events:
                    data = LlamaCppBackend._sse_event_payload(event)
                    if data is None:
                        continue
                    if _llama_chunk_has_generated_output(data) or any(
                        choice.get("finish_reason")
                        for choice in data.get("choices", [])
                        if isinstance(choice, dict)
                    ):
                        starts_output = True
                        break
                    processed = LlamaCppBackend._sse_event_prefill_progress(event)
                    if processed is not None and (
                        last_prefill_progress is None or processed > last_prefill_progress
                    ):
                        last_prefill_progress = processed
                        first_token_deadline = start_first_token_wait(_first_token_timeout_s())
                if not starts_output:
                    if time.monotonic() >= first_token_deadline:
                        raise httpx.ReadTimeout("The model did not produce a first token in time.")
                    yield item
                    continue
                prefill_buffer = b""
            if last_item_at is None and response is not None:
                # Before yielding: the consumer may sit on this item while the first-token deadline is armed.
                _set_stream_response_read_timeout(response, _post_first_timeout_s())
            finish_first_token_wait()
            last_item_at = time.monotonic()
            yield item
    finally:
        if item_task is not None:
            # Bounded, then abandoned; the callback drains it. Cf _aclose_send_task. #7617
            if not item_task.done():
                item_task.cancel()
            item_task.add_done_callback(_discard_task_outcome)
            stop_cancelled = False
            try:
                await asyncio.wait({item_task}, timeout = _TEARDOWN_TASK_STOP_TIMEOUT_S)
            except asyncio.CancelledError:
                # Recorded, not swallowed: _aclose_stream_resources re-raises it after shutdown.
                stop_cancelled = True
            if stop_cancelled:
                raise asyncio.CancelledError()


