def _active_gguf_intent(
    request: LoadRequest,
    llama_backend: LlamaCppBackend,
    *,
    model_identifier: str,
    chat_template_override: Optional[str],
    n_parallel: int,
    native_grant_backed: bool,
) -> GgufLoadIntent:
    backend_extra = list(llama_backend.extra_args or ())
    request_fields_set = getattr(request, "model_fields_set", set())
    inherits_extras = request.llama_extra_args is None
    if inherits_extras:
        effective_extra = strip_shadowing_flags(
            backend_extra,
            strip_split_mode = _should_strip_split_mode(request, backend_extra),
            strip_tensor_split = _should_strip_tensor_split(request),
            strip_offload = request.gpu_memory_mode == "manual",
        )
        # mirror _resolve_inherited_extra_args, or a stale inherited -b / -ub reads as equal
        batch_stripped_extra = strip_shadowing_flags(
            effective_extra,
            strip_context = False,
            strip_cache = False,
            strip_spec = False,
            strip_template = False,
            strip_split_mode = False,
            strip_reasoning_budget = "reasoning_budget" in request_fields_set,
            strip_reasoning_budget_message = "reasoning_budget_message" in request_fields_set,
            strip_batch = "n_batch" in request_fields_set,
            strip_ubatch = "n_ubatch" in request_fields_set,
            strip_ctx_checkpoints = "ctx_checkpoints" in request_fields_set,
            strip_cache_ram = "cache_ram" in request_fields_set,
            strip_spec_draft_cache = "spec_draft_cache_type" in request_fields_set,
            strip_load_mode = "load_mode" in request_fields_set,
            strip_load_mode_aliases = "load_mode" in request_fields_set,
        )
        # a strip that changed the list is an override, so the dedupe compares the stripped one
        batch_overrides_inherit = batch_stripped_extra != effective_extra
        effective_extra = batch_stripped_extra
    else:
        effective_extra = request.llama_extra_args
        batch_overrides_inherit = False
    source = llama_backend.last_load_intent or GgufLoadIntent(
        model_identifier = model_identifier,
        gguf_path = None if llama_backend.hf_repo else llama_backend.gguf_path,
        hf_repo = llama_backend.hf_repo,
        hf_variant = llama_backend.hf_variant,
    )
    # What the launch searched, recorded at load, not what one snapshot holds.
    _loaded_roots = tuple(getattr(llama_backend, "_openai_gguf_companion_roots", ()) or ())
    return _gguf_request_intent(
        source,
        request,
        model_identifier = model_identifier,
        # Unresolved variant: do not inherit the resident file or a quant switch is ignored.
        gguf_path = (
            source.gguf_path
            if is_ollama_manifest_ref(model_identifier)
            or model_identifier.lower().endswith(".gguf")
            else None
        ),
        hf_variant = request.gguf_variant or source.hf_variant,
        chat_template_override = chat_template_override,
        extra_args = effective_extra,
        gpu_ids = request.gpu_ids,
        n_parallel = n_parallel,
        preserve_multi_gpu_on_layer = (
            llama_backend.layer_preserves_tensor_intent and not _is_explicit_tensor_drop(request)
        ),
        mtp_draft_path = _mtp_draft_for_path(
            llama_backend.gguf_path, native_grant_backed, companion_roots = _loaded_roots
        ),
        dspark_draft_path = _dspark_draft_for_path(
            llama_backend.gguf_path, native_grant_backed, companion_roots = _loaded_roots
        ),
        dflash_draft_path = _dflash_draft_for_path(
            llama_backend.gguf_path, native_grant_backed, companion_roots = _loaded_roots
        ),
        compare_mtp_draft = True,
        extra_args_inherited = inherits_extras and not batch_overrides_inherit,
    )


def _public_model_identifier(requested: str, resolved: str) -> str:
    return requested if is_ollama_manifest_ref(requested) else resolved


def _canonical_model_identity(model_id: Optional[str]) -> str:
    """Case-folded *model_id*, reading an HF cache snapshot path as its ``org/name`` repo id.
    Other local paths stay distinct: two files sharing a stem are two models."""
    from core.inference.model_ids import hf_cache_repo_id

    if not model_id:
        return ""
    return (hf_cache_repo_id(model_id) or str(model_id)).lower()


def _as_ollama_manifest_request(request):
    """*request* with a materialized Ollama ``.gguf`` link rewritten to the tag that produced it."""
    from hub.services.models.ollama import ollama_manifest_ref_for_path, ollama_model_ref_files

    # Authorized requests keep their path: a tag may now name weights the check never saw.
    if account_access.managed_account() or getattr(request, "native_path_lease", None):
        return request
    ref = ollama_manifest_ref_for_path(request.model_path)
    if not ref or ref == request.model_path:
        return request
    try:
        ollama_model_ref_files(ref)
    except Exception:
        # A tag whose manifest no longer reads is no improvement on a link that still resolves.
        return request
    return request.model_copy(update = {"model_path": ref})


def _as_local_scan_folder_request(request, owner_session: bool):
    """*request* with a repo id whose GGUF copy sits outside the active hub cache (e.g. a scan folder) rewritten to it."""
    from core.inference.local_model_resolver import _is_abs_path_id, resolve_local_gguf
    from core.inference.model_ids import hf_cache_repo_id

    identifier = (request.model_path or "").strip()
    # Bare names mean unsloth/<name> remotely; a same-stemmed local file must not win them.
    if (
        not identifier
        or "/" not in identifier
        or is_ollama_manifest_ref(identifier)
        or _is_abs_path_id(identifier)
    ):
        return request
    # Owner session only (as _refused_repo_cached_gguf); a native lease names one exact artifact.
    if not owner_session or getattr(request, "native_path_lease", None):
        return request
    wanted = f"{identifier}:{request.gguf_variant}" if request.gguf_variant else identifier
    try:
        resolved = resolve_local_gguf(wanted)
    except Exception:
        return request
    if resolved is None:
        return request
    load_path, variant = str(resolved[0]), resolved[1]
    # Only a GGUF snapshot of this repo: its path maps back to the repo id (status, unload, consent).
    if not variant or (hf_cache_repo_id(load_path) or "").lower() != identifier.lower():
        return request
    # A repo directly in the active hub cache already loads by repo id without downloading.
    try:
        from hub.utils.hf_cache_state import same_existing_path
        from routes.models import _resolve_hf_cache_dir

        repo_dir = next(p for p in Path(load_path).parents if p.name.startswith("models--"))
        if same_existing_path(repo_dir.parent, Path(_resolve_hf_cache_dir())):
            return request
    except Exception:
        return request
    logger.info(
        "Resolved repo id '%s' to local path %s instead of downloading",
        identifier,
        load_path,
    )
    return request.model_copy(update = {"model_path": load_path, "gguf_variant": variant})


async def _lease_ollama_model_ref(
    request: LoadRequest | ValidateModelRequest, *, operation: str, stack: ExitStack
) -> Optional[str]:
    if not is_ollama_manifest_ref(request.model_path):
        return None
    loop = asyncio.get_running_loop()
    lease_future = loop.run_in_executor(
        _OLLAMA_LEASE_EXECUTOR,
        run_as,
        current_account(),
        acquire_ollama_model_ref,
        request.model_path,
    )
    try:
        lease = await asyncio.shield(lease_future)
    except asyncio.CancelledError:

        def _release_cancelled_lease(done):
            try:
                done.result().release()
            except BaseException:
                pass

        lease_future.add_done_callback(_release_cancelled_lease)
        raise
    except ValueError as exc:
        logger.warning("inference.ollama_materialize_failed: %s", exc)
        raise HTTPException(
            status_code = 400,
            detail = redact_native_paths(str(exc)),
        ) from exc
    stack.callback(lease.release)
    return lease.path


def _defers_access_to_native_grant(request) -> bool:
    """A native selection sends a label, so the check waits for the lease's canonical path."""
    return bool(
        account_access.managed_account()
        and getattr(request, "native_path_lease", None)
        and not is_ollama_manifest_ref(request.model_path)
    )


def _resolve_model_identifier_for_request(
    request: LoadRequest | ValidateModelRequest,
    *,
    operation: str,
    resolved_ollama_path: Optional[str] = None,
) -> tuple[str, str, bool]:
    if is_ollama_manifest_ref(request.model_path):
        # The read-only scan returns an opaque manifest ref; the load path does the .gguf link write.
        if resolved_ollama_path is None:
            try:
                resolved_ollama_path = materialize_ollama_model_ref(request.model_path)
            except ValueError as exc:
                logger.warning("inference.ollama_materialize_failed: %s", exc)
                raise HTTPException(
                    status_code = 400,
                    detail = redact_native_paths(str(exc)),
                ) from exc
        return resolved_ollama_path, Path(resolved_ollama_path).name, False
    if not request.native_path_lease:
        return request.model_path, request.model_path, False
    try:
        grant = verify_native_path_lease(
            request.native_path_lease,
            operation = operation,
            expected_kind = "model",
            expected_path_type = "file",
            allowed_suffixes = (".gguf",),
        )
    except NativePathLeaseError as exc:
        # Client-fixable lease error: keep the actionable message but redact paths.
        logger.warning("inference.native_path_lease_failed: %s", exc)
        raise HTTPException(
            status_code = 400,
            detail = redact_native_paths(str(exc)),
        ) from exc
    display_label = grant.display_label or Path(request.model_path).name or "Native model"
    return str(grant.canonical_path), display_label, True


# GGUF inference backend (llama-server)
_llama_cpp_backend = LlamaCppBackend()
register_serving_backend(_llama_cpp_backend)


def get_llama_cpp_backend() -> LlamaCppBackend:
    slot = routed_slot.get()
    return slot.llama if slot is not None else _llama_cpp_backend


def _worker_exited(slot: Optional[_ExtraSlot]) -> bool:
    proc = getattr(model_slots.in_slot(slot, _peek_inference_backend), "_proc", None)
    return proc is not None and not proc.is_alive()


def _reap_dead_workers(slots: list) -> None:
    for slot in slots:
        model_slots.in_slot(slot, lambda: reap_dead_worker(_peek_inference_backend()))


async def _reap_exited_workers() -> None:
    # A killed worker stays named until reaped; is_alive() is a non-blocking waitpid.
    exited = [slot for slot in (None, *model_slots.slots) if _worker_exited(slot)]
    if exited:
        await asyncio.to_thread(_reap_dead_workers, exited)


async def _route_to_extra_slot(requested: Optional[str]) -> Optional[_ExtraSlot]:
    """Route this request to the kept model serving *requested*, if any. The primary wins a tie."""
    await _reap_exited_workers()
    return await model_slots.route(requested, _loaded_satisfies)


def _model_key(request: LoadRequest) -> str:
    return (
        f"{request.model_path}:{request.gguf_variant}"
        if request.gguf_variant
        else request.model_path
    )


def _raise_or_cancel_slot_generations(
    slot: _ExtraSlot,
    *,
    force: bool,
    cancel: bool = True,
    action: str = "Unloading this model",
) -> int:
    """The primary's 409 for a slot: only the generations this slot serves are in the way."""
    events = list(slot.generations)
    if not events:
        return 0
    if not force:
        raise _active_generations_conflict(
            action, len(events), active_generations.active_thread_ids(None, (), events)
        )
    if not cancel:
        return 0
    for event in events:
        event.set()
    return len(events)


# Serializes opt-in auto-switch loads per running loop: a module-level asyncio.Lock binds to one loop and breaks multi-loop runners.
_auto_switch_locks: "weakref.WeakKeyDictionary" = weakref.WeakKeyDictionary()
_auto_switch_locks_guard = threading.Lock()


def _auto_switch_lock() -> asyncio.Lock:
    loop = asyncio.get_running_loop()
    # WeakKeyDictionary mutation is not thread-safe.
    with _auto_switch_locks_guard:
        lock = _auto_switch_locks.get(loop)
        if lock is None:
            lock = _auto_switch_locks[loop] = asyncio.Lock()
        return lock


# Process-wide gate: the asyncio lock is per loop but the model slot is process-wide.
# threading.Lock, not RLock: it may be released from a different thread.
_auto_switch_process_lock = threading.Lock()


async def _acquire_swap_gate() -> None:
    # Poll, not to_thread(acquire): a cancelled to_thread still acquires and deadlocks later swaps.
    while not _auto_switch_process_lock.acquire(blocking = False):
        await asyncio.sleep(0.02)


# Queued auto-switch requests are not generating; the drain wait excludes them.
_auto_switch_waiters: dict[tuple[str, str], int] = {}
_auto_switch_waiters_guard = threading.Lock()


def _switch_key(override_id: str, variant: Optional[str]) -> tuple[str, str]:
    return (override_id.lower(), (variant or "").lower())


def _note_switch_waiter(key: tuple[str, str], delta: int) -> None:
    with _auto_switch_waiters_guard:
        n = _auto_switch_waiters.get(key, 0) + delta
        if n > 0:
            _auto_switch_waiters[key] = n
        else:
            _auto_switch_waiters.pop(key, None)


def _switch_waiter_count() -> int:
    with _auto_switch_waiters_guard:
        return sum(max(0, count) for count in _auto_switch_waiters.values())


async def _wait_for_model_switch_idle(
    *,
    current_request_counted: bool,
    cancel_pending: bool = False,
    timeout_s: Optional[float] = None,
) -> None:
    """Excludes queued waiters and to-be-cancelled generations; only post-cancel drains set timeout_s (pre-cancel waits stay unbounded)."""
    from core.inference.llama_keepwarm import other_inference_request_count
    from core.inference.gpu_arbiter import require_no_foreign_generations

    # account_scope(), not login mode: deactivation only signals its generation, not the decode.
    account_id = account_access.account_scope()
    deadline = None if timeout_s is None else time.monotonic() + timeout_s
    while True:
        if account_id is not None:
            require_no_foreign_generations(account_id)
        queued_switches = _switch_waiter_count()
        if current_request_counted and queued_switches > 0:
            queued_switches -= 1
        active_others = other_inference_request_count(
            current_request_counted = current_request_counted,
            include_pending = False,
        )
        elsewhere = model_slots.all_generations()
        active_others -= min(active_others, len(elsewhere))
        if cancel_pending:
            cancellable = active_generations.count(account_id, elsewhere, include_external = False)
            active_others -= min(active_others, cancellable)
        if active_others <= queued_switches:
            return
        if deadline is not None and time.monotonic() >= deadline:
            logger.warning(
                "model_switch_drain_timed_out",
                extra = {
                    "event": "inference.switch_drain_timeout",
                    "remaining": active_others - queued_switches,
                },
            )
            return
        await asyncio.sleep(0.02)


def _llama_public_model_id(llama_backend, fallback: Optional[str] = None) -> Optional[str]:
    """API-facing id for the loaded GGUF: a recorded advertised id, else the public id, never a path."""
    return (
        getattr(llama_backend, "_openai_advertised_id", None)
        or public_model_id(getattr(llama_backend, "model_identifier", None))
        or public_model_id(fallback)
        or fallback
    )


def _loading_public_id(model_path: Optional[str]) -> Optional[str]:
    """Mid-load status is path-free like a finished load: native label if redeemed, else public id."""
    if not model_path:
        return model_path
    label = display_label_for_native_path(model_path)
    if label != model_path:
        return label
    return public_model_id(model_path) or model_path


def _orchestrator_public_model_id(backend) -> Optional[str]:
    """Advertised repo id from an auto-switch load, else the public id; read only while a model is
    active."""
    return getattr(backend, "_openai_advertised_id", None) or public_model_id(
        getattr(backend, "active_model_name", None)
    )


def _llama_status_model_ids(llama_backend) -> "tuple[Optional[str], Optional[str]]":
    """The ``(active_model, model_identifier)`` pair ``/api/inference/status`` publishes
    for a loaded GGUF. A native-lease load reports only the display label, never the
    leased on-disk path."""
    model_id = getattr(llama_backend, "model_identifier", None)
    native_grant_backed = getattr(llama_backend, "_native_grant_backed", False)
    display_model_id = getattr(
        llama_backend, "_native_display_label", None
    ) or display_label_for_native_path(model_id)
    if (
        native_grant_backed
        and model_id
        and display_model_id == model_id
        and os.path.isabs(model_id)
    ):
        display_model_id = os.path.basename(model_id)
    elif not native_grant_backed and display_model_id == model_id:
        # No label registered, so report the clean public id, not the snapshot's sha.
        display_model_id = _llama_public_model_id(llama_backend) or display_model_id
    return display_model_id, (None if native_grant_backed else model_id)


def _llama_status_checkpoint_id(llama_backend) -> Optional[str]:
    """The exact string an Unsloth client holds as ``params.checkpoint`` for the loaded
    GGUF: ``status.model_identifier ?? status.active_model``. Built from the same pair the
    status handler returns so the two cannot drift."""
    display_model_id, model_identifier = _llama_status_model_ids(llama_backend)
    return display_model_id if model_identifier is None else model_identifier


_DISABLE_OPENAI_AUTO_SWITCH_SCOPE_KEY = "_unsloth_disable_openai_auto_switch"
# Routes a named model to the slot already serving it but never loads one (scheduled runs).
LOADED_MODELS_ONLY_SCOPE_KEY = "_unsloth_loaded_models_only"
# Sentinel a raw-body endpoint passes when the request omits ``model``: it must
# only restore an idle-freed model, never run the resolver (so a downloaded GGUF
# literally named "default" can't be swapped to). The NUL keeps it off any index.
_RELOAD_ONLY_MODEL = "\x00reload-only"
# One cold scan is worth paying to avoid answering a named model with another,
# bounded so a pathological install cannot hang the request behind it.
_COLD_INDEX_WAIT_S = 10.0


def _switch_model_for_payload(payload) -> str:
    # Pydantic fills omitted model with 'default'; only an explicitly set model may switch.
    return payload.model if "model" in payload.model_fields_set else _RELOAD_ONLY_MODEL


def _target_is_vision(
    load_path: str,
    gguf_variant: Optional[str] = None,
    need_image: bool = True,
    gguf_companion_roots: tuple[str, ...] = (),
) -> bool:
    # GGUF vision = companion mmproj (filesystem check); audio asks with need_image False.
    # hf_token is passed even though unused here: capability probes must always thread it.
    from utils.models.model_config import is_vision_model
    try:
        if is_ollama_manifest_ref(load_path):
            from hub.services.models.ollama import ollama_model_ref_files
            from utils.models.gguf_metadata import mmproj_accepts_image

            _, projector = ollama_model_ref_files(load_path)
            return projector is not None and (not need_image or mmproj_accepts_image(projector))
        # Deliberately unguarded: resolver yields local paths, so no hub call happens.
        return bool(
            is_vision_model(
                load_path,
                hf_token = account_access.ambient_hf_token(),
                gguf_variant = gguf_variant,
                require_image = need_image,
                gguf_companion_roots = gguf_companion_roots or None,
            )
        )
    except Exception as exc:
        # Detection failure: don't block the swap, let the load decide.
        logger.debug("auto-switch: vision probe failed for %s: %s", load_path, exc)
        return True


def _target_accepts_audio_input(load_path: str) -> bool:
    """Read offline from tokenizer special tokens; a detection failure must not block the swap."""
    from utils.models.model_config import detect_audio_type, is_audio_input_type
    try:
        return is_audio_input_type(
            detect_audio_type(
                load_path,
                hf_token = account_access.ambient_hf_token(),
                local_files_only = True,
            )
        )
    except Exception as exc:
        logger.debug("auto-switch: audio probe failed for %s: %s", load_path, exc)
        return True


def _names_video_token(config) -> bool:
    if not isinstance(config, dict):
        return False
    return any(
        (key in ("video_token_id", "video_token_index") and value is not None)
        or _names_video_token(value)
        for key, value in config.items()
    )


def _target_accepts_video_input(load_path: str) -> bool:
    """Whether an MLX target's config names a video placeholder token; a config that cannot
    be read is left to the load."""
    from utils.hardware import DeviceType, get_device

    if get_device() != DeviceType.MLX:
        return False
    from core.inference.mlx_inference import _mlx_vlm_decodes_video

    if not _mlx_vlm_decodes_video():
        return False
    try:
        config = json.loads(
            (Path(load_path).expanduser() / "config.json").read_text(encoding = "utf-8")
        )
    except Exception as exc:
        logger.debug("auto-switch: video probe failed for %s: %s", load_path, exc)
        return True
    return _names_video_token(config)


def _target_accepts_request_input(
    load_path: str,
    is_gguf: bool,
    needs_vision: bool,
    needs_audio: bool,
    gguf_variant: Optional[str] = None,
    need_image: bool = True,
    needs_video: bool = False,
    gguf_companion_roots: tuple[str, ...] = (),
) -> bool:
    """A GGUF's mmproj covers image and audio alike; other checkpoints declare each modality apart."""
    if is_gguf:
        if not gguf_companion_roots:
            return _target_is_vision(load_path, gguf_variant, need_image)
        return _target_is_vision(
            load_path,
            gguf_variant,
            need_image,
            gguf_companion_roots,
        )
    if needs_video and not _target_accepts_video_input(load_path):
        return False
    if needs_audio and not _target_accepts_audio_input(load_path):
        return False
    # need_image, not needs_vision: audio sets needs_vision but needs no vision tower.
    return _target_is_vision(load_path) if (needs_vision and need_image) else True


def _resolve_target_gguf_file(load_path: str, gguf_variant: Optional[str]) -> Optional[str]:
    from utils.models.model_config import _find_local_gguf_by_variant, detect_gguf_model

    if is_ollama_manifest_ref(load_path):
        from hub.services.models.ollama import ollama_model_ref_files
        return ollama_model_ref_files(load_path)[0]
    local_path = os.path.expanduser(load_path)
    if gguf_variant and Path(local_path).is_dir():
        return _find_local_gguf_by_variant(local_path, gguf_variant)
    return detect_gguf_model(local_path)


# Keep this order aligned with NativeAudioBackend._context_length.
_NATIVE_CONTEXT_SUBCONFIGS = ("language_config", "qwen3_config", "text_config")
_NATIVE_CONTEXT_FIELDS = (
    "max_position_embeddings",
    "max_sequence_length",
    "max_seq_length",
    "n_positions",
    "seq_length",
)


def _local_config_context_length(load_path: str) -> Optional[int]:
    import json

    config_path = Path(os.path.expanduser(load_path))
    if config_path.is_dir():
        config_path = config_path / "config.json"
    if not config_path.is_file():
        return None
    with open(config_path, encoding = "utf-8") as f:
        config = json.load(f)
    if not isinstance(config, dict):
        return None
    for candidate in (*(config.get(name) for name in _NATIVE_CONTEXT_SUBCONFIGS), config):
        if not isinstance(candidate, dict):
            continue
        for field in _NATIVE_CONTEXT_FIELDS:
            value = _positive_int_or_none(candidate.get(field))
            if value is not None:
                return value
    return None


def _target_native_context_length(
    load_path: str,
    is_gguf: bool,
    gguf_variant: Optional[str] = None,
) -> Optional[int]:
    try:
        if not is_gguf:
            return _local_config_context_length(load_path)
        from utils.models.gguf_metadata import read_gguf_context_length

        gguf_file = _resolve_target_gguf_file(load_path, gguf_variant)
        return read_gguf_context_length(gguf_file) if gguf_file else None
    except Exception as exc:
        logger.debug("auto-switch: context probe failed for %s: %s", load_path, exc)
        return None


def _target_effective_context_length(
    load_path: str,
    is_gguf: bool,
    gguf_variant: Optional[str] = None,
    override_id: Optional[str] = None,
    audio_type: Optional[str] = None,
    resolved_override: Optional[dict] = None,
    override_is_resolved: bool = False,
) -> Optional[int]:
    # MiniMax has no measurable window; MOSS ignores saved context overrides.
    if audio_type == "minimax_music3":
        return None
    if audio_type in _CONTEXT_OVERRIDE_IGNORED_AUDIO_TYPES:
        return _target_native_context_length(load_path, is_gguf, gguf_variant)
    try:
        from utils.openai_auto_switch_settings import (
            resolve_fit_max_seq_length,
            resolve_override_for_load,
        )

        if override_is_resolved:
            override = resolved_override
        else:
            _key, override = resolve_override_for_load(load_path, override_id, gguf_variant)
        configured = _positive_int_or_none(
            resolve_fit_max_seq_length(override, is_gguf = is_gguf) if override else None
        )
        if configured is None and override and is_gguf:
            from core.inference.llama_server_args import parse_ctx_override
            configured = _positive_int_or_none(parse_ctx_override(override.get("llama_extra_args")))
        if configured is not None:
            from core.inference.native_audio import NATIVE_AUDIO_TYPES
            if not is_gguf and audio_type in NATIVE_AUDIO_TYPES:
                detected = _target_native_context_length(load_path, is_gguf, gguf_variant)
                return min(configured, detected) if detected else configured
            return configured
    except Exception as exc:
        logger.debug("auto-switch: context override lookup failed for %s: %s", load_path, exc)
    from core.inference.native_audio import NATIVE_AUDIO_TYPES

    if not is_gguf and audio_type not in NATIVE_AUDIO_TYPES:
        # The generic loader converts its zero default to 2048, not the declared window.
        return _STANDARD_LOAD_DEFAULT_CONTEXT
    return _target_native_context_length(load_path, is_gguf, gguf_variant)


def _target_speech_audio_type(
    load_path: str,
    is_gguf: bool,
    gguf_variant: Optional[str] = None,
) -> Optional[str]:
    from core.inference.local_model_resolver import _host_serves_mlx
    from utils.models.model_config import (
        _find_local_gguf_by_variant,
        detect_audio_type,
        detect_gguf_model,
    )
    try:
        if not is_gguf:
            from core.inference.native_audio import (
                REMOTE_CODE_AUDIO_TYPES,
                is_native_audio_model,
            )

            # Native audio precedes MLX and has an MPS path; ordinary codecs cannot serve there.
            if _host_serves_mlx() and not is_native_audio_model(load_path):
                return None
            audio_type = detect_audio_type(
                load_path, hf_token = os.environ.get("HF_TOKEN"), local_files_only = True
            )
            # Auto-switch never grants trust_remote_code; reject before evicting the resident.
            if audio_type in REMOTE_CODE_AUDIO_TYPES:
                return None
            return audio_type if audio_type in _TRANSFORMERS_TTS_AUDIO_TYPES else None
        from utils.models.gguf_metadata import read_gguf_tts_audio_type

        gguf_file = _resolve_target_gguf_file(load_path, gguf_variant)
        audio_type = read_gguf_tts_audio_type(gguf_file) if gguf_file else None
        return audio_type if audio_type in _GGUF_TTS_AUDIO_TYPES else None
    except Exception as exc:
        logger.debug("auto-switch: speech probe failed for %s: %s", load_path, exc)
        return None


def _target_audio_workflows(target_id: str, speech_type: Optional[str]) -> list[str]:
    """The Audio page workflows a switch target runs, answered from the HF cache alone."""
    from core.inference.audio_cpp_models import looks_like_audio_cpp, resolve
    from core.inference.audio_workflows import status_audio_workflows

    if not looks_like_audio_cpp(target_id):
        return status_audio_workflows(speech_type is not None, speech_type)
    try:
        model = resolve(target_id, network = False)
    except Exception:  # noqa: BLE001 - unreadable from the cache: it runs nothing
        return []
    return list(model.workflows) if model is not None else []


@dataclass(frozen = True)
class _SpeechCodecPreflightResult:
    cache_environment: Optional[dict[str, str]] = None
    codec_path: Optional[str] = None


def _preflight_speech_codec_for_switch(
    audio_type: str,
    load_path: str,
    is_gguf: bool,
    hf_token: Optional[str] = None,
) -> _SpeechCodecPreflightResult:
    from utils.utils import hf_env_offline

    offline = hf_env_offline()
    hub_token = hf_token or False
    if audio_type == "snac":
        from huggingface_hub import snapshot_download
        from utils.hf_cache_settings import get_hf_cache_paths

        cache_paths = get_hf_cache_paths()
        staged = snapshot_download(
            "hubertsiuzdak/snac_24khz",
            token = hub_token,
            cache_dir = str(cache_paths.hub_cache),
            local_files_only = offline,
        )
        return _SpeechCodecPreflightResult(cache_paths.child_env({}), str(staged))
    elif audio_type == "bicodec":
        from core.inference.audio_codecs import resolve_bicodec_repo_path
        from utils.hf_cache_settings import get_hf_cache_paths

        cache_paths = get_hf_cache_paths()
        staged = resolve_bicodec_repo_path(
            None if is_gguf else load_path,
            hf_token = hub_token,
            local_files_only = offline,
            cache_dir = str(cache_paths.hub_cache),
        )
        return _SpeechCodecPreflightResult(cache_paths.child_env({}), str(staged))
    elif audio_type == "dac":
        from utils.third_party_source import ensure_dac_speech_weights, ensure_outetts_source
        from utils.hf_cache_settings import get_hf_cache_paths

        cache_paths = get_hf_cache_paths()
        ensure_outetts_source()
        staged = ensure_dac_speech_weights(
            hub_cache = cache_paths.hub_cache,
            hf_token = hub_token,
        )
        return _SpeechCodecPreflightResult(cache_paths.child_env({}), str(staged))
    elif audio_type == "higgs_tts2":
        from core.inference.native_audio import (
            higgs_tts2_codec_local_complete,
            native_audio_security_targets,
        )
        from huggingface_hub import snapshot_download
        from utils.hf_cache_settings import get_hf_cache_paths

        cache_paths = get_hf_cache_paths()
        companions = native_audio_security_targets(load_path, audio_type, hub_token)[1:]
        if not companions:
            raise RuntimeError("Higgs TTS 2 exposes no companion audio tokenizer.")
        for companion in companions:
            local_companion = Path(companion).expanduser()
            staged = (
                str(local_companion)
                if local_companion.exists()
                else snapshot_download(
                    companion,
                    token = hub_token,
                    cache_dir = str(cache_paths.hub_cache),
                    local_files_only = offline,
                )
            )
            from utils.security import evaluate_file_security

            security = evaluate_file_security(
                staged,
                hf_token = hub_token,
                local_only_load = offline,
            )
            if security.blocked:
                raise RuntimeError(security.reason)
            if not higgs_tts2_codec_local_complete(staged):
                raise RuntimeError(f"Higgs TTS 2 companion '{companion}' is incomplete.")
        # Pin the verified cache across the lifecycle wait; settings may change meanwhile.
        return _SpeechCodecPreflightResult(cache_paths.child_env({}))
    return _SpeechCodecPreflightResult()


_AUDIO_IMAGE_INPUT_DETAIL = (
    "This model takes audio or an image in one message, not both. Send the image on its own turn."
)
_AUDIO_VIDEO_INPUT_DETAIL = "This model takes audio or a video in one message, not both."
_MLX_MULTI_AUDIO_DETAIL = (
    "This MLX model takes one audio file per message. Send the recordings on separate turns, "
    "or load the GGUF build of the model to send several at once."
)


async def _preflight_audio_for_switch(audio_preflight: dict, target_is_gguf: bool) -> None:
    """Runs before a swap so unservable audio fails before the load evicts the resident model."""
    clips = audio_preflight["clips"]
    if target_is_gguf:
        try:
            audio_preflight["prepared"] = await asyncio.to_thread(
                _prepare_audio_clips_for_llama, clips
            )
        except _DecodedAudioTooLongError:
            # Too-long audio is a 413 limit, not a decode error; the answer must not depend on a running swap.
            raise HTTPException(
                status_code = 413,
                detail = _audio_too_long_detail(),
            ) from None
        except Exception:
            raise HTTPException(
                status_code = 400,
                detail = openai_error_body(
                    "The 'audio_base64' value could not be decoded as audio.",
                    status = 400,
                    code = "invalid_value",
                    param = "audio_base64",
                ),
            ) from None
        return
    if audio_preflight.get("has_video"):
        raise HTTPException(status_code = 400, detail = _AUDIO_VIDEO_INPUT_DETAIL)
    if audio_preflight.get("continue_final"):
        raise HTTPException(
            status_code = 400,
            detail = "continue_final_message is not supported with audio input.",
        )
    if audio_preflight.get("has_image"):
        raise HTTPException(status_code = 400, detail = _AUDIO_IMAGE_INPUT_DETAIL)
    from core.inference.local_model_resolver import _host_serves_mlx

    # A non-GGUF target on an MLX host loads on MLX, which takes one clip.
    if len(clips) > 1 and _host_serves_mlx():
        raise HTTPException(status_code = 400, detail = _MLX_MULTI_AUDIO_DETAIL)
    if not _audio_decoder_is_available():
        raise HTTPException(
            status_code = 400,
            detail = openai_error_body(
                "This server cannot decode audio input for a non-GGUF model: "
                "torchaudio is not installed.",
                status = 400,
                code = "invalid_value",
                param = "model",
            ),
        )
    try:
        audio_preflight["decoded"] = await asyncio.to_thread(_decode_audio_clips, clips)
    except _DecodedAudioTooLongError:
        raise HTTPException(
            status_code = 413,
            detail = _audio_too_long_detail(),
        ) from None
    except Exception:
        raise HTTPException(
            status_code = 400,
            detail = openai_error_body(
                "The 'audio_base64' value could not be decoded as audio.",
                status = 400,
                code = "invalid_value",
                param = "audio_base64",
            ),
        ) from None


def _validate_image_base64(encoded: str) -> None:
    """Decode one image far enough to reject malformed bytes before a switch."""
    from io import BytesIO
    from PIL import Image

    image_data = base64.b64decode(encoded)
    with Image.open(BytesIO(image_data)) as image:
        image.load()


def _local_target_may_take_several_images(load_path: Optional[str]) -> bool:
    import json

    from utils.hardware import DeviceType, get_device
    try:
        if get_device() != DeviceType.MLX:
            return False
        from mlx_vlm.prompt_utils import SINGLE_IMAGE_ONLY_MODELS

        config_path = Path(os.path.expanduser(load_path or ""))
        if config_path.is_dir():
            config_path = config_path / "config.json"
        if not config_path.is_file():
            return False
        with open(config_path, encoding = "utf-8") as f:
            config = json.load(f)
        model_type = config.get("model_type") if isinstance(config, dict) else None
        return bool(model_type) and model_type not in SINGLE_IMAGE_ONLY_MODELS
    except BaseException:
        return False


def _override_selects_managed_engine(target_id, override_id, variant) -> bool:
    """A saved vLLM/SGLang choice: the managed branch inlines remote URLs and takes several images."""
    from utils.openai_auto_switch_settings import resolve_override_for_load
    return resolve_override_for_load(target_id, override_id, variant)[1].get("engine") in (
        "vllm",
        "sglang",
    )


async def _preflight_image_for_switch(
    image_preflight: dict,
    target_is_gguf: bool,
    target_takes_several: bool = False,
) -> None:
    """Apply target-specific image checks before loading the resolved target."""
    serves_several = (
        target_takes_several
        and len(image_preflight.get("admitted", ())) > 1
        and not image_preflight.get("unservable_alongside")
    )
    # Structural: one real image beside a payloadless URL is still a multi-image request.
    if not target_is_gguf and image_preflight.get("multiple") and not serves_several:
        raise HTTPException(
            status_code = 400,
            detail = (
                "This model takes one image per message. Attach one, or load a"
                " GGUF build of it, which accepts several."
            ),
        )
    # The images the model reads are fetched after the load, so a scheme it refuses is refused now.
    for scheme in image_preflight.get("fetch_schemes", {}).get(target_takes_several, ()):
        rejection = _remote_image_scheme_rejection(scheme) if scheme else None
        if not target_is_gguf and rejection is not None:
            raise HTTPException(status_code = rejection[0], detail = rejection[1])
    # Only what the single-image path selects: an architecture guess must not refuse the rest.
    encoded_images = (
        image_preflight.get("b64s", ()) if target_is_gguf else (image_preflight.get("b64"),)
    )
    for encoded in encoded_images:
        if encoded is None:
            continue
        try:
            await asyncio.to_thread(_validate_image_base64, encoded)
        except Exception:
            detail = "Failed to process image." if target_is_gguf else "Failed to decode image"
            raise HTTPException(status_code = 400, detail = detail) from None


def _messages_have_image(messages) -> bool:
    return any(
        isinstance(m.content, list) and any(isinstance(p, ImageContentPart) for p in m.content)
        for m in messages
    )


def _omit_tool_images(messages) -> None:
    for message in messages:
        if message.role != "tool" or not _messages_have_image((message,)):
            continue
        parts = [
            TextContentPart(type = "text", text = TOOL_RESULT_IMAGE_OMITTED)
            if isinstance(part, ImageContentPart)
            else part
            for part in message.content
        ]
        # Flatten text-only, as _responses_tool_output_content does: some templates render a
        # part list as an empty tool result.
        message.content = (
            "\n".join(part.text for part in parts)
            if all(isinstance(part, TextContentPart) for part in parts)
            else parts
        )


def _messages_have_remote_image(messages) -> bool:
    return any(
        isinstance(m.content, list)
        and any(
            isinstance(p, ImageContentPart) and not p.image_url.url.startswith("data:")
            for p in m.content
        )
        for m in messages
    )


def _request_has_attached_image(payload) -> bool:
    """An image the request itself carries, which the target model has to be able
    to read. History is not counted: a replayed MCP envelope is stripped for a
    text-only model, so it must not veto a switch to one."""
    if getattr(payload, "image_base64", None):
        return True
    return _messages_have_image(payload.messages)


def _names_a_non_mcp_tool(message) -> bool:
    """An absent name is not evidence of a non-MCP tool: older stored turns carry none."""
    name = message.get("name") if isinstance(message, dict) else getattr(message, "name", None)
    return isinstance(name, str) and bool(name) and not is_image_tool(name)


# Mirrors NON_VISION_PROVIDER_TYPES in frontend external-providers.ts: the registry marks these vision-capable, but their chat endpoint is text-only.
_TEXT_ONLY_PROVIDER_TYPES = frozenset({"cohere", "deepseek", "mistral"})


# Mixed catalogs require model-level vision capability; family flags do not
# identify which models accept images. Qwen has unrestricted text defaults;
# its vision models use separate qwen-vl-* or Qwen2.5-VL IDs. Z.ai lists text
# GLMs beside the -v / flash vision ones. Kimi is excluded
# because its allowlist permits only multimodal kimi-k3/k2.5/k2.6.
# Single-endpoint types (custom, vllm, ollama, llamacpp, lmstudio) retain the
# registry default: no model catalog exists to check the configured endpoint.
_MIXED_CATALOG_PROVIDER_TYPES = frozenset({"huggingface", "openrouter", "qwen", "qwencloud", "zai"})

# Mixed catalogs whose models.dev namespace answers vision per model.
# Mirrors CATALOG_VISION_PROVIDER_TYPES in external-providers.ts.
_CATALOG_VISION_NAMESPACES = {"qwencloud": "qwen", "zai": "zai"}


def _external_takes_mcp_images(
    provider_type,
    supports_vision: bool,
    model: "str | None" = None,
    info: "dict | None" = None,
) -> bool:
    """Stricter than the provider flag: an unsupported image fails the run, so unknown models answer no."""
    if provider_type in _TEXT_ONLY_PROVIDER_TYPES:
        return False
    if not supports_vision:
        return False
    capabilities = ((info or {}).get("model_capabilities") or {}) if info else {}
    if model and model in capabilities:
        return bool(capabilities[model].get("vision"))
    if provider_type in _MIXED_CATALOG_PROVIDER_TYPES:
        namespace = _CATALOG_VISION_NAMESPACES.get(provider_type)
        if namespace and model:
            from routes.providers import cached_catalog_model_inputs
            inputs = cached_catalog_model_inputs(namespace, model)
            if inputs is not None:
                return "image" in inputs
        # Vision for the family, unknown for this model: an image would be sent to
        # something that may not take one, and the failure lands mid-run.
        return False
    return True


def _messages_mention_mcp_images(messages) -> bool:
    """Dispatch only -- whether the work belongs off the loop. Substring, never a
    parse: the exact check json-loads the whole array, and doing that on the loop
    to decide whether to leave it parsed a 12 MB envelope right there."""
    for message in messages or ():
        role = message.get("role") if isinstance(message, dict) else getattr(message, "role", None)
        if role != "tool":
            continue
        content = (
            message.get("content")
            if isinstance(message, dict)
            else getattr(message, "content", None)
        )
        if isinstance(content, str) and mcp_images_mentioned_in(content):
            return True
    return False


def _messages_have_promotable_mcp_images(messages) -> bool:
    """Mirrors generation's promotion, so a named non-MCP result is not refused as an image."""
    for message in messages or ():
        if not isinstance(message, dict) or message.get("role") != "tool":
            continue
        content = message.get("content")
        if not isinstance(content, str) or not mcp_images_sentinel_in(content):
            continue
        if _names_a_non_mcp_tool(message):
            continue
        return True
    return False


def _request_has_replayed_mcp_images(payload) -> bool:
    return _messages_mention_mcp_images(payload.messages)


def _request_has_promotable_mcp_images(payload, *, exact: bool = True) -> bool:
    """exact=False is a substring test for the event loop; false positives only cost a catalog fetch."""
    present = mcp_images_sentinel_in if exact else mcp_images_mentioned_in
    # Same positional correlation as generation: non-MCP results are never promoted.
    names = _mcp_resolve_tool_names(payload.messages)
    for index, message in enumerate(payload.messages):
        if getattr(message, "role", None) != "tool":
            continue
        content = getattr(message, "content", None)
        if not isinstance(content, str) or not present(content):
            continue
        name = getattr(message, "name", None) or names.get(index)
        if isinstance(name, str) and name and not is_image_tool(name):
            continue
        return True
    return False


def _request_has_image(payload) -> bool:
    # A replayed envelope is decoded and re-encoded like an image, so the work runs off the event loop.
    return _request_has_attached_image(payload) or _request_has_replayed_mcp_images(payload)


def _anthropic_image_blocks(payload, *, tool_results: bool = True):
    for msg in getattr(payload, "messages", None) or ():
        content = msg.get("content") if isinstance(msg, dict) else msg.content
        if not isinstance(content, list):
            continue
        for block in content:
            block = block if isinstance(block, dict) else block.model_dump()
            if block.get("type") == "image":
                yield block
            elif (
                tool_results
                and block.get("type") == "tool_result"
                and isinstance(block.get("content"), list)
            ):
                for part in block["content"]:
                    if isinstance(part, dict) and part.get("type") == "image":
                        yield part


def _anthropic_request_has_image(payload, *, tool_results: bool = True) -> bool:
    return next(_anthropic_image_blocks(payload, tool_results = tool_results), None) is not None


def _anthropic_top_level_image_location(payload) -> Optional[str]:
    ordinals = getattr(payload, "_message_ordinals", None) or []
    for i, msg in enumerate(payload.messages):
        if isinstance(msg.content, list):
            for j, block in enumerate(msg.content):
                if block.type == "image":
                    return f"messages.{ordinals[i] if i < len(ordinals) else i}.content.{j}.image"
    return None


def _anthropic_local_image_payloads(payload) -> list[str]:
    encoded_images = []
    for block in _anthropic_image_blocks(payload):
        source = block.get("source")
        if not isinstance(source, dict):
            continue
        source_type = source.get("type")
        data = source.get("data")
        if source_type == "base64" and isinstance(data, str):
            encoded_images.append(data)
        url = source.get("url")
        if source_type == "url" and isinstance(url, str) and url.startswith("data:"):
            encoded_images.append(url.partition(",")[2])
    return encoded_images


def _auto_switch_opted_out(fastapi_request) -> bool:
    scope = getattr(fastapi_request, "scope", None)
    return isinstance(scope, dict) and bool(scope.get(_DISABLE_OPENAI_AUTO_SWITCH_SCOPE_KEY))


def disable_openai_auto_switch_for_request(scope) -> None:
    """Opt a request out of OpenAI auto-switch. The public preview route uses this:
    it always serves its pinned checkpoint, so a caller-supplied model must never
    swap the loaded model."""
    if isinstance(scope, dict):
        scope[_DISABLE_OPENAI_AUTO_SWITCH_SCOPE_KEY] = True


_ALLOW_MODEL_SWITCH_SCOPE_KEY = "unsloth.allow_model_switch"


def allow_model_switch_for_request(scope) -> None:
    """Let one in-process request load its named model with auto-switch off; a scope key, so no HTTP client can set it."""
    if isinstance(scope, dict):
        scope[_ALLOW_MODEL_SWITCH_SCOPE_KEY] = True


def _model_switch_allowed_for_request(fastapi_request) -> bool:
    scope = getattr(fastapi_request, "scope", None)
    return isinstance(scope, dict) and bool(scope.get(_ALLOW_MODEL_SWITCH_SCOPE_KEY))


_SWITCH_PRECONDITION_SCOPE_KEY = "unsloth.switch_precondition"


def require_for_model_switch(scope, check) -> None:
    """Have this in-process request's switch call ``check()`` under the swap gate, just before it replaces the
    loaded model; ``check`` raises to refuse. A scope key, so no HTTP client can set it."""
    if isinstance(scope, dict):
        scope[_SWITCH_PRECONDITION_SCOPE_KEY] = check


def _check_switch_precondition(fastapi_request) -> None:
    scope = getattr(fastapi_request, "scope", None)
    check = scope.get(_SWITCH_PRECONDITION_SCOPE_KEY) if isinstance(scope, dict) else None
    if callable(check):
        check()


_LOAD_ALONGSIDE_SCOPE_KEY = "unsloth.load_alongside"


def load_alongside_for_request(scope) -> None:
    """Under Keep multiple models loaded, let this in-process request's switch load beside the loaded model, as Chat's picker does."""
    if isinstance(scope, dict):
        scope[_LOAD_ALONGSIDE_SCOPE_KEY] = True


def _load_alongside_for_request(fastapi_request) -> bool:
    scope = getattr(fastapi_request, "scope", None)
    return isinstance(scope, dict) and bool(scope.get(_LOAD_ALONGSIDE_SCOPE_KEY))


_NO_AUTO_DOWNLOAD_SCOPE_KEY = "unsloth.no_auto_download"


def disable_auto_download_for_request(scope) -> None:
    """Stop an in-process scheduled run from auto-downloading; a model gone from disk fails the run."""
    if isinstance(scope, dict):
        scope[_NO_AUTO_DOWNLOAD_SCOPE_KEY] = True


async def _keyless_caller_held_back(fastapi_request) -> bool:
    """Keyless caller that may not POST /api/inference/load itself, so it may not switch models."""
    from auth.authentication import request_admitted_without_credential
    from utils.keyless_api_access import keyless_request_may_load_models

    if not request_admitted_without_credential(fastapi_request):
        return False
    return not await keyless_request_may_load_models(fastapi_request)


def _automatic_model_load_may_run() -> bool:
    """Reads the configured setting, not the effective TTL: residency stops unloads but not reloads."""
    from utils.openai_auto_switch_settings import (
        get_openai_auto_switch_enabled,
        idle_unload_is_configured,
    )
    return get_openai_auto_switch_enabled() or idle_unload_is_configured()


def _no_model_loaded_detail(base: str) -> str:
    """Appends the auto-switch hint only when the toggle is off; with it on the hint would mislead."""
    from utils.openai_auto_switch_settings import get_openai_auto_switch_enabled

    if get_openai_auto_switch_enabled():
        return base
    return base + (
        " Or enable Model auto-switch (Settings > API) to load a requested model automatically."
    )


# Cap on ids listed by a "not downloaded" error, so it stays readable in a terminal.
_MAX_LISTED_AVAILABLE_MODELS = 8


def _raw_body_model(body) -> Optional[str]:
    """The ``model`` a raw-body endpoint was given, else None (same value
    :func:`_auto_switch_from_request_body` fed the switch hook)."""
    return body.get("model") if isinstance(body, dict) else None


def _catalog_object_ids(objects: list[dict]) -> list[str]:
    """Ids to offer a chat caller. Task-carrying rows are dropped for the reason
    _chat_servable_ids drops them, or the error names the model it just refused."""
    return sorted(
        mid
        for mid in (m.get("id") for m in objects if m.get("task") is None)
        if isinstance(mid, str) and mid
    )


def _chat_servable_ids(objects: list[dict]) -> set[str]:
    """Casefolded ids the chat endpoints can serve: a media, speech or TTS row carries a ``task``."""
    return {
        obj["id"].casefold()
        for obj in objects
        if isinstance(obj.get("id"), str) and obj["id"] and obj.get("task") is None
    }


async def _downloaded_model_ids() -> set[str]:
    """Casefolded ids of every complete model in the local catalog, read before the servability
    filter so an id here and absent from the chat listing is downloaded but withheld. Filtered for
    visibility, or it would report another account's inventory."""
    catalog = await _cached_local_catalog()
    if account_access.managed_account():
        catalog = await asyncio.to_thread(account_access.filter_model_rows, catalog)
    ids = set()
    for info in catalog:
        if getattr(info, "partial", False):
            continue
        cid = getattr(info, "model_id", None) or public_model_id(getattr(info, "id", None))
        if isinstance(cid, str) and cid:
            ids.add(cid.casefold())
    return ids


def _format_available_models(ids: list[str]) -> str:
    if not ids:
        return ""
    shown = ", ".join(ids[:_MAX_LISTED_AVAILABLE_MODELS])
    extra = len(ids) - _MAX_LISTED_AVAILABLE_MODELS
    return f"{shown} and {extra} more" if extra > 0 else shown


async def _unavailable_model_message(requested_model: str) -> str:
    """A named model usually fails because it is not downloaded here, which /inference/load cannot fix."""
    from core.inference.local_model_resolver import (
        MISS_VARIANT_NOT_FOUND,
        describe_local_miss,
    )

    reason, variants = await asyncio.to_thread(describe_local_miss, requested_model)
    if reason == MISS_VARIANT_NOT_FOUND:
        # Repo downloaded, only the quant missing: sibling quants beat the catalog.
        base_id, _, wanted = requested_model.strip().rpartition(":")
        return (
            f"The model '{base_id}' is downloaded, but the quant '{wanted}' is not. "
            f"Available quants: {', '.join(variants)}."
        )
    # One build, two views: each _openai_catalog_objects() call re-probes quants through the resolver.
    catalog_objects = await _openai_catalog_objects()
    available = _format_available_models(_catalog_object_ids(catalog_objects))
    requested = requested_model.strip()
    base, sep, _tag = requested.rpartition(":")
    # The branch above only fires for an indexed repo with variants, so test the base too.
    candidates = [requested.casefold()] + (
        [base.strip().casefold()] if sep and base.strip() else []
    )
    # Include advertised aliases (e.g. 'tiny' for whisper-tiny), not just raw model_id.
    downloaded = await _downloaded_model_ids() | {
        obj["id"].casefold()
        for obj in catalog_objects
        if isinstance(obj.get("id"), str) and obj["id"]
    }
    servable = _chat_servable_ids(catalog_objects)
    withheld = next((c for c in candidates if c in downloaded and c not in servable), None)
    if withheld is not None:
        named = requested if withheld == requested.casefold() else base.strip()
        # No 'load it in Studio' hint: model_file checkpoints bypass the consent gate.
        message = (
            f"The model '{named}' is downloaded, but this server cannot serve it here: it is not a "
            "chat model this backend loads, or it needs custom code an API request cannot approve."
        )
        return f"{message} Available models: {available}." if available else message
    if not available:
        if downloaded:
            # `downloaded`, not catalog: resolver-withheld checkpoints never enter the catalog.
            return (
                f"The model '{requested_model}' is not downloaded on this server, and none of "
                "the downloaded models is a chat model. Download one in Unsloth Studio, "
                "or list what is here with GET /v1/models."
            )
        return (
            f"The model '{requested_model}' is not downloaded on this server, and no "
            "models are downloaded yet. Download one in Unsloth Studio."
        )
    return (
        f"The model '{requested_model}' is not downloaded on this server. "
        f"Available models: {available}. Download more in Unsloth Studio, "
        "or list them with GET /v1/models."
    )


async def _no_model_loaded_error(
    base: str, requested_model: Optional[str], fastapi_request: Optional[Request], *, status: int
):
    """Changes only the cases the generic text gets wrong; everything else keeps status and detail."""
    from utils.openai_auto_switch_settings import get_openai_auto_switch_enabled
    from core.inference.local_model_resolver import resolve_local_gguf

    _npu_model = _resident_npu_model()
    if _npu_model is not None:
        return 400, (
            f"The loaded NPU model ({_npu_model.model_path}) serves "
            "/v1/chat/completions only. Load a GGUF model to use this endpoint."
        )
    named = (
        requested_model
        if isinstance(requested_model, str)
        and requested_model.strip()
        and requested_model != _RELOAD_ONLY_MODEL
        else None
    )
    if named is None or not get_openai_auto_switch_enabled():
        return status, _no_model_loaded_detail(base)
    try:
        if await asyncio.to_thread(_loaded_satisfies, named):
            # Resident but on a backend this endpoint can't use, so "not downloaded" is false.
            return status, _no_model_loaded_detail(base)
        if await asyncio.to_thread(resolve_local_gguf, named) is not None:
            if fastapi_request is not None and await _keyless_caller_held_back(fastapi_request):
                return status, (
                    f"No model is loaded, and keyless API access cannot load '{named}' by "
                    "request. Load it in Unsloth Studio, or send an Unsloth API key."
                )
            # Resolvable but unloaded: the switch failed, which the generic text covers.
            return status, _no_model_loaded_detail(base)
        message = await _unavailable_model_message(named)
    except Exception as exc:
        # The diagnosis is a nicety; never let it turn a 4xx into a 500.
        logger.debug("no-model-loaded diagnosis failed for %r: %s", named, exc)
        return status, _no_model_loaded_detail(base)
    path = getattr(getattr(fastapi_request, "url", None), "path", None)
    if not isinstance(path, str):
        # No request in hand: let the global /v1/* handler pick the envelope.
        return 404, message
    return 404, error_body_for_path(
        path,
        message,
        status = 404,
        code = "model_not_found",
        param = "model",
    )


def _auto_download_hf_token(fastapi_request: Optional[Request]) -> Optional[str]:
    """Only the caller's own token, so an API key cannot borrow the owner's private repo access."""
    from hub.dependencies import HUB_HF_TOKEN_HEADER, HUB_HF_TOKEN_MAX_LENGTH

    headers = getattr(fastapi_request, "headers", None)
    if headers is None:
        return None
    supplied = (headers.get(HUB_HF_TOKEN_HEADER) or "").strip()
    if supplied and len(supplied) <= HUB_HF_TOKEN_MAX_LENGTH:
        return supplied
    return None


async def _maybe_auto_download_model(
    requested_model: str,
    fastapi_request: Optional[Request],
    *,
    require_vision: bool = False,
    require_speech: bool = False,
    current_subject: Optional[str] = None,
    rejection_prefix: str = "",
) -> None:
    """Opt-in fetch of a missing named GGUF; raises to stop the request while it downloads. Off by default, and gpt-4 style ids still fall through."""
    from utils.openai_auto_switch_settings import get_openai_auto_download_enabled
    from core.inference.openai_auto_download import (
        is_downloadable_ref,
        maybe_auto_download,
        split_model_ref,
    )

    if not requested_model or not get_openai_auto_download_enabled():
        return
    scope = getattr(fastapi_request, "scope", None)
    if isinstance(scope, dict) and scope.get(_NO_AUTO_DOWNLOAD_SCOPE_KEY):
        return
    if not is_downloadable_ref(requested_model):
        return
    # The resolver never serves a Decision API repo, so fetching one would only fill the disk.
    if is_decision_api_model(split_model_ref(requested_model)[0]):
        return
    # An Ollama-style tag (":latest") names no quant, so the resolver misses a servable model.
    if await asyncio.to_thread(_loaded_satisfies, requested_model):
        return
    try:
        refusal = await maybe_auto_download(
            requested_model,
            hf_token = _auto_download_hf_token(fastapi_request),
            require_vision = require_vision,
            require_speech = require_speech,
            subject = current_subject,
            # These endpoints also serve Unsloth's chat on a JWT, so only mark real API traffic.
            via_api_key = _request_used_api_key(fastapi_request),
        )
    except Exception as exc:
        # Never turn a servable request into a 500 over the download attempt.
        logger.warning("auto-download failed for %r: %s", requested_model, exc)
        return
    if refusal is None:
        return
    message = refusal.message
    if refusal.code == "invalid_value":
        message = f"{rejection_prefix}{message}"
    path = getattr(getattr(fastapi_request, "url", None), "path", None)
    detail = (
        error_body_for_path(
            path,
            message,
            status = refusal.status,
            code = refusal.code,
            param = "model",
        )
        if isinstance(path, str)
        else message
    )
    _record_refused_request(fastapi_request, requested_model, refusal, current_subject)
    raise HTTPException(
        status_code = refusal.status,
        detail = detail,
        headers = ({"Retry-After": str(refusal.retry_after)} if refusal.retry_after else None),
    )


def _record_refused_request(
    fastapi_request: Optional[Request],
    requested_model: str,
    refusal: Any,
    current_subject: Optional[str],
) -> None:
    """Logs the refused call itself: the refusal replaces the handler, so its api_monitor.start
    never runs."""
    state = getattr(fastapi_request, "state", None)
    if getattr(state, "skip_api_monitor", False):
        return
    path = getattr(getattr(fastapi_request, "url", None), "path", None)
    entry_id = api_monitor.start(
        endpoint = path if isinstance(path, str) else "/v1",
        method = str(getattr(fastapi_request, "method", "") or "POST"),
        model = requested_model,
        prompt = "",
        subject = current_subject,
        via_api_key = _request_used_api_key(fastapi_request),
    )
    api_monitor.fail(entry_id, refusal.message)


def _resident_id_is_namespaced() -> bool:
    """Directory-loaded models have bare names, so a namespaced request is undecidable, not refused."""
    llama_backend = get_llama_cpp_backend()
    if getattr(llama_backend, "is_loaded", False):
        candidates = (
            getattr(llama_backend, "model_identifier", None),
            getattr(llama_backend, "_openai_advertised_id", None),
            _llama_public_model_id(llama_backend),
        )
    else:
        orchestrator = get_inference_backend()
        active = getattr(orchestrator, "active_model_name", None)
        # The alias outlives an unload; only trust it while active_model_name is set.
        candidates = (
            (active, getattr(orchestrator, "_openai_advertised_id", None)) if active else ()
        )
    return any("/" in (public_model_id(c) or "") for c in candidates if c)


def _resident_npu_model():
    """The NPU model serving chat, or None. It answers to its own names only, and holds the
    primary's seat: a request routed to a model kept alongside is not the NPU's."""
    from core.inference.npu_backend import peek_npu_backend

    if routed_slot.get() is not None:
        return None
    npu = peek_npu_backend()
    return npu.loaded_model if npu is not None else None


def _unindexed_build_stem(variant: str) -> bool:
    """Whether *variant* may name a same-quant build (``beta-Q4_K_M``) the cold index cannot place yet."""
    from core.inference.local_model_resolver import index_is_built
    from hub.utils.gguf import extract_quant_token

    return not index_is_built() and extract_quant_token(variant) is not None


def _loaded_satisfies(requested: str) -> bool:
    """A bare org/model matches any loaded quant of that repo; an explicit :QUANT must match it."""
    from core.inference.openai_auto_download import looks_like_quant, split_model_ref

    npu_model = _resident_npu_model()
    if npu_model is not None:
        return requested in (npu_model.model_path, npu_model.id)
    base, variant = split_model_ref(requested)
    llama_backend = get_llama_cpp_backend()
    if getattr(llama_backend, "is_loaded", False):
        candidates = [
            candidate
            for candidate in (
                getattr(llama_backend, "model_identifier", None),
                getattr(llama_backend, "_openai_advertised_id", None),
                _llama_public_model_id(llama_backend),
            )
            if candidate
        ]
        identifier = getattr(llama_backend, "model_identifier", None)
        if identifier and is_ollama_manifest_ref(identifier):
            # A re-pull keeps a spelling and replaces its blobs: the tag vouches for itself only.
            own = [name for name in (identifier, _ollama_public_id(identifier)) if name]
            still_tagged = _resident_is_still_tagged(identifier, llama_backend)
            if _matches_any(requested, own):
                return still_tagged
            if _matches_any(base, own):
                # The tag itself is the whole name, so a quant suffix on top of it names nothing.
                return still_tagged and not looks_like_quant(variant)
            return _ollama_request_is_resident(requested, llama_backend)
        if not _matches_any(requested, candidates) and not _matches_any(base, candidates):
            return False
        if variant and not looks_like_quant(variant):
            from core.inference.local_model_resolver import (
                local_gguf_pinned_variant,
                local_gguf_withheld,
            )

            pinned_variant = local_gguf_pinned_variant(requested, allow_scan = False)
            if pinned_variant is not None:
                return _same_local_build(
                    base, getattr(llama_backend, "hf_variant", None) or "", pinned_variant
                )
            if _unindexed_build_stem(variant) or local_gguf_withheld(requested):
                return False
        if not looks_like_quant(variant):
            return True
        return (getattr(llama_backend, "hf_variant", None) or "").lower() == variant.lower()
    backend = get_inference_backend()
    active = getattr(backend, "active_model_name", None)
    if not active:
        return False
    matches = _matches_any(
        base, [active, public_model_id(active), getattr(backend, "_openai_advertised_id", None)]
    )
    if not matches:
        # a fine-tuning job's "<run>/checkpoint-N" name for the folder loaded by path
        trained = _trained_run_dir(requested)
        matches = trained is not None and _norm_path(trained) == _norm_path(active)
    if not matches:
        return False
    # Only llama.cpp carries a quant identity, so this backend can only match on the repo.
    if looks_like_quant(variant):
        return False
    if variant:
        from core.inference.local_model_resolver import (
            local_gguf_pinned_variant,
            local_gguf_withheld,
        )
        if local_gguf_pinned_variant(requested, allow_scan = False) is not None:
            return False
        if _unindexed_build_stem(variant) or local_gguf_withheld(requested):
            return False
    # The alias too: auto-switch records the repo id there, not in active_model_name.
    return True


def _loaded_identity_satisfies(requested: str) -> bool:
    """Excludes the path-derived public id so an alias reaches the resolver to be recorded; a request naming the load path is held back until then."""
    from core.inference.openai_auto_download import split_model_ref

    npu_model = _resident_npu_model()
    if npu_model is not None:
        return requested in (npu_model.model_path, npu_model.id)
    base, _ = split_model_ref(requested)
    llama_backend = get_llama_cpp_backend()
    if getattr(llama_backend, "is_loaded", False):
        identifier = getattr(llama_backend, "model_identifier", None)
        advertised = getattr(llama_backend, "_openai_advertised_id", None)
        # Local-path loads advertise nothing; go through the resolver so the alias is recorded.
        if advertised is None and identifier and _looks_like_local_path(identifier):
            return False
        companion_roots = tuple(getattr(llama_backend, "_openai_gguf_companion_roots", ()) or ())
        if companion_roots:
            from core.inference.local_model_resolver import (
                local_gguf_companion_roots,
                local_gguf_companion_state,
            )

            # A revision pin drops repo scope; a repo alias must notice newly cached companions.
            if _looks_like_local_path(base) or companion_roots != local_gguf_companion_roots(
                identifier, repo_level = True
            ):
                return False
            if getattr(
                llama_backend, "_openai_gguf_companion_state", ()
            ) != local_gguf_companion_state(companion_roots):
                return False
        return _matches_any(base, (identifier, advertised)) and _loaded_satisfies(requested)
    backend = get_inference_backend()
    active = getattr(backend, "active_model_name", None)
    if not active:
        return False
    advertised = getattr(backend, "_openai_advertised_id", None)
    # Same rule as the llama branch: answering from the path alone skips the recording.
    if advertised is None and _looks_like_local_path(active):
        return False
    return _matches_any(base, (active, advertised)) and _loaded_satisfies(requested)


def _raise_still_indexing(requested_model: str, fastapi_request) -> None:
    """Refuse a name we cannot yet place, rather than answer it with another model."""
    path = getattr(getattr(fastapi_request, "url", None), "path", None)
    message = (
        f"This server is still indexing its local models, so it cannot confirm "
        f"'{requested_model}' yet. Retry shortly."
    )
    raise HTTPException(
        status_code = 503,
        detail = (
            error_body_for_path(path, message, status = 503, code = "model_indexing")
            if isinstance(path, str)
            else message
        ),
        headers = {"Retry-After": "5"},
    )


def _matches_any(requested: str, candidates) -> bool:
    """Repo ids match case-insensitively; paths stay case-sensitive, or foo.gguf and Foo.gguf merge."""
    lowered = requested.strip().lower()
    for candidate in candidates:
        if not candidate:
            continue
        if _looks_like_local_path(requested) or _looks_like_local_path(candidate):
            if _norm_path(requested) == _norm_path(candidate):
                return True
            continue
        if lowered == str(candidate).strip().lower():
            return True
    return False


_TRAINED_CHECKPOINT = re.compile(r"checkpoint-\d+")


def _trained_run_dir(model: Optional[str]) -> Optional[str]:
    """The outputs folder a fine-tuning job names as ``<run>`` or ``<run>/checkpoint-<step>``."""
    from utils.paths import outputs_root

    if not isinstance(model, str) or "\\" in model:
        return None
    parts = model.split("/")
    if len(parts) > 2 or (len(parts) == 2 and not _TRAINED_CHECKPOINT.fullmatch(parts[1])):
        return None
    if any(part in ("", ".", "..") or part != os.path.basename(part) for part in parts):
        return None
    try:
        run_dir = outputs_root().joinpath(*parts)
        return str(run_dir) if run_dir.is_dir() else None
    except (OSError, ValueError):
        return None


def _resolve_trained_run_request(request) -> bool:
    """Rewrites a run or checkpoint name on a load / unload request to its folder."""
    trained = _trained_run_dir(request.model_path)
    if not trained:
        return False
    from hub.utils.host_paths import note_resolved_handle

    note_resolved_handle(request.model_path, trained)
    request.model_path = trained
    return True


def _looks_like_local_path(value: str) -> bool:
    """A filesystem path rather than a repo id, so case matters."""
    text = str(value)
    return text.startswith("/") or text.startswith("~") or ":\\" in text or "\\" in text


def _norm_path(value: str) -> str:
    """Compare-ready path. normcase, not lower: on a case-sensitive filesystem
    /srv/models/Foo and /srv/models/foo are different models."""
    import os

    # Replace after normcase: on Windows normcase rewrites '/' to a backslash.
    return os.path.normcase(str(value)).replace("\\", "/").rstrip("/")


def _resident_quant_is(variant: Optional[str], base: Optional[str] = None) -> bool:
    """Whether the loaded GGUF is that exact quant."""
    resident = getattr(get_llama_cpp_backend(), "hf_variant", None) or ""
    return bool(variant) and _same_local_build(base, resident, variant)


def _same_local_build(base: Optional[str], resident: str, wanted: str) -> bool:
    from core.inference.local_model_resolver import local_gguf_same_build
    return local_gguf_same_build(base, resident, wanted)


def _blob_identity(identity: Optional[tuple]) -> Optional[tuple]:
    """A load identity reduced to (device, inode, size, mtime): link, hardlink and blob then match."""
    return tuple(part[-4:] for part in identity) if identity else None


def _ollama_public_id(ref: str) -> Optional[str]:
    try:
        return ollama_model_ref_public_id(ref)
    except (OSError, ValueError):
        return None


def _ollama_source_identity(ref: str) -> Optional[tuple]:
    """Blob identity of every file *ref*'s manifest names now, projector included, or None."""
    from core.inference.llama_cpp import LlamaCppBackend
    from hub.services.models.ollama import ollama_model_ref_files

    try:
        model_path, projector_path = ollama_model_ref_files(ref)
        return _blob_identity(
            LlamaCppBackend._gguf_load_source_identity(model_path, projector_path)
        )
    except (OSError, ValueError):
        return None


def _resident_is_still_tagged(ref: str, llama_backend) -> bool:
    # The load identity survives a failed load, so it describes a resident model only while one is.
    if not getattr(llama_backend, "is_loaded", False):
        return False
    source = _ollama_source_identity(ref)
    loaded = _blob_identity(getattr(llama_backend, "_gguf_load_identity", None))
    return bool(source and source == loaded)


def _ollama_request_is_resident(requested: str, llama_backend) -> bool:
    """Whether *requested*'s blobs are the resident ones. Reads the built index, never a scan."""
    identifier = getattr(llama_backend, "model_identifier", None)
    if not identifier or not is_ollama_manifest_ref(identifier):
        return False
    if is_ollama_manifest_ref(requested):
        return _resident_is_still_tagged(requested, llama_backend)
    from core.inference.local_model_resolver import resolve_local_gguf

    try:
        load_path = (resolve_local_gguf(requested, allow_scan = False) or (None,))[0]
    except Exception as e:
        logger.debug("inference.ollama_alias_resolve_failed: %s", e)
        return False
    return bool(
        load_path
        and is_ollama_manifest_ref(load_path)
        and _resident_is_still_tagged(load_path, llama_backend)
    )


def _resolves_to_resident(
    load_path: Optional[str],
    *,
    llama_only: bool = False,
    exact_only: bool = False,
) -> bool:
    """llama_only drops Transformers (no quant identity); exact_only drops directory-prefix matches."""
    if not load_path:
        return False
    target = _norm_path(load_path)
    llama_backend = get_llama_cpp_backend()
    # A reference and the .gguf link the picker loaded share no spelling, so only the blobs decide.
    if is_ollama_manifest_ref(load_path):
        return _resident_is_still_tagged(load_path, llama_backend)
    orchestrator_model = (
        None if llama_only else getattr(get_inference_backend(), "active_model_name", None)
    )
    for candidate in (
        getattr(llama_backend, "gguf_path", None)
        if getattr(llama_backend, "is_loaded", False)
        else None,
        getattr(llama_backend, "model_identifier", None)
        if getattr(llama_backend, "is_loaded", False)
        else None,
        orchestrator_model,
    ):
        if not candidate:
            continue
        current = _norm_path(candidate)
        if current == target:
            return True
        # Non-GGUF loads from its own directory, so nested rows are different weights.
        if exact_only or (candidate is orchestrator_model and orchestrator_model is not None):
            continue
        if current.startswith(f"{target}/"):
            # Innermost indexed model owns the file, so /models/A is not answered with A/sub/B; with no nested model indexed, keep matching.
            owner = _innermost_indexed_owner(current)
            if owner is None or owner == target:
                return True
            continue
        if target.startswith(f"{current}/"):
            return True
    return False


def _classify_and_probe_residency(
    load_path: str, alias: Optional[str], llama_only: bool
) -> tuple[bool, bool]:
    """A non-GGUF checkpoint must not match resident models through the GGUF directory-prefix rules."""
    from core.inference.local_model_resolver import local_target_is_gguf

    is_gguf = local_target_is_gguf(load_path, alias)
    return is_gguf, _resolves_to_resident(load_path, llama_only = llama_only, exact_only = not is_gguf)


def _validated_target_is_resident(
    request: "ValidateModelRequest",
    *,
    model_identifier: str,
    config,
    is_gguf: bool,
    native_grant_backed: bool,
) -> bool:
    """Judges the artifact validation resolved, not the spelling asked; a lease picks file and variant."""
    if is_ollama_manifest_ref(request.model_path):
        return _resolves_to_resident(request.model_path, llama_only = is_gguf)
    if native_grant_backed or not is_gguf:
        target = model_identifier
    else:
        from hub.utils.gguf import resolve_local_gguf_path
        target = config.gguf_file or resolve_local_gguf_path(model_identifier, request.gguf_variant)
    return _resolves_to_resident(target, llama_only = is_gguf, exact_only = True)


def _innermost_indexed_owner(path: str) -> Optional[str]:
    """Longest catalog-listed model path containing *path*, or None if none does."""
    best = None
    for info in _account_catalog_cache()["models"] or ():
        listed = getattr(info, "path", None)
        if not listed:
            continue
        normalized = _norm_path(listed)
        if path == normalized or path.startswith(f"{normalized}/"):
            if best is None or len(normalized) > len(best):
                best = normalized
    return best


async def _reject_unservable_model(
    requested_model: Optional[str], fastapi_request: Optional[Request]
) -> None:
    """Namespace decides nothing: refuses only an explicit quant or a model present locally."""
    from core.inference.openai_auto_download import (
        looks_like_gguf_hub_repo_id,
        looks_like_quant,
        split_model_ref,
    )

    if (
        not isinstance(requested_model, str)
        or not requested_model.strip()
        or requested_model == _RELOAD_ONLY_MODEL
    ):
        return
    base, variant = split_model_ref(requested_model)
    quantified = looks_like_quant(variant)
    gguf_hub_repo = looks_like_gguf_hub_repo_id(base)
    from core.inference.local_model_resolver import (
        index_is_built,
        local_gguf_pinned_variant,
        local_gguf_torn_only,
        local_gguf_withheld,
        recently_downloaded,
        resolve_local_gguf,
        warm_index_soon,
    )
    from utils.openai_auto_switch_settings import get_openai_auto_switch_enabled
    from core.inference.npu_backend import is_npu_model_path

    if is_npu_model_path(requested_model) and not await asyncio.to_thread(
        _loaded_satisfies, requested_model
    ):
        message = (
            f"The NPU model '{requested_model}' is not loaded. Load it in Unsloth Studio, or turn "
            "on 'Switch model by request' under Settings > API to load it from a request."
        )
        path = getattr(getattr(fastapi_request, "url", None), "path", None)
        raise HTTPException(
            status_code = 404,
            detail = (
                error_body_for_path(
                    path, message, status = 404, code = "model_not_found", param = "model"
                )
                if isinstance(path, str)
                else message
            ),
        )

    still_indexing = torn = trained = False
    try:
        if await asyncio.to_thread(_loaded_satisfies, requested_model):
            return
        if not (
            get_llama_cpp_backend().is_loaded
            or getattr(await asyncio.to_thread(get_inference_backend), "active_model_name", None)
            or _resident_npu_model() is not None
        ):
            return
        # Do not scan here; a cold index only costs evidence and the gate fails safe.
        if index_is_built():
            warm_index_soon()
            resolved = resolve_local_gguf(requested_model, allow_scan = False)
        else:
            # Nothing cached: pay one bounded scan off the loop rather than answer with the resident.
            try:
                resolved = await asyncio.wait_for(
                    asyncio.to_thread(resolve_local_gguf, requested_model),
                    _COLD_INDEX_WAIT_S,
                )
            except (TimeoutError, asyncio.TimeoutError):
                # Still scanning, so the name is unknown: answer not yet, never guess the resident model.
                warm_index_soon()
                still_indexing = True
                resolved = None
        if resolved is not None:
            # canonical even for a quant-shaped key: a saved build key can be re-keyed
            pinned_variant = local_gguf_pinned_variant(requested_model, allow_scan = False)
            if pinned_variant is not None:
                variant = pinned_variant
                quantified = True
        elif local_gguf_withheld(requested_model):
            # names a build that cannot be served, so no sibling may answer for it
            quantified = True
        # A manual load stores the on-disk path the resolver advertises under an alias,
        # so match on the path too. Quants of one repo share a directory, so the path
        # alone cannot tell them apart: without the variant check an explicit :Q8_0
        # would be answered by a resident Q4_K_M.
        # Off-loop: reads the Transformers singleton, and the llama.cpp short-circuits above
        # skip the offloaded reads, so on a restart this built the singleton on the loop.
        # the resolver's colon base: split_model_ref keeps a slash-qualified pin whole
        index_base = requested_model.rpartition(":")[0] or base
        resolved_is_resident = (
            resolved is not None
            and (
                await asyncio.to_thread(
                    _classify_and_probe_residency, resolved[0], resolved[2], quantified
                )
            )[1]
        )
        if resolved_is_resident and (not quantified or _resident_quant_is(variant, index_base)):
            return
        downloaded = resolved is not None
        # /v1/models may have advertised this id off its own scan while the index is cold.
        advertised_alias = requested_model
        advertised = _advertised_local_path(requested_model)
        if advertised is None:
            advertised_alias = base
            advertised = _advertised_local_path(base)
        # classified from the advertised path itself, since a resolver miss left the pair above safe.
        advertised_is_resident = (
            advertised is not None
            and (
                await asyncio.to_thread(
                    _classify_and_probe_residency, advertised, advertised_alias, quantified
                )
            )[1]
        )
        if advertised_is_resident and (not quantified or _resident_quant_is(variant, index_base)):
            return
        # The exact ref may miss on the quant alone, so ask about the repo too.
        here = (
            downloaded
            or advertised is not None
            # Just landed, so no scan has indexed it yet and neither of the above sees it.
            or recently_downloaded(base)
            or (variant is not None and resolve_local_gguf(base, allow_scan = False) is not None)
        )
        # Torn split sets are kept out of the index, but the name is still ours, not a foreign label.
        torn = (
            not here
            and base.strip().count("/") == 1
            and await asyncio.to_thread(local_gguf_torn_only, base)
        )
        trained = (
            not here and await asyncio.to_thread(_trained_run_dir, requested_model) is not None
        )
        here = here or torn or trained
        switchable = downloaded and get_openai_auto_switch_enabled()
    except HTTPException:
        # A refusal decided above must propagate, not fall through to the resident model.
        raise
    except Exception as exc:
        # Cannot verify: refuse only an explicit quant; this path cannot tell missing from broken scan.
        logger.debug("unservable-model check failed for %r: %s", requested_model, exc)
        if not quantified:
            return
        downloaded = here = switchable = torn = trained = False
    if still_indexing:
        _raise_still_indexing(requested_model, fastapi_request)
    if gguf_hub_repo and not (quantified or here):
        # Only decisive against a resident with a hub-style id; directory loads use bare names.
        gguf_hub_repo = await asyncio.to_thread(_resident_id_is_namespaced)
    if not (quantified or here or gguf_hub_repo):
        return
    if (
        switchable
        and fastapi_request is not None
        and await _keyless_caller_held_back(fastapi_request)
    ):
        # Switching is on but not for this caller, so a retry can never succeed.
        status_code, code = 404, "model_not_found"
        message = (
            f"The model '{requested_model}' is downloaded but not loaded, and keyless API "
            "access can only use the loaded model. Send an Unsloth API key to switch "
            "models by request, or load it in Unsloth Studio."
        )
    elif switchable:
        # On disk and switching allowed, so the swap failed: the resident model is wrong weights.
        status_code, code = 503, "model_switch_failed"
        message = (
            f"The model '{requested_model}' is downloaded, but this server could not "
            "switch to it. Retry shortly, or load it in Unsloth Studio."
        )
    elif torn:
        status_code, code = 404, "model_not_found"
        message = (
            f"The model '{requested_model}' is only partly downloaded on this server, so it "
            "cannot be served. Finish the download in Unsloth Studio."
        )
    elif trained:
        status_code, code = 404, "model_not_found"
        message = (
            f"The fine-tuned model '{requested_model}' is not loaded. Load it in Unsloth "
            "Studio, or with POST /api/inference/load, then retry."
        )
    elif downloaded:
        status_code, code = 404, "model_not_found"
        message = (
            f"The model '{requested_model}' is downloaded but not loaded, and "
            "'Switch model by request' is off, so this server can only serve the "
            "loaded model. Turn it on in Unsloth Studio under Settings > API."
        )
    else:
        status_code, code = 404, "model_not_found"
        try:
            message = await _unavailable_model_message(requested_model)
        except Exception as exc:
            # Only the wording is uncertain; the mismatch is already established.
            logger.debug("unavailable-model diagnosis failed for %r: %s", requested_model, exc)
            message = f"The model '{requested_model}' is not the model this server is serving."
    path = getattr(getattr(fastapi_request, "url", None), "path", None)
    raise HTTPException(
        status_code = status_code,
        detail = (
            error_body_for_path(path, message, status = status_code, code = code, param = "model")
            if isinstance(path, str)
            else message
        ),
        headers = {"Retry-After": "5"} if status_code == 503 else None,
    )


async def _require_named_model_access(
    named_model: str, fastapi_request: Optional[Request] = None
) -> None:
    """Authorize a named model via the account catalog, or an uncached Hub ref via caller token."""
    trained = await asyncio.to_thread(_trained_run_dir, named_model)
    if trained is not None:
        # a run name is no Hub id: the Hub allowlist would refuse it, so authorize the folder
        await asyncio.to_thread(account_access.require_model_access, trained)
        return
    try:
        await asyncio.to_thread(account_access.require_model_access, named_model)
        return
    except HTTPException as refusal:
        if refusal.status_code != 404:
            raise
    from core.inference.openai_auto_download import split_model_ref

    alias = (split_model_ref(named_model)[0] or "").strip().lower()
    if alias:
        await _cached_local_catalog()
        if await asyncio.to_thread(_own_local_model_for_alias, alias) is not None:
            return
        # split_model_ref keeps a quant-directory build pin (custom:Q4_K_M/beta-Q4_K_M) whole
        from core.inference.local_model_resolver import local_gguf_pinned_variant

        pinned_base = named_model.rpartition(":")[0].strip().lower()
        if (
            pinned_base
            and pinned_base != alias
            and await asyncio.to_thread(local_gguf_pinned_variant, named_model) is not None
            and await asyncio.to_thread(_own_local_model_for_alias, pinned_base) is not None
        ):
            return
    if await _caller_token_authorizes_download(named_model, fastapi_request):
        return
    raise HTTPException(status_code = 404, detail = "Model not found")


async def _caller_token_authorizes_download(
    named_model: str, fastapi_request: Optional[Request]
) -> bool:
    """Whether the caller's own Hub token authorizes fetching an uncached Hub reference."""
    from core.inference.openai_auto_download import is_downloadable_ref, split_model_ref
    from utils.openai_auto_switch_settings import get_openai_auto_download_enabled

    if fastapi_request is None or not get_openai_auto_download_enabled():
        return False
    reference = named_model.strip()
    if reference.startswith(("./", "../", "~", "/")) or not is_downloadable_ref(reference):
        return False
    # Only the caller's own token, never the server's ambient one.
    hf_token = _auto_download_hf_token(fastapi_request)
    if not hf_token:
        return False
    try:
        await asyncio.to_thread(
            account_access.authorize_download, split_model_ref(reference)[0], "model", hf_token
        )
    except HTTPException:
        return False
    return True


def _own_local_model_for_alias(alias: str) -> Optional[str]:
    for info in _account_catalog_cache()["models"] or ():
        cid = getattr(info, "model_id", None) or public_model_id(getattr(info, "id", None))
        path = getattr(info, "path", None)
        if not cid or not path or cid.strip().lower() != alias:
            continue
        if account_access.model_visible(path):
            return path
    return None


def _audio_cpp_switch_target(requested_model: Optional[str]) -> Optional[tuple]:
    """Answered from the HF cache alone: an umbrella folder id cannot be keyed by the local index, and a repo GGUF would otherwise reach llama-server."""
    from core.inference import audio_cpp_files
    from core.inference.audio_cpp_models import parse_identifier, resolve, split_variant_ref
    from core.inference.audio_cpp_server import model_runtime_problem

    if not isinstance(requested_model, str):
        return None
    base, _variant = split_variant_ref(requested_model)
    if parse_identifier(base) is None:
        return None
    try:
        model = resolve(requested_model, network = False)
    except Exception:  # noqa: BLE001 - not resolvable from the cache: not a switch target
        return None
    if model is None or model.audio_type is None or not audio_cpp_files.is_downloaded(model):
        return None
    # Refuse before the switch evicts the resident model.
    problem = model_runtime_problem(model)
    if problem:
        from core.inference.audio_cpp_failures import problem_http_exception
        raise problem_http_exception(problem, model)
    return (model.id, model.variant.key, model.id, False)


async def _refuse_unservable_npu_switch(
    named_model: str,
    fastapi_request: Request,
    *,
    gguf_only: bool,
    needs_vision: bool,
    needs_audio: bool,
    rejection_prefix: str,
    request_check: Optional[Callable[[Any], None]] = None,
) -> None:
    """400 for a request naming an NPU model that could not serve it once loaded.

    ``request_check`` runs the serving route's own checks against the target's catalog entry.
    """
    from core.inference.npu_backend import NpuError, get_npu_backend, model_id_from_path

    message = None
    if gguf_only:
        message = (
            f"The NPU model '{named_model}' serves /v1/chat/completions only. "
            "Load a GGUF model to use this endpoint."
        )
    elif needs_audio:
        message = f"{rejection_prefix}The NPU model '{named_model}' takes no audio or video input."
    elif (needs_vision or request_check is not None) and not await asyncio.to_thread(
        _loaded_satisfies, named_model
    ):
        try:
            model = await asyncio.to_thread(
                get_npu_backend().loadable_model, model_id_from_path(named_model)
            )
        except NpuError:
            model = None  # Not downloaded or unknown: the load reports that itself.
        if model is not None and needs_vision and not model.vision:
            message = f"{rejection_prefix}The NPU model '{named_model}' cannot read images."
        elif model is not None and request_check is not None:
            request_check(model)
    if message is None:
        return
    path = getattr(getattr(fastapi_request, "url", None), "path", None)
    raise HTTPException(
        status_code = 400,
        detail = (
            error_body_for_path(path, message, status = 400, code = "invalid_value", param = "model")
            if isinstance(path, str)
            else message
        ),
    )


async def _auto_switch_npu_model(
    named_model: str, fastapi_request: Request, current_subject: str, *, claim_resident: bool
) -> None:
    """Load a downloaded ``lemonade:<id>`` model a request names.

    The caller has checked auto-switch is on. Same lock, gates, waiter count, cancellation and
    deferred claim as a GGUF switch.
    """
    from core.inference.gpu_arbiter import MultiModelAlwaysRefusal, require_no_foreign_generations
    from core.inference.llama_keepwarm import inference_lifecycle_gate, model_load_gate
    from utils.openai_auto_switch_settings import get_model_override, resolve_fit_max_seq_length

    if await asyncio.to_thread(_loaded_satisfies, named_model):
        return
    # The context length saved in the model's settings, as a picker load sends it.
    max_seq_length = resolve_fit_max_seq_length(get_model_override(named_model), is_gguf = False)
    cancel_event = getattr(getattr(fastapi_request, "state", None), "generation_cancel_event", None)

    def _raise_if_cancelled() -> None:
        if cancel_event is not None and cancel_event.is_set():
            raise HTTPException(status_code = 409, detail = "Generation cancelled")

    _raise_if_cancelled()
    switch_path = getattr(getattr(fastapi_request, "url", None), "path", None)
    # Counted as a queued switch, so another switch's drain does not wait on this request.
    key = _switch_key(named_model, None)
    _note_switch_waiter(key, 1)
    try:
        async with _auto_switch_lock():
            await _acquire_swap_gate()
            try:
                async with model_load_gate(), inference_lifecycle_gate():
                    # Re-read under the gate: another request may have loaded it while this one waited.
                    if await asyncio.to_thread(_loaded_satisfies, named_model):
                        return
                    require_no_foreign_generations(path = switch_path)
                    prior_marker = _get_preview_resident()
                    loaded_ok = False
                    try:
                        await _load_model_impl(
                            LoadRequest(model_path = named_model, max_seq_length = max_seq_length or 0),
                            fastapi_request,
                            current_subject,
                            current_request_counted = True,
                            **(
                                {"load_cancel_event": cancel_event}
                                if cancel_event is not None
                                else {}
                            ),
                        )
                        loaded_ok = True
                        _raise_if_cancelled()
                    except MultiModelAlwaysRefusal as exc:
                        raise exc.as_http_exception(switch_path) from exc
                    finally:
                        if not claim_resident:
                            # Preview-owned until the route's 2xx claims it, so a later rejection
                            # leaves it evictable, as in the GGUF switch.
                            if loaded_ok or _loaded_slot_ident() == named_model:
                                _set_preview_resident(_loaded_slot_ident())
                            else:
                                _set_preview_resident(prior_marker)
            finally:
                # Deregister before releasing the gate, as the GGUF switch does.
                _note_switch_waiter(key, -1)
                key = None
                _auto_switch_process_lock.release()
    finally:
        if key is not None:
            _note_switch_waiter(key, -1)


def _switch_loads_beside(target_speaks: Callable[[], bool]) -> bool:
    """Under Keep multiple models loaded, a speech model loads beside a text one (or the reverse); the same kind replaces."""
    from utils.multi_model_settings import get_multi_model_enabled

    if not get_multi_model_enabled():
        return False
    if _llama_cpp_backend.is_active:
        return target_speaks() != bool(getattr(_llama_cpp_backend, "_is_audio", False))
    orchestrator = _peek_inference_backend()
    active = getattr(orchestrator, "active_model_name", None)
    if not active or getattr(orchestrator, "_managed_engine", None) is not None:
        return False
    info = orchestrator.models.get(active, {})
    return target_speaks() != bool(info.get("is_audio") and info.get("audio_type") != "whisper")


async def _maybe_auto_switch_model(
    requested_model: Optional[str],
    fastapi_request: Request,
    current_subject: str,
    *,
    require_vision: bool = False,
    require_image: bool = True,
    modality_label: str = "image or audio",
    rejection_prefix: str = "",
    claim_resident: bool = True,
    require_audio_input: bool = False,
    require_video: bool = False,
    gguf_only: bool = False,
    gguf_only_reason: Optional[str] = None,
    audio_cpp_ok: bool = True,
    audio_preflight: Optional[dict] = None,
    image_preflight: Optional[dict] = None,
    require_speech: bool = False,
    require_audio_workflow: Optional[str] = None,
    speech_budget: Optional[dict] = None,
    tool_images_only: bool = False,
    serves_npu: bool = False,
    npu_request_check: Optional[Callable[[Any], None]] = None,
    gguf_target_check: Optional[Callable[[], None]] = None,
) -> None:
    """Load a downloaded local model named by an OpenAI request when auto-switch is on.

    Covers both formats this server can serve from disk: a GGUF through llama.cpp
    and a non-GGUF checkpoint (safetensors, MLX) through the inference orchestrator.
    No-op unless enabled and ``requested_model`` resolves to a downloaded local
    model different from the loaded one. Unknown names fall through (drop-in
    compat); a miss only reaches the network when auto-download is also on, and
    even then only for ``namespace/name`` ids. ``require_vision`` rejects a swap
    to a target that cannot accept the request's input before it runs, so an image
    or audio request can't evict the resident model only to 400 afterwards.
    ``claim_resident`` claims a resident model the request adopts (clears the preview
    marker) at the no-load exits; a route that still has its own capability/backend
    checks that can reject (e.g. GGUF-only /v1/completions, /audio/generate) passes
    ``False`` and claims itself only after those checks pass, so a later rejection
    can't strand a preview-owned model as Unsloth-owned. ``require_image`` makes that
    rejection modality-aware for a GGUF, whose one projector carries both, and
    ``require_audio_input`` covers a non-GGUF checkpoint, which declares the two
    separately, and ``require_video`` asks a non-GGUF target for a video placeholder
    token. ``modality_label`` names the inputs attached, so the
    rejection does not report a modality the request never carried. ``gguf_only``
    marks an endpoint that reads llama.cpp alone, where loading a non-GGUF model
    would unload the resident one and leave the handler with nothing to serve;
    ``gguf_only_reason`` replaces its refusal message when the request, not the
    endpoint, is what only llama.cpp can serve. ``audio_preflight`` carries an audio upload whose format-dependent
    checks only the resolved target can decide; see
    :func:`_preflight_audio_for_switch`. ``image_preflight`` does the same for
    non-GGUF image count and byte validation. ``require_audio_workflow`` refuses a target that
    cannot run that Audio page workflow (``separate``, ``clone``...). ``serves_npu`` marks
    the chat route, the only one an NPU model serves; ``npu_request_check``
    refuses a request an NPU target would reject once loaded, given its catalog entry.
    """
    # A text-only GGUF reads tool-result images as a note, so only audio or video needs its mmproj.
    gguf_requires_vision = (
        (require_audio_input or require_video) if tool_images_only else require_vision
    )
    # The reload-only sentinel means an omitted model, not a name.
    named_model = requested_model if requested_model != _RELOAD_ONLY_MODEL else None
    # The public preview serves its pinned checkpoint only, never a model kept alongside.
    routed = await _route_to_extra_slot(
        None if _auto_switch_opted_out(fastapi_request) else named_model
    )
    if account_access.managed_account():
        if named_model:
            await _require_named_model_access(named_model, fastapi_request)
        elif account_access.resident_hidden("chat", _loaded_slot_ident()):
            raise HTTPException(status_code = 404, detail = "Model not found")
    if routed is not None:
        return

    async def _refuse_foreign_resident() -> None:
        """Serve a named model only if the resident is the caller's own, or answers to the name
        and is itself a model the caller may load."""
        if not named_model or not account_access.managed_account():
            return
        if not account_access.resident_hidden("chat", _loaded_slot_ident()):
            return
        if await asyncio.to_thread(_loaded_identity_satisfies, named_model):
            # The name was authorized, not the resident: a caller's own file can carry any id.
            resident = _loaded_slot_ident()
            try:
                await asyncio.to_thread(account_access.require_model_access, resident)
            except HTTPException as refusal:
                # A Hub resident the caller's own token can fetch is theirs to use as well.
                if refusal.status_code != 404:
                    raise
                resident_reference = str(resident or "")
                cached_repo = await asyncio.to_thread(
                    account_access.cached_model_repo, resident_reference
                )
                if not await _caller_token_authorizes_download(
                    cached_repo or resident_reference, fastapi_request
                ):
                    raise
            return
        raise HTTPException(status_code = 404, detail = "Model not found")

    from utils.openai_auto_switch_settings import (
        get_openai_auto_switch_enabled,
        get_model_override,
        idle_unload_is_configured,
        model_override_load_kwargs,
    )
    from core.inference.local_model_resolver import (
        local_gguf_companion_roots,
        local_gguf_pinned_variant,
        local_gguf_companion_state,
        local_target_is_gguf,
        resolve_local_gguf_for_switch,
        resolve_trusted_cached_local_gguf,
        warm_index_soon,
    )
    from core.inference.llama_keepwarm import (
        get_last_unloaded_model,
        inference_lifecycle_gate,
        model_load_gate,
        note_admitted_inference,
        preview_swapped_since_entry,
        stash_is_mlx,
    )

    generation_cancel_event = getattr(
        getattr(fastapi_request, "state", None),
        "generation_cancel_event",
        None,
    )
    caller_hf_token = _auto_download_hf_token(fastapi_request)

    def _raise_if_generation_cancelled() -> None:
        if generation_cancel_event is not None and generation_cancel_event.is_set():
            raise HTTPException(status_code = 409, detail = "Generation cancelled")

    # Count in the admitted-inference tally the preview busy guard uses, not raw _inflight.
    _swap_scope = getattr(fastapi_request, "scope", None)
    note_admitted_inference(_swap_scope)
    # Reject if a preview swapped checkpoints since entry; never serve its model. Here, not middleware, so external providers are not refused.
    if preview_swapped_since_entry(_swap_scope):
        raise HTTPException(
            status_code = 503,
            detail = "A preview is loading a model. Please retry shortly.",
            headers = {"Retry-After": "1"},
        )

    # Treat a non-string model (e.g. {"model": 123} on a raw-body endpoint) as
    # absent so it falls through instead of raising in the membership checks below.
    if not isinstance(requested_model, str) or not requested_model:
        # Omitted model on a non-preview call uses the resident one, so claim it; previews keep ownership.
        if claim_resident:
            _claim_slot_for_non_preview(fastapi_request)
        return
    # Preview route opts out so callers cannot switch away from the pinned checkpoint.
    if _auto_switch_opted_out(fastapi_request):
        return
    if (
        named_model
        and isinstance(_swap_scope, dict)
        and _swap_scope.get(LOADED_MODELS_ONLY_SCOPE_KEY)
    ):
        # A named model not routed to a kept slot: only the resident may answer, under the same
        # access check. An omitted one (the reload-only sentinel) keeps the path below.
        if not await asyncio.to_thread(_loaded_identity_satisfies, named_model):
            raise HTTPException(status_code = 404, detail = "Model not found")
        await _refuse_foreign_resident()
        if claim_resident:
            _claim_slot_for_non_preview(fastapi_request)
        return
    auto_switch_on = get_openai_auto_switch_enabled() or _model_switch_allowed_for_request(
        fastapi_request
    )

    def _refuse_non_gguf_endpoint() -> None:
        """Refuse a switch target this endpoint cannot serve.

        Raised only for a target the resolver found and that is not already serving:
        a resident non-GGUF model reaches the handler's own error instead, since no
        swap is pending to refuse.
        """
        message = gguf_only_reason or (
            f"This endpoint serves GGUF models only, and '{requested_model}' is not one. "
            "Use /v1/chat/completions for this model."
        )
        # error_body_for_path: Anthropic routes reach this too.
        path = getattr(getattr(fastapi_request, "url", None), "path", None)
        raise HTTPException(
            status_code = 400,
            detail = (
                error_body_for_path(path, message, status = 400, code = "invalid_value", param = "model")
                if isinstance(path, str)
                else message
            ),
        )

    # configured, not effective: residency zeroes the TTL, and the stash still has to restore.
    if not auto_switch_on and not idle_unload_is_configured():
        # Reject before claiming the slot.
        await _reject_unservable_model(requested_model, fastapi_request)
        await _refuse_foreign_resident()
        # Auto-switch off: this non-preview turn uses the resident model, claim it.
        if claim_resident:
            _claim_slot_for_non_preview(fastapi_request)
        return

    # Check resident state before the filesystem index; rebuilding it can take seconds.
    if auto_switch_on and await asyncio.to_thread(_loaded_identity_satisfies, requested_model):
        await _refuse_foreign_resident()
        warm_index_soon()
        if claim_resident:
            _claim_slot_for_non_preview(fastapi_request)
        return

    keyless_held_back = await _keyless_caller_held_back(fastapi_request)
    if auto_switch_on and keyless_held_back:
        auto_switch_on = False
        if not idle_unload_is_configured():
            await _reject_unservable_model(requested_model, fastapi_request)
            return

    from core.inference.npu_backend import is_npu_model_path

    if auto_switch_on and named_model and is_npu_model_path(named_model):
        # Refused before the switch, so a request the NPU cannot serve never evicts the resident model.
        await _refuse_unservable_npu_switch(
            named_model,
            fastapi_request,
            # gguf_only alone misses routes that relax it for in-process models.
            gguf_only = gguf_only or not serves_npu,
            # Not gguf_requires_vision: NPU chat rejects tool-result images too.
            needs_vision = require_vision,
            needs_audio = bool(
                require_audio_input
                or require_video
                or require_speech
                or require_audio_workflow
                or audio_preflight
            ),
            rejection_prefix = rejection_prefix,
            request_check = npu_request_check,
        )
        await _auto_switch_npu_model(
            named_model, fastapi_request, current_subject, claim_resident = claim_resident
        )
        if claim_resident:
            _claim_slot_for_non_preview(fastapi_request)
        return

    async def _resolve_and_switch() -> None:
        from core.inference.openai_auto_download import looks_like_quant, split_model_ref

        _raise_if_generation_cancelled()
        # Off the loop: a cold rebuild walks model dirs and HF caches; with auto-switch off or reload-only, skip the resolve so no name is matched.
        reload_only = requested_model == _RELOAD_ONLY_MODEL
        resolved = None
        repo_level_companion_resolution = False
        stashed_gguf_companion_roots: tuple[str, ...] = ()
        stashed_mlx = False
        if auto_switch_on and not reload_only:
            # audio.cpp GGUFs load via the audio worker, not llama-server; the HF cache resolves them.
            resolved = await asyncio.to_thread(_audio_cpp_switch_target, requested_model)
            if resolved is None:
                # Trusted hits are used at once; switch resolution refreshes stale hits and unconfirmed misses.
                resolved = resolve_trusted_cached_local_gguf(
                    requested_model,
                    include_companion_scope = True,
                )
            if resolved is not None:
                warm_index_soon()
            else:
                resolved = await asyncio.to_thread(
                    resolve_local_gguf_for_switch,
                    requested_model,
                    include_companion_scope = True,
                )
        if resolved is None:
            # A "<run>/checkpoint-N" name looks like a Hub id; the reject below refuses it instead.
            trained = (
                not reload_only
                and await asyncio.to_thread(_trained_run_dir, requested_model) is not None
            )
            # Not on disk. Opt-in: fetch in the background and ask the caller to retry.
            if auto_switch_on and not reload_only and not trained:
                await _maybe_auto_download_model(
                    requested_model,
                    fastapi_request,
                    # One mmproj carries both; splitting the needs would fetch a text-only repo.
                    require_vision = gguf_requires_vision or require_audio_input,
                    require_speech = require_speech,
                    current_subject = current_subject,
                    rejection_prefix = rejection_prefix,
                )
            # Reload exactly what idle-unload freed (path, quant, advertised id), keying the override by advertised id so an alias stays servable.
            last = get_last_unloaded_model()
            # Do not resurrect a stale GGUF over a live non-GGUF model.
            if (
                not last
                or get_llama_cpp_backend().is_loaded
                or getattr(
                    await asyncio.to_thread(get_inference_backend), "active_model_name", None
                )
            ):
                # Unknown name, model already resident: the non-preview call uses it,
                # so claim it for Unsloth.
                if claim_resident:
                    _claim_slot_for_non_preview(fastapi_request)
                return
            if len(last) >= 3:
                target_id, variant, override_id = last[:3]
                if len(last) >= 4:
                    stashed_gguf_companion_roots = tuple(last[3] or ())
            else:  # pre-3-tuple stash: fall back to the path as the override key
                target_id, variant = last
                override_id = target_id
            stashed_mlx = stash_is_mlx(last)
            # Held-back keyless callers may restore only the model they named; check before loading.
            if keyless_held_back and not reload_only:
                requested_base, requested_variant = split_model_ref(requested_model)
                if not _matches_any(
                    requested_base, (target_id, override_id, public_model_id(target_id))
                ) or (
                    looks_like_quant(requested_variant)
                    and (not variant or requested_variant.lower() != variant.lower())
                ):
                    return
        else:
            # load_path is a concrete local path, so /load cannot trigger a download.
            if len(resolved) >= 4:
                target_id, variant, override_id, repo_level_companion_resolution = resolved[:4]
            else:
                target_id, variant, override_id = resolved
                requested_base, _requested_variant = split_model_ref(requested_model)
                repo_level_companion_resolution = _matches_any(
                    requested_base,
                    (override_id, public_model_id(override_id)),
                )
        # Not inferred from the quant; audio.cpp GGUFs are read only by audiocpp_server.
        from core.inference.audio_cpp_models import looks_like_audio_cpp

        # A cold resolver index reads an unknown repo id as GGUF, so trust the stash's own format.
        target_is_gguf = (
            not stashed_mlx
            and not looks_like_audio_cpp(target_id)
            and await asyncio.to_thread(local_target_is_gguf, target_id, override_id)
        )
        gguf_companion_roots: tuple[str, ...] = ()
        if target_is_gguf:
            if resolved is None:
                gguf_companion_roots = stashed_gguf_companion_roots
            else:
                gguf_companion_roots = await asyncio.to_thread(
                    local_gguf_companion_roots,
                    target_id,
                    repo_level = repo_level_companion_resolution,
                )
        gguf_companion_state = (
            await asyncio.to_thread(local_gguf_companion_state, gguf_companion_roots)
            if gguf_companion_roots
            else ()
        )
        # no orchestrator means nothing non-GGUF is resident, so the cold build only precedes a 400.
        if (
            gguf_only
            and not target_is_gguf
            and resolved is not None
            and _peek_inference_backend() is None
        ):
            _refuse_non_gguf_endpoint()
        # Resolved once, off the loop: a cold orchestrator build waits on hardware detection.
        target_backend = (
            get_llama_cpp_backend()
            if target_is_gguf
            else await asyncio.to_thread(get_inference_backend)
        )
        backend = get_llama_cpp_backend()
        # A bare id or non-quant tag (':latest') is satisfied by any loaded quant of the repo.
        _, _requested_variant = split_model_ref(requested_model)
        # the index pin also covers directory-qualified keys split_model_ref cannot parse
        bare = (
            not looks_like_quant(_requested_variant)
            and local_gguf_pinned_variant(requested_model, allow_scan = False) is None
        )

        ollama_target = target_is_gguf and is_ollama_manifest_ref(target_id)
        ollama_source_identity = (
            await asyncio.to_thread(_ollama_source_identity, target_id) if ollama_target else None
        )

        def _already_serving() -> bool:
            # Match the load path and advertised repo id, so either load style counts as already serving.
            if not target_is_gguf:
                active = getattr(target_backend, "active_model_name", None)
                if not active:
                    return False
                # _matches_any, not lowercased: case-differing roots are different weights.
                loaded_keys = [active, getattr(target_backend, "_openai_advertised_id", None)]
                if _matches_any(target_id, loaded_keys):
                    return True
                # two scan roots can advertise one basename, so it cannot vouch for a path.
                if _looks_like_local_path(target_id) and _looks_like_local_path(active):
                    return False
                return _matches_any(override_id, loaded_keys)
            if not backend.is_loaded or not backend.model_identifier:
                return False
            loaded_keys = {backend.model_identifier.lower()}
            advertised = getattr(backend, "_openai_advertised_id", None)
            if advertised:
                loaded_keys.add(advertised.lower())
            if ollama_target:
                # The blobs, not the keys: an alias shares no spelling with the resident tag.
                loaded_source = _blob_identity(getattr(backend, "_gguf_load_identity", None))
                if not ollama_source_identity or loaded_source != ollama_source_identity:
                    return False
            elif loaded_keys.isdisjoint({target_id.lower(), override_id.lower()}):
                return False
            loaded_companion_roots = tuple(
                getattr(backend, "_openai_gguf_companion_roots", ()) or ()
            )
            if loaded_companion_roots != gguf_companion_roots:
                return False
            if getattr(backend, "_openai_gguf_companion_state", ()) != gguf_companion_state:
                return False
            if bare:
                return True
            if variant:
                loaded_variant = (getattr(backend, "hf_variant", None) or "").lower()
                return loaded_variant == variant.lower()
            return True

        def _record_serving_alias() -> None:
            # Record the alias as public id, resolver branch only (a stash override_id can be a bare path). Lock-free: the busy guard blocks concurrent swaps.
            if resolved is None or not override_id:
                return
            if getattr(target_backend, "_openai_advertised_id", None) != override_id:
                target_backend._openai_advertised_id = override_id

        if _already_serving():
            # Claiming it stops a later preview swapping it out from under an active OpenAI caller.
            if claim_resident:
                _set_preview_resident(None)
            _record_serving_alias()
            return
        from core.inference.gpu_arbiter import require_no_foreign_generations

        switch_path = getattr(getattr(fastapi_request, "url", None), "path", None)
        require_no_foreign_generations(path = switch_path)
        # These endpoints read llama.cpp only; a non-GGUF swap would strand them.
        if gguf_only and not target_is_gguf and resolved is not None:
            _refuse_non_gguf_endpoint()
        # A raw-prompt endpoint opened to MLX still has nothing an audio.cpp model can serve.
        if not audio_cpp_ok and looks_like_audio_cpp(target_id) and resolved is not None:
            _refuse_non_gguf_endpoint()
        # Raises for a request only a non-GGUF target serves, before any GGUF load or reload.
        if gguf_target_check is not None and target_is_gguf:
            gguf_target_check()
        # An image/audio request naming a different text-only target would load it
        # here and only 400 below, evicting the working model. Reject before the
        # swap. Only the resolver branch (an explicit new target); the reload-stash
        # path just restores the model the request was already using. The probe hits
        # the filesystem, so run it off the loop like the resolver above.
        target_requires_image = require_image
        if require_audio_input and not target_is_gguf and audio_preflight is not None:
            target_requires_image = bool(audio_preflight.get("has_image"))
        target_requires_vision = gguf_requires_vision if target_is_gguf else require_vision
        if tool_images_only and target_is_gguf:
            target_requires_image = False
        if (
            (target_requires_vision or require_audio_input)
            and resolved is not None
            and not await asyncio.to_thread(
                _target_accepts_request_input,
                target_id,
                target_is_gguf,
                target_requires_vision,
                require_audio_input,
                variant,
                target_requires_image,
                require_video,
                gguf_companion_roots,
            )
        ):
            raise HTTPException(
                status_code = 400,
                detail = openai_error_body(
                    f"{rejection_prefix}The requested model does not support the {modality_label} input in this request.",
                    status = 400,
                    code = "invalid_value",
                    param = "model",
                ),
            )
        speech_type = None
        if require_speech and resolved is not None:
            speech_type = await asyncio.to_thread(
                _target_speech_audio_type, target_id, target_is_gguf, variant
            )
            if speech_type is None:
                raise HTTPException(
                    status_code = 400,
                    detail = openai_error_body(
                        "The requested model is not a text-to-speech model.",
                        status = 400,
                        code = "invalid_value",
                        param = "model",
                    ),
                )
            from core.inference.native_audio import PYTHON310_AUDIO_TYPES

            if speech_type in PYTHON310_AUDIO_TYPES and sys.version_info < (3, 10):
                raise HTTPException(
                    status_code = 400,
                    detail = openai_error_body(
                        "The requested text-to-speech model requires Python 3.10 or newer in Unsloth.",
                        status = 400,
                        code = "unsupported_runtime",
                        param = "model",
                    ),
                )
            if speech_budget is not None:
                target_context = await asyncio.to_thread(
                    _target_effective_context_length,
                    target_id,
                    target_is_gguf,
                    variant,
                    override_id,
                    speech_type,
                )
                prompt_tokens = _byte_fallback_prompt_tokens(
                    _speech_prompt_for_budget(speech_type, speech_budget)
                )
                if target_context and _speech_budget_exhausted(target_context, prompt_tokens):
                    raise HTTPException(
                        status_code = 400,
                        detail = openai_error_body(
                            f"Input is too long for the requested model's "
                            f"{target_context}-token context. Shorten it, or pick a model "
                            "with a larger context.",
                            status = 400,
                            code = "invalid_value",
                            param = "input",
                        ),
                    )
            if (
                speech_type == "minimax_music3"
                and not str((speech_budget or {}).get("instructions") or "").strip()
            ):
                raise HTTPException(
                    status_code = 400,
                    detail = openai_error_body(
                        _MINIMAX_NEEDS_DESCRIPTION,
                        status = 400,
                        code = "invalid_value",
                        param = "instructions",
                    ),
                )
        if require_audio_workflow and resolved is not None:
            target_workflows = await asyncio.to_thread(
                _target_audio_workflows, target_id, speech_type
            )
            if require_audio_workflow not in target_workflows:
                from core.inference.audio_workflows import AUDIO_WORKFLOW_LABELS, pages_sentence

                page = AUDIO_WORKFLOW_LABELS.get(require_audio_workflow, require_audio_workflow)
                # Name the model as asked, never target_id: that can be a local path.
                label = _audio_model_label(str(named_model or "").replace("\\", "/"))
                raise HTTPException(
                    status_code = 400,
                    detail = openai_error_body(
                        f"{label} can't run {page} "
                        f"({require_audio_workflow}). {pages_sentence(target_workflows)}",
                        status = 400,
                        code = "invalid_value",
                        param = "model",
                    ),
                )
        # resolver branch only, like the probe above: a reload-stash restore changes no format.
        if audio_preflight is not None and resolved is not None:
            await _preflight_audio_for_switch(audio_preflight, target_is_gguf)
        if (
            image_preflight is not None
            and resolved is not None
            and (target_is_gguf or not require_audio_input)
            and not (
                not target_is_gguf
                and _override_selects_managed_engine(target_id, override_id, variant)
            )
        ):
            await _preflight_image_for_switch(
                image_preflight,
                target_is_gguf,
                target_takes_several = not target_is_gguf
                and await asyncio.to_thread(_local_target_may_take_several_images, target_id),
            )
        speech_cache_environment = None
        speech_codec_path = None
        if speech_type is not None:
            try:
                speech_preflight_result = await asyncio.to_thread(
                    _preflight_speech_codec_for_switch,
                    speech_type,
                    target_id,
                    target_is_gguf,
                    caller_hf_token,
                )
                if isinstance(speech_preflight_result, _SpeechCodecPreflightResult):
                    speech_cache_environment = speech_preflight_result.cache_environment
                    speech_codec_path = speech_preflight_result.codec_path
                elif isinstance(speech_preflight_result, dict):
                    speech_cache_environment = speech_preflight_result
            except Exception as exc:
                raise HTTPException(
                    status_code = 503,
                    detail = openai_error_body(
                        modelscope_missing(exc)
                        or "The requested model's codec assets are unavailable. Connect this "
                        "server to the network once to download them, or install them in the "
                        "active cache before retrying.",
                        status = 503,
                        code = "codec_unavailable",
                        param = "model",
                    ),
                ) from None
        key = _switch_key(override_id, variant)
        _note_switch_waiter(key, 1)
        waiter_noted = True
        try:
            async with _auto_switch_lock():
                # Process-wide gate: the asyncio lock is per loop.
                await _acquire_swap_gate()
                try:
                    # Hold the keep-warm gate across the swap so no new inference can
                    # start on the model while it is being torn down and replaced.
                    from utils.multi_model_settings import get_multi_model_enabled

                    # Beside: load_model_gated takes the load gate itself; the primary keeps serving.
                    beside = await asyncio.to_thread(
                        _switch_loads_beside,
                        # Chat serves a TTS model too, so the target decides, not the endpoint.
                        lambda: require_speech
                        or (
                            resolved is not None
                            and _target_speech_audio_type(target_id, target_is_gguf, variant)
                            is not None
                        ),
                    ) or (
                        # The load itself still replaces the loaded model when it does not fit beside it.
                        _load_alongside_for_request(fastapi_request)
                        and await asyncio.to_thread(get_multi_model_enabled)
                    )
                    async with AsyncExitStack() as swap_gates:
                        if not beside:
                            await swap_gates.enter_async_context(model_load_gate())
                            await swap_gates.enter_async_context(inference_lifecycle_gate())
                        # Re-read under the gate: the snapshot above predates the wait.
                        if ollama_target:
                            ollama_source_identity = await asyncio.to_thread(
                                _ollama_source_identity, target_id
                            )
                        if _already_serving():
                            if claim_resident:
                                _set_preview_resident(None)
                            _record_serving_alias()
                            return
                        require_no_foreign_generations(path = switch_path)
                        # Last chance to refuse: held swap gates keep inference and loads from starting before it.
                        _check_switch_precondition(fastapi_request)
                        # Order: variant-qualified keys before bare ids, load path before advertised id.
                        from utils.openai_auto_switch_settings import (
                            resolve_override_for_load,
                            stored_gpu_index_kind,
                        )

                        # Shared candidate order so the settings panel reads the same row.
                        _override_key, override = resolve_override_for_load(
                            target_id, override_id, variant
                        )
                        if require_speech and resolved is not None and speech_budget is not None:
                            target_context = await asyncio.to_thread(
                                _target_effective_context_length,
                                target_id,
                                target_is_gguf,
                                variant,
                                override_id,
                                speech_type,
                                override,
                                True,
                            )
                            prompt_tokens = _byte_fallback_prompt_tokens(
                                _speech_prompt_for_budget(speech_type, speech_budget)
                            )
                            if target_context and _speech_budget_exhausted(
                                target_context, prompt_tokens
                            ):
                                raise HTTPException(
                                    status_code = 400,
                                    detail = openai_error_body(
                                        f"Input is too long for the requested model's "
                                        f"{target_context}-token context. Shorten it, or pick a model "
                                        "with a larger context.",
                                        status = 400,
                                        code = "invalid_value",
                                        param = "input",
                                    ),
                                )
                        load_kwargs = {"model_path": target_id, "gguf_variant": variant}
                        load_kwargs.update(
                            model_override_load_kwargs(override, is_gguf = target_is_gguf)
                        )
                        if caller_hf_token:
                            load_kwargs["hf_token"] = caller_hf_token
                        if beside:
                            load_kwargs["alongside"] = True
                        saved_gpu_ids = load_kwargs.get("gpu_ids")
                        if saved_gpu_ids and not await _override_gpu_ids_still_resolve(
                            saved_gpu_ids, stored_gpu_index_kind(override)
                        ):
                            # Stale pin (GPU removed, another host, or a backend change
                            # renumbering these ids): drop it rather than 400 the load.
                            load_kwargs.pop("gpu_ids", None)
                            load_kwargs.pop("tensor_split", None)
                            logger.warning(
                                "Dropping saved gpu_ids %s for %s: not available here.",
                                saved_gpu_ids,
                                override_id,
                            )
                        # Call the impl directly: we hold the lifecycle gate the /load route takes (deadlock).
                        # Deferred claim: base preview ownership on what is actually resident, in a finally.
                        _switch_prior_marker = _get_preview_resident()
                        _switch_loaded_ok = False
                        try:
                            durable_cancel_kw = (
                                {"load_cancel_event": generation_cancel_event}
                                if generation_cancel_event is not None
                                else {}
                            )
                            load_internal_kw = dict(durable_cancel_kw)
                            if speech_cache_environment is not None:
                                load_internal_kw["cache_environment"] = speech_cache_environment
                            if speech_codec_path is not None:
                                load_internal_kw["speech_codec_path"] = speech_codec_path
                            if speech_type is not None and caller_hf_token is None:
                                load_internal_kw["anonymous_hf_access"] = True

                            async def _switch_load(load_request: LoadRequest) -> None:
                                nonlocal target_backend
                                if not beside:
                                    await _load_model_impl(
                                        load_request,
                                        fastapi_request,
                                        current_subject,
                                        current_request_counted = True,
                                        **load_internal_kw,
                                    )
                                    return
                                await load_model_gated(
                                    load_request,
                                    fastapi_request,
                                    current_subject,
                                    current_request_counted = True,
                                    impl_kwargs = load_internal_kw,
                                    background = True,
                                )
                                slot = routed_slot.get()
                                if slot is None:
                                    return
                                if not model_slots.reserve(slot):
                                    # Unloaded since: never answer as the primary.
                                    routed_slot.set(None)
                                    raise HTTPException(
                                        status_code = 503,
                                        detail = openai_error_body(
                                            "The requested model was unloaded before this request "
                                            "could use it. Please retry shortly.",
                                            status = 503,
                                            code = "model_loading",
                                            param = "model",
                                        ),
                                    )
                                target_backend = slot.llama if target_is_gguf else slot.orchestrator

                            try:
                                load_request = LoadRequest(**load_kwargs)
                                load_request._gguf_companion_roots = gguf_companion_roots
                                load_request._gguf_companion_roots_set = True
                                load_request._override_alias_id = override_id
                                await _switch_load(load_request)
                            except HTTPException as exc:
                                # Stale gpu_ids pins must never block a request; retry without.
                                if not (
                                    exc.status_code == 400
                                    and load_kwargs.get("gpu_ids")
                                    and "gpu" in str(exc.detail).lower()
                                ):
                                    raise
                                logger.warning(
                                    "Retrying %s without saved gpu_ids %s: %s",
                                    override_id,
                                    load_kwargs.get("gpu_ids"),
                                    exc.detail,
                                )
                                load_kwargs.pop("gpu_ids", None)
                                load_kwargs.pop("tensor_split", None)
                                load_request = LoadRequest(**load_kwargs)
                                load_request._gguf_companion_roots = gguf_companion_roots
                                load_request._gguf_companion_roots_set = True
                                load_request._override_alias_id = override_id
                                await _switch_load(load_request)
                            _switch_loaded_ok = True
                            # publish the completed load before a late cancellation is observed.
                            target_backend._openai_advertised_id = override_id
                            target_backend._loaded_by_user_action = False
                            _raise_if_generation_cancelled()
                        finally:
                            if not claim_resident:
                                if _switch_loaded_ok or _loaded_slot_ident() == target_id:
                                    _set_preview_resident(_loaded_slot_ident())
                                else:
                                    _set_preview_resident(_switch_prior_marker)
                finally:
                    # Deregister before releasing the gate or another loop's swap counts this as queued.
                    _note_switch_waiter(key, -1)
                    waiter_noted = False
                    _auto_switch_process_lock.release()
        finally:
            if waiter_noted:
                _note_switch_waiter(key, -1)

    from core.inference.gpu_arbiter import MultiModelAlwaysRefusal

    try:
        await _resolve_and_switch()
    except MultiModelAlwaysRefusal as exc:
        raise exc.as_http_exception(
            getattr(getattr(fastapi_request, "url", None), "path", None)
        ) from exc
    except HTTPException as exc:
        path = getattr(getattr(fastapi_request, "url", None), "path", None)
        if (
            path
            and path.startswith("/v1/")
            and isinstance(exc.detail, dict)
            and exc.detail.get("error") == "gpu_busy"
        ):
            raise HTTPException(
                status_code = 409,
                detail = error_body_for_path(
                    path, exc.detail["message"], status = 409, code = "gpu_busy", param = "model"
                ),
                headers = exc.headers,
            ) from exc
        raise
    # The switch may have missed, so refuse rather than answer as whatever is resident.
    await _reject_unservable_model(requested_model, fastapi_request)
    await _refuse_foreign_resident()


async def _auto_switch_from_request_body(
    request: Request,
    current_subject: str,
    *,
    gguf_only: bool = False,
    gguf_only_reason: Optional[str] = None,
    gguf_target_check: Optional[Callable[[], None]] = None,
    audio_cpp_ok: bool = True,
):
    """A malformed body yields no model, so an unloaded backend still 503s rather than 500."""
    try:
        body = await request.json()
    except (json.JSONDecodeError, ValueError):
        return None
    if isinstance(body, dict):
        # A raw-body client may omit ``model`` and rely on the loaded backend. Pass
        # a reload-only sentinel so the idle-stash reload still runs (an idle-freed
        # model is restored) without the resolver ever matching a real name.
        model = body.get("model") or _RELOAD_ONLY_MODEL
    else:
        model = None
    # Serves /v1/completions and /v1/embeddings, which still 503 "No GGUF model loaded"
    # after this returns when nothing loaded can serve them. Don't claim here
    # (claim_resident=False), so that 503 can't strand a preview-owned model as Unsloth-owned.
    await _maybe_auto_switch_model(
        model,
        request,
        current_subject,
        claim_resident = False,
        gguf_only = gguf_only,
        gguf_only_reason = gguf_only_reason,
        gguf_target_check = gguf_target_check,
        audio_cpp_ok = audio_cpp_ok,
    )
    return body


_preview_slot_lock = threading.Lock()
_preview_resident_ident: Optional[str] = None


def _set_preview_resident(ident: Optional[str]) -> None:
    global _preview_resident_ident
    if routed_slot.get() is not None:
        return  # a model kept alongside never takes the preview seat
    with _preview_slot_lock:
        _preview_resident_ident = ident


def _is_preview_resident(ident: str) -> bool:
    with _preview_slot_lock:
        marked = _preview_resident_ident
    return marked is not None and marked.lower() == ident.lower()


def _preview_slot_is_owned() -> bool:
    """True when the resident slot is currently preview-owned, so a non-preview turn
    adopting it would clear that ownership."""
    with _preview_slot_lock:
        return _preview_resident_ident is not None


def _get_preview_resident() -> Optional[str]:
    """The current preview-ownership marker, for callers that must restore it (e.g. a
    preview reload that fails after _load_model_impl already cleared it)."""
    with _preview_slot_lock:
        return _preview_resident_ident


def _same_loaded_identifier(loaded: Optional[str], requested: str) -> bool:
    """Paths compare with normcase (case matters on disk); repo ids compare case-insensitively."""
    if not loaded:
        return False

    # Local = absolute or existing relative path; only repo ids get the lower() compare.
    def _is_local_path(ident: str) -> bool:
        return os.path.isabs(ident) or os.path.exists(ident)

    if _is_local_path(loaded) or _is_local_path(requested):
        return os.path.normcase(loaded) == os.path.normcase(requested)
    return loaded.lower() == requested.lower()


def _should_validate_before_switch() -> bool:
    """Validate first: claiming a preview-owned slot, then rejecting, would strand the next preview."""
    return _automatic_model_load_may_run() or _preview_slot_is_owned()


def _loaded_slot_ident() -> Optional[str]:
    backend = _peek_inference_backend()
    active = getattr(backend, "active_model_name", None) if backend is not None else None
    if active:
        return str(active)
    llama_backend = get_llama_cpp_backend()
    if llama_backend.is_loaded and llama_backend.model_identifier:
        return str(llama_backend.model_identifier)
    npu_model = _resident_npu_model()
    return npu_model.model_path if npu_model is not None else None


def release_chat_gpu_claim() -> bool:
    """Drop the CHAT claim once nothing is resident or loading, else the arbiter hides an empty GPU
    from other accounts. release_if runs under the arbiter lock, so a re-registered load keeps it."""
    from core.inference.gpu_arbiter import CHAT, release_if
    from core.inference.llama_cpp import chat_load_active

    def chat_idle() -> bool:
        if model_slots.busy():
            return False
        llama = get_llama_cpp_backend()
        # is_active, not is_loaded: a starting model holds VRAM, and an HF load has no process yet.
        if llama.is_active or chat_load_active():
            return False
        backend = _peek_inference_backend()
        # A managed engine whose stop failed keeps its VRAM with no model name left.
        if getattr(backend, "_managed_engine", None) is not None:
            return False
        return not getattr(backend, "active_model_name", None) and not tuple(
            getattr(backend, "loading_models", ()) or ()
        )

    return model_slots.in_slot(None, lambda: release_if(CHAT, chat_idle))


def _release_chat_for_zero_vram_primary() -> None:
    """A primary that holds no VRAM drops CHAT, unless a model kept alongside still holds it."""
    from core.inference.gpu_arbiter import CHAT, release, release_if

    if not model_slots.slots and not model_slots.stuck and model_slots.loading is None:
        release(CHAT)
        return
    release_if(CHAT, lambda: not model_slots.holds_vram())


def release_chat_after_kept_models() -> bool:
    """Once kept models are gone, drop CHAT if nothing is left or only a primary that holds no VRAM."""
    from core.inference.gpu_arbiter import CHAT, release_if
    from core.inference.llama_cpp import chat_load_active

    if release_chat_gpu_claim():
        return True

    def zero_vram_primary_only() -> bool:
        llama = get_llama_cpp_backend()
        return (
            not model_slots.holds_vram()
            and llama.is_loaded
            and llama.holds_no_vram
            and not chat_load_active()
        )

    return model_slots.in_slot(None, lambda: release_if(CHAT, zero_vram_primary_only))


def release_chat_after_cpu_fallback(backend, identifier) -> bool:
    """A primary whose GPU start fell back to the CPU drops CHAT, unless something else still holds VRAM."""
    from core.inference.gpu_arbiter import CHAT, release_if

    def only_cpu_left() -> bool:
        if getattr(backend, "active_model_name", None) != identifier:
            return False
        entry = (getattr(backend, "models", None) or {}).get(identifier)
        if not isinstance(entry, dict) or entry.get("audio_device_fallback") != "cpu":
            return False
        llama = get_llama_cpp_backend()
        return not model_slots.holds_vram() and (not llama.is_active or llama.holds_no_vram)

    return model_slots.in_slot(None, lambda: release_if(CHAT, only_cpu_left))


# True while load_model_gated can free memory and retry, so only there does a primary refuse a partial GPU fit.
_primary_can_retry_fit: contextvars.ContextVar[bool] = contextvars.ContextVar(
    "primary_can_retry_fit", default = False
)


def _placement_gpu_ids(placement) -> Optional[list[int]]:
    # Only GGUF and native audio resolve their GPUs; any other chat load keeps the ids it asked for.
    if placement.resolved_gpu_ids is not None:
        return placement.resolved_gpu_ids
    return placement.requested_gpu_ids


def _media_on_target_gpus(placement) -> bool:
    """Whether an image or video model kept loaded beside chat holds memory on the GPUs this load targets."""
    from core.inference.gpu_residency import media_held_mib

    held = media_held_mib()
    gpus = None if placement.gpu_ids_are_vulkan_ordinals else _placement_gpu_ids(placement)
    return bool(held) and (not gpus or bool(set(held) & set(gpus)))


def _idle_kept_chat_on_target_gpus(placement) -> bool:
    gpus = None if placement.gpu_ids_are_vulkan_ordinals else _placement_gpu_ids(placement)
    return bool(model_slots.eviction_victims(None, 0, set(gpus) if gpus else None, discrete = True))


def _primary_refuses_partial_fit(serving: bool, policy: str, placement) -> bool:
    """Whether a primary GGUF load refuses a partial fit so room can be made first. Not under Always while a primary
    serves: the refusal lands after its teardown, leaving nothing loaded."""
    return (
        _primary_can_retry_fit.get()
        and not (serving and policy == "always")
        and (
            _media_on_target_gpus(placement)
            or (policy == "fit" and _idle_kept_chat_on_target_gpus(placement))
        )
    )


def _visible_ordinals(physical_ids) -> Optional[list[int]]:
    """Visible device ordinals for physical GPU ids, or None when one isn't visible (then every GPU counts)."""
    try:
        from utils.hardware.hardware import get_parent_visible_gpu_ids
        parent = list(get_parent_visible_gpu_ids() or ())
    except Exception:  # noqa: BLE001
        return None
    if not parent:
        return [int(g) for g in physical_ids]
    if any(int(g) not in parent for g in physical_ids):
        return None
    return [parent.index(int(g)) for g in physical_ids]


def _chat_fit_kwargs(
    config,
    placement,
    policy: Optional[str] = None,
    credit_gb: Optional[dict] = None,
    mlx_need_mib: Optional[int] = None,
    mlx_credit_mib: int = 0,
) -> dict:
    """How the CHAT acquire shares the GPU under When they fit / Always.

    audio.cpp and native audio are priced from the placement estimate, an MLX load on Apple Silicon from
    ``mlx_need_mib``. A GGUF launch prices itself (it refuses a partial fit and load_model_gated makes room).
    Anything else has no estimate before launch: When they fit evicts first, Always tries the load and turns an
    out-of-memory failure into its refusal. ``credit_gb`` is what the outgoing primary frees per GPU when this
    load replaces it.
    """
    if policy is None:
        from core.inference.gpu_residency import current_policy
        policy = current_policy()
    if policy == "off":
        return {}
    kwargs: dict = {"policy": policy}
    gpus = _placement_gpu_ids(placement)
    ordinals = (
        _visible_ordinals(gpus) if gpus and not placement.gpu_ids_are_vulkan_ordinals else None
    )
    if ordinals is not None:
        # Only residents on these GPUs are weighed or unloaded; the arbiter maps them back to physical ids.
        kwargs["gpu_ids"] = ordinals
    if placement.native_required_gb and gpus and not placement.gpu_ids_are_vulkan_ordinals:
        credit = credit_gb or {}
        # Net of the outgoing primary, so it may be negative: a smaller replacement needs no extra room.
        kwargs["need_mib"] = {
            int(g): int((placement.native_required_gb / len(gpus) - credit.get(int(g), 0.0)) * 1024)
            for g in gpus
        }
    elif mlx_need_mib is not None:
        from core.inference.gpu_residency import ChatNeed
        kwargs["need_mib"] = ChatNeed({0: int(mlx_need_mib)}, credit_mib = mlx_credit_mib)
    elif not (config.is_gguf and _primary_can_retry_fit.get()) and (
        policy == "fit" or (not config.is_gguf and _unified_metal_host())
    ):
        # Unified memory pages past the budget: Always gets no OOM to refuse on.
        kwargs["evict_first"] = True
    return kwargs


def _unified_metal_host() -> bool:
    from core.inference.gpu_residency import _on_metal
    return _on_metal()


def _mlx_cache_bounded(entry: dict, slots: int = 1) -> bool:
    from core.inference.gpu_residency import mlx_cache_bounded
    return mlx_cache_bounded(entry, slots)


def _note_mlx_slots(backend, slots: int) -> None:
    """A batch opened at a wider setting keeps its width after the setting drops, so the reservation never shrinks."""
    entry = backend.models.get(backend.active_model_name or "") or {}
    growth = entry.get("mlx_growth")
    if isinstance(growth, dict):
        growth["slots"] = max(int(growth.get("slots", 1)), int(slots))
        if not _mlx_cache_bounded(entry, growth["slots"]):
            entry.pop("mlx_growth")


def _mlx_slots_outgrow_price(backend, n_parallel) -> bool:
    from core.inference.gpu_residency import mlx_slots_outgrow_price
    return mlx_slots_outgrow_price(backend, n_parallel)


def _outgoing_chat_credit_gb(
    placement, policy: str, replacing: bool, availability: "Optional[_NativeAudioAvailability]"
) -> tuple[Optional[dict], Optional[dict]]:
    """VRAM the primary chat model frees per GPU when a priced native load replaces it beside an image or video model.

    Returns (credit, wait): the CHAT acquire charges the new load less the credit, and the load waits for ``wait`` GB
    to be free after the teardown. (None, None) when nothing is credited.
    """
    if not (
        replacing
        and policy != "off"
        and placement.native_required_gb
        and placement.resolved_gpu_ids
        and _media_on_target_gpus(placement)
    ):
        return None, None
    from core.inference.gpu_arbiter import CHAT

    if availability is not None and availability.credited == CHAT:
        # The automatic placement already measured the outgoing chat model and waits for it.
        return availability.reclaimable_gpu_gb, None
    chat = _native_audio_post_handoff_free_gb(CHAT)
    if chat is None:
        return None, None
    target = list(placement.resolved_gpu_ids)
    share = float(placement.native_required_gb) / len(target)
    return chat.reclaimable_gpu_gb, {int(g): share for g in target}


async def _make_room_for_primary(request: LoadRequest, exc, evicted: list) -> LoadRequest:
    """A primary chat load refused a partial GPU fit beside other models: return the request to retry.

    When they fit frees the cheapest residents, else lets llama-server fit what it can. Always only accepts a
    smaller context or a host RAM spill, else refuses.
    """
    from core.inference import gpu_arbiter, gpu_residency

    policy = await asyncio.to_thread(gpu_residency.current_policy)
    if exc.capped or (policy == "always" and getattr(exc, "host", False)):
        return request.model_copy(update = {"force_alongside": True})
    if policy == "always":
        rows = (await asyncio.to_thread(gpu_residency._free_mib_by_gpu))[0] or {}
        gpus = [g for g in exc.gpu_indices or () if "free_mib" in rows.get(g, {})]
        free = sum(rows[g]["free_mib"] for g in gpus)
        info = {
            "need_mib": {0: free + exc.short_mib},
            "free_mib": {0: free},
            "short_mib": {0: exc.short_mib},
        }
        held, short = gpu_arbiter.residents(), set(exc.gpu_indices or ())
        # Name only models that could be in the way: skip one known to sit on other GPUs.
        slots = [
            s
            for o in gpu_residency.MEDIA_OWNERS
            if not (short and held.get(o) and not held[o] & short)
            for s in gpu_arbiter.resident_slots(o)
        ]
        raise gpu_residency.need_free_refusal(info if gpus else {}, slots)
    freed = await _free_for_chat(exc, evicted)
    # Anything freed (an idle video server counts) earns a retry at full size; else llama-server fits what it can.
    return request if freed else request.model_copy(update = {"force_alongside": True})


async def _free_for_chat(
    exc,
    evicted: list,
    media_only: bool = False,
) -> list[str]:
    """Free the cheapest residents on the GPUs a chat load came up short on; ``media_only`` keeps every chat model."""
    from core.inference import gpu_arbiter, gpu_residency

    # The route's eviction sink when it keeps one (it reports the slots itself), else the plain list.
    sink = gpu_arbiter.eviction_sink.get()
    slots: list = sink if sink is not None else []
    before = len(slots)
    freed = await asyncio.to_thread(
        gpu_residency.free_for,
        gpu_arbiter.CHAT,
        exc.gpu_indices,
        "a chat model",
        slots,
        short_mib = exc.short_mib,
        media_only = media_only,
    )
    if sink is None:
        evicted += [s["model"] for s in slots[before:] if s.get("model")]
    return freed


def reap_dead_managed_engine(backend) -> None:
    """A crashed engine leaves nothing resident, so its claim and sharers go with it."""
    from core.inference.gpu_arbiter import CHAT, holds
    if backend.reap_dead_managed_engine() and (release_chat_gpu_claim() or not holds(CHAT)):
        account_access.clear_resident("chat")


def _orchestrator_occupied(orchestrator) -> bool:
    """A standard, MLX or managed-engine model held or loading, as release_chat_gpu_claim counts it."""
    if orchestrator is None:
        return False
    return bool(
        getattr(orchestrator, "_managed_engine", None) is not None
        or getattr(orchestrator, "active_model_name", None)
        or tuple(getattr(orchestrator, "loading_models", ()) or ())
    )


def _primary_seat_occupied() -> bool:
    """A non-GGUF model holds or is loading into the primary seat (call in the primary's slot)."""
    return _orchestrator_occupied(_peek_inference_backend()) or _resident_npu_model() is not None


def _release_after_terminal_retirement(backend, epoch) -> None:
    """A llama-server stopped for good by a second Metal out-of-memory strike unloads itself
    (llama_cpp._retire_device_lost_server); finish it as a manual unload would. A kept slot is
    dropped at once (dead, it holds nothing a request could still use, so its refs do not keep
    it) and leaves the primary's residency alone; the primary clears its own sharers. CHAT goes
    once nothing else holds it. A reload that landed since the strike owns the slot and the
    residency now, so nothing is touched then (checked under the lock every load takes).
    A non-GGUF model holding or loading into the seat (primary or kept slot) owns it too."""
    primary = backend is _llama_cpp_backend
    with backend._while_still_retired(epoch) as retired:
        filling = model_slots.loading[0] if model_slots.loading else None
        if not retired or (filling is not None and filling.llama is backend):
            return
        for slot in [
            s
            for s in list(model_slots.slots)
            if s.llama is backend and not _orchestrator_occupied(s.orchestrator)
        ]:
            try:
                model_slots.drop(slot)
            except Exception as exc:  # noqa: BLE001 -- drop() keeps a stuck slot for retry
                logger.warning("Could not drop a kept model after its Metal out-of-memory: %s", exc)
        if primary and not model_slots.in_slot(None, _primary_seat_occupied):
            account_access.clear_resident("chat")
    # The arbiter lock comes before the backend's: released outside it, and release_if
    # re-checks that nothing is resident.
    if primary:
        release_chat_gpu_claim()
    else:
        release_chat_after_kept_models()


_TERMINAL_RETIREMENT_HOOKS.append(_release_after_terminal_retirement)


def reap_dead_worker(backend) -> None:
    """Cleared, never respawned: every routed request runs this, so an OOM respawn would loop."""
    from core.inference.gpu_arbiter import CHAT, holds

    if getattr(backend, "_proc", None) is None:
        return
    if backend.reap_dead_worker() and (release_chat_after_kept_models() or not holds(CHAT)):
        account_access.clear_resident("chat")


def _preview_same_checkpoint(loaded: str, requested: str) -> bool:
    """Falls back to resolved paths so an equivalent spelling matches; case is never folded."""
    if loaded == requested:
        return True
    try:
        return Path(loaded).resolve() == Path(requested).resolve()
    except OSError:
        return False


def _claim_slot_for_non_preview(fastapi_request) -> None:
    """Non-preview use clears the preview marker so a later preview cannot swap out an active turn; /p requests keep it, decided by path not handler."""
    from core.inference.llama_keepwarm import _is_preview_path

    scope = getattr(fastapi_request, "scope", None)
    path = scope.get("path") if isinstance(scope, dict) else None
    if _is_preview_path(path or ""):
        return
    _set_preview_resident(None)


async def load_model_for_preview(
    request: LoadRequest, fastapi_request: Request, current_subject: str
) -> None:
    if account_access.managed_account():
        await asyncio.to_thread(account_access.require_model_access, request.model_path)
    await _require_drafter_access(request)
    account_access.require_idle_other_accounts()
    from core.inference.llama_keepwarm import (
        inference_lifecycle_gate,
        model_load_gate,
        note_preview_swap,
        note_preview_swap_begin,
        note_preview_swap_end,
        other_admitted_inference_count,
        untrack_current_request,
    )
    from utils.transformers_version import sidecar_swap_in_progress

    # A refused preview must not stamp keep-warm activity, or public /p spam could pin an idle model in VRAM; untrack balances the counter.
    scope = getattr(fastapi_request, "scope", None)
    async with _auto_switch_lock():
        await _acquire_swap_gate()
        _swap_begun = False
        try:
            async with model_load_gate(), inference_lifecycle_gate():
                # Preview loads bypass load_model(), so re-apply its sidecar install guard: a load must not finish mid-install or the installer later aborts.
                if sidecar_swap_in_progress():
                    untrack_current_request(scope)
                    raise HTTPException(
                        status_code = 409,
                        detail = "A transformers installation is in progress. Retry when it completes.",
                        headers = {"Retry-After": "10"},
                    )
                # Else a dead worker's name refuses every preview as Studio-owned.
                await _reap_exited_workers()
                loaded = _loaded_slot_ident()
                # Match equivalent spellings via realpath; never lowercase distinct paths.
                same_target = loaded is not None and _preview_same_checkpoint(
                    loaded, request.model_path
                )

                def _refuse_studio_owned_model() -> None:
                    if loaded is None or _is_preview_resident(loaded):
                        return
                    # Borrowing an Unsloth-owned LoRA would mutate shared adapter state.
                    if (
                        same_target
                        and not (Path(request.model_path) / "adapter_config.json").is_file()
                    ):
                        return
                    untrack_current_request(scope)
                    raise HTTPException(
                        status_code = 503,
                        detail = "Unsloth already has a different model loaded. Unload it before using this preview.",
                        headers = {"Retry-After": "10"},
                    )

                _refuse_studio_owned_model()
                # Mark the swap BEFORE the admitted-count check so the two are atomic.
                # Skip for a same-target borrow, which changes nothing.
                if not same_target:
                    note_preview_swap_begin()
                    _swap_begun = True
                # Count only admitted (post-auth) inference, or pre-auth requests would starve previews.
                if other_admitted_inference_count() > 0:
                    untrack_current_request(scope)
                    raise HTTPException(
                        status_code = 503,
                        detail = "The preview model is busy. Please try again shortly.",
                        headers = {"Retry-After": "10"},
                    )
                # recheck after the admitted count because another loop may have claimed the slot.
                _refuse_studio_owned_model()
                if same_target:
                    # Borrow as-is: reloading with bare preview settings would restart an idle GGUF. Ownership is unchanged: Unsloth stays Unsloth, preview stays preview.
                    return
                # Refuse if Images/Video own the GPU: they bypass the admitted-count guard, and the load would evict their in-flight generation.
                from core.inference.gpu_arbiter import (
                    DIFFUSION,
                    VIDEO,
                    GpuOwnerBusyError,
                    MultiModelAlwaysRefusal,
                    holds,
                )

                if holds(DIFFUSION) or holds(VIDEO):
                    untrack_current_request(scope)
                    raise HTTPException(
                        status_code = 503,
                        detail = (
                            "Unsloth is using the GPU for image or video generation. "
                            "Unload that model before using this preview."
                        ),
                        headers = {"Retry-After": "10"},
                    )
                # Restore the prior preview owner if the load fails: a stale marker would make the next preview see this model as Unsloth-owned and 503.
                prior_marker = _get_preview_resident()
                loaded_ok = False
                try:
                    await _load_model_impl(
                        request,
                        fastapi_request,
                        current_subject,
                        # The preview is itself in-flight; exclude it or the drain waits on itself.
                        current_request_counted = True,
                        # Never forced: a public preview must refuse rather than stop Unsloth chats.
                        on_reload_confirmed = lambda *, cancel: _raise_or_cancel_active_generations(
                            force = False,
                            action = "Loading a model",
                            cancel = cancel,
                        ),
                        allow_gpu_owner_eviction = False,
                    )
                    loaded_ok = True
                except (GpuOwnerBusyError, MultiModelAlwaysRefusal) as exc:
                    untrack_current_request(scope)
                    raise HTTPException(
                        status_code = 503,
                        detail = (
                            "Unsloth is using the GPU for image or video generation. "
                            "Unload that model before using this preview."
                        ),
                        headers = {"Retry-After": "10"},
                    ) from exc
                finally:
                    resident_after = _loaded_slot_ident()
                    # Ownership follows what is resident: the load may succeed then raise.
                    if loaded_ok or resident_after == request.model_path:
                        _set_preview_resident(request.model_path)
                    else:
                        _set_preview_resident(prior_marker)
                    # A failed atomic GPU acquisition changes no chat model state. Only
                    # publish a swap when a load succeeded or the resident identifier
                    # actually changed during a partial failure.
                    if loaded_ok or resident_after != loaded:
                        note_preview_swap()
        finally:
            # Cleared only after the lifecycle gate is released, so window arrivals are rejected.
            if _swap_begun:
                note_preview_swap_end()
            _auto_switch_process_lock.release()


def _effective_load_in_4bit(config: ModelConfig, requested: bool) -> bool:
    """Effective quantization the loader will use: a LoRA adapter can flip 4-bit to
    16-bit via adapter_config.json, so the guard sizes this, not the raw request."""
    from core.inference.native_audio import NATIVE_AUDIO_TYPES

    if getattr(config, "audio_type", None) in NATIVE_AUDIO_TYPES:
        return False
    load_in_4bit = requested
    if not getattr(config, "is_lora", False) and is_full_finetune_output(
        getattr(config, "path", None)
    ):
        return False
    if not getattr(config, "is_lora", False) or not getattr(config, "path", None):
        return load_in_4bit
    adapter_cfg_path = Path(config.path) / "adapter_config.json"
    if not adapter_cfg_path.exists():
        return load_in_4bit
    try:
        with open(adapter_cfg_path, encoding = "utf-8-sig") as f:
            adapter_cfg = json.load(f)
        if not isinstance(adapter_cfg, dict):  # malformed -> keep requested
            return load_in_4bit
    except Exception as e:
        logger.warning(f"Could not read adapter_config.json: {e}")
        return load_in_4bit
    trained_in_4bit = adapter_cfg.get("unsloth_load_in_4bit")
    if isinstance(trained_in_4bit, bool):
        return trained_in_4bit
    training_method = adapter_cfg.get("unsloth_training_method")
    if training_method == "lora":
        return False
    if training_method == "qlora":
        return True
    if not training_method and config.base_model and "-bnb-4bit" not in config.base_model.lower():
        return False
    return load_in_4bit


def _projector_survives_vision_off(mmproj_path: str) -> bool:
    """Whether the Vision switch leaves *mmproj_path* loaded (audio-only projectors
    stay). Unreadable reads as image-capable, hence suppressed, matching the loader."""
    try:
        from utils.models.gguf_metadata import mmproj_accepts_image
        return not mmproj_accepts_image(str(mmproj_path))
    except Exception as exc:
        logger.debug(f"mmproj capability read failed: {exc}")
        return False


def _load_keeps_a_projector(config, *, disable_vision: bool) -> bool:
    """Projector not on disk yet counts as kept: over-claiming is recoverable, under-claiming is not."""
    if not getattr(config, "is_vision", False):
        return False
    if not disable_vision:
        return True
    mmproj = getattr(config, "gguf_mmproj_file", None) or getattr(
        config, "gguf_local_mmproj_file", None
    )
    return True if not mmproj else _projector_survives_vision_off(str(mmproj))


def _remote_gguf_companion_bytes(
    repo: str,
    *,
    hf_token: Optional[str],
    include_mmproj: bool,
    include_mtp: bool = True,
    include_dspark: bool = False,
    include_dflash: bool = False,
    dspark_first: bool = False,
    weight_bytes: int = 0,
    local_mmproj_bytes: int = 0,
) -> int:
    """Charges one drafter in promotion order (DSpark, DFlash, MTP): the loader launches only one."""
    try:
        from core.inference.llama_cpp import (
            _gguf_extra_shards,
            _is_dspark_drafter_path,
            _is_root_dflash_drafter_path,
        )
        from huggingface_hub import model_info
        from utils.models.drafters import dflash_budget_bytes, split_listing_is_complete
        from utils.models.model_config import dspark_preference_key

        # A refused token must not zero the companion bytes and slip past the training budget.
        info = call_hub_with_anonymous_retry(model_info, hf_token, repo, files_metadata = True)
        listed_mmproj_bytes = 0
        mtp_bytes = 0
        dspark_candidates: list[tuple[str, int]] = []
        dflash_sizes: dict[str, int] = {}
        from hub.utils.gguf import drop_shadowed_appledouble_siblings

        # Same listing the downloader uses, so a sidecar cannot outrank the real drafter.
        for sibling in drop_shadowed_appledouble_siblings(list(info.siblings or [])):
            name = sibling.rfilename or ""
            base = Path(name).name.lower()
            if not base.endswith(".gguf"):
                continue
            size = getattr(sibling, "size", 0) or 0
            # Root-level mtp- only: -hf auto-fetches the root drafter, not MTP/ subdir copies.
            is_root_mtp = "/" not in name and base.startswith("mtp-")
            if include_mtp and is_root_mtp:
                mtp_bytes += size
            elif include_mmproj and "mmproj" in base:
                listed_mmproj_bytes += size
            if include_dspark and _is_dspark_drafter_path(name):
                dspark_candidates.append((name, size))
            # Root level only, matching _download_dflash's picker.
            if include_dflash and _is_root_dflash_drafter_path(name):
                dflash_sizes[name] = size
        # Price whole shard sets (llama-server maps every shard); drop incomplete sets.
        _dspark_sizes = dict(dspark_candidates)
        dspark_families = [
            (
                name,
                size
                + sum(_dspark_sizes.get(s, 0) for s in _gguf_extra_shards(_dspark_sizes, name)),
            )
            for name, size in dspark_candidates
            if split_listing_is_complete(_dspark_sizes, name)
        ]
        dspark_bytes = (
            min(dspark_families, key = lambda c: dspark_preference_key(c[0]))[1]
            if dspark_families
            else 0
        )
        # Max over whole shard sets, capped by target, so drafters the fetch refuses are not charged.
        dflash_bytes = dflash_budget_bytes(dflash_sizes, _gguf_extra_shards, weight_bytes)
        # Alternatives, never both: the fetch uses the local one only when none is listed.
        total = max(int(local_mmproj_bytes), listed_mmproj_bytes)
        if not dspark_first:
            return total + mtp_bytes + dspark_bytes + dflash_bytes
        if dspark_families:
            # A complete DSpark set wins Auto promotion, so DFlash/MTP are not charged.
            return total + dspark_bytes
        if dflash_sizes:
            # DFlash replaces MTP when accepted, but may be rejected; charge the larger.
            return total + max(dflash_bytes, mtp_bytes)
        return total + mtp_bytes
    except Exception as e:
        logger.warning(f"Could not size GGUF companions for {repo}: {e}")
        return int(local_mmproj_bytes)


# Unreadable remote drafter: sized to the largest known class (DSpark ~11 GB);
# over-estimating is this guard's safe direction.
_REMOTE_DRAFTER_RESERVE_BYTES = 12 * 1024**3


def _split_hf_draft_spec(spec: str) -> tuple[Optional[str], str]:
    """Splits user/model:quant, also reading the repo from a trailing /file.gguf that llama.cpp rejects."""
    repo, sep, tag = (spec or "").strip().partition(":")
    parts = [p for p in repo.split("/") if p]
    hint = tag.strip().lower() if sep else ""
    if len(parts) > 2 and parts[-1].lower().endswith(".gguf"):
        hint = parts[-1].lower()
        parts = parts[:2]
    if len(parts) != 2:
        return None, ""
    return "/".join(parts), hint


def _remote_drafter_repo_bytes(spec: str, *, hf_token: Optional[str]) -> int:
    """Largest whole shard set; a failed listing charges the flat reserve, never zero."""
    repo, hint = _split_hf_draft_spec(spec)
    if not repo:
        return _REMOTE_DRAFTER_RESERVE_BYTES
    try:
        from core.inference.llama_cpp import _gguf_extra_shards
        from huggingface_hub import model_info
        from utils.models.drafters import dflash_budget_bytes, split_listing_is_complete

        from hub.utils.gguf import drop_shadowed_appledouble_siblings
        from hub.utils.hf_tokens import call_hub_with_anonymous_retry

        info = call_hub_with_anonymous_retry(model_info, hf_token, repo, files_metadata = True)
        sizes: dict[str, int] = {}
        # A sidecar's few KB is not the drafter the launch fetches; this figure gates loads beside training.
        for sibling in drop_shadowed_appledouble_siblings(list(info.siblings or [])):
            name = sibling.rfilename or ""
            if not Path(name).name.lower().endswith(".gguf"):
                continue
            sizes[name] = getattr(sibling, "size", 0) or 0
        if hint:
            # Mirror llama.cpp's quant-tag narrowing on the full relative name; a tag matching
            # nothing returns every candidate (repos label quants inconsistently).
            matched = {n: s for n, s in sizes.items() if hint in n.lower()}
            sizes = matched or sizes
        # require_full_sizes: a partial sum undercounts, so cache measurement or the reserve wins instead.
        bounded = dflash_budget_bytes(sizes, _gguf_extra_shards, require_full_sizes = True)
        if bounded:
            return bounded
        # Zero from a GGUF listing is right only if every family is an incomplete split.
        if sizes and not any(split_listing_is_complete(sizes, name) for name in sizes):
            return 0
    except Exception as e:
        logger.warning(f"Could not size remote drafter repo {spec}: {e}")
    # Unreadable listing is usually a locally cached repo; measure it, the flat reserve undercounts.
    cached = _cached_repo_gguf_bytes(repo, hint)
    if cached:
        return cached
    # Not listable or cached: llama-server would fetch it, so the reserve is a cushion, not a bound.
    return _REMOTE_DRAFTER_RESERVE_BYTES


def _cached_repo_gguf_bytes(repo: str, hint: str = "") -> int:
    """Largest cached shard set, narrowed by the quant hint so a multi-quant repo isn't charged its F16."""
    try:
        from huggingface_hub import scan_cache_dir

        from core.inference.llama_cpp import _gguf_extra_shards
        from utils.models.drafters import dflash_budget_bytes

        # Use the current cache dir, not the one huggingface_hub resolved at import.
        try:
            from utils.hf_cache_settings import active_hf_hub_cache
            _cache_dir: Optional[str] = active_hf_hub_cache()
        except Exception:
            _cache_dir = None

        sizes: dict[str, int] = {}
        for cached_repo in scan_cache_dir(cache_dir = _cache_dir).repos:
            if (cached_repo.repo_id or "").lower() != repo.lower():
                continue
            # One revision only (the ref, else newest): merging stale snapshots over-charges.
            revisions = list(cached_repo.revisions)
            chosen = next(
                (
                    r
                    for r in revisions
                    if "main" in {str(x) for x in (getattr(r, "refs", None) or ())}
                ),
                None,
            ) or max(revisions, key = lambda r: getattr(r, "last_modified", 0) or 0, default = None)
            from hub.services.models.cache_inventory import cached_repo_files

            # Quant subdirectories share a basename, so the largest file carrying one is charged.
            for f in cached_repo_files(chosen):
                name = str(f.file_name)
                if name.lower().endswith(".gguf"):
                    sizes[name] = max(sizes.get(name, 0), int(f.size_on_disk or 0))
        if hint:
            sizes = {n: b for n, b in sizes.items() if hint in n.lower()} or sizes
        return dflash_budget_bytes(sizes, _gguf_extra_shards)
    except Exception as e:
        logger.warning(f"Could not measure the cached drafter repo {repo}: {e}")
        return 0


# Modes where _build_speculative_flags returns before emitting --model-draft.
_SPEC_MODES_WITHOUT_A_DRAFTER = frozenset({"off", "ngram", "ngram-simple"})


class _GgufRuntimeBytes(NamedTuple):
    """The context-dependent half of a GGUF's footprint, itemized.

    ``_estimate_gguf_kv_gb`` sums this into the single number the training guard
    needs; the Load-Model estimate shows the items separately.
    """

    kv_bytes: int
    compute_bytes: int
    # False when header lacks dims: kv_bytes is 'unknown', not 'none'; the UI must tell them apart.
    kv_estimable: bool
    # What was actually priced, after the ctx override and the slot/cache clamps.
    n_ctx: int
    cache_type_kv: Optional[str]
    n_parallel: int
    # GGUF block_count, carried out of the header walk this already paid for.
    layer_count: Optional[int] = None
    # Cache layout used for pricing, so a drafter's cache is sized the same way.
    swa_full: bool = False
    kv_unified: bool = True
    n_ubatch: Optional[int] = None
    # Host-heap checkpoint share of kv_bytes (bounded by --cache-ram); never reaches the GPU.
    kv_checkpoint_bytes: int = 0


_GGUF_RUNTIME_UNKNOWN = _GgufRuntimeBytes(0, 0, False, 0, None, 1)


def _inherited_ctx_size() -> int:
    """Positive LLAMA_ARG_CTX_SIZE is kept by the launch, so the estimate uses it, not native length."""
    raw = (os.environ.get("LLAMA_ARG_CTX_SIZE") or "").strip()
    if not raw:
        return 0
    try:
        return max(0, int(raw))
    except ValueError:
        return 0


class _EstimateContextFloor(NamedTuple):
    """Minimum Auto context and whether GPU layers can move to the CPU."""

    ctx: int
    can_offload: bool


def _estimate_context_floor(
    n_ctx: Optional[int],
    llama_extra_args: Optional[list[str]],
    gpu_memory_mode: Optional[str],
    gpu_layers: Optional[int],
    breakdown: Any,
) -> Optional[_EstimateContextFloor]:
    """Returns None for a pinned context; manual with Auto layers floors at --fit-ctx."""
    from core.inference.llama_cpp import (
        _FIT_FLOOR_MIN_CTX,
        _FIT_MIN_CTX,
        _LLAMA_FIT_MIN_CTX,
        LlamaCppBackend,
        _env_asks_for_the_native_context,
        _env_fixes_gpu_layers,
    )
    from core.inference.llama_server_args import (
        _GPU_LAYER_FLAGS,
        _last_flag_value,
        fit_ctx_in,
        fit_is_effectively_on,
        parse_ctx_override,
        parse_gpu_layers_override,
    )
    from utils.hardware import is_apple_silicon

    if (n_ctx or 0) > 0 or not breakdown.kv_on_gpu or not breakdown.kv_estimable:
        return None
    extras = list(llama_extra_args or [])
    try:
        # Keep -c 0 pinned even on Metal: checking its fit budget would require MLX.
        if parse_ctx_override(extras) is not None:
            return None
        # The last -ngl wins. llama.cpp also takes "auto" and "all" here.
        layer_arg = _last_flag_value(extras, _GPU_LAYER_FLAGS)
    except ValueError:
        return None
    if _inherited_ctx_size() > 0:
        return None
    if gpu_memory_mode != "manual":
        # The launch's own --fit on precedes the extras, so only they can turn it off.
        try:
            fitter_runs = fit_is_effectively_on(["--fit", "on", *extras], os.environ)
        except ValueError:
            return None
        # Arguments beat the environment; only auto/-1 let the fitter move layers.
        layers_fixed = _env_fixes_gpu_layers(
            os.environ if layer_arg is None else {"LLAMA_ARG_N_GPU_LAYERS": layer_arg}
        )
        floor_ctx = _FIT_FLOOR_MIN_CTX if is_apple_silicon() else _FIT_MIN_CTX
        return _EstimateContextFloor(floor_ctx, fitter_runs and not layers_fixed)
    # Manual /load folds -ngl into gpu_layers and strips --fit.
    try:
        layer_override = parse_gpu_layers_override(extras)
    except ValueError:
        return None
    if layer_override is not None:
        gpu_layers = layer_override
    if gpu_layers is not None and gpu_layers >= 0:
        return None
    # Manual clears inherited fit/layer settings: argv, then launcher's 8192, then llama.cpp's 4096.
    try:
        fit_ctx = fit_ctx_in(extras)
    except ValueError:
        return None
    if fit_ctx is None and LlamaCppBackend.probe_server_capabilities().get("supports_fit_ctx"):
        fit_ctx = _FIT_MIN_CTX
    if fit_ctx is None:
        # Without --fit-ctx, an inherited zero keeps native context.
        if _env_asks_for_the_native_context():
            return None
        fit_ctx = _LLAMA_FIT_MIN_CTX
    # Negative wraps unsigned; zero resolves to native context. Neither shrinks.
    if fit_ctx <= 0:
        return None
    return _EstimateContextFloor(fit_ctx, True)


def _launch_required_ubatch_for_config(
    config,
    llama_extra_args: Optional[list[str]] = None,
    disable_vision: bool = False,
) -> int:
    """Return the required micro-batch for a local GGUF config."""
    from core.inference.llama_cpp import _launch_required_ubatch
    from utils.models.gguf_metadata import read_gguf_embedding_length

    gguf_file = str(getattr(config, "gguf_file", "") or "")
    own = getattr(config, "gguf_mmproj_file", None)
    resolved = None
    if own and getattr(config, "is_vision", False) and not disable_vision:
        resolved = _probe_backend()._resolve_launch_mmproj_path(
            model_path = gguf_file,
            mmproj_path = str(own),
        )
    return _launch_required_ubatch(
        resolved,
        # The text embedding size identifies the causal Gemma 4 variants.
        read_gguf_embedding_length(gguf_file) if gguf_file else None,
        llama_extra_args,
        is_vision = bool(getattr(config, "is_vision", False)),
        vision_off = disable_vision,
    )


def _remote_required_ubatch(
    config,
    llama_extra_args: Optional[list[str]] = None,
    disable_vision: bool = False,
) -> int:
    """Return a conservative micro-batch for an undownloaded GGUF config."""
    from core.inference.llama_cpp import _launch_required_ubatch, extra_args_disable_mmproj

    from core.inference.llama_cpp import _extra_args_device, _unknown_projector_ubatch

    # A local --mmproj replaces the repo projector, so size from that file instead.
    if (
        bool(getattr(config, "is_vision", False))
        and not disable_vision
        and not extra_args_disable_mmproj(llama_extra_args)
        and _extra_args_device(llama_extra_args, {"--mmproj", "-mm"}) is None
    ):
        # Match the worst-case post-download allocation.
        return _unknown_projector_ubatch(llama_extra_args)
    # No repo projector in play, but the extras or the environment may still name one.
    return _launch_required_ubatch(
        None,
        None,
        llama_extra_args,
        is_vision = False,
        vision_off = disable_vision,
    )


def _gguf_runtime_bytes(
    gguf_path: str,
    max_seq_length: int,
    llama_extra_args: Optional[list[str]] = None,
    n_parallel: int = 1,
    cache_type_kv: Optional[str] = None,
    tensor_parallel: bool = False,
    n_batch: Optional[int] = None,
    n_ubatch: Optional[int] = None,
    ctx_checkpoints: Optional[int] = None,
    n_devices: int = 1,
    is_diffusion: bool = False,
    ctx_last_wins: bool = False,
    model_identifier: Optional[str] = None,
    launch_required_ubatch: int = 0,
    # True also reserves for a flash-attention-off respawn the fitter cannot re-place (guard use).
    reserve_no_flash_respawn: bool = False,
) -> _GgufRuntimeBytes:
    """Max of max_seq_length and -c; 0 if metadata unreadable; diffusion skips compute. ctx_last_wins uses the -c the launch runs, not the over-reserving guard rule"""
    try:
        from core.inference.llama_cpp import (
            _ASSUMED_MAX_VOCAB,
            _batch_ubatch_for_mmproj,
            _embedding_batch_ubatch,
        )
        from core.inference.llama_cpp import effective_ctx_checkpoints_for_caps
        from core.inference.llama_server_args import (
            parse_ctx_override,
            resolve_requested_ctx,
        )

        probe = _probe_backend()
        probe._model_identifier = model_identifier
        probe._read_gguf_metadata(gguf_path)
        # Older llama.cpp reserves an output row per micro-batch token. getattr: stand-ins lack the probe.
        try:
            probe._reserves_micro_batch_outputs = bool(
                getattr(LlamaCppBackend, "reserves_micro_batch_outputs", lambda: False)()
            )
        except Exception as _rows_exc:
            logger.debug("llama-server build probe failed: %s", _rows_exc)
        # Keep block_count even when the cache is unsized, or --gpu-layers 0 prices as fully GPU-resident.
        unknown = _GGUF_RUNTIME_UNKNOWN._replace(
            layer_count = getattr(probe, "_n_layers", None) or None
        )
        if not probe._can_estimate_kv():
            return unknown
        try:
            _raw_ctx_override = parse_ctx_override(llama_extra_args)
        except Exception:
            _raw_ctx_override = None  # malformed extras are rejected upstream; fall back
        ctx_override = _raw_ctx_override or 0
        # Explicit -c 0 requests native context and beats an inherited LLAMA_ARG_CTX_SIZE at the child.
        _extras_ask_for_native_ctx = _raw_ctx_override == 0
        if ctx_last_wins:
            # Resolve ctx as load_model does so a quoted number is what the launch runs; extras win either way; not the guard max.
            try:
                ctx = resolve_requested_ctx(llama_extra_args, max_seq_length or 0)
            except Exception:
                ctx = max_seq_length or 0
            ctx = (
                ctx
                or (0 if _extras_ask_for_native_ctx else _inherited_ctx_size())
                or (probe._context_length or 0)
            )
        else:
            ctx = (
                max(max_seq_length or 0, ctx_override)
                or (0 if _extras_ask_for_native_ctx else _inherited_ctx_size())
                or (probe._context_length or 0)
            )
        if ctx <= 0:
            return unknown
        # Same batch sizes, in the same order, as load_model.
        if getattr(probe, "_pooling_type", None) in (1, 2):
            n_batch, n_ubatch = _embedding_batch_ubatch(ctx, n_batch, n_ubatch, llama_extra_args)
        n_batch, n_ubatch = _batch_ubatch_for_mmproj(
            0 if is_diffusion else launch_required_ubatch,
            n_batch,
            n_ubatch,
            llama_extra_args,
        )
        slots = max(1, n_parallel or 1)
        planned_cache_types = _planned_main_cache_types(cache_type_kv, llama_extra_args)
        # KV bytes use the heavier cache type; dequant scratch the lighter (any quantized axis allocates it).
        cache_type_for_budget = max(planned_cache_types, key = _kv_bytes_per_elem)
        cache_type_for_scratch = _planned_scratch_cache_type(cache_type_kv, llama_extra_args)
        # Quantized V cache forces flash attention on in llama.cpp. Loader raises --batch-size to
        # max(slots, 2); diffusion takes neither flag.
        effective_ubatch = (
            None
            if is_diffusion
            else _extra_args_n_ubatch(
                llama_extra_args,
                n_ctx = ctx,
                n_batch = _emitted_n_batch(n_batch, slots),
                n_ubatch = n_ubatch,
            )
        )
        # --embedding caps n_batch to n_ubatch; the loader reduces slots to match before fitting.
        if (
            getattr(probe, "is_embedding_gguf", False)
            and effective_ubatch is not None
            and effective_ubatch < slots
        ):
            slots = max(1, effective_ubatch)
            effective_ubatch = _extra_args_n_ubatch(
                llama_extra_args,
                n_ctx = ctx,
                n_batch = _emitted_n_batch(n_batch, slots),
                n_ubatch = n_ubatch,
            )
        # Probe only when slots > 1: it shells out and a raise loses the whole runtime estimate.
        _kv_caps = LlamaCppBackend.probe_server_capabilities() if slots > 1 else {}
        _supports_kv_unified = bool(_kv_caps.get("supports_kv_unified", False))
        if slots > 1 and _kv_caps.get("found") and not _supports_kv_unified:
            # Without --kv-unified load_model drops to one slot before sizing, since an explicit --parallel N would split -c into N windows.
            slots = 1
        managed_kv_unified = bool(slots > 1 and _supports_kv_unified)
        swa_full = _swa_full_from_args_or_env(llama_extra_args)
        kv_unified = _kv_unified_from_args(
            llama_extra_args,
            default = managed_kv_unified,
        )
        # load_model adds --flash-attn when supported, so default ON; off pads V to the model-wide max and can overflow. Grok forced off first.
        _fa_supported = True
        try:
            _fa_caps = LlamaCppBackend.probe_server_capabilities()
            # Check 'found': the defaults dict reports nothing supported.
            if _fa_caps.get("found") and not _fa_caps.get("supports_flash_attn", True):
                _fa_supported = False
        except Exception as _fa_exc:
            logger.debug("flash-attention capability probe failed: %s", _fa_exc)
        # Shared with load_model so the estimate and the launch cannot disagree.
        flash_attn = _planned_flash_attn_state(
            llama_extra_args,
            planned_cache_types = planned_cache_types,
            supports_flash_attn = _fa_supported,
            tensor_parallel = bool(tensor_parallel),
            architecture = getattr(probe, "_architecture", None),
            env = os.environ,
        )
        if reserve_no_flash_respawn:
            # Guard admits the worst case, incl. a flash-attention-off respawn; the panel keeps the plan.
            flash_attn = _reserved_flash_attn_state(
                flash_attn,
                llama_extra_args,
                tensor_parallel = bool(tensor_parallel),
                env = os.environ,
            )
        _cc_caps: dict = {}
        try:
            _cc_caps = LlamaCppBackend.probe_server_capabilities() or {}
        except Exception as _cc_exc:
            logger.debug("ctx-checkpoints capability probe failed: %s", _cc_exc)
        _per_checkpoint = getattr(probe, "_ctx_checkpoint_bytes", lambda *_a, **_k: 0)(
            cache_type_for_budget, swa_full = swa_full, flash_attn = flash_attn
        )
        _host_mib = getattr(probe, "_host_memory_capacity_mib", lambda: None)()
        _resolved_checkpoints = effective_ctx_checkpoints_for_caps(
            _cc_caps,
            llama_extra_args,
            ctx_checkpoints,
            per_checkpoint_bytes = _per_checkpoint,
            n_parallel = slots,
            total_host_bytes = (_host_mib * 1024 * 1024) if _host_mib else None,
        )
        kv = probe._estimate_kv_cache_bytes(
            ctx,
            cache_type_for_budget,
            n_parallel = slots,
            swa_full = swa_full,
            kv_unified = kv_unified,
            n_ubatch = effective_ubatch,
            # Extras beat the field, as at launch.
            ctx_checkpoints = _resolved_checkpoints,
            flash_attn = flash_attn,
        )
        # Checkpoint share by difference: the only term separating the two calls.
        kv_checkpoint_bytes = 0
        if _resolved_checkpoints:
            _kv_without = probe._estimate_kv_cache_bytes(
                ctx,
                cache_type_for_budget,
                n_parallel = slots,
                swa_full = swa_full,
                kv_unified = kv_unified,
                n_ubatch = effective_ubatch,
                ctx_checkpoints = 0,
                flash_attn = flash_attn,
            )
            kv_checkpoint_bytes = max(0, int(kv) - int(_kv_without))
        _resolved = dict(
            kv_checkpoint_bytes = kv_checkpoint_bytes,
            kv_estimable = True,
            n_ctx = ctx,
            cache_type_kv = cache_type_for_budget,
            n_parallel = slots,
            layer_count = getattr(probe, "_n_layers", None) or None,
            swa_full = swa_full,
            kv_unified = kv_unified,
            n_ubatch = effective_ubatch,
        )
        # the load reserves ubatch-scaled compute buffers, so they count against training too
        if is_diffusion:
            return _GgufRuntimeBytes(kv_bytes = int(kv), compute_bytes = 0, **_resolved)
        devices = max(1, int(n_devices))

        def _flat_buffer(per_device_tensor: bool) -> int:
            """Use a vocabulary ceiling when a truncated header omits the token array."""
            return probe._estimate_compute_buffer_bytes(
                n_ubatch = effective_ubatch,
                n_parallel = slots,
                per_device_tensor = per_device_tensor,
                vocab_ceiling = _ASSUMED_MAX_VOCAB,
            )

        if tensor_parallel:
            # mirrors _plan_tensor_parallel: per-device buffer and ctx growth on every device
            compute = devices * (
                _flat_buffer(True)
                + probe._compute_buffer_ctx_bytes(ctx, effective_ubatch, cache_type_for_scratch)
            )
        else:
            # layer_split follows the loader: -ot, -ncmoe, --no-kv-offload disable pipeline parallelism.
            from core.inference.llama_cpp import _pipeline_parallel_disabled_by_args
            pipeline_parallel_off = _pipeline_parallel_disabled_by_args(
                llama_extra_args, n_layers = getattr(probe, "_n_layers", None)
            )
            compute = (
                _flat_buffer(False)
                + (devices - 1) * probe._PIPELINE_PER_DEVICE_OVERHEAD_MIB * 1024 * 1024
                + devices
                * probe._compute_buffer_ctx_bytes(
                    ctx,
                    effective_ubatch,
                    cache_type_for_scratch,
                    layer_split = devices > 1 and not pipeline_parallel_off,
                    flash_attn = flash_attn,
                    n_parallel = slots,
                )
            )
        if compute <= 0:
            # No embedding_length: floor at the loader flat reserve, charged once; it is an invented number with no basis to scale per device.
            compute = int(getattr(probe, "_TENSOR_PARALLEL_BUFFER_RESERVE_MIB", 0)) * 1024**2
        return _GgufRuntimeBytes(kv_bytes = int(kv), compute_bytes = int(compute), **_resolved)
    except Exception as e:
        logger.warning(f"Could not size GGUF KV cache for training guard: {e}")
        return _GGUF_RUNTIME_UNKNOWN


def _estimate_gguf_kv_gb(
    gguf_path: str,
    max_seq_length: int,
    llama_extra_args: Optional[list[str]] = None,
    n_parallel: int = 1,
    cache_type_kv: Optional[str] = None,
    tensor_parallel: bool = False,
    n_batch: Optional[int] = None,
    n_ubatch: Optional[int] = None,
    ctx_checkpoints: Optional[int] = None,
    n_devices: int = 1,
    is_diffusion: bool = False,
    model_identifier: Optional[str] = None,
    launch_required_ubatch: int = 0,
    shared_memory_pool: bool = True,
) -> float:
    """Checkpoints drop out only if shared_memory_pool is False (iGPU VRAM is host RAM); an unreadable header is 0 GB, never a refusal alone."""
    runtime = _gguf_runtime_bytes(
        gguf_path,
        max_seq_length,
        llama_extra_args,
        n_parallel,
        cache_type_kv,
        tensor_parallel,
        n_batch,
        n_ubatch,
        ctx_checkpoints = ctx_checkpoints,
        n_devices = n_devices,
        is_diffusion = is_diffusion,
        model_identifier = model_identifier,
        launch_required_ubatch = launch_required_ubatch,
        reserve_no_flash_respawn = True,
    )
    gpu_kv_bytes = (
        runtime.kv_bytes
        if shared_memory_pool
        else max(0, runtime.kv_bytes - runtime.kv_checkpoint_bytes)
    )
    return (gpu_kv_bytes + runtime.compute_bytes) / (1024**3)


def _remote_gguf_compute_reserve_gb(
    llama_extra_args: Optional[list[str]] = None,
    max_seq_length: int = 0,
    n_parallel: int = 1,
    n_batch: Optional[int] = None,
    n_ubatch: Optional[int] = None,
    n_devices: int = 1,
    tensor_parallel: bool = False,
    is_diffusion: bool = False,
    required_ubatch: int = 0,
) -> float:
    """Split out so a caller pricing something else, like a drafter, can hold compute reserve at zero."""
    from core.inference.llama_cpp import (
        _ASSUMED_MAX_ACTIVATION_WIDTH,
        _ASSUMED_MAX_VOCAB,
        _batch_ubatch_for_mmproj,
    )
    from core.inference.llama_server_args import parse_ctx_override

    n_batch, n_ubatch = _batch_ubatch_for_mmproj(
        0 if is_diffusion else required_ubatch,
        n_batch,
        n_ubatch,
        llama_extra_args,
    )

    try:
        ctx_override = parse_ctx_override(llama_extra_args) or 0
    except Exception:
        ctx_override = 0
    ctx = max(max_seq_length or 0, ctx_override)
    effective_ubatch = (
        None
        if is_diffusion
        else _extra_args_n_ubatch(
            llama_extra_args,
            n_ctx = ctx if ctx > 0 else None,
            # same floor raise the loader applies at launch
            n_batch = _emitted_n_batch(n_batch, n_parallel),
            n_ubatch = n_ubatch,
        )
    )
    if effective_ubatch is None and not is_diffusion:
        effective_ubatch = LlamaCppBackend._DEFAULT_N_UBATCH
    if effective_ubatch:
        # auto context: assume the native one fits at least a full micro-batch
        budget_ctx = ctx if ctx > 0 else effective_ubatch
        devices = max(1, int(n_devices))
        # Multi-device layer split materialises the KQ mask _CTX_COMPUTE_SPLIT_MULT times; with the header unread, -ot, -ncmoe, --no-kv-offload still register.
        from core.inference.llama_cpp import _pipeline_parallel_disabled_by_args

        split_mult = (
            LlamaCppBackend._CTX_COMPUTE_SPLIT_MULT
            if devices > 1
            and not tensor_parallel
            and not _pipeline_parallel_disabled_by_args(llama_extra_args, n_layers = None)
            else 1
        )
        mask_bytes = budget_ctx * effective_ubatch * 2 * devices * split_mult
        # Unknown dims: activation ceiling, output rows for max draft depth; tensor mode replicates.
        activation_bytes = _ASSUMED_MAX_ACTIVATION_WIDTH * effective_ubatch * 4
        output_rows = min(
            effective_ubatch,
            max(1, n_parallel) * (1 + LlamaCppBackend._UNKNOWN_SPEC_DRAFT_N_MAX),
        )
        try:
            if LlamaCppBackend.reserves_micro_batch_outputs():
                output_rows = effective_ubatch
        except Exception as _rows_exc:
            logger.debug("llama-server build probe failed: %s", _rows_exc)
        flat_bytes = (
            (activation_bytes + _ASSUMED_MAX_VOCAB * output_rows * 4)
            * LlamaCppBackend._COMPUTE_BUFFER_SAFETY
            * (devices if tensor_parallel else 1)
        )
        return (mask_bytes + flat_bytes) / (1024**3)
    return 0.0


def _admission_pool_shares_host_ram(
    *,
    is_vulkan_backend: bool,
    vulkan_gpu_memory: Optional[list] = None,
    requested_gpu_ids: Optional[list[int]] = None,
    gpu_ids_are_vulkan_ordinals: bool = False,
) -> bool:
    """Fails closed: an unreadable inventory, unmappable selection or any integrated GPU answers True."""
    try:
        from core.inference.llama_cpp import LlamaCppBackend

        if is_vulkan_backend:
            # total 0 means integrated. Narrow to the pin only if it is in Vulkan's own index space.
            rows = list(vulkan_gpu_memory or [])
            if gpu_ids_are_vulkan_ordinals and requested_gpu_ids:
                pinned = {int(i) for i in requested_gpu_ids}
                rows = [row for row in rows if int(row[0]) in pinned]
            return not rows or any(int(total) <= 0 for _idx, _free, total in rows)
        import torch

        if LlamaCppBackend._torch_is_rocm(torch):
            # Empty unified set means 'no APU' or 'could not read'; only the first is evidence.
            if not LlamaCppBackend._rocm_classification_answered():
                return True
            unified = LlamaCppBackend._rocm_unified_memory_gpu_ids()
        else:
            # Never probe Jetson/DGX Spark here: _integrated_cuda_gpu_ids pins ~700 MiB per card that training holds. Use cached answers only, else keep the charge.
            if not LlamaCppBackend._integrated_cuda_probe_is_free():
                return True
            unified = LlamaCppBackend._integrated_cuda_gpu_ids()
        if not unified:
            return False
        return not requested_gpu_ids or any(int(i) in unified for i in requested_gpu_ids)
    except Exception as e:  # noqa: BLE001 -- an unreadable device keeps the charge
        logger.debug("Could not classify the admission pool: %s", e)
        return True


def _estimate_gguf_required_gb(
    config: ModelConfig,
    hf_token: Optional[str] = None,
    max_seq_length: int = 0,
    llama_extra_args: Optional[list[str]] = None,
    speculative_type: Optional[str] = None,
    n_parallel: int = 1,
    cache_type_kv: Optional[str] = None,
    tensor_parallel: bool = False,
    n_batch: Optional[int] = None,
    n_ubatch: Optional[int] = None,
    ctx_checkpoints: Optional[int] = None,
    n_devices: int = 1,
    is_diffusion: bool = False,
    disable_vision: bool = False,
    # Skip the network listing of a --spec-draft-hf repo: the panel reprices on every settings change; the caller marks the total a floor.
    local_only: bool = False,
    # Only a caller that confirmed a discrete pool may drop the host-resident checkpoint share.
    shared_memory_pool: bool = True,
) -> Optional[float]:
    """Approximate GGUF VRAM (GB): quantized weights + companions, plus the KV
    cache for local files (unreadable pre-download for remote). None when nothing
    resolves so the caller default-denies."""
    try:
        from core.inference.llama_cpp import (
            _canonicalize_spec_mode,
            _dflash_drafter_breaks_on_images,
            _extra_args_device,
            _extra_args_draft_offloaded_to_cpu,
            _extra_args_mtp_draft_path,
            _extra_args_mtp_draft_source,
            _extra_args_requests_dflash,
            _extra_args_requests_dspark,
            _extra_args_set_spec_type,
            _mmproj_env_is_audio_only,
            _mtp_drafter_loads_standalone,
            extra_args_disable_mmproj,
        )

        _spec_mode = _canonicalize_spec_mode(speculative_type) or "auto"
        _extra_args_own_spec = _extra_args_set_spec_type(llama_extra_args)
        # --spec-type in extras skips mode branches, yet a drafter may still arrive unseen, so charge it.
        _extras_own_draft_path = _extra_args_mtp_draft_path(llama_extra_args, env = {})
        # Extras draft path wins (last-wins); charged as _extras_bytes, so don't charge the sidecar too.
        _extras_own_drafter = bool(_extras_own_draft_path)
        # -ngld 0 / --spec-draft-device cpu: no separate drafter in the VRAM budget.
        _draft_pinned_to_cpu = _extra_args_draft_offloaded_to_cpu(llama_extra_args, env = os.environ)
        _forced_dspark = bool(
            (_spec_mode == "dspark" or _extra_args_requests_dspark(llama_extra_args, env = {}))
            and not _extras_own_drafter
            and not _draft_pinned_to_cpu
        )
        # Auto loads any sidecar present, so size it too, or the guard admits loads 11 GB over estimate.
        _auto_dspark = _spec_mode == "auto" and not _extras_own_drafter and not _draft_pinned_to_cpu
        _dspark_capable = True
        if _forced_dspark or _auto_dspark:
            # Gate on the loader's draft-dspark probe; an unreadable probe keeps the sidecar counted.
            try:
                _dspark_capable = bool(
                    LlamaCppBackend.probe_server_capabilities().get("supports_dspark")
                )
            except Exception:
                pass
        dspark_requested = bool(
            _dspark_capable
            and (_forced_dspark or (_auto_dspark and getattr(config, "gguf_dspark_file", None)))
        )
        # DFlash sidecar (~1.5 GiB) is charged under Auto as well, since a training guard must count it.
        _forced_dflash = bool(
            (
                _extra_args_requests_dflash(llama_extra_args, env = {})
                or (_spec_mode == "dflash" and not _extra_args_own_spec)
            )
            and not _extras_own_drafter
            and not _draft_pinned_to_cpu
        )
        # Auto skips DFlash when extras own --spec-type or name their own drafter; the loader uses that one.
        _auto_dflash = (
            _spec_mode == "auto"
            and not _extra_args_own_spec
            and not _extras_own_drafter
            and not _draft_pinned_to_cpu
        )
        # Mirrors load_model's #11308 rule: Auto on tensor split runs a loadable MTP sidecar, not DFlash.
        if _auto_dflash:
            from core.inference.llama_server_args import _effective_tensor_parallel
            from utils.models.gguf_metadata import read_gguf_nextn_predict_layers

            _tp_mtp = getattr(config, "gguf_mtp_file", None)
            _tp_main = getattr(config, "gguf_file", None)
            if (
                _tp_mtp
                and _effective_tensor_parallel(llama_extra_args, tensor_parallel)
                and Path(_tp_mtp).is_file()
                and not (_tp_main and (read_gguf_nextn_predict_layers(str(_tp_main)) or 0) > 0)
                and _mtp_drafter_loads_standalone(str(_tp_mtp))
            ):
                try:
                    if LlamaCppBackend.probe_server_capabilities().get("mtp_token"):
                        _auto_dflash = False
                except Exception:
                    pass
        # Mirrors load_model's #13511 rule: Auto skips a NeoX DFlash drafter on an M-RoPE vision load.
        if _auto_dflash and not disable_vision and not extra_args_disable_mmproj(llama_extra_args):
            _vd_mmproj = _extra_args_device(llama_extra_args, {"--mmproj", "-mm"}) or getattr(
                config, "gguf_mmproj_file", None
            )
            if _vd_mmproj and Path(_vd_mmproj).is_file():
                _auto_dflash = not _dflash_drafter_breaks_on_images(
                    getattr(config, "gguf_file", None),
                    getattr(config, "gguf_dflash_file", None),
                    str(_vd_mmproj),
                )
        _dflash_capable = True
        if _forced_dflash or _auto_dflash:
            try:
                _dflash_capable = bool(
                    LlamaCppBackend.probe_server_capabilities().get("supports_dflash")
                )
            except Exception:
                pass
        # DSpark keeps first refusal under Auto, mirroring the loader.
        dflash_requested = bool(
            _dflash_capable
            and not dspark_requested
            and (_forced_dflash or (_auto_dflash and getattr(config, "gguf_dflash_file", None)))
        )
        # Forced DSpark on an unsupporting binary loads no drafter; Auto falls through to MTP.
        _charge_no_drafter = (
            _draft_pinned_to_cpu
            or _extras_own_drafter
            or (_forced_dspark and not _dspark_capable)
            or (_forced_dflash and not _dflash_capable)
            # off, ngram and ngram-simple emit no --model-draft unless extras own --spec-type, so no MTP sidecar is charged for them.
            or (_spec_mode in _SPEC_MODES_WITHOUT_A_DRAFTER and not _extra_args_own_spec)
        )

        def _same_file_key(p: str) -> str:
            # Identity by resolved path, so a symlinked or differently spelled copy still counts as one file.
            try:
                return os.path.realpath(p)
            except OSError:
                return str(p)

        total_bytes = 0
        # Only files already charged, so the extras drafter tells another sidecar from the one discovered.
        _sized_keys: set[str] = set()
        main = getattr(config, "gguf_file", None)
        if main and Path(main).is_file():
            total_bytes += LlamaCppBackend._get_gguf_size_bytes(str(main))
            _sized_keys.add(_same_file_key(str(main)))
        # Charge only the drafter the launch loads. Vision off still keeps an audio-only projector.
        _mmproj_override = _extra_args_device(llama_extra_args, {"--mmproj", "-mm"})
        _sized_attrs = ["gguf_mmproj_file"]
        # Whether the configured projector is opened by this launch; bound early for the inherited gate.
        _dv_opens_projector = True
        if extra_args_disable_mmproj(llama_extra_args):
            # llama_cpp.py skips the resolve, so nothing is downloaded; inherited paths are charged below.
            _dv_opens_projector = False
            _sized_attrs = []
        elif disable_vision:
            _dv_mmproj = _mmproj_override or getattr(config, "gguf_mmproj_file", None)
            _dv_opens_projector = bool(_dv_mmproj) and _projector_survives_vision_off(
                str(_dv_mmproj)
            )
            if not _dv_opens_projector:
                _sized_attrs = []
        # An extras --mmproj last-wins at the child, so charge it instead of the configured one.
        _mmproj_override_bytes = 0
        if _sized_attrs == ["gguf_mmproj_file"]:
            if _mmproj_override and Path(_mmproj_override).is_file():
                _sized_attrs = []
                _mmproj_override_bytes = LlamaCppBackend._get_gguf_size_bytes(_mmproj_override)
                _sized_keys.add(_same_file_key(_mmproj_override))
        if not _charge_no_drafter:
            if dspark_requested:
                _sized_attrs.append("gguf_dspark_file")
            elif dflash_requested:
                # Only when extras own --spec-type does llama-server open their drafter alone.
                _manual_draft = (
                    _extra_args_mtp_draft_path(llama_extra_args, env = {})
                    if _extra_args_own_spec
                    else None
                )
                _configured = getattr(config, "gguf_dflash_file", None)
                if not (
                    _manual_draft
                    and _configured
                    and _same_file_key(str(_manual_draft)) != _same_file_key(str(_configured))
                ):
                    _sized_attrs.append("gguf_dflash_file")
            else:
                # The launch drops a drafter it cannot open, so charging one would refuse
                # a load that fits.
                _mtp = getattr(config, "gguf_mtp_file", None)
                if not (
                    _mtp and Path(_mtp).is_file() and not _mtp_drafter_loads_standalone(str(_mtp))
                ):
                    _sized_attrs.append("gguf_mtp_file")

        for attr in _sized_attrs:
            f = getattr(config, attr, None)
            if f and Path(f).is_file():
                # Split-aware: discovery hands back shard 1, so stat() alone would size a split drafter at one shard and admit a load that evicts training.
                total_bytes += LlamaCppBackend._get_gguf_size_bytes(str(f))
                _sized_keys.add(_same_file_key(str(f)))
        # An EAGLE-3 drafter a Studio export paired with this GGUF (drafter.json): the
        # launch attaches it under Auto, so it is charged like the sidecars above.
        if main and not _charge_no_drafter and _spec_mode in ("auto", "eagle3"):
            try:
                from core.export.drafter_export import eagle3_sidecar_path
                _eagle3 = eagle3_sidecar_path(str(main))
            except Exception:
                _eagle3 = None
            # Like DSpark / DFlash: a binary without draft-eagle3 never opens it.
            if _eagle3:
                try:
                    if not LlamaCppBackend.probe_server_capabilities().get("supports_eagle3"):
                        _eagle3 = None
                except Exception:
                    _eagle3 = None
            if _eagle3 and _same_file_key(_eagle3) not in _sized_keys:
                total_bytes += LlamaCppBackend._get_gguf_size_bytes(_eagle3)
                _sized_keys.add(_same_file_key(_eagle3))

        # Extras --model-draft is charged once (may equal a discovered sidecar) and never decides the branch: it is no evidence of a local main weight.
        _extras_bytes = 0
        # Draft flags are last-wins, so track which flag carried the final value.
        _extras_draft, _extras_draft_is_remote = _extra_args_mtp_draft_source(
            llama_extra_args, env = {}
        )
        # A host-memory drafter competes for RAM, not VRAM.
        if _extra_args_draft_offloaded_to_cpu(llama_extra_args, env = os.environ):
            _extras_bytes = 0
        elif _extras_draft and Path(_extras_draft).is_file():
            if _same_file_key(str(_extras_draft)) not in _sized_keys:
                _extras_bytes = LlamaCppBackend._get_gguf_size_bytes(str(_extras_draft))
        elif _extras_draft and _extras_draft_is_remote and not local_only:
            _extras_bytes = _remote_drafter_repo_bytes(str(_extras_draft), hf_token = hf_token)
        # Inherited LLAMA_ARG_MMPROJ loads unless our --mmproj is on argv; --no-mmproj empties argv, not mmproj.path. Added to return, not total_bytes.
        _studio_mmproj_on_argv = bool(
            (_mmproj_override or getattr(config, "gguf_mmproj_file", None)) and _dv_opens_projector
        )
        _env_mmproj_bytes = 0
        _env_mmproj = (os.environ.get("LLAMA_ARG_MMPROJ") or "").strip()
        if (
            _env_mmproj
            and not _studio_mmproj_on_argv
            and (not disable_vision or _mmproj_env_is_audio_only(_env_mmproj))
            and Path(_env_mmproj).is_file()
            and _same_file_key(_env_mmproj) not in _sized_keys
        ):
            _env_mmproj_bytes = LlamaCppBackend._get_gguf_size_bytes(_env_mmproj)

        if total_bytes > 0:
            return (total_bytes + _mmproj_override_bytes + _extras_bytes + _env_mmproj_bytes) / (
                1024**3
            ) + _estimate_gguf_kv_gb(
                main,
                max_seq_length,
                llama_extra_args,
                n_parallel,
                cache_type_kv,
                tensor_parallel,
                n_batch,
                n_ubatch,
                ctx_checkpoints = ctx_checkpoints,
                n_devices = n_devices,
                is_diffusion = is_diffusion,
                model_identifier = getattr(config, "identifier", None),
                launch_required_ubatch = _launch_required_ubatch_for_config(
                    config, llama_extra_args, disable_vision
                ),
                shared_memory_pool = shared_memory_pool,
            )

        repo = getattr(config, "gguf_hf_repo", None)
        variant = getattr(config, "gguf_variant", None)
        if repo and variant:
            from utils.models.model_config import list_gguf_variants

            variants, has_vision = list_gguf_variants(repo, hf_token = hf_token)
            selected = next((v for v in variants if v.quant.lower() == variant.lower()), None)
            main_bytes = selected.size_bytes if selected is not None else None
            if main_bytes is None:
                return None
            _local_mmproj = getattr(config, "gguf_local_mmproj_file", None)
            _local_mmproj_bytes = 0
            # A --mmproj in the extras replaces it and is charged on its own.
            if (
                _local_mmproj
                and _mmproj_override is None
                and not extra_args_disable_mmproj(llama_extra_args)
            ):
                if not disable_vision or _projector_survives_vision_off(str(_local_mmproj)):
                    _local_mmproj_bytes = LlamaCppBackend._get_gguf_size_bytes(str(_local_mmproj))
            companions = _remote_gguf_companion_bytes(
                repo,
                hf_token = hf_token,
                # Charged regardless of the vision switch: only the file's metadata says if audio-only.
                include_mmproj = bool(has_vision) and _mmproj_override is None,
                # Remote: sidecar kind unknown until listing, so Auto sizes both (the absent one is 0).
                include_mtp = (
                    not _charge_no_drafter
                    and (_auto_dspark or not (dspark_requested or dflash_requested))
                ),
                include_dspark = (_dspark_capable and (_auto_dspark or dspark_requested)),
                include_dflash = (_dflash_capable and (_auto_dflash or dflash_requested)),
                # Weight size DFlash candidates are measured against, so refused oversize weights go uncharged.
                weight_bytes = int(main_bytes or 0),
                # Hand-added (#9286): invisible to the listing, still resident.
                local_mmproj_bytes = _local_mmproj_bytes,
                # Auto launches one drafter in a fixed order, so the listing settles which to charge.
                dspark_first = _auto_dspark,
            )
            # Plus caller --model-draft / --spec-draft-hf, which the repo listing cannot see but stays resident.
            total_gb = (main_bytes + companions + _mmproj_override_bytes + _extras_bytes) / (
                1024**3
            )
            total_gb += _remote_gguf_compute_reserve_gb(
                llama_extra_args = llama_extra_args,
                max_seq_length = max_seq_length,
                n_parallel = n_parallel,
                n_batch = n_batch,
                n_ubatch = n_ubatch,
                n_devices = n_devices,
                tensor_parallel = tensor_parallel,
                is_diffusion = is_diffusion,
                required_ubatch = _remote_required_ubatch(config, llama_extra_args, disable_vision),
            )
            return total_gb
        return None
    except Exception as e:
        logger.warning(f"Could not size GGUF model for training guard: {e}")
        return None


class _GgufMemoryBreakdown(NamedTuple):
    """What a prospective GGUF load would occupy, itemized for the Load-Model panel.

    ``weights_bytes`` is the files that become resident (weights plus whichever
    projector and drafter this launch opens) and is the one term that does not move
    with the settings above it.
    """

    weights_bytes: int
    kv_bytes: int
    compute_bytes: int
    # Separate drafter KV and rollback state, kept out of compute_bytes so each field names one thing.
    drafter_runtime_bytes: int
    # GPU share of drafter runtime: under MTP, target-side state follows the target cache.
    drafter_runtime_gpu_bytes: int
    # The vision encoder's buffers, about 0.4x the projector file on top of it.
    projector_runtime_bytes: int
    # Drafter charged but its cache unsized: --spec-draft-hf names a repo whose header is not on disk.
    drafter_kv_unsized: bool
    # A --lora or --control-vector file could not be stat'd, so its bytes are missing from the total.
    adapters_unsized: bool
    # Weights + KV + compute, wherever they sit: GPU, host RAM, or a unified pool.
    total_bytes: int
    # The part that lands on the GPU under the requested offload.
    gpu_bytes: int
    kv_estimable: bool
    kv_on_gpu: bool
    n_ctx: int
    cache_type_kv: Optional[str]
    n_parallel: int
    layer_count: Optional[int]
    gpu_layers: Optional[int]
    # Host-resident checkpoint share of kv_bytes. Keep last for positional callers.
    kv_checkpoint_bytes: int = 0
    lookup_table_bytes: int = 0
    lookup_table_on_disk: bool = False


def _gguf_offloaded_layer_fraction(
    gpu_memory_mode: Optional[str],
    gpu_layers: Optional[int],
    layer_count: Optional[int],
    extras: Optional[list[str]] = None,
    *,
    device_pin_governs: bool = False,
) -> float:
    """Share of weights kept on GPU in [0,1]: Auto 1.0; Manual --gpu-layers over block_count+1; an extras -ngl wins; --n-cpu-moe not modelled, reads high."""
    from core.inference.llama_cpp import _device_selection_is_cpu
    from core.inference.llama_server_args import parse_gpu_layers_override

    # A --device naming no GPU beats every layer count; same predicate as the loader.
    if not device_pin_governs and (
        _device_selection_is_cpu(extras, os.environ) or _estimate_host_has_no_gpu()
    ):
        return 0.0

    try:
        override = parse_gpu_layers_override(extras)
    except ValueError:
        # Malformed value: llama-server names it better than a guess here would.
        override = None
    if override is not None:
        gpu_layers = override
    elif gpu_memory_mode != "manual":
        # Auto emits no -ngl, so an inherited LLAMA_ARG_N_GPU_LAYERS fixes layers and fit.cpp won't override.
        from core.inference.llama_cpp import _env_fixes_gpu_layers
        if not _env_fixes_gpu_layers(os.environ):
            return 1.0
        try:
            gpu_layers = int(str(os.environ.get("LLAMA_ARG_N_GPU_LAYERS", "")).strip())
        except ValueError:
            # llama.cpp's std::stoi would throw and the child never starts.
            return 1.0
    if gpu_layers is None or gpu_layers < 0:
        return 1.0
    if gpu_layers == 0:
        # Before the layer count: zero needs none, and an unreadable header must not mean 1.0 here.
        return 0.0
    if not layer_count or layer_count <= 0:
        # No dims to scale against; 1.0 keeps it consistent with Auto.
        return 1.0
    return max(0.0, min(1.0, gpu_layers / float(layer_count + 1)))


def _probe_backend():
    """Fall back only for an unsupported keyword; the bare constructor reaps llama-server processes."""
    import inspect
    try:
        return LlamaCppBackend(manages_processes = False)
    except TypeError:
        try:
            inspect.signature(LlamaCppBackend).bind(manages_processes = False)
        except (TypeError, ValueError):
            # Keyword truly unsupported, or no introspectable signature: fall back to today's behaviour.
            return LlamaCppBackend()
        # It bound fine, so the fault came from the body. Let it surface.
        raise


def _manual_keeps_tensor_split(
    gpu_memory_mode: Optional[str],
    gpu_layers: Optional[int],
    extras: Optional[list[str]] = None,
) -> bool:
    """Manual keeps tensor split unless gpu_layers is 0 (CPU-only mask aborts the server) or Auto (--fit is incompatible); an extras -ngl overrides."""
    if gpu_memory_mode != "manual":
        return True
    from core.inference.llama_server_args import parse_gpu_layers_override

    try:
        override = parse_gpu_layers_override(extras)
    except ValueError:
        # Malformed override: ignored like _gguf_offloaded_layer_fraction; llama-server names it better.
        override = None
    if override is not None:
        gpu_layers = override
    return gpu_layers is not None and gpu_layers >= 1


# Three answers: ONLINE resolution must tell 'present' from 'could not tell'.
_ESTIMATE_DISK_PRESENT = "present"
_ESTIMATE_DISK_ABSENT = "absent"
_ESTIMATE_DISK_UNKNOWN = "unknown"


def _estimate_disk_residency(model_identifier: str) -> str:
    """Keeps unknown apart from absent; the route must never answer unknown with a Hub round trip."""
    try:
        from utils.paths import is_local_path
    except Exception:
        return _ESTIMATE_DISK_UNKNOWN
    if not model_identifier or not model_identifier.strip():
        return _ESTIMATE_DISK_UNKNOWN
    identifier = model_identifier.strip()
    try:
        if is_local_path(identifier):
            return _ESTIMATE_DISK_PRESENT
    except Exception:
        return _ESTIMATE_DISK_UNKNOWN

    # from_identifier prefixes a bare name, so ask about the id it will actually use.
    candidates = [identifier]
    if "/" not in identifier:
        candidates.append(f"unsloth/{identifier}")
    try:
        from utils.models.model_config import _iter_hf_cache_snapshots
        roots = _estimate_hf_cache_roots()
    except Exception:
        return _ESTIMATE_DISK_UNKNOWN
    if not roots:
        return _ESTIMATE_DISK_UNKNOWN
    try:
        for root in roots:
            for candidate in candidates:
                for _snapshot in _iter_hf_cache_snapshots(candidate, cache_dir = root):
                    return _ESTIMATE_DISK_PRESENT
    except Exception:
        return _ESTIMATE_DISK_UNKNOWN
    return _ESTIMATE_DISK_ABSENT


def _estimate_target_is_on_this_disk(model_identifier: str) -> bool:
    """Remote repos count only if cached in any scanned HF root, legacy included; errors fail open, but never by reaching the network."""
    return _estimate_disk_residency(model_identifier) != _ESTIMATE_DISK_ABSENT


def _estimate_hf_cache_roots() -> list:
    """Falls back to two known roots, not [], since an empty list would silently disable the cache check."""
    try:
        from hub.utils.hf_cache_state import hf_cache_roots
        roots = [Path(r) for r in hf_cache_roots()]
        if roots:
            return roots
    except Exception:
        pass

    roots = []
    seen = set()

    def _add(value) -> None:
        if not value:
            return
        try:
            path = Path(value)
            key = str(path.resolve())
        except OSError:
            return
        if key not in seen and path.is_dir():
            seen.add(key)
            roots.append(path)

    try:
        from utils.hf_cache_settings import known_hf_hub_caches
        for configured in known_hf_hub_caches():
            _add(configured)
    except Exception:
        pass
    try:
        from huggingface_hub import constants as _hf_constants
        _add(getattr(_hf_constants, "HF_HUB_CACHE", None))
    except Exception:
        pass
    return roots


def _estimate_token_fingerprint(hf_token: Optional[str]) -> str:
    """Hashes the token so the credential never sits verbatim in a cache key."""
    if not hf_token:
        return ""
    return _hashlib.sha256(hf_token.encode("utf-8")).hexdigest()[:16]


# Keyed on what decides which files open, not ctx/cache type, so sliders never re-list a repo.
_ESTIMATE_FILES_TTL_SECONDS = 30.0
_ESTIMATE_FILES_CACHE_MAX = 16
_estimate_files_cache: "dict[tuple, tuple[float, Optional[float]]]" = {}
# Held only across evict-and-insert, never across a header walk or resolution.
_ESTIMATE_CACHE_LOCK = threading.Lock()
# Distinct from None: None is 'unsizable', this is 'not_downloaded'.
_ESTIMATE_NOT_ON_DISK = object()


def _localized_estimate_config(config: ModelConfig, gguf_path: str) -> ModelConfig:
    """Config unchanged if gguf_file is on disk; else a copy with cached weights, no network call. Copied, never mutated: the original lives in a TTL cache."""
    main = getattr(config, "gguf_file", None)
    if main and Path(main).is_file():
        return config
    from utils.models.model_config import (
        _local_gguf_companion_search_root,
        detect_dflash_file,
        detect_dspark_file,
        detect_mmproj_file,
        detect_mtp_file,
    )

    local = replace(config, gguf_file = gguf_path)
    # Use the load path helper, not the weight parent: quant-subdir layouts keep projector and drafter at the snapshot root, else silently dropped.
    search_root = _local_gguf_companion_search_root(gguf_path, gguf_path)
    try:
        if getattr(local, "is_vision", False) and not local.gguf_mmproj_file:
            # A hand-added one may sit above the snapshot, past this search root (#9286).
            local.gguf_mmproj_file = detect_mmproj_file(gguf_path, search_root) or getattr(
                local, "gguf_local_mmproj_file", None
            )
        if not local.gguf_mtp_file:
            local.gguf_mtp_file = detect_mtp_file(gguf_path, search_root)
        if not local.gguf_dspark_file:
            local.gguf_dspark_file = detect_dspark_file(gguf_path, search_root)
        if not local.gguf_dflash_file:
            local.gguf_dflash_file = detect_dflash_file(gguf_path, search_root)
    except Exception as exc:
        # An uncounted sidecar is a smaller error than no estimate at all.
        logger.debug("Companion detection failed for the memory estimate: %s", exc)
    return local


def _gguf_resident_file_gb(
    config: ModelConfig,
    *,
    hf_token: Optional[str] = None,
    llama_extra_args: Optional[list[str]] = None,
    speculative_type: Optional[str] = None,
    disable_vision: bool = False,
    local_only: bool = False,
    tensor_parallel: bool = False,
) -> Optional[float]:
    """Files-only part of _estimate_gguf_required_gb, minus its context term, so the two cannot drift."""
    main = getattr(config, "gguf_file", None)
    local_arm = bool(main and Path(main).is_file())
    key = (
        getattr(config, "identifier", None),
        getattr(config, "gguf_variant", None),
        str(main or ""),
        bool(disable_vision),
        speculative_type or "",
        tuple(llama_extra_args or ()),
        # A gated repo resolves per token, so entries must not cross subjects.
        _estimate_token_fingerprint(hf_token),
    )
    # In the key: a local-only answer served to the admission guard would drop a
    # remote drafter it must charge for.
    key = (*key, local_only, bool(tensor_parallel))
    now = time.monotonic()
    hit = _estimate_files_cache.get(key)
    if hit is not None and now - hit[0] < _ESTIMATE_FILES_TTL_SECONDS:
        return hit[1]

    priced = dict(
        llama_extra_args = llama_extra_args,
        speculative_type = speculative_type,
        disable_vision = disable_vision,
        hf_token = hf_token,
        local_only = local_only,
        tensor_parallel = tensor_parallel,
    )
    required_gb = _estimate_gguf_required_gb(config, max_seq_length = 0, **priced)
    if required_gb is None:
        return None  # deliberately not cached: usually a download still in flight
    if local_arm:
        # Same identifier as the required-GB arm, or the subtraction stops pairing.
        context_term_gb = _estimate_gguf_kv_gb(
            str(main),
            0,
            llama_extra_args,
            model_identifier = getattr(config, "identifier", None),
            # Subtract the same runtime term added above.
            launch_required_ubatch = _launch_required_ubatch_for_config(
                config, llama_extra_args, disable_vision
            ),
        )
    else:
        context_term_gb = _remote_gguf_compute_reserve_gb(
            llama_extra_args = llama_extra_args,
            max_seq_length = 0,
            required_ubatch = _remote_required_ubatch(config, llama_extra_args, disable_vision),
        )
    files_gb = max(0.0, required_gb - context_term_gb)
    # Lock: route runs in to_thread workers; concurrent min()/pop would 500 a slider drag.
    with _ESTIMATE_CACHE_LOCK:
        if len(_estimate_files_cache) >= _ESTIMATE_FILES_CACHE_MAX:
            oldest = min(_estimate_files_cache, key = lambda k: _estimate_files_cache[k][0])
            _estimate_files_cache.pop(oldest, None)
        # Stamp now, not at `now`, so a slow header walk is not inserted pre-expired.
        _estimate_files_cache[key] = (time.monotonic(), files_gb)
    return files_gb


# Both flags are last-wins, so appending overrides earlier args and the env fallback.
_DRAFT_FORCE_GPU_ARGS = ("--spec-draft-ngl", "999", "--spec-draft-device", "gpu")
_DRAFT_FORCE_CPU_ARGS = ("--spec-draft-ngl", "0")


def _charged_drafter_path(
    config: ModelConfig,
    drafter_bytes: int,
    *,
    extras: Optional[list[str]] = None,
) -> Optional[tuple[str, str]]:
    """Returns (path, kind) of the drafter charged, matched by byte size so it cannot pick another sidecar; an extras --model-draft is taken first, unmatched."""
    if drafter_bytes <= 0:
        return None
    from core.inference.llama_cpp import _child_spec_env, _extra_args_mtp_draft_path

    named = _extra_args_mtp_draft_path(extras, env = _child_spec_env(extras)) if extras else None
    if named and Path(named).is_file():
        return str(named), "extras"
    for attr, kind in (
        ("gguf_dspark_file", "dspark"),
        ("gguf_dflash_file", "dflash"),
        ("gguf_mtp_file", "mtp"),
    ):
        candidate = getattr(config, attr, None)
        if not candidate or not Path(candidate).is_file():
            continue
        if LlamaCppBackend._get_gguf_size_bytes(str(candidate)) == drafter_bytes:
            return str(candidate), kind
    return None


def _estimate_host_has_no_gpu() -> bool:
    """Only a probe that ran and found no devices counts; a zero CUDA count is not proof on Vulkan hosts."""
    devices = _cached_inference_devices()
    return devices is not None and len(devices) == 0


def _cached_inference_devices() -> Optional[list[tuple[int, int, int]]]:
    """Reads the snapshot /api/system filled, never refreshing it: the Vulkan probe runs a subprocess."""
    try:
        cached = getattr(sys.modules.get("main"), "_system_gpu_cache", None)
        if not cached:
            return None
        _, (_, inference_gpu) = cached
        devices = (inference_gpu or {}).get("devices") or []
        # NOT `or None`: empty list = no GPU found, None = snapshot never filled.
        return [(int(device.get("index", i)), 0, 0) for i, device in enumerate(devices)]
    except Exception:
        return None


def _tensor_split_possible(requested_gpu_ids: Optional[list[int]]) -> bool:
    """Tensor split needs two usable GPUs, since load_model falls back to a layer split below that."""
    if requested_gpu_ids:
        return len(requested_gpu_ids) >= 2
    try:
        if LlamaCppBackend._is_vulkan_backend():
            devices = _cached_inference_devices()
            return len(devices) >= 2 if devices is not None else True
    except Exception:
        pass
    try:
        return LlamaCppBackend._effective_gpu_count(None) >= 2
    except Exception:
        return True


def _charged_projector_bytes(
    config: ModelConfig, extras: Optional[list[str]], disable_vision: bool
) -> int:
    """Projector the launch opens, or 0; an inherited LLAMA_ARG_MMPROJ loads even through --no-mmproj; under the vision switch only audio-only survives."""
    from core.inference.llama_cpp import (
        _extra_args_device,
        _mmproj_env_is_audio_only,
        extra_args_disable_mmproj,
    )

    # An extras --mmproj last-wins, so the child opens the user's projector.
    override = _extra_args_device(extras, {"--mmproj", "-mm"})
    if override and Path(override).is_file() and not extra_args_disable_mmproj(extras):
        if not disable_vision:
            return LlamaCppBackend._get_gguf_size_bytes(override)
        try:
            from utils.models.gguf_metadata import mmproj_accepts_image
            if not mmproj_accepts_image(override):
                return LlamaCppBackend._get_gguf_size_bytes(override)
        except Exception:
            pass
        # Unreadable under the vision switch reads as image-capable, hence dropped, as the loader does.
        return 0

    studio_mmproj = getattr(config, "gguf_mmproj_file", None)
    on_argv = bool(studio_mmproj) and not extra_args_disable_mmproj(extras)
    if on_argv and disable_vision:
        try:
            from utils.models.gguf_metadata import mmproj_accepts_image
            on_argv = not mmproj_accepts_image(str(studio_mmproj))
        except Exception:
            on_argv = False
    if on_argv and Path(str(studio_mmproj)).is_file():
        return LlamaCppBackend._get_gguf_size_bytes(str(studio_mmproj))
    if on_argv:
        return 0
    inherited = (os.environ.get("LLAMA_ARG_MMPROJ") or "").strip()
    if (
        inherited
        and (not disable_vision or _mmproj_env_is_audio_only(inherited))
        and Path(inherited).is_file()
    ):
        return LlamaCppBackend._get_gguf_size_bytes(inherited)
    return 0


def _inherited_drafter_bytes(extras: Optional[list[str]]) -> int:
    """Sizes a drafter inherited only via LLAMA_ARG_SPEC_DRAFT_MODEL; the files term reads an empty env."""
    from core.inference.llama_cpp import _child_spec_env, _extra_args_mtp_draft_path

    if _extra_args_mtp_draft_path(extras, env = {}):
        return 0
    inherited = _extra_args_mtp_draft_path(extras, env = _child_spec_env(extras))
    if not inherited or not Path(str(inherited)).is_file():
        return 0
    try:
        return LlamaCppBackend._get_gguf_size_bytes(str(inherited))
    except Exception:
        return 0


def _inherited_remote_files_unsized(extras: Optional[list[str]], disable_vision: bool) -> bool:
    """True if the inherited env names a remote drafter (LLAMA_ARG_SPEC_DRAFT_HF_REPO or LLAMA_ARG_HFD_REPO) or projector (LLAMA_ARG_MMPROJ_URL); total is a floor."""
    from core.inference.llama_cpp import _child_spec_env

    spec_env = _child_spec_env(extras)
    for key in ("LLAMA_ARG_SPEC_DRAFT_HF_REPO", "LLAMA_ARG_HFD_REPO"):
        if (spec_env.get(key) or "").strip():
            return True
    if not disable_vision and (os.environ.get("LLAMA_ARG_MMPROJ_URL") or "").strip():
        return True
    return False


def _build_default_spec_draft_n_max(extras: Optional[list[str]] = None) -> int:
    """Default draft depth: inherited LLAMA_ARG_SPEC_* depth wins first, then the build default; never probed, so unprobed assumes the deepest llama.cpp shipped."""
    from core.inference.llama_cpp import _child_spec_env, _is_positive_int

    spec_env = _child_spec_env(extras)
    inherited = next(
        (
            value
            for value in (
                spec_env.get("LLAMA_ARG_SPEC_DRAFT_N_MAX"),
                spec_env.get("LLAMA_ARG_DRAFT_MAX"),
            )
            if _is_positive_int(value)
        ),
        None,
    )
    if inherited is not None:
        return int(str(inherited).strip())
    try:
        binary = LlamaCppBackend._exec_path_for_launch(LlamaCppBackend._find_llama_server_binary())
        stat = os.stat(str(binary))
        caps = LlamaCppBackend._capability_cache.get((str(binary), stat.st_mtime_ns, stat.st_size))
        default = (caps or {}).get("spec_draft_n_max_default")
        return int(default) if default else LlamaCppBackend._UNKNOWN_SPEC_DRAFT_N_MAX
    except Exception:
        return LlamaCppBackend._UNKNOWN_SPEC_DRAFT_N_MAX


def _estimate_spec_mode_terms(
    drafter_kind: str,
    extras: list[str],
    studio_emits_mtp: bool = False,
) -> tuple[bool, bool]:
    """Only true MTP duplicates the target context; a bare --model-draft does not own the mode."""
    from core.inference.llama_cpp import (
        _accumulated_spec_types,
        _child_spec_env,
        _extra_args_set_spec_type,
        _TARGET_ROLLBACK_SPEC_TYPES,
    )

    # Child env: scrubbed of LLAMA_ARG_SPEC_* unless extras own the spec block.
    spec_types = _accumulated_spec_types(extras, env = _child_spec_env(extras))
    if spec_types:
        return (
            bool(spec_types & {"mtp", "draft-mtp"}),
            bool(spec_types & _TARGET_ROLLBACK_SPEC_TYPES),
        )
    if drafter_kind == "extras" and _extra_args_set_spec_type(extras):
        # A --spec-type whose value named no flavour we recognise. Theirs either way.
        return False, False
    if drafter_kind == "extras":
        # Studio still emits the mode; only the file came from the extras.
        return (studio_emits_mtp, True) if studio_emits_mtp else (False, False)
    return drafter_kind == "mtp", True


def _estimate_draft_n_max(
    config: ModelConfig, drafter_path: str, *, requested: Optional[int], extras: list[str]
) -> int:
    """A blank draft depth means the launch default, not zero (zero drops the rollback allocation); an explicit 0 is honored as a request to draft nothing."""
    from core.inference.llama_cpp import _extra_args_set_spec_type, _extra_args_spec_draft_n_max

    depth = _extra_args_spec_draft_n_max(extras)
    if depth is None and _extra_args_set_spec_type(extras):
        # No depth emitted here, so the child uses the build default.
        depth = _build_default_spec_draft_n_max(extras)
    if depth is None:
        depth = requested
    if depth is not None:
        return max(0, int(depth))
    dspark = getattr(config, "gguf_dspark_file", None)
    if dspark and str(dspark) == drafter_path:
        return 3
    try:
        gpus = LlamaCppBackend._effective_gpu_count() > 0
    except Exception:
        gpus = False
    return 2 if gpus else 3


def _embedded_mtp_engages(probe, config, speculative_type, extras) -> bool:
    """Mirrors each no-MTP outcome of _build_speculative_flags; an embedded head has no file to weigh."""
    if not getattr(probe, "_nextn_predict_layers", None):
        return False
    from core.inference.llama_cpp import (
        _MTP_MIN_SIZE_B,
        _canonicalize_spec_mode,
        _extra_args_set_spec_type,
        _extract_model_size_b,
        _mla_mtp_auto_enabled,
    )

    if _extra_args_set_spec_type(extras):
        # --spec-type draft-mtp in extras engages an embedded NextN head.
        from core.inference.llama_cpp import _accumulated_spec_types, _child_spec_env
        return bool(
            _accumulated_spec_types(extras, env = _child_spec_env(extras)) & {"mtp", "draft-mtp"}
        )
    mode = _canonicalize_spec_mode(speculative_type) or "auto"
    if mode not in ("auto", "mtp", "mtp+ngram"):
        return False
    # No mtp_token: build cannot run MTP, even when forced. Drop the term only if the probe ran.
    try:
        caps = LlamaCppBackend.probe_server_capabilities()
        if caps.get("found") and not caps.get("mtp_token"):
            return False
    except Exception as exc:
        logger.debug("MTP capability probe failed while pricing the draft head: %s", exc)

    if mode != "auto":
        # Remaining drops are Auto-only; an explicit request is charged as asked.
        return True
    size_b = _extract_model_size_b(getattr(config, "identifier", None))
    if size_b is not None and size_b < _MTP_MIN_SIZE_B:
        return False
    if getattr(probe, "_kv_lora_rank", None) is not None and not _mla_mtp_auto_enabled():
        return False
    return True


def _tensor_latches_allow_a_split(
    gguf_path: str,
    config: ModelConfig,
    cache_type_kv: Optional[str],
    llama_extra_args: Optional[list[str]],
) -> bool:
    """Checks the in-process latches that silently turn a tensor split into a layer split; fails open."""
    from core.inference.llama_cpp import _planned_main_cache_types
    try:
        binary = LlamaCppBackend._find_llama_server_binary()
        if not binary:
            return True
        pair = _planned_main_cache_types(cache_type_kv, llama_extra_args)
        model = getattr(config, "identifier", None) or gguf_path
        if LlamaCppBackend._tensor_quant_kv_unsupported_binary(binary, pair):
            return False
        return not LlamaCppBackend._tensor_split_aborts(binary, model, pair)
    except Exception as exc:
        logger.debug("Tensor-split latch lookup failed while pricing: %s", exc)
        return True


def _gguf_memory_breakdown(
    config: ModelConfig,
    gguf_path: str,
    *,
    hf_token: Optional[str] = None,
    n_ctx: int = 0,
    llama_extra_args: Optional[list[str]] = None,
    speculative_type: Optional[str] = None,
    n_parallel: int = 1,
    cache_type_kv: Optional[str] = None,
    tensor_parallel: bool = False,
    n_batch: Optional[int] = None,
    n_ubatch: Optional[int] = None,
    ctx_checkpoints: Optional[int] = None,
    n_devices: int = 1,
    is_diffusion: bool = False,
    disable_vision: bool = False,
    gpu_memory_mode: Optional[str] = None,
    gpu_layers: Optional[int] = None,
    spec_draft_n_max: Optional[int] = None,
    spec_draft_cache_type: Optional[str] = None,
    tensor_split_possible: bool = True,
    # A GPU pin owns placement: load_model strips device flags and env before launch.
    device_pin_governs: bool = False,
    selected_gpu_ids: Optional[list[int]] = None,
) -> Optional[_GgufMemoryBreakdown]:
    """None if nothing sizes. Files are cached; the KV and compute buffers are re-derived per call."""
    from core.inference.llama_server_args import (
        _effective_tensor_parallel,
        parse_gpu_layers_override,
        strip_shadowing_flags,
    )

    # Manual: /load folds the last -ngl into the field and strips raw flags; price that list.
    if gpu_memory_mode == "manual" and llama_extra_args:
        try:
            _manual_ngl = parse_gpu_layers_override(llama_extra_args)
        except ValueError:
            _manual_ngl = None
        if _manual_ngl is not None:
            gpu_layers = _manual_ngl
        llama_extra_args = strip_shadowing_flags(
            llama_extra_args,
            strip_context = False,
            strip_cache = False,
            strip_spec = False,
            strip_template = False,
            strip_split_mode = False,
            # _should_strip_tensor_split's rule, from the same two values it reads.
            strip_tensor_split = gpu_layers is not None and gpu_layers >= 0,
            strip_offload = True,
        )

    # Extras --split-mode last-wins; inherited LLAMA_ARG_SPLIT_MODE can enable tensor.
    tensor_parallel = (
        _effective_tensor_parallel(llama_extra_args, tensor_parallel)
        and tensor_split_possible
        # Latches that force a layer split: a build refusing quantized KV under tensor, or a session abort.
        and _tensor_latches_allow_a_split(gguf_path, config, cache_type_kv, llama_extra_args)
        # Extras already lack -ngl and the count carries it, so the inner override lookup is a no-op.
        and _manual_keeps_tensor_split(gpu_memory_mode, gpu_layers, llama_extra_args)
    )
    runtime = _gguf_runtime_bytes(
        gguf_path,
        n_ctx,
        llama_extra_args = llama_extra_args,
        n_parallel = n_parallel,
        cache_type_kv = cache_type_kv,
        tensor_parallel = tensor_parallel,
        n_batch = n_batch,
        n_ubatch = n_ubatch,
        ctx_checkpoints = ctx_checkpoints,
        n_devices = n_devices,
        is_diffusion = is_diffusion,
        # Panel prices the launch: a smaller -c in extras is what the user gets.
        ctx_last_wins = True,
        # Embedding models are recognised from the identifier, so pass the same one /load does.
        model_identifier = getattr(config, "identifier", None),
        launch_required_ubatch = _launch_required_ubatch_for_config(
            config, llama_extra_args, disable_vision
        ),
    )
    files_gb = _gguf_resident_file_gb(
        config,
        hf_token = hf_token,
        llama_extra_args = llama_extra_args,
        speculative_type = speculative_type,
        disable_vision = disable_vision,
        # No Hub listing per slider change: --spec-draft-hf left uncharged and marked below.
        local_only = True,
        tensor_parallel = tensor_parallel,
    )
    if files_gb is None:
        return None
    from core.inference.llama_cpp import (
        _canonicalize_spec_mode,
        _device_selection_is_cpu,
        _extra_args_draft_cache_types,
        _extra_args_draft_offloaded_to_cpu,
        _extra_args_mtp_draft_source,
        _kv_offload_from_args,
        _resolved_mmproj_offload,
    )

    gpu_files_bytes = int(round(files_gb * (1024**3)))
    extras = list(llama_extra_args or ())
    # --lora/--control-vector adapters are resident (not mmapped) and scale with layer fraction.
    from core.inference.llama_cpp import _sidecar_adapter_bytes

    adapter_bytes = _sidecar_adapter_bytes(extras)
    # None means engaged but unsized; show a floor with the marker.
    adapters_unsized = adapter_bytes is None
    adapter_bytes = adapter_bytes or 0
    files_probe = dict(
        hf_token = hf_token,
        speculative_type = speculative_type,
        disable_vision = disable_vision,
        local_only = True,
        tensor_parallel = tensor_parallel,
    )

    def _files_bytes_with(extra: tuple[str, ...]) -> Optional[int]:
        gb = _gguf_resident_file_gb(config, llama_extra_args = extras + list(extra), **files_probe)
        return None if gb is None else int(round(gb * (1024**3)))

    # CPU-pinned drafter bytes belong in the host total. Bound before the branch (UnboundLocalError).
    host_drafter_bytes = 0
    gpu_drafter_bytes = 0
    if _extra_args_draft_offloaded_to_cpu(extras):
        unpinned = _files_bytes_with(_DRAFT_FORCE_GPU_ARGS)
        if unpinned is not None and unpinned > gpu_files_bytes:
            host_drafter_bytes = unpinned - gpu_files_bytes
    else:
        no_drafter = _files_bytes_with(_DRAFT_FORCE_CPU_ARGS)
        if no_drafter is not None:
            gpu_drafter_bytes = max(0, gpu_files_bytes - no_drafter)
    if not (host_drafter_bytes or gpu_drafter_bytes):
        # Child inherits LLAMA_ARG_SPEC_DRAFT_MODEL once extras own --spec-type.
        inherited = _inherited_drafter_bytes(extras)
        if inherited:
            if _extra_args_draft_offloaded_to_cpu(extras):
                host_drafter_bytes = inherited
            else:
                gpu_drafter_bytes = inherited
                gpu_files_bytes += inherited
    weights_bytes = gpu_files_bytes + host_drafter_bytes + adapter_bytes

    # Drafter KV and rollback state, priced wherever the drafter lives.
    drafter_runtime_bytes = 0
    # Allocated in the target's context, so it stays with the target when placed apart.
    target_spec_bytes = 0
    # The verification output rows in that reserve: target compute, not target KV.
    target_verify_bytes = 0
    drafter_on_gpu = host_drafter_bytes == 0
    charged_drafter = _charged_drafter_path(
        config, host_drafter_bytes or gpu_drafter_bytes, extras = extras
    )
    # Embedded NextN head has no file but still allocates draft KV; safe to price unconditionally.
    probe = _probe_backend()
    probe._read_gguf_metadata(gguf_path)
    embedded_mtp = bool(
        not charged_drafter and _embedded_mtp_engages(probe, config, speculative_type, extras)
    )
    # Not re-placed by draft-only pins: an embedded head keeps the target's placement.
    if charged_drafter or embedded_mtp:
        drafter_path, drafter_kind = charged_drafter or (None, "mtp")
        # Ask extras alone, then env alone, to get launch precedence: extras > field > env.
        draft_k, draft_v = _extra_args_draft_cache_types(extras, env = {})
        env_draft_k, env_draft_v = _extra_args_draft_cache_types([], env = os.environ)
        # The field reaches argv only on builds with the flag; drop it only if the probe ran.
        _managed_draft_cache = True
        try:
            _dc_caps = LlamaCppBackend.probe_server_capabilities()
            # BOTH: the launcher emits the pair or neither.
            if _dc_caps.get("found") and not (
                _dc_caps.get("spec_draft_cache_k_flag") and _dc_caps.get("spec_draft_cache_v_flag")
            ):
                _managed_draft_cache = False
        except Exception as _dc_exc:
            logger.debug("draft cache-type capability probe failed: %s", _dc_exc)
        _field_draft_cache = spec_draft_cache_type if _managed_draft_cache else None
        draft_n_max = _estimate_draft_n_max(
            config, drafter_path, requested = spec_draft_n_max, extras = extras
        )
        keeps_target_ctx, target_rollback = _estimate_spec_mode_terms(
            drafter_kind,
            extras,
            # Asked of the header: the predicate that engages an embedded head also gates draft-mtp emission.
            studio_emits_mtp = embedded_mtp
            or _embedded_mtp_engages(probe, config, speculative_type, extras),
        )
        # Use the target's layout, not helper defaults, or the drafter cache is under-priced.
        _draft_v_type = draft_v or _field_draft_cache or env_draft_v
        layout = dict(
            swa_full = runtime.swa_full,
            kv_unified = runtime.kv_unified,
            n_ubatch = runtime.n_ubatch,
            flash_attn = bool(_draft_v_type) and _draft_v_type not in {"f16", "bf16", "f32"},
        )
        # The draft decode graph is charged on top; the helper prices only its growth past this floor.
        drafter_runtime_bytes = getattr(probe, "_MTP_DRAFT_COMPUTE_BYTES", 0) + (
            probe._estimate_mtp_overhead_bytes(
                runtime.n_ctx,
                spec_draft_n_max = draft_n_max,
                draft_cache_type_k = draft_k or _field_draft_cache or env_draft_k,
                draft_cache_type_v = draft_v or _field_draft_cache or env_draft_v,
                drafter_path = drafter_path,
                # The file is already in weights_bytes; this term is runtime only.
                draft_weights_bytes = 0,
                n_parallel = runtime.n_parallel,
                mtp_keeps_target_ctx = keeps_target_ctx,
                target_rollback = target_rollback,
                **layout,
            )
            or 0
        )
        # MLA KV copy and hybrid rollback state live in the target's context.
        if keeps_target_ctx and probe._kv_lora_rank is not None:
            # Same layout as the helper, so the subtraction names the same bytes.
            target_spec_bytes += probe._estimate_kv_cache_bytes(
                runtime.n_ctx, "f16", n_parallel = runtime.n_parallel, **layout
            )
        if target_rollback and draft_n_max > 0:
            target_spec_bytes += (
                probe._mamba_recurrent_state_bytes(runtime.n_parallel) * draft_n_max
            )
        target_spec_bytes = min(target_spec_bytes, drafter_runtime_bytes)
        target_verify_bytes = min(
            probe._spec_verify_rows_bytes(runtime.n_parallel, draft_n_max),
            drafter_runtime_bytes - target_spec_bytes,
        )

    layer_count = runtime.layer_count
    gpu_fraction = _gguf_offloaded_layer_fraction(
        gpu_memory_mode, gpu_layers, layer_count, extras, device_pin_governs = device_pin_governs
    )

    # Only the main weight is split by --gpu-layers; companions have their own placement flags.
    main_bytes = min(gpu_files_bytes, LlamaCppBackend._get_gguf_size_bytes(gguf_path))
    companion_bytes = max(0, gpu_files_bytes - main_bytes)
    from core.inference.llama_cpp import (
        _effective_lazy_mode,
        _is_per_layer_embedding,
        _override_places_tensor_on_device,
        _without_torch_gpu_probe,
    )
    from hub.utils.gguf_lookup_tables import local_lookup_info

    _lt_backend = get_llama_cpp_backend()
    try:
        _lt_flag = str(
            _lt_backend.probe_server_capabilities().get("lazy_mode_flag") or "--lazy-mode"
        )
    except Exception:  # noqa: BLE001 -- unknown build: the default spelling
        _lt_flag = "--lazy-mode"
    _lt_arch, _lt_bytes = local_lookup_info(
        gguf_path,
        "on" if _effective_lazy_mode(extras, os.environ, flag = _lt_flag) == "on" else "auto",
    )
    lookup_table_bytes = min(main_bytes, _lt_bytes)
    lookup_table_on_disk = False
    _lt_extras, _lt_env = extras, dict(os.environ)
    if selected_gpu_ids or device_pin_governs:
        _lt_extras = LlamaCppBackend._strip_device_extra_args(extras)
        LlamaCppBackend._clear_device_placement_env(_lt_env)
    if gpu_memory_mode == "manual":
        LlamaCppBackend._clear_manual_placement_env(_lt_env)
    LlamaCppBackend._reconcile_split_mode_env(_lt_env, tensor_parallel = bool(tensor_parallel))
    if lookup_table_bytes:
        lookup_table_on_disk = _lt_backend.lookup_tables_stream_by_default(
            _lt_extras,
            _lt_env,
            gpu_ids = selected_gpu_ids,
            tensor_parallel = tensor_parallel,
        )
    if not lookup_table_on_disk:
        try:
            _lt_scan = _lt_backend._gguf_tensor_scan(gguf_path)
        except Exception:  # noqa: BLE001 -- unread header: keep the lazy answer
            _lt_scan = None
        if _lt_scan:
            _lt_arch = _lt_arch or _lt_scan[0]
            _resident = sum(
                int(v) for k, v in (_lt_scan[1] or {}).items() if _is_per_layer_embedding(k)
            )
            lookup_table_bytes = min(main_bytes, max(lookup_table_bytes, _resident))

    def _lt_override_moves_table() -> bool:
        if _lt_arch in _lt_backend._host_forced_table_archs():
            return False  # this build keeps the table on the host whatever -ot says
        try:
            scan = _lt_backend._gguf_tensor_scan(gguf_path)
        except Exception:  # noqa: BLE001 -- unread header: the canonical name alone
            scan = None
        names = [k for k in ((scan[1] if scan else None) or {}) if _is_per_layer_embedding(k)]
        return any(
            _override_places_tensor_on_device(name, _lt_extras, _lt_env)
            for name in names or ["per_layer_token_embd.weight"]
        )

    _lt_device_bytes = 0
    if lookup_table_bytes:
        if not lookup_table_on_disk and _lt_override_moves_table():
            _lt_device_bytes, lookup_table_bytes = lookup_table_bytes, 0
    if lookup_table_on_disk:
        from core.inference.llama_cpp import (
            _HOST_RAM_HEADROOM_MIB,
            _LAZY_MODE_SPELLINGS,
            _LAZY_RESIDENT_MARGIN_FRAC,
            _extra_args_set_any_flag,
            _kv_offload_from_args,
            _device_selection_is_cpu,
            _pass_through_overrides_placement,
            _pass_through_reprices_cache,
            _prompt_cache_host_bytes,
            _sidecar_adapter_bytes,
            _sidecar_adapter_paths,
        )
        from core.inference.llama_server_args import fit_target_margin_in, resolve_requested_ctx

        _lt_flags, _lt_env_name = _LAZY_MODE_SPELLINGS.get(_lt_flag, (frozenset({_lt_flag}), ""))
        _lt_user = bool(
            (_lt_env_name and str(_lt_env.get(_lt_env_name) or "").strip())
            or _extra_args_set_any_flag(_lt_extras, _lt_flags)
        )
        _lt_avail = LlamaCppBackend._available_system_memory_mib()
        _lt_device_share = max(0, main_bytes - lookup_table_bytes)
        _lt_forced_host = int(_lt_device_share * max(0.0, 1.0 - gpu_fraction))
        _lt_table_host = lookup_table_bytes + int(lookup_table_bytes * _LAZY_RESIDENT_MARGIN_FRAC)

        def _lt_resident_fits() -> bool:
            if not _lt_avail or not runtime.kv_estimable:
                return False  # unsized: the launch keeps llama.cpp's default too
            if _sidecar_adapter_bytes(_lt_extras) is None:
                return False
            # A pass-through -c 0 or larger --parallel sizes a cache runtime did not price.
            if _pass_through_reprices_cache(_lt_extras, n_parallel):
                return False
            # A CPU child keeps llama.cpp's default; Manual Auto layers without a context leave it
            # to --fit.
            if _lt_backend._child_runs_on_cpu(
                _lt_backend._find_llama_server_binary(),
                _lt_extras,
                _lt_env,
                cpu_forced = bool(_gpu_placement_paravirtual()),
                tensor_parallel = bool(tensor_parallel),
            ):
                return False
            _lt_manual = gpu_memory_mode == "manual"
            if (
                _lt_manual
                and (gpu_layers if gpu_layers is not None else -1) < 0
                and resolve_requested_ctx(_lt_extras, n_ctx) <= 0
            ):
                return False
            prompt = _prompt_cache_host_bytes(
                None,
                _lt_extras,
                _lt_env,
                supports_cache_ram = bool(
                    (_lt_backend.probe_server_capabilities() or {}).get("supports_cache_ram")
                ),
            )
            if prompt is None:
                return False
            host_only = _lt_forced_host + _lt_table_host + prompt
            if not _kv_offload_from_args(_lt_extras, env = _lt_env):
                host_only += runtime.kv_bytes
            if not drafter_on_gpu:
                host_only += host_drafter_bytes + drafter_runtime_bytes
            _lt_mm = _charged_projector_bytes(config, extras, disable_vision)
            _lt_mm = _lt_mm if _lt_mm and _lt_mm <= companion_bytes else 0
            _lt_mm_runtime = int(_lt_mm * (LlamaCppBackend._MMPROJ_VRAM_SAFETY - 1.0))
            if _lt_mm and _resolved_mmproj_offload(llama_extra_args) is False:
                host_only += _lt_mm + _lt_mm_runtime
            footprint = (
                _lt_device_share
                + companion_bytes
                + host_drafter_bytes
                + _lt_mm_runtime
                + adapter_bytes
                + runtime.kv_bytes
                + runtime.compute_bytes
                + drafter_runtime_bytes
                + _lt_table_host
                + prompt
            )
            from utils.hardware import is_apple_silicon

            if is_apple_silicon():
                if _sidecar_adapter_paths(_lt_extras):
                    return False
                budget = _lt_backend._apple_metal_memory_budget_bytes()
                if budget <= 0:
                    return False
                # Metal refuses past the wired limit: None is unknown, 0 used up.
                wired = _lt_backend._apple_metal_wired_headroom_bytes()
                if wired is not None:
                    budget = min(budget, wired)
                if budget <= 0:
                    return False
                return footprint <= min(
                    budget, max(0, _lt_avail - _HOST_RAM_HEADROOM_MIB) * 1024 * 1024
                )
            try:
                with _without_torch_gpu_probe():
                    rows = list(
                        _lt_backend._get_gpu_memory(
                            _lt_backend._find_llama_server_binary(), for_llama_server = True
                        )
                        or ()
                    )
            except Exception:  # noqa: BLE001 -- unread cards: the whole load in RAM
                rows = []
            pick = sorted(int(i) for i in selected_gpu_ids) if selected_gpu_ids else None
            _lt_vulkan = LlamaCppBackend._is_vulkan_backend()
            # Manual mode plans no cards at launch (gpus = []): the whole load is RAM.
            if (
                not rows
                or _lt_manual
                or _pass_through_overrides_placement(
                    _lt_extras,
                    _lt_env,
                    len(pick) if pick is not None else len(rows),
                    is_vulkan_backend = _lt_vulkan,
                    gpu_indices = pick,
                )
            ):
                rows, pick = [], None
            _lt_rows = [(idx, free) for idx, free, _total in rows]
            return bool(
                _lt_backend._fits_without_paging(
                    footprint,
                    _lt_rows,
                    gpu_indices = pick,
                    # Vulkan reports total 0 for an iGPU; ROCm APUs and integrated CUDA SoCs pool
                    # host RAM.
                    shared_gpu_ids = _lt_backend._unified_pool_gpu_ids(
                        _lt_rows,
                        gpu_indices = pick,
                        shared_gpu_ids = (
                            {idx for idx, _free, total in rows if total <= 0}
                            if _lt_vulkan
                            else set()
                        ),
                        is_vulkan_backend = _lt_vulkan,
                    ),
                    host_only_bytes = host_only,
                    vram_margin_mib = max(1024.0, fit_target_margin_in(_lt_extras, _lt_env) or 0.0),
                    avail_mib = _lt_avail,
                )
            )

        if not _lt_user and not _lt_override_moves_table() and _lt_resident_fits():
            lookup_table_on_disk = False
    if lookup_table_on_disk:
        weights_bytes = max(0, weights_bytes - lookup_table_bytes)
    # Projector is the only charged companion that can sit off-GPU (--no-mmproj-offload).
    host_companion_bytes = 0
    # The projector costs more than its file: the encoder's buffers run about 1.3x it,
    # which the placement path budgets as _MMPROJ_VRAM_SAFETY - 1. Charged whenever the
    # projector is in the resident set, and it is in the total wherever it sits, so a
    # near-capacity multimodal load is not called a fit on the file size alone.
    projector_runtime_bytes = 0
    mmproj_bytes = _charged_projector_bytes(config, extras, disable_vision)
    if mmproj_bytes and mmproj_bytes <= companion_bytes:
        # <= companion_bytes: the projector must be in the charged set to be this launch's.
        projector_runtime_bytes = int(mmproj_bytes * (LlamaCppBackend._MMPROJ_VRAM_SAFETY - 1.0))
        if _resolved_mmproj_offload(llama_extra_args) is False:
            host_companion_bytes = min(companion_bytes, mmproj_bytes)
    gpu_weights = (
        int((main_bytes - lookup_table_bytes - _lt_device_bytes) * gpu_fraction)
        + _lt_device_bytes
        + int(adapter_bytes * gpu_fraction)
        + companion_bytes
        - host_companion_bytes
    )
    # --spec-draft-hf drafter: cache unsized without a local header, so the total is a floor.
    drafter_kv_unsized = bool(
        ((host_drafter_bytes or gpu_drafter_bytes) and not charged_drafter)
        # Inherited remote drafter or projector URLs cannot be weighed locally, so the total is a floor.
        or _inherited_remote_files_unsized(extras, disable_vision)
        # Extras' --spec-draft-hf repo is uncharged; listing it per settings change would hit the network.
        or bool(_extra_args_mtp_draft_source(extras)[1])
    )
    runtime_bytes = (
        runtime.kv_bytes + runtime.compute_bytes + drafter_runtime_bytes + projector_runtime_bytes
    )

    # -nkvo puts the cache in host RAM.
    kv_on_gpu = _kv_offload_from_args(llama_extra_args) and gpu_fraction > 0.0
    # Context checkpoints are host heap (--cache-ram); excluded from the GPU figure.
    gpu_kv_bytes = max(0, runtime.kv_bytes - runtime.kv_checkpoint_bytes)
    # Cache follows its layer's device; scale linearly by offloaded fraction (exact at 0 and full).
    gpu_bytes = gpu_weights + (int(gpu_kv_bytes * gpu_fraction) if kv_on_gpu else 0)
    if gpu_fraction > 0.0:
        # Compute buffers land on the devices running layers.
        gpu_bytes += runtime.compute_bytes
    # A separate drafter ignores --gpu-layers; an embedded head goes where the target goes.
    _drafter_on_gpu = (gpu_fraction > 0.0) if embedded_mtp else drafter_on_gpu
    drafter_runtime_gpu_bytes = (
        (target_spec_bytes if kv_on_gpu else 0)
        + (target_verify_bytes if gpu_fraction > 0.0 else 0)
        + (
            (drafter_runtime_bytes - target_spec_bytes - target_verify_bytes)
            if _drafter_on_gpu
            else 0
        )
    )
    gpu_bytes += drafter_runtime_gpu_bytes
    # Encoder buffers sit with the projector; --no-mmproj-offload moves them to host RAM too.
    if not host_companion_bytes:
        gpu_bytes += projector_runtime_bytes
    if not device_pin_governs and (
        _device_selection_is_cpu(extras, os.environ) or _estimate_host_has_no_gpu()
    ):
        # No GPU given or present: zero even for companions, which ignore --gpu-layers; a GPU pin overrides both readings.
        gpu_bytes = 0
        drafter_runtime_gpu_bytes = 0
    return _GgufMemoryBreakdown(
        weights_bytes = weights_bytes,
        kv_bytes = runtime.kv_bytes,
        compute_bytes = runtime.compute_bytes,
        drafter_runtime_bytes = drafter_runtime_bytes,
        drafter_runtime_gpu_bytes = drafter_runtime_gpu_bytes,
        projector_runtime_bytes = projector_runtime_bytes,
        drafter_kv_unsized = drafter_kv_unsized,
        adapters_unsized = adapters_unsized,
        total_bytes = weights_bytes + runtime_bytes,
        gpu_bytes = gpu_bytes,
        kv_estimable = runtime.kv_estimable,
        kv_on_gpu = kv_on_gpu,
        n_ctx = runtime.n_ctx,
        cache_type_kv = runtime.cache_type_kv,
        n_parallel = runtime.n_parallel,
        layer_count = layer_count,
        gpu_layers = gpu_layers if gpu_memory_mode == "manual" else None,
        kv_checkpoint_bytes = runtime.kv_checkpoint_bytes,
        lookup_table_bytes = lookup_table_bytes,
        lookup_table_on_disk = lookup_table_on_disk,
    )


def _guard_device_count(
    requested_gpu_ids: Optional[list[int]],
    vulkan_gpu_memory: Optional[list[tuple[int, int, int]]] = None,
    *,
    tensor_parallel: bool = False,
) -> int:
    """Tensor uses the whole pool (pin, else Vulkan, else CUDA); auto layer split is modeled as fewest GPUs, an approximation that under-charges big models."""
    if not tensor_parallel:
        return max(1, len(requested_gpu_ids or ()))
    if not requested_gpu_ids and vulkan_gpu_memory:
        return max(1, len(vulkan_gpu_memory))
    return max(1, LlamaCppBackend._effective_gpu_count(requested_gpu_ids))


def _gguf_layer_count(config: ModelConfig) -> Optional[int]:
    """Total block count from a local GGUF header, or None (remote / unreadable)."""
    try:
        main = getattr(config, "gguf_file", None)
        if not (main and Path(main).is_file()):
            repo = getattr(config, "gguf_hf_repo", None)
            variant = getattr(config, "gguf_variant", None)
            if repo and variant:
                from hub.utils.gguf import resolve_local_gguf_path
                main = resolve_local_gguf_path(repo, variant)
        if main and Path(main).is_file():
            probe = _probe_backend()
            probe._read_gguf_metadata(str(main))
            return getattr(probe, "_n_layers", None) or None
    except Exception as e:
        logger.debug("Could not read GGUF layer count for training guard: %s", e)
    return None


def _local_gguf_main_path(config: ModelConfig) -> Optional[str]:
    """Main GGUF path once downloaded, else None; callers fall back rather than reach for the network."""
    main = getattr(config, "gguf_file", None)
    if main and Path(main).is_file():
        return str(main)
    repo = getattr(config, "gguf_hf_repo", None)
    variant = getattr(config, "gguf_variant", None)
    if repo and variant:
        from hub.utils.gguf import resolve_local_gguf_path
        main = resolve_local_gguf_path(repo, variant)
        if main and Path(main).is_file():
            return str(main)
    return None


def _mlx_estimate_ceiling(model_dir: str) -> Optional[int]:
    """The window this checkpoint declares, held to what a load may be asked for."""
    from core.inference.mlx_inference import mlx_checkpoint_window
    return mlx_checkpoint_window(model_dir)


def _mlx_estimate_fitted_context(config, model_dir: str, load_in_4bit: bool, kv_bits, **route):
    """The window a load naming no Context Length would be fitted to."""
    from core.inference.mlx_inference import (
        mlx_fit_to_memory,
        mlx_vlm_snapshot_store_available,
    )

    ceiling = _mlx_estimate_ceiling(model_dir)
    if not ceiling:
        return None
    return mlx_fit_to_memory(
        model_dir,
        ceiling,
        load_in_4bit = load_in_4bit,
        retains_history = (
            not getattr(config, "is_vision", False) or mlx_vlm_snapshot_store_available()
        ),
        kv_bits = kv_bits,
        **route,
    )


def _mlx_estimate_offload(
    request, config, model_identifier, model_dir: str, load_in_4bit: bool, kv_bits: Optional[int]
) -> tuple[dict, tuple, Optional[dict]]:
    """``({"offload": (ple, experts)} or {}, offloadable parts, baseline route)`` for an MLX load of
    *request*, "auto" decided as the load does, on its route, with the target-only route an auto
    drafter's costless check measures against; none of them if the load quantizes, which unsloth_zoo
    refuses."""
    from core.inference import mlx_speculative
    from core.inference.mlx_inference import (
        mlx_offload_route,
        mlx_resolve_drafter_offload,
        mlx_vlm_snapshot_store_available,
        normalize_mlx_offload,
    )
    from core.inference.mlx_memory import _snapshot_config, mlx_offloadable_parts

    checkpoint = _snapshot_config(model_dir) or {}
    if load_in_4bit and not (
        checkpoint.get("quantization") or checkpoint.get("quantization_config")
    ):
        return {}, (), None
    vision = True if _mlx_estimate_speculates(request, model_dir) else None
    try:
        parts = mlx_offloadable_parts(model_dir, vision)
    except Exception as exc:
        logger.info("MLX offload eligibility unknown for %s: %s", model_dir, exc)
        parts = ()
    drafter = vision and mlx_speculative.offload_drafter(
        request.speculative_type,
        request.spec_draft_model,
        model_dir = model_dir,
        target_name = model_identifier,
        allowed = _discoverable_drafters(model_identifier),
    )
    offload, alone = mlx_resolve_drafter_offload(
        model_dir,
        (
            normalize_mlx_offload(request.mlx_ple_offload),
            normalize_mlx_offload(request.mlx_expert_offload),
        ),
        drafter or None,
        auto = mlx_speculative.mlx_spec_mode(request.speculative_type) == "auto",
        pinned = request.max_seq_length or None,
        load_in_4bit = load_in_4bit,
        # As the load: any mlx-vlm route, a speculative text load included, keeps no history without the store.
        retains_history = (
            not (getattr(config, "is_vision", False) or vision)
            or mlx_vlm_snapshot_store_available()
        ),
        kv_bits = kv_bits,
        vision = vision,
    )
    *offload, step = offload
    route = {"offload": tuple(offload)} if any(offload) else {}
    route = {**route, "prefill_chunk": step} if step else route
    return route, parts, alone and mlx_offload_route(alone)


def _mlx_offload_warning(info: dict) -> Optional[str]:
    """What an MLX load tells the user when its automatic offload put weights on disk."""
    offload = info.get("mlx_offload") or {}
    parts = [
        f"{round(applied * 100)}% of its {what}"
        for part, what in (("ple", "per-layer embedding tables"), ("experts", "MoE experts"))
        if (applied := (offload.get(part) or {}).get("applied"))
        and offload[part]["requested"] in (None, "auto")
    ]
    if not parts:
        return None
    return (
        f"To fit in memory, this model reads {' and '.join(parts)} from disk (automatic offload), "
        "so it generates more slowly. Set offload to Off to keep them in memory."
    )


def _mlx_estimate_speculates(request, model_dir) -> bool:
    from core.inference import mlx_speculative
    from core.inference.mlx_inference import parse_mlx_kv_quant
    from core.inference.mlx_memory import _loads_as_vision, _snapshot_config

    mode = mlx_speculative.mlx_spec_mode(request.speculative_type)
    if not mlx_speculative.speculates_on_route(
        mode, _loads_as_vision(_snapshot_config(model_dir) or {}), request.spec_draft_model
    ):
        return False
    bits, turboquant = parse_mlx_kv_quant(request.mlx_kv_quant)
    legacy_bits = request.mlx_kv_quant is None and request.mlx_kv_bits is not None
    kv_quant = bits is not None or turboquant or legacy_bits
    return not mlx_speculative.speculation_refusal(kv_quant = kv_quant, distributed = False, lora = False)


def _mlx_estimate_drafter(
    request,
    model_identifier,
    model_dir,
    ceiling,
    load_in_4bit: bool,
    offload_route: Optional[dict] = None,
    baseline: Optional[dict] = None,
):
    """``((path, builtin), fitted context, speculates)`` of an MLX load of *request*: the drafter it
    would attach, chosen as the load chooses it, and whether it speculates at all (so loads through mlx-vlm)."""
    from core.inference import mlx_speculative
    from core.inference.mlx_inference import mlx_drafter_fit

    if not _mlx_estimate_speculates(request, model_dir):
        return None, None, False
    mode = mlx_speculative.mlx_spec_mode(request.speculative_type)
    resolution = mlx_speculative.resolve_speculation(
        request.speculative_type,
        request.spec_draft_model,
        model_dir = model_dir,
        target_name = model_identifier,
        allowed = _discoverable_drafters(model_identifier),
    )
    for source in resolution.sources:
        attaches, fitted = mlx_drafter_fit(
            model_dir,
            ceiling,
            request.max_seq_length or None,
            source,
            load_in_4bit = load_in_4bit,
            costless = mode == "auto",
            baseline = baseline,
            **(offload_route or {}),
        )
        if attaches:
            return (source.path, source.builtin), fitted, True
    return None, None, True


class _MlxLoadEstimate(NamedTuple):
    breakdown: Any
    fitted_ctx: Optional[int]
    offloadable: tuple
    retains_history: bool
    offloaded: bool = False


def _mlx_load_estimate(
    request, config, model_identifier
) -> tuple[Optional[str], Optional[_MlxLoadEstimate]]:
    """``(refusal reason, None)`` or ``(None, estimate)`` of what an MLX load of *request* occupies."""
    if not _mlx_estimate_available():
        return "not_gguf", None
    from core.inference.native_audio import is_native_audio_model

    if getattr(config, "audio_cpp", None) is not None or is_native_audio_model(model_identifier):
        return "not_gguf", None
    if getattr(config, "is_lora", False):
        return "unsizable", None
    model_dir = _local_mlx_model_dir(config)
    if not model_dir:
        return "not_downloaded", None
    from core.inference.mlx_inference import (
        mlx_kv_quant_is_refused,
        mlx_vlm_snapshot_store_available,
    )
    from core.inference.mlx_memory import mlx_memory_breakdown

    load_in_4bit = _mlx_estimate_load_in_4bit(config, request)
    kv_bits = _mlx_estimate_kv_bits(request.mlx_kv_quant, request.mlx_kv_bits)
    # A width the cache takes makes the window a budget, pinned or fit.
    if kv_bits is not None and mlx_kv_quant_is_refused(model_dir, kv_bits):
        kv_bits = None
    named_ctx = request.max_seq_length or 0
    offload, offloadable, offload_baseline = _mlx_estimate_offload(
        request, config, model_identifier, model_dir, load_in_4bit, kv_bits
    )
    drafter, fitted_ctx, speculates = _mlx_estimate_drafter(
        request,
        model_identifier,
        model_dir,
        _mlx_estimate_ceiling(model_dir),
        load_in_4bit,
        offload,
        offload_baseline,
    )
    route = {**({"vision": True} if speculates else {}), **offload}
    if not named_ctx and drafter is None:
        fitted_ctx = _mlx_estimate_fitted_context(config, model_dir, load_in_4bit, kv_bits, **route)
    priced_ctx = named_ctx or fitted_ctx or _mlx_estimate_ceiling(model_dir)
    if not priced_ctx:
        return "unsizable", None
    breakdown = mlx_memory_breakdown(
        model_dir,
        n_ctx = priced_ctx,
        kv_bits = kv_bits,
        load_in_4bit = load_in_4bit,
        **route,
        **({} if drafter is None else {"drafter": drafter}),
    )
    if breakdown is None:
        return "unsizable", None
    retains_history = (
        not (getattr(config, "is_vision", False) or speculates)
        or mlx_vlm_snapshot_store_available()
    )
    return None, _MlxLoadEstimate(
        breakdown, fitted_ctx, offloadable, retains_history, "offload" in offload
    )


def _mlx_chat_need(
    request,
    config,
    model_identifier,
    slots: int = 1,
) -> Optional[tuple[int, dict]]:
    """``(need MiB, growth)`` of an MLX chat load serving ``slots`` rows, or None; rows prefill as one batch."""
    if getattr(config, "is_gguf", False) or not _unified_metal_host():
        return None
    try:
        _, estimate = _mlx_load_estimate(request, config, model_identifier)
        # Offload workspaces allocate at prefill but are priced as weights.
        if estimate is None or estimate.offloaded:
            return None
        from core.inference.mlx_inference import mlx_memory_budget

        reserve = 0
        if estimate.retains_history:
            without, within = (
                mlx_memory_budget(retains_history = False),
                mlx_memory_budget(retains_history = True),
            )
            reserve = max(0, (without or 0) - (within or 0))
    except Exception as exc:
        logger.info("MLX load of %s left unpriced: %s", model_identifier, exc)
        return None
    from core.inference.llama_server_args import clamp_parallel_slots

    mib = 1024 * 1024
    one_row = -(-(int(estimate.breakdown.total_bytes) + reserve) // mib)
    row = -(-int(estimate.breakdown.kv_bytes + estimate.breakdown.compute_bytes) // mib)
    slots = clamp_parallel_slots(slots)
    growth = {
        "mib": max(0, one_row - int(estimate.breakdown.weights_bytes) // mib),
        "row_mib": row,
        "slots": slots,
    }
    return one_row + (slots - 1) * row, growth


def _mlx_estimate_available() -> bool:
    """Whether this host would actually run the load through MLX."""
    try:
        from utils.mlx_repair import is_apple_silicon, mlx_stack_blockers
    except Exception:
        return False
    try:
        return bool(is_apple_silicon() and not mlx_stack_blockers())
    except Exception:
        return False


def _the_revision_that_loads(snapshots: list) -> list:
    """Just the revision `main` names, where it names one that is here."""
    from hub.utils.hf_cache_state import ref_snapshot_dir

    paths = [Path(snapshot) for snapshot in snapshots]
    if not paths:
        return paths
    pinned = ref_snapshot_dir(paths[0].parent.parent)
    return [pinned] if pinned is not None else paths


def _local_mlx_model_dir(config: ModelConfig) -> Optional[str]:
    def _complete(directory: Path, shards) -> bool:
        named = [
            (Path(shard).parent, match)
            for shard in shards
            if (match := _re.fullmatch(r"(.+)-(\d+)-of-(\d+)\.safetensors", Path(shard).name))
        ]
        if not named:
            return _index_agrees(directory)
        for parent, match in named:
            stem, total = match.group(1), match.group(3)
            width, count = len(match.group(2)), int(total)
            if any(
                not (parent / f"{stem}-{i:0{width}d}-of-{total}.safetensors").is_file()
                for i in range(1, count + 1)
            ):
                return False
        return _index_agrees(directory)

    def _index_agrees(directory: Path) -> bool:
        """Whether an index that describes THIS directory finds all of it here."""
        index = directory / "model.safetensors.index.json"
        if not index.is_file():
            return True
        try:
            with open(index, encoding = "utf-8") as handle:
                weight_map = json.load(handle).get("weight_map", {})
            named = {shard for shard in weight_map.values() if isinstance(shard, str)}
        except (ValueError, OSError, AttributeError):
            return True
        here = {
            path.relative_to(directory).as_posix() for path in directory.glob("**/*.safetensors")
        }
        return not (named & here) or named <= here

    def _usable(path) -> bool:
        directory = Path(path)
        if not directory.is_dir() or not (directory / "config.json").is_file():
            return False
        from core.inference.mlx_memory import mlx_shard_files

        try:
            snapshot = json.loads((directory / "config.json").read_text(encoding = "utf-8"))
        except Exception:
            snapshot = None
        try:
            shards = mlx_shard_files(
                str(directory), snapshot if isinstance(snapshot, dict) else None
            )
        except Exception:
            return False
        if not shards:
            return False
        return _complete(directory, shards)

    folder = None if getattr(config, "is_gguf", False) else getattr(config, "gguf_variant", None)

    def _pick(path) -> Optional[str]:
        target = Path(path) / folder if folder else Path(path)
        return str(target) if _usable(target) else None

    candidate = getattr(config, "path", None)
    if candidate and (found := _pick(candidate)):
        return found
    identifier = candidate or getattr(config, "identifier", None)
    if not identifier or getattr(config, "is_local", False):
        return None
    names = [_mlx_load_identifier(str(identifier))]
    if "/" not in names[0]:
        names.append(f"unsloth/{names[0]}")
    try:
        from utils.models.model_config import _iter_hf_cache_snapshots
        roots = _estimate_hf_cache_roots()
    except Exception:
        return None
    for root in roots or [None]:
        for name in names:
            try:
                snapshots = _iter_hf_cache_snapshots(name, cache_dir = root)
            except Exception:
                continue
            for snapshot in _the_revision_that_loads(list(snapshots)):
                if found := _pick(snapshot):
                    return found
    return None


def _mlx_load_identifier(identifier: str) -> str:
    """The repository the MLX load would actually open, not the one selected."""
    try:
        from unsloth_zoo.mlx.loader import _remap_unsloth_bnb_hub_id_for_mlx
    except Exception:
        return identifier
    try:
        return _remap_unsloth_bnb_hub_id_for_mlx(identifier, None)[0] or identifier
    except Exception:
        return identifier


def _mlx_estimate_load_in_4bit(config, request) -> bool:
    """The 4-bit setting the load resolves, not the one the panel sent."""
    # Same order as the load route: a full-finetune output loads 16-bit before any tier check.
    if not _effective_load_in_4bit(config, request.load_in_4bit):
        return False
    from utils.transformers_version import latest_tier_active_for

    identifier = getattr(config, "identifier", None)
    return not _offline_guarded(
        (identifier, getattr(config, "base_model", None)),
        latest_tier_active_for,
        identifier,
        request.hf_token,
    )


def _mlx_estimate_kv_bits(mlx_kv_quant, mlx_kv_bits = None) -> Optional[int]:
    """The mx.quantize width the load would price, or None for a full-width cache."""
    try:
        from core.inference.mlx_inference import MLX_KV_BITS_CHOICES, parse_mlx_kv_quant
    except Exception:
        return None
    if mlx_kv_quant is None:
        if isinstance(mlx_kv_bits, bool) or not isinstance(mlx_kv_bits, int):
            return None
        return mlx_kv_bits if mlx_kv_bits in MLX_KV_BITS_CHOICES else None
    bits, turboquant = parse_mlx_kv_quant(mlx_kv_quant)
    # TurboQuant's layout is not one the planner prices; the load fits it at full width too.
    if turboquant or bits not in MLX_KV_BITS_CHOICES:
        return None
    return bits


def _is_embedding_gguf(config: ModelConfig) -> bool:
    """Uses the loader's basename hints for an uncached remote GGUF; generic names stay unclassified."""
    try:
        main = _local_gguf_main_path(config)
        if not main:
            return False
        probe = _probe_backend()
        probe._model_identifier = config.identifier
        probe._gguf_path = main
        probe._read_gguf_metadata(main)
        return bool(probe.is_embedding_gguf)
    except Exception as exc:
        logger.debug("Could not identify embedding GGUF for the batch floor: %s", exc)
        return False


def _embedding_clamped_slots(
    config: ModelConfig,
    slots: int,
    *,
    extra_args: Optional[list[str]],
    n_batch: Optional[int],
    n_ubatch: Optional[int],
    n_ctx: Optional[int],
) -> int:
    """Applies the micro-batch clamp --embedding forces, so the batch floor sees the slots that launch."""
    if slots <= 1:
        return max(1, slots)
    if not _is_embedding_gguf(config):
        return slots
    from core.inference.llama_cpp import _emitted_n_batch, _extra_args_n_ubatch

    effective_ubatch = _extra_args_n_ubatch(
        extra_args,
        n_ctx = n_ctx if n_ctx and n_ctx > 0 else None,
        n_batch = _emitted_n_batch(n_batch, slots),
        n_ubatch = n_ubatch,
    )
    if effective_ubatch is None or effective_ubatch >= slots:
        return slots
    # Same floor load_model applies: a degenerate -b 0 resolves to 0, and --parallel 0 is rejected at arg parse.
    return max(1, effective_ubatch)  # allow-slot-clamp: mirrors the load_model clamp


async def _batch_floor_survives_embedding_clamp(
    config: ModelConfig,
    extra_args: Optional[list[str]],
    requested_slots: int,
    request,
    *,
    diffusion_kind: Optional[bool] = None,
) -> bool:
    """Re-checks a refused batch floor against embedding-clamped slots, reading the header only then."""
    from core.inference.llama_server_args import check_batch_floor

    # Off loop: reads the GGUF header and callers serve download progress polls.
    slots = await asyncio.to_thread(
        _embedding_clamped_slots,
        config,
        _effective_parallel_slots(requested_slots, diffusion_kind = diffusion_kind),
        extra_args = extra_args,
        n_batch = getattr(request, "n_batch", None),
        n_ubatch = getattr(request, "n_ubatch", None),
        n_ctx = getattr(request, "max_seq_length", None),
    )
    try:
        check_batch_floor(extra_args, slots)
    except ValueError:
        return False
    return True


def _classify_diffusion_gguf(config: ModelConfig) -> Optional[bool]:
    """Classify a GGUF as diffusion, normal, or unknown before loading."""
    identity = " ".join(
        str(getattr(config, attr, "") or "") for attr in ("identifier", "gguf_hf_repo", "gguf_file")
    ).lower()
    # Only use the specific DiffusionGemma family name as a header fallback.
    name_says_diffusion = "diffusiongemma" in _re.sub(r"[^a-z0-9]+", "", identity)

    try:
        main = _local_gguf_main_path(config)
        if main:
            probe = _probe_backend()
            probe._read_gguf_metadata(main)
            if probe.is_diffusion:
                return True
            if getattr(probe, "_architecture", None):
                return False
    except Exception as e:
        logger.debug("Could not identify diffusion GGUF for training guard: %s", e)
    return True if name_says_diffusion else None


async def _validate_reasoning_budget_preflight(
    config: ModelConfig,
    diffusion_kind: Optional[bool],
    extra_args: Optional[list[str]],
    request: LoadRequest | ValidateModelRequest,
) -> None:
    """Only explicit config counts; an inherited LLAMA_ARG_THINK_BUDGET* env must not reject a load."""
    if not config.is_gguf:
        return
    effective_budget = resolve_reasoning_budget(extra_args, request.reasoning_budget)
    effective_message = resolve_reasoning_budget_message(
        extra_args, request.reasoning_budget_message
    )
    requested = any(
        LlamaCppBackend.reasoning_budget_settings_requested(
            extra_args = extra_args,
            reasoning_budget = effective_budget,
            reasoning_budget_message = effective_message,
        )
    )
    if diffusion_kind and requested:
        raise HTTPException(
            status_code = 400,
            detail = "Reasoning Budget settings are not supported for DiffusionGemma models.",
        )
    if diffusion_kind is None and requested:
        raise HTTPException(
            status_code = 400,
            detail = (
                "Reasoning Budget settings cannot be applied until this GGUF is "
                "downloaded and its architecture can be verified. Load it once with "
                "the default reasoning budget, then apply these settings."
            ),
        )
    if not requested:
        return
    backend = get_llama_cpp_backend()
    try:
        await asyncio.to_thread(
            backend.validate_reasoning_budget_capabilities,
            backend._find_llama_server_binary(),
            extra_args = extra_args,
            reasoning_budget = effective_budget,
            reasoning_budget_message = effective_message,
        )
    except ValueError as exc:
        raise HTTPException(status_code = 400, detail = str(exc)) from exc


async def _override_gpu_ids_still_resolve(
    gpu_ids: List[int], stored_index_kind: str = "physical"
) -> bool:
    """Checks the pin's stored index space first: Vulkan ordinals and CUDA ids name different devices."""
    try:
        from utils.hardware import DeviceType, get_device
        from utils.hardware.hardware import resolve_requested_gpu_ids

        # One hop: resolve_requested_gpu_ids() calls get_device() and waits on the detection lock.
        def _device_and_resolution() -> tuple[object, bool, list]:
            is_vulkan = LlamaCppBackend._is_vulkan_backend()
            return (
                get_device(),
                is_vulkan,
                resolve_requested_gpu_ids(gpu_ids, is_vulkan = is_vulkan),
            )

        device, is_vulkan, resolved = await asyncio.to_thread(_device_and_resolution)
        from utils.hardware.hardware import current_gpu_index_kind

        current_kind = await asyncio.to_thread(current_gpu_index_kind, is_vulkan)
        if stored_index_kind != current_kind:
            return False
        if device == DeviceType.XPU and not is_vulkan:
            # Rejected outright on XPU.
            return False
        if is_vulkan and resolved:
            # Vulkan ordinals are their own index space, so presence needs the ggml probe.
            binary = LlamaCppBackend._find_llama_server_binary()
            if binary:
                probed = {
                    gpu[0]
                    for gpu in await asyncio.to_thread(LlamaCppBackend._get_gpu_memory, binary)
                }
                if not {int(gpu_id) for gpu_id in resolved}.issubset(probed):
                    return False
        return True
    except Exception:
        return False


def _reject_draft_device_with_gpu_ids(
    gpu_ids: Optional[List[int]],
    extra_args: Optional[list[str]],
    *,
    gpu_ids_are_vulkan_ordinals: bool,
) -> None:
    """Reject a physical drafter pin beside Vulkan-ordinal main placement."""
    if not gpu_ids or not gpu_ids_are_vulkan_ordinals:
        return
    draft_device = _extra_args_draft_device_pin(extra_args)
    if draft_device is not None:
        raise HTTPException(
            status_code = 400,
            detail = (
                f"A draft-model device override ('{draft_device}') cannot be combined "
                "with explicit gpu_ids: it would place the speculative drafter outside "
                "the pinned GPUs the training guard budgeted. Remove the draft-device "
                "flag to follow gpu_ids, or set it to none."
            ),
        )


_DIFFUSION_KIND_UNSET = object()


async def _resolve_gguf_gpu_ids_for_request(
    config: ModelConfig,
    gpu_ids: Optional[List[int]],
    *,
    diffusion_kind: Optional[bool] | object = _DIFFUSION_KIND_UNSET,
) -> tuple[Optional[List[int]], bool]:
    """Validate GGUF GPU IDs and report whether they are Vulkan ordinals."""
    if not gpu_ids:
        return None, False

    from utils.hardware import DeviceType, get_device
    from utils.hardware.hardware import resolve_requested_gpu_ids

    llama_backend = get_llama_cpp_backend()
    is_vulkan_build = await asyncio.to_thread(llama_backend.is_vulkan_build)
    if diffusion_kind is _DIFFUSION_KIND_UNSET:
        diffusion_kind = _classify_diffusion_gguf(config)
    confirmed_diffusion = diffusion_kind is True
    definitively_non_diffusion = diffusion_kind is False
    # Off-loop: get_device() waits on the detection lock, i.e. the cold torch import.
    device = await asyncio.to_thread(get_device)
    lacks_gpu_lib = getattr(llama_backend, "_backend_lacks_gpu_lib", None)

    # ROCm is DeviceType.CUDA internally (torch.cuda.*), so this accepts CUDA and ROCm physical IDs.
    diffusion_physical_ids_supported = device == DeviceType.CUDA
    if confirmed_diffusion and not diffusion_physical_ids_supported:
        raise HTTPException(
            status_code = 400,
            detail = (
                "GPU selection (gpu_ids) for DiffusionGemma requires CUDA or ROCm. "
                "Omit gpu_ids on this host."
            ),
        )

    if confirmed_diffusion and is_vulkan_build:
        raise HTTPException(
            status_code = 400,
            detail = (
                "GPU selection (gpu_ids) is not supported for a DiffusionGemma "
                "GGUF on a Vulkan llama.cpp build: the picker uses Vulkan ordinals, "
                "which have no defined mapping to CUDA physical indices. Omit gpu_ids "
                "to use the default device."
            ),
        )

    ids_are_vulkan_ordinals = is_vulkan_build

    if device == DeviceType.XPU and not ids_are_vulkan_ordinals:
        raise HTTPException(
            status_code = 400,
            detail = (
                "GPU selection (gpu_ids) is not supported on Intel XPU. "
                "Omit gpu_ids to use all devices."
            ),
        )

    if (
        device == DeviceType.CUDA
        and not ids_are_vulkan_ordinals
        and definitively_non_diffusion
        and callable(lacks_gpu_lib)
        and await asyncio.to_thread(lacks_gpu_lib)
    ):
        raise HTTPException(
            status_code = 400,
            detail = (
                f"Requested gpu_ids {list(gpu_ids)} but the llama.cpp build has "
                "no GPU backend (CPU-only build); it would ignore the pin and run "
                "on CPU. Omit gpu_ids to run on CPU."
            ),
        )

    try:
        resolved = resolve_requested_gpu_ids(
            gpu_ids,
            is_vulkan = ids_are_vulkan_ordinals,
        )
    except ValueError as exc:
        raise HTTPException(status_code = 400, detail = str(exc)) from exc

    if ids_are_vulkan_ordinals and resolved:
        binary = LlamaCppBackend._find_llama_server_binary()
        if binary:
            probed = {
                gpu[0] for gpu in await asyncio.to_thread(LlamaCppBackend._get_gpu_memory, binary)
            }
            wanted = {int(gpu_id) for gpu_id in resolved}
            if not wanted.issubset(probed):
                raise HTTPException(
                    status_code = 400,
                    detail = (
                        f"Requested Vulkan GPU ordinal(s) {sorted(wanted)} not "
                        f"present. Available Vulkan devices: {sorted(probed)}."
                    ),
                )

    return resolved, ids_are_vulkan_ordinals


class _LoadPlacement(NamedTuple):
    requested_gpu_ids: Optional[List[int]]
    resolved_gpu_ids: Optional[List[int]]
    gpu_ids_are_vulkan_ordinals: bool
    diffusion_kind: Optional[bool]
    native_required_gb: Optional[float] = None
    native_post_handoff_free_gb: Optional[dict[int, float]] = None


class _NativeAudioAvailability(NamedTuple):
    effective_free_gb: dict[int, float]
    reclaimable_gpu_gb: dict[int, float]
    owner_snapshot: tuple[Optional[str], int] = (None, 0)
    # The owner whose memory is credited, when not the last claimant (owner_snapshot[0]).
    credited_owner: Optional[str] = None

    @property
    def credited(self) -> Optional[str]:
        return self.credited_owner or self.owner_snapshot[0]


def _native_audio_post_handoff_free_gb(
    outgoing: Optional[str] = None,
) -> Optional[_NativeAudioAvailability]:
    """Free VRAM after the outgoing Studio owner (``outgoing``, default the last claimant) is torn down, or ``None``.

    Only memory attributable to a backend this CHAT handoff provably evicts is
    credited.  Training, STT, export and unknown/external processes remain in
    the live-used figure.  Missing attribution fails closed.
    """
    import utils.hardware as hardware
    from core.inference.gpu_arbiter import CHAT, DIFFUSION, VIDEO, holds, owner_snapshot

    outgoing_owner = owner_snapshot()
    if (
        outgoing is None
        and outgoing_owner[0] in (DIFFUSION, VIDEO)
        and routed_slot.get() is None
        and holds(CHAT)
    ):
        # A primary load replaces the chat model; an image or video model claimed after it may stay beside.
        chat = _native_audio_post_handoff_free_gb(CHAT)
        if chat is not None:
            return chat
    owner = outgoing or outgoing_owner[0]
    live: dict[int, tuple[float, float]] = {}
    reclaimable: dict[int, float] = {}

    def _read_live() -> bool:
        from utils.hardware import gpu_query

        with gpu_query.fresh_reads():
            utilization = hardware.get_visible_gpu_utilization()
        live.clear()
        for device in utilization.get("devices", []):
            try:
                index = int(device["index"])
                total = float(device["vram_total_gb"])
                used = float(device["vram_used_gb"])
            except (KeyError, TypeError, ValueError):
                continue
            live[index] = (max(total - used, 0.0), total)
        return bool(live)

    def _merge_report(reported) -> bool:
        if not isinstance(reported, dict):
            return False
        try:
            parsed = {
                int(index): max(float(value), 0.0)
                for index, value in reported.items()
                if int(index) in live
            }
        except (TypeError, ValueError, OverflowError):
            return False
        if any(value >= 1_000_000 for value in parsed.values()):
            return False
        for index, value in parsed.items():
            reclaimable[index] = reclaimable.get(index, 0.0) + value
        return True

    if owner == CHAT:
        # llama-server contributes only its stable startup model-buffer floor.
        backend = get_inference_backend()
        worker_snapshot = None
        if getattr(backend, "active_model_name", None):
            worker_snapshot = getattr(backend, "post_handoff_gpu_availability_gb", lambda: None)()
        if worker_snapshot is not None:
            free_by_index, total_by_index, worker_reclaimable = worker_snapshot
            live = {
                int(index): (float(free), float(total_by_index[index]))
                for index, free in free_by_index.items()
                if index in total_by_index
            }
            if not live:
                return None
            _merge_report(worker_reclaimable)
        elif not _read_live():
            return None
        llama_backend = get_llama_cpp_backend()
        if getattr(llama_backend, "is_loaded", False):
            _merge_report(getattr(llama_backend, "reclaimable_gpu_memory_gb", lambda: None)())
    elif owner in (DIFFUSION, VIDEO):
        # Hold the generation barrier across both readings so freed activations are not double counted.
        if owner == DIFFUSION:
            from core.inference.diffusion_engine_router import get_active_diffusion_engine
            media_backend = get_active_diffusion_engine()
        else:
            from core.inference.video import get_video_backend
            media_backend = get_video_backend()
        generate_lock = getattr(media_backend, "_generate_lock", None)
        state_lock = getattr(media_backend, "_lock", None)
        if generate_lock is None or state_lock is None:
            return None
        acquired = generate_lock.acquire(blocking = False)
        if not acquired:
            return None
        try:
            with state_lock:
                # begin_load publishes before replacing state; sampling the old state would overspend.
                if getattr(media_backend, "_loading", None) is not None:
                    return None
                if owner == DIFFUSION and (
                    getattr(media_backend, "_pending_server", None) is not None
                    or int(getattr(media_backend, "_stopping_servers", 0) or 0) > 0
                ):
                    return None
                state = getattr(media_backend, "_state", None)
                if state is None or not _read_live():
                    return None
                if hasattr(state, "server"):
                    # Native sd.cpp owns VRAM in a child; only its startup floor is attributable.
                    server = getattr(state, "server", None)
                    if (
                        server is None
                        or getattr(media_backend, "_cpu_backend_forced", False)
                        or "--offload-to-cpu" in tuple(getattr(state, "offload_flags", ()) or ())
                    ):
                        return None
                    reported = getattr(server, "reclaimable_params_vram_gb", lambda _gpu: None)(
                        getattr(state, "physical_gpu_id", None)
                    )
                    if not _merge_report(reported):
                        return None
                else:
                    import torch

                    device_type = hardware.get_device()
                    if device_type == hardware.DeviceType.CUDA:
                        device_module = torch.cuda
                    elif device_type == hardware.DeviceType.XPU:
                        device_module = torch.xpu
                    else:
                        return None
                    memory_reserved = getattr(device_module, "memory_reserved", None)
                    device_count = int(device_module.device_count())
                    if not callable(memory_reserved) or device_count <= 0:
                        return None
                    physical_ids = hardware.get_parent_visible_gpu_ids()
                    if not physical_ids:
                        physical_ids = sorted(live) if len(live) == device_count else None
                    if not physical_ids or len(physical_ids) < device_count:
                        return None
                    reclaimable = {
                        int(physical_ids[ordinal]): max(
                            int(memory_reserved(ordinal)) / float(1024**3), 0.0
                        )
                        for ordinal in range(device_count)
                    }
        except Exception as exc:
            logger.warning("Could not attribute resident media GPU memory: %s", exc)
            return None
        finally:
            generate_lock.release()
    else:
        return None

    # Fail closed on a concurrent media handoff or unload.
    if owner_snapshot() != outgoing_owner:
        return None
    if not any(value > 0 for value in reclaimable.values()):
        return None
    return _NativeAudioAvailability(
        effective_free_gb = {
            index: min(free + reclaimable.get(index, 0.0), total)
            for index, (free, total) in live.items()
        },
        reclaimable_gpu_gb = reclaimable,
        owner_snapshot = outgoing_owner,
        credited_owner = owner,
    )


def _wait_for_native_audio_gpu_free_gb(
    gpu_index: int,
    required_gb: float,
    *,
    max_wait: float = 5.0,
    interval: float = 0.25,
) -> bool:
    """Wait until an evicted media backend's credited VRAM is actually free."""
    from utils.hardware import get_visible_gpu_utilization

    deadline = time.monotonic() + max(max_wait, 0.0)
    while True:
        try:
            from utils.hardware import gpu_query
            with gpu_query.fresh_reads():
                devices = get_visible_gpu_utilization().get("devices", [])
            for device in devices:
                if int(device["index"]) != int(gpu_index):
                    continue
                total = float(device["vram_total_gb"])
                used = float(device["vram_used_gb"])
                if max(total - used, 0.0) >= required_gb:
                    return True
        except (KeyError, TypeError, ValueError, OverflowError):
            pass
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            return False
        time.sleep(min(interval, remaining))


async def _unload_llama_before_standard_load(llama_backend) -> None:
    """Tear down llama-server and wait for asynchronous driver VRAM reclaim.

    Unloads even when nothing is loaded, under the lock that every GGUF load and a terminal
    Metal retirement's cleanup (_release_after_terminal_retirement) hold: the unload advances
    the epoch, so a cleanup still pending sees this load replaced the retired server, and one
    already past its check finishes first."""

    def handoff() -> Optional[float]:
        # getattr: a stand-in backend has no load to order against.
        lock = getattr(llama_backend, "_serial_load_lock", None)
        if lock is not None:
            # As the unload would: a recovery reload holding the lock stops instead of finishing.
            llama_backend._cancel_event.set()
        with lock or nullcontext():
            if not llama_backend.is_loaded:
                if lock is None:
                    return None
                kill_started = time.monotonic()
                llama_backend.unload_model()
                # A starting or recovering server was killed: wait for it like a loaded one.
                last_kill = getattr(llama_backend, "_last_kill_monotonic", 0.0) or 0.0
                return kill_started if last_kill >= kill_started else None
            logger.info("Unloading GGUF model before loading Unsloth model")
            kill_started = time.monotonic()
            llama_backend.unload_model()
            return kill_started

    kill_started = await asyncio.to_thread(handoff)
    if kill_started is None:
        return
    await asyncio.to_thread(
        llama_backend._wait_for_vram_settle,
        since_kill = kill_started,
    )


def _spec_fallback_binary_changed(llama_backend) -> Optional[bool]:
    """Only binary_no_mtp and binary_outdated can be repaired by reloading; a replacement must still
    pass."""
    if getattr(llama_backend, "spec_fallback_reason", None) not in (
        "binary_no_mtp",
        "binary_outdated",
    ):
        return None
    try:
        return bool(llama_backend.spec_binary_fallback_can_retry())
    except Exception:
        return None


def _spec_probe_retry_pending(llama_backend) -> Optional[bool]:
    """Mirrors the inconclusive-probe arm of _runtime_matches_intent; reloads once the probe is decisive."""
    if not getattr(llama_backend, "_capability_probe_inconclusive", False):
        return False
    if getattr(llama_backend, "_is_diffusion", False):
        return False
    try:
        return not llama_backend.probe_server_capabilities().get("mtp_probe_inconclusive")
    except Exception:
        return None


def _diffusion_split_supported(llama_backend) -> Optional[bool]:
    """Whether a resident diffusion runner now honours --ngl, so a reload can apply a split it dropped."""
    if not getattr(llama_backend, "_is_diffusion", False):
        return None
    try:
        return bool(llama_backend.diffusion_split_supported())
    except Exception:
        return None


def _audio_probe_pending(llama_backend) -> bool:
    """Blocks reuse until the audio probe runs; nothing else re-probes if the client skips /load."""
    return not getattr(llama_backend, "_audio_probed", True)


def _gpu_placement_paravirtual() -> Optional[bool]:
    """On a paravirtual Metal device every placement is rewritten to CPU, so raw placement cannot differ."""
    try:
        from core.inference.llama_cpp import _metal_device_is_paravirtual
        return bool(_metal_device_is_paravirtual())
    except Exception:
        return None


def _arch_gate_dropped_tensor_parallel(llama_backend) -> Optional[bool]:
    """True when the arch gate rewrote a tensor-parallel request to layer mode, which must still match."""
    try:
        return bool(llama_backend._arch_gate_dropped_tensor_parallel)
    except Exception:
        return None


def _spec_dspark_sidecar_absent(llama_backend) -> Optional[bool]:
    """An absent DSpark sidecar is permanent for most repos; reloading it would relaunch the same server."""
    try:
        return bool(llama_backend._dspark_sidecar_absent)
    except Exception:
        return None


def _spec_dflash_retry_pending(llama_backend) -> Optional[bool]:
    """A retryable DFlash sidecar fetch failure, which Auto records no spec_fallback_reason for."""
    try:
        return bool(llama_backend._dflash_retry_needed)
    except Exception:
        return None


class _NoParallelRequest:
    """A stand-in for a load that named no slot count, for reading the default."""

    n_parallel = None


def _resolve_parallel_slots(request, fastapi_request: Optional[Request]) -> int:
    if request.n_parallel is not None:
        return request.n_parallel
    state = getattr(getattr(fastapi_request, "app", None), "state", None)
    return getattr(state, "llama_parallel_slots", 1)


def _effective_parallel_slots(n_parallel: int, *, diffusion_kind: Optional[bool] = None) -> int:
    """Slots a launch really serves: one without --kv-unified, and always one for diffusion runners."""
    if n_parallel <= 1:
        return max(1, n_parallel)
    if diffusion_kind is True:
        return 1  # allow-slot-clamp: diffusion never receives --parallel
    try:
        caps = LlamaCppBackend.probe_server_capabilities()
        if caps.get("found") and not caps.get("supports_kv_unified"):
            return 1  # allow-slot-clamp: mirrors the load_model clamp
    except Exception as exc:
        # Unreadable capabilities never refuse: keep the ask.
        logger.warning("Could not probe llama-server slots: %s", exc)
    return n_parallel


async def _prepare_load_placement(
    config: ModelConfig,
    request: LoadRequest | ValidateModelRequest,
    extra_args: Optional[list[str]],
) -> _LoadPlacement:
    requested = request.gpu_ids or None
    if not config.is_gguf:
        return _LoadPlacement(requested, None, False, False)
    diffusion_kind = _classify_diffusion_gguf(config)
    resolved, is_vulkan = await _resolve_gguf_gpu_ids_for_request(
        config, requested, diffusion_kind = diffusion_kind
    )
    _reject_draft_device_with_gpu_ids(resolved, extra_args, gpu_ids_are_vulkan_ordinals = is_vulkan)
    return _LoadPlacement(requested, resolved, is_vulkan, diffusion_kind)


def _audio_intent_gguf_refusal(config, request) -> Optional[str]:
    """Refuses a GGUF sent with audio_device unless it is a speech-codec model; judged from the header."""
    if getattr(request, "audio_device", None) is None:
        return None
    path = getattr(config, "gguf_file", None)
    verified = getattr(config, "gguf_verified", None)
    if not path and verified:
        path = verified[2]
    repo = getattr(config, "gguf_hf_repo", None)
    variant = getattr(config, "gguf_variant", None)
    if not path and repo and variant:
        try:
            from hub.utils.gguf import resolve_local_gguf_path
            path = resolve_local_gguf_path(repo, variant)
        except Exception:  # noqa: BLE001 - unresolvable locally: nothing to judge yet
            path = None
    if not path or not Path(path).is_file():
        return None
    from hub.services.models.catalog_classification import _arch_to_audio_type
    from utils.gguf_archs import is_audio_cpp_gguf_architecture, is_speech_gguf_architecture
    from utils.models.gguf_metadata import read_gguf_architecture, read_gguf_tts_audio_type

    arch = read_gguf_architecture(str(path))
    if arch is None or is_speech_gguf_architecture(arch) or is_audio_cpp_gguf_architecture(arch):
        # Unreadable, or a speech arch the chat gate already refuses with its own message.
        return None
    if read_gguf_tts_audio_type(str(path)) or _arch_to_audio_type(
        arch, (config.identifier, Path(path).name)
    ):
        return None
    return (
        f"This GGUF is not an audio model (architecture '{arch}'), so the Audio page cannot run it. "
        "Load it from Chat instead."
    )


from core.inference.audio_cpp_failures import estimate_resident_gb as audio_cpp_resident_gb


def _native_audio_cpu_load(config, request) -> bool:
    """Gated on audio type: a chat model cannot send audio_device to skip the VRAM guards."""
    from core.inference.audio_device import audio_load_runs_on_cpu
    from core.inference.native_audio import NATIVE_AUDIO_TYPES

    audio_type = getattr(config, "audio_type", None)
    return audio_type in NATIVE_AUDIO_TYPES and audio_load_runs_on_cpu(
        audio_type, getattr(request, "audio_device", None)
    )


def _resident_audio_placement_matches(backend, request) -> bool:
    """Reads the resident entry; entries without a placement key are read as GPU, as those loads were."""
    from core.inference.audio_device import audio_load_runs_on_cpu
    from core.inference.native_audio import NATIVE_AUDIO_TYPES

    resident = backend.models.get(backend.active_model_name, {})
    audio_type = resident.get("audio_type")
    if audio_type not in NATIVE_AUDIO_TYPES:
        return True
    device = getattr(request, "audio_device", None)
    if resident.get("audio_device_fallback") == "cpu":
        # Its GPU start failed: Auto would land on the CPU again, so only a pinned GPU reloads.
        from core.inference.audio_device import audio_device_default, normalize_audio_device
        return (
            normalize_audio_device(device) != "gpu" if device else audio_device_default() != "gpu"
        )
    return bool(resident.get("audio_cpu", False)) == audio_load_runs_on_cpu(audio_type, device)


def _resident_audio_holds_no_gpu(backend) -> bool:
    """True only for native audio recorded as CPU-placed, so only a real CPU placement skips the arbiter."""
    from core.inference.native_audio import NATIVE_AUDIO_TYPES

    resident = backend.models.get(backend.active_model_name, {})
    return resident.get("audio_type") in NATIVE_AUDIO_TYPES and bool(
        resident.get("audio_cpu", False)
    )


async def _preflight_native_audio_placement(
    config: ModelConfig, request: LoadRequest | ValidateModelRequest, placement: _LoadPlacement
) -> _LoadPlacement:
    """Resolve native-audio placement before a resident model can be evicted."""
    from core.inference.native_audio import NATIVE_AUDIO_TYPES

    audio_type = getattr(config, "audio_type", None)
    if audio_type not in NATIVE_AUDIO_TYPES:
        return placement
    from core.inference.audio_cpp_models import AUDIO_CPP_AUDIO_TYPES

    if audio_type in AUDIO_CPP_AUDIO_TYPES:
        from core.inference.audio_cpp_server import model_runtime_problem

        audio_cpp_model = getattr(config, "audio_cpp", None)
        problem = (
            await asyncio.to_thread(model_runtime_problem, audio_cpp_model)
            if audio_cpp_model is not None
            else None
        )
        if problem:
            # Refused here, before the orchestrator evicts the resident model for a load that cannot start.
            from core.inference.audio_cpp_failures import problem_http_exception
            raise problem_http_exception(problem, audio_cpp_model)
    if getattr(config, "is_lora", False):
        raise HTTPException(
            status_code = 400,
            detail = (
                "Native audio LoRA adapters are not supported yet. "
                "Load a merged checkpoint instead."
            ),
        )
    if audio_type in ("higgs_tts2", "higgs_tts3") and sys.version_info < (3, 10):
        raise HTTPException(
            status_code = 400,
            detail = "Higgs TTS requires Python 3.10 or newer in Unsloth.",
        )

    # Before every VRAM question: sizing a CPU load refuses it on a full GPU.
    if _native_audio_cpu_load(config, request):
        if audio_type == "minimax_music3":
            # The switch already evicted the resident model, so a doomed load costs it.
            raise HTTPException(
                status_code = 400,
                detail = (
                    "MiniMax Music 3 cannot be loaded into CPU RAM: its official local "
                    "runtime requires an NVIDIA CUDA GPU. Set the audio device back to "
                    "Auto to load this model."
                ),
            )
        return placement

    automatic = not placement.requested_gpu_ids
    availability = (
        await asyncio.to_thread(_native_audio_post_handoff_free_gb) if automatic else None
    )

    def _resolve() -> tuple[Optional[List[int]], Optional[float], Optional[dict[int, float]]]:
        import utils.hardware as hardware
        from core.inference.native_audio import (
            native_audio_kv_memory_gb,
            native_audio_security_targets,
        )

        device = hardware.get_device()
        if audio_type == "minimax_music3":
            if device != hardware.DeviceType.CUDA or hardware.IS_ROCM:
                raise ValueError(
                    "MiniMax Music 3 requires an NVIDIA CUDA GPU in its official local runtime."
                )
            if sys.version_info < (3, 10):
                raise ValueError("MiniMax Music 3 requires Python 3.10 or newer in Unsloth.")
        if device not in (hardware.DeviceType.CUDA, hardware.DeviceType.XPU):
            if placement.requested_gpu_ids:
                raise ValueError(
                    "Native audio GPU selection is only supported on CUDA and Intel XPU."
                )
            return None, None, None

        model_source = getattr(config, "path", None) or config.identifier
        targets = list(
            dict.fromkeys(
                native_audio_security_targets(
                    model_source,
                    audio_type,
                    request.hf_token,
                )
            )
        )
        # Repo is ~67 GB but the BF16 pipeline is resident on one 24 GB GPU; repo bytes over-place.
        required_gb = _MINIMAX_MUSIC3_RESIDENT_GB if audio_type == "minimax_music3" else None
        from core.inference.audio_cpp_models import AUDIO_CPP_AUDIO_TYPES

        if audio_type in AUDIO_CPP_AUDIO_TYPES:
            # Umbrella id: size from the one variant it loads, not repository bytes.
            audio_cpp_model = getattr(config, "audio_cpp", None)
            if audio_cpp_model is not None:
                required_gb = audio_cpp_resident_gb(audio_cpp_model.size_bytes)
        elif len(targets) > 1:
            required_gb = 0.0
            for target in targets:
                target_required_gb, _metadata = hardware.estimate_required_model_memory_gb(
                    target,
                    hf_token = request.hf_token,
                    training_type = None,
                    load_in_4bit = False,
                    max_seq_length = request.max_seq_length,
                )
                if target_required_gb is None:
                    raise ValueError(
                        f"Could not estimate GPU memory for native audio component '{target}'."
                    )
                required_gb += target_required_gb
            required_gb += native_audio_kv_memory_gb(
                model_source,
                audio_type,
                request.hf_token,
            )
        resolved, metadata = hardware.prepare_gpu_selection(
            placement.requested_gpu_ids,
            model_name = config.identifier,
            hf_token = request.hf_token,
            load_in_4bit = False,
            max_seq_length = request.max_seq_length,
            required_override_gb = required_gb,
        )
        post_handoff_free_gb = None
        if required_gb is None:
            required_gb = metadata.get("required_gb")
        if metadata.get("selection_mode") == "fallback_all":
            candidates = set(resolved or ())
            fitting = sorted(
                (
                    (index, free_gb)
                    for index, free_gb in (
                        availability.effective_free_gb if availability is not None else {}
                    ).items()
                    if index in candidates and required_gb is not None and free_gb >= required_gb
                ),
                key = lambda item: (-item[1], item[0]),
            )
            if not fitting:
                refusal = ValueError(
                    "No single GPU has enough free memory for this native audio model. "
                    "Select a GPU with enough free memory and try again."
                )
                if audio_type in AUDIO_CPP_AUDIO_TYPES and audio_cpp_model is not None:
                    from core.inference.audio_cpp_failures import (
                        attach_failure,
                        classify_audio_cpp_failure,
                    )

                    free_by_gpu = availability.effective_free_gb if availability is not None else {}
                    free = [gb for index, gb in free_by_gpu.items() if index in candidates]
                    failure = classify_audio_cpp_failure(
                        str(refusal), model = audio_cpp_model, free_gb = max(free, default = None)
                    )
                    attach_failure(refusal, failure)
                raise refusal
            resolved = [fitting[0][0]]
        if automatic and availability is not None and resolved and len(resolved) == 1:
            selected_gpu = resolved[0]
            reported = availability.effective_free_gb.get(selected_gpu)
            if reported is not None:
                post_handoff_free_gb = {selected_gpu: reported}
        if resolved and len(resolved) > 1:
            raise ValueError(
                "Native audio models currently require one GPU. Select a single GPU; "
                "multi-GPU sharding is not supported yet."
            )
        return resolved, required_gb, post_handoff_free_gb

    try:
        resolved, required_gb, post_handoff_free_gb = await asyncio.to_thread(_resolve)
    except ValueError as exc:
        from core.inference.audio_cpp_failures import failure_of

        failure = failure_of(exc)
        detail = failure.detail() if failure is not None else str(exc)
        raise HTTPException(status_code = 400, detail = detail) from exc
    return placement._replace(
        resolved_gpu_ids = resolved,
        native_required_gb = required_gb,
        native_post_handoff_free_gb = post_handoff_free_gb,
    )


def _inherited_batch_flags_stripped(request) -> bool:
    """Inherited -b/-ub superseded by a set field are stripped, else an Apply reports already_loaded."""
    if getattr(request, "llama_extra_args", None) is not None:
        return False
    fields_set = getattr(request, "model_fields_set", set())
    strip_batch = "n_batch" in fields_set
    strip_ubatch = "n_ubatch" in fields_set
    # Tuning flags shadow the same way: an inherited copy counts as an override here too.
    strip_ctx_checkpoints = "ctx_checkpoints" in fields_set
    strip_cache_ram = "cache_ram" in fields_set
    strip_spec_draft_cache = "spec_draft_cache_type" in fields_set
    strip_load_mode = "load_mode" in fields_set
    if not (
        strip_batch
        or strip_ubatch
        or strip_ctx_checkpoints
        or strip_cache_ram
        or strip_spec_draft_cache
        or strip_load_mode
    ):
        return False
    stored = list(getattr(get_llama_cpp_backend(), "extra_args", None) or ())
    if not stored:
        return False
    return (
        strip_shadowing_flags(
            stored,
            strip_context = False,
            strip_cache = False,
            strip_spec = False,
            strip_template = False,
            strip_split_mode = False,
            strip_batch = strip_batch,
            strip_ubatch = strip_ubatch,
            strip_ctx_checkpoints = strip_ctx_checkpoints,
            strip_cache_ram = strip_cache_ram,
            strip_spec_draft_cache = strip_spec_draft_cache,
            strip_load_mode = strip_load_mode,
            strip_load_mode_aliases = strip_load_mode,
        )
        != stored
    )


def _resolve_gguf_load_intent(
    config: ModelConfig,
    request: LoadRequest,
    *,
    native_grant_backed: bool,
    chat_template_override: Optional[str],
    extra_args: Optional[list[str]],
    placement: _LoadPlacement,
    n_parallel: int,
) -> GgufLoadIntent:
    """Resolve source, companions, settings, and placement into one load value."""

    public_model_identifier = _public_model_identifier(request.model_path, config.identifier)
    if config.gguf_hf_repo:
        source = GgufLoadIntent(
            model_identifier = public_model_identifier,
            hf_repo = config.gguf_hf_repo,
            hf_variant = config.gguf_variant,
            hf_token = request.hf_token,
            verified_gguf = getattr(config, "gguf_verified", None),
        )
    else:
        if native_grant_backed:
            if config.gguf_mmproj_file:
                _validate_native_gguf_companion(
                    config.gguf_mmproj_file, config.gguf_file, "vision companion"
                )
            if config.gguf_mtp_file:
                config.gguf_mtp_file = _mtp_draft_for_path(
                    config.gguf_file,
                    True,
                    log_native_fallback = True,
                )
            if config.gguf_dspark_file:
                config.gguf_dspark_file = _dspark_draft_for_path(
                    config.gguf_file,
                    True,
                    log_native_fallback = True,
                )
            if config.gguf_dflash_file:
                config.gguf_dflash_file = _dflash_draft_for_path(
                    config.gguf_file,
                    True,
                    log_native_fallback = True,
                )
        source = GgufLoadIntent(
            model_identifier = public_model_identifier,
            gguf_path = config.gguf_file,
            mmproj_path = config.gguf_mmproj_file,
            mtp_draft_path = config.gguf_mtp_file,
            dspark_draft_path = config.gguf_dspark_file,
            dflash_draft_path = config.gguf_dflash_file,
            hf_variant = config.gguf_variant,
        )

    return _gguf_request_intent(
        source,
        request,
        chat_template_override = chat_template_override,
        extra_args = extra_args,
        gpu_ids = placement.resolved_gpu_ids,
        n_parallel = n_parallel,
        is_vision = config.is_vision,
        gpu_ids_are_vulkan_ordinals = placement.gpu_ids_are_vulkan_ordinals,
        extra_args_inherited = (
            getattr(request, "llama_extra_args", None) is None
            # a strip that changed the list is an override, so the dedupe compares it
            and not _inherited_batch_flags_stripped(request)
        ),
    )


def _guard_chat_load_against_training(
    config: ModelConfig,
    request: LoadRequest | ValidateModelRequest,
    *,
    load_in_4bit: bool,
    placement: _LoadPlacement,
    llama_extra_args: Optional[list[str]] = None,
    n_parallel: int = 1,
) -> Optional[dict[str, Any]]:
    """Guards automatic chat loads against training; manual GGUF placement is not estimated, but diffusion and unclassified GGUFs are."""
    from core.training import get_training_backend
    from routes.training_vram import can_load_chat_during_training

    # Ahead of the diffusion branch, which would 409 a load that takes no VRAM.
    if _native_audio_cpu_load(config, request):
        return

    requested_gpu_ids = placement.requested_gpu_ids
    gpu_ids_are_vulkan_ordinals = placement.gpu_ids_are_vulkan_ordinals
    diffusion_kind = placement.diffusion_kind
    try:
        llm_active = get_training_backend().is_training_active()
    except Exception as e:
        # Independent probes: an unreadable LLM backend must still fall through to the diffusion check, which reads a different service.
        logger.warning("Could not check training state for chat-load guard: %s", e)
        llm_active = False

    if llm_active and getattr(request, "engine", "auto") != "auto":
        raise HTTPException(
            status_code = 409,
            detail = "Wait for training to finish before loading an optional inference engine.",
        )

    if not llm_active:
        # An SDXL LoRA trainer runs in its own subprocess and cannot be cheaply fit-checked, so refuse the chat load while one is active.
        if _diffusion_training_active():
            raise HTTPException(
                status_code = 409,
                detail = (
                    "Can't load this model while diffusion (Images) training is running: "
                    "its GPU memory use can't be verified against the trainer, so the load "
                    "was refused to protect the run. Try again after training finishes."
                ),
            )
        return

    from core.inference.llama_cpp import _diffusion_manual_ngl, _scale_diffusion_required_gb

    is_gguf = bool(getattr(config, "is_gguf", False))
    # load_model pins a GGUF to CPU on virtualised Metal; guard what will run.
    _guard_gpu_memory_mode = request.gpu_memory_mode
    _guard_gpu_layers = request.gpu_layers
    _guard_tensor_parallel = request.tensor_parallel
    _pv_guard_forced_cpu = is_gguf and _metal_device_is_paravirtual()
    if _pv_guard_forced_cpu:
        _pv = paravirtual_normalized_request(
            gpu_memory_mode = request.gpu_memory_mode,
            gpu_layers = request.gpu_layers,
            tensor_parallel = request.tensor_parallel,
            tensor_split = None,
            n_cpu_moe = 0,
            extra_args = llama_extra_args,
            log_dropped = False,
        )
        _guard_gpu_memory_mode = _pv.gpu_memory_mode
        _guard_gpu_layers = _pv.gpu_layers
        _guard_tensor_parallel = _pv.tensor_parallel
        llama_extra_args = _pv.extra_args
    # Forced-CPU pin puts nothing on the GPU; checked before the diffusion exemptions.
    if _pv_guard_forced_cpu:
        return
    if is_gguf and _guard_gpu_memory_mode == "manual" and (diffusion_kind is False):
        return
    # Zero-layer diffusion split uses no VRAM; mirrors the loader's cpu_only.
    diffusion_ngl = (
        _diffusion_manual_ngl(_guard_gpu_memory_mode, _guard_gpu_layers) if is_gguf else None
    )
    if diffusion_ngl is not None and diffusion_kind is not False:
        # Loader drops the split when the shim lacks --ngl; guard what will run.
        try:
            if not get_llama_cpp_backend().diffusion_split_supported():
                diffusion_ngl = None
        except Exception as e:
            logger.warning("Could not probe diffusion shim for chat-load guard: %s", e)
            diffusion_ngl = None
    # `is True`: only a CONFIRMED diffusion GGUF places nothing at ngl 0.
    if is_gguf and diffusion_kind is True and diffusion_ngl == 0:
        return

    diffusion_gpu = None
    if is_gguf and diffusion_kind is not False and not gpu_ids_are_vulkan_ordinals:
        # Same token selection as the runner. No force_cpu: an empty token would short-circuit the guard to cpu_only and always allow an unclassified GGUF.
        diffusion_gpu = LlamaCppBackend._diffusion_gpu_arg(
            requested_gpu_ids,
            cpu_only = LlamaCppBackend._effective_gpu_count() == 0,
        )

    # Ordinal pins exist only on Vulkan builds, so they settle it without probing the binary.
    binary = LlamaCppBackend._find_llama_server_binary() if is_gguf else None
    is_vulkan_backend = bool(
        is_gguf
        and (gpu_ids_are_vulkan_ordinals or (binary and LlamaCppBackend._is_vulkan_backend(binary)))
    )

    # ggml's vulkan pool, probed once: the device count and the free-vram view below both read it
    vulkan_gpu_memory: Optional[list[tuple[int, int, int]]] = None
    if is_vulkan_backend and (
        gpu_ids_are_vulkan_ordinals
        or diffusion_kind is False
        or (diffusion_kind is None and not requested_gpu_ids)
    ):
        vulkan_gpu_memory = LlamaCppBackend._get_gpu_memory(binary)
        if not requested_gpu_ids:
            # automatic placement prefers the discrete cards, like the loader's fit
            vulkan_gpu_memory = LlamaCppBackend._vulkan_auto_gpu_memory(vulkan_gpu_memory)

    guard_tensor_parallel = _effective_tensor_parallel(
        llama_extra_args, _guard_tensor_parallel
    ) and (is_vulkan_backend or LlamaCppBackend._effective_gpu_count(requested_gpu_ids) >= 2)
    guard_n_devices = _guard_device_count(
        requested_gpu_ids, vulkan_gpu_memory, tensor_parallel = guard_tensor_parallel
    )

    # Size with the slot count that will launch. An unclassified GGUF keeps the ask.
    if is_gguf and n_parallel > 1:
        if diffusion_kind is True:
            n_parallel = 1  # allow-slot-clamp: diffusion never receives --parallel
        else:
            try:
                caps = LlamaCppBackend.probe_server_capabilities()
                if caps.get("found") and not caps.get("supports_kv_unified"):
                    n_parallel = 1  # allow-slot-clamp: mirrors the load_model clamp
            except Exception as e:
                logger.warning("Could not probe llama-server slots for chat-load guard: %s", e)

    required_override_gb = placement.native_required_gb
    if is_gguf:
        required_override_gb = _estimate_gguf_required_gb(
            config,
            hf_token = request.hf_token,
            max_seq_length = request.max_seq_length,
            llama_extra_args = llama_extra_args,
            speculative_type = getattr(request, "speculative_type", None),
            n_parallel = n_parallel,
            cache_type_kv = request.cache_type_kv,
            # getattr: older callers hand this guard a bare request double
            n_batch = getattr(request, "n_batch", None),
            n_ubatch = getattr(request, "n_ubatch", None),
            ctx_checkpoints = getattr(request, "ctx_checkpoints", None),
            tensor_parallel = guard_tensor_parallel,
            # size the compute buffers for the split the loader would budget
            n_devices = guard_n_devices,
            # a confirmed diffusion runner ignores the batch flags, so no reserve for it
            is_diffusion = diffusion_kind is True,
            # getattr: an older caller passes a bare request double that lacks disable_vision.
            disable_vision = bool(getattr(request, "disable_vision", False)),
            shared_memory_pool = _admission_pool_shares_host_ram(
                is_vulkan_backend = is_vulkan_backend,
                vulkan_gpu_memory = vulkan_gpu_memory,
                requested_gpu_ids = requested_gpu_ids,
                gpu_ids_are_vulkan_ordinals = gpu_ids_are_vulkan_ordinals,
            ),
        )
    # Confirmed-diffusion split (a split the loader drops is nulled above): only ngl/n_layers on GPU. Unknown keeps full estimate: header unreadable, layers too.
    if (
        required_override_gb is not None
        and diffusion_kind is True
        and diffusion_ngl is not None
        and diffusion_ngl > 0
    ):
        required_override_gb = _scale_diffusion_required_gb(
            required_override_gb, diffusion_ngl, _gguf_layer_count(config)
        )

    # Without a manual split the runner layer-splits a GGUF its one device cannot hold
    # (#6347): budget the devices that same decision picks, from the same weight bytes the
    # launcher reads. A GGUF not on disk yet keeps the stricter single-device budget.
    guard_gpu_ids = requested_gpu_ids
    _gguf_file = getattr(config, "gguf_file", None) if is_gguf else None
    if diffusion_gpu and diffusion_ngl is None and _gguf_file and os.path.isfile(_gguf_file):
        try:
            _assets = get_llama_cpp_backend()._find_diffusion_assets()
            fit_gpus = LlamaCppBackend._diffusion_fit_gpus(
                LlamaCppBackend._get_gguf_size_bytes(_gguf_file),
                requested_gpu_ids,
                diffusion_gpu,
                _assets[1] if _assets else None,
            )
        except Exception as e:
            logger.debug("Diffusion GPU fit skipped in the training guard: %s", e)
            fit_gpus = None
        if fit_gpus:
            diffusion_gpu, guard_gpu_ids = None, fit_gpus

    vulkan_free_vram_gb = None
    if is_gguf:
        if is_vulkan_backend and (gpu_ids_are_vulkan_ordinals or diffusion_kind is False):
            vulkan_free_vram_gb = {
                index: free_mib / 1024.0
                for index, free_mib, _total_mib in (vulkan_gpu_memory or [])
            }
        elif is_vulkan_backend and diffusion_kind is None and requested_gpu_ids:
            # Before the header, an explicit pin cannot be budgeted (Vulkan vs CUDA namespaces differ); auto placement keeps the torch view, not a refusal.
            vulkan_free_vram_gb = {}

    native_post_handoff_free_gb = placement.native_post_handoff_free_gb
    if native_post_handoff_free_gb is not None:
        # One atomic post-handoff snapshot; mixing reads can double count a reset cache.
        availability = _native_audio_post_handoff_free_gb()
        selected = list(placement.resolved_gpu_ids or ())
        if availability is None or len(selected) != 1:
            native_post_handoff_free_gb = None
        else:
            selected_gpu = selected[0]
            effective_free = availability.effective_free_gb.get(selected_gpu)
            native_post_handoff_free_gb = (
                {selected_gpu: effective_free} if effective_free is not None else None
            )

    ok, info = can_load_chat_during_training(
        model_name = getattr(config, "identifier", request.model_path),
        hf_token = request.hf_token,
        load_in_4bit = load_in_4bit,
        max_seq_length = request.max_seq_length,
        requested_gpu_ids = guard_gpu_ids,
        is_gguf = is_gguf,
        gpu_ids_are_vulkan_ordinals = gpu_ids_are_vulkan_ordinals,
        vulkan_free_vram_gb = vulkan_free_vram_gb,
        required_override_gb = required_override_gb,
        single_device_gpu = diffusion_gpu,
        post_handoff_free_gpu_vram_gb = native_post_handoff_free_gb,
    )
    if ok:
        return info

    usable = info.get("usable_gb")
    needed = info.get("needed_gb")
    if needed is None:
        needed = info.get("required_gb")
    if needed is not None and usable is not None:
        detail = (
            f"Not enough free GPU memory to load this model while training is "
            f"running (needs ~{needed:.0f} GB including safety headroom, "
            f"~{usable:.0f} GB free). Training was left untouched. Use an external "
            f"provider, a smaller or more quantized model, or try again after "
            f"training finishes."
        )
    else:
        detail = (
            "Can't load this model while training is running: its GPU memory use "
            "could not be verified, so the load was refused to protect the "
            "training run. Use an external provider or try again after training "
            "finishes."
        )
    logger.info("Refusing chat-model load during training: %s", info)
    raise HTTPException(status_code = 409, detail = detail)


def _resolve_inherited_extra_args(
    request,
    config: ModelConfig,
    model_identifier: str,
    extra_llama_args: Optional[list[str]],
    effective_chat_template_override: Optional[str] = None,
) -> Optional[list[str]]:
    """Effective pass-through extras for a GGUF request that omitted the field:
    the previous same-model load's extras, shadow-stripped, so a settings-Apply
    reload (which does not round-trip the extras field) keeps them (#5401)."""
    if getattr(request, "llama_extra_args", None) is not None:
        return extra_llama_args
    if not getattr(config, "is_gguf", False):
        return extra_llama_args
    llama_backend = get_llama_cpp_backend()
    stored_args = getattr(llama_backend, "extra_args", None)
    if not stored_args:
        return extra_llama_args
    # Inherit previous extras only for the same model; explicit [] clears them; strip shadowed flags so an inherited one can't win the last-wins parse.
    source = getattr(llama_backend, "extra_args_source", None)
    # Compare the resolved variant: callers often omit gguf_variant.
    resolved_variant = (config.gguf_variant or "").lower()
    request_variant = (request.gguf_variant or "").lower()
    stored_variant = (source[1] or "").lower() if source else ""
    # A picker load records the snapshot path, an API auto-switch loads the repo id.
    stored_identity = _canonical_model_identity(source[0]) if source else ""
    same_model = bool(
        stored_identity and stored_identity == _canonical_model_identity(model_identifier)
    )
    if request.gguf_variant:
        variant_mismatch = request_variant != stored_variant
    else:
        variant_mismatch = bool(stored_variant and resolved_variant != stored_variant)
    same_source = same_model and not variant_mismatch
    if not same_source:
        logger.info(
            "Not inheriting llama_extra_args: stored args came from %s, loading %s",
            source,
            (model_identifier, resolved_variant),
        )
        # Clear explicitly so the backend doesn't inherit via 'no opinion'.
        extra_llama_args = []
    else:
        # Strip only groups whose field was set; a bundled family template also strips --chat-template-file, else the stale arg shadows the bundled template.
        fields_set = getattr(request, "model_fields_set", set())
        # A matching inherited -c is the user's opt-in to exceed the fit estimate; keep it.
        from core.inference.llama_server_args import matches_explicit_ctx_override

        stripped = strip_shadowing_flags(
            stored_args,
            strip_context = "max_seq_length" in fields_set
            and not matches_explicit_ctx_override(
                stored_args, getattr(request, "max_seq_length", None)
            ),
            strip_cache = "cache_type_kv" in fields_set,
            strip_spec = ("speculative_type" in fields_set or "spec_draft_n_max" in fields_set),
            strip_template = (
                "chat_template_override" in fields_set
                or effective_chat_template_override is not None
            ),
            strip_split_mode = _should_strip_split_mode(request, stored_args),
            # Manual per-GPU ratio emits its own --tensor-split; drop the inherited one (appended last wins), but keep the user's --split-mode choice.
            strip_tensor_split = _should_strip_tensor_split(request),
            # Manual emits its own --fit/--gpu-layers, so an inherited offload flag must not win last; auto keeps the user's -ngl. getattr: validate lacks fields.
            strip_offload = getattr(request, "gpu_memory_mode", "auto") == "manual",
            strip_reasoning_budget = "reasoning_budget" in fields_set,
            strip_reasoning_budget_message = "reasoning_budget_message" in fields_set,
            # a set field emits its own flag; an inherited -b / -ub would last-wins-override it
            strip_batch = "n_batch" in fields_set,
            strip_ubatch = "n_ubatch" in fields_set,
            # The load mode also strips its deprecated aliases: a trailing one resets the mode.
            strip_ctx_checkpoints = "ctx_checkpoints" in fields_set,
            strip_cache_ram = "cache_ram" in fields_set,
            strip_spec_draft_cache = "spec_draft_cache_type" in fields_set,
            strip_load_mode = "load_mode" in fields_set,
            strip_load_mode_aliases = "load_mode" in fields_set,
        )
        # Drop only denylisted flags, not the whole inherited list.
        extra_llama_args, _dropped = drop_managed_flags(stripped)
        if _dropped:
            logger.warning(
                "Stored llama_extra_args are no longer allowed; dropped %s",
                ", ".join(_dropped),
            )
        else:
            if extra_llama_args:
                logger.info(
                    "Inheriting llama_extra_args from previous "
                    "load (same model, shadow-stripped): %s",
                    extra_llama_args,
                )
        # Inherited path options get the same owner-only check as a sent list.
        _refuse_managed_custom_projector(
            extra_llama_args,
            getattr(request, "model_path", None),
            getattr(request, "_override_alias_id", None),
            getattr(config, "gguf_variant", None),
        )
    return extra_llama_args


def _model_json_response(model, status_code: int = 200) -> Response:
    """Serializes via model_dump_json, skipping the dict round-trip and Starlette's second json.dumps."""
    return Response(
        content = model.model_dump_json(),
        media_type = "application/json",
        status_code = status_code,
    )


def _model_json_response_with_context_truncation(
    model, context_truncation: Optional[dict]
) -> Response:
    if context_truncation is None:
        return _model_json_response(model)
    content = model.model_dump()
    content["context_truncated"] = context_truncation
    return JSONResponse(content = content)


_NOT_SUPPORTED_HINTS = (
    "No config file found",
    "not yet supported",
    "is not supported",
    "does not support",
)

_NVFP4_INFERENCE_UNSUPPORTED_MESSAGE = (
    "We are working on supporting NVFP4 inference. For now it is not supported"
)

# Users cannot pip install into Studio's environment, so give our own message.
_COMPRESSED_TENSORS_INFERENCE_UNSUPPORTED_MESSAGE = (
    "This model is quantized with compressed-tensors, which Unsloth cannot run yet. "
    "Installing compressed-tensors will not help. Try a GGUF or a bitsandbytes 4-bit "
    "build of this model instead."
)

# The optional vLLM engine loads compressed-tensors checkpoints (#11728); said only where it can run.
_COMPRESSED_TENSORS_VLLM_HINT = (
    " Or run it with vLLM: open this model's run settings and set Inference engine to vLLM."
)


def _vllm_engine_hint(engine: Optional[str]) -> str:
    """Empty unless this host can run vLLM; ``wait = False`` keeps the GPU probe off this path."""
    if engine not in (None, "auto"):
        return ""
    try:
        from core.inference.engine_install import support_reason
        return _COMPRESSED_TENSORS_VLLM_HINT if support_reason("vllm", wait = False) is None else ""
    except Exception:
        return ""


# Quantizations the Default engine cannot run, with the packages that would let it (Studio ships none).
_MANAGED_ENGINE_QUANTIZATIONS = {
    "compressed-tensors": (),
    "awq": ("gptqmodel", "awq"),
    "gptq": ("gptqmodel", "auto_gptq"),
    "auto-round": ("auto_round",),
}
_OFFERED_ENGINES = ("vllm", "sglang")
# SGLang registers auto-round too, but only vLLM has been run on it (#7997).
_OFFERED_ENGINES_FOR = {"auto-round": ("vllm",)}


def _managed_engine_offer(
    metadata, *, engine, is_gguf, is_lora, is_audio, supported
) -> Optional[dict]:
    """Offers optional engines only where Default cannot run it; supported() is asked last so the GPU probe runs only for these; GGUF/adapters/audio refused."""
    if (
        engine not in (None, "auto")
        or is_gguf
        or is_lora
        or is_audio
        or not isinstance(metadata, dict)
    ):
        return None
    text_config = metadata.get("text_config")
    quant = metadata.get("quantization_config") or (
        text_config.get("quantization_config") if isinstance(text_config, dict) else None
    )
    method = quant.get("quant_method") if isinstance(quant, dict) else None
    if not isinstance(method, str):
        return None
    method = method.strip().lower()
    if method not in _MANAGED_ENGINE_QUANTIZATIONS:
        return None
    import importlib.util

    for module in _MANAGED_ENGINE_QUANTIZATIONS[method]:
        try:
            if importlib.util.find_spec(module) is not None:
                return None
        except (ImportError, ValueError):
            pass
    engines = [
        name
        for name in _OFFERED_ENGINES_FOR.get(method, _OFFERED_ENGINES)
        if supported(name, method)
    ]
    return {"quantization": method, "engines": engines} if engines else None


def _managed_engine_offer_for(config, hf_token) -> Optional[dict]:
    """``_managed_engine_offer`` from the checkpoint's own config.json; None on any failure."""
    try:
        if config.is_local:
            path = Path(config.path) / "config.json"
        else:
            from huggingface_hub import hf_hub_download, try_to_load_from_cache

            # Resolving the model already cached config.json; the Hub round trip costs ~45 ms per pick.
            cached = try_to_load_from_cache(config.identifier, "config.json")
            path = Path(
                cached
                if isinstance(cached, str)
                else hf_hub_download(config.identifier, "config.json", token = hf_token)
            )
        metadata = json.loads(path.read_text(encoding = "utf-8"))
        from core.inference.engine_install import (
            _driver_rows,
            gpu_platform,
            rocm_loads_quantization,
            support_reason,
        )

        def supported(name, method):
            if support_reason(name) is not None:
                return False
            if gpu_platform() == "rocm":
                if method == "auto-round":
                    # Unmeasured on ROCm vLLM; an explicit vLLM load still gets to try (#7997).
                    return False
                text_config = metadata.get("text_config")
                return rocm_loads_quantization(
                    metadata.get("quantization_config")
                    or (
                        text_config.get("quantization_config")
                        if isinstance(text_config, dict)
                        else None
                    )
                )
            if name != "sglang" or method != "compressed-tensors":
                return True
            # SGLang 0.5.20's compressed-tensors NVFP4 needs SM 10.0; vLLM falls back to Marlin from 7.5.
            try:
                return any(
                    float(row[1]) >= 10.0 for row in _driver_rows(None) or () if len(row) == 2
                )
            except ValueError:
                return False

        return _managed_engine_offer(
            metadata,
            engine = "auto",
            is_gguf = getattr(config, "is_gguf", False),
            is_lora = getattr(config, "is_lora", False),
            is_audio = getattr(config, "is_audio", False),
            supported = supported,
        )
    except Exception as exc:
        logger.debug("Managed engine offer check failed for '%s': %s", config.identifier, exc)
        return None


def _diagnosis_text(msg: str) -> str:
    """Cuts msg before llama-server output or log path (untrusted child text); never match phrases past the cut, they say nothing about the model."""
    for marker in ("\n\nllama-server output:", "\n\nFull log: "):
        head, sep, _ = msg.partition(marker)
        if sep:
            msg = head
    return msg


def _is_unsupported_nvfp4_inference_error(msg: str) -> bool:
    """Whether ``msg`` is the verbose MLX per-module metadata error emitted
    while loading an NVFP4 checkpoint."""
    lower_msg = _diagnosis_text(msg).lower()
    return "nvfp4" in lower_msg and "per-module mlx quantization metadata" in lower_msg


# The two transformers sites, reworded in 5.10 to add a version: match only what survived.
_MISSING_COMPRESSED_TENSORS_SIGNATURES = (
    "is required for compressed-tensors quantization",
    "`compressed_tensors` quantized models requires",
)


def _is_missing_compressed_tensors_error(msg: str) -> bool:
    """Matches the missing compressed-tensors error on CUDA, ROCm and CPU, where transformers raises it."""
    lower_msg = _diagnosis_text(msg).lower()
    return any(sig in lower_msg for sig in _MISSING_COMPRESSED_TENSORS_SIGNATURES)


def _unsupported_quantization_detail(msg: str, engine: Optional[str] = None) -> Optional[str]:
    """The refusal to show for a quantization error, or None; the one place signatures are added."""
    if _is_unsupported_nvfp4_inference_error(msg):
        return _NVFP4_INFERENCE_UNSUPPORTED_MESSAGE
    if _is_missing_compressed_tensors_error(msg):
        return _COMPRESSED_TENSORS_INFERENCE_UNSUPPORTED_MESSAGE + _vllm_engine_hint(engine)
    return None


def _maybe_unsupported_message(msg: str) -> str:
    """Rewrite a load/validate error into the friendly "not supported yet"
    message when it matches a known unsupported-model signature; otherwise
    return ``msg`` unchanged."""
    hay = _diagnosis_text(msg).lower()
    if any(h.lower() in hay for h in _NOT_SUPPORTED_HINTS):
        return f"This model is not supported yet. Try a different model. (Original error: {msg})"
    return msg


def _raise_if_sidecar_swap_in_progress() -> None:
    from utils.transformers_version import sidecar_swap_in_progress
    if sidecar_swap_in_progress():
        raise HTTPException(
            status_code = 409,
            detail = "A transformers installation is in progress. Retry when it completes.",
        )


def _active_generations_conflict(action: str, running: int, thread_ids) -> HTTPException:
    return HTTPException(
        status_code = 409,
        detail = {
            "error": "active_generations",
            "message": (
                f"{action} would stop {running} chat"
                f"{'s' if running != 1 else ''} that "
                f"{'are' if running != 1 else 'is'} still generating. "
                "Stop them first, or retry with force_cancel_active."
            ),
            "running": running,
            "thread_ids": thread_ids,
        },
    )


def _raise_or_cancel_active_generations(
    *,
    force: bool,
    action: str,
    cancel: bool = True,
) -> int:
    """refuse model swaps that would stop managed chats, or cancel them only after preflight."""
    from core.inference.gpu_arbiter import require_no_foreign_generations

    scope = account_access.account_scope()
    if scope is not None:
        # account_scope() catches deactivated GPU use; check it before any destructive cancellation.
        require_no_foreign_generations(scope)
    elsewhere = model_slots.all_generations()
    if not active_generations.count(scope, elsewhere, include_external = False):
        return 0
    if not force:
        raise _active_generations_conflict(
            action,
            active_generations.count(scope, elsewhere, include_external = False),
            active_generations.active_thread_ids(scope, elsewhere, include_external = False),
        )
    if not cancel:
        # the caller cancels only after preflight can no longer reject the load.
        return 0
    cancelled = active_generations.cancel_all(scope, elsewhere, include_external = False)
    if cancelled:
        logger.info(
            "model_swap_cancelled_active_generations",
            extra = {"event": "inference.reload_cancelled_generations", "count": cancelled},
        )
    return cancelled


_POST_CANCEL_DRAIN_TIMEOUT_S = 5.0


async def _cancel_and_drain_for_sidecar_swap(timeout_s: Optional[float] = None) -> None:
    """drain unrelated requests before cancellation so a rejected install cannot stop chats for nothing."""
    from core.inference.llama_keepwarm import other_inference_request_count

    budget = _POST_CANCEL_DRAIN_TIMEOUT_S if timeout_s is None else timeout_s

    async def _drain(deadline: float, *, discount_registered: bool) -> bool:
        while True:
            counted = other_inference_request_count(
                current_request_counted = False, include_pending = False
            )
            if discount_registered:
                counted -= min(counted, active_generations.count(None, include_external = False))
            if counted <= 0:
                return True
            if time.monotonic() >= deadline:
                return False
            await asyncio.sleep(0.02)

    # reserve most of the unchanged budget for chats that have been cancelled and are unwinding.
    if not await _drain(time.monotonic() + budget / 5, discount_registered = True):
        return
    _raise_or_cancel_active_generations(force = True, action = "Installing a new transformers version")
    await _drain(time.monotonic() + budget * 4 / 5, discount_registered = False)


async def _drain_and_recancel_before_teardown(*, force: bool, action: str) -> None:
    """Drains on the middleware count, not the registry, so admitted requests are caught; never raises."""
    await _wait_for_model_switch_idle(
        current_request_counted = False,
        timeout_s = _POST_CANCEL_DRAIN_TIMEOUT_S,
    )
    if force:
        _raise_or_cancel_active_generations(force = True, action = action)


_UNRESOLVED_BACKEND_STATE = object()


def _names_the_resident_model(resident: Optional[str], model_path: str) -> bool:
    """A pinned snapshot path and the repo id it maps to name the same model, so either must match."""
    if not resident:
        return False
    if model_id_matches(model_path, resident):
        return True
    # A load rewrites a materialized Ollama link to its tag; compare by ref.
    return is_ollama_manifest_ref(resident) and _ollama_ref_for_link(model_path) == resident


def _ollama_ref_for_link(model_path: str) -> Optional[str]:
    from hub.services.models.ollama import ollama_manifest_ref_for_path
    try:
        return ollama_manifest_ref_for_path(model_path)
    except (OSError, ValueError):
        return None


def _names_the_resident_gguf(llama_backend, model_path: str) -> bool:
    """Whether a client's ``model_path`` names the GGUF ``llama_backend`` runs.

    A scan-folder load runs as its directory while /v1/models, status and the monitor publish its
    repo id (the monitor as ``repo:QUANT``), and chat is served under that id, so /unload must
    accept it too or it answers success and leaves the model loaded (#13766).
    """
    identifier = llama_backend.model_identifier
    if (
        identifier == model_path
        or is_registered_native_path_label(identifier, model_path)
        or _names_the_resident_model(identifier, model_path)
    ):
        return True
    # A load in flight can still carry the previous model's advertised id.
    if not getattr(llama_backend, "is_loaded", False):
        return False
    from core.inference.openai_auto_download import split_model_ref

    published = [
        getattr(llama_backend, "_openai_advertised_id", None),
        _llama_public_model_id(llama_backend),
    ]
    if _matches_any(model_path, published):
        return True
    base, variant = split_model_ref(model_path)
    resident_variant = getattr(llama_backend, "hf_variant", None) or ""
    return (
        bool(variant)
        and variant.lower() == resident_variant.lower()
        and _matches_any(base, published)
    )


def _names_the_resident_standard_model(backend, active: str, model_path: str) -> bool:
    """``_names_the_resident_model`` plus the repo id auto-switch advertises for ``active``."""
    return _names_the_resident_model(active, model_path) or _matches_any(
        model_path, [getattr(backend, "_openai_advertised_id", None)]
    )


def _names_the_loading_model(loading: str, model_path: str) -> bool:
    """Matches the picker id too: a pinned row's id is not the path the load runs as."""
    return (
        model_path == loading
        or model_path.lower() == loading.lower()
        or _names_the_resident_model(loading, model_path)
    )


def _resident_standard_model_name(backend, model_path: str) -> str:
    """Returns the registry name to unload, since the backend refuses names it never loaded."""
    active = getattr(backend, "active_model_name", None)
    if isinstance(active, str) and _names_the_resident_standard_model(backend, active, model_path):
        return active
    loaded = getattr(backend, "models", None)
    if isinstance(loaded, dict):
        for name in loaded:
            if isinstance(name, str) and _names_the_resident_model(name, model_path):
                return name
    return model_path


def _unload_evicts_standard_backend(backend, model_path: str) -> bool:
    """Mirrors the backend's refusal to unload a name it never loaded; a stale /unload is not a teardown."""
    active = getattr(backend, "active_model_name", _UNRESOLVED_BACKEND_STATE)
    loaded = getattr(backend, "models", _UNRESOLVED_BACKEND_STATE)
    if active is _UNRESOLVED_BACKEND_STATE and loaded is _UNRESOLVED_BACKEND_STATE:
        return True
    if isinstance(active, str) and active and active.lower() == (model_path or "").lower():
        return True
    if (
        isinstance(active, str)
        and active
        and _names_the_resident_standard_model(backend, active, model_path)
    ):
        return True
    if not isinstance(loaded, dict):
        return False
    return model_path in loaded or any(
        isinstance(name, str) and _names_the_resident_model(name, model_path) for name in loaded
    )


def _unload_may_evict(model_path: str) -> bool:
    """Attribute reads only, no lifecycle gate; True means a branch may fire, never that unload succeeds. A stale answer is safe: each branch re-refuses."""
    backend = get_inference_backend()
    loading = getattr(backend, "get_loading_model", lambda: None)()
    if (
        loading is not None
        and hasattr(backend, "cancel_load")
        and _names_the_loading_model(loading, model_path)
    ):
        return True
    llama_backend = get_llama_cpp_backend()
    if llama_backend.is_active and (
        _names_the_resident_gguf(llama_backend, model_path)
        # Up but not serving is mid-load, evicted whatever model was named.
        or not llama_backend.is_loaded
    ):
        return True
    return _unload_evicts_standard_backend(backend, model_path)


@studio_router.get("/active-generations")
async def get_active_generations(
    fastapi_request: Request,
    current_subject: str = Depends(get_current_subject),
    model: Optional[str] = None,
):
    """return interruptible local generations and the effective decode capacity."""
    scope = account_access.account_scope()
    exclude, only, llama = set(), None, None
    if model and model_slots.slots:
        slot = await asyncio.to_thread(
            model_slots.serving_slot, model, model_slots.visible(), _loaded_satisfies
        )
        if slot is not None:
            only, llama = set(slot.generations), slot.llama
        elif await asyncio.to_thread(
            model_slots.in_slot,
            None,
            # A cached standard-backend model counts as primary: /unload of it stops primary chats.
            lambda: _loaded_satisfies(model)
            or (
                (standard := _peek_inference_backend()) is not None
                and _unload_evicts_standard_backend(standard, model)
            ),
        ):
            exclude |= model_slots.all_generations()
        else:
            only = set()  # an absent model cannot interrupt any generation
    entries = active_generations.snapshot(scope, exclude, only, include_external = False)
    # legacy streams record native model paths, so redact them at the serialization boundary.
    for _entry in entries:
        if isinstance(_entry.get("model"), str):
            _entry["model"] = redact_native_paths(_entry["model"])
    slots = 1
    try:
        slots = _openai_llama_admission_capacity(fastapi_request, llama or get_llama_cpp_backend())
    except Exception:
        slots = int(getattr(fastapi_request.app.state, "llama_parallel_slots", 1) or 1)
    return {
        "active": entries,
        "count": len(entries),
        "thread_ids": active_generations.active_thread_ids(
            scope, exclude, only, include_external = False
        ),
        "parallel_slots": max(1, int(slots)),
    }


def _mlx_runtime_settings_match(backend, request) -> bool:
    """match normalized MLX settings without forcing reloads for backends that do not record them."""
    entry = backend.models.get(backend.active_model_name, {}) or {}
    if "mlx_kv_quant_requested" not in entry:
        return True
    from core.inference.mlx_inference import (
        encode_mlx_kv_quant,
        normalize_mlx_offload,
        parse_mlx_kv_quant,
    )

    from core.inference.mlx_speculative import mlx_spec_mode

    requested = encode_mlx_kv_quant(*parse_mlx_kv_quant(getattr(request, "mlx_kv_quant", None)))
    return (
        entry["mlx_kv_quant_requested"] == requested
        and (entry.get("chat_template_override_requested") or None)
        == (request.chat_template_override or None)
        and bool(entry.get("mlx_int8_prefill_requested"))
        == bool(getattr(request, "mlx_int8_prefill", False))
        and all(
            normalize_mlx_offload(
                ((entry.get("mlx_offload") or {}).get(part) or {}).get("requested")
            )
            == normalize_mlx_offload(getattr(request, f"mlx_{knob}_offload", None))
            for part, knob in (("ple", "ple"), ("experts", "expert"))
        )
        and entry.get("speculative_type", "auto") == mlx_spec_mode(request.speculative_type)
        and entry.get("spec_draft_model") == (getattr(request, "spec_draft_model", None) or None)
        and entry.get("spec_draft_n_max") == _positive_int_or_none(request.spec_draft_n_max)
    )


def _inherit_resident_load_in_4bit(backend, request, model_identifier: str) -> None:
    """An omitted load_in_4bit keeps the resident precision, not the 4-bit default."""
    if "load_in_4bit" in (getattr(request, "model_fields_set", set()) or set()):
        return
    if not _same_loaded_identifier(backend.active_model_name, model_identifier):
        return
    entry = backend.models.get(backend.active_model_name, {}) or {}
    if entry.get("engine", "auto") != getattr(request, "engine", "auto"):
        return
    resident = entry.get("load_in_4bit_requested")
    if resident is not None:
        request.load_in_4bit = bool(resident)


# Managed-engine launch options a load records and a status echoes; the value is "not set".
_MANAGED_ENGINE_LAUNCH_DEFAULTS = {
    "engine_kv_cache_dtype": "auto",
    "engine_seed": None,
    "engine_gpu_memory_utilization": None,
}


def _managed_engine_launch_fields(model_info) -> dict:
    return {
        field: (model_info or {}).get(field, default)
        for field, default in _MANAGED_ENGINE_LAUNCH_DEFAULTS.items()
    }


def _non_gguf_runtime_settings_match(backend, request) -> bool:
    """Unrecorded resident value counts as a match (UI loads send these anyway); max_seq_length 0 reset is honoured on GGUF only, not here."""
    if getattr(request, "engine", "auto") != "auto" and (
        backend.models.get(backend.active_model_name) or {}
    ).get("engine_precision", "auto") != getattr(request, "engine_precision", "auto"):
        return False

    if getattr(request, "force_reload", False):
        return False
    fields_set = getattr(request, "model_fields_set", set()) or set()
    entry = backend.models.get(backend.active_model_name, {}) or {}
    if entry.get("engine") in ("vllm", "sglang"):
        if entry.get("engine_parallelism", "tensor") != getattr(
            request, "engine_parallelism", "tensor"
        ):
            return False
        for field, default in _MANAGED_ENGINE_LAUNCH_DEFAULTS.items():
            if entry.get(field, default) != getattr(request, field, default):
                return False
        if list(request.gpu_ids or [0]) != list(entry.get("gpu_ids_requested") or [0]):
            return False
    if "max_seq_length" in fields_set and int(request.max_seq_length or 0) > 0:
        resident = entry.get("max_seq_length_requested")
        if resident is not None and int(resident) != int(request.max_seq_length):
            return False
    if "load_in_4bit" in fields_set:
        # As REQUESTED, not resolved: _effective_load_in_4bit rewrites it (LoRA, latest tier), so comparing resolved values would never match.
        resident = entry.get("load_in_4bit_requested")
        if resident is not None and bool(resident) != bool(request.load_in_4bit):
            return False
    return True


class _ScopedLoadAttempt(NamedTuple):
    token: str
    request_id: Optional[str]
    model_path: str
    subject: str
    cancel_event: threading.Event
    cancel_complete: threading.Event


_scoped_load_attempts_lock = threading.Lock()
_scoped_load_attempts: dict[tuple[str, str], _ScopedLoadAttempt] = {}
_scoped_load_cancel_tombstones: dict[tuple[str, str], tuple[str, float]] = {}
_running_load_attempt: Optional[_ScopedLoadAttempt] = None
_pending_load_attempts: dict[str, _ScopedLoadAttempt] = {}
# Latched by cancel_pending_loads, cleared by begin_load_lifecycle; catches admitted-but-unscheduled
# requests during shutdown. Lifecycle-scoped so an embedded host can run_server again.
_loads_shutting_down = False
_SCOPED_LOAD_CANCEL_TOMBSTONE_TTL_S = 60.0
# Bound: nobody may set cancel_complete after a disconnect; an unbounded wait blocks exit.
_SCOPED_LOAD_CANCEL_HANDSHAKE_TIMEOUT_S = 15.0
_SCOPED_LOAD_CANCEL_TOMBSTONE_LIMIT_PER_SUBJECT = 256


def cancel_pending_loads() -> int:
    """Cancels in-flight /load attempts through their own events at shutdown, since the backend flag only guards its own spawn; never blocks on teardown."""
    global _loads_shutting_down
    with _scoped_load_attempts_lock:
        _loads_shutting_down = True
        attempts = list(_pending_load_attempts.values())
        running = _running_load_attempt
    if running is not None and all(a.token != running.token for a in attempts):
        attempts.append(running)
    for attempt in attempts:
        _cancel_for_shutdown(attempt)
    return len(attempts)


def _cancel_for_shutdown(attempt: _ScopedLoadAttempt) -> None:
    """Sets cancel_complete too: at shutdown no /unload will, so the handshake wait would block exit."""
    attempt.cancel_event.set()
    attempt.cancel_complete.set()


def retire_account_loads(account_id: str) -> int:
    """Cancel every /load the account owns. Runs after its tombstone, which refuses later ones."""
    with _scoped_load_attempts_lock:
        attempts = {
            attempt.token: attempt
            for attempt in (*_pending_load_attempts.values(), *_scoped_load_attempts.values())
            if attempt.subject == account_id
        }
        running = _running_load_attempt
        if running is not None and running.subject == account_id:
            attempts[running.token] = running
    for attempt in attempts.values():
        _cancel_for_shutdown(attempt)
    return len(attempts)


def begin_load_lifecycle() -> None:
    """Clear the shutdown latch so a restarted server accepts loads again."""
    global _loads_shutting_down
    with _scoped_load_attempts_lock:
        _loads_shutting_down = False


def _prune_scoped_load_cancel_tombstones(now: float) -> None:
    expired = [
        key for key, (_, expires_at) in _scoped_load_cancel_tombstones.items() if expires_at <= now
    ]
    for key in expired:
        _scoped_load_cancel_tombstones.pop(key, None)


def _begin_load_attempt(request: LoadRequest, current_subject: str) -> _ScopedLoadAttempt:
    if account_access.account_scope() is not None:
        current_subject = current_account_id()
    attempt = _ScopedLoadAttempt(
        token = uuid.uuid4().hex,
        request_id = request.load_request_id,
        model_path = request.model_path,
        subject = current_subject,
        cancel_event = threading.Event(),
        cancel_complete = threading.Event(),
    )
    if attempt.request_id is None:
        return attempt
    key = (current_subject, attempt.request_id)
    with _scoped_load_attempts_lock:
        now = time.monotonic()
        _prune_scoped_load_cancel_tombstones(now)
        if key in _scoped_load_attempts:
            raise HTTPException(
                status_code = 409,
                detail = "A load with this request ID is already in progress",
            )
        tombstone = _scoped_load_cancel_tombstones.pop(key, None)
        if (
            tombstone is not None
            and tombstone[0].strip().casefold() == attempt.model_path.strip().casefold()
        ):
            attempt.cancel_event.set()
            attempt.cancel_complete.set()
        _scoped_load_attempts[key] = attempt
    return attempt


def _finish_load_attempt(attempt: _ScopedLoadAttempt) -> None:
    if attempt.request_id is None:
        return
    key = (attempt.subject, attempt.request_id)
    with _scoped_load_attempts_lock:
        if _scoped_load_attempts.get(key) is attempt:
            _scoped_load_attempts.pop(key, None)


def _cancel_scoped_load_attempt(
    request: UnloadRequest, current_subject: str
) -> tuple[Optional[_ScopedLoadAttempt], bool]:
    if account_access.account_scope() is not None:
        current_subject = current_account_id()
    request_id = request.cancel_load_request_id
    if request_id is None:
        return None, False
    key = (current_subject, request_id)
    with _scoped_load_attempts_lock:
        now = time.monotonic()
        _prune_scoped_load_cancel_tombstones(now)
        attempt = _scoped_load_attempts.get(key)
        if attempt is None:
            subject_tombstones = [
                tombstone_key
                for tombstone_key in _scoped_load_cancel_tombstones
                if tombstone_key[0] == current_subject
            ]
            if len(subject_tombstones) >= _SCOPED_LOAD_CANCEL_TOMBSTONE_LIMIT_PER_SUBJECT:
                oldest = min(
                    subject_tombstones,
                    key = lambda item: _scoped_load_cancel_tombstones[item][1],
                )
                _scoped_load_cancel_tombstones.pop(oldest, None)
            _scoped_load_cancel_tombstones[key] = (
                request.model_path,
                now + _SCOPED_LOAD_CANCEL_TOMBSTONE_TTL_S,
            )
            return None, False
        if attempt.model_path.strip().casefold() != request.model_path.strip().casefold():
            return None, False
        attempt.cancel_event.set()
        is_running = _running_load_attempt is attempt
        if not is_running:
            # No backend teardown will signal a queued/completed attempt, so complete it here.
            attempt.cancel_complete.set()
        return attempt, is_running


def _hub_access_warnings(token_rejections) -> list[str]:
    """What this request's Hub reads tell the user: a refused token, a refused repo's copy."""
    warnings = [HUB_TOKEN_REJECTED_WARNING] if token_rejections.recovered else []
    warnings += [
        hub_refused_cached_copy_warning(repo)
        for repo in dict.fromkeys(token_rejections.served_from_cache)
    ]
    return warnings


def _with_token_rejected_warning(response, token_rejections):
    """Tell the user the model loaded without their token, or from a copy the Hub now refuses."""
    warnings = _hub_access_warnings(token_rejections)
    if not warnings or not isinstance(response, LoadResponse):
        return response
    existing = response.memory_warning
    warning = " ".join(([existing] if existing else []) + warnings)
    return response.model_copy(update = {"memory_warning": warning})


def _remember_hub_access_warning(response, token_rejections) -> None:
    """Keep a GGUF load's Hub notice for /status, whose warning the client re-shows after a load."""
    if isinstance(response, LoadResponse) and response.is_gguf:
        warnings = _hub_access_warnings(token_rejections)
        get_llama_cpp_backend().hub_access_warning = " ".join(warnings) or None


def _status_load_warning(llama_backend) -> Optional[str]:
    """The running GGUF's load warning as its load response carried it."""
    notices = (llama_backend.last_load_warning, getattr(llama_backend, "hub_access_warning", None))
    return " ".join(notice for notice in notices if notice) or None


# True only in the user's /load, the one that shows the warning; background loads stay refused.
_load_warnings_reach_user: contextvars.ContextVar[bool] = contextvars.ContextVar(
    "load_warnings_reach_user", default = False
)


def _owner_session(fastapi_request) -> bool:
    """Owner UI session: no managed account and no API key of any kind, internal workflow keys included."""
    if fastapi_request is None or account_access.managed_account():
        return False
    return not _request_has_api_key(fastapi_request)


def _raise_if_load_cancelled(attempt: _ScopedLoadAttempt, impl_kwargs: Optional[dict]) -> None:
    request_cancel = (impl_kwargs or {}).get("load_cancel_event")
    if attempt.cancel_event.is_set() or (request_cancel is not None and request_cancel.is_set()):
        raise HTTPException(status_code = 409, detail = "Model load cancelled")


async def _run_tracked_load_model_impl(
    request: LoadRequest,
    fastapi_request: Request,
    current_subject: str,
    *,
    attempt: Optional[_ScopedLoadAttempt] = None,
    current_request_counted: bool = False,
    on_reload_confirmed = None,
    impl_kwargs: Optional[dict] = None,
    background: bool = False,
):
    global _running_load_attempt

    owned_attempt = attempt is None
    attempt = attempt or _begin_load_attempt(request, current_subject)
    impl_kwargs = dict(impl_kwargs or {})
    request_cancel = impl_kwargs.pop("load_cancel_event", None)
    follow = None
    with _scoped_load_attempts_lock:
        _running_load_attempt = attempt
    try:
        if request_cancel is not None:
            # /unload, shutdown and account retirement cancel through the attempt's event.
            async def _follow_request_cancel():
                while not attempt.cancel_event.is_set():
                    if request_cancel.is_set():
                        _cancel_for_shutdown(attempt)
                        return
                    await asyncio.sleep(0.1)

            if request_cancel.is_set():
                _cancel_for_shutdown(attempt)
            follow = asyncio.create_task(_follow_request_cancel())
        if attempt.cancel_event.is_set():
            raise HTTPException(status_code = 409, detail = "Model load cancelled")
        warnings_token = _load_warnings_reach_user.set(not background)
        try:
            with collecting_hub_token_rejections() as token_rejections:
                response = await _load_model_impl(
                    request,
                    fastapi_request,
                    current_subject,
                    current_request_counted = current_request_counted,
                    on_reload_confirmed = on_reload_confirmed,
                    load_cancel_event = attempt.cancel_event,
                    **impl_kwargs,
                )
        finally:
            _load_warnings_reach_user.reset(warnings_token)
        response = _with_token_rejected_warning(response, token_rejections)
        _remember_hub_access_warning(response, token_rejections)
        return response
    finally:
        if follow is not None:
            follow.cancel()
        if attempt.cancel_event.is_set() and not attempt.cancel_complete.is_set():
            if not await asyncio.to_thread(
                attempt.cancel_complete.wait, _SCOPED_LOAD_CANCEL_HANDSHAKE_TIMEOUT_S
            ):
                logger.warning(
                    "Scoped load cancel did not report back in %.0fs; releasing the load: %s",
                    _SCOPED_LOAD_CANCEL_HANDSHAKE_TIMEOUT_S,
                    request.model_path,
                )
        with _scoped_load_attempts_lock:
            if _running_load_attempt is attempt:
                _running_load_attempt = None
        if owned_attempt:
            _finish_load_attempt(attempt)


@router.post("/load", response_model = LoadResponse)
@account_access.gpu_busy_route
async def load_model(
    request: LoadRequest,
    fastapi_request: Request,
    current_subject: str = Depends(get_current_subject),
):
    """
    Load a model for inference.

    model_path is a clean identifier from GET /models/list. Returns inference
    config (temperature, top_p, top_k, min_p) from the model's YAML, falling
    back to default.yaml for missing values.

    GGUF models load via llama-server (llama.cpp) instead of Unsloth.
    """
    named = request.model_path
    if _resolve_trained_run_request(request):
        # keeps the job's name as the served id, so chat and /v1/models answer to it
        request._advertised_id = request._advertised_id or named
    return await _tunnel_safe_json(
        load_model_gated(request, fastapi_request, current_subject, user_initiated = True),
        label = "Model load",
    )


def _repo_is_in_the_hub_cache(model_ref) -> Optional[bool]:
    """``None`` when the question does not arise or cannot be answered."""
    try:
        from hub.utils import hf_tokens as _hf_tokens

        repo = (model_ref or "").strip()
        if not repo or "/" not in repo or repo.startswith((".", "/", "~")) or ":" in repo[:3]:
            return None
        return bool(_hf_tokens._repo_present_on_disk(repo, "model"))
    except Exception:  # noqa: BLE001 -- a load never fails on its own bookkeeping
        return None


def _hub_cache_footprint(model_ref) -> Optional[tuple]:
    """Only ``blobs/`` counts: ``refs/`` and ``.no_exist`` are written by a cache HIT too."""
    try:
        from hub.utils.hf_cache_state import iter_repo_cache_dirs

        repo = (model_ref or "").strip()
        if not repo or "/" not in repo or repo.startswith((".", "/", "~")) or ":" in repo[:3]:
            return None
        count = total = 0
        errors: list = []
        for repo_dir in iter_repo_cache_dirs("model", repo, scan_errors = errors):
            for blob in (repo_dir / "blobs").iterdir():
                if blob.is_symlink() or not blob.is_file():
                    continue
                count += 1
                total += blob.stat().st_size
        # A root that could not be listed makes the comparison meaningless rather than equal.
        return None if errors else (count, total)
    except FileNotFoundError:
        return (0, 0)
    except Exception:  # noqa: BLE001 -- a load never fails on its own bookkeeping
        return None


def _load_fetched_bytes(model_ref, cached_before, footprint_before) -> bool:
    """Only usable where the caller AWAITED the fetch; the media loads decide at entry instead.
    A wrong record withholds a public cached copy permanently, so a reading that could not be
    taken is not evidence, and GROWTH is the test, not difference (a SHRUNK cache was pruned)."""
    if cached_before is False and _repo_is_in_the_hub_cache(model_ref):
        return True
    if cached_before is not True or footprint_before is None:
        return False
    footprint_after = _hub_cache_footprint(model_ref)
    if footprint_after is None:
        return False
    # Per component, so a prune racing an arrival still reads as a fetch.
    return any(after > before for after, before in zip(footprint_after, footprint_before))


def _lora_base_already_in_the_hub_cache(model_ref) -> Optional[str]:
    """Resolvable only once the adapter itself is cached; otherwise this load brings both in."""
    try:
        from utils.transformers_version import _adapter_base_from_hf_cache
        base = _adapter_base_from_hf_cache(model_ref) if model_ref else None
    except Exception:  # noqa: BLE001 -- a load never fails on its own bookkeeping
        return None
    return base if base and _repo_is_in_the_hub_cache(base) else None


def _note_lora_base_fetched_with_a_request_token(
    model_ref,
    hf_token,
    already_cached = None,
) -> None:
    """Read from the hub cache, not the network: an unresolvable base has no record, so REFUSES."""
    try:
        from utils.transformers_version import _adapter_base_from_hf_cache
        base = _adapter_base_from_hf_cache(model_ref) if model_ref else None
    except Exception:  # noqa: BLE001 -- a load never fails on its own bookkeeping
        return
    # A base ALREADY here was not fetched by this load; recording it withholds a public model.
    if base and base != model_ref and base != already_cached and _repo_is_in_the_hub_cache(base):
        _note_load_fetched_with_a_request_token(base, hf_token)


def _note_load_fetched_with_a_request_token(model_ref, hf_token) -> None:
    """A load auto-downloads through its own loader, not the download lifecycle. Never local."""
    try:
        from hub.utils import hf_tokens as _hf_tokens

        repo = (model_ref or "").strip()
        if not repo or "/" not in repo or repo.startswith((".", "/", "~")) or ":" in repo[:3]:
            return
        _hf_tokens.note_repo_fetched_with_a_request_token(hf_token, repo, "model")
    except Exception:  # noqa: BLE001 -- a load never fails on its own bookkeeping
        pass


async def load_model_gated(
    request: LoadRequest,
    fastapi_request: Request,
    current_subject: str,
    *,
    user_initiated: bool = False,
    current_request_counted: bool = False,
    impl_kwargs: Optional[dict] = None,
    background: bool = False,
):
    """Everything ``POST /load`` does except the tunnel-safe padding.

    In-process callers (preview) must await THIS, not the route: the route's slow
    path returns a StreamingResponse nobody in-process drains, so awaiting it would
    return mid-load and hide a late failure in an unread body. This blocks until the
    model is resident and raises the real exception.
    """
    if is_decision_api_model(request.model_path):
        raise HTTPException(
            status_code = 400,
            detail = (
                "This is a Decision API model, not a chat model. "
                "Use it from Settings > API > Decision API (POST /v1/systemone)."
            ),
        )
    # A sidecar install that has reserved the swap must not lose to a load that
    # then gets unloaded by the pre-swap teardown. Rechecked under the gate: an
    # install can reserve while this request queues on the gate, so the pre-gate
    # check alone is only a fast path.
    from core.inference.gpu_arbiter import (
        MultiModelAlwaysRefusal,
        eviction_sink,
        note_evictions,
        refusal_for,
    )
    from core.inference.llama_cpp import GpuMemoryShortError
    from core.inference.llama_keepwarm import inference_lifecycle_gate, model_load_gate

    extra = None
    evicted: list[str] = []
    # Every model this load unloads, as {kind, model}: kept slots dropped here and anything the arbiter evicts.
    evicted_slots: list[dict] = []
    replaced_slots: list[dict] = []
    replaced_token = None
    # Indices of evicted_slots that already have a legacy ``_model_key`` entry in ``evicted``.
    keyed: set[int] = set()

    def note_keyed(reports) -> None:
        start = len(evicted_slots)
        note_evictions(reports)
        keyed.update(range(start, len(evicted_slots)))

    sink_token = None
    attempt = _begin_load_attempt(request, current_subject)
    with _scoped_load_attempts_lock:
        _pending_load_attempts[attempt.token] = attempt
        # Under the latch lock; a load registered after the shutdown sweep snapshot is never cancelled by it, so check the latch here too.
        _shutting_down_now = _loads_shutting_down
    if _shutting_down_now:
        _cancel_for_shutdown(attempt)
    try:
        _raise_if_sidecar_swap_in_progress()
        # Hold the gate so idle auto-unload can't unload mid-load; auto-switch already holds it.
        async with model_load_gate():
            sink_token = eviction_sink.set(evicted_slots)
            replaced_token = _replaced_primary_sink.set(replaced_slots)
            # Chosen under the gate, so two loads cannot both claim an empty primary.
            extra = await _select_load_slot(request)
            new_slot = extra is not None and extra not in model_slots.slots
            if new_slot:
                model_slots.slots.append(extra)
            if extra is not None:
                model_slots.loading = (extra, request.model_path)
                extra.llama._llama_update_in_progress = getattr(
                    _llama_cpp_backend, "_llama_update_in_progress", False
                )
            async with nullcontext() if new_slot else inference_lifecycle_gate():
                _raise_if_sidecar_swap_in_progress()
                if not new_slot:
                    # An auto-switch beside checked before this gate: this load replaces a loaded model.
                    _check_switch_precondition(fastapi_request)
                # The 409 gate runs inside _load_model_impl, under the lifecycle gate, atomic with teardown.
                if new_slot:
                    reload_gate = None
                elif extra is not None:
                    reload_gate = functools.partial(
                        _raise_or_cancel_slot_generations,
                        extra,
                        force = request.force_cancel_active,
                        action = "Reloading this model",
                    )
                elif background:
                    # Under the lifecycle gate the load waits for running chats instead.
                    reload_gate = None
                else:
                    reload_gate = functools.partial(
                        _raise_or_cancel_active_generations,
                        force = request.force_cancel_active,
                        action = "Loading a model",
                    )

                _primary_can_retry_fit.set(True)
                while True:
                    try:
                        response = await _run_tracked_load_model_impl(
                            request,
                            fastapi_request,
                            current_subject,
                            attempt = attempt,
                            current_request_counted = current_request_counted,
                            on_reload_confirmed = reload_gate,
                            impl_kwargs = impl_kwargs,
                            background = background,
                        )
                        break
                    except (GpuMemoryShortError, HTTPException) as exc:
                        # Before any eviction below: a cancelled load unloads nothing to make room.
                        _raise_if_load_cancelled(attempt, impl_kwargs)
                        measured = isinstance(exc, GpuMemoryShortError)
                        if not measured:
                            if extra is None and _ran_out_of_memory(exc):
                                await asyncio.to_thread(_refuse_oom_beside_media_under_always)
                            # A non-GGUF load reports no fit up front: its out-of-memory failure
                            # makes room the same way, one idle kept model at a time.
                            if extra is None or not _ran_out_of_memory(exc):
                                raise
                            detail = exc.detail
                            exc = GpuMemoryShortError(
                                str(detail.get("message") or detail)
                                if isinstance(detail, dict)
                                else str(detail)
                            )
                        if extra is None:
                            # Only a primary beside an image or video model refuses a partial fit.
                            request = await _make_room_for_primary(request, exc, evicted)
                            continue
                        from utils.multi_model_settings import get_multi_model_mode

                        if await asyncio.to_thread(get_multi_model_mode) == "always":
                            # Always unloads nothing: try once more beside the others, else refuse.
                            if (
                                exc.capped or getattr(exc, "host", False)
                            ) and not request.force_alongside:
                                request = request.model_copy(update = {"force_alongside": True})
                                continue
                            if measured and not account_access.managed_account():
                                # Its Always copy already says nothing is unloaded to make room.
                                raise MultiModelAlwaysRefusal(str(exc), kind = "chat") from exc
                            raise refusal_for(
                                await asyncio.to_thread(chat_eviction_reports)
                            ) from exc
                        # The new slot loads with no gate against chats: recheck before anything is unloaded.
                        _check_switch_precondition(fastapi_request)
                        # An idle image or video model goes before any chat model, as gpu_residency orders it.
                        if await _free_for_chat(exc, evicted, media_only = True):
                            continue
                        # No chat may start on a victim between its pick and teardown.
                        async with inference_lifecycle_gate() if new_slot else nullcontext():
                            _check_switch_precondition(fastapi_request)
                            victims = await asyncio.to_thread(
                                model_slots.eviction_victims,
                                extra,
                                exc.short_mib,
                                exc.gpu_indices,
                                exc.discrete,
                            )
                            # Named before the drop, while their public ids are still live.
                            reports = await asyncio.to_thread(
                                lambda: {slot: _kept_slot_reports(slot) for slot in victims}
                            )
                            dropped = await asyncio.to_thread(model_slots.evict_these, victims)
                        note_keyed([r for slot in dropped for r in reports.get(slot, ())])
                        if not dropped:
                            # An active model off the short GPUs frees nothing there: load beside it.
                            if exc.capped or (
                                not request.force_alongside
                                and await asyncio.to_thread(
                                    model_slots.in_slot,
                                    None,
                                    lambda: _active_model_holds_none_of(exc),
                                )
                            ):
                                request = request.model_copy(update = {"force_alongside": True})
                                continue
                            # Fits nowhere: replace the active model; its chats refuse first.
                            routed_slot.set(None)
                            if not background:
                                _raise_or_cancel_active_generations(
                                    force = request.force_cancel_active,
                                    action = "Loading a model",
                                    cancel = False,
                                )
                            await asyncio.to_thread(model_slots.drop, extra)
                            model_slots.loading, extra = None, None
                            replaced = _primary_model_label()
                            replaced_reports = await asyncio.to_thread(
                                model_slots.in_slot, None, _primary_chat_reports
                            )
                            request = request.model_copy(
                                update = {"alongside": False, "force_alongside": False}
                            )
                            async with inference_lifecycle_gate() if new_slot else nullcontext():
                                if background:
                                    await _wait_for_model_switch_idle(
                                        current_request_counted = current_request_counted
                                    )
                                    # The drain can outlast a sidecar install or a cancel: never unload for nothing.
                                    _raise_if_sidecar_swap_in_progress()
                                    _raise_if_load_cancelled(attempt, impl_kwargs)
                                    # A user back during the drain keeps their model.
                                    _check_switch_precondition(fastapi_request)
                                else:
                                    _raise_or_cancel_active_generations(
                                        force = request.force_cancel_active,
                                        action = "Loading a model",
                                    )
                                victims = await asyncio.to_thread(
                                    model_slots.in_slot,
                                    None,
                                    lambda: _kept_victims_beside_primary(exc),
                                )
                                reports = await asyncio.to_thread(
                                    lambda: {slot: _kept_slot_reports(slot) for slot in victims}
                                )
                                dropped = await asyncio.to_thread(model_slots.evict_these, victims)
                                note_keyed([r for slot in dropped for r in reports.get(slot, ())])
                                evicted += [
                                    _model_key(s.request) for s in dropped if s.request is not None
                                ]
                                # As a pick does before a switch: the active model goes first, so
                                # the new one is placed on a GPU it no longer shares.
                                await asyncio.to_thread(_unload_primary)
                                note_keyed(replaced_reports)
                                # No retry follows this load, so it must not refuse a partial fit beside media.
                                _primary_can_retry_fit.set(False)
                                response = await _run_tracked_load_model_impl(
                                    request,
                                    fastapi_request,
                                    current_subject,
                                    attempt = attempt,
                                    current_request_counted = current_request_counted,
                                    on_reload_confirmed = None,
                                    impl_kwargs = impl_kwargs,
                                    background = background,
                                )
                            evicted += [replaced] if replaced else []
                            break
                        evicted += [_model_key(s.request) for s in dropped if s.request is not None]
                        logger.info(
                            "Unloaded %d model(s) loaded alongside to fit %s",
                            len(dropped),
                            request.model_path,
                        )
                        extra.llama._last_kill_monotonic = time.monotonic()
            if extra is not None:
                from core.inference.llama_keepwarm import _note_activity

                extra.request = request
                extra.last_used = time.monotonic()
                # A fresh load is use: without it the idle loop drops the slot on its next tick.
                _note_activity()
        # Record provenance once resident, here so the fast paths are covered; outside the gate. Preview keeps False: only an explicit UI load pins.
        get_llama_cpp_backend()._loaded_by_user_action = user_initiated
        standard = _peek_inference_backend()
        if getattr(standard, "active_model_name", None):
            standard._loaded_by_user_action = user_initiated
        # Every other model this load unloaded is listed too, under its model id: idle kept models,
        # kept models a vLLM/SGLang load retired and media a chat load freed.
        evicted += [
            slot["model"]
            for index, slot in enumerate(evicted_slots)
            if slot.get("model") and index not in keyed
        ]
        if isinstance(response, LoadResponse):
            if evicted:
                response.evicted = evicted
            # A retried attempt can name the same model twice.
            response.evicted_slots = [
                dict(pair)
                for pair in dict.fromkeys(
                    tuple(slot.items()) for slot in [*evicted_slots, *replaced_slots]
                )
            ]
        return response
    except MultiModelAlwaysRefusal as exc:
        path = getattr(getattr(fastapi_request, "url", None), "path", None)
        raise exc.as_http_exception(path) from exc
    finally:
        if sink_token is not None:
            eviction_sink.reset(sink_token)
        if replaced_token is not None:
            _replaced_primary_sink.reset(replaced_token)
        try:
            if extra is not None:
                model_slots.loading = None
                if extra not in model_slots.slots or not model_slots.in_use(extra):
                    await asyncio.to_thread(model_slots.drop, extra)
                    await asyncio.to_thread(release_chat_gpu_claim)
        finally:
            _primary_can_retry_fit.set(False)
            # A slot that would not stop stays stuck, but this attempt is over either way.
            with _scoped_load_attempts_lock:
                _pending_load_attempts.pop(attempt.token, None)
            _finish_load_attempt(attempt)


def _refuse_oom_beside_media_under_always() -> None:
    """Under Always a chat load that ran out of memory beside an image or video model is refused, not retried."""
    from core.inference import gpu_arbiter, gpu_residency

    held = gpu_arbiter.residents()
    chat_gpus = held.get(gpu_arbiter.CHAT)
    # Only a model sharing a GPU with chat could have caused it; None (unknown) shares every GPU.
    slots = [
        s
        for o in gpu_residency.MEDIA_OWNERS
        if o in held and (chat_gpus is None or held[o] is None or held[o] & chat_gpus)
        for s in gpu_arbiter.resident_slots(o)
    ]
    if slots and gpu_residency.current_policy() == "always":
        raise gpu_arbiter.refusal_for(slots)


def _ran_out_of_memory(exc: HTTPException) -> bool:
    if isinstance(exc.detail, dict):  # a classified audio.cpp failure
        # Out of CPU RAM: evicting GPU models frees none of it.
        return exc.detail.get("code") == "out_of_memory" and exc.detail.get("device") != "cpu"
    return exc.status_code == 500 and "out of memory" in str(exc.detail).lower()


def _gate_kept_models(request: LoadRequest, cancel: bool = True) -> None:
    for slot in list(model_slots.slots):
        _raise_or_cancel_slot_generations(
            slot, force = request.force_cancel_active, cancel = cancel, action = "Loading a model"
        )


async def _retire_kept_models(request: LoadRequest) -> None:
    """vLLM and SGLang reserve the GPU, so a load of either takes the kept models down too: gated
    before any chat is cancelled, torn down once nothing can still reject the load."""
    from core.inference.gpu_arbiter import note_evictions

    _gate_kept_models(request)
    # Named before the teardown, while their public ids are still live.
    kept = await asyncio.to_thread(
        lambda: {slot: _kept_slot_reports(slot) for slot in list(model_slots.slots)}
    )
    await asyncio.to_thread(model_slots.unload_extra_models, strict = True)
    note_evictions(
        [r for slot, found in kept.items() if slot not in model_slots.slots for r in found]
    )


def _unload_primary() -> None:
    llama = get_llama_cpp_backend()
    if llama.is_active:
        llama.unload_model()
    backend = _peek_inference_backend()
    name = getattr(backend, "active_model_name", None)
    if name:
        backend.unload_model(name)


def _active_model_holds_none_of(exc) -> bool:
    """The active llama-server holds nothing on the discrete GPUs ``exc`` was short on; call via
    ``in_slot(None, ...)``. Only a placement the child cannot leave counts: an explicit pin (its
    device mask, widened for companion devices) or no GPU at all. Anything else answers False."""
    llama = get_llama_cpp_backend()
    if not (exc.discrete and exc.gpu_indices and llama.is_active):
        return False
    if getattr(_peek_inference_backend(), "active_model_name", None):
        return False
    if not getattr(llama, "_planned_vram_mib", None) and model_slots.cpu_only(llama):
        return True
    pin = getattr(llama, "_gpu_ids", None)
    return bool(getattr(llama, "_requested_gpu_ids", None) and pin) and not set(pin) & set(
        exc.gpu_indices
    )


def _kept_victims_beside_primary(exc) -> list:
    """Idle kept slots that cover ``exc``'s shortfall together with the active server; call via ``in_slot(None, ...)``."""
    if getattr(exc, "host", False) or not exc.short_mib:
        return []
    gpus = exc.gpu_indices or None
    held = sum(
        mib
        for idx, mib in (getattr(get_llama_cpp_backend(), "_planned_vram_mib", None) or {}).items()
        if not gpus or idx in gpus
    )
    if not held or held >= exc.short_mib:
        return []
    return model_slots.eviction_victims(None, exc.short_mib - held, gpus, exc.discrete)


def _primary_model_label() -> Optional[str]:
    llama = get_llama_cpp_backend()
    if getattr(llama, "is_loaded", False):
        return _llama_public_model_id(llama)
    return getattr(_peek_inference_backend(), "active_model_name", None)


def _orchestrator_chat_report(backend, account) -> Optional[dict]:
    from core.inference.native_audio import NATIVE_AUDIO_TYPES

    name = getattr(backend, "active_model_name", None)
    if not name:
        return None
    entry = (getattr(backend, "models", None) or {}).get(name) or {}
    kind = "audio" if entry.get("audio_type") in NATIVE_AUDIO_TYPES else "chat"
    return {"kind": kind, "model": _orchestrator_public_model_id(backend) or "", "account": account}


def _primary_chat_reports() -> list[dict]:
    """Reports for the loaded primary chat model; call through ``model_slots.in_slot(None, ...)``."""
    from core.inference.npu_backend import peek_npu_backend
    from hub.services.models.account_access import _resident_loader

    account = _resident_loader("chat")
    found = []
    llama = get_llama_cpp_backend()
    if getattr(llama, "is_loaded", False):
        found.append(
            {"kind": "chat", "model": _llama_status_model_ids(llama)[0] or "", "account": account}
        )
    report = _orchestrator_chat_report(_peek_inference_backend(), account)
    if report is not None:
        found.append(report)
    npu = peek_npu_backend()
    npu_model = npu.loaded_model if npu is not None else None
    if npu_model is not None:
        found.append({"kind": "chat", "model": npu_model.id or "", "account": account})
    return found


def _kept_slot_reports(slot) -> list[dict]:
    """Reports for one kept slot, evaluated in the slot as the status code does."""

    def collect() -> list[dict]:
        found = []
        if getattr(slot.llama, "is_loaded", False):
            model = _llama_public_model_id(slot.llama) or ""
            found.append({"kind": "chat", "model": model, "account": slot.account})
        report = _orchestrator_chat_report(slot.orchestrator, slot.account)
        if report is not None:
            found.append(report)
        return found

    try:
        return model_slots.in_slot(slot, collect)
    except Exception as exc:  # noqa: BLE001 - a report never blocks an eviction
        logger.warning("Could not list a model kept alongside: %s", exc)
        return []


def chat_eviction_reports() -> list[dict]:
    """``{kind, model, account}`` for every loaded chat model, read before an eviction tears it down.

    The GPU arbiter calls this under its lock, so it never calls back into the arbiter, never
    takes ``model_slots.lock`` and never raises. Models still loading and stuck slots are skipped.
    """
    reports: list[dict] = []
    try:
        reports += model_slots.in_slot(None, _primary_chat_reports)
    except Exception as exc:  # noqa: BLE001 - a report never blocks an eviction
        logger.warning("Could not list the active chat model: %s", exc)
    try:
        filling = model_slots.loading[0] if model_slots.loading else None
        for slot in list(model_slots.slots):
            if slot is not filling:
                reports += _kept_slot_reports(slot)
    except Exception as exc:  # noqa: BLE001
        logger.warning("Could not list the models kept alongside: %s", exc)
    return reports


# The serving primary an ordinary load replaces, reported in ``evicted_slots`` only: the legacy
# ``evicted`` list drives the "to make room" toast, which an ordinary switch must not show.
_replaced_primary_sink: contextvars.ContextVar[Optional[list]] = contextvars.ContextVar(
    "replaced_primary_sink", default = None
)


async def _guard_primary_replacement(request: LoadRequest, names) -> None:
    """Before any teardown: under Always, refuse a load that would replace the serving primary with
    another repo, or whose vLLM/SGLang engine would retire a kept model. Otherwise report the
    primary such a load replaces."""
    from core.inference.gpu_arbiter import public_slots, refusal_for
    from core.inference.openai_auto_download import split_model_ref
    from utils.multi_model_settings import get_multi_model_mode

    always = await asyncio.to_thread(get_multi_model_mode) == "always"
    sink = _replaced_primary_sink.get()
    if not always and sink is None:
        return
    if always and request.engine != "auto":
        for slot in list(model_slots.slots):
            if model_slots.in_use(slot):
                raise refusal_for(await asyncio.to_thread(_kept_slot_reports, slot))
        # A slot that failed to stop still holds its model, and the retire retries its unload.
        stuck = list(model_slots.stuck)
        if stuck:
            raise refusal_for(await asyncio.to_thread(_kept_slot_reports, stuck[0]), "chat")
    try:
        reports = await asyncio.to_thread(model_slots.in_slot, None, _primary_chat_reports)
    except Exception:  # noqa: BLE001 - unreadable: Always keeps it, as for media
        if always:
            raise refusal_for([], "chat")
        reports = []
    if not reports:
        # A primary restarting after a crash reports no row yet, but Always still keeps it.
        if not (always and await asyncio.to_thread(model_slots.in_slot, None, _primary_respawning)):
            return
    # The bare repo id, so another quant of the same repo is allowed; the full name for an NPU id.
    candidates = dict.fromkeys(
        ref for name in names if name for ref in (split_model_ref(name)[0], name) if ref
    )
    for ref in candidates:
        if await asyncio.to_thread(
            model_slots.in_slot, None, functools.partial(_loaded_satisfies, ref)
        ):
            return
    if always:
        raise refusal_for(reports)
    sink.extend(public_slots(reports))


def _primary_respawning() -> bool:
    llama_backend = get_llama_cpp_backend()
    return bool(getattr(llama_backend, "is_active", False)) and not getattr(
        llama_backend, "is_loaded", False
    )


def _reassert_chat_claim(policy: str) -> None:
    """Re-assert CHAT for a chat model already loaded. Under Always a refusal is ignored: the
    model stays usable and nothing is unloaded."""
    from core.inference.gpu_arbiter import (
        CHAT,
        MultiModelAlwaysRefusal,
        acquire_for_request,
        policy_kwargs,
    )
    try:
        acquire_for_request(CHAT, **policy_kwargs(policy))
    except MultiModelAlwaysRefusal:
        pass


async def _select_load_slot(request: LoadRequest) -> Optional[_ExtraSlot]:
    """The extra slot already serving the model, or a new one for ``alongside``. None is the primary."""
    from core.inference.npu_backend import is_npu_model_path

    # Before the early return: the NPU and managed-engine guards read the primary's name.
    await _reap_exited_workers()
    # The NPU backend is one per process and replaces the primary, so it never takes a slot. vLLM
    # and SGLang reserve a fixed share of the GPU up front, so neither shares it with a kept model.
    if is_npu_model_path(request.model_path) or request.engine != "auto":
        routed_slot.set(None)
        return None
    requested = _model_key(request)
    slot = await _route_to_extra_slot(requested)
    if slot is None and request.gguf_variant:
        # Another quant replaces its repo in place: requests name the repo, so a copy beside it is unreachable.
        slot = await _route_to_extra_slot(request.model_path)
        if slot is not None or await asyncio.to_thread(_loaded_satisfies, request.model_path):
            return slot
    if slot is not None:
        return slot
    from utils.multi_model_settings import get_multi_model_enabled

    # Off unless enabled in Settings; a kept model left busy when disabled is evicted once idle.
    if not await asyncio.to_thread(get_multi_model_enabled):
        if model_slots.slots:
            from core.inference.gpu_arbiter import note_evictions

            kept = await asyncio.to_thread(
                lambda: {slot: _kept_slot_reports(slot) for slot in list(model_slots.slots)}
            )
            await asyncio.to_thread(model_slots.unload_idle)
            note_evictions(
                [r for slot, found in kept.items() if slot not in model_slots.slots for r in found]
            )
        return None
    if not request.alongside:
        return None
    orchestrator = _peek_inference_backend()
    if getattr(orchestrator, "_managed_engine", None) is not None:
        return None
    occupied = _llama_cpp_backend.is_active or getattr(orchestrator, "active_model_name", None)
    if not occupied or await asyncio.to_thread(_loaded_satisfies, requested):
        return None
    slot = _ExtraSlot(
        await asyncio.to_thread(LlamaCppBackend),
        await asyncio.to_thread(InferenceOrchestrator),
        current_account_id(),
    )
    slot.llama._owns_pidfile = False
    register_serving_backend(slot.llama)
    routed_slot.set(slot)
    return slot


def _restore_alias_if_failed_load_left_the_prior_model(
    backend, prior_alias: Optional[str], prior_active: Optional[str]
) -> None:
    """Restores the alias a load cleared, when a failed load leaves the prior model still serving."""
    if prior_active is None or getattr(backend, "active_model_name", None) != prior_active:
        return
    backend._openai_advertised_id = prior_alias


def _gguf_load_cancelled(llama_backend, load_cancel_event: Optional[threading.Event]) -> bool:
    return llama_backend.load_cancelled() or bool(
        load_cancel_event is not None and load_cancel_event.is_set()
    )


async def _run_gguf_load_attempt(
    llama_backend,
    intent,
    load_cancel_event,
    codec_failures: Optional[list] = None,
) -> bool:
    def load() -> bool:
        loaded = llama_backend.load_model(intent = intent, load_cancel_event = load_cancel_event)
        failure = getattr(llama_backend, "codec_failure", lambda: None)()
        if isinstance(failure, str) and codec_failures is not None:
            codec_failures.append(failure)
        return loaded

    try:
        return await asyncio.to_thread(load)
    except GgufDownloadCancelled:
        return False


async def _require_drafter_access(request) -> None:
    """A named MLX drafter is a second model reference, so the caller needs access to it too."""
    drafter = getattr(request, "spec_draft_model", None)
    if account_access.managed_account() and isinstance(drafter, str) and drafter.strip():
        await asyncio.to_thread(account_access.require_model_access, drafter.strip())


def _discoverable_drafters(model_path: str) -> Optional[list]:
    """The cached drafters a load may attach on its own: any for the owner, else those the account may see."""
    if not account_access.managed_account():
        return None
    return [row["repo_id"] for row in _mlx_cached_drafters(model_path)]


def _require_resolved_base_access(config) -> None:
    """Grants apply to the base in an adapter's config, so it cannot pull a foreign cached base."""
    base = getattr(config, "base_model", None)
    if account_access.managed_account() and isinstance(base, str) and base.strip():
        account_access.require_model_access(base.strip())


async def _managed_engine_request(request):
    """Normalize an optional-engine request; /validate and /load must judge the same one."""
    from core.inference.managed_engine import validate_load

    precision = request.engine_precision
    if (
        "engine_precision" not in request.model_fields_set
        and "load_in_4bit" in request.model_fields_set
        and request.load_in_4bit
    ):
        precision = "int4"
    # Validate the precision the engine will be started with, before anything is unloaded.
    request = request.model_copy(update = {"load_in_4bit": False, "engine_precision": precision})
    try:
        gpu_ids = await asyncio.to_thread(validate_load, request.engine, request)
    except ValueError as exc:
        raise HTTPException(status_code = 400, detail = str(exc)) from exc
    return request.model_copy(update = {"gpu_ids": gpu_ids})


def _managed_engine_unsupported_controls(payload, model_info = None) -> bool:
    reasoning = (model_info or {}).get("reasoning_flags") is not None
    return bool(
        payload.use_adapter is not None
        or (
            not reasoning
            and (
                payload.enable_thinking
                or payload.preserve_thinking
                or payload.reasoning_effort not in (None, "none")
            )
        )
    )


def _reject_unsupported_managed_kind(request, config) -> None:
    if not (config.is_gguf or config.is_lora or config.is_audio):
        return
    detected_kind = (
        "GGUF" if config.is_gguf else "a LoRA adapter" if config.is_lora else "an audio model"
    )
    raise HTTPException(
        status_code = 400,
        detail = (
            f"This model was detected as {detected_kind}. "
            f"The Unsloth {request.engine} integration currently supports text and vision checkpoints. "
            "Choose Default for this model, or select a supported text checkpoint."
        ),
    )


async def _managed_engine_options(request, config, hf_token) -> dict:
    """Metadata checks that must reject before the resident model is released."""
    from core.inference.managed_engine import validate_model
    try:
        return await asyncio.to_thread(
            validate_model,
            config,
            hf_token,
            request.gpu_ids,
            request.engine,
            request.engine_precision,
            request.engine_parallelism,
            kv_cache_dtype = getattr(request, "engine_kv_cache_dtype", "auto"),
            seed = getattr(request, "engine_seed", None),
            gpu_memory_utilization = getattr(request, "engine_gpu_memory_utilization", None),
        )
    except (ValueError, OSError) as exc:
        raise HTTPException(status_code = 400, detail = str(exc)) from exc


def _npu_load_response(resident, status: str) -> LoadResponse:
    model = resident.model
    return LoadResponse(
        status = status,
        model = model.model_path,
        display_name = model.id,
        is_npu = True,
        is_vision = model.vision,
        inference = load_inference_config(model.id),
        context_length = resident.context_length,
        max_context_length = model.max_context_length,
        native_context_length = model.max_context_length,
        context_length_enforced = True,
        context_length_fitted = None,
        supports_reasoning = model.reasoning,
        reasoning_style = "enable_thinking",
        supports_tools = model.tools,
    )


async def _unload_npu_before_local_load() -> None:
    """Unload the NPU model before loading another local model into the primary's seat."""
    from core.inference.npu_backend import peek_npu_backend

    if routed_slot.get() is not None:
        return
    npu = peek_npu_backend()
    if npu is not None and npu.is_loaded:
        logger.info("Unloading the NPU model before loading a local model")
        await asyncio.to_thread(npu.unload)


async def _load_npu_model(
    request: LoadRequest,
    *,
    current_request_counted: bool,
    on_reload_confirmed,
    load_cancel_event: Optional[threading.Event],
) -> LoadResponse:
    """``/load`` for a ``lemonade:<id>`` model: the same swap rules as any local model."""
    from core.inference.npu_backend import (
        NpuError,
        NpuLoadCancelled,
        get_npu_backend,
        model_id_from_path,
    )
    from core.inference.llama_keepwarm import note_model_unloaded

    if account_access.managed_account():
        raise HTTPException(
            status_code = 403,
            detail = "The AMD NPU runtime is available to this installation's owner only.",
        )
    npu = get_npu_backend()
    try:
        model_id = model_id_from_path(request.model_path)
    except NpuError as exc:
        raise HTTPException(status_code = 400, detail = str(exc)) from None
    requested_ctx = (
        request.max_seq_length if request.max_seq_length and request.max_seq_length > 0 else None
    )
    resident = npu.resident()
    if (
        resident is not None
        and resident.model.id == model_id
        and not request.force_reload
        # Exact: Auto after a pin, or a pin after Auto, is a different load.
        and requested_ctx == resident.requested_context_length
    ):
        account_access.join_resident("chat")
        return _npu_load_response(resident, "already_loaded")
    try:
        await asyncio.to_thread(npu.loadable_model, model_id)
    except NpuError as exc:
        raise HTTPException(status_code = 400, detail = str(exc)) from None
    # The NPU model replaces the primary: under Always only the one already serving may reload.
    # After the checks above, so a request that can only fail never asks to unload a model.
    if routed_slot.get() is None:
        await _guard_primary_replacement(request, (request.model_path,))
    llama_backend = get_llama_cpp_backend()
    unsloth_backend = _peek_inference_backend()
    serving = bool(
        getattr(llama_backend, "is_active", getattr(llama_backend, "is_loaded", False))
        or (unsloth_backend is not None and unsloth_backend.active_model_name)
        or resident is not None
    )
    _raise_if_sidecar_swap_in_progress()
    if serving:
        # Drain active inference before unloading, as for GGUF: an auto-switch has no
        # on_reload_confirmed, so this drain alone keeps it from cutting a reply short.
        if on_reload_confirmed is not None:
            on_reload_confirmed(cancel = False)
        await _wait_for_model_switch_idle(
            current_request_counted = current_request_counted,
            cancel_pending = on_reload_confirmed is not None and bool(request.force_cancel_active),
        )
    # The rechecks the GGUF and standard paths make before their point of no return: an
    # auto-switch has no scoped attempt for the shutdown sweep to cancel.
    _raise_if_sidecar_swap_in_progress()
    with _scoped_load_attempts_lock:
        shutting_down = _loads_shutting_down
    if shutting_down or (load_cancel_event is not None and load_cancel_event.is_set()):
        raise HTTPException(status_code = 409, detail = "Model load cancelled")
    if on_reload_confirmed is not None:
        on_reload_confirmed(cancel = True)
        if request.force_cancel_active:
            await _wait_for_model_switch_idle(
                current_request_counted = current_request_counted,
                timeout_s = _POST_CANCEL_DRAIN_TIMEOUT_S,
            )
    _set_preview_resident(None)
    await _unload_llama_before_standard_load(llama_backend)
    backend = _peek_inference_backend()
    if backend is not None and backend.active_model_name:
        logger.info(
            f"Unloading Unsloth model '{backend.active_model_name}' before loading on the NPU"
        )
        await asyncio.to_thread(backend.unload_model, backend.active_model_name)
    # Nothing to reload once idle: this model is not the one the idle stash names.
    note_model_unloaded()
    await asyncio.to_thread(release_chat_gpu_claim)
    if load_cancel_event is not None and load_cancel_event.is_set():
        raise HTTPException(status_code = 409, detail = "Model load cancelled")
    load = asyncio.ensure_future(asyncio.to_thread(npu.load, model_id, requested_ctx))
    if load_cancel_event is not None:
        # Stop the load mid-way, as a GGUF load polls its cancel event.
        while not load.done():
            await asyncio.wait({load}, timeout = 0.25)
            # False until npu.load marks itself in flight, so keep asking.
            if load_cancel_event.is_set() and not load.done():
                if await asyncio.to_thread(npu.cancel_load, model_id):
                    break
    try:
        await load
    except NpuLoadCancelled:
        raise HTTPException(status_code = 409, detail = "Model load cancelled") from None
    except NpuError as exc:
        raise HTTPException(status_code = 400, detail = str(exc)) from None
    if load_cancel_event is not None and load_cancel_event.is_set():
        # Cancelled before npu.load marked itself in flight, so cancel_load found nothing to stop.
        await asyncio.to_thread(npu.unload)
        raise HTTPException(status_code = 409, detail = "Model load cancelled")
    resident = npu.resident()
    if resident is None:
        raise HTTPException(status_code = 409, detail = "Model load cancelled")
    account_access.publish_resident("chat", request.model_path)
    api_monitor.record_lifecycle(event = "load", model = request.model_path)
    return _npu_load_response(resident, "loaded")


async def _load_model_impl(
    request: LoadRequest,
    fastapi_request: Request,
    current_subject: str,
    *,
    current_request_counted: bool = False,
    on_reload_confirmed = None,
    allow_gpu_owner_eviction: bool = True,
    load_cancel_event: Optional[threading.Event] = None,
    cache_environment: Optional[dict[str, str]] = None,
    anonymous_hf_access: bool = False,
    speech_codec_path: Optional[str] = None,
):
    from core.inference.npu_backend import is_npu_model_path

    if is_npu_model_path(request.model_path):
        return await _load_npu_model(
            request,
            current_request_counted = current_request_counted,
            on_reload_confirmed = on_reload_confirmed,
            load_cancel_event = load_cancel_event,
        )

    engine_options = None
    if request.engine != "auto":
        request = await _managed_engine_request(request)
    native_access_deferred = _defers_access_to_native_grant(request)
    if account_access.managed_account() and not native_access_deferred:
        await asyncio.to_thread(account_access.require_model_access, request.model_path)
    await _require_drafter_access(request)
    request = await asyncio.to_thread(_as_ollama_manifest_request, request)
    _requested_model_id = request.model_path
    request = await asyncio.to_thread(
        _as_local_scan_folder_request, request, _owner_session(fastapi_request)
    )
    # The client keeps the repo id it picked as the checkpoint; only the load reads the copy.
    scan_folder_public_id = (
        _requested_model_id if request.model_path != _requested_model_id else None
    )
    if account_access.managed_account():
        request = request.model_copy(
            update = {"hf_token": account_access.account_hf_token(request.hf_token)}
        )
    # A one-off X-Unsloth-HF-Token keeps no record, so record provenance in the finally; header presence alone is not the test (an existing repo can gain blobs).
    _cached_before_this_load = _repo_is_in_the_hub_cache(request.model_path)
    _cache_footprint_before = _hub_cache_footprint(request.model_path)
    _lora_base_before_this_load = _lora_base_already_in_the_hub_cache(request.model_path)
    from core.inference.llama_cpp import GpuMemoryShortError, LlamaServerNotFoundError
    from core.inference.gpu_arbiter import MultiModelAlwaysRefusal

    def _raise_if_scoped_load_cancelled() -> None:
        if load_cancel_event is not None and load_cancel_event.is_set():
            raise HTTPException(status_code = 409, detail = "Model load cancelled")
        # Retirement sweeps registered attempts; a load it raced is refused here, before the GPU.
        account_access.require_live_account()

        # Auto-switch and preview have no _ScopedLoadAttempt; read the shutdown latch here.
        with _scoped_load_attempts_lock:
            _shutting_down_now = _loads_shutting_down
        if _shutting_down_now:
            raise HTTPException(status_code = 409, detail = "Model load cancelled")

    # Arm the throttle so even an instant 100% load logs its first step.
    _reset_load_progress_step()

    # Live "loading" row: discarded if already loaded, relabelled on the real id, closed on exit.
    _load_event = api_monitor.record_lifecycle(
        event = "load",
        model = _lifecycle_model_label(request.model_path, request.gguf_variant),
        running = True,
        # Auto-switch loads run before the request row opens, so a failure leaves only this.
        via_api_key = _request_used_api_key(fastapi_request),
        # The row is shared, so name its owner or the overlay pops open in unrelated tabs.
        subject = current_subject,
    )

    native_grant_backed = False
    model_log_label = request.model_path
    gguf_load_stack = ExitStack()
    token_rejections = gguf_load_stack.enter_context(collecting_hub_token_rejections())
    try:
        # Validate up front so a managed-flag collision 400s before any model work.
        try:
            extra_llama_args = validate_extra_args(request.llama_extra_args)
        except ValueError as exc:
            # Keep the curated validation message (names the flag); just strip paths.
            logger.warning("inference.validate_extra_args_failed: %s", exc)
            raise HTTPException(
                status_code = 400,
                detail = redact_native_paths(str(exc)),
            )
        # Restore None so inheritance can tell 'omitted' from explicit [].
        extra_llama_args: Optional[list[str]] = (
            None if request.llama_extra_args is None else extra_llama_args
        )
        _refuse_managed_custom_projector(
            extra_llama_args, request.model_path, request._override_alias_id, request.gguf_variant
        )

        _reasoning_updates = {}
        _reasoning_budget_override = parse_reasoning_budget_override(extra_llama_args)
        if _reasoning_budget_override is not None:
            _reasoning_updates["reasoning_budget"] = _reasoning_budget_override
        _reasoning_message_override = parse_reasoning_budget_message_override(extra_llama_args)
        if _reasoning_message_override is not None:
            _reasoning_updates["reasoning_budget_message"] = _reasoning_message_override

        # Manual owns offload flags: promote -ngl/-ts into fields before stripping.
        if request.gpu_memory_mode == "manual" and extra_llama_args:
            _manual_updates: dict[str, Any] = {}
            _gpu_layers_override = parse_gpu_layers_override(extra_llama_args)
            if _gpu_layers_override is not None:
                _manual_updates["gpu_layers"] = _gpu_layers_override
            # Reserialize only where the launcher rewrites the ratio (_should_strip_tensor_split); Auto layers drop both copies before argv. Return 400, not 500.
            _resolved_layers = (
                _gpu_layers_override
                if _gpu_layers_override is not None
                else getattr(request, "gpu_layers", -1)
            )
            try:
                _tensor_split_override = parse_tensor_split_override(
                    extra_llama_args, reserialized = _resolved_layers >= 0
                )
            except ValueError as exc:
                raise HTTPException(status_code = 400, detail = redact_native_paths(str(exc))) from exc
            if _tensor_split_override is not None:
                _manual_updates["tensor_split"] = _tensor_split_override
            if _manual_updates:
                request = request.model_copy(update = _manual_updates)
            _stripped_explicit = strip_shadowing_flags(
                extra_llama_args,
                strip_context = False,
                strip_cache = False,
                strip_spec = False,
                strip_template = False,
                strip_split_mode = False,
                strip_tensor_split = _should_strip_tensor_split(request),
                strip_offload = True,
            )
            if _stripped_explicit != extra_llama_args:
                logger.info(
                    "Manual GPU memory owns the offload flags; stripping them "
                    "from explicit llama_extra_args: %s -> %s",
                    extra_llama_args,
                    _stripped_explicit,
                )
                extra_llama_args = _stripped_explicit

        # Downstream (incl. already-loaded comparison) must see the normalized list.
        request = request.model_copy(update = {"llama_extra_args": extra_llama_args})
        if _reasoning_updates:
            request = request.model_copy(update = _reasoning_updates)

        resolved_ollama_path = await _lease_ollama_model_ref(
            request,
            operation = "load-model",
            stack = gguf_load_stack,
        )
        model_identifier, model_log_label, native_grant_backed = (
            _resolve_model_identifier_for_request(
                request,
                operation = "load-model",
                resolved_ollama_path = resolved_ollama_path,
            )
        )
        if native_access_deferred:
            await asyncio.to_thread(account_access.require_model_access, model_identifier)

        # Keep the inventory ref public while loading the materialized artifact.
        public_model_identifier = _public_model_identifier(request.model_path, model_identifier)
        # Only when unset: auto-switch and the idle stash own their scope. Walks snapshots/, so off-loop.
        if not request._gguf_companion_roots and not request._gguf_companion_roots_set:
            request._gguf_companion_roots = await asyncio.to_thread(
                _path_load_companion_roots, model_identifier, native_grant_backed
            )
            request._gguf_companion_roots_set = True
        ollama_advertised_id = (
            await asyncio.to_thread(ollama_model_ref_public_id, request.model_path)
            if resolved_ollama_path is not None
            else request._advertised_id
        )
        # Resolve once so the reload-dedup check and load_model compare the same template.
        effective_chat_template_override = resolve_effective_chat_template_override(
            model_identifier = model_identifier,
            user_override = request.chat_template_override,
        )

        # Reclaim the GPU only once the load is known viable, so a doomed load evicts nothing.
        from core.inference.gpu_arbiter import (
            acquire_for_request,
            holds,
            policy_kwargs,
            CHAT,
            DIFFUSION,
            VIDEO,
        )

        # ── Already-loaded check: skip reload if the exact model is active ──
        backend = await asyncio.to_thread(get_inference_backend)
        llama_backend = get_llama_cpp_backend()
        replacing = routed_slot.get() is None
        serving = bool(
            getattr(llama_backend, "is_active", getattr(llama_backend, "is_loaded", False))
            or getattr(backend, "active_model_name", None)
            or (replacing and _resident_npu_model() is not None)
        )
        # Under Always, a load that would unload the serving primary or a kept model is refused
        # here, before any teardown; another quant, context or engine of the same repo is not.
        if replacing and (
            serving or (request.engine != "auto" and (model_slots.slots or model_slots.stuck))
        ):
            # A native lease's model_path is only its display label; the granted path is the identity.
            await _guard_primary_replacement(
                request,
                (model_identifier,)
                if native_grant_backed
                else (
                    _model_key(request),
                    request.model_path,
                    _requested_model_id,
                    scan_folder_public_id,
                    model_identifier,
                ),
            )
        from utils.multi_model_settings import get_multi_model_mode

        multi_model_mode = await asyncio.to_thread(get_multi_model_mode)

        # Resolve once so dedupe, admission and launch use the same slot count.
        _n_parallel = _resolve_parallel_slots(request, fastapi_request)
        from core.inference.local_model_resolver import local_gguf_companion_state

        # Capture before metadata resolution; a download completing during launch must be noticed next time.
        gguf_companion_state = (
            await asyncio.to_thread(
                local_gguf_companion_state, tuple(request._gguf_companion_roots)
            )
            if request._gguf_companion_roots
            else ()
        )

        def _reuse_loaded_gguf(
            intent: GgufLoadIntent, *, display_name: Optional[str] = None
        ) -> Optional[LoadResponse]:
            if not (
                # Case-sensitive paths must not dedup onto the fast path; checked before adopting placement.
                _same_loaded_identifier(llama_backend.model_identifier, public_model_identifier)
                and tuple(getattr(llama_backend, "_openai_gguf_companion_roots", ()) or ())
                == tuple(request._gguf_companion_roots)
                and getattr(llama_backend, "_openai_gguf_companion_state", ())
                == gguf_companion_state
                and (
                    llama_backend.adopt_load_intent_if_matched(intent)
                    # Another account's capacity mismatch is its defaults, not a reconfig (#12365).
                    or (
                        replacing
                        and account_access.joins_resident_runtime(
                            "chat", llama_backend.model_identifier
                        )
                        and llama_backend.components_match_intent(intent)
                    )
                )
                and getattr(llama_backend, "_audio_probed", True)
            ):
                return None
            api_monitor.discard(_load_event)
            logger.info("Model already loaded (GGUF): %s, skipping reload", model_log_label)
            # A no-op Unsloth load of a preview-owned checkpoint still claims it.
            _set_preview_resident(None)
            if ollama_advertised_id:
                llama_backend._openai_advertised_id = ollama_advertised_id
            if replacing:
                account_access.join_resident("chat")
            return _gguf_load_response(
                llama_backend,
                "already_loaded",
                model_log_label
                if native_grant_backed
                else scan_folder_public_id or llama_backend.model_identifier,
                display_name = model_log_label if native_grant_backed else display_name,
                is_local_model = _loaded_is_local_model(
                    llama_backend, native_grant_backed, llama_backend.model_identifier
                ),
                inference_identifier = model_identifier,
            )

        is_direct_gguf_request = model_identifier.lower().endswith(".gguf")
        if llama_backend.is_loaded and (request.gguf_variant or is_direct_gguf_request):
            reused = _reuse_loaded_gguf(
                _active_gguf_intent(
                    request,
                    llama_backend,
                    model_identifier = public_model_identifier,
                    chat_template_override = effective_chat_template_override,
                    n_parallel = _n_parallel,
                    native_grant_backed = native_grant_backed,
                )
            )
            if reused is not None:
                # Reassert CHAT ownership unless the resident server is zero-VRAM.
                if not llama_backend.holds_no_vram:
                    await asyncio.to_thread(_reassert_chat_claim, multi_model_mode)
                return reused
        if not (request.gguf_variant or is_direct_gguf_request):
            _inherit_resident_load_in_4bit(backend, request, model_identifier)
            await asyncio.to_thread(reap_dead_worker, backend)
            if (
                not request.max_seq_length
                and _same_loaded_identifier(backend.active_model_name, model_identifier)
                and _mlx_slots_outgrow_price(backend, _n_parallel)
            ):
                # A reload for more rows keeps the context the resident was asked for.
                request.max_seq_length = (
                    int(
                        (backend.models.get(backend.active_model_name) or {}).get(
                            "max_seq_length_requested"
                        )
                        or 0
                    )
                    or request.max_seq_length
                )
            if (
                _same_loaded_identifier(backend.active_model_name, model_identifier)
                and (backend.models.get(backend.active_model_name) or {}).get("engine", "auto")
                == request.engine
                # A resident precision folder (6-bit/) is not the root checkpoint a variantless request names.
                and not (backend.models.get(backend.active_model_name) or {}).get(
                    "precision_folder"
                )
                and _mlx_runtime_settings_match(backend, request)
                and _non_gguf_runtime_settings_match(backend, request)
                and _resident_context_satisfies(
                    backend.models.get(backend.active_model_name) or {},
                    request.max_seq_length,
                )
                # Without this the route reports already_loaded and nothing moves.
                and _resident_audio_placement_matches(backend, request)
                and not _mlx_slots_outgrow_price(backend, _n_parallel)
            ):
                api_monitor.discard(_load_event)  # nothing loaded, no monitor row
                logger.info(f"Model already loaded (Unsloth): {model_log_label}, skipping reload")
                _note_mlx_slots(backend, backend.set_parallel_slots(_n_parallel))
                # A no-op Unsloth load of a preview-owned checkpoint still claims it.
                _set_preview_resident(None)
                inference_config = load_inference_config(backend.active_model_name)
                _model_info = backend.models.get(backend.active_model_name, {})
                _chat_template = None
                try:
                    _tpl_info = _model_info.get("chat_template_info", {})
                    _chat_template = _tpl_info.get("template")
                except Exception as e:
                    logger.warning(
                        f"Could not retrieve chat template for {backend.active_model_name}: {e}"
                    )
                # Classify via the same path as GGUF.
                _sf_flags, _ = _sf_rendered_features(backend, _model_info)
                _sf_supports_reasoning = _sf_flags["supports_reasoning"]
                _sf_reasoning_style = _sf_flags["reasoning_style"]
                # Reassert CHAT ownership; skip when it owns no GPU (would cancel a generation for nothing).
                if not _resident_audio_holds_no_gpu(backend):
                    await asyncio.to_thread(_reassert_chat_claim, multi_model_mode)
                if replacing:
                    account_access.join_resident("chat")
                if request._advertised_id:
                    backend._openai_advertised_id = request._advertised_id
                return LoadResponse(
                    engine = request.engine,
                    engine_parallelism = request.engine_parallelism,
                    engine_precision = request.engine_precision,
                    **_managed_engine_launch_fields(_model_info),
                    gpu_ids = _model_info.get("gpu_ids"),
                    requested_gpu_ids = _model_info.get("gpu_ids_requested"),
                    tensor_parallel = bool(_model_info.get("tensor_parallel", False)),
                    status = "already_loaded",
                    model = model_log_label if native_grant_backed else backend.active_model_name,
                    display_name = model_log_label
                    if native_grant_backed
                    else backend.active_model_name,
                    is_vision = _model_info.get("is_vision", False),
                    is_lora = _model_info.get("is_lora", False),
                    is_gguf = False,
                    is_local_model = native_grant_backed or is_local_path(backend.active_model_name),
                    is_audio = _model_info.get("is_audio", False),
                    audio_type = _model_info.get("audio_type"),
                    has_audio_input = _model_info.get("has_audio_input", False),
                    has_video_input = _model_info.get("has_video_input", False),
                    is_mlx = bool(_model_info.get("is_mlx", False)),
                    mlx_kv_quant = _model_info.get("mlx_kv_quant"),
                    mlx_kv_quant_requested = _model_info.get("mlx_kv_quant_requested"),
                    **_unsloth_serving_fields(_model_info),
                    mlx_kv_bits = _model_info.get("mlx_kv_bits"),
                    mlx_kv_bits_requested = _model_info.get("mlx_kv_bits_requested"),
                    mlx_kv_quant_eligibility = _model_info.get("mlx_kv_quant_eligibility"),
                    mlx_kv_quant_reason = _model_info.get("mlx_kv_quant_reason"),
                    mlx_kv_quant_note = _model_info.get("mlx_kv_quant_note"),
                    mlx_int8_prefill = _model_info.get("mlx_int8_prefill"),
                    mlx_int8_prefill_requested = _model_info.get("mlx_int8_prefill_requested"),
                    mlx_int8_prefill_reason = _model_info.get("mlx_int8_prefill_reason"),
                    mlx_offload = _model_info.get("mlx_offload"),
                    memory_warning = _mlx_offload_warning(_model_info),
                    # Requested, as /status reports it: a null override would read
                    # as "using the default".
                    chat_template_override = _model_info.get("chat_template_override_requested"),
                    chat_template_override_reason = _model_info.get("chat_template_override_reason"),
                    inference = inference_config,
                    requires_trust_remote_code = _resolve_loaded_trust_remote_code(
                        backend.active_model_name, _model_info, inference_config
                    ),
                    supports_reasoning = _sf_supports_reasoning,
                    reasoning_style = _sf_reasoning_style,
                    reasoning_effort_levels = _sf_flags.get("reasoning_effort_levels", []),
                    reasoning_always_on = _sf_flags["reasoning_always_on"],
                    supports_preserve_thinking = _sf_flags["supports_preserve_thinking"],
                    preserve_thinking_default = _sf_flags.get("preserve_thinking_default", False),
                    supports_tools = _sf_flags["supports_tools"],
                    context_length = _positive_int_or_none(_model_info.get("context_length")),
                    native_context_length = _positive_int_or_none(
                        _model_info.get("native_context_length")
                    ),
                    max_context_length = _positive_int_or_none(_model_info.get("max_context_length")),
                    mlx_context_budget = _model_info.get("mlx_context_budget"),
                    chat_template = _chat_template,
                )

        _caller_is_owner = _owner_session(fastapi_request) and _load_warnings_reach_user.get()

        # Offline guard skips soft-failed network checks before the worker starts; off-loop, as its DNS/HEAD can take seconds.

        def _resolve_config():
            with _hf_offline_if_unreachable_for(model_identifier):
                return ModelConfig.from_identifier(
                    model_id = model_identifier,
                    hf_token = request.hf_token,
                    gguf_variant = request.gguf_variant,
                    owner_session = _caller_is_owner,
                    # A native grant covers one directory; pass the boundary to the first drafter pass.
                    drafter_accept = _native_drafter_accept if native_grant_backed else None,
                    mmproj_accept = _native_mmproj_accept if native_grant_backed else None,
                    gguf_companion_roots = request._gguf_companion_roots or None,
                )

        # Guard and call go to the worker together (transformers import, network probe).
        config = await asyncio.to_thread(_resolve_config)

        if not config:
            raise HTTPException(
                status_code = 400,
                detail = f"Invalid model identifier: {model_log_label}",
            )
        await asyncio.to_thread(_require_resolved_base_access, config)

        # Resolve inherited extras once before command-dependent preflights.
        extra_llama_args = _resolve_inherited_extra_args(
            request,
            config,
            public_model_identifier,
            extra_llama_args,
            effective_chat_template_override,
        )

        # Invalid GPU IDs must fail before the training coexistence guard.
        placement = await _prepare_load_placement(config, request, extra_llama_args)
        # Ahead of the diffusion drop: an explicit reasoning flag is a refusal, not a no-op.
        await _validate_reasoning_budget_preflight(
            config, placement.diffusion_kind, extra_llama_args, request
        )
        if placement.diffusion_kind is True and extra_llama_args:
            # The visual runner appends none of these; drop them so the load isn't recorded with them.
            logger.info(
                "Dropping %d extra llama-server arg(s) for %s: the diffusion runner takes none.",
                len(extra_llama_args),
                model_log_label,
            )
            extra_llama_args = []
        if config.is_gguf and extra_llama_args:
            # After the slot count is known; a bad batch floor kills the server at startup, so 400 early.
            from core.inference.llama_server_args import check_batch_floor
            try:
                check_batch_floor(
                    extra_llama_args,
                    # Use the slot count that will launch (no --kv-unified means one slot).
                    _effective_parallel_slots(_n_parallel, diffusion_kind = placement.diffusion_kind),
                )
            except ValueError as exc:
                # --embedding caps batch at micro-batch; read lazily: it only turns a refusal into acceptance.
                if not await _batch_floor_survives_embedding_clamp(
                    config,
                    extra_llama_args,
                    _n_parallel,
                    request,
                    diffusion_kind = placement.diffusion_kind,
                ):
                    raise HTTPException(status_code = 400, detail = str(exc)) from exc
        gguf_intent: Optional[GgufLoadIntent] = None
        _tensor_intent_overall = False
        if request.engine != "auto":
            _reject_unsupported_managed_kind(request, config)
        if config.is_gguf:
            gguf_intent = _resolve_gguf_load_intent(
                config,
                request,
                native_grant_backed = native_grant_backed,
                chat_template_override = effective_chat_template_override,
                extra_args = extra_llama_args,
                placement = placement,
                n_parallel = _n_parallel,
            )
            if speech_codec_path is not None:
                gguf_intent = replace(gguf_intent, audio_codec_path = speech_codec_path)
            if not request.force_alongside and (
                not replacing or _primary_refuses_partial_fit(serving, multi_model_mode, placement)
            ):
                gguf_intent = replace(gguf_intent, refuse_partial_gpu_fit = True)
            same_loaded_model = llama_backend.matches_load_source(gguf_intent)
            _loaded_companion_roots = tuple(
                getattr(llama_backend, "_openai_gguf_companion_roots", ()) or ()
            )
            if same_loaded_model and config.gguf_hf_repo and llama_backend.gguf_path:
                gguf_intent = replace(
                    gguf_intent,
                    mtp_draft_path = _mtp_draft_for_path(
                        llama_backend.gguf_path, False, companion_roots = _loaded_companion_roots
                    ),
                    dspark_draft_path = _dspark_draft_for_path(
                        llama_backend.gguf_path, False, companion_roots = _loaded_companion_roots
                    ),
                    dflash_draft_path = _dflash_draft_for_path(
                        llama_backend.gguf_path, False, companion_roots = _loaded_companion_roots
                    ),
                    compare_mtp_draft = True,
                )
            _effective_tensor = _effective_tensor_parallel(
                extra_llama_args, request.tensor_parallel
            )
            _tensor_intent_overall = _effective_tensor or _carry_preserved_tensor_intent(
                preserved = getattr(llama_backend, "layer_preserves_tensor_intent", False),
                same_model = same_loaded_model,
                explicit_drop = _is_explicit_tensor_drop(request),
            )
            gguf_intent = replace(
                gguf_intent,
                preserve_multi_gpu_on_layer = (_tensor_intent_overall and not _effective_tensor),
            )
            reused = _reuse_loaded_gguf(
                gguf_intent,
                display_name = config.display_name,
            )
            if reused is not None:
                return reused

        if request.engine != "auto":
            engine_options = await _managed_engine_options(
                request, config, False if anonymous_hf_access else request.hf_token
            )

        # Dedupe first; refusal is non-destructive, forced cancellation deferred past every rejection.
        account_access.require_idle_other_accounts()
        if serving and on_reload_confirmed is not None:
            on_reload_confirmed(cancel = False)
        cancel_pending = (
            serving and on_reload_confirmed is not None and bool(request.force_cancel_active)
        )

        if not config.is_gguf and _mlx_distributed_launch_detected():
            raise HTTPException(
                status_code = 400,
                detail = (
                    "Unsloth does not support distributed MLX inference under "
                    "mlx.launch. Use `mlx.launch ... unsloth chat` or run Unsloth "
                    "without the distributed launcher."
                ),
            )

        # Effective quantization (LoRA can flip 4-bit -> 16-bit); guard + load reuse it.
        effective_load_in_4bit = _effective_load_in_4bit(config, request.load_in_4bit)
        if effective_load_in_4bit != request.load_in_4bit:
            logger.info(
                f"Resolved load_in_4bit={effective_load_in_4bit} for '{model_log_label}' "
                f"from adapter_config.json / base model (requested {request.load_in_4bit})"
            )
        # Latest-sidecar models load 16-bit (worker refuses bnb 4-bit); size the guard to match.
        if effective_load_in_4bit and not config.is_gguf:
            from utils.transformers_version import latest_tier_active_for
            if await asyncio.to_thread(
                _offline_guarded,
                (model_identifier, config.identifier, getattr(config, "base_model", None)),
                latest_tier_active_for,
                config.identifier,
                request.hf_token,
            ):
                effective_load_in_4bit = False
                logger.info(
                    f"Latest-transformers sidecar active for '{model_log_label}' - "
                    "sizing and loading in 16-bit (4-bit is disabled for brand-new "
                    "architectures)"
                )

        placement = await _preflight_native_audio_placement(config, request, placement)

        async def _guard_training(guard_placement: _LoadPlacement):
            return await asyncio.to_thread(
                _offline_guarded,
                (model_identifier, config.identifier, getattr(config, "base_model", None)),
                _guard_chat_load_against_training,
                config,
                request,
                load_in_4bit = effective_load_in_4bit,
                placement = guard_placement,
                llama_extra_args = extra_llama_args,
                n_parallel = _n_parallel,
            )

        # Apply the training coexistence policy before the unload below frees the resident model.
        initial_training_info = await _guard_training(placement)

        # Refuse a repo the download manager owns BEFORE eviction; after inheritance (--no-mmproj matters).
        interlock_repo = config.is_gguf and (
            config.gguf_hf_repo or getattr(config, "gguf_cache_repo", None)
        )
        if interlock_repo:
            from core.inference.llama_cpp import gguf_load_in_flight

            gguf_load_stack.enter_context(gguf_load_in_flight(interlock_repo))

            from core.inference.llama_cpp import _hub_download_blocks_gguf_load

            if await asyncio.to_thread(
                _hub_download_blocks_gguf_load,
                interlock_repo,
                config.gguf_variant,
                # Same predicate as the loader's download gate; vision-off must not relax it, or it bypasses the 409 and downloads into the shared cache beside a running job.
                require_mmproj = bool(
                    config.is_vision and not extra_args_disable_mmproj(extra_llama_args)
                ),
                hf_token = request.hf_token,
            ):
                raise HTTPException(
                    status_code = 409,
                    detail = (
                        f"'{model_log_label}' is currently being downloaded "
                        "by the download manager. Wait for the download to "
                        "finish (or cancel it), then load the model."
                    ),
                )

        # Marker entered UNDER the arbiter lock: a chat load holds no process until its GGUF lands.
        from core.inference.llama_cpp import chat_load_in_flight, zero_vram_chat_load

        # Only take the arbiter when the load uses the GPU (gpu_layers=0 runs on CPU).
        chat_load_needs_gpu = not (
            # The non-GGUF case of the same thing: no VRAM, so no arbiter.
            _native_audio_cpu_load(config, request)
            or config.is_gguf
            and await asyncio.to_thread(
                zero_vram_chat_load,
                request.gpu_memory_mode,
                request.gpu_layers,
                extra_llama_args,
                # Vision off: no projector, no arbiter, unless audio-only is kept; remote claims GPU (safe).
                bool(
                    config.is_vision
                    and not extra_args_disable_mmproj(extra_llama_args)
                    and _load_keeps_a_projector(
                        config,
                        disable_vision = bool(getattr(request, "disable_vision", False)),
                    )
                ),
                request.speculative_type,
            )
        )
        # Ahead of the arbiter, which evicts pipelines and cancels generations. Fails open.
        if config.is_gguf:
            _not_audio = await asyncio.to_thread(_audio_intent_gguf_refusal, config, request)
            if _not_audio:
                logger.error("Refusing a non-audio GGUF loaded for audio: %s", _not_audio)
                raise HTTPException(status_code = 400, detail = _not_audio)
        if config.is_gguf and gguf_intent is not None:
            _non_chat = await asyncio.to_thread(
                llama_backend.non_chat_gguf_refusal_for_intent, gguf_intent
            )
            if _non_chat:
                logger.error("Refusing non-chat GGUF before the GPU handoff: %s", _non_chat)
                raise HTTPException(status_code = 400, detail = _non_chat)
            # Advisory only, never a gate: an oversized GGUF pages from disk. Asked here too because load_model's copy runs too deep to reach the response.
            _host_offload_warning = await asyncio.to_thread(
                llama_backend.host_offload_warning_for_intent, gguf_intent
            )
            if _host_offload_warning:
                logger.warning("Loading an oversized GGUF: %s", _host_offload_warning)

        expected_native_owner = None
        mlx_chat_need = None
        post_media_handoff_gpu = None
        post_media_handoff_needed_gb = None
        post_chat_handoff_expected_free_gb = None
        if chat_load_needs_gpu and placement.native_post_handoff_free_gb is not None:
            # Refresh right before handoff and bind the epoch so a smaller same-owner swap can't sneak in.
            final_availability = await asyncio.to_thread(_native_audio_post_handoff_free_gb)
            selected = list(placement.resolved_gpu_ids or ())
            required = placement.native_required_gb
            if final_availability is None or len(selected) != 1 or required is None:
                raise HTTPException(
                    status_code = 409,
                    detail = "GPU residency changed while preparing this audio model. Retry the load.",
                )
            selected_gpu = selected[0]
            effective_free = final_availability.effective_free_gb.get(selected_gpu)
            if effective_free is None or effective_free < required:
                raise HTTPException(
                    status_code = 409,
                    detail = "GPU residency changed and the audio model no longer fits. Retry the load.",
                )
            final_placement = placement._replace(
                native_post_handoff_free_gb = {selected_gpu: effective_free}
            )
            final_training_info = await _guard_training(final_placement)
            expected_native_owner = final_availability.owner_snapshot
            post_handoff_needed_gb = float(
                (final_training_info or initial_training_info or {}).get("needed_gb") or required
            )
            if final_availability.credited in (DIFFUSION, VIDEO):
                post_media_handoff_gpu = selected_gpu
                post_media_handoff_needed_gb = post_handoff_needed_gb
            elif final_availability.credited == CHAT:
                post_chat_handoff_expected_free_gb = {selected_gpu: post_handoff_needed_gb}

        if chat_load_needs_gpu:
            try:
                handoff_kwargs = {}
                if expected_native_owner is not None:
                    handoff_kwargs["expected_current"] = expected_native_owner
                if not allow_gpu_owner_eviction:
                    handoff_kwargs["allow_evict"] = False
                if not replacing:
                    handoff_kwargs["alongside"] = True
                handoff_kwargs.update(policy_kwargs(multi_model_mode))
                outgoing_chat_gb, chat_wait_gb = await asyncio.to_thread(
                    _outgoing_chat_credit_gb,
                    placement,
                    multi_model_mode,
                    replacing,
                    final_availability if expected_native_owner is not None else None,
                )
                if post_chat_handoff_expected_free_gb is None:
                    post_chat_handoff_expected_free_gb = chat_wait_gb
                mlx_chat_need = await asyncio.to_thread(
                    _mlx_chat_need, request, config, model_identifier, _n_parallel
                )
                mlx_credit_mib = 0
                if mlx_chat_need is not None:
                    from core.inference.gpu_residency import mlx_replaced_credit_mib

                    # No llama-server credit: its footprint mixes CPU-only buffers with Metal ones.
                    mlx_credit_mib = await asyncio.to_thread(mlx_replaced_credit_mib, backend)
                handoff_kwargs.update(
                    _chat_fit_kwargs(
                        config,
                        placement,
                        multi_model_mode,
                        outgoing_chat_gb,
                        mlx_need_mib = None if mlx_chat_need is None else mlx_chat_need[0],
                        mlx_credit_mib = mlx_credit_mib,
                    )
                )
                await asyncio.to_thread(
                    acquire_for_request,
                    CHAT,
                    lambda: gguf_load_stack.enter_context(chat_load_in_flight()),
                    **handoff_kwargs,
                )
            except Exception as exc:
                from core.inference.gpu_arbiter import OwnerChangedError
                if isinstance(exc, OwnerChangedError):
                    raise HTTPException(status_code = 409, detail = str(exc)) from exc
                raise
            if post_media_handoff_gpu is not None and post_media_handoff_needed_gb is not None:
                # Wait for the freed VRAM only when the media model was actually evicted.
                settled = holds(expected_native_owner[0]) or await asyncio.to_thread(
                    _wait_for_native_audio_gpu_free_gb,
                    post_media_handoff_gpu,
                    post_media_handoff_needed_gb,
                )
                if not settled:
                    raise HTTPException(
                        status_code = 409,
                        detail = (
                            "GPU memory was not released after the resident media model "
                            "was stopped. Retry the audio-model load."
                        ),
                    )
                # Re-run the training policy against live free VRAM only: the
                # media allocation is gone, or was kept beside and never freed,
                # and a concurrent training change cannot hide behind the
                # earlier reclaimable snapshot.
                live_placement = placement._replace(
                    # Bind to the chosen card, or a roomy second GPU could approve it.
                    requested_gpu_ids = [post_media_handoff_gpu],
                    native_post_handoff_free_gb = None,
                )
                await _guard_training(live_placement)
        else:
            # The marker still goes up (the download-manager handshake reads it, and it keeps this load cancellable). A stale CHAT claim is dropped AFTER the load.
            gguf_load_stack.enter_context(chat_load_in_flight())

        # capture the prior marker before either load path reaches its point of no return.
        _prior_preview_marker = _get_preview_resident()

        def _restore_marker_if_prior_preview_still_resident() -> None:
            # A failed load can leave the prior preview checkpoint resident; restore its marker if so.
            if _prior_preview_marker is not None and _loaded_slot_ident() == _prior_preview_marker:
                _set_preview_resident(_prior_preview_marker)

        # ── GGUF path: load via llama-server ──────────────────────
        if config.is_gguf:
            llama_backend = get_llama_cpp_backend()
            unsloth_backend = await asyncio.to_thread(get_inference_backend)

            # Fast path only: a swap can still be reserved during the drain.
            _raise_if_sidecar_swap_in_progress()

            # Drain generations first; a forced swap excludes the ones it will cancel.
            if replacing and serving:
                await _wait_for_model_switch_idle(
                    current_request_counted = current_request_counted,
                    cancel_pending = cancel_pending,
                )
            # Last rejection point, so it runs BEFORE the cancel.
            _raise_if_sidecar_swap_in_progress()

            # Point of no return for the GGUF path: nothing after this can reject, so cancel the chats the swap interrupts (or refuse if not opted in).
            _raise_if_scoped_load_cancelled()
            if serving and on_reload_confirmed is not None:
                on_reload_confirmed(cancel = True)

            # Bounded: TTS observes no cancel event.
            if cancel_pending:
                await _wait_for_model_switch_idle(
                    current_request_counted = current_request_counted,
                    timeout_s = _POST_CANCEL_DRAIN_TIMEOUT_S,
                )

            # every rejection and drain has completed. the load now owns the slot for studio.
            _set_preview_resident(None)

            # Unload any active Unsloth model only after every hub conflict check.
            if unsloth_backend.active_model_name:
                logger.info(
                    f"Unloading Unsloth model '{unsloth_backend.active_model_name}' before loading GGUF"
                )
                try:
                    await asyncio.to_thread(
                        unsloth_backend.unload_model, unsloth_backend.active_model_name
                    )
                except Exception:
                    # On teardown failure, restore the prior preview owner so later previews are not 503'd.
                    _restore_marker_if_prior_preview_still_resident()
                    raise
            await _unload_npu_before_local_load()

            # After all checks, the intent resolved before teardown is the only launch input.
            if gguf_intent is None:
                raise RuntimeError("GGUF load intent was not resolved")
            load_intent = gguf_intent
            codec_failures: list[str] = []

            # Run a single load attempt with the given tensor flag + extras.
            async def _attempt_gguf_load(
                tensor_parallel: bool, attempt_extra_args: Optional[list[str]]
            ) -> bool:
                attempt = replace(
                    load_intent,
                    extra_args = (
                        tuple(attempt_extra_args) if attempt_extra_args is not None else None
                    ),
                    tensor_parallel = tensor_parallel,
                    preserve_multi_gpu_on_layer = bool(
                        _tensor_intent_overall
                        and not _effective_tensor_parallel(attempt_extra_args, tensor_parallel)
                    ),
                )
                return await _run_gguf_load_attempt(
                    llama_backend,
                    attempt,
                    load_cancel_event,
                    codec_failures,
                )

            # Tensor parallelism crashes some loads (Gemma 3n GGML_ASSERT); helper falls back to layer split, and the response reports the actual TP state.
            try:
                success = await load_with_tensor_fallback(
                    _attempt_gguf_load,
                    requested_tensor = request.tensor_parallel,
                    extra_args = extra_llama_args,
                    label = config.identifier,
                    cancelled = lambda: _gguf_load_cancelled(llama_backend, load_cancel_event),
                )
            except Exception:
                # A GGUF load can raise before killing the old server; restore the preview marker.
                _restore_marker_if_prior_preview_still_resident()
                raise

            if not success:
                _restore_marker_if_prior_preview_still_resident()
                # A cancelled load is not a failed one; don't build a 500.
                if _gguf_load_cancelled(llama_backend, load_cancel_event):
                    raise HTTPException(status_code = 409, detail = "Model load cancelled")
                raise HTTPException(
                    status_code = 500,
                    detail = codec_failures[-1]
                    if codec_failures
                    else f"Failed to load GGUF model: {model_log_label if native_grant_backed else config.display_name}",
                )

            # An Images/Video acquire can slip between acquire and cancel-event clear; undo this load.
            if llama_backend.holds_no_vram:
                chat_load_needs_gpu = False
            if chat_load_needs_gpu and not holds(CHAT):
                await asyncio.to_thread(llama_backend.unload_model)
                raise HTTPException(
                    status_code = 409,
                    detail = (
                        "An image or video model took the GPU while this model was loading, "
                        "so the load was cancelled. Unload that model, then try again."
                    ),
                )
            if replacing and not chat_load_needs_gpu:
                # Drop the stale CHAT claim after any zero-VRAM load.
                await asyncio.to_thread(_release_chat_for_zero_vram_primary)

            logger.info(
                f"Loaded GGUF model via llama-server: {model_log_label if native_grant_backed else config.identifier}"
            )
            _close_load_event(
                _load_event,
                model_log_label if native_grant_backed else public_model_identifier,
                request.gguf_variant or getattr(llama_backend, "hf_variant", None),
            )
            # Clear any idle-unload reload stash now, not only on the next poll.
            from core.inference.llama_keepwarm import note_model_loaded

            llama_backend._openai_gguf_companion_roots = tuple(request._gguf_companion_roots)
            llama_backend._openai_gguf_companion_state = gguf_companion_state
            if replacing:
                await asyncio.to_thread(note_model_loaded, llama_backend)
            # Else None, or the catalog id a /models/load named: only those loads have an alias to keep.
            llama_backend._openai_advertised_id = ollama_advertised_id

            # Audio detection moved into load_model under _serial_load_lock (#5642).
            _gguf_audio = llama_backend._audio_type
            _gguf_is_audio = llama_backend._is_audio
            llama_backend._native_display_label = model_log_label if native_grant_backed else None
            llama_backend._native_grant_backed = bool(native_grant_backed)
            # Provenance is load-time; re-deriving per poll flips if the dir disappears.
            llama_backend._is_local_model = bool(native_grant_backed or config.is_local)
            if _gguf_is_audio:
                logger.info(f"GGUF model detected as audio: audio_type={_gguf_audio}")
            if replacing:
                account_access.publish_resident(
                    "chat",
                    request.model_path,
                    model_log_label if native_grant_backed else public_model_identifier,
                )

            return _gguf_load_response(
                llama_backend,
                "loaded",
                model_log_label
                if native_grant_backed
                else scan_folder_public_id or public_model_identifier,
                display_name = model_log_label if native_grant_backed else config.display_name,
                is_local_model = config.is_local,
                inference_identifier = config.identifier,
            )

        # ── Standard path: load via Unsloth/transformers ──────────
        backend = await asyncio.to_thread(get_inference_backend)

        # Same sidecar rejection as GGUF: fast path ahead of the drain, rechecked after.
        _raise_if_sidecar_swap_in_progress()

        llama_backend = get_llama_cpp_backend()
        if replacing and serving:
            await _wait_for_model_switch_idle(
                current_request_counted = current_request_counted,
                cancel_pending = cancel_pending,
            )
        _raise_if_sidecar_swap_in_progress()

        # Point of no return for the Unsloth path: cancel only once nothing can still reject the load.
        _raise_if_scoped_load_cancelled()
        retire_kept = (
            request.engine != "auto" and replacing and bool(model_slots.slots or model_slots.stuck)
        )
        if retire_kept:
            _gate_kept_models(request, cancel = False)
        if serving and on_reload_confirmed is not None:
            on_reload_confirmed(cancel = True)
        if retire_kept:
            await _retire_kept_models(request)

        # Let the cancelled generations unwind before the teardown; no check follows. Bounded like GGUF.
        if cancel_pending:
            await _wait_for_model_switch_idle(
                current_request_counted = current_request_counted,
                timeout_s = _POST_CANCEL_DRAIN_TIMEOUT_S,
            )
        # every rejection and drain has completed. the load now owns the slot for studio.
        _set_preview_resident(None)
        # Off-loop: a 600 GB teardown takes ~160s.
        try:
            await _unload_llama_before_standard_load(llama_backend)
        except Exception:
            # On teardown failure, restore the prior preview GGUF's ownership so later previews are not 503'd.
            _restore_marker_if_prior_preview_still_resident()
            raise
        await _unload_npu_before_local_load()

        # Free the export's VRAM only when this load wants VRAM: a CPU load masks the accelerators.
        try:
            from core.export import get_export_backend
            exp_backend = get_export_backend()
            if chat_load_needs_gpu and exp_backend.current_checkpoint:
                logger.info("Shutting down export subprocess to free GPU memory for inference")
                exp_backend._shutdown_subprocess()
                exp_backend.current_checkpoint = None
                exp_backend.is_vision = False
                exp_backend.is_peft = False
        except Exception as e:
            logger.warning("Could not shut down export subprocess: %s", e)

        # Resolved before the guard so both size the same load.
        load_in_4bit = effective_load_in_4bit

        # Clear the alias before the load, or a request matching the old alias hits the new weights.
        _prior_alias = getattr(backend, "_openai_advertised_id", None)
        _prior_active = getattr(backend, "active_model_name", None)
        backend._openai_advertised_id = None
        # Released mid-load by load_model: after would cancel this load, before would allow a double alloc.
        _release_chat_after_teardown = (
            _release_chat_for_zero_vram_primary if replacing and not chat_load_needs_gpu else None
        )
        anonymous_hf_kw = {"anonymous_hf_access": True} if anonymous_hf_access else {}
        speech_codec_kw = (
            {"audio_codec_path": speech_codec_path} if speech_codec_path is not None else {}
        )
        # The inference worker is not bound to the account, so refuse here.
        if request.trust_remote_code and managed_remote_code_refused():
            raise HTTPException(status_code = 403, detail = MANAGED_REMOTE_CODE_REFUSAL)
        try:
            success = await asyncio.to_thread(
                backend.load_model,
                **(
                    {"engine": request.engine, "engine_options": engine_options}
                    if request.engine != "auto"
                    else {}
                ),
                config = config,
                max_seq_length = request.max_seq_length,
                load_in_4bit = load_in_4bit,
                hf_token = request.hf_token,
                trust_remote_code = request.trust_remote_code,
                approved_remote_code_fingerprint = request.approved_remote_code_fingerprint,
                gpu_ids = (
                    placement.resolved_gpu_ids
                    if placement.resolved_gpu_ids is not None
                    else placement.requested_gpu_ids
                ),
                subject = current_subject,
                mlx_kv_quant = request.mlx_kv_quant,
                mlx_int8_prefill = request.mlx_int8_prefill,
                mlx_offload = (request.mlx_ple_offload, request.mlx_expert_offload),
                speculative_type = request.speculative_type,
                spec_draft_n_max = request.spec_draft_n_max,
                spec_draft_model = request.spec_draft_model,
                spec_drafters_allowed = await asyncio.to_thread(
                    _discoverable_drafters, request.model_path
                ),
                chat_template_override = request.chat_template_override,
                load_cancel_event = load_cancel_event,
                on_prior_worker_released = _release_chat_after_teardown,
                post_handoff_expected_free_gb = post_chat_handoff_expected_free_gb,
                audio_device = request.audio_device,
                n_parallel = _n_parallel,
                cache_environment = cache_environment,
                **anonymous_hf_kw,
                **speech_codec_kw,
            )
        except Exception:
            _restore_marker_if_prior_preview_still_resident()
            _restore_alias_if_failed_load_left_the_prior_model(backend, _prior_alias, _prior_active)
            if request.engine != "auto":
                # Cancelled managed startup raises; report the scoped-cancel 409.
                _raise_if_scoped_load_cancelled()
            raise

        if not success:
            _restore_marker_if_prior_preview_still_resident()
            _restore_alias_if_failed_load_left_the_prior_model(backend, _prior_alias, _prior_active)
            # Check if YAML says this model needs trust_remote_code.
            if not request.trust_remote_code:
                model_defaults = load_model_defaults(config.identifier)
                yaml_trust = model_defaults.get("inference", {}).get("trust_remote_code", False)
                if yaml_trust:
                    raise HTTPException(
                        status_code = 400,
                        detail = (
                            f"Model '{config.display_name}' requires trust_remote_code to be enabled. "
                            f"Please enable 'Trust remote code' in Chat Settings and try again."
                        ),
                    )
            raise HTTPException(
                status_code = 500,
                detail = f"Failed to load model: {model_log_label if native_grant_backed else config.display_name}",
            )

        # Same guard the GGUF branch runs above: an Images/Video acquire can land between this load's cancellation and its publish, so this load undoes itself.
        # On a clean server the owner is None, so ungated this unloads what it loaded.
        if chat_load_needs_gpu and not holds(CHAT):
            await asyncio.to_thread(backend.unload_model, config.identifier)
            # The worker's base CUDA context outlives the model unload, so kill it too.
            await asyncio.to_thread(backend._shutdown_subprocess, 5.0)
            raise HTTPException(
                status_code = 409,
                detail = (
                    "An image or video model took the GPU while this model was loading, "
                    "so the load was cancelled. Unload that model, then try again."
                ),
            )
        if replacing and not chat_load_needs_gpu:
            # Otherwise the next Images/Video acquire evicts a model that never used the GPU.
            await asyncio.to_thread(_release_chat_for_zero_vram_primary)

        # Stamped here: backend.load_model runs in the subprocess, its entry never crosses back.
        _resident_entry = backend.models.get(backend.active_model_name)
        if isinstance(_resident_entry, dict):
            _resident_entry["max_seq_length_requested"] = int(request.max_seq_length or 0)
            _resident_entry["load_in_4bit_requested"] = bool(request.load_in_4bit)
            # Persist placement so a reload doesn't land on a different GPU.
            _resident_entry["gpu_ids_requested"] = (
                list(request.gpu_ids) if request.gpu_ids else None
            )
            if mlx_chat_need is not None and _mlx_cache_bounded(
                _resident_entry, mlx_chat_need[1]["slots"]
            ):
                from core.inference.gpu_residency import mlx_worker_footprint_mib
                _resident_entry["mlx_growth"] = {
                    **mlx_chat_need[1],
                    "footprint_mib": mlx_worker_footprint_mib(backend),
                }
            elif mlx_chat_need is not None:
                # Admitted at a price the loaded cache does not keep to: settle as an unpriced load would have.
                from core.inference.gpu_arbiter import (
                    GpuBusyForAnotherAccountError,
                    MultiModelAlwaysRefusal,
                )
                from core.inference.gpu_residency import settle_unpriced_chat_beside_media
                try:
                    await asyncio.to_thread(settle_unpriced_chat_beside_media, multi_model_mode)
                except (MultiModelAlwaysRefusal, GpuBusyForAnotherAccountError) as exc:
                    await asyncio.to_thread(backend.unload_model, config.identifier)
                    await asyncio.to_thread(backend._shutdown_subprocess, 5.0)
                    if isinstance(exc, GpuBusyForAnotherAccountError):
                        raise exc.as_http_exception() from exc
                    raise

        if request._advertised_id:
            backend._openai_advertised_id = request._advertised_id
        logger.info(
            f"Loaded model: {model_log_label if native_grant_backed else config.identifier}"
        )
        _close_load_event(
            _load_event, model_log_label if native_grant_backed else config.identifier, None
        )
        # Consume the reload stash: an MLX swap's chat context is restored, anything else dropped.
        from core.inference.llama_keepwarm import note_model_loaded

        if replacing:
            await asyncio.to_thread(note_model_loaded, backend)
            account_access.publish_resident(
                "chat",
                request.model_path,
                model_log_label if native_grant_backed else config.identifier,
            )

        # Load inference configuration parameters
        inference_config = load_inference_config(config.identifier)

        # Get chat template from tokenizer
        _chat_template = None
        try:
            _model_info = backend.models.get(config.identifier, {})
            _tpl_info = _model_info.get("chat_template_info", {})
            _chat_template = _tpl_info.get("template")
        except Exception:
            pass

        # Classify reasoning/tool flags via the GGUF sniffer.
        _sf_flags, _ = _sf_rendered_features(backend, _model_info)

        # Persist trust_remote_code so a retry/rollback doesn't send false for a custom-code model.
        _requires_rc = _resolve_loaded_trust_remote_code(
            config.identifier,
            None,
            inference_config,
            request.hf_token,
            trust_remote_code_used = bool(getattr(request, "trust_remote_code", False)),
        )
        try:
            backend.models.setdefault(config.identifier, {})["requires_trust_remote_code"] = (
                _requires_rc
            )
        except Exception:
            pass

        if replacing and chat_load_needs_gpu:
            # A GPU start that fell back to the CPU holds no VRAM, so the claim it took would evict media for nothing.
            await asyncio.to_thread(release_chat_after_cpu_fallback, backend, config.identifier)

        return LoadResponse(
            engine = request.engine,
            engine_parallelism = request.engine_parallelism,
            engine_precision = request.engine_precision,
            **_managed_engine_launch_fields(_model_info),
            gpu_ids = _model_info.get("gpu_ids"),
            requested_gpu_ids = _model_info.get("gpu_ids_requested"),
            tensor_parallel = bool(_model_info.get("tensor_parallel", False)),
            status = "loaded",
            model = model_log_label if native_grant_backed else config.identifier,
            display_name = model_log_label if native_grant_backed else config.display_name,
            is_vision = config.is_vision,
            is_lora = config.is_lora,
            is_gguf = False,
            is_local_model = config.is_local,
            # Post-load classification (mirrored from the worker) wins here.
            is_audio = _model_info.get("is_audio", config.is_audio),
            audio_type = _model_info.get("audio_type", config.audio_type),
            has_audio_input = _model_info.get("has_audio_input", config.has_audio_input),
            has_video_input = _model_info.get("has_video_input", False),
            audio_family = _model_info.get("audio_family"),
            audio_options = _model_info.get("audio_options"),
            audio_workflows = _model_info.get("audio_workflows"),
            audio_reference_text = _model_info.get("audio_reference_text"),
            audio_options_by_workflow = _model_info.get("audio_options_by_workflow"),
            audio_workflow_tasks = _model_info.get("audio_workflow_tasks"),
            audio_server_task = _model_info.get("audio_server_task"),
            audio_convert = _model_info.get("audio_convert"),
            audio_convert_route = _model_info.get("audio_convert_route"),
            audio_required_inputs = _model_info.get("audio_required_inputs"),
            audio_request_inputs = _model_info.get("audio_request_inputs"),
            audio_device_fallback = _model_info.get("audio_device_fallback"),
            audio_music = _model_info.get("audio_music"),
            is_mlx = bool(_model_info.get("is_mlx", False)),
            mlx_kv_quant = _model_info.get("mlx_kv_quant"),
            mlx_kv_quant_requested = _model_info.get("mlx_kv_quant_requested"),
            **_unsloth_serving_fields(_model_info),
            mlx_kv_bits = _model_info.get("mlx_kv_bits"),
            mlx_kv_bits_requested = _model_info.get("mlx_kv_bits_requested"),
            mlx_kv_quant_eligibility = _model_info.get("mlx_kv_quant_eligibility"),
            mlx_kv_quant_reason = _model_info.get("mlx_kv_quant_reason"),
            mlx_kv_quant_note = _model_info.get("mlx_kv_quant_note"),
            mlx_int8_prefill = _model_info.get("mlx_int8_prefill"),
            mlx_int8_prefill_requested = _model_info.get("mlx_int8_prefill_requested"),
            mlx_int8_prefill_reason = _model_info.get("mlx_int8_prefill_reason"),
            mlx_offload = _model_info.get("mlx_offload"),
            memory_warning = _mlx_offload_warning(_model_info),
            # Requested, as /status reports it: a null override would read as
            # "using the default".
            chat_template_override = _model_info.get("chat_template_override_requested"),
            chat_template_override_reason = _model_info.get("chat_template_override_reason"),
            inference = inference_config,
            requires_trust_remote_code = _requires_rc,
            supports_reasoning = _sf_flags["supports_reasoning"],
            reasoning_style = _sf_flags["reasoning_style"],
            reasoning_effort_levels = _sf_flags.get("reasoning_effort_levels", []),
            reasoning_always_on = _sf_flags["reasoning_always_on"],
            supports_preserve_thinking = _sf_flags["supports_preserve_thinking"],
            preserve_thinking_default = _sf_flags.get("preserve_thinking_default", False),
            supports_tools = _sf_flags["supports_tools"],
            context_length = _positive_int_or_none(_model_info.get("context_length")),
            native_context_length = _positive_int_or_none(_model_info.get("native_context_length")),
            max_context_length = _positive_int_or_none(_model_info.get("max_context_length")),
            mlx_context_budget = _model_info.get("mlx_context_budget"),
            chat_template = _chat_template,
        )

    except HTTPException:
        raise
    except ValueError as e:
        redacted_msg = redact_native_paths(str(e))
        _unsupported_quantization = _unsupported_quantization_detail(
            redacted_msg, getattr(request, "engine", None)
        )
        if _unsupported_quantization is not None:
            logger.warning(
                "Unsupported quantization while loading '%s': %s",
                model_log_label,
                _unsupported_quantization,
            )
            raise HTTPException(
                status_code = 500,
                detail = _unsupported_quantization,
            )
        if native_grant_backed:
            logger.warning(
                "Rejected inference selection for native model %s: %s",
                model_log_label,
                redacted_msg,
            )
            raise HTTPException(status_code = 400, detail = redacted_msg)
        logger.warning("Rejected inference GPU selection: %s", e)
        # User-facing validation (e.g. "Invalid gpu_ids [99]"): redact paths, keep detail.
        raise HTTPException(status_code = 400, detail = redacted_msg)
    except GpuMemoryShortError:
        raise  # load_model_gated makes room and retries
    except MultiModelAlwaysRefusal:
        raise  # the route answers 409 with the refusal header
    except LlamaServerNotFoundError as e:
        # Missing GGUF runtime: 400 with the install message, not a generic 500.
        logger.warning("GGUF runtime missing while loading '%s': %s", model_log_label, e)
        raise HTTPException(status_code = 400, detail = str(e))
    except Exception as e:
        from core.inference.audio_cpp_failures import failure_of
        from core.inference.gpu_arbiter import DECISIONS, GpuOwnerBusyError
        from utils.transformers_version import SidecarSwapInProgress

        if (failure := failure_of(e)) is not None:
            logger.warning(
                "Load of '%s' failed (%s): %s",
                model_log_label,
                failure.code,
                redact_native_paths(str(e)),
            )
            raise HTTPException(status_code = failure.status, detail = failure.detail()) from e
        if isinstance(e, account_access.GpuBusyForAnotherAccountError):
            raise account_access.gpu_busy_error() from e
        if isinstance(e, GpuOwnerBusyError) and e.owner == DECISIONS:
            # A llama.cpp decision server loading or deciding refuses eviction until it is idle.
            raise HTTPException(
                status_code = 409,
                detail = "The Decision API is using the GPU; retry shortly.",
                headers = {"Retry-After": "5"},
            ) from e
        if isinstance(e, GpuOwnerBusyError):
            raise
        if isinstance(e, SidecarSwapInProgress):
            # Lost the spawn-time race to a sidecar install/repair: retryable 409.
            raise HTTPException(status_code = 409, detail = str(e))
        if token_rejections.refused and (is_hf_authentication_error(e) or is_token_rejection(e)):
            logger.warning("Load of '%s' failed: Hugging Face rejected the token", model_log_label)
            raise HTTPException(status_code = 400, detail = HUB_TOKEN_REJECTED_ERROR)
        # Friendlier message for models Unsloth cannot load.
        redacted_msg = redact_native_paths(str(e))
        _unsupported_quantization = _unsupported_quantization_detail(
            redacted_msg, getattr(request, "engine", None)
        )
        if _unsupported_quantization is not None:
            logger.warning(
                "Unsupported quantization while loading '%s': %s",
                model_log_label,
                _unsupported_quantization,
            )
            raise HTTPException(
                status_code = 500,
                detail = _unsupported_quantization,
            )
        if native_grant_backed:
            logger.error(
                "Error loading native model %s: %s",
                model_log_label,
                redacted_msg,
            )
            msg = _maybe_unsupported_message(redacted_msg)
            raise HTTPException(
                status_code = 500,
                detail = f"Failed to load native model {model_log_label}: {msg}",
            )
        logger.error(f"Error loading model: {e}", exc_info = True)
        msg = _maybe_unsupported_message(redacted_msg)
        raise HTTPException(status_code = 500, detail = f"Failed to load model: {msg}")
    finally:
        gguf_load_stack.close()
        # Runs for a load that failed part way too: the bytes it pulled are cached anyway.
        if _load_fetched_bytes(
            request.model_path, _cached_before_this_load, _cache_footprint_before
        ):
            _note_load_fetched_with_a_request_token(request.model_path, request.hf_token)
        # The LoRA base, unknown until the adapter's config is on disk.
        _note_lora_base_fetched_with_a_request_token(
            request.model_path, request.hf_token, already_cached = _lora_base_before_this_load
        )
        # Catch-all: an error or cancelled load would otherwise leave the row "loading".
        api_monitor.fail_open(_load_event, "Load did not complete")


def _any_remote(targets) -> bool:
    """True unless every target is a local path. Falsy entries are skipped (no base to
    read); anything unresolvable counts as remote, since guarding a local read costs one
    memoised verdict while missing a remote one costs the retry backoff."""
    from utils.paths import is_local_path

    for target in (targets,) if isinstance(targets, str) else targets or ():
        if not target:
            continue  # no base is not an unknown base: nothing to read, nothing to guard
        try:
            if not (isinstance(target, str) and is_local_path(target)):
                return True
        except Exception:
            return True  # unresolvable: guard, since missing a remote read costs the backoff
    return False


def _offline_guarded(targets, fn, /, *args, **kwargs):
    """Runs a preflight in the forced-offline window, from a worker thread (it can block); targets = what is read, as an adapter may resolve to a remote base."""
    from contextlib import nullcontext

    # Module-level symbol: route tests patch routes.inference._hf_offline_if_unreachable.
    ctx = _hf_offline_if_unreachable() if _any_remote(targets) else nullcontext()
    with ctx:
        return fn(*args, **kwargs)


def _requires_trust_remote_code_for_model(
    model_identifier: str, hf_token: Optional[str] = None
) -> bool:
    """True if the YAML default or any raw config auto_map runs remote code; reads JSON, never imports. Must run before the consent dialog."""
    from utils.inference import load_inference_config

    try:
        if bool(load_inference_config(model_identifier).get("trust_remote_code", False)):
            return True
    except Exception:
        pass
    try:
        from utils.security.consent import _config_has_auto_map
        from utils.security import load_scan_target, security_load_subdirs

        load_subdirs = security_load_subdirs(model_identifier, hf_token)
        target, load_subdirs = load_scan_target(model_identifier, load_subdirs)
        return (
            _config_has_auto_map(
                target,
                hf_token,
                load_subdirs = load_subdirs,
            )
            is True
        )
    except Exception:
        return False


def _stored_trust_remote_code(
    model_info,
    inference_config,
    trust_remote_code_used = False,
) -> Optional[bool]:
    """Network-free part of the resolution order; None = only ``auto_map`` can answer."""
    stored = (model_info or {}).get("requires_trust_remote_code")
    if stored is not None:
        return bool(stored)
    if trust_remote_code_used or bool((inference_config or {}).get("trust_remote_code", False)):
        return True
    return None


def _auto_map_trust_remote_code(model_id, hf_token = None) -> bool:
    """Raw ``auto_map`` check; can reach the Hub, so keep it off the event loop."""
    try:
        return bool(_requires_trust_remote_code_for_model(model_id, hf_token))
    except Exception:
        return False


def _resolve_loaded_trust_remote_code(
    model_id,
    model_info,
    inference_config,
    hf_token = None,
    trust_remote_code_used = False,
) -> bool:
    """Resolves a loaded model's TRC: stored value, value used, YAML default, then raw auto_map."""
    known = _stored_trust_remote_code(model_info, inference_config, trust_remote_code_used)
    if known is not None:
        return known
    return _auto_map_trust_remote_code(model_id, hf_token)


def _requires_security_review_for_model(
    model_identifier: str, hf_token: Optional[str] = None
) -> bool:
    """Whether Hugging Face's security scan flagged unsafe files for this repo, so
    the consent dialog must open as a hard block before loading. Metadata-only;
    never downloads the flagged files. Fails open (False) on any error."""
    try:
        from utils.security import (
            evaluate_file_security,
            load_scan_target,
            security_load_subdirs,
        )

        # Normalize the `<name>/LLM` alias so subdirs resolve against the same repo.
        load_subdirs = security_load_subdirs(model_identifier, hf_token)
        target, load_subdirs = load_scan_target(model_identifier, load_subdirs)
        return evaluate_file_security(
            target,
            hf_token,
            load_subdirs = load_subdirs,
        ).blocked
    except Exception:
        return False


def _mlx_base_for_config(config) -> Optional[str]:
    from core.inference.model_ids import mlx_host_bnb_base_repo
    for candidate in (getattr(config, "identifier", None), getattr(config, "base_model", None)):
        base = mlx_host_bnb_base_repo(candidate)
        if base:
            return base
    return None


@router.post("/validate", response_model = ValidateModelResponse)
async def validate_model(
    request: ValidateModelRequest,
    fastapi_request: Request = None,
    current_subject: str = Depends(get_current_subject),
):
    """
    Lightweight validation endpoint for model identifiers.

    Checks that ModelConfig.from_identifier() can resolve model_path, but does
    NOT load model weights into GPU memory.
    """
    # Return the incoming string, not the resolved path.
    from hub.utils.host_paths import restore_inventory_handles

    if account_access.managed_account():
        request = request.model_copy(
            update = {"hf_token": account_access.account_hf_token(request.hf_token)}
        )
    if request.engine != "auto":
        request = await _managed_engine_request(request)
    native_access_deferred = _defers_access_to_native_grant(request)
    if account_access.managed_account() and not native_access_deferred:
        await asyncio.to_thread(account_access.require_model_access, request.model_path)
    request = await asyncio.to_thread(_as_ollama_manifest_request, request)
    # The chat flow validates before /load; offline the remote probe would refuse the id.
    request = await asyncio.to_thread(
        _as_local_scan_folder_request, request, _owner_session(fastapi_request)
    )
    from core.inference.llama_cpp import (
        LlamaServerNotFoundError,
        _hf_offline_if_unreachable_for,
    )

    native_grant_backed = False
    model_log_label = request.model_path

    ollama_load_stack = ExitStack()
    token_rejections = ollama_load_stack.enter_context(collecting_hub_token_rejections())
    try:
        resolved_ollama_path = await _lease_ollama_model_ref(
            request,
            operation = "validate-model",
            stack = ollama_load_stack,
        )
        model_identifier, model_log_label, native_grant_backed = (
            _resolve_model_identifier_for_request(
                request,
                operation = "validate-model",
                resolved_ollama_path = resolved_ollama_path,
            )
        )
        if native_access_deferred:
            await asyncio.to_thread(account_access.require_model_access, model_identifier)

        # Same roots /load will use, or a sibling-revision projector is missed.
        _validate_companion_roots = await asyncio.to_thread(
            _path_load_companion_roots, model_identifier, native_grant_backed
        )

        # The frontend validates before loading, so this needs /load's offline guard; off-loop.
        _caller_is_owner = _owner_session(fastapi_request)

        def _resolve_config():
            with _hf_offline_if_unreachable_for(model_identifier):
                return ModelConfig.from_identifier(
                    model_id = model_identifier,
                    hf_token = request.hf_token,
                    gguf_variant = request.gguf_variant,
                    owner_session = _caller_is_owner,
                    # A native grant covers one directory; pass the boundary to the first drafter pass.
                    drafter_accept = _native_drafter_accept if native_grant_backed else None,
                    mmproj_accept = _native_mmproj_accept if native_grant_backed else None,
                    gguf_companion_roots = _validate_companion_roots or None,
                )

        config = await asyncio.to_thread(_resolve_config)

        if not config:
            raise HTTPException(
                status_code = 400,
                detail = f"Invalid model identifier: {model_log_label}",
            )
        if request.engine != "auto":
            # The picker unloads the resident once this passes, so /load's engine checks run here too.
            _reject_unsupported_managed_kind(request, config)
            await _managed_engine_options(request, config, request.hf_token)

        # Pass the caller's list, or a --ctx-size the load uses is missing from the estimate.
        effective_extra_args = _resolve_inherited_extra_args(
            request,
            config,
            _public_model_identifier(request.model_path, model_identifier),
            getattr(request, "llama_extra_args", None),
        )

        # Validate the caller's list BEFORE translation, as /load does.
        if config.is_gguf and effective_extra_args:
            from core.inference.llama_server_args import validate_extra_args
            try:
                validate_extra_args(effective_extra_args)
            except ValueError as exc:
                raise HTTPException(status_code = 400, detail = str(exc)) from exc
            if getattr(request, "llama_extra_args", None) is not None:
                _refuse_managed_custom_projector(
                    effective_extra_args,
                    _public_model_identifier(request.model_path, model_identifier),
                    config.identifier,
                    getattr(request, "gguf_variant", None) or getattr(config, "gguf_variant", None),
                )

        # Translate -ngl/-ts and strip as /load does, so the guard judges the same command; run after the validation above, so no refused token gets parsed.
        if getattr(request, "gpu_memory_mode", None) == "manual" and effective_extra_args:
            from core.inference.llama_server_args import (
                parse_gpu_layers_override,
                parse_tensor_split_override,
                strip_shadowing_flags,
            )

            _validate_manual_updates: dict[str, Any] = {}
            _validate_ngl_override = parse_gpu_layers_override(effective_extra_args)
            if _validate_ngl_override is not None:
                _validate_manual_updates["gpu_layers"] = _validate_ngl_override
            # Same reserialized judgement, and the same 400, as the load path above.
            _validate_resolved_layers = (
                _validate_ngl_override
                if _validate_ngl_override is not None
                else getattr(request, "gpu_layers", -1)
            )
            try:
                _validate_ts_override = parse_tensor_split_override(
                    effective_extra_args, reserialized = _validate_resolved_layers >= 0
                )
            except ValueError as exc:
                raise HTTPException(status_code = 400, detail = str(exc)) from exc
            if _validate_ts_override is not None:
                _validate_manual_updates["tensor_split"] = _validate_ts_override
            if _validate_manual_updates:
                request = request.model_copy(update = _validate_manual_updates)
            effective_extra_args = strip_shadowing_flags(
                effective_extra_args,
                strip_context = False,
                strip_cache = False,
                strip_spec = False,
                strip_template = False,
                strip_split_mode = False,
                strip_tensor_split = _should_strip_tensor_split(request),
                strip_offload = True,
            )

        # Same placement policy as /load, before the frontend unloads the current model.
        placement = await _prepare_load_placement(config, request, effective_extra_args)
        # Before the diffusion drop, or an explicit flag is ignored rather than refused.
        await _validate_reasoning_budget_preflight(
            config, placement.diffusion_kind, effective_extra_args, request
        )
        if placement.diffusion_kind is True and effective_extra_args:
            # Same drop as /load: the diffusion runner appends none of these; decide only after placement, or a ctx-size estimate approves a load it never gets.
            logger.info(
                "Ignoring %d extra llama-server arg(s) for %s: the diffusion runner takes none.",
                len(effective_extra_args),
                model_log_label,
            )
            effective_extra_args = []
        if config.is_gguf and effective_extra_args:
            # Same checks as /load: the picker unloads on a successful validate. Only the floor here.
            from core.inference.llama_server_args import check_batch_floor
            _requested_slots = _resolve_parallel_slots(request, fastapi_request)
            try:
                check_batch_floor(
                    effective_extra_args,
                    _effective_parallel_slots(
                        _requested_slots,
                        diffusion_kind = placement.diffusion_kind,
                    ),
                )
            except ValueError as exc:
                # The same embedding clamp /load allows for.
                if not await _batch_floor_survives_embedding_clamp(
                    config,
                    effective_extra_args,
                    _requested_slots,
                    request,
                    diffusion_kind = placement.diffusion_kind,
                ):
                    raise HTTPException(status_code = 400, detail = str(exc)) from exc
        effective_load_in_4bit = _effective_load_in_4bit(config, request.load_in_4bit)
        placement = await _preflight_native_audio_placement(config, request, placement)

        # Cover [adapter, base]: either repo can ship auto_map code or a poisoned pickle.
        from core.inference.native_audio import native_audio_security_targets

        security_targets = native_audio_security_targets(
            config.identifier, getattr(config, "audio_type", None), request.hf_token
        )
        try:
            from utils.models.model_config import get_base_model_from_lora_identifier

            # Resolve a LOCAL or REMOTE adapter's base so its code/weights are reviewed too.
            _base = await asyncio.to_thread(
                _offline_guarded,
                model_identifier,
                get_base_model_from_lora_identifier,
                model_identifier,
                request.hf_token,
            )
            if _base:
                security_targets.append(_base)
        except Exception:
            pass
        security_targets = list(dict.fromkeys(security_targets))

        is_gguf = getattr(config, "is_gguf", False)
        # Never fails validation; runs before the training guard so an upgrade sizes as 16-bit.
        transformers_upgrade: Optional[TransformersUpgradeInfo] = None
        if not is_gguf:
            from utils.transformers_latest import check_upgrade_for_model

            # Cover [adapter, base]: the worker activates transformers for the base model.
            for _target in security_targets:
                _upgrade = await asyncio.to_thread(
                    _offline_guarded,
                    _target,
                    check_upgrade_for_model,
                    _target,
                    request.hf_token,
                )
                if _upgrade is not None:
                    transformers_upgrade = TransformersUpgradeInfo(**_upgrade)
                    break

        # Computed before the 16-bit flip: a remote-code fallback still loads 4-bit.
        requires_trust_remote_code = False
        if not is_gguf:
            # Reads raw config/tokenizer JSON, so guarded and off-loop like the rest.
            requires_trust_remote_code = await asyncio.to_thread(
                _offline_guarded,
                security_targets,
                lambda: any(
                    _requires_trust_remote_code_for_model(_t, request.hf_token)
                    for _t in security_targets
                ),
            )

        # Mirror /load's latest-sidecar 16-bit flip: an active sidecar forces 16-bit; an offered upgrade
        # only without a custom-code (auto_map) fallback, which still loads 4-bit.
        if effective_load_in_4bit and not is_gguf:
            from utils.transformers_version import latest_tier_active_for
            _install_only_upgrade = (
                transformers_upgrade is not None
                and transformers_upgrade.installable
                and not requires_trust_remote_code
            )
            if _install_only_upgrade or await asyncio.to_thread(
                _offline_guarded,
                (model_identifier, config.identifier, getattr(config, "base_model", None)),
                latest_tier_active_for,
                config.identifier,
                request.hf_token,
            ):
                effective_load_in_4bit = False
        # A metadata-only probe allocates no VRAM, so skip the training guard; /load guards again.
        if not (request.include_context_length or request.include_chat_template):
            # Off-loop and guarded: the guard does sync nvidia-smi / HF work.
            await asyncio.to_thread(
                _offline_guarded,
                (model_identifier, config.identifier, getattr(config, "base_model", None)),
                _guard_chat_load_against_training,
                config,
                request,
                load_in_4bit = effective_load_in_4bit,
                placement = placement,
                llama_extra_args = effective_extra_args,
                n_parallel = _resolve_parallel_slots(request, fastapi_request),
            )

        # GGUF loads ignore auto_map/pickles, so the security preflight is non-GGUF only.
        requires_security_review = False
        if not is_gguf:
            # Network timeouts (10s, 20s): needs the same offline window and worker thread as the preflights above.
            requires_security_review = await asyncio.to_thread(
                _offline_guarded,
                security_targets,
                lambda: any(
                    _requires_security_review_for_model(_t, request.hf_token)
                    for _t in security_targets
                ),
            )
        # Staged header dims let the context, GPU-layers and --n-cpu-moe sliders size before load.
        context_length: Optional[int] = None
        layer_count: Optional[int] = None
        moe_layer_count: Optional[int] = None
        chat_template: Optional[str] = None
        # Both header probes read the same local GGUF, so resolve it once.
        if (request.include_context_length or request.include_chat_template) and is_gguf:
            from hub.utils.gguf import resolve_local_gguf_path
            from picker.schemas import MAX_CHAT_TEMPLATE_BYTES
            from utils.models.gguf_metadata import (
                read_gguf_chat_template,
                read_gguf_staged_dims,
            )

            # Best-effort: a header-read failure must never fail validation.
            try:
                if native_grant_backed:
                    # model_identifier is the resolved canonical .gguf path.
                    local_gguf = model_identifier
                else:
                    # gguf_file is None for HF repos, which fall back to the HF-cache lookup.
                    local_gguf = config.gguf_file or resolve_local_gguf_path(
                        model_identifier, request.gguf_variant
                    )
                if local_gguf:
                    if request.include_context_length:
                        # Header walk reads tokenizer arrays (tens of ms); keep it off the event loop.
                        dims = await asyncio.to_thread(read_gguf_staged_dims, local_gguf)
                        if dims:
                            context_length = dims["context_length"]
                            layer_count = dims["layer_count"]
                            moe_layer_count = dims["moe_layer_count"]
                    if request.include_chat_template:
                        # Only the leased GGUF's embedded template: the grant covers this path, not siblings.
                        raw_template = await asyncio.to_thread(read_gguf_chat_template, local_gguf)
                        if (
                            raw_template is not None
                            and len(raw_template.encode("utf-8")) <= MAX_CHAT_TEMPLATE_BYTES
                        ):
                            chat_template = raw_template
            except Exception as e:
                logger.debug("Header probe failed for %s: %s", model_log_label, e)

        managed_engine_offer = None
        if request.engine == "auto" and not is_gguf:
            managed_engine_offer = await asyncio.to_thread(
                _offline_guarded,
                (model_identifier, config.identifier, getattr(config, "base_model", None)),
                _managed_engine_offer_for,
                config,
                request.hf_token,
            )

        return restore_inventory_handles(
            ValidateModelResponse(
                valid = True,
                message = " ".join(
                    ["Model identifier is valid."] + _hub_access_warnings(token_rejections)
                ),
                identifier = model_log_label if native_grant_backed else config.identifier,
                resident = await asyncio.to_thread(
                    _validated_target_is_resident,
                    request,
                    model_identifier = model_identifier,
                    config = config,
                    is_gguf = is_gguf,
                    native_grant_backed = native_grant_backed,
                ),
                display_name = model_log_label
                if native_grant_backed
                else getattr(config, "display_name", config.identifier),
                is_gguf = is_gguf,
                is_diffusion = is_gguf and placement.diffusion_kind is True,
                # An unavailable header is inconclusive, not proof of an ordinary GGUF.
                diffusion_unknown = is_gguf and placement.diffusion_kind is None,
                is_lora = getattr(config, "is_lora", False),
                is_vision = getattr(config, "is_vision", False),
                requires_trust_remote_code = requires_trust_remote_code,
                requires_security_review = requires_security_review,
                context_length = context_length,
                layer_count = layer_count,
                moe_layer_count = moe_layer_count,
                chat_template = chat_template,
                requires_transformers_upgrade = transformers_upgrade is not None,
                transformers_upgrade = transformers_upgrade,
                mlx_loads_base_model = await asyncio.to_thread(_mlx_base_for_config, config),
                managed_engine_offer = managed_engine_offer,
            )
        )

    except HTTPException as http_error:
        # The `model_log_label` in the detail is the RESOLVED path.
        raise _handle_restored_http_exception(http_error) from http_error
    except LlamaServerNotFoundError as e:
        # Missing GGUF runtime: 400 with the install message, not a generic "Invalid model".
        logger.warning("GGUF runtime missing while validating '%s': %s", request.model_path, e)
        raise HTTPException(status_code = 400, detail = restore_inventory_handles(str(e)))
    except Exception as e:
        # Restored here rather than at each raise below: every branch quotes this string.
        redacted_msg = restore_inventory_handles(redact_native_paths(str(e)))
        if token_rejections.refused and (is_hf_authentication_error(e) or is_token_rejection(e)):
            raise HTTPException(status_code = 400, detail = HUB_TOKEN_REJECTED_ERROR)
        if is_hf_authentication_error(e):
            raise HTTPException(
                status_code = 400,
                detail = (
                    "Hugging Face authentication failed. Check or clear the token "
                    "in Settings, and confirm access to this gated repository."
                ),
            )
        if _raised_repository_not_found(e):
            # The Hub answers alike for a missing repo and a private one, so the message names both.
            raise HTTPException(
                status_code = 400,
                detail = (
                    f"'{model_log_label}' was not found on Hugging Face, or it is private. "
                    "Check the name, or add a token with access to it in Settings."
                ),
            )
        _unsupported_quantization = _unsupported_quantization_detail(
            redacted_msg, getattr(request, "engine", None)
        )
        if _unsupported_quantization is not None:
            logger.warning(
                "Unsupported quantization while validating '%s': %s",
                model_log_label,
                _unsupported_quantization,
            )
            raise HTTPException(
                status_code = 400,
                detail = _unsupported_quantization,
            )
        if native_grant_backed:
            logger.error(
                "Error validating native model %s: %s",
                model_log_label,
                redacted_msg,
            )
            msg = _maybe_unsupported_message(redacted_msg)
            raise HTTPException(
                status_code = 400,
                detail = f"Invalid native model {model_log_label}: {msg}",
            )
        logger.error(
            f"Error validating model identifier '{request.model_path}': {e}",
            exc_info = True,
        )
        # Surface actionable RuntimeError/ValueError messages (path-redacted); keep others generic.
        if isinstance(e, (RuntimeError, ValueError)):
            msg = redacted_msg.strip()
            if msg:
                msg = _maybe_unsupported_message(msg)
                raise HTTPException(
                    status_code = 400,
                    detail = msg,
                )
        raise HTTPException(
            status_code = 400,
            detail = "Invalid model",
        )

    finally:
        ollama_load_stack.close()


def _raised_repository_not_found(error: BaseException) -> bool:
    seen: set[int] = set()
    current: Optional[BaseException] = error
    while current is not None and id(current) not in seen:
        seen.add(id(current))
        if type(current).__name__ == "RepositoryNotFoundError":
            return True
        if isinstance(current, (ValueError, RuntimeError)):
            return False
        current = current.__cause__ or (
            None if current.__suppress_context__ else current.__context__
        )
    return False


def _upgrade_check_config_target(request: TransformersUpgradeCheckRequest) -> str:
    """The config.json to read, as the remote-code scan does (a pinned snapshot wins); falls back to the identifier and never raises."""
    from utils.paths import is_local_path, normalize_path

    model_name = request.model_name
    try:
        if is_local_path(model_name):
            normalized = normalize_path(model_name)
            try:
                return str(Path(normalized).expanduser().resolve(strict = False))
            except (OSError, RuntimeError, ValueError):
                return normalized
        snapshot_path = (request.model_snapshot_path or "").strip()
        if snapshot_path:
            from routes.models import _model_config_inspection_target
            return _model_config_inspection_target(
                (request.model_snapshot_repo_id or "").strip() or model_name,
                True,
                normalize_path(snapshot_path),
            )
        local_path = (request.model_local_path or "").strip()
        if request.prefer_local_cache:
            # A null cachePath is a valid cached selection; _resolve_model_snapshot searches all roots.
            from core.training.training import _resolve_model_snapshot
            return (
                _resolve_model_snapshot(
                    model_name, normalize_path(local_path) if local_path else None
                )
                or model_name
            )
    except Exception as exc:
        logger.debug("Cache pin resolution failed for '%s': %s", model_name, exc)
    return model_name


def _install_breaks_exact_resume(run_id: str) -> bool:
    """True if the offered install would strand a 4-bit run's exact resume; False for an unknown run."""
    from core.training.provenance import exact_resume_requires_current_4bit
    from core.training.resume import training_run_config
    from storage.studio_db import get_run

    try:
        run = get_run(run_id)
        if run is None:
            return False
        return exact_resume_requires_current_4bit(training_run_config(run))
    except Exception as exc:
        logger.debug("Exact-resume check failed for run '%s': %s", run_id, exc)
        return False


# studio_router only: an Unsloth preflight, kept off the OpenAI-compatible /v1 mount.
@studio_router.post("/transformers-upgrade-check", response_model = TransformersUpgradeCheckResponse)
async def check_transformers_upgrade_route(
    request: TransformersUpgradeCheckRequest, current_subject: str = Depends(get_current_subject)
):
    """
    Does loading this model need a newer transformers than any installed overlay?

    /validate answers this for a chat load, but only as one field of a check that also
    resolves a ModelConfig, picks a GPU placement and runs the coexistence guard, none of
    which apply to a training start and several of which refuse while a run is active. So
    training asks on its own here, before spawning a worker that would otherwise die at
    model load with an unrecognized-architecture error the user cannot act on.

    Answers the same way /validate does: check_upgrade_for_model across [adapter, base],
    inside the same forced-offline window, on a worker thread. Also reports whether the
    run would load 16-bit instead of bnb 4-bit, which is what the latest sidecar means
    for training. Never raises: an unreadable model reports "no upgrade needed" and the
    caller proceeds exactly as it did before.
    """
    from utils.transformers_version import latest_tier_active_for

    if account_access.managed_account():
        for ref in (
            request.model_name,
            request.model_local_path,
            request.model_snapshot_path,
            request.model_snapshot_repo_id,
        ):
            if isinstance(ref, str) and ref:
                await asyncio.to_thread(account_access.require_model_access, ref)
        # None reads as ambient-authorized downstream and keeps the hub-cache fallback open.
        request = request.model_copy(
            update = {"hf_token": account_access.account_hf_token(request.hf_token)}
        )
    model_name = request.model_name
    # Inspect what the load will open, not what the identifier resolves to today.
    load_target = await asyncio.to_thread(_upgrade_check_config_target, request)
    targets = [load_target]
    try:
        from utils.models.model_config import get_base_model_from_lora_identifier

        # Worker activates transformers for the BASE model; resolve it from the load target, not the identifier, since a repo may have repointed its base.
        base = await asyncio.to_thread(
            _offline_guarded,
            load_target,
            get_base_model_from_lora_identifier,
            load_target,
            request.hf_token,
        )
        if base:
            targets.append(base)
    except Exception:
        pass
    targets = list(dict.fromkeys(targets))

    transformers_upgrade: Optional[TransformersUpgradeInfo] = None
    try:
        from utils.transformers_latest import check_upgrade_for_model
        for target in targets:
            upgrade = await asyncio.to_thread(
                _offline_guarded,
                target,
                check_upgrade_for_model,
                target,
                request.hf_token,
            )
            if upgrade is not None:
                transformers_upgrade = TransformersUpgradeInfo(**upgrade)
                break
    except Exception as exc:
        logger.debug("Transformers upgrade check failed for '%s': %s", model_name, exc)

    requires_trust_remote_code = False
    try:
        requires_trust_remote_code = await asyncio.to_thread(
            _offline_guarded,
            targets,
            lambda: any(
                _requires_trust_remote_code_for_model(target, request.hf_token)
                for target in targets
            ),
        )
    except Exception as exc:
        logger.debug("Custom-code check failed for '%s': %s", model_name, exc)

    latest_tier_active = False
    try:
        latest_tier_active = await asyncio.to_thread(
            _offline_guarded,
            # latest_tier_active_for resolves a remote adapter's base itself, so fetch it too.
            tuple(targets),
            latest_tier_active_for,
            load_target,
            request.hf_token,
        )
    except Exception as exc:
        logger.debug("Latest-tier check failed for '%s': %s", model_name, exc)

    # Only install-only upgrades or active sidecars force 16-bit; offered ones do not (bnb 4-bit feeds unvalidated paths for new architectures).
    install_only_upgrade = bool(
        transformers_upgrade is not None
        and transformers_upgrade.installable
        and not requires_trust_remote_code
    )
    # Already on the sidecar: the install does not strand the checkpoint; resume is refused regardless.
    install_breaks_exact_resume = False
    if request.resume_run_id and not latest_tier_active:
        install_breaks_exact_resume = await asyncio.to_thread(
            _install_breaks_exact_resume, request.resume_run_id
        )
    from hub.utils.host_paths import restore_inventory_handles

    return TransformersUpgradeCheckResponse(
        model_name = restore_inventory_handles(model_name),
        requires_transformers_upgrade = transformers_upgrade is not None,
        transformers_upgrade = transformers_upgrade,
        # Already booleans; bool() here would trip the GGUF consistency guard's raw-YAML check.
        requires_trust_remote_code = requires_trust_remote_code,
        latest_tier_active = latest_tier_active,
        forces_16bit = latest_tier_active or install_only_upgrade,
        install_breaks_exact_resume = install_breaks_exact_resume,
    )


@studio_router.post(
    "/install-latest-transformers",
    response_model = InstallLatestTransformersResponse,
    dependencies = [Depends(get_current_subject), Depends(auth_policy.require_owner)],
)
async def install_latest_transformers_route(
    request: InstallLatestTransformersRequest, current_subject: str = Depends(get_current_subject)
):
    """
    Consented install of the latest transformers release into the persistent
    .venv_t5_latest sidecar.

    Called after the user confirms the transformers-upgrade dialog raised by /validate
    (requires_transformers_upgrade). The requested version must match the current latest
    PyPI release, or transformers main when only main ships the architecture (both
    re-verified server-side); the sidecar then participates in routing on
    this and every future start. A pip install runs off-loop, so this can take a minute.
    """
    from utils.transformers_latest import install_latest_transformers
    from utils.transformers_version import end_sidecar_swap, try_begin_sidecar_swap

    # Reserve the swap FIRST, before any await: training/export starts check this reservation,
    # and a live worker would lazy-import from the swapped .venv_t5_latest.
    if not try_begin_sidecar_swap():
        raise HTTPException(
            status_code = 409,
            detail = "A transformers installation is already in progress.",
        )
    # Owns the reservation until the installer thread takes over; release on early exit.
    owns_reservation = True
    try:
        from core.export import get_export_backend
        from core.training import get_training_backend

        if get_training_backend().is_training_active():
            raise HTTPException(
                status_code = 409,
                detail = (
                    "A training run is active. Wait for it to finish before "
                    "installing a new transformers version."
                ),
            )
        _export = get_export_backend()
        if _export.is_export_active():
            raise HTTPException(
                status_code = 409,
                detail = (
                    "An export is running. Wait for it to finish before "
                    "installing a new transformers version."
                ),
            )
        # Swap cleanup would tear down a loaded export checkpoint with no rollback; require unload.
        if getattr(_export, "current_checkpoint", None):
            raise HTTPException(
                status_code = 409,
                detail = (
                    "An export checkpoint is loaded. Unload it from the Export "
                    "page before installing a new transformers version."
                ),
            )
        # In-flight streams already passed the middleware; the swap's unload would kill them.
        from core.inference.llama_keepwarm import (
            inference_lifecycle_gate,
            model_load_gate,
            note_model_unloaded,
            other_inference_request_count,
        )

        # A confirmed swap skips only this fast path; the gate recheck still applies to everyone.
        if (
            not request.force_cancel_active
            and other_inference_request_count(current_request_counted = False, include_pending = False)
            > 0
        ):
            raise HTTPException(
                status_code = 409,
                detail = (
                    "Another inference request is in progress. Wait for it to "
                    "finish before installing a new transformers version."
                ),
            )

        # Hold the /load lifecycle gate during the swap; teardown runs only after the staged install
        # succeeds. GGUF stays loaded (llama-server never imports transformers).
        backend = await asyncio.to_thread(get_inference_backend)
        export_backend = get_export_backend()

        unloaded_chat = {"v": False}

        def _unload_before_swap() -> None:
            # Export teardown FIRST so its failure aborts while chat is loaded; judge by worker liveness.
            export_backend.cleanup_memory()
            export_alive = getattr(export_backend, "is_worker_alive", None)
            if callable(export_alive) and export_alive():
                raise RuntimeError("Export worker still alive before the transformers swap")
            active = getattr(backend, "active_model_name", None)
            if active:
                if not backend.unload_model(active):
                    # A failed unload still clears orchestrator state, so report it for client rollback.
                    if getattr(backend, "active_model_name", None) != active:
                        unloaded_chat["v"] = True
                        note_model_unloaded()
                    raise RuntimeError(f"Could not unload '{active}' before the transformers swap")
                note_model_unloaded()
                unloaded_chat["v"] = True
                logger.info(
                    "Unloaded '%s' before swapping in transformers %s",
                    active,
                    request.version,
                )
            # A failed load can leave a live worker holding sidecar modules (blocks rename on Windows).
            worker_alive = getattr(backend, "is_worker_alive", None)
            if callable(worker_alive) and worker_alive():
                # _shutdown_subprocess keeps the handle if the worker survives SIGKILL; check both results.
                stopped = backend._shutdown_subprocess()
                if not stopped or worker_alive():
                    raise RuntimeError("Inference worker still alive before the transformers swap")
            model_slots.stop_orchestrator_workers()

        def _run_install() -> dict:
            # Release in the thread, not the route, so cancellation keeps the reservation held.
            try:
                return install_latest_transformers(request.version, _unload_before_swap, True)
            finally:
                end_sidecar_swap()

        # Snapshot before the gate wait: a /load may finish meanwhile; generation catches reloads.
        active_before_gate = (
            getattr(backend, "active_model_name", None),
            getattr(backend, "load_generation", 0),
        )

        async def _gated_install() -> dict:
            # Held by THIS task: a cancelled POST unwinding `async with` would drop /load's guard.
            async with model_load_gate(), inference_lifecycle_gate():
                _active_now = (
                    getattr(backend, "active_model_name", None),
                    getattr(backend, "load_generation", 0),
                )
                if _active_now != active_before_gate:
                    end_sidecar_swap()
                    raise HTTPException(
                        status_code = 409,
                        detail = (
                            "A model load completed while the install was waiting. "
                            "Retry the install."
                        ),
                    )
                # Deliberately LAST: cancel only once nothing can still reject the install (/load's rule).
                if request.force_cancel_active:
                    await _cancel_and_drain_for_sidecar_swap()
                # Recheck under the gate: new streams bump their count while holding it.
                if (
                    other_inference_request_count(
                        current_request_counted = False, include_pending = False
                    )
                    > 0
                ):
                    end_sidecar_swap()
                    raise HTTPException(
                        status_code = 409,
                        detail = (
                            "Another inference request is in progress. Wait for "
                            "it to finish before installing a new transformers "
                            "version."
                        ),
                    )
                return await asyncio.to_thread(_run_install)

        install_task = asyncio.ensure_future(_gated_install())
        owns_reservation = False
        # shield: the installer runs to completion even if the request is cancelled.
        result = await asyncio.shield(install_task)
    finally:
        if owns_reservation:
            end_sidecar_swap()
    if not result["success"]:
        if result.get("latest_version") or result.get("latest_main_version"):
            # Structured failure so the dialog can update to the newer release
            # and offer a retry that can actually succeed.
            return InstallLatestTransformersResponse(**result, model_unloaded = unloaded_chat["v"])
        if unloaded_chat["v"]:
            # Chat model already gone; structured failure lets the client restore its state.
            return InstallLatestTransformersResponse(**result, model_unloaded = True)
        raise HTTPException(status_code = 400, detail = result["message"])
    return InstallLatestTransformersResponse(**result, model_unloaded = unloaded_chat["v"])


# Short TTL: cached config goes stale when a download finishes mid-panel.
_ESTIMATE_CONFIG_TTL_SECONDS = 30.0
_ESTIMATE_CONFIG_CACHE_MAX = 8
_estimate_config_cache: "dict[tuple, tuple[float, Any]]" = {}


def _cached_estimate_config(
    model_identifier: str,
    gguf_variant: Optional[str],
    hf_token: Optional[str],
    native_grant_backed: bool,
):
    """Briefly caches ModelConfig.from_identifier; failures are not cached, as a download may be pending."""
    key = (
        model_identifier,
        gguf_variant,
        native_grant_backed,
        # Same reason as the file cache: a gated repo resolves per token.
        _estimate_token_fingerprint(hf_token),
    )
    now = time.monotonic()
    hit = _estimate_config_cache.get(key)
    if hit is not None and now - hit[0] < _ESTIMATE_CONFIG_TTL_SECONDS:
        return hit[1]
    if not _estimate_target_is_on_this_disk(model_identifier):
        # Must run before from_identifier, which hits the Hub and writes cache for remote ids.
        # Not cached: an absent repo usually means a download is in flight.
        return _ESTIMATE_NOT_ON_DISK
    from core.inference.llama_cpp import _hf_offline_if_unreachable_for

    # Same roots /load will use: a sibling-revision head or projector is weight it maps.
    _estimate_companion_roots = _path_load_companion_roots(model_identifier, native_grant_backed)

    def _resolve():
        return ModelConfig.from_identifier(
            model_id = model_identifier,
            hf_token = hf_token,
            gguf_variant = gguf_variant,
            drafter_accept = _native_drafter_accept if native_grant_backed else None,
            mmproj_accept = _native_mmproj_accept if native_grant_backed else None,
            gguf_companion_roots = _estimate_companion_roots or None,
        )

    # Offline FIRST: repo is on disk, so avoid Hub round trips per tick; the reachable retry stays as fallback, since a slow right answer beats a blank row.
    config = None
    try:
        from utils.utils import force_hf_offline
        with force_hf_offline():
            config = _resolve()
    except Exception as exc:
        logger.debug(
            "Offline resolve of %s did not answer, retrying online: %s", model_identifier, exc
        )
    # Skip the network retry when the fail-open gate could not answer: route promises no downloads.
    if config is None and _estimate_disk_residency(model_identifier) != _ESTIMATE_DISK_UNKNOWN:
        try:
            with _hf_offline_if_unreachable_for(model_identifier):
                config = _resolve()
        except Exception as exc:
            logger.debug("Memory estimate could not resolve %s: %s", model_identifier, exc)
            return None
    if config is None:
        return None
    # Same lock, same reason as the files cache: see the note at its eviction.
    with _ESTIMATE_CACHE_LOCK:
        if len(_estimate_config_cache) >= _ESTIMATE_CONFIG_CACHE_MAX:
            # Oldest first; the panel works one model at a time, so this is housekeeping.
            oldest = min(_estimate_config_cache, key = lambda k: _estimate_config_cache[k][0])
            _estimate_config_cache.pop(oldest, None)
        # Stamp after the slow part, or slow repos are inserted already expired.
        _estimate_config_cache[key] = (time.monotonic(), config)
    return config


@router.post("/int8-prefill-availability", response_model = Int8PrefillAvailabilityResponse)
async def int8_prefill_availability(
    request: Int8PrefillAvailabilityRequest, current_subject: str = Depends(get_current_subject)
):
    """Whether MLX int8 prefill would apply to this model, judged from its downloaded checkpoint
    without loading it. The first answer on a new macOS or MLX version builds the kernels once."""
    if account_access.managed_account():
        await asyncio.to_thread(account_access.require_model_access, request.model_path)
    if is_ollama_manifest_ref(request.model_path):
        return Int8PrefillAvailabilityResponse(available = False, reason = "unsupported_model")

    def _check() -> Int8PrefillAvailabilityResponse:
        if not _mlx_estimate_available():
            return Int8PrefillAvailabilityResponse(available = False, reason = "unsupported_model")
        config = _cached_estimate_config(request.model_path, None, request.hf_token, False)
        if config is _ESTIMATE_NOT_ON_DISK:
            return Int8PrefillAvailabilityResponse(available = False, reason = "not_downloaded")
        from core.inference.native_audio import is_native_audio_model

        if (
            config is None
            or getattr(config, "is_gguf", False)
            or getattr(config, "is_lora", False)
            or is_native_audio_model(request.model_path)
        ):
            return Int8PrefillAvailabilityResponse(available = False, reason = "unsupported_model")
        model_dir = _local_mlx_model_dir(config)
        if not model_dir:
            return Int8PrefillAvailabilityResponse(available = False, reason = "not_downloaded")
        from core.inference.mlx_inference import mlx_int8_prefill_checkpoint_status

        available, reason = mlx_int8_prefill_checkpoint_status(model_dir)
        return Int8PrefillAvailabilityResponse(available = available, reason = reason or None)

    return await asyncio.to_thread(_check)


@router.post("/estimate-memory", response_model = EstimateMemoryResponse)
async def estimate_memory(
    request: EstimateMemoryRequest,
    fastapi_request: Request = None,
    current_subject: str = Depends(get_current_subject),
):
    """Price a prospective load from its metadata, before the load allocates anything.

    Reads GGUF metadata and file sizes -- or, for an MLX repo, safetensors headers and the
    shapes of an architecture built and never evaluated -- so it is safe to call on every
    settings change: no model is loaded, no tensor data is read, nothing is downloaded.

    The arithmetic is the loader's own KV, compute-buffer and companion sizing. Weights
    times a constant is fine until the KV cache stops being a rounding error: at 262k
    tokens the cache can outweigh the weights. Where the metadata cannot supply the dims
    this answers ``kv_estimable = false`` rather than quoting an assumed total.
    """
    native_access_deferred = _defers_access_to_native_grant(request)
    if account_access.managed_account() and not native_access_deferred:
        await asyncio.to_thread(account_access.require_model_access, request.model_path)
    await _require_drafter_access(request)
    from core.inference.llama_cpp import _args_place_tensors_on_cpu
    from core.inference.llama_server_args import (
        _effective_tensor_parallel,
        strip_split_mode_only,
    )

    # Sizing reads the files those flags name, so a path the load would refuse is not sized either.
    try:
        _refuse_managed_custom_projector(
            request.llama_extra_args, request.model_path, None, request.gguf_variant
        )
    except HTTPException:
        return EstimateMemoryResponse(available = False, reason = "unsizable")
    if is_ollama_manifest_ref(request.model_path):
        # Resolving one writes a .gguf link to disk; that belongs to the load path.
        return EstimateMemoryResponse(available = False, reason = "unsupported_source")
    try:
        model_identifier, _model_log_label, native_grant_backed = (
            # "validate-model": leases verify against their signed op; estimate-memory cannot be minted.
            _resolve_model_identifier_for_request(request, operation = "validate-model")
        )
    except HTTPException:
        # An expired lease is not worth a red error under a settings panel.
        return EstimateMemoryResponse(available = False, reason = "unsupported_source")
    if native_access_deferred:
        await asyncio.to_thread(account_access.require_model_access, model_identifier)

    # Blank slots means the server default (4), as /load resolves it. The clamp runs in the worker:
    # it may run `llama-server --help` (10s timeout) and must not stall the loop.
    requested_slots = _resolve_parallel_slots(request, fastapi_request)

    def _estimate() -> EstimateMemoryResponse:
        config = _cached_estimate_config(
            model_identifier,
            request.gguf_variant,
            request.hf_token,
            native_grant_backed,
        )
        if config is _ESTIMATE_NOT_ON_DISK:
            return EstimateMemoryResponse(available = False, reason = "not_downloaded")
        if config is None:
            return EstimateMemoryResponse(available = False, reason = "unsizable")
        if not getattr(config, "is_gguf", False):
            reason, mlx = _mlx_load_estimate(request, config, model_identifier)
            if mlx is None:
                return EstimateMemoryResponse(available = False, reason = reason)
            return EstimateMemoryResponse(
                **project_estimate_memory_response(
                    build_memory_estimate(
                        dataclasses.replace(mlx.breakdown, offloadable = mlx.offloadable),
                        quant_file_bytes = 0,
                        context_fitted = mlx.fitted_ctx,
                    )
                )
            )
        gguf_path = _local_gguf_main_path(config)
        if not gguf_path:
            return EstimateMemoryResponse(available = False, reason = "not_downloaded")
        resolved_slots = _effective_parallel_slots(
            requested_slots,
            diffusion_kind = False,
        )
        # Price the files on this disk, not the repository they came from.
        config = _localized_estimate_config(config, gguf_path)

        # A CPU-only launch drops the split flags, so a pin charges no per-device buffers.
        pinned_gpu_ids = (
            None
            if _gguf_offloaded_layer_fraction(
                request.gpu_memory_mode,
                request.gpu_layers,
                None,
                request.llama_extra_args,
                device_pin_governs = bool(request.selected_gpu_ids),
            )
            == 0.0
            else request.selected_gpu_ids or None
        )
        # Resolved as the breakdown does: extras --split-mode wins, Manual fixed layers drop tensor.
        tensor_split = (
            _effective_tensor_parallel(request.llama_extra_args, bool(request.tensor_parallel))
            and _tensor_split_possible(request.selected_gpu_ids or None)
            and _manual_keeps_tensor_split(
                request.gpu_memory_mode,
                request.gpu_layers,
                request.llama_extra_args,
            )
        )
        # The probed inventory is the pool: a Vulkan build's _effective_gpu_count sees none of it.
        device_count = _guard_device_count(
            pinned_gpu_ids, _cached_inference_devices(), tensor_parallel = tensor_split
        )
        price = functools.partial(
            _gguf_memory_breakdown,
            config,
            gguf_path,
            hf_token = request.hf_token,
            llama_extra_args = request.llama_extra_args,
            speculative_type = request.speculative_type,
            n_parallel = resolved_slots,
            cache_type_kv = request.cache_type_kv,
            tensor_parallel = bool(request.tensor_parallel),
            n_batch = request.n_batch,
            n_ubatch = request.n_ubatch,
            ctx_checkpoints = request.ctx_checkpoints,
            n_devices = device_count,
            disable_vision = bool(request.disable_vision),
            gpu_memory_mode = request.gpu_memory_mode,
            gpu_layers = request.gpu_layers,
            spec_draft_n_max = request.spec_draft_n_max,
            spec_draft_cache_type = request.spec_draft_cache_type,
            tensor_split_possible = _tensor_split_possible(request.selected_gpu_ids or None),
            # A pin names the cards; the launch strips conflicting device flags.
            device_pin_governs = bool(request.selected_gpu_ids),
            selected_gpu_ids = pinned_gpu_ids,
        )
        breakdown = price(n_ctx = request.n_ctx or 0)
        if breakdown is None:
            return EstimateMemoryResponse(available = False, reason = "unsizable")
        context_floor = _estimate_context_floor(
            request.n_ctx,
            request.llama_extra_args,
            request.gpu_memory_mode,
            request.gpu_layers,
            breakdown,
        )
        floor = None
        if context_floor is not None and breakdown.n_ctx > context_floor.ctx:
            floor = price(n_ctx = context_floor.ctx)
            # Tensor launch can fall back to layer split, replicating compute buffers: take the larger.
            if floor is not None and tensor_split:
                layer = price(
                    n_ctx = context_floor.ctx,
                    tensor_parallel = False,
                    # As tensor_fallback.py relaunches.
                    llama_extra_args = [
                        *(strip_split_mode_only(request.llama_extra_args) or []),
                        "--split-mode",
                        "layer",
                    ],
                    n_devices = device_count,
                )
                if layer is not None and layer.gpu_bytes > floor.gpu_bytes:
                    floor = layer
        elif context_floor is not None:
            floor = breakdown
        # Shaped via canonical MemoryEstimate (core/inference/memory_contract.py) to stay in sync; weights_bytes here means every resident file, not the quant alone.
        estimate = build_memory_estimate(
            breakdown,
            # 0, not a stand-in: nothing here measured the single quant file.
            quant_file_bytes = 0,
            gpu_floor_bytes = (
                None if floor is None else min(int(floor.gpu_bytes), int(breakdown.gpu_bytes))
            ),
            floor_can_offload = context_floor is not None and context_floor.can_offload,
            context_is_pinned = context_floor is None,
            moe_offload_unmodelled = bool(
                (request.gpu_memory_mode == "manual" and (request.n_cpu_moe or 0) > 0)
                # Outside Manual extras keep expert-placement flags (-ncmoe, -cmoe, -ot); /load strips them only on Manual, where the field owns them.
                or (
                    request.gpu_memory_mode != "manual"
                    and _args_place_tensors_on_cpu(request.llama_extra_args)
                )
            ),
        )
        return EstimateMemoryResponse(**project_estimate_memory_response(estimate))

    # Blocking header walks and stats; keep off the loop so slider drags don't stall chats.
    return await asyncio.to_thread(_estimate)


def _mlx_cached_drafters(model_path: str) -> list:
    from core.inference import mlx_speculative
    from utils.utils import hf_cache_snapshot_dir

    model_dir = model_path if os.path.isdir(model_path) else hf_cache_snapshot_dir(model_path)
    if model_dir is None:
        return []
    config = mlx_speculative._read_config(model_dir)
    # The cache is shared between accounts: list only what this one may see.
    return account_access.filter_model_rows(
        [
            {"repo_id": repo, "kind": source.kind, "named": named}
            for repo, source, named in mlx_speculative.cached_drafters(model_path, config)
        ]
    )


@router.post("/mlx-drafters", response_model = MlxDraftersResponse)
async def mlx_drafters(
    request: MlxDraftersRequest, current_subject: str = Depends(get_current_subject)
):
    """Cached drafters an MLX load of this model could name. Reads only local config files."""
    if account_access.managed_account():
        await asyncio.to_thread(account_access.require_model_access, request.model_path)
    return MlxDraftersResponse(
        drafters = await asyncio.to_thread(_mlx_cached_drafters, request.model_path)
    )


@router.post("/unload", response_model = UnloadResponse)
@account_access.gpu_busy_route
async def unload_model(request: UnloadRequest, current_subject: str = Depends(get_current_subject)):
    """Unload a model from memory.

    Padded like /load: a 600 GB GGUF teardown measures 160s, past the proxy timer.
    See ``_tunnel_safe_json``. No in-process caller today; a future one must await
    ``_unload_model_impl`` (as preview awaits ``load_model_gated``), since the padded
    path returns a StreamingResponse, not the payload.
    """
    # /load records a run name as its folder, so unload and cancel by the same spelling
    _resolve_trained_run_request(request)
    return await _tunnel_safe_json(
        _unload_model_impl(request, current_subject), label = "Model unload"
    )


async def _unload_model_impl(request: UnloadRequest, current_subject: str):
    """Routes the unload to llama-server for GGUF models and to Unsloth otherwise."""
    extra = (
        await _route_to_extra_slot(request.model_path)
        if request.cancel_load_request_id is None
        else None
    )
    if extra is not None:
        from core.inference.llama_keepwarm import inference_lifecycle_gate, model_load_gate

        # Load gate first: a reload holds its ref while waiting on the lifecycle gate.
        async with model_load_gate(), inference_lifecycle_gate():
            _raise_or_cancel_slot_generations(extra, force = request.force_cancel_active)
            # Other refs are requests already routed here: let them start or finish, then gate what they start.
            deadline = time.monotonic() + _POST_CANCEL_DRAIN_TIMEOUT_S
            while (extra.generations or extra.refs > 1) and time.monotonic() < deadline:
                await asyncio.sleep(0.05)
                _raise_or_cancel_slot_generations(extra, force = request.force_cancel_active)
            await asyncio.to_thread(model_slots.drop, extra)
        await asyncio.to_thread(release_chat_after_kept_models)
        api_monitor.record_lifecycle(
            event = "unload", model = _lifecycle_model_label(request.model_path), reason = "manual"
        )
        return UnloadResponse(status = "unloaded", model = request.model_path)
    filling = model_slots.visible_loading()
    if filling and _names_the_loading_model(filling[1], request.model_path):
        routed_slot.set(filling[0])
    on_primary = routed_slot.get() is None
    if on_primary:
        sharing = (
            request.cancel_load_request_id is None
            and account_access.managed_account()
            and account_access.shares_resident_with_others("chat")
        )
        if sharing and not await asyncio.to_thread(_loaded_satisfies, request.model_path):
            # Another model's name must not drop this share, and the generic teardown below would
            # clear every sharer's record of the shared model: answer the idempotent no-op.
            return UnloadResponse(status = "unloaded", model = request.model_path)
        if sharing:
            # Leaving a share stops only this account's chats on it; the others keep theirs.
            scope = account_access.account_scope()
            elsewhere = model_slots.all_generations()
            running = active_generations.count(scope, elsewhere, include_external = False)
            if running and not request.force_cancel_active:
                raise _active_generations_conflict(
                    "Unloading the model",
                    running,
                    active_generations.active_thread_ids(scope, elsewhere, include_external = False),
                )
            if account_access.release_shared_resident("chat"):
                if running:
                    active_generations.cancel_all(scope, elsewhere, include_external = False)
                return UnloadResponse(status = "unloaded", model = request.model_path)
        account_access.require_resident_control(
            "chat", _loaded_slot_ident() if account_access.managed_account() else None
        )
    # Drop the idle reload stash so a /v1 request can't resurrect a deliberately unloaded model.
    from core.inference.llama_keepwarm import inference_lifecycle_gate, note_model_unloaded
    from core.inference.npu_backend import MODEL_PREFIX, is_npu_model_path, peek_npu_backend

    if not on_primary:
        note_model_unloaded = lambda: None

    try:
        if is_npu_model_path(request.model_path):
            if account_access.managed_account():
                # Only the owner loads NPU models, so no managed account shares or stops one.
                raise HTTPException(status_code = 404, detail = "Model not found")
            npu = peek_npu_backend()
            requested_id = request.model_path[len(MODEL_PREFIX) :].strip()
            if request.cancel_load_request_id is not None:
                # Bound to that attempt: an early cancel leaves a tombstone, a stale one stops nothing newer.
                attempt, is_running = _cancel_scoped_load_attempt(request, current_subject)
                if attempt is not None and is_running:
                    try:
                        if npu is not None and await asyncio.to_thread(
                            npu.cancel_load, requested_id
                        ):
                            logger.info(
                                f"Cancelled scoped in-flight NPU load: {request.model_path}"
                            )
                    finally:
                        attempt.cancel_complete.set()
                return UnloadResponse(status = "unloaded", model = request.model_path)
            # "Stop loading": /load holds the lifecycle gate until /v1/load returns.
            if npu is not None and await asyncio.to_thread(npu.cancel_load, requested_id):
                logger.info(f"Cancelled in-flight NPU load: {request.model_path}")
                return UnloadResponse(status = "unloaded", model = request.model_path)
            async with inference_lifecycle_gate():
                # Only the named model: another tab may have replaced it since.
                npu_model = npu.loaded_model if npu is not None else None
                if npu_model is not None and npu_model.id == requested_id:
                    _raise_or_cancel_active_generations(
                        force = request.force_cancel_active, action = "Unloading the model"
                    )
                    await _drain_and_recancel_before_teardown(
                        force = request.force_cancel_active, action = "Unloading the model"
                    )
                    await asyncio.to_thread(npu.unload)
                    note_model_unloaded()
                    account_access.clear_resident("chat")
                    api_monitor.record_lifecycle(
                        event = "unload", model = request.model_path, reason = "manual"
                    )
                    logger.info(f"Unloaded NPU model: {request.model_path}")
            return UnloadResponse(status = "unloaded", model = request.model_path)

        # Bound to the exact load attempt so a delayed cancel never stops a newer load.
        if request.cancel_load_request_id is not None:
            attempt, is_running = _cancel_scoped_load_attempt(request, current_subject)
            if attempt is None or not is_running:
                return UnloadResponse(status = "unloaded", model = request.model_path)
            try:
                backend = await asyncio.to_thread(get_inference_backend)
                loading = getattr(backend, "get_loading_model", lambda: None)()
                if (
                    loading is not None
                    and hasattr(backend, "cancel_load")
                    and _names_the_loading_model(loading, attempt.model_path)
                    and await asyncio.to_thread(backend.cancel_load, loading)
                ):
                    note_model_unloaded()
                    logger.info("Cancelled scoped in-flight load: %s", request.model_path)
                    return UnloadResponse(status = "unloaded", model = request.model_path)

                llama_backend = get_llama_cpp_backend()
                if (
                    llama_backend.is_active
                    and not llama_backend.is_loaded
                    and (
                        llama_backend.model_identifier == attempt.model_path
                        or is_registered_native_path_label(
                            llama_backend.model_identifier, attempt.model_path
                        )
                        or _names_the_resident_model(
                            llama_backend.model_identifier, attempt.model_path
                        )
                    )
                ):
                    await asyncio.to_thread(llama_backend.unload_model)
                    note_model_unloaded()
                    logger.info("Cancelled scoped in-flight GGUF load: %s", request.model_path)
                return UnloadResponse(status = "unloaded", model = request.model_path)
            finally:
                attempt.cancel_complete.set()

        # cancel_load only kills the loading subprocess, so it runs off-gate and must stay ahead of the active-generation refusal.
        backend = await asyncio.to_thread(get_inference_backend)
        loading = getattr(backend, "get_loading_model", lambda: None)()
        if (
            loading is not None
            and hasattr(backend, "cancel_load")
            and _names_the_loading_model(loading, request.model_path)
        ):
            # Cancel under the name the load runs as, which a pinned row states as a path.
            if await asyncio.to_thread(backend.cancel_load, loading):
                note_model_unloaded()
                logger.info(f"Cancelled in-flight load: {request.model_path}")
                return UnloadResponse(status = "unloaded", model = request.model_path)

        # Still-loading GGUF: unload_model sets cancel_event with no worker command, safe off-gate; gated on the loading model so other unloads cannot cancel it.
        llama_backend = get_llama_cpp_backend()
        if (
            llama_backend.is_active
            and not llama_backend.is_loaded
            and (
                llama_backend.model_identifier == request.model_path
                or is_registered_native_path_label(
                    llama_backend.model_identifier, request.model_path
                )
                or _names_the_resident_model(llama_backend.model_identifier, request.model_path)
            )
        ):
            await asyncio.to_thread(llama_backend.unload_model)
            note_model_unloaded()
            logger.info(f"Cancelled in-flight GGUF load: {request.model_path}")
            return UnloadResponse(status = "unloaded", model = request.model_path)
        if not on_primary:
            return UnloadResponse(status = "unloaded", model = request.model_path)

        # Must stay BEHIND the stop-loading fast paths: they cannot interrupt a chat.
        if await asyncio.to_thread(_unload_may_evict, request.model_path):
            _raise_or_cancel_active_generations(
                force = request.force_cancel_active,
                action = "Unloading the model",
                cancel = False,
            )

        # Serialize with /load: otherwise a new subprocess could receive this unload command.
        async with inference_lifecycle_gate():
            # Rechecked under the gate, like /load: a chat can register while this queues.
            if await asyncio.to_thread(_unload_may_evict, request.model_path):
                _raise_or_cancel_active_generations(
                    force = request.force_cancel_active,
                    action = "Unloading the model",
                    cancel = False,
                )
            # Check if the GGUF backend has this model loaded or is loading it.
            llama_backend = get_llama_cpp_backend()
            if llama_backend.is_active and (
                _names_the_resident_gguf(llama_backend, request.model_path)
                or not llama_backend.is_loaded
            ):
                # Read the identity before teardown clears it, so the row reads repo:QUANT.
                _unloaded = _llama_public_model_id(llama_backend, request.model_path)
                _unloaded_variant = getattr(llama_backend, "hf_variant", None)
                # Manual unload replaces the running server, so it cancels mid-stream chats; idle unload defers.
                _raise_or_cancel_active_generations(
                    force = request.force_cancel_active, action = "Unloading the model"
                )
                # Drain cancelled streams first, like /load, or they end as dropped connections; the wait is bounded since a manual unload is deliberate.
                await _drain_and_recancel_before_teardown(
                    force = request.force_cancel_active, action = "Unloading the model"
                )
                # Off the loop: a long teardown would block the event loop and this route's own padding.
                await asyncio.to_thread(llama_backend.unload_model)
                note_model_unloaded()
                account_access.clear_resident("chat")
                await asyncio.to_thread(release_chat_gpu_claim)
                api_monitor.record_lifecycle(
                    event = "unload",
                    model = _lifecycle_model_label(_unloaded, _unloaded_variant),
                    reason = "manual",
                )
                # No log here: unload_model logs every unload, and duplicates break the reload count grep.
                return UnloadResponse(status = "unloaded", model = request.model_path)

            # Off-loop: unload takes _gen_lock, which a paused SSE stream may hold.
            backend = await asyncio.to_thread(get_inference_backend)
            evicts = _unload_evicts_standard_backend(backend, request.model_path)
            if evicts:
                # Point of no return for the standard path, same rule as above.
                _raise_or_cancel_active_generations(
                    force = request.force_cancel_active, action = "Unloading the model"
                )
                await _drain_and_recancel_before_teardown(
                    force = request.force_cancel_active, action = "Unloading the model"
                )
            managed = getattr(backend, "_managed_engine", None) is not None
            stopped = await asyncio.to_thread(
                backend.unload_model, _resident_standard_model_name(backend, request.model_path)
            )
            # A live engine still holds its VRAM, so keep the chat claim, as training does.
            if managed and stopped is False:
                raise HTTPException(status_code = 500, detail = "The inference engine did not stop.")
            note_model_unloaded()
            account_access.clear_resident("chat")
            await asyncio.to_thread(release_chat_gpu_claim)
            # The no-op stays a 200 for stale tabs, but logging it read as an unload of whatever is resident.
            if evicts:
                api_monitor.record_lifecycle(
                    event = "unload",
                    model = _lifecycle_model_label(request.model_path),
                    reason = "manual",
                )
                logger.info(f"Unloaded model: {request.model_path}")
            return UnloadResponse(status = "unloaded", model = request.model_path)

    except HTTPException:
        # Typed refusals (the gate's 409) must not be rewritten as a 500 below.
        raise
    except Exception as e:
        logger.error(f"Error unloading model: {e}", exc_info = True)
        raise HTTPException(status_code = 500, detail = "Failed to unload model")


@studio_router.post("/cancel")
async def cancel_inference(request: Request, current_subject: str = Depends(get_current_subject)):
    """Cancel in-flight inference requests.

    Body (JSON, at least one key required):
      cancel_id    - preferred: per-run UUID, matched exclusively.
      session_id   - fallback when cancel_id is absent.
      completion_id - fallback when cancel_id is absent.

    A cancel_id arriving before its stream registers is stashed briefly and
    replayed on registration. Returns {"cancelled": N}.
    """
    try:
        body = await request.json()
        if not isinstance(body, dict):
            body = {}
    except Exception as e:
        logger.debug("Failed to parse cancel request body: %s", e)
        body = {}

    cancel_id = body.get("cancel_id")
    if isinstance(cancel_id, str) and cancel_id:
        return {"cancelled": _cancel_by_cancel_id_or_stash(cancel_id)}

    keys = []
    # `message_id`: Anthropic passthrough id, so /v1/messages clients can cancel.
    for k in ("completion_id", "session_id", "message_id"):
        v = body.get(k)
        if isinstance(v, str) and v:
            keys.append(v)

    if not keys:
        return {"cancelled": 0}

    n = _cancel_by_keys(keys)
    return {"cancelled": n}


@studio_router.post("/tool-confirm")
async def confirm_tool_call(
    request: ToolConfirmRequest, current_subject: str = Depends(get_current_subject)
):
    full_access = request.permission_mode == "full"
    if full_access and (
        not auth_policy.full_access_permitted() or auth_policy.api_full_access_refused()
    ):
        raise HTTPException(
            status_code = 403,
            detail = "Full access is only available to the installation owner in the Unsloth UI "
            "(API callers require UNSLOTH_STUDIO_ALLOW_API_FULL_ACCESS=1).",
        )
    # Approving a host-path call unsandboxes it: like Full access, the UI's choice, not an API key's. Deny stays open.
    if (
        request.decision == "allow"
        and auth_policy.api_full_access_refused()
        and tool_decision_grants_host_access(request.approval_id, request.session_id)
    ):
        raise HTTPException(
            status_code = 403,
            detail = "This tool call reaches files outside the sandbox, and API keys cannot approve "
            "that: approve it in the Unsloth UI, or set UNSLOTH_STUDIO_ALLOW_API_FULL_ACCESS=1 on "
            "the server to allow it.",
        )
    matched = resolve_tool_decision(
        request.approval_id,
        request.decision,
        session_id = request.session_id,
        full_access = full_access,
    )
    if not matched:
        raise HTTPException(status_code = 404, detail = "No pending tool call confirmation")
    # An older backend ignores the new request field; clients require this acknowledgement.
    return {"resolved": True, **({"full_access_granted": True} if full_access else {})}


@studio_router.post("/browser-action-result")
async def browser_action_result(
    body: BrowserActionResultRequest, current_subject: str = Depends(get_current_subject)
):
    from state.browser_actions import resolve_browser_action
    from utils.account_context import current_account_id

    if not resolve_browser_action(
        body.action_id, body.result, body.session_id, current_account_id()
    ):
        raise HTTPException(status_code = 404, detail = "No pending browser action")
    return {"resolved": True}


@studio_router.post("/tool-approval-status")
async def tool_approval_status(
    request: ToolApprovalStatusRequest, current_subject: str = Depends(get_current_subject)
):
    """Whether a parked approval is still waiting on a human.

    A reopened tab restores Approve/Deny from a saved card that has no result and an approval id.
    That shape is identical whether the call is still parked or the user already answered it and
    the tool is mid-flight, since the result only arrives with tool_end. Without this the tab
    re-arms the answered one and every press 404s.

    POST rather than GET so the id travels in the body instead of a URL that lands in logs.
    """
    return {"pending": tool_decision_is_pending(request.approval_id, request.session_id)}


@studio_router.get("/monitor")
async def get_api_monitor(current_subject: str = Depends(get_current_subject)):
    """Return recent OpenAI-compatible API activity for Unsloth."""
    # Off-loop: first get_inference_backend() waits on hardware detection.
    active_model, context_length, queue, direct_busy = await asyncio.to_thread(
        lambda: (
            _monitor_active_model(),
            _monitor_context_length(),
            _monitor_queue_state(),
            _direct_llama_is_busy(),
        )
    )
    if account_access.resident_hidden("chat", active_model):
        active_model, context_length = None, None
    active_requests = api_monitor.active_count(subject = current_subject)
    # Direct llama calls (RAG caption/OCR) open no row; count the server-wide queue too.
    queue_busy = bool(queue) and bool(queue.get("active") or queue.get("queued"))
    # direct_busy stands alone: with admission control off the queue readout is None.
    if active_requests or queue_busy or direct_busy:
        operating_status = "generating"
    elif active_model:
        operating_status = "ready"
    else:
        operating_status = "idle"
    # Logging off makes snapshot() empty, like an idle Unsloth; flag disabled so the UI can say why.
    return {
        "status": operating_status,
        # Browser clock may disagree over a tunnel; the monitor dates snapshots against this.
        "server_time": time.time(),
        "active_model": active_model,
        "context_length": context_length,
        "active_requests": active_requests,
        "queue": queue,
        "logging_enabled": api_monitor.enabled,
        "entries": api_monitor.snapshot(include_details = False, subject = current_subject),
    }


@studio_router.get("/sampling-defaults")
async def get_sampling_defaults(model: str, current_subject: str = Depends(get_current_subject)):
    """The sampling a /v1 request naming ``model`` gets for every field it leaves out.

    The same resolution the request path applies (operator ``UNSLOTH_SAMPLING_*`` pins, then the
    model's recommendation, then the schema default), so the API page's example request shows the
    values a client would actually get. Off-loop: the first read of a model loads its YAML.
    """
    # A kept model answers its own requests: route as the request path does, so the backend getters
    # below read that slot rather than the primary.
    await _route_to_extra_slot(model)
    return await asyncio.to_thread(_sampling_defaults_for, model)


def _sampling_defaults_for(model: str) -> dict:
    """``resolve_effective_sampling`` as the request path calls it. For the loaded llama model that
    keys on its identifier and passes its default thinking mode: Qwen3-family recommendations
    differ between thinking and non-thinking, and leaving it out shows values a request never gets.
    """
    from utils.inference.inference_config import resolve_effective_sampling

    model_id, thinking = model, None
    llama_backend = get_llama_cpp_backend()
    # Another account's resident stays hidden, as on the monitor: resolving against it would tell
    # the caller which model that account has loaded.
    if getattr(llama_backend, "is_loaded", False) and not account_access.resident_hidden(
        "chat", _monitor_active_model()
    ):
        identifier = getattr(llama_backend, "model_identifier", None)
        names = {n for n in (identifier, _llama_public_model_id(llama_backend)) if n}
        if model in names or model.rsplit(":", 1)[0] in names:
            model_id = identifier or model
            thinking = _sampling_thinking_mode(
                llama_backend,
                ChatCompletionRequest(messages = [{"role": "user", "content": "Hello!"}]),
            )
    return resolve_effective_sampling(model_id, {}, thinking = thinking)


@studio_router.delete("/monitor")
async def clear_api_monitor(current_subject: str = Depends(get_current_subject)):
    """Drop this caller's recorded API history so a debugging session starts clean.

    Scoped to the current subject, like every read on the monitor: an unscoped
    wipe would erase another user's history and zero their active-request count
    while their generation is still streaming.

    The caller's own in-flight requests are dropped from the log too; they keep
    streaming to their client, they just stop being reported here (a later append
    re-adds nothing, since the entry id no longer resolves).
    """
    api_monitor.clear(subject = current_subject)
    return {"cleared": True}


@studio_router.get("/monitor/{entry_id}")
async def get_api_monitor_entry(
    entry_id: str,
    current_subject: str = Depends(get_current_subject),
    include_prompt: bool = True,
):
    """Return full prompt/reply details for one OpenAI-compatible API request."""
    entry = api_monitor.get(entry_id, subject = current_subject, include_prompt = include_prompt)
    if entry is None:
        raise HTTPException(status_code = 404, detail = "Monitor entry not found")
    return entry


def _decode_and_resize_image(backend, encoded: str):
    """Off the event loop. The decode is forced so a truncated picture is a bad request here, and
    the result is flattened RGB: CMYK, PA, F and LAB decode and none can be saved back, and a plain
    convert would turn a transparent background black under dark ink."""
    from PIL import Image
    from io import BytesIO

    image_data = base64.b64decode(encoded)
    image = Image.open(BytesIO(image_data))
    image.load()
    image = exif_upright(image)
    # After the resize: converting first resamples interpolated RGB, a different picture.
    return _mcp_flattened_rgb(backend.resize_image(image))


# Caps retained rasters: ~4.8 KB base64 can decode to 1.92 MB (391x amplification).
_MAX_SERVED_IMAGES = 64


async def _decode_request_images(
    backend,
    encoded_images,
    decoded = None,
    reject = None,
):
    """Returns images in encoded_images order, decoding one at a time so one full-size raster is held; repeats count each time."""
    total = len(encoded_images)
    if total > _MAX_SERVED_IMAGES:
        detail = (
            f"This request carries {total} images; at most {_MAX_SERVED_IMAGES} are "
            "served per request. Send fewer, or split the conversation."
        )
        # Through the caller's reject, so an open API monitor row is failed, not left running.
        raise (
            reject(400, detail)
            if reject is not None
            else HTTPException(
                status_code = 400,
                detail = detail,
            )
        )
    ready = dict(decoded or {})
    images = []
    for encoded in encoded_images:
        if encoded not in ready:
            ready[encoded] = await asyncio.to_thread(_decode_and_resize_image, backend, encoded)
        images.append(ready[encoded])
    return images


@router.post("/generate/stream")
async def generate_stream(
    request: GenerateRequest,
    fastapi_request: Request,
    current_subject: str = Depends(get_current_subject),
):
    """
    Generate a chat response with Server-Sent Events (SSE) streaming.

    For vision models, provide image_base64 (base64-encoded image).
    """
    if account_access.managed_account() and await asyncio.to_thread(
        lambda: account_access.resident_hidden("chat", _loaded_slot_ident())
    ):
        raise HTTPException(status_code = 404, detail = "Model not found")
    # Enforce the preview-swap reject FIRST: later checks would run on the swapped model.
    # generate_stream skips _maybe_auto_switch_model, where this guard otherwise runs.
    from core.inference.llama_keepwarm import (
        mark_response_failed,
        note_admitted_inference,
        preview_swapped_since_entry,
    )

    _gs_scope = getattr(fastapi_request, "scope", None)
    # Count admitted inference in the tally the preview busy guard uses, not raw _inflight.
    note_admitted_inference(_gs_scope)
    # Reject if a preview swapped in since entry, including requests still pre-admission at the gate.
    if preview_swapped_since_entry(_gs_scope):
        raise HTTPException(
            status_code = 503,
            detail = "A preview is loading a model. Please retry shortly.",
            headers = {"Retry-After": "1"},
        )

    backend = await asyncio.to_thread(get_inference_backend)

    if not backend.active_model_name:
        raise HTTPException(
            status_code = 400, detail = "No model loaded. Call POST /inference/load first."
        )
    # Decode image if provided (vision models)
    image = None
    if request.image_base64:
        try:
            # Check current model supports vision
            model_info = backend.models.get(backend.active_model_name, {})
            if not model_info.get("is_vision"):
                raise HTTPException(
                    status_code = 400,
                    detail = "Image provided but current model is text-only. Load a vision model.",
                )

            image = await asyncio.to_thread(
                _decode_and_resize_image,
                backend,
                request.image_base64,
            )

        except HTTPException:
            raise
        except Exception as e:
            raise log_and_http_error(
                e,
                400,
                "Failed to decode image",
                event = "inference.decode_image_failed",
                log = logger,
            )

    cancel_event = threading.Event()

    async def stream():
        gen = None
        completed = False
        # Watch for disconnect: the generator only awaits to_thread(next), so it would not notice.
        disconnect_watcher = asyncio.create_task(
            _await_disconnect_then_cancel(fastapi_request, cancel_event)
        )
        # Registered inside the generator, under its unregistering finally, so an unstarted body leaks nothing.
        _tracker = _TrackedCancel(cancel_event, model = backend.active_model_name)
        _tracker.__enter__()
        try:
            gen = backend.generate_chat_response(
                messages = request.messages,
                system_prompt = request.system_prompt,
                image = image,
                temperature = request.temperature,
                top_p = request.top_p,
                top_k = request.top_k,
                min_p = request.min_p,
                max_new_tokens = request.max_new_tokens,
                repetition_penalty = request.repetition_penalty,
                presence_penalty = request.presence_penalty,
                cancel_event = cancel_event,
            )
            gen_step = ThreadStepper(gen).next
            _DONE = object()
            while True:
                if cancel_event.is_set():
                    # Closing the generator does not signal a subprocess backend; reset here.
                    backend.reset_generation_state(cancel_event)
                    # Flag failed so the middleware does not claim the model on a cancelled stream.
                    mark_response_failed(_gs_scope)
                    break
                chunk = await gen_step(_DONE)
                if chunk is _DONE:
                    if cancel_event.is_set():
                        mark_response_failed(_gs_scope)
                        break
                    completed = True
                    break
                if isinstance(chunk, GenStreamError):
                    # In-band backend sentinel under a sent 200: flag failed so the middleware won't claim.
                    mark_response_failed(_gs_scope)
                    yield f"data: {json.dumps({'error': _friendly_gen_stream_error(chunk)})}\n\n"
                    yield "data: [DONE]\n\n"
                    return
                yield f"data: {json.dumps({'content': chunk})}\n\n"
            if completed:
                yield "data: [DONE]\n\n"

        except asyncio.CancelledError:
            cancel_event.set()
            backend.reset_generation_state(cancel_event)
            raise
        except Exception as e:
            cancel_event.set()
            backend.reset_generation_state(cancel_event)
            logger.error(f"Error during generation: {e}", exc_info = True)
            # Already sent 200: flag failure out-of-band so the middleware won't claim the model.
            mark_response_failed(_gs_scope)
            yield f"data: {json.dumps({'error': _friendly_error(e)})}\n\n"
            yield "data: [DONE]\n\n"
        finally:
            # Nested so a teardown failure still unregisters; a phantom entry 409s swaps.
            try:
                await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
                if not completed and not cancel_event.is_set():
                    cancel_event.set()
                    backend.reset_generation_state(cancel_event)
                if gen is not None:
                    try:
                        await asyncio.to_thread(gen.close)
                    except (RuntimeError, ValueError):
                        pass
            finally:
                _tracker.__exit__(None, None, None)

    return _sse_streaming_response(stream())


def _probe_llama_cpp_status(llama_backend) -> tuple[bool, dict]:
    """Read llama.cpp capabilities and release freshness without raising."""
    try:
        binary = type(llama_backend)._find_llama_server_binary()
        capabilities = type(llama_backend).probe_server_capabilities(binary)
        # Treat a discovered but inconclusive binary as MTP-compatible.
        supports_mtp = bool(
            capabilities.get("supports_mtp", False)
            or (
                capabilities.get("found", False)
                and capabilities.get("mtp_probe_inconclusive", False)
            )
        )
    except Exception:
        binary = None
        supports_mtp = False  # no usable binary: MTP genuinely unavailable
    try:
        from utils.llama_cpp_freshness import check_prebuilt_freshness
        freshness = check_prebuilt_freshness(binary)
    except Exception:
        freshness = {}
    return supports_mtp, freshness


def _parallel_slots_are_clamped() -> bool:
    """Whether this build clamps to one slot, asked of the load's own helper so they cannot drift; the editor needs it to accept batches that run."""
    return _effective_parallel_slots(2) == 1


async def _effective_default_slots(fastapi_request) -> tuple[int, bool]:
    """Probes the binary in a thread: a cold cache can take ten seconds and would stall every request."""
    requested = _resolve_parallel_slots(_NoParallelRequest(), fastapi_request)
    if requested <= 1:
        # Still probe: the editor sizes an explicit Slots value by whether this build clamps.
        return requested, await asyncio.to_thread(_parallel_slots_are_clamped)
    effective = await asyncio.to_thread(_effective_parallel_slots, requested)
    return effective, effective == 1


@router.get("/llama-flags", response_model = LlamaFlagCatalogResponse)
async def get_llama_flags(
    fastapi_request: Request = None,
    managed_only: bool = False,
    current_subject: str = Depends(get_current_subject),
):
    """Flags the installed llama-server accepts, for the extra-arguments editor.

    Cheap to call: ``probe_server_capabilities`` caches on the binary's revision, so
    only the first call after an install or an update runs the 10s ``--help`` probe.
    A failed probe answers ``probe_ok = false`` with no flags rather than erroring, so
    the editor degrades to "cannot verify" instead of blocking every argument.

    ``managed_only`` skips the probe entirely. The denylist is Unsloth's own and needs
    no binary to read, while the caller that needs it most is the panel sanitizing a
    stored list before it becomes an explicit request: making that wait on a cold
    ``--help`` would leave a legacy flag in the request for as long as the probe runs.
    """
    from core.inference.llama_server_args import (
        WINDOWS_COMMAND_LIMIT,
        WINDOWS_COMMAND_RESERVE,
        max_extra_args_bytes,
        sorted_managed_flags,
    )

    _default_slots, _slots_clamped = await _effective_default_slots(fastapi_request)
    # Size limits this host enforces, so editors reject what the server would reject with a 400.
    limits = {
        "max_bytes": max_extra_args_bytes(),
        "windows_command_budget": (
            WINDOWS_COMMAND_LIMIT - WINDOWS_COMMAND_RESERVE if sys.platform == "win32" else 0
        ),
        # Effective default slot count after clamps; llama-server aborts on a batch below the slots.
        "default_parallel_slots": _default_slots,
        "parallel_slots_clamped": _slots_clamped,
    }

    if managed_only:
        return LlamaFlagCatalogResponse(
            flags = {},
            managed = sorted_managed_flags(),
            # No probe was attempted, so nothing here can say a flag is a typo.
            probe_ok = False,
            **limits,
        )
    try:
        backend = get_llama_cpp_backend()
        # Off-loop: a cold cache runs `llama-server --help` with a 10s timeout.
        capabilities = await asyncio.to_thread(type(backend).probe_server_capabilities)
        flags = capabilities.get("flags") or {}
        switch_flags = list(capabilities.get("switch_flags") or ())
        # Read the probe's own result: a partial --help catalogue would mark later flags as typos.
        probe_ok = (
            bool(capabilities.get("found"))
            and bool(flags)
            and bool(capabilities.get("help_probe_ok", True))
        )
    except Exception as exc:  # noqa: BLE001 -- an unverifiable flag is not a failed request
        logger.debug(f"llama-server flag catalogue unavailable: {exc}")
        flags = {}
        switch_flags = []
        probe_ok = False
    return LlamaFlagCatalogResponse(
        flags = {str(k): str(v) for k, v in flags.items()},
        managed = sorted_managed_flags(),
        switch_flags = [str(flag) for flag in switch_flags],
        probe_ok = probe_ok,
        **limits,
    )


@router.get("/status", response_model = InferenceStatusResponse)
async def inference_status(
    current_subject: str = Depends(get_current_subject),
    via_api_key: bool = Depends(authenticated_via_api_key),
    model: Optional[str] = None,
):
    """`GET /api/inference/status`, redacted the way the image and video status routes are.

    A chat or GGUF row loaded from an inventory reference RETAINS the resolved absolute path
    as the resident model identity, and it comes back out here through `active_model`,
    `model_identifier` and `loaded`. This route answers long after the request that resolved
    the reference has ended, so there is no handle in the request context to put back and
    `restore_inventory_handles` cannot help: the redactor hands out the same opaque reference
    the caller sent instead. Without it, an API-key caller recovered the path the inventory
    redaction exists to hide by loading the row and then polling status.
    """
    from hub.utils.host_paths import redact_host_paths
    return redact_host_paths(
        await get_status(current_subject = current_subject, model = model),
        via_api_key = via_api_key,
    )


async def get_status(current_subject: str, model: Optional[str] = None):
    """Status of the slot serving ``model`` (the primary one by default), listing every loaded model."""
    slot = await _route_to_extra_slot(model)
    response = await _slot_status(current_subject)
    if isinstance(response, InferenceStatusResponse) and response.is_gguf:
        response.resident_mib = _llama_resident_mib()
    if isinstance(response, InferenceStatusResponse):
        from utils.multi_model_settings import get_multi_model_mode

        response.multi_model_mode = await asyncio.to_thread(get_multi_model_mode)
        active = response.active_model
        response.serving = [active] if active else []
        response.serving_checkpoints = [response.model_identifier or active] if active else []
        for other in (None, *model_slots.visible()):
            if other is not slot:
                entries, checkpoints = await asyncio.to_thread(
                    model_slots.in_slot, other, _slot_entries_and_checkpoints
                )
                response.loaded += [e["id"] for e in entries if e["id"] not in response.loaded]
                for e in entries:
                    # By checkpoint: two local files can share a label.
                    checkpoint = checkpoints.get(e["id"]) or e["id"]
                    if checkpoint not in response.serving_checkpoints:
                        response.serving.append(e["id"])
                        response.serving_checkpoints.append(checkpoint)
    return response


def _llama_resident_mib() -> Optional[int]:
    """The routed slot's llama-server footprint; None when not loaded or unreadable."""
    try:
        llama = get_llama_cpp_backend()
        return llama.resident_memory_mib() if getattr(llama, "is_loaded", False) else None
    except Exception:  # noqa: BLE001 - optional decoration on a status read
        return None


def _slot_entries_and_checkpoints() -> "tuple[list[dict], dict[str, str]]":
    """This slot's /v1/models entries, and the checkpoint each local one is loaded from."""
    checkpoints: dict[str, str] = {}
    llama = get_llama_cpp_backend()
    if getattr(llama, "is_loaded", False):
        public = _llama_public_model_id(llama)
        if public:
            checkpoints[public] = _llama_status_model_ids(llama)[1] or public
    backend = _peek_inference_backend()
    name = getattr(backend, "active_model_name", None)
    if name:
        checkpoints[_orchestrator_public_model_id(backend) or name] = name
    return _slot_model_objects(), checkpoints


async def _slot_status(current_subject: str):
    """Reports whichever backend (Unsloth or llama-server) is active."""
    on_primary = routed_slot.get() is None
    backend = _peek_inference_backend()
    if getattr(backend, "_managed_engine", None) is not None:
        await asyncio.to_thread(reap_dead_managed_engine, backend)
    if on_primary and account_access.resident_hidden("chat"):
        return account_access.hidden_chat_status_response()
    try:
        llama_backend = get_llama_cpp_backend()
        if (
            on_primary
            and account_access.managed_account()
            and account_access.resident_hidden("chat", _loaded_slot_ident())
        ):
            return account_access.hidden_chat_status_response()

        # Cold subprocess/GitHub probes must not block the loop or the default executor.
        _supports_mtp, _freshness = await asyncio.get_running_loop().run_in_executor(
            _STATUS_PROBE_EXECUTOR,
            run_as,
            current_account(),
            _probe_llama_cpp_status,
            llama_backend,
        )
        _stale = bool(_freshness.get("stale"))
        _installed_tag = _freshness.get("installed_tag")
        _latest_tag = _freshness.get("latest_tag")

        with _scoped_load_attempts_lock:

            def visible_attempt(attempt):
                return attempt is not None and (
                    not account_access.managed_account() or attempt.subject == current_account_id()
                )

            _tracked_loading_id = (
                _running_load_attempt.model_path if visible_attempt(_running_load_attempt) else ""
            )
            if not _tracked_loading_id:
                _queued = next(
                    (a for a in _pending_load_attempts.values() if visible_attempt(a)), None
                )
                _tracked_loading_id = _queued.model_path if _queued is not None else ""
        # The attempt holds what the client sent, which for an on-device model is a path.
        _tracked_loading_id = _loading_public_id(_tracked_loading_id) or ""
        _loading = [_tracked_loading_id] if _tracked_loading_id else []
        backend = _peek_inference_backend()

        from core.inference.npu_backend import peek_npu_backend

        _npu = peek_npu_backend()
        _npu_resident = _npu.resident() if _npu is not None and routed_slot.get() is None else None
        if _npu_resident is not None:
            _npu_model = _npu_resident.model
            return InferenceStatusResponse(
                active_model = _npu_model.id,
                model_identifier = _npu_model.model_path,
                is_npu = True,
                is_vision = _npu_model.vision,
                loading = _loading,
                loaded = [_npu_model.model_path],
                inference = load_inference_config(_npu_model.id),
                context_length = _npu_resident.context_length,
                requested_context_length = _npu_resident.requested_context_length,
                max_context_length = _npu_model.max_context_length,
                native_context_length = _npu_model.max_context_length,
                context_length_enforced = True,
                context_length_fitted = None,
                supports_reasoning = _npu_model.reasoning,
                reasoning_style = "enable_thinking",
                supports_tools = _npu_model.tools,
                llama_cpp_supports_mtp = _supports_mtp,
            )

        # If a GGUF model is loaded via llama-server, report that
        if llama_backend.is_loaded:
            _model_id = llama_backend.model_identifier
            # is_local_model below needs the flag; the helper reports identities, not provenance.
            _native_grant_backed = getattr(llama_backend, "_native_grant_backed", False)
            # Shared with /chat/count_tokens, so a client can tell whose tokenizer counted.
            _display_model_id, _reported_model_identifier = _llama_status_model_ids(llama_backend)
            _inference_cfg = load_inference_config(_model_id) if _model_id else None
            # Hide Unsloth's auto-applied bundled template: the frontend would re-send it as an override.
            _reported_chat_template_override = llama_backend.chat_template_override
            _auto_chat_template_override = resolve_effective_chat_template_override(
                model_identifier = _model_id,
                user_override = None,
            )
            if (
                _auto_chat_template_override is not None
                and _reported_chat_template_override == _auto_chat_template_override
            ):
                _reported_chat_template_override = None
            # Overwrite in the dict rather than pass as a second keyword (TypeError).
            _runtime_fields = _llama_runtime_fields(llama_backend)
            _runtime_fields["chat_template_override"] = _reported_chat_template_override
            return InferenceStatusResponse(
                active_model = _display_model_id,
                model_identifier = _reported_model_identifier,
                is_gguf = True,
                is_local_model = _loaded_is_local_model(
                    llama_backend, _native_grant_backed, _model_id
                ),
                gguf_variant = llama_backend.hf_variant,
                memory_warning = _status_load_warning(llama_backend),
                loading = _loading,
                # The GGUF load unloaded only the ACTIVE model; registry-cached ones stay in VRAM.
                loaded = ([_display_model_id] if _display_model_id else [])
                + [name for name in _standard_models_still_held() if name != _display_model_id],
                inference = _inference_cfg,
                **_runtime_fields,
                requested_context_length = llama_backend.requested_n_ctx,
                llama_cpp_supports_mtp = _supports_mtp,
                spec_fallback_binary_changed = _spec_fallback_binary_changed(llama_backend),
                spec_probe_retry_pending = _spec_probe_retry_pending(llama_backend),
                spec_dflash_retry_pending = _spec_dflash_retry_pending(llama_backend),
                spec_dspark_sidecar_absent = _spec_dspark_sidecar_absent(llama_backend),
                gpu_placement_paravirtual = _gpu_placement_paravirtual(),
                audio_probe_pending = _audio_probe_pending(llama_backend),
                diffusion_split_supported = _diffusion_split_supported(llama_backend),
                tensor_parallel_dropped_by_arch_gate = _arch_gate_dropped_tensor_parallel(
                    llama_backend
                ),
                llama_cpp_prebuilt_stale = _stale,
                llama_cpp_installed_tag = _installed_tag,
                llama_cpp_latest_tag = _latest_tag,
            )

        # Peek rather than build: the chat UI polls this from first paint.
        if backend is None:
            return InferenceStatusResponse(
                loading = _loading,
                llama_cpp_supports_mtp = _supports_mtp,
                llama_cpp_prebuilt_stale = _stale,
                llama_cpp_installed_tag = _installed_tag,
                llama_cpp_latest_tag = _latest_tag,
            )

        is_vision = False
        is_audio = False
        audio_type = None
        has_audio_input = False
        has_video_input = False
        # Snapshot before the await below: a load landing mid-await must not mix two models.
        _active = backend.active_model_name
        _loaded = list(backend.models.keys())
        model_info = {}
        if _active:
            model_info = backend.models.get(_active, {})
            is_vision = model_info.get("is_vision", False)
            is_audio = model_info.get("is_audio", False)
            audio_type = model_info.get("audio_type")
            has_audio_input = model_info.get("has_audio_input", False)
            has_video_input = model_info.get("has_video_input", False)
        chat_template_info = model_info.get("chat_template_info", {})
        chat_template = (
            chat_template_info.get("template") if isinstance(chat_template_info, dict) else None
        )

        # Non-GGUF: classify from the loaded template.
        _sf_flags, _ = _sf_rendered_features(backend, model_info)
        inference_config = load_inference_config(_active) if _active else None

        # Backend and attempt registry name one load, so compare public ids or path loads show twice.
        _loading_models = list(getattr(backend, "loading_models", set()))
        if _tracked_loading_id and not any(
            _loading_public_id(_name) == _tracked_loading_id for _name in _loading_models
        ):
            _loading_models.append(_tracked_loading_id)

        # Only the auto_map fallback can reach the Hub; skip the guard's probe otherwise.
        _requires_trc = False
        if _active:
            _known = _stored_trust_remote_code(model_info, inference_config)
            if _known is not None:
                _requires_trc = _known
            else:
                _requires_trc = await asyncio.get_running_loop().run_in_executor(
                    _STATUS_PROBE_EXECUTOR,
                    functools.partial(
                        _offline_guarded, [_active], _auto_map_trust_remote_code, _active
                    ),
                )

        return InferenceStatusResponse(
            engine = model_info.get("engine", "auto"),
            engine_parallelism = model_info.get("engine_parallelism", "tensor"),
            engine_precision = model_info.get("engine_precision", "auto"),
            **_managed_engine_launch_fields(model_info),
            gpu_ids = model_info.get("gpu_ids"),
            tensor_parallel = bool(model_info.get("tensor_parallel", False)),
            active_model = _active,
            model_identifier = _active,
            is_vision = is_vision,
            is_gguf = False,
            is_local_model = bool(_active and is_local_path(_active)),
            is_audio = is_audio,
            audio_type = audio_type,
            has_audio_input = has_audio_input,
            has_video_input = has_video_input,
            audio_family = model_info.get("audio_family"),
            audio_options = model_info.get("audio_options"),
            audio_workflows = model_info.get("audio_workflows"),
            audio_options_by_workflow = model_info.get("audio_options_by_workflow"),
            audio_workflow_tasks = model_info.get("audio_workflow_tasks"),
            audio_server_task = model_info.get("audio_server_task"),
            audio_convert = model_info.get("audio_convert"),
            audio_convert_route = model_info.get("audio_convert_route"),
            audio_reference_text = model_info.get("audio_reference_text"),
            audio_required_inputs = model_info.get("audio_required_inputs"),
            audio_request_inputs = model_info.get("audio_request_inputs"),
            audio_device_fallback = model_info.get("audio_device_fallback"),
            audio_music = model_info.get("audio_music"),
            gguf_variant = model_info.get("gguf_variant"),
            is_mlx = bool(model_info.get("is_mlx", False)),
            mlx_kv_quant = model_info.get("mlx_kv_quant"),
            mlx_kv_quant_requested = model_info.get("mlx_kv_quant_requested"),
            **_unsloth_serving_fields(model_info),
            mlx_kv_bits = model_info.get("mlx_kv_bits"),
            mlx_kv_bits_requested = model_info.get("mlx_kv_bits_requested"),
            mlx_kv_quant_eligibility = model_info.get("mlx_kv_quant_eligibility"),
            mlx_kv_quant_reason = model_info.get("mlx_kv_quant_reason"),
            mlx_kv_quant_note = model_info.get("mlx_kv_quant_note"),
            mlx_int8_prefill = model_info.get("mlx_int8_prefill"),
            mlx_int8_prefill_requested = model_info.get("mlx_int8_prefill_requested"),
            mlx_int8_prefill_reason = model_info.get("mlx_int8_prefill_reason"),
            mlx_offload = model_info.get("mlx_offload"),
            memory_warning = _mlx_offload_warning(model_info),
            chat_template_override = model_info.get("chat_template_override_requested"),
            chat_template_override_reason = model_info.get("chat_template_override_reason"),
            loading = _loading_models,
            loaded = _loaded,
            inference = inference_config,
            requires_trust_remote_code = _requires_trc,
            supports_reasoning = _sf_flags["supports_reasoning"],
            reasoning_style = _sf_flags["reasoning_style"],
            reasoning_effort_levels = _sf_flags.get("reasoning_effort_levels", []),
            reasoning_always_on = _sf_flags["reasoning_always_on"],
            supports_preserve_thinking = _sf_flags["supports_preserve_thinking"],
            preserve_thinking_default = _sf_flags.get("preserve_thinking_default", False),
            supports_tools = _sf_flags["supports_tools"],
            context_length = _positive_int_or_none(model_info.get("context_length")),
            native_context_length = _positive_int_or_none(model_info.get("native_context_length")),
            max_context_length = _positive_int_or_none(model_info.get("max_context_length")),
            mlx_context_budget = model_info.get("mlx_context_budget"),
            # 0 means size it yourself, None means none recorded; read requested_context_length or max_seq_length_requested, which non-GGUF loads stamp.
            requested_context_length = _nonnegative_int_or_none(
                model_info.get("requested_context_length")
                if model_info.get("requested_context_length") is not None
                else model_info.get("max_seq_length_requested")
            ),
            load_in_4bit = model_info.get("load_in_4bit_requested"),
            requested_gpu_ids = model_info.get("gpu_ids_requested"),
            chat_template = chat_template,
            llama_cpp_supports_mtp = _supports_mtp,
            llama_cpp_prebuilt_stale = _stale,
            llama_cpp_installed_tag = _installed_tag,
            llama_cpp_latest_tag = _latest_tag,
        )

    except Exception as e:
        logger.error(f"Error getting status: {e}", exc_info = True)
        raise HTTPException(status_code = 500, detail = "Failed to get status")


_load_progress_lock = threading.Lock()
_last_load_progress_step = -1


def _log_load_progress_step(fraction, phase):
    """One inference_load_progress line per 10% step, so a model load shows
    progress without a line per poll. Reset per load by _reset_load_progress_step."""
    global _last_load_progress_step
    step = int(max(0.0, min(float(fraction), 1.0)) * 10)
    with _load_progress_lock:
        prev = _last_load_progress_step
        if step == prev:
            return
        _last_load_progress_step = step
        if step < prev:
            return  # load regressed/restarted mid-poll; resync without logging
    logger.info("inference_load_progress", phase = phase or "", percent = step * 10)


def _reset_load_progress_step():
    """Arm the throttle for a new load so its first sampled step always logs,
    even a cached load that already reports fraction=1.0 on the first poll."""
    global _last_load_progress_step
    with _load_progress_lock:
        _last_load_progress_step = -1


@router.get("/load-progress", response_model = LoadProgressResponse)
async def get_load_progress(current_subject: str = Depends(get_current_subject)):
    """
    Return the active GGUF load's mmap/upload progress.

    During the warmup window after a GGUF download -- when llama-server pages
    ~tens-to-hundreds of GB of shards into the page cache before pushing layers
    to VRAM -- ``/api/inference/status`` only shows a generic spinner. This
    exposes sampled progress so the UI can render a real bar plus rate/ETA.

    Returns an empty payload (``phase=null, bytes=0``) when no load is in
    flight. The frontend should stop polling once ``phase`` becomes ``ready``.
    """
    loading = model_slots.visible_loading()
    if loading is None and account_access.resident_hidden("chat"):
        return account_access.hidden_resident_response()
    try:
        backend = loading[0].orchestrator if loading else _peek_inference_backend()
        managed = getattr(backend, "_managed_engine", None)
        if managed is not None and backend.loading_models:
            return LoadProgressResponse(phase = managed.phase)
        llama_backend = loading[0].llama if loading else get_llama_cpp_backend()
        progress = llama_backend.load_progress()
        if progress is None:
            return LoadProgressResponse()
        resp = LoadProgressResponse(**progress)
        _log_load_progress_step(resp.fraction, resp.phase)
        return resp
    except Exception as e:
        logger.warning(f"Error sampling load progress: {e}")
        return LoadProgressResponse()


# =====================================================================

# Audio (TTS) Generation  (/audio/generate)
# =====================================================================

_TRANSFORMERS_TTS_AUDIO_TYPES = frozenset(
    (
        "snac",
        "csm",
        "bicodec",
        "dac",
        "higgs_tts2",
        "moss_tts_local",
        "moss_tts_nano",
        "higgs_tts3",
        "minimax_music3",
        "audiocpp_tts",
        "audiocpp_music",
    )
)
# NativeAudioBackend._context_length ignores the requested window for these.
_CONTEXT_OVERRIDE_IGNORED_AUDIO_TYPES = frozenset(("moss_tts_local", "moss_tts_nano"))
# inference.py: load_model raises max_seq_length <= 0 to this before loading.
_STANDARD_LOAD_DEFAULT_CONTEXT = 2048
_MINIMAX_NEEDS_DESCRIPTION = "MiniMax Music 3 requires a music description in addition to lyrics."


def _audio_cpp_music_request_problem(
    family: Optional[str], lyrics: Optional[str], description: Optional[str]
) -> Optional[str]:
    """Checked on the route so a family's missing required field is a 400 naming it, not a worker 500."""
    if family == "minimax_music3" and not str(lyrics or "").strip():
        return "MiniMax Music 3 needs lyrics."
    if family == "yue2" and not str(description or "").strip():
        return "YuE2 needs a style description."
    if family == "heartmula":
        if not str(lyrics or "").strip() or not str(description or "").strip():
            return "HeartMuLa needs lyrics and a description of the style."
    return None


def _audio_model_label(model_name: Optional[str]) -> str:
    """``audio-cpp/audio.cpp-gguf/Maya1-GGUF`` -> ``Maya1``, for a sentence naming the model."""
    label = str(model_name or "").rstrip("/").rsplit("/", 1)[-1]
    label = re.sub(r"[-_.]gguf$", "", label, flags = re.IGNORECASE)
    return label or "This model"


def _audio_request_problem(
    model_info: dict,
    model_name: Optional[str],
    audio_type: Optional[str],
    payload: ChatCompletionRequest,
    run_inputs: Optional[dict],
) -> Optional[str]:
    """Why the loaded model cannot serve this request, in words for the user; else None."""
    workflows = model_info.get("audio_workflows")
    label = _audio_model_label(model_name)
    inputs = (run_inputs or {}).get("audio_inputs") or {}
    if (run_inputs or {}).get("workflow") == "edit":
        from core.inference import audio_edit

        # The llama.cpp direct path reports no workflows.
        if not workflows or "edit" not in workflows or not model_info.get("audio_edit"):
            return "Load a model that can edit speech."
        if not inputs.get("source"):
            return "Add a recording to edit."
        return audio_edit.request_problem(
            model_info.get("audio_edit"),
            run_inputs.get("edit"),
            str(run_inputs.get("text") or ""),
            run_inputs.get("reference_text"),
            label,
        )
    if run_inputs and run_inputs.get("workflow") == "music":
        # The model may have changed since the route checked the mode.
        if not model_info.get("audio_music"):
            return _audio_music_unavailable(label)
        return None
    converting = bool(run_inputs) and run_inputs.get("workflow") == "convert"
    cloning = (
        bool(run_inputs)
        and not converting
        and (run_inputs.get("workflow") == "clone" or bool(inputs))
    )
    if converting:
        problem = _audio_convert_problem(model_info, label, run_inputs)
        if problem:
            return problem
    elif cloning:
        if not workflows or "clone" not in workflows:
            return "Load a model that can clone a voice."
        if not inputs.get("reference"):
            return "Add a reference clip to clone."
        rules = model_info.get("audio_clone") or {}
        if inputs.get("emotion") and not rules.get("emotion_audio"):
            return f"{label} does not take an emotion clip."
        if (
            rules.get("reference_text") == "required"
            and not str((run_inputs or {}).get("reference_text") or "").strip()
        ):
            from core.inference.audio_cpp_models import option_matches
            if not option_matches(rules.get("reference_text_waived") or [], payload.audio_options):
                return "Type what's said in the reference clip."
    elif (
        workflows is not None
        and audio_type == "audiocpp_tts"
        and "speak" not in workflows
        and "clone" in workflows
    ):
        return f"{label} speaks in a voice cloned from a recording. Open Clone and add one."
    elif (
        workflows is not None
        and audio_type == "audiocpp_tts"
        and "speak" not in workflows
        and "convert" in workflows
    ):
        return f"{label} converts recordings. Open Convert and add one."
    if (
        "instruct" in (model_info.get("audio_required_inputs") or [])
        and not str(payload.audio_instructions or "").strip()
    ):
        return f"{label} needs a voice description."
    return None


def _audio_convert_problem(model_info: dict, label: str, run_inputs: dict) -> Optional[str]:
    caps = model_info.get("audio_convert")
    if "convert" not in (model_info.get("audio_workflows") or []) or not caps:
        return "Load a model that can convert a voice."
    given = run_inputs.get("convert_inputs") or ()
    if "source" not in given:
        return "Add the recording to convert."
    builtin = caps.get("target") == "builtin"
    if builtin and "target" in given:
        return f"{label} converts to its built-in voices; pick one under Built-in."
    if not builtin and "target" not in given:
        return "Add the target voice."
    params = run_inputs.get("convert") or {}
    mode = params.get("mode") or "speech"
    if mode not in (caps.get("modes") or []):
        return f"{label} does not convert {mode}."
    if (
        caps.get("style")
        and params.get("style") == "target"
        and mode == "speech"
        and not str(params.get("source_text") or "").strip()
    ):
        return "Type what's said in the recording, or press Transcribe."
    return None


def _apply_builtin_voice(payload, voice: Optional[str], options) -> None:
    """Send a requested built-in speaker as the ``voice`` option when the loaded model lists it
    and the request set none."""
    speakers = next((o.get("values") for o in options or () if o.get("name") == "voice"), None)
    if voice in (speakers or ()) and "voice" not in (payload.audio_options or {}):
        payload.audio_options = {**(payload.audio_options or {}), "voice": voice}


async def _generate_tts_wav(
    text: str,
    payload: ChatCompletionRequest,
    request: Request,
    current_subject: str,
    *,
    speech_api_default_max_tokens: bool = False,
    requested_model: str = _RELOAD_ONLY_MODEL,
    run_inputs: Optional[dict] = None,
    stats_holder: Optional[dict] = None,
    voice: Optional[str] = None,
) -> tuple[bytes, int, str, Optional[str]]:
    """Shared core of the three audio generation routes; a named target is budgeted after preflight."""
    # A named target must be budgeted against its own context after preflight.
    if requested_model == _RELOAD_ONLY_MODEL:
        _raise_if_prompt_leaves_no_speech_budget(text)
    workflow = (run_inputs or {}).get("workflow")
    if workflow == "speak" and (run_inputs or {}).get("audio_inputs"):
        # Speaking in a saved voice is cloning, as _audio_request_problem reads it.
        workflow = "clone"
    await _maybe_auto_switch_model(
        requested_model,
        request,
        current_subject,
        claim_resident = False,
        require_speech = True,
        require_audio_workflow = workflow,
        speech_budget = (
            None
            if requested_model == _RELOAD_ONLY_MODEL
            else {
                "text": text,
                "instructions": payload.audio_instructions,
                "language": payload.audio_language,
            }
        ),
    )
    # Recheck once a context exists: before the restore, nothing loaded passes everything.
    _raise_if_prompt_leaves_no_speech_budget(text)

    # Created before the backend pick so the GGUF lambda can close over it; the registration
    # that arms it is below, once the model name is known.
    _audio_cancel = _audio_run_event()
    prompt_for_budget = text

    # Pick backend - both return (wav_bytes, sample_rate)
    audio_family = None
    model_info: dict = {}
    llama_backend = get_llama_cpp_backend()
    # GGUF TTS holds a llama-server slot with no admission lease; only the direct counter shows it.
    _direct_llama_tts = bool(llama_backend.is_loaded and getattr(llama_backend, "_is_audio", False))
    if _direct_llama_tts:
        # Advertised repo id after an auto-switch load, else a clean public id,
        # never the absolute .gguf path.
        model_name = _llama_public_model_id(llama_backend)
        audio_type = getattr(llama_backend, "_audio_type", None)
        supported_audio_types = _GGUF_TTS_AUDIO_TYPES
        _audio_model_id = getattr(llama_backend, "model_identifier", None) or model_name
        from core.inference.chat_template_helpers import tts_voice_options

        _apply_builtin_voice(payload, voice, tts_voice_options(audio_type))
        gen = lambda: llama_backend.generate_audio_response(
            text = text,
            audio_type = llama_backend._audio_type,
            temperature = payload.temperature,
            top_p = payload.top_p,
            top_k = payload.top_k,
            min_p = payload.min_p,
            max_new_tokens = _tts_max_new_tokens(
                payload,
                prompt_for_budget,
                audio_type = audio_type,
                speech_api_default_max_tokens = speech_api_default_max_tokens,
            ),
            repetition_penalty = payload.repetition_penalty,
            cancel_event = _audio_cancel,
            stats_holder = stats_holder,
            audio_options = payload.audio_options,
        )
    else:
        backend = await asyncio.to_thread(get_inference_backend)
        if not backend.active_model_name:
            raise HTTPException(status_code = 400, detail = "No model loaded.")
        model_info = backend.models.get(backend.active_model_name, {})
        if not model_info.get("is_audio"):
            raise HTTPException(status_code = 400, detail = "Active model is not an audio model.")
        model_name = _orchestrator_public_model_id(backend)
        audio_type = model_info.get("audio_type")
        audio_family = model_info.get("audio_family")
        supported_audio_types = _TRANSFORMERS_TTS_AUDIO_TYPES
        _apply_builtin_voice(payload, voice, model_info.get("audio_options"))
        _audio_model_id = getattr(backend, "active_model_name", None) or model_name
        gen = lambda: backend.generate_audio_response(
            text = text,
            temperature = payload.temperature,
            top_p = payload.top_p,
            top_k = payload.top_k,
            min_p = payload.min_p,
            max_new_tokens = _tts_max_new_tokens(
                payload,
                prompt_for_budget,
                audio_type = audio_type,
                speech_api_default_max_tokens = speech_api_default_max_tokens,
            ),
            repetition_penalty = payload.repetition_penalty,
            use_adapter = payload.use_adapter,
            cancel_event = _audio_cancel,
            instructions = payload.audio_instructions,
            language = payload.audio_language,
            seed = payload.seed,
            **({"audio_options": payload.audio_options} if payload.audio_options else {}),
            **{
                key: value
                for key, value in (run_inputs or {}).items()
                if key
                in (
                    "workflow",
                    "audio_inputs",
                    "reference_text",
                    "speed",
                    "convert",
                    "edit",
                    "music",
                    "output_dir",
                )
                and value is not None
            },
            stats_holder = stats_holder,
        )

    if audio_type == "audiocpp_sep":
        raise HTTPException(
            status_code = 400,
            detail = f"{_audio_model_label(model_name)} separates audio into stems. Open Audio, then Separate.",
        )
    if audio_type not in supported_audio_types:
        raise HTTPException(
            status_code = 400,
            detail = f"Active model does not support text-to-speech (audio_type={audio_type or 'unknown'}).",
        )
    _request_problem = _audio_request_problem(
        model_info, model_name, audio_type, payload, run_inputs
    )
    if _request_problem:
        raise HTTPException(status_code = 400, detail = _request_problem)
    _prepare_audio_inputs = (run_inputs or {}).get("prepare_audio_inputs")
    if _prepare_audio_inputs is not None:
        # The gen lambda reads run_inputs when it runs, so the prepared paths reach the worker.
        run_inputs["audio_inputs"] = await asyncio.to_thread(_prepare_audio_inputs, model_info)
    if audio_type == "minimax_music3" and not str(payload.audio_instructions or "").strip():
        raise HTTPException(status_code = 400, detail = _MINIMAX_NEEDS_DESCRIPTION)
    if audio_type == "audiocpp_music" and (run_inputs or {}).get("workflow") != "music":
        _music_request_problem = _audio_cpp_music_request_problem(
            audio_family, text, payload.audio_instructions
        )
        if _music_request_problem:
            raise HTTPException(status_code = 400, detail = _music_request_problem)
    if audio_type in _EXTRA_PROMPT_FIELD_AUDIO_TYPES:
        prompt_for_budget = _native_tts_prompt_for_budget(
            text,
            audio_type,
            payload.audio_instructions,
            payload.audio_language,
        )
        _raise_if_prompt_leaves_no_speech_budget(prompt_for_budget)

    # No claim here: middleware claims on 2xx. Fill recommended sampling and UNSLOTH_SAMPLING_* pins here so TTS gets them; gen lambdas read payload lazily.
    _fill_recommended_sampling_openai(payload, _audio_model_id)

    # TTS holds the model for the whole request, so unregistered a non-forced swap counted zero
    # generations and tore the model down mid-generation. Both GGUF and subprocess paths observe
    # the request event. An /audio/run cancel_id (POST /audio/cancel) is registered for the whole
    # run by _dispatch_audio_run; otherwise the disconnect watcher below is the cancellation source.
    with _TrackedCancel(
        _audio_cancel,
        thread_id = getattr(payload, "thread_id", None),
        model = model_name,
        kind = "audio",
    ):
        # Cancelled while the model was loading: nothing has been generated yet.
        if _audio_cancel.is_set():
            raise HTTPException(status_code = 499, detail = "Audio generation cancelled")
        # Stop in the UI aborts the fetch and nothing more, and this route has no cancel id to
        # address, so without watching the disconnect llama-server kept generating for the rest
        # of the request timeout after the chat had already reported it stopped.
        _audio_watcher = asyncio.create_task(_await_disconnect_then_cancel(request, _audio_cancel))
        try:
            with _direct_llama_request(_direct_llama_tts):
                wav_bytes, sample_rate = await asyncio.to_thread(gen)
        except Exception as e:
            # An idle auto-unload cancels through the backend without setting this route's event.
            if _audio_cancel.is_set() or isinstance(e, AudioGenerationCancelledError):
                raise HTTPException(status_code = 499, detail = "Audio generation cancelled")
            from core.inference.audio_cpp_failures import failure_of

            if (failure := failure_of(e)) is not None:
                logger.warning("Audio generation failed (%s): %s", failure.code, e)
                raise HTTPException(status_code = failure.status, detail = failure.detail())
            # Missing capability, not a failure: no retry helps, and the message
            # carries no path or user input, so send it as written.
            if isinstance(e, AudioBackendUnsupportedError):
                logger.info("Audio generation unsupported on this backend: %s", e.detail)
                raise HTTPException(status_code = 501, detail = e.message)
            if isinstance(e, AudioRuntimeError):
                status_code, detail = audio_runtime_http_error(e)
                logger.warning("Audio generation refused by the runtime: %s", e)
                raise HTTPException(status_code = status_code, detail = detail)
            if audio_type == "minimax_music3" and _MINIMAX_PROMPT_OVERFLOW.fullmatch(str(e)):
                raise HTTPException(status_code = 400, detail = str(e))
            logger.error(f"Audio generation error: {e}", exc_info = True)
            raise HTTPException(status_code = 500, detail = safe_error_detail(e))
        finally:
            await _stop_local_disconnect_cancel_watcher(_audio_watcher)

    return wav_bytes, sample_rate, model_name, audio_type


def _wav_duration_seconds(wav_bytes: bytes, sample_rate: int) -> float:
    """Duration of an in-memory WAV, from its own header when readable."""
    import io
    import wave

    try:
        with wave.open(io.BytesIO(wav_bytes)) as wav:
            rate = wav.getframerate() or sample_rate
            return round(wav.getnframes() / rate, 3) if rate else 0.0
    except Exception:  # noqa: BLE001 - fall back to the 16-bit mono pcm the codecs emit
        payload_bytes = max(0, len(wav_bytes) - 44)
        return round(payload_bytes / (2 * sample_rate), 3) if sample_rate else 0.0


def _persist_tts_clip(
    wav_bytes: bytes,
    sample_rate: int,
    text: str,
    model_name: str,
    audio_type: Optional[str],
    extra_meta: Optional[dict] = None,
    workflow: Optional[str] = None,
    source_wav: Optional[str] = None,
) -> Optional[dict[str, Any]]:
    """Best-effort gallery save: persistence never fails the request that produced
    the audio. Blocking, so callers run it off the event loop."""
    from core.inference import audio_gallery
    from core.inference.audio_workflows import workflow_for_audio_type

    meta = {
        "prompt": text,
        "model": model_name,
        "audio_type": audio_type or "unknown",
        "workflow": workflow or workflow_for_audio_type(audio_type),
        "sample_rate": sample_rate,
        "duration_s": _wav_duration_seconds(wav_bytes, sample_rate),
        "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
    }
    meta.update({k: v for k, v in (extra_meta or {}).items() if v is not None})
    try:
        if source_wav is not None:
            return audio_gallery.save(wav_bytes, meta, Path(source_wav))
        return audio_gallery.save(wav_bytes, meta)
    except Exception as exc:  # noqa: BLE001 - log and serve the audio anyway
        logger.warning("audio_gallery.persist_failed: %s", exc)
        return None


@studio_router.post("/audio/download-plan", response_model = DiffusionDownloadPlanResponse)
async def audio_download_plan(
    request: LoadRequest, current_subject: str = Depends(get_current_subject)
):
    """Stage native-audio checkpoints and companion codecs through Download Manager."""
    if account_access.managed_account():
        request = request.model_copy(
            update = {"hf_token": account_access.account_hf_token(request.hf_token)}
        )
    if account_access.managed_account():
        await asyncio.to_thread(account_access.require_model_access, request.model_path)
    from core.inference.native_audio import native_audio_download_plan
    from utils.native_path_leases import redact_native_paths

    try:
        plan = await asyncio.to_thread(
            native_audio_download_plan,
            request.model_path,
            request.hf_token,
        )
        return DiffusionDownloadPlanResponse(**plan)
    except (ValueError, FileNotFoundError) as exc:
        raise HTTPException(status_code = 400, detail = redact_native_paths(str(exc))) from exc
    except Exception as exc:  # noqa: BLE001 - Hub/API failures become a useful picker error
        logger.warning("audio.download_plan_failed: %s", exc)
        raise HTTPException(
            status_code = 502,
            detail = redact_native_paths(
                f"Could not prepare the audio model download: {safe_error_detail(exc)}"
            ),
        ) from exc


@router.post("/audio/generate")
async def generate_audio(
    payload: AudioGenerateRequest,
    request: Request,
    current_subject: str = Depends(get_current_subject),
):
    """Generate audio (TTS) from the latest user message, as base64 WAV.
    Works with both GGUF (llama-server) and Unsloth/transformers backends."""
    import base64

    # Refuse unvoiceable parts as the completion does: _extract_content_parts keeps only text.
    _reject_unsupported_content_parts(payload)
    # Also the field: /chat/completions may already have lifted the part into audio_base64.
    if _messages_have_input_audio(payload.messages) or getattr(payload, "audio_base64", None):
        _raise_unsupported_openai_parameter(
            "messages",
            "Audio input is not supported here; this route speaks the message text.",
        )
    # Now a known tag, so the guard above misses it: the clip would be dropped and only text spoken.
    if _request_has_video(payload):
        _raise_unsupported_openai_parameter(
            "messages",
            "Video input is not supported here; this route speaks the message text.",
        )

    # Extract text from the last user message
    _, chat_messages, _ = await _extract_content_parts_async(payload.messages)
    if not chat_messages:
        raise HTTPException(status_code = 400, detail = "No messages provided.")
    last_user_msg = next((m for m in reversed(chat_messages) if m["role"] == "user"), None)
    if not last_user_msg:
        raise HTTPException(status_code = 400, detail = "No user message found.")
    text = last_user_msg["content"]
    # /chat/completions hands its own request here: no saved voice, and the clip is kept.
    voice_id = payload.voice_id if isinstance(payload, AudioGenerateRequest) else None
    persist = payload.persist if isinstance(payload, AudioGenerateRequest) else True

    run = None
    if voice_id:
        from fastapi.exceptions import RequestValidationError
        from pydantic import ValidationError

        # Built before the monitor opens a row, so a bad request records no failure.
        try:
            run = AudioRunRequest(
                workflow = "speak",
                text = text,
                language = payload.audio_language,
                instructions = payload.audio_instructions,
                inputs = AudioRunInputs(reference = AudioSourceRef(voice_id = voice_id)),
                options = payload.audio_options,
                seed = payload.seed,
                max_tokens = _effective_max_tokens(payload),
            )
        except ValidationError as exc:
            raise RequestValidationError(exc.errors()) from None

    tts_stats: dict = {}
    tts_kwargs = {
        # ``or`` like /v1/audio/speech: an explicitly empty model is accepted by the
        # request model, and without this it stops the hook at its falsey check before
        # the idle-stash restore, failing a request the sibling route serves.
        "requested_model": _switch_model_for_payload(payload) or _RELOAD_ONLY_MODEL,
        "stats_holder": tts_stats,
    }

    async def generate():
        if run is not None:
            return await _speak(run, request, current_subject, persist = persist, **tts_kwargs)
        wav_bytes, sample_rate, model_name, audio_type = await _generate_tts_wav(
            text, payload, request, current_subject, **tts_kwargs
        )
        record = None
        if persist:
            seed = _audio_stats(tts_stats).get("seed")
            meta = {"settings": {"seed": seed}} if seed is not None else None
            record = await asyncio.to_thread(
                _persist_tts_clip, wav_bytes, sample_rate, text, model_name, audio_type, meta
            )
        return record, wav_bytes, sample_rate, model_name

    # Chat completions monitors the turns it hands here, and the chat's read-aloud is no API traffic.
    if getattr(getattr(request, "url", None), "path", "").rstrip("/") != "/v1/audio/generate":
        persisted_clip, wav_bytes, sample_rate, model_name = await generate()
    else:
        async with _monitored_media_request(
            request,
            model = public_model_id(payload.model) or payload.model,
            prompt = text,
            subject = current_subject,
        ) as monitor_id:
            persisted_clip, wav_bytes, sample_rate, model_name = await generate()
            api_monitor.relabel(monitor_id, model_name)
    truncated = bool((tts_stats.get("stats") or {}).get("truncated"))
    stats = _audio_stats(tts_stats)

    audio_b64 = base64.b64encode(wav_bytes).decode("ascii")
    return JSONResponse(
        content = {
            "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
            "object": "chat.completion.audio",
            "model": model_name,
            "clip_id": persisted_clip.get("id") if persisted_clip else None,
            "seed": stats.get("seed"),
            "ignored_options": list(stats.get("ignored_options") or []),
            "audio": {"data": audio_b64, "format": "wav", "sample_rate": sample_rate},
            "choices": [
                {
                    "index": 0,
                    "message": {
                        "role": "assistant",
                        "content": text,
                    },
                    "finish_reason": "length" if truncated else "stop",
                }
            ],
        }
    )


def _audio_source_error(exc) -> HTTPException:
    return HTTPException(status_code = exc.status, detail = exc.detail)


def _v1_url(request: Request, url: str) -> str:
    """A Studio file URL on the mount the client called, so a /v1 client needs only that base URL."""
    prefix = "/api/inference/"
    if request.url.path.startswith("/v1/") and url.startswith(prefix):
        return "/v1/" + url[len(prefix) :]
    return url


CONVERT_EXPIRED_DETAIL = {
    "source": "This recording expired. Add it again.",
    "target": "This target voice expired. Add it again.",
}


def _convert_role_error(exc, role: str):
    from core.inference.audio_inputs import AudioInputError
    if exc.status == 404 and exc.detail == "This reference expired. Add it again.":
        return AudioInputError(404, CONVERT_EXPIRED_DETAIL[role])
    return exc


def _audio_stats(holder: dict) -> dict[str, Any]:
    stats = holder.get("stats")
    return stats if isinstance(stats, dict) else {}


def _audio_run_settings(
    body: AudioRunRequest,
    reference_text_used: bool,
    seed: Optional[int] = None,
) -> dict[str, Any]:
    """The run's recipe for history: scalar options only, and the seed the run used."""
    options = {
        str(name): value
        for name, value in (body.options or {}).items()
        if isinstance(value, (bool, int, float)) or (isinstance(value, str) and len(value) <= 4000)
    }
    return {
        "language": body.language,
        "instructions": body.instructions,
        "options": options,
        "reference_text_used": reference_text_used,
        "speed": body.speed,
        "seed": seed,
    }


def _audio_edit_settings(body: AudioRunRequest) -> dict[str, Any]:
    """An edit's recipe for history; never a file or server path."""
    from core.inference import audio_edit

    edit = body.edit.model_dump(exclude_none = True) if body.edit is not None else {}
    settings: dict[str, Any] = {
        "mode": edit.get("mode", "words"),
        "changes": audio_edit.change_count(edit),
        "original_text": (body.inputs.reference_text or "").strip() or None,
        "options": _audio_run_settings(body, False)["options"],
    }
    if edit.get("mode") == "delivery":
        for name in ("speed", "pitch_steps"):
            if edit.get(name) is not None:
                settings[name] = edit[name]
    return settings


def _audio_run_clip(record: dict[str, Any], role: str = "output") -> dict[str, Any]:
    return {
        "role": role,
        **{k: record[k] for k in ("id", "url", "sample_rate", "duration_s", "workflow")},
        "seed": (record.get("settings") or {}).get("seed"),
        "voice_id": record.get("voice_id"),
        "source_clip_id": record.get("source_clip_id"),
    }


def _audio_run_response(
    record: Optional[dict[str, Any]],
    wav_bytes: bytes,
    sample_rate: int,
    model_name: str,
    sources: list[dict[str, Any]] = (),
    stats: Optional[dict] = None,
) -> AudioRunResponse:
    """The clips a run made; the WAV inline when history could not keep it."""
    import base64

    ignored = list((stats or {}).get("ignored_options") or [])
    if record is None:
        audio = {"data": base64.b64encode(wav_bytes).decode("ascii"), "sample_rate": sample_rate}
        audio["seed"] = (stats or {}).get("seed")
        return AudioRunResponse(
            clips = list(sources), model = model_name, audio = audio, ignored_options = ignored
        )
    return AudioRunResponse(
        clips = [_audio_run_clip(record), *sources], model = model_name, ignored_options = ignored
    )


async def _run_audio_edit(
    body: AudioRunRequest, request: Request, current_subject: str
) -> AudioRunResponse:
    """Edit speech on a recording from the caller's account, prepared as 24 kHz mono. Over 30 s is
    refused, never cut; an uploaded recording is kept in history as the run's source."""
    from core.inference import audio_edit, audio_inputs

    if any(
        name in body.model_fields_set and getattr(body, name) not in (None, False, 1)
        for name in _MUSIC_ONLY_FIELDS
        if name != "edit"
    ):
        raise HTTPException(
            status_code = 400,
            detail = "A music mode, lyrics and variations apply to Music only.",
        )
    source_ref = body.inputs.source
    if source_ref is None:
        raise HTTPException(status_code = 400, detail = "Add a recording to edit.")
    if source_ref.voice_id:
        raise HTTPException(status_code = 400, detail = "Pick a recording or a history clip to edit.")
    ref = source_ref.model_dump(exclude_none = True)
    limit = audio_edit.EDIT_SOURCE_MAX_SECONDS + 0.05

    def prepare():
        source = audio_inputs.resolve_source(ref)
        seconds = audio_edit.wav_seconds(source.path)
        if seconds is not None and seconds > limit:
            raise audio_inputs.AudioInputError(400, audio_edit.TOO_LONG)
        path = audio_inputs.prepared_path(source, audio_inputs.REFERENCE_RATE)
        if seconds is None and (audio_edit.wav_seconds(path) or 0.0) > limit:
            raise audio_inputs.AudioInputError(400, audio_edit.TOO_LONG)
        return source, path

    try:
        source, source_path = await asyncio.to_thread(prepare)
    except audio_inputs.AudioInputError as exc:
        raise _audio_source_error(exc) from None
    reference_text = (body.inputs.reference_text or "").strip() or None
    edit = body.edit.model_dump(exclude_none = True) if body.edit is not None else {}
    payload = ChatCompletionRequest(
        messages = [{"role": "user", "content": body.text}],
        max_tokens = body.max_tokens,
        audio_options = body.options,
        seed = body.seed,
    )
    stats: dict = {}
    wav_bytes, sample_rate, model_name, audio_type = await _generate_tts_wav(
        body.text,
        payload,
        request,
        current_subject,
        run_inputs = {
            "workflow": "edit",
            "audio_inputs": {"source": str(source_path)},
            "reference_text": reference_text,
            "edit": edit,
            # For the request check; the worker gets the text as the prompt.
            "text": body.text,
        },
        requested_model = body.model or _RELOAD_ONLY_MODEL,
        stats_holder = stats,
    )

    def keep() -> tuple[Optional[dict[str, Any]], Optional[dict[str, Any]]]:
        # Under the cancel cleanup's lock, so a cancelled Edit of the same recording cannot remove
        # the source between this run picking it and saving the output that plays it.
        with _EDIT_SOURCE_LOCK:
            kept = None
            try:
                created = _AUDIO_RUN_CREATED.get()
                kept = audio_edit.save_source_clip(source, source_path, reference_text, created)
            except Exception as exc:  # noqa: BLE001 - the edit is served even when its source is not kept
                logger.warning("audio_edit.source_save_failed: %s", exc)
            if kept is not None:
                source_clip_id = kept["id"]
            else:
                source_clip_id = source.id if source.kind == "clip" else None
            extra_meta: dict[str, Any] = {
                "role": "output",
                "source_clip_id": source_clip_id,
                "reference_name": source.name,
                "settings": _audio_edit_settings(body),
            }
            output = _persist_tts_clip(
                wav_bytes, sample_rate, body.text, model_name, audio_type, extra_meta, "edit"
            )
            return kept, output

    source_record, record = await asyncio.to_thread(keep)
    sources = [_audio_run_clip(source_record, "source")] if source_record is not None else []
    return _audio_run_response(
        record, wav_bytes, sample_rate, model_name, sources, _audio_stats(stats)
    )


_REPAINT_BEYOND_END_S = 30.0
_MUSIC_ONLY_FIELDS = ("mode", "lyrics", "instrumental", "duration_s", "variations", "edit")
_MUSIC_MODE_NAMES = {"song": "songs", "sfx": "sound effects", "edit": "edits"}


def _audio_music_unavailable(label: str) -> str:
    return f"{label} does not work in the Music studio. Load an audio.cpp music model."


def _music_mode_rules(rules: Optional[dict], mode: Optional[str]) -> Optional[dict]:
    for entry in (rules or {}).get("modes") or []:
        if isinstance(entry, dict) and entry.get("id") == mode:
            return entry
    return None


def _audio_music_body_problem(
    body: AudioRunRequest, rules: Optional[dict], label: str
) -> Optional[str]:
    """User-facing reason the loaded model cannot run this request, else None."""
    if body.inputs.reference or body.inputs.emotion or body.inputs.reference_text:
        return "Music takes a clip to edit, not a voice reference. Remove the reference."
    if not rules:
        return _audio_music_unavailable(label)
    mode = _music_mode_rules(rules, body.mode)
    if mode is None:
        return f"{label} does not make {_MUSIC_MODE_NAMES.get(body.mode, body.mode)}."
    text = body.text.strip()
    if body.mode != "edit":
        if body.edit is not None or body.inputs.source is not None:
            return "A source clip and edit settings apply to Edit only."
        variations = mode.get("variations")
        if body.variations > 1 and not variations:
            return f"{label} makes one take at a time. Set variations to 1."
        if variations and body.variations > int(variations.get("max") or 1):
            return f"{label} makes at most {variations.get('max')} variations at a time."
        if body.mode == "sfx":
            return None if text else "Describe the sound to make."
        lyrics = (body.lyrics or "").strip()
        if body.instrumental and mode.get("instrumental") == "never":
            return f"{label} always sings. Turn off Instrumental and add lyrics."
        if mode.get("lyrics") == "required" and not lyrics:
            return f"{label} needs lyrics."
        if mode.get("description") == "required" and not text:
            return f"{label} needs a description of the music."
        if not text and not lyrics:
            return "Describe the music or add lyrics."
        return None
    if body.variations > 1:
        return "An edit makes one take at a time. Set variations to 1."
    source = body.inputs.source
    if source is None:
        return "Add a clip to edit."
    if source.voice_id:
        return "Edit an upload or a clip from history. Saved voices cannot be edited."
    edit = body.edit
    if edit is None:
        return "Choose what to do to the clip."
    if edit.action not in (mode.get("actions") or []):
        return f"{label} cannot {edit.action} a clip."
    if edit.action in ("repaint", "inpaint") and not edit.ranges:
        return "Select the part of the clip to change."
    if edit.action in ("extend", "cover", "continue", "restyle") and edit.ranges:
        return f"{edit.action.capitalize()} changes the whole clip; clear the selected parts."
    if len(edit.ranges) > int(mode.get("max_ranges") or 0):
        return f"{label} changes at most {mode.get('max_ranges')} part(s) of a clip at a time."
    if edit.action == "extend" and not edit.extend_s:
        return "Choose how many seconds to add."
    if not text:
        return "Describe the change."
    return None


def _audio_music_source_problem(
    body: AudioRunRequest, rules: dict, source_s: float, song_max: float
) -> Optional[str]:
    mode = _music_mode_rules(rules, "edit") or {}
    max_source = float(mode.get("max_source_s") or 240.0)
    if source_s > max_source + 0.05:
        return f"Edit clips up to {_music_length_words(max_source)}. Trim it first."
    edit = body.edit
    for r in edit.ranges:
        if r.start_s >= source_s:
            return "A selected part starts after the clip ends. Select inside the clip."
        if edit.action == "repaint" and r.end_s > song_max:
            return f"A repaint can reach at most {_music_length_words(song_max)} into the song."
        # The page draws at most this much tail past the clip; extend covers longer additions.
        if edit.action == "repaint" and r.end_s > source_s + _REPAINT_BEYOND_END_S + 0.05:
            return f"A repaint can reach at most {_REPAINT_BEYOND_END_S:g} s past the end."
    if edit.action == "extend" and source_s + float(edit.extend_s or 0) > song_max + 0.05:
        return f"The extended clip would pass {_music_length_words(song_max)}. Add fewer seconds."
    return None


def _music_length_words(seconds: float) -> str:
    if seconds >= 60 and float(seconds) % 60 == 0:
        minutes = int(seconds // 60)
        return f"{minutes} minute{'s' if minutes != 1 else ''}"
    return f"{seconds:g} s"


def _audio_music_settings(
    body: AudioRunRequest,
    duration_s: Optional[float],
    seed: Optional[int],
    variation: Optional[int],
    song: Optional[dict] = None,
) -> dict[str, Any]:
    """Scalars only: never a file or server path. Records what ran: an always-instrumental model
    is instrumental and takes no lyrics, whatever the request said."""
    instrumental = lyrics = None
    if body.mode == "song":
        how = (song or {}).get("instrumental")
        instrumental = how == "always" or (body.instrumental and how != "never")
        if (song or {}).get("lyrics") != "unused":
            lyrics = body.lyrics
    settings = _audio_run_settings(body, False)
    settings.update(
        {
            "mode": body.mode,
            "variation": variation,
            "seed": seed,
            "duration_s": duration_s,
            "instrumental": instrumental,
            "lyrics": lyrics,
        }
    )
    if body.edit is not None:
        settings["edit"] = {
            "action": body.edit.action,
            "ranges": [{"start_s": r.start_s, "end_s": r.end_s} for r in body.edit.ranges],
            "strength": body.edit.strength,
            "extend_s": body.edit.extend_s,
        }
    return settings


def _read_music_outputs(run_dir: Path) -> list[tuple[bytes, int, Optional[int]]]:
    """A listed file outside ``run_dir`` is never read."""
    from core.inference.audio_task_outputs import wav_header

    try:
        manifest = json.loads((run_dir / "outputs.json").read_text(encoding = "utf-8"))
    except (OSError, ValueError):
        return []
    root = run_dir.resolve()
    outputs: list[tuple[bytes, int, Optional[int]]] = []
    for entry in manifest if isinstance(manifest, list) else []:
        if not isinstance(entry, dict) or not isinstance(entry.get("file"), str):
            continue
        path = (run_dir / entry["file"]).resolve()
        if path.parent != root or not path.is_file():
            logger.warning("audio.music: ignoring an output outside the run folder")
            continue
        data = path.read_bytes()
        try:
            rate = wav_header(data)[0]
        except Exception:  # noqa: BLE001 - not a WAV
            continue
        seed = entry.get("seed")
        outputs.append((data, rate, seed if isinstance(seed, int) else None))
    return outputs


def _clamp_note(
    applied: dict[str, Any], warnings: list[str], asked: Optional[float], used: float
) -> None:
    """Report the music length used, with a warning when it differs from the one asked for."""
    applied["duration_s"] = used
    if asked is not None and used != asked:
        warnings.append(f"duration_s {asked:g} clamped to {used:g}")


async def _run_music_workflow(
    body: AudioRunRequest, request: Request, current_subject: str
) -> AudioRunResponse:
    import base64
    import shutil

    from core.inference import audio_inputs
    from core.inference.audio_cpp_models import MUSIC_SPECS
    from core.inference.audio_cpp_music import frames_for, timeout_seconds

    await _maybe_auto_switch_model(
        body.model or _RELOAD_ONLY_MODEL,
        request,
        current_subject,
        claim_resident = False,
        require_speech = True,
        require_audio_workflow = "music",
    )
    backend = await asyncio.to_thread(get_inference_backend)
    if not backend.active_model_name:
        raise HTTPException(status_code = 400, detail = "Load a music model first.")
    model_info = backend.models.get(backend.active_model_name, {}) or {}
    label = _audio_model_label(_orchestrator_public_model_id(backend))
    rules = model_info.get("audio_music")
    problem = _audio_music_body_problem(body, rules, label)
    if problem:
        raise HTTPException(status_code = 400, detail = problem)
    family = model_info.get("audio_family")
    song = _music_mode_rules(rules, "song") or {}
    song_max = float((song.get("duration") or {}).get("max") or 240.0)

    run_dir = audio_inputs.inputs_dir() / "runs" / uuid.uuid4().hex
    try:
        source_path = None
        source = None
        seconds: Optional[float] = None
        applied: dict[str, Any] = {}
        warnings: list[str] = []
        if body.mode == "edit":
            spec = MUSIC_SPECS.get(str(family or ""))
            rate = spec.edit_rate if spec is not None else None
            if not rate:
                raise HTTPException(status_code = 400, detail = f"{label} cannot edit a clip.")
            try:
                source = await asyncio.to_thread(
                    audio_inputs.resolve_source, body.inputs.source.model_dump(exclude_none = True)
                )
                source_s = float(
                    (await asyncio.to_thread(audio_inputs.wav_info, source.path))["duration_s"]
                )
                problem = _audio_music_source_problem(body, rules, source_s, song_max)
                if problem:
                    raise HTTPException(status_code = 400, detail = problem)
                source_path = await asyncio.to_thread(
                    audio_inputs.prepared_path, source, rate, None, True
                )
            except audio_inputs.AudioInputError as exc:
                raise _audio_source_error(exc) from None
            work_s = source_s + float(body.edit.extend_s or 0.0)
            # A repaint range past the end pads the source out to it.
            work_s = max([work_s, *(r.end_s for r in body.edit.ranges)])
            if body.edit.action == "continue" and body.duration_s:
                seconds = min(song_max, float(body.duration_s))
                _clamp_note(applied, warnings, body.duration_s, seconds)
                work_s = max(work_s, seconds)
        else:
            mode = _music_mode_rules(rules, body.mode) or {}
            bounds = mode.get("duration") or {}
            low = float(bounds.get("min") or 1.0)
            high = float(bounds.get("max") or 240.0)
            wanted = body.duration_s if body.duration_s is not None else bounds.get("default")
            seconds = max(low, min(high, float(wanted if wanted is not None else low)))
            spec = MUSIC_SPECS.get(str(family or ""))
            if spec is not None and spec.self_ending_s:
                # The model ends the song itself and is sent no length.
                if body.duration_s is not None:
                    warnings.append(f"duration_s ignored: {label} sets its own length")
            else:
                _clamp_note(applied, warnings, body.duration_s, seconds)
            work_s = seconds
        variations = body.variations if body.mode != "edit" else 1
        music = {
            "mode": body.mode,
            "text": body.text,
            "lyrics": body.lyrics,
            "instrumental": body.instrumental,
            "duration_s": seconds,
            "variations": variations,
            # 0-based: the backend seeds take n with seed + n.
            "take": body.take - 1 if body.take else None,
            "edit": body.edit.model_dump() if body.edit is not None else None,
            "timeout_s": timeout_seconds(
                family, work_s, variations, model_info.get("audio_cpp_backend")
            ),
        }
        run_dir.mkdir(parents = True, exist_ok = True)
        payload = ChatCompletionRequest(
            messages = [{"role": "user", "content": body.text or body.lyrics or ""}],
            # Only scales the orchestrator's deadline.
            max_tokens = max(1, min(8192, frames_for(work_s, variations))),
            audio_options = body.options,
            seed = body.seed,
        )
        stats: dict = {}
        wav_bytes, sample_rate, model_name, audio_type = await _generate_tts_wav(
            body.text,
            payload,
            request,
            current_subject,
            run_inputs = {
                "workflow": "music",
                "audio_inputs": {"source": str(source_path)} if source_path else None,
                "music": music,
                "output_dir": str(run_dir),
            },
            stats_holder = stats,
        )
        outputs = await asyncio.to_thread(_read_music_outputs, run_dir)
    finally:
        await asyncio.to_thread(shutil.rmtree, run_dir, ignore_errors = True)
    if not outputs:
        outputs = [(wav_bytes, sample_rate, _audio_stats(stats).get("seed", body.seed))]
    ignored = list(_audio_stats(stats).get("ignored_options") or [])
    many = len(outputs) > 1 or body.take is not None
    group_id = body.group_id or (uuid.uuid4().hex if len(outputs) > 1 else None)
    role = "edit" if body.mode == "edit" else ("variation" if many else "output")
    prompt = body.text.strip() or " ".join((body.lyrics or "").split())[:200]
    clips = []
    for index, (wav, rate, seed) in enumerate(outputs):
        extra_meta: dict[str, Any] = {
            "role": role,
            "group_id": group_id,
            "settings": _audio_music_settings(
                body, seconds, seed, (body.take or index + 1) if many else None, song
            ),
        }
        if source is not None:
            extra_meta["reference_name"] = source.name
            if source.kind == "clip":
                extra_meta["source_clip_id"] = source.id
        record = await asyncio.to_thread(
            _persist_tts_clip, wav, rate, prompt, model_name, audio_type, extra_meta, "music"
        )
        if record is None:
            if not clips:
                return AudioRunResponse(
                    clips = [],
                    model = model_name,
                    audio = {
                        "data": base64.b64encode(wav).decode("ascii"),
                        "format": "wav",
                        "sample_rate": rate,
                        "seed": seed,
                    },
                    ignored_options = ignored,
                    applied = applied,
                    warnings = warnings,
                )
            continue
        clips.append(
            {
                "id": record["id"],
                "role": role,
                "url": record["url"],
                "sample_rate": record["sample_rate"],
                "duration_s": record["duration_s"],
                "workflow": record["workflow"],
                "seed": seed,
                "source_clip_id": record.get("source_clip_id"),
            }
        )
    return AudioRunResponse(
        clips = clips,
        group_id = group_id,
        model = model_name,
        ignored_options = ignored,
        applied = applied,
        warnings = warnings,
    )


async def _run_audio_convert(
    body: AudioRunRequest, request: Request, current_subject: str
) -> AudioRunResponse:
    from core.inference import audio_inputs
    from core.inference.audio_cpp_convert import (
        CONVERT_SOURCE_MAX_SECONDS,
        CONVERT_TARGET_MAX_SECONDS,
    )

    if any(
        name in body.model_fields_set and getattr(body, name) not in (None, False, 1)
        for name in _MUSIC_ONLY_FIELDS
    ):
        raise HTTPException(
            status_code = 400,
            detail = "A music mode, lyrics, variations and edits apply to Music only.",
        )
    params = body.convert.model_dump()
    refs = {"source": body.inputs.source, "target": body.inputs.target}
    if refs["source"] is None:
        raise HTTPException(status_code = 400, detail = "Add the recording to convert.")
    resolved: dict[str, Any] = {}
    for role, ref in refs.items():
        if ref is None:
            continue
        try:
            resolved[role] = await asyncio.to_thread(
                audio_inputs.resolve_source, ref.model_dump(exclude_none = True)
            )
        except audio_inputs.AudioInputError as exc:
            # Names the side so the page marks only the card that expired.
            raise _audio_source_error(_convert_role_error(exc, role)) from None
    source, target = resolved["source"], resolved.get("target")
    max_seconds = {"source": CONVERT_SOURCE_MAX_SECONDS, "target": CONVERT_TARGET_MAX_SECONDS}
    seen: dict[str, Any] = {}

    def _prepare(model_info: dict) -> dict[str, str]:
        seen["model_info"] = model_info
        rules = model_info.get("audio_convert_rules") or {}
        try:
            seen["paths"] = {
                role: str(
                    audio_inputs.prepared_path(
                        item,
                        int(rules.get(f"{role}_rate") or 16000),
                        max_seconds = max_seconds[role],
                    )
                )
                for role, item in resolved.items()
            }
        except audio_inputs.AudioInputError as exc:
            raise _audio_source_error(exc) from None
        return seen["paths"]

    source_text = (body.inputs.source_text or "").strip() or None
    payload = ChatCompletionRequest(
        messages = [{"role": "user", "content": source.name}],
        audio_options = body.options,
        seed = body.seed,
    )
    stats: dict = {}
    wav_bytes, sample_rate, model_name, audio_type = await _generate_tts_wav(
        source.name,
        payload,
        request,
        current_subject,
        run_inputs = {
            "workflow": "convert",
            "audio_inputs": None,
            "convert": {**params, "source_text": source_text},
            "convert_inputs": tuple(resolved),
            "prepare_audio_inputs": _prepare,
        },
        requested_model = body.model or _RELOAD_ONLY_MODEL,
        stats_holder = stats,
    )
    builtin = None
    if target is not None:
        target_name = target.name
    else:
        voices = ((seen.get("model_info") or {}).get("audio_convert") or {}).get("builtin_voices")
        voices = voices or [{"id": params.get("voice"), "label": "Built-in"}]
        voice = next((v for v in voices if v.get("id") == params.get("voice")), voices[0])
        builtin, target_name = voice.get("id"), voice.get("label") or voice.get("id")
    extra_meta: dict[str, Any] = {
        "role": "output",
        "source_name": source.name,
        "reference_name": target_name,
        "target_builtin": builtin,
        "settings": {
            **{key: params.get(key) for key in ("mode", "pitch", "pitch_auto", "style")},
            "options": _audio_run_settings(body, False)["options"],
        },
    }
    if source.kind == "clip":
        extra_meta["source_clip_id"] = source.id
    elif source.kind == "input":
        extra_meta["source_input_id"] = source.id
    if target is not None:
        key = {"voice": "voice_id", "clip": "target_clip_id", "input": "target_input_id"}
        if target.kind in key:
            extra_meta[key[target.kind]] = target.id
    record = await asyncio.to_thread(
        _persist_tts_clip,
        wav_bytes,
        sample_rate,
        f"{source.name} → {target_name}",
        model_name,
        audio_type,
        extra_meta,
        "convert",
        # An upload expires within a day; a history clip does not.
        (seen.get("paths") or {}).get("source") if source.kind == "input" else None,
    )
    return _audio_run_response(
        record, wav_bytes, sample_rate, model_name, stats = _audio_stats(stats)
    )


@router.post("/audio/run", response_model = AudioRunResponse)
async def run_audio_workflow(
    body: AudioRunRequest,
    request: Request,
    current_subject: str = Depends(get_current_subject),
):
    """Run one Audio page workflow (Clone, Speak in a saved voice, Edit, Convert, Music or
    Separate); clips go to history. Audio is named by id and resolved here in the caller's account;
    the worker gets a prepared copy's path, never bytes."""
    if not request.url.path.startswith("/v1/"):
        return await _dispatch_audio_run(body, request, current_subject)
    # Only API runs are monitored, like /v1/audio/speech; the Audio page's are not.
    async with _monitored_media_request(
        request,
        model = public_model_id(body.model) or body.model,
        prompt = body.text or body.workflow,
        subject = current_subject,
    ) as monitor_id:
        response = await _dispatch_audio_run(body, request, current_subject)
        api_monitor.relabel(monitor_id, response.model)
    for clip in response.clips:
        clip.url = _v1_url(request, clip.url)
    return response


# The /audio/run cancel_id, read where the run registers its cancel event.
_AUDIO_RUN_CANCEL_ID: "contextvars.ContextVar[Optional[str]]" = contextvars.ContextVar(
    "audio_run_cancel_id", default = None
)


# The event that run's cancel_id sets. It is registered before any model switch, so a cancel sent
# while a cold model loads (often longer than the 30 s a stashed cancel is kept) still stops it.
_AUDIO_RUN_CANCEL: "contextvars.ContextVar[Optional[threading.Event]]" = contextvars.ContextVar(
    "audio_run_cancel", default = None
)


# Clips a run saved that its response lists as reused sources, so a cancel can remove them too.
_AUDIO_RUN_CREATED: "contextvars.ContextVar[Optional[list[str]]]" = contextvars.ContextVar(
    "audio_run_created", default = None
)


def _audio_run_cancel_key() -> Optional[tuple[str, str]]:
    # Namespaced, so a chat cancel_id can never stop an audio run.
    cancel_id = _AUDIO_RUN_CANCEL_ID.get()
    return ("audio", cancel_id) if cancel_id else None


def _audio_run_event() -> threading.Event:
    """The current /audio/run's cancel event, or a fresh one outside a run."""
    return _AUDIO_RUN_CANCEL.get() or threading.Event()


async def _dispatch_audio_run(
    body: AudioRunRequest, request: Request, current_subject: str
) -> AudioRunResponse:
    if body.cancel_id:
        # One cancel_id names one run: a second run under a live id would be stopped by the same
        # cancel. Nothing awaits between this check and the registration below.
        with _CANCEL_LOCK:
            busy = bool(_CANCEL_REGISTRY.get(_account_cancel_key(("audio", body.cancel_id))))
        if busy:
            raise HTTPException(
                status_code = 409, detail = "Another audio run is using this cancel_id."
            )
    token = _AUDIO_RUN_CANCEL_ID.set(body.cancel_id)
    cancel = threading.Event()
    event_token = _AUDIO_RUN_CANCEL.set(cancel)
    created: list[str] = []
    created_token = _AUDIO_RUN_CREATED.set(created)
    try:
        # Registry only: each stage records itself as a generation once a model is loaded.
        with _TrackedCancel(cancel, _audio_run_cancel_key(), track_run = False):
            response = await _dispatch_audio_workflow(body, request, current_subject)
        # Unregistered now, so a later cancel finds nothing to stop. One that arrived while the
        # clips were being saved still wins: the clips this run made are removed (a source clip
        # it reused stays) and the run answers 499, as a cancel during generation would.
        if cancel.is_set():
            made = [clip.id for clip in response.clips if clip.role != "source"]
            await asyncio.to_thread(_discard_audio_clips, made, created)
            raise HTTPException(status_code = 499, detail = "Audio generation cancelled")
        return response
    finally:
        _AUDIO_RUN_CREATED.reset(created_token)
        _AUDIO_RUN_CANCEL.reset(event_token)
        _AUDIO_RUN_CANCEL_ID.reset(token)


# Held while an Edit picks or saves its source and saves its output, and while a cancel removes clips.
_EDIT_SOURCE_LOCK = threading.Lock()


def _discard_audio_clips(outputs: list[str], sources: list[str]) -> None:
    """Remove a cancelled run's outputs, then the sources it saved unless another clip, such as a
    concurrent Edit of the same recording, now plays them."""
    from core.inference import audio_gallery

    def remove(clip_id: str, cascade: bool = True) -> None:
        try:
            audio_gallery.delete(clip_id, cascade = cascade)
        except Exception as exc:  # noqa: BLE001 - remove the rest even if one delete fails
            logger.warning("audio_run.cancel_cleanup_failed: %s", exc)

    with _EDIT_SOURCE_LOCK:
        # No cascade: a reused source an earlier run kept is not this run's to remove.
        for clip_id in outputs:
            remove(clip_id, cascade = False)
        in_use = (
            audio_gallery._sources_in_use(audio_gallery.gallery_dir(), set()) if sources else ()
        )
        for clip_id in sources:
            if clip_id not in in_use:
                remove(clip_id)


async def _dispatch_audio_workflow(
    body: AudioRunRequest, request: Request, current_subject: str
) -> AudioRunResponse:
    if body.provider_id:
        return await _speak_on_connection(body, request)
    if body.workflow == "separate":
        return await _run_separation(body, request, current_subject)
    if body.workflow == "convert":
        return await _run_audio_convert(body, request, current_subject)
    if body.workflow == "edit":
        return await _run_audio_edit(body, request, current_subject)
    if body.workflow == "music":
        return await _run_music_workflow(body, request, current_subject)
    music_fields = sorted(
        name
        for name in _MUSIC_ONLY_FIELDS
        if name in body.model_fields_set and getattr(body, name) not in (None, False, 1)
    )
    if music_fields or body.inputs.source is not None:
        raise HTTPException(
            status_code = 400,
            detail = "A music mode, lyrics, variations, a source clip and edits apply to Music only.",
        )
    stats: dict = {}
    record, wav_bytes, sample_rate, model_name = await _speak(
        body,
        request,
        current_subject,
        requested_model = body.model or _RELOAD_ONLY_MODEL,
        stats_holder = stats,
    )
    return _audio_run_response(record, wav_bytes, sample_rate, model_name, [], _audio_stats(stats))


async def _speak(
    body: AudioRunRequest,
    request: Request,
    current_subject: str,
    *,
    persist: bool = True,
    **tts_kwargs,
) -> tuple[Optional[dict[str, Any]], bytes, int, str]:
    """Clone, or Speak in a saved voice, and keep the clip in history unless ``persist`` is off;
    shared by /audio/run, /audio/speech and /audio/generate. ``(record, wav_bytes, sample_rate,
    model_name)``."""
    from core.inference import audio_inputs

    if body.workflow == "clone" and body.inputs.reference is None:
        raise HTTPException(status_code = 400, detail = "Add a reference clip to clone.")
    prepared = {}
    try:
        for role in ("reference", "emotion"):
            ref = getattr(body.inputs, role)
            if ref is not None:
                prepared[role] = await asyncio.to_thread(
                    audio_inputs.prepare_reference, ref.model_dump(exclude_none = True)
                )
    except audio_inputs.AudioInputError as exc:
        raise _audio_source_error(exc) from None
    paths = {role: str(path) for role, (_source, path) in prepared.items()}
    reference_source = prepared["reference"][0] if "reference" in prepared else None
    reference_text = (body.inputs.reference_text or "").strip() or None
    # An omitted transcript falls back to the saved voice's; a sent blank one was cleared on purpose.
    if (
        body.inputs.reference_text is None
        and reference_source is not None
        and reference_source.kind == "voice"
    ):
        from core.inference import audio_voices
        voice = await asyncio.to_thread(audio_voices.get, reference_source.id)
        reference_text = ((voice or {}).get("transcript") or "").strip() or None

    payload = ChatCompletionRequest(
        messages = [{"role": "user", "content": body.text}],
        max_tokens = body.max_tokens,
        audio_instructions = body.instructions,
        audio_language = body.language,
        audio_options = body.options,
        seed = body.seed,
    )
    stats = tts_kwargs.setdefault("stats_holder", {})
    wav_bytes, sample_rate, model_name, audio_type = await _generate_tts_wav(
        body.text,
        payload,
        request,
        current_subject,
        run_inputs = {
            "workflow": body.workflow,
            "audio_inputs": paths or None,
            "reference_text": reference_text,
            "speed": body.speed,
        },
        **tts_kwargs,
    )
    if not persist:
        return None, wav_bytes, sample_rate, model_name
    extra_meta: dict[str, Any] = {
        "role": "output",
        "settings": _audio_run_settings(
            body, reference_text is not None, _audio_stats(stats).get("seed")
        ),
    }
    if reference_source is not None:
        extra_meta["reference_name"] = reference_source.name
        if reference_source.kind == "clip":
            extra_meta["source_clip_id"] = reference_source.id
        elif reference_source.kind == "voice":
            extra_meta["voice_id"] = reference_source.id
    record = await asyncio.to_thread(
        _persist_tts_clip,
        wav_bytes,
        sample_rate,
        body.text,
        model_name,
        audio_type,
        extra_meta,
        body.workflow,
    )
    return record, wav_bytes, sample_rate, model_name


# Stems in the order the Separate page lists them; ids a runtime adds follow in its own order.
_STEM_ORDER = ("vocals", "drums", "bass", "guitar", "piano", "other", "instrumental")
_SEPARATE_MAX_SECONDS = 600.0
_SEPARATE_RATE = 44100


def _separation_options(body: AudioRunRequest, family: Optional[str], label: str) -> Optional[dict]:
    """The run's separation options, checked against what the loaded family takes."""
    from core.inference.audio_cpp_models import FAMILIES

    options = body.options or {}
    if not options:
        return None
    policy = FAMILIES.get(family or "")
    if policy is None or policy.separation is None or not policy.separation.overlap_option:
        raise HTTPException(status_code = 400, detail = f"{label} has no separation options.")
    for name in options:
        if name != "num_overlap":
            raise HTTPException(status_code = 400, detail = f"Unknown option '{name}'.")
    value = options["num_overlap"]
    if isinstance(value, bool) or not isinstance(value, int) or not 1 <= value <= 8:
        raise HTTPException(
            status_code = 400, detail = "num_overlap must be a whole number from 1 to 8."
        )
    return {"num_overlap": value}


def _clock(seconds: float) -> str:
    whole = int(math.ceil(seconds))
    return f"{whole // 60}:{whole % 60:02d}"


def _probe_audio_with_av(path) -> Optional[tuple[int, float]]:
    """``(channels, seconds)`` of the first audio stream, through FFmpeg; None if unreadable."""
    try:
        import av

        from core.inference.audio_inputs import _av_open
        with _av_open(av, str(path)) as container:
            stream = container.streams.audio[0]
            if stream.duration is not None and stream.time_base is not None:
                seconds = float(stream.duration * stream.time_base)
            elif container.duration is not None:
                seconds = container.duration / 1_000_000
            else:
                return None
            return int(stream.channels), seconds
    except Exception:  # noqa: BLE001 - any failure reads as an unreadable track
        return None


def _prepare_separation_source(ref: dict[str, Any]):
    """``(source, prepared 44.1 kHz path)``, after the 10-minute cap; stereo stays stereo."""
    import wave

    from core.inference import audio_inputs

    source = audio_inputs.resolve_source(ref)
    try:
        with wave.open(str(source.path), "rb") as wav:
            channels = wav.getnchannels()
            seconds = wav.getnframes() / wav.getframerate()
    except Exception:  # noqa: BLE001 - e.g. a float stem from history, which wave cannot open
        probed = _probe_audio_with_av(source.path)
        if probed is None:
            raise audio_inputs.AudioInputError(400, "This track could not be read. Add it again.")
        channels, seconds = probed
    if seconds > _SEPARATE_MAX_SECONDS:
        raise HTTPException(
            status_code = 400,
            detail = "Separate tracks up to 10 minutes long. This one is "
            f"{_clock(seconds)}. Pick a shorter track.",
        )
    return source, audio_inputs.prepared_path(source, _SEPARATE_RATE, stereo = channels == 2)


def _stem_rank(ids: list[str]):
    runtime = {stem_id: index for index, stem_id in enumerate(ids)}
    return lambda stem_id: (
        _STEM_ORDER.index(stem_id) if stem_id in _STEM_ORDER else len(_STEM_ORDER),
        runtime[stem_id],
    )


def _checked_stems(outputs: Any, staging: Path) -> list[dict]:
    """The worker's stems, each a WAV inside ``staging``, in display order; 502 otherwise."""
    if not isinstance(outputs, list) or not outputs:
        raise HTTPException(status_code = 502, detail = NO_STEMS)
    root = staging.resolve()
    stems = []
    for output in outputs:
        try:
            path = Path(str(output["path"])).resolve()
            path.relative_to(root)
            with open(path, "rb") as f:
                riff = f.read(4) == b"RIFF"
            stem = {
                "id": str(output["id"]),
                "path": path,
                "sample_rate": int(output["sample_rate"]),
                "duration_s": float(output["duration_s"]),
            }
        except (KeyError, TypeError, ValueError, OSError):
            riff = False
        if not riff:
            logger.warning("audio.separate: the worker returned an unusable stem")
            raise HTTPException(status_code = 502, detail = NO_STEMS)
        stems.append(stem)
    rank = _stem_rank([stem["id"] for stem in stems])
    return sorted(stems, key = lambda stem: rank(stem["id"]))


def _save_stems(stems: list[dict], base_meta: dict[str, Any]) -> list[dict]:
    """Save every stem to history under one group, all or none, then prune once."""
    from core.inference import audio_gallery

    records: list[dict] = []
    try:
        for stem in stems:
            meta = {
                **base_meta,
                "sample_rate": stem["sample_rate"],
                "duration_s": stem["duration_s"],
                "role": stem["id"],
            }
            records.append(audio_gallery.save_file(stem["path"], meta, prune = False))
    except Exception:
        for record in records:
            audio_gallery.delete(record["id"])
        raise
    audio_gallery._prune_to_cap()
    return records


async def _run_separation(
    body: AudioRunRequest, request: Request, current_subject: str
) -> AudioRunResponse:
    """Split a track into stems saved as one history group; worker paths are checked to stay in
    the account's gallery and never reach the client."""
    from core.inference import audio_gallery, audio_inputs

    if body.text is not None:
        raise HTTPException(status_code = 400, detail = "Separate takes no text.")
    if any(
        name in body.model_fields_set and getattr(body, name) not in (None, False, 1)
        for name in _MUSIC_ONLY_FIELDS
    ):
        raise HTTPException(
            status_code = 400,
            detail = "A music mode, lyrics, variations and edits apply to Music only.",
        )
    inputs = body.inputs
    if inputs.reference is not None or inputs.emotion is not None or inputs.reference_text:
        raise HTTPException(status_code = 400, detail = "Separate takes only a track.")
    source_ref = inputs.source
    if source_ref is None:
        raise HTTPException(status_code = 400, detail = "Add a track to separate.")
    if source_ref.voice_id:
        raise HTTPException(status_code = 400, detail = "Pick a track to separate, not a saved voice.")
    await _maybe_auto_switch_model(
        body.model or _RELOAD_ONLY_MODEL,
        request,
        current_subject,
        claim_resident = False,
        require_audio_workflow = "separate",
    )
    backend = await asyncio.to_thread(get_inference_backend)
    model_info = (
        backend.models.get(backend.active_model_name, {}) if backend.active_model_name else {}
    )
    if "separate" not in (model_info.get("audio_workflows") or []):
        raise HTTPException(status_code = 400, detail = "Load a model that can separate audio.")
    model_name = _orchestrator_public_model_id(backend)
    options = _separation_options(
        body, model_info.get("audio_family"), _audio_model_label(model_name)
    )
    ref = source_ref.model_dump(exclude_none = True)
    try:
        source, prepared = await asyncio.to_thread(_prepare_separation_source, ref)
    except audio_inputs.AudioInputError as exc:
        if exc.status == 404 and source_ref.input_id:
            raise HTTPException(status_code = 404, detail = "This track expired. Add it again.")
        raise _audio_source_error(exc) from None

    staging = await asyncio.to_thread(
        lambda: audio_gallery.gallery_dir() / f".separate-{uuid.uuid4().hex}"
    )
    try:
        await asyncio.to_thread(staging.mkdir, parents = True)
        cancel = _audio_run_event()
        with _TrackedCancel(cancel, model = model_name, kind = "audio"):
            if cancel.is_set():
                raise HTTPException(status_code = 499, detail = "Audio generation cancelled")
            watcher = asyncio.create_task(_await_disconnect_then_cancel(request, cancel))
            try:
                outputs = await asyncio.to_thread(
                    backend.separate_audio_response, str(prepared), str(staging), options, cancel
                )
            except Exception as e:
                if cancel.is_set() or isinstance(e, AudioGenerationCancelledError):
                    raise HTTPException(status_code = 499, detail = "Audio generation cancelled")
                if isinstance(e, AudioBackendUnsupportedError):
                    raise HTTPException(status_code = 501, detail = e.message)
                from core.inference.audio_cpp_failures import failure_of

                if (failure := failure_of(e)) is not None:
                    logger.warning("Audio separation failed: %s", failure.code)
                    raise HTTPException(status_code = failure.status, detail = failure.detail())
                if isinstance(e, AudioRuntimeError):
                    status_code, detail = audio_runtime_http_error(e)
                    logger.warning("Audio separation refused by the runtime: %s", e)
                    raise HTTPException(status_code = status_code, detail = detail)
                logger.error(f"Audio separation error: {e}", exc_info = True)
                raise HTTPException(status_code = 500, detail = safe_error_detail(e))
            finally:
                await _stop_local_disconnect_cancel_watcher(watcher)
        stems = _checked_stems(outputs, staging)
        group_id = uuid.uuid4().hex
        base_meta: dict[str, Any] = {
            "prompt": source.name,
            "model": model_name,
            "audio_type": "audiocpp_sep",
            "workflow": "separate",
            "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
            "group_id": group_id,
            "settings": {
                "stems": [stem["id"] for stem in stems],
                "num_overlap": (options or {}).get("num_overlap"),
            },
        }
        if source.kind == "clip":
            base_meta["source_clip_id"] = source.id
        try:
            records = await asyncio.to_thread(_save_stems, stems, base_meta)
        except Exception as exc:  # noqa: BLE001 - every stem of the group was rolled back
            logger.warning("audio_gallery.separate_save_failed: %s", exc)
            reason = sanitize_runtime_detail(str(exc)) or "unknown error"
            raise HTTPException(
                status_code = 500, detail = f"Could not save the stems to history: {reason}"
            )
    finally:
        await asyncio.to_thread(shutil.rmtree, staging, True)
    return AudioRunResponse(
        clips = [
            {
                "id": record["id"],
                "role": record["role"],
                "url": record["url"],
                "sample_rate": record["sample_rate"],
                "duration_s": record["duration_s"],
                "workflow": record["workflow"],
                "source_clip_id": record.get("source_clip_id"),
            }
            for record in records
        ],
        group_id = group_id,
        model = model_name,
    )


def _refuse_decision_connection(provider_type: Optional[str], api_type: Optional[str]) -> None:
    if answers_decisions_only(provider_type, api_type):
        raise HTTPException(
            status_code = 400,
            detail = "This connection answers decisions only. Use it from Settings > API > Decision API.",
        )


async def _external_tts_speech(body: AudioSpeechRequest, request: Request) -> Response:
    """Proxy CreateSpeech to a saved connection, so read-aloud skips the local model slot."""
    provider_id = (body.provider_id or "").strip()
    external_model = (body.model or "").strip()
    external_voice = body.voice.strip() if isinstance(body.voice, str) else ""
    if not provider_id:
        raise HTTPException(status_code = 400, detail = "provider_id cannot be empty.")
    if not external_model:
        raise HTTPException(
            status_code = 400, detail = "model is required when using an external TTS connection."
        )
    if not external_voice:
        raise HTTPException(
            status_code = 400, detail = "voice is required when using an external TTS connection."
        )

    config = await asyncio.to_thread(providers_db.get_provider, provider_id)
    if config is None:
        raise HTTPException(status_code = 404, detail = f"Provider config not found: {provider_id}")
    account_access.require_connection_model_allowed(config, external_model)
    _refuse_decision_connection(config["provider_type"], config.get("api_type"))
    if not config["is_enabled"]:
        raise HTTPException(
            status_code = 400, detail = f"Provider '{config['display_name']}' is disabled."
        )
    base_url = config["base_url"] or get_base_url(config["provider_type"])
    if not base_url:
        raise HTTPException(status_code = 400, detail = "The connection has no base URL.")
    # Validate the destination before decrypting the key: a refused target sees no credential.
    try:
        base_url = validate_provider_base_url(base_url)
    except ValueError as exc:
        raise HTTPException(status_code = 400, detail = str(exc)) from None
    async with provider_config_guard(
        provider_id, shared_by_owner = bool(config.get("shared_by_owner"))
    ):
        current = await asyncio.to_thread(providers_db.get_provider, provider_id)
        routing_fields = ("provider_type", "base_url", "is_enabled")
        if current is None or any(
            current.get(field) != config.get(field) for field in routing_fields
        ):
            raise HTTPException(
                status_code = 409,
                detail = "Provider changed while the request was starting; retry.",
            )
        account_access.require_connection_model_allowed(current, external_model)
        if body.encrypted_api_key and body.provider_base_url != current.get("base_url"):
            # A concurrent same-id edit may have replaced the endpoint; never attach the captured key.
            raise HTTPException(
                status_code = 409,
                detail = "Provider changed while the request was starting; retry.",
            )
        api_key = await asyncio.to_thread(
            resolve_provider_api_key_or_400,
            provider_id,
            body.encrypted_api_key,
            allow_saved_key = not _request_has_api_key(request),
            prefer_saved_key = True,
        )
        # Another process may edit the provider; final row check prevents old URL + new key.
        latest = await asyncio.to_thread(providers_db.get_provider, provider_id)
        if latest is None or any(
            latest.get(field) != current.get(field) for field in routing_fields
        ):
            raise HTTPException(
                status_code = 409,
                detail = "Provider changed while the request was starting; retry.",
            )
    client = ExternalProviderClient(
        provider_type = config["provider_type"],
        base_url = base_url,
        api_key = api_key,
    )
    # FastAPI does not cancel non-streaming handlers on disconnect; paid synthesis would continue.
    speech_task = asyncio.create_task(
        client.create_speech(
            text = body.input,
            model = external_model,
            voice = external_voice,
            response_format = (body.response_format or "wav").strip().lower(),
            speed = body.speed,
            instructions = body.instructions,
        )
    )
    disconnect_watcher = asyncio.create_task(
        _await_disconnect_then_cancel_task(request, speech_task)
    )
    try:
        audio_bytes, media_type = await speech_task
    except httpx.HTTPStatusError as exc:
        raise HTTPException(
            status_code = 502,
            detail = (
                f"TTS endpoint returned HTTP {exc.response.status_code}: {exc.response.text[:300]}"
            ),
        )
    except httpx.HTTPError as exc:
        raise HTTPException(status_code = 502, detail = f"Could not reach the TTS endpoint: {exc}")
    finally:
        await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
    return Response(content = audio_bytes, media_type = media_type)


async def _speak_on_connection(body: AudioRunRequest, request: Request) -> AudioRunResponse:
    import wave

    if (
        body.workflow != "speak"
        or body.inputs != AudioRunInputs()
        or body.language
        or body.options
        or body.seed is not None
        or body.max_tokens is not None
        or any(
            name in body.model_fields_set and getattr(body, name) not in (None, False, 1)
            for name in _MUSIC_ONLY_FIELDS
        )
    ):
        raise HTTPException(
            status_code = 400,
            detail = "A saved connection only speaks text, in a voice, with instructions and speed.",
        )
    speech = await _external_tts_speech(
        AudioSpeechRequest(
            input = body.text,
            model = body.model,
            voice = body.voice,
            speed = body.speed,
            instructions = body.instructions,
            provider_id = body.provider_id,
        ),
        request,
    )
    try:
        with wave.open(io.BytesIO(speech.body)) as wav:
            params = wav.getparams()
            frames = wav.readframes(wav.getnframes())
    except (wave.Error, EOFError):
        raise HTTPException(
            status_code = 502, detail = "The TTS endpoint did not return WAV audio."
        ) from None
    # OpenAI streams WAV with 0xFFFFFFFF sizes; rewrite the header from the frames received.
    out = io.BytesIO()
    with wave.open(out, "wb") as wav:
        wav.setparams(params._replace(nframes = 0))
        wav.writeframes(frames)
    wav_bytes, sample_rate = out.getvalue(), params.framerate
    settings = {"voice": body.voice, "instructions": body.instructions, "speed": body.speed}
    record = await asyncio.to_thread(
        _persist_tts_clip,
        wav_bytes,
        sample_rate,
        body.text,
        body.model,
        "connection",
        {"settings": settings},
        "speak",
    )
    return _audio_run_response(record, wav_bytes, sample_rate, body.model)


# openai-compatible speech api: the router's dual mount also answers /v1/audio/speech
@router.post("/audio/speech")
async def openai_audio_speech(
    body: AudioSpeechRequest,
    request: Request,
    current_subject: str = Depends(get_current_subject),
) -> Response:
    """OpenAI-compatible text-to-speech (POST /v1/audio/speech).

    With ``provider_id`` the request is proxied. Otherwise an omitted ``model`` serves the
    resident model. A named downloaded local model is loaded when auto-switch is on; when
    it is off, the shared switch guard rejects a different recognized local model.
    A saved voice (``voice``) or ``reference`` clones; history keeps the clip as WAV."""
    fmt = (body.response_format or "wav").strip().lower()
    # Neither path streams, a saved connection included.
    if body.stream_format == "sse":
        _raise_unsupported_openai_parameter(
            "stream_format", "stream_format 'sse' is not supported. Use 'audio'."
        )
    if body.provider_id:
        if fmt != "wav":
            raise HTTPException(
                status_code = 400,
                detail = (
                    f"Unsupported response_format '{body.response_format}' for an external "
                    "TTS connection. Only 'wav' is supported."
                ),
            )
        # Untrack before any await so slow external speech can't block local swaps or idle timers.
        from core.inference.llama_keepwarm import untrack_current_request

        untrack_current_request(request.scope)
        # Saved TTS connections are media traffic: keep them monitored, closing rows on failure or cancel.
        async with _monitored_media_request(
            request,
            model = public_model_id(body.model) or body.model,
            prompt = body.input,
            subject = current_subject,
        ):
            return await _external_tts_speech(body, request)
    from core.inference import audio_inputs, audio_voices

    formats = await asyncio.to_thread(audio_inputs.speech_formats)
    if fmt not in formats:
        _raise_unsupported_openai_parameter(
            "response_format",
            f"Unsupported response_format '{body.response_format}'. Use {', '.join(formats)}.",
        )
    voice = body.voice
    voice_id = voice.id if isinstance(voice, AudioSpeechVoice) else None
    if isinstance(voice, str) and await asyncio.to_thread(audio_voices.get, voice):
        voice_id = voice
    if voice_id and body.reference is not None:
        _raise_unsupported_openai_parameter(
            "reference", "Send a saved voice or a reference, not both."
        )
    run = None
    if voice_id or body.reference is not None:
        from fastapi.exceptions import RequestValidationError
        from pydantic import ValidationError
        try:
            run = AudioRunRequest(
                workflow = "speak" if voice_id else "clone",
                text = body.input,
                language = body.language,
                instructions = body.instructions,
                inputs = AudioRunInputs(
                    reference = body.reference or AudioSourceRef(voice_id = voice_id),
                    reference_text = body.reference_text,
                ),
                options = body.audio_options,
                speed = body.speed,
                seed = body.seed,
                max_tokens = body.max_new_tokens or AUDIO_GENERATION_MAX_TOKENS,
            )
        except ValidationError as exc:
            raise RequestValidationError(exc.errors()) from None
    # Caps the speech ceiling to context left after the prompt, since max_seq_length=0 loads at
    # 2048.
    payload = ChatCompletionRequest(
        messages = [{"role": "user", "content": body.input}],
        max_tokens = body.max_new_tokens or AUDIO_GENERATION_MAX_TOKENS,
        audio_instructions = body.instructions,
        audio_language = body.language,
        audio_options = body.audio_options,
        seed = body.seed,
    )
    # Redact up front: a failure before relabel would leave a host path on a tunneled row.
    async with _monitored_media_request(
        request,
        model = public_model_id(body.model) or body.model,
        prompt = body.input,
        subject = current_subject,
    ) as monitor_id:
        tts_kwargs = {
            "speech_api_default_max_tokens": body.max_new_tokens is None,
            "requested_model": body.model or _RELOAD_ONLY_MODEL,
        }
        if run is not None:
            _, wav_bytes, sample_rate, model_name = await _speak(
                run, request, current_subject, **tts_kwargs
            )
        else:
            wav_bytes, sample_rate, model_name, audio_type = await _generate_tts_wav(
                body.input,
                payload,
                request,
                current_subject,
                voice = voice if isinstance(voice, str) else None,
                **tts_kwargs,
            )
            await asyncio.to_thread(
                _persist_tts_clip, wav_bytes, sample_rate, body.input, model_name, audio_type
            )
        api_monitor.relabel(monitor_id, model_name)
    if fmt == "wav":
        return Response(content = wav_bytes, media_type = "audio/wav")
    content, media_type = await asyncio.to_thread(audio_inputs.encode_wav, wav_bytes, fmt)
    return Response(content = content, media_type = media_type)


async def _external_stt_transcription(
    *,
    provider_id: str,
    raw: bytes,
    filename: str,
    content_type: str,
    model: Optional[str],
    language: Optional[str],
    response_format: str,
    encrypted_api_key: Optional[str],
    request: Request,
    timestamp_granularities: Optional[list[str]] = None,
) -> Response:
    provider_id = provider_id.strip()
    if not provider_id:
        raise HTTPException(status_code = 400, detail = "provider_id cannot be empty.")
    if not raw:
        raise HTTPException(status_code = 400, detail = "Audio is empty.")
    if len(raw) > _MAX_AUDIO_RAW_BYTES:
        raise HTTPException(status_code = 413, detail = "Audio is too large.")
    external_model = (model or "").strip()
    if not external_model:
        raise HTTPException(
            status_code = 400,
            detail = "model is required when using an external STT connection.",
        )

    config = await asyncio.to_thread(providers_db.get_provider, provider_id)
    if config is None:
        raise HTTPException(status_code = 404, detail = f"Provider config not found: {provider_id}")
    account_access.require_connection_model_allowed(config, external_model)
    _refuse_decision_connection(config["provider_type"], config.get("api_type"))
    if not config["is_enabled"]:
        raise HTTPException(
            status_code = 400,
            detail = f"Provider '{config['display_name']}' is disabled.",
        )
    base_url = config["base_url"] or get_base_url(config["provider_type"])
    if not base_url:
        raise HTTPException(status_code = 400, detail = "The connection has no base URL.")
    try:
        base_url = validate_provider_base_url(base_url)
    except ValueError as exc:
        raise HTTPException(status_code = 400, detail = str(exc)) from None

    async with provider_config_guard(
        provider_id, shared_by_owner = bool(config.get("shared_by_owner"))
    ):
        current = await asyncio.to_thread(providers_db.get_provider, provider_id)
        routing_fields = ("provider_type", "base_url", "is_enabled")
        if current is None or any(
            current.get(field) != config.get(field) for field in routing_fields
        ):
            raise HTTPException(
                status_code = 409,
                detail = "Provider changed while the request was starting; retry.",
            )
        account_access.require_connection_model_allowed(current, external_model)
        api_key = await asyncio.to_thread(
            resolve_provider_api_key_or_400,
            provider_id,
            encrypted_api_key,
            allow_saved_key = not _request_has_api_key(request),
        )

    client = ExternalProviderClient(
        provider_type = config["provider_type"],
        base_url = base_url,
        api_key = api_key,
    )
    transcription_task = asyncio.create_task(
        client.create_transcription(
            audio = raw,
            filename = filename,
            content_type = content_type,
            model = external_model,
            language = language,
            response_format = response_format,
            timestamp_granularities = timestamp_granularities,
        )
    )
    disconnect_watcher = asyncio.create_task(
        _await_disconnect_then_cancel_task(request, transcription_task)
    )
    try:
        body, media_type = await transcription_task
    except httpx.HTTPStatusError as exc:
        detail = exc.response.text[:300] if exc.response is not None else str(exc)
        raise HTTPException(
            status_code = 502,
            detail = (
                f"STT endpoint returned HTTP {exc.response.status_code}: {detail}"
                if exc.response is not None
                else f"STT endpoint rejected the request: {detail}"
            ),
        ) from exc
    except httpx.HTTPError as exc:
        raise log_and_http_error(
            exc,
            502,
            "Could not reach the STT endpoint.",
            event = "external_stt.transport_error",
            log = logger,
        ) from exc
    finally:
        await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
    return Response(content = body, media_type = media_type)


# openai-compatible transcription api, dual-mounted like /audio/speech; runs on the stt sidecar, not the main gpu slot
@router.post("/audio/transcriptions")
async def openai_audio_transcriptions(
    request: Request,
    file: UploadFile = File(...),
    model: Optional[str] = Form(None),
    language: Optional[str] = Form(None),
    response_format: str = Form("json"),
    provider_id: Optional[str] = Form(None),
    encrypted_api_key: Optional[str] = Form(None),
    timestamp_granularities: Optional[list[str]] = Form(None, alias = "timestamp_granularities[]"),
    current_subject: str = Depends(get_current_subject),
):
    """OpenAI-compatible speech-to-text (POST /v1/audio/transcriptions).

    With ``provider_id`` set, the request is proxied to that saved connection.
    Otherwise ``model`` maps to a sidecar model id, with ``whisper-1`` or nothing
    selecting the default. ``response_format`` supports ``json``, ``text`` and
    ``verbose_json``; an audio.cpp model also gives segments, words (``timestamp_granularities``)
    and ``diarized_json``."""
    fmt = (response_format or "json").strip().lower()
    if fmt not in ("json", "text", "verbose_json", "diarized_json"):
        raise HTTPException(
            status_code = 400,
            detail = (
                f"Unsupported response_format '{response_format}'. "
                "Use 'json', 'text', 'verbose_json' or 'diarized_json'."
            ),
        )
    # Bounded read: an unbounded read materializes the whole upload in memory before the size check; one byte past the limit rejects it.
    raw = await file.read(_MAX_AUDIO_RAW_BYTES + 1)
    if isinstance(provider_id, str):
        # Proxied path opens the same monitor row, or a saved STT connection is invisible; label is kept for life, so it stays path-free.
        _requested = (model or "").strip()
        async with _monitored_media_request(
            request,
            model = public_model_id(_requested) or _requested,
            prompt = file.filename or "audio",
            subject = current_subject,
        ) as monitor_id:
            response = await _external_stt_transcription(
                provider_id = provider_id,
                raw = raw,
                filename = file.filename or "audio",
                content_type = file.content_type or "application/octet-stream",
                model = model,
                language = language,
                response_format = fmt,
                timestamp_granularities = timestamp_granularities,
                encrypted_api_key = encrypted_api_key,
                request = request,
            )
            api_monitor.set_reply(monitor_id, _external_transcript_preview(response))
        return response
    from core.inference import audio_inputs, stt_capabilities, stt_details

    # openai's whisper-1 placeholder means the default transcription model, not a sidecar id
    sidecar_model = None if model in (None, "", "whisper-1") else model
    engine = _stt_engine_for_model(sidecar_model)
    # isinstance because a direct call passes the raw Form default.
    granularities = timestamp_granularities if isinstance(timestamp_granularities, list) else []
    if granularities and fmt != "verbose_json":
        # OpenAI's contract; also spares an aligner download whose timings would be dropped.
        _raise_unsupported_openai_parameter(
            "timestamp_granularities",
            "timestamp_granularities needs response_format 'verbose_json'.",
        )
    has_language = isinstance(language, str) and language.strip()
    serving_engine = _resolve_serving_stt_engine(engine)
    timed = serving_engine == "audiocpp" and (
        fmt in ("verbose_json", "diarized_json") or bool(granularities)
    )
    if timed or fmt == "diarized_json":
        caps = await asyncio.to_thread(
            stt_capabilities.capabilities_for, sidecar_model, serving_engine
        )
        _refuse_stt_caps(
            caps, timestamps = timed and bool(granularities), speakers = fmt == "diarized_json"
        )
    if timed:
        # The prepared copy is read in place, past the sidecar's own size check.
        if len(raw) > _MAX_AUDIO_RAW_BYTES:
            raise HTTPException(status_code = 413, detail = "Audio is too large.")
    elif fmt == "verbose_json" and not has_language:
        # The sidecar detects no language, so verbose_json with auto-detect is refused rather than
        # guessed.
        raise HTTPException(
            status_code = 501,
            detail = (
                "verbose_json reports the language of the audio and the local STT engine "
                "does not detect one. Send the 'language' parameter, or use response_format "
                "'json' or 'text'."
            ),
        )
    elif granularities:
        # Accepting the parameter and returning neither words nor segments would look like
        # the audio simply had none. Only audio.cpp models report timings.
        raise HTTPException(
            status_code = 400,
            detail = (
                "timestamp_granularities is not supported by the local STT engine. "
                "Use a saved STT connection with provider_id for word or segment timings."
            ),
        )
    # The relabel below only lands on success; a sidecar failure would otherwise strand the
    # raw client string, which may be a host path, on the terminal row.
    _opening_label = sidecar_model or "whisper-1"
    async with _monitored_media_request(
        request,
        model = public_model_id(_opening_label) or _opening_label,
        prompt = file.filename or "audio",
        subject = current_subject,
    ) as monitor_id:
        path = None
        try:
            if timed:
                rate = stt_details.FIXED_SPAN_RATES.get(caps["family"], 16000)
                try:
                    path = await asyncio.to_thread(_prepared_upload, raw, rate)
                except audio_inputs.AudioInputError as exc:
                    raise _audio_source_error(exc) from None
            result = await _transcribe_audio_result(
                raw,
                sidecar_model,
                language,
                fast = False,
                engine = engine,
                request = request,
                source_path = path,
                timestamps = bool(granularities),
            )
        finally:
            if path is not None:
                await asyncio.to_thread(path.unlink, True)
        text = str(result.get("text", ""))
        # Required by OpenAI's schema: a null fails validation inside the official clients.
        detected = str(result.get("language") or (language if has_language else "")).strip()
        if fmt == "verbose_json" and not detected:
            raise HTTPException(
                status_code = 501,
                detail = "This model did not report the language of the audio. Send the "
                "'language' parameter, or use response_format 'json' or 'text'.",
            )
        # Same path-free treatment the image route gives its label: sidecar ids are
        # curated or owner/model today, but the row goes out over the tunnel.
        _served_model = str(result.get("model") or "")
        api_monitor.relabel(monitor_id, public_model_id(_served_model) or _served_model)
        api_monitor.set_reply(monitor_id, text)

    if fmt == "text":
        return PlainTextResponse(content = text)
    _duration = result.get("duration")
    # Unlike the language, this is not a guess: duration is None only for a clip that decoded
    # to no samples, and that clip really is zero seconds.
    duration = float(_duration) if isinstance(_duration, (int, float)) else 0.0
    segments = result.get("segments") or []
    if fmt == "diarized_json":
        labels = {s["id"]: s["label"] for s in result.get("speakers") or ()}
        return JSONResponse(
            content = {
                "task": "transcribe",
                "duration": duration,
                "text": text,
                "segments": [
                    {
                        "type": "transcript.text.segment",
                        "id": f"seg_{index}",
                        "start": s["start"],
                        "end": s["end"],
                        "text": s["text"],
                        "speaker": labels.get(s.get("speaker"), s.get("speaker") or ""),
                    }
                    for index, s in enumerate(segments)
                ],
            }
        )
    if fmt == "verbose_json":
        content = {"task": "transcribe", "language": detected, "duration": duration, "text": text}
        if segments:
            content["segments"] = [
                {
                    "id": index,
                    "seek": 0,
                    "start": s["start"],
                    "end": s["end"],
                    "text": s["text"],
                    "tokens": [],
                    "temperature": 0.0,
                    "avg_logprob": 0.0,
                    "compression_ratio": 0.0,
                    "no_speech_prob": 0.0,
                }
                for index, s in enumerate(segments)
            ]
        if "word" in granularities and result.get("words"):
            content["words"] = [
                {"word": w["word"], "start": w["start"], "end": w["end"]} for w in result["words"]
            ]
        return JSONResponse(content = content)
    return JSONResponse(content = {"text": text})


@router.post("/audio/translations")
async def openai_audio_translations(
    request: Request,
    file: UploadFile = File(...),
    model: Optional[str] = Form(None),
    response_format: str = Form("json"),
    provider_id: Optional[str] = Form(None),
    current_subject: str = Depends(get_current_subject),
):
    """OpenAI-compatible speech translation to English (POST /v1/audio/translations).

    Runs on the local Whisper sidecar; ``whisper-1`` or nothing selects the default model.
    ``response_format`` supports ``json``, ``text`` and ``verbose_json``. ``prompt`` and
    ``temperature`` are accepted and ignored."""
    fmt = (response_format or "json").strip().lower()
    if fmt not in ("json", "text", "verbose_json"):
        _raise_unsupported_openai_parameter(
            "response_format",
            f"Unsupported response_format '{response_format}'. Use 'json', 'text' or 'verbose_json'.",
        )
    if isinstance(provider_id, str):
        _raise_unsupported_openai_parameter(
            "provider_id",
            "Translations run on a local Whisper model; provider_id is not supported.",
        )
    from core.inference.stt_sidecar import can_translate

    sidecar_model = None if model in (None, "", "whisper-1") else model
    # mtmd / audio.cpp engines and turbo checkpoints would just transcribe.
    if _stt_engine_for_model(sidecar_model) is not None or not can_translate(sidecar_model):
        raise HTTPException(
            status_code = 400,
            detail = openai_error_body(
                f"'{model}' cannot translate. Use a multilingual Whisper model such as 'small'.",
                status = 400,
                code = "invalid_value",
                param = "model",
            ),
        )
    raw = await file.read(_MAX_AUDIO_RAW_BYTES + 1)
    _opening_label = sidecar_model or "whisper-1"
    async with _monitored_media_request(
        request,
        model = public_model_id(_opening_label) or _opening_label,
        prompt = file.filename or "audio",
        subject = current_subject,
    ) as monitor_id:
        result = await _transcribe_audio_result(
            raw, sidecar_model, None, fast = False, request = request, translate = True
        )
        text = str(result.get("text", ""))
        _served_model = str(result.get("model") or "")
        api_monitor.relabel(monitor_id, public_model_id(_served_model) or _served_model)
        api_monitor.set_reply(monitor_id, text)
    if fmt == "text":
        return PlainTextResponse(content = text)
    if fmt == "verbose_json":
        duration = result.get("duration")
        return JSONResponse(
            content = {
                "task": "translate",
                "language": "english",
                "duration": float(duration) if isinstance(duration, (int, float)) else 0.0,
                "text": text,
            }
        )
    return JSONResponse(content = {"text": text})


# =====================================================================

# Speech-to-text (STT) sidecar  (/audio/transcribe, /audio/stt/*)
# =====================================================================


def _stt_engine_for_model(model: Optional[str]) -> Optional[str]:
    """Qwen3-ASR runs only on the mtmd sidecar; without this an explicit id fell through to Whisper."""
    if not model:
        return None
    from core.inference.audio_cpp_models import looks_like_audio_cpp, resolve
    from core.inference.stt_mtmd_sidecar import is_mtmd_model

    # Only mtmd and audio.cpp ids are forced; Whisper ids also work on the Transformers sidecar.
    if is_mtmd_model(model.strip()):
        return "mtmd"
    if looks_like_audio_cpp(model.strip()):
        return "audiocpp"
    try:
        audio_cpp_model = resolve(model.strip(), network = False)
    except Exception:  # noqa: BLE001 - unreadable from the cache: leave the default
        audio_cpp_model = None
    if audio_cpp_model is not None and audio_cpp_model.task == "asr":
        return "audiocpp"
    return None


def _resolve_stt_engine(engine: Optional[str]) -> str:
    """Normalize the requested STT engine name; default is Transformers."""
    normalized = (engine or "transformers").strip().lower()
    if normalized in ("", "transformers", "whisper"):
        return "transformers"
    if normalized in ("gguf", "ggml", "whisper_cpp", "whisper.cpp"):
        return "gguf"
    if normalized in ("mtmd", "llama_cpp", "llama.cpp"):
        return "mtmd"
    if normalized in ("audiocpp", "audio_cpp", "audio.cpp"):
        return "audiocpp"
    raise HTTPException(
        status_code = 422,
        detail = (
            f"Unknown STT engine '{engine}'. Use 'transformers', 'gguf', 'mtmd', or 'audiocpp'."
        ),
    )


def _resolve_serving_stt_engine(engine: Optional[str]) -> str:
    """Falls back to Transformers when whisper-server is missing, instead of 501ing every recording."""
    resolved = _resolve_stt_engine(engine)
    if resolved == "gguf":
        from core.inference import stt_ggml_sidecar
        if not stt_ggml_sidecar.is_available():
            return "transformers"
    # mtmd models exist in no other engine, so there is nothing to fall back to.
    return resolved


def _prepare_runtime_fallback_checkpoint(
    requested_engine: Optional[str],
    serving_engine: str,
    model: Optional[str],
    hf_token: Optional[str] = None,
) -> None:
    """Fetches the Transformers snapshot a broken whisper.cpp falls back to; without it every retry raises SttModelNotDownloadedError."""
    if serving_engine != "transformers" or _resolve_stt_engine(requested_engine) != "gguf":
        return
    from core.inference import stt_ggml_sidecar, stt_sidecar

    if stt_ggml_sidecar.runtime_inference_failure() is None:
        return
    if stt_sidecar.is_model_downloaded(model):
        return
    try:
        if account_access.account_scope() is None:
            stt_sidecar.start_model_download(model, hf_token)
        else:
            _start_account_stt_download(
                stt_sidecar, "transformers", model, account_access.account_hf_token(hf_token)
            )
    except Exception as exc:  # noqa: BLE001 - preparation is best effort, never fatal
        # Another dictation model already downloading is common; the caller says not downloaded anyway.
        logger.info(
            "Could not start the Transformers fallback download for STT model %r: %s",
            model,
            exc,
        )


def _stt_download_module(engine: str):
    """Module owning download/status for an engine."""
    if engine == "mtmd":
        from core.inference import stt_mtmd_sidecar
        return stt_mtmd_sidecar
    if engine == "gguf":
        from core.inference import stt_ggml_sidecar
        return stt_ggml_sidecar
    if engine == "audiocpp":
        from core.inference import stt_audiocpp_sidecar
        return stt_audiocpp_sidecar
    from core.inference import stt_sidecar

    return stt_sidecar


def _stt_sidecar_for(engine: str):
    """The sidecar serving an engine. One resolver, shared with the orchestrator."""
    from core.inference import stt_registry
    return stt_registry.sidecar_for(engine)


def _stt_resident_model(engine: str) -> Optional[str]:
    """The model an engine holds right now, or None when that cannot be read."""
    try:
        return _stt_sidecar_for(engine).loaded_model
    except Exception:  # noqa: BLE001 - a broken sidecar holds nothing we can report
        return None


def _stt_lifecycle() -> tuple:
    """Uses stt_registry directly if no orchestrator exists; building one blocks on hardware detection."""
    from core.inference import stt_registry
    from core.inference.orchestrator import peek_inference_backend

    backend = peek_inference_backend()
    if backend is None:
        return stt_registry.load, stt_registry.unload
    return backend.load_stt_model, backend.unload_stt_model


_stt_download_accounts: dict[str, str] = {}
_stt_download_id_accounts: dict[str, dict[str, str]] = {}
_stt_download_lock = threading.Lock()
_stt_grant_pending: dict[str, threading.Event] = {}


def _start_account_stt_download(
    module,
    engine,
    model,
    hf_token,
    revision = None,
):
    args = (model, hf_token, revision) if engine == "transformers" else (model, hf_token)
    if account_access.account_scope() is None:
        return module.start_model_download(*args)
    from core.training.account_jobs import account_is_retired

    with _stt_download_lock:
        # Shares retire_stt_downloads' lock: a start is either swept by it or sees this tombstone.
        if account_is_retired():
            raise HTTPException(status_code = 403, detail = "Account is retired")
        if module.download_status().get("downloading"):
            if _stt_download_accounts.get(engine, OWNER_ACCOUNT_ID) != current_account_id():
                raise HTTPException(
                    status_code = 409, detail = {"error": "download_busy", "retry_after": 1}
                )
            return module.start_model_download(*args)
        pending = _stt_grant_pending.get(engine)
        if pending is not None and not pending.is_set():
            raise HTTPException(
                status_code = 409, detail = {"error": "download_busy", "retry_after": 1}
            )
        repo = _stt_repo_reference(model, engine)
        account_access.authorize_download(repo, "model", hf_token)
        download_id = module.start_model_download(*args)
        _stt_download_accounts[engine] = current_account_id()
        account = current_account_id()
        if download_id is not None:
            attempts = _stt_download_id_accounts.setdefault(engine, {})
            attempts[str(download_id)] = account
            while len(attempts) > 64:
                attempts.pop(next(iter(attempts)))
        settled = _stt_grant_pending[engine] = threading.Event()

        def watch():
            try:
                while True:
                    status = module.download_status()
                    if not status.get("downloading"):
                        break
                    time.sleep(0.1)
                if status.get("error") or status.get("cancelled"):
                    return
                with _stt_download_lock:
                    if _stt_download_accounts.get(engine) != account:
                        return
                    downloaded = getattr(module, "is_model_downloaded", None)
                    complete = (
                        downloaded(model)
                        if downloaded is not None
                        else module._cached_model_path(model) is not None
                    )
                    if complete:
                        account_access.record_model_grant(repo)

            finally:
                settled.set()

        account_thread(target = watch, name = f"stt-grant-{engine}", daemon = True).start()
        return download_id


def retire_stt_downloads() -> None:
    """Cancel and reap this account's dictation downloads, which keep their own registry."""
    if account_access.account_scope() is None:
        return
    account = current_account_id()
    claimed = []
    with _stt_download_lock:
        for engine, owner in list(_stt_download_accounts.items()):
            if owner != account:
                continue
            module = _stt_download_module(engine)
            try:
                module.cancel_model_download()
            finally:
                _stt_download_accounts.pop(engine, None)
            claimed.append((engine, module))
    stragglers = []
    for engine, module in claimed:
        deadline = time.monotonic() + 10
        while module.download_status().get("downloading"):
            if time.monotonic() >= deadline:
                stragglers.append(engine)
                break
            time.sleep(0.1)
        else:
            _stt_grant_pending.pop(engine, None)
    if stragglers:
        raise RuntimeError(
            f"Retired account dictation downloads have not stopped: {sorted(stragglers)}"
        )


def _cancel_account_stt_download(
    module,
    engine,
    model = None,
    download_id = None,
):
    with _stt_download_lock:
        if (
            account_access.account_scope() is not None
            and _stt_download_accounts.get(engine, OWNER_ACCOUNT_ID) != current_account_id()
        ):
            return {"downloading": False, "cancelled": False}
        if download_id is not None:
            cancelled = module.cancel_model_download(model, download_id)
        elif model is not None:
            cancelled = module.cancel_model_download(model)
        else:
            cancelled = module.cancel_model_download()
        return {**module.download_status(), "cancelled": cancelled}


def _stt_repo_reference(model, engine):
    from core.inference import stt_ggml_sidecar, stt_mtmd_sidecar, stt_sidecar

    selected = _resolve_serving_stt_engine(engine)
    if selected == "gguf":
        return stt_ggml_sidecar.GGML_STT_REPOS.get(
            model or stt_ggml_sidecar.DEFAULT_GGML_STT_MODEL, model
        )
    if selected == "mtmd":
        spec = stt_mtmd_sidecar.MTMD_STT_MODELS.get(model)
        return spec.repo if spec else model
    if selected == "audiocpp":
        from core.inference.audio_cpp_models import DEFAULT_AUDIO_CPP_STT_MODEL, repo_of
        return repo_of(model or DEFAULT_AUDIO_CPP_STT_MODEL) or model
    return stt_sidecar.resolve_model_repo(model)


def _stt_resolved_model_id(model, engine):
    """The id the sidecar records for this request, resolved as its loader does."""
    from core.inference import stt_ggml_sidecar, stt_mtmd_sidecar, stt_sidecar
    try:
        if engine == "gguf":
            return stt_ggml_sidecar.resolve_ggml_model_id(model)
        if engine == "mtmd":
            return stt_mtmd_sidecar.resolve_mtmd_model_id(model)
        if engine == "audiocpp":
            from core.inference import stt_audiocpp_sidecar
            return stt_audiocpp_sidecar.resolve_audio_cpp_stt_model_id(model)
        return stt_sidecar.resolve_model_id(model)
    except Exception:  # noqa: BLE001 - an id the loader would refuse is not what it loaded
        return None


def _account_stt_status(status):
    for engine in ("transformers", "gguf", "mtmd", "audiocpp"):
        section = status[engine]
        loaded = section.get("loaded_model")
        if account_access.resident_hidden(f"stt:{engine}", loaded):
            section["loaded_model"] = None
            section["loaded"], section["yours"] = True, False
            if engine == "transformers":
                status["loaded_model"] = None
        section["downloaded_models"] = [
            model
            for model in section.get("downloaded_models", [])
            if account_access.model_visible(_stt_repo_reference(model, engine))
        ]
        download = section.get("download", {})
        attempt_accounts = _stt_download_id_accounts.get(engine, {})
        completed_download_ids = [
            download_id
            for download_id in download.get("completed_download_ids", [])
            if attempt_accounts.get(download_id) == current_account_id()
        ]
        if _stt_download_accounts.get(engine, OWNER_ACCOUNT_ID) != current_account_id():
            # Opaque ids tell stale trackers the engine moved on; no other account's model leaks.
            section["download"] = {
                "downloading": False,
                "download_id": download.get("download_id"),
                "completed_download_ids": completed_download_ids,
            }
        else:
            download["completed_download_ids"] = completed_download_ids
    return status


_AUDIO_CPP_RUNTIME_MISSING = {
    "available": False,
    "espeak": False,
    "backend": None,
    "release_tag": None,
    "expected_tag": None,
    "outdated": False,
}


def _audio_cpp_runtime_status() -> dict:
    try:
        from core.inference import audio_cpp_server

        binary = audio_cpp_server.find_audio_cpp_server_binary()
        if binary is None:
            return dict(_AUDIO_CPP_RUNTIME_MISSING)
        record = audio_cpp_server.read_install_record(binary)
        backend = record.get("backend")
        release_tag = record.get("release_tag")
        try:
            launch_backend = audio_cpp_server.select_backend(binary, False)
        except Exception as exc:  # noqa: BLE001 - the build is there even if its launch cannot be told
            logger.debug("audio.cpp backend selection failed: %s", exc)
            launch_backend = None
        status = {
            "available": True,
            "espeak": audio_cpp_server.binary_has_espeak(binary),
            "backend": backend if isinstance(backend, str) else None,
            "launch_backend": launch_backend,
            "release_tag": release_tag if isinstance(release_tag, str) else None,
            "expected_tag": None,
            "outdated": False,
        }
    except Exception as exc:  # noqa: BLE001 - a status poll must not fail on a probe
        logger.debug("audio.cpp runtime probe failed: %s", exc)
        return dict(_AUDIO_CPP_RUNTIME_MISSING)
    try:
        from utils import audio_cpp_update
        status.update(audio_cpp_update.release_status(binary, record))
    except Exception as exc:  # noqa: BLE001 - cannot tell is not outdated
        logger.debug("audio.cpp release lookup failed: %s", exc)
    return status


@studio_router.get("/audio/stt/status")
async def stt_status(
    model: Optional[str] = None, current_subject: str = Depends(get_current_subject)
):
    """Report STT availability and which model, if any, is resident.

    ``model`` extends the Transformers ``downloaded_models`` check to a
    custom Hugging Face repository beyond the curated defaults.
    """
    if account_access.managed_account() and model:
        # Transformers resolver refuses mtmd/audio.cpp keys, which would 500 a status poll.
        engine = _stt_engine_for_model(model) or "transformers"
        try:
            repo = _stt_repo_reference(model, engine)
        except Exception as exc:  # noqa: BLE001 - an id no engine accepts is not a server error
            raise HTTPException(status_code = 422, detail = str(exc)) from exc
        await asyncio.to_thread(account_access.require_model_access, repo)
    from core.inference import (
        stt_audiocpp_sidecar,
        stt_ggml_sidecar,
        stt_mtmd_sidecar,
        stt_sidecar,
    )
    from core.inference.stt_sidecar import (
        DEFAULT_STT_MODEL,
        STT_MODELS,
        get_stt_sidecar,
        is_available,
    )

    sidecar = get_stt_sidecar()
    ggml = stt_ggml_sidecar.get_ggml_stt_sidecar()
    mtmd = stt_mtmd_sidecar.get_mtmd_stt_sidecar()
    audiocpp = stt_audiocpp_sidecar.get_audio_cpp_stt_sidecar()
    audiocpp_downloaded = await asyncio.to_thread(stt_audiocpp_sidecar.downloaded_model_ids)
    # Choosing the launch backend can run the binary's --version.
    audio_cpp_runtime = await asyncio.to_thread(_audio_cpp_runtime_status)
    transformers_downloaded = [
        model_id for model_id in STT_MODELS if stt_sidecar.is_model_downloaded(model_id)
    ]
    if model and model not in STT_MODELS and stt_sidecar.is_model_downloaded(model):
        transformers_downloaded.append(model)
    response = JSONResponse(
        content = {
            "available": is_available(),
            "loaded_model": sidecar.loaded_model,
            "loading": sidecar.is_loading(),
            "device": sidecar.device,
            "keep_alive_seconds": sidecar.keep_alive_seconds,
            "default_model": DEFAULT_STT_MODEL,
            "models": list(STT_MODELS.keys()),
            # Transformers block mirrors the gguf shape so clients read either generically; top-level fields above are kept for old clients.
            "transformers": {
                "available": is_available(),
                "loaded_model": sidecar.loaded_model,
                "loading": sidecar.is_loading(),
                "device": sidecar.device,
                "keep_alive_seconds": sidecar.keep_alive_seconds,
                "default_model": DEFAULT_STT_MODEL,
                "models": list(STT_MODELS.keys()),
                "downloaded_models": transformers_downloaded,
                "download": stt_sidecar.download_status(),
            },
            # llama.cpp (mtmd) engine: non-Whisper ASR models.
            "mtmd": {
                "available": stt_mtmd_sidecar.is_available(),
                "loaded_model": mtmd.loaded_model,
                "loading": mtmd.is_loading(),
                "device": mtmd.device,
                "keep_alive_seconds": mtmd.keep_alive_seconds,
                "default_model": None,
                "models": list(stt_mtmd_sidecar.MTMD_STT_MODELS),
                "downloaded_models": [
                    model_id
                    for model_id in stt_mtmd_sidecar.MTMD_STT_MODELS
                    if stt_mtmd_sidecar.is_model_downloaded(model_id)
                ],
                "download": stt_mtmd_sidecar.download_status(),
            },
            # whisper.cpp (GGUF) engine.
            "gguf": {
                "available": stt_ggml_sidecar.is_available(),
                "loaded_model": ggml.loaded_model,
                "loading": ggml.is_loading(),
                "device": ggml.device,
                "keep_alive_seconds": ggml.keep_alive_seconds,
                "default_model": stt_ggml_sidecar.DEFAULT_GGML_STT_MODEL,
                "models": list(stt_ggml_sidecar.GGML_STT_MODELS.keys()),
                "downloaded_models": [
                    model_id
                    for model_id in stt_ggml_sidecar.GGML_STT_MODELS
                    if stt_ggml_sidecar._cached_model_path(model_id) is not None
                ],
                "download": stt_ggml_sidecar.download_status(),
            },
            # models: recommended list plus downloads; downloaded_models: found by GGUF header in the HF cache.
            "audiocpp": {
                "available": stt_audiocpp_sidecar.is_available(),
                "loaded_model": audiocpp.loaded_model,
                "loaded_variant": audiocpp.loaded_variant,
                "loading": audiocpp.is_loading(),
                "device": audiocpp.device,
                "keep_alive_seconds": audiocpp.keep_alive_seconds,
                "default_model": None,
                "models": list(
                    dict.fromkeys(
                        [*stt_audiocpp_sidecar.AUDIO_CPP_STT_MODELS, *audiocpp_downloaded]
                    )
                ),
                "downloaded_models": audiocpp_downloaded,
                "download": stt_audiocpp_sidecar.download_status(),
            },
            # The audio.cpp runtime itself, for the Audio page's TTS and music rows.
            "audio_cpp_runtime": audio_cpp_runtime,
        }
    )
    if account_access.managed_account():
        status = json.loads(response.body)
        status = await asyncio.to_thread(_account_stt_status, status)
        return JSONResponse(content = status)
    return response


@studio_router.post("/audio/stt/download")
async def stt_download(
    payload: SttLoadRequest,
    current_subject: str = Depends(get_current_subject),
    hf_token: HfTokenArg = Depends(get_request_hf_token),
):
    """Start a background download of a dictation model.

    Both engines download directly (a GGML checkpoint is a single file the Model
    Hub's GGUF variant planner cannot express; a Transformers checkpoint is a
    whole snapshot). Progress is reported by /audio/stt/status.
    """
    hf_token = account_access.account_hf_token(hf_token)
    from core.inference import stt_ggml_sidecar, stt_sidecar
    from core.inference.stt_sidecar import (
        SttModelCompatibilityError,
        SttModelIdError,
        validate_remote_model,
    )

    engine = _resolve_serving_stt_engine(payload.engine)
    module = _stt_download_module(engine)
    try:
        # Confirm a custom repo is Whisper (metadata-only) before downloading into the shared cache.
        if engine == "transformers":
            validated = await asyncio.to_thread(validate_remote_model, payload.model, hf_token)
            # Pin the download to the commit that was just validated so the
            # repo cannot be swapped between validation and snapshot_download.
            download_id = await asyncio.to_thread(
                _start_account_stt_download,
                module,
                engine,
                payload.model,
                hf_token,
                validated.get("revision"),
            )
        else:
            download_id = await asyncio.to_thread(
                _start_account_stt_download, module, engine, payload.model, hf_token
            )
    except SttModelIdError as e:
        raise HTTPException(status_code = 422, detail = str(e))
    except SttModelCompatibilityError as e:
        raise HTTPException(status_code = 422, detail = str(e))
    return JSONResponse(content = {**module.download_status(), "download_id": download_id})


@studio_router.post("/audio/stt/download/cancel")
async def stt_download_cancel(
    payload: Optional[SttLoadRequest] = None, current_subject: str = Depends(get_current_subject)
):
    """Stop an in-flight dictation model download.

    Partial files stay cached, so the same download resumes. Cancelling when
    nothing is downloading is a no-op, so a double click cannot fail.
    """
    from core.inference import stt_ggml_sidecar, stt_sidecar

    engine = _resolve_serving_stt_engine(payload.engine if payload else None)
    module = _stt_download_module(engine)
    status = await asyncio.to_thread(
        _cancel_account_stt_download,
        module,
        engine,
        payload.model if payload else None,
        payload.download_id if payload else None,
    )
    return JSONResponse(content = status)


@studio_router.post("/audio/stt/load")
async def stt_load(
    payload: SttLoadRequest,
    request: Request,
    current_subject: str = Depends(get_current_subject),
):
    """Load the selected STT model after the user starts local dictation."""
    if account_access.managed_account():
        await asyncio.to_thread(
            account_access.require_model_access, _stt_repo_reference(payload.model, payload.engine)
        )
    from core.inference.stt_sidecar import (
        SttLoadCancelledError,
        SttModelBusyError,
        SttModelCompatibilityError,
        SttModelIdError,
        SttModelNotDownloadedError,
        SttTranscriptionCancelledError,
        SttUnavailableError,
        get_stt_sidecar,
    )

    engine = _resolve_serving_stt_engine(payload.engine)
    await asyncio.to_thread(
        _prepare_runtime_fallback_checkpoint,
        payload.engine,
        engine,
        payload.model,
    )
    sidecar = _stt_sidecar_for(engine)
    load_stt, _ = _stt_lifecycle()
    cancel_event = threading.Event()
    disconnect_watcher = asyncio.create_task(
        _await_stt_disconnect_then_cancel(request, sidecar, cancel_event)
    )
    try:
        await asyncio.to_thread(
            functools.partial(load_stt, payload.model, engine, cancel_event, device = payload.device)
        )
    except SttModelNotDownloadedError as e:
        raise HTTPException(status_code = 409, detail = str(e))
    except SttUnavailableError as e:
        raise HTTPException(status_code = 501, detail = str(e))
    except (SttLoadCancelledError, SttTranscriptionCancelledError) as e:
        raise HTTPException(status_code = 409, detail = str(e))
    except SttModelBusyError as e:
        raise HTTPException(status_code = 409, detail = str(e))
    except SttModelIdError as e:
        raise HTTPException(status_code = 422, detail = str(e))
    except SttModelCompatibilityError as e:
        raise HTTPException(status_code = 422, detail = str(e))
    except Exception as e:
        logger.error(f"STT load error: {e}", exc_info = True)
        raise HTTPException(status_code = 500, detail = safe_error_detail(e))
    finally:
        await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
    # The load lock is released and another account may have switched engines, so claim only ours.
    loaded = sidecar.loaded_model
    if loaded is not None and loaded == _stt_resolved_model_id(payload.model, engine):
        account_access.note_resident_account(f"stt:{engine}", loaded)
    else:
        loaded = None
    return JSONResponse(
        content = {"loaded_model": loaded, "device": sidecar.device if loaded else None}
    )


@studio_router.post("/audio/stt/validate")
async def stt_validate(
    payload: SttLoadRequest,
    current_subject: str = Depends(get_current_subject),
    hf_token: HfTokenArg = Depends(get_request_hf_token),
):
    """Verify a Hub repository is a Whisper checkpoint before downloading it."""
    hf_token = account_access.account_hf_token(hf_token)
    from core.inference.stt_sidecar import (
        SttModelCompatibilityError,
        SttModelIdError,
        validate_remote_model,
    )

    try:
        result = await asyncio.to_thread(validate_remote_model, payload.model, hf_token)
    except (SttModelIdError, SttModelCompatibilityError) as e:
        raise HTTPException(status_code = 422, detail = str(e))
    return JSONResponse(content = result)


@studio_router.post("/audio/stt/unload")
async def stt_unload(
    engine: Optional[str] = None,
    model: Optional[str] = None,
    wait: bool = True,
    current_subject: str = Depends(get_current_subject),
):
    """Release the local STT model when dictation is idle.

    Without an engine, both sidecars unload so an engine switch in Voice
    settings always frees whichever backend was resident. ``model`` scopes the
    release to the model the caller claims: a surface owns one model, and another
    can switch the same engine between that ownership check and this request
    arriving, so the sidecar re-checks under its own lock rather than releasing
    whatever happens to be resident by then. ``wait=false`` skips a sidecar that
    is mid-transcription instead of draining it: a caller freeing memory as a
    convenience must not cost the user a recording that is still being decoded.
    """
    if engine is None:
        engines = None
    else:
        # Serving resolver: a gguf pick without whisper-server is served by Transformers, so unload must target that engine or the resident model is never freed.
        engines = [_resolve_serving_stt_engine(engine)]
    if account_access.managed_account():
        engines = [
            candidate
            for candidate in (engines or ["transformers", "gguf", "mtmd", "audiocpp"])
            if not account_access.resident_hidden(
                f"stt:{candidate}", _stt_sidecar_for(candidate).loaded_model
            )
        ]
    from core.inference.stt_registry import STT_ENGINES

    targets = list(STT_ENGINES if engines is None else engines)
    before = {name: _stt_resident_model(name) for name in targets}
    # Every engine is attempted even if one raises, so failing to free one never
    # skips the other (both can be resident after a switch).
    _, unload_stt = _stt_lifecycle()
    # expected_model by keyword: the registry unload takes it keyword-only.
    failed: list[str] = await asyncio.to_thread(
        unload_stt, engines, expected_model = model, wait = wait
    )
    if failed:
        raise HTTPException(
            status_code = 500,
            detail = f"Failed to unload STT engine(s): {', '.join(failed)}",
        )
    # The sidecar keeps a model it does not recognise as the claimed one (or one
    # mid-request under wait=false, or one swapped in before its lock), so report
    # whether an engine that held a model is actually empty now.
    held = [name for name, model_id in before.items() if model_id is not None]
    released = not held or any(_stt_resident_model(name) is None for name in held)
    return JSONResponse(content = {"loaded_model": None, "device": None, "released": released})


async def _transcribe_audio_bytes(
    raw: bytes,
    model: Optional[str],
    language: Optional[str],
    fast: bool,
    engine: Optional[str] = None,
    request: Optional[Request] = None,
    device: Optional[str] = None,
) -> JSONResponse:
    """Run STT for already-decoded request bytes."""
    return JSONResponse(
        content = await _transcribe_audio_result(raw, model, language, fast, engine, request, device)
    )


@holds_inference
async def _transcribe_audio_result(
    raw: bytes,
    model: Optional[str],
    language: Optional[str],
    fast: bool,
    engine: Optional[str] = None,
    request: Optional[Request] = None,
    device: Optional[str] = None,
    on_progress = None,
    *,
    source_path: Optional[Path] = None,
    timestamps: bool = False,
    translate: bool = False,
) -> dict:
    """source_path is read in place by audio.cpp; translate is honoured only by the Transformers sidecar."""
    if account_access.managed_account():
        await asyncio.to_thread(
            account_access.require_model_access, _stt_repo_reference(model, engine)
        )
    from core.inference.stt_sidecar import (
        SttAudioDecodeError,
        SttAudioTooLongError,
        SttLanguageError,
        SttLoadCancelledError,
        SttModelBusyError,
        SttModelCompatibilityError,
        SttModelIdError,
        SttModelNotDownloadedError,
        SttUnavailableError,
        SttTranscriptionCancelledError,
    )

    if source_path is None:
        if not raw:
            raise HTTPException(status_code = 400, detail = "Audio is empty.")
        if len(raw) > _MAX_AUDIO_RAW_BYTES:
            raise HTTPException(status_code = 413, detail = "Audio is too large.")

    serving_engine = _resolve_serving_stt_engine(engine)
    if source_path is not None and serving_engine != "audiocpp":
        # Prepared WAVs are capped at 30 min; the encoded-upload cap would refuse past ~13 min.
        raw = await asyncio.to_thread(source_path.read_bytes)
        source_path = None
        if not raw:
            raise HTTPException(status_code = 400, detail = "Audio is empty.")
    await asyncio.to_thread(
        _prepare_runtime_fallback_checkpoint,
        engine,
        serving_engine,
        model,
    )
    sidecar = _stt_sidecar_for(serving_engine)
    transcribe = (
        functools.partial(sidecar.transcribe, task = "translate") if translate else sidecar.transcribe
    )
    cancel_event = threading.Event() if request is not None or on_progress is not None else None
    disconnect_watcher = (
        asyncio.create_task(_await_stt_disconnect_then_cancel(request, sidecar, cancel_event))
        if request is not None and cancel_event is not None
        else None
    )
    try:
        # Load via the registry, not the sidecar: only it releases other engines (avoids OOM).
        load_stt, _ = _stt_lifecycle()
        on_phase = (
            (lambda phase: on_progress({"text": "", "phase": phase}))
            if on_progress is not None and source_path is not None
            else None
        )
        load_options = {"on_phase": on_phase} if on_phase is not None else {}
        if source_path is not None and timestamps:
            await asyncio.to_thread(
                holds_inference(sidecar.ensure_aligner), model, on_phase, cancel_event
            )
            # Started with its aligner now, or transcribe_path would restart it.
            load_options["timestamps"] = True
        await asyncio.to_thread(
            holds_inference(
                functools.partial(
                    load_stt, model, serving_engine, cancel_event, device = device, **load_options
                )
            )
        )
        loaded = getattr(sidecar, "loaded_model", None)
        if loaded is not None and loaded == _stt_resolved_model_id(model, serving_engine):
            account_access.note_resident_account(f"stt:{serving_engine}", loaded)
        if source_path is not None:
            result = await asyncio.to_thread(
                holds_inference(
                    functools.partial(
                        sidecar.transcribe_path,
                        source_path,
                        model,
                        language,
                        timestamps = timestamps,
                        cancel_event = cancel_event,
                        on_phase = on_phase,
                    )
                )
            )
        elif on_progress is not None and serving_engine in ("transformers", "mtmd"):
            result = await asyncio.to_thread(
                holds_inference(transcribe),
                raw,
                model,
                language,
                fast,
                cancel_event,
                on_progress = on_progress,
            )
        elif cancel_event is None:
            result = await asyncio.to_thread(
                holds_inference(transcribe), raw, model, language, fast
            )
        else:
            result = await asyncio.to_thread(
                holds_inference(transcribe),
                raw,
                model,
                language,
                fast,
                cancel_event,
            )
    except asyncio.CancelledError:
        if cancel_event is not None:
            # cancel_transcription takes a lock a load can hold, so inline would stall the loop.
            threading.Thread(
                target = sidecar.cancel_transcription,
                args = (cancel_event,),
                daemon = True,
            ).start()
        raise
    except SttTranscriptionCancelledError as e:
        raise HTTPException(status_code = 499, detail = str(e))
    except SttUnavailableError as e:
        raise HTTPException(status_code = 501, detail = str(e))
    except SttLoadCancelledError as e:
        raise HTTPException(status_code = 409, detail = str(e))
    except SttModelNotDownloadedError as e:
        raise HTTPException(status_code = 409, detail = str(e))
    except SttModelBusyError as e:
        # Another client switching the dictation model is normal concurrency; say retry, not a failure.
        raise HTTPException(status_code = 409, detail = str(e))
    except SttModelIdError as e:
        raise HTTPException(status_code = 422, detail = str(e))
    except SttModelCompatibilityError as e:
        raise HTTPException(status_code = 422, detail = str(e))
    except SttLanguageError as e:
        raise HTTPException(status_code = 422, detail = str(e))
    except SttAudioTooLongError as e:
        raise HTTPException(status_code = 413, detail = str(e))
    except SttAudioDecodeError as e:
        raise HTTPException(status_code = 400, detail = str(e))
    except Exception as e:
        logger.error(f"Transcription error: {e}", exc_info = True)
        raise HTTPException(status_code = 500, detail = safe_error_detail(e))
    finally:
        if disconnect_watcher is not None:
            await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
    speakers = result.get("speakers") if isinstance(result, dict) else None
    if isinstance(speakers, list) and all(isinstance(s, str) for s in speakers):
        from core.inference.stt_capabilities import label_speakers
        result = {**result, "speakers": label_speakers(speakers)}
    return result


@studio_router.post("/audio/transcribe")
async def transcribe_audio(
    payload: TranscribeRequest,
    request: Request,
    current_subject: str = Depends(get_current_subject),
):
    """Transcribe dictation audio to text via the STT sidecar.

    Runs alongside the chat model without evicting it, so any model (including
    text-only ones) can be driven by voice.
    """
    b64 = payload.audio or ""
    if not b64:
        raise HTTPException(status_code = 400, detail = "No audio provided.")
    if len(b64) > _MAX_AUDIO_B64_CHARS:
        raise HTTPException(status_code = 413, detail = "Audio is too large.")
    try:
        raw = base64.b64decode(b64, validate = True)
    except Exception:
        raise HTTPException(status_code = 400, detail = "Audio is not valid base64.")
    # Cancel on disconnect like the raw/OpenAI routes, or the sidecar keeps transcribing under its lock.
    return await _transcribe_audio_bytes(
        raw,
        payload.model,
        payload.language,
        payload.fast,
        payload.engine,
        request,
        payload.device,
    )


@studio_router.post("/audio/transcribe/raw")
async def transcribe_audio_raw(
    request: Request,
    model: Optional[str] = None,
    language: Optional[str] = None,
    fast: bool = False,
    engine: Optional[str] = None,
    # Literal so a misspelled "cpu" is a 422, not a silent fallback to GPU.
    device: Optional[Literal["auto", "cpu", "gpu"]] = None,
    current_subject: str = Depends(get_current_subject),
    stream: bool = False,
    title: str = Query("Recording", max_length = 255),
):
    """Transcribe a raw audio body without base64 or JSON conversion overhead."""
    chunks: list[bytes] = []
    size = 0
    async for chunk in request.stream():
        size += len(chunk)
        if size > _MAX_AUDIO_RAW_BYTES:
            raise HTTPException(status_code = 413, detail = "Audio is too large.")
        chunks.append(chunk)
    if stream:
        from core.inference.transcript_stream import stream_transcript
        raw = b"".join(chunks)
        return StreamingResponse(
            stream_transcript(
                lambda on_progress: _transcribe_audio_result(
                    raw, model, language, fast, engine, None, device, on_progress
                ),
                title,
            ),
            media_type = "application/x-ndjson",
            headers = {"Cache-Control": "no-store", "X-Accel-Buffering": "no"},
        )
    return JSONResponse(
        content = await _transcribe_audio_result(
            b"".join(chunks), model, language, fast, engine, request, device
        )
    )


def _refuse_stt_caps(caps: dict, *, timestamps: bool, speakers: bool) -> None:
    """422 when the model cannot add what the transcript asks for."""
    if timestamps and caps["timestamps"] == "unsupported":
        raise HTTPException(
            status_code = 422,
            detail = "This model cannot add timestamps. Pick Qwen3-ASR (audio.cpp), Parakeet-TDT, "
            "MOSS-Transcribe-Diarize or VibeVoice-ASR.",
        )
    if speakers and not caps["speakers"]:
        raise HTTPException(
            status_code = 422,
            detail = "This model cannot tell speakers apart. Pick MOSS-Transcribe-Diarize or "
            "VibeVoice-ASR.",
        )


def _prepared_upload(raw: bytes, rate: int) -> Path:
    """An upload decoded to a mono WAV at ``rate`` in this account's inputs, for audio.cpp to read
    in place. The caller removes it."""
    from core.inference import audio_inputs

    directory = audio_inputs.inputs_dir()
    stem = uuid.uuid4().hex
    src = directory / f".{stem}.upload.tmp"
    dst = directory / f".{stem}.{rate}.wav"
    try:
        src.write_bytes(raw)
        # Refused past 30 minutes like every other transcription, never cut short.
        audio_inputs.transcode(src, dst, rate = rate, mono = True)
    finally:
        src.unlink(missing_ok = True)
    return dst


def _source_transcript(result: dict, source, speakers: bool) -> dict:
    out = dict(result)
    if not (speakers and out.get("speakers")):
        out.pop("speakers", None)
        if out.get("segments"):
            out["segments"] = [
                {k: v for k, v in s.items() if k != "speaker"} for s in out["segments"]
            ]
    out["source"] = {"kind": source.kind, "id": source.id, "name": source.name}
    out["timestamps"] = bool(out.get("segments"))
    return out


async def _external_source_transcript(
    body: TranscribeSourceRequest, source, request: Request
) -> dict:
    from core.inference import audio_inputs, audio_metrics

    def _encode():
        path = audio_inputs.prepared_path(source, 16000)
        flac, _ = audio_inputs.encode_wav(path.read_bytes(), "flac")
        return audio_metrics.wav_seconds(path), flac

    try:
        duration, audio = await asyncio.to_thread(_encode)
    except audio_inputs.AudioInputError as exc:
        raise _audio_source_error(exc) from None
    if len(audio) > _MAX_AUDIO_RAW_BYTES:
        raise HTTPException(
            status_code = 413,
            detail = (
                f"This audio comes to {len(audio) / 2**20:.0f} MB, past the "
                f"{_MAX_AUDIO_RAW_BYTES // 2**20} MB a connection takes. Trim it, or pick an "
                "on-device model."
            ),
        )
    response = await _external_stt_transcription(
        provider_id = body.provider_id,
        raw = audio,
        filename = "audio.flac",
        content_type = "audio/flac",
        model = body.model,
        language = body.language,
        response_format = "verbose_json" if body.timestamps else "json",
        timestamp_granularities = ["segment", "word"] if body.timestamps else None,
        encrypted_api_key = None,
        request = request,
    )
    data = json.loads(response.body) if "json" in response.media_type else {}
    if not isinstance(data, dict) or not isinstance(data.get("text"), str):
        raise HTTPException(status_code = 502, detail = "The connection returned no transcript.")

    def spans(key: str, text_key: str) -> list[dict]:
        return [
            {
                "start": s.get("start"),
                "end": s.get("end"),
                text_key: str(s.get(text_key, "")).strip(),
            }
            for s in data.get(key) or ()
            if isinstance(s, dict)
        ]

    result = {
        "text": data["text"].strip(),
        "model": body.model,
        "language": data.get("language") or body.language,
        "duration": duration,
    }
    if body.timestamps:
        result.update(segments = spans("segments", "text"), words = spans("words", "word"))
    return _source_transcript(result, source, False)


@studio_router.post("/audio/transcribe/source")
async def transcribe_audio_source(
    body: TranscribeSourceRequest,
    request: Request,
    current_subject: str = Depends(get_current_subject),
):
    """Transcribe Audio page audio named by id, streamed as NDJSON and saved to history."""
    from core.inference import audio_inputs, stt_capabilities, stt_details
    from core.inference.transcript_stream import stream_transcript

    if body.provider_id is not None:
        try:
            source = await asyncio.to_thread(
                audio_inputs.resolve_source, body.source.model_dump(exclude_none = True)
            )
        except audio_inputs.AudioInputError as exc:
            raise _audio_source_error(exc) from None
        return StreamingResponse(
            stream_transcript(
                lambda _on_progress: _external_source_transcript(body, source, request),
                body.title or source.name,
            ),
            media_type = "application/x-ndjson",
            headers = {"Cache-Control": "no-store", "X-Accel-Buffering": "no"},
        )

    engine = body.engine or await asyncio.to_thread(_stt_engine_for_model, body.model)
    serving_engine = _resolve_serving_stt_engine(engine)
    caps = await asyncio.to_thread(stt_capabilities.capabilities_for, body.model, serving_engine)
    _refuse_stt_caps(caps, timestamps = body.timestamps, speakers = body.speakers)
    rate = stt_details.FIXED_SPAN_RATES.get(caps["family"], 16000)

    def _prepare():
        source = audio_inputs.resolve_source(body.source.model_dump(exclude_none = True))
        return source, audio_inputs.prepared_path(source, rate)

    try:
        source, path = await asyncio.to_thread(_prepare)
    except audio_inputs.AudioInputError as exc:
        raise _audio_source_error(exc) from None

    async def _run(on_progress):
        result = await _transcribe_audio_result(
            b"",
            body.model,
            body.language,
            False,
            engine,
            None,
            body.device,
            on_progress,
            source_path = path,
            timestamps = body.timestamps,
        )
        return _source_transcript(result, source, body.speakers)

    return StreamingResponse(
        stream_transcript(_run, body.title or source.name),
        media_type = "application/x-ndjson",
        headers = {"Cache-Control": "no-store", "X-Accel-Buffering": "no"},
    )


@studio_router.get("/audio/stt/capabilities")
async def stt_model_capabilities(
    model: Optional[str] = Query(None, max_length = 512),
    engine: Optional[str] = Query(None, max_length = 64),
    current_subject: str = Depends(get_current_subject),
):
    """What ``model`` can add to a transcript (timestamps, speakers) and where it runs. Offline."""
    from core.inference import stt_capabilities
    return await asyncio.to_thread(stt_capabilities.capabilities_for, model, engine)


@router.post("/audio/cancel")
async def cancel_audio_run(
    body: AudioCancelRequest, current_subject: str = Depends(get_current_subject)
):
    """Stop the /audio/run sent with this cancel_id, as a disconnect would: it answers 499 and saves
    nothing. A cancel that arrives first is kept for 30 s. Returns {"cancelled": N}."""
    return {"cancelled": _cancel_by_cancel_id_or_stash(("audio", body.cancel_id))}


_ANALYZE_MAX_SECONDS = 600.0


def _analyze_metrics(path: Path) -> dict[str, Any]:
    """Metrics for a PCM or float WAV as is; anything else is decoded to a temporary 16-bit WAV first."""
    import wave

    from core.inference import audio_inputs, audio_metrics

    try:
        if audio_metrics.wav_seconds(path) > _ANALYZE_MAX_SECONDS:
            raise audio_inputs.AudioInputError(413, "Audio is longer than 10 minutes.")
        return audio_metrics.measure_file(path)
    except audio_inputs.AudioInputError:
        raise
    except (wave.Error, EOFError, ValueError):
        pass
    decoded = audio_inputs.inputs_dir() / f".analyze-{uuid.uuid4().hex}.wav"
    try:
        audio_inputs.transcode(path, decoded, max_seconds = _ANALYZE_MAX_SECONDS)
        return audio_metrics.measure_file(decoded)
    finally:
        decoded.unlink(missing_ok = True)


async def _analyze_transcript(source, expected_text: str, request: Request) -> dict[str, Any]:
    """Transcribe with the resident speech-to-text model, else the default, and score the match."""
    from core.inference import audio_inputs, stt_capabilities, stt_details, stt_registry
    from core.inference.audio_metrics import match_score
    from core.inference.stt_sidecar import DEFAULT_STT_MODEL

    def usable(resident: Optional[str], name: str) -> bool:
        # A managed caller cannot use a resident model another account loaded outside its access.
        if not resident or not account_access.managed_account():
            return bool(resident)
        try:
            account_access.require_model_access(_stt_repo_reference(resident, name))
        except HTTPException:
            return False
        return True

    model, engine = DEFAULT_STT_MODEL, None
    for name in stt_registry.STT_ENGINES:
        resident = await asyncio.to_thread(_stt_resident_model, name)
        if await asyncio.to_thread(usable, resident, name):
            model, engine = resident, name
            break
    serving_engine = _resolve_serving_stt_engine(engine)
    caps = await asyncio.to_thread(stt_capabilities.capabilities_for, model, serving_engine)
    rate = stt_details.FIXED_SPAN_RATES.get(caps["family"], 16000)
    try:
        path = await asyncio.to_thread(audio_inputs.prepared_path, source, rate)
    except audio_inputs.AudioInputError as exc:
        raise _audio_source_error(exc) from None
    result = await _transcribe_audio_result(
        b"", model, None, False, engine, request, None, source_path = path
    )
    transcript = str(result.get("text") or "").strip()
    # Word edit distance grows with both lengths, so it stays off the event loop.
    score = await asyncio.to_thread(match_score, expected_text, transcript)
    return {"transcript": transcript, "stt_model": model, "match_score": score}


@router.post("/audio/analyze", response_model = AudioAnalyzeResponse)
async def analyze_audio(
    body: AudioAnalyzeRequest,
    request: Request,
    current_subject: str = Depends(get_current_subject),
):
    """Measure an upload, history clip or saved voice: duration, loudness (LUFS), true peak,
    clipping and the span that holds sound. With expected_text, also the transcript and how well
    it matches. Nothing is saved."""
    from core.inference import audio_inputs

    ref = body.model_dump(include = {"input_id", "clip_id", "voice_id"}, exclude_none = True)
    try:
        source = await asyncio.to_thread(audio_inputs.resolve_source, ref)
        metrics = await asyncio.to_thread(_analyze_metrics, source.path)
    except audio_inputs.AudioInputError as exc:
        raise _audio_source_error(exc) from None
    if body.expected_text is not None:
        metrics.update(await _analyze_transcript(source, body.expected_text, request))
    return AudioAnalyzeResponse(**metrics)


# =====================================================================

# OpenAI-Compatible Chat Completions  (/chat/completions)
# =====================================================================


def _audio_decoder_is_available() -> bool:
    """Whether _decode_audio_base64 can run here; it needs torchaudio, which a
    GGUF-only install does not ship. find_spec keeps this off the import path."""
    try:
        from importlib.util import find_spec
        return find_spec("torchaudio") is not None
    except Exception:
        return False


def _decode_audio_base64(b64: str) -> "np.ndarray":
    """Decode base64 audio (any format) → float32 numpy array at 16kHz."""
    import torchaudio
    import tempfile
    import os
    from utils.media_playlist import refuse_playlist
    from utils.paths import ensure_dir, tmp_root

    raw = base64.b64decode(b64)
    # torchaudio and torchcodec open the file through FFmpeg, which follows playlist entries.
    refuse_playlist(raw)
    # torchaudio.load needs a path or file-like with a format hint; write a
    # temp file so it can auto-detect the format.
    with tempfile.NamedTemporaryFile(
        suffix = ".audio",
        delete = False,
        dir = str(ensure_dir(tmp_root())),
    ) as tmp:
        tmp.write(raw)
        tmp_path = tmp.name
    try:
        # Compressed audio can hold hours of PCM; bound the decode rather than check after.
        try:
            probe = torchaudio.info(tmp_path)
            rate = int(getattr(probe, "sample_rate", 0) or 0)
            frames = int(getattr(probe, "num_frames", 0) or 0)
            channels = max(1, int(getattr(probe, "num_channels", 1) or 1))
        except Exception:  # noqa: BLE001 - a container info cannot read is still loadable
            rate, frames, channels = 0, 0, 1
        limit = rate * _audio_seconds_cap()
        if limit and frames > limit:
            raise _DecodedAudioTooLongError(
                f"decoded audio exceeds the {_MAX_AUDIO_SECONDS // 60}-minute limit"
            )
        # load() materializes all channels; only safe when length is known and fits the cap.
        if limit and frames and frames * channels <= _decoded_samples_cap():
            # Cap with both limits: info() may understate num_frames.
            read_frames = min(limit, _decoded_samples_cap() // channels)
            waveform, sr = torchaudio.load(tmp_path, num_frames = read_frames + 1)
        else:
            import torch
            try:
                samples, sr = _decode_audio_mono(raw)
            except RuntimeError:
                # torchaudio 2.9 load() decodes the whole file before slicing; bound via torchcodec instead.
                waveform, sr = _decode_audio_with_torchcodec(tmp_path)
            else:
                waveform = torch.from_numpy(samples).unsqueeze(0)
    finally:
        os.unlink(tmp_path)

    # Backstop for a container that reported neither rate nor length.
    if (sr > 0 and waveform.shape[-1] > sr * _audio_seconds_cap()) or (
        waveform.shape[-1] * waveform.shape[0] > _decoded_samples_cap()
    ):
        raise _DecodedAudioTooLongError(
            f"decoded audio exceeds the {_MAX_AUDIO_SECONDS // 60}-minute limit"
        )

    if waveform.shape[0] > 1:
        waveform = waveform.mean(dim = 0, keepdim = True)

    if sr != 16000:
        resampler = torchaudio.transforms.Resample(orig_freq = sr, new_freq = 16000)
        waveform = resampler(waveform)

    return waveform.squeeze(0).numpy()


# base64 inflates ~4/3; _MAX_AUDIO_SECONDS bounds decoded length of compressed files.
_MAX_AUDIO_RAW_BYTES = STT_AUDIO_RAW_MAX_BYTES
_MAX_AUDIO_B64_CHARS = STT_AUDIO_B64_MAX_CHARS
# Padded base64 of the composer's 64 MB, rounded up (flooring refused exact-size files).
_MAX_VIDEO_BYTES = 64 * 1024 * 1024
_MAX_VIDEO_B64_CHARS = 4 * math.ceil(_MAX_VIDEO_BYTES / 3)
# Longest scheme named back to the caller; bounds the scan over a megabytes-long clip.
_MAX_VIDEO_SCHEME_CHARS = 16
# llama-server's fetch follows redirects, so remote clips are refused entirely (SSRF).
# Each clip spawns ffprobe+ffmpeg; 4 bounds process launches per request.
_MAX_VIDEO_CLIPS_PER_REQUEST = 4
_REMOTE_VIDEO_REFUSAL = (
    400,
    "Remote video URLs are not supported. Send the clip as a data URI instead.",
)
_MAX_AUDIO_SECONDS = 30 * 60
# Byte and duration caps cover all clips together; the count bounds per-clip decode cost.
_MAX_AUDIO_CLIPS_PER_REQUEST = 8
_AUDIO_CLIP_B64_SLACK_CHARS = 64
# Duration cap is rate-relative; this bounds memory for high-rate containers.
_MAX_DECODED_SAMPLES = 48_000 * _MAX_AUDIO_SECONDS
# One streamed block across all channels; 4 MB float32, held twice.
_MAX_DECODE_BLOCK_SAMPLES = 1 << 20
# Resample slice, counted on the side with most samples: a few MB of float64 at any length.
_RESAMPLE_SLICE_SAMPLES = 1 << 18
_WAV_HEADER_BYTES = 44
_MIN_TRANSCODE_AUDIO_SAMPLE_RATE = 8000


class _DecodedAudioTooLongError(ValueError):
    """Decoded audio crossed the duration cap before it could be buffered."""


# (seconds, samples) the current decode may use: what earlier clips in the request left over.
_AUDIO_BUDGET_LEFT: "contextvars.ContextVar[Optional[tuple[int, int]]]" = contextvars.ContextVar(
    "_AUDIO_BUDGET_LEFT", default = None
)


def _audio_seconds_cap() -> int:
    left = _AUDIO_BUDGET_LEFT.get()
    return _MAX_AUDIO_SECONDS if left is None else min(left[0], _MAX_AUDIO_SECONDS)


def _decoded_samples_cap() -> int:
    left = _AUDIO_BUDGET_LEFT.get()
    if left is None or _MAX_AUDIO_SECONDS <= 0:
        return _MAX_DECODED_SAMPLES
    scaled = _MAX_DECODED_SAMPLES * _audio_seconds_cap() // _MAX_AUDIO_SECONDS
    return min(scaled, left[1])


def _decode_within(
    seconds_used: float,
    decode,
    *args,
    samples_used: int = 0,
):
    """Run ``decode`` capped to the duration and samples the earlier clips left."""
    seconds_left = math.ceil(_MAX_AUDIO_SECONDS - seconds_used)
    samples_left = _MAX_DECODED_SAMPLES - samples_used
    if seconds_left <= 0 or samples_left <= 0:
        raise _DecodedAudioTooLongError("combined audio exceeds the duration cap")
    token = _AUDIO_BUDGET_LEFT.set((seconds_left, samples_left))
    try:
        return decode(*args)
    finally:
        _AUDIO_BUDGET_LEFT.reset(token)


def _request_audio_clips(payload) -> list[str]:
    """Every recording the request carries, ``audio_base64`` first."""
    first = getattr(payload, "audio_base64", None)
    if not first:
        return []
    return [first, *(getattr(payload, "extra_audio_base64", None) or [])]


def _audio_too_large_detail(clip_count: int) -> str:
    if clip_count > 1:
        return "Audio files are too large (max ~25 MB per message, all files together)."
    return "Audio file is too large (max ~25 MB)."


def _request_audio_rejection(payload) -> Optional[tuple[int, str]]:
    """Refuse too many clips or too many combined bytes."""
    clips = _request_audio_clips(payload)
    if len(clips) > _MAX_AUDIO_CLIPS_PER_REQUEST:
        return (
            400,
            f"Too many audio files in one message (max {_MAX_AUDIO_CLIPS_PER_REQUEST}).",
        )
    # Slack for per-clip base64 padding and data: headers.
    budget = _MAX_AUDIO_B64_CHARS + _AUDIO_CLIP_B64_SLACK_CHARS * (len(clips) - 1)
    if sum(len(clip) for clip in clips) > budget:
        return (413, _audio_too_large_detail(len(clips)))
    return None


def _check_decoded_audio_budget(arrays: list) -> None:
    """Apply the duration cap to all decoded 16 kHz clips together."""
    if sum(len(array) for array in arrays) > 16000 * _MAX_AUDIO_SECONDS:
        raise _DecodedAudioTooLongError("combined audio exceeds the duration cap")


def _decode_audio_clips(clips: list[str]) -> list:
    """Decode clips in order, each capped to the duration the earlier ones left."""
    arrays: list = [_decode_audio_base64(clips[0])]
    for clip in clips[1:]:
        used = sum(len(array) for array in arrays) / 16000
        arrays.append(_decode_within(used, _decode_audio_base64, clip))
        _check_decoded_audio_budget(arrays)
    return arrays


def _audio_too_long_detail() -> str:
    """The one answer an overlong upload gets, whichever path found it out."""
    return f"Audio is too long (max {_MAX_AUDIO_SECONDS // 60} minutes)."


def _id3_tag_length(raw: bytes) -> int:
    """Bytes an ID3v2 tag takes before the first MPEG frame; its size bytes are synchsafe, top bit clear."""
    if len(raw) < 10 or raw[:3] != b"ID3" or any(byte & 0x80 for byte in raw[6:10]):
        return 0
    tag_size = 0
    for byte in raw[6:10]:
        tag_size = (tag_size << 7) | byte
    length = 10 + tag_size
    # ID3v2.4's optional footer is not included in the stored tag size.
    if raw[3] == 4 and raw[5] & 0x10:
        length += 10
    return length


def _sniff_audio_container(raw: bytes) -> Optional[str]:
    """Return 'wav' or 'mp3' if the bytes are a container llama-server accepts
    directly (so we can forward them untouched), else None (needs transcoding)."""
    if len(raw) >= 12 and raw[:4] == b"RIFF" and raw[8:12] == b"WAVE":
        return "wav"

    frame_offset = _id3_tag_length(raw)

    # Only Layer III (01) is mp3; Layer II is 10 and ADTS AAC uses 00.
    if len(raw) >= frame_offset + 2:
        first, second = raw[frame_offset : frame_offset + 2]
        version = (second >> 3) & 0x03
        layer = (second >> 1) & 0x03
        is_mpeg_sync = first == 0xFF and (second & 0xE0) == 0xE0
        if is_mpeg_sync and version != 0x01 and layer == 0x01:
            return "mp3"

    # ID3-only or malformed data must be decoded; trusting the tag reintroduces MP2/AAC collision.
    return None


# Index 0 is "free" and 15 invalid; both read as 0.
_MPEG_LAYER3_BITRATES = {
    3: (0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 0),
    2: (0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160, 0),
    0: (0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160, 0),
}
_MPEG_SAMPLE_RATES = {
    3: (44_100, 48_000, 32_000, 0),
    2: (22_050, 24_000, 16_000, 0),
    0: (11_025, 12_000, 8_000, 0),
}


def _decode_audio_with_torchcodec(path: str) -> "tuple[Any, int]":
    """Last-resort bounded reader for torchaudio-only installs: reads a bounded range via torchcodec, or refuses."""
    try:
        from torchcodec.decoders import AudioDecoder
    except Exception as e:  # noqa: BLE001 - no bounded reader, so no read
        raise RuntimeError(
            "this audio format could not be decoded; run `unsloth studio update` "
            "to install PyAV or convert it to wav, mp3, ogg or flac"
        ) from e

    decoder = AudioDecoder(path)
    metadata = decoder.metadata
    rate = int(getattr(metadata, "sample_rate", 0) or 0)
    if rate <= 0:
        raise RuntimeError(
            "this audio file does not report a sample rate, so it cannot be "
            "decoded within the size limit; convert it to wav or mp3"
        )
    duration = float(getattr(metadata, "duration_seconds", 0.0) or 0.0)
    if duration > _audio_seconds_cap():
        raise _DecodedAudioTooLongError(
            f"decoded audio exceeds the {_MAX_AUDIO_SECONDS // 60}-minute limit"
        )
    # A second past the clock, so a container understating its duration is still cut.
    channels = max(1, int(getattr(metadata, "num_channels", 1) or 1))
    seconds = min(_audio_seconds_cap() + 1, _decoded_samples_cap() / (rate * channels) + 1)
    samples = decoder.get_samples_played_in_range(0.0, seconds)
    return samples.data, rate


_WAVE_FORMAT_PCM = 0x0001
_WAVE_FORMAT_IEEE_FLOAT = 0x0003
_WAVE_FORMAT_EXTENSIBLE = 0xFFFE


def _wav_format_is_pcm(raw: bytes, body: int, size: int, format_tag: int) -> bool:
    """WAVE_FORMAT_EXTENSIBLE is PCM only via its SubFormat GUID, so the extension must be present."""
    if format_tag in (_WAVE_FORMAT_PCM, _WAVE_FORMAT_IEEE_FLOAT):
        return True
    if format_tag != _WAVE_FORMAT_EXTENSIBLE or size < 40 or body + 26 > len(raw):
        return False
    sub_format = int.from_bytes(raw[body + 24 : body + 26], "little")
    return sub_format in (_WAVE_FORMAT_PCM, _WAVE_FORMAT_IEEE_FLOAT)


def _wav_seconds(raw: bytes) -> Optional[float]:
    """Header arithmetic only, so a file forwarded without decoding can still be bounded."""
    if len(raw) < 12 or raw[:4] != b"RIFF" or raw[8:12] != b"WAVE":
        return None
    byte_rate = 0
    offset = 12
    while offset + 8 <= len(raw):
        chunk = raw[offset : offset + 4]
        size = int.from_bytes(raw[offset + 4 : offset + 8], "little")
        body = offset + 8
        if chunk == b"fmt " and size >= 16 and body + 16 <= len(raw):
            format_tag = int.from_bytes(raw[body : body + 2], "little")
            channels = int.from_bytes(raw[body + 2 : body + 4], "little")
            sample_rate = int.from_bytes(raw[body + 4 : body + 8], "little")
            declared_rate = int.from_bytes(raw[body + 8 : body + 12], "little")
            block_align = int.from_bytes(raw[body + 12 : body + 14], "little")
            bits = int.from_bytes(raw[body + 14 : body + 16], "little")
            if not _wav_format_is_pcm(raw, body, size, format_tag):
                # Only WAVE_FORMAT_PCM fixes blockAlign and byte rate; PCM math on other codecs understates length.
                return None
            # Measure frames as miniaudio does; trusting rate fields let inflated values hide length.
            frame_bytes = channels * bits // 8 if bits % 8 == 0 else block_align
            computed = sample_rate * frame_bytes
            byte_rate = computed or declared_rate
        elif chunk == b"data":
            if byte_rate <= 0:
                return None
            # Streaming writers may declare a size the file lacks; use the smaller.
            carried = len(raw) - body
            return (min(size, carried) if size else carried) / byte_rate
        # Chunks are padded to an even length, and the padding is not counted.
        offset = body + size + (size & 1)
    return None


def _mp3_trailer_length(raw: bytes, offset: int) -> int:
    """Counts only trailers with a stated length; matching TAG alone misread concatenated MP3 durations."""
    tail = raw[offset:]
    if tail[:3] == b"TAG":
        # ID3v1 and ID3v1.1 are both exactly 128 bytes.
        return 128 if len(tail) >= 128 else 0
    if tail[:3] == b"ID3":
        return _id3_tag_length(tail)
    if tail[:8] == b"APETAGEX" and len(tail) >= 32:
        # Size covers items + 32-byte footer, never the header.
        return int.from_bytes(tail[12:16], "little") + 32
    return 0


def _mp3_seconds(raw: bytes, cap: float) -> Optional[float]:
    """None when the walk cannot establish a length, such as unreadable bytes; the caller must bound it."""
    offset = _id3_tag_length(raw)
    seconds = 0.0
    frames = 0
    while offset + 4 <= len(raw):
        first, second, third = raw[offset], raw[offset + 1], raw[offset + 2]
        if first != 0xFF or (second & 0xE0) != 0xE0:
            break
        version = (second >> 3) & 0x03
        layer = (second >> 1) & 0x03
        if version == 0x01 or layer != 0x01:
            break
        bitrate = _MPEG_LAYER3_BITRATES[version][(third >> 4) & 0x0F] * 1000
        rate = _MPEG_SAMPLE_RATES[version][(third >> 2) & 0x03]
        if bitrate <= 0 or rate <= 0:
            break
        # MPEG-1 Layer III carries 1152 samples per frame, MPEG-2 and 2.5 half that.
        samples = 1152 if version == 0x03 else 576
        length = (samples // 8) * bitrate // rate + ((third >> 1) & 0x01)
        if length <= 4:
            break
        seconds += samples / rate
        frames += 1
        if seconds > cap:
            return seconds
        offset += length
    if not frames:
        return None
    # Longer tails must account for themselves to EOF, or unread bytes follow.
    while offset < len(raw):
        if len(raw) - offset < 4:
            return seconds
        length = _mp3_trailer_length(raw, offset)
        if length <= 0:
            return None
        offset += length
    return seconds


def _passthrough_audio_seconds(raw: bytes, container: str, cap: float) -> Optional[float]:
    """How long a container forwarded untouched runs, or None if unreadable."""
    if container == "wav":
        return _wav_seconds(raw)
    if container == "mp3":
        return _mp3_seconds(raw, cap)
    return None


def _mono_f32_to_wav_bytes(arr: "np.ndarray", sample_rate: int) -> bytes:
    """Stays torch-free for GGUF-only installs; the shared audio_codecs helper pulls torch in on import."""
    import io
    import numpy as np
    import wave

    if np.asarray(arr).size == 0:
        raise ValueError("decoded audio is empty")
    # One copy, then every stage in place to avoid whole-recording allocations.
    scratch = np.nan_to_num(np.asarray(arr, dtype = np.float32).ravel(), posinf = 0.0, neginf = 0.0)
    # Values are finite after the scrub, so min and max give the peak without an absolute-value copy.
    peak = max(abs(float(scratch.min())), abs(float(scratch.max())))
    if peak > 1.0:
        np.divide(scratch, peak, out = scratch)
    np.multiply(scratch, 32767.0, out = scratch)
    pcm = scratch.astype(np.int16)
    del scratch

    buf = io.BytesIO()
    with wave.open(buf, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(int(sample_rate))
        # The array itself, not a bytes copy of it: wave casts the buffer.
        wf.writeframes(pcm)
    return buf.getvalue()


def _resample_mono_linear(arr: "np.ndarray", source_rate: int, target_rate: int) -> "np.ndarray":
    """Small numpy-only resampler for upload size limiting."""
    import numpy as np

    if source_rate <= 0 or target_rate <= 0 or source_rate == target_rate:
        return arr
    count = len(arr)
    if count == 0:
        return arr
    duration = count / float(source_rate)
    target_len = max(1, int(round(duration * target_rate)))
    if target_len == count:
        return arr
    # Build grid slices as index * step; full float64 grids were the largest transient.
    source_step = duration / count
    target_step = duration / target_len
    out = np.empty(target_len, dtype = np.float32)
    # Sized from the source window: np.interp widens that window to float64.
    ratio = max(1.0, count / target_len)
    slice_len = max(1, int(_RESAMPLE_SLICE_SAMPLES / ratio))
    for start in range(0, target_len, slice_len):
        stop = min(start + slice_len, target_len)
        target_x = np.arange(start, stop, dtype = np.float64) * target_step
        # Widened a sample each side so results match the whole-array pass.
        first = max(0, int(target_x[0] / source_step) - 1)
        last = min(count, int(target_x[-1] / source_step) + 3)
        source_x = np.arange(first, last, dtype = np.float64) * source_step
        out[start:stop] = np.interp(target_x, source_x, arr[first:last])
    return out


def _fit_transcoded_audio_to_wav_cap(
    arr: "np.ndarray",
    sample_rate: int,
    cap: Optional[int] = None,
) -> "tuple[np.ndarray, int]":
    """Downsample only when needed so transcoded WAV fits ``cap`` (default: the upload cap)."""
    cap = _MAX_AUDIO_RAW_BYTES if cap is None else cap
    if sample_rate <= 0:
        raise ValueError("decoded audio has an invalid sample rate")
    wav_bytes = _WAV_HEADER_BYTES + len(arr) * 2
    if wav_bytes <= cap:
        return arr, sample_rate

    duration = len(arr) / float(sample_rate)
    max_samples = max(1, (cap - _WAV_HEADER_BYTES) // 2)
    target_rate = int(max_samples // duration)
    if target_rate < _MIN_TRANSCODE_AUDIO_SAMPLE_RATE:
        raise ValueError("decoded audio exceeds the transcoded WAV size limit")
    target_rate = min(sample_rate, target_rate)
    fitted = _resample_mono_linear(arr, sample_rate, target_rate)
    if _WAV_HEADER_BYTES + len(fitted) * 2 > cap:
        raise ValueError("decoded audio exceeds the transcoded WAV size limit")
    return fitted, target_rate


def _decode_audio_mono_with_soundfile(raw: bytes) -> "tuple[np.ndarray, int]":
    """Decode libsndfile-supported audio in bounded blocks."""
    import io

    import numpy as np
    import soundfile as sf

    sample_count = 0
    joined = None
    with sf.SoundFile(io.BytesIO(raw)) as source:
        sample_rate = int(source.samplerate)
        if sample_rate <= 0:
            raise ValueError("decoded audio has an invalid sample rate")
        # Bound the block by channels too: blocks() allocates frames * channels.
        channels = max(1, int(getattr(source, "channels", 1) or 1))
        block_frames = max(1, min(sample_rate, 65_536, _MAX_DECODE_BLOCK_SAMPLES // channels))
        ceiling = _decoded_sample_ceiling(sample_rate)
        # Declared length is only a sizing hint, never trusted.
        declared = int(getattr(source, "frames", 0) or 0)
        if declared > ceiling:
            declared = 0
        for block in source.blocks(
            blocksize = block_frames,
            dtype = "float32",
            always_2d = False,
        ):
            sample_count += len(block)
            if sample_count > ceiling:
                raise _DecodedAudioTooLongError(
                    f"decoded audio exceeds the {_MAX_AUDIO_SECONDS // 60}-minute limit"
                )
            if block.ndim > 1:
                block = block.mean(axis = 1)
            if joined is None:
                joined = np.empty(min(max(len(block), 1), ceiling), dtype = np.float32)
            if sample_count > len(joined):
                # Double for amortised growth; adopt the declared length only after half is decoded, since an unread header can force a large allocation.
                target = max(sample_count, 2 * len(joined))
                if declared > target and sample_count * 2 >= declared:
                    target = declared
                grown = np.empty(min(target, ceiling), dtype = np.float32)
                grown[: sample_count - len(block)] = joined[: sample_count - len(block)]
                joined = grown
            # One append-only buffer keeps decode order (separate overflow lists reordered audio).
            joined[sample_count - len(block) : sample_count] = block
    if not sample_count:
        raise ValueError("audio container decoded to no samples")
    # A slice keeps the whole allocation alive; copy when the buffer was oversized.
    if sample_count * 2 < len(joined):
        return joined[:sample_count].copy(), sample_rate
    return joined[:sample_count], sample_rate


def _decoded_sample_ceiling(sample_rate: int) -> int:
    """Caps decoded samples at the smaller of the duration limit and a rate-independent sample count."""
    return min(sample_rate * _audio_seconds_cap(), _decoded_samples_cap())


def _av_expected_samples(container, sample_rate: int, ceiling: int) -> int:
    """The container duration is only a hint for the first allocation, clamped to the ceiling."""
    import av

    micros = getattr(container, "duration", None) or 0
    seconds = float(micros) / float(av.time_base) if micros > 0 else 0.0
    if seconds <= 0.0:
        stream = container.streams.audio[0]
        if stream.duration and stream.time_base:
            seconds = float(stream.duration * stream.time_base)
    if not (seconds > 0.0):
        # Nothing declared, so start at a minute and grow.
        seconds = 60.0
    return min(int(seconds * sample_rate) + 1, ceiling)


# An upload probed as a concat playlist would otherwise decode the files it names.
NO_PROTOCOLS = {"protocol_whitelist": "none"}


def _av_open(av, source, **extra):
    """Open ``source`` for reading with undecodable metadata ignored. PyAV 19 removed ``metadata_errors`` from ``av.open``, so passing it there raises TypeError before anything is read; retry without it."""
    try:
        return av.open(source, mode = "r", metadata_errors = "ignore", **extra)
    except TypeError as exc:
        if "metadata_errors" not in str(exc):
            raise
        # format = None is PyAV's own default (probe the container); spelling it keeps this call
        # distinguishable from Path.open for the text-encoding lint.
        return av.open(source, mode = "r", format = None, **extra)


def _decode_audio_mono_with_av(raw: bytes) -> "tuple[np.ndarray, int]":
    """Decode an audio container with PyAV's bundled FFmpeg libraries."""
    import io

    import av
    import numpy as np

    # Write blocks into one buffer: collecting then joining kept two copies resident.
    joined = None
    sample_rate = 0
    sample_count = 0
    ceiling = 0
    resampler = None

    def append_resampled(resampled) -> None:
        nonlocal joined, sample_count
        block = resampled.to_ndarray().reshape(-1)
        sample_count += len(block)
        if sample_count > ceiling:
            raise _DecodedAudioTooLongError(
                f"decoded audio exceeds the {_MAX_AUDIO_SECONDS // 60}-minute limit"
            )
        if sample_count > len(joined):
            # Doubling amortises growth; clamp it to the ceiling too.
            grown = np.empty(min(max(sample_count, 2 * len(joined)), ceiling), dtype = np.float32)
            grown[: sample_count - len(block)] = joined[: sample_count - len(block)]
            joined = grown
        joined[sample_count - len(block) : sample_count] = block

    with _av_open(av, io.BytesIO(raw), options = NO_PROTOCOLS) as container:
        if not container.streams.audio:
            raise ValueError("audio container has no audio stream")
        for frame in container.decode(audio = 0):
            if resampler is None:
                sample_rate = int(frame.sample_rate or 0)
                if sample_rate <= 0:
                    raise ValueError("decoded audio has an invalid sample rate")
                resampler = av.AudioResampler(
                    format = "flt",
                    layout = "mono",
                    rate = sample_rate,
                )
                ceiling = _decoded_sample_ceiling(sample_rate)
                joined = np.empty(
                    _av_expected_samples(container, sample_rate, ceiling), dtype = np.float32
                )
            for resampled in resampler.resample(frame):
                append_resampled(resampled)
        if resampler is not None:
            for resampled in resampler.resample(None):
                append_resampled(resampled)
    if not sample_count:
        raise ValueError("audio container decoded to no samples")
    # A slice pins the whole buffer, so copy when the declared duration overstated it (under half used).
    if sample_count * 2 < len(joined):
        return joined[:sample_count].copy(), sample_rate
    return joined[:sample_count], sample_rate


def _decode_audio_mono(raw: bytes) -> "tuple[np.ndarray, int]":
    """Decode audio bytes to (mono float32 array, native sample_rate).

    soundfile (libsndfile) reads wav/mp3/ogg/flac in bounded blocks. PyAV is
    installed in every Studio environment and uses its bundled FFmpeg libraries
    for containers including m4a/webm/WMA/AMR. librosa remains the final fallback
    in full ML environments, but is absent from no-torch GGUF-only installs.
    """
    from utils.media_playlist import refuse_playlist

    # Checked once up front so no decoder below, the librosa fallback included, sees a playlist.
    refuse_playlist(raw)
    try:
        arr, sr = _decode_audio_mono_with_soundfile(raw)
    except _DecodedAudioTooLongError:
        raise
    except Exception:
        try:
            arr, sr = _decode_audio_mono_with_av(raw)
        except _DecodedAudioTooLongError:
            raise
        except Exception as av_error:
            try:
                import librosa
            except ModuleNotFoundError:
                raise RuntimeError(
                    "this audio format could not be decoded; run `unsloth studio update` "
                    "to install PyAV or convert it to wav, mp3, ogg or flac"
                ) from av_error
            import os
            import tempfile
            from utils.paths import ensure_dir, tmp_root

            with tempfile.NamedTemporaryFile(
                suffix = ".audio",
                delete = False,
                dir = str(ensure_dir(tmp_root())),
            ) as tmp:
                tmp.write(raw)
                tmp_path = tmp.name
            try:
                # Native rate first so the window bounds samples as well as seconds.
                try:
                    probe_rate = int(librosa.get_samplerate(tmp_path) or 0)
                except Exception:  # noqa: BLE001 - handled below
                    probe_rate = 0
                if probe_rate <= 0:
                    # Without the rate no window bounds the read; this is the last fallback.
                    raise RuntimeError(
                        "this audio file does not report a sample rate, so it cannot "
                        "be decoded within the size limit; convert it to wav or mp3"
                    )
                window = min(
                    float(_audio_seconds_cap() + 1), _decoded_samples_cap() / probe_rate + 1
                )
                arr, sr = librosa.load(tmp_path, sr = None, mono = True, duration = window)
            finally:
                os.unlink(tmp_path)
    if arr.ndim > 1:
        arr = arr.mean(axis = 1)
    if (sr > 0 and len(arr) > sr * _audio_seconds_cap()) or len(arr) > _decoded_samples_cap():
        raise _DecodedAudioTooLongError(
            f"decoded audio exceeds the {_MAX_AUDIO_SECONDS // 60}-minute limit"
        )
    return arr, sr


def _prepare_audio_for_llama(b64: str) -> tuple[str, str]:
    """Passes wav and mp3 through untouched, since llama-server takes only those; others become mono WAV. Blocking: call via a thread from async paths."""
    return _prepare_audio_clips_for_llama([b64])[0]


def _prepare_audio_clips_for_llama(clips: list[str]) -> list[tuple[str, str]]:
    """Clips share one byte and duration budget, so the result ignores attachment order. Blocking: call via a thread from async paths."""
    stripped = [_strip_audio_data_uri(clip) for clip in clips]
    raws = [base64.b64decode(clip) for clip in stripped]
    passthrough = [_llama_passthrough_audio(raw) for raw in raws]
    wav_budget = _MAX_AUDIO_RAW_BYTES - sum(
        len(raw) for raw, kept in zip(raws, passthrough) if kept is not None
    )
    total_seconds = 0.0
    samples_held = 0
    decoded: dict[int, tuple] = {}
    for index, (raw, kept) in enumerate(zip(raws, passthrough)):
        if kept is not None:
            seconds = kept[1]
        else:
            arr, sr = (
                _decode_within(total_seconds, _decode_audio_mono, raw, samples_used = samples_held)
                if index
                else _decode_audio_mono(raw)
            )
            decoded[index] = (arr, sr)
            samples_held += len(arr)
            seconds = len(arr) / float(sr) if sr else 0.0
        total_seconds += seconds
        if total_seconds > _MAX_AUDIO_SECONDS:
            raise _DecodedAudioTooLongError(
                f"audio exceeds the {_MAX_AUDIO_SECONDS // 60}-minute limit"
            )
    shared_rate = (
        _shared_wav_rate([(len(a), sr) for a, sr in decoded.values()], wav_budget)
        if len(decoded) > 1
        else None
    )
    prepared: list[tuple[str, str]] = []
    for index, (clip, kept) in enumerate(zip(stripped, passthrough)):
        if kept is not None:
            prepared.append((clip, kept[0]))
            continue
        arr, sr = decoded.pop(index)
        if shared_rate is None:
            arr, sr = _fit_transcoded_audio_to_wav_cap(arr, sr, cap = wav_budget)
        elif shared_rate < sr:
            if shared_rate < _MIN_TRANSCODE_AUDIO_SAMPLE_RATE:
                raise ValueError("decoded audio exceeds the transcoded WAV size limit")
            arr, sr = _resample_mono_linear(arr, sr, shared_rate), shared_rate
        prepared.append((base64.b64encode(_mono_f32_to_wav_bytes(arr, sr)).decode("ascii"), "wav"))
    return prepared


def _shared_wav_rate(clips: list[tuple[int, int]], budget: int) -> int:
    """Highest rate at which every (samples, rate) clip, capped to it, fits ``budget`` as WAV."""

    def samples_at(n: int, sr: int, rate: int) -> int:
        # _resample_mono_linear's own output length, so the budget holds exactly.
        return n if rate >= sr or sr <= 0 else max(1, int(round(n / float(sr) * rate)))

    def total(rate: int) -> int:
        return sum(_WAV_HEADER_BYTES + 2 * samples_at(n, sr, rate) for n, sr in clips)

    low, high = 0, max(sr for _, sr in clips)
    if total(high) <= budget:
        return high
    while low < high:
        mid = (low + high + 1) // 2
        if total(mid) <= budget:
            low = mid
        else:
            high = mid - 1
    return low


def _strip_audio_data_uri(b64: str) -> str:
    if b64.startswith("data:"):
        return b64.split(",", 1)[1] if "," in b64 else ""
    return b64


def _llama_passthrough_audio(raw: bytes) -> Optional[tuple[str, float]]:
    """(container, seconds) if the upload can be forwarded as is, else None."""
    passthrough = _sniff_audio_container(raw)
    if passthrough is None:
        return None
    # Forwarding skips the bounded decoders: cap duration from headers (16 kbps MP3 = hours).
    seconds = _passthrough_audio_seconds(raw, passthrough, _MAX_AUDIO_SECONDS)
    if seconds is not None and seconds > _MAX_AUDIO_SECONDS:
        raise _DecodedAudioTooLongError(
            f"audio exceeds the {_MAX_AUDIO_SECONDS // 60}-minute limit"
        )
    # No stated length (junk MPEG bytes, WAV without data chunk) means decode, not forward.
    if seconds is None:
        return None
    return passthrough, seconds


_VIDEO_INPUT_REFUSAL = (
    "Video input is only supported on a local GGUF or MLX model with video support."
)


def _local_video_clip(payload, model_info) -> str:
    """Serves a video_url part the same as the legacy field; refuses a model with no video input."""
    if not model_info.get("has_video_input"):
        raise HTTPException(status_code = 400, detail = _VIDEO_INPUT_REFUSAL)
    clips = _request_video_clips(payload)
    if not clips:
        raise HTTPException(status_code = 400, detail = "Could not read the provided video file.")
    # Generation takes one video kwarg; extra clips would be silently dropped.
    if len(clips) > 1:
        raise HTTPException(
            status_code = 400,
            detail = "Only one video is supported per request on this model.",
        )
    # MLX would move an older-turn clip onto the newest turn.
    if _video_is_on_an_older_turn(payload):
        raise HTTPException(
            status_code = 400,
            detail = "A video must be attached to the latest message on this model.",
        )
    # Refused everywhere, so the message must not send the caller to GGUF for it.
    if _is_remote_video(clips[0]):
        raise HTTPException(status_code = _REMOTE_VIDEO_REFUSAL[0], detail = _REMOTE_VIDEO_REFUSAL[1])
    # _request_video_rejection may not have run; reject unsupported schemes here too.
    scheme_rejection = _video_scheme_rejection(clips[0])
    if scheme_rejection is not None:
        raise HTTPException(status_code = scheme_rejection[0], detail = scheme_rejection[1])
    video_b64, rejection = _video_b64_rejection(clips[0])
    if rejection is not None:
        raise HTTPException(status_code = rejection[0], detail = rejection[1])
    return video_b64


def _video_payload_chars(clip: str) -> int:
    """Base64 length without the data URI header, measured rather than sliced."""
    if clip[:5].lower() != "data:":
        return len(clip)
    comma = clip.find(",")
    return len(clip) - comma - 1 if comma != -1 else 0


def _video_size_rejection(clip: str) -> Optional[tuple[int, str]]:
    """Measures the payload length without slicing, which copied the whole clip on every validation pass."""
    payload_len = _video_payload_chars(clip)
    if not payload_len:
        return (400, "Could not read the provided video file.")
    if payload_len > _MAX_VIDEO_B64_CHARS:
        return (413, "Video file is too large (max 64 MB).")
    return None


def _video_b64_rejection(video_b64: str) -> tuple[str, Optional[tuple[int, str]]]:
    """Strips the data URI header before the size check, so the header does not count against the limit."""
    if video_b64[:5].lower() == "data:":
        video_b64 = video_b64.split(",", 1)[1] if "," in video_b64 else ""
    if not video_b64:
        return "", (400, "Could not read the provided video file.")
    if len(video_b64) > _MAX_VIDEO_B64_CHARS:
        return video_b64, (413, "Video file is too large (max 64 MB).")
    return video_b64, None


def _inject_video_part(messages: list[dict], video_b64: str) -> None:
    """Attaches the container, not frames: llama-server samples the clip into frames itself via mtmd."""
    part = {"type": "input_video", "input_video": {"data": video_b64}}
    for msg in reversed(messages):
        if msg.get("role") == "user":
            content = msg.get("content")
            if isinstance(content, list):
                content.append(part)
            else:
                msg["content"] = [{"type": "text", "text": content or ""}, part]
            return


def _reject_unsupported_content_parts(payload) -> None:
    """Refuses unknown content parts here, since the external proxy would drop them silently."""
    for msg in payload.messages:
        if not isinstance(msg.content, list):
            continue
        for part in msg.content:
            if isinstance(part, UnknownContentPart):
                _raise_unsupported_openai_parameter(
                    "messages",
                    f"Message content parts of type '{part.type}' are not supported.",
                )
    _reject_misplaced_audio_parts(payload)


def _reject_misplaced_audio_parts(payload) -> None:
    """Checks audio placement before routing, so a doomed request cannot evict the resident model first."""
    last_user = None
    for index, msg in enumerate(payload.messages):
        if msg.role == "user":
            last_user = index
    # Only user turns can carry a recording; the lift also clears assistant-history clips, and says so.
    for msg in payload.messages:
        if msg.role == "user" or not isinstance(msg.content, list):
            continue
        if any(isinstance(part, InputAudioContentPart) for part in msg.content):
            _raise_unsupported_openai_parameter(
                "messages",
                f"Audio input is supported on a user message, not on a '{msg.role}' one.",
            )
    parts = [
        (index, part)
        for index, msg in enumerate(payload.messages)
        if isinstance(msg.content, list) and msg.role == "user"
        for part in msg.content
        if isinstance(part, InputAudioContentPart)
    ]
    if len(parts) > _MAX_AUDIO_CLIPS_PER_REQUEST:
        _raise_unsupported_openai_parameter(
            "messages",
            f"At most {_MAX_AUDIO_CLIPS_PER_REQUEST} audio recordings per request are supported, "
            f"and this one carries {len(parts)}.",
        )
    if any(index != last_user for index, _ in parts):
        _raise_unsupported_openai_parameter(
            "messages",
            "Audio input is supported on the latest user message, and this one carries it on an "
            "earlier turn. Re-send the recording on the current turn.",
        )


def _messages_have_input_audio(messages) -> bool:
    return any(
        isinstance(getattr(msg, "content", None), list)
        and any(isinstance(part, InputAudioContentPart) for part in msg.content)
        for msg in messages
    )


def _messages_have_embedded_image(messages) -> bool:
    """True only for inline base64 image data URLs; durable runs would persist them into every later
    turn."""
    for msg in messages:
        content = getattr(msg, "content", None)
        if not isinstance(content, list):
            continue
        for part in content:
            if getattr(part, "type", None) != "image_url":
                continue
            url = getattr(getattr(part, "image_url", None), "url", None)
            if isinstance(url, str) and url.startswith("data:"):
                return True
    return False


def _normalise_chat_content_parts(payload) -> None:
    """Lifts input_audio parts onto the audio fields the safety checks read; an explicit field still
    wins."""
    lifted: list[str] = []
    for msg in payload.messages:
        if not isinstance(msg.content, list):
            continue
        kept = []
        for part in msg.content:
            if isinstance(part, InputAudioContentPart):
                if msg.role == "user" and part.input_audio.data:
                    lifted.append(part.input_audio.data)
                continue
            kept.append(part)
        if len(kept) != len(msg.content):
            msg.content = kept
    if lifted and not getattr(payload, "audio_base64", None):
        payload.audio_base64 = lifted[0]
        payload.extra_audio_base64 = lifted[1:] or None


def _message_video_urls(messages) -> list[str]:
    urls: list[str] = []
    for msg in messages or []:
        content = msg.get("content") if isinstance(msg, dict) else getattr(msg, "content", None)
        if not isinstance(content, list):
            continue
        for part in content:
            if isinstance(part, VideoContentPart):
                urls.append(part.video_url.url)
            elif isinstance(part, dict) and part.get("type") == "video_url":
                video_url = part.get("video_url")
                url = video_url.get("url") if isinstance(video_url, dict) else video_url
                urls.append(url if isinstance(url, str) else "")
    return urls


def _video_is_on_an_older_turn(payload) -> bool:
    """True if a video part sits on an older turn, which non-GGUF moves to the newest turn."""
    messages = getattr(payload, "messages", None) or []
    roles = [m.get("role") if isinstance(m, dict) else getattr(m, "role", None) for m in messages]
    if "user" not in roles:
        return False
    return bool(_message_video_urls(messages[: len(roles) - 1 - roles[::-1].index("user")]))


def _request_video_clips(payload) -> list[str]:
    legacy = getattr(payload, "video_base64", None)
    return ([legacy] if legacy else []) + _message_video_urls(getattr(payload, "messages", None))


def _request_has_video(payload) -> bool:
    return bool(_request_video_clips(payload))


def _is_remote_video(url: str) -> bool:
    # Schemes are case-insensitive and a clip is megabytes: read the prefix, not a copy.
    return url[:8].lower().startswith(("http://", "https://"))


def _video_scheme_rejection(clip: str) -> Optional[tuple[int, str]]:
    """Refuse a clip whose URL names a scheme neither we nor llama-server should honour.

    ``handle_media`` reads ``input_video`` as ``data`` else ``url`` and treats the one string it
    finds the same way, honouring ``file://`` under ``--media-path``. Forwarding such a clip as
    opaque payload is therefore still a local file read, so refuse it by name instead.
    """
    if not clip or _is_remote_video(clip):
        return None
    if clip[:5].lower() == "data:":
        # Skip every data: header (bounded) and judge what follows like any other clip.
        pos = 0
        while clip[pos : pos + 5].lower() == "data:":
            comma = clip.find(",", pos, pos + 256)
            if comma < 0:
                # No payload separator within a real header's length: never forward it as data.
                return (400, "Unsupported video payload in data URI. Send the clip as base64 data.")
            pos = comma + 1
        rest = clip[pos : pos + _MAX_VIDEO_SCHEME_CHARS + 1]
        if ":" not in rest:
            return None
        return (
            _REMOTE_VIDEO_REFUSAL
            if _is_remote_video(rest)
            else (
                400,
                "Unsupported video payload in data URI. Send the clip as base64 data.",
            )
        )
    # ':' is not in the base64 alphabet, so an early colon marks a URL, not payload.
    head = clip[: _MAX_VIDEO_SCHEME_CHARS + 1]
    if ":" not in head:
        return None
    return (
        400,
        f"Unsupported video URL scheme ('{head.split(':', 1)[0]}:'). Send the clip as a data URI.",
    )


def _request_video_rejection(payload) -> Optional[tuple[int, str]]:
    clips = _request_video_clips(payload)
    # Count bounds ffprobe/ffmpeg launches; tiny clips stay under the byte cap.
    if len(clips) > _MAX_VIDEO_CLIPS_PER_REQUEST:
        return (
            400,
            f"Too many videos in one request (max {_MAX_VIDEO_CLIPS_PER_REQUEST}).",
        )
    total = 0
    for clip in clips:
        if _is_remote_video(clip):
            return _REMOTE_VIDEO_REFUSAL
        rejection = _video_scheme_rejection(clip)
        if rejection is not None:
            return rejection
        rejection = _video_size_rejection(clip)
        if rejection is not None:
            return rejection
        total += _video_payload_chars(clip)
        # And bytes bound the per-clip transcode cost the count cannot see.
        if total > _MAX_VIDEO_B64_CHARS:
            return (413, "Videos are too large (max 64 MB per request).")
    return None


async def _shrink_clip_for_llama(video_b64: str, llama_backend) -> str:
    """Transcodes before llama-server samples frames, so the explicit rate must reach the transcode."""
    try:
        return await asyncio.to_thread(
            shrink_video_for_llama,
            video_b64,
            _MAX_VIDEO_BYTES,
            sampled_fps = requested_video_fps(getattr(llama_backend, "extra_args", None)),
        )
    except Exception as e:
        # The helper absorbs ffmpeg errors, so a raw 500 would leak the monitor row; reject with a 400.
        logger.warning("Video preprocessing failed: %s", e, exc_info = True)
        raise HTTPException(
            status_code = 400, detail = "Could not process the provided video file."
        ) from None


async def _shrink_video_parts(messages: list[dict], llama_backend) -> None:
    """Transcodes video_url parts in place, before translation renames them, so a part matches the legacy field's resolution."""
    for msg in messages:
        content = msg.get("content")
        if not isinstance(content, list):
            continue
        for part in content:
            if not isinstance(part, dict) or part.get("type") != "video_url":
                continue
            video_url = part.get("video_url")
            url = video_url.get("url") if isinstance(video_url, dict) else video_url
            url = url if isinstance(url, str) else ""
            if _is_remote_video(url) or _video_scheme_rejection(url) is not None:
                continue  # _translate_video_parts refuses these by name a moment later.
            clip, rejection = _video_b64_rejection(url)
            if rejection is not None:
                continue
            part["video_url"] = {"url": await _shrink_clip_for_llama(clip, llama_backend)}


def _translate_video_parts(messages: list[dict]) -> None:
    """Rewrite ``video_url`` parts in place as llama-server's ``input_video``, always as bytes."""
    for msg in messages:
        content = msg.get("content")
        if not isinstance(content, list):
            continue
        for part in content:
            if not isinstance(part, dict) or part.get("type") != "video_url":
                continue
            video_url = part.get("video_url")
            url = video_url.get("url") if isinstance(video_url, dict) else video_url
            url = url if isinstance(url, str) else ""
            # Restated because the rejection above runs only on pre-switch validation; no other route may hand llama-server a URL to dial.
            if _is_remote_video(url):
                raise HTTPException(
                    status_code = _REMOTE_VIDEO_REFUSAL[0], detail = _REMOTE_VIDEO_REFUSAL[1]
                )
            scheme_rejection = _video_scheme_rejection(url)
            if scheme_rejection is not None:
                raise HTTPException(status_code = scheme_rejection[0], detail = scheme_rejection[1])
            part.clear()
            part.update(
                {"type": "input_video", "input_video": {"data": _video_b64_rejection(url)[0]}}
            )


def _inject_audio_part(messages: list[dict], audio_b64: str, audio_format: str) -> None:
    """Audio rides in the message list like image_url, so plain and tool-calling paths both receive it."""
    part = {
        "type": "input_audio",
        "input_audio": {"data": audio_b64, "format": audio_format},
    }
    for msg in reversed(messages):
        if msg.get("role") == "user":
            content = msg.get("content")
            if isinstance(content, list):
                content.append(part)
            else:
                msg["content"] = [{"type": "text", "text": content or ""}, part]
            return


def _extract_content_parts(
    messages: list,
    structured: bool = False,
    *,
    keep_tool_images: bool = False,
) -> tuple[str, list[dict], "Union[Optional[str], list[str]]"]:
    """Splits messages into system text, chat turns and images: newest image base64, or every served image in document order when structured."""
    system_parts: list[str] = []
    chat_messages: list[dict] = []
    latest_image_b64: Optional[str] = None
    latest_user_image_b64: Optional[str] = None
    served_images: list[str] = []

    _resolved_tool_names = _mcp_resolve_tool_names(messages)
    for _msg_index, msg in enumerate(messages):
        # ── System / developer messages → extract as system_prompt ────────
        if msg.role in ("system", "developer"):
            if isinstance(msg.content, str):
                system_parts.append(msg.content)
            elif isinstance(msg.content, list):
                # Unlikely but handle: join text parts
                system_parts.append("\n".join(p.text for p in msg.content if p.type == "text"))
            continue

        # ── User / assistant messages ─────────────────────────
        if structured and isinstance(msg.content, list):
            parts, payloads = _conversation_with_image_markers([msg])
            served_images.extend(payloads)
            chat_messages.append(dict(parts[0]))
            continue

        combined_text: Optional[str] = None
        if isinstance(msg.content, str):
            # Plain string content - pass through
            combined_text = msg.content
        elif isinstance(msg.content, list):
            # Multimodal content parts
            text_parts: list[str] = []
            message_image_b64: Optional[str] = None
            for part in msg.content:
                if part.type == "text":
                    text_parts.append(part.text)
                elif part.type == "image_url":
                    url = part.image_url.url
                    if url.startswith("data:"):
                        # A payloadless data URL must not displace a real image from an earlier turn.
                        part_b64 = url.partition(",")[2]
                        if part_b64:
                            # First within a message, matching findLatestUserImageBase64 (chat-adapter.ts).
                            if message_image_b64 is None:
                                message_image_b64 = part_b64
                        else:
                            logger.warning(
                                f"Ignoring image URL with no base64 payload: {url[:80]}..."
                            )
                    else:
                        logger.warning(
                            f"Dropping a remote image URL while flattening to text: {url[:80]}..."
                        )
            # Latest message wins: send the image just attached, not the thread's first.
            if message_image_b64 is not None:
                latest_image_b64 = message_image_b64
                if msg.role == "user":
                    latest_user_image_b64 = message_image_b64
            combined_text = "\n".join(text_parts) if text_parts else ""
        elif msg.role == "assistant" and msg.reasoning_content:
            # Reasoning-only turns still need a message for templates using reasoning_content.
            combined_text = ""
        elif msg.role == "assistant" and msg.tool_calls:
            combined_text = ""

        if combined_text is None:
            continue
        if msg.role == "tool" and not keep_tool_images:
            # Exact split: tool text may contain the marker line without an envelope.
            combined_text = split_mcp_images(combined_text)[0]
        chat_message = {"role": msg.role, "content": combined_text}
        # Keep the name: promote_history reads it to verify an MCP envelope's origin, and an unnamed tool message bypasses that check.
        if msg.name:
            chat_message["name"] = msg.name
        if msg.role == "tool":
            _tool_name = getattr(msg, "name", None) or _resolved_tool_names.get(_msg_index)
            if isinstance(_tool_name, str) and _tool_name:
                chat_message["name"] = _tool_name
        if msg.role == "assistant" and msg.reasoning_content:
            chat_message["reasoning_content"] = msg.reasoning_content
        if msg.tool_calls:
            chat_message["tool_calls"] = msg.tool_calls
        if msg.tool_call_id:
            chat_message["tool_call_id"] = msg.tool_call_id
        chat_messages.append(chat_message)

    # Gated so a history without tool calls renders exactly as before.
    if any(m.get("tool_calls") for m in chat_messages):
        chat_messages = _strip_provider_synthetic_tool_history(chat_messages)

    # A user's attachment outranks an assistant-generated one.
    return (
        "\n\n".join(p for p in system_parts if p),
        # Mappings, not JSON strings: Qwen3.5's template renders string arguments as nothing.
        _structured_tool_history_for_local_template(chat_messages),
        served_images if structured else (latest_user_image_b64 or latest_image_b64),
    )


async def _extract_content_parts_async(messages: list, **kwargs):
    """The same, off the shared loop when a tool result carries the envelope marker:
    stripping it is the exact split, a json-load of a permitted 12 MB array, and the
    awaited audio, count and safetensors callers must not do that on the loop."""
    if _messages_mention_mcp_images(messages):
        return await asyncio.to_thread(_extract_content_parts, messages, **kwargs)
    return _extract_content_parts(messages, **kwargs)


def _user_ordinal_supplying_the_image(messages: list) -> Optional[int]:
    """Ordinal among user turns, not message index (passthrough folds system turns), of the turn that supplied the image; may predate the newest."""
    ordinal = None
    seen = 0
    for msg in messages:
        if msg.role != "user":
            continue
        if isinstance(msg.content, list):
            for part in msg.content:
                if part.type != "image_url":
                    continue
                url = getattr(getattr(part, "image_url", None), "url", "") or ""
                if url.startswith("data:") and url.partition(",")[2]:
                    ordinal = seen
                    break
        seen += 1
    return ordinal


def _mark_image_owner_turn(
    messages: list,
    ordinal: int,
    marked_at: "list | None" = None,
) -> list:
    """Puts the image part ahead of its owning user turn, since positional processors bind in order."""
    marked = list(messages)
    seen = 0
    for index, message in enumerate(marked):
        if not isinstance(message, dict) or message.get("role") != "user":
            continue
        if seen == ordinal:
            if marked_at is not None:
                marked_at.append(index)
            body = message.get("content")
            if isinstance(body, str):
                marked[index] = {
                    **message,
                    "content": [{"type": "image"}, {"type": "text", "text": body}],
                }
            break
        seen += 1
    return marked


def _images_in_last_user_message(messages: list) -> int:
    """Counts images on the newest user turn only; only the answered turn decides multi-image calls."""
    for msg in reversed(messages):
        if msg.role != "user":
            continue
        if not isinstance(msg.content, list):
            return 0
        return sum(1 for part in msg.content if part.type == "image_url")
    return 0


def _legacy_image_is_distinct(payload) -> bool:
    """True if image_base64 is not Studio's echo of the latest user image; other images do not match."""
    image = getattr(payload, "image_base64", None)
    if not image:
        return False
    return _latest_user_image_payload(getattr(payload, "messages", None)) != image


def _latest_user_image_payload(messages) -> "Optional[str]":
    """Newest user turn first; an empty image part does not end the scan, matching the frontend's walk."""
    for msg in reversed(list(messages or ())):
        role = msg.get("role") if isinstance(msg, dict) else getattr(msg, "role", None)
        content = msg.get("content") if isinstance(msg, dict) else getattr(msg, "content", None)
        if role != "user" or not isinstance(content, list):
            continue
        for part in content:
            if isinstance(part, dict):
                if part.get("type") != "image_url":
                    continue
                image_url = part.get("image_url")
                url = image_url.get("url") if isinstance(image_url, dict) else image_url
            else:
                if getattr(part, "type", None) != "image_url":
                    continue
                url = getattr(getattr(part, "image_url", None), "url", None)
            if not isinstance(url, str):
                continue
            encoded = url.partition(",")[2] if url.startswith("data:") else url
            if encoded:
                return encoded
    return None


def _part_attr(part, name):
    return part.get(name) if isinstance(part, dict) else getattr(part, name, None)


def _image_part_payload(part) -> "Optional[str]":
    """Shared, so extraction, the tool rebuild and the preflight agree on what is servable."""
    if _part_attr(part, "type") != "image_url":
        return None
    image_url = _part_attr(part, "image_url")
    url = image_url.get("url") if isinstance(image_url, dict) else getattr(image_url, "url", None)
    if not isinstance(url, str) or not url.startswith("data:"):
        return None
    return url.partition(",")[2] or None


def _conversation_with_image_markers(messages) -> tuple[list[dict], list[str]]:
    """Markers stay where they stood: the backend binds pixel values to image tokens by position."""
    rebuilt: list[dict] = []
    payloads: list[str] = []
    for message in messages or ():
        plain = message if isinstance(message, dict) else message.model_dump(exclude_none = True)
        content = plain.get("content")
        if not isinstance(content, list):
            rebuilt.append(plain)
            continue
        parts = []
        for part in content:
            if _part_attr(part, "type") == "image_url":
                # User turns only: several templates leave an assistant's own image unmarked.
                served = _image_part_payload(part) if plain.get("role") == "user" else None
                if served is not None:
                    payloads.append(served)
                    parts.append({"type": "image"})
                # Otherwise dropped: a part left here claims a marker nothing can bind.
                continue
            if _part_attr(part, "type") != "text":
                # Text and image only: local templates (e.g. mistral3) raise on other part types.
                continue
            parts.append(part)
        rebuilt.append({**plain, "content": parts})
    return rebuilt, payloads


def _serves_several_images(backend) -> bool:
    entry = (getattr(backend, "models", None) or {}).get(
        getattr(backend, "active_model_name", None), {}
    )
    return bool((entry.get("chat_template_info") or {}).get("accepts_multiple_images"))


def _serve_legacy_image_on_the_newest_turn(
    messages: list[dict], payloads: list[str], encoded: str
) -> list[str]:
    newest = len(messages)
    for position in range(len(messages) - 1, -1, -1):
        if messages[position].get("role") == "user":
            newest = position
            break

    marker = {"type": "image"}
    if newest == len(messages):
        messages.append({"role": "user", "content": [marker]})
    else:
        content = messages[newest].get("content")
        messages[newest] = {
            **messages[newest],
            "content": (
                [*content, marker]
                if isinstance(content, list)
                else [{"type": "text", "text": content or ""}, marker]
            ),
        }
    return [*payloads, encoded]


def _newest_turn_shows_more_images_than_it_sends(messages, legacy_is_distinct: bool) -> bool:
    """The shape the one-image-per-message refusal answers, rather than answering about the rest."""
    for message in reversed(messages or ()):
        role = message.get("role") if isinstance(message, dict) else message.role
        if role != "user":
            continue
        content = message.get("content") if isinstance(message, dict) else message.content
        if not isinstance(content, list):
            return False
        parts = [part for part in content if _part_attr(part, "type") == "image_url"]
        if len(parts) + int(legacy_is_distinct) < 2:
            return False
        return any(_image_part_payload(part) is None for part in parts)
    return False


def _local_image_payloads_from_messages(messages) -> list[str]:
    """All data-URL image payloads in OpenAI-format messages."""
    encoded_images = []
    for message in messages or ():
        content = message.get("content") if isinstance(message, dict) else message.content
        if not isinstance(content, list):
            continue
        for part in content:
            part_type = part.get("type") if isinstance(part, dict) else part.type
            if part_type != "image_url":
                continue
            image_url = part.get("image_url") if isinstance(part, dict) else part.image_url
            url = image_url.get("url") if isinstance(image_url, dict) else image_url.url
            if isinstance(url, str) and url.startswith("data:"):
                encoded_images.append(url.partition(",")[2])
    return encoded_images


def _request_local_image_payloads(payload) -> list[str]:
    """All data-URL and distinct legacy image payloads forwarded locally."""
    encoded_images = _local_image_payloads_from_messages(getattr(payload, "messages", None) or ())
    if _legacy_image_is_distinct(payload):
        encoded_images.append(payload.image_base64)
    return encoded_images


# ── External provider proxy ──────────────────────────────────────
# Only these helpers translate input_document; generic passthroughs would 400 on it.
_INPUT_DOCUMENT_PROVIDERS = frozenset({"anthropic", "openai"})

# Frontend ids "<provider id>:<uuid4>" are 66 chars; OpenAI caps call ids at 64.
_MINTED_TOOL_CALL_ID_SUFFIX = _re.compile(
    r":[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"
)

# Mistral requires replayed tool-call ids to match ^[a-zA-Z0-9]{9}$.
_MISTRAL_TOOL_CALL_ID = _re.compile(r"[a-zA-Z0-9]{9}")

# Anthropic requires ^[a-zA-Z0-9_-]+$ (charset only); colon ids under 64 chars hit this.
_ANTHROPIC_TOOL_CALL_ID = _re.compile(r"[a-zA-Z0-9_-]+")
_ANTHROPIC_TOOL_CALL_ID_ILLEGAL = _re.compile(r"[^a-zA-Z0-9_-]")


def _replay_tool_call_id_map(
    originals: "set[str]", provider_type: Optional[str] = None
) -> dict[str, str]:
    """Maps tool-call ids per provider; hashes the whole value so ids sharing a prefix stay distinct, and is idempotent on replay."""
    bases = {v: _MINTED_TOOL_CALL_ID_SUFFIX.sub("", v) for v in originals}
    claims: dict[str, int] = {}
    for base in bases.values():
        claims[base] = claims.get(base, 0) + 1
    out = {}
    for value, base in bases.items():
        replay = base if claims[base] == 1 else value
        if provider_type == "mistral":
            if not _MISTRAL_TOOL_CALL_ID.fullmatch(replay):
                replay = _hashlib.sha256(replay.encode("utf-8")).hexdigest()[:9]
        elif provider_type == "anthropic" and not _ANTHROPIC_TOOL_CALL_ID.fullmatch(replay):
            # sha256 of the unsanitized value keeps the mapping injective; 31 + 1 + 32 = 64.
            digest = _hashlib.sha256(replay.encode("utf-8")).hexdigest()[:32]
            sanitized = _ANTHROPIC_TOOL_CALL_ID_ILLEGAL.sub("_", replay)[:31]
            replay = f"{sanitized}_{digest}"
        elif len(replay) > 64:
            digest = _hashlib.sha256(replay.encode("utf-8")).hexdigest()[:32]
            replay = f"{replay[:31]}_{digest}"
        out[value] = replay
    return out


def _replay_tool_call_ids(tool_calls: Any, replay_ids: dict[str, str]) -> Any:
    if not isinstance(tool_calls, list):
        return tool_calls
    out = []
    for tc in tool_calls:
        if isinstance(tc, dict) and isinstance(tc.get("id"), str):
            fixed = replay_ids.get(tc["id"], tc["id"])
            if fixed != tc["id"]:
                tc = {**tc, "id": fixed}
        out.append(tc)
    return out


def _live_tool_call_ids(messages: list[dict]) -> list[dict]:
    """GGUF history with each tool-call id as the model generated it: the client suffixes every card id
    with a minted uuid, which templates that render ids (Kimi, Mistral) would otherwise show, and Mistral
    rejects outright. Calls and results lose the same suffix, so they stay paired."""
    out = []
    for message in messages:
        calls = message.get("tool_calls")
        call_id = message.get("tool_call_id")
        if isinstance(calls, list):
            calls = [
                {**call, "id": _MINTED_TOOL_CALL_ID_SUFFIX.sub("", call["id"]) or call["id"]}
                if isinstance(call, dict) and isinstance(call.get("id"), str)
                else call
                for call in calls
            ]
            message = {**message, "tool_calls": calls}
        if isinstance(call_id, str):
            message = {
                **message,
                "tool_call_id": _MINTED_TOOL_CALL_ID_SUFFIX.sub("", call_id) or call_id,
            }
        out.append(message)
    return out


def _build_external_messages(
    messages: list,
    supports_vision: bool,
    provider_type: Optional[str] = None,
    base_url: Optional[str] = None,
    api_type: Optional[str] = None,
    promoted_out: "Optional[list]" = None,
    promote_mcp_images: "Optional[bool]" = None,
    model: Optional[str] = None,
    preserve_thinking: Optional[bool] = None,
) -> list[dict]:
    """Strips input_document unless the provider translates it, and image_url unless vision; promote_mcp_images must not be passed as the vision flag."""
    document_provider = provider_type in _INPUT_DOCUMENT_PROVIDERS or (
        provider_type == "custom" and api_type == "responses"
    )
    anthropic = provider_type == "anthropic"
    responses_native_parts = provider_type == "openai" or (
        provider_type == "custom" and api_type == "responses"
    )
    # emit `extra_content` only to endpoints that understand Gemini `thoughtSignature` metadata.
    _native_gemini = False
    if provider_type == "gemini" and base_url:
        try:
            from urllib.parse import urlparse as _urlparse
            _host = (_urlparse(base_url).hostname or "").lower()
            _native_gemini = _host == "generativelanguage.googleapis.com"
        except Exception:
            _native_gemini = False
    emit_extra_content = _native_gemini or provider_type == "openai_codex"
    emit_message_extra_content = emit_extra_content or (
        provider_type == "custom" and api_type == "responses"
    )

    _SERVER_BUILTIN_TOOL_NAMES = frozenset(
        {"web_search", "web_fetch", "code_execution", "image_generation"}
    )

    def _is_marked_server_builtin_tool_call(tc: Any) -> bool:
        """True for synthetic provider cards marked by args._server_tool or a Gemini native_part payload."""
        if not isinstance(tc, dict):
            return False
        fn = tc.get("function")
        if not isinstance(fn, dict):
            return False
        name = (fn.get("name") or "").lower()
        if name not in _SERVER_BUILTIN_TOOL_NAMES:
            return False
        raw_args = fn.get("arguments") or ""
        try:
            args = json.loads(raw_args) if isinstance(raw_args, str) else raw_args
        except Exception:
            return False
        if not isinstance(args, dict):
            return False
        if args.get("_server_tool") is True:
            return True
        google = args.get("google")
        return isinstance(google, dict) and isinstance(google.get("native_part"), dict)

    # Drop matching role=tool follow-ups too; orphan tool_call_ids are rejected upstream.
    dropped_server_builtin_tool_call_ids: set[str] = set()

    def _filter_tool_calls(tool_calls: Any) -> Optional[list]:
        """Strips extra_content and marked server cards for non-native providers; native Gemini
        keeps them."""
        if not tool_calls:
            return None
        if not isinstance(tool_calls, list):
            return tool_calls
        if emit_extra_content:
            return tool_calls
        cleaned: list = []
        for _tc in tool_calls:
            if _is_marked_server_builtin_tool_call(_tc):
                _tc_id = _tc.get("id") if isinstance(_tc, dict) else None
                if isinstance(_tc_id, str) and _tc_id:
                    dropped_server_builtin_tool_call_ids.add(_tc_id)
                continue
            if not isinstance(_tc, dict):
                cleaned.append(_tc)
                continue
            if "extra_content" not in _tc:
                cleaned.append(_tc)
                continue
            _stripped = {k: v for k, v in _tc.items() if k != "extra_content"}
            cleaned.append(_stripped)
        return cleaned

    def _openai_responses_part(item: Any) -> Optional[dict[str, Any]]:
        """rebuild replayable OpenAI Responses assistant parts."""
        if item.type == "reasoning":
            reasoning: dict[str, Any] = {
                "type": "reasoning",
                "id": item.id,
                "summary": item.summary,
            }
            if item.status:
                reasoning["status"] = item.status
            return reasoning
        if item.type == "image_generation_call":
            image_ref: dict[str, Any] = {"type": "image_generation_call", "id": item.id}
            if getattr(item, "response_id", None):
                image_ref["response_id"] = item.response_id
            return image_ref
        if item.type == "compaction" and item.encrypted_content:
            return {"type": "compaction", "encrypted_content": item.encrypted_content}
        return None

    replays_reasoning = (
        provider_type == "llama_cpp"
        or (provider_type == "vllm" and preserve_thinking is True)
        or _is_kimi_k3(provider_type, model)
        # Thinking mode with tools answers 400 without it, and ignores it elsewhere
        # (api-docs.deepseek.com/guides/thinking_mode).
        or provider_type == "deepseek"
    )
    result = []
    for msg in messages:
        replay = (
            {"reasoning_content": msg.reasoning_content}
            if replays_reasoning and msg.role == "assistant" and msg.reasoning_content
            else {}
        )
        has_message_extra_content = bool(
            emit_message_extra_content and msg.role == "assistant" and msg.extra_content
        )
        if anthropic and msg.role == "assistant" and isinstance(msg.extra_content, dict):
            native = msg.extra_content.get("anthropic")
            if (
                isinstance(native, dict)
                and isinstance(native.get("content"), list)
                and native["content"]
            ):
                replay["extra_content"] = {"anthropic": {"content": native["content"]}}
        if (
            provider_type == "openai"
            and not emit_message_extra_content
            and msg.role == "assistant"
            and isinstance(msg.extra_content, dict)
            and msg.extra_content.get("openai_responses_reasoning")
        ):
            # OpenAI wants a tool call's reasoning items back with its outputs; only that key.
            replay["extra_content"] = {
                "openai_responses_reasoning": msg.extra_content["openai_responses_reasoning"]
            }
        # Drop role=tool messages whose matching server-builtin tool_call was
        # filtered above. An orphan tool_result with no matching tool_call is
        # rejected by OpenAI Responses and Anthropic.
        if (
            msg.role == "tool"
            and isinstance(msg.tool_call_id, str)
            and msg.tool_call_id in dropped_server_builtin_tool_call_ids
        ):
            continue
        if isinstance(msg.content, str) or (
            msg.content is None and (replay or has_message_extra_content)
        ):
            # Drops bare empty assistant turns (some providers reject them); keeps tool_calls-only
            # turns.
            if (
                msg.role == "assistant"
                and not (msg.content or "").strip()
                and not msg.tool_calls
                and not replay
                and not has_message_extra_content
            ):
                continue
            out: dict[str, Any] = {"role": msg.role, "content": msg.content or "", **replay}
            if msg.role == "assistant" and msg.tool_calls:
                _tcs = _filter_tool_calls(msg.tool_calls)
                if _tcs:
                    out["tool_calls"] = _tcs
                elif (
                    not (msg.content or "").strip() and not replay and not has_message_extra_content
                ):
                    # Turns emptied by dropped synthetic cards are skipped, since some providers
                    # reject empty turns.
                    continue
            if msg.role == "tool":
                if msg.tool_call_id:
                    out["tool_call_id"] = msg.tool_call_id
                if msg.name:
                    out["name"] = msg.name
            if emit_message_extra_content and msg.role == "assistant" and msg.extra_content:
                out["extra_content"] = msg.extra_content

            result.append(out)
            continue
        # content=None with tool_calls is a valid post-tool turn; forward it so functionCall can be rebuilt.
        if msg.content is None and msg.role == "assistant" and msg.tool_calls:
            _filtered_tcs = _filter_tool_calls(msg.tool_calls)
            if not _filtered_tcs:
                # Skip the whole message when every tool_call was provider-side synthetic, avoiding an empty turn.
                continue
            _assistant_only: dict[str, Any] = {
                "role": "assistant",
                "content": "",
                "tool_calls": _filtered_tcs,
            }
            if emit_message_extra_content and msg.extra_content:
                _assistant_only["extra_content"] = msg.extra_content
            result.append(_assistant_only)
            continue
        if isinstance(msg.content, list):
            if supports_vision:
                parts = []
                for part in msg.content:
                    if part.type == "text":
                        parts.append({"type": "text", "text": part.text})
                    elif part.type == "image_url":
                        parts.append(
                            {
                                "type": "image_url",
                                "image_url": {"url": part.image_url.url},
                            }
                        )
                    elif (
                        responses_native_parts
                        and msg.role == "assistant"
                        and (_rp := _openai_responses_part(part)) is not None
                    ):
                        # ExternalProviderClient maps image_generation_call after the user prompt, or to previous_response_id.
                        parts.append(_rp)
                    elif part.type == "input_document" and document_provider:
                        # input_document becomes Anthropic's document or OpenAI's input_file; other providers would 400.
                        doc: dict[str, Any] = {"type": "input_document"}
                        if part.file_data:
                            doc["file_data"] = part.file_data
                        if part.file_url:
                            doc["file_url"] = part.file_url
                        if part.filename:
                            doc["filename"] = part.filename
                        if part.media_type:
                            doc["media_type"] = part.media_type
                        parts.append(doc)
                    elif part.type == "compaction" and anthropic:
                        # Anthropic stream helper forwards this as a native
                        # `compaction` block; every other provider would 400 on
                        # the unknown part, so gate by provider_type.
                        compaction = {"type": "compaction", "content": part.content}
                        if part.content and part.encrypted_content:
                            compaction["encrypted_content"] = part.encrypted_content
                        parts.append(compaction)
                entry: dict[str, Any] = {"role": msg.role, "content": parts, **replay}
                if msg.role == "assistant" and msg.tool_calls:
                    _tcs = _filter_tool_calls(msg.tool_calls)
                    if _tcs:
                        entry["tool_calls"] = _tcs
                    elif not parts and not replay and not has_message_extra_content:
                        # All tool_calls were synthetic and dropped, and no
                        # content parts survived. Skip rather than forward an
                        # empty assistant turn that downstream providers reject.
                        continue
                elif (
                    msg.role == "assistant"
                    and not parts
                    and not replay
                    and not has_message_extra_content
                ):
                    continue
                if msg.role == "tool":
                    if msg.tool_call_id:
                        entry["tool_call_id"] = msg.tool_call_id
                    if msg.name:
                        entry["name"] = msg.name
                if emit_message_extra_content and msg.role == "assistant" and msg.extra_content:
                    entry["extra_content"] = msg.extra_content
                result.append(entry)
            else:
                # Non-vision providers drop images and documents; compaction is kept for Anthropic only, as a guard.
                preserved = []
                for p in msg.content:
                    if p.type == "text":
                        preserved.append({"type": "text", "text": p.text})
                    elif (
                        responses_native_parts
                        and msg.role == "assistant"
                        and (_rp := _openai_responses_part(p)) is not None
                    ):
                        preserved.append(_rp)
                    elif p.type == "compaction" and anthropic:
                        compaction = {"type": "compaction", "content": p.content}
                        if p.content and p.encrypted_content:
                            compaction["encrypted_content"] = p.encrypted_content
                        preserved.append(compaction)
                if (
                    msg.role == "assistant"
                    and not preserved
                    and not replay
                    and not has_message_extra_content
                ):
                    continue
                if len(preserved) == 1 and preserved[0]["type"] == "text":
                    # A lone text part collapses to a plain string for providers that reject content arrays.
                    entry = {"role": msg.role, "content": preserved[0]["text"], **replay}
                else:
                    entry = {"role": msg.role, "content": preserved, **replay}
                if msg.role == "assistant" and msg.tool_calls:
                    _tcs = _filter_tool_calls(msg.tool_calls)
                    if _tcs:
                        entry["tool_calls"] = _tcs
                    else:
                        # If every tool_call was synthetic and dropped, skip the entry unless some content survived.
                        _entry_content = entry.get("content")
                        _has_text = (
                            isinstance(_entry_content, str) and _entry_content.strip()
                        ) or (isinstance(_entry_content, list) and len(_entry_content) > 0)
                        if not _has_text and not replay and not has_message_extra_content:
                            continue
                if msg.role == "tool":
                    if msg.tool_call_id:
                        entry["tool_call_id"] = msg.tool_call_id
                    if msg.name:
                        entry["name"] = msg.name
                if emit_message_extra_content and msg.role == "assistant" and msg.extra_content:
                    entry["extra_content"] = msg.extra_content
                result.append(entry)
    originals = {
        tc["id"]
        for entry in result
        if isinstance(entry.get("tool_calls"), list)
        for tc in entry["tool_calls"]
        if isinstance(tc, dict) and isinstance(tc.get("id"), str)
    } | {entry["tool_call_id"] for entry in result if isinstance(entry.get("tool_call_id"), str)}
    if originals:
        replay_ids = _replay_tool_call_id_map(originals, provider_type)
        for entry in result:
            if entry.get("tool_calls"):
                entry["tool_calls"] = _replay_tool_call_ids(entry["tool_calls"], replay_ids)
            if isinstance(entry.get("tool_call_id"), str):
                entry["tool_call_id"] = replay_ids.get(entry["tool_call_id"], entry["tool_call_id"])
    promote = supports_vision if promote_mcp_images is None else promote_mcp_images
    # Providers cap images in document order, so the replay leaves room for the caller's.
    return promote_mcp_history_images(
        result, vision = promote, promoted_out = promoted_out, reserve_for_caller = True
    )


async def _promote_mcp_history_images_async(
    messages,
    *,
    vision: bool,
    promoted_out = None,
):
    """Off the event loop when an MCP envelope is present, since stripping it json-loads a large array."""
    if _messages_mention_mcp_images(messages):
        return await asyncio.to_thread(
            promote_mcp_history_images, messages, vision = vision, promoted_out = promoted_out
        )
    return promote_mcp_history_images(messages, vision = vision, promoted_out = promoted_out)


async def _promote_local_mcp_images_async(
    messages,
    *,
    vision: bool,
    decode_cache = None,
    caller_images = (),
):
    """Re-encoding replayed MCP images is slow, so it runs off the loop whenever a marker is present."""
    if _messages_mention_mcp_images(messages):
        return await asyncio.to_thread(
            promote_mcp_history_images_local,
            messages,
            vision = vision,
            decode_cache = decode_cache,
            caller_images = caller_images,
        )
    return promote_mcp_history_images_local(
        messages, vision = vision, decode_cache = decode_cache, caller_images = caller_images
    )


async def _build_external_messages_async(messages, supports_vision, **kwargs) -> list[dict]:
    """Also collects what promotion created when the caller passes promoted_out."""
    """Promoting a replayed envelope decodes and re-encodes every picture in it,
    which is PIL work on the shared loop. Hop to a thread only when there is an
    envelope to promote, so an ordinary text turn keeps its direct call."""
    # On marker presence alone: a text-only target still needs the envelope stripped.
    if _messages_mention_mcp_images(messages):
        return await asyncio.to_thread(
            _build_external_messages, messages, supports_vision, **kwargs
        )
    return _build_external_messages(messages, supports_vision, **kwargs)


def _safe_retry_after_header(value: Any) -> Optional[str]:
    """Validates provider Retry-After so only delay-seconds or a GMT date reach a response header."""
    if not isinstance(value, str):
        return None
    if (
        len(value) > 128
        or not value.isascii()
        or any(ord(char) < 0x20 or ord(char) > 0x7E for char in value)
    ):
        return None
    candidate = value.strip()
    if not candidate:
        return None
    if candidate.isdecimal():
        return candidate

    from datetime import timedelta
    from email.utils import parsedate_to_datetime

    try:
        parsed = parsedate_to_datetime(candidate)
    except (TypeError, ValueError, OverflowError):
        return None
    if (
        parsed is None
        or parsed.tzinfo is None
        or parsed.utcoffset() != timedelta(0)
        or not candidate.endswith(" GMT")
    ):
        return None
    return candidate


def _sse_line_finishes(line: str) -> bool:
    """Whether an OpenAI stream line carries a choice's finish_reason."""
    raw = line[len("data:") :].strip() if line.startswith("data:") else line
    try:
        chunk = json.loads(raw)
    except ValueError:
        return False
    return isinstance(chunk, dict) and any(
        isinstance(choice, dict) and choice.get("finish_reason")
        for choice in chunk.get("choices") or ()
    )


class _TurnFinish:
    """Whether a stream's last provider turn carried a finish_reason (the tool loop relays intermediate ones)."""

    def __init__(self) -> None:
        self.turn = False
        self.last: bool | None = None

    def see(self, line: str) -> None:
        if not self.turn:
            self.turn = _sse_line_finishes(line)

    def end_turn(self) -> None:
        self.last, self.turn = self.turn, False

    @property
    def finished(self) -> bool:
        return self.turn or bool(self.last)


async def _stop_on_cancel(agen, cancel_event: threading.Event):
    """Stops on cancel even while awaiting a frame, since a runtime can prefill for seconds without one."""

    def _retrieve_exception(task: asyncio.Task) -> None:
        try:
            task.exception()
        except asyncio.CancelledError:
            pass

    async def _cancelled() -> None:
        while not cancel_event.is_set():
            await asyncio.sleep(0.1)

    waiter = asyncio.ensure_future(_cancelled())
    step = None
    try:
        while True:
            step = asyncio.ensure_future(agen.__anext__())
            done, _ = await asyncio.wait({step, waiter}, return_when = asyncio.FIRST_COMPLETED)
            if step not in done:
                return
            try:
                line = step.result()
            except StopAsyncIteration:
                return
            yield line
    finally:
        pending = [task for task in (step, waiter) if task is not None and not task.done()]
        for task in pending:
            task.add_done_callback(_retrieve_exception)
            task.cancel()
        if pending:
            # asyncio.wait leaves cancellation cleanup running when the relay is cancelled.
            await asyncio.wait(pending)
        try:
            await agen.aclose()
        except RuntimeError:
            pass


# keep these limits aligned with auto-compaction.ts, which derives catalogued-window thresholds.
_EXTERNAL_COMPACTION_HEADROOM = 0.25
_EXTERNAL_COMPACTION_THRESHOLD_MAX = 2_000_000


def _fit_external_context(
    messages: list[dict],
    payload,
    *,
    tools: Optional[list[dict]] = None,
    branch: Optional[list[dict]] = None,
    tool_loop: bool = False,
) -> tuple[list[dict], Optional[dict], Optional[int]]:
    """``branch`` is the client's request when ``messages`` is a tool loop's conversation, so recall
    queries the user's turn rather than a controller re-prompt the loop appended."""
    from core.inference.context_window import (
        estimate_message_tokens_without_unpriced_media,
        estimate_messages_tokens_conservative,
        messages_without_unpriced_media,
        prompt_budget,
        retrieval_budget,
    )
    from core.inference.llama_cpp import (
        _archive_and_recall,
        _boundary_metadata,
        _compaction_fit_kwargs,
        _conversation_recall_reserve,
        _fit_with_instruction_pins,
        _keeps_compaction_boundary,
        _records_boundary,
        _sticky_compaction_state,
    )

    tool_tokens = _openai_llama_admission_injected_tool_tokens(tools)

    def _count(fitted):
        estimate_messages, image_parts = _openai_llama_admission_messages_for_estimate(fitted)
        media_tokens = _openai_llama_admission_media_tokens(
            payload,
            message_image_parts = image_parts,
            message_video_clips = _conversation_video_clips(fitted),
        )
        return (
            estimate_messages_tokens_conservative(
                messages_without_unpriced_media(estimate_messages)
            )
            + media_tokens
            + tool_tokens
        )

    context_length = payload.compaction_threshold
    max_tokens = _effective_max_tokens(payload)
    window = payload.context_window
    prompt_tokens = _count(messages)
    if window and max_tokens:
        # reserve the full reply cap while leaving at least half the window for the prompt.
        margin = window // 32
        if prompt_tokens + max_tokens + margin > window:
            room = max(window - max_tokens, window // 2) - margin
            max_tokens = min(max_tokens, window - room - margin)
            # The largest context whose prompt_budget stays within room.
            context_length = min(context_length, room + max_tokens, room * 4 // 3)
    if prompt_tokens <= prompt_budget(context_length, max_tokens):
        return messages, None, max_tokens
    policy = _request_context_policy(payload)
    ratio = _request_compaction_headroom_ratio(payload)
    thread_id = payload.thread_id
    # Recall below is inline and rolling (every evicting fit), so a checkpoint reset may not start.
    sticky, sticky_is_checkpoint = _sticky_compaction_state(
        thread_id,
        messages,
        context_policy = policy,
        can_reset = False,
        compaction_headroom_ratio = ratio,
    )
    fitted, truncation = _fit_with_instruction_pins(
        messages,
        context_length = context_length,
        max_tokens = max_tokens,
        count_tokens = _count,
        keeps_boundary = _keeps_compaction_boundary(thread_id),
        recall_offered = False,
        reserve_tokens = _conversation_recall_reserve(thread_id),
        sticky_dropped = sticky,
        sticky_is_checkpoint = sticky_is_checkpoint,
        estimate_message = estimate_message_tokens_without_unpriced_media,
        **_compaction_fit_kwargs(policy, ratio),
    )
    if truncation and _records_boundary(truncation):
        # From the fit, not the recalled list: inline recall swaps the latest user dict and the
        # anchor is matched by identity.
        truncation = {**truncation, **_boundary_metadata(fitted, messages, ratio)}
    if truncation:
        # The catalogue is chosen before this fit, so the turn that first evicts has no
        # search_conversation: recall inline, as the local plain path does, or a question about
        # an evicted attachment on that turn gets "I have no record of it".
        recall = _archive_and_recall(
            fitted,
            messages,
            branch_messages = branch or messages,
            thread_id = str(thread_id) if thread_id else None,
            style = "inline",
            recall_done = not truncation.get("fits", True),
            recall_budget_tokens = retrieval_budget(
                context_length,
                max_tokens,
                truncation.get("prompt_tokens_after") or 0,
                reply_returns = tool_loop,
            ),
            count_tokens = _count,
        )
        fitted = recall["conversation"]
        truncation = {**truncation, **recall["counts"]}
    return fitted, truncation, max_tokens


def _is_compaction_block_sse(line: str) -> bool:
    if '"compaction_block"' not in line:
        return False
    event = (_sse_payload(line) or {}).get("_toolEvent")
    return isinstance(event, dict) and event.get("type") == "compaction_block"


def _provider_compaction_truncation(messages: list[dict]) -> dict:
    latest_user = max(
        (index for index, message in enumerate(messages) if message.get("role") == "user"),
        default = 0,
    )
    summarized = sum(
        1
        for message in messages[:latest_user]
        if message.get("role") not in ("system", "developer")
    )
    return {
        "dropped_messages": summarized,
        "boundary_messages": summarized,
        "fits": True,
        "summarized": True,
    }


async def _proxy_to_external_provider(
    payload: ChatCompletionRequest,
    request: Request,
    current_subject: Optional[str] = None,
    *,
    managed = None,
    early_close_status = None,
) -> Response:
    """Managed upstream streams are tracked for swap cancel; early_close_status defaults to cancelled."""
    provider_type = payload.provider_type
    base_url = payload.provider_base_url
    api_type = payload.provider_api_type
    reasoning_config = normalize_provider_reasoning_config(payload.provider_reasoning_config)
    saved_provider_snapshot: Optional[dict] = None

    if managed is not None:
        provider_type = managed.provider_type
        base_url = managed.base_url
        api_type = "chat_completions"
        reasoning_config = None
    elif payload.provider_id and (
        not payload.encrypted_api_key or payload.provider_reasoning_config is not None
    ):
        # Legacy explicit-key requests retain editable routing; reasoning opt-ins use the saved contract.
        config = await asyncio.to_thread(providers_db.get_provider, payload.provider_id)
        if config is None:
            raise HTTPException(
                status_code = 404,
                detail = f"Provider config not found: {payload.provider_id}",
            )
        if not config["is_enabled"]:
            raise HTTPException(
                status_code = 400,
                detail = f"Provider '{config['display_name']}' is disabled.",
            )
        # A saved credential is scoped to its provider; never pair it with request routing.
        saved_provider_snapshot = config
        account_access.require_connection_model_allowed(
            config, payload.external_model or payload.model
        )
        provider_type = config["provider_type"]
        base_url = config["base_url"]
        api_type = config.get("api_type", "chat_completions")
        reasoning_config = normalize_provider_reasoning_config(config.get("reasoning_config"))

    if not provider_type:
        raise HTTPException(
            status_code = 400,
            detail = "Either provider_id or provider_type is required for external provider routing.",
        )
    _refuse_decision_connection(provider_type, api_type)
    if provider_type == "custom":
        try:
            validate_provider_reasoning_contract(provider_type, api_type, reasoning_config)
        except ValueError as exc:
            raise HTTPException(status_code = 400, detail = str(exc)) from None
    else:
        reasoning_config = None

    # Loop requires streaming: approvals ride SSE, so non-streaming must be refused below.
    studio_tool_loop = (
        # Gemini image models drop the function catalog, so don't enter the loop for them.
        provider_model_runs_local_tools(provider_type, payload.external_model or payload.model)
        and (managed is None or managed.supports_tools)
        and payload.stream is True
        and _explicit_studio_tool_loop_requested(payload)
        # Hosted-only selections proxy through unchanged. Last, to avoid scanning skill roots.
        and not _selects_only_provider_hosted_tools(payload, provider_type, _enabled_agent_skills())
    )
    codex_studio_tool_loop = studio_tool_loop and provider_type == "openai_codex"
    # The loop relays the same control frames the local routes gate (see UI_STREAM_EVENTS_HEADER).
    _ui_events = _ui_stream_events_enabled(request)
    _mcp_image = await _request_mcp_image(payload, _ui_events)
    if not studio_tool_loop:
        _refuse_unused_mcp_image(_mcp_image)
    _drop_keepalive = _DroppedFrameKeepalive()
    # One per request: carries the withheld-call state across the lines of a turn.
    _tool_call_stripper = ServerToolCallStripper()
    # Derive the gate from permission_mode as the local guard does, or a non-stream ask runs unconfirmed.
    _external_confirm_gate = bool(payload.confirm_tool_calls) or (
        not payload.stream and _confirm_gate_needs_stream(payload)
    )
    if (
        _external_confirm_gate
        and not payload.bypass_permissions
        and not studio_tool_loop
        and (
            payload.enable_tools is True
            or bool(payload.enabled_tools)
            or bool(payload.tools)
            or bool(payload.openai_code_exec_container_id)
            or bool(payload.anthropic_code_exec_container_id)
        )
    ):
        raise HTTPException(
            status_code = 400,
            detail = openai_error_body(
                "confirm_tool_calls is only supported for local streaming tools.",
                status = 400,
                code = "invalid_request_error",
                param = "confirm_tool_calls",
            ),
        )
    _provider_info_entry = get_provider_info(provider_type)
    if _provider_info_entry is None or (managed is None and _provider_info_entry.get("managed")):
        raise HTTPException(
            status_code = 400,
            detail = f"Unknown provider type: {provider_type}",
        )
    if not base_url:
        base_url = get_base_url(provider_type)
    if not base_url:
        raise HTTPException(
            status_code = 400,
            detail = f"Base URL is required for provider type: {provider_type}",
        )
    # Validate the proxy destination before the API key is decrypted, so a
    # refused target never sees a credential. A managed upstream is Unsloth's own loopback.
    if managed is None:
        try:
            base_url = await asyncio.to_thread(validate_provider_base_url, base_url)
        except ValueError as exc:
            raise HTTPException(status_code = 400, detail = str(exc)) from None

    if provider_type == "openai_codex":
        from core.inference.openai_codex_auth import (
            OPENAI_CODEX_API_BASE,
            CodexAuthError,
            load_oauth_bundle,
            resolve_access,
        )
        from core.inference.openai_codex_client import (
            OpenAICodexClient,
            CodexTransportError,
            CodexQuotaError,
            CodexReauthorizationError,
            ensure_subscription_models,
            offered_subscription_model,
            offered_subscription_model_ids,
            forget_subscription_models,
            mark_subscription_catalog_stale,
            subscription_catalog_known,
            saved_models_proven_for,
            subscription_catalog_matches_account,
            subscription_catalog_stale,
        )

        # Use the shared helper: a raising probe must withhold the credential, not 500.
        if _request_has_api_key(request) and not _request_is_saved_credential_workflow(request):
            raise HTTPException(
                status_code = 403,
                detail = "ChatGPT subscriptions are available only to Unsloth UI and internal workflows.",
            )
        if not payload.provider_id or payload.encrypted_api_key:
            raise HTTPException(
                status_code = 400, detail = "A saved ChatGPT subscription connection is required."
            )
        if base_url != OPENAI_CODEX_API_BASE:
            raise HTTPException(status_code = 400, detail = "ChatGPT subscription routing is fixed.")
        if payload.stream is not True:
            raise HTTPException(
                status_code = 400, detail = "ChatGPT subscription chat requires stream=true."
            )
        model = payload.external_model or payload.model
        from core.inference.providers import get_provider_info as _get_codex_provider_info

        info = _get_codex_provider_info("openai_codex") or {}

        # /codex/models may list slugs newer than the seed. Drop a catalog from another account.
        current_bundle = load_oauth_bundle(payload.provider_id)
        current_account = current_bundle.get("account_id") if current_bundle else None
        if current_account and not subscription_catalog_matches_account(
            payload.provider_id, current_account
        ):
            forget_subscription_models(payload.provider_id)
            mark_subscription_catalog_stale(payload.provider_id)

        def _allowed_codex_models() -> set[str]:
            """Once read, the plan catalog is the authority; a saved slug survives hide, not a plan dropping it."""
            saved = set(config.get("models") or [])
            if subscription_catalog_known(payload.provider_id):
                return offered_subscription_model_ids(payload.provider_id) | {
                    slug
                    for slug in saved
                    if offered_subscription_model(payload.provider_id, slug) is not None
                }
            if subscription_catalog_stale(payload.provider_id):
                return set(info.get("default_models", []))
            if not saved_models_proven_for(payload.provider_id, current_account):
                # Saved models unproven for this account: a rebind before restart or on another worker leaves this.
                return set(info.get("default_models", []))
            return set(info.get("default_models", [])) | saved

        allowed_models = _allowed_codex_models()
        if model not in allowed_models:
            # Catalog is process-local; refresh once before refusing a saved slug.
            try:
                await ensure_subscription_models(payload.provider_id)
            except (CodexAuthError, CodexReauthorizationError) as exc:
                # Say reconnect: the connection, not the model, is the problem.
                raise HTTPException(status_code = 401, detail = str(exc)) from exc
            allowed_models = _allowed_codex_models()
        if model not in allowed_models:
            raise HTTPException(status_code = 400, detail = "Choose a curated Codex model.")

        capabilities = info.get("model_capabilities", {})
        image_requested = any(
            isinstance(message.content, list)
            and any(part.type == "image_url" for part in message.content)
            for message in payload.messages
        )
        listed_model = (
            None
            if model in capabilities
            else offered_subscription_model(payload.provider_id, model)
        )
        # Vision flag is fixed for the run; an MCP tool may return a picture later.
        _may_receive_image = (
            image_requested
            or (
                _effective_enable_tools(payload) is True
                and (payload.enabled_tools is None or "view_image" in payload.enabled_tools)
            )
            # A tool can hand this loop a picture on a later turn...
            or bool(getattr(payload, "mcp_enabled", False))
            # A conversation already carrying an image needs the capability even with MCP off, or it is stripped.
            or _request_has_promotable_mcp_images(payload, exact = False)
        )
        if _may_receive_image and model not in capabilities and listed_model is None:
            # No catalog read this process; fetch modalities only when an image may be sent.
            try:
                await ensure_subscription_models(payload.provider_id)
            except (CodexAuthError, CodexReauthorizationError) as exc:
                # A dead connection is not a text-only model; this runs before resolve_access, so do not swallow it.
                raise HTTPException(status_code = 401, detail = str(exc)) from exc
            except Exception:
                pass
            listed_model = offered_subscription_model(payload.provider_id, model)
        if model in capabilities:
            model_supports_vision = bool(capabilities[model].get("vision"))
        else:
            # A slug the registry never listed: the plan's own entry is all we know.
            model_supports_vision = bool(listed_model and listed_model.get("vision"))
        if not model_supports_vision:
            for message in payload.messages:
                if isinstance(message.content, list) and any(
                    part.type == "image_url" for part in message.content
                ):
                    raise HTTPException(
                        status_code = 400,
                        detail = f"{model} does not accept image input.",
                    )
        try:
            access_token, account_id = await resolve_access(payload.provider_id)
        except CodexAuthError as exc:
            raise HTTPException(status_code = 401, detail = str(exc)) from exc
        if (current_account and account_id != current_account) or (
            not subscription_catalog_matches_account(payload.provider_id, account_id)
        ):
            # Another worker rebound the connection; drop and re-judge before sending credentials.
            forget_subscription_models(payload.provider_id)
            mark_subscription_catalog_stale(payload.provider_id)
            if model not in _allowed_codex_models():
                raise HTTPException(status_code = 400, detail = "Choose a curated Codex model.")
        _codex_promoted_parts: list = []
        chat_messages = await _build_external_messages_async(
            payload.messages,
            model_supports_vision,
            provider_type = provider_type,
            base_url = base_url,
            promoted_out = _codex_promoted_parts,
        )
        tool_payloads = [
            tool.model_dump(exclude_none = True) if hasattr(tool, "model_dump") else tool
            for tool in (payload.tools or [])
        ]

        studio_tool_payloads: list[dict] = []
        if _explicit_studio_tool_loop_requested(payload):
            studio_tool_payloads = await _select_request_tools(
                payload,
                supports_vision = model_supports_vision,
                tools_on = _effective_enable_tools(payload) is True,
                mcp_allowed = bool(payload.mcp_enabled),
                ui_events = _ui_events,
            )
            if studio_tool_payloads:
                # The tool loop runs only when the catalog is non-empty; its approval handshake rides control frames.
                _reject_confirm_gate_without_channel(
                    payload, _ui_events, selected_names = _catalog_names(studio_tool_payloads)
                )
            # The loop owns its schemas; a caller catalog would yield calls we may not run.
            tool_payloads = studio_tool_payloads
            # Runs python/terminal locally: only the Full access sentence and skill catalog, no general nudge.
            _codex_nudge = _build_tool_action_nudge(
                tools = studio_tool_payloads,
                model_name = model,
                full_access = bool(payload.bypass_permissions),
                full_access_only = True,
            )
            chat_messages = _append_to_codex_instructions(chat_messages, _codex_nudge)
        _refuse_unused_mcp_image(_mcp_image, _catalog_names(studio_tool_payloads))
        chat_messages = _prepend_current_date_to_messages(
            chat_messages,
            request,
            include_api_key = bool(studio_tool_payloads),
        )
        cancel_event = threading.Event()
        cancel_keys = tuple(
            _account_cancel_key(key) for key in (payload.cancel_id, payload.session_id) if key
        )

        async def _codex_stream():
            current_access_token = access_token

            async def _refresh_codex_access() -> tuple[str, str]:
                nonlocal current_access_token
                current_access_token, refreshed_account_id = await resolve_access(
                    payload.provider_id,
                    force_refresh = True,
                    expected_access_token = current_access_token,
                )
                if (current_account and refreshed_account_id != current_account) or (
                    not subscription_catalog_matches_account(
                        payload.provider_id, refreshed_account_id
                    )
                ):
                    # Mid-stream rebind: retrying would send under an unauthorized account.
                    forget_subscription_models(payload.provider_id)
                    mark_subscription_catalog_stale(payload.provider_id)
                    raise CodexAuthError(
                        "This ChatGPT connection changed accounts. Send the message again."
                    )
                return current_access_token, refreshed_account_id

            from core.inference.openai_codex_tool_loop import (
                CodexRunContext,
                CodexToolPolicy,
                stream_codex_with_studio_tools,
            )

            run = CodexRunContext(
                provider_id = payload.provider_id,
                thread_id = payload.thread_id,
                session_id = payload.session_id,
                messages = chat_messages,
                model = model,
                reasoning_effort = payload.reasoning_effort,
                response_format = _extract_response_format(payload),
                tool_choice = payload.tool_choice,
                continue_final_message = _continue_final_message(payload),
                supports_vision = model_supports_vision,
                promoted_image_parts = tuple(_codex_promoted_parts),
            )
            policy = (
                CodexToolPolicy(
                    tools = studio_tool_payloads,
                    max_calls = (
                        payload.max_tool_calls_per_message
                        if payload.max_tool_calls_per_message is not None
                        else 25
                    ),
                    timeout = payload.tool_call_timeout or 300,
                    permission_mode = payload.permission_mode or "auto",
                    sandbox_level = payload.sandbox_level,
                    confirm_calls = _permission_mode_confirm(payload)
                    or _off_mode_sandbox_gate(payload, _ui_events),
                    bypass_permissions = bool(payload.bypass_permissions),
                    rag_scope = payload.rag_scope,
                    nudge_tool_calls = payload.nudge_tool_calls,
                    deduplicate_tool_calls = payload.deduplicate_tool_calls,
                )
                if studio_tool_payloads
                else None
            )
            should_cancel = False
            with _CANCEL_LOCK:
                now = time.monotonic()
                _prune_pending(now)
                for key in cancel_keys:
                    _CANCEL_REGISTRY.setdefault(key, set()).add(cancel_event)
                if (
                    payload.cancel_id
                    and _PENDING_CANCELS.pop(_account_cancel_key(payload.cancel_id), None)
                    is not None
                ):
                    should_cancel = True
            if should_cancel:
                cancel_event.set()

            async def _watch_disconnect() -> None:
                while not cancel_event.is_set():
                    if await request.is_disconnected():
                        cancel_event.set()
                        return
                    await asyncio.sleep(0.1)

            disconnect_task = asyncio.create_task(_watch_disconnect())

            client = OpenAICodexClient(
                access_token,
                account_id,
                refresh_access = _refresh_codex_access,
            )
            try:
                # Closing upstream from the watcher makes cancel immediate even while no SSE line arrives.
                generator = (
                    stream_codex_with_studio_tools(
                        client,
                        run = run,
                        policy = policy,
                        cancel_event = cancel_event,
                        mcp_image = _mcp_image,
                    )
                    if policy
                    else client.stream(
                        provider_id = run.provider_id,
                        thread_id = run.thread_id,
                        messages = run.messages,
                        model = run.model,
                        max_tokens = _effective_max_tokens(payload),
                        reasoning_effort = run.reasoning_effort,
                        response_format = run.response_format,
                        tools = tool_payloads,
                        tool_choice = payload.tool_choice,
                        cancel_event = cancel_event,
                    )
                )
                async for line in generator:
                    if cancel_event.is_set() or await request.is_disconnected():
                        await generator.aclose()
                        break
                    if not _ui_events and is_ui_control_sse_line(line):
                        if _drop_keepalive.due():
                            yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                        continue
                    if not _ui_events and policy is not None:
                        # Policy is set only when the loop owns the catalogue, so a call here is one this server runs.
                        line = _tool_call_stripper.strip(line)
                        if line is None:
                            # Withheld tool-call fragments are dropped here, and like gated frames they hold off the stall timer.
                            if _drop_keepalive.due():
                                yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                            continue
                    yield f"{line}\n\n"
                # The loop can end without opening the turn a withheld call promised; flush the owed terminal chunk.
                _owed = _tool_call_stripper.owed_terminal_chunk()
                if _owed is not None:
                    yield f"{_owed}\n\n"
                yield "data: [DONE]\n\n"
            except asyncio.CancelledError:
                raise
            except CodexReauthorizationError as exc:
                from core.inference.openai_codex_auth import (
                    mark_reauthorization_required,
                    provider_oauth_write_guard,
                )

                async with provider_oauth_write_guard(payload.provider_id):
                    mark_reauthorization_required(
                        payload.provider_id,
                        expected_access_token = exc.metadata.get("access_token"),
                    )
                yield (
                    "data: "
                    + json.dumps({"error": {"message": str(exc), "type": "authentication_error"}})
                    + "\n\n"
                )
                yield "data: [DONE]\n\n"
            except CodexQuotaError as exc:
                yield (
                    "data: "
                    + json.dumps(
                        {
                            "error": {
                                "message": str(exc),
                                "type": "rate_limit_error",
                                "metadata": exc.metadata,
                            }
                        }
                    )
                    + "\n\n"
                )
                yield "data: [DONE]\n\n"

            except CodexTransportError as exc:
                logger.warning(
                    "openai_codex.stream_failed",
                    error_type = type(exc).__name__,
                    status = exc.status,
                    error = str(exc),
                )
                yield (
                    "data: "
                    + json.dumps({"error": {"message": str(exc), "type": "upstream_error"}})
                    + "\n\n"
                )
                yield "data: [DONE]\n\n"

            except Exception as exc:
                logger.warning(
                    "openai_codex.stream_failed",
                    error_type = type(exc).__name__,
                    status = getattr(exc, "status", None),
                    error = str(exc),
                )
                yield (
                    "data: "
                    + json.dumps(
                        {"error": {"message": _friendly_error(exc), "type": "server_error"}}
                    )
                    + "\n\n"
                )
                yield "data: [DONE]\n\n"
            finally:
                await client.close()
                await _stop_local_disconnect_cancel_watcher(disconnect_task)

                with _CANCEL_LOCK:
                    for key in cancel_keys:
                        bucket = _CANCEL_REGISTRY.get(key)
                        if bucket:
                            bucket.discard(cancel_event)
                            if not bucket:
                                _CANCEL_REGISTRY.pop(key, None)

        return StreamingResponse(
            _codex_stream(),
            media_type = "text/event-stream",
            headers = {"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    api_key: Optional[str] = None
    if managed is not None:
        api_key = managed.api_key
    elif saved_provider_snapshot is not None:
        async with provider_config_guard(
            payload.provider_id,
            shared_by_owner = bool(saved_provider_snapshot.get("shared_by_owner")),
        ):
            current = await asyncio.to_thread(providers_db.get_provider, payload.provider_id)
            routing_fields = (
                "provider_type",
                "base_url",
                "api_type",
                "is_enabled",
                "reasoning_config",
            )
            if current is None or any(
                current.get(field) != saved_provider_snapshot.get(field) for field in routing_fields
            ):
                raise HTTPException(
                    status_code = 409,
                    detail = "Provider changed while the request was starting; retry.",
                )
            account_access.require_connection_model_allowed(
                current, payload.external_model or payload.model
            )
            api_key = await asyncio.to_thread(
                resolve_provider_api_key_or_400,
                payload.provider_id,
                payload.encrypted_api_key,
                allow_saved_key = _request_may_use_saved_provider_key(request),
            )
    else:
        api_key = resolve_provider_api_key_or_400(
            payload.provider_id,
            payload.encrypted_api_key,
            # Scoped to the Deep Research workflow key: other internal keys belong to user recipes.
            allow_saved_key = (
                not _request_has_api_key(request) or _request_is_saved_credential_workflow(request)
            ),
        )

    model = managed.model if managed is not None else (payload.external_model or payload.model)
    if model == "default":
        raise HTTPException(
            status_code = 400,
            detail = "external_model is required when using an external provider.",
        )

    # Build messages, preserving multimodal content for vision providers
    from core.inference.providers import get_provider_info as _get_provider_info

    _pinfo = _get_provider_info(provider_type) or {}
    _supports_vision = (
        managed.supports_vision if managed is not None else _pinfo.get("supports_vision", False)
    )
    _external_promoted_parts: list = []
    chat_messages = await _build_external_messages_async(
        payload.messages,
        # Provider-wide flag for caller images; model-level answer gates MCP promotion only.
        _supports_vision,
        provider_type = provider_type,
        base_url = base_url,
        api_type = api_type,
        promoted_out = _external_promoted_parts,
        promote_mcp_images = _external_takes_mcp_images(
            provider_type, _supports_vision, model, _pinfo
        ),
        model = model,
        preserve_thinking = payload.preserve_thinking,
    )
    monitor_id = None
    if not getattr(request.state, "skip_api_monitor", False):
        monitor_id = api_monitor.start(
            endpoint = request.url.path,
            via_api_key = _request_used_api_key(request),
            method = request.method,
            model = managed.public_model if managed is not None else model,
            prompt = _monitor_prompt_from_messages(payload.messages),
            context_length = managed.context_length if managed is not None else None,
            subject = current_subject,
        )

    client = await asyncio.to_thread(
        ExternalProviderClient,
        provider_type = provider_type,
        base_url = base_url,
        api_key = api_key,
        api_type = api_type,
        **({"reasoning_config": reasoning_config} if reasoning_config is not None else {}),
        **({"managed_loopback": True} if managed is not None else {}),
    )
    _non_stream_custom_responses = (
        provider_type == "custom" and api_type == "responses" and payload.stream is False
    )

    # Always send defaults to FastFlowLM, which otherwise reuses the previous request's values.
    _always_send = managed is not None
    _top_p_explicit = payload.top_p if _always_send or "top_p" in payload.model_fields_set else None
    _top_k_explicit = payload.top_k if _always_send or "top_k" in payload.model_fields_set else None
    _min_p_explicit = payload.min_p if "min_p" in payload.model_fields_set else None
    _repetition_penalty_explicit = (
        payload.repetition_penalty
        if _always_send or "repetition_penalty" in payload.model_fields_set
        else None
    )

    # Same selector as local/Codex: omitted enabled_tools means all allowed built-ins; [] stays empty.
    external_studio_tools: list[dict] = []
    if studio_tool_loop:
        external_studio_tools = await _select_request_tools(
            payload,
            supports_vision = _external_takes_mcp_images(
                provider_type, _supports_vision, model, _pinfo
            ),
            tools_on = _effective_enable_tools(payload) is True,
            mcp_allowed = bool(payload.mcp_enabled),
            ui_events = _ui_events,
        )
    run_studio_tool_loop = bool(external_studio_tools)
    _external_fit_tools = external_studio_tools if run_studio_tool_loop else payload.tools
    _refuse_unused_mcp_image(_mcp_image, _catalog_names(external_studio_tools))
    if run_studio_tool_loop:
        # Only once the catalog is known: mcp_enabled with no MCP tools skips the loop and needs no channel.
        _reject_confirm_gate_without_channel(
            payload, _ui_events, monitor_id, _catalog_names(external_studio_tools)
        )
    # Built before the date, because whether a nudge exists decides whether the server prompt
    # exemption is worth claiming: _append_to_system_message below displaces that prompt anyway.
    # Full access disables the sandbox, so the schemas say so; the general nudge stays off this path.
    _external_nudge = ""
    if run_studio_tool_loop:
        _external_nudge = _build_tool_action_nudge(
            tools = external_studio_tools,
            model_name = model,
            full_access = bool(payload.bypass_permissions),
            full_access_only = True,
        )
        # The compaction nudge is not part of the general nudge: once the thread has an archive
        # the catalogue carries search_conversation, and without this the model is never told
        # that turns it cannot see exist, so it answers that it has no record of them. Not when
        # no call can happen: the loop withdraws the catalogue and inline recall still runs.
        if not _tool_calls_are_disabled(payload):
            _external_nudge = _apply_compaction_nudge(
                _external_nudge, external_studio_tools, payload = payload
            )
    _served_template = None
    if (
        provider_type == "llama_cpp"
        and not _external_nudge
        and not _date_gate_blocks(request, run_studio_tool_loop)
        and current_date_prompt_line(request = request)
        and not any(m.get("role") in ("system", "developer") for m in chat_messages)
    ):
        _served_template = await client.served_chat_template(model)
    chat_messages = _prepend_current_date_to_messages(
        chat_messages,
        request,
        include_api_key = run_studio_tool_loop,
        provider_type = None if _external_nudge else provider_type,
        served_template = _served_template,
        tools = bool(external_studio_tools or payload.tools),
        controls = llama_cpp_template_controls(
            payload.enable_thinking, payload.reasoning_effort, payload.preserve_thinking
        ),
    )
    if _external_nudge:
        chat_messages = _append_to_system_message(chat_messages, _external_nudge)
    _provider_compacts = compacts_server_side(provider_type, base_url, api_type, model)
    # UNSLOTH_CONTEXT_OVERFLOW must not bypass Studio's auto-compact switch.
    if (
        managed is None
        and payload.context_overflow == "truncate_oldest"
        and not payload.compaction_threshold
        and not _provider_compacts
    ):
        # a self-hosted server reports its startup window when the catalog has none.
        _served_window = payload.context_window or await client.served_context_window(model)
        if _served_window:
            payload = payload.model_copy(
                update = {
                    "context_window": _served_window,
                    "compaction_threshold": min(
                        _EXTERNAL_COMPACTION_THRESHOLD_MAX,
                        int(_served_window * (1 - _EXTERNAL_COMPACTION_HEADROOM)),
                    ),
                }
            )
    _external_truncation = None
    _external_max_tokens = _effective_max_tokens(payload)
    _external_context_fitter = None
    _compaction_fallback = None
    if payload.compaction_threshold and _rolling_context_policy(payload) is not None:
        _request_branch = chat_messages

        async def _external_context_fitter(messages):
            nonlocal _external_truncation
            fitted, truncation, fallback_max_tokens = await asyncio.to_thread(
                _fit_external_context,
                messages,
                payload,
                tools = _external_fit_tools,
                branch = _request_branch,
                tool_loop = run_studio_tool_loop and not _tool_calls_are_disabled(payload),
            )
            fitted = _date_a_fitted_system_turn(fitted, request, run_studio_tool_loop)
            if truncation and truncation.get("dropped_messages"):
                _external_truncation = truncation
            truncation_line = None
            if (
                truncation
                and truncation.get("dropped_messages")
                and not _non_stream_custom_responses
            ):
                truncation_line = _context_truncated_sse_chunk(
                    f"chatcmpl-{uuid.uuid4().hex}", model, truncation
                ).rstrip("\n")
            return fitted, fallback_max_tokens, truncation_line

        if _provider_compacts and (provider_type == "openai" or api_type == "responses"):
            _compaction_fallback = _external_context_fitter

    if (
        payload.compaction_threshold
        and not _provider_compacts
        and not run_studio_tool_loop
        and _rolling_context_policy(payload) is not None
    ):
        chat_messages, _external_truncation, _external_max_tokens = await asyncio.to_thread(
            _fit_external_context,
            chat_messages,
            payload,
            tools = _external_fit_tools,
        )
        chat_messages = _date_a_fitted_system_turn(chat_messages, request, run_studio_tool_loop)

    cancel_event = threading.Event()
    cancel_keys = tuple(key for key in (payload.cancel_id, payload.session_id) if key)

    async def _watch_disconnect() -> None:
        # tool execution may emit no SSE lines for minutes, so poll for disconnects.
        while not cancel_event.is_set():
            if await request.is_disconnected():
                cancel_event.set()
                return
            await asyncio.sleep(0.1)

    async def _stream():
        _provider_kwargs = dict(
            temperature = (
                None
                if provider_type == "custom"
                and api_type == "responses"
                and "temperature" not in payload.model_fields_set
                else payload.temperature
            ),
            top_p = _top_p_explicit,
            # honor max_completion_tokens when max_tokens is absent to avoid provider defaults.
            max_tokens = _external_max_tokens,
            presence_penalty = payload.presence_penalty,
            top_k = _top_k_explicit,
            min_p = _min_p_explicit,
            repetition_penalty = _repetition_penalty_explicit,
            enable_thinking = payload.enable_thinking,
            reasoning_effort = payload.reasoning_effort,
            preserve_thinking = payload.preserve_thinking,
            enable_prompt_caching = payload.enable_prompt_caching,
            openai_code_exec_container_id = payload.openai_code_exec_container_id,
            anthropic_code_exec_container_id = payload.anthropic_code_exec_container_id,
            prompt_cache_ttl = payload.prompt_cache_ttl,
            compaction_threshold = payload.compaction_threshold,
            compaction_fallback = _compaction_fallback,
            fast_mode = payload.fast_mode,
            response_format = _extract_response_format(payload),
            thread_id = payload.thread_id,
        )
        # A managed runtime that drops a reply still closes with [DONE]; it is cut short, not done.
        managed_finish = _TurnFinish()
        if run_studio_tool_loop:
            # Drop caller catalog and hosted names Unsloth runs; endpoint check must match Responses translator.
            hosted_provider_type = (
                "openai"
                if provider_type == "custom"
                and api_type == "responses"
                and _is_openai_family_cloud(base_url)
                else provider_type
            )
            loop_hosted_tools = hosted_only_tools(hosted_provider_type, payload.enabled_tools)

            def _end_provider_turn() -> None:
                managed_finish.end_turn()
                if not _ui_events:
                    _tool_call_stripper.end_turn()

            gen = stream_with_studio_tools(
                OAICompatTransport(
                    client,
                    model = model,
                    continue_final_message = _continue_final_message(payload),
                    message_fitter = (_external_context_fitter if not _provider_compacts else None),
                    enabled_tools = loop_hosted_tools or None,
                    stream = True,
                    **_provider_kwargs,
                ),
                run = ToolLoopRun(
                    messages = chat_messages,
                    session_id = payload.session_id,
                    thread_id = payload.thread_id,
                    # Only model id the client sees; if omitted it falls back to external, and usage is unattributed.
                    model = model,
                    tool_choice = payload.tool_choice,
                    continue_final_message = _continue_final_message(payload),
                    supports_vision = _external_takes_mcp_images(
                        provider_type, _supports_vision, model, _pinfo
                    ),
                    promoted_image_parts = tuple(_external_promoted_parts),
                ),
                policy = ToolLoopPolicy(
                    tools = external_studio_tools,
                    max_calls = (
                        payload.max_tool_calls_per_message
                        if payload.max_tool_calls_per_message is not None
                        else 25
                    ),
                    timeout = payload.tool_call_timeout or 300,
                    permission_mode = payload.permission_mode or "auto",
                    sandbox_level = payload.sandbox_level,
                    confirm_calls = _permission_mode_confirm(payload)
                    or _off_mode_sandbox_gate(payload, _ui_events),
                    bypass_permissions = bool(payload.bypass_permissions),
                    rag_scope = payload.rag_scope,
                    auto_heal = payload.auto_heal_tool_calls,
                    nudge_tool_calls = payload.nudge_tool_calls,
                    deduplicate_tool_calls = payload.deduplicate_tool_calls,
                    # Matches the strip below: only a headerless caller has its calls
                    # withheld, so only it needs a healed one the wire never carried flagged.
                    on_withheld_tool_call = (None if _ui_events else _tool_call_stripper.arm),
                    on_provider_turn_end = _end_provider_turn,
                ),
                cancel_event = cancel_event,
                mcp_image = _mcp_image,
            )
        else:
            gen = client.stream_chat_completion(
                messages = chat_messages,
                model = model,
                enabled_tools = payload.enabled_tools,
                tools = payload.tools,
                tool_choice = payload.tool_choice,
                continue_final_message = _continue_final_message(payload),
                stream = payload.stream,
                **_provider_kwargs,
            )
        if managed is not None:
            # Stopping the read stops FastFlowLM, which a model swap is waiting on.
            gen = _stop_on_cancel(gen, cancel_event)
        disconnect_task = asyncio.create_task(_watch_disconnect()) if run_studio_tool_loop else None

        def _managed_cut_short() -> bool:
            return (
                managed is not None
                and not stream_failed
                and not managed_finish.finished
                and not cancel_event.is_set()
            )

        def _fail_cut_short() -> str:
            api_monitor.fail(monitor_id, _NPU_CUT_SHORT_ERROR["message"])
            return "data: " + json.dumps({"error": dict(_NPU_CUT_SHORT_ERROR)}) + "\n\n"

        try:
            sent_done = False
            stream_failed = False
            if (
                _external_truncation
                and _external_truncation.get("dropped_messages")
                and not _non_stream_custom_responses
            ):
                yield _context_truncated_sse_chunk(
                    f"chatcmpl-{uuid.uuid4().hex}", model, _external_truncation
                )
            provider_compaction_reported = False
            async for line in gen:
                if _is_openai_sse_done(line) and _managed_cut_short():
                    # intercept [DONE] before the monitor records a cut-short reply as complete.
                    yield _fail_cut_short()
                    stream_failed = True
                if managed is not None:
                    managed_finish.see(line)
                monitor_event = _monitor_openai_sse_line(monitor_id, line)
                if monitor_event is None:
                    try:
                        # stamp TTFT only for delta streams; stream:false reports total latency.
                        _monitor_openai_chunk(
                            monitor_id, json.loads(line), streaming = bool(payload.stream)
                        )
                    except Exception:
                        pass
                if _non_stream_custom_responses:
                    yield line
                    continue
                if monitor_event == "error":
                    stream_failed = True
                # Providers always send usage; hide the usage-only chunk unless the caller opted in.
                if not _wants_stream_usage(payload) and _is_openai_usage_only_sse(line):
                    continue
                if not _ui_events and is_ui_control_sse_line(line):
                    if _drop_keepalive.due():
                        yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                    continue
                if not _ui_events and run_studio_tool_loop:
                    # strip calls only in the loop because plain-proxy calls belong to the caller.
                    line = _tool_call_stripper.strip(line)
                    if line is None:
                        if _drop_keepalive.due():
                            yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                        continue
                yield f"{line}\n\n"
                if (
                    _provider_compacts
                    and not provider_compaction_reported
                    and _is_compaction_block_sse(line)
                ):
                    provider_compaction_reported = True
                    yield _context_truncated_sse_chunk(
                        f"chatcmpl-{uuid.uuid4().hex}",
                        model,
                        _provider_compaction_truncation(chat_messages),
                    )
                # inspect the line directly because a disabled monitor would duplicate [DONE].
                if _is_openai_sse_done(line):
                    sent_done = True
            if _non_stream_custom_responses:
                return
            # emit withheld terminal state before [DONE] if the loop did not open the promised turn.
            _owed = _tool_call_stripper.owed_terminal_chunk()
            if _owed is not None and not stream_failed:
                managed_finish.see(_owed)
                _monitor_openai_sse_line(monitor_id, _owed)
                yield f"{_owed}\n\n"
            if not sent_done and _managed_cut_short():
                yield _fail_cut_short()
                stream_failed = True
            if managed is not None and cancel_event.is_set() and not sent_done:
                yield (
                    "data: "
                    + json.dumps(
                        {
                            "id": f"chatcmpl-{uuid.uuid4().hex}",
                            "object": "chat.completion.chunk",
                            "created": int(time.time()),
                            "model": model,
                            "choices": [{"index": 0, "delta": {}, "finish_reason": "stop"}],
                        }
                    )
                    + "\n\n"
                )
            if not sent_done:
                if not stream_failed:
                    _monitor_openai_sse_line(monitor_id, "data: [DONE]")
                yield "data: [DONE]\n\n"
        except asyncio.CancelledError:
            api_monitor.finish(monitor_id, "cancelled")
            raise
        except GeneratorExit:
            api_monitor.finish(
                monitor_id, early_close_status() if early_close_status else "cancelled"
            )
            raise
        except Exception as exc:
            logger.error("external_provider.stream_error", error = str(exc))
            api_monitor.fail(monitor_id, _friendly_error(exc))
            if _non_stream_custom_responses:
                yield json.dumps(
                    {"error": {"message": _friendly_error(exc), "type": "server_error"}}
                )
                return
            # A bare EOF reads as success to the chat client; surface the failure.
            yield (
                "data: "
                + json.dumps({"error": {"message": _friendly_error(exc), "type": "server_error"}})
                + "\n\n"
            )
            yield "data: [DONE]\n\n"
        finally:
            cancel_event.set()
            if disconnect_task is not None:
                # cancel_event ends the loop if is_disconnected() swallows cancellation (#7617).
                disconnect_task.cancel()
                await asyncio.gather(disconnect_task, return_exceptions = True)
            try:
                await gen.aclose()
            except RuntimeError:
                pass  # httpcore cleanup may raise on Python 3.13 with httpcore 1.0.x
            await client.close()

    def _tracked_stream():
        if not run_studio_tool_loop and managed is None:
            return _stream()

        async def _wrapped():
            inner = _stream()
            with _TrackedCancel.for_payload(
                cancel_event, payload, *cancel_keys, external = managed is None
            ):
                try:
                    async for chunk in inner:
                        yield chunk
                finally:
                    # explicit close releases the upstream request before garbage collection.
                    await inner.aclose()

        return _wrapped()

    if _non_stream_custom_responses:
        body = "".join([chunk async for chunk in _stream()])
        try:
            content = json.loads(body)
        except json.JSONDecodeError:
            logger.error("external_provider.non_stream_invalid_json")
            api_monitor.fail(
                monitor_id,
                "External provider returned an invalid non-streaming response.",
            )
            return JSONResponse(
                status_code = 502,
                content = openai_error_body(
                    "External provider returned an invalid non-streaming response.",
                    status = 502,
                ),
            )
        error_message = (
            _monitor_openai_error_message(content) if isinstance(content, dict) else None
        )
        if (
            not error_message
            and isinstance(content, dict)
            and _external_truncation
            and _external_truncation.get("dropped_messages")
        ):
            content["context_truncated"] = _external_truncation
        retry_after_header = None
        if error_message:
            api_monitor.fail(monitor_id, error_message)
            error = content.get("error") if isinstance(content, dict) else None
            raw_status = error.get("code") if isinstance(error, dict) else None
            retry_after_header = _safe_retry_after_header(
                error.get("retry_after") if isinstance(error, dict) else None
            )
            try:
                upstream_status = int(raw_status)
            except (TypeError, ValueError):
                upstream_status = 0
            status_code = upstream_status if 400 <= upstream_status <= 599 else 502
        else:
            api_monitor.finish(monitor_id)
            status_code = 200
        return JSONResponse(
            status_code = status_code,
            content = content,
            headers = (
                {"Retry-After": retry_after_header} if retry_after_header is not None else None
            ),
        )

    return StreamingResponse(
        _tracked_stream(),
        media_type = "text/event-stream",
        headers = {
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
        },
    )


_NPU_CUT_SHORT_ERROR = {
    "message": "The NPU model stopped before finishing its reply.",
    "type": "upstream_error",
}


def _npu_kv_cache_full(usage: Any) -> bool:
    """Whether FastFlowLM's usage says the reply used the whole loaded context."""
    if not isinstance(usage, dict):
        return False
    # active_kv_tokens is the KV position; total_tokens undercounts by the empty think block's
    # three uncounted tokens when thinking is off.
    total = usage.get("active_kv_tokens")
    if not isinstance(total, int):
        total = usage.get("total_tokens")
    capacity = usage.get("max_kv_token_capacity")
    return (
        isinstance(total, int) and isinstance(capacity, int) and capacity > 0 and total >= capacity
    )


class _NpuStreamRelay:
    """Normalize model IDs, enforce stop sequences, and collect non-streaming replies.

    FastFlowLM ignores stop sequences, so buffer partial matches until resolved.
    """

    def __init__(self, public_model: str, stop: Optional[list[str]]) -> None:
        self.public_model = public_model
        self.stop = stop or []
        self._pending = ""
        self.stopped = False
        self.content = ""
        self.reasoning = ""
        self.tool_calls: dict[int, dict] = {}
        self.finish_reason: Optional[str] = None
        self.usage: Optional[dict] = None
        self.error: Optional[dict] = None
        self.completion_id: Optional[str] = None
        self.created: Optional[int] = None

    def _held_back(self, text: str) -> int:
        """Length of the longest tail of ``text`` that begins some stop sequence."""
        longest = 0
        for stop in self.stop:
            for size in range(min(len(stop) - 1, len(text)), 0, -1):
                if stop.startswith(text[-size:]):
                    longest = max(longest, size)
                    break
        return longest

    def _take_content(self, text: str) -> str:
        buffer = self._pending + text
        hits = [index for index in (buffer.find(stop) for stop in self.stop) if index >= 0]
        if hits:
            self._pending = ""
            self.stopped = True
            return buffer[: min(hits)]
        keep = self._held_back(buffer)
        self._pending = buffer[len(buffer) - keep :] if keep else ""
        return buffer[: len(buffer) - keep] if keep else buffer

    def _chunk(
        self,
        delta: dict,
        finish_reason: Optional[str],
        tool_event: Optional[dict] = None,
    ) -> str:
        chunk = {
            "id": self.completion_id or "chatcmpl-npu",
            "object": "chat.completion.chunk",
            "created": self.created or int(time.time()),
            "model": self.public_model,
            "choices": [{"index": 0, "delta": delta, "finish_reason": finish_reason}],
        }
        if tool_event is not None:
            chunk["_toolEvent"] = tool_event
        return "data: " + json.dumps(chunk)

    def feed(self, line: str) -> list[str]:
        """The lines to send on for one line of the upstream stream."""
        if not line.startswith("data:"):
            return [line]
        raw = line[len("data:") :].strip()
        if raw == "[DONE]":
            out = []
            if self._pending:
                self.content += self._pending
                out.append(self._chunk({"content": self._pending}, None))
                self._pending = ""
            out.append(line)
            return out
        try:
            chunk = json.loads(raw)
        except ValueError:
            return [line]
        if not isinstance(chunk, dict):
            return [line]
        if "error" in chunk:
            self.error = (
                chunk["error"]
                if isinstance(chunk["error"], dict)
                else {"message": str(chunk["error"])}
            )
            return [line]
        self.completion_id = self.completion_id or chunk.get("id")
        self.created = self.created or chunk.get("created")
        if "model" in chunk:
            chunk["model"] = self.public_model
        if isinstance(chunk.get("usage"), dict):
            self.usage = chunk["usage"]
        out: list[str] = []
        for choice in chunk.get("choices") or []:
            if not isinstance(choice, dict):
                continue
            delta = choice.get("delta") if isinstance(choice.get("delta"), dict) else {}
            reasoning = delta.get("reasoning_content")
            if isinstance(reasoning, str):
                self.reasoning += reasoning
            for call in delta.get("tool_calls") or []:
                if not isinstance(call, dict):
                    continue
                slot = self.tool_calls.setdefault(
                    int(call.get("index", len(self.tool_calls))),
                    {"id": None, "type": "function", "function": {"name": "", "arguments": ""}},
                )
                slot["id"] = call.get("id") or slot["id"]
                function = call.get("function") or {}
                slot["function"]["name"] += function.get("name") or ""
                slot["function"]["arguments"] += function.get("arguments") or ""
            content = delta.get("content")
            if isinstance(content, str) and self.stop:
                visible = self._take_content(content)
                self.content += visible
                delta["content"] = visible
                if self.stopped:
                    self.finish_reason = "stop"
                    choice["finish_reason"] = None
                    out.append("data: " + json.dumps(chunk))
                    out.append(self._chunk({}, "stop"))
                    out.append("data: [DONE]")
                    return out
            elif isinstance(content, str):
                self.content += content
            if choice.get("finish_reason") is not None:
                if choice["finish_reason"] == "stop" and _npu_kv_cache_full(chunk.get("usage")):
                    # FastFlowLM says "stop" when the reply filled the context.
                    choice["finish_reason"] = "length"
                    out.append(self._chunk({}, None, {"type": "context_window_exceeded"}))
                self.finish_reason = choice["finish_reason"]
                if self._pending:
                    # The reply ended partway into a stop sequence, so what was held back is text.
                    delta["content"] = (delta.get("content") or "") + self._pending
                    self.content += self._pending
                    self._pending = ""
                    choice["delta"] = delta
        out.append("data: " + json.dumps(chunk))
        return out

    def completion(self) -> dict:
        # A tool-calling turn often streams only newlines as text; OpenAI sends null content there.
        content = self.content if self.content.strip() or not self.tool_calls else ""
        message: dict[str, Any] = {"role": "assistant", "content": content or None}
        if self.reasoning:
            message["reasoning_content"] = self.reasoning
        if self.tool_calls:
            message["tool_calls"] = [self.tool_calls[index] for index in sorted(self.tool_calls)]
        body = {
            "id": self.completion_id or f"chatcmpl-{uuid.uuid4().hex}",
            "object": "chat.completion",
            "created": self.created or int(time.time()),
            "model": self.public_model,
            "choices": [
                {
                    "index": 0,
                    "message": message,
                    "finish_reason": self.finish_reason or "stop",
                    "logprobs": None,
                }
            ],
        }
        if self.usage is not None:
            body["usage"] = self.usage
        return body


def _refuse_npu_chat_request(payload, *, supports_vision: bool, supports_tools: bool) -> None:
    """Reject a chat request FastFlowLM cannot serve; also run before a switch to an NPU model."""
    if _wants_multiple_choices(payload):
        _raise_unsupported_n("NPU chat completions")
    if _response_format_constrains_decoding(payload):
        _raise_unsupported_openai_parameter(
            "response_format", "FastFlowLM on the NPU has no guided decoding for response_format."
        )
    if getattr(payload, "seed", None) is not None:
        _raise_unsupported_openai_parameter(
            "seed", "FastFlowLM on the NPU does not take a sampling seed."
        )
    if getattr(payload, "frequency_penalty", 0.0):
        _raise_unsupported_openai_parameter(
            "frequency_penalty", "FastFlowLM on the NPU does not take a frequency penalty."
        )
    if getattr(payload, "logit_bias", None):
        _raise_unsupported_openai_parameter(
            "logit_bias", "FastFlowLM on the NPU does not take a logit bias."
        )
    if payload.logprobs or payload.top_logprobs is not None:
        _raise_unsupported_openai_parameter(
            "logprobs", "FastFlowLM on the NPU does not report log probabilities."
        )
    if (
        _request_has_video(payload)
        or payload.audio_base64
        or _messages_have_input_audio(payload.messages)
    ):
        raise HTTPException(
            status_code = 400, detail = "Audio and video input are not supported on the NPU."
        )
    if not supports_vision and _request_has_attached_image(payload):
        raise HTTPException(
            status_code = 400,
            detail = "This NPU model does not read images. Load a vision model to send one.",
        )
    if payload.tools and payload.tool_choice != "none":
        if payload.parallel_tool_calls is False:
            _raise_unsupported_openai_parameter(
                "parallel_tool_calls",
                "FastFlowLM on the NPU cannot limit a reply to one tool call.",
            )
        if payload.tool_choice not in (None, "auto"):
            _raise_unsupported_openai_parameter(
                "tool_choice", "FastFlowLM on the NPU chooses its own tool; use auto or none."
            )
        if not supports_tools:
            raise HTTPException(
                status_code = 400,
                detail = openai_error_body(
                    "This NPU model does not support tool calling.",
                    status = 400,
                    code = "unsupported_parameter",
                    param = "tools",
                ),
            )


async def _npu_chat_completions(payload, request: Request, current_subject: str):
    """Proxy NPU chat, rejecting unsupported parameters.

    Always stream upstream: FastFlowLM's non-streaming replies mishandle reasoning
    and finish reasons on length cutoffs. Collect the stream for JSON callers.
    """
    from core.inference.npu_backend import NpuError, get_npu_backend

    try:
        upstream = await asyncio.to_thread(get_npu_backend().upstream)
    except NpuError as exc:
        raise HTTPException(status_code = 400, detail = str(exc)) from None
    _refuse_npu_chat_request(
        payload,
        supports_vision = upstream.supports_vision,
        supports_tools = upstream.supports_tools,
    )
    if payload.tool_choice == "none":
        # FastFlowLM 1.0.3 ignores tool_choice and calls a tool anyway.
        payload.tools = None

    _normalize_chat_reasoning_controls(payload)
    if not upstream.supports_reasoning:
        payload.enable_thinking = False
    elif payload.enable_thinking is None:
        payload.enable_thinking = payload.reasoning_effort != "none"
    _fill_recommended_sampling_openai(
        payload,
        upstream.model,
        thinking = payload.enable_thinking if upstream.supports_reasoning else None,
    )

    wants_stream = bool(payload.stream)
    relay = _NpuStreamRelay(upstream.public_model, _normalize_stop_sequences(payload.stop))
    update: dict = {"stream": True}
    if _legacy_image_is_distinct(payload):
        # The proxy reads messages only, so splice a top-level image in as GGUF chat does.
        update["messages"] = [
            ChatMessage.model_validate(message)
            for message in _openai_messages_for_passthrough(payload, vision = True)
        ]
    upstream_payload = payload.model_copy(update = update)
    response = await _proxy_to_external_provider(
        upstream_payload,
        request,
        current_subject,
        managed = upstream,
        early_close_status = lambda: "completed" if relay.stopped else "cancelled",
    )

    async def _lines():
        body = response.body_iterator
        try:
            async for piece in body:
                text = piece.decode("utf-8") if isinstance(piece, bytes) else piece
                for line in text.split("\n"):
                    if line.strip():
                        yield line
        finally:
            await body.aclose()

    if wants_stream:

        async def _stream():
            lines = _lines()
            try:
                async for line in lines:
                    for out in relay.feed(line):
                        yield f"{out}\n\n"
                    if relay.stopped:
                        return
            finally:
                await lines.aclose()

        return StreamingResponse(
            _stream(),
            media_type = "text/event-stream",
            headers = {"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    # Nothing cancels a handler whose caller left, so watch for it: FastFlowLM is the one runtime.
    disconnected = threading.Event()

    async def _watch_disconnect() -> None:
        while not disconnected.is_set():
            if await request.is_disconnected():
                disconnected.set()
                return
            await asyncio.sleep(0.25)

    watcher = asyncio.create_task(_watch_disconnect())
    lines = _stop_on_cancel(_lines(), disconnected)
    try:
        async for line in lines:
            relay.feed(line)
            if relay.stopped or relay.error is not None:
                break
    finally:
        await _stop_local_disconnect_cancel_watcher(watcher)
        await lines.aclose()
    if disconnected.is_set():
        return Response(status_code = 499)
    if relay.error is not None:
        try:
            status = int(relay.error.get("code") or 502)
        except (TypeError, ValueError):
            status = 502
        status = status if 400 <= status < 600 else 502
        return JSONResponse(status_code = status, content = {"error": relay.error})
    if relay.finish_reason is None:
        return JSONResponse(status_code = 502, content = {"error": dict(_NPU_CUT_SHORT_ERROR)})
    return JSONResponse(content = relay.completion())


# ── OpenAI shell-tool container management ───────────────────────


def _resolve_openai_cloud_client(
    body: OpenAIContainerRequest, *, allow_saved_key: bool
) -> ExternalProviderClient:
    """Needs an OpenAI cloud base URL (shell tool exists only there); runs on the loop for one snapshot."""
    base_url = body.provider_base_url or get_base_url("openai")
    if body.provider_id and not body.encrypted_api_key:
        config = providers_db.get_provider(body.provider_id)
        if config is None:
            raise HTTPException(
                status_code = 404,
                detail = f"Provider config not found: {body.provider_id}",
            )
        if config["provider_type"] != "openai":
            raise HTTPException(
                status_code = 400,
                detail = "OpenAI container management requires a saved OpenAI provider.",
            )
        if config.get("shared_by_owner"):
            raise HTTPException(
                status_code = 403,
                detail = "OpenAI containers are not available on a connection shared by the owner.",
            )

        if not config["is_enabled"]:
            raise HTTPException(
                status_code = 400,
                detail = f"Provider '{config['display_name']}' is disabled.",
            )
        base_url = config["base_url"]
    from urllib.parse import urlparse

    parsed_base_url = urlparse(base_url)
    if parsed_base_url.scheme != "https" or parsed_base_url.hostname != "api.openai.com":
        raise HTTPException(
            status_code = 400,
            detail = (
                "OpenAI container management is only available on the "
                "managed cloud (api.openai.com). The provider's base URL "
                f"points at {base_url!r}."
            ),
        )
    api_key = resolve_provider_api_key_or_400(
        body.provider_id,
        body.encrypted_api_key,
        allow_saved_key = allow_saved_key,
    )
    if not api_key:
        raise HTTPException(status_code = 400, detail = "No OpenAI API key is saved.")
    return ExternalProviderClient(
        provider_type = "openai",
        base_url = base_url,
        api_key = api_key,
    )


def _summarize_container(raw: dict) -> OpenAIContainerSummary:
    expires = raw.get("expires_after")
    expires_minutes: Optional[int] = None
    if isinstance(expires, dict):
        minutes = expires.get("minutes")
        if isinstance(minutes, int):
            expires_minutes = minutes
    return OpenAIContainerSummary(
        id = str(raw.get("id") or ""),
        name = raw.get("name"),
        created_at = raw.get("created_at") if isinstance(raw.get("created_at"), int) else None,
        last_active_at = raw.get("last_active_at")
        if isinstance(raw.get("last_active_at"), int)
        else None,
        expires_after_minutes = expires_minutes,
        status = raw.get("status") if isinstance(raw.get("status"), str) else None,
    )


@router.post(
    "/external/openai/containers/list",
    response_model = ListOpenAIContainersResponse,
)
async def list_openai_containers(
    body: OpenAIContainerRequest,
    request: Request,
    current_subject: str = Depends(get_current_subject),
) -> ListOpenAIContainersResponse:
    """List the user's OpenAI shell-tool containers."""
    client = _resolve_openai_cloud_client(body, allow_saved_key = not _request_has_api_key(request))
    try:
        try:
            raw = await client.list_openai_containers()
        except httpx.HTTPStatusError as exc:
            detail = exc.response.text[:500] if exc.response is not None else str(exc)
            raise HTTPException(
                status_code = exc.response.status_code if exc.response else 502,
                detail = f"OpenAI rejected /containers list: {detail}",
            )
        except httpx.HTTPError as exc:
            raise log_and_http_error(
                exc,
                502,
                "Could not reach OpenAI.",
                event = "openai_container_list.transport_error",
                log = logger,
            )
        # OpenAI lists expired containers indefinitely; hide them.
        return ListOpenAIContainersResponse(
            containers = [
                _summarize_container(c)
                for c in raw
                if isinstance(c, dict) and c.get("status") != "expired"
            ],
        )
    finally:
        await client.close()


@router.post(
    "/external/openai/containers/create",
    response_model = OpenAIContainerSummary,
)
async def create_openai_container(
    body: CreateOpenAIContainerBody,
    request: Request,
    _current_subject: str = Depends(get_current_subject),
) -> OpenAIContainerSummary:
    """Create a named container with the user-chosen idle TTL."""
    client = _resolve_openai_cloud_client(body, allow_saved_key = not _request_has_api_key(request))
    try:
        try:
            raw = await client.create_openai_container(
                name = body.name,
                ttl_minutes = body.ttl_minutes,
            )
        except httpx.HTTPStatusError as exc:
            detail = exc.response.text[:500] if exc.response is not None else str(exc)
            raise HTTPException(
                status_code = exc.response.status_code if exc.response else 502,
                detail = f"OpenAI rejected /containers create: {detail}",
            )
        except httpx.HTTPError as exc:
            raise log_and_http_error(
                exc,
                502,
                "Could not reach OpenAI.",
                event = "openai_container_create.transport_error",
                log = logger,
            )
        if not isinstance(raw, dict):
            raise HTTPException(
                status_code = 502,
                detail = "OpenAI returned an unexpected container payload.",
            )
        return _summarize_container(raw)
    finally:
        await client.close()


@router.post("/external/openai/containers/delete", status_code = 204)
async def delete_openai_container(
    body: DeleteOpenAIContainerBody,
    request: Request,
    current_subject: str = Depends(get_current_subject),
) -> None:
    """Delete a named container by id."""
    logger.info(
        "openai_container_delete.request subject=%s container_id=%s base_url=%s",
        current_subject,
        body.container_id,
        body.provider_base_url,
    )
    client = _resolve_openai_cloud_client(body, allow_saved_key = not _request_has_api_key(request))
    try:
        try:
            await client.delete_openai_container(body.container_id)
            logger.info(
                "openai_container_delete.success container_id=%s",
                body.container_id,
            )
        except httpx.HTTPStatusError as exc:
            detail = exc.response.text[:500] if exc.response is not None else str(exc)
            logger.warning(
                "openai_container_delete.openai_rejected container_id=%s status=%s body=%s",
                body.container_id,
                exc.response.status_code if exc.response else None,
                detail,
            )
            raise HTTPException(
                status_code = exc.response.status_code if exc.response else 502,
                detail = f"OpenAI rejected /containers delete: {detail}",
            )
        except httpx.HTTPError as exc:
            raise log_and_http_error(
                exc,
                502,
                "Could not reach OpenAI.",
                event = "openai_container_delete.transport_error",
                log = logger,
            )
    finally:
        await client.close()


_REASONING_EFFORT_VALUES = {"none", "minimal", "low", "medium", "high", "max", "xhigh"}


def _valid_reasoning_effort(value) -> Optional[str]:
    """An effort level the templates understand, else None."""
    if isinstance(value, str) and value in _REASONING_EFFORT_VALUES:
        return value
    return None


def _chat_template_reasoning_kwargs(payload) -> dict:
    """Validated reasoning controls from OpenAI ``extra_body``."""
    extra = getattr(payload, "model_extra", None)
    template_kwargs = extra.get("chat_template_kwargs") if isinstance(extra, dict) else None
    if not isinstance(template_kwargs, dict):
        return {}
    controls = {}
    enable_thinking = template_kwargs.get("enable_thinking")
    if isinstance(enable_thinking, bool):
        controls["enable_thinking"] = enable_thinking
    effort = _valid_reasoning_effort(template_kwargs.get("reasoning_effort"))
    if effort is not None:
        controls["reasoning_effort"] = effort
    preserve = template_kwargs.get("preserve_thinking")
    if isinstance(preserve, bool):
        controls["preserve_thinking"] = preserve
    return controls


_CHAT_TEMPLATE_REASONING_KEYS = ("enable_thinking", "reasoning_effort", "preserve_thinking")


def _consume_chat_template_reasoning_kwargs(payload) -> None:
    """Drop the reasoning keys a lift has just taken onto the typed fields, which is what makes the lift a fixed point; every render rebuilds the nested dict from those fields through ``_reasoning_template_kwargs``. Rebinds a filtered copy rather than popping: the dict is the parsed request body, shared with anything else holding it."""
    extra = getattr(payload, "model_extra", None)
    template_kwargs = extra.get("chat_template_kwargs") if isinstance(extra, dict) else None
    if not isinstance(template_kwargs, dict):
        return
    if not any(key in template_kwargs for key in _CHAT_TEMPLATE_REASONING_KEYS):
        return
    extra["chat_template_kwargs"] = {
        key: value
        for key, value in template_kwargs.items()
        if key not in _CHAT_TEMPLATE_REASONING_KEYS
    }


def _resolve_reasoning_controls(
    enable_thinking: Optional[bool], reasoning_effort: Optional[str]
) -> tuple[Optional[bool], Optional[str]]:
    """Resolve the on/off gate while keeping a compatible effort level."""
    if reasoning_effort is None:
        return enable_thinking, None
    effort_enables_thinking = reasoning_effort != "none"
    if enable_thinking is None:
        return effort_enables_thinking, reasoning_effort
    if enable_thinking != effort_enables_thinking:
        return enable_thinking, None
    return enable_thinking, reasoning_effort


def _normalize_chat_reasoning_controls(payload) -> None:
    """Merge typed and nested controls, then remove contradictory state. Consumes what it lifts, so the second call /v1/responses makes inside the chat route is a no-op; otherwise a dropped contradictory effort came back through the nested-effort rescue and reached generation."""
    nested = _chat_template_reasoning_kwargs(payload)
    _consume_chat_template_reasoning_kwargs(payload)
    fields_set = getattr(payload, "model_fields_set", set())
    typed_enable = payload.enable_thinking if "enable_thinking" in fields_set else None
    typed_effort = (
        _valid_reasoning_effort(payload.reasoning_effort)
        if "reasoning_effort" in fields_set
        else None
    )

    if typed_enable is not None or typed_effort is not None:
        enable_thinking, reasoning_effort = _resolve_reasoning_controls(typed_enable, typed_effort)
        nested_effort = nested.get("reasoning_effort")
        if typed_effort is None and nested_effort is not None:
            _, compatible_effort = _resolve_reasoning_controls(enable_thinking, nested_effort)
            if compatible_effort is not None:
                reasoning_effort = compatible_effort
    elif "enable_thinking" in nested or "reasoning_effort" in nested:
        enable_thinking, reasoning_effort = _resolve_reasoning_controls(
            nested.get("enable_thinking"), nested.get("reasoning_effort")
        )
    else:
        # Lowest priority: Anthropic ``thinking``, already mapped onto the boolean.
        enable_thinking = payload.enable_thinking
        reasoning_effort = _valid_reasoning_effort(payload.reasoning_effort)

    payload.enable_thinking = enable_thinking
    payload.reasoning_effort = reasoning_effort
    if payload.preserve_thinking is None and "preserve_thinking" in nested:
        payload.preserve_thinking = nested["preserve_thinking"]


def _sampling_thinking_mode(llama_backend, payload) -> Optional[bool]:
    if not getattr(llama_backend, "supports_reasoning", False):
        return None
    return _think_parsing_expected(llama_backend, payload)


def _client_sampling(payload) -> dict:
    from utils.inference.inference_config import SAMPLING_FIELD_NAMES
    return {
        f: (getattr(payload, f) if f in payload.model_fields_set else None)
        for f in SAMPLING_FIELD_NAMES
    }


def _fill_recommended_sampling_openai(
    payload,
    model_id,
    thinking = None,
    explicit = None,
) -> None:
    """Fills only fields the client did not send; a second fill must pass the first fill's explicit set."""
    from utils.inference.inference_config import resolve_effective_sampling

    if explicit is None:
        explicit = _client_sampling(payload)
    effective = resolve_effective_sampling(model_id, explicit, thinking = thinking)
    for field, value in effective.items():
        setattr(payload, field, value)


# llama-server names it repeat_penalty; mirrors _build_passthrough_payload.
_COMPLETIONS_SAMPLING_BODY_KEY = {"repetition_penalty": "repeat_penalty"}


def _fill_recommended_sampling_completions(body: dict, model_id) -> None:
    """Fields with no pin, client value or recommendation keep llama-server's own default."""
    from utils.inference.inference_config import resolve_effective_sampling, SAMPLING_FIELD_NAMES

    explicit = {f: body.get(_COMPLETIONS_SAMPLING_BODY_KEY.get(f, f)) for f in SAMPLING_FIELD_NAMES}
    effective = resolve_effective_sampling(model_id, explicit, fill_defaults = False)
    for field, value in effective.items():
        body[_COMPLETIONS_SAMPLING_BODY_KEY.get(field, field)] = value


class _DisconnectPolicyRequest:
    """Delegate a request while making generation disconnect policy explicit."""

    def __init__(self, request: Request, *, cancel_on_disconnect: bool) -> None:
        self._request = request
        self._cancel_on_disconnect = cancel_on_disconnect

    async def is_disconnected(self) -> bool:
        if not self._cancel_on_disconnect:
            return False
        return await self._request.is_disconnected()

    def __getattr__(self, name):
        return getattr(self._request, name)


def _chat_cancel_event(request: Request) -> threading.Event:
    """Reuse a durable run's event across auto-load and generation registration."""
    event = getattr(getattr(request, "state", None), "generation_cancel_event", None)
    return event if event is not None else threading.Event()


# UI control frames lack `choices` and break strict OpenAI clients; Studio opts in via header.
UI_STREAM_EVENTS_HEADER = "X-Unsloth-Events"


def _ui_stream_events_enabled(request: Optional[Request]) -> bool:
    """Whether this request opted into Unsloth's UI control frames on an OpenAI stream."""
    if request is None:
        return False
    # A compat route delegating to chat decides, since only it knows whether it relays them.
    delegated = getattr(getattr(request, "state", None), "ui_stream_events", None)
    if delegated is not None:
        return bool(delegated)
    headers = getattr(request, "headers", None)
    if headers is None:
        return False
    try:
        value = headers.get(UI_STREAM_EVENTS_HEADER)
    except Exception:
        return False
    return (value or "").strip() == "1"


def _accepts_keyword(fn, name: str) -> bool:
    import inspect
    try:
        return name in inspect.signature(fn).parameters
    except (TypeError, ValueError):
        return False


# The loaded model serves the request, so a caller that cannot use speech says so per request.
REQUIRE_TEXT_HEADER = "X-Unsloth-Require-Text"


def _text_output_required(request: Optional[Request]) -> bool:
    """Whether this request refuses a spoken reply, whatever model ends up serving it."""
    if request is None:
        return False
    headers = getattr(request, "headers", None)
    if headers is None:
        return False
    try:
        value = headers.get(REQUIRE_TEXT_HEADER)
    except Exception:
        return False
    return (value or "").strip() == "1"


class _DroppedFrameKeepalive:
    """Paces an SSE keepalive comment in place of dropped UI control frames.

    A stall keepalive is only written while the generator is silent, and a control frame
    is not silence: it restarts that wait but, once gated off, puts nothing on the wire.
    A tool streaming stdout emits `tool_output` continuously, which also resets
    tool_stream_exec's own heartbeat, so a non-opt-in caller would see no bytes for the
    whole tool run and a Cloudflare quick tunnel drops the stream at ~100s idle. The
    Anthropic route pays the same cost on the same events; this is its `_last_drop_keepalive`.
    """

    def __init__(self, now: Optional[float] = None) -> None:
        self._last = time.monotonic() if now is None else now

    def due(self, now: Optional[float] = None) -> bool:
        current = time.monotonic() if now is None else now
        if current - self._last < _LOCAL_TOOL_STREAM_STALL_KEEPALIVE_S:
            return False
        self._last = current
        return True


def _chat_image_preflight(payload: ChatCompletionRequest, parsed_image_b64) -> dict:
    """The switch's ``image_preflight`` for a chat request carrying an image."""
    images_on_turn = _images_in_last_user_message(payload.messages)
    legacy_image_distinct = _legacy_image_is_distinct(payload)
    local_image_payloads = _request_local_image_payloads(payload)
    # A remote image the model reads is decoded after its fetch; no older image stands in for it.
    selected_image = _served_image_part(payload.messages)
    selects_remote = _remote_image_part(selected_image)
    image_b64 = (
        (payload.image_base64 if legacy_image_distinct else None)
        if selects_remote
        else parsed_image_b64 or payload.image_base64
    )
    if image_b64 is None and local_image_payloads and not selects_remote:
        image_b64 = local_image_payloads[0]
    # Read as the render reads it after the fetch; b64s stays as sent for GGUF to validate.
    served_messages = _remote_images_as_served(payload.messages)
    admitted_payloads = _conversation_with_image_markers(served_messages)[1]
    if legacy_image_distinct:
        admitted_payloads = [*admitted_payloads, payload.image_base64]
    return {
        "b64": image_b64,
        "b64s": local_image_payloads,
        "admitted": admitted_payloads,
        "multiple": (
            images_on_turn + int(legacy_image_distinct) > 1
            or bool((parsed_image_b64 or selects_remote) and legacy_image_distinct)
        ),
        # Refused after the load whatever the target is, so refused before evicting for it.
        "unservable_alongside": _newest_turn_shows_more_images_than_it_sends(
            served_messages, legacy_image_distinct
        ),
        "fetch_schemes": {
            several: [
                _image_url_scheme(part.image_url.url)
                for part in _served_remote_parts(payload.messages, several)
            ]
            for several in (False, True)
        },
    }


_CONNECTION_MODEL_PREFIX = "external::"


# The id the chat picker gives a Connection model: external::<connection id>::<url-encoded model>.
def _connection_model_ref(model: Any) -> Optional[tuple[str, str]]:
    if not isinstance(model, str) or not model.startswith(_CONNECTION_MODEL_PREFIX):
        return None
    provider_id, _, encoded = model[len(_CONNECTION_MODEL_PREFIX) :].partition("::")
    if not provider_id or not encoded:
        return None
    return provider_id, _urlunquote(encoded)


# Provider replay metadata agent clients drop: Gemini 3 answers 400 to a functionCall without its
# thoughtSignature (tool call extra_content), and Anthropic to a tool continuation without its signed
# thinking (message extra_content). Keep both by echoed tool id, capped per subject and overall.
_CONNECTION_TOOL_EXTRAS: collections.OrderedDict = collections.OrderedDict()
_CONNECTION_TOOL_EXTRAS_MAX = 4096
_CONNECTION_TOOL_EXTRAS_SUBJECTS_MAX = 64
_CONNECTION_TOOL_EXTRAS_LOCK = threading.Lock()


def _remember_connection_extra(subject: Optional[str], kind: str, tool_id: Any, extra: Any) -> None:
    if not isinstance(tool_id, str) or not tool_id or not isinstance(extra, dict) or not extra:
        return
    key = (kind, tool_id)
    with _CONNECTION_TOOL_EXTRAS_LOCK:
        extras = _CONNECTION_TOOL_EXTRAS.setdefault(subject or "", collections.OrderedDict())
        _CONNECTION_TOOL_EXTRAS.move_to_end(subject or "")
        extras[key] = extra
        extras.move_to_end(key)
        while len(extras) > _CONNECTION_TOOL_EXTRAS_MAX:
            extras.popitem(last = False)
        while len(_CONNECTION_TOOL_EXTRAS) > _CONNECTION_TOOL_EXTRAS_SUBJECTS_MAX:
            _CONNECTION_TOOL_EXTRAS.popitem(last = False)


def _connection_extra(subject: Optional[str], kind: str, tool_id: Any) -> Optional[dict]:
    with _CONNECTION_TOOL_EXTRAS_LOCK:
        extras = _CONNECTION_TOOL_EXTRAS.get(subject or "")
        extra = extras.get((kind, tool_id)) if extras is not None else None
        if extra is not None:
            # A replay keeps the account recent, so a new account does not evict its history.
            _CONNECTION_TOOL_EXTRAS.move_to_end(subject or "")
        return extra


class _ConnectionExtrasRecorder:
    """One reply's tool ids (as the client sees them) and its message-level extra_content."""

    def __init__(self, subject: Optional[str]) -> None:
        self.subject = subject
        self.tool_ids: list[str] = []
        self.message_extra: Optional[dict] = None

    def call(self, tool_id: Any, extra: Any) -> None:
        if isinstance(tool_id, str) and tool_id:
            self.tool_ids.append(tool_id)
            _remember_connection_extra(self.subject, "call", tool_id, extra)
            self._file_message_extra()

    def message(self, extra: Any) -> None:
        if isinstance(extra, dict) and extra:
            self.message_extra = extra
            self._file_message_extra()

    def chunk(
        self,
        chunk: Any,
        *,
        calls: bool = True,
    ) -> None:
        for choice in (chunk.get("choices") if isinstance(chunk, dict) else None) or []:
            delta = choice.get("delta") if isinstance(choice, dict) else None
            if not isinstance(delta, dict):
                continue
            self.message(delta.get("extra_content"))
            for call in (delta.get("tool_calls") if calls else None) or []:
                if isinstance(call, dict):
                    self.call(call.get("id"), call.get("extra_content"))

    def _file_message_extra(self) -> None:
        if self.message_extra:
            for tool_id in self.tool_ids:
                _remember_connection_extra(self.subject, "message", tool_id, self.message_extra)


def _restore_connection_tool_extras(subject: Optional[str], messages: Any) -> None:
    for message in messages or []:
        is_dict = isinstance(message, dict)
        tool_calls = message.get("tool_calls") if is_dict else getattr(message, "tool_calls", None)
        message_extra = None
        for call in tool_calls or []:
            if not isinstance(call, dict):
                continue
            message_extra = message_extra or _connection_extra(subject, "message", call.get("id"))
            if not call.get("extra_content"):
                extra = _connection_extra(subject, "call", call.get("id"))
                if extra:
                    call["extra_content"] = extra
        has_extra = (
            message.get("extra_content") if is_dict else getattr(message, "extra_content", None)
        )
        if message_extra and not has_extra:
            if is_dict:
                message["extra_content"] = message_extra
            else:
                message.extra_content = message_extra


async def _relay_recording_tool_extras(chunks, subject: Optional[str]):
    recorder = _ConnectionExtrasRecorder(subject)
    pending = ""
    try:
        async for chunk in chunks:
            yield chunk
            pending += chunk.decode("utf-8", "replace") if isinstance(chunk, bytes) else chunk
            *complete, pending = pending.split("\n")
            for line in complete:
                if line.startswith("data:") and (
                    '"tool_calls"' in line or '"extra_content"' in line
                ):
                    try:
                        recorder.chunk(json.loads(line[5:]))
                    except ValueError:
                        pass
    finally:
        await chunks.aclose()


async def _relay_split_thinking(
    chunks,
    stops: Any = None,
    parse_thinking: bool = True,
):
    """Native thinking arrives as a leading <think> block in content (the Studio chat's form); OpenAI
    clients read it from reasoning_content. The proxy forwards no stop sequences, so cut here."""
    think = _ResponsesReasoningExtractor(parse_think_markers = parse_thinking, single_block = True)
    stop = _StopSequenceFilter([stops] if isinstance(stops, str) else stops)
    lines = _sse_data_lines(chunks)
    try:
        async for line in lines:
            data = line[len("data:") :].strip() if line.startswith("data:") else ""
            if data == "[DONE]":
                reasoning, text = think.finish()
                text = stop.feed(text) + stop.flush()
                if reasoning or text:
                    delta = {
                        k: v for k, v in (("reasoning_content", reasoning), ("content", text)) if v
                    }
                    yield (
                        "data: " + json.dumps({"choices": [{"index": 0, "delta": delta}]}) + "\n\n"
                    )
            elif data and '"choices"' in data:
                try:
                    chunk = json.loads(data)
                except ValueError:
                    chunk = None
                if isinstance(chunk, dict):
                    for choice in chunk.get("choices") or []:
                        delta = choice.get("delta") if isinstance(choice, dict) else None
                        if not isinstance(delta, dict):
                            continue
                        reasoning, text = think.feed(
                            delta.get("content") if isinstance(delta.get("content"), str) else "",
                            delta.get("reasoning_content"),
                        )
                        if choice.get("finish_reason"):
                            tail_reasoning, tail_text = think.finish()
                            reasoning, text = reasoning + tail_reasoning, text + tail_text
                        text = stop.feed(text)
                        if choice.get("finish_reason") and stop.hit is None:
                            text += stop.flush()
                        if stop.hit is not None:
                            choice["finish_reason"] = "stop"
                        delta.pop("reasoning_content", None)
                        delta.pop("content", None)
                        if text:
                            delta["content"] = text
                        if reasoning:
                            delta["reasoning_content"] = reasoning
                    line = "data: " + json.dumps(chunk)
            yield line + "\n"
            if stop.hit is not None:
                yield "\ndata: [DONE]\n\n"
                return
    finally:
        await lines.aclose()


async def _chat_completion_from_connection_stream(response: StreamingResponse, model: str):
    lines = _sse_data_lines(response.body_iterator)
    try:
        return await _collect_chat_completion(lines, model)
    finally:
        await lines.aclose()


async def _collect_chat_completion(lines, model: str):
    completion_id, created, finish, usage = None, int(time.time()), None, None
    content, reasoning = "", ""
    calls: dict[int, dict] = {}
    async for line in lines:
        data = line[len("data:") :].strip() if line.startswith("data:") else ""
        if data == "[DONE]":
            break
        if not data:
            continue
        chunk = json.loads(data)
        error = chunk.get("error")
        if error:
            message = error.get("message") if isinstance(error, dict) else str(error)
            try:
                status_code = int(error.get("code"))
            except (AttributeError, TypeError, ValueError):
                status_code = 502
            if not 400 <= status_code <= 599:
                status_code = 502
            return JSONResponse(
                status_code = status_code,
                content = openai_error_body(message or "The connection failed.", status = status_code),
            )
        completion_id = completion_id or chunk.get("id")
        usage = chunk.get("usage") or usage
        for choice in chunk.get("choices") or []:
            delta = choice.get("delta") or {}
            content += delta.get("content") or ""
            reasoning += delta.get("reasoning_content") or ""
            for part in delta.get("tool_calls") or []:
                call = calls.setdefault(
                    part.get("index", len(calls)),
                    {"id": None, "type": "function", "function": {"name": "", "arguments": ""}},
                )
                call["id"] = call["id"] or part.get("id")
                function = part.get("function") or {}
                call["function"]["name"] += function.get("name") or ""
                call["function"]["arguments"] += function.get("arguments") or ""
                if part.get("extra_content"):
                    call["extra_content"] = part["extra_content"]
            finish = choice.get("finish_reason") or finish
    message: dict = {"role": "assistant", "content": content or None}
    if reasoning:
        message["reasoning_content"] = reasoning
    if calls:
        message["tool_calls"] = [calls[index] for index in sorted(calls)]
    body = {
        "id": completion_id or f"chatcmpl-{uuid.uuid4().hex}",
        "object": "chat.completion",
        "created": created,
        "model": model,
        "choices": [{"index": 0, "message": message, "finish_reason": finish or "stop"}],
    }
    if usage:
        body["usage"] = usage
    return JSONResponse(body)


@router.post("/chat/completions")
@account_access.gpu_busy_route
async def openai_chat_completions(
    payload: ChatCompletionRequest,
    request: Request,
    current_subject: str = Depends(get_current_subject),
):
    _admit_tool_access(payload)
    connection = _connection_model_ref(payload.model)
    if connection is not None and (payload.provider_id or payload.provider_type):
        connection = None
    collect = False
    if connection is not None:
        payload.provider_id, payload.external_model = connection
        _restore_connection_tool_extras(current_subject, payload.messages)
        # The proxy relays a stream:false provider body as is, so stream and answer from the chunks.
        collect = payload.stream is not True
        if collect:
            payload.stream = True
            payload.stream_options = {"include_usage": True}
    from auth.authentication import request_admitted_without_credential

    if (payload.provider_id or payload.provider_type) and request_admitted_without_credential(
        request
    ):
        raise HTTPException(
            status_code = 403,
            detail = "External providers can only be used from the Unsloth UI or with an API key.",
        )
    response = await produce_openai_chat_completions(
        payload,
        request,
        current_subject,
        cancel_on_disconnect = True,
    )
    if connection is None or not isinstance(response, StreamingResponse):
        return response
    response.body_iterator = _relay_split_thinking(
        _relay_recording_tool_extras(response.body_iterator, current_subject),
        payload.stop,
        # Thinking switched off: a leading tag is the answer's own text.
        parse_thinking = payload.enable_thinking is not False,
    )
    if collect:
        return await _chat_completion_from_connection_stream(response, payload.model)
    return response


async def produce_openai_chat_completions(
    payload: ChatCompletionRequest,
    request: Request,
    current_subject: str,
    *,
    cancel_on_disconnect: bool,
):
    """GGUF models route to llama-server, others to the transformers backend; stream defaults to false."""
    request = _DisconnectPolicyRequest(
        request,
        cancel_on_disconnect = cancel_on_disconnect,
    )
    # Opt-in per request via UI_STREAM_EVENTS_HEADER; read once so every stream generator shares it.
    _ui_events = _ui_stream_events_enabled(request)
    # Seeded at stream start, so a tool already chatty past the window still gets a keepalive.
    _drop_keepalive = _DroppedFrameKeepalive()

    # Normalize "developer" to "system" before routing; some providers reject it.
    for _m in payload.messages:
        if _m.role == "developer":
            _m.role = "system"

    if payload.logprobs:
        _raise_unsupported_openai_parameter(
            "logprobs", "logprobs is not supported for chat completions."
        )
    if payload.top_logprobs is not None:
        _raise_unsupported_openai_parameter(
            "top_logprobs", "top_logprobs is not supported for chat completions."
        )

    # Before routing splits, or unsupported parts are silently dropped.
    _reject_unsupported_content_parts(payload)
    await _materialize_sandbox_attachments(payload)
    from core.inference import file_history

    file_history.set_turn(payload.thread_id, payload.user_message_id)

    # ── External provider routing ────────────────────────────────
    # encrypted_api_key is optional: local providers may run without auth.
    if payload.provider_id or payload.provider_type:
        from auth.authentication import request_admitted_without_credential

        # caller-chosen egress from this host, which is not the loaded model on offer
        if request_admitted_without_credential(request):
            raise HTTPException(
                status_code = 403,
                detail = "External providers can only be used from the Unsloth UI or with an API key.",
            )
        # Drop from keep-warm count or this stream would block local model switches.
        from core.inference.llama_keepwarm import untrack_current_request

        untrack_current_request(request.scope)
        if _wants_multiple_choices(payload):
            _raise_unsupported_n("external provider chat completions")
        # Refuse video here: the proxy cannot place a clip, and video_url is refused as the legacy field is.
        if _request_has_video(payload):
            raise HTTPException(status_code = 400, detail = _VIDEO_INPUT_REFUSAL)
        # _build_external_messages has no input_audio case; refuse rather than drop it.
        if _messages_have_input_audio(payload.messages):
            raise HTTPException(
                status_code = 400,
                detail = "Audio input is only supported on a local model with audio support.",
            )
        return await _proxy_to_external_provider(payload, request, current_subject)

    _mcp_image = await _request_mcp_image(payload, _ui_events)
    # Local path only: the lift targets audio_base64, which the proxy never reads.
    _normalise_chat_content_parts(payload)

    # Reject malformed function tools here, or llama-server fails opaquely with "Failed to parse tools".
    if payload.tools:
        for _tool in payload.tools:
            if not isinstance(_tool, dict):
                continue
            # llama-server 500s when a function tool omits "type"; default it to "function".
            if _tool.get("type") is None and isinstance(_tool.get("function"), dict):
                _tool["type"] = "function"
            if _tool.get("type") != "function":
                continue
            _fn = _tool.get("function")
            _name = _fn.get("name") if isinstance(_fn, dict) else None
            if not isinstance(_name, str) or not _name.strip():
                raise HTTPException(
                    status_code = 400,
                    detail = openai_error_body(
                        "Invalid 'tools': each tool must have a 'function' with a 'name'.",
                        status = 400,
                        code = "invalid_value",
                        param = "tools",
                    ),
                )

    # Reject a system-only chat before any auto load, even with features off, to keep preview ownership.
    _pre_parsed = None
    _needs_vision = False
    _needs_image = False
    _modality_label = "image or audio"
    _needs_audio_input = False
    _needs_video = False
    _tool_images_only = False
    _predecoded_audio = None
    _preprepared_audio = None
    _image_preflight = None
    if _should_validate_before_switch():
        _pre_parsed = _extract_content_parts(payload.messages, keep_tool_images = True)
        if not _pre_parsed[1]:
            raise HTTPException(
                status_code = 400, detail = "At least one non-system message is required."
            )
        # Match the passthrough router's local-loop gate (`_tools_on or _mcp_allowed`); a policy-forced
        # loop must not steal client-tool passthrough. Reject before the switch evicts the model.
        from state.tool_policy import get_tool_policy as _get_tool_policy_pre

        _cli_policy_pre = _get_tool_policy_pre()
        _use_tools_intent = _effective_enable_tools(payload) or (
            bool(payload.mcp_enabled) and _cli_policy_pre is not False
        )
        if payload.tool_choice == "none" and not _explicit_studio_tool_loop_requested(payload):
            _use_tools_intent = False
        _client_tool_passthrough = (
            bool(payload.tools)
            or bool(payload.openai_code_exec_container_id)
            or bool(payload.anthropic_code_exec_container_id)
            # A JSON-schema response_format is grammar-constrained decoding; check it with the router's predicate.
            or _response_format_constrains_decoding(payload)
        )
        # Client-tool passthrough leaves confirm_tool_calls unset; only an explicit True rejects.
        _studio_local_tool_loop = bool(_use_tools_intent) and (
            _explicit_studio_tool_loop_requested(payload) or not _client_tool_passthrough
        )
        # Non-streaming only: pre-switch we know only intent; per-backend guards handle streams.
        if (
            not payload.bypass_permissions
            and not payload.stream
            and (
                (_confirm_gate_needs_stream(payload) and _studio_local_tool_loop)
                or (payload.confirm_tool_calls is True and _client_tool_passthrough)
            )
        ):
            raise HTTPException(
                status_code = 400,
                detail = openai_error_body(
                    "confirm_tool_calls requires stream=true and the X-Unsloth-Events: 1 "
                    'header for local tool execution; set permission_mode to "off" to '
                    "run tools without confirmation.",
                    status = 400,
                    code = "invalid_request_error",
                    param = "confirm_tool_calls",
                ),
            )
        # Reject a nameless tool_choice function before the switch swaps the model.
        _tc = payload.tool_choice
        if isinstance(_tc, dict) and _tc.get("type") == "function":
            _tc_fn = _tc.get("function")
            _tc_name = _tc_fn.get("name") if isinstance(_tc_fn, dict) else None
            if not isinstance(_tc_name, str) or not _tc_name.strip():
                raise HTTPException(
                    status_code = 400,
                    detail = openai_error_body(
                        "Invalid 'tool_choice': the forced function must have a 'name'.",
                        status = 400,
                        code = "invalid_value",
                        param = "tool_choice",
                    ),
                )
        # target-independent, unlike the format-dependent checks the switch itself runs.
        _audio_rejection = _request_audio_rejection(payload)
        if _audio_rejection is not None:
            raise HTTPException(status_code = _audio_rejection[0], detail = _audio_rejection[1])
        # stream + n>1 is invalid on every local path; reject before loading another model.
        if payload.stream and _wants_multiple_choices(payload):
            _raise_unsupported_n("streaming chat completions")
        # Audio input rides the same mmproj projector as vision; guard both before the switch.
        _needs_image = bool(_pre_parsed[2]) or _request_has_attached_image(payload)
        _tool_images_only = (
            _needs_image
            and not payload.image_base64
            and not _messages_have_image(m for m in payload.messages if m.role != "tool")
        )
        # Video needs the projector too; its /props gate runs only after load, so refuse before any eviction.
        _needs_video = _request_has_video(payload)
        _needs_vision = _needs_image or bool(payload.audio_base64) or _needs_video
        # Name only the modalities actually attached, so a refusal never reports one the request lacks.
        _modality_label = (
            " or ".join(
                name
                for name, present in (
                    ("image", _needs_image),
                    ("audio", bool(payload.audio_base64)),
                    ("video", _needs_video),
                )
                if present
            )
            or _modality_label
        )
        # Size is known now and a model switch is costly, so refuse an oversized clip before loading.
        _video_rejection = _request_video_rejection(payload)
        if _video_rejection is not None:
            raise HTTPException(status_code = _video_rejection[0], detail = _video_rejection[1])
        _needs_audio_input = bool(payload.audio_base64)

    # the rest of the audio checks depend on the target's format, so the switch runs them.
    _audio_preflight = (
        {
            "clips": _request_audio_clips(payload),
            "continue_final": _continue_final_message(payload),
            "has_image": _images_in_last_user_message(payload.messages)
            or _legacy_image_is_distinct(payload),
            "has_video": _needs_video,
        }
        if _needs_audio_input
        else None
    )
    if _needs_image and _pre_parsed is not None:
        _image_preflight = _chat_image_preflight(payload, _pre_parsed[2])

    def _npu_switch_check(model) -> None:
        # NPU chat runs no MCP tool loop, so it refuses an MCP image after the switch.
        _refuse_unused_mcp_image(_mcp_image)
        _refuse_npu_chat_request(payload, supports_vision = model.vision, supports_tools = model.tools)

    # Defer the resident claim: chat has several post-switch capability checks that can still
    # reject (Whisper without audio, n>1 on a non-GGUF backend, tool or response_format
    # passthrough), so claiming here could strand a preview-owned model for a request that
    # never generates. The middleware instead claims the slot on a successful 2xx non-preview
    # response.
    await _maybe_auto_switch_model(
        _switch_model_for_payload(payload),
        request,
        current_subject,
        require_vision = _needs_vision,
        require_image = _needs_image,
        modality_label = _modality_label,
        claim_resident = False,
        require_audio_input = _needs_audio_input,
        require_video = _needs_video,
        audio_preflight = _audio_preflight,
        image_preflight = _image_preflight,
        tool_images_only = _tool_images_only,
        serves_npu = True,
        npu_request_check = _npu_switch_check,
    )
    if _audio_preflight is not None:
        _predecoded_audio = _audio_preflight.get("decoded")
        _preprepared_audio = _audio_preflight.get("prepared")

    from core.inference.npu_backend import peek_npu_backend

    _npu = peek_npu_backend()
    if _npu is not None and _npu.is_loaded and routed_slot.get() is None:
        _refuse_unused_mcp_image(_mcp_image)
        return await _npu_chat_completions(payload, request, current_subject)

    llama_backend = get_llama_cpp_backend()
    using_gguf = llama_backend.is_loaded

    # Lift ``extra_body`` template controls before sampling and generation read them.
    _normalize_chat_reasoning_controls(payload)

    # ── Determine which backend is active ─────────────────────
    # Single-model server: any model name serves the loaded model; payload.model is a label.
    monitor_id = None

    async def _monitored_generate_audio(model_label: str, context_length: Optional[int] = None):
        if _text_output_required(request):
            raise HTTPException(
                status_code = 400,
                detail = "This request requires text output; select a text model.",
            )
        tts_monitor_id = None
        if not getattr(request.state, "skip_api_monitor", False):
            tts_monitor_id = api_monitor.start(
                endpoint = request.url.path,
                via_api_key = _request_used_api_key(request),
                method = request.method,
                model = model_label,
                prompt = _monitor_prompt_from_messages(payload.messages),
                context_length = context_length,
                subject = current_subject,
            )
        try:
            response = await generate_audio(payload, request)
        except asyncio.CancelledError:
            api_monitor.finish(tts_monitor_id, "cancelled")
            raise
        except Exception as e:
            api_monitor.fail(tts_monitor_id, _friendly_error(e))
            raise
        if isinstance(response, JSONResponse):
            try:
                body = json.loads(response.body.decode())
                choices = body.get("choices") or []
                message = (choices[0].get("message") or {}) if choices else {}
                content = message.get("content")
                if isinstance(content, str):
                    api_monitor.set_reply(tts_monitor_id, content)
            except Exception:
                pass
        api_monitor.finish(tts_monitor_id)
        return response

    # Place above the backend branch: audio returns inside it, so it must read normalized stop sequences.
    normalized_stop = _normalize_stop_sequences(payload.stop)

    if using_gguf:
        # Advertised repo id after an auto-switch load, else a clean public id,
        # never the absolute .gguf path.
        model_name = _llama_public_model_id(llama_backend, payload.model)
        if getattr(llama_backend, "_is_audio", False):
            if _wants_multiple_choices(payload):
                _raise_unsupported_n("GGUF audio chat completions")
            if _response_format_constrains_decoding(payload):
                # No grammar can constrain a waveform, and this branch skips response_format routing, so refuse here.
                _raise_unsupported_openai_parameter(
                    "response_format",
                    "response_format cannot be honored by an audio reply; send the "
                    "request to a text model to use guided decoding.",
                )
            _reject_audio_output_continuation(payload)
            # This branch speaks only the newest user TEXT; an image would go unread.
            if _images_in_last_user_message(payload.messages) or _legacy_image_is_distinct(payload):
                raise HTTPException(
                    status_code = 400,
                    detail = (
                        "This model generates speech and does not read images."
                        " Load a vision model to send one."
                    ),
                )
            _refuse_unused_mcp_image(_mcp_image)
            return await _monitored_generate_audio(
                model_name,
                context_length = llama_backend.context_length,
            )
    else:
        backend = await asyncio.to_thread(get_inference_backend)
        if not backend.active_model_name:
            _status, _detail = await _no_model_loaded_error(
                "No model loaded. Call POST /inference/load first.",
                _switch_model_for_payload(payload),
                request,
                status = 400,
            )
            raise HTTPException(status_code = _status, detail = _detail)
        # Public id so the response never echoes a local path.
        model_name = _orchestrator_public_model_id(backend) or payload.model
        model_info = backend.models.get(backend.active_model_name, {})
        # Before the speech and audio-input dispatches, which return before the clip is attached.
        _video_clip = None
        if _request_has_video(payload):
            _video_clip = _local_video_clip(payload, model_info)
            # Settled here: a model without audio input never enters the audio-input path.
            if payload.audio_base64:
                raise HTTPException(status_code = 400, detail = _AUDIO_VIDEO_INPUT_DETAIL)
        # One SSE stream carries a single choice; the pre-switch check may not have run.
        if payload.stream and _wants_multiple_choices(payload):
            _raise_unsupported_n("streaming chat completions")
        model_info = backend.models.get(backend.active_model_name, {})
        if _response_format_constrains_decoding(payload):
            _audio_reply = model_info.get("is_audio") and model_info.get("audio_type") != "whisper"
            _transcribes = model_info.get("audio_type") == "whisper"
            _listens = payload.audio_base64 and model_info.get("has_audio_input")
            if _audio_reply or _transcribes or _listens:
                _raise_unsupported_openai_parameter(
                    "response_format",
                    "response_format is not supported when the reply comes from an audio "
                    "route: a waveform admits no grammar, and transcription and audio-input "
                    "answers are decoded without one. Send the request to a text model.",
                )
        # Callable client tools set the format aside (_response_format_beside_tools), so nothing
        # below applies, unless the request asks for Unsloth's own loop, which keeps the format.
        if _response_format_constrains_decoding(payload) and (
            _explicit_studio_tool_loop_requested(payload)
            or not _tools_outrank_response_format(payload, payload.tools)
        ):
            _engine_grammar = model_info.get("engine") in ("vllm", "sglang")
            if not (model_info.get("is_mlx") or _engine_grammar):
                _raise_unsupported_openai_parameter(
                    "response_format",
                    "response_format needs a grammar engine, and the transformers backend "
                    "has none; load an MLX or GGUF model to use it.",
                )
            if payload.tool_choice not in (None, "auto", "none"):
                _raise_unsupported_openai_parameter(
                    "tool_choice",
                    "response_format cannot be combined with a tool_choice that requires a "
                    "call: guided decoding admits only the document, so no tool would be "
                    "called. Use tool_choice 'auto' or 'none'.",
                )
            if _continue_final_message(payload, thought = True):
                _raise_unsupported_openai_parameter(
                    "response_format",
                    "response_format cannot resume a partial assistant message: guided "
                    "decoding starts a new document rather than continuing the text before "
                    "it. Send the turn without continue_final_message.",
                )
            if not _engine_grammar:
                await asyncio.get_running_loop().run_in_executor(
                    _SCHEMA_VALIDATION_EXECUTOR, _reject_unhonorable_response_format, payload
                )

        # ── Audio TTS path: auto-route to audio generation ────
        # Whisper is ASR, not TTS, so it skips this branch and is handled in the audio input path below.
        if model_info.get("is_audio") and model_info.get("audio_type") != "whisper":
            if _wants_multiple_choices(payload):
                _raise_unsupported_n("non-GGUF audio chat completions")
            _reject_audio_output_continuation(payload)
            # generate_audio speaks only the newest user text, so refuse an attached image here.
            if _images_in_last_user_message(payload.messages) or _legacy_image_is_distinct(payload):
                raise HTTPException(
                    status_code = 400,
                    detail = (
                        "This model generates speech and does not read images."
                        " Load a vision model to send one."
                    ),
                )
            _refuse_unused_mcp_image(_mcp_image)
            return await _monitored_generate_audio(model_name)

        # ── Whisper without audio: return clear error ──
        if payload.audio_base64 and _wants_multiple_choices(payload):
            _raise_unsupported_n("non-GGUF audio-input chat completions")
        if model_info.get("audio_type") == "whisper" and not payload.audio_base64:
            raise HTTPException(
                status_code = 400,
                detail = "Whisper models require audio input. Please upload an audio file.",
            )

        if not getattr(request.state, "skip_api_monitor", False):
            monitor_id = api_monitor.start(
                endpoint = request.url.path,
                via_api_key = _request_used_api_key(request),
                method = request.method,
                model = model_name,
                prompt = _monitor_prompt_from_messages(payload.messages),
                context_length = _monitor_context_length(),
                subject = current_subject,
            )

        # With auto-switch off the capability check never ran, so refuse unreadable audio here.
        if payload.audio_base64 and not model_info.get("has_audio_input"):
            _audio_unsupported_detail = (
                "The loaded model cannot read audio input. Load a model with audio support."
            )
            api_monitor.fail(monitor_id, _audio_unsupported_detail)
            raise HTTPException(status_code = 400, detail = _audio_unsupported_detail)
        # mlx-vlm drops or misplaces extra clips; bound clips before decoding.
        _audio_rejection = _request_audio_rejection(payload)
        if _audio_rejection is not None:
            api_monitor.fail(monitor_id, _audio_rejection[1])
            raise HTTPException(status_code = _audio_rejection[0], detail = _audio_rejection[1])
        if payload.extra_audio_base64 and model_info.get("is_mlx"):
            api_monitor.fail(monitor_id, _MLX_MULTI_AUDIO_DETAIL)
            raise HTTPException(status_code = 400, detail = _MLX_MULTI_AUDIO_DETAIL)

        # ── Audio INPUT path: decode WAV and route to audio input generation ──
        if payload.audio_base64 and model_info.get("has_audio_input"):
            _refuse_unused_mcp_image(_mcp_image)
            # No boundary to resume from: this route re-listens and answers afresh.
            if _continue_final_message(payload):
                raise HTTPException(
                    status_code = 400,
                    detail = "continue_final_message is not supported with audio input.",
                )
            # Only audio is forwarded, so refuse an image on this turn; earlier-turn images are fine.
            # api_monitor directly: _reject is not bound this early.
            if _images_in_last_user_message(payload.messages) or _legacy_image_is_distinct(payload):
                _audio_image_detail = _AUDIO_IMAGE_INPUT_DETAIL
                api_monitor.fail(monitor_id, _audio_image_detail)
                raise HTTPException(status_code = 400, detail = _audio_image_detail)
            try:
                # Normally decoded before the switch; only paths that skipped that preflight decode here.
                audio_arrays = (
                    _predecoded_audio
                    if _predecoded_audio is not None
                    else await asyncio.to_thread(_decode_audio_clips, _request_audio_clips(payload))
                )
                audio_array = audio_arrays[0]
                # Passed only when present, so single-clip calls are unchanged.
                extra_audio_kwargs = (
                    {"extra_audio_arrays": audio_arrays[1:]} if len(audio_arrays) > 1 else {}
                )
                system_prompt, chat_messages, _ = await _extract_content_parts_async(
                    payload.messages
                )
                system_prompt = _audio_input_system_prompt(system_prompt, request)
            except _DecodedAudioTooLongError as e:
                # A limit the caller can act on, not a server fault.
                api_monitor.fail(monitor_id, str(e))
                raise HTTPException(
                    status_code = 413,
                    detail = _audio_too_long_detail(),
                )
            except Exception as e:
                api_monitor.fail(monitor_id, _friendly_error(e))
                raise
            cancel_event = _chat_cancel_event(request)
            completion_id = f"chatcmpl-{uuid.uuid4().hex[:12]}"
            created = int(time.time())

            # Fill recommended sampling + operator pins so audio-input honors them like chat.
            _fill_recommended_sampling_openai(
                payload, getattr(backend, "active_model_name", None) or model_name
            )

            # Request-scoped usage/budget receptacle (filled at gen_done).
            _audio_stats_holder: dict = {}

            def audio_input_generate():
                if model_info.get("audio_type") == "whisper":
                    return backend.generate_whisper_response(
                        audio_array = audio_array,
                        use_adapter = payload.use_adapter,
                        cancel_event = cancel_event,
                        stats_holder = _audio_stats_holder,
                        **extra_audio_kwargs,
                    )
                return backend.generate_audio_input_response(
                    messages = chat_messages,
                    system_prompt = system_prompt,
                    audio_array = audio_array,
                    temperature = payload.temperature,
                    top_p = payload.top_p,
                    top_k = payload.top_k,
                    min_p = payload.min_p,
                    max_new_tokens = _effective_max_tokens(payload),
                    repetition_penalty = payload.repetition_penalty,
                    # Compare sends audio_base64 and use_adapter in one body.
                    use_adapter = payload.use_adapter,
                    cancel_event = cancel_event,
                    stats_holder = _audio_stats_holder,
                    stop = normalized_stop,
                    **extra_audio_kwargs,
                )

            if payload.stream:
                _cancel_keys = (payload.cancel_id, payload.session_id, completion_id)
                _tracker = _TrackedCancel.for_payload(cancel_event, payload, *_cancel_keys)
                _tracker.__enter__()

                async def audio_input_stream():
                    disconnect_watcher = asyncio.create_task(
                        _await_disconnect_then_cancel(request, cancel_event)
                    )
                    try:
                        from core.inference.llama_keepwarm import mark_current_response_failed

                        yield _chat_role_chunk(completion_id, created, model_name)

                        gen = audio_input_generate()
                        gen_step = ThreadStepper(gen).next
                        _DONE = object()
                        cancelled = False
                        while True:
                            if cancel_event.is_set():
                                cancelled = True
                                # Flag failed so the middleware does not claim a preview-owned model.
                                mark_current_response_failed()
                                break
                            if await request.is_disconnected():
                                cancel_event.set()
                                api_monitor.finish(monitor_id, "cancelled")
                                mark_current_response_failed()
                                return
                            chunk_text = await gen_step(_DONE)
                            if chunk_text is _DONE:
                                if cancel_event.is_set():
                                    cancelled = True
                                    mark_current_response_failed()
                                break
                            if isinstance(chunk_text, GenStreamError):
                                _msg = _friendly_gen_stream_error(chunk_text)
                                api_monitor.fail(monitor_id, _msg)
                                yield _openai_stream_error_sse(
                                    {"error": {"message": _msg, "type": "server_error"}}
                                )
                                return
                            if chunk_text:
                                api_monitor.append_reply(monitor_id, chunk_text)
                                yield _chat_content_chunk(
                                    completion_id, created, model_name, chunk_text
                                )

                        _audio_stats = _audio_stats_holder.get("stats")
                        _audio_finish = "stop" if cancelled else _stats_finish_reason(_audio_stats)
                        # The worker fills these stats for both backends (MLX adds timings), so the row has counts and speed.
                        if isinstance(_audio_stats, dict):
                            _monitor_usage(
                                monitor_id,
                                _audio_stats.get("usage"),
                                _monitor_context_length(),
                                timings = _audio_stats.get("timings"),
                            )
                        # Before finish(): a later write would escape the clearing a cancelled row gets.
                        api_monitor.set_perf(monitor_id, stop_reason = _audio_finish)
                        api_monitor.finish(monitor_id, "cancelled" if cancelled else "completed")
                        yield _chat_final_chunk(completion_id, created, model_name, _audio_finish)
                        yield "data: [DONE]\n\n"
                    except asyncio.CancelledError:
                        cancel_event.set()
                        api_monitor.finish(monitor_id, "cancelled")
                        raise
                    except context_refusal.ContextBudgetExceeded as e:
                        api_monitor.fail(monitor_id, _friendly_error(e))
                        yield _openai_stream_error_sse(_openai_stream_error_chunk(e))
                    except Exception as e:
                        logger.error(f"Error during audio input streaming: {e}", exc_info = True)
                        _msg = _friendly_error(e)
                        api_monitor.fail(monitor_id, _msg)
                        # _openai_stream_error_sse marks the response failed, so the middleware won't claim a preview model.
                        yield _openai_stream_error_sse(
                            {"error": {"message": _msg, "type": "server_error"}}
                        )
                    finally:
                        await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
                        _tracker.__exit__(None, None, None)

                return _sse_streaming_response(
                    audio_input_stream(),
                    unstarted_cleanup = _tracked_cancel_unstarted_cleanup(_tracker),
                    monitor_id = monitor_id,
                )
            else:
                # Register even non-streaming: an unregistered request lets a swap cancel it instead of 409.
                _cancel_keys = (payload.cancel_id, payload.session_id, completion_id)
                _tracker = _TrackedCancel.for_payload(cancel_event, payload, *_cancel_keys)
                _tracker.__enter__()
                try:

                    def _drain_audio_input():
                        text_parts = []
                        for chunk_text in audio_input_generate():
                            if isinstance(chunk_text, GenStreamError):
                                return chunk_text
                            text_parts.append(chunk_text)
                        return "".join(text_parts)

                    full_text = await _run_blocking_generation(
                        _drain_audio_input,
                        cancel_event,
                        name = "openai-audio-input-nonstream",
                    )
                    if isinstance(full_text, GenStreamError):
                        _msg = _friendly_gen_stream_error(full_text)
                        api_monitor.fail(monitor_id, _msg)
                        raise HTTPException(status_code = 500, detail = _msg)
                except asyncio.CancelledError:
                    cancel_event.set()
                    api_monitor.finish(monitor_id, "cancelled")
                    raise
                except HTTPException:
                    raise
                except context_refusal.ContextBudgetExceeded as e:
                    api_monitor.fail(monitor_id, _friendly_error(e))
                    raise _context_budget_http_error(e)
                except Exception as e:
                    api_monitor.fail(monitor_id, _friendly_error(e))
                    raise
                finally:
                    # Nested under the except arms too: api_monitor.fail() can throw, and a leaked entry 409s swaps.
                    _tracker.__exit__(None, None, None)
                api_monitor.set_reply(monitor_id, full_text)
                _audio_json_stats = _audio_stats_holder.get("stats")
                _audio_json_finish = (
                    "stop" if cancel_event.is_set() else _stats_finish_reason(_audio_json_stats)
                )
                _mark_cancelled_json_response_failed(request, cancel_event)
                if isinstance(_audio_json_stats, dict):
                    _monitor_usage(
                        monitor_id,
                        _audio_json_stats.get("usage"),
                        _monitor_context_length(),
                        timings = _audio_json_stats.get("timings"),
                    )
                api_monitor.set_perf(monitor_id, stop_reason = _audio_json_finish)
                api_monitor.finish(monitor_id)
                _audio_usage = (_audio_json_stats or {}).get("usage") or {}
                response = ChatCompletion(
                    id = completion_id,
                    created = created,
                    model = model_name,
                    choices = [
                        CompletionChoice(
                            message = CompletionMessage(content = full_text),
                            finish_reason = _audio_json_finish,
                        )
                    ],
                    usage = CompletionUsage(
                        prompt_tokens = _audio_usage.get("prompt_tokens") or 0,
                        completion_tokens = _audio_usage.get("completion_tokens") or 0,
                        total_tokens = (
                            _audio_usage.get("total_tokens")
                            or (_audio_usage.get("prompt_tokens") or 0)
                            + (_audio_usage.get("completion_tokens") or 0)
                        ),
                        prompt_tokens_details = _prompt_tokens_details(
                            _audio_usage.get("prompt_tokens_details")
                        ),
                    ),
                )
                return _model_json_response(response)

    if monitor_id is None and not getattr(request.state, "skip_api_monitor", False):
        monitor_id = api_monitor.start(
            endpoint = request.url.path,
            via_api_key = _request_used_api_key(request),
            method = request.method,
            model = model_name,
            prompt = _monitor_prompt_from_messages(payload.messages),
            context_length = _monitor_context_length(),
            subject = current_subject,
        )

    # Finalize the monitor entry on validation rejection before raising.
    def _reject(status_code: int, detail: Any) -> "HTTPException":
        if monitor_id is not None:
            fail_detail = detail if isinstance(detail, str) else json.dumps(detail, default = str)
            api_monitor.fail(monitor_id, fail_detail)
        return HTTPException(status_code = status_code, detail = detail)

    def _reject_missing_forced_tool(tool_choice, selected_tools) -> None:
        from core.inference.chat_template_helpers import catalog_tool_names, forced_tool_name
        forced_name = forced_tool_name(tool_choice)
        if forced_name and forced_name not in catalog_tool_names(selected_tools):
            raise _reject(
                400,
                openai_error_body(
                    f"Invalid 'tool_choice': function '{forced_name}' is not enabled.",
                    status = 400,
                    code = "invalid_value",
                    param = "tool_choice",
                ),
            )

    def _reject_unsupported_n(path_label: str) -> "HTTPException":
        return _reject(
            400,
            openai_error_body(
                f"n > 1 is not supported for {path_label}.",
                status = 400,
                code = "unsupported_parameter",
                param = "n",
            ),
        )

    # Fill omitted fields from per-model recommended sampling and UNSLOTH_SAMPLING_* pins.
    # Placed after external-provider routing so only local backends are touched.
    _reco_model_id = (
        getattr(llama_backend, "model_identifier", None)
        if using_gguf
        else getattr(backend, "active_model_name", None)
    ) or model_name
    _client_sampling_fields = _client_sampling(payload)
    _fill_recommended_sampling_openai(
        payload,
        _reco_model_id,
        thinking = _sampling_thinking_mode(llama_backend, payload) if using_gguf else None,
        explicit = _client_sampling_fields,
    )

    # ── Standard OpenAI function-calling pass-through (GGUF only) ────
    # Client-supplied OpenAI tools go to llama-server verbatim. Must run BEFORE
    # _extract_content_parts, which cannot handle role=tool or tool_calls-only messages.
    effective_max_tokens = _effective_openai_max_tokens(payload)

    _has_tool_messages = _has_openai_tool_history(payload.messages)
    _has_tool_catalog = bool(payload.tools and len(payload.tools) > 0)
    _has_active_tool_catalog = _has_tool_catalog and payload.tool_choice != "none"
    # History from Unsloth's own loop is not a client contract (same as _takes_tool_passthrough).
    _has_client_tool_history = _has_tool_messages and not _only_studio_tool_history(payload)
    _has_client_tool_contract = _has_active_tool_catalog or _has_client_tool_history
    # Backends that cannot run the tool loop (e.g. DiffusionGemma) must not steal client tools.
    _studio_tool_loop_requested = (
        _explicit_studio_tool_loop_requested(payload) and llama_backend.supports_tools
    )
    _client_disabled_tool_calls = payload.tool_choice == "none" and not _studio_tool_loop_requested
    # Only asks if search_conversation is reachable, never narrows catalogue; else keep rolling window.
    _tool_loop_unusable = (
        _client_disabled_tool_calls
        or payload.max_tool_calls_per_message == 0
        or _wants_multiple_choices(payload)
        # Non-streaming confirm gate has no channel; an epoch here would wedge the thread with 400s.
        or (
            _confirm_gate_needs_stream(payload)
            and not payload.bypass_permissions
            and not payload.stream
        )
    )
    _supports_tool_passthrough = getattr(
        llama_backend, "supports_tool_passthrough", llama_backend.supports_tools
    )
    # Before the route split so both paths treat a tool-result image as a note on text-only GGUF.
    if using_gguf and not llama_backend.is_vision:
        _omit_tool_images(payload.messages)
    # Before the passthrough dispatch and the parse, so every later reader sees the fold.
    if using_gguf and _folds_studio_tool_history(payload, llama_backend):
        payload.messages = _folded_studio_tool_messages(payload.messages)
        _pre_parsed = None
    if (
        using_gguf
        and not _studio_tool_loop_requested
        and _has_client_tool_contract
        and not _supports_tool_passthrough
    ):
        raise _reject(
            400,
            openai_error_body(
                (
                    "Client-supplied tools or tool-call history require a GGUF chat template "
                    "with tool-call support; the current model/template does not advertise tools."
                ),
                status = 400,
                code = "unsupported_parameter",
                param = "tools" if payload.tools else "messages",
            ),
        )
    # Shared with the token counter. Guided decoding routes here too: the other path drops schema.
    if using_gguf and _takes_tool_passthrough(payload, llama_backend):
        _refuse_unused_mcp_image(_mcp_image)
        if _wants_multiple_choices(payload):
            raise _reject_unsupported_n("GGUF tool or response_format passthrough")
        _reject_unresumable_thought(payload, llama_backend, _reject)
        if payload.audio_base64:
            # Passthrough forwards verbatim, so transcoded audio would never be injected.
            raise _reject(
                400,
                "Audio input is not supported together with guided decoding or client-supplied tools yet.",
            )
        if _request_has_video(payload):
            # _build_openai_passthrough_body forwards a fixed field list, so the clip would be dropped.
            raise _reject(
                400,
                "Video input is not supported together with guided decoding or client-supplied tools yet.",
            )

        # Text-only GGUFs get a clear 400 instead of an opaque llama-server error.
        if not llama_backend.is_vision and (
            payload.image_base64
            or any(
                isinstance(m.content, list)
                and any(isinstance(p, ImageContentPart) for p in m.content)
                for m in payload.messages
            )
        ):
            raise _reject(
                400,
                "Image provided but current GGUF model does not support vision.",
            )

        # Fetch before taking an admission lease so a slow image host holds no inference slot.
        if _messages_have_remote_image(payload.messages):
            try:
                await asyncio.to_thread(_inline_request_remote_images, payload)
            except HTTPException as exc:
                raise _reject(exc.status_code, exc.detail)

        cancel_event = _chat_cancel_event(request)
        completion_id = f"chatcmpl-{uuid.uuid4().hex[:12]}"
        # `stream` defaults to False (OpenAI parity); non-SSE clients rely on it.
        if payload.stream:
            return await _openai_passthrough_stream(
                request,
                cancel_event,
                llama_backend,
                payload,
                model_name,
                completion_id,
                monitor_id = monitor_id,
            )
        _cancel_keys = (payload.cancel_id, payload.session_id, completion_id)
        _tracker = _TrackedCancel.for_payload(cancel_event, payload, *_cancel_keys)
        _tracker.__enter__()
        try:
            return await _openai_passthrough_non_streaming(
                llama_backend,
                payload,
                model_name,
                monitor_id = monitor_id,
                request = request,
                cancel_event = cancel_event,
            )
        finally:
            _tracker.__exit__(None, None, None)

    if not using_gguf and _messages_have_remote_image(
        m for m in payload.messages if m.role not in ("system", "developer")
    ):
        if not model_info.get("is_vision"):
            raise _reject(
                400, "Image provided but current model is text-only. Load a vision model."
            )
        try:
            await asyncio.to_thread(
                _inline_served_remote_images, payload, _serves_several_images(backend)
            )
        except HTTPException as exc:
            raise _reject(exc.status_code, exc.detail)
        _pre_parsed = None

    # ── Parse messages (handles multimodal content parts) ─────
    # Reuse the pre-hook parse when an auto-switch already did it; otherwise parse the messages here.
    if _pre_parsed is not None:
        system_prompt, chat_messages, extracted_image_b64 = _pre_parsed
    else:
        system_prompt, chat_messages, extracted_image_b64 = _extract_content_parts(
            payload.messages, keep_tool_images = True
        )
    # applied once so both backends inherit it, with or without tools, and never state it twice.
    _user_system_prompt = system_prompt
    # What renders through the processor template; the MCP scan runs off-loop (12 MB envelope).
    _renders_media = (
        _request_has_attached_image(payload)
        or _request_has_video(payload)
        or (
            _request_has_promotable_mcp_images(payload, exact = False)
            and await asyncio.to_thread(_request_has_promotable_mcp_images, payload)
        )
    )
    _date_controls = _template_controls(payload)
    system_prompt = _apply_current_date_prompt(
        system_prompt, request, image = _renders_media, controls = _date_controls
    )

    if not chat_messages:
        raise _reject(400, "At least one non-system message is required.")

    # ── GGUF path: proxy to llama-server /v1/chat/completions ──
    if using_gguf:
        # wav/mp3 pass through (llama-server decodes them); other containers are transcoded to WAV.
        prepared_audio: list[tuple[str, str]] = []
        if payload.audio_base64:
            if not getattr(llama_backend, "_has_audio_input", False):
                raise _reject(
                    400,
                    "Audio provided but current GGUF model does not support audio input.",
                )
            audio_rejection = _request_audio_rejection(payload)
            if audio_rejection is not None:
                raise _reject(*audio_rejection)
            try:
                prepared_audio = (
                    _preprepared_audio
                    if _preprepared_audio is not None
                    else await asyncio.to_thread(
                        _prepare_audio_clips_for_llama, _request_audio_clips(payload)
                    )
                )
            except _DecodedAudioTooLongError as e:
                # A valid but over-long file reports the duration limit like the non-GGUF path, not corrupt audio.
                logger.info("Audio rejected at the duration limit: %s", e)
                raise _reject(413, _audio_too_long_detail())
            except Exception as e:
                logger.warning("Audio decode failed: %s", e, exc_info = True)
                raise _reject(400, "Could not decode the provided audio file.")
            # Admission reads duration from wav/mp3 headers; other formats would be charged by bytes.
            payload.audio_base64 = prepared_audio[0][0]
            payload.extra_audio_base64 = [clip for clip, _ in prepared_audio[1:]] or None

        # llama-server samples frames but encodes each at the clip's resolution.
        video_b64 = None
        if _request_has_video(payload):
            if not getattr(llama_backend, "_has_video_input", False):
                raise _reject(
                    400,
                    "Video provided but the current GGUF model cannot take video input. "
                    "It needs an mmproj with video support, and ffmpeg/ffprobe installed.",
                )
            video_rejection = _request_video_rejection(payload)
            if video_rejection is not None:
                raise _reject(*video_rejection)
            if payload.video_base64:
                video_b64, _ = _video_b64_rejection(payload.video_base64)
                video_b64 = await _shrink_clip_for_llama(video_b64, llama_backend)

        # The loop's image cap counts the whole conversation, so seed it with replayed parts.
        _gguf_replayed_image_parts: list = []
        _reject_unresumable_thought(payload, llama_backend, _reject)
        gguf_messages, _ = await _openai_messages_for_gguf_chat_async(
            payload,
            llama_backend.is_vision,
            _gguf_replayed_image_parts,
        )
        gguf_messages = _set_or_prepend_system_message(gguf_messages, system_prompt)
        image_b64 = None
        for audio_b64, audio_format in prepared_audio:
            _inject_audio_part(gguf_messages, audio_b64, audio_format)
        if video_b64:
            _inject_video_part(gguf_messages, video_b64)
        await _shrink_video_parts(gguf_messages, llama_backend)
        _translate_video_parts(gguf_messages)

        cancel_event = _chat_cancel_event(request)

        completion_id = f"chatcmpl-{uuid.uuid4().hex[:12]}"
        created = int(time.time())

        def _new_chat_reasoning_extractor():
            return _ResponsesReasoningExtractor(
                parse_think_markers = _responses_should_parse_think_markers(
                    payload,
                    llama_backend,
                )
            )

        _gguf_monitor_callback = (
            _monitor_perf_callback(monitor_id, llama_backend.context_length)
            if not _wants_multiple_choices(payload)
            else None
        )
        # Only a stream has a stall loop to feed; elsewhere the monitor callback (or None) stands.
        _gguf_prefill_signal = _PrefillProgressSignal(
            _gguf_monitor_callback,
            live = bool(payload.stream and _ui_events and not _wants_multiple_choices(payload)),
        )
        _gguf_perf_callback = _gguf_prefill_signal if payload.stream else _gguf_monitor_callback

        def _gguf_chat_delta_line(delta: ChoiceDelta, finish_reason = None) -> str:
            if delta.reasoning_content is not None and delta.content is None:
                delta = delta.model_copy(update = {"content": ""})
            chunk = ChatCompletionChunk(
                id = completion_id,
                created = created,
                model = model_name,
                choices = [
                    ChunkChoice(
                        delta = delta,
                        finish_reason = finish_reason,
                    )
                ],
            )
            return f"data: {chunk.model_dump_json(exclude_none = True)}\n\n"

        # ── Tool-calling path (agentic loop) ──────────────────
        # mcp_enabled also opens the loop but must still honor a CLI --disable-tools policy.
        from state.tool_policy import get_tool_policy as _get_tool_policy_g

        _cli_policy = _get_tool_policy_g()
        _tools_on = False if _client_disabled_tool_calls else _effective_enable_tools(payload)
        if _tools_on and not _launcher_tool_default_applies(payload, _ui_events):
            _tools_on = False
        _mcp_allowed = (
            not _client_disabled_tool_calls
            and bool(payload.mcp_enabled)
            and _cli_policy is not False
        )
        use_tools = (_tools_on or _mcp_allowed) and llama_backend.supports_tools
        # Compacted threads open the loop for search_conversation, but only with supports_tools
        # and context_overflow == truncate_oldest (otherwise no reset can happen).
        if (
            not use_tools
            and not _tool_loop_unusable
            and llama_backend.supports_tools
            and _checkpoint_recall_may_enable_tools(payload)
        ):
            use_tools = True

        if use_tools:
            from core.inference.tools import set_mcp_listing_context_tokens

            set_mcp_listing_context_tokens(
                getattr(llama_backend, "context_length", None),
                payload.thread_id,
                payload.messages,
                payload.tool_choice,
                getattr(payload, "mcp_image", None),
            )
            tools_to_use = await _select_request_tools(
                payload,
                supports_vision = bool(getattr(llama_backend, "is_vision", False)),
                tools_on = _tools_on,
                mcp_allowed = _mcp_allowed,
                # Process policy says a reset is possible somewhere, not that this request can do one.
                checkpoint_fitted = _rolling_context_policy(payload) is not None,
                ui_events = _ui_events,
            )
            _reject_missing_forced_tool(payload.tool_choice, tools_to_use)
            # Skip the loop when no tool survived so 'empty = allow all' cannot reach built-ins.
            if not tools_to_use:
                use_tools = False

        if _response_format_constrains_decoding(payload):
            # Neither the loop nor the generator forwards response_format; refuse rather than violate it.
            raise _reject(
                400,
                openai_error_body(
                    "response_format is not supported with Unsloth tool execution; "
                    "send the request without enable_tools to use guided decoding.",
                    status = 400,
                    code = "unsupported_parameter",
                    param = "response_format",
                ),
            )

        _refuse_unused_mcp_image(_mcp_image, _catalog_names(tools_to_use) if use_tools else None)
        if use_tools:
            # Derive confirm from permission_mode for CLI-forced loops; a non-stream ask/auto is rejected below.
            _effective_confirm = _permission_mode_confirm(payload)
            # Bypass, or auto with only always-safe tools, never prompts, so no stream is required.
            if _confirm_gate_has_no_channel(payload, _ui_events, _catalog_names(tools_to_use)):
                raise _reject(
                    400,
                    openai_error_body(
                        "confirm_tool_calls requires stream=true and the X-Unsloth-Events: 1 "
                        'header for local tool execution; set permission_mode to "off" to '
                        "run tools without confirmation.",
                        status = 400,
                        code = "invalid_request_error",
                        param = "confirm_tool_calls",
                    ),
                )
            # After the channel check, which "off" never trips.
            _effective_confirm = _effective_confirm or _off_mode_sandbox_gate(payload, _ui_events)
            if _wants_multiple_choices(payload):
                raise _reject_unsupported_n("GGUF tool chat completions")
            # main's tool turn: the date and the caller's prompt, not the template's chat default.
            system_prompt = _apply_current_date_prompt(
                _user_system_prompt,
                request,
                include_api_key = True,
                template_default = False,
                tools = True,
                controls = _date_controls,
            )
            gguf_messages = _set_or_prepend_system_message(gguf_messages, system_prompt)
            # ── Tool-use system prompt nudge ──────────────────────
            _nudge = _build_tool_action_nudge(
                tools = tools_to_use,
                model_name = model_name,
                full_access = bool(payload.bypass_permissions),
            )

            # Nudge the model to ground in attached documents instead of memory.
            _nudge = await _apply_rag_nudge(_nudge, tools_to_use, rag_scope = payload.rag_scope)
            # Only _fit_context can reset the epoch, and only when truncation was requested.
            _nudge = _apply_compaction_nudge(
                _nudge,
                tools_to_use,
                checkpoint_fitted = _rolling_context_policy(payload) is not None,
                payload = payload,
            )

            if _nudge:
                # Append nudge to system prompt (preserve user's prompt)
                if system_prompt:
                    system_prompt = system_prompt.rstrip() + "\n\n" + _nudge
                else:
                    system_prompt = _nudge
                gguf_messages = _set_or_prepend_system_message(gguf_messages, system_prompt)

            _gguf_auto_heal_tool_calls = (
                payload.auto_heal_tool_calls if payload.auto_heal_tool_calls is not None else True
            )
            # Generator is built before the reservation exists but not iterated until after.
            _gguf_admission_hold: dict = {"reservation": None}
            _gguf_decode_lock = threading.Lock()
            _gguf_decode: dict = {"slot": None, "erased": False}

            def _gguf_record_decode_slot(base_url: str, slot: int) -> None:
                with _gguf_decode_lock:
                    _gguf_decode["slot"] = (base_url, slot)
                    _gguf_decode["erased"] = False

            def _gguf_recost(conversation) -> None:
                with _gguf_decode_lock:
                    erased = _gguf_decode["erased"]
                    _gguf_decode["slot"] = None
                    _gguf_decode["erased"] = False
                _openai_llama_admission_recost(
                    _gguf_admission_hold["reservation"],
                    conversation,
                    request = request,
                    llama_backend = llama_backend,
                    # Payload the reservation was priced from; each round is charged for media and non-message prompt.
                    payload = payload,
                    # NOT `or 0`: None means uncapped; zero would re-cost the loop on its first round.
                    output_tokens = effective_max_tokens,
                    injected_tools = tools_to_use,
                    count_prepared_prompt = True,
                    # Same event the loop polls, so a cache-room wait still honors Stop.
                    cancel_event = cancel_event,
                    # Erased cells make yielding honest, so a grown round may wait.
                    cache_is_empty = erased,
                )

            # Active tool names gating the bare-rehearsal strip, matching the loop gate.
            _gguf_display_tool_names = _display_tool_name_gate(tools_to_use)

            # ── Strip stale tool-call XML from conversation history ─
            # Continuation target keeps exact whitespace: the frontend appends output to its partial.
            _gguf_continue_target = (
                gguf_messages[-1]
                if _continue_final_message(payload, thought = True) and gguf_messages
                else None
            )
            for _msg in gguf_messages:
                if _msg.get("role") == "assistant" and isinstance(_msg.get("content"), str):
                    # Gate on enabled tool names like the live strip, so an inactive foo[ARGS]{...} survives replay.
                    _stripped = _strip_tool_xml_for_display(
                        _msg["content"],
                        auto_heal_tool_calls = _gguf_auto_heal_tool_calls,
                        enabled_tool_names = _gguf_display_tool_names,
                    )
                    _msg["content"] = (
                        _stripped if _msg is _gguf_continue_target else _stripped.strip()
                    )

            def gguf_generate_with_tools():
                from core.inference.skill_mentions import load_mentioned_skills
                from state.tool_approvals import LiveToolPermissions

                gguf_live_permissions = LiveToolPermissions(payload.session_id, cancel_event)

                skill_instruction_ids = set()
                yield from load_mentioned_skills(
                    gguf_messages,
                    # "none" / a zero budget withdraw read_skill, so they withdraw the preload too.
                    tools_to_use
                    if payload.tool_choice != "none" and payload.max_tool_calls_per_message != 0
                    else [],
                    permission_mode = payload.permission_mode,
                    bypass_permissions = bool(payload.bypass_permissions),
                    confirm_tool_calls = _effective_confirm,
                    session_id = payload.session_id,
                    cancel_event = cancel_event,
                    context_length = llama_backend.context_length,
                    continue_final_message = _continue_final_message(payload, thought = True),
                    protected_message_ids = skill_instruction_ids,
                    permission_upgrade = gguf_live_permissions,
                )
                yield from llama_backend.generate_chat_completion_with_tools(
                    live_permissions = gguf_live_permissions,
                    instruction_anchor_ids = skill_instruction_ids,
                    messages = gguf_messages,
                    replayed_image_parts = tuple(_gguf_replayed_image_parts),
                    tools = tools_to_use,
                    temperature = payload.temperature,
                    top_p = payload.top_p,
                    top_k = payload.top_k,
                    min_p = payload.min_p,
                    max_tokens = effective_max_tokens,
                    repetition_penalty = payload.repetition_penalty,
                    presence_penalty = payload.presence_penalty,
                    frequency_penalty = payload.frequency_penalty,
                    logit_bias = payload.logit_bias,
                    stop = normalized_stop,
                    cancel_event = cancel_event,
                    seed = payload.seed,
                    enable_thinking = payload.enable_thinking,
                    reasoning_effort = payload.reasoning_effort,
                    preserve_thinking = payload.preserve_thinking,
                    continue_final_message = _continue_final_message(payload, thought = True),
                    auto_heal_tool_calls = _gguf_auto_heal_tool_calls,
                    deduplicate_tool_calls = payload.deduplicate_tool_calls is not False,
                    nudge_tool_calls = payload.nudge_tool_calls,
                    tool_choice = payload.tool_choice,
                    max_tool_iterations = payload.max_tool_calls_per_message
                    if payload.max_tool_calls_per_message is not None
                    else 25,
                    tool_call_timeout = payload.tool_call_timeout
                    if payload.tool_call_timeout is not None
                    else 300,
                    session_id = payload.session_id,
                    thread_id = payload.thread_id,
                    rag_scope = payload.rag_scope,
                    disable_parallel_tool_use = payload.parallel_tool_calls is False,
                    # Bypass Permissions takes precedence over the confirm gate: never prompt while bypassing.
                    confirm_tool_calls = _effective_confirm and not bool(payload.bypass_permissions),
                    mcp_image = _mcp_image,
                    bypass_permissions = bool(payload.bypass_permissions),
                    permission_mode = payload.permission_mode,
                    sandbox_level = payload.sandbox_level,
                    perf_callback = _gguf_perf_callback,
                    on_conversation_grew = _gguf_recost,
                    # Only streams park and reclaim; an MCP image forces the approval wait in any mode.
                    on_decode_slot = _gguf_record_decode_slot
                    if payload.stream
                    and (
                        (_effective_confirm and not payload.bypass_permissions)
                        or _mcp_image is not None
                    )
                    else None,
                    context_overflow = _rolling_context_policy(payload),
                    context_policy = _request_context_policy(payload),
                    compaction_headroom_ratio = _request_compaction_headroom_ratio(payload),
                    compact_context = getattr(payload, "compact_context", None) is True,
                )

            _tool_admission_mode = "chat_tool_stream" if payload.stream else "chat_tool_nonstream"
            try:
                reservation, admission_config = await _reserve_counted_gguf_chat(
                    messages = gguf_messages,
                    request = request,
                    llama_backend = llama_backend,
                    payload = payload,
                    # Server-side catalogue: not in payload.tools and roughly 1250 prompt tokens.
                    injected_tools = tools_to_use,
                    # Server-side loop from any tool source opens at an equal share; _gguf_recost re-costs it.
                    tool_loop = True,
                )
                # Hand the rounds their reservation now; the generator is not iterated before admission returns.
                _gguf_admission_hold["reservation"] = reservation
            except LlamaAdmissionQueueFull as exc:
                _llama_admission_log(
                    "queue-full",
                    snapshot = exc.snapshot,
                    request = request,
                    mode = _tool_admission_mode,
                    completion_id = completion_id,
                    level = "warning",
                )
                api_monitor.fail(monitor_id, str(exc))
                raise _openai_admission_http_exception(exc, status_code = 429)

            _tool_sentinel = object()
            # True only once the sync generator returned on its own; see _gguf_decode_finished.
            _tool_decode_finished = False

            _cancel_keys = (payload.cancel_id, payload.session_id, completion_id)
            _tracker = _TrackedCancel.for_payload(cancel_event, payload, *_cancel_keys)
            _tracker.__enter__()

            async def gguf_tool_stream():
                nonlocal _tool_decode_finished
                gen = None
                next_task = None
                stream_completed = False
                # A call parked on approval gives its slot back, else unanswered prompts hold every slot.
                _parked = False

                _reclaim_task = None
                _reclaim_stop = asyncio.Event()

                def _erase_and_record(target) -> bool:
                    if not llama_backend.release_idle_chat_slot(*target):
                        return False
                    with _gguf_decode_lock:
                        _gguf_decode["erased"] = True
                    return True

                async def _reclaim_approval_cache(lease):
                    """Erases only on demand, since cells are dropped not spilled; Stop is honored only before the send."""
                    try:
                        while not lease.reclaim_would_admit():
                            try:
                                await asyncio.wait_for(
                                    _reclaim_stop.wait(), _APPROVAL_CACHE_RECLAIM_POLL_S
                                )
                            except asyncio.TimeoutError:
                                continue
                            return
                        with _gguf_decode_lock:
                            target = _gguf_decode["slot"]
                            erased = _gguf_decode["erased"]
                        if target is None or _reclaim_stop.is_set():
                            return
                        if not erased and not await asyncio.to_thread(_erase_and_record, target):
                            return
                        lease.release_parked_cache()
                    except asyncio.CancelledError:
                        raise
                    except Exception:
                        logger.debug("Approval cache reclamation failed", exc_info = True)

                def _watch_for_reclaim(lease) -> None:
                    nonlocal _reclaim_task
                    with _gguf_decode_lock:
                        known = _gguf_decode["slot"] is not None
                    if not known or _reclaim_task is not None:
                        return
                    _reclaim_stop.clear()
                    _reclaim_task = asyncio.create_task(_reclaim_approval_cache(lease))

                async def _settle_reclaim_watch() -> None:
                    """Waits out a sending erase instead of cancelling, since cancelling would not
                    stop the worker."""
                    nonlocal _reclaim_task
                    task, _reclaim_task = _reclaim_task, None
                    if task is None:
                        return
                    _reclaim_stop.set()
                    try:
                        await task
                    except Exception:
                        logger.debug("Approval cache reclamation failed", exc_info = True)

                def _stop_reclaim_watch() -> None:
                    nonlocal _reclaim_task
                    _reclaim_stop.set()
                    if _reclaim_task is not None:
                        _reclaim_task.cancel()
                        _reclaim_task = None

                async def _park_admission(on: bool, *, wait: bool = True):
                    nonlocal _parked
                    if on == _parked:
                        return
                    # Use this run's lease: queues key on base_url and a reload mints a new port.
                    lease = reservation.lease_nowait()
                    if lease is None:
                        return
                    if on:
                        if not lease.park():
                            return
                        _watch_for_reclaim(lease)
                    elif wait:
                        await _settle_reclaim_watch()
                        await lease.unpark_async(cancel_event = cancel_event)
                    else:
                        # Tearing down; the lease is released separately.
                        _stop_reclaim_watch()
                        lease.unpark()
                    _parked = on

                disconnect_watcher = asyncio.create_task(
                    _await_disconnect_then_cancel(request, cancel_event)
                )
                try:
                    from core.inference.llama_keepwarm import mark_current_response_failed

                    yield _chat_role_chunk(completion_id, created, model_name)

                    # Open in this context BEFORE the task/thread below copy it, or refit refusals are lost.
                    context_refusal.open_slot()
                    # In a thread so the event loop stays free for disconnect detection.
                    gen = gguf_generate_with_tools()
                    gen_step = ThreadStepper(gen).next
                    prev_text = ""
                    _gguf_display_strip = _StreamingDisplayStrip(
                        auto_heal_tool_calls = _gguf_auto_heal_tool_calls,
                        enabled_tool_names = _gguf_display_tool_names,
                    )
                    reasoning_extractor = _new_chat_reasoning_extractor()
                    _stream_usage = None
                    _stream_timings = None
                    _stream_finish = None
                    approval_flush_pending = False

                    def _flush_reasoning_extractor():
                        final_reasoning, final_visible = reasoning_extractor.finish()
                        chunks = []
                        if final_reasoning:
                            # Held-back markers can make this the FIRST output of all.
                            api_monitor.mark_first_token(monitor_id)
                            chunks.append(
                                _gguf_chat_delta_line(
                                    ChoiceDelta(reasoning_content = final_reasoning)
                                )
                            )
                        if final_visible:
                            api_monitor.append_reply(monitor_id, final_visible)
                            chunks.append(_gguf_chat_delta_line(ChoiceDelta(content = final_visible)))
                        return chunks

                    # Set by the frame that ends a park: other tabs clear their prompt on it, so it
                    # is forwarded first and the slot is retaken before the generator does more.
                    resume_before_next = False
                    while True:
                        if cancel_event.is_set():
                            mark_current_response_failed()
                            break
                        if await request.is_disconnected():
                            cancel_event.set()
                            mark_current_response_failed()
                            api_monitor.finish(monitor_id, "cancelled")
                            return

                        if resume_before_next:
                            resume_before_next = False
                            await _park_admission(False)

                        next_task = asyncio.create_task(gen_step(_tool_sentinel))
                        try:
                            # asyncio.wait never cancels next_task, matching the finally-drain shield.
                            wait_timeout = (
                                TOOL_APPROVAL_FLUSH_DELAY_S
                                if approval_flush_pending
                                else _LOCAL_TOOL_STREAM_STALL_KEEPALIVE_S
                            )
                            async for stall_line in _stall_wait_frames(
                                next_task, _gguf_prefill_signal, wait_timeout
                            ):
                                yield stall_line
                            event = next_task.result()
                            approval_flush_pending = False
                        finally:
                            if next_task.done():
                                next_task = None
                        if event is _tool_sentinel:
                            _tool_decode_finished = True
                            break

                        # Anything after the gated tool_start is the answer, except the context meter sent before the wait.
                        if not (
                            (event["type"] == "tool_start" and event.get("awaiting_confirmation"))
                            or event["type"] == "context_usage"
                            or (
                                event["type"] == "skill_load"
                                and event.get("status") == "awaiting_approval"
                            )
                        ):
                            resume_before_next = True

                        if event["type"] == "heartbeat":
                            # Tool-wrapper heartbeat while a server-side tool blocks; keeps SSE alive.
                            yield _OPENAI_TOOL_HEARTBEAT_SSE
                            continue

                        if event["type"] in (
                            "tool_output",
                            "tool_args",
                            "skill_load",
                            "tool_model_note",
                            "tool_approved",
                        ):
                            if (
                                event["type"] == "skill_load"
                                and event.get("status") == "awaiting_approval"
                            ):
                                await _park_admission(True)
                                approval_flush_pending = True
                            # Live stdout/stderr and tool-call args go verbatim to the UI; the final result comes in tool_end.
                            if _ui_events:
                                yield f"data: {json.dumps(event)}\n\n"
                            elif _drop_keepalive.due():
                                yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                            continue

                        if event["type"] == "status":
                            # Empty status marks an iteration boundary; reset the cumulative cursor.
                            if not event["text"]:
                                for chunk in _flush_reasoning_extractor():
                                    yield chunk
                                prev_text = ""
                                reasoning_extractor = _new_chat_reasoning_extractor()
                            # Tool status goes out as a custom SSE event; empty ones clear the UI badges.
                            if _ui_events:
                                status_data = json.dumps(
                                    {
                                        "type": "tool_status",
                                        "content": event["text"],
                                    }
                                )
                                yield f"data: {status_data}\n\n"
                            elif _drop_keepalive.due():
                                yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                            continue

                        if event["type"] in ("tool_start", "tool_end"):
                            if event["type"] == "tool_start":
                                # Gated with the card since the stamp is set once: a caller that cannot
                                # see the card would otherwise report the tool run as its TTFT.
                                if _ui_events:
                                    api_monitor.mark_first_token(monitor_id, decoded = False)
                                for chunk in _flush_reasoning_extractor():
                                    yield chunk
                                prev_text = ""
                                reasoning_extractor = _new_chat_reasoning_extractor()
                                # Yielded just before the loop blocks on the user.
                                await _park_admission(bool(event.get("awaiting_confirmation")))
                                approval_flush_pending = bool(event.get("awaiting_confirmation"))
                            if _ui_events:
                                yield f"data: {json.dumps(event)}\n\n"
                            elif _drop_keepalive.due():
                                yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                            continue

                        if event["type"] == "metadata":
                            _stream_usage = event.get("usage")
                            _stream_timings = event.get("timings")
                            _stream_finish = event.get("finish_reason")
                            continue

                        if event["type"] == "context_usage":
                            # Must not reach the content branch below: its empty text resets prev_text.
                            if _ui_events:
                                yield f"data: {json.dumps(event)}\n\n"
                            elif _drop_keepalive.due():
                                yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                            continue

                        if event["type"] == "quote_cut":
                            # Bypass content handling to avoid resetting the text cursor.
                            if _ui_events:
                                yield _quote_cut_sse_chunk(completion_id, model_name)
                            elif _drop_keepalive.due():
                                yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                            continue

                        if event["type"] == "reasoning_summary":
                            # Forward server-side reasoning timing to the UI.
                            if _ui_events:
                                yield f"data: {json.dumps(event)}\n\n"
                            elif _drop_keepalive.due():
                                yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                            continue

                        if event["type"] == "context_truncated":
                            yield _context_truncated_sse_chunk(
                                completion_id,
                                model_name,
                                {key: value for key, value in event.items() if key != "type"},
                            )
                            continue

                        # Sanitize the full cumulative text then diff, so cross-chunk XML tags are handled.
                        raw_cumulative = event.get("text", "")
                        clean_cumulative = _gguf_display_strip.strip(raw_cumulative)
                        new_text = clean_cumulative[len(prev_text) :]
                        prev_text = clean_cumulative
                        if not new_text:
                            continue
                        reasoning_delta, visible_delta = reasoning_extractor.feed(new_text)
                        if reasoning_delta:
                            api_monitor.mark_first_token(monitor_id)
                            yield _gguf_chat_delta_line(
                                ChoiceDelta(reasoning_content = reasoning_delta)
                            )
                        if visible_delta:
                            api_monitor.append_reply(monitor_id, visible_delta)
                            yield _gguf_chat_delta_line(ChoiceDelta(content = visible_delta))

                    for chunk in _flush_reasoning_extractor():
                        yield chunk

                    final_chunk = ChatCompletionChunk(
                        id = completion_id,
                        created = created,
                        model = model_name,
                        choices = [
                            ChunkChoice(
                                delta = ChoiceDelta(),
                                finish_reason = _clamp_finish_reason(_stream_finish),
                            )
                        ],
                    )
                    # finish_reason chunk must precede the usage chunk and [DONE] for OpenAI clients.
                    yield f"data: {final_chunk.model_dump_json(exclude_none = True)}\n\n"
                    usage_line = _openai_stream_usage_chunk(
                        payload,
                        completion_id,
                        created,
                        model_name,
                        _stream_usage,
                        _stream_timings,
                    )
                    if usage_line is not None:
                        yield usage_line
                    _monitor_usage(
                        monitor_id,
                        _stream_usage,
                        _monitor_context_length(),
                        timings = _stream_timings,
                        stop_reason = _clamp_finish_reason(_stream_finish),
                    )
                    if cancel_event.is_set():
                        mark_current_response_failed()
                    api_monitor.finish(
                        monitor_id, "cancelled" if cancel_event.is_set() else "completed"
                    )
                    stream_completed = True
                    yield "data: [DONE]\n\n"

                except asyncio.CancelledError:
                    cancel_event.set()
                    api_monitor.finish(monitor_id, "cancelled")
                    raise
                except Exception as e:
                    logger.error(f"Error during GGUF tool streaming: {e}", exc_info = True)
                    api_monitor.fail(monitor_id, _friendly_error(e))
                    # Recover if an MTP crash killed the server mid-stream.
                    get_llama_cpp_backend()._maybe_recover_from_mtp_crash(e)
                    error_chunk = _openai_stream_error_chunk(e)
                    yield _openai_stream_error_sse(error_chunk)
                finally:
                    # A disconnect mid-approval must not leave a slot parked.
                    await _park_admission(False, wait = False)
                    try:
                        if not stream_completed:
                            cancel_event.set()
                        task_to_drain = next_task
                        next_task = None
                        while task_to_drain is not None and not task_to_drain.done():
                            try:
                                await asyncio.shield(task_to_drain)
                            except asyncio.CancelledError:
                                cancel_event.set()
                                continue
                            except Exception:
                                break
                        if task_to_drain is not None and task_to_drain.done():
                            try:
                                task_to_drain.exception()
                            except (asyncio.CancelledError, Exception):
                                pass
                        if gen is not None and not stream_completed:
                            try:
                                await asyncio.to_thread(gen.close)
                            except (RuntimeError, ValueError):
                                pass
                            except Exception:
                                logger.debug(
                                    "Error closing GGUF tool stream generator during cleanup",
                                    exc_info = True,
                                )
                        await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
                    finally:
                        _tracker.__exit__(None, None, None)

            if payload.stream:
                stream_lease = reservation.lease_nowait()
                admission_wait_started_at = None
                if stream_lease is None:
                    admission_wait_started_at = time.monotonic()
                    _llama_admission_log(
                        "queued",
                        reservation,
                        request = request,
                        mode = _tool_admission_mode,
                        completion_id = completion_id,
                        level = "debug",
                    )

                async def admitted_gguf_tool_stream():
                    lease = stream_lease
                    stream_started = False
                    stream_cancelled = False
                    try:
                        if lease is None:
                            async for wait_item in _openai_admission_wait_stream_chunks(
                                reservation,
                                admission_config,
                                request = request,
                                cancel_event = cancel_event,
                            ):
                                if isinstance(wait_item, str):
                                    yield wait_item
                                    continue
                                lease = wait_item
                                _llama_admission_log(
                                    "granted-after-wait",
                                    reservation,
                                    request = request,
                                    mode = _tool_admission_mode,
                                    wait_started_at = admission_wait_started_at,
                                    completion_id = completion_id,
                                    level = "debug",
                                )
                                break
                        if lease is None:
                            return
                        await _raise_if_openai_admission_cancelled(
                            reservation,
                            request = request,
                            cancel_event = cancel_event,
                        )
                        iterator = gguf_tool_stream()
                        stream_started = True
                        try:
                            async for chunk in iterator:
                                # Release before the yield; see gguf_stream_chunks.
                                if (
                                    lease is not None
                                    and _tool_decode_finished
                                    and chunk == _SSE_DONE_CHUNK
                                ):
                                    lease.release()
                                yield chunk
                        except asyncio.CancelledError:
                            stream_cancelled = True
                            raise
                        finally:
                            await _close_openai_admitted_stream_iterator(
                                iterator,
                                cancelled = stream_cancelled,
                            )
                    except LlamaAdmissionTimeout as exc:
                        _llama_admission_log(
                            "timeout",
                            reservation,
                            request = request,
                            mode = _tool_admission_mode,
                            wait_started_at = admission_wait_started_at,
                            completion_id = completion_id,
                            level = "warning",
                        )
                        api_monitor.fail(monitor_id, str(exc))
                        yield _openai_stream_error_sse(
                            _openai_admission_error_body(exc, status_code = 503)
                        )
                    except LlamaAdmissionCancelled:
                        _llama_admission_log(
                            "cancelled-before-upstream",
                            reservation,
                            request = request,
                            mode = _tool_admission_mode,
                            wait_started_at = admission_wait_started_at,
                            completion_id = completion_id,
                            level = "debug",
                        )
                        api_monitor.finish(monitor_id, "cancelled")
                        return
                    except asyncio.CancelledError:
                        api_monitor.finish(monitor_id, "cancelled")
                        raise
                    except HTTPException as exc:
                        status_code = getattr(exc, "status_code", 500) or 500
                        detail = exc.detail
                        error = (
                            detail
                            if isinstance(detail, dict) and "error" in detail
                            else openai_error_body(str(detail), status = status_code)
                        )
                        api_monitor.fail(monitor_id, str(detail))
                        yield _openai_stream_error_sse(error)
                    finally:
                        if lease is not None:
                            lease.release()
                        if not stream_started:
                            api_monitor.finish(monitor_id, "cancelled")
                            reservation.cancel()
                            _tracker.__exit__(None, None, None)

                async def _gguf_tool_admission_unstarted_cleanup() -> None:
                    api_monitor.finish(monitor_id, "cancelled")
                    if stream_lease is not None:
                        stream_lease.release()
                    reservation.cancel()
                    _tracker.__exit__(None, None, None)

                return _sse_streaming_response(
                    admitted_gguf_tool_stream(),
                    unstarted_cleanup = _gguf_tool_admission_unstarted_cleanup,
                    monitor_id = monitor_id,
                )

            # Non-streaming: drain into one ChatCompletion; CLI forced tools reach this path.
            def _drain_gguf_tool_loop():
                full_text = ""
                usage = None
                finish = None
                timings = None
                context_truncation = None
                gen = gguf_generate_with_tools()
                raw_text = None
                try:
                    for event in gen:
                        if cancel_event.is_set():
                            break
                        if event.get("type") == "metadata":
                            usage = event.get("usage")
                            finish = event.get("finish_reason")
                            timings = event.get("timings")
                        elif event.get("type") == "context_truncated":
                            context_truncation = _accumulate_context_truncation(
                                context_truncation, event
                            )
                        elif event.get("type") == "content":
                            # Content is cumulative within a turn and resets
                            # between turns, so the last event holds the final
                            # turn's text. As in the safetensors drain, a visible
                            # preamble emitted before a tool call (its own earlier
                            # turn) isn't carried -- only the final turn is.
                            raw_text = event.get("text", "")
                    if raw_text is not None:
                        # Stripped once: stripping every cumulative event is quadratic in the turn.
                        full_text = _strip_tool_xml_for_display(
                            raw_text,
                            auto_heal_tool_calls = _gguf_auto_heal_tool_calls,
                            enabled_tool_names = _gguf_display_tool_names,
                        )
                    return full_text, usage, finish, timings, context_truncation
                finally:
                    # Close on early break/cancel so the llama-server socket is released.
                    try:
                        gen.close()
                    except (RuntimeError, ValueError):
                        pass

            drain_task = None

            async def _drain_cancelled_gguf_tool_task():
                if drain_task is None:
                    return
                while not drain_task.done():
                    try:
                        await asyncio.shield(drain_task)
                    except asyncio.CancelledError:
                        cancel_event.set()
                        continue
                    except Exception:
                        break
                if drain_task.done():
                    try:
                        drain_task.exception()
                    except (asyncio.CancelledError, Exception):
                        pass

            admission_lease = None
            admission_wait_started_at = None
            try:
                if reservation.lease_nowait() is None:
                    admission_wait_started_at = time.monotonic()
                    _llama_admission_log(
                        "queued",
                        reservation,
                        request = request,
                        mode = _tool_admission_mode,
                        completion_id = completion_id,
                        level = "debug",
                    )
                admission_lease = await _wait_for_openai_admission_non_streaming(
                    reservation,
                    admission_config,
                    request = request,
                    cancel_event = cancel_event,
                )
                if admission_wait_started_at is not None:
                    _llama_admission_log(
                        "granted-after-wait",
                        reservation,
                        request = request,
                        mode = _tool_admission_mode,
                        wait_started_at = admission_wait_started_at,
                        completion_id = completion_id,
                        level = "debug",
                    )
                await _raise_if_openai_admission_cancelled(
                    reservation,
                    request = request,
                    cancel_event = cancel_event,
                )
                # Open before the task/thread copy the context so _friendly_error sees the slot.
                context_refusal.open_slot()
                drain_task = asyncio.create_task(asyncio.to_thread(_drain_gguf_tool_loop))
                disconnect_watcher = asyncio.create_task(
                    _await_disconnect_then_cancel(request, cancel_event)
                )
                try:
                    (
                        full_text,
                        completion_usage,
                        completion_finish,
                        completion_timings,
                        completion_context_truncation,
                    ) = await asyncio.shield(drain_task)
                finally:
                    await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
                reasoning_text, visible_text = _extract_responses_reasoning(
                    full_text,
                    parse_think_markers = _responses_should_parse_think_markers(
                        payload, llama_backend
                    ),
                )
                message_kwargs = {"content": visible_text}
                if reasoning_text:
                    message_kwargs["reasoning_content"] = reasoning_text
                _usage = completion_usage or {}
                _prompt_tokens = _usage.get("prompt_tokens") or 0
                _completion_tokens = _usage.get("completion_tokens") or 0
                response = ChatCompletion(
                    id = completion_id,
                    created = created,
                    model = model_name,
                    choices = [
                        CompletionChoice(
                            message = CompletionMessage(**message_kwargs),
                            finish_reason = _clamp_finish_reason(completion_finish),
                        )
                    ],
                    usage = CompletionUsage(
                        prompt_tokens = _prompt_tokens,
                        completion_tokens = _completion_tokens,
                        total_tokens = _prompt_tokens + _completion_tokens,
                        prompt_tokens_details = _prompt_tokens_details(
                            _usage.get("prompt_tokens_details")
                        ),
                    ),
                )
                api_monitor.set_reply(monitor_id, visible_text)
                _monitor_usage(
                    monitor_id,
                    {
                        "prompt_tokens": _prompt_tokens,
                        "completion_tokens": _completion_tokens,
                        "total_tokens": _prompt_tokens + _completion_tokens,
                    },
                    _monitor_context_length(),
                    timings = completion_timings,
                    stop_reason = _clamp_finish_reason(completion_finish),
                )
                # Cancel still returns JSON 200; flag failed so middleware does not claim a preview slot.
                if cancel_event.is_set():
                    from core.inference.llama_keepwarm import mark_current_response_failed
                    mark_current_response_failed()
                api_monitor.finish(
                    monitor_id, "cancelled" if cancel_event.is_set() else "completed"
                )
                return _model_json_response_with_context_truncation(
                    response, completion_context_truncation
                )
            except asyncio.CancelledError:
                cancel_event.set()
                await _drain_cancelled_gguf_tool_task()
                api_monitor.finish(monitor_id, "cancelled")
                reservation.cancel()
                if admission_lease is not None:
                    admission_lease.release()
                _tracker.__exit__(None, None, None)
                raise
            except LlamaAdmissionTimeout as exc:
                _llama_admission_log(
                    "timeout",
                    reservation,
                    request = request,
                    mode = _tool_admission_mode,
                    wait_started_at = admission_wait_started_at,
                    completion_id = completion_id,
                    level = "warning",
                )
                api_monitor.fail(monitor_id, str(exc))
                if admission_lease is not None:
                    admission_lease.release()
                _tracker.__exit__(None, None, None)
                raise _openai_admission_http_exception(exc, status_code = 503)
            except LlamaAdmissionCancelled as exc:
                _llama_admission_log(
                    "cancelled-before-upstream",
                    reservation,
                    request = request,
                    mode = _tool_admission_mode,
                    wait_started_at = admission_wait_started_at,
                    completion_id = completion_id,
                    level = "debug",
                )
                api_monitor.finish(monitor_id, "cancelled")
                if admission_lease is not None:
                    admission_lease.release()
                _tracker.__exit__(None, None, None)
                raise HTTPException(
                    status_code = 499,
                    detail = _openai_admission_error_body(exc, status_code = 499),
                )
            except Exception as e:
                logger.error(f"Error during GGUF tool completion: {e}", exc_info = True)
                api_monitor.fail(monitor_id, _friendly_error(e))
                # Recover if an MTP crash killed the server.
                get_llama_cpp_backend()._maybe_recover_from_mtp_crash(e)
                # Map upstream 4xx (e.g. over-context) to a 400 instead of leaking a 500.
                _cls = _classify_llama_generation_error(e)
                if _cls is not None:
                    raise HTTPException(
                        status_code = 400,
                        detail = openai_error_body(
                            _friendly_error(e),
                            status = 400,
                            code = "context_length_exceeded" if _cls else None,
                            param = "messages",
                        ),
                    )
                raise HTTPException(status_code = 500, detail = safe_error_detail(e))
            finally:
                if admission_lease is not None:
                    admission_lease.release()
                _tracker.__exit__(None, None, None)

        # ── Standard GGUF path (no tools) ─────────────────────

        def gguf_generate(choice_index: int = 0):
            _seed = _choice_seed(payload.seed, choice_index, negative_is_random = True)
            return llama_backend.generate_chat_completion(
                messages = gguf_messages,
                image_b64 = image_b64,
                temperature = payload.temperature,
                top_p = payload.top_p,
                top_k = payload.top_k,
                min_p = payload.min_p,
                max_tokens = effective_max_tokens,
                repetition_penalty = payload.repetition_penalty,
                presence_penalty = payload.presence_penalty,
                frequency_penalty = payload.frequency_penalty,
                logit_bias = payload.logit_bias,
                stop = normalized_stop,
                cancel_event = cancel_event,
                enable_thinking = payload.enable_thinking,
                reasoning_effort = payload.reasoning_effort,
                preserve_thinking = payload.preserve_thinking,
                continue_final_message = _continue_final_message(payload, thought = True),
                seed = _seed,
                perf_callback = _gguf_perf_callback,
                context_overflow = _rolling_context_policy(payload),
                context_policy = _request_context_policy(payload),
                compaction_headroom_ratio = _request_compaction_headroom_ratio(payload),
                compact_context = getattr(payload, "compact_context", None) is True,
                thread_id = payload.thread_id,
                # Tell the epoch gate tools are withheld; it cannot see that from process policy.
                tools_withheld = _tool_loop_unusable,
            )

        _gguf_sentinel = object()
        # True only once the sync generator returned on its own; a cancel still emits [DONE].
        _gguf_decode_finished = False

        if payload.stream:
            if _wants_multiple_choices(payload):
                raise _reject_unsupported_n("streaming GGUF chat completions")
            _cancel_keys = (payload.cancel_id, payload.session_id, completion_id)
            _tracker = _TrackedCancel.for_payload(cancel_event, payload, *_cancel_keys)
            _tracker.__enter__()
            try:
                reservation, admission_config = await _reserve_counted_gguf_chat(
                    messages = gguf_messages,
                    request = request,
                    llama_backend = llama_backend,
                    payload = payload,
                )
            except LlamaAdmissionQueueFull as exc:
                _tracker.__exit__(None, None, None)
                _llama_admission_log(
                    "queue-full",
                    snapshot = exc.snapshot,
                    request = request,
                    mode = "chat_standard_stream",
                    completion_id = completion_id,
                    level = "warning",
                )
                api_monitor.fail(monitor_id, str(exc))
                raise _openai_admission_http_exception(exc, status_code = 429)
            except BaseException:
                _tracker.__exit__(None, None, None)
                raise

            async def gguf_stream_chunks():
                nonlocal _gguf_decode_finished
                disconnect_watcher = asyncio.create_task(
                    _await_disconnect_then_cancel(request, cancel_event)
                )
                gen = None
                next_task = None
                stream_completed = False
                try:
                    from core.inference.llama_keepwarm import mark_current_response_failed

                    yield _chat_role_chunk(completion_id, created, model_name)

                    # In a thread so the event loop stays free for disconnect detection.
                    gen = gguf_generate()
                    gen_step = ThreadStepper(gen).next
                    prev_text = ""
                    reasoning_extractor = _new_chat_reasoning_extractor()
                    _stream_usage = None
                    _stream_timings = None
                    _stream_finish = None
                    while True:
                        if cancel_event.is_set():
                            mark_current_response_failed()
                            break
                        if await request.is_disconnected():
                            cancel_event.set()
                            mark_current_response_failed()
                            api_monitor.finish(monitor_id, "cancelled")
                            return
                        next_task = asyncio.create_task(gen_step(_gguf_sentinel))
                        try:
                            # Stall-timeout wait: keepalive while the generator stays
                            # silent (e.g. no-tool prefill). asyncio.wait never cancels
                            # next_task, matching the finally-drain shield (see GGUF stream).
                            async for stall_line in _stall_wait_frames(
                                next_task,
                                _gguf_prefill_signal,
                                _LOCAL_TOOL_STREAM_STALL_KEEPALIVE_S,
                            ):
                                yield stall_line
                            cumulative = next_task.result()
                        finally:
                            if next_task.done():
                                next_task = None
                        if cumulative is _gguf_sentinel:
                            _gguf_decode_finished = True
                            break
                        # Capture server metadata for the final usage chunk
                        if isinstance(cumulative, dict):
                            if cumulative.get("type") == "metadata":
                                _stream_usage = cumulative.get("usage")
                                _stream_timings = cumulative.get("timings")
                                _stream_finish = cumulative.get("finish_reason")
                            elif cumulative.get("type") == "quote_cut":
                                if _ui_events:
                                    yield _quote_cut_sse_chunk(completion_id, model_name)
                                elif _drop_keepalive.due():
                                    yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                            elif cumulative.get("type") == "diffusion_frame":
                                # Diffusion frames go raw on tool_status and never enter the cumulative diff.
                                if _ui_events:
                                    yield f"data: {json.dumps(cumulative)}\n\n"
                                elif _drop_keepalive.due():
                                    yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                            elif cumulative.get("type") == "context_truncated":
                                yield _context_truncated_sse_chunk(
                                    completion_id,
                                    model_name,
                                    {
                                        key: value
                                        for key, value in cumulative.items()
                                        if key != "type"
                                    },
                                )
                            else:
                                logger.warning(
                                    "gguf_stream_chunks: unexpected dict event: %s",
                                    {k: v for k, v in cumulative.items() if k != "timings"},
                                )
                            continue
                        new_text = cumulative[len(prev_text) :]
                        prev_text = cumulative
                        if not new_text:
                            continue
                        reasoning_delta, visible_delta = reasoning_extractor.feed(new_text)
                        if reasoning_delta:
                            api_monitor.mark_first_token(monitor_id)
                            yield _gguf_chat_delta_line(
                                ChoiceDelta(reasoning_content = reasoning_delta)
                            )
                        if visible_delta:
                            api_monitor.append_reply(monitor_id, visible_delta)
                            yield _gguf_chat_delta_line(ChoiceDelta(content = visible_delta))

                    final_reasoning, final_visible = reasoning_extractor.finish()
                    if final_reasoning:
                        # Held-back markers can make this the FIRST output of all.
                        api_monitor.mark_first_token(monitor_id)
                        yield _gguf_chat_delta_line(ChoiceDelta(reasoning_content = final_reasoning))
                    if final_visible:
                        api_monitor.append_reply(monitor_id, final_visible)
                        yield _gguf_chat_delta_line(ChoiceDelta(content = final_visible))

                    # Final chunk
                    final_chunk = ChatCompletionChunk(
                        id = completion_id,
                        created = created,
                        model = model_name,
                        choices = [
                            ChunkChoice(
                                delta = ChoiceDelta(),
                                finish_reason = _clamp_finish_reason(_stream_finish),
                            )
                        ],
                    )
                    # finish_reason chunk must precede the usage chunk and [DONE].
                    yield f"data: {final_chunk.model_dump_json(exclude_none = True)}\n\n"
                    usage_line = _openai_stream_usage_chunk(
                        payload,
                        completion_id,
                        created,
                        model_name,
                        _stream_usage,
                        _stream_timings,
                    )
                    if usage_line is not None:
                        yield usage_line
                    _monitor_usage(
                        monitor_id,
                        _stream_usage,
                        _monitor_context_length(),
                        timings = _stream_timings,
                        stop_reason = _clamp_finish_reason(_stream_finish),
                    )
                    if cancel_event.is_set():
                        mark_current_response_failed()
                    api_monitor.finish(
                        monitor_id, "cancelled" if cancel_event.is_set() else "completed"
                    )
                    stream_completed = True
                    yield "data: [DONE]\n\n"

                except asyncio.CancelledError:
                    cancel_event.set()
                    api_monitor.finish(monitor_id, "cancelled")
                    raise
                except Exception as e:
                    logger.error(f"Error during GGUF streaming: {e}", exc_info = True)
                    api_monitor.fail(monitor_id, _friendly_error(e))
                    error_chunk = _openai_stream_error_chunk(e)
                    yield _openai_stream_error_sse(error_chunk)
                finally:
                    try:
                        if not stream_completed:
                            cancel_event.set()
                        task_to_drain = next_task
                        next_task = None
                        while task_to_drain is not None and not task_to_drain.done():
                            try:
                                await asyncio.shield(task_to_drain)
                            except asyncio.CancelledError:
                                cancel_event.set()
                                continue
                            except Exception:
                                break
                        if task_to_drain is not None and task_to_drain.done():
                            try:
                                task_to_drain.exception()
                            except (asyncio.CancelledError, Exception):
                                pass
                        if gen is not None and not stream_completed:
                            try:
                                await asyncio.to_thread(gen.close)
                            except (RuntimeError, ValueError):
                                pass
                            except Exception:
                                logger.debug(
                                    "Error closing GGUF stream generator during cleanup",
                                    exc_info = True,
                                )
                        await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
                    finally:
                        _tracker.__exit__(None, None, None)

            stream_lease = reservation.lease_nowait()
            admission_wait_started_at = None
            if stream_lease is None:
                admission_wait_started_at = time.monotonic()
                _llama_admission_log(
                    "queued",
                    reservation,
                    request = request,
                    mode = "chat_standard_stream",
                    completion_id = completion_id,
                    level = "debug",
                )

            async def admitted_gguf_stream_chunks():
                lease = stream_lease
                stream_started = False
                stream_cancelled = False
                try:
                    if lease is None:
                        async for wait_item in _openai_admission_wait_stream_chunks(
                            reservation,
                            admission_config,
                            request = request,
                            cancel_event = cancel_event,
                        ):
                            if isinstance(wait_item, str):
                                yield wait_item
                                continue
                            lease = wait_item
                            _llama_admission_log(
                                "granted-after-wait",
                                reservation,
                                request = request,
                                mode = "chat_standard_stream",
                                wait_started_at = admission_wait_started_at,
                                completion_id = completion_id,
                                level = "debug",
                            )
                            break
                    if lease is None:
                        return
                    await _raise_if_openai_admission_cancelled(
                        reservation,
                        request = request,
                        cancel_event = cancel_event,
                    )
                    iterator = gguf_stream_chunks()
                    stream_started = True
                    try:
                        async for chunk in iterator:
                            # Release before the final yield: the finally only runs at ASGI teardown.
                            # Exact equality, not endswith: _openai_stream_error_sse ends in the same
                            # sentinel but still owns the slot.
                            if (
                                lease is not None
                                and _gguf_decode_finished
                                and chunk == _SSE_DONE_CHUNK
                            ):
                                lease.release()
                            yield chunk
                    except asyncio.CancelledError:
                        stream_cancelled = True
                        raise
                    finally:
                        await _close_openai_admitted_stream_iterator(
                            iterator,
                            cancelled = stream_cancelled,
                        )
                except LlamaAdmissionTimeout as exc:
                    _llama_admission_log(
                        "timeout",
                        reservation,
                        request = request,
                        mode = "chat_standard_stream",
                        wait_started_at = admission_wait_started_at,
                        completion_id = completion_id,
                        level = "warning",
                    )
                    api_monitor.fail(monitor_id, str(exc))
                    yield _openai_stream_error_sse(
                        _openai_admission_error_body(exc, status_code = 503)
                    )
                except LlamaAdmissionCancelled:
                    _llama_admission_log(
                        "cancelled-before-upstream",
                        reservation,
                        request = request,
                        mode = "chat_standard_stream",
                        wait_started_at = admission_wait_started_at,
                        completion_id = completion_id,
                        level = "debug",
                    )
                    api_monitor.finish(monitor_id, "cancelled")
                    return
                except asyncio.CancelledError:
                    api_monitor.finish(monitor_id, "cancelled")
                    raise
                except HTTPException as exc:
                    status_code = getattr(exc, "status_code", 500) or 500
                    detail = exc.detail
                    error = (
                        detail
                        if isinstance(detail, dict) and "error" in detail
                        else openai_error_body(str(detail), status = status_code)
                    )
                    api_monitor.fail(monitor_id, str(detail))
                    yield _openai_stream_error_sse(error)
                finally:
                    if lease is not None:
                        lease.release()
                    if not stream_started:
                        api_monitor.finish(monitor_id, "cancelled")
                        reservation.cancel()
                        _tracker.__exit__(None, None, None)

            async def _gguf_admission_unstarted_cleanup() -> None:
                api_monitor.finish(monitor_id, "cancelled")
                if stream_lease is not None:
                    stream_lease.release()
                reservation.cancel()
                _tracker.__exit__(None, None, None)

            return _sse_streaming_response(
                admitted_gguf_stream_chunks(),
                unstarted_cleanup = _gguf_admission_unstarted_cleanup,
                monitor_id = monitor_id,
            )
        else:
            try:
                reservation, admission_config = await _reserve_counted_gguf_chat(
                    messages = gguf_messages,
                    request = request,
                    llama_backend = llama_backend,
                    payload = payload,
                )
            except LlamaAdmissionQueueFull as exc:
                _llama_admission_log(
                    "queue-full",
                    snapshot = exc.snapshot,
                    request = request,
                    mode = "chat_standard_nonstream",
                    completion_id = completion_id,
                    level = "warning",
                )
                api_monitor.fail(monitor_id, str(exc))
                raise _openai_admission_http_exception(exc, status_code = 429)

            _cancel_keys = (payload.cancel_id, payload.session_id, completion_id)
            _tracker = _TrackedCancel.for_payload(cancel_event, payload, *_cancel_keys)
            _tracker.__enter__()
            admission_lease = None
            admission_wait_started_at = None
            try:
                if reservation.lease_nowait() is None:
                    admission_wait_started_at = time.monotonic()
                    _llama_admission_log(
                        "queued",
                        reservation,
                        request = request,
                        mode = "chat_standard_nonstream",
                        completion_id = completion_id,
                        level = "debug",
                    )
                admission_lease = await _wait_for_openai_admission_non_streaming(
                    reservation,
                    admission_config,
                    request = request,
                    cancel_event = cancel_event,
                )
                if admission_wait_started_at is not None:
                    _llama_admission_log(
                        "granted-after-wait",
                        reservation,
                        request = request,
                        mode = "chat_standard_nonstream",
                        wait_started_at = admission_wait_started_at,
                        completion_id = completion_id,
                        level = "debug",
                    )
                await _raise_if_openai_admission_cancelled(
                    reservation,
                    request = request,
                    cancel_event = cancel_event,
                )
            except asyncio.CancelledError:
                api_monitor.finish(monitor_id, "cancelled")
                reservation.cancel()
                if admission_lease is not None:
                    admission_lease.release()
                _tracker.__exit__(None, None, None)
                raise
            except LlamaAdmissionTimeout as exc:
                _llama_admission_log(
                    "timeout",
                    reservation,
                    request = request,
                    mode = "chat_standard_nonstream",
                    wait_started_at = admission_wait_started_at,
                    completion_id = completion_id,
                    level = "warning",
                )
                api_monitor.fail(monitor_id, str(exc))
                if admission_lease is not None:
                    admission_lease.release()
                _tracker.__exit__(None, None, None)
                raise _openai_admission_http_exception(exc, status_code = 503)
            except LlamaAdmissionCancelled as exc:
                _llama_admission_log(
                    "cancelled-before-upstream",
                    reservation,
                    request = request,
                    mode = "chat_standard_nonstream",
                    wait_started_at = admission_wait_started_at,
                    completion_id = completion_id,
                    level = "debug",
                )
                api_monitor.finish(monitor_id, "cancelled")
                if admission_lease is not None:
                    admission_lease.release()
                _tracker.__exit__(None, None, None)
                raise HTTPException(
                    status_code = 499,
                    detail = _openai_admission_error_body(exc, status_code = 499),
                )

            try:
                # The single decode slot yields one at a time, so n choices run sequentially.
                drain_task = None

                async def _drain_cancelled_gguf_task():
                    if drain_task is None:
                        return
                    while not drain_task.done():
                        try:
                            await asyncio.shield(drain_task)
                        except asyncio.CancelledError:
                            cancel_event.set()
                            continue
                        except Exception:
                            break
                    if drain_task.done():
                        try:
                            drain_task.exception()
                        except (asyncio.CancelledError, Exception):
                            pass

                def _drain_gguf_choices():
                    _n = payload.n or 1
                    _choices = []
                    _monitor_replies = []
                    _prompt_tokens = 0
                    _sum_completion = 0
                    _prompt_details = None
                    _last_timings = None
                    _last_finish = None
                    _context_truncation = None
                    for _idx in range(_n):
                        # Stop spawning the remaining choices once cancelled.
                        if cancel_event.is_set():
                            break
                        full_text = ""
                        completion_usage = None
                        completion_finish = None
                        _choice_context_truncation = None
                        for token in gguf_generate(_idx):
                            if isinstance(token, dict):
                                if token.get("type") == "metadata":
                                    completion_usage = token.get("usage")
                                    completion_finish = token.get("finish_reason")
                                    _last_timings = token.get("timings")
                                    _last_finish = completion_finish
                                elif token.get("type") == "context_truncated":
                                    _choice_context_truncation = _accumulate_context_truncation(
                                        _choice_context_truncation, token
                                    )
                                continue
                            full_text = token

                        if _choice_context_truncation is not None and (
                            _context_truncation is None
                            or int(_choice_context_truncation.get("dropped_messages") or 0)
                            >= int(_context_truncation.get("dropped_messages") or 0)
                        ):
                            # Choices share one prompt: report the max truncation, not the sum.
                            _context_truncation = _choice_context_truncation

                        reasoning_text, visible_text = _extract_responses_reasoning(
                            full_text,
                            parse_think_markers = _responses_should_parse_think_markers(
                                payload,
                                llama_backend,
                            ),
                        )
                        message_kwargs = {"content": visible_text}
                        if reasoning_text:
                            message_kwargs["reasoning_content"] = reasoning_text
                        _choices.append(
                            CompletionChoice(
                                index = _idx,
                                message = CompletionMessage(**message_kwargs),
                                finish_reason = _clamp_finish_reason(completion_finish),
                            )
                        )
                        _monitor_replies.append(visible_text)
                        if completion_usage:
                            # Prompt shared across n choices: count its tokens once.
                            _prompt_tokens = completion_usage.get("prompt_tokens") or _prompt_tokens
                            _sum_completion += completion_usage.get("completion_tokens") or 0
                            if _prompt_details is None:
                                _prompt_details = completion_usage.get("prompt_tokens_details")
                    return (
                        _n,
                        _choices,
                        _monitor_replies,
                        _prompt_tokens,
                        _sum_completion,
                        _prompt_details,
                        _last_timings,
                        _last_finish,
                        _context_truncation,
                    )

                # See the tool-loop drain: the slot has to exist before the copies.
                context_refusal.open_slot()
                drain_task = asyncio.create_task(asyncio.to_thread(_drain_gguf_choices))
                disconnect_watcher = asyncio.create_task(
                    _await_disconnect_then_cancel(request, cancel_event)
                )
                try:
                    (
                        _n,
                        _choices,
                        _monitor_replies,
                        _prompt_tokens,
                        _sum_completion,
                        _prompt_details,
                        _last_timings,
                        _last_finish,
                        _context_truncation,
                    ) = await asyncio.shield(drain_task)
                finally:
                    await _stop_local_disconnect_cancel_watcher(disconnect_watcher)

                _mark_cancelled_json_response_failed(request, cancel_event)

                response = ChatCompletion(
                    id = completion_id,
                    created = created,
                    model = model_name,
                    choices = _choices,
                    usage = CompletionUsage(
                        prompt_tokens = _prompt_tokens,
                        completion_tokens = _sum_completion,
                        total_tokens = _prompt_tokens + _sum_completion,
                        prompt_tokens_details = _prompt_tokens_details(_prompt_details),
                    ),
                )
                monitor_reply = _monitor_replies[-1] if _monitor_replies else ""
                if _n > 1:
                    monitor_reply = "\n\n".join(
                        f"Choice {_idx + 1}:\n{text}" for _idx, text in enumerate(_monitor_replies)
                    )
                api_monitor.set_reply(monitor_id, monitor_reply)
                _monitor_usage(
                    monitor_id,
                    {
                        "prompt_tokens": _prompt_tokens,
                        "completion_tokens": _sum_completion,
                        "total_tokens": _prompt_tokens + _sum_completion,
                    },
                    _monitor_context_length(),
                    # Omit for n > 1: they describe only the final choice.
                    timings = _last_timings if len(_monitor_replies) <= 1 else None,
                    stop_reason = (
                        _clamp_finish_reason(_last_finish)
                        if _last_finish and len(_monitor_replies) <= 1
                        else None
                    ),
                )
                api_monitor.finish(
                    monitor_id, "cancelled" if cancel_event.is_set() else "completed"
                )
                return _model_json_response_with_context_truncation(response, _context_truncation)

            except asyncio.CancelledError:
                cancel_event.set()
                await _drain_cancelled_gguf_task()
                api_monitor.finish(monitor_id, "cancelled")
                raise
            except Exception as e:
                logger.error(f"Error during GGUF completion: {e}", exc_info = True)
                api_monitor.fail(monitor_id, _friendly_error(e))
                # Recover if an MTP crash killed the server.
                get_llama_cpp_backend()._maybe_recover_from_mtp_crash(e)
                # Map upstream 4xx (e.g. over-context) to a 400 instead of leaking a 500.
                _cls = _classify_llama_generation_error(e)
                if _cls is not None:
                    raise HTTPException(
                        status_code = 400,
                        detail = openai_error_body(
                            _friendly_error(e),
                            status = 400,
                            code = "context_length_exceeded" if _cls else None,
                            param = "messages",
                        ),
                    )
                raise HTTPException(status_code = 500, detail = safe_error_detail(e))
            finally:
                if admission_lease is not None:
                    admission_lease.release()
                _tracker.__exit__(None, None, None)
    # ── Standard Unsloth path ─────────────────────────────────
    # Re-derived: an auto-switch may have changed models.
    served_images: list[str] = []
    images: list = []
    _managed_images = backend.models.get(backend.active_model_name, {}).get("engine") in (
        "vllm",
        "sglang",
    )
    if _serves_several_images(backend) and not _managed_images:
        _, _msgs, _payloads = _extract_content_parts(
            payload.messages, structured = True, keep_tool_images = True
        )
        _legacy_distinct = _legacy_image_is_distinct(payload)
        # A legacy image the messages do not carry joins the newest user turn, as GGUF splices it.
        if _legacy_distinct:
            _payloads = _serve_legacy_image_on_the_newest_turn(
                _msgs, _payloads, payload.image_base64
            )
        # Only above one image, so an ordinary single-image request renders exactly as before.
        if len(_payloads) > 1 and not _newest_turn_shows_more_images_than_it_sends(
            payload.messages, _legacy_distinct
        ):
            chat_messages, served_images = _msgs, _payloads

    # Decode image (from content parts OR legacy field)
    image_b64 = extracted_image_b64 or payload.image_base64
    image = None
    # Count image PARTS, not decoded ones: remote or empty URLs yield no base64.
    images_on_turn = _images_in_last_user_message(payload.messages)

    _managed_promoted_parts: list = []
    if _managed_images:
        # Fetch remote image URLs here: the engine's own fetch has no SSRF guard.
        if _messages_have_remote_image(payload.messages):
            try:
                await asyncio.to_thread(_inline_request_remote_images, payload)
            except HTTPException as exc:
                raise _reject(exc.status_code, exc.detail)
        chat_messages = [
            message
            for message in await _promote_mcp_history_images_async(
                _openai_messages_for_passthrough(
                    payload, normalize_images = False, promote_mcp_images = False
                ),
                vision = bool(backend.models.get(backend.active_model_name, {}).get("is_vision")),
                promoted_out = _managed_promoted_parts,
            )
            if message.get("role") not in ("system", "developer")
        ]
        if any(
            isinstance(message.get("content"), list)
            and any(part.get("type") == "image_url" for part in message["content"])
            for message in chat_messages
        ) and not backend.models.get(backend.active_model_name, {}).get("is_vision"):
            raise _reject(
                400, "Image provided but current model is text-only. Load a vision model."
            )
        _managed_image_count = sum(
            part.get("type") == "image_url"
            for message in chat_messages
            if isinstance(message.get("content"), list)
            for part in message["content"]
        )
        if _managed_image_count > _MAX_SERVED_IMAGES:
            raise _reject(
                400,
                f"This request carries {_managed_image_count} images; at most "
                f"{_MAX_SERVED_IMAGES} are served per request. Send fewer, or split the conversation.",
            )

    if not _managed_images and (image_b64 or images_on_turn > 1):
        try:
            model_info = backend.models.get(backend.active_model_name, {})
            if not model_info.get("is_vision"):
                # _reject, not a bare raise: the monitor row is open and must be closed.
                raise _reject(
                    400,
                    "Image provided but current model is text-only. Load a vision model.",
                )

            # A distinct legacy image counts as a second image; otherwise it would go unread.
            _legacy_is_distinct = _legacy_image_is_distinct(payload)
            if not served_images and (
                images_on_turn + int(_legacy_is_distinct) > 1
                or (extracted_image_b64 and _legacy_is_distinct)
            ):
                raise _reject(
                    400,
                    (
                        "This model takes one image per message. Attach one, or load a"
                        " GGUF build of it, which accepts several."
                    ),
                )

            if served_images:
                images = await _decode_request_images(backend, served_images, reject = _reject)
            elif image_b64:
                image = await asyncio.to_thread(
                    _decode_and_resize_image,
                    backend,
                    image_b64,
                )

        except HTTPException:
            raise
        except Exception as e:
            # log_and_http_error does not know the monitor row, so pass its public detail to _reject to close it.
            decode_error = log_and_http_error(
                e,
                400,
                "Failed to decode image",
                event = "inference.decode_image_failed",
                log = logger,
            )
            raise _reject(decode_error.status_code, decode_error.detail)

    # Classify capability flags from the loaded template.
    _sf_model_info = backend.models.get(backend.active_model_name, {})
    _sf_fit_overflow = (
        _rolling_context_policy(payload)
        if _sf_model_info.get("is_mlx") or _sf_model_info.get("engine") in ("vllm", "sglang")
        else None
    )
    if _sf_model_info.get("engine") in ("vllm", "sglang"):
        if _managed_engine_unsupported_controls(payload, _sf_model_info):
            raise _reject(
                400,
                "This engine integration does not support adapters or reasoning controls.",
            )
        if _continue_final_message(payload, thought = True) and not _continue_final_message(payload):
            raise _reject(
                400, "This engine cannot resume a response that stopped mid-thought. Use Retry."
            )
        from routes.managed_engine_chat import managed_tool_chat

        response = await managed_tool_chat(
            payload,
            request,
            backend,
            chat_messages,
            system_prompt,
            monitor_id,
            promoted_image_parts = tuple(_managed_promoted_parts),
        )
        if response is not None:
            return response
    # Decode cache shared with the client-tool rebuild so large pictures decode once.
    _sf_mcp_decode_cache: dict = {}
    # Pass DECODED pictures: the worker's decode skips 16-bit scaling and color conversion.
    chat_messages, sf_mcp_images = await _promote_local_mcp_images_async(
        chat_messages,
        vision = bool(_sf_model_info.get("is_vision")),
        decode_cache = _sf_mcp_decode_cache,
        caller_images = images or served_images,
    )
    # Resolve tool policy BEFORE classifying the protocol: the branch must match generation.
    from state.tool_policy import get_tool_policy as _get_tool_policy_sf

    _sf_cli_policy = _get_tool_policy_sf()
    _sf_tools_on = _effective_enable_tools(payload)
    # A request that says anything about tools keeps its opt-out; the launcher default
    # does not apply (mirrors GGUF _client_disabled_tool_calls / _takes_tool_passthrough).
    if _sf_tools_on and not _launcher_tool_default_applies(payload, _ui_events):
        _sf_tools_on = False
    if _response_format_constrains_decoding(payload) and not _explicit_studio_tool_loop_requested(
        payload
    ):
        _sf_tools_on = False
    # Nothing below reads tool_choice: drop the catalogue for none, or a headerless stream waits an hour.
    if payload.tool_choice == "none":
        _sf_tools_on = False
    _sf_mcp_allowed = (
        payload.tool_choice != "none" and bool(payload.mcp_enabled) and _sf_cli_policy is not False
    )
    # tool_choice asked directly: _tool_loop_unusable weighs it against GGUF's tools.
    _sf_recall_loop_usable = (
        payload.tool_choice != "none"
        # Managed engines refuse tools on this path; their tool turns go through managed_tool_chat.
        and _sf_model_info.get("engine") not in ("vllm", "sglang")
        and not _tool_loop_unusable
        and not _has_client_tool_contract
        and not _response_format_constrains_decoding(payload)
        and (_ui_events or not _confirm_gate_would_prompt(payload, ("search_conversation",)))
    )
    # GGUF parity: a checkpointed thread reopens the loop with search_conversation alone.
    _sf_recall_reopens_loop = (
        _sf_fit_overflow is not None
        and not (_sf_tools_on or _sf_mcp_allowed)
        and _sf_recall_loop_usable
        and _checkpoint_recall_may_enable_tools(payload)
    )

    # Some named templates expose reasoning only in their tool_use branch.
    _sf_server_tool_intent = payload.tool_choice != "none" and bool(
        _sf_tools_on or _sf_recall_reopens_loop or _explicit_studio_tool_loop_requested(payload)
    )
    # Detection only; must not follow tool_choice or client tool history loses its fields.
    _sf_template_tools = payload.tools or None
    if not _sf_template_tools and (
        _sf_server_tool_intent or any(m.role == "tool" or m.tool_calls for m in payload.messages)
    ):
        _sf_template_tools = ({},)

    # Must match what generation renders: normalized messages and the same <think> sweep.
    try:
        from core.inference.chat_template_helpers import (
            neutralize_control_markup_in_messages as _sf_sweep,
        )
        _sf_probe_messages = (
            jsonable_encoder(
                _sf_sweep(
                    ([{"role": "system", "content": system_prompt}] if system_prompt else [])
                    + chat_messages
                )
            )
            or None
        )
    except Exception:
        _sf_probe_messages = None

    def _sf_response_protocol(
        tools = None,
        template = None,
        prefer_tool_use = True,
    ):
        # Forward only the non-default: unconditional breaks stubs predating the parameter.
        _pref = {} if prefer_tool_use else {"prefer_tool_use": False}
        if template is None:
            features, body = _sf_rendered_features(backend, _sf_model_info, tools, **_pref)
        else:
            body = template
            # One specific body, so no reasoning rescue from an unselected branch.
            _pref["reasoning_fallback"] = False
            features = _detect_safetensors_features(backend, body, tools = tools, **_pref)
        # The prefill probe needs the ONE body that renders, not the collection (#10092).
        try:
            from core.inference.chat_template_helpers import (
                _selected_template_strings_from_value,
            )
            _selected = _selected_template_strings_from_value(
                body, tools, prefer_tool_use = prefer_tool_use
            )
            if _selected:
                body = _selected[0]
        except Exception:
            logger.debug("safetensors_prefill_template_selection_failed", exc_info = True)
        parse_think = _sf_parse_think_markers(
            features,
            payload.enable_thinking,
            payload.reasoning_effort,
        )
        reasoning_prefilled = _sf_reasoning_prefill_mode(
            features,
            payload.enable_thinking,
            body,
            reasoning_effort = payload.reasoning_effort,
            messages = _sf_probe_messages,
        )
        return features, parse_think, reasoning_prefilled

    # Branch selection must match whether this request renders tools.
    _sf_features, _sf_parse_think, _sf_reasoning_prefilled = _sf_response_protocol(
        _sf_template_tools
    )

    # Replayed MCP pictures use the processor path, so classify against its template.
    _sf_has_any_image = image is not None or bool(sf_mcp_images) or bool(images)
    # Resolved BEFORE the capability gate below, which classifies from this body (#10092).
    _sf_image_tpl = (
        (_sf_model_info.get("chat_template_info") or {}).get("processor_template")
        # A clip renders through the processor as an image does.
        if _sf_has_any_image or _video_clip is not None
        else None
    )
    # Differs from processor_template: a template-less processor still places the image.
    _sf_renders_image = _sf_has_any_image and bool(
        (_sf_model_info.get("chat_template_info") or {}).get("renders_image")
    )
    if _sf_image_tpl is not None:
        # Reclassify the WHOLE protocol: a processor body can carry an undeclared reasoning channel.
        _sf_features, _sf_parse_think, _sf_reasoning_prefilled = _sf_response_protocol(
            _sf_template_tools,
            template = _sf_image_tpl,
            prefer_tool_use = False,
        )

    # The safetensors thinking mode is only known from the template classified above.
    if _sf_features.get("supports_reasoning"):
        _fill_recommended_sampling_openai(
            payload,
            _reco_model_id,
            thinking = bool(_sf_parse_think),
            explicit = _client_sampling_fields,
        )

    # Only the first turn continues and prefills nothing; later tool-loop turns prefill as usual.
    _sf_continue = _continue_final_message(payload, thought = bool(_sf_model_info.get("is_mlx")))
    _sf_resumes_thought = _sf_continue and not _continue_final_message(payload)
    _sf_continued_turn = [_sf_continue]

    _sf_single_block = _response_format_constrains_decoding(payload)

    def _new_sf_reasoning_extractor():
        prefilled = _sf_reasoning_prefilled
        if _sf_continued_turn[0]:
            _sf_continued_turn[0] = False
            prefilled = _sf_resumes_thought
        return _ResponsesReasoningExtractor(
            parse_think_markers = _sf_parse_think,
            reasoning_prefilled = prefilled,
            single_block = _sf_single_block,
        )

    cancel_event = _chat_cancel_event(request)
    completion_id = f"chatcmpl-{uuid.uuid4().hex[:12]}"
    created = int(time.time())

    # ── Safetensors tool-calling path ─────────────────────────
    # Disabled for gpt-oss (Harmony channels, not <tool_call> XML).
    _sf_is_gptoss = False
    try:
        _sf_is_gptoss = bool(hasattr(backend, "_is_gpt_oss_model") and backend._is_gpt_oss_model())
    except Exception:
        _sf_is_gptoss = False

    _sf_tool_budget = (
        payload.max_tool_calls_per_message if payload.max_tool_calls_per_message is not None else 25
    )

    # _sf_cli_policy, _sf_tools_on and _sf_mcp_allowed resolve first, so both paths share one decision.
    _sf_use_tools = (
        (_sf_tools_on or _sf_mcp_allowed or _sf_recall_reopens_loop)
        and _sf_features.get("supports_tools", False)
        # Images stay in the loop only for vision models without a client catalog, so client
        # tools are not swapped for built-ins. Replayed MCP images count too.
        and (not _sf_has_any_image or (bool(_sf_model_info.get("is_vision")) and not payload.tools))
        # A caller's several images and a video clip stay out of the loop, as on main.
        and not images
        and _video_clip is None
        and not _sf_is_gptoss
        and _sf_tool_budget > 0
    )

    if _sf_use_tools:
        from core.inference.tools import set_mcp_listing_context_tokens

        set_mcp_listing_context_tokens(
            _monitor_context_length(),
            payload.thread_id,
            payload.messages,
            payload.tool_choice,
            getattr(payload, "mcp_image", None),
        )
        _sf_tools_to_use = await _select_request_tools(
            payload,
            tools_on = _sf_tools_on,
            mcp_allowed = _sf_mcp_allowed,
            supports_vision = bool(_sf_model_info.get("is_vision")),
            checkpoint_fitted = _sf_fit_overflow is not None,
            ui_events = _ui_events,
        )
        _reject_missing_forced_tool(payload.tool_choice, _sf_tools_to_use)
        # Refuse the loop when nothing survived so built-in calls can't use the empty allow-list.
        if not _sf_tools_to_use:
            _sf_use_tools = False

    if _sf_use_tools and _wants_multiple_choices(payload):
        _raise_unsupported_n("non-GGUF tool chat completions", monitor_id)

    if _sf_use_tools and _response_format_constrains_decoding(payload):
        raise _reject(
            400,
            openai_error_body(
                "response_format is not supported with Unsloth tool execution; "
                "send the request without enable_tools or mcp_enabled to use "
                "guided decoding.",
                status = 400,
                code = "unsupported_parameter",
                param = "response_format",
            ),
        )

    _refuse_unused_mcp_image(
        _mcp_image, _catalog_names(_sf_tools_to_use) if _sf_use_tools else None
    )
    if _sf_use_tools:
        # Derive confirm from permission_mode for CLI-forced loops (matches GGUF).
        _sf_effective_confirm = _permission_mode_confirm(payload)
        # Bypass, or auto with only always-safe tools, never prompts, so no stream is required.
        if _confirm_gate_has_no_channel(payload, _ui_events, _catalog_names(_sf_tools_to_use)):
            raise _reject(
                400,
                openai_error_body(
                    "confirm_tool_calls requires stream=true and the X-Unsloth-Events: 1 "
                    'header for local tool execution; set permission_mode to "off" to '
                    "run tools without confirmation.",
                    status = 400,
                    code = "invalid_request_error",
                    param = "confirm_tool_calls",
                ),
            )
        # After the channel check, which "off" never trips (see the GGUF branch).
        _sf_effective_confirm = _sf_effective_confirm or _off_mode_sandbox_gate(payload, _ui_events)
        _sf_nudge = _build_tool_action_nudge(
            tools = _sf_tools_to_use,
            model_name = model_name,
            full_access = bool(payload.bypass_permissions),
        )

        # RAG nudge, mirroring the GGUF path.
        _sf_nudge = await _apply_rag_nudge(_sf_nudge, _sf_tools_to_use, rag_scope = payload.rag_scope)
        _sf_nudge = _apply_compaction_nudge(
            _sf_nudge,
            _sf_tools_to_use,
            checkpoint_fitted = _sf_fit_overflow is not None,
            payload = payload,
        )

        _sf_system_prompt = _apply_current_date_prompt(
            _user_system_prompt,
            request,
            include_api_key = True,
            template_default = False,
            image = _sf_has_any_image or _video_clip is not None,
            tools = True,
            controls = _date_controls,
        )
        if _sf_nudge:
            if _sf_system_prompt:
                _sf_system_prompt = _sf_system_prompt.rstrip() + "\n\n" + _sf_nudge
            else:
                _sf_system_prompt = _sf_nudge

        _sf_auto_heal_tool_calls = (
            payload.auto_heal_tool_calls if payload.auto_heal_tool_calls is not None else True
        )
        # Active tool names gating the bare-rehearsal strip, matching the loop gate.
        _sf_display_tool_names = _display_tool_name_gate(_sf_tools_to_use)

        # Strip stale tool-call XML from prior assistant turns. The continuation target
        # keeps its exact whitespace (see the GGUF path).
        _sf_continue_target = chat_messages[-1] if _sf_continue and chat_messages else None
        _sf_chat_messages = []
        for _msg in chat_messages:
            if _msg.get("role") == "assistant" and isinstance(_msg.get("content"), str):
                _sf_stripped = _strip_tool_xml_for_display(
                    _msg["content"],
                    auto_heal_tool_calls = _sf_auto_heal_tool_calls,
                    enabled_tool_names = _sf_display_tool_names,
                )
                _sf_chat_messages.append(
                    {
                        **_msg,
                        "content": (
                            _sf_stripped if _msg is _sf_continue_target else _sf_stripped.strip()
                        ),
                    }
                )
            else:
                _sf_chat_messages.append(_msg)

        # Attachment goes last to match its marker; MCP pictures came from earlier turns.
        _sf_loop_images = list(sf_mcp_images)
        # Position read off the conversation: the attachment's turn can precede a tool's pictures.
        _sf_attachment_at: list[int] = []
        if image is not None:
            # Trim BEFORE the attachment's marker exists: the trim drops by marker ordinal
            # against a replay-only payload list.
            trim_mcp_image_turns(
                _sf_chat_messages, sf_mcp_images, limit = _MCP_MAX_TOTAL_MODEL_IMAGES - 1
            )
            # Snapshot after the trim, so "history" names the markers that survived it.
            _sf_prior_markers = mcp_image_marker_parts(_sf_chat_messages)
            # A positional VLM binds the Nth pixel to the Nth marker.
            _sf_chat_messages = mark_mcp_image_turn(
                _sf_chat_messages,
                1,
                ordinal = _user_ordinal_supplying_the_image(payload.messages),
            )
            _sf_loop_images = mcp_pixels_in_marker_order(
                _sf_chat_messages,
                _sf_prior_markers,
                sf_mcp_images,
                _pil_to_png_b64(image),
                placed_at = _sf_attachment_at,
            )

        # Request-scoped usage/timings receptacle (filled at gen_done).
        _sf_stats_holder: dict = {}

        _sf_website_policy = getattr(payload, "_website_policy", None)
        _sf_website_policy_kwargs = (
            {"website_policy": _sf_website_policy} if _sf_website_policy else {}
        )

        def sf_generate_with_tools():
            return backend.generate_chat_completion_with_tools(
                messages = _sf_chat_messages,
                tools = _sf_tools_to_use,
                system_prompt = _sf_system_prompt or "",
                images = _sf_loop_images or None,
                # The caller's own picture is not the loop's to evict.
                caller_image_indexes = tuple(_sf_attachment_at),
                temperature = payload.temperature,
                top_p = payload.top_p,
                top_k = payload.top_k,
                min_p = payload.min_p,
                max_tokens = effective_max_tokens,
                repetition_penalty = payload.repetition_penalty,
                presence_penalty = payload.presence_penalty,
                seed = payload.seed,
                frequency_penalty = payload.frequency_penalty,
                logit_bias = payload.logit_bias,
                stop = normalized_stop,
                cancel_event = cancel_event,
                enable_thinking = payload.enable_thinking,
                reasoning_effort = payload.reasoning_effort,
                preserve_thinking = payload.preserve_thinking,
                continue_final_message = _sf_continue,
                auto_heal_tool_calls = _sf_auto_heal_tool_calls,
                deduplicate_tool_calls = payload.deduplicate_tool_calls is not False,
                nudge_tool_calls = payload.nudge_tool_calls,
                tool_choice = payload.tool_choice,
                disable_parallel_tool_use = payload.parallel_tool_calls is False,
                max_tool_iterations = _sf_tool_budget,
                tool_call_timeout = payload.tool_call_timeout
                if payload.tool_call_timeout is not None
                else 300,
                session_id = payload.session_id,
                thread_id = payload.thread_id,
                rag_scope = payload.rag_scope,
                # Bypass Permissions takes precedence over the confirm gate: never prompt while bypassing.
                confirm_tool_calls = _sf_effective_confirm and not bool(payload.bypass_permissions),
                mcp_image = _mcp_image,
                bypass_permissions = bool(payload.bypass_permissions),
                permission_mode = payload.permission_mode,
                sandbox_level = payload.sandbox_level,
                use_adapter = payload.use_adapter,
                stats_holder = _sf_stats_holder,
                reasoning_prefilled = _sf_reasoning_prefilled,
                context_overflow = _sf_fit_overflow,
                context_policy = _request_context_policy(payload),
                compaction_headroom_ratio = _request_compaction_headroom_ratio(payload),
                compact_context = getattr(payload, "compact_context", None) is True,
                **_sf_website_policy_kwargs,
            )

        _sf_tool_sentinel = object()
        _sf_cancel_keys = (payload.cancel_id, payload.session_id, completion_id)
        _sf_tracker = _TrackedCancel.for_payload(cancel_event, payload, *_sf_cancel_keys)
        _sf_tracker.__enter__()

        async def sf_tool_stream():
            gen = None
            _sf_next_task = None
            disconnect_watcher = asyncio.create_task(
                _await_disconnect_then_cancel(request, cancel_event)
            )
            try:
                from core.inference.llama_keepwarm import mark_current_response_failed

                yield _chat_role_chunk(completion_id, created, model_name)

                gen = sf_generate_with_tools()
                gen_step = ThreadStepper(gen).next
                prev_text = ""
                _sf_display_strip = _StreamingDisplayStrip(
                    auto_heal_tool_calls = _sf_auto_heal_tool_calls,
                    enabled_tool_names = _sf_display_tool_names,
                )
                reasoning_extractor = _new_sf_reasoning_extractor()
                approval_flush_pending = False

                def _sf_flush_reasoning():
                    # Drain the extractor at turn/stream end (mirrors GGUF); only visible text hits the monitor.
                    fr, fv = reasoning_extractor.finish()
                    out = []
                    if fr:
                        # Held-back markers can make this the FIRST output of all.
                        api_monitor.mark_first_token(monitor_id)
                        out.append(_chat_reasoning_chunk(completion_id, created, model_name, fr))
                    if fv:
                        api_monitor.append_reply(monitor_id, fv)
                        out.append(_chat_content_chunk(completion_id, created, model_name, fv))
                    return out

                while True:
                    if cancel_event.is_set():
                        backend.reset_generation_state(cancel_event)
                        mark_current_response_failed()
                        break
                    if await request.is_disconnected():
                        cancel_event.set()
                        backend.reset_generation_state(cancel_event)
                        mark_current_response_failed()
                        api_monitor.finish(monitor_id, "cancelled")
                        return

                    # Keepalive so silent backend segments do not exceed proxy timeouts.
                    _sf_next_task = asyncio.create_task(gen_step(_sf_tool_sentinel))
                    wait_timeout = (
                        TOOL_APPROVAL_FLUSH_DELAY_S
                        if approval_flush_pending
                        else _LOCAL_TOOL_STREAM_STALL_KEEPALIVE_S
                    )
                    while True:
                        _sf_done, _ = await asyncio.wait(
                            {_sf_next_task},
                            timeout = wait_timeout,
                        )
                        if _sf_done:
                            break
                        yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                        approval_flush_pending = False
                        wait_timeout = _LOCAL_TOOL_STREAM_STALL_KEEPALIVE_S
                    event = _sf_next_task.result()
                    approval_flush_pending = False
                    # Done; drop the reference so the finally-block drain no-ops.
                    _sf_next_task = None
                    if event is _sf_tool_sentinel:
                        break
                    if isinstance(event, GenStreamError):
                        backend.reset_generation_state(cancel_event)
                        _msg = _friendly_gen_stream_error(event)
                        api_monitor.fail(monitor_id, _msg)
                        yield _openai_stream_error_sse(
                            {"error": {"message": _msg, "type": "server_error"}}
                        )
                        return
                    if not isinstance(event, dict):
                        raise RuntimeError(
                            f"Invalid safetensors tool event: {type(event).__name__}"
                        )

                    if event["type"] == "heartbeat":
                        # Tool-execution wrapper heartbeat -> SSE comment.
                        yield _OPENAI_TOOL_HEARTBEAT_SSE
                        continue

                    if event["type"] in ("tool_output", "tool_args", "tool_approved"):
                        # Live stdout/stderr, tool-call arguments as the model writes them, or an approval.
                        if _ui_events:
                            yield f"data: {json.dumps(event)}\n\n"
                        elif _drop_keepalive.due():
                            yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                        continue

                    if event["type"] == "status":
                        if not event["text"]:
                            # Iteration boundary: flush reasoning, then a fresh prefilled extractor for the next turn.
                            for _c in _sf_flush_reasoning():
                                yield _c
                            prev_text = ""
                            reasoning_extractor = _new_sf_reasoning_extractor()
                        if _ui_events:
                            status_data = json.dumps(
                                {
                                    "type": "tool_status",
                                    "content": event["text"],
                                }
                            )
                            yield f"data: {status_data}\n\n"
                        elif _drop_keepalive.due():
                            yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                        continue

                    if event["type"] == "skill_load":
                        approval_flush_pending = event.get("status") == "awaiting_approval"
                        if _ui_events:
                            yield f"data: {json.dumps(event)}\n\n"
                        elif _drop_keepalive.due():
                            yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                        continue
                    if event["type"] in ("tool_start", "tool_end"):
                        if event["type"] == "tool_start":
                            # Gated with the card: the stamp is set once.
                            if _ui_events:
                                api_monitor.mark_first_token(monitor_id, decoded = False)
                            # Flush reasoning before tool_start so the thinking block closes ahead of the card.
                            for _c in _sf_flush_reasoning():
                                yield _c
                            prev_text = ""
                            reasoning_extractor = _new_sf_reasoning_extractor()
                            approval_flush_pending = bool(event.get("awaiting_confirmation"))
                        if _ui_events:
                            yield f"data: {json.dumps(event)}\n\n"
                        elif _drop_keepalive.due():
                            yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                        continue

                    if event["type"] == "context_truncated":
                        yield _context_truncated_sse_chunk(
                            completion_id,
                            model_name,
                            {key: value for key, value in event.items() if key != "type"},
                        )
                        continue

                    # Diff cumulative cleaned text against last snapshot.
                    raw_cumulative = event.get("text", "")
                    clean_cumulative = _sf_display_strip.strip(raw_cumulative)
                    new_text = clean_cumulative[len(prev_text) :]
                    prev_text = clean_cumulative
                    if not new_text:
                        continue
                    # Split reasoning vs visible; only visible reaches the monitor.
                    reasoning_delta, visible_delta = reasoning_extractor.feed(new_text)
                    if reasoning_delta:
                        api_monitor.mark_first_token(monitor_id)
                        yield _chat_reasoning_chunk(
                            completion_id, created, model_name, reasoning_delta
                        )
                    if visible_delta:
                        api_monitor.append_reply(monitor_id, visible_delta)
                        yield _chat_content_chunk(completion_id, created, model_name, visible_delta)

                for _c in _sf_flush_reasoning():
                    yield _c
                # Request-scoped holder so concurrent streams cannot read each other's stats.
                _stats = _sf_stats_holder.get("stats")
                # The last turn's budget decides: an earlier capped turn does not truncate this answer.
                _sf_finish = "stop" if cancel_event.is_set() else _stats_finish_reason(_stats)
                yield _chat_final_chunk(completion_id, created, model_name, _sf_finish)
                # Outside the stats block: a run with unknown token count reports no stats.
                api_monitor.set_perf(monitor_id, stop_reason = _sf_finish)
                if _stats:
                    usage_line = _openai_stream_usage_chunk(
                        payload,
                        completion_id,
                        created,
                        model_name,
                        _stats.get("usage"),
                        _stats.get("timings"),
                    )
                    if usage_line is not None:
                        yield usage_line
                    _monitor_usage(
                        monitor_id,
                        _stats.get("usage"),
                        timings = _stats.get("timings"),
                    )
                if cancel_event.is_set():
                    mark_current_response_failed()
                api_monitor.finish(
                    monitor_id, "cancelled" if cancel_event.is_set() else "completed"
                )
                yield "data: [DONE]\n\n"

            except asyncio.CancelledError:
                cancel_event.set()
                backend.reset_generation_state(cancel_event)
                api_monitor.finish(monitor_id, "cancelled")
                raise
            except GenStreamErrorRaised as exc:
                backend.reset_generation_state(cancel_event)
                _msg = _friendly_gen_stream_error(exc)
                api_monitor.fail(monitor_id, _msg)
                yield _openai_stream_error_sse({"error": {"message": _msg, "type": "server_error"}})
            except context_refusal.ContextBudgetExceeded as e:
                backend.reset_generation_state(cancel_event)
                api_monitor.fail(monitor_id, _friendly_error(e))
                yield _openai_stream_error_sse(_openai_stream_error_chunk(e))
            except Exception:
                backend.reset_generation_state(cancel_event)
                # Generic message; trace stays in the log (CWE-209).
                logger.exception("safetensors tool stream error")
                api_monitor.fail(monitor_id, "An internal error occurred.")
                error_chunk = {
                    "error": {
                        "message": "An internal error occurred.",
                        "type": "server_error",
                    },
                }
                yield _openai_stream_error_sse(error_chunk)
            finally:
                await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
                # Closing mid-next(gen) raises 'generator already executing' and skips cleanup.
                await _drain_pending_worker(_sf_next_task, cancel_event)
                if gen is not None:
                    try:
                        # Close off the event loop so a disconnect can't stall it.
                        await asyncio.to_thread(gen.close)
                    except (RuntimeError, ValueError):
                        pass
                _sf_tracker.__exit__(None, None, None)

        if payload.stream:
            return _sse_streaming_response(
                sf_tool_stream(),
                unstarted_cleanup = _tracked_cancel_unstarted_cleanup(_sf_tracker),
                monitor_id = monitor_id,
            )

        # Non-streaming JSON: drain the loop, build one ChatCompletion.
        try:
            _sf_context_truncation = None

            def _drain_to_text():
                nonlocal _sf_context_truncation
                full_text = ""
                # Only the resumed turn skips the generation prompt; track the mode of the kept turn.
                continued = _sf_continue
                prefilled = _sf_resumes_thought if continued else _sf_reasoning_prefilled
                gen = sf_generate_with_tools()
                raw_text = None
                for event in gen:
                    if cancel_event.is_set():
                        break
                    if isinstance(event, GenStreamError):
                        raise HTTPException(
                            status_code = 500,
                            detail = _friendly_gen_stream_error(event),
                        )
                    if not isinstance(event, dict):
                        raise RuntimeError(
                            f"Invalid safetensors tool event: {type(event).__name__}"
                        )
                    _event_type = event.get("type")
                    if _event_type == "content":
                        raw_text = event.get("text", "")
                        prefilled = _sf_resumes_thought if continued else _sf_reasoning_prefilled
                    elif _event_type == "tool_start" or (
                        _event_type == "status" and not event.get("text")
                    ):
                        continued = False
                    elif _event_type == "context_truncated":
                        _sf_context_truncation = _accumulate_context_truncation(
                            _sf_context_truncation, event
                        )
                if raw_text is not None:
                    full_text = _strip_tool_xml_for_display(
                        raw_text,
                        auto_heal_tool_calls = _sf_auto_heal_tool_calls,
                        enabled_tool_names = _sf_display_tool_names,
                    )
                return full_text, prefilled

            content_text, _sf_drain_prefilled = await asyncio.to_thread(_drain_to_text)
            # Split prefilled <think> out of the visible answer (GGUF parity); the monitor gets visible text only.
            _reasoning_text, _visible_text = _extract_responses_reasoning(
                content_text,
                parse_think_markers = _sf_parse_think,
                reasoning_prefilled = _sf_drain_prefilled,
            )
            api_monitor.set_reply(monitor_id, _visible_text)
            _stats = _sf_stats_holder.get("stats")
            # Outside the stats block: a run with unknown token count reports no stats.
            _sf_json_finish = "stop" if cancel_event.is_set() else _stats_finish_reason(_stats)
            api_monitor.set_perf(monitor_id, stop_reason = _sf_json_finish)
            if _stats:
                _monitor_usage(
                    monitor_id,
                    _stats.get("usage"),
                    timings = _stats.get("timings"),
                )
            if cancel_event.is_set():
                from core.inference.llama_keepwarm import mark_current_response_failed
                mark_current_response_failed()
            api_monitor.finish(monitor_id, "cancelled" if cancel_event.is_set() else "completed")
            _sf_msg_kwargs = {"content": _visible_text}
            if _reasoning_text:
                _sf_msg_kwargs["reasoning_content"] = _reasoning_text
            _sf_usage = (_stats or {}).get("usage") or {}
            response = ChatCompletion(
                id = completion_id,
                created = created,
                model = model_name,
                choices = [
                    CompletionChoice(
                        message = CompletionMessage(**_sf_msg_kwargs),
                        finish_reason = _sf_json_finish,
                    )
                ],
                usage = CompletionUsage(
                    prompt_tokens = _sf_usage.get("prompt_tokens") or 0,
                    completion_tokens = _sf_usage.get("completion_tokens") or 0,
                    total_tokens = (
                        _sf_usage.get("total_tokens")
                        or (_sf_usage.get("prompt_tokens") or 0)
                        + (_sf_usage.get("completion_tokens") or 0)
                    ),
                    prompt_tokens_details = _prompt_tokens_details(
                        _sf_usage.get("prompt_tokens_details")
                    ),
                ),
            )
            return _model_json_response_with_context_truncation(response, _sf_context_truncation)
        except asyncio.CancelledError:
            cancel_event.set()
            backend.reset_generation_state(cancel_event)
            api_monitor.finish(monitor_id, "cancelled")
            raise
        except GenStreamErrorRaised as exc:
            backend.reset_generation_state(cancel_event)
            _msg = _friendly_gen_stream_error(exc)
            api_monitor.fail(monitor_id, _msg)
            raise HTTPException(status_code = 500, detail = _msg)
        except HTTPException as exc:
            backend.reset_generation_state(cancel_event)
            api_monitor.fail(monitor_id, str(exc.detail))
            raise
        except context_refusal.ContextBudgetExceeded as e:
            backend.reset_generation_state(cancel_event)
            api_monitor.fail(monitor_id, _friendly_error(e))
            raise _context_budget_http_error(e)
        except Exception:
            backend.reset_generation_state(cancel_event)
            # CWE-209: generic detail; full trace in log.
            logger.exception("safetensors tool completion error")
            api_monitor.fail(monitor_id, "An internal error occurred.")
            raise HTTPException(
                status_code = 500,
                detail = "An internal error occurred.",
            )
        finally:
            _sf_tracker.__exit__(None, None, None)

    # Attachment and replay reach the backend as one sequence; trim replay to reserve its slot.
    if image is not None and sf_mcp_images:
        trim_mcp_image_turns(chat_messages, sf_mcp_images, limit = _MCP_MAX_TOTAL_MODEL_IMAGES - 1)

    # Shared generation kwargs
    gen_kwargs = dict(
        messages = chat_messages,
        system_prompt = system_prompt,
        image = image,
        images = sf_mcp_images or images or None,
        # The extractor takes the newest user image anywhere, so find the supplying turn.
        image_ordinal = _user_ordinal_supplying_the_image(payload.messages),
        temperature = payload.temperature,
        top_p = payload.top_p,
        top_k = payload.top_k,
        min_p = payload.min_p,
        max_new_tokens = effective_max_tokens,
        repetition_penalty = payload.repetition_penalty,
        presence_penalty = payload.presence_penalty,
        seed = payload.seed,
        frequency_penalty = payload.frequency_penalty,
        logit_bias = payload.logit_bias,
        stop = normalized_stop,
        response_format = _extract_response_format(payload),
    )
    if _video_clip is not None:
        gen_kwargs["video"] = _video_clip
    # The worker/template wrapper peels off kwargs the template doesn't accept.
    if payload.enable_thinking is not None:
        gen_kwargs["enable_thinking"] = payload.enable_thinking
    if payload.reasoning_effort is not None:
        gen_kwargs["reasoning_effort"] = payload.reasoning_effort
    if payload.preserve_thinking is not None:
        gen_kwargs["preserve_thinking"] = payload.preserve_thinking
    if _sf_continue:
        gen_kwargs["continue_final_message"] = True

    # Client-tool passthrough heals text-form calls; a catalog the model cannot render is refused.
    _sf_has_tool_msgs = any(m.role == "tool" or m.tool_calls for m in payload.messages)
    # Classified against the processor body so the loop and generation agree on tool support.
    _sf_supports_tools = _sf_features.get("supports_tools", False)
    if _has_active_tool_catalog and (_sf_is_gptoss or not _sf_supports_tools):
        raise _reject(
            400,
            openai_error_body(
                (
                    "Client-supplied tools are not supported for gpt-oss on this backend; "
                    "load a GGUF build of the model."
                    if _sf_is_gptoss
                    else "Client-supplied tools require a chat template with tool-call support; "
                    "the current model/template does not advertise tools."
                ),
                status = 400,
                code = "unsupported_parameter",
                param = "tools",
            ),
        )
    # Gate on _sf_use_tools, not mcp_enabled: an empty MCP registry must not drop client tools.
    _sf_client_tools = (
        # Read the resolved value: recomputing would undo the launcher-default withdrawal above.
        (not _sf_tools_on or ((_sf_has_any_image or _video_clip is not None) and not _sf_use_tools))
        and not _sf_use_tools
        and not _sf_is_gptoss
        and _sf_supports_tools
        and ((payload.tools and len(payload.tools) > 0) or _sf_has_tool_msgs)
    )
    _sf_response_format = _response_format_beside_tools(
        payload, payload.tools if _sf_client_tools else None
    )
    gen_kwargs["response_format"] = _sf_response_format
    _sf_single_block = _sf_single_block and _sf_response_format is not None
    # apply_chat_template sanitizes the catalog it renders, so a tool dropped for unsafe
    # markup never reached the prompt. Gating the healer on the caller's list instead would
    # promote a dropped tool with a clean NAME out of text-form output, handing the client a
    # call for a tool the model was never shown (#7066).
    from core.inference.chat_template_helpers import (
        chat_render_target as _sf_chat_render_target,
        markup_for_tokenizer as _sf_markup_for,
        neutralize_tool_descriptions as _sf_neutralize_tools,
        renderable_tool_catalog_for_targets as _sf_renderable_tools,
    )

    _sf_markup = _sf_markup_for(_sf_model_info.get("tokenizer"))

    # MLX renders via the processor, transformers via the tokenizer: intersect both catalogs.
    _sf_processor = _sf_model_info.get("processor")
    _sf_tokenizer = _sf_model_info.get("tokenizer")
    _sf_mlx_target = _sf_chat_render_target(_sf_processor, _sf_tokenizer)
    _sf_hf_target = getattr(_sf_mlx_target, "tokenizer", _sf_mlx_target)
    _sf_chat_targets = (
        (_sf_mlx_target,) if _sf_hf_target is _sf_mlx_target else (_sf_mlx_target, _sf_hf_target)
    )
    # Qwen2.5-VL processor body omits tools but its tokenizer body has them, so healing from the tokenizer promotes calls the render never carried
    _sf_healing_tools = (
        # Must be safe under every selectable template: a native fallback can drop a tool the active one kept. Threaded: native template load blocks
        await asyncio.to_thread(
            _sf_renderable_tools,
            payload.tools,
            _sf_chat_targets,
            _sf_model_info,
            active_model_name = backend.active_model_name,
            template = _sf_image_tpl,
            template_is_processor = _sf_image_tpl is not None,
        )
        if _sf_client_tools
        else None
    )
    _sf_heal = (
        heal_gate(
            payload.auto_heal_tool_calls,
            _sf_healing_tools,
            payload.tool_choice,
            response_format = _sf_response_format,
        )
        if _sf_client_tools
        else None
    )
    if _sf_client_tools:
        # Re-derive from messages to keep tool history; fold system and developer into one system message; tool_choice none drops tools or markup leaks as prose
        _sf_tc = payload.tool_choice
        _sf_forced = None
        if isinstance(_sf_tc, dict) and isinstance(_sf_tc.get("function"), dict):
            _sf_forced = _sf_tc["function"].get("name")
        if _sf_tc == "none":
            _sf_client_catalog = None
        elif isinstance(_sf_forced, str):
            _sf_client_catalog = [
                t
                for t in payload.tools or []
                if isinstance(t, dict)
                and isinstance(t.get("function"), dict)
                and t["function"].get("name") == _sf_forced
            ] or None
        else:
            _sf_client_catalog = payload.tools
        _sf_client_system_prompt = _apply_current_date_prompt(
            _user_system_prompt,
            request,
            image = _sf_has_any_image or _video_clip is not None,
            tools = bool(_sf_client_catalog),
            controls = _date_controls,
        )
        if served_images:
            # One pass over the conversation this renders, so markers and payloads stay in step.
            _sf_rebuilt, _sf_payloads = _conversation_with_image_markers(
                _openai_messages_for_passthrough(
                    payload, normalize_images = False, promote_mcp_images = False
                )
            )
            _sf_rebuilt, _sf_rebuilt_images = await _promote_local_mcp_images_async(
                _sf_rebuilt,
                vision = _sf_renders_image,
                decode_cache = _sf_mcp_decode_cache,
                caller_images = _sf_payloads,
            )
            # The same pictures the extraction already decoded, unless the rebuild dropped one.
            gen_kwargs["images"] = await _decode_request_images(
                backend, _sf_rebuilt_images, dict(zip(served_images, images)), reject = _reject
            )
            gen_kwargs["messages"] = _set_or_prepend_system_message(
                _structured_tool_history_for_local_template(_sf_rebuilt), _sf_client_system_prompt
            )
        else:
            # Promote after flattening, which drops images; keep one marker per batch in place or merged forward: a detached one breaks image limits and turn alternation
            _sf_rebuilt, _sf_rebuilt_images = await _promote_local_mcp_images_async(
                _structured_tool_history_for_local_template(
                    _flatten_content_parts_for_local_template(
                        _openai_messages_for_passthrough(
                            payload, normalize_images = False, promote_mcp_images = False
                        )
                    )
                ),
                vision = _sf_renders_image,
                decode_cache = _sf_mcp_decode_cache,
            )
            if image is not None and _sf_rebuilt_images:
                # The attachment and the replay reach the backend as one sequence, so reserve its slot here as the server-tool path does
                trim_mcp_image_turns(
                    _sf_rebuilt, _sf_rebuilt_images, limit = _MCP_MAX_TOTAL_MODEL_IMAGES - 1
                )
            gen_kwargs["messages"] = _set_or_prepend_system_message(
                _sf_rebuilt, _sf_client_system_prompt
            )
            gen_kwargs["images"] = _sf_rebuilt_images or None
        # Mark the image owner turn so newest-user scans cannot move an older picture; no part lists for text-template renders; not when pictures were replayed
        if _sf_renders_image and not _sf_rebuilt_images and not served_images:
            _sf_image_ordinal = _user_ordinal_supplying_the_image(payload.messages)
            if _sf_image_ordinal is not None:
                gen_kwargs["messages"] = _mark_image_owner_turn(
                    gen_kwargs["messages"], _sf_image_ordinal
                )
        gen_kwargs["system_prompt"] = ""
        gen_kwargs["tools"] = _sf_client_catalog
    elif _sf_renders_image and not sf_mcp_images:
        # Only when nothing was replayed: a marker added here is counted as replayed history and binds the pixels to the wrong turns
        _sf_image_ordinal = _user_ordinal_supplying_the_image(payload.messages)
        if _sf_image_ordinal is not None:
            gen_kwargs["messages"] = _mark_image_owner_turn(
                gen_kwargs["messages"], _sf_image_ordinal
            )

    # Re-resolve with the exact rendered schemas; the tokenizer body would undo the above.
    _, _sf_parse_think, _sf_reasoning_prefilled = _sf_response_protocol(
        gen_kwargs.get("tools"),
        template = _sf_image_tpl,
        prefer_tool_use = _sf_image_tpl is None,
    )
    if gen_kwargs.get("response_format") is not None:
        gen_kwargs["reasoning_is_extracted"] = bool(_sf_parse_think)

    # Request-scoped usage/timings receptacle (filled at gen_done).
    stats_holder: dict = {}
    _sf_context_truncation_holder: dict = {"value": None}
    # Diffusion canvas frames only for a streaming, single-choice reply to a client rendering Studio events.
    _sf_ui_events = _ui_stream_events_enabled(request)
    _sf_frame_kwargs = (
        {"diffusion_frames": True}
        if payload.stream
        and _sf_ui_events
        and (payload.n or 1) == 1
        and _accepts_keyword(backend.generate_chat_response, "diffusion_frames")
        else {}
    )

    if payload.use_adapter is not None:

        def _sf_raw_generate(kw):
            return backend.generate_with_adapter_control(
                use_adapter = payload.use_adapter,
                cancel_event = cancel_event,
                stats_holder = stats_holder,
                **_sf_frame_kwargs,
                **kw,
            )
    else:

        def _sf_raw_generate(kw):
            return backend.generate_chat_response(
                cancel_event = cancel_event,
                stats_holder = stats_holder,
                **_sf_frame_kwargs,
                **kw,
            )

    # A plain reset needs the next turn to reopen the loop, which renders the tool branch.
    # A vision model renders text turns through its processor body too (Qwen2.5-VL drops tools, #7066).
    _sf_recall_tpl = (_sf_model_info.get("chat_template_info") or {}).get("processor_template")
    _sf_recall_reachable = (
        _sf_fit_overflow is not None
        and _sf_recall_loop_usable
        and not _sf_is_gptoss
        and bool(
            (
                _sf_rendered_features(backend, _sf_model_info, ({},))[0]
                if _sf_recall_tpl is None
                else _detect_safetensors_features(
                    backend, _sf_recall_tpl, tools = ({},), prefer_tool_use = False
                )
            ).get("supports_tools")
        )
    )

    _sf_fit_cache: dict = {}

    def _sf_fit_request():
        # On the generation thread, once: every choice and retry starts from this prompt.
        if "kwargs" in _sf_fit_cache:
            return _sf_fit_cache["kwargs"], ()
        fitted_kwargs, events = gen_kwargs, ()
        # The count cannot price pictures or video, so those prompts are left alone.
        if _sf_fit_overflow and all(
            gen_kwargs.get(key) is None for key in ("image", "images", "video")
        ):
            fitted = backend.compact_chat_context(
                gen_kwargs.get("messages") or [],
                system_prompt = gen_kwargs.get("system_prompt") or "",
                tools = gen_kwargs.get("tools"),
                context_overflow = _sf_fit_overflow,
                context_policy = _request_context_policy(payload),
                compaction_headroom_ratio = _request_compaction_headroom_ratio(payload),
                force_reset = getattr(payload, "compact_context", None) is True,
                max_tokens = effective_max_tokens,
                thread_id = payload.thread_id,
                cancel_event = cancel_event,
                enable_thinking = gen_kwargs.get("enable_thinking"),
                reasoning_effort = gen_kwargs.get("reasoning_effort"),
                preserve_thinking = gen_kwargs.get("preserve_thinking"),
                continue_final_message = bool(gen_kwargs.get("continue_final_message", False)),
                recall_reachable = _sf_recall_reachable,
            )
            fitted_kwargs = {
                **gen_kwargs,
                "messages": fitted["messages"],
                "system_prompt": fitted["system_prompt"],
            }
            events = fitted.get("events") or ()
        _sf_fit_cache["kwargs"] = fitted_kwargs
        return fitted_kwargs, events

    def generate(messages_override = None, choice_index = 0):
        def _run():
            generation_kwargs, events = _sf_fit_request()
            yield from events
            if messages_override is not None:
                generation_kwargs = {**generation_kwargs, "messages": messages_override}
            if choice_index:
                generation_kwargs = {
                    **generation_kwargs,
                    "seed": _choice_seed(payload.seed, choice_index),
                }
            yield from _sf_raw_generate(generation_kwargs)

        return _run()

    # ── Streaming response ────────────────────────────────────────
    if payload.stream:
        _cancel_keys = (payload.cancel_id, payload.session_id, completion_id)
        _tracker = _TrackedCancel.for_payload(cancel_event, payload, *_cancel_keys)
        _tracker.__enter__()

        async def stream_chunks():
            gen = None
            _next_task = None
            disconnect_watcher = asyncio.create_task(
                _await_disconnect_then_cancel(request, cancel_event)
            )
            try:
                from core.inference.llama_keepwarm import mark_current_response_failed

                yield _chat_role_chunk(completion_id, created, model_name)

                # Text-form tool calls are healed on the fly; with healing off (None) the stream is relayed verbatim.
                healer = StreamToolCallHealer(_sf_heal, _sf_healing_tools) if _sf_heal else None
                heal_state = {"idx": 0}

                prev_text = ""
                # Split prefilled <think> into reasoning_content deltas (GGUF parity); single turn, serves MLX.
                reasoning_extractor = _new_sf_reasoning_extractor()
                # Worker thread: a blocking _gen_lock in compare mode would otherwise freeze the loop.
                _DONE = object()  # sentinel for generator exhaustion
                gen = generate()
                gen_step = ThreadStepper(gen).next
                while True:
                    if cancel_event.is_set():
                        backend.reset_generation_state(cancel_event)
                        mark_current_response_failed()
                        break
                    # next(gen, _DONE) avoids StopIteration, which can't cross asyncio futures.
                    _next_task = asyncio.create_task(gen_step(_DONE))
                    while True:
                        _done_tasks, _ = await asyncio.wait(
                            {_next_task},
                            timeout = _LOCAL_TOOL_STREAM_STALL_KEEPALIVE_S,
                        )
                        if _done_tasks:
                            break
                        yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                    cumulative = _next_task.result()
                    # Done; drop the reference so the finally-block drain no-ops.
                    _next_task = None
                    if cumulative is _DONE:
                        break
                    if isinstance(cumulative, dict):
                        if cumulative.get("type") == "context_truncated":
                            yield _context_truncated_sse_chunk(
                                completion_id,
                                model_name,
                                {key: value for key, value in cumulative.items() if key != "type"},
                            )
                        elif cumulative.get("type") == "diffusion_frame":
                            # As on the GGUF path: never in the transcript.
                            if _sf_ui_events:
                                yield f"data: {json.dumps(cumulative)}\n\n"
                            elif _drop_keepalive.due():
                                yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                        continue
                    if isinstance(cumulative, GenStreamError):
                        backend.reset_generation_state(cancel_event)
                        _msg = _friendly_gen_stream_error(cumulative)
                        api_monitor.fail(monitor_id, _msg)
                        _refused = _refused_parameter(cumulative)
                        yield _openai_stream_error_sse(
                            openai_error_body(
                                _msg,
                                status = 400,
                                code = "unsupported_parameter",
                                param = _refused,
                            )
                            if _refused
                            else {"error": {"message": _msg, "type": "server_error"}}
                        )
                        return
                    if await request.is_disconnected():
                        cancel_event.set()
                        backend.reset_generation_state(cancel_event)
                        mark_current_response_failed()
                        api_monitor.finish(monitor_id, "cancelled")
                        return
                    new_text = cumulative[len(prev_text) :]
                    prev_text = cumulative
                    if not new_text:
                        continue
                    # Split reasoning first so tool markup inside a reasoning block is never healed.
                    reasoning_delta, visible_delta = reasoning_extractor.feed(new_text)
                    if reasoning_delta:
                        api_monitor.mark_first_token(monitor_id)
                        yield _chat_reasoning_chunk(
                            completion_id, created, model_name, reasoning_delta
                        )
                    if visible_delta:
                        if healer is None:
                            # With healing on, _sf_heal_events_to_sse records the reply instead.
                            api_monitor.append_reply(monitor_id, visible_delta)
                            yield _chat_content_chunk(
                                completion_id, created, model_name, visible_delta
                            )
                        else:
                            for line in _sf_heal_events_to_sse(
                                healer.feed(visible_delta),
                                completion_id,
                                created,
                                model_name,
                                heal_state,
                                payload.parallel_tool_calls,
                                monitor_id,
                            ):
                                yield line

                final_reasoning, final_visible = reasoning_extractor.finish()
                if final_reasoning:
                    # Held-back markers can make this the FIRST output of all.
                    api_monitor.mark_first_token(monitor_id)
                    yield _chat_reasoning_chunk(completion_id, created, model_name, final_reasoning)
                if final_visible:
                    if healer is None:
                        api_monitor.append_reply(monitor_id, final_visible)
                        yield _chat_content_chunk(completion_id, created, model_name, final_visible)
                    else:
                        for line in _sf_heal_events_to_sse(
                            healer.feed(final_visible),
                            completion_id,
                            created,
                            model_name,
                            heal_state,
                            payload.parallel_tool_calls,
                            monitor_id,
                        ):
                            yield line

                # A cancelled stream must not heal incomplete markup into a tool the user cancelled.
                _cancelled = cancel_event.is_set()
                if healer is not None and not _cancelled:
                    for line in _sf_heal_events_to_sse(
                        healer.finalize(),
                        completion_id,
                        created,
                        model_name,
                        heal_state,
                        payload.parallel_tool_calls,
                        monitor_id,
                    ):
                        yield line

                # Request-scoped holder so concurrent streams cannot read each other's stats.
                _stats = stats_holder.get("stats")
                # A healed tool call wins; a cancelled turn is never 'length'.
                _finish = (
                    "tool_calls"
                    if (healer is not None and not _cancelled and healer.healed)
                    else (
                        "stop"
                        if _cancelled
                        else _safetensors_finish_reason(
                            _stats,
                            payload,
                            is_mlx = bool(_sf_model_info.get("is_mlx", False)),
                            durable_run = not cancel_on_disconnect,
                        )
                    )
                )
                yield _chat_final_chunk(completion_id, created, model_name, _finish)
                # Outside the stats block: a run with unknown token count reports no stats.
                api_monitor.set_perf(monitor_id, stop_reason = _finish)
                if _stats:
                    usage_line = _openai_stream_usage_chunk(
                        payload,
                        completion_id,
                        created,
                        model_name,
                        _stats.get("usage"),
                        _stats.get("timings"),
                    )
                    if usage_line is not None:
                        yield usage_line
                    _monitor_usage(
                        monitor_id,
                        _stats.get("usage"),
                        timings = _stats.get("timings"),
                    )
                if cancel_event.is_set():
                    mark_current_response_failed()
                api_monitor.finish(
                    monitor_id, "cancelled" if cancel_event.is_set() else "completed"
                )
                yield "data: [DONE]\n\n"

            except asyncio.CancelledError:
                cancel_event.set()
                backend.reset_generation_state(cancel_event)
                api_monitor.finish(monitor_id, "cancelled")
                raise
            except GenStreamErrorRaised as exc:
                # Honor the public flag so operational errors surface their real message (compare-mode adapters).
                backend.reset_generation_state(cancel_event)
                _msg = _friendly_gen_stream_error(exc)
                api_monitor.fail(monitor_id, _msg)
                _refused = _refused_parameter(exc)
                yield _openai_stream_error_sse(
                    openai_error_body(
                        _msg, status = 400, code = "unsupported_parameter", param = _refused
                    )
                    if _refused
                    else {"error": {"message": _msg, "type": "server_error"}}
                )
            except context_refusal.ContextBudgetExceeded as e:
                backend.reset_generation_state(cancel_event)
                api_monitor.fail(monitor_id, _friendly_error(e))
                yield _openai_stream_error_sse(_openai_stream_error_chunk(e))
            except Exception as e:
                backend.reset_generation_state(cancel_event)
                logger.error(f"Error during OpenAI streaming: {e}", exc_info = True)
                _msg = _friendly_error(e)
                api_monitor.fail(monitor_id, _msg)
                from core.inference.engine_transport import EngineHTTPError

                error_chunk = (
                    _openai_stream_error_chunk(e)
                    if isinstance(e, EngineHTTPError)
                    else {"error": {"message": _msg, "type": "server_error"}}
                )
                yield _openai_stream_error_sse(error_chunk)
            finally:
                await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
                # Drain the next(gen) worker before closing: closing mid-next raises generator already executing and skips the cleanup finally
                await _drain_pending_worker(_next_task, cancel_event)
                if gen is not None:
                    try:
                        # Close off the event loop so a disconnect can't stall it.
                        await asyncio.to_thread(gen.close)
                    except (RuntimeError, ValueError):
                        pass
                _tracker.__exit__(None, None, None)

        return _sse_streaming_response(
            stream_chunks(),
            unstarted_cleanup = _tracked_cancel_unstarted_cleanup(_tracker),
            monitor_id = monitor_id,
        )

    # ── Non-streaming response ────────────────────────────────────
    else:
        # Register so a swap returns 409 instead of cancelling (/unload runs no idle drain).
        _cancel_keys = (payload.cancel_id, payload.session_id, completion_id)
        _tracker = _TrackedCancel.for_payload(cancel_event, payload, *_cancel_keys)
        _tracker.__enter__()
        try:
            _n = payload.n or 1
            _choices = []
            _monitor_replies = []
            _prompt_tokens = 0
            _sum_completion = 0
            _prompt_details = None
            _last_stats = None

            def _note_fit(event):
                if event.get("type") == "context_truncated":
                    _sf_context_truncation_holder["value"] = _accumulate_context_truncation(
                        None, event
                    )

            def _drain_generate(messages_override = None, choice_index = 0):
                final = ""
                for token in generate(messages_override, choice_index = choice_index):
                    if isinstance(token, dict):
                        _note_fit(token)
                        continue
                    if isinstance(token, GenStreamError):
                        return token
                    final = token
                return final

            _produced: dict = {}

            async def _produce_choices(_indices):
                """These choices' first replies, asked for in one command."""
                rows = [
                    {} if idx == 0 else {"seed": _choice_seed(payload.seed, idx)}
                    for idx in _indices
                ]
                batch_stats: dict = {}
                texts = [""] * len(rows)
                _finished = set()

                def _drain_batch():
                    fitted_kwargs, fit_events = _sf_fit_request()
                    for event in fit_events:
                        _note_fit(event)
                    for event in backend.generate_chat_batch(
                        rows = rows,
                        cancel_event = cancel_event,
                        stats_holder = batch_stats,
                        **fitted_kwargs,
                    ):
                        if isinstance(event, GenStreamError):
                            return event
                        _row, _text = event
                        if _text is None:
                            _finished.add(_row)
                        else:
                            texts[_row] = _text
                    return None

                failed = await _run_blocking_generation(
                    _drain_batch,
                    cancel_event,
                    name = "openai-chat-nonstream-batch",
                )
                _reported = batch_stats.get("stats") or []

                def _keep(_row, idx):
                    _stats = _reported[_row] if _row < len(_reported) else None
                    if texts[_row] or _stats is not None:
                        _produced[idx] = (texts[_row], _stats)

                if isinstance(failed, GenStreamError):
                    backend.reset_generation_state(cancel_event)
                    logger.warning(
                        "Falling back to one command per choice: %s",
                        _friendly_gen_stream_error(failed),
                    )
                    for _row, idx in enumerate(_indices):
                        if _row in _finished:
                            _keep(_row, idx)
                    return False
                for _row, idx in enumerate(_indices):
                    _keep(_row, idx)
                return any(idx in _produced for idx in _indices)

            async def _one_choice(choice_index):
                """Each choice gets its own seed and stats, matching how the llama-server path
                drains its own n."""
                # Cleared per choice so a cancelled choice does not inherit the previous token count.
                stats_holder.pop("stats", None)
                if choice_index in _produced:
                    full_text, stats_holder["stats"] = _produced[choice_index]
                else:
                    full_text = await _run_blocking_generation(
                        lambda: _drain_generate(choice_index = choice_index),
                        cancel_event,
                        name = "openai-chat-nonstream",
                    )
                if isinstance(full_text, GenStreamError):
                    backend.reset_generation_state(cancel_event)
                    _msg = _friendly_gen_stream_error(full_text)
                    api_monitor.fail(monitor_id, _msg)
                    _refused = _refused_parameter(full_text)
                    if _refused:
                        raise _reject(
                            400,
                            openai_error_body(
                                _msg,
                                status = 400,
                                code = "unsupported_parameter",
                                param = _refused,
                            ),
                        )
                    raise HTTPException(status_code = 500, detail = _msg)

                # Heal only visible text so tool markup inside reasoning is never promoted.
                _reasoning_text, _visible_text = _extract_responses_reasoning(
                    full_text,
                    parse_think_markers = _sf_parse_think,
                    reasoning_prefilled = (
                        _sf_resumes_thought if _sf_continue else _sf_reasoning_prefilled
                    ),
                    single_block = _sf_single_block,
                )
                # Promotes text-form calls; an opt-in single nudge retry handles unparseable tool markup.
                _msg = {"role": "assistant", "content": _visible_text}
                if _reasoning_text:
                    _msg["reasoning_content"] = _reasoning_text
                # A Stop aimed at another choice must not rewrite this finished choice's reason.
                _finish = (
                    "stop"
                    if cancel_event.is_set() and choice_index not in _produced
                    else _stats_finish_reason(stats_holder.get("stats"))
                )
                if _sf_heal:
                    if heal_openai_message(_msg, _sf_heal, _sf_healing_tools):
                        _finish = "tool_calls"
                    elif nudge_enabled(
                        payload.nudge_tool_calls,
                        response_format = _sf_response_format,
                    ):
                        _data = {
                            "choices": [
                                {"message": {"role": "assistant", "content": _visible_text}}
                            ]
                        }
                        if nudge_should_retry(_data, _sf_heal, _sf_healing_tools):
                            # A failed retry must not 500; keep the first response. Popped, not read, so a
                            # retry that raises before publishing cannot double the completion count.
                            _first_stats = stats_holder.pop("stats", None)
                            try:
                                # Mark the owning turn before the correction is appended,
                                # or the reverse scan attaches the picture to it (#10092).
                                # The fitted prompt: the retry extends it and is not refitted.
                                _nudge_base = _sf_fit_request()[0]["messages"]
                                if _sf_renders_image or _video_clip is not None:
                                    from core.inference.chat_template_helpers import (
                                        messages_with_attached_image as _nudge_attach,
                                    )
                                    _nudge_base = _nudge_attach(
                                        _nudge_base,
                                        image = _sf_renders_image,
                                        video = _video_clip is not None,
                                    )
                                retry_messages = [
                                    *_nudge_base,
                                    *nudge_messages(_data, _sf_heal),
                                ]
                                retry_text = await _run_blocking_generation(
                                    lambda: _drain_generate(
                                        retry_messages, choice_index = choice_index
                                    ),
                                    cancel_event,
                                    name = "openai-chat-nudge-nonstream",
                                )
                                # Re-split reasoning on retry so visible text heals into a call; a nudge is not a continuation.
                                _retry_reasoning, _retry_visible = _extract_responses_reasoning(
                                    retry_text,
                                    parse_think_markers = _sf_parse_think,
                                    reasoning_prefilled = _sf_reasoning_prefilled,
                                )
                                retry_msg = {"role": "assistant", "content": _retry_visible}
                                if _retry_reasoning:
                                    retry_msg["reasoning_content"] = _retry_reasoning
                                # The winning attempt's prompt is reported; completions of both are summed.
                                if heal_openai_message(retry_msg, _sf_heal, _sf_healing_tools):
                                    _visible_text, _msg, _finish = (
                                        _retry_visible,
                                        retry_msg,
                                        "tool_calls",
                                    )
                                    stats_holder["stats"] = _summed_tool_loop_stats(
                                        _first_stats, stats_holder.get("stats")
                                    )
                                else:
                                    # Retry produced no healable call -> first response wins.
                                    stats_holder["stats"] = _summed_tool_loop_stats(
                                        stats_holder.get("stats"), _first_stats
                                    )
                            except Exception as retry_exc:
                                logger.debug(
                                    "Nudge retry failed; keeping first response: %s", retry_exc
                                )
                                stats_holder["stats"] = _summed_tool_loop_stats(
                                    stats_holder.get("stats"), _first_stats
                                )
                    # parallel_tool_calls=false: cap to one call (GGUF parity).
                    if payload.parallel_tool_calls is False:
                        _tcs = _msg.get("tool_calls")
                        if isinstance(_tcs, list) and len(_tcs) > 1:
                            _msg["tool_calls"] = _tcs[:1]
                return _msg, _finish, stats_holder.get("stats")

            from core.inference.llama_server_args import PARALLEL_DEFAULT

            _width = getattr(backend, "effective_parallel_slots", PARALLEL_DEFAULT)
            if _n > 1 and _width > 1 and payload.use_adapter is None and not cancel_event.is_set():
                for _start in range(0, _n, _width):
                    if cancel_event.is_set():
                        break
                    if not await _produce_choices(range(_start, min(_start + _width, _n))):
                        break

            for _idx in range(_n):
                if _idx and cancel_event.is_set() and _idx not in _produced:
                    continue
                _msg, _finish, _choice_stats = await _one_choice(_idx)
                _choices.append(
                    CompletionChoice(
                        index = _idx,
                        message = CompletionMessage(
                            content = _msg["content"],
                            reasoning_content = _msg.get("reasoning_content"),
                            tool_calls = _msg.get("tool_calls"),
                        ),
                        finish_reason = _finish,
                    )
                )
                _monitor_replies.append(_msg)
                if _choice_stats:
                    _last_stats = _choice_stats
                    _choice_usage = _choice_stats.get("usage") or {}
                    # Prompt shared across n choices: count its tokens once.
                    if _choice_usage.get("prompt_tokens"):
                        _prompt_tokens = _choice_usage["prompt_tokens"]
                        # Details come from the same choice as prompt_tokens, else cached can exceed prompt.
                        _prompt_details = _choice_usage.get("prompt_tokens_details")
                    _sum_completion += _choice_usage.get("completion_tokens") or 0
            _mark_cancelled_json_response_failed(request, cancel_event)
            _msg, _finish = _monitor_replies[-1], _choices[-1].finish_reason

            # Built once, so what the monitor records is this same object and cannot disagree with the body.
            _usage = CompletionUsage(
                prompt_tokens = _prompt_tokens,
                completion_tokens = _sum_completion,
                total_tokens = _prompt_tokens + _sum_completion,
                prompt_tokens_details = _prompt_tokens_details(_prompt_details),
            )
            response = ChatCompletion(
                id = completion_id,
                created = created,
                model = model_name,
                choices = _choices,
                usage = _usage,
            )

            def _reply_text(msg, finish):
                _text = msg.get("content") or ""
                if finish != "tool_calls":
                    return _text
                _calls_text = "; ".join(
                    f"{(tc.get('function') or {}).get('name', '')}"
                    f"({(tc.get('function') or {}).get('arguments', '')})"
                    for tc in msg.get("tool_calls") or []
                )
                return _text + (f"[tool_calls] {_calls_text}" if _calls_text else "")

            if len(_choices) > 1:
                # Label every choice as llama-server does so the last one does not hide the rest; number by each choice index since cancelled turns skip unproduced ones
                _monitor_reply = "\n\n".join(
                    f"Choice {_choice.index + 1}:\n{_reply_text(_reply, _choice.finish_reason)}"
                    for _reply, _choice in zip(_monitor_replies, _choices)
                )
            else:
                _monitor_reply = _reply_text(_msg, _finish)
            api_monitor.set_reply(monitor_id, _monitor_reply)
            if len(_choices) <= 1:
                # Suppressed for n > 1: choices can end differently.
                api_monitor.set_perf(monitor_id, stop_reason = _finish)
            if _last_stats:
                _monitor_usage(
                    monitor_id,
                    _usage.model_dump(),
                    # Omitted for n > 1: timings describe only the last choice.
                    timings = _last_stats.get("timings") if len(_choices) <= 1 else None,
                )
            api_monitor.finish(monitor_id)
            return _model_json_response_with_context_truncation(
                response, _sf_context_truncation_holder["value"]
            )

        except asyncio.CancelledError:
            cancel_event.set()
            backend.reset_generation_state(cancel_event)
            api_monitor.finish(monitor_id, "cancelled")
            raise
        except HTTPException:
            raise
        except GenStreamErrorRaised as exc:
            # Compare-mode adapter failure: honor the public flag and the refused parameter so a contract refusal stays a client error
            backend.reset_generation_state(cancel_event)
            _msg = _friendly_gen_stream_error(exc)
            api_monitor.fail(monitor_id, _msg)
            _refused = _refused_parameter(exc)
            if _refused:
                raise _reject(
                    400,
                    openai_error_body(
                        _msg, status = 400, code = "unsupported_parameter", param = _refused
                    ),
                )
            raise HTTPException(status_code = 500, detail = _msg)
        except context_refusal.ContextBudgetExceeded as e:
            backend.reset_generation_state(cancel_event)
            api_monitor.fail(monitor_id, _friendly_error(e))
            raise _context_budget_http_error(e)
        except Exception as e:
            backend.reset_generation_state(cancel_event)
            logger.error(f"Error during OpenAI completion: {e}", exc_info = True)
            api_monitor.fail(monitor_id, _friendly_error(e))
            from core.inference.engine_transport import EngineHTTPError

            if isinstance(e, EngineHTTPError):
                raise _openai_passthrough_error(e.status_code, e.body)
            raise HTTPException(status_code = 500, detail = safe_error_detail(e))
        finally:
            # Nested under the except arms too: reset_generation_state() can throw, and a leaked entry 409s swaps.
            _tracker.__exit__(None, None, None)


# =====================================================================

# Sandbox file serving  (/sandbox/{session_id}/{filename})
# =====================================================================

_SANDBOX_MEDIA_TYPES = {
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".gif": "image/gif",
    ".webp": "image/webp",
    ".bmp": "image/bmp",
    # `nosniff` pins the type either way, so serve .avif as an image.
    ".avif": "image/avif",
    # `.svg` stays OUT: a model-chosen inline SVG would be same-origin script execution.
}


def _sandbox_dir_for(session_id: str, create: bool = True) -> str:
    """create=False resolves the path without creating it, so read-only lookups leave no directory."""
    from core.inference.tools import get_sandbox_workdir, resolve_sandbox_workdir

    resolver = get_sandbox_workdir if create else resolve_sandbox_workdir
    return os.path.realpath(resolver(session_id))


# Taken from the snapshot walk so the card never advertises a file this route refuses.
from core.inference.tools import (
    _INTERNAL_SANDBOX_FILES,
    _MAX_SANDBOX_PATH_SEGMENTS,
    _MAX_SNAPSHOT_DIRS,
    _MAX_SNAPSHOT_FILES,
    _servable_segment,
    _user_path_parts,
)
from utils.paths.path_utils import is_appledouble_metadata


def _contained_sandbox_path(session_id: str, filename: str) -> tuple[str, str]:
    """Containment is decided by the realpath, not the string, so an escaping symlink is refused."""
    parts = [part for part in filename.replace("\\", "/").split("/") if part not in ("", ".")]
    if not parts or len(_user_path_parts(parts)) > _MAX_SANDBOX_PATH_SEGMENTS:
        raise HTTPException(status_code = 404, detail = "Not found")
    for part in parts:
        # os.path.join drops the prefix on an absolute segment or drive; realpath check backs this.
        if part == ".." or os.path.isabs(part) or os.path.splitdrive(part)[0]:
            raise HTTPException(status_code = 404, detail = "Not found")
        if not _re.fullmatch(r"[^/\\\x00-\x1f]{1,255}", part):
            raise HTTPException(status_code = 404, detail = "Not found")
    sandbox_dir = _sandbox_dir_for(session_id, create = False)
    # The lexical check above is the cheap refusal; this one knows the real scratch dir.
    if len(_user_path_parts(parts, sandbox_dir)) > _MAX_SANDBOX_PATH_SEGMENTS:
        raise HTTPException(status_code = 404, detail = "Not found")
    file_path = os.path.realpath(os.path.join(sandbox_dir, *parts))
    if file_path != sandbox_dir and not file_path.startswith(sandbox_dir + os.sep):
        raise HTTPException(
            status_code = status.HTTP_403_FORBIDDEN,
            detail = "Access denied",
        )
    return sandbox_dir, file_path


def _sandbox_listing_names(sandbox_dir: str) -> "list[str]":
    """Bounded like the snapshot walk, so an unpacked archive cannot turn a listing into a crawl."""
    names: "list[str]" = []
    visited = 0
    for base, dirs, entries in os.walk(sandbox_dir):
        visited += 1
        if visited > _MAX_SNAPSHOT_DIRS:
            return names
        relative = base[len(sandbox_dir) :].strip(os.sep)
        depth = len(_user_path_parts(relative.split(os.sep) if relative else []))
        # Depth 0 is the sandbox itself, whose files are one segment, hence the minus one; drop segments the route would refuse so the two walks agree
        dirs[:] = (
            []
            if depth >= _MAX_SANDBOX_PATH_SEGMENTS - 1
            else [d for d in sorted(dirs) if not d.startswith(".") and _servable_segment(d)]
        )
        for entry in sorted(entries):
            # Mirrors the snapshot, dotfiles included; bookkeeping is hidden only in the sandbox root.
            if base == sandbox_dir and entry in _INTERNAL_SANDBOX_FILES:
                continue
            if not _servable_segment(entry):
                continue
            path = os.path.join(base, entry)
            try:
                if not os.path.isfile(path) or os.path.islink(path):
                    continue
            except OSError:
                continue
            if is_appledouble_metadata(Path(path)):
                continue
            names.append(os.path.relpath(path, sandbox_dir).replace(os.sep, "/"))
            if len(names) >= _MAX_SNAPSHOT_FILES:
                return names
    return names


def _sandbox_listing(sandbox_dir: str) -> "list[dict]":
    """Name, size and mtime for everything this chat's tools left behind."""
    files = []
    if not os.path.isdir(sandbox_dir):
        return files
    for name in _sandbox_listing_names(sandbox_dir):
        path = os.path.join(sandbox_dir, name)
        try:
            stat = os.stat(path)
        except OSError:
            continue
        files.append(
            {
                "name": name,
                "size": stat.st_size,
                "modified": int(stat.st_mtime),
                "inline": os.path.splitext(name)[1].lower() in _SANDBOX_MEDIA_TYPES,
            }
        )
    return files


@router.get("/sandbox/{session_id}")
async def list_sandbox_files(
    session_id: str,
    request: Request,
    token: Optional[str] = None,
    session: Optional[str] = None,
):
    """Where this chat's files are, and what is in there.

    The path answers "where did my file go"; before this the only way to find
    one was to search the filesystem by hand.
    """
    await _authenticate_header_or_query(request, token)

    from starlette.concurrency import run_in_threadpool

    def _resolve_and_list() -> "tuple[str, list[dict]]":
        # The query form allows ids with a slash; ASGI decodes %2F before route matching.
        sandbox_dir = _sandbox_dir_for(session or session_id, create = False)
        if not os.path.isdir(sandbox_dir):
            # The legacy-tree background move can race resolve; one more resolve finds it.
            sandbox_dir = _sandbox_dir_for(session or session_id, create = False)
        return sandbox_dir, _sandbox_listing(sandbox_dir)

    # Resolving scans the root; keep it off the event loop for slow filesystems.
    sandbox_dir, files = await run_in_threadpool(_resolve_and_list)
    return {"path": sandbox_dir, "files": files}


def _sandbox_regular_file(session_id: str, filename: str) -> tuple[str, str]:
    """(sandbox_dir, contained path) of a regular (not linked) file in the sandbox, or a 404."""
    import stat as _stat

    sandbox_dir, path = _contained_sandbox_path(session_id, filename)
    try:
        entry = os.lstat(path)
    except OSError:
        raise HTTPException(status_code = 404, detail = "Not found") from None
    if not _stat.S_ISREG(entry.st_mode):
        raise HTTPException(status_code = 404, detail = "Not found")
    return sandbox_dir, path


def _unmoved_sandbox_file(root: str, path: str) -> str:
    """``path`` resolved, if it still names the same file under ``root``; a link swapped in since
    the check is refused, since a reveal hands the file manager a name."""
    try:
        real = os.path.realpath(path)
        expected = os.path.relpath(os.path.abspath(path), os.path.abspath(root))
        actual = os.path.relpath(real, os.path.realpath(root))
    except ValueError:
        raise FileNotFoundError(path) from None
    if expected != actual or actual.startswith(os.pardir) or not os.path.isfile(real):
        raise FileNotFoundError(path)
    return real


@router.post("/sandbox/{session_id}/open")
async def open_sandbox_file(
    session_id: str,
    request: Request,
    file: str,
    token: Optional[str] = None,
    session: Optional[str] = None,
):
    """Open one of this chat's sandbox files with the OS default app.

    Like reveal, this is the backend host's desktop, so it only means anything in
    the desktop app. Only document and media types open: the files are
    model-written, and a script or app would run rather than be viewed.
    """
    await _authenticate_header_or_query(request, token)
    # It launches an app on the host's desktop, like the library and model reveals.
    account_access.require_installation_owner()

    from pathlib import Path

    from starlette.concurrency import run_in_threadpool

    from utils.paths.path_utils import open_in_default_app

    root, path = await run_in_threadpool(_sandbox_regular_file, session or session_id, file)
    try:
        await run_in_threadpool(open_in_default_app, Path(path), Path(root))
    except PermissionError:
        raise HTTPException(
            status_code = 415, detail = "This kind of file does not open outside Unsloth"
        ) from None
    except FileNotFoundError:
        raise HTTPException(status_code = 404, detail = "Not found") from None
    except Exception:
        logger.error(f"Failed to open sandbox file {path}", exc_info = True)
        raise HTTPException(status_code = 500, detail = "Failed to open the file") from None
    return {"status": "ok"}


@router.post("/sandbox/{session_id}/reveal")
async def reveal_sandbox_dir(
    session_id: str,
    request: Request,
    token: Optional[str] = None,
    session: Optional[str] = None,
    file: Optional[str] = None,
):
    """Open this chat's sandbox directory in the OS file manager.

    With ``file``, that file is selected in its folder instead.

    The file manager is the backend host's, so this only means anything when the
    backend runs on the user's own machine, which is the desktop app.
    """
    await _authenticate_header_or_query(request, token)
    # Like open: it drives the host's desktop, so only its owner may.
    account_access.require_installation_owner()

    from starlette.concurrency import run_in_threadpool

    if file:
        from pathlib import Path

        from utils.paths.path_utils import reveal_in_file_manager

        root, path = await run_in_threadpool(_sandbox_regular_file, session or session_id, file)
        try:
            real = await run_in_threadpool(_unmoved_sandbox_file, root, path)
            await run_in_threadpool(reveal_in_file_manager, Path(real))
        except FileNotFoundError:
            raise HTTPException(status_code = 404, detail = "Not found") from None
        except Exception:
            logger.error(f"Failed to reveal sandbox file {path}", exc_info = True)
            raise HTTPException(status_code = 500, detail = "Failed to open file manager") from None
        return {"status": "ok", "path": path}

    def _resolve_existing() -> "str | None":
        sandbox_dir = _sandbox_dir_for(session or session_id, create = False)
        if not os.path.isdir(sandbox_dir):
            # One more resolve: the legacy move can race resolve.
            sandbox_dir = _sandbox_dir_for(session or session_id, create = False)
        return sandbox_dir if os.path.isdir(sandbox_dir) else None

    # Resolving scans the sandbox root, so it stays off the event loop.
    sandbox_dir = await run_in_threadpool(_resolve_existing)
    if sandbox_dir is None:
        raise HTTPException(status_code = 404, detail = "This chat has no folder yet")

    from pathlib import Path

    from utils.paths.path_utils import reveal_in_file_manager

    try:
        # expect_dir: a tool replacing its sandbox with a file would otherwise reveal the root.
        await run_in_threadpool(reveal_in_file_manager, Path(sandbox_dir), expect_dir = True)
    except FileNotFoundError:
        # Distinguish a vanished sandbox from a missing file manager (xdg-open).
        if os.path.isdir(sandbox_dir):
            logger.error(f"Failed to reveal sandbox {sandbox_dir}", exc_info = True)
            raise HTTPException(status_code = 500, detail = "Failed to open file manager")
        raise HTTPException(status_code = 404, detail = "This chat has no folder yet")
    except Exception:
        logger.error(f"Failed to reveal sandbox {sandbox_dir}", exc_info = True)
        raise HTTPException(status_code = 500, detail = "Failed to open file manager")
    return {"status": "ok", "path": sandbox_dir}


@router.post("/sandbox/{session_id}/upload")
async def upload_sandbox_file(
    session_id: str,
    file: UploadFile = File(...),
    overwrite: bool = Form(False),
    session: Optional[str] = None,
    current_subject: str = Depends(get_current_subject),
):
    """Put one file into this chat's sandbox folder, where its tools read and write.

    Saved at the folder's root under the file's own name. A taken name is a 409 unless
    ``overwrite``, so a second upload never silently replaces what a tool wrote.
    """
    from starlette.concurrency import run_in_threadpool

    from core.inference.tools import SandboxUploadExists, save_sandbox_upload
    from utils.upload_limits import SANDBOX_UPLOAD_MAX_BYTES

    def _chunks():
        total = 0
        while chunk := file.file.read(1 << 20):
            total += len(chunk)
            if total > SANDBOX_UPLOAD_MAX_BYTES:
                raise HTTPException(status_code = 413, detail = f"{file.filename} is too large")
            yield chunk

    try:
        saved = await run_in_threadpool(
            save_sandbox_upload, session or session_id, file.filename, _chunks(), overwrite
        )
    except SandboxUploadExists as exc:
        raise HTTPException(status_code = 409, detail = f"{exc} already exists") from None
    except OSError:
        logger.error("Failed to save a sandbox upload", exc_info = True)
        raise HTTPException(status_code = 500, detail = "Could not save the file") from None
    return saved


@router.api_route("/sandbox/{session_id}/{filename:path}", methods = ["GET", "HEAD"])
async def serve_sandbox_file(
    session_id: str,
    filename: str,
    request: Request,
    token: Optional[str] = None,
    session: Optional[str] = None,
):
    """
    Serve a file a tool call created in this chat's sandbox.

    Images keep their real media type and render inline. Everything else is an
    opaque attachment: the model picks these filenames, so an inline text/html
    or image/svg+xml would be same-origin script execution. nosniff plus a
    Content-Disposition filename is what makes serving them safe.

    Accepts auth via an Authorization header or a query token. Unsloth uses an
    authenticated fetch and object URL; query auth remains for older clients.
    """
    # ── Authentication (header or query param) ──────────────────
    await _authenticate_header_or_query(request, token)

    # ── Filename sanitization + path containment ────────────────
    import stat as _stat

    from starlette.concurrency import run_in_threadpool

    safe_filename = os.path.basename(filename)

    # Runs in a worker like the listing: resolving the sandbox and opening the file both touch disk.
    def _open_checked() -> "tuple[int, int]":
        _dir, path = _contained_sandbox_path(session or session_id, filename)
        if not os.path.isfile(path):
            # The legacy move can rename the tree after resolve; retry once.
            _dir, path = _contained_sandbox_path(session or session_id, filename)
        try:
            # O_NOFOLLOW: tool code can plant a link between the check and the open.
            handle = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
        except OSError:
            raise HTTPException(status_code = 404, detail = "Not found") from None
        try:
            info = os.fstat(handle)
            # Re-check containment against the open descriptor, or a swapped parent link escapes.
            _dir, again = _contained_sandbox_path(session or session_id, filename)
            checked = os.stat(again)
            if not _stat.S_ISREG(info.st_mode) or (checked.st_dev, checked.st_ino) != (
                info.st_dev,
                info.st_ino,
            ):
                raise HTTPException(status_code = 404, detail = "Not found")
        except BaseException:
            os.close(handle)
            raise
        return handle, info.st_size

    handle, size = await run_in_threadpool(_open_checked)
    head_only = getattr(request, "method", "GET").upper() == "HEAD"
    if head_only:
        # FastAPI adds no HEAD to GET routes; nothing is read since artifacts can be huge.
        os.close(handle)

    ext = os.path.splitext(safe_filename)[1].lower()
    media_type = _SANDBOX_MEDIA_TYPES.get(ext)
    headers = {
        "Cache-Control": "private, no-store",
        "X-Content-Type-Options": "nosniff",
    }
    if media_type is None:
        media_type = "application/octet-stream"
        # RFC 5987: ASCII fallback plus UTF-8 form, so "ventas año.csv" saves.
        ascii_name = safe_filename.encode("ascii", "replace").decode("ascii").replace('"', "_")
        quoted = _urlquote(safe_filename)
        headers["Content-Disposition"] = (
            f"attachment; filename=\"{ascii_name}\"; filename*=UTF-8''{quoted}"
        )

    headers["Content-Length"] = str(size)
    if head_only:
        return Response(status_code = 200, media_type = media_type, headers = headers)

    def _read():
        # Exactly Content-Length: another call can still append to this file.
        remaining = size
        with os.fdopen(handle, "rb") as opened:
            while remaining > 0:
                chunk = opened.read(min(64 * 1024, remaining))
                if not chunk:
                    return
                remaining -= len(chunk)
                yield chunk

    return StreamingResponse(_read(), media_type = media_type, headers = headers)


# =====================================================================
# Every /v1/models entry, loaded and available alike, carries the owned_by marker.
# =====================================================================
_OWNED_BY = "unsloth-studio"


def _openai_model_objects() -> list[dict]:
    return [
        entry
        for slot in (None, *model_slots.visible())
        for entry in model_slots.in_slot(slot, _slot_model_objects)
    ]


def _slot_model_objects() -> list[dict]:
    """Shared by LIST and RETRIEVE so both report the same ids and shape; one per loaded local backend still answering to its advertised id"""
    from core.inference.audio_cpp_models import AUDIO_CPP_SEP_AUDIO_TYPE
    from core.inference.audio_workflows import status_audio_workflows

    if (
        routed_slot.get() is None
        and account_access.managed_account()
        and account_access.resident_hidden("chat", _loaded_slot_ident())
    ):
        return []
    models: list[dict] = []
    _created = int(time.time())

    from core.inference.npu_backend import peek_npu_backend

    _npu = peek_npu_backend()
    _npu_resident = _npu.resident() if _npu is not None and routed_slot.get() is None else None
    if _npu_resident is not None:
        _npu_model = _npu_resident.model
        _npu_entry = {
            "id": _npu_model.model_path,
            "object": "model",
            "created": _created,
            "owned_by": _OWNED_BY,
            "device": "npu",
        }
        if _npu_resident.context_length:
            _npu_entry["context_length"] = _npu_resident.context_length
        if _npu_model.max_context_length:
            _npu_entry["max_context_length"] = _npu_model.max_context_length
        models.append(_npu_entry)

    # Check GGUF backend
    llama_backend = get_llama_cpp_backend()
    # Claiming a re-pulled tag would displace the scanned row holding its weights; the id published can differ from the recorded tag for an alias
    _resident_identifier = getattr(llama_backend, "model_identifier", None) or ""
    _stale_ollama_resident = (
        llama_backend.is_loaded
        and is_ollama_manifest_ref(_resident_identifier)
        and not _loaded_satisfies(_llama_public_model_id(llama_backend))
    )
    if llama_backend.is_loaded and not _stale_ollama_resident:
        # Advertise the recorded repo id, never the on-disk path, to avoid leaks and duplicates.
        entry = {
            # Recorded id after an auto-switch or Ollama load; else a clean id, as .gguf paths leak the host.
            "id": _llama_public_model_id(llama_backend),
            "object": "model",
            "created": _created,
            "owned_by": _OWNED_BY,
        }
        _quant = getattr(llama_backend, "hf_variant", None)
        if _quant and _quant_reference_resolves(entry["id"], _quant):
            entry["quant"] = _quant
        _ctx = _positive_int_or_none(getattr(llama_backend, "context_length", None))
        if _ctx is not None:
            entry["context_length"] = _ctx
        _max_ctx = _positive_int_or_none(getattr(llama_backend, "max_context_length", None))
        if _max_ctx is not None:
            entry["max_context_length"] = _max_ctx
        # Not the running window (context_length): omitted when no fit vouched for one (#12571).
        _fit_ctx = _positive_int_or_none(getattr(llama_backend, "vram_fit_context_length", None))
        if _fit_ctx is not None:
            entry["vram_fit_context_length"] = _fit_ctx
        _native_ctx = _positive_int_or_none(getattr(llama_backend, "native_context_length", None))
        if _native_ctx is not None:
            entry["native_context_length"] = _native_ctx
        # Same gate as /v1/audio/speech: _audio_type also matches whisper and audio_vlm.
        if getattr(llama_backend, "_is_audio", False) and (
            getattr(llama_backend, "_audio_type", None) in _GGUF_TTS_AUDIO_TYPES
        ):
            entry["task"] = _TTS_MODEL_TASK
            entry["audio_workflows"] = status_audio_workflows(True, llama_backend._audio_type)
        models.append(entry)

    # Must not construct an unused orchestrator: its cold init runs device detection.
    backend = _peek_inference_backend()
    if backend is not None and backend.active_model_name:
        model_info = backend.models.get(backend.active_model_name, {})
        entry = {
            # The alias, or an LM Studio model switched to by repo id loses its publisher.
            "id": _orchestrator_public_model_id(backend),
            "object": "model",
            "created": _created,
            "owned_by": _OWNED_BY,
        }
        _ctx = _positive_int_or_none(model_info.get("context_length"))
        if _ctx is None:
            for _candidate in (
                getattr(backend, "context_length", None),
                getattr(backend, "max_seq_length", None),
            ):
                _ctx = _positive_int_or_none(_candidate)
                if _ctx is not None:
                    break
        if _ctx is not None:
            entry["context_length"] = _ctx
        audio_type = model_info.get("audio_type")
        is_sep = audio_type == AUDIO_CPP_SEP_AUDIO_TYPE
        if (
            not model_info.get("is_mlx")
            and model_info.get("is_audio")
            and (audio_type in _TRANSFORMERS_TTS_AUDIO_TYPES or is_sep)
        ):
            # A resident separation model is not a chat model either.
            entry["task"] = _SEP_MODEL_TASK if is_sep else _TTS_MODEL_TASK
            entry["audio_workflows"] = model_info.get("audio_workflows") or (
                status_audio_workflows(True, audio_type)
            )

        for _field in ("native_context_length", "max_context_length", "context_length_fitted"):
            _value = _positive_int_or_none(model_info.get(_field))
            if _value is not None:
                entry[_field] = _value
        _serving = _unsloth_serving_fields(model_info)
        if _serving["context_length_enforced"] is not None:
            entry["context_length_enforced"] = bool(_serving["context_length_enforced"])
        if _serving["context_unbounded_when_batched"]:
            entry["context_unbounded_when_batched"] = True
        if _serving["parallel_slots"] is not None:
            entry["parallel_slots"] = _serving["parallel_slots"]
        models.append(entry)

    return models


# Short cache so repeated /v1/models calls do not rescan the HF cache and models dirs.
_CATALOG_CACHE: dict = {"at": 0.0, "models": []}
# Ids the last catalog scan listed, rebuilt only when that scan is replaced.
_ADVERTISED_CACHE: dict = {"at": None, "paths": {}}


def _quant_reference_resolves(model_id: Optional[str], quant: str) -> bool:
    """A standalone .gguf has no resolver quants, so an advertised pin dies when another model loads."""
    from core.inference.local_model_resolver import (
        index_is_built,
        recently_downloaded,
        resolve_local_gguf,
        warm_index_soon,
    )

    if not model_id:
        return False
    # A cold index proves nothing; warm so the next response carries the quant.
    warm_index_soon()
    return resolve_local_gguf(f"{model_id}:{quant}", allow_scan = False) is not None


def _advertised_local_path(model: str) -> Optional[str]:
    """Cache-only, never scans: a local model the catalog lists but the resolver index lacks is evidence the name means something other than the resident one"""
    if _account_advertised_cache()["at"] != _account_catalog_cache()["at"]:
        paths = {}
        for info in _account_catalog_cache()["models"] or ():
            cid = getattr(info, "model_id", None) or public_model_id(getattr(info, "id", None))
            path = getattr(info, "path", None)
            if cid and path:
                paths.setdefault(cid.strip().lower(), path)
        _account_advertised_cache().update(at = _account_catalog_cache()["at"], paths = paths)
    return _account_advertised_cache()["paths"].get(model.strip().lower())


_CATALOG_TTL_S = 30.0
# Per-loop lock: a module-level asyncio.Lock binds to the first loop and can hang others.
_catalog_locks: "weakref.WeakKeyDictionary" = weakref.WeakKeyDictionary()
_catalog_locks_guard = threading.Lock()


_managed_catalogs: dict[str, dict] = {}
_managed_catalogs_lock = threading.Lock()


def _account_catalog_cache():
    if not account_access.managed_account():
        return _CATALOG_CACHE
    with _managed_catalogs_lock:
        return _managed_catalogs.setdefault(current_account_id(), {"at": 0.0, "models": []})


def _account_advertised_cache():
    if not account_access.managed_account():
        return _ADVERTISED_CACHE
    return _account_catalog_cache().setdefault("advertised", {"at": None, "paths": {}})


def _catalog_lock() -> asyncio.Lock:
    loop = asyncio.get_running_loop()
    with _catalog_locks_guard:
        lock = _catalog_locks.get(loop)
        if lock is None:
            lock = _catalog_locks[loop] = asyncio.Lock()
        return lock


def _classified_catalog(models: list) -> list:
    from hub.services.models.catalog_classification import _local_model_classification

    classified = []
    for model in models:
        if getattr(model, "task", None) is None and hasattr(model, "model_copy"):
            try:
                task, audio_type = _local_model_classification(model)
                model = model.model_copy(update = {"task": task, "audio_type": audio_type})
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "model task classification failed for %s: %s", getattr(model, "id", "?"), exc
                )
        classified.append(model)
    return classified


_MEDIA_MODEL_TASKS = ("text-to-image", "text-to-video")
_STT_MODEL_TASK = "automatic-speech-recognition"
_TTS_MODEL_TASK = "text-to-speech"
_SEP_MODEL_TASK = "audio-to-audio"


def _media_owner(task: str) -> str:
    from core.inference.gpu_arbiter import DIFFUSION, VIDEO
    return DIFFUSION if task == "text-to-image" else VIDEO


def _resident_media_status(task: str) -> Optional[dict]:
    if account_access.resident_hidden(_media_owner(task)):
        return None
    from core.inference.media_keepwarm import engine_if_imported

    try:
        engine = engine_if_imported(_media_owner(task))
        status = engine.status() if engine is not None else None
    except Exception as exc:  # noqa: BLE001
        logger.debug("%s status unavailable for /v1/models: %s", task, exc)
        return None
    if status and account_access.resident_hidden(_media_owner(task), status.get("repo_id")):
        return None
    return status if status and status.get("loaded") else None


_MEDIA_PICK_CACHE: dict = {"at": None, "picks": {}}
_MEDIA_PICK_CACHE_LOCK = threading.Lock()


def _validated_media_picks(catalog_at: float) -> dict:
    """Rebuilt only when the catalog scan changes; per-request resolving re-walked the media indexes."""
    if _MEDIA_PICK_CACHE["at"] == catalog_at:
        return _MEDIA_PICK_CACHE["picks"]
    with _MEDIA_PICK_CACHE_LOCK:
        if _MEDIA_PICK_CACHE["at"] == catalog_at:
            return _MEDIA_PICK_CACHE["picks"]
        from core.inference.media_locality import (
            _PLANNED_ORDINAL,
            catalog_gpu_ordinal,
            is_edit_only,
            missing_download_bytes,
        )
        from core.inference.media_model_index import (
            available_media_model_ids,
            resolve_local_media_model,
        )

        picks: dict = {}
        # One placement decision per refresh, never a live ranking per pick.
        planned = _PLANNED_ORDINAL.set(catalog_gpu_ordinal())
        try:
            for task in _MEDIA_MODEL_TASKS:
                rows = []
                for model_id in available_media_model_ids(task):
                    pick = resolve_local_media_model(model_id, task = task)
                    if pick is None:
                        continue
                    # The local catalog tags an instruction-editing checkpoint text-to-image, but it
                    # ships no txt2img workflow: the switch refuses it with a 400 and a resident one
                    # is refused by /v1/images/generations too.
                    if task == "text-to-image" and is_edit_only(pick):
                        continue
                    try:
                        local = missing_download_bytes(_media_owner(task), pick) == 0
                    except Exception as exc:  # noqa: BLE001
                        logger.debug("media locality unavailable for %s: %s", model_id, exc)
                        local = False
                    rows.append((model_id, pick, local))
                picks[task] = rows
        finally:
            _PLANNED_ORDINAL.reset(planned)
        _MEDIA_PICK_CACHE.update(at = catalog_at, picks = picks)
        return picks


def _media_model_objects(catalog: list, created: int, catalog_at: float) -> list[dict]:
    """Built from the media index generation resolves against, so rejected entries are not advertised; residency via resident_is_pick, read per request"""
    from core.inference.media_model_index import (
        partition_matches,
        resident_is_gguf,
        satisfied_by,
    )
    from hub.utils.gguf import extract_quant_token

    display_by_id: dict[str, str] = {}
    for info in catalog:
        cid = getattr(info, "model_id", None) or public_model_id(getattr(info, "id", None))
        display = getattr(info, "display_name", None)
        if cid and display:
            display_by_id.setdefault(cid, display)

    picks_by_task = _validated_media_picks(catalog_at)
    objects: list[dict] = []
    for task in _MEDIA_MODEL_TASKS:
        status = _resident_media_status(task)
        for model_id, pick, local in picks_by_task.get(task, ()):
            if account_access.managed_account() and not account_access.model_visible(
                pick.model_path
            ):
                continue
            loaded = bool(status) and satisfied_by(status, model_id, pick)
            if not loaded and not local:
                continue
            obj = {
                "id": model_id,
                "object": "model",
                "created": created,
                "owned_by": _OWNED_BY,
                "task": task,
                "loaded": loaded,
            }
            quant = (status.get("gguf_variant") if loaded else None) or (
                extract_quant_token(pick.gguf_filename) if pick.gguf_filename else None
            )
            if quant:
                obj["quant"] = quant
            display = display_by_id.get(model_id)
            if display:
                obj["display_name"] = display
            objects.append(obj)
        resident_id = str((status or {}).get("repo_id") or "").strip()
        resident_workflows = (status or {}).get("workflows") or ()
        if (
            status
            and resident_id
            and not resident_is_gguf(status)
            and partition_matches(status)
            and (
                task != "text-to-image" or not resident_workflows or "txt2img" in resident_workflows
            )
            and public_model_id(resident_id) == resident_id
            and not any(obj["id"].lower() == resident_id.lower() for obj in objects)
        ):
            objects.append(
                {
                    "id": resident_id,
                    "object": "model",
                    "created": created,
                    "owned_by": _OWNED_BY,
                    "task": task,
                    "loaded": True,
                }
            )
    return objects


_CUSTOM_STT_CACHE: dict = {"at": None, "ids": ()}
_CUSTOM_STT_CACHE_LOCK = threading.Lock()


def _downloaded_custom_stt_ids(catalog_at: Optional[float]) -> tuple[str, ...]:
    if catalog_at is not None and _CUSTOM_STT_CACHE["at"] == catalog_at:
        return _CUSTOM_STT_CACHE["ids"]
    with _CUSTOM_STT_CACHE_LOCK:
        if catalog_at is not None and _CUSTOM_STT_CACHE["at"] == catalog_at:
            return _CUSTOM_STT_CACHE["ids"]
        from core.inference import stt_sidecar
        from hub.services.models.cache_inventory import _scan_cached_models

        try:
            ids = tuple(
                sorted(
                    row["repo_id"]
                    for row in _scan_cached_models()
                    if row.get("task") == _STT_MODEL_TASK
                    and not row.get("partial")
                    and isinstance(row.get("repo_id"), str)
                    and stt_sidecar.is_model_downloaded(row["repo_id"])
                )
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug("custom stt cache scan unavailable for /v1/models: %s", exc)
            ids = ()
        _CUSTOM_STT_CACHE.update(at = catalog_at, ids = ids)
        return ids


def _stt_model_objects(created: int, catalog_at: Optional[float] = None) -> list[dict]:
    """Only lists STT models this route can serve, gating each engine on its own runtime availability."""
    try:
        from core.inference import stt_audiocpp_sidecar, stt_mtmd_sidecar, stt_sidecar

        whisper_ready = stt_sidecar.is_available()
        mtmd_ready = stt_mtmd_sidecar.is_available()
        audiocpp_ready = stt_audiocpp_sidecar.is_available()
        loaded = set()
        if whisper_ready:
            whisper_loaded = stt_sidecar.get_stt_sidecar().loaded_model
            loaded.add(stt_sidecar.STT_MODELS.get(whisper_loaded, whisper_loaded))
        if mtmd_ready:
            loaded.add(stt_mtmd_sidecar.get_mtmd_stt_sidecar().loaded_model)
        if audiocpp_ready:
            # Status may name it by a legacy key; the listing names rows.
            loaded.add(
                stt_audiocpp_sidecar.acm_row_id(
                    stt_audiocpp_sidecar.get_audio_cpp_stt_sidecar().loaded_model
                )
                or None
            )
        loaded -= {None}

        ids: list[str] = []
        if whisper_ready:
            ids.extend(
                repo_id
                for model_id, repo_id in stt_sidecar.STT_MODELS.items()
                if stt_sidecar.is_model_downloaded(model_id)
            )
            ids.extend(
                model_id
                for model_id in _downloaded_custom_stt_ids(catalog_at)
                if model_id not in ids
            )
        if mtmd_ready:
            ids.extend(
                model_id
                for model_id in stt_mtmd_sidecar.MTMD_STT_MODELS
                if stt_mtmd_sidecar.is_model_downloaded(model_id)
            )
        audiocpp_ids: set[str] = set()
        if audiocpp_ready:
            audiocpp_ids = set(stt_audiocpp_sidecar.downloaded_model_ids())
            ids.extend(model_id for model_id in sorted(audiocpp_ids) if model_id not in ids)
        # A custom Whisper repo the route can still reload by name while it is resident.
        ids.extend(sorted(model_id for model_id in loaded if model_id not in ids))
    except Exception as exc:  # noqa: BLE001
        logger.debug("stt models unavailable for /v1/models: %s", exc)
        return []
    objects = []
    for model_id in ids:
        obj = {
            "id": model_id,
            "object": "model",
            "created": created,
            "owned_by": _OWNED_BY,
            "task": _STT_MODEL_TASK,
            "loaded": model_id in loaded,
            # Custom Whisper repos are not probed here, so only curated ones advertise translate.
            "audio_workflows": (
                ["transcribe", "translate"]
                if model_id in stt_sidecar.STT_MODELS.values()
                and stt_sidecar.can_translate(model_id)
                else ["transcribe"]
            ),
        }
        spec = stt_mtmd_sidecar.MTMD_STT_MODELS.get(model_id)
        if spec is not None:
            from hub.utils.gguf import extract_quant_token
            quant = extract_quant_token(spec.model_file)
            if quant:
                obj["quant"] = quant
        is_audio_cpp = model_id in audiocpp_ids
        if account_access.managed_account():
            if is_audio_cpp:
                from core.inference.audio_cpp_models import repo_of
                repo = repo_of(model_id) or model_id
            else:
                repo = spec.repo if spec is not None else model_id
            if not account_access.model_visible(repo):
                continue
            engine = (
                "audiocpp" if is_audio_cpp else ("mtmd" if spec is not None else "transformers")
            )
            if account_access.resident_hidden(f"stt:{engine}", model_id):
                obj["loaded"] = False
        objects.append(obj)
    return objects


async def _cached_local_catalog() -> list:
    """Runs the scan in a worker thread so the event loop is not blocked; a lock collapses bursts."""
    # Keyed on 'at' so an empty/errored scan is still cached.
    now = time.monotonic()
    if _account_catalog_cache()["at"] and (now - _account_catalog_cache()["at"]) <= _CATALOG_TTL_S:
        return _account_catalog_cache()["models"]
    async with _catalog_lock():
        now = time.monotonic()
        if (
            _account_catalog_cache()["at"]
            and (now - _account_catalog_cache()["at"]) <= _CATALOG_TTL_S
        ):
            return _account_catalog_cache()["models"]
        try:
            from routes.models import collect_local_models

            # By manifest reference: this catalog resolves rows rather than opening their ids.
            _account_catalog_cache()["models"] = await asyncio.to_thread(
                lambda: _classified_catalog(
                    collect_local_models(Path("./models").resolve(), materialize_ollama_links = False)
                )
            )
        except Exception as exc:
            logger.debug("model catalog scan failed: %s", exc)
            _account_catalog_cache()["models"] = []
        # Stamp after the scan, else a scan slower than the TTL leaves the cache already expired.
        _account_catalog_cache()["at"] = time.monotonic()
    return _account_catalog_cache()["models"]


# One tuple in one assignment so the lock-free fast path never reads a half-replaced stamp and rows; TTL bounds files changed outside Studio
_SERVABLE_SCAN_TTL_S = 5.0
_SERVABLE_SCAN_CACHE: dict = {"entry": None}  # (catalog_at, catalog, generation, at, rows)
_SERVABLE_SCAN_CACHE_LOCK = threading.Lock()


def _servability_generation() -> tuple[int, int, int]:
    """Three counters move independently, so one tuple keeps a stale row from outliving any of them; nothing is caught, since a missing counter pins the key"""
    from core.inference.local_model_resolver import index_generation
    from utils.hardware import hardware as hw

    from hub.utils.inventory_scan import hf_cache_scans_epoch

    return (
        index_generation(),
        int(hf_cache_scans_epoch()),
        int(hw.DETECTION_GENERATION),
    )


def _servable_catalog_scan(catalog, catalog_at: Optional[float]):
    """Rebuilt only on a catalog rescan, since local_servable_model stats many files per entry."""
    from core.inference.local_model_resolver import (
        index_generation,
        local_load_dir,
        local_servable_model,
    )
    from hub.services.models.catalog_classification import _UNSUPPORTED_DIFFUSION_TASK

    # Check catalog identity, not just its stamp (only the cached scan advances it), plus resolver index, HF cache epoch and device generation (MLX self-repair)
    def _fresh():
        """Generation is read before and after the entry, since invalidate_index does not take this lock."""
        before = _servability_generation()
        entry = _SERVABLE_SCAN_CACHE["entry"]  # one read, so the tuple cannot tear
        if entry is None or catalog_at is None:
            return None
        at, cached_catalog, cached_generation, scanned_at, rows = entry
        if cached_generation != before or _servability_generation() != before:
            return None
        # Own TTL too: hand-removed files move no counter, and root mtime misses nested edits.
        if time.monotonic() - scanned_at > _SERVABLE_SCAN_TTL_S:
            return None
        return rows if at == catalog_at and cached_catalog is catalog else None

    hit = _fresh()
    if hit is not None:
        return hit
    with _SERVABLE_SCAN_CACHE_LOCK:
        hit = _fresh()
        if hit is not None:
            return hit
        # Captured before the scan so an invalidation during it leaves the entry stale.
        generation = _servability_generation()
        scanned = []
        for info in catalog:
            if getattr(info, "task", None) in (
                *_MEDIA_MODEL_TASKS,
                _STT_MODEL_TASK,
                _TTS_MODEL_TASK,
                # A separation GGUF: listed by _audio_cpp_speech_model_objects with its workflows.
                _SEP_MODEL_TASK,
                _UNSUPPORTED_DIFFUSION_TASK,
            ):
                continue
            servable = local_servable_model(info)
            if servable is None:
                continue
            is_gguf, quants = servable
            # Source path, not the resolved snapshot dir: HF snapshot pointers can move, and a cached snapshot would report a loaded model as unloaded
            row_id = getattr(info, "id", None)
            scanned.append(
                (
                    info,
                    is_gguf,
                    quants,
                    row_id if is_ollama_manifest_ref(row_id or "") else getattr(info, "path", None),
                )
            )
        if catalog_at is not None:
            # Read the generation before the scan, or a mid-scan invalidation gets cached as already seen.
            _SERVABLE_SCAN_CACHE["entry"] = (
                catalog_at,
                catalog,
                generation,
                time.monotonic(),
                scanned,
            )
        return scanned


def _servable_catalog_rows(
    catalog, catalog_at: Optional[float] = None
) -> list[tuple[object, bool, tuple[str, ...], bool]]:
    """Only the scan is cached; residency and the HF snapshot are read per request. Always call via asyncio.to_thread: it stats files and reads the singleton"""
    from core.inference.local_model_resolver import local_load_dir
    return [
        (
            info,
            is_gguf,
            quants,
            _resolves_to_resident(
                path if is_gguf else local_load_dir(path),
                llama_only = is_gguf,
                exact_only = not is_gguf,
            ),
        )
        for info, is_gguf, quants, path in _servable_catalog_scan(catalog, catalog_at)
    ]


def _with_openai_residency(entry: dict) -> dict:
    # Open WebUI's llama.cpp provider reads status.value and calls a row without one loaded (#10610).
    loaded = bool(entry.get("loaded"))
    return {**entry, "loaded": loaded, "status": {"value": "loaded" if loaded else "unloaded"}}


def _audio_cpp_speech_model_objects(created: int) -> list[dict]:
    """Finds audio.cpp GGUFs by header; the cache scan cannot key umbrella folders."""
    try:
        from core.inference import audio_cpp_server
        from core.inference.audio_cpp_models import downloaded_models

        binary = audio_cpp_server.find_audio_cpp_server_binary()
        if binary is None:
            return []
        objects = []
        for model in downloaded_models():
            if model.audio_type is None or model.task not in ("tts", "music", "sep"):
                continue
            if account_access.managed_account() and not account_access.model_visible(
                model.repo_id or model.id
            ):
                continue
            # An eSpeak model on a build without eSpeak would only 501.
            if audio_cpp_server.model_runtime_problem(model, binary) is not None:
                continue
            objects.append(
                {
                    "id": model.id,
                    "object": "model",
                    "created": created,
                    "owned_by": _OWNED_BY,
                    # Music stays text-to-speech, since /v1/audio/speech serves it.
                    "task": _SEP_MODEL_TASK if model.task == "sep" else _TTS_MODEL_TASK,
                    "display_name": model.display_name,
                    "loaded": False,
                    "audio_workflows": list(model.workflows),
                }
            )
        return objects
    except Exception as exc:  # noqa: BLE001 - a listing never fails for one engine
        logger.debug("audio.cpp models unavailable for /v1/models: %s", exc)
        return []


async def _openai_catalog_objects(quant_pins: bool = False) -> list[dict]:
    """Every model the server knows about for ``GET /v1/models``: the loaded
    model(s) plus locally available (downloaded/cached) models discovered by
    scanning. Loaded entries keep their context fields and are marked
    ``loaded: true``. All ids are clean public ids (never absolute paths). ``quant_pins``
    adds a ``<id>:<quant>`` row per on-disk quant of a multi-quant GGUF repo."""
    _created = int(time.time())
    # Loaded models first (clean ids + context fields), marked loaded.
    by_id: dict[str, dict] = {}
    # Off-loop: the per-entry quant probe reads the resolver index synchronously.
    for entry in await asyncio.to_thread(_openai_model_objects):
        by_id[entry["id"]] = {**entry, "loaded": True}
    orchestrator = _peek_inference_backend()
    resident_id = _orchestrator_public_model_id(orchestrator) if orchestrator else None

    # Downloaded but unloaded: GGUF via llama.cpp, other weights via the orchestrator.
    catalog = await _cached_local_catalog()
    catalog_at = _account_catalog_cache()["at"]
    rows = await asyncio.to_thread(_servable_catalog_rows, catalog, catalog_at)
    if account_access.managed_account():
        catalog = await asyncio.to_thread(account_access.filter_model_rows, catalog)
        visible = {id(info) for info in catalog}
        rows = [row for row in rows if id(row[0]) in visible]
    pins: dict[str, tuple[str, ...]] = {}
    for info, is_gguf, quants, loaded in rows:
        if account_access.resident_hidden("chat"):
            loaded = False
        cid = getattr(info, "model_id", None) or public_model_id(getattr(info, "id", None))
        if not cid:
            continue
        if is_gguf and len(quants) > 1:
            pins.setdefault(cid, quants)
        if cid in by_id:
            continue
        if loaded and not is_gguf:
            if resident_id in by_id:
                continue
        obj = {
            "id": cid,
            "object": "model",
            "created": _created,
            "owned_by": _OWNED_BY,
            "loaded": loaded,
        }
        # Resident model must advertise the quant actually loaded, not the preferred one on disk.
        resident_quant = getattr(get_llama_cpp_backend(), "hf_variant", None)
        if is_gguf and loaded and resident_quant:
            obj["quant"] = resident_quant
        elif quants:
            obj["quant"] = quants[0]
        display = getattr(info, "display_name", None)
        if display:
            obj["display_name"] = display
        by_id[cid] = obj

    media = await asyncio.to_thread(
        lambda: (
            _media_model_objects(catalog, _created, _account_catalog_cache()["at"])
            + _stt_model_objects(_created, _account_catalog_cache()["at"])
            + _audio_cpp_speech_model_objects(_created)
        )
    )
    for obj in media:
        by_id.setdefault(obj["id"], obj)

    rows = list(by_id.values())
    if quant_pins and pins:
        # Off-loop: a loaded row on a cold index reads residency from every slot.
        rows = await asyncio.to_thread(_with_quant_pin_rows, rows, pins)
    return [_with_openai_residency(entry) for entry in rows]


def _with_quant_pin_rows(objects: list[dict], pins: dict[str, tuple[str, ...]]) -> list[dict]:
    """*objects* plus, after each multi-quant repo's bare row, one ``<id>:<quant>`` row per on-disk
    quant, as ``GET /v1/models/<id>:<quant>`` returns it: dropdown clients cannot type a pin (#9340)."""
    from core.inference.local_model_resolver import (
        index_is_built,
        local_gguf_pinned_variant,
        warm_index_soon,
    )

    # Never rebuild per listing (5 s TTL, multi-root scan); build only if it never was, or a
    # client that lists once at connect sees no pins.
    allow_scan = not index_is_built()
    warm_index_soon()
    listed = {obj["id"] for obj in objects}
    resident_quants = functools.lru_cache(maxsize = 1)(_resident_gguf_quants)
    out: list[dict] = []
    for obj in objects:
        out.append(obj)
        if obj.get("task"):
            continue
        out.extend(
            _quant_pin_object(obj, quant, resident_quants)
            for quant in pins.get(obj["id"], ())
            if f"{obj['id']}:{quant}" not in listed
            and local_gguf_pinned_variant(f"{obj['id']}:{quant}", allow_scan = allow_scan) == quant
        )
    return out


@studio_router.get("/loaded-models")
async def loaded_inference_models(current_subject: str = Depends(get_current_subject)):
    """Loaded llama.cpp/orchestrator models for agent startup, without a disk catalog scan.

    Keep the public ids and context fields shared with /v1/models. The full catalog
    also discovers unloaded and media models, which an attaching coding agent does
    not need and which can take longer than its HTTP deadline on slow scan folders.
    """
    models = await asyncio.to_thread(_openai_model_objects)
    return {"object": "list", "data": [{**entry, "loaded": True} for entry in models]}


async def _openai_catalog_with_aliases(quant_pins: bool = False) -> list[dict]:
    from utils.model_aliases import alias_model_objects

    if quant_pins:
        objects = await _openai_catalog_objects(quant_pins = True)
    else:
        objects = await _openai_catalog_objects()
    aliases = await asyncio.to_thread(alias_model_objects, objects, _pinned_quant_row)
    # The rewrite gives an alias precedence, so a same-named model row would never be served.
    shadowed = {row["id"].lower() for row in aliases}
    return [o for o in objects if str(o.get("id", "")).lower() not in shadowed] + aliases


# Some OpenAI-compatible clients (notably DEVONthink) probe ``/v1/models/``
# literally and do not follow FastAPI's automatic slash redirect. Register the
# slash form directly so model discovery reaches authentication and returns the
# catalog in one response. Keep it out of the schema because it is only a wire
# compatibility alias for the canonical OpenAI path.
@router.get("/models/", include_in_schema = False)
@router.get("/models")
@in_scan_memo
async def openai_list_models(
    output_modalities: Optional[str] = None, current_subject: str = Depends(get_current_subject)
):
    """
    OpenAI-compatible model listing endpoint (``GET /v1/models``).

    Lists every model available on this server -- the loaded model(s) plus
    locally available (downloaded/cached) models -- not only what is resident in
    memory. Each entry carries a clean public id and a ``loaded`` flag.
    """
    wanted = {m.strip() for m in (output_modalities or "").split(",")}
    if not wanted & {"all", "decisions"}:
        return {"object": "list", "data": await _openai_catalog_with_aliases(quant_pins = True)}
    from routes.systemone import decision_model_objects

    data = [] if wanted == {"decisions"} else await _openai_catalog_with_aliases(quant_pins = True)
    data += await asyncio.to_thread(decision_model_objects)
    return {"object": "list", "data": data}


def _resident_gguf_quants() -> dict[str, str]:
    """Lowercased public id -> loaded quant, per slot: outside a slot get_llama_cpp_backend() is the primary."""
    resident: dict[str, str] = {}

    def _probe():
        backend = get_llama_cpp_backend()
        quant = getattr(backend, "hf_variant", None)
        public = _llama_public_model_id(backend) if backend.is_loaded else None
        return (public, quant) if public and quant else None

    for slot in (None, *model_slots.visible()):
        found = model_slots.in_slot(slot, _probe)
        if found:
            resident.setdefault(found[0].lower(), found[1])
    return resident


def _pinned_quant_object(model_id: str, objects: list[dict]) -> Optional[dict]:
    """``<listed id>:<on-disk quant>``, the same pin chat completions accept (#9340), else None."""
    from core.inference.local_model_resolver import local_gguf_pinned_variant

    base, sep, _ = model_id.rpartition(":")
    if not sep or not base:
        return None
    listed = next(
        (m for m in objects if isinstance(m.get("id"), str) and m["id"].lower() == base.lower()),
        None,
    )
    if listed is None:
        return None
    variant = local_gguf_pinned_variant(f"{listed['id']}:{model_id[len(base) + 1:]}")
    if not variant:
        return None
    return _quant_pin_object(listed, variant, _resident_gguf_quants)


def _pinned_quant_row(model_id: str, objects: list[dict]) -> Optional[dict]:
    pinned = _pinned_quant_object(model_id, objects)
    return None if pinned is None else _with_openai_residency(pinned)


def _quant_pin_object(listed: dict, variant: str, resident_quants) -> dict:
    """*listed* pinned to its on-disk *variant*: the loaded row when that quant is resident."""
    pinned_id = f"{listed['id']}:{variant}"
    if listed.get("loaded"):
        # A cold index leaves "quant" off the loaded row until it can prove the pin.
        resident = listed.get("quant") or resident_quants().get(listed["id"].lower())
        if str(resident or "").lower() == variant.lower():
            return {**listed, "id": pinned_id, "quant": variant}
    # The listed row's context fields describe the resident quant, not this one.
    shared = {
        k: listed[k]
        for k in ("object", "created", "owned_by", "display_name", "task")
        if k in listed
    }
    return {"id": pinned_id, **shared, "loaded": False, "quant": variant}


@router.get("/models/{model_id:path}")
async def openai_retrieve_model(model_id: str, current_subject: str = Depends(get_current_subject)):
    """
    OpenAI-compatible single-model retrieval endpoint (``GET /v1/models/{id}``).

    Returns the bare model object when ``model_id`` matches a known model
    (loaded or locally available), or 404 model_not_found otherwise. Defined
    after the LIST route so it does not shadow it; ``{model_id:path}`` keeps ids
    with slashes intact.
    """
    from core.inference.model_ids import model_id_matches

    # Loaded models resolve without a catalog scan (the common case); only build
    # the full catalog -- which may hit the filesystem -- for unloaded ids. Match
    # case-insensitively, like the catalog loop below and the resolver's index.
    # Off-loop like the catalog helper, and for the same sync resolver-index work.
    from utils.model_aliases import resolve_model_alias

    _loaded = await asyncio.to_thread(_openai_model_objects)
    # An alias wins over a same-named loaded model, as the request rewrite does.
    aliased = await asyncio.to_thread(resolve_model_alias, model_id)
    for entry in [] if aliased else _loaded:
        eid = entry["id"]
        if isinstance(eid, str) and eid.lower() == model_id.lower():
            return _with_openai_residency({**entry, "loaded": True})

    objects = await _openai_catalog_with_aliases()
    for model in objects:
        # Case-insensitive to match the resolver, which lowercases its index.
        mid = model.get("id")
        if isinstance(mid, str) and mid.lower() == model_id.lower():
            return model
    # Map legacy raw ids to the SAME public id /v1/models uses, without echoing the path; an auto-switch load lists a repo id, so the raw path would 404
    llama_backend = get_llama_cpp_backend()
    backend = await asyncio.to_thread(get_inference_backend)
    raw_to_public: list[tuple[str, Optional[str]]] = []
    if llama_backend.is_loaded and llama_backend.model_identifier:
        raw_to_public.append(
            (llama_backend.model_identifier, _llama_public_model_id(llama_backend))
        )
    if backend.active_model_name:
        raw_to_public.append((backend.active_model_name, _orchestrator_public_model_id(backend)))
    for raw, clean in raw_to_public:
        if model_id_matches(model_id, raw):
            for entry in _loaded:
                if entry["id"] == clean:
                    return _with_openai_residency({**entry, "loaded": True})
    pinned = await asyncio.to_thread(_pinned_quant_object, model_id, objects)
    if pinned is not None:
        return _with_openai_residency(pinned)
    raise HTTPException(
        status_code = 404,
        detail = openai_error_body(
            f"The model '{model_id}' does not exist",
            status = 404,
            code = "model_not_found",
            param = "id",
        ),
    )


# =====================================================================

# OpenAI-Compatible Completions Proxy  (/completions → /v1/completions)
# =====================================================================


def _flatten_monitor_prompt(value) -> str:
    """Flatten an OpenAI prompt/input field (str or list) into the single
    string the api_monitor prompt preview expects."""
    if isinstance(value, list):
        return "\n".join(str(part) for part in value)
    return str(value)


# Unparsable body defers to the post-switch re-read; a non-object JSON is rejected early.
_UNPARSEABLE_BODY = object()


def _completions_prompt_present(body: dict) -> bool:
    """Whether a completions body carries a usable ``prompt`` (non-empty)."""
    prompt = body.get("prompt")
    if isinstance(prompt, str):
        return prompt != ""
    if isinstance(prompt, (list, tuple)):
        return len(prompt) > 0
    return prompt is not None


def _raise_ignored_completions_params(body: dict, echo: bool = True) -> None:
    # llama-server ignores echo; an MLX model serves it, so its caller passes ``echo = False``.
    if echo and body.get("echo"):
        _raise_unsupported_openai_parameter("echo", "echo is not supported for completions.")
    if body.get("suffix"):
        _raise_unsupported_openai_parameter("suffix", "suffix is not supported for completions.")
    if body.get("best_of") not in (None, 1, _llama_value(body, "n_cmpl")):
        _raise_unsupported_openai_parameter("best_of", "best_of is not supported for completions.")


def _is_token_id(value) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _completion_prompts(prompt) -> Optional[list]:
    """The prompts in a /v1/completions ``prompt``, split as llama-server's
    ``tokenize_input_prompts`` splits it, or None for a shape it rejects. A list holding
    any token id is one prompt; any other list is one prompt per element."""
    if isinstance(prompt, (str, dict)) or (
        isinstance(prompt, list) and any(_is_token_id(p) for p in prompt)
    ):
        prompts = [prompt]
    elif isinstance(prompt, list):
        prompts = prompt
    else:
        return None
    for one in prompts:
        pieces = one.get("prompt_string") if isinstance(one, dict) else one
        if not isinstance(pieces, str) and not (
            isinstance(pieces, list) and all(isinstance(p, str) or _is_token_id(p) for p in pieces)
        ):
            return None
    return prompts


def _llama_field(body: dict, name: str, default):
    value = body.get(name)
    return default if value is None else value


def _llama_dry_off(body: dict) -> bool:
    return (
        _llama_field(body, "dry_multiplier", 0.0) == 0
        or _llama_field(body, "dry_penalty_last_n", 64) == 0
    )


def _llama_grammar_off(body: dict) -> bool:
    # llama-server converts json_schema only while the body has no "grammar" key at all.
    if "grammar" not in body:
        return body.get("json_schema") is None
    return not (isinstance(body["grammar"], str) and body["grammar"])


_LLAMA_DEFAULT_SAMPLERS = (
    ["penalties", "dry", "top_n_sigma", "top_k", "typ_p", "top_p", "min_p", "xtc", "temperature"],
    "edskypmxt",
)

# /v1/completions fields that change the text or the response shape and that MLX cannot
# reproduce, each with the test for the value that leaves it off: llama-server's own
# (tools/server/server-schema.cpp) plus OpenAI's. A field llama-server reads only while another
# is on is off with it.
_MLX_COMPLETION_FIELDS_OFF = {
    # best_of equal to the choice count asks for no hidden candidates; llama-server ignores it.
    "best_of": lambda v, b: v in (1, _llama_value(b, "n_cmpl")),
    "suffix": lambda v, b: v == "",
    # A lazy grammar waits for a trigger; this one constrains from the first token.
    "grammar_lazy": lambda v, b: v is False or _llama_grammar_off(b),
    # Ours are pre-sampler; llama-server's post_sampling_probs flips that and renames fields,
    # but only with n_probs, so refuse only together.
    "post_sampling_probs": lambda v, b: v is False or not _llama_value(b, "n_probs"),
    "timings_per_token": lambda v, b: v is False,
    "return_tokens": lambda v, b: v is False,
    "return_progress": lambda v, b: v is False,
    "verbose": lambda v, b: v is False,
    "response_fields": lambda v, b: v == [],
    "lora": lambda v, b: v == [],
    # A raw reply decodes without special tokens, so none can be kept.
    "preserved_tokens": lambda v, b: v == [],
    "n_indent": lambda v, b: v == 0,
    "t_max_predict_ms": lambda v, b: v <= 0,
    "ignore_eos": lambda v, b: v is False,
    "min_keep": lambda v, b: v == 0,
    "samplers": lambda v, b: v in _LLAMA_DEFAULT_SAMPLERS,
    "typical_p": lambda v, b: v >= 1,
    "top_n_sigma": lambda v, b: v <= 0,
    # llama-server's XTC keeps one qualifying candidate chosen by an unspecified sort order.
    "xtc_probability": lambda v, b: v <= 0 or _llama_field(b, "xtc_threshold", 0.1) > 0.5,
    "xtc_threshold": lambda v, b: v > 0.5 or _llama_field(b, "xtc_probability", 0.0) <= 0,
    "dynatemp_range": lambda v, b: v <= 0,
    "dynatemp_exponent": lambda v, b: _llama_field(b, "dynatemp_range", 0.0) <= 0,
    "mirostat": lambda v, b: v <= 0,
    "mirostat_tau": lambda v, b: _llama_field(b, "mirostat", 0) <= 0,
    "mirostat_eta": lambda v, b: _llama_field(b, "mirostat", 0) <= 0,
    "dry_multiplier": lambda v, b: _llama_dry_off(b),
    "dry_base": lambda v, b: _llama_dry_off(b),
    "dry_allowed_length": lambda v, b: _llama_dry_off(b),
    "dry_penalty_last_n": lambda v, b: _llama_dry_off(b),
    "dry_sequence_breakers": lambda v, b: _llama_dry_off(b),
    "adaptive_target": lambda v, b: v < 0,
    "adaptive_decay": lambda v, b: _llama_field(b, "adaptive_target", -1.0) < 0,
    "reasoning_budget_tokens": lambda v, b: v == -1,
}

# n_cmpl's upper bound is llama-server's slot count there; here it is chat's cap on n.
_LLAMA_HARD_LIMITS = {
    "n_predict": (-1, 2**31 - 1),
    "n_cmpl": (1, 128),
    "repeat_last_n": (0, 2**31 - 1),
}


# llama-server reads only the first non-null name of each group.
_LLAMA_ALIASES = (
    ("n_predict", "max_completion_tokens", "max_tokens"),
    ("n_cmpl", "n"),
    ("n_probs", "logprobs"),
)


def _llama_read_fields(body: dict) -> dict:
    """*body* without the aliases llama-server passes over."""
    fields = dict(body)
    for names in _LLAMA_ALIASES:
        for name in [n for n in names if body.get(n) is not None][1:]:
            del fields[name]
    return fields


def _llama_value(body: dict, name: str):
    """*name*, or the alias of it llama-server reads."""
    names = next((group for group in _LLAMA_ALIASES if group[0] == name), (name,))
    return next((body[n] for n in names if body.get(n) is not None), None)


# llama-server's defaults for the fields no pin or per-model recommendation sets, so an MLX
# model samples a request as the GGUF route's llama-server would.
_LLAMA_SAMPLING_DEFAULTS = {
    "temperature": 0.8,
    "top_p": 0.95,
    "top_k": 40,
    "min_p": 0.05,
    "repetition_penalty": 1.0,
    "presence_penalty": 0.0,
}


def _llama_logit_bias(raw) -> Optional[dict]:
    """llama-server's ``logit_bias`` (an object or ``[token, bias]`` pairs; ``false`` bans the
    token) as ``{token id: bias}``. Raises ValueError for a token given as text, which needs
    the tokenizer."""
    if isinstance(raw, dict):
        pairs = list(raw.items())
    elif isinstance(raw, list):
        pairs = [p for p in raw if isinstance(p, list) and len(p) == 2]
    else:
        return None
    bias = {}
    for token, value in pairs:
        if isinstance(token, str) and token.lstrip("-").isdigit() and isinstance(raw, dict):
            token = int(token)
        if not _is_token_id(token):
            raise ValueError("logit_bias tokens given as text are not supported for MLX models.")
        if value is False:
            bias[token] = float("-inf")
        elif isinstance(value, (int, float)) and not isinstance(value, bool):
            bias[token] = bias.get(token, 0.0) + float(value)
    return bias or None


def _mlx_completion_grammar(body: dict) -> Optional[str]:
    """The llguidance grammar constraining a /v1/completions body, read in llama-server's
    precedence, with ``response_format`` (which llama-server ignores here) honored last.
    Raises ResponseFormatError for one that does not compile."""
    from core.inference.grammar_constraint import (
        ResponseFormatError,
        constraint_spec_from_response_format,
        grammar_from_gbnf,
        grammar_from_json_schema,
    )

    if "grammar" in body:
        gbnf = body["grammar"]
        if gbnf is not None and not isinstance(gbnf, str):
            raise ResponseFormatError("'grammar' must be a GBNF string.")
        return grammar_from_gbnf(gbnf) if gbnf else None
    schema = body.get("json_schema")
    if schema is not None:
        if not isinstance(schema, dict):
            raise ResponseFormatError("'json_schema' must be a JSON Schema object.")
        # llama.cpp reads an empty schema as any object, llguidance as any value.
        return grammar_from_json_schema(schema or {"type": "object"})
    spec = constraint_spec_from_response_format(body.get("response_format"))
    return spec.grammar if spec is not None else None


def _mlx_completions_refusal(body: dict) -> Optional[str]:
    """Why an MLX model cannot serve this /v1/completions body as llama-server would, or None."""
    prompts = _completion_prompts(body.get("prompt"))
    if not prompts:
        return (
            "'prompt' must be a string, a list of strings and token ids, a "
            '{"prompt_string": ...} object, or an array of those.'
        )
    if any(isinstance(p, dict) and p.get("multimodal_data") for p in prompts):
        return "'multimodal_data' is not supported for MLX models; send images to /v1/chat/completions."
    fields = _llama_read_fields(body)
    for name, off in _MLX_COMPLETION_FIELDS_OFF.items():
        value = fields.get(name)
        try:
            neutral = value is None or bool(off(value, fields))
        except (TypeError, ValueError):
            neutral = False
        if not neutral:
            return f"'{name}' is not supported for MLX models."
    for name, (low, high) in _LLAMA_HARD_LIMITS.items():
        value = _llama_value(body, name)
        if value is not None and not (_is_token_id(value) and low <= value <= high):
            return (
                f"Field '{name}': Value must be between {low} <= value <= {high}, but got {value}"
            )
    if body.get("stream") is True and len(prompts) * (_llama_value(body, "n_cmpl") or 1) > 1:
        return "Streaming more than one completion is not supported for MLX models."
    n_probs = _llama_value(body, "n_probs")
    if n_probs not in (None, False) and not (_is_token_id(n_probs) and n_probs >= 0):
        return f"Field 'n_probs': Value must be a non-negative integer, but got {n_probs}"
    if n_probs:
        # Only the reported tokens: a prompt's own logprobs (echo) are not computed.
        if body.get("stream") is True:
            return "'logprobs' is not supported with stream for MLX models."
        if body.get("echo") is True:
            return "'logprobs' is not supported with echo for MLX models."
        if len(prompts) * (_llama_value(body, "n_cmpl") or 1) > 1:
            return "'logprobs' is supported for one completion per request on MLX models."
    try:
        _llama_logit_bias(body.get("logit_bias"))
        _mlx_completion_grammar(body)
    except ValueError as exc:
        return str(exc)
    return None


def _active_mlx_backend():
    """The orchestrator while it holds an MLX model, else None."""
    backend = _peek_inference_backend()
    name = getattr(backend, "active_model_name", None)
    models = getattr(backend, "models", None)
    if name and isinstance(models, dict) and models.get(name, {}).get("is_mlx"):
        return backend
    return None


def _active_managed_engine_backend():
    backend = _peek_inference_backend()
    name = getattr(backend, "active_model_name", None)
    models = getattr(backend, "models", None)
    engine = getattr(backend, "_managed_engine", None)
    if (
        engine is not None
        and name
        and isinstance(models, dict)
        and models.get(name, {}).get("engine") in ("vllm", "sglang")
        and engine.alive()
    ):
        return backend
    return None


def _mlx_completion_sampling(body: dict, model_id) -> dict:
    """``generate_completion`` knobs for a /v1/completions body, read as llama-server reads
    them: its field names and aliases, its clamps, and its defaults for anything unset."""
    from utils.inference.inference_config import resolve_effective_sampling, SAMPLING_FIELD_NAMES

    explicit = {f: body.get(_COMPLETIONS_SAMPLING_BODY_KEY.get(f, f)) for f in SAMPLING_FIELD_NAMES}
    sampling = {
        **_LLAMA_SAMPLING_DEFAULTS,
        **resolve_effective_sampling(model_id, explicit, fill_defaults = False),
    }
    seed = body.get("seed")
    top_p = min(max(float(sampling["top_p"]), 0.0), 1.0)
    return dict(
        temperature = max(0.0, float(sampling["temperature"])),
        top_p = top_p,
        # llama-server's top-p keeps its one minimum candidate at p = 0; MLX reads 0 as off.
        top_k = 1 if top_p == 0 else max(0, int(sampling["top_k"])),
        min_p = min(max(float(sampling["min_p"]), 0.0), 1.0),
        repetition_penalty = float(sampling["repetition_penalty"]),
        presence_penalty = float(sampling["presence_penalty"]),
        frequency_penalty = float(_llama_field(body, "frequency_penalty", 0.0)),
        # llama-server draws a random seed for LLAMA_DEFAULT_SEED (0xFFFFFFFF, e.g. -1).
        seed = None if seed is None or (int(seed) & 0xFFFFFFFF) == 0xFFFFFFFF else int(seed),
        logit_bias = _llama_logit_bias(body.get("logit_bias")),
        stop = _normalize_stop_sequences(body.get("stop")),
        penalty_window = _llama_field(body, "repeat_last_n", 64),
        grammar = _mlx_completion_grammar(body),
    )


def _mlx_completion_error(failure, message: str, body: dict) -> tuple:
    """A failed MLX completion's status and OpenAI error body, typed as chat types them."""
    if isinstance(failure, context_refusal.ContextBudgetExceeded):
        code, param = "context_length_exceeded", "prompt"
    else:
        code, param = "unsupported_parameter", _refused_parameter(failure)
    if param == "response_format":
        # Name the field the grammar came from, in _mlx_completion_grammar's precedence.
        if "grammar" in body:
            param = "grammar"
        elif body.get("json_schema") is not None:
            param = "json_schema"
    if param is None:
        return 500, {"error": {"message": message, "type": "server_error"}}
    return 400, openai_error_body(message, status = 400, code = code, param = param)


def _text_completion_chunk(completion_id, created, model_name, text, finish_reason) -> dict:
    return {
        "id": completion_id,
        "object": "text_completion",
        "created": created,
        "model": model_name,
        "choices": [{"text": text, "index": 0, "logprobs": None, "finish_reason": finish_reason}],
    }


async def _mlx_completions(request, current_subject, backend, body: dict, refusal):
    """Serve /v1/completions from the resident MLX model: one prompt, untemplated."""
    if refusal:
        raise HTTPException(
            status_code = 400,
            detail = openai_error_body(refusal, status = 400, code = "unsupported_parameter"),
        )
    n_predict = _llama_value(body, "n_predict")
    budget = None if n_predict == -1 else n_predict
    n = _llama_value(body, "n_cmpl") or 1
    stream_options = body.get("stream_options")
    include_usage = isinstance(stream_options, dict) and stream_options.get("include_usage") is True
    try:
        model_name = _orchestrator_public_model_id(backend) or backend.active_model_name
        sampling = _mlx_completion_sampling(body, model_name)
    except (TypeError, ValueError) as exc:
        raise HTTPException(
            status_code = 400,
            detail = openai_error_body(f"Invalid sampling parameter: {exc}", status = 400),
        )
    completion_id = f"cmpl-{uuid.uuid4().hex}"
    cancel_event = threading.Event()
    # Resolving waits behind a running generation, so the request is cancellable from here on.
    tracker = _TrackedCancel(cancel_event, completion_id, model = model_name, kind = "completions")
    tracker.__enter__()
    watcher = asyncio.create_task(_await_disconnect_then_cancel(request, cancel_event))
    try:
        # Every prompt first (an invalid one is a 400), tracked until a cancel ends the thread.
        resolved = await _run_blocking_generation(
            lambda: [
                backend.resolve_completion_prompt(prompt, cancel_event = cancel_event)
                for prompt in _completion_prompts(body["prompt"])
            ],
            cancel_event,
            name = "openai-completions-prompt",
        )
    except BaseException as exc:
        tracker.__exit__(None, None, None)
        if isinstance(exc, InterruptedError):
            raise HTTPException(status_code = 499, detail = "Request cancelled.")
        if not isinstance(exc, ValueError):
            raise
        raise HTTPException(
            status_code = 400,
            detail = openai_error_body(str(exc), status = 400, param = "prompt"),
        )
    finally:
        await _stop_local_disconnect_cancel_watcher(watcher)
    n_vocab = resolved[0].get("n_vocab")
    if n_vocab and sampling["top_k"] >= n_vocab:
        # llama-server keeps every candidate here; mlx_lm's apply_top_k raises instead.
        sampling["top_k"] = 0
    echo = body.get("echo") is True
    created = int(time.time())
    stats_holder: dict = {}
    monitor_id = api_monitor.start(
        endpoint = request.url.path,
        via_api_key = _request_used_api_key(request),
        method = request.method,
        model = model_name,
        prompt = resolved[0]["text"]
        if len(resolved) == 1
        else "\n\n".join(f"Prompt {i + 1}:\n{r['text']}" for i, r in enumerate(resolved)),
        context_length = _monitor_context_length(),
        subject = current_subject,
    )

    n_probs = _llama_value(body, "n_probs") or 0

    def generate(prompt_ids, choice = 0):
        return backend.generate_completion(
            prompt_ids,
            cancel_event = cancel_event,
            stats_holder = stats_holder,
            max_new_tokens = budget,
            **{**sampling, "seed": _choice_seed(sampling["seed"], choice)},
            **({"n_probs": n_probs} if n_probs else {}),
        )

    def choice_end(prompt_ids, stats):
        if budget == 0:
            reason = "length"
        elif cancel_event.is_set():
            reason = "stop"
        else:
            reason = _stats_finish_reason(stats, token_budget = budget)
        usage = (stats or {}).get("usage") or {
            "prompt_tokens": len(prompt_ids),
            "completion_tokens": 0,
            "total_tokens": len(prompt_ids),
        }
        return reason, usage

    if body.get("stream") is True:
        prompt_ids = resolved[0]["ids"]

        def sse(obj) -> str:
            return f"data: {json.dumps(obj)}\n\n"

        async def stream_chunks():
            gen = None
            next_task = None
            watcher = asyncio.create_task(_await_disconnect_then_cancel(request, cancel_event))
            try:
                from core.inference.llama_keepwarm import mark_current_response_failed

                if echo:
                    yield sse(
                        _text_completion_chunk(
                            completion_id, created, model_name, resolved[0]["text"], None
                        )
                    )
                _DONE = object()
                gen = generate(prompt_ids) if budget != 0 else iter(())
                gen_step = ThreadStepper(gen).next
                prev = ""
                while True:
                    if cancel_event.is_set():
                        break
                    next_task = asyncio.create_task(gen_step(_DONE))
                    while not (
                        await asyncio.wait(
                            {next_task}, timeout = _LOCAL_TOOL_STREAM_STALL_KEEPALIVE_S
                        )
                    )[0]:
                        yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                    cumulative, next_task = next_task.result(), None
                    if cumulative is _DONE:
                        break
                    if isinstance(cumulative, GenStreamError):
                        backend.reset_generation_state(cancel_event)
                        message = _friendly_gen_stream_error(cumulative)
                        api_monitor.fail(monitor_id, message)
                        yield _openai_stream_error_sse(
                            _mlx_completion_error(cumulative, message, body)[1]
                        )
                        return
                    delta, prev = cumulative[len(prev) :], cumulative
                    if delta:
                        api_monitor.append_reply(monitor_id, delta)
                        yield sse(
                            _text_completion_chunk(completion_id, created, model_name, delta, None)
                        )
                if cancel_event.is_set():
                    backend.reset_generation_state(cancel_event)
                    mark_current_response_failed()
                stats = stats_holder.pop("stats", None)
                reason, usage = choice_end(prompt_ids, stats)
                api_monitor.set_perf(monitor_id, stop_reason = reason)
                _monitor_usage(monitor_id, usage, timings = (stats or {}).get("timings"))
                yield sse(_text_completion_chunk(completion_id, created, model_name, "", reason))
                if include_usage:
                    yield sse(
                        {
                            **_text_completion_chunk(completion_id, created, model_name, "", None),
                            "choices": [],
                            "usage": usage,
                        }
                    )
                api_monitor.finish(
                    monitor_id, "cancelled" if cancel_event.is_set() else "completed"
                )
                yield "data: [DONE]\n\n"
            except asyncio.CancelledError:
                cancel_event.set()
                backend.reset_generation_state(cancel_event)
                api_monitor.finish(monitor_id, "cancelled")
                raise
            except Exception as exc:
                backend.reset_generation_state(cancel_event)
                logger.error("MLX completions stream error: %s", exc, exc_info = True)
                message = _friendly_error(exc)
                api_monitor.fail(monitor_id, message)
                yield _openai_stream_error_sse(_mlx_completion_error(exc, message, body)[1])
            finally:
                await _stop_local_disconnect_cancel_watcher(watcher)
                await _drain_pending_worker(next_task, cancel_event)
                if gen is not None and hasattr(gen, "close"):
                    try:
                        await asyncio.to_thread(gen.close)
                    except (RuntimeError, ValueError):
                        pass
                tracker.__exit__(None, None, None)

        async def unstarted_cleanup():
            api_monitor.finish(monitor_id, "cancelled")
            tracker.__exit__(None, None, None)

        return _sse_streaming_response(stream_chunks(), unstarted_cleanup = unstarted_cleanup)

    # llama-server's order: each prompt's n choices in turn, choice j seeded as chat seeds it.
    rows = [
        {"prompt_ids": resolved[i // n]["ids"], "seed": _choice_seed(sampling["seed"], i % n)}
        for i in range(len(resolved) * n)
    ]

    def drain_rows(chunk):
        texts, batch_stats = [""] * len(chunk), {}
        if len(rows) == 1:
            events = (
                text if isinstance(text, GenStreamError) else (0, text)
                for text in generate(chunk[0]["prompt_ids"])
            )
        else:
            events = backend.generate_completion_batch(
                chunk,
                cancel_event = cancel_event,
                stats_holder = batch_stats,
                max_new_tokens = budget,
                **{k: v for k, v in sampling.items() if k != "seed"},
            )
        for event in events:
            if isinstance(event, GenStreamError):
                return event
            row, text = event
            if text is not None:
                texts[row] = text
        reported = (
            [stats_holder.pop("stats", None)] if len(rows) == 1 else batch_stats.get("stats") or []
        )
        return [
            (text, reported[row] if row < len(reported) else None) for row, text in enumerate(texts)
        ]

    def drain():
        """At most chat's n cap per batch, so many prompts cannot exhaust memory."""
        produced, width = [], _LLAMA_HARD_LIMITS["n_cmpl"][1]
        for start in range(0, len(rows), width):
            chunk = rows[start : start + width]
            if cancel_event.is_set() and produced:
                produced += [("", None)] * len(chunk)
                continue
            result = drain_rows(chunk)
            if isinstance(result, GenStreamError):
                return result
            produced += result
        return produced

    choices, replies, stats = [], [], None
    prompt_tokens = completion_tokens = 0
    cached_tokens: Optional[int] = None
    failure = None
    watcher = asyncio.create_task(_await_disconnect_then_cancel(request, cancel_event))
    try:
        produced = (
            [("", None)] * len(rows)
            if budget == 0 or cancel_event.is_set()
            else await _run_blocking_generation(drain, cancel_event, name = "openai-completions")
        )
        if isinstance(produced, GenStreamError):
            failure, produced = produced, []
        for index, (text, stats) in enumerate(produced):
            prompt_index, choice = divmod(index, n)
            reason, usage = choice_end(resolved[prompt_index]["ids"], stats)
            if not choice:
                prompt_tokens += usage["prompt_tokens"]
                cached = cached_prompt_tokens(usage)
                if cached is not None:
                    cached_tokens = (cached_tokens or 0) + cached
            completion_tokens += usage["completion_tokens"]
            prefix = resolved[prompt_index]["text"] if echo else ""
            token_logprobs = (stats or {}).get("token_logprobs") if n_probs else None
            choices.append(
                {
                    "text": prefix + text,
                    "index": index,
                    # llama-server's shape, null when nothing was generated.
                    "logprobs": {"content": token_logprobs} if token_logprobs else None,
                    "finish_reason": reason,
                }
            )
            replies.append(text)
    except asyncio.CancelledError:
        backend.reset_generation_state(cancel_event)
        api_monitor.finish(monitor_id, "cancelled")
        raise
    except Exception as exc:
        failure = exc
    finally:
        await _stop_local_disconnect_cancel_watcher(watcher)
        tracker.__exit__(None, None, None)
    if failure is not None:
        backend.reset_generation_state(cancel_event)
        message = (
            _friendly_gen_stream_error(failure)
            if isinstance(failure, GenStreamError)
            else _friendly_error(failure)
        )
        api_monitor.fail(monitor_id, message)
        status, error = _mlx_completion_error(failure, message, body)
        raise HTTPException(status_code = status, detail = message if status == 500 else error)
    usage = {
        "prompt_tokens": prompt_tokens,
        "completion_tokens": completion_tokens,
        "total_tokens": prompt_tokens + completion_tokens,
    }
    if cached_tokens is not None:
        usage["prompt_tokens_details"] = {"cached_tokens": cached_tokens}
    single = len(choices) == 1
    api_monitor.set_reply(
        monitor_id,
        replies[0]
        if single
        else "\n\n".join(f"Choice {i + 1}:\n{r}" for i, r in enumerate(replies)),
    )
    # One choice's reason and timings would misdescribe several.
    if single:
        api_monitor.set_perf(monitor_id, stop_reason = choices[0]["finish_reason"])
    _monitor_usage(monitor_id, usage, timings = (stats or {}).get("timings") if single else None)
    if cancel_event.is_set():
        from core.inference.llama_keepwarm import mark_current_response_failed
        mark_current_response_failed()
    api_monitor.finish(monitor_id, "cancelled" if cancel_event.is_set() else "completed")
    return {
        **_text_completion_chunk(completion_id, created, model_name, "", None),
        "choices": choices,
        "usage": usage,
    }


@router.post("/completions")
@account_access.gpu_busy_route
async def openai_completions(request: Request, current_subject: str = Depends(get_current_subject)):
    """
    OpenAI-compatible text completions endpoint (non-chat).

    Proxies to the running llama-server's ``/v1/completions`` when a GGUF model is
    loaded or to a managed vLLM/SGLang engine's, and serves an MLX model in process.
    """
    from utils.hardware import DeviceType, get_device

    try:
        _pre = await request.json()
    except (json.JSONDecodeError, ValueError):
        _pre = _UNPARSEABLE_BODY
    _mlx_device = await asyncio.to_thread(get_device) == DeviceType.MLX
    # MLX hosts only; grammar compiles off the event loop, as chat's does.
    _mlx_refusal = (
        await asyncio.get_running_loop().run_in_executor(
            _SCHEMA_VALIDATION_EXECUTOR, _mlx_completions_refusal, _pre
        )
        if _mlx_device and isinstance(_pre, dict)
        else None
    )

    # Reject a request with no prompt before any automatic load so an invalid request never
    # swaps or reloads the resident model (as chat/embeddings already validate before
    # switching). Gate on every automatic-load trigger, and on a preview-owned slot the switch
    # helper would claim even with both features off.
    if _should_validate_before_switch():
        if isinstance(_pre, dict):
            _pre_prompt = _pre.get("prompt")
            if _pre_prompt is not None and not (
                isinstance(_pre_prompt, (str, list, tuple))
                or (isinstance(_pre_prompt, dict) and "prompt_string" in _pre_prompt)
            ):
                # Any other prompt is a deterministic client error; reject it before the
                # switch so a bad shape can't load a model only to be rejected after.
                raise HTTPException(
                    status_code = 400,
                    detail = "'prompt' must be a string, an array or a {\"prompt_string\": ...} object.",
                )
            if not _completions_prompt_present(_pre):
                raise HTTPException(status_code = 400, detail = "'prompt' is required for completions.")
            # A resident managed engine serves echo; a switch to a GGUF still refuses it below.
            _raise_ignored_completions_params(
                _pre, echo = not (_mlx_device or _active_managed_engine_backend() is not None)
            )
        elif _pre is not _UNPARSEABLE_BODY:
            # Reject before the switch so the slot claim can't take a preview-owned model.
            raise HTTPException(status_code = 400, detail = "Request body must be a JSON object")

    # Opt-in: load the requested local model before the loaded-state check. Only an MLX model
    # serves a raw prompt in process, and only a request it can serve as llama-server would.
    body = await _auto_switch_from_request_body(
        request,
        current_subject,
        gguf_only = _mlx_refusal is not None or not _mlx_device,
        gguf_only_reason = _mlx_refusal,
        # echo, which the check above left to the target: a GGUF one refuses it unloaded.
        gguf_target_check = (
            (lambda: _raise_ignored_completions_params(_pre)) if isinstance(_pre, dict) else None
        ),
        audio_cpp_ok = False,
    )
    llama_backend = get_llama_cpp_backend()
    mlx_backend = None if llama_backend.is_loaded else _active_mlx_backend()
    engine_backend = (
        None
        if llama_backend.is_loaded or mlx_backend is not None
        else _active_managed_engine_backend()
    )
    if not llama_backend.is_loaded and mlx_backend is None and engine_backend is None:
        _status, _detail = await _no_model_loaded_error(
            "No GGUF model loaded. Load a GGUF model first.",
            _raw_body_model(body),
            request,
            status = 503,
        )
        raise HTTPException(status_code = _status, detail = _detail)
    if not isinstance(body, dict):
        # Re-read to re-raise a malformed-body error; a valid non-dict body gets a clean 400.
        body = await request.json()
        if not isinstance(body, dict):
            raise HTTPException(status_code = 400, detail = "Request body must be a JSON object")
    if mlx_backend is not None:
        refusal = await asyncio.get_running_loop().run_in_executor(
            _SCHEMA_VALIDATION_EXECUTOR, _mlx_completions_refusal, body
        )
        return await _mlx_completions(request, current_subject, mlx_backend, body, refusal)
    if engine_backend is not None:
        _raise_ignored_completions_params(body, echo = False)
        from routes.managed_engine_chat import managed_engine_completions
        return await managed_engine_completions(request, current_subject, engine_backend, body)
    _raise_ignored_completions_params(body)

    # No claim here: middleware claims on 2xx, and llama-server can still non-2xx a valid body, which would strand a preview-owned model as Unsloth-owned

    _resolved_max_tokens = _effective_openai_max_tokens_from_values(body.get("max_tokens"))
    body["max_tokens"] = (
        _resolved_max_tokens
        if _resolved_max_tokens is not None
        else (llama_backend.context_length or _DEFAULT_MAX_TOKENS_FLOOR)
    )
    # Apply recommended sampling and any UNSLOTH_SAMPLING_* operator pin so /v1/completions honors the same pins as chat; otherwise it is a verbatim proxy
    _fill_recommended_sampling_completions(body, getattr(llama_backend, "model_identifier", None))
    is_stream = body.get("stream", False)
    prompt_text = _flatten_monitor_prompt(body.get("prompt", ""))
    monitor_model = _monitor_active_model() or str(
        body.get("model") or _llama_public_model_id(llama_backend) or "default"
    )
    monitor_id = api_monitor.start(
        endpoint = request.url.path,
        via_api_key = _request_used_api_key(request),
        method = request.method,
        model = monitor_model,
        prompt = prompt_text,
        context_length = llama_backend.context_length,
        subject = current_subject,
    )

    if is_stream:

        async def _stream():
            # Manual httpx lifecycle + explicit iterator close; see _anthropic_passthrough_stream.
            # Buffer whole SSE events so ids and include_usage can be rewritten per event.
            _include_usage = bool((body.get("stream_options") or {}).get("include_usage"))
            # Always request usage internally; _cmpl_stream_event_out filters it per the caller's opt-in.
            upstream_body = dict(body)
            _client_wants_progress = bool(body.get("return_progress"))
            upstream_body["return_progress"] = True
            upstream_stream_options = dict(body.get("stream_options") or {})
            upstream_stream_options["include_usage"] = True
            upstream_body["stream_options"] = upstream_stream_options
            _keepalive_s = _openai_passthrough_stream_keepalive_interval()
            from core.inference.llama_cpp import LlamaCppBackend
            from core.inference.llama_keepwarm import mark_response_failed

            client = _llama_stream_client()
            resp = None
            bytes_iter = None
            items_iter = None
            disconnect_event = threading.Event()
            disconnect_watcher = None
            # Register with the swap gate or a non-forced /unload tears the server down mid-response.
            # Entered inside the body generator so an unstarted body leaves nothing behind.
            _tracker = _TrackedCancel(disconnect_event, model = monitor_model, kind = "completions")
            _tracker.__enter__()
            # Must stay the last statement before the try: a raise in between leaks a permanent +1.
            _direct_llama_request_started()
            try:
                # Same event the relay loop polls, so a forced swap ends the request during prefill
                # instead of only once headers arrive.
                upstream = _LlamaUpstream(llama_backend, "/v1/completions")
                async with aclosing(
                    upstream.stream_response(client, upstream_body, disconnect_event, request)
                ) as opening:
                    async for opened in opening:
                        if opened is _LLAMA_STREAM_KEEPALIVE:
                            yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE.encode()
                        else:
                            resp = opened
                first_token_deadline = upstream.first_token_deadline
                if resp is None:
                    api_monitor.finish(monitor_id, "cancelled")
                    return
                if resp.status_code != 200:
                    err_bytes = await resp.aread()
                    err_text = err_bytes.decode("utf-8", errors = "replace")
                    api_monitor.fail(monitor_id, err_text[:500])
                    raise RuntimeError(f"llama-server returned {resp.status_code}: {err_text}")
                disconnect_watcher = asyncio.create_task(
                    _await_disconnect_then_close(request, resp, disconnect_event)
                )
                bytes_iter = resp.aiter_bytes()
                buffer = b""
                # Bound, not inlined: teardown must aclose() this before bytes_iter.
                items_iter = _aiter_llama_stream_items(
                    bytes_iter,
                    cancel_event = disconnect_event,
                    request = request,
                    first_token_deadline = first_token_deadline,
                    response = resp,
                    track_prefill_progress = True,
                    keepalive_interval_s = _keepalive_s,
                )
                progress_keepalive = _ProgressKeepalive(_keepalive_s)
                async for chunk in items_iter:
                    # Out of `buffer`: the split below would hand it to the monitor.
                    if chunk is _LLAMA_STREAM_KEEPALIVE:
                        yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE.encode()
                        continue
                    buffer += chunk
                    while b"\n\n" in buffer:
                        event, buffer = buffer.split(b"\n\n", 1)
                        if (
                            _monitor_openai_sse_event(
                                monitor_id,
                                event,
                                llama_backend.context_length,
                            )
                            == "error"
                        ):
                            # HTTP-200 SSE error: flag failed so the middleware does not claim the slot.
                            mark_response_failed(getattr(request, "scope", None))
                        if (
                            not _client_wants_progress
                            and b'"prompt_progress"' in event
                            and _is_prefill_progress_only(
                                LlamaCppBackend._sse_event_payload(event.decode("utf-8", "replace"))
                            )
                        ):
                            if progress_keepalive.due():
                                yield _OPENAI_PREFILL_PROGRESS_SSE.encode()
                            continue
                        out = _cmpl_stream_event_out(event, _include_usage)
                        if out is not None:
                            yield out + b"\n\n"
                if not disconnect_event.is_set() and buffer:
                    if (
                        _monitor_openai_sse_event(
                            monitor_id,
                            buffer,
                            llama_backend.context_length,
                        )
                        == "error"
                    ):
                        mark_response_failed(getattr(request, "scope", None))
                    out = _cmpl_stream_event_out(buffer, _include_usage)
                    if out is not None:
                        # Re-add the separator the split consumed so a final event is terminated.
                        yield out + b"\n\n"
                if disconnect_event.is_set():
                    mark_response_failed(getattr(request, "scope", None))
                    api_monitor.finish(monitor_id, "cancelled")
                    return
                api_monitor.finish(monitor_id)
            except (httpx.RemoteProtocolError, httpx.ReadError, httpx.CloseError) as e:
                if not disconnect_event.is_set():
                    logger.error("openai_completions stream error: %s", e)
                    api_monitor.fail(monitor_id, _friendly_error(e))
                    error_chunk = _openai_stream_error_chunk(e)
                    yield _openai_stream_error_sse_bytes(error_chunk)
                    return
                mark_response_failed(getattr(request, "scope", None))
                api_monitor.finish(monitor_id, "cancelled")
                return
            except asyncio.CancelledError:
                disconnect_event.set()
                api_monitor.finish(monitor_id, "cancelled")
                raise
            except Exception as e:
                if disconnect_event.is_set():
                    mark_response_failed(getattr(request, "scope", None))
                    api_monitor.finish(monitor_id, "cancelled")
                    return
                logger.error("openai_completions stream error: %s", e)
                api_monitor.fail(monitor_id, _friendly_error(e))
                error_chunk = _openai_stream_error_chunk(e)
                yield _openai_stream_error_sse_bytes(error_chunk)
                return
            finally:
                # Nested so a close-time failure still unregisters; a phantom entry 409s swaps.
                try:
                    await _aclose_stream_resources(
                        watchers = (disconnect_watcher,),
                        items = items_iter,
                        iterator = bytes_iter,
                        resp = resp,
                        client = client,
                    )
                finally:
                    _direct_llama_request_finished()
                    _tracker.__exit__(None, None, None)

        return _sse_streaming_response(_stream(), monitor_id = monitor_id)
    else:
        async with _monitored_llama_call(
            llama_backend,
            "/v1/completions",
            request = request,
            monitor_id = monitor_id,
            model = monitor_model,
            kind = "completions",
        ) as upstream:
            resp = await upstream.post(body, timeout = _llama_non_streaming_generation_timeout())

        if resp.status_code != 200:
            api_monitor.fail(monitor_id, resp.text[:500])
            raise _openai_passthrough_error(resp.status_code, resp.text)
        try:
            _monitor_openai_chunk(monitor_id, resp.json(), llama_backend.context_length)
        except Exception:
            pass
        api_monitor.finish(monitor_id)

        return Response(
            content = _rewrite_cmpl_id(resp.content),
            status_code = resp.status_code,
            media_type = "application/json",
        )


# =====================================================================

# OpenAI-Compatible Embeddings Proxy  (/embeddings → /v1/embeddings)
# =====================================================================


_STUDIO_EMBED_CONCURRENCY = 4
_STUDIO_EMBED_MAX_INPUTS = 2048
_studio_embed_semaphores: "weakref.WeakKeyDictionary" = weakref.WeakKeyDictionary()
_studio_embed_semaphores_guard = threading.Lock()


def _studio_embed_semaphore() -> asyncio.Semaphore:
    loop = asyncio.get_running_loop()
    with _studio_embed_semaphores_guard:
        semaphore = _studio_embed_semaphores.get(loop)
        if semaphore is None:
            semaphore = _studio_embed_semaphores[loop] = asyncio.Semaphore(
                _STUDIO_EMBED_CONCURRENCY
            )
        return semaphore


def _resident_serves_embeddings(llama_backend) -> bool:
    return bool(llama_backend.is_loaded and getattr(llama_backend, "is_embedding_gguf", True))


def _embeddings_items(body: dict, *, tokens_ok: bool) -> list:
    value = body.get("input")
    if isinstance(value, str):
        items = [value]
    # `type(...) is int`, not isinstance: bool subclasses int.
    elif (
        tokens_ok
        and isinstance(value, list)
        and value
        and all(type(token) is int for token in value)
    ):
        items = [value]
    elif isinstance(value, (list, tuple)):
        items = list(value)
    else:
        items = []
    if not items:
        raise HTTPException(status_code = 400, detail = "'input' is required for embeddings.")
    if not tokens_ok and len(items) > _STUDIO_EMBED_MAX_INPUTS:
        raise HTTPException(
            status_code = 400,
            detail = f"'input' may hold at most {_STUDIO_EMBED_MAX_INPUTS} items.",
        )

    def _ok(item) -> bool:
        if isinstance(item, str):
            return bool(item)
        return (
            tokens_ok
            and isinstance(item, list)
            and bool(item)
            and all(type(token) is int for token in item)
        )

    if not all(_ok(item) for item in items):
        raise HTTPException(
            status_code = 400,
            detail = "'input' must be a non-empty string or an array of non-empty strings.",
        )
    encoding_format = body.get("encoding_format")
    if encoding_format is not None and encoding_format not in ("float", "base64"):
        raise HTTPException(
            status_code = 400, detail = "'encoding_format' must be 'float' or 'base64'."
        )
    _embeddings_truncate(body)
    return items


def _embeddings_truncate(body: dict) -> bool:
    """``truncate`` (Ollama / TEI spelling), default on (#14309)."""
    truncate = body.get("truncate", True)
    if not isinstance(truncate, bool):
        raise HTTPException(status_code = 400, detail = "'truncate' must be a boolean.")
    return truncate


def _embeddings_texts(body: dict) -> list[str]:
    return _embeddings_items(body, tokens_ok = False)


def _public_embedding_name(model_name: str) -> str:
    """Basename alone collides: checkpoints in different dirs can be different embedding spaces."""
    from utils.paths import is_local_path

    if not is_local_path(model_name):
        return model_name
    import hashlib

    normalized = model_name.replace("\\", "/").rstrip("/")
    base = normalized.rsplit("/", 1)[-1] or "model"
    return f"{base}-{hashlib.sha256(normalized.encode('utf-8')).hexdigest()[:8]}"


def _public_embedding_identity(identity: str, model_name: str, label: str) -> str:
    """Redacts whole segments only; a substring replace would also rewrite sentence-transformers."""
    from core.rag.config import (
        EMBEDDING_IDENTITY_TAGS,
        _escape_identity_segment,
        _unescape_identity_segment,
        effective_gguf_repo_for_embedding_model,
    )
    from utils.paths import is_local_path

    tag = next((t for t in EMBEDDING_IDENTITY_TAGS if identity.startswith(f"{t}:")), None)
    if tag is None:
        return identity
    repo = effective_gguf_repo_for_embedding_model(model_name)
    # Check both: a hub id GGUF companion can be a local path (RAG_EMBED_GGUF_REPO or a stored repo), and that path is a segment of the identity too
    if not is_local_path(model_name) and not is_local_path(repo):
        return identity
    public = {model_name: label, repo: _public_embedding_name(repo)}
    segments = [_unescape_identity_segment(s) for s in identity[len(tag) + 1 :].split(":")]
    redacted = [_escape_identity_segment(public.get(s, s)) for s in segments]
    return ":".join([tag, *redacted])


def _embedding_payload(vector, encoding_format: str):
    if encoding_format == "base64":
        import base64
        import numpy as np
        return base64.b64encode(np.asarray(vector, dtype = np.float32).tobytes()).decode("ascii")
    return [float(x) for x in vector]


def _names_studio_embedder(requested: str) -> Optional[str]:
    from core.rag import config as rag_config
    from core.rag import embeddings as rag_embeddings
    from utils.paths import is_local_path

    model = rag_config.effective_embedding_model()
    repo = rag_config.effective_gguf_repo_for_embedding_model(model)
    label = _public_embedding_name(model)
    wanted = requested.strip()
    if rag_config.embedding_identity_model(wanted) is not None:
        current = rag_embeddings.embedding_identity(model)
        if wanted in (current, _public_embedding_identity(current, model, label)):
            return model
        return None
    for name in (model, repo, label, _public_embedding_name(repo)):
        if not name:
            continue
        if is_local_path(name) or is_local_path(wanted):
            if wanted == name:
                return model
        elif wanted.casefold() == name.casefold():
            return model
    return None


def _resident_absent(llama_backend) -> bool:
    return not getattr(llama_backend, "is_loaded", False)


def _stashed_gguf_embeds() -> bool:
    from core.inference.llama_keepwarm import get_last_unloaded_model
    from core.inference.local_model_resolver import resolve_local_gguf
    from hub.services.models.ollama import ollama_model_ref_files

    last = get_last_unloaded_model()
    if not last:
        return False
    target_id, variant = last[0], last[1]
    try:
        # The variant beside a manifest reference is its tag, so pinning it asks for no quant.
        pin_variant = variant and not is_ollama_manifest_ref(target_id)
        resolved = resolve_local_gguf(
            f"{target_id}:{variant}" if pin_variant else target_id, allow_scan = False
        )
        path = resolved[0] if resolved else None
        if not path:
            return False
        # Read the blob out rather than materializing a link: this only asks what was stashed.
        if is_ollama_manifest_ref(path):
            path = ollama_model_ref_files(path)[0]
        probe = _probe_backend()
        probe._read_gguf_metadata(path)
        return bool(probe.is_embedding_gguf)
    except Exception:  # noqa: BLE001 - an unreadable stash is not an embedding model
        return False


async def _default_embeddings_request_body(request: Request) -> Optional[dict]:
    try:
        body = await request.json()
    except (json.JSONDecodeError, ValueError):
        return None
    if not isinstance(body, dict):
        return None
    requested = body.get("model")
    return body if requested is None or requested == "" else None


async def _embeddings_client_gone(request: Request) -> bool:
    is_disconnected = getattr(request, "is_disconnected", None)
    if is_disconnected is None:
        return False
    try:
        return bool(await is_disconnected())
    except Exception:  # noqa: BLE001 - a broken transport reads as still connected
        return False


async def _resident_answers_embeddings(llama_backend, requested: str) -> bool:
    if not _resident_serves_embeddings(llama_backend):
        return False
    return await asyncio.to_thread(_loaded_satisfies, requested)


def _reference_is_decisive(requested: str) -> bool:
    """Only a GGUF quant label or a repo on disk counts; bare vendor ids must fall through, not 404."""
    from core.inference.openai_auto_download import (
        looks_like_gguf_hub_repo_id,
        looks_like_quant,
        split_model_ref,
    )

    from core.rag.config import embedding_identity_model

    base, variant = split_model_ref(requested)
    # Shape alone decides, with no index: a quant label or GGUF hub repo id is never a vendor alias.
    if looks_like_quant(variant) or looks_like_gguf_hub_repo_id(base):
        return True
    # A tag names one exact vector space; never answer it from a different one.
    if embedding_identity_model(requested) is not None:
        return True
    try:
        from core.inference.local_model_resolver import (
            index_is_built,
            resolve_local_gguf,
            warm_index_soon,
        )
        from utils.paths import is_local_path

        if resolve_local_gguf(requested, allow_scan = False) is not None:
            return True
        if not index_is_built():
            # A cold index is missing evidence, not absence: do not pass a local-looking name through.
            warm_index_soon()
            return is_local_path(requested) or "/" in requested
        return False
    except Exception:  # noqa: BLE001 - a broken index cannot clear the name either
        return True


async def _studio_embedder_request_body(request: Request) -> Optional[tuple[dict, str]]:
    try:
        body = await request.json()
    except (json.JSONDecodeError, ValueError):
        return None
    if not isinstance(body, dict):
        return None
    requested = body.get("model")
    if not isinstance(requested, str) or not requested.strip():
        return None
    model = await asyncio.to_thread(_names_studio_embedder, requested)
    return (body, model) if model else None


async def _studio_embeddings(
    request: Request,
    body: dict,
    current_subject: str,
    model_name: Optional[str] = None,
) -> Response:
    from core.inference.llama_keepwarm import (
        untrack_admitted_inference,
        untrack_current_request,
    )
    from core.rag import config as rag_config
    from core.rag import embeddings as rag_embeddings

    # Untrack before encoding, or a 2xx claims the llama slot and blocks preview swaps.
    _scope = getattr(request, "scope", None)
    untrack_current_request(_scope)
    # The auto-switch hook admitted this before the route knew it lands here, so untrack the admitted tally; the preview busy guard reads that tally
    untrack_admitted_inference(_scope)

    texts = _embeddings_texts(body)
    encoding_format = body.get("encoding_format")
    if encoding_format is None:
        encoding_format = "float"
    dimensions = body.get("dimensions")
    model_name = model_name or rag_config.effective_embedding_model()
    label = _public_embedding_name(model_name)

    def _embed():
        # Pass the captured model: defaults re-read the live setting and can mix models.
        limit = rag_embeddings.max_tokens(model_name)
        count = rag_embeddings.token_counter(model_name)
        inputs = texts
        token_counts = [count(text) for text in inputs]
        if limit and max(token_counts) > limit:
            if not _embeddings_truncate(body):
                raise HTTPException(
                    status_code = 400,
                    detail = f"'input' exceeds the {limit}-token limit of {label}.",
                )
            inputs = [rag_embeddings.clip_to_limit(text, count, limit)[0] for text in inputs]
            logger.warning(
                "Embedding input over the %d-token limit of %s truncated to fit", limit, label
            )
            token_counts = [count(text) for text in inputs]
        if dimensions is not None and dimensions != rag_embeddings.dim(model_name):
            raise HTTPException(
                status_code = 400, detail = f"'dimensions' is not supported by {label}."
            )
        # An ST failure can swap to llama-server mid-encode; report the identity actually used.
        vectors, identity = rag_embeddings.encode_with_identity(
            inputs, model_name = model_name, normalize = True
        )
        return vectors, identity, sum(token_counts), limit

    monitor_id = None
    if not getattr(request.state, "skip_api_monitor", False):
        monitor_id = api_monitor.start(
            endpoint = request.url.path,
            via_api_key = _request_used_api_key(request),
            method = request.method,
            model = label,
            prompt = _flatten_monitor_prompt(body.get("input", "")),
            subject = current_subject,
        )
    # Release on the worker's lifetime: cancelling does not stop the to_thread worker.
    semaphore = _studio_embed_semaphore()
    acquire = asyncio.ensure_future(semaphore.acquire())
    try:
        while not acquire.done():
            await asyncio.wait({acquire}, timeout = 0.25)
            if not acquire.done() and await _embeddings_client_gone(request):
                raise _NonStreamingRequestCancelled("Request cancelled.")
    except (asyncio.CancelledError, _NonStreamingRequestCancelled) as exc:
        if not acquire.done():
            acquire.cancel()
        elif not acquire.cancelled() and acquire.exception() is None:
            semaphore.release()
        api_monitor.finish(monitor_id, "cancelled")
        if isinstance(exc, _NonStreamingRequestCancelled):
            raise _openai_admission_http_exception(exc, status_code = 499)
        raise
    try:
        gone = await _embeddings_client_gone(request)
    except asyncio.CancelledError:
        semaphore.release()
        api_monitor.finish(monitor_id, "cancelled")
        raise
    if gone:
        semaphore.release()
        api_monitor.finish(monitor_id, "cancelled")
        raise _openai_admission_http_exception(
            _NonStreamingRequestCancelled("Request cancelled."), status_code = 499
        )
    worker = asyncio.ensure_future(asyncio.to_thread(_embed))

    def _release_embed_permit(finished) -> None:
        if not finished.cancelled():
            finished.exception()  # retrieved so a cancelled request logs no "never retrieved"
        semaphore.release()

    worker.add_done_callback(_release_embed_permit)
    try:
        vectors, identity, prompt_tokens, limit = await asyncio.shield(worker)
    except asyncio.CancelledError:
        api_monitor.finish(monitor_id, "cancelled")
        raise
    except HTTPException as exc:
        api_monitor.fail(monitor_id, str(exc.detail))
        raise
    # Surface actionable errors instead of _friendly_error's generic message. 409: not ready yet.
    except (
        rag_embeddings.EmbeddingModelDownloadRequiredError,
        rag_embeddings.UnsafeEmbeddingModelError,
    ) as exc:
        # The configured model may be a local path, which every other field here hashes.
        detail = str(exc).replace(repr(model_name), repr(label))
        api_monitor.fail(monitor_id, detail)
        raise HTTPException(status_code = 409, detail = detail) from exc
    except Exception as exc:
        api_monitor.fail(monitor_id, _friendly_error(exc))
        raise HTTPException(
            status_code = 502, detail = f"Embedding model failed: {_friendly_error(exc)}"
        ) from exc
    payload = {
        "object": "list",
        "data": [
            {
                "object": "embedding",
                "index": index,
                "embedding": _embedding_payload(vector, encoding_format),
            }
            for index, vector in enumerate(vectors)
        ],
        "model": _public_embedding_identity(identity, model_name, label),
        "usage": {"prompt_tokens": prompt_tokens, "total_tokens": prompt_tokens},
    }
    # The gauge only makes sense for a single input; prompt_tokens sums the batch.
    _monitor_openai_chunk(monitor_id, payload, limit if len(texts) == 1 else None)
    api_monitor.finish(monitor_id)
    return Response(content = json.dumps(payload), media_type = "application/json")


# llama-server's refusals past one micro-batch (500) or the slot context (400), server-context.cpp;
# a splittable slot (LAST pooling, e.g. Qwen3-Embedding) refuses n_tokens >= n_ctx instead.
_LLAMA_EMBED_OVERFLOW_RE = re.compile(
    r"input \(\d+ tokens\) is (?:too large to process\. increase the physical batch size "
    r"\(current batch size: (\d+)\)|larger than the max context size \((\d+) tokens\))"
    r"|request \(\d+ tokens\) exceeds the available context size \((\d+) tokens\)"
)


def _llama_embedding_overflow_limit(resp) -> Optional[int]:
    if resp.status_code not in (400, 500):
        return None
    try:
        match = _LLAMA_EMBED_OVERFLOW_RE.search(resp.json()["error"]["message"])
    except Exception:  # noqa: BLE001
        return None
    if not match:
        return None
    if match.group(3):
        return int(match.group(3)) - 1
    return int(match.group(1) or match.group(2))


async def _truncated_llama_embedding_inputs(
    upstream: _LlamaUpstream, value, limit, cache: dict
) -> Optional[list]:
    """Strings past ``limit`` cut to their first tokens, keeping the special tokens llama-server
    adds around a string. None when nothing was cut. ``cache`` spans the retries."""
    items = [value] if isinstance(value, str) else value
    # A top-level array holding numbers is one prompt (tokens, or tokens mixed with strings).
    if not isinstance(items, list) or any(not isinstance(item, (str, list)) for item in items):
        return None

    async def tokenize(text: str, add_special: bool) -> Optional[list]:
        r = await upstream.post(
            {"content": text, "add_special": add_special},
            timeout = _DEFAULT_FIRST_TOKEN_TIMEOUT_S,
            path = "/tokenize",
        )
        try:
            tokens = r.json()["tokens"] if r.status_code == 200 else None
        except (ValueError, KeyError, TypeError):
            tokens = None
        return tokens if isinstance(tokens, list) else None

    out, cut = [], False
    for index, item in enumerate(items):
        # Short ASCII skips /tokenize (>= 1 byte per token); normalization can expand non-ASCII.
        if isinstance(item, str) and (not item.isascii() or len(item) + 8 > limit):
            if index not in cache:
                cache[index] = [await tokenize(item, True), None]
            full, bare = cache[index]
            if full is None:
                return None
            if len(full) > limit:
                if bare is None:
                    bare = cache[index][1] = await tokenize(item, False)
                    if bare is None:
                        return None
                extra = len(full) - len(bare)
                head = next((h for h in range(extra + 1) if full[h : h + len(bare)] == bare), None)
                if head is not None and limit > extra:
                    item = full[:head] + bare[: limit - extra] + full[head + len(bare) :]
                    cut = True
        out.append(item)
    return out if cut else None


def _embedding_width(resp) -> Optional[int]:
    try:
        embedding = resp.json()["data"][0]["embedding"]
        if isinstance(embedding, str):
            return len(base64.b64decode(embedding)) // 4
        return len(embedding)
    except Exception:  # noqa: BLE001
        return None


def _embeddings_input_present(body: dict) -> bool:
    """Whether an embeddings body carries a usable ``input`` (non-empty)."""
    inp = body.get("input")
    if isinstance(inp, str):
        return inp != ""
    if isinstance(inp, (list, tuple)):
        return len(inp) > 0
    return inp is not None


@router.post("/embeddings")
@account_access.gpu_busy_route
async def openai_embeddings(request: Request, current_subject: str = Depends(get_current_subject)):
    """OpenAI-compatible embeddings: the resident embedding GGUF when one is loaded,
    else Unsloth's configured embedding model."""
    if model_slots.slots:
        try:
            await _route_to_extra_slot(_raw_body_model(await request.json()))
        except (json.JSONDecodeError, ValueError):
            pass
    else:
        routed_slot.set(None)
    llama_backend = get_llama_cpp_backend()
    # Validate before any automatic load (auto-switch, idle TTL, or a preview-owned slot claim) so a bad request never swaps the resident model
    if _should_validate_before_switch():
        try:
            _pre = await request.json()
        except (json.JSONDecodeError, ValueError):
            _pre = _UNPARSEABLE_BODY
        if isinstance(_pre, dict):
            _pre_input = _pre.get("input")
            if _pre_input is not None and not isinstance(_pre_input, (str, list, tuple)):
                # Reject a bad shape before the switch so it can't load a GGUF just to be rejected.
                raise HTTPException(status_code = 400, detail = "'input' must be a string or array.")
            if not _embeddings_input_present(_pre):
                raise HTTPException(status_code = 400, detail = "'input' is required for embeddings.")
            _embeddings_items(_pre, tokens_ok = True)
        elif _pre is not _UNPARSEABLE_BODY:
            # Reject before the switch so the slot claim can't take a preview-owned model.
            raise HTTPException(status_code = 400, detail = "Request body must be a JSON object")
    # Best-effort auto-switch: GGUF pooling support has no reliable pre-load probe.
    studio_request = await _studio_embedder_request_body(request)
    if studio_request is not None and not await _resident_answers_embeddings(
        llama_backend, studio_request[0]["model"]
    ):
        return await _studio_embeddings(
            request, studio_request[0], current_subject, model_name = studio_request[1]
        )
    if studio_request is None and _resident_absent(llama_backend):
        default_body = await _default_embeddings_request_body(request)
        if default_body is not None and not await asyncio.to_thread(_stashed_gguf_embeds):
            return await _studio_embeddings(request, default_body, current_subject)
    body = await _auto_switch_from_request_body(request, current_subject, gguf_only = True)
    llama_backend = get_llama_cpp_backend()
    if not llama_backend.is_loaded:
        # With the slot empty, refuse a decisive repo:QUANT rather than answer from another space.
        _named = _raw_body_model(body)
        if not isinstance(_named, str):
            _named = None
        if _named and not await asyncio.to_thread(_names_studio_embedder, _named):
            _decisive = await asyncio.to_thread(_reference_is_decisive, _named)
        else:
            _decisive = False
        if _decisive or not isinstance(body, dict):
            _status, _detail = await _no_model_loaded_error(
                "No GGUF model loaded. Load a GGUF model first.",
                _named,
                request,
                status = 503,
            )
            raise HTTPException(status_code = _status, detail = _detail)
    if not isinstance(body, dict):
        # Re-read to re-raise a malformed-body error; a valid non-dict body gets a clean 400.
        body = await request.json()
        if not isinstance(body, dict):
            raise HTTPException(status_code = 400, detail = "Request body must be a JSON object")

    if not _resident_serves_embeddings(llama_backend):
        return await _studio_embeddings(request, body, current_subject)

    # No claim here: middleware claims on 2xx, and llama-server can still non-2xx a valid body, stranding a preview model; it ignores dimensions.
    body = dict(body)
    if account_access.managed_account():
        # llama-server fetches media URLs inside multimodal items; a managed account sends text or tokens only.
        _embeddings_items(body, tokens_ok = True)
    dimensions = body.pop("dimensions", None)
    truncate = _embeddings_truncate(body)
    body.pop("truncate", None)
    prompt_text = _flatten_monitor_prompt(body.get("input", ""))
    monitor_id = None
    monitor_model = _monitor_active_model() or str(
        body.get("model") or _llama_public_model_id(llama_backend) or "default"
    )
    if not getattr(request.state, "skip_api_monitor", False):
        monitor_id = api_monitor.start(
            endpoint = request.url.path,
            via_api_key = _request_used_api_key(request),
            method = request.method,
            model = monitor_model,
            prompt = prompt_text,
            context_length = llama_backend.context_length,
            subject = current_subject,
        )

    async with _monitored_llama_call(
        llama_backend,
        "/v1/embeddings",
        request = request,
        monitor_id = monitor_id,
        model = monitor_model,
        kind = "embeddings",
    ) as upstream:
        resp = await upstream.post(body, timeout = _DEFAULT_FIRST_TOKEN_TIMEOUT_S)
        original, cache, limit = body.get("input"), {}, None
        for _ in range(2):
            reported = _llama_embedding_overflow_limit(resp) if truncate else None
            if not reported:
                break
            # Cut the client's inputs, not the token arrays the first retry sent.
            limit = min(limit or reported, reported)
            inputs = await _truncated_llama_embedding_inputs(upstream, original, limit, cache)
            if not inputs:
                break
            logger.warning("Embedding input over the %d-token limit truncated to fit", limit)
            body["input"] = inputs
            resp = await upstream.post(body, timeout = _DEFAULT_FIRST_TOKEN_TIMEOUT_S)
    if resp.status_code == 200 and dimensions is not None and dimensions != _embedding_width(resp):
        detail = f"'dimensions' is not supported by {_llama_public_model_id(llama_backend)}."
        api_monitor.fail(monitor_id, detail)
        raise HTTPException(status_code = 400, detail = detail)
    if resp.status_code != 200:
        api_monitor.fail(monitor_id, resp.text[:500])
    else:
        try:
            _monitor_openai_chunk(monitor_id, resp.json(), _monitor_context_length())
        except Exception:
            pass
        api_monitor.finish(monitor_id)
    return Response(
        content = resp.content,
        status_code = resp.status_code,
        media_type = "application/json",
    )


# =====================================================================

# OpenAI Responses API  (/responses → /v1/responses)
# =====================================================================


_RESPONSES_CUSTOM_APPLY_PATCH = "apply_patch"


def _is_responses_apply_patch_tool(tool: Any) -> bool:
    if not isinstance(tool, dict):
        return False
    format_spec = tool.get("format")
    return (
        tool.get("type") == "custom"
        and tool.get("name") == _RESPONSES_CUSTOM_APPLY_PATCH
        and isinstance(format_spec, dict)
        and format_spec.get("type") == "grammar"
        and format_spec.get("syntax") == "lark"
        and isinstance(format_spec.get("definition"), str)
    )


def _responses_custom_tool_names(tools: Optional[list[dict]]) -> set[str]:
    return {tool["name"] for tool in tools or [] if _is_responses_apply_patch_tool(tool)}


def _responses_namespaced_name(namespace: str, name: str) -> str:
    return f"{namespace}__{name}"


def _responses_namespace_functions(tool: dict) -> list[tuple[str, dict]]:
    namespace = tool.get("name")
    if not isinstance(namespace, str) or not namespace:
        return []
    return [
        (_responses_namespaced_name(namespace, inner["name"]), inner)
        for inner in tool.get("tools") or []
        if isinstance(inner, dict)
        and inner.get("type") == "function"
        and isinstance(inner.get("name"), str)
    ]


def _responses_namespaced_tool_names(tools: Optional[list[dict]]) -> dict[str, tuple[str, str]]:
    return {
        flat_name: (tool["name"], inner["name"])
        for tool in tools or []
        if isinstance(tool, dict) and tool.get("type") == "namespace"
        for flat_name, inner in _responses_namespace_functions(tool)
    }


def _responses_function_call_name(
    name: str, namespaced_tool_names: dict[str, tuple[str, str]]
) -> dict:
    if name in namespaced_tool_names:
        namespace, bare_name = namespaced_tool_names[name]
        return {"name": bare_name, "namespace": namespace}
    return {"name": name}


def _responses_apply_patch_description(tool: dict) -> str:
    description = (
        "Edit files by passing one complete patch in the input field. "
        "Every added content line must start with +. Example:\n"
        "*** Begin Patch\n"
        "*** Add File: path/to/file.txt\n"
        "+first line\n"
        "*** End Patch"
    )
    format_spec = tool.get("format")
    if isinstance(format_spec, dict) and isinstance(format_spec.get("definition"), str):
        description += "\n\nThe input must match this Lark grammar:\n" + format_spec["definition"]
    return description


def _translate_responses_tools_to_chat(tools: Optional[list[dict]]) -> Optional[list[dict]]:
    """Codex apply_patch becomes a string-input function; other custom and built-in tools are dropped since llama-server cannot run them server-side"""
    if not tools:
        return None
    out: list[dict] = []
    for tool in tools:
        if not isinstance(tool, dict):
            continue
        if _is_responses_apply_patch_tool(tool):
            out.append(
                {
                    "type": "function",
                    "function": {
                        "name": _RESPONSES_CUSTOM_APPLY_PATCH,
                        "description": _responses_apply_patch_description(tool),
                        "parameters": {
                            "type": "object",
                            "properties": {
                                "input": {
                                    "type": "string",
                                    "description": "A complete patch matching the tool grammar.",
                                }
                            },
                            "required": ["input"],
                            "additionalProperties": False,
                        },
                        "strict": False,
                    },
                }
            )
            continue
        if tool.get("type") == "namespace":
            out.extend(
                _responses_function_tool_to_chat({**inner, "name": flat_name})
                for flat_name, inner in _responses_namespace_functions(tool)
            )
            continue
        if tool.get("type") != "function":
            continue
        out.append(_responses_function_tool_to_chat(tool))
    return out or None


def _responses_function_tool_to_chat(tool: dict) -> dict:
    fn: dict = {}
    if "name" in tool:
        fn["name"] = tool["name"]
    if tool.get("description") is not None:
        fn["description"] = tool["description"]
    if tool.get("parameters") is not None:
        fn["parameters"] = tool["parameters"]
    if tool.get("strict") is not None:
        fn["strict"] = tool["strict"]
    return {"type": "function", "function": fn}


def _translate_responses_tool_choice_to_chat(
    tool_choice: Any, custom_tool_names: Optional[set[str]] = None
) -> Any:
    """Strings pass through; the flat forcing object becomes the nested Chat function shape."""
    if tool_choice is None:
        return None
    if isinstance(tool_choice, str):
        return tool_choice
    if (
        isinstance(tool_choice, dict)
        and tool_choice.get("type") in ("function", "custom")
        and "name" in tool_choice
        and "function" not in tool_choice
    ):
        if tool_choice.get("type") == "custom":
            custom_tool_names = custom_tool_names or set()
            if tool_choice["name"] not in custom_tool_names:
                return tool_choice
        return {"type": "function", "function": {"name": tool_choice["name"]}}
    return tool_choice


def _responses_message_text(content: Union[str, list]) -> str:
    """Flattens content to text, silently dropping non-text parts; not for user turns."""
    if isinstance(content, str):
        return content
    parts: list[str] = []
    for part in content or []:
        if isinstance(part, (ResponsesInputTextPart, ResponsesOutputTextPart)):
            parts.append(part.text)
    return "\n".join(parts)


def _responses_tool_output_content(output: Union[str, list]) -> Union[str, list]:
    """Return Chat Completions-safe content for a Responses tool result."""
    if isinstance(output, str):
        return output if output.strip() else "(no output)"

    if not output:
        return "(no output)"

    text_parts: list[str] = []
    chat_parts: list = []
    has_multimodal = False
    for part in output:
        if not isinstance(part, dict):
            return json.dumps(output)
        part_type = part.get("type")
        if part_type in ("input_text", "output_text", "text"):
            text = part.get("text")
            if text is None:
                _raise_unsupported_openai_parameter(
                    "input",
                    "Responses function_call_output.output text parts require a text field.",
                )
            text = str(text)
            text_parts.append(text)
            chat_parts.append(TextContentPart(type = "text", text = text))
            continue
        if part_type == "input_image":
            image_url = part.get("image_url")
            if not isinstance(image_url, str) or not image_url:
                if part.get("file_id"):
                    _raise_unsupported_openai_parameter(
                        "input",
                        "Responses function_call_output.output input_image parts with file_id are not supported by the local adapter. Use image_url instead.",
                    )
                _raise_unsupported_openai_parameter(
                    "input",
                    "Responses function_call_output.output input_image parts require an image_url string.",
                )
            detail = part.get("detail", "auto")
            if detail is None:
                detail = "auto"
            if detail not in ("auto", "low", "high", "original"):
                _raise_unsupported_openai_parameter(
                    "input",
                    "Responses function_call_output.output input_image detail must be auto, low, high, or original.",
                )
            chat_parts.append(
                ImageContentPart(
                    type = "image_url",
                    image_url = ImageUrl(url = image_url, detail = detail),
                )
            )
            has_multimodal = True
            continue
        if part_type == "input_file":
            _raise_unsupported_openai_parameter(
                "input",
                "Responses function_call_output.output input_file parts are not supported by the local adapter.",
            )
        return json.dumps(output)

    if has_multimodal:
        return chat_parts

    text = "\n".join(text_parts)
    return text if text.strip() else "(no output)"


_RESPONSES_THINK_OPEN = "<think>"
_RESPONSES_THINK_CLOSE = "</think>"


def _coerce_responses_reasoning_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        return "".join(_coerce_responses_reasoning_text(part) for part in value)
    if isinstance(value, dict):
        for key in ("text", "reasoning_text", "content"):
            text = _coerce_responses_reasoning_text(value.get(key))
            if text:
                return text
        return ""
    return json.dumps(value)


def _responses_marker_holdback(text: str, markers: tuple[str, ...]) -> int:
    """Number of trailing chars to retain because they may start a marker."""
    for size in range(min(len(text), max(len(m) for m in markers) - 1), 0, -1):
        suffix = text[-size:]
        if any(marker.startswith(suffix) for marker in markers):
            return size
    return 0


class _ResponsesReasoningExtractor:
    """Split local <think> markup into Responses reasoning and visible text."""

    def __init__(
        self,
        *,
        parse_think_markers: bool = False,
        reasoning_prefilled: bool = False,
        single_block: bool = False,
    ) -> None:
        self._buffer = ""
        # Prefilled template opens an unclosed <think>, so start in reasoning.
        self._in_reasoning = reasoning_prefilled and not single_block
        # Splitting requires marker parsing; a prefilled open implies it.
        self._parse_think_markers = parse_think_markers or reasoning_prefilled
        self._single_block = single_block

    def feed(
        self,
        text: str = "",
        reasoning_content: Any = None,
    ) -> tuple[str, str]:
        reasoning_parts: list[str] = []
        visible_parts: list[str] = []
        structured_reasoning = _coerce_responses_reasoning_text(reasoning_content)
        if structured_reasoning:
            reasoning_parts.append(structured_reasoning)
        if text:
            self._buffer += text
        if not self._parse_think_markers:
            visible_parts.append(self._buffer)
            self._buffer = ""
            return "".join(reasoning_parts), "".join(visible_parts)

        while self._buffer:
            if self._in_reasoning:
                close_idx = self._buffer.find(_RESPONSES_THINK_CLOSE)
                if close_idx != -1:
                    reasoning_parts.append(
                        self._buffer[:close_idx].replace(_RESPONSES_THINK_OPEN, "")
                    )
                    self._buffer = self._buffer[close_idx + len(_RESPONSES_THINK_CLOSE) :]
                    self._in_reasoning = False
                    continue
                # Hold back a trailing partial of either marker so splits and stray opens are handled.
                keep = _responses_marker_holdback(
                    self._buffer, (_RESPONSES_THINK_CLOSE, _RESPONSES_THINK_OPEN)
                )
                if keep == len(self._buffer):
                    break
                emit = self._buffer[:-keep] if keep else self._buffer
                reasoning_parts.append(emit.replace(_RESPONSES_THINK_OPEN, ""))
                self._buffer = self._buffer[-keep:] if keep else ""
                break

            if self._single_block:
                if self._buffer.startswith(_RESPONSES_THINK_OPEN):
                    self._buffer = self._buffer[len(_RESPONSES_THINK_OPEN) :]
                    self._in_reasoning = True
                    continue
                if _RESPONSES_THINK_OPEN.startswith(self._buffer):
                    break  # still short of the opener; it may yet arrive
                self._parse_think_markers = False
                visible_parts.append(self._buffer)
                self._buffer = ""
                break

            open_idx = self._buffer.find(_RESPONSES_THINK_OPEN)
            close_idx = self._buffer.find(_RESPONSES_THINK_CLOSE)
            if close_idx != -1 and (open_idx == -1 or close_idx < open_idx):
                visible_parts.append(self._buffer[:close_idx])
                self._buffer = self._buffer[close_idx + len(_RESPONSES_THINK_CLOSE) :]
                continue
            if open_idx != -1:
                visible_parts.append(self._buffer[:open_idx])
                self._buffer = self._buffer[open_idx + len(_RESPONSES_THINK_OPEN) :]
                self._in_reasoning = True
                continue

            keep = _responses_marker_holdback(
                self._buffer,
                (_RESPONSES_THINK_OPEN, _RESPONSES_THINK_CLOSE),
            )
            if keep == len(self._buffer):
                break
            visible_parts.append(self._buffer[:-keep] if keep else self._buffer)
            self._buffer = self._buffer[-keep:] if keep else ""
            break

        return "".join(reasoning_parts), "".join(visible_parts)

    def finish(self) -> tuple[str, str]:
        if not self._buffer:
            return "", ""
        remaining = self._buffer
        self._buffer = ""
        if not self._parse_think_markers:
            return "", remaining
        if self._in_reasoning:
            self._in_reasoning = False
            return remaining.replace(_RESPONSES_THINK_OPEN, ""), ""
        return "", remaining.replace(_RESPONSES_THINK_CLOSE, "")


def _extract_responses_reasoning(
    text: str = "",
    reasoning_content: Any = None,
    *,
    parse_think_markers: bool = False,
    reasoning_prefilled: bool = False,
    single_block: bool = False,
) -> tuple[str, str]:
    extractor = _ResponsesReasoningExtractor(
        parse_think_markers = parse_think_markers,
        reasoning_prefilled = reasoning_prefilled,
        single_block = single_block,
    )
    reasoning, visible = extractor.feed(text, reasoning_content)
    final_reasoning, final_visible = extractor.finish()
    return reasoning + final_reasoning, visible + final_visible


def _responses_should_parse_think_markers(
    chat_req: ChatCompletionRequest, llama_backend: Any = None
) -> bool:
    if llama_backend is not None and getattr(llama_backend, "is_loaded", False):
        if getattr(llama_backend, "reasoning_always_on", False):
            return True
        if not getattr(llama_backend, "supports_reasoning", False):
            return False
        # Same rule as _think_parsing_expected: decide from the resolved kwargs.
        resolved = (
            _reasoning_template_kwargs(
                llama_backend,
                chat_req.enable_thinking,
                chat_req.reasoning_effort,
                chat_req.preserve_thinking,
            )
            or {}
        )
        return _resolved_kwargs_think(llama_backend, resolved)
    if chat_req.enable_thinking is True:
        return True
    return chat_req.enable_thinking is None and chat_req.reasoning_effort not in (None, "none")


def _responses_reasoning_output_item(
    reasoning_text: str,
    item_id: Optional[str] = None,
    status: Literal["completed", "incomplete"] = "completed",
) -> dict:
    kwargs: dict[str, Any] = {
        "status": status,
        "summary": [],
        "content": [ResponsesOutputReasoningContent(text = reasoning_text)],
    }
    if item_id is not None:
        kwargs["id"] = item_id
    return ResponsesOutputReasoning(**kwargs).model_dump()


def _reject_unserviceable_responses_attachment(part, *, role = "user") -> None:
    """Refuse an attachment the local adapter cannot serve instead of dropping it; same rules and wording as _responses_tool_output_content so they cannot drift"""
    part_type = getattr(part, "type", None)
    if part_type in ("input_text", "output_text") and not isinstance(
        part, (ResponsesInputTextPart, ResponsesOutputTextPart)
    ):
        # A known type name would pass a name-only allowlist and be silently dropped.
        _raise_unsupported_openai_parameter(
            "input",
            f"Responses {part_type} message parts require a text field.",
        )
    if part_type == "input_file":
        _raise_unsupported_openai_parameter(
            "input",
            "Responses input_file message parts are not supported by the local adapter.",
        )
    if part_type == "input_image":
        image_url = getattr(part, "image_url", None)
        if not isinstance(image_url, str) or not image_url:
            if getattr(part, "file_id", None):
                _raise_unsupported_openai_parameter(
                    "input",
                    "Responses input_image message parts with file_id are not supported by the "
                    "local adapter. Use image_url instead.",
                )
            _raise_unsupported_openai_parameter(
                "input",
                "Responses input_image message parts require an image_url string.",
            )
        detail = getattr(part, "detail", "auto")
        if detail is None:
            detail = "auto"
        if detail not in ("auto", "low", "high", "original"):
            _raise_unsupported_openai_parameter(
                "input",
                "Responses input_image message detail must be auto, low, high, or original.",
            )
        if role != "user":
            _raise_unsupported_openai_parameter(
                "input",
                f"Responses input_image message parts are only supported on user messages; "
                f"{role} content is flattened to text by the local adapter.",
            )


# Metadata parts may be dropped only on assistant replay turns, never system or developer; an allowlist, since an input_ prefix misses computer_screenshot
_RESPONSES_TEXT_PART_TYPES = frozenset({"input_text", "output_text"})
_RESPONSES_ASSISTANT_METADATA_PART_TYPES = frozenset({"refusal", "summary_text"})


def _responses_part_survives_flatten(part_type, role) -> bool:
    if part_type in _RESPONSES_TEXT_PART_TYPES:
        return True
    return role == "assistant" and part_type in _RESPONSES_ASSISTANT_METADATA_PART_TYPES


def _reject_unserviceable_responses_attachments(item) -> None:
    """Refuses attachments outside user turns: system and assistant turns must be plain strings, since Chat Completions and strict templates reject arrays"""
    if isinstance(item.content, str):
        return
    for part in item.content or []:
        _reject_unserviceable_responses_attachment(part, role = item.role)
        part_type = getattr(part, "type", None)
        if item.role != "user" and not _responses_part_survives_flatten(part_type, item.role):
            _raise_unsupported_openai_parameter(
                "input",
                f"Responses message content parts of type '{part_type}' are not supported on "
                f"{item.role} messages; {item.role} content is flattened to text by the local "
                "adapter.",
            )


def _reject_unknown_responses_message_part(part) -> None:
    """User turns only: replayed assistant output can carry parts that hold no attachment."""
    _raise_unsupported_openai_parameter(
        "input",
        f"Responses message content parts of type '{getattr(part, 'type', None)}' "
        "are not supported.",
    )


def _normalise_responses_input(payload: ResponsesRequest) -> list[ChatMessage]:
    """Converts input to Chat messages, linking call_id to results; hoists system and developer content into one leading system message for strict templates"""
    system_parts: list[str] = []
    messages: list[ChatMessage] = []

    if payload.instructions:
        system_parts.append(payload.instructions)

    def _with_system(msgs: list[ChatMessage]) -> list[ChatMessage]:
        if not system_parts:
            return msgs
        merged = "\n\n".join(p for p in system_parts if p)
        return [ChatMessage(role = "system", content = merged), *msgs]

    # Simple string input
    if isinstance(payload.input, str):
        if payload.input:
            messages.append(ChatMessage(role = "user", content = payload.input))
        return _with_system(messages)

    custom_tool_names = _responses_custom_tool_names(payload.tools)
    custom_tool_call_ids = {
        item.call_id
        for item in payload.input
        if isinstance(item, ResponsesCustomToolCallInputItem) and item.name in custom_tool_names
    }

    turn_reasoning: list[str] = []
    turn_text: list[str] = []
    turn_calls: list[dict] = []

    def _flush_assistant_turn() -> None:
        if turn_text or turn_calls:
            messages.append(
                ChatMessage(
                    role = "assistant",
                    content = "\n\n".join(turn_text) or None,
                    reasoning_content = "\n\n".join(turn_reasoning) or None,
                    tool_calls = list(turn_calls) or None,
                )
            )
        turn_reasoning.clear()
        turn_text.clear()
        turn_calls.clear()

    for item in payload.input:
        if not (
            isinstance(item, (ResponsesFunctionCallInputItem, ResponsesCustomToolCallInputItem))
            or getattr(item, "role", None) == "assistant"
            or getattr(item, "type", None) == "reasoning"
        ):
            _flush_assistant_turn()

        if isinstance(item, ResponsesFunctionCallInputItem):
            turn_calls.append(
                {
                    "id": item.call_id,
                    "type": "function",
                    "function": {
                        "name": (
                            _responses_namespaced_name(item.namespace, item.name)
                            if item.namespace
                            else item.name
                        ),
                        "arguments": item.arguments,
                    },
                }
            )
            continue

        if isinstance(item, ResponsesFunctionCallOutputInputItem):
            # Flatten pure text arrays for template compatibility; image URL outputs stay multimodal parts.
            output = _responses_tool_output_content(item.output)
            messages.append(
                ChatMessage(
                    role = "tool",
                    tool_call_id = item.call_id,
                    content = output,
                )
            )
            continue

        if isinstance(item, ResponsesCustomToolCallInputItem):
            if item.call_id not in custom_tool_call_ids:
                continue
            turn_calls.append(
                {
                    "id": item.call_id,
                    "type": "function",
                    "function": {
                        "name": item.name,
                        "arguments": json.dumps({"input": item.input}, ensure_ascii = False),
                    },
                }
            )
            continue

        if isinstance(item, ResponsesCustomToolCallOutputInputItem):
            if item.call_id not in custom_tool_call_ids:
                continue
            messages.append(
                ChatMessage(
                    role = "tool",
                    tool_call_id = item.call_id,
                    content = _responses_tool_output_content(item.output),
                )
            )
            continue

        if isinstance(item, ResponsesUnknownInputItem):
            if item.type == "reasoning":
                replayed = _coerce_responses_reasoning_text(
                    getattr(item, "content", None)
                ) or _coerce_responses_reasoning_text(getattr(item, "summary", None))
                if replayed.strip():
                    turn_reasoning.append(replayed)
            continue

        # Before the role branches: each `continue`s, so a later refusal would miss attachments.
        _reject_unserviceable_responses_attachments(item)

        # Hoist system/developer to the top, merge.
        if item.role in ("system", "developer"):
            hoisted = _responses_message_text(item.content)
            if hoisted:
                system_parts.append(hoisted)
            continue

        # Assistant role expects a plain string, so flatten replayed output_text parts.
        if item.role == "assistant":
            message_text = _responses_message_text(item.content)
            if message_text:
                turn_text.append(message_text)
            continue

        if isinstance(item.content, str):
            messages.append(ChatMessage(role = item.role, content = item.content))
            continue

        # Attachments were refused above, so any part still here is one no local route can serve.
        parts: list = []
        for part in item.content:
            if isinstance(part, (ResponsesInputTextPart, ResponsesOutputTextPart)):
                parts.append(TextContentPart(type = "text", text = part.text))
            elif isinstance(part, ResponsesInputImagePart):
                parts.append(
                    ImageContentPart(
                        type = "image_url",
                        image_url = ImageUrl(url = part.image_url, detail = part.detail),
                    )
                )
            else:
                _reject_unknown_responses_message_part(part)
        if parts:
            # Legacy templates reject multimodal arrays for some roles.
            if len(parts) == 1 and isinstance(parts[0], TextContentPart):
                messages.append(ChatMessage(role = item.role, content = parts[0].text))
            else:
                messages.append(ChatMessage(role = item.role, content = parts))

    _flush_assistant_turn()
    return _with_system(messages)


def _responses_text_format(text: Any) -> Optional[dict]:
    """Plain text and verbosity-only text carry no constraint and map to None."""
    fmt = text.get("format") if isinstance(text, dict) else None
    if not isinstance(fmt, dict):
        return None
    if fmt.get("type") == "json_object":
        return {"type": "json_object"}
    if fmt.get("type") != "json_schema" or not isinstance(fmt.get("schema"), dict):
        return None
    json_schema = {"name": str(fmt.get("name") or "response"), "schema": fmt["schema"]}
    if fmt.get("strict") is not None:
        json_schema["strict"] = bool(fmt["strict"])
    return {"type": "json_schema", "json_schema": json_schema}


def _build_chat_request(
    payload: ResponsesRequest, messages: list[ChatMessage], stream: bool
) -> ChatCompletionRequest:
    """Tools are converted to nested Chat shape here so the chat pass-through takes them unchanged."""
    chat_kwargs: dict = dict(
        messages = messages,
        stream = stream,
    )
    # Forward only an explicit model so an omitted one stays reload-only.
    if "model" in payload.model_fields_set:
        chat_kwargs["model"] = payload.model
    if payload.temperature is not None:
        chat_kwargs["temperature"] = payload.temperature
    if payload.top_p is not None:
        chat_kwargs["top_p"] = payload.top_p
    if payload.seed is not None:
        chat_kwargs["seed"] = payload.seed
    if payload.max_output_tokens is not None:
        chat_kwargs["max_tokens"] = payload.max_output_tokens

    chat_tools = _translate_responses_tools_to_chat(payload.tools)
    if chat_tools is not None:
        chat_kwargs["tools"] = chat_tools

    chat_tool_choice = _translate_responses_tool_choice_to_chat(
        payload.tool_choice, _responses_custom_tool_names(payload.tools)
    )
    if chat_tool_choice is not None:
        chat_kwargs["tool_choice"] = chat_tool_choice
    if payload.parallel_tool_calls is not None:
        chat_kwargs["parallel_tool_calls"] = payload.parallel_tool_calls

    # chat_template_kwargs arrives in model_extra; lift it so both chat paths see it.
    explicit_enable_thinking = False
    _extra = getattr(payload, "model_extra", None)
    if isinstance(_extra, dict):
        _nested_reasoning = _chat_template_reasoning_kwargs(payload)
        chat_kwargs.update(_nested_reasoning)
        if "enable_thinking" in _nested_reasoning:
            explicit_enable_thinking = True
        # Not typed on ResponsesRequest; lift from extra-body for both paths.
        if isinstance(_extra.get("auto_heal_tool_calls"), bool):
            chat_kwargs["auto_heal_tool_calls"] = _extra["auto_heal_tool_calls"]
        if isinstance(_extra.get("nudge_tool_calls"), bool):
            chat_kwargs["nudge_tool_calls"] = _extra["nudge_tool_calls"]
        # Lift continuation too, or a Responses request resuming an assistant turn restarts the answer.
        if isinstance(_extra.get("continue_final_message"), bool):
            chat_kwargs["continue_final_message"] = _extra["continue_final_message"]
        # Lift the ownership marker too, or every fold reads a Studio thread as a client's.
        if isinstance(_extra.get("studio_tool_history"), bool):
            chat_kwargs["studio_tool_history"] = _extra["studio_tool_history"]

    if isinstance(payload.reasoning, dict):
        effort = payload.reasoning.get("effort")
        if isinstance(effort, str) and effort in _REASONING_EFFORT_VALUES:
            if not explicit_enable_thinking:
                chat_kwargs["reasoning_effort"] = effort
                chat_kwargs["enable_thinking"] = effort != "none"
            elif chat_kwargs.get("enable_thinking") is False:
                chat_kwargs["reasoning_effort"] = "none"
            elif effort != "none":
                chat_kwargs["reasoning_effort"] = effort

    response_format = _responses_text_format(payload.text)
    if response_format is not None:
        chat_kwargs["response_format"] = response_format

    chat_request = ChatCompletionRequest(**chat_kwargs)
    _normalize_chat_reasoning_controls(chat_request)
    return chat_request


def _responses_custom_tool_input(arguments: Any) -> str:
    if not isinstance(arguments, str):
        return ""
    try:
        parsed = json.loads(arguments)
    except json.JSONDecodeError:
        return arguments
    if isinstance(parsed, dict) and isinstance(parsed.get("input"), str):
        return parsed["input"]
    return arguments


def _chat_tool_calls_to_responses_output(
    tool_calls: list[dict],
    custom_tool_names: Optional[set[str]] = None,
    status: Literal["completed", "incomplete"] = "completed",
    namespaced_tool_names: Optional[dict[str, tuple[str, str]]] = None,
) -> list[dict]:
    """The call id is the cross-turn correlation key: stored as call_id, echoed back by the client."""
    custom_tool_names = custom_tool_names or set()
    items: list[dict] = []
    for tc in tool_calls:
        if tc.get("type") != "function":
            continue
        fn = tc.get("function") or {}
        name = fn.get("name", "")
        arguments = fn.get("arguments", "") or ""
        if name in custom_tool_names:
            items.append(
                ResponsesOutputCustomToolCall(
                    call_id = tc.get("id", ""),
                    name = name,
                    input = _responses_custom_tool_input(arguments),
                    status = status,
                ).model_dump()
            )
            continue
        items.append(
            ResponsesOutputFunctionCall(
                call_id = tc.get("id", ""),
                **_responses_function_call_name(name, namespaced_tool_names or {}),
                arguments = arguments,
                status = status,
            ).model_dump()
        )
    return items


def _responses_incomplete_reason(
    finish_reason: Any,
) -> Optional[Literal["max_output_tokens", "content_filter"]]:
    if finish_reason == "length":
        return "max_output_tokens"
    if finish_reason == "content_filter":
        return "content_filter"
    return None


async def _responses_non_streaming(
    payload: ResponsesRequest,
    messages: list[ChatMessage],
    request: Request,
    current_subject: Optional[str] = None,
) -> JSONResponse:
    """Handle a non-streaming Responses API call."""
    chat_req = _build_chat_request(payload, messages, stream = False)
    request_state = getattr(request, "state", None)
    if request_state is None:
        request_state = type("_RequestState", (), {})()
        try:
            setattr(request, "state", request_state)
        except Exception:
            request_state = None
    previous_skip_monitor = (
        bool(getattr(request_state, "skip_api_monitor", False))
        if request_state is not None
        else False
    )
    monitor_id = None
    if not previous_skip_monitor:
        monitor_id = api_monitor.start(
            endpoint = getattr(getattr(request, "url", None), "path", "/v1/responses"),
            method = getattr(request, "method", "POST"),
            via_api_key = _request_used_api_key(request),
            model = payload.model,
            prompt = _monitor_prompt_from_messages(messages),
            context_length = _monitor_context_length(),
            subject = current_subject,
        )
    if request_state is not None:
        request_state.skip_api_monitor = True

    # Catches the engine timings the suppressed inner monitor would otherwise drop.
    inner_perf: dict = {}
    if monitor_id:
        inner_perf["monitor_id"] = monitor_id
        inner_perf["context_length"] = _monitor_context_length()
    try:
        _sink_token = _monitor_perf_sink.set(inner_perf if monitor_id else None)
        try:
            result = await openai_chat_completions(chat_req, request, current_subject)
        finally:
            _monitor_perf_sink.reset(_sink_token)

        # openai_chat_completions returns a JSONResponse for non-streaming.
        if isinstance(result, Response):
            body = json.loads(result.body.decode())
        else:
            body = result

        choices = body.get("choices", [])
        text = ""
        reasoning_text = ""
        tool_calls: list[dict] = []
        incomplete_reason = (
            _responses_incomplete_reason(choices[0].get("finish_reason")) if choices else None
        )
        truncated = incomplete_reason is not None
        if choices:
            msg = choices[0].get("message", {}) or {}
            raw_content = msg.get("content", "") or ""
            raw_text = raw_content if isinstance(raw_content, str) else json.dumps(raw_content)
            llama_backend = get_llama_cpp_backend()
            reasoning_text, text = _extract_responses_reasoning(
                raw_text,
                msg.get("reasoning_content"),
                parse_think_markers = _responses_should_parse_think_markers(chat_req, llama_backend),
                single_block = _response_format_constrains_decoding(chat_req),
            )
            tool_calls = msg.get("tool_calls") or []

        usage_data = body.get("usage", {})
        input_tokens = usage_data.get("prompt_tokens", 0)
        output_tokens = usage_data.get("completion_tokens", 0)
        cached_input = cached_prompt_tokens(usage_data)

        resp_id = f"resp_{uuid.uuid4().hex[:12]}"

        # Emit the text message only when there is content, so tool-call turns have none.
        output_items: list[dict] = []
        item_status = "incomplete" if truncated else "completed"
        if reasoning_text:
            output_items.append(
                _responses_reasoning_output_item(reasoning_text, status = item_status)
            )
        if text:
            msg_id = f"msg_{uuid.uuid4().hex[:12]}"
            output_items.append(
                ResponsesOutputMessage(
                    id = msg_id,
                    status = item_status,
                    role = "assistant",
                    content = [ResponsesOutputTextContent(text = text)],
                ).model_dump()
            )
        output_items.extend(
            _chat_tool_calls_to_responses_output(
                tool_calls,
                _responses_custom_tool_names(payload.tools),
                status = item_status,
                namespaced_tool_names = _responses_namespaced_tool_names(payload.tools),
            )
        )

        response = ResponsesResponse(
            id = resp_id,
            created_at = int(time.time()),
            status = "incomplete" if truncated else "completed",
            incomplete_details = ({"reason": incomplete_reason} if truncated else None),
            model = body.get("model", payload.model),
            output = output_items,
            usage = ResponsesUsage(
                input_tokens = input_tokens,
                output_tokens = output_tokens,
                total_tokens = input_tokens + output_tokens,
                input_tokens_details = (
                    None if cached_input is None else {"cached_tokens": cached_input}
                ),
            ),
            temperature = payload.temperature,
            top_p = payload.top_p,
            max_output_tokens = payload.max_output_tokens,
            instructions = payload.instructions,
        )
        api_monitor.set_reply(monitor_id, text or _monitor_tool_calls_text(tool_calls))
        _monitor_usage(
            monitor_id,
            usage_data,
            _monitor_context_length(),
            # Only the llama-server passthrough carries timings on the body.
            timings = (
                (body.get("timings") if isinstance(body, dict) else None)
                or inner_perf.get("timings")
            ),
            stop_reason = (choices[0].get("finish_reason") if choices else None),
        )
        # The inner chat route stops generating on disconnect and returns the partial reply.
        client_left = await _embeddings_client_gone(request)
        api_monitor.finish(monitor_id, "cancelled" if client_left else "completed")
        return _model_json_response(response)
    except asyncio.CancelledError:
        api_monitor.finish(monitor_id, "cancelled")
        raise
    except Exception as exc:
        api_monitor.fail(monitor_id, _friendly_error(exc))
        raise
    finally:
        if request_state is not None:
            request_state.skip_api_monitor = previous_skip_monitor


def _responses_error_code(exc: Exception) -> str:
    if _classify_llama_generation_error(exc):
        return "context_length_exceeded"
    return "server_error"


class _ResponsesStreamTranslator:
    """Chat Completions stream chunks -> named Responses SSE events for one response.

    Output items are allocated as upstream deltas appear. Reasoning/text deltas
    open top-level ``reasoning`` / ``message`` items; each tool call from
    ``delta.tool_calls[]`` is promoted to its own top-level ``function_call``
    item (one per distinct ``tool_calls[].index``). Regular functions relay
    argument deltas. Codex's bridged ``apply_patch`` call is buffered and
    restored to one native ``custom_tool_call`` item with raw patch input.
    """

    def __init__(
        self,
        *,
        payload: ResponsesRequest,
        chat_req: ChatCompletionRequest,
        request: Request,
        monitor_id: Optional[str],
        resp_id: str,
        created_at: int,
        model: Optional[str],
        context_length: Optional[int],
        parse_think_markers: bool,
        healer: Optional[StreamToolCallHealer],
        connection: bool = False,
    ) -> None:
        self.payload = payload
        self.request = request
        self.monitor_id = monitor_id
        self.resp_id = resp_id
        self.created_at = created_at
        self.model = model
        self.context_length = context_length
        # A Connection relays an external provider's stream, read by its own rules below.
        self.connection = connection
        self.custom_tool_names = _responses_custom_tool_names(payload.tools)
        self.namespaced_tool_names = _responses_namespaced_tool_names(payload.tools)
        self.full_reasoning = ""
        self.input_tokens = 0
        self.output_tokens = 0
        self.cached_input: Optional[int] = None
        # From the chat chunks; applied once before finish, so chunk order does not matter.
        self.stream_finish_reason: Optional[str] = None
        self.extractor = _ResponsesReasoningExtractor(
            parse_think_markers = parse_think_markers,
            single_block = connection or _response_format_constrains_decoding(chat_req),
        )
        self.reasoning_state: dict[str, Any] = {
            "output_index": None,
            "item_id": None,
            "opened": False,
        }
        self.message_state: dict[str, Any] = {
            "output_index": None,
            "item_id": None,
            "opened": False,
            "text": "",
        }
        # Message items a healed tool call closed mid-stream, for the response.completed snapshot.
        self.closed_message_states: list[dict] = []
        # Keyed by chat `tool_calls[].index`, stable across a call's chunks.
        self.tool_call_state: dict[int, dict] = {}
        self.next_output_index = 0
        # Promotes text-form calls to declared client tools; dormant once structured deltas appear.
        self.healer = healer
        self.healed_tc_index = 0
        self.terminated = False
        self.sequence_number = 0

    def sse(self, event_name: str, payload: dict) -> str:
        payload = {**payload, "sequence_number": self.sequence_number}
        self.sequence_number += 1
        return f"event: {event_name}\ndata: {json.dumps(payload)}\n\n"

    def _healed_tc(self, call: dict):
        # Disjoint index range: a healed call never merges into a structured call's slot. The
        # upstream parallel cap ran before injection, so it is applied here too.
        if self.payload.parallel_tool_calls is False and self.healed_tc_index >= 1:
            return None
        tc = {
            "index": 1_000_000 + self.healed_tc_index,
            "id": call["id"],
            "type": "function",
            "function": call["function"],
        }
        self.healed_tc_index += 1
        return tc

    def _tool_call_delta_events(self, tc: dict) -> list:
        events = []
        idx = tc.get("index", 0)
        st = self.tool_call_state.get(idx)
        fn = tc.get("function") or {}
        if st is None:
            st = {
                "output_index": self._claim_output_index(),
                "item_id": f"fc_{uuid.uuid4().hex[:12]}",
                "call_id": tc.get("id") or "",
                "name": fn.get("name") or "",
                "arguments": "",
                "opened": False,
            }
            self.tool_call_state[idx] = st
        else:
            # id/name may arrive on a later chunk, once.
            if tc.get("id") and not st["call_id"]:
                st["call_id"] = tc["id"]
            if fn.get("name") and not st["name"]:
                st["name"] = fn["name"]

        is_custom_tool = st["name"] in self.custom_tool_names
        if not is_custom_tool and not st["opened"] and st["call_id"] and st["name"]:
            item_added = {
                "type": "response.output_item.added",
                "output_index": st["output_index"],
                "item": {
                    "type": "function_call",
                    "id": st["item_id"],
                    "status": "in_progress",
                    "call_id": st["call_id"],
                    **_responses_function_call_name(st["name"], self.namespaced_tool_names),
                    "arguments": "",
                },
            }
            events.append(self.sse("response.output_item.added", item_added))
            st["opened"] = True

        arg_delta = fn.get("arguments") or ""
        if arg_delta:
            st["arguments"] += arg_delta
        if arg_delta and st["opened"]:
            args_delta_event = {
                "type": "response.function_call_arguments.delta",
                "item_id": st["item_id"],
                "output_index": st["output_index"],
                "delta": arg_delta,
            }
            events.append(self.sse("response.function_call_arguments.delta", args_delta_event))
        return events

    def _claim_output_index(self) -> int:
        output_index = self.next_output_index
        self.next_output_index += 1
        return output_index

    def _apply_usage(
        self,
        u,
        timings = None,
    ) -> None:
        # No early return on a falsy usage: the final chunk can carry timings alone.
        if isinstance(u, dict):
            self.input_tokens = u.get("prompt_tokens", self.input_tokens)
            self.output_tokens = u.get("completion_tokens", self.output_tokens)
            cached = cached_prompt_tokens(u)
            self.cached_input = self.cached_input if cached is None else cached
        _monitor_usage(self.monitor_id, u, self.context_length, timings = timings)

    def _ensure_reasoning_open(self) -> list[str]:
        if self.reasoning_state["opened"]:
            return []
        self.reasoning_state["output_index"] = self._claim_output_index()
        self.reasoning_state["item_id"] = f"rs_{uuid.uuid4().hex[:12]}"
        self.reasoning_state["opened"] = True
        output_index = self.reasoning_state["output_index"]
        item_id = self.reasoning_state["item_id"]
        return [
            self.sse(
                "response.output_item.added",
                {
                    "type": "response.output_item.added",
                    "output_index": output_index,
                    "item": {
                        "type": "reasoning",
                        "id": item_id,
                        "status": "in_progress",
                        "summary": [],
                        "content": [],
                    },
                },
            ),
            self.sse(
                "response.content_part.added",
                {
                    "type": "response.content_part.added",
                    "item_id": item_id,
                    "output_index": output_index,
                    "content_index": 0,
                    "part": {"type": "reasoning_text", "text": ""},
                },
            ),
        ]

    def _ensure_message_open(self) -> list[str]:
        if self.message_state["opened"]:
            return []
        self.message_state["output_index"] = self._claim_output_index()
        self.message_state["item_id"] = f"msg_{uuid.uuid4().hex[:12]}"
        self.message_state["opened"] = True
        output_index = self.message_state["output_index"]
        item_id = self.message_state["item_id"]
        return [
            self.sse(
                "response.output_item.added",
                {
                    "type": "response.output_item.added",
                    "output_index": output_index,
                    "item": {
                        "type": "message",
                        "id": item_id,
                        "status": "in_progress",
                        "role": "assistant",
                        "content": [],
                    },
                },
            ),
            self.sse(
                "response.content_part.added",
                {
                    "type": "response.content_part.added",
                    "item_id": item_id,
                    "output_index": output_index,
                    "content_index": 0,
                    "part": {"type": "output_text", "text": "", "annotations": []},
                },
            ),
        ]

    def _close_message_item(self) -> list[str]:
        """Close the open message item so later text opens a fresh one.

        Emits the same done-event triplet the end-of-stream close loop
        would, records the item for the final snapshot, and resets the
        state in place. No-op when no message item is open.
        """
        message_state = self.message_state
        if not message_state["opened"]:
            return []
        text = message_state["text"]
        events = [
            self.sse(
                "response.output_text.done",
                {
                    "type": "response.output_text.done",
                    "item_id": message_state["item_id"],
                    "output_index": message_state["output_index"],
                    "content_index": 0,
                    "text": text,
                },
            ),
            self.sse(
                "response.content_part.done",
                {
                    "type": "response.content_part.done",
                    "item_id": message_state["item_id"],
                    "output_index": message_state["output_index"],
                    "content_index": 0,
                    "part": {"type": "output_text", "text": text, "annotations": []},
                },
            ),
            self.sse(
                "response.output_item.done",
                {
                    "type": "response.output_item.done",
                    "output_index": message_state["output_index"],
                    "item": {
                        "type": "message",
                        "id": message_state["item_id"],
                        "status": "completed",
                        "role": "assistant",
                        "content": [{"type": "output_text", "text": text, "annotations": []}],
                    },
                },
            ),
        ]
        self.closed_message_states.append(dict(message_state))
        message_state.update({"output_index": None, "item_id": None, "opened": False, "text": ""})
        return events

    # Generators, so the opening events go out before the reply is recorded.
    def _visible_text_events(self, value: str) -> Iterator[str]:
        yield from self._ensure_message_open()
        self.message_state["text"] += value
        api_monitor.append_reply(self.monitor_id, value)
        yield self.sse(
            "response.output_text.delta",
            {
                "type": "response.output_text.delta",
                "item_id": self.message_state["item_id"],
                "output_index": self.message_state["output_index"],
                "content_index": 0,
                "delta": value,
            },
        )

    def _reasoning_text_events(self, value: str) -> Iterator[str]:
        yield from self._ensure_reasoning_open()
        self.full_reasoning += value
        yield self.sse(
            "response.reasoning_text.delta",
            {
                "type": "response.reasoning_text.delta",
                "item_id": self.reasoning_state["item_id"],
                "output_index": self.reasoning_state["output_index"],
                "content_index": 0,
                "delta": value,
            },
        )

    def _healed_event_sse(self, events) -> list[str]:
        """Serialize healer events preserving their order.

        Text around a healed call must keep its position relative to the
        function_call item (output indexes are claimed in emission order),
        so never split an event list into all-text-then-all-calls. A healed
        call also CLOSES any open message item, so trailing text opens a
        fresh message with a later output index, exactly like a native
        Responses stream that interleaves messages and calls.
        """
        out: list[str] = []
        for kind, value in events:
            if kind == "text":
                if not value:
                    continue
                out.extend(self._visible_text_events(value))
            else:
                tc = self._healed_tc(value)
                if tc is None:
                    continue
                out.extend(self._close_message_item())
                out.extend(self._tool_call_delta_events(tc))
        return out

    def _snapshot_output(self, active_item_status: str = "completed") -> list[dict]:
        """Snapshot output items using the response's terminal state."""
        indexed_items: list[tuple[int, dict]] = []
        if self.reasoning_state["opened"]:
            indexed_items.append(
                (
                    self.reasoning_state["output_index"],
                    {
                        "type": "reasoning",
                        "id": self.reasoning_state["item_id"],
                        "status": active_item_status,
                        "summary": [],
                        "content": [{"type": "reasoning_text", "text": self.full_reasoning}],
                    },
                )
            )
        # Closed copies keep opened=True (snapshotted before reset); the
        # live state contributes only when a message is currently open.
        for msg_st in [*self.closed_message_states, self.message_state]:
            if not msg_st["opened"]:
                continue
            indexed_items.append(
                (
                    msg_st["output_index"],
                    {
                        "type": "message",
                        "id": msg_st["item_id"],
                        "status": (
                            "completed" if msg_st is not self.message_state else active_item_status
                        ),
                        "role": "assistant",
                        "content": [
                            {
                                "type": "output_text",
                                "text": msg_st["text"],
                                "annotations": [],
                            }
                        ],
                    },
                )
            )
        for st in self.tool_call_state.values():
            if st["name"] in self.custom_tool_names:
                item = {
                    "type": "custom_tool_call",
                    "status": active_item_status,
                    "call_id": st["call_id"],
                    "name": st["name"],
                    "input": _responses_custom_tool_input(st["arguments"]),
                }
            else:
                item = {
                    "type": "function_call",
                    "id": st["item_id"],
                    "status": active_item_status,
                    "call_id": st["call_id"],
                    **_responses_function_call_name(st["name"], self.namespaced_tool_names),
                    "arguments": st["arguments"],
                }
            indexed_items.append(
                (
                    st["output_index"],
                    item,
                )
            )
        return [item for _, item in sorted(indexed_items, key = lambda pair: pair[0])]

    def created(self) -> str:
        return self.sse(
            "response.created",
            {
                "type": "response.created",
                "response": {
                    "id": self.resp_id,
                    "object": "response",
                    "created_at": self.created_at,
                    "status": "in_progress",
                    "model": self.model,
                    "output": [],
                    "usage": {"input_tokens": 0, "output_tokens": 0, "total_tokens": 0},
                },
            },
        )

    def failed(
        self,
        exc: Exception,
        *,
        message: Optional[str] = None,
        code: Optional[str] = None,
    ) -> str:
        """In-band ``response.failed`` carrying everything streamed so far."""
        from core.inference.llama_keepwarm import mark_response_failed

        # Built only after the 200 headers, so flag failed: the middleware must
        # not treat a failed stream as a success.
        mark_response_failed(getattr(self.request, "scope", None))
        return self.sse(
            "response.failed",
            {
                "type": "response.failed",
                "response": {
                    "id": self.resp_id,
                    "object": "response",
                    "created_at": self.created_at,
                    "status": "failed",
                    "model": self.model,
                    "output": self._snapshot_output(),
                    "usage": {
                        "input_tokens": self.input_tokens,
                        "output_tokens": self.output_tokens,
                        "total_tokens": self.input_tokens + self.output_tokens,
                    },
                    "error": {
                        "code": code or _responses_error_code(exc),
                        "message": message or _friendly_error(exc),
                    },
                },
            },
        )

    def feed(self, chunk_data: dict) -> Iterator[str]:
        """Translate one chat chunk; sets ``terminated`` after an in-band failure."""
        monitor_id = self.monitor_id
        if self.payload.parallel_tool_calls is False:
            _drop_parallel_tool_call_deltas(chunk_data)

        choices = chunk_data.get("choices", [])
        # A Connection can report a mid-stream error beside a non-empty choices array
        # (OpenRouter does), so it is checked before choices there.
        if not choices or (self.connection and chunk_data.get("error")):
            error_message = _monitor_openai_error_message(chunk_data)
            if error_message:
                # A 200 SSE error payload is a failed generation: response.failed flags the scope,
                # so no response.completed follows and no preview-owned slot is claimed.
                api_monitor.fail(monitor_id, error_message)
                self.terminated = True
                error = chunk_data.get("error")
                yield self.failed(
                    RuntimeError(error_message),
                    message = error_message if self.connection else None,
                    code = "rate_limit_exceeded"
                    if self.connection
                    and isinstance(error, dict)
                    and str(error.get("code")) == "429"
                    else None,
                )
                return
        if not choices:
            self._apply_usage(chunk_data.get("usage"), chunk_data.get("timings"))
            return
        if choices[0].get("finish_reason"):
            self.stream_finish_reason = choices[0]["finish_reason"]

        delta = choices[0].get("delta", {}) or {}
        reasoning_delta, visible_delta = self.extractor.feed(
            delta.get("content") or "",
            delta.get("reasoning_content"),
        )
        if reasoning_delta:
            # Not on visible text: the client already has this, so waiting would
            # time from the end of the thinking block instead.
            api_monitor.mark_first_token(monitor_id)
            yield from self._reasoning_text_events(reasoning_delta)
        # Visible text only, never reasoning. Healer events keep their order so text after a
        # healed call never jumps ahead of its function_call item.
        healer = self.healer
        if healer is not None and not healer.dormant:
            healed_events = []
            if delta.get("tool_calls"):
                # Held text preceded the structured call.
                healed_events = healer.structured_tool_call_seen()
                if visible_delta:
                    healed_events.append(("text", visible_delta))
            elif visible_delta:
                healed_events = healer.feed(visible_delta)
            visible_delta = ""
            if healed_events:
                # Not append_reply below: this is where the client first sees
                # the promoted tool call or its surrounding text.
                api_monitor.mark_first_token(monitor_id)
            yield from self._healed_event_sse(healed_events)
        if visible_delta:
            yield from self._visible_text_events(visible_delta)

        if delta.get("tool_calls"):
            # A tool call is output the client already received; stamp it too.
            api_monitor.mark_first_token(monitor_id)
        for tc in delta.get("tool_calls") or []:
            if (
                self.payload.parallel_tool_calls is False
                and self.healed_tc_index >= 1
                and tc.get("index", 0) not in self.tool_call_state
            ):
                # A healed call took the single slot, and _drop_parallel_tool_call_deltas sees
                # only native indexes, so a native call would open a second function_call item.
                continue
            yield from self._tool_call_delta_events(tc)

        self._apply_usage(chunk_data.get("usage"), chunk_data.get("timings"))

    def finish(self) -> Iterator[str]:
        """Flush held text, close every open item and emit the terminal event."""
        monitor_id = self.monitor_id
        final_reasoning, final_visible = self.extractor.finish()
        if final_reasoning:
            # Held-back markers can make this the FIRST output of all.
            api_monitor.mark_first_token(monitor_id)
            yield from self._reasoning_text_events(final_reasoning)
        # Heal held residue (an unclosed tool block) before the trailing text, keeping healer order.
        healer = self.healer
        if healer is not None:
            events = (healer.feed(final_visible) if final_visible else []) + healer.finalize()
            final_visible = ""
            if events:
                # Same as the in-loop stamp: this is where the client first sees
                # the promoted call, and the item only closes several yields later.
                api_monitor.mark_first_token(monitor_id)
            yield from self._healed_event_sse(events)
        if final_visible:
            yield from self._visible_text_events(final_visible)

        # Healing changes a natural stop into tool_calls, but it must not erase
        # an authoritative truncation or failure reason from the upstream model.
        if healer is not None and healer.healed and self.stream_finish_reason in (None, "stop"):
            self.stream_finish_reason = "tool_calls"

        incomplete_reason = _responses_incomplete_reason(self.stream_finish_reason)
        truncated = incomplete_reason is not None
        active_item_status = "incomplete" if truncated else "completed"

        close_items: list[tuple[int, str, dict[str, Any]]] = []
        if self.reasoning_state["opened"]:
            close_items.append(
                (self.reasoning_state["output_index"], "reasoning", self.reasoning_state)
            )
        if self.message_state["opened"]:
            close_items.append((self.message_state["output_index"], "message", self.message_state))
        close_items.extend((st["output_index"], "tool", st) for st in self.tool_call_state.values())

        full_reasoning = self.full_reasoning
        for _, kind, st in sorted(close_items, key = lambda item: item[0]):
            if kind == "reasoning":
                yield self.sse(
                    "response.reasoning_text.done",
                    {
                        "type": "response.reasoning_text.done",
                        "item_id": st["item_id"],
                        "output_index": st["output_index"],
                        "content_index": 0,
                        "text": full_reasoning,
                    },
                )
                yield self.sse(
                    "response.content_part.done",
                    {
                        "type": "response.content_part.done",
                        "item_id": st["item_id"],
                        "output_index": st["output_index"],
                        "content_index": 0,
                        "part": {"type": "reasoning_text", "text": full_reasoning},
                    },
                )
                yield self.sse(
                    "response.output_item.done",
                    {
                        "type": "response.output_item.done",
                        "output_index": st["output_index"],
                        "item": {
                            "type": "reasoning",
                            "id": st["item_id"],
                            "status": active_item_status,
                            "summary": [],
                            "content": [{"type": "reasoning_text", "text": full_reasoning}],
                        },
                    },
                )
                continue

            if kind == "message":
                # Items closed mid-stream already emitted their done events: this one's text only.
                _msg_text = st["text"]
                yield self.sse(
                    "response.output_text.done",
                    {
                        "type": "response.output_text.done",
                        "item_id": st["item_id"],
                        "output_index": st["output_index"],
                        "content_index": 0,
                        "text": _msg_text,
                    },
                )
                yield self.sse(
                    "response.content_part.done",
                    {
                        "type": "response.content_part.done",
                        "item_id": st["item_id"],
                        "output_index": st["output_index"],
                        "content_index": 0,
                        "part": {"type": "output_text", "text": _msg_text, "annotations": []},
                    },
                )
                yield self.sse(
                    "response.output_item.done",
                    {
                        "type": "response.output_item.done",
                        "output_index": st["output_index"],
                        "item": {
                            "type": "message",
                            "id": st["item_id"],
                            "status": active_item_status,
                            "role": "assistant",
                            "content": [
                                {"type": "output_text", "text": _msg_text, "annotations": []}
                            ],
                        },
                    },
                )
                continue

            if st["name"] in self.custom_tool_names:
                if not st["call_id"]:
                    st["call_id"] = f"call_{uuid.uuid4().hex[:12]}"
                custom_input = _responses_custom_tool_input(st["arguments"])
                item_done = {
                    "type": "response.output_item.done",
                    "output_index": st["output_index"],
                    "item": {
                        "type": "custom_tool_call",
                        "status": active_item_status,
                        "call_id": st["call_id"],
                        "name": st["name"],
                        "input": custom_input,
                    },
                }
                api_monitor.append_reply(monitor_id, _monitor_call_text(st["name"], custom_input))
                yield self.sse("response.output_item.done", item_done)
                continue

            # id/name never arrived (malformed upstream): synthesise a coherent frame sequence.
            if not st["opened"]:
                if not st["call_id"]:
                    st["call_id"] = f"call_{uuid.uuid4().hex[:12]}"
                item_added = {
                    "type": "response.output_item.added",
                    "output_index": st["output_index"],
                    "item": {
                        "type": "function_call",
                        "id": st["item_id"],
                        "status": "in_progress",
                        "call_id": st["call_id"],
                        **_responses_function_call_name(st["name"], self.namespaced_tool_names),
                        "arguments": "",
                    },
                }
                yield self.sse("response.output_item.added", item_added)
                if st["arguments"]:
                    yield self.sse(
                        "response.function_call_arguments.delta",
                        {
                            "type": "response.function_call_arguments.delta",
                            "item_id": st["item_id"],
                            "output_index": st["output_index"],
                            "delta": st["arguments"],
                        },
                    )
                st["opened"] = True

            args_done = {
                "type": "response.function_call_arguments.done",
                "item_id": st["item_id"],
                "output_index": st["output_index"],
                **_responses_function_call_name(st["name"], self.namespaced_tool_names),
                "arguments": st["arguments"],
            }
            yield self.sse("response.function_call_arguments.done", args_done)

            item_done = {
                "type": "response.output_item.done",
                "output_index": st["output_index"],
                "item": {
                    "type": "function_call",
                    "id": st["item_id"],
                    "status": active_item_status,
                    "call_id": st["call_id"],
                    **_responses_function_call_name(st["name"], self.namespaced_tool_names),
                    "arguments": st["arguments"],
                },
            }
            api_monitor.append_reply(monitor_id, _monitor_call_text(st["name"], st["arguments"]))
            yield self.sse("response.output_item.done", item_done)

        total_tokens = self.input_tokens + self.output_tokens
        terminal_event = "response.incomplete" if truncated else "response.completed"
        terminal_response = {
            "type": terminal_event,
            "response": {
                "id": self.resp_id,
                "object": "response",
                "created_at": self.created_at,
                "status": "incomplete" if truncated else "completed",
                "incomplete_details": ({"reason": incomplete_reason} if truncated else None),
                "model": self.model,
                "output": self._snapshot_output(active_item_status),
                "usage": {
                    "input_tokens": self.input_tokens,
                    "output_tokens": self.output_tokens,
                    "total_tokens": total_tokens,
                    **(
                        {}
                        if self.cached_input is None
                        else {"input_tokens_details": {"cached_tokens": self.cached_input}}
                    ),
                },
            },
        }
        if self.stream_finish_reason:
            api_monitor.set_perf(monitor_id, stop_reason = self.stream_finish_reason)
        api_monitor.finish(monitor_id)
        yield self.sse(terminal_event, terminal_response)


@contextmanager
def _delegated_request_state(request, **values):
    """Set ``request.state`` attributes around a call into another handler, then restore them."""
    state = getattr(request, "state", None)
    if state is None:
        state = type("_RequestState", (), {})()
        try:
            setattr(request, "state", state)
        except Exception:
            state = None
    missing = object()
    previous = {}
    if state is not None:
        previous = {name: getattr(state, name, missing) for name in values}
        for name, value in values.items():
            setattr(state, name, value)
    try:
        yield
    finally:
        for name, value in previous.items():
            if value is missing:
                delattr(state, name)
            else:
                setattr(state, name, value)


class _InProcessChatStream:
    """``openai_chat_completions`` on an in-process model as the inner stream of a compat route.

    The caller owns the API monitor, so the inner one is suppressed and asked for usage. The
    inner run polls ``cancel_event``, and a cancelled run ends like a finished one, so
    ``cancelled`` is how the caller tells them apart.
    """

    def __init__(self, response, cancel_event: threading.Event) -> None:
        self._iterator = response.body_iterator
        self._unstarted_cleanup = getattr(response, "_unstarted_cleanup", None)
        self._started = False
        self.cancel_event = cancel_event

    @classmethod
    async def open(
        cls,
        chat_req: ChatCompletionRequest,
        request,
        current_subject,
        cancel_event: Optional[threading.Event] = None,
        tool_names = None,
    ):
        """``tool_names``: the caller's server-tool selection, run with chat's tool-loop frames."""
        chat_req.stream = True
        chat_req.stream_options = {"include_usage": True}
        cancel_event = cancel_event or threading.Event()
        with (
            _delegated_request_state(
                request,
                skip_api_monitor = True,
                generation_cancel_event = cancel_event,
                # Only a server-tool caller relays chat's control frames; elsewhere an approval
                # prompt would be lost, so the client's opt-in is hidden.
                ui_stream_events = tool_names is not None,
            ),
            _delegated_tool_selection(tool_names),
        ):
            response = await openai_chat_completions(chat_req, request, current_subject)
        if getattr(response, "body_iterator", None) is None:
            raise HTTPException(
                status_code = 400, detail = "The loaded model does not produce a text stream."
            )
        return cls(response, cancel_event)

    @property
    def cancelled(self) -> bool:
        return self.cancel_event.is_set()

    async def chunks(self):
        """Each chat chunk as a dict, or ``_LLAMA_STREAM_KEEPALIVE`` for a stall keepalive."""
        self._started = True
        async for raw in self._iterator:
            text = raw.decode() if isinstance(raw, bytes) else raw
            for line in text.split("\n"):
                if line.startswith(":"):
                    yield _LLAMA_STREAM_KEEPALIVE
                    continue
                if not line.startswith("data: "):
                    continue
                data = line[6:]
                if data.strip() == "[DONE]":
                    return
                try:
                    yield json.loads(data)
                except json.JSONDecodeError:
                    continue

    async def next_chunk(self, chunks):
        """The next of ``chunks``, or None at its end, a Stop the source raised included."""
        try:
            return await chunks.__anext__()
        except StopAsyncIteration:
            return None
        except asyncio.CancelledError:
            # The managed engine tool path turns its own Stop into CancelledError; that ends
            # the stream like any stopped run, and only the consumer's cancellation propagates.
            # Task.cancelling is 3.11+; without it every cancellation is treated as the consumer's.
            cancelling = getattr(asyncio.current_task(), "cancelling", None)
            if self.cancelled and cancelling is not None and not cancelling():
                return None
            raise

    async def close(self, *, cancelled: bool) -> None:
        if self._started:
            await _close_openai_admitted_stream_iterator(self._iterator, cancelled = cancelled)
        else:
            # Its tracker was entered before it returned, and only this hook exits it.
            await _release_unstarted_anthropic_stream(self._iterator, self._unstarted_cleanup)


async def _responses_in_process_stream(
    payload: ResponsesRequest,
    chat_req: ChatCompletionRequest,
    request: Request,
    monitor_id: Optional[str],
    current_subject: Optional[str],
    resp_id: str,
    created_at: int,
):
    """Stream /v1/responses from an in-process model (MLX, transformers) through chat."""
    from core.inference.llama_keepwarm import mark_response_failed

    # Registered by the chat handler's tracker, so a cancel by response id, thread or run
    # reaches the run just as it does on llama-server.
    chat_req.cancel_id = resp_id
    chat_req.thread_id = getattr(payload, "thread_id", None)
    chat_req.generation_run_id = getattr(payload, "generation_run_id", None)
    source = await _InProcessChatStream.open(chat_req, request, current_subject)
    try:
        backend = await asyncio.to_thread(get_inference_backend)
        translator = _ResponsesStreamTranslator(
            payload = payload,
            chat_req = chat_req,
            request = request,
            monitor_id = monitor_id,
            resp_id = resp_id,
            created_at = created_at,
            model = _orchestrator_public_model_id(backend) or payload.model,
            context_length = _monitor_context_length(),
            parse_think_markers = _responses_should_parse_think_markers(
                chat_req, get_llama_cpp_backend()
            ),
            # Chat already healed text-form tool calls.
            healer = None,
        )
    except BaseException:
        await source.close(cancelled = False)
        raise

    async def event_generator():
        chunks = source.chunks()
        cancelled = False
        try:
            yield translator.created()
            while (chunk := await source.next_chunk(chunks)) is not None:
                if chunk is _LLAMA_STREAM_KEEPALIVE:
                    yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                    continue
                for event in translator.feed(chunk):
                    yield event
                if translator.terminated:
                    return
            if source.cancelled:
                mark_response_failed(getattr(request, "scope", None))
                api_monitor.finish(monitor_id, "cancelled")
                return
            for event in translator.finish():
                yield event
        except asyncio.CancelledError:
            cancelled = True
            source.cancel_event.set()
            api_monitor.finish(monitor_id, "cancelled")
            raise
        except Exception as e:
            if source.cancelled:
                mark_response_failed(getattr(request, "scope", None))
                api_monitor.finish(monitor_id, "cancelled")
                return
            logger.error("responses stream error: %s", e)
            api_monitor.fail(monitor_id, _friendly_error(e))
            yield translator.failed(e)
        finally:
            await chunks.aclose()
            await source.close(cancelled = cancelled)

    async def _unstarted_cleanup() -> None:
        api_monitor.finish(monitor_id, "cancelled")
        await source.close(cancelled = False)

    return _sse_streaming_response(
        event_generator(), unstarted_cleanup = _unstarted_cleanup, monitor_id = monitor_id
    )


async def _sse_data_lines(chunks):
    pending = ""
    try:
        async for chunk in chunks:
            pending += chunk.decode("utf-8") if isinstance(chunk, bytes) else chunk
            *complete, pending = pending.split("\n")
            for line in complete:
                yield line
        if pending:
            yield pending
    finally:
        await chunks.aclose()


async def _responses_stream(
    payload: ResponsesRequest,
    messages: list[ChatMessage],
    request: Request,
    monitor_id: Optional[str] = None,
    current_subject: Optional[str] = None,
    connection: Optional[tuple[str, str]] = None,
):
    """Handle a streaming Responses API call, emitting named SSE events.

    For GGUF models the request goes directly to llama-server's
    ``/v1/chat/completions`` from inside the StreamingResponse child task -- one
    httpx lifecycle, one async generator. Wrapping the existing
    ``openai_chat_completions`` pass-through (which has its own httpx lifecycle)
    stacks two generators: Python 3.13 + httpcore 1.0.x then loses the
    close-propagation chain on the innermost ``HTTP11ConnectionByteStream`` at
    asyncgen finalisation, tripping "Attempted to exit cancel scope in a
    different task" / "async generator ignored GeneratorExit". The direct path
    avoids that. Non-GGUF falls back to the wrapper (which doesn't use httpx, so
    the issue doesn't apply).
    """
    from core.inference.llama_keepwarm import mark_response_failed

    resp_id = f"resp_{uuid.uuid4().hex[:12]}"
    created_at = int(time.time())

    chat_req = _build_chat_request(payload, messages, stream = True)

    llama_backend = get_llama_cpp_backend()
    orchestrator = _peek_inference_backend()
    entry = (getattr(orchestrator, "models", None) or {}).get(
        getattr(orchestrator, "active_model_name", None)
    )
    upstream = None
    if connection is not None:
        # A Connection model: the chat proxy serves it and the converter below relays its stream.
        chat_req.provider_id, chat_req.external_model = connection
        _restore_connection_tool_extras(current_subject, chat_req.messages)
        chat_req.stream_options = {"include_usage": True}
        request.state.skip_api_monitor = True
        upstream = await produce_openai_chat_completions(
            chat_req, request, current_subject, cancel_on_disconnect = True
        )
        if not isinstance(upstream, StreamingResponse):
            return upstream
        body = {
            "tools": chat_req.tools,
            "tool_choice": chat_req.tool_choice,
            "response_format": chat_req.response_format,
        }
        cancel_event = threading.Event()
    # An NPU model streams through a provider proxy that keeps its own cancel event, and chat
    # answers a TTS model with a finished clip rather than a text stream.
    elif (
        not llama_backend.is_loaded
        and isinstance(entry, dict)
        and not (entry.get("is_audio") and entry.get("audio_type") != "whisper")
    ):
        return await _responses_in_process_stream(
            payload, chat_req, request, monitor_id, current_subject, resp_id, created_at
        )
    elif not llama_backend.is_loaded:
        _status, _detail = await _no_model_loaded_error(
            "Streaming /v1/responses requires a GGUF model loaded via llama-server or an "
            "in-process model. Use non-streaming /v1/responses or /v1/chat/completions.",
            _switch_model_for_payload(payload),
            request,
            status = 400,
        )
        raise HTTPException(status_code = _status, detail = _detail)

    if upstream is None:
        # Direct pass-through bypasses the openai_chat_completions tool-image note and image gate.
        if not llama_backend.is_vision:
            _omit_tool_images(chat_req.messages)
            if _messages_have_image(chat_req.messages):
                raise HTTPException(
                    status_code = 400,
                    detail = "Image provided but current GGUF model does not support vision.",
                )

        # Same bypass, same reason as the image gate: without this the non-streaming half of this
        # very route folds a Studio tool thread and answers while the streaming half still ships
        # role="tool" to a template that cannot render it, so one thread's replies depend on which
        # half the client called.
        if _folds_studio_tool_history(chat_req, llama_backend):
            chat_req.messages = _folded_studio_tool_messages(chat_req.messages)

        # Streaming /v1/responses builds the passthrough body directly (bypassing
        # openai_chat_completions), so apply recommended sampling here too.
        _fill_recommended_sampling_openai(
            chat_req,
            getattr(llama_backend, "model_identifier", None),
            thinking = _sampling_thinking_mode(llama_backend, chat_req),
        )
        body = await _build_openai_passthrough_body_async(
            chat_req, backend_ctx = llama_backend.context_length, llama_backend = llama_backend
        )
        body["stream_options"] = {"include_usage": True}
        # The stream's own disconnect event, shared with the cancel/active-generation registries:
        # this path decodes on llama-server, so a non-forced /unload must see it and refuse instead
        # of tearing the server down mid-response. Entered inside the body generator below, so a
        # response whose body never starts leaves nothing behind.
        cancel_event = threading.Event()
        _tracker = _TrackedCancel.for_payload(cancel_event, payload, resp_id)
        try:
            reservation, admission_config, body = await _reserve_counted_gguf_passthrough(
                request = request,
                llama_backend = llama_backend,
                # chat_req, not payload: a ResponsesRequest carries `input` and
                # `max_output_tokens`, so the estimator found no `messages` and fell back to
                # one equal cache share no matter how large the request really was.
                payload = chat_req,
                body = body,
            )
        except LlamaAdmissionQueueFull as exc:
            _llama_admission_log(
                "queue-full",
                snapshot = exc.snapshot,
                request = request,
                mode = "responses_stream",
                completion_id = resp_id,
                level = "warning",
            )
            api_monitor.fail(monitor_id, str(exc))
            raise _openai_admission_http_exception(exc, status_code = 429)

    def _responses_admission_failed_sse(exc: Exception, *, code: str) -> str:
        # In-band after the 200 headers: flag failed so the middleware does not claim the model.
        mark_response_failed(getattr(request, "scope", None))
        return (
            "event: response.failed\n"
            "data: "
            + json.dumps(
                {
                    "type": "response.failed",
                    "sequence_number": 0,
                    "response": {
                        "id": resp_id,
                        "object": "response",
                        "created_at": created_at,
                        "status": "failed",
                        "model": _llama_public_model_id(llama_backend, payload.model)
                        or payload.model,
                        "output": [],
                        "usage": {
                            "input_tokens": 0,
                            "output_tokens": 0,
                            "total_tokens": 0,
                        },
                        "error": {
                            "code": code,
                            "message": str(exc),
                        },
                    },
                }
            )
            + "\n\n"
        )

    async def event_generator():
        # Clean public id for every response envelope. Prefer the loaded model's
        # id so the stream agrees with /v1/models, chat/completions and the
        # non-streaming twin; fall back to a sanitized payload.model (a legacy
        # raw .gguf path is stripped, never echoed back). Use the advertised-id
        # helper, not the raw identifier: after an auto-switch to a cached HF GGUF
        # the identifier is the snapshot path while the repo id lives in
        # _openai_advertised_id, so the raw form would stream a snapshot basename.
        _clean_model = payload.model
        if upstream is None:
            _clean_model = _llama_public_model_id(llama_backend, payload.model) or payload.model
        _allowed_tools = heal_gate(
            getattr(chat_req, "auto_heal_tool_calls", None),
            body.get("tools"),
            body.get("tool_choice"),
            response_format = body.get("response_format"),
        )
        translator = _ResponsesStreamTranslator(
            payload = payload,
            chat_req = chat_req,
            request = request,
            monitor_id = monitor_id,
            resp_id = resp_id,
            created_at = created_at,
            model = _clean_model,
            context_length = None if upstream is not None else llama_backend.context_length,
            # A Connection's native thinking arrives as a leading <think> block even when thinking is on
            # by default; only that block is read, so a literal tag later in the answer stays text.
            parse_think_markers = (upstream is not None and chat_req.enable_thinking is not False)
            or (
                upstream is None and _responses_should_parse_think_markers(chat_req, llama_backend)
            ),
            connection = upstream is not None,
            healer = (
                StreamToolCallHealer(_allowed_tools, body.get("tools")) if _allowed_tools else None
            ),
        )
        _sse = translator.sse

        yield translator.created()

        # ── Direct httpx lifecycle to llama-server ──
        # Full same-task open + close, same pattern as
        # _openai_passthrough_stream and _anthropic_passthrough_stream: no
        # `async with`, explicit aclose of lines_iter BEFORE resp / client so
        # the innermost httpcore byte stream is finalised in this task (not via
        # the asyncgen GC in a sibling task).
        client = None
        resp = None
        lines_iter = None
        items_iter = None
        disconnect_watcher = None
        # Tracked per-run event: a client disconnect and a forced reload both land here.
        disconnect_event = cancel_event
        try:
            if upstream is not None:
                items_iter = _sse_data_lines(
                    _relay_recording_tool_extras(upstream.body_iterator, current_subject)
                )
            else:
                client = _llama_stream_client()
                llama_upstream = _LlamaUpstream(llama_backend, "/v1/chat/completions")
                try:
                    # Same event the loop below polls: prefill can run for the whole first-token window,
                    # and only the send watcher can end it early.
                    async with aclosing(
                        llama_upstream.stream_response(client, body, disconnect_event, request)
                    ) as opening:
                        async for opened in opening:
                            if opened is _LLAMA_STREAM_KEEPALIVE:
                                yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                            else:
                                resp = opened
                    first_token_deadline = llama_upstream.first_token_deadline
                    if resp is None:
                        api_monitor.finish(monitor_id, "cancelled")
                        return
                except httpx.RequestError as e:
                    logger.error("responses stream: upstream unreachable: %s", e)
                    api_monitor.fail(monitor_id, _friendly_error(e))
                    # 200 headers already flushed; this is an in-band failure, so the
                    # middleware must not claim a preview-owned model for it.
                    mark_response_failed(getattr(request, "scope", None))
                    yield _sse(
                        "response.failed",
                        {
                            "type": "response.failed",
                            "response": {
                                "id": resp_id,
                                "object": "response",
                                "created_at": created_at,
                                "status": "failed",
                                "model": _clean_model,
                                "output": [],
                                "error": {"code": "server_error", "message": _friendly_error(e)},
                            },
                        },
                    )
                    return

                if resp.status_code != 200:
                    err_bytes = await resp.aread()
                    err_text = err_bytes.decode("utf-8", errors = "replace")
                    logger.error(
                        "responses stream upstream error: status=%s body=%s",
                        resp.status_code,
                        err_text[:500],
                    )
                    api_monitor.fail(monitor_id, err_text[:500])
                    # 200 headers already flushed; an upstream non-200 is an in-band
                    # failure, so the middleware must not claim a preview-owned model.
                    mark_response_failed(getattr(request, "scope", None))
                    yield _sse(
                        "response.failed",
                        {
                            "type": "response.failed",
                            "response": {
                                "id": resp_id,
                                "object": "response",
                                "created_at": created_at,
                                "status": "failed",
                                "model": _clean_model,
                                "output": [],
                                "error": {
                                    "code": _responses_error_code(RuntimeError(err_text)),
                                    "message": _friendly_upstream_error(err_text[:500]),
                                },
                            },
                        },
                    )
                    return

                lines_iter = resp.aiter_lines()
                disconnect_watcher = asyncio.create_task(
                    _await_disconnect_then_close(request, resp, disconnect_event)
                )
                items_iter = _aiter_llama_stream_items(
                    lines_iter,
                    cancel_event = disconnect_event,
                    request = request,
                    first_token_deadline = first_token_deadline,
                    response = resp,
                    keepalive_interval_s = _openai_passthrough_stream_keepalive_interval(),
                )
            async for raw_line in items_iter:
                if raw_line is _LLAMA_STREAM_KEEPALIVE:
                    yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                    continue
                if not raw_line:
                    continue
                if not raw_line.startswith("data:"):
                    continue
                data_str = raw_line[5:]
                if data_str.strip() == "[DONE]":
                    break
                try:
                    chunk_data = json.loads(data_str)
                except json.JSONDecodeError:
                    continue
                for event in translator.feed(chunk_data):
                    yield event
                if translator.terminated:
                    return
        except asyncio.CancelledError:
            disconnect_event.set()
            api_monitor.finish(monitor_id, "cancelled")
            raise
        except (httpx.RemoteProtocolError, httpx.ReadError, httpx.CloseError) as e:
            if not disconnect_event.is_set():
                logger.error("responses stream error: %s", e)
                api_monitor.fail(monitor_id, _friendly_error(e))
                yield translator.failed(e)
                return
        except Exception as e:
            if disconnect_event.is_set():
                mark_response_failed(getattr(request, "scope", None))
                api_monitor.finish(monitor_id, "cancelled")
                return
            logger.error("responses stream error: %s", e)
            api_monitor.fail(monitor_id, _friendly_error(e))
            yield translator.failed(e)
            return
        finally:
            await _aclose_stream_resources(
                watchers = (disconnect_watcher,),
                items = items_iter,
                iterator = lines_iter,
                resp = resp,
                client = client,
            )

        if disconnect_event.is_set():
            # Disconnect after headers is a cancellation: flag failed so preview ownership is kept.
            mark_response_failed(getattr(request, "scope", None))
            api_monitor.finish(monitor_id, "cancelled")
            return

        for event in translator.finish():
            yield event

    if upstream is not None:
        return _sse_streaming_response(event_generator(), monitor_id = monitor_id)

    async def admitted_event_generator():
        # Registered for the body's whole lifetime (admission wait included) so /load and /unload count
        # it; __exit__ runs in the finally below.
        _tracker.__enter__()
        lease = reservation.lease_nowait()
        admission_wait_started_at = None
        stream_started = False
        stream_cancelled = False
        iterator = None
        try:
            if lease is None:
                admission_wait_started_at = time.monotonic()
                _llama_admission_log(
                    "queued",
                    reservation,
                    request = request,
                    mode = "responses_stream",
                    completion_id = resp_id,
                    level = "debug",
                )
                # Use the tracked event so a forced swap's cancel_all() reaches this run while still queued.
                async for wait_item in _openai_admission_wait_stream_chunks(
                    reservation,
                    admission_config,
                    request = request,
                    cancel_event = cancel_event,
                ):
                    if isinstance(wait_item, str):
                        yield wait_item
                        continue
                    lease = wait_item
                    _llama_admission_log(
                        "granted-after-wait",
                        reservation,
                        request = request,
                        mode = "responses_stream",
                        wait_started_at = admission_wait_started_at,
                        completion_id = resp_id,
                        level = "debug",
                    )
                    break
            if lease is None:
                return
            await _raise_if_openai_admission_cancelled(
                reservation,
                request = request,
                cancel_event = cancel_event,
            )
            iterator = event_generator()
            stream_started = True
            try:
                async for chunk in iterator:
                    yield chunk
            except asyncio.CancelledError:
                stream_cancelled = True
                api_monitor.finish(monitor_id, "cancelled")
                raise
            finally:
                await _close_openai_admitted_stream_iterator(
                    iterator,
                    cancelled = stream_cancelled,
                )
        except LlamaAdmissionTimeout as exc:
            _llama_admission_log(
                "timeout",
                reservation,
                request = request,
                mode = "responses_stream",
                wait_started_at = admission_wait_started_at,
                completion_id = resp_id,
                level = "warning",
            )
            api_monitor.fail(monitor_id, str(exc))
            yield _responses_admission_failed_sse(exc, code = "server_is_overloaded")
        except LlamaAdmissionCancelled:
            _llama_admission_log(
                "cancelled-before-upstream",
                reservation,
                request = request,
                mode = "responses_stream",
                wait_started_at = admission_wait_started_at,
                completion_id = resp_id,
                level = "debug",
            )
            api_monitor.finish(monitor_id, "cancelled")
            return
        except asyncio.CancelledError:
            api_monitor.finish(monitor_id, "cancelled")
            raise
        finally:
            if lease is not None:
                lease.release()
            if not stream_started:
                api_monitor.finish(monitor_id, "cancelled")
                reservation.cancel()
            _tracker.__exit__(None, None, None)

    async def _responses_admission_unstarted_cleanup() -> None:
        api_monitor.finish(monitor_id, "cancelled")
        reservation.cancel()

    return _sse_streaming_response(
        admitted_event_generator(),
        unstarted_cleanup = _responses_admission_unstarted_cleanup,
        monitor_id = monitor_id,
    )


@router.post("/responses")
@account_access.gpu_busy_route
async def openai_responses(
    payload: ResponsesRequest,
    request: Request,
    current_subject: str = Depends(get_current_subject),
):
    """
    OpenAI Responses API endpoint.

    Accepts a Responses-format request, converts it to a ChatCompletionRequest
    internally, and returns a response matching the Responses API schema
    (output array, input_tokens/output_tokens, named SSE events for streaming).
    """
    _admit_tool_access(payload)
    connection = _connection_model_ref(payload.model)
    for history_param in ("previous_response_id", "conversation"):
        if getattr(payload, history_param, None) is not None:
            raise HTTPException(
                status_code = 400,
                detail = openai_error_body(
                    f"'{history_param}' is not supported. Send the full conversation history in 'input'.",
                    status = 400,
                    code = "unsupported_parameter",
                    param = history_param,
                ),
            )
    messages = _normalise_responses_input(payload)
    if not messages:
        raise HTTPException(status_code = 400, detail = "No input provided.")
    # Reject system-only input before the switch, or an invalid request evicts the resident model.
    if not any(m.role not in ("system", "developer") for m in messages):
        raise HTTPException(status_code = 400, detail = "At least one non-system message is required.")
    # Validate function tools before any model load so an invalid request never switches the model; built-in tools with no name are skipped
    for _tool in payload.tools or []:
        if not isinstance(_tool, dict) or _tool.get("type") != "function":
            continue
        _name = _tool.get("name")
        if not isinstance(_name, str) or not _name.strip():
            raise HTTPException(
                status_code = 400,
                detail = openai_error_body(
                    "Invalid 'tools': each function tool must have a 'name'.",
                    status = 400,
                    code = "invalid_value",
                    param = "tools",
                ),
            )
    # Reject a nameless forcing tool_choice before the switch so a malformed request can't evict.
    _tc = payload.tool_choice
    if isinstance(_tc, dict) and _tc.get("type") == "function":
        _tc_name = _tc.get("name")
        if not isinstance(_tc_name, str) or not _tc_name.strip():
            raise HTTPException(
                status_code = 400,
                detail = openai_error_body(
                    "Invalid 'tool_choice': the forced function must have a 'name'.",
                    status = 400,
                    code = "invalid_value",
                    param = "tool_choice",
                ),
            )
    if payload.stream or connection is not None:
        # streaming preflights here; non-streaming delegates its complete preflight to chat.
        if connection is None:
            # Either source may serve the stream, so refuse before loading what chat would refuse.
            _stream_chat_req = _build_chat_request(payload, messages, stream = True)
            _stream_parts = _extract_content_parts(_stream_chat_req.messages, keep_tool_images = True)
            _responses_has_image = _messages_have_image(messages)
            # A text-only GGUF reads a tool result's image as a note, as in chat.
            _tool_images_only = _responses_has_image and not _messages_have_image(
                m for m in messages if m.role != "tool"
            )
            from utils.hardware import DeviceType, get_device

            _stream_needs_grammar = (
                get_device() != DeviceType.MLX
                and _response_format_constrains_decoding(_stream_chat_req)
                and (
                    _explicit_studio_tool_loop_requested(_stream_chat_req)
                    or not _tools_outrank_response_format(_stream_chat_req, _stream_chat_req.tools)
                )
            )
            await _maybe_auto_switch_model(
                _switch_model_for_payload(payload),
                request,
                current_subject,
                require_vision = _responses_has_image,
                claim_resident = False,
                image_preflight = (
                    _chat_image_preflight(_stream_chat_req, _stream_parts[2])
                    if _responses_has_image
                    else None
                ),
                tool_images_only = _tool_images_only,
                # Off an MLX host a non-GGUF target is transformers, which has no grammar engine.
                gguf_only = _stream_needs_grammar,
                gguf_only_reason = (
                    "response_format needs a grammar engine, and the transformers backend has none; "
                    "load an MLX or GGUF model to use it."
                )
                if _stream_needs_grammar
                else None,
            )
        monitor_id = None
        if not getattr(request.state, "skip_api_monitor", False):
            monitor_id = api_monitor.start(
                endpoint = request.url.path,
                via_api_key = _request_used_api_key(request),
                method = request.method,
                model = payload.model,
                prompt = _monitor_prompt_from_messages(messages),
                context_length = None if connection else _monitor_context_length(),
                subject = current_subject,
            )
        try:
            response = await _responses_stream(
                payload, messages, request, monitor_id, current_subject, connection
            )
        except asyncio.CancelledError:
            # Before the stream exists, nothing else finishes the entry.
            api_monitor.finish(monitor_id, "cancelled")
            raise
        except HTTPException as exc:
            detail = exc.detail
            if not isinstance(detail, str):
                detail = json.dumps(detail, default = str)
            api_monitor.fail(monitor_id, detail)
            raise
        except Exception as exc:
            api_monitor.fail(monitor_id, _friendly_error(exc))
            raise
        if payload.stream or not isinstance(response, StreamingResponse):
            return response
        # A Connection streams whatever the client asked for; answer from the terminal event.
        return await _responses_from_stream(response, payload)
    return await _responses_non_streaming(payload, messages, request, current_subject)


async def _responses_from_stream(response: StreamingResponse, payload: ResponsesRequest):
    terminal = None
    async for line in _sse_data_lines(response.body_iterator):
        if line.startswith("data:"):
            event = json.loads(line[5:])
            if event.get("type") in (
                "response.completed",
                "response.incomplete",
                "response.failed",
            ):
                terminal = event["response"]
    if terminal is None or terminal["status"] == "failed":
        error = (terminal or {}).get("error") or {}
        raise HTTPException(
            status_code = 429 if error.get("code") == "rate_limit_exceeded" else 502,
            detail = error.get("message") or "The connection failed.",
        )
    terminal.update(
        temperature = payload.temperature,
        top_p = payload.top_p,
        max_output_tokens = payload.max_output_tokens,
        instructions = payload.instructions,
    )
    return JSONResponse(terminal)


# =====================================================================

# Anthropic-Compatible Messages API  (/messages → /v1/messages)
# =====================================================================


_STUDIO_ANTHROPIC_TOOL_ALIASES = {
    "web_search": "web_search",
    "web_search_20250305": "web_search",
    "web_search_20260209": "web_search",
    "web_search_20260318": "web_search",
    "web_fetch": "web_search",
    "web_fetch_20250910": "web_search",
    "web_fetch_20260209": "web_search",
    "web_fetch_20260309": "web_search",
    "web_fetch_20260318": "web_search",
    "python": "python",
    "terminal": "terminal",
    "read_skill": "read_skill",
}
# Server tools that never need a confirmation prompt (read-only / non code-
# executing; mirrors the unconditional-safe names in is_potentially_unsafe_tool_call).
# Any other selected tool (terminal, python, render_html) can require the gate
# this channel has no way to present, so an omitted permission_mode ("ask") only
# asks then. render_html is excluded because a networked canvas prompts in auto,
# and this channel invokes the loop without confirm; auto/ask reject, off/full run.
from core.inference.media_chat_tools import MEDIA_CHAT_TOOLS as _MEDIA_CHAT_TOOLS

# The media tools are always-safe too, though this channel never selects them (ALL_TOOLS only).
_ANTHROPIC_UNPROMPTED_SAFE_TOOLS = (
    frozenset(
        {"web_search", "search_knowledge_base", "search_conversation", "read_skill", "view_image"}
    )
    | _MEDIA_CHAT_TOOLS
)


def _anthropic_selects_server_tools(
    payload, requested_studio_tools: set[str], has_client_tool: bool
) -> bool:
    """Process-wide --enable-tools is only a default: only enable_tools, mcp_enabled or a server tool selects tools; --disable-tools or enable_tools false vetoes"""
    if has_client_tool or _effective_enable_tools(payload) is False:
        return False
    # enable_tools only, not mcp_enabled: nothing here loads MCP schemas.
    return payload.enable_tools is True or bool(requested_studio_tools)


def _guard_anthropic_client_tool_catalog(
    openai_client_tools, openai_tool_choice, server_tools, llama_backend
) -> None:
    """Rejects a live client tool catalogue the template would drop, not replayed history alone; the token counter shares this so counts match"""
    if server_tools or not openai_client_tools or openai_tool_choice == "none":
        return
    if getattr(llama_backend, "supports_tool_passthrough", llama_backend.supports_tools):
        return
    raise HTTPException(
        status_code = 400,
        detail = anthropic_error_body(
            "Client-supplied tools require a GGUF chat template with tool-call support; "
            "the current model/template does not advertise tools.",
            status = 400,
            err_type = "invalid_request_error",
        ),
    )


def _anthropic_client_tools_for_turn(openai_client_tools, openai_tool_choice, openai_messages):
    """Withdraw a disabled catalog unless replayed history still needs its schemas."""
    if openai_tool_choice == "none" and not _has_openai_tool_history(openai_messages):
        return []
    return openai_client_tools


def _anthropic_requested_studio_tools(tools: Optional[list]) -> set[str]:
    requested: set[str] = set()
    for tool in tools or []:
        td = tool if isinstance(tool, dict) else tool.model_dump()
        if td.get("input_schema") is not None or anthropic_schema_client_tool_kind(td) is not None:
            continue
        # Dispatch server tools by `type` only, or a client tool named `python` flips to server execution.
        type_ = td.get("type")
        if isinstance(type_, str) and type_ in _STUDIO_ANTHROPIC_TOOL_ALIASES:
            requested.add(_STUDIO_ANTHROPIC_TOOL_ALIASES[type_])
    return requested


def _anthropic_domain_entry(entry):
    # Anthropic accepts an optional path ("example.com/blog", "example.com/*"); Studio limits by domain.
    if isinstance(entry, str) and "://" not in entry:
        return entry.split("/", 1)[0]
    return entry


def _anthropic_website_policy(tools: Optional[list]) -> Optional[dict]:
    from core.inference.web_access_policy import normalize_website_policy

    policy = {"allowedDomains": [], "blockedDomains": []}
    try:
        for tool in tools or []:
            td = tool if isinstance(tool, dict) else tool.model_dump()
            if _STUDIO_ANTHROPIC_TOOL_ALIASES.get(td.get("type")) != "web_search":
                continue
            declared = {}
            for key, field in (
                ("allowedDomains", "allowed_domains"),
                ("blockedDomains", "blocked_domains"),
            ):
                entries = td.get(field)
                if entries is None:
                    entries = []
                elif isinstance(entries, list):
                    entries = [_anthropic_domain_entry(entry) for entry in entries]
                declared[key] = entries
            declared = normalize_website_policy(declared)
            for key in policy:
                policy[key] += declared[key]
        policy = normalize_website_policy(policy)
    except ValueError as exc:
        raise HTTPException(
            status_code = 400,
            detail = anthropic_error_body(str(exc), status = 400, err_type = "invalid_request_error"),
        )
    return policy if policy["allowedDomains"] or policy["blockedDomains"] else None


def _select_anthropic_server_tools(
    all_tools: list[dict],
    requested_studio_tools: set[str],
    enabled_tools: Optional[list[str]],
    *,
    supports_vision: bool = True,
) -> list[dict]:
    """Select Unsloth tools requested through Anthropic tools and extensions."""
    available = [
        tool for tool in all_tools if supports_vision or tool["function"]["name"] != "view_image"
    ]
    if _enabled_agent_skills():
        from core.inference.tools import READ_SKILL_TOOL
        available.append(READ_SKILL_TOOL)
    if not requested_studio_tools and enabled_tools is None:
        return available

    selected_names = set(requested_studio_tools)
    if enabled_tools is not None:
        selected_names.update(enabled_tools)

    return [tool for tool in available if tool["function"]["name"] in selected_names]


def _pil_to_png_b64(img) -> str:
    buf = io.BytesIO()
    # Composited, not merely converted: convert("RGB") keeps whatever colour sits
    # under the alpha, so a transparent attachment whose background was never painted
    # reaches the worker as black -- and its dark text with it.
    _mcp_flattened_rgb(img).save(buf, format = "PNG")
    return base64.b64encode(buf.getvalue()).decode("ascii")


def _image_bytes_to_png_b64(raw: bytes) -> str:
    """Convert image bytes to base64 PNG for formats llama-server cannot decode."""
    from PIL import Image

    img = _mcp_flattened_rgb(Image.open(io.BytesIO(raw)))
    buf = io.BytesIO()
    img.save(buf, format = "PNG")
    return base64.b64encode(buf.getvalue()).decode("ascii")


_PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"


def _stb_reads_jpeg(raw: bytes) -> bool:
    """Accept 8-bit SOF0-SOF2 JPEG frames with one or three components."""
    i = 2
    while i + 4 <= len(raw):
        if raw[i] != 0xFF:
            return False
        marker = raw[i + 1]
        if marker == 0xFF:  # Fill byte before a marker.
            i += 1
            continue
        if 0xC0 <= marker <= 0xCF and marker not in (0xC4, 0xC8, 0xCC):
            if marker not in (0xC0, 0xC1, 0xC2) or i + 10 > len(raw):
                return False
            height = int.from_bytes(raw[i + 5 : i + 7], "big")
            width = int.from_bytes(raw[i + 7 : i + 9], "big")
            return raw[i + 4] == 8 and height > 0 and width > 0 and raw[i + 9] in (1, 3)
        if marker in (0xD9, 0xDA):  # EOI or scan data before any frame header.
            return False
        i += 2 + int.from_bytes(raw[i + 2 : i + 4], "big")
    return False


def _stb_reads_png(raw: bytes) -> bool:
    """Accepts PNGs stb_image reads (IEND reached, IDAT complete); inflation capped near IHDR size so a compressed tail cannot cost unbounded CPU and memory"""
    i = len(_PNG_SIGNATURE)
    inflater = zlib.decompressobj()
    budget = 0
    try:
        while i + 12 <= len(raw):
            kind = raw[i + 4 : i + 8]
            end = i + 12 + int.from_bytes(raw[i : i + 4], "big")
            if end > len(raw) or (kind == b"IHDR") != (i == len(_PNG_SIGNATURE)):
                return False
            if kind == b"IHDR":
                if end - i != 25:
                    return False
                width = int.from_bytes(raw[i + 8 : i + 12], "big")
                height = int.from_bytes(raw[i + 12 : i + 16], "big")
                bits = raw[i + 16] * {0: 1, 2: 3, 3: 1, 4: 2, 6: 4}.get(raw[i + 17], 4)
                # Doubled for Adam7, whose pass rows each add a filter byte and padding.
                budget = 2 * height * ((width * bits + 7) // 8 + 1) + 64
            elif kind == b"IEND":
                return inflater.eof
            elif kind == b"IDAT":
                data = raw[i + 8 : end - 4]
                while data and not inflater.eof:
                    budget -= len(inflater.decompress(data, 1 << 20))
                    if budget < 0:
                        return False
                    data = inflater.unconsumed_tail
            elif kind != b"PLTE" and not kind[0] & 0x20:
                return False
            i = end
    except zlib.error:
        pass
    return False


def _llama_image_data_url(raw: bytes) -> str:
    """Keeps PNG and JPEG bytes stb_image reads; other or EXIF-rotated images are re-encoded; Pillow rejects truncated JPEGs stb_image accepts; failures are HTTP 400"""
    from PIL import Image, JpegImagePlugin

    with Image.open(io.BytesIO(raw)) as img:
        img.load()
        upright = exif_upright(img)
        # 16-bit tRNS keys cannot survive the 8-bit scaling, so those pass through as before.
        if img.has_transparency_data and not img.mode.startswith("I;16"):
            # Alpha band only: no RGBA copy of opaque screenshots.
            bands = img.getbands()
            alpha = img.getchannel("A") if "A" in bands else img.convert("RGBA").getchannel("A")
            if alpha.getextrema()[0] < 255:
                del alpha
                buf = io.BytesIO()
                # Reuse this decode: a second one doubles peak memory on large images.
                _mcp_flattened_rgb(upright).save(buf, format = "PNG")
                return f"data:image/png;base64,{base64.b64encode(buf.getvalue()).decode('ascii')}"
    if upright is not img:
        buf = io.BytesIO()
        if raw.startswith(b"\xff\xd8") and _stb_reads_jpeg(raw):
            upright.save(
                buf,
                format = "JPEG",
                # A list: Pillow keeps only dict keys 0..n-1, and some encoders number tables from 1.
                qtables = [img.quantization[key] for key in sorted(img.quantization)],
                subsampling = JpegImagePlugin.get_sampling(img),
            )
            return f"data:image/jpeg;base64,{base64.b64encode(buf.getvalue()).decode('ascii')}"
        _mcp_flattened_rgb(upright).save(buf, format = "PNG")
        return f"data:image/png;base64,{base64.b64encode(buf.getvalue()).decode('ascii')}"
    if raw.startswith(_PNG_SIGNATURE) and _stb_reads_png(raw):
        return f"data:image/png;base64,{base64.b64encode(raw).decode('ascii')}"
    if raw.startswith(b"\xff\xd8") and _stb_reads_jpeg(raw):
        return f"data:image/jpeg;base64,{base64.b64encode(raw).decode('ascii')}"
    return f"data:image/png;base64,{_image_bytes_to_png_b64(raw)}"


# Match llama-server's per-image limit and add a per-request budget.
_REMOTE_IMAGE_MAX_BYTES = 10 * 1024 * 1024
_REMOTE_IMAGE_REQUEST_BUDGET_BYTES = 32 * 1024 * 1024
# Bound DNS, connection and redirect work independently of response size.
_REMOTE_IMAGE_MAX_COUNT = 8
# Wall-clock budget shared by every remote image fetch in one request.
_REMOTE_IMAGE_REQUEST_DEADLINE_S = 60.0

# Do not reveal why a caller-selected host could not be fetched.
_REMOTE_IMAGE_FETCH_REFUSAL = (
    "Could not fetch the remote image URL. Send the image as a base64 data URL instead."
)
# Stands in for a remote image in token counts and in the switch preflight's image checks.
_COUNT_IMAGE_PLACEHOLDER = (
    "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1Pe"
    "AAAADElEQVR4nGNgYGAAAAAEAAH2FzhVAAAAAElFTkSuQmCC"
)


# A bare base64 payload holds neither a colon nor any of these, so a URL cannot pass as one.
_NOT_BASE64 = _re.compile(r"[^A-Za-z0-9+/=_\s-]")
# urlsplit drops these before it reads a scheme, so skip them the same way.
_URL_LEADING_BLANKS = "".join(map(chr, range(0x21)))
# Wider than any real scheme, so the scan stays bounded without missing one.
_MAX_IMAGE_SCHEME_CHARS = 64


def _image_url_scheme(url: str) -> str:
    """Skips leading blanks and reads a bounded window, so a padded scheme cannot pass a URL as base64."""
    head = url.lstrip(_URL_LEADING_BLANKS)[:_MAX_IMAGE_SCHEME_CHARS]
    if ":" not in head and not _NOT_BASE64.search(head):
        return ""
    return head.split(":", 1)[0][:_MAX_VIDEO_SCHEME_CHARS].lower()


def _remote_image_scheme_rejection(scheme: str) -> Optional[tuple[int, str]]:
    """Allow only the HTTPS scheme supported by the pinned fetcher."""
    if scheme == "https":
        return None
    return (
        400,
        f"Unsupported image URL scheme ('{scheme}:'). Send the image over https, "
        "or as a base64 data URL.",
    )


def _placeholder_remote_images_for_count(openai_messages: list[dict]) -> None:
    """Replace remote images before ``/apply-template`` can fetch them."""
    for msg in openai_messages:
        content = msg.get("content")
        if not isinstance(content, list):
            continue
        for part in content:
            if not isinstance(part, dict) or part.get("type") != "image_url":
                continue
            image_url = part.get("image_url") or {}
            url = image_url.get("url", "")
            if url.startswith("data:"):
                continue
            scheme = _image_url_scheme(url)
            if not scheme:
                continue  # Bare base64 payload, not a URL. Nothing to dial.
            rejection = _remote_image_scheme_rejection(scheme)
            if rejection is not None:
                raise HTTPException(status_code = rejection[0], detail = rejection[1])
            image_url["url"] = _COUNT_IMAGE_PLACEHOLDER


def _remote_images_as_served(messages) -> list[dict]:
    def _fetchable(part) -> bool:
        url = (
            (part.get("image_url") or {}).get("url", "") if part.get("type") == "image_url" else ""
        )
        return _image_url_scheme(url) == "https"

    served = []
    for message in messages or ():
        plain = message if isinstance(message, dict) else message.model_dump(exclude_none = True)
        content = plain.get("content")
        if isinstance(content, list):
            content = [
                {**part, "image_url": {"url": _COUNT_IMAGE_PLACEHOLDER}}
                if _fetchable(part)
                else part
                for part in content
            ]
            plain = {**plain, "content": content}
        served.append(plain)
    return served


def _inline_remote_image_url(
    url: str, scheme: str, budget_bytes: int, deadline: float
) -> tuple[str, int]:
    """Fetch an image safely and return its data URL and decoded size."""
    from core.inference.external_provider import safe_fetch_remote_image_sync

    rejection = _remote_image_scheme_rejection(scheme)
    if rejection is not None:
        raise HTTPException(status_code = rejection[0], detail = rejection[1])
    # Detect the MIME type from the fetched bytes.
    fetched = safe_fetch_remote_image_sync(
        url,
        "image/png",
        max_bytes = min(_REMOTE_IMAGE_MAX_BYTES, budget_bytes),
        deadline = deadline,
        require_image_content_type = False,
    )
    if fetched is None:
        raise HTTPException(status_code = 400, detail = _REMOTE_IMAGE_FETCH_REFUSAL)
    mime, b64 = fetched
    # Convert the encoded length back to the request budget's byte unit.
    return f"data:{mime};base64,{b64}", (len(b64) * 3) // 4


class _RemoteImageFetches:
    """One request's remote image budget: bytes, URL count and a shared deadline."""

    def __init__(self):
        self.remaining_bytes = _REMOTE_IMAGE_REQUEST_BUDGET_BYTES
        self.remaining_fetches = _REMOTE_IMAGE_MAX_COUNT
        self.deadline: Optional[float] = None

    def inline(self, url: str) -> str:
        """Return a remote image as a data URL; llama-server's bare base64 form is returned as is."""
        scheme = _image_url_scheme(url)
        if not scheme:
            return url
        # A zero max_bytes value means no limit to some fetch callers.
        if self.remaining_bytes <= 0 or self.remaining_fetches <= 0:
            raise HTTPException(
                status_code = 400,
                detail = (
                    f"Too many remote image URLs in one request (max {_REMOTE_IMAGE_MAX_COUNT})."
                    if self.remaining_fetches <= 0
                    else _REMOTE_IMAGE_FETCH_REFUSAL
                ),
            )
        self.remaining_fetches -= 1
        if self.deadline is None:
            self.deadline = time.monotonic() + _REMOTE_IMAGE_REQUEST_DEADLINE_S
        data_url, spent = _inline_remote_image_url(url, scheme, self.remaining_bytes, self.deadline)
        self.remaining_bytes -= spent
        return data_url


def _inline_request_remote_images(payload) -> None:
    """Replace a chat request's remote image URLs with fetched data URLs, in place."""
    fetches = _RemoteImageFetches()
    for message in payload.messages:
        if not isinstance(message.content, list):
            continue
        for part in message.content:
            if isinstance(part, ImageContentPart) and not part.image_url.url.startswith("data:"):
                part.image_url.url = fetches.inline(part.image_url.url)


def _served_image_part(messages):
    """The image part _extract_content_parts selects, counting a remote URL as fetched."""
    latest = latest_user = None
    for message in messages:
        if message.role in ("system", "developer") or not isinstance(message.content, list):
            continue
        part = next(
            (
                p
                for p in message.content
                if isinstance(p, ImageContentPart)
                and (
                    p.image_url.url.partition(",")[2]
                    if p.image_url.url.startswith("data:")
                    else _image_url_scheme(p.image_url.url)
                )
            ),
            None,
        )
        if part is not None:
            latest = part
            if message.role == "user":
                latest_user = part
    return latest_user or latest


def _remote_image_part(part) -> bool:
    return part is not None and not part.image_url.url.startswith("data:")


def _served_remote_parts(messages, several: bool) -> list:
    # Only what renderers read: the selected image, plus each user turn's on multi-image models.
    selected = _served_image_part(messages)
    return [
        part
        for message in messages
        if isinstance(message.content, list)
        for part in message.content
        if isinstance(part, ImageContentPart)
        and _remote_image_part(part)
        and (part is selected or (several and message.role == "user"))
    ]


def _inline_served_remote_images(payload, several: bool) -> None:
    images_on_turn = _images_in_last_user_message(payload.messages)
    if not several and images_on_turn + int(_legacy_image_is_distinct(payload)) > 1:
        return  # The caller refuses it as "one image per message".
    fetches = _RemoteImageFetches()
    for part in _served_remote_parts(payload.messages, several):
        part.image_url.url = fetches.inline(part.image_url.url)


def _normalize_openai_image_parts_for_llama(openai_messages: list[dict], on_image = None) -> bool:
    """Fetches and normalizes image URLs in place, calling on_image per image; returns whether any image was seen; raises HTTP 400 on fetch or decode failure"""
    has_image = False
    fetches = _RemoteImageFetches()
    for msg in openai_messages:
        content = msg.get("content")
        if not isinstance(content, list):
            continue
        for part in content:
            if not isinstance(part, dict) or part.get("type") != "image_url":
                continue

            has_image = True
            if on_image is not None:
                on_image()

            image_url = part.get("image_url") or {}
            url = image_url.get("url", "")
            if not url.startswith("data:"):
                url = fetches.inline(url)
                if not url.startswith("data:"):
                    # llama-server also accepts bare base64 payloads.
                    continue
                image_url["url"] = url

            try:
                _, b64data = url.split(",", 1)
                raw = base64.b64decode(b64data)
                data_url = _llama_image_data_url(raw)
            except Exception:
                raise HTTPException(
                    status_code = 400,
                    detail = "Failed to process image.",
                )
            # Preserve the client's `detail` setting.
            image_url["url"] = data_url

    return has_image


def _normalize_anthropic_openai_images(openai_messages: list[dict], is_vision: bool) -> bool:
    def _guard():
        if not is_vision:
            raise HTTPException(
                status_code = 400,
                detail = "Image provided but current GGUF model does not support vision.",
            )

    return _normalize_openai_image_parts_for_llama(openai_messages, on_image = _guard)


def _validate_anthropic_client_tools(tools) -> None:
    # Reject malformed client tools before any model load since the converter silently drops them; client tools need input_schema, other types are server tools
    for tool in tools or []:
        td = tool if isinstance(tool, dict) else tool.model_dump()
        name, type_, schema = td.get("name"), td.get("type"), td.get("input_schema")
        schema_client_kind = anthropic_schema_client_tool_kind(td)
        if schema is None and not isinstance(type_, str):
            raise HTTPException(
                status_code = 400,
                detail = f"Tool {name!r} is missing required field 'input_schema'.",
            )
        if (schema is not None or schema_client_kind is not None) and (
            not isinstance(name, str) or not name
        ):
            raise HTTPException(
                status_code = 400,
                detail = "Client tool is missing required field 'name'.",
            )


def _anthropic_response_format(
    payload, *, require_llama_compatibility: bool = True
) -> Optional[dict]:
    output_config = payload.output_config if isinstance(payload.output_config, dict) else {}
    fmt = output_config.get("format")
    if fmt is None:
        fmt = (payload.model_extra or {}).get("output_format")
    if fmt is None:
        return None
    if not (
        isinstance(fmt, dict)
        and fmt.get("type") == "json_schema"
        and isinstance(fmt.get("schema"), dict)
    ):
        logger.warning("Ignoring unsupported Anthropic output format: %r", fmt)
        return None
    schema = fmt["schema"]
    if require_llama_compatibility and _llama_compatible_tool_schema(schema) != schema:
        raise HTTPException(
            status_code = 400,
            detail = anthropic_error_body(
                "The output format schema contains constraints that llama.cpp cannot enforce "
                "without weakening them; use anchored patterns and supported repetition bounds.",
                status = 400,
                err_type = "invalid_request_error",
            ),
        )
    return {"type": "json_schema", "json_schema": {"name": "response", "schema": schema}}


def _append_to_codex_instructions(messages: list[dict], addition: str) -> list[dict]:
    """Only system turns: Responses folds just those into instructions, so developer text would be lost."""
    if not addition:
        return messages
    copied = [dict(msg) for msg in messages]
    for msg in copied:
        if msg.get("role") != "system":
            continue
        content = msg.get("content", "")
        if isinstance(content, str):
            msg["content"] = content.rstrip() + "\n\n" + addition
            return copied
    return [{"role": "system", "content": addition}, *copied]


def _append_to_system_message(messages: list[dict], addition: str) -> list[dict]:
    """Append text to the leading system/developer message, or prepend one."""
    if not addition:
        return messages
    copied = [dict(msg) for msg in messages]
    for msg in copied:
        if msg.get("role") not in ("system", "developer"):
            continue
        content = msg.get("content", "")
        if isinstance(content, str):
            msg["content"] = content.rstrip() + "\n\n" + addition
            return copied
    return [{"role": "system", "content": addition}, *copied]


def _resident_context_satisfies(model_info: dict, max_seq_length: Any) -> bool:
    """Compares requested lengths, not served windows (which cannot tell asked from backend-chosen); nothing else forces a reload"""
    recorded = _nonnegative_int_or_none(model_info.get("requested_context_length"))
    if recorded is None:
        return True
    return _positive_int_or_none(max_seq_length) == _positive_int_or_none(recorded)


async def _resident_model_reads_images() -> bool:
    """Asks both backends: a resident MLX or safetensors model would otherwise miss a llama-only check."""
    if bool(getattr(get_llama_cpp_backend(), "is_vision", False)):
        return True
    # Off the loop: building the singleton runs the torch import.
    backend = await asyncio.to_thread(get_inference_backend)
    active = getattr(backend, "active_model_name", None)
    if not active:
        return False
    entry = (getattr(backend, "models", {}) or {}).get(active) or {}
    return bool(entry.get("is_vision"))


async def _mlx_count_chat_tokens(
    payload,
    request = None,
    via_api_key = None,
) -> Optional[JSONResponse]:
    """Count with a resident MLX or managed engine tokenizer, otherwise return None.

    This has to answer the question the safetensors completion answers -- which of its two
    paths claims the request, and what each renders -- because a count that decides any of
    it differently prices a prompt the model never sees. Where a helper carries a decision
    it is called rather than restated; the admission conditions themselves are restated,
    so they have to be kept in step with the completion above.
    """
    # Off the loop: building the singleton runs the torch import, and a count is not
    # worth stalling login and the health probe behind it.
    backend = await asyncio.to_thread(get_inference_backend)
    active = getattr(backend, "active_model_name", None)
    # A same-ID reload (template override) keeps the name, so capture the generation and re-check.
    _load_generation = getattr(backend, "load_generation", 0)
    if not active:
        return None
    entry = getattr(backend, "models", {}).get(active) or {}
    # Audio skips the chat render; vision does not, as it serves text turns through the same render.
    managed = entry.get("engine") in ("vllm", "sglang")
    if not (entry.get("is_mlx") or managed) or entry.get("is_audio"):
        return None
    if entry.get("engine") == "sglang":
        raise HTTPException(
            status_code = 503,
            detail = "Exact prompt token counting is unavailable for SGLang.",
        )
    if managed and (
        payload.tools
        or any(m.role == "tool" or m.tool_calls for m in payload.messages)
        or payload.enable_thinking
        or payload.preserve_thinking
        or payload.reasoning_effort not in (None, "none")
    ):
        raise HTTPException(
            status_code = 503,
            detail = "Exact token counting with tools or reasoning controls is unavailable for this engine profile.",
        )

    # Use the completion's own helper; rebuilding the prompt here would price one nobody sends.
    system_prompt, messages, _image = await _extract_content_parts_async(payload.messages)
    # Once for both non-GGUF backends; only with a request, since requestless mode injects the date.
    _user_system_prompt = system_prompt
    # Attachment, clip or promoted MCP picture selects the processor template; checked off-loop (12 MB).
    _renders_media = (
        _request_has_attached_image(payload)
        or _request_has_video(payload)
        or (
            _request_has_promotable_mcp_images(payload, exact = False)
            and await asyncio.to_thread(_request_has_promotable_mcp_images, payload)
        )
    )
    _date_controls = _template_controls(payload)
    if request is not None:
        system_prompt = _apply_current_date_prompt(
            system_prompt, request, image = _renders_media, controls = _date_controls
        )

    from core.inference.chat_template_helpers import (
        forced_tool_name,
        forced_turn_tools,
        mapped_chat_template,
        renderable_tool_catalog,
    )
    from state.tool_policy import get_tool_policy as _get_tool_policy_mlx

    _tools_on = bool(_effective_enable_tools(payload))
    # Use the completion's own helper so a count cannot price a tool_use branch it renders plain.
    if _tools_on and not _launcher_tool_default_applies(
        payload, _ui_stream_events_enabled(request)
    ):
        _tools_on = False
    # tool_choice none withdraws the catalogue, so neither schemas nor MCP discovery is counted.
    if getattr(payload, "tool_choice", None) == "none":
        _tools_on = False
    _mcp_on = (
        getattr(payload, "tool_choice", None) != "none"
        and bool(getattr(payload, "mcp_enabled", False))
        and _get_tool_policy_mlx() is not False
    )

    # Pass the tools so the template's tool_use branch is read, as the completion does;
    # detection only, so it must not follow tool_choice.
    _template_tools = payload.tools or None
    if not _template_tools and (
        _tools_on
        or _explicit_studio_tool_loop_requested(payload)
        or any(m.role == "tool" or m.tool_calls for m in payload.messages)
    ):
        _template_tools = ({},)
    _takes_tools = bool(
        _sf_rendered_features(backend, entry, tools = _template_tools)[0].get("supports_tools", False)
    )
    # A budget of zero never enters the loop, so the relay is what renders.
    _budget = getattr(payload, "max_tool_calls_per_message", None)
    _tools_to_use = None
    if _takes_tools and (_tools_on or _mcp_on) and (_budget is None or _budget > 0):
        # Never MCP discovery on a count (spawns stdio servers): use the completion cache and decline if incomplete; mcp_allowed stays False
        _mcp_tools: list[dict] = []
        if _mcp_on:
            from core.inference.mcp_client import mcp_server_snapshot_guard
            from core.inference.tools import cached_mcp_tools, set_mcp_listing_context_tokens

            set_mcp_listing_context_tokens(
                _monitor_context_length(),
                getattr(payload, "thread_id", None),
                payload.messages,
                getattr(payload, "tool_choice", None),
                getattr(payload, "mcp_image", None),
            )

            # A database read, so off the loop; guarded like the GGUF count, or an interleaving edit pairs a new row with a stale schema
            async with mcp_server_snapshot_guard():
                _mcp_tools, _mcp_complete = await asyncio.to_thread(cached_mcp_tools)
            if not _mcp_complete:
                raise HTTPException(
                    status_code = 503,
                    detail = "Cannot count tokens until enabled MCP tools have been discovered.",
                )
        _tools_to_use = (
            await _select_request_tools(
                payload,
                tools_on = _tools_on,
                mcp_allowed = False,
                supports_vision = bool(entry.get("is_vision")),
                checkpoint_fitted = _rolling_context_policy(payload) is not None,
            )
        ) + _mcp_tools
        # With no tools left the completion skips the loop, so use the plain render, not an empty catalog.
        if not _tools_to_use:
            _tools_to_use = None

    if (
        not _tools_to_use
        and _takes_tools
        and not _tools_on
        and (payload.tools or _has_openai_tool_history(payload.messages))
    ):
        # The relay renders from a rebuilt message list keeping structured tool_calls and the caller's
        # catalog; counting the flattened conversation underprices it.
        _tool_choice = getattr(payload, "tool_choice", None)
        _forced = (
            _tool_choice["function"].get("name")
            if isinstance(_tool_choice, dict) and isinstance(_tool_choice.get("function"), dict)
            else None
        )
        if _tool_choice == "none":
            _tools_to_use = None
        elif isinstance(_forced, str):
            _tools_to_use = [
                _tool
                for _tool in payload.tools or []
                if isinstance(_tool, dict)
                and isinstance(_tool.get("function"), dict)
                and _tool["function"].get("name") == _forced
            ] or None
        else:
            _tools_to_use = payload.tools or None
        messages = await _promote_mcp_history_images_async(
            _structured_tool_history_for_local_template(
                _flatten_content_parts_for_local_template(
                    _openai_messages_for_passthrough(
                        payload, normalize_images = False, promote_mcp_images = False
                    )
                )
            ),
            vision = False,
        )
        _client_system_prompt = _user_system_prompt
        if request is not None:
            _client_system_prompt = _apply_current_date_prompt(
                _user_system_prompt,
                request,
                image = _renders_media,
                tools = bool(_tools_to_use),
                controls = _date_controls,
            )
        messages = _set_or_prepend_system_message(messages, _client_system_prompt)
        system_prompt = ""
    elif _tools_to_use:
        # A pending turn makes the loop splice in RAG retrieval this cannot see; 'ask' without a
        # bypass holds retrieval behind the confirm gate, so the count stands there.
        _asks_first = (
            payload.permission_mode is not None
            and payload.permission_mode not in ("auto", "off", "full")
            and not payload.bypass_permissions
            and _permission_mode_confirm(payload)
        )
        # Only checked when it matters: answering it opens the DB and this runs on every keystroke.
        if not _asks_first and messages and messages[-1].get("role") in ("user", "tool"):
            from core.inference.tools import rag_autoinject_reaches_retrieval

            # Store-reaching retrieval cannot be priced, so decline the turn; run off the loop (ingest blocks).
            _retrieves, _whole_doc = await asyncio.to_thread(
                rag_autoinject_reaches_retrieval, messages, payload.rag_scope
            )
            if _retrieves or _whole_doc:
                raise HTTPException(
                    status_code = 503,
                    detail = "Cannot count tokens for a pending turn that would retrieve documents.",
                )

        # Tools also add a nudge and strip stale call markup from replayed turns; price both.
        _nudge = await _apply_rag_nudge(
            _build_tool_action_nudge(
                tools = _tools_to_use,
                model_name = public_model_id(active) or payload.model,
                full_access = bool(payload.bypass_permissions),
            ),
            _tools_to_use,
            rag_scope = payload.rag_scope,
        )
        # Match the MLX completion's preflight policy and rendered nudge.
        _nudge = _apply_compaction_nudge(
            _nudge,
            _tools_to_use,
            checkpoint_fitted = _rolling_context_policy(payload) is not None,
            payload = payload,
        )
        # Tool-loop completion passes include_api_key; the plain call must match or the count runs short.
        if request is not None:
            system_prompt = _apply_current_date_prompt(
                _user_system_prompt,
                request,
                include_api_key = True,
                template_default = False,
                image = _renders_media,
                tools = True,
                controls = _date_controls,
            )
        if _nudge:
            system_prompt = (system_prompt.rstrip() + "\n\n" + _nudge) if system_prompt else _nudge
        _auto_heal = (
            payload.auto_heal_tool_calls if payload.auto_heal_tool_calls is not None else True
        )
        _name_gate = _display_tool_name_gate(_tools_to_use)
        messages = [
            {
                **_msg,
                "content": _strip_tool_xml_for_display(
                    _msg["content"],
                    auto_heal_tool_calls = _auto_heal,
                    enabled_tool_names = _name_gate,
                ).strip(),
            }
            if _msg.get("role") == "assistant" and isinstance(_msg.get("content"), str)
            else _msg
            for _msg in messages
        ]
        # The first turn renders only a forced tool, narrowed as the loop narrows the catalog it
        # authorizes: a forced tool the sanitizer drops narrows nothing. The nudge names them all.
        _choice = getattr(payload, "tool_choice", None)
        if forced_tool_name(_choice):
            # Off the loop: the first call may fetch the native template.
            _safe_tools = await asyncio.to_thread(
                lambda: renderable_tool_catalog(
                    _tools_to_use,
                    entry.get("tokenizer"),
                    entry,
                    active_model_name = active,
                    template = mapped_chat_template(entry, active),
                )
            )
            _tools_to_use = forced_turn_tools(_choice, _safe_tools)

    # Nothing to price: the template would render only its generation marker.
    if not messages and not system_prompt and not _tools_to_use:
        raise HTTPException(
            status_code = 503,
            detail = "Cannot count tokens for an empty prompt.",
        )
    # The same normalization the completion applies before it renders.
    _normalize_chat_reasoning_controls(payload)
    # Re-check right before taking the orchestrator lock: a chat may have started since entry.
    if model_slots.routed_generation_count() > 0:
        raise HTTPException(
            status_code = 503,
            detail = "Cannot count tokens while a generation is in progress.",
        )
    try:
        count, _counted = await asyncio.to_thread(
            backend.count_chat_tokens,
            messages,
            system_prompt or "",
            tools = _tools_to_use,
            enable_thinking = payload.enable_thinking,
            reasoning_effort = payload.reasoning_effort,
            preserve_thinking = payload.preserve_thinking,
        )
    except Exception:
        raise HTTPException(
            status_code = 503,
            detail = "Unable to count tokens with the loaded model tokenizer.",
        )
    # A load landing mid-count leaves the total attributable to neither model.
    if (
        getattr(backend, "active_model_name", None) != active
        or getattr(backend, "load_generation", 0) != _load_generation
    ):
        raise HTTPException(
            status_code = 503,
            detail = "The loaded model changed while counting tokens.",
        )
    # The id /status publishes as model_identifier (the raw active name, a local folder or
    # snapshot path included): the client drops a count naming any other checkpoint.
    return JSONResponse(
        content = {"input_tokens": int(count), "model": _count_model_id(active, via_api_key)}
    )


def _count_model_id(model_id, via_api_key):
    """A count's ``model``, redacted for an API-key caller exactly as /status redacts its
    ``model_identifier`` (the redactor keys on that field name)."""
    from hub.utils.host_paths import redact_host_paths
    return redact_host_paths({"model_identifier": model_id}, via_api_key = via_api_key)[
        "model_identifier"
    ]


def _count_chat_context_tokens(backend, payload, messages, tools, template_kwargs):
    from core.inference.llama_cpp import (
        _can_reset_epoch,
        _compaction_fit_kwargs,
        _fit_with_instruction_pins,
        _memory_tool_withheld,
        _sticky_compaction_details,
    )

    def count_tokens(candidate):
        return backend.count_chat_tokens(
            candidate,
            None,
            tools,
            strict = True,
            chat_template_kwargs = template_kwargs,
            # A generation can start between /apply-template and /tokenize.
            should_abort = lambda: model_slots.routed_generation_count() > 0,
        )

    context_length = getattr(backend, "_effective_context_length", None)
    thread_id = getattr(payload, "thread_id", None)
    if (
        _rolling_context_policy(payload) is not None
        and context_length
        and thread_id
        and not _takes_tool_passthrough(payload, backend)
    ):
        policy = _request_context_policy(payload)
        ratio = _request_compaction_headroom_ratio(payload)
        can_reset = _can_reset_epoch(
            thread_id,
            backend.supports_tools,
            tools_withheld = _memory_tool_withheld(thread_id, tools),
        )
        sticky, checkpoint, manual = _sticky_compaction_details(
            thread_id,
            messages,
            context_policy = policy,
            can_reset = can_reset,
            compaction_headroom_ratio = ratio,
        )
        if sticky > 0:
            fitted, truncation = _fit_with_instruction_pins(
                messages,
                context_length = context_length,
                max_tokens = getattr(payload, "max_tokens", None),
                count_tokens = count_tokens,
                sticky_dropped = sticky,
                sticky_is_checkpoint = checkpoint,
                sticky_manual = manual,
                can_reset = can_reset,
                keeps_boundary = True,
                recall_offered = any(
                    (tool.get("function") or {}).get("name") == "search_conversation"
                    for tool in tools or []
                ),
                replay_only = True,
                **_compaction_fit_kwargs(policy, ratio),
            )
            if truncation is not None:
                return int(truncation["prompt_tokens_after"])
            messages = fitted
    return count_tokens(messages)


@router.post("/chat/count_tokens")
async def chat_count_tokens(
    payload: ChatCountTokensRequest,
    current_subject: str = Depends(get_current_subject),
    request: Request = None,
    via_api_key: bool = Depends(authenticated_via_api_key),
):
    """Count prompt tokens for OpenAI-form chat messages using the loaded tokenizer.

    Unlike the /v1 count endpoints this never auto-switches: ``model`` is informational. The
    caller is a background recount with no abort signal, so switching could drag the backend back
    to the model loaded when the count started, a reload the client's guards cannot undo."""
    if account_access.managed_account() and await asyncio.to_thread(
        lambda: account_access.resident_hidden("chat", _loaded_slot_ident())
    ):
        raise HTTPException(status_code = 404, detail = "Model not found")
    # Admitted only while idle, not atomic by design; also blocks second-tab and /api runs the UI misses.
    await _route_to_extra_slot(payload.model)
    if model_slots.routed_generation_count() > 0:
        raise HTTPException(
            status_code = 503,
            detail = "Cannot count tokens while a generation is in progress.",
        )

    # Same role normalization as /chat/completions: a developer turn is priced as system, as it renders.
    for _m in payload.messages:
        if _m.role == "developer":
            _m.role = "system"
    # Same refusal and lift as the completion, so the audio guard sees a part as it sees the field.
    _reject_unsupported_content_parts(payload)
    _normalise_chat_content_parts(payload)
    # Same default for a function tool missing its discriminator, since templates render the whole entry.
    for _tool in payload.tools or []:
        if (
            isinstance(_tool, dict)
            and _tool.get("type") is None
            and isinstance(_tool.get("function"), dict)
        ):
            _tool["type"] = "function"

    # /apply-template swaps each image for a short media marker, so refuse rather than undercount.
    if _request_has_attached_image(payload):
        raise HTTPException(
            status_code = 503,
            detail = "Cannot count tokens for messages containing images.",
        )
    # Same for audio: the completion injects the recording, this cannot.
    if getattr(payload, "audio_base64", None) or getattr(payload, "extra_audio_base64", None):
        raise HTTPException(
            status_code = 503,
            detail = "Cannot count tokens for messages containing audio.",
        )
    # And video, whose frames llama-server samples at completion time.
    if _request_has_video(payload):
        raise HTTPException(
            status_code = 503,
            detail = "Cannot count tokens for messages containing video.",
        )

    # A replay envelope is countable only on a text-only model; a vision model promotes it to pixels.
    # Checked before the MLX dispatch, which returns its own count.
    if (
        _request_has_promotable_mcp_images(payload, exact = False)
        and await asyncio.to_thread(_request_has_promotable_mcp_images, payload)
        and await _resident_model_reads_images()
    ):
        raise HTTPException(
            status_code = 503,
            detail = "Cannot count tokens for messages containing images.",
        )

    from core.inference.npu_backend import peek_npu_backend

    _npu = peek_npu_backend()
    if _npu is not None and _npu.is_loaded and routed_slot.get() is None:
        # FastFlowLM has no tokenizer endpoint; each reply's usage still reports the prompt size.
        raise HTTPException(
            status_code = 503,
            detail = "Token counting is not available for NPU models.",
        )

    llama_backend = get_llama_cpp_backend()
    if not llama_backend.is_loaded:
        # The refusals above are about the request and so are shared; the ones below are
        # llama.cpp's own render concerns, so this returns rather than falling through.
        _mlx_count = await _mlx_count_chat_tokens(payload, request, via_api_key = via_api_key)
        if _mlx_count is not None:
            return _mlx_count
        raise HTTPException(
            status_code = 503,
            detail = _no_model_loaded_detail("No GGUF model loaded. Load a GGUF model first."),
        )

    # Route FIRST: the passthrough does not merge adjacent user turns, so coalescing would misprice.
    _takes_passthrough = _takes_tool_passthrough(payload, llama_backend)
    _count_messages = payload.messages
    if _folds_studio_tool_history(payload, llama_backend):
        _count_messages = _folded_studio_tool_messages(_count_messages)
    _count_dumped = [m.model_dump(exclude_none = True) for m in _count_messages]
    if not _takes_passthrough:
        from core.inference.tool_loop_controller import restore_replayed_tool_results

        # As generation sends them; off the loop since restoring may parse an envelope.
        _count_dumped = await asyncio.to_thread(restore_replayed_tool_results, _count_dumped)
    _count_kept = _strip_provider_synthetic_tool_history(
        _drop_empty_assistant_sentinels(_count_dumped)
    )
    if not _takes_passthrough:
        _count_kept = _live_tool_call_ids(_count_kept)
    # Awaited: stripping parses the whole envelope, and this recount runs in the
    # background on every turn, so it must not do that on the shared loop.
    openai_messages = await _promote_mcp_history_images_async(
        _count_kept,
        # Never as pixels: /apply-template prices a media marker, not the image.
        vision = False,
    )
    if not _takes_passthrough:
        openai_messages = _coalesce_consecutive_user_turns(openai_messages)
    _system_prompt, _, _ = await _extract_content_parts_async(payload.messages)
    # the verbatim passthrough carries no date line, so counting one here would overcount it.
    _user_system_prompt = _system_prompt
    _date_controls = _template_controls(payload)
    if not _takes_passthrough:
        _system_prompt = _apply_current_date_prompt(
            _system_prompt, request, controls = _date_controls
        )
    openai_messages = _set_or_prepend_system_message(openai_messages, _system_prompt)

    # A pending turn (unanswered user or tool result) lets the loop splice in RAG this cannot see.
    if (
        payload.rag_scope
        and openai_messages
        and openai_messages[-1].get("role") in ("user", "tool")
    ):
        raise HTTPException(
            status_code = 503,
            detail = "Cannot count tokens for a pending turn that would retrieve documents.",
        )

    # Only the passthrough sends the caller's own catalog; others render from the selection below.
    openai_tools = _passthrough_client_tools(payload) if _takes_passthrough else None
    # The CLI hard-override still applies: _effective_enable_tools resolves it into _tools_on.
    _client_disabled_tool_calls = getattr(payload, "tool_choice", None) == "none" and not (
        _explicit_studio_tool_loop_requested(payload) and llama_backend.supports_tools
    )
    # Schemas and the nudge are a large share of the prompt: price the completion's own selection.
    _tools_on = False if _client_disabled_tool_calls else _effective_enable_tools(payload)
    # Same rule as the completion path, so both agree on whether MCP schemas are in the prompt.
    from state.tool_policy import get_tool_policy as _get_tool_policy_ct

    _mcp_on = (
        not _client_disabled_tool_calls
        and bool(getattr(payload, "mcp_enabled", False))
        and _get_tool_policy_ct() is not False
    )
    # Never MCP discovery on a count: spawns stdio servers, blocks on probe; keep _mcp_allowed False.
    _mcp_allowed = False
    _mcp_tools: list[dict] = []
    if _mcp_on and not _takes_passthrough and llama_backend.supports_tools:
        from core.inference.tools import cached_mcp_tools, set_mcp_listing_context_tokens

        set_mcp_listing_context_tokens(
            getattr(llama_backend, "context_length", None),
            getattr(payload, "thread_id", None),
            payload.messages,
            getattr(payload, "tool_choice", None),
            getattr(payload, "mcp_image", None),
        )
        from core.inference.mcp_client import mcp_server_snapshot_guard

        # Keep the SQLite read off-loop while coordinating the row/cache snapshot with edits.
        async with mcp_server_snapshot_guard():
            _mcp_tools, _mcp_complete = await asyncio.to_thread(cached_mcp_tools)
        if not _mcp_complete:
            raise HTTPException(
                status_code = 503,
                detail = "Cannot count tokens until enabled MCP tools have been discovered.",
            )
    if (
        not _takes_passthrough
        and llama_backend.supports_tools
        and (
            _tools_on
            or _mcp_on
            or (
                not _client_disabled_tool_calls
                and payload.max_tool_calls_per_message != 0
                and await asyncio.to_thread(_checkpoint_recall_may_enable_tools, payload)
            )
        )
    ):
        tools_to_use = await _select_request_tools(
            payload,
            tools_on = _tools_on,
            mcp_allowed = _mcp_allowed,
            supports_vision = bool(getattr(llama_backend, "is_vision", False)),
            checkpoint_fitted = _rolling_context_policy(payload) is not None,
        )
        # Appended in the position _select_request_tools would have used, so the order matches.
        tools_to_use = tools_to_use + _mcp_tools
        if tools_to_use:
            openai_tools = tools_to_use
            openai_messages = _set_or_prepend_system_message(
                openai_messages,
                _apply_current_date_prompt(
                    _user_system_prompt,
                    request,
                    include_api_key = True,
                    template_default = False,
                    tools = True,
                    controls = _date_controls,
                ),
            )
            _count_nudge = await _apply_rag_nudge(
                _build_tool_action_nudge(
                    tools = tools_to_use,
                    model_name = _llama_public_model_id(llama_backend, payload.model),
                    full_access = bool(payload.bypass_permissions),
                ),
                tools_to_use,
                rag_scope = payload.rag_scope,
            )
            _count_nudge = _apply_compaction_nudge(
                _count_nudge,
                tools_to_use,
                checkpoint_fitted = _rolling_context_policy(payload) is not None,
                payload = payload,
            )
            openai_messages = _append_to_system_message(openai_messages, _count_nudge)

            # The GGUF tool path strips leaked markup from replayed history, so the count must strip it too.
            _count_auto_heal = (
                payload.auto_heal_tool_calls if payload.auto_heal_tool_calls is not None else True
            )
            _count_history_gate = _display_tool_name_gate(tools_to_use)
            openai_messages = [dict(msg) for msg in openai_messages]
            for _msg in openai_messages:
                if _msg.get("role") == "assistant" and isinstance(_msg.get("content"), str):
                    _msg["content"] = _strip_tool_xml_for_display(
                        _msg["content"],
                        auto_heal_tool_calls = _count_auto_heal,
                        enabled_tool_names = _count_history_gate,
                    ).strip()

    # Nothing survived: the template would render only its generation marker.
    if not openai_messages and not openai_tools:
        raise HTTPException(
            status_code = 503,
            detail = "Cannot count tokens for an empty prompt.",
        )

    # Omitted keys fall back to load-time --chat-template-kwargs, so omitting prices the LOADED mode.
    _normalize_chat_reasoning_controls(payload)
    _template_kwargs = llama_backend._request_reasoning_kwargs(
        payload.enable_thinking,
        payload.reasoning_effort,
        # Off the loop: first use probes the template.
        await asyncio.to_thread(_replay_preserve_thinking, llama_backend, payload, openai_messages),
    )

    # Another tab's load can swap the tokenizer unseen by the caller's guard, so report the id.
    _tokenizer_model = _llama_status_checkpoint_id(llama_backend)

    # Re-check right before reaching llama-server: a run may have started since entry.
    if model_slots.routed_generation_count() > 0:
        raise HTTPException(
            status_code = 503,
            detail = "Cannot count tokens while a generation is in progress.",
        )

    from core.inference.llama_cpp import CountAborted

    try:
        count = await asyncio.to_thread(
            _count_chat_context_tokens,
            llama_backend,
            payload,
            openai_messages,
            openai_tools,
            _template_kwargs,
        )
    except CountAborted:
        raise HTTPException(
            status_code = 503,
            detail = "Cannot count tokens while a generation is in progress.",
        )
    except Exception:
        raise HTTPException(
            status_code = 503,
            detail = "Unable to count tokens with the loaded model tokenizer.",
        )
    # A load landing mid-count leaves the total attributable to neither model.
    if _llama_status_checkpoint_id(llama_backend) != _tokenizer_model:
        raise HTTPException(
            status_code = 503,
            detail = "The loaded model changed while counting tokens.",
        )
    return JSONResponse(
        content = {
            "input_tokens": int(count),
            "model": _count_model_id(_tokenizer_model, via_api_key),
        }
    )


def _anthropic_chat_fields(
    payload: AnthropicMessagesRequest,
    *,
    reads_images: bool,
    server_tools = (),
) -> dict:
    """The chat request fields a /v1/messages request becomes on an in-process model.

    Tool intent is stated for chat: a client catalog or tool history already keeps the
    launcher's tools default out of it, and a request with neither sends tool_choice "none",
    so chat never opens a tool loop the Messages route did not select. ``server_tools`` is
    the Messages route's own selection, run by chat's loop with no confirmation to wait on.
    """
    messages = _named_anthropic_tool_results(
        anthropic_messages_to_openai(
            [m.model_dump() for m in payload.messages],
            payload.system,
            # Kept for the template to decide, as for a chat caller replaying reasoning_content.
            preserve_thinking = payload.preserve_thinking is not False,
            tool_result_images = reads_images,
        )
    )
    studio_tools = _anthropic_requested_studio_tools(payload.tools)
    tool_choice = anthropic_tool_choice_to_openai(payload.tool_choice) or "auto"
    tools = _anthropic_client_tools_for_turn(
        [
            tool
            for tool in anthropic_tools_to_openai(payload.tools or [])
            if tool.get("function", {}).get("name") not in studio_tools
        ],
        tool_choice,
        messages,
    )
    fields = {
        "messages": messages,
        "tools": tools or None,
        "tool_choice": tool_choice if tools else "none",
        "thread_id": payload.thread_id,
        **_anthropic_reasoning_args(payload),
    }
    if "model" in payload.model_fields_set:
        fields["model"] = payload.model
    if payload.auto_heal_tool_calls is not None:
        fields["auto_heal_tool_calls"] = payload.auto_heal_tool_calls
    if server_tools:
        from core.inference.chat_template_helpers import catalog_tool_names

        # What the llama-server loop is handed on this route. Messages refused a confirm
        # gate before the switch, so the loop is told there is none.
        fields.update(
            tools = None,
            tool_choice = _anthropic_server_tool_choice(tool_choice),
            enable_tools = True,
            enabled_tools = sorted(catalog_tool_names(server_tools)),
            mcp_enabled = False,
            confirm_tool_calls = False,
            permission_mode = payload.permission_mode,
            sandbox_level = payload.sandbox_level,
            bypass_permissions = bool(payload.bypass_permissions),
            rag_scope = getattr(payload, "rag_scope", None),
            max_tool_calls_per_message = 25,
            tool_call_timeout = 300,
            auto_heal_tool_calls = True,
        )
    return fields


def _anthropic_server_tool_choice(openai_tool_choice):
    """``tool_choice`` for the server-tool loop: a forced Anthropic alias names its Unsloth tool."""
    if isinstance(openai_tool_choice, dict):
        forced_function = openai_tool_choice.get("function")
        forced_name = forced_function.get("name") if isinstance(forced_function, dict) else None
        canonical_name = _STUDIO_ANTHROPIC_TOOL_ALIASES.get(forced_name)
        if canonical_name:
            return {"type": "function", "function": {"name": canonical_name}}
    return openai_tool_choice


def _anthropic_server_tool_refusal(payload, server_tool_choice, tools) -> Optional[str]:
    """Why the server-tool loop cannot take this request, found once the target is resident."""
    from core.inference.chat_template_helpers import catalog_tool_names, forced_tool_name

    # Bypass Permissions suppresses confirm, so both flags together is fine.
    if bool(getattr(payload, "confirm_tool_calls", False)) and not bool(
        getattr(payload, "bypass_permissions", False)
    ):
        return "confirm_tool_calls is not supported for Anthropic Messages server tools."
    forced_name = forced_tool_name(server_tool_choice)
    if forced_name and forced_name not in catalog_tool_names(tools):
        return f"Invalid 'tool_choice': function '{forced_name}' is not enabled."
    return None


async def _anthropic_in_process_count(
    payload, request, current_subject, *, server_tools: list
) -> Optional[JSONResponse]:
    """Count on a resident MLX model through the chat count route, or None if none is serving."""
    backend = await asyncio.to_thread(get_inference_backend)
    active = getattr(backend, "active_model_name", None)
    entry = (getattr(backend, "models", {}) or {}).get(active) or {}
    if not active or not entry.get("is_mlx"):
        return None
    fields = _anthropic_chat_fields(
        payload, reads_images = bool(entry.get("is_vision")), server_tools = server_tools
    )
    return JSONResponse(
        content = {"input_tokens": await _anthropic_chat_count(fields, request, current_subject)}
    )


async def _anthropic_chat_count(fields: dict, request, current_subject) -> int:
    """Chat's count of the translated request, priced with the tool selection it would run."""
    with _delegated_tool_selection(fields["enabled_tools"] if fields.get("enable_tools") else None):
        counted = await chat_count_tokens(
            ChatCountTokensRequest(**fields), current_subject, request
        )
    return int(json.loads(counted.body)["input_tokens"])


def _anthropic_connection_error_event(error: Any) -> str:
    message = error.get("message") if isinstance(error, dict) else None
    try:
        code = int(error.get("code"))
    except (AttributeError, TypeError, ValueError):
        code = 500
    # Keep the provider's class (an expired saved key is a 401, not a bad request).
    status = code if code in ANTHROPIC_TYPE_BY_STATUS or 500 <= code < 600 else 400
    return build_anthropic_sse_event(
        "error", anthropic_error_body(message or "The connection failed.", status = status)
    )


class _StopSequenceFilter:
    """Cut visible text at the first stop sequence, holding back a tail that could start one: the
    provider proxy forwards no stop sequences, so the relay enforces them like llama-server does."""

    def __init__(self, stops: Any) -> None:
        self.stops = [stop for stop in stops or [] if isinstance(stop, str) and stop]
        self.held = ""
        self.hit: Optional[str] = None

    def feed(self, text: str) -> str:
        if not self.stops or self.hit is not None:
            return "" if self.hit is not None else text
        self.held += text
        found = [(self.held.find(stop), stop) for stop in self.stops if stop in self.held]
        if found:
            index, self.hit = min(found)
            out, self.held = self.held[:index], ""
            return out
        keep = max(len(stop) for stop in self.stops) - 1
        cut = max(len(self.held) - keep, 0)
        out, self.held = self.held[:cut], self.held[cut:]
        return out

    def flush(self) -> str:
        out, self.held = self.held, ""
        return out


def _split_connection_text(chunk: dict, think: Any, stop: _StopSequenceFilter) -> dict:
    """Native thinking arrives as <think> markup in content (the Studio chat's form): hand it to the
    emitter as reasoning_content, and apply the stop sequences to what remains visible."""
    choices = chunk.get("choices") or []
    if not any(
        isinstance(choice.get("delta"), dict)
        and (choice["delta"].get("content") or choice["delta"].get("reasoning_content"))
        for choice in choices
    ):
        return chunk
    chunk = {**chunk, "choices": []}
    for choice in choices:
        delta = dict(choice.get("delta") or {})
        text = delta.get("content") if isinstance(delta.get("content"), str) else ""
        if think is not None:
            reasoning, text = think.feed(text, delta.get("reasoning_content"))
            delta["reasoning_content"] = reasoning or None
        delta["content"] = stop.feed(text) or None
        chunk["choices"].append(
            {**choice, "delta": {k: v for k, v in delta.items() if v is not None}}
        )
    return chunk


# The emitter closes a tool_use block as soon as another call's fragment arrives, so interleaved
# parallel calls would close with partial arguments: hold calls whole until the reply finishes.
def _hold_tool_calls(chunk: dict, held: dict) -> dict:
    choices = chunk.get("choices") or []
    if not any((choice.get("delta") or {}).get("tool_calls") for choice in choices):
        return chunk
    chunk = {**chunk, "choices": []}
    for choice in choices:
        delta = dict(choice.get("delta") or {})
        for part in delta.pop("tool_calls", None) or []:
            if not isinstance(part, dict):
                continue
            call = held.setdefault(
                part.get("index", len(held)),
                {"id": None, "name": "", "arguments": "", "extra_content": None},
            )
            call["id"] = call["id"] or part.get("id")
            function = part.get("function") or {}
            call["name"] += function.get("name") or ""
            call["arguments"] += function.get("arguments") or ""
            call["extra_content"] = part.get("extra_content") or call["extra_content"]
        chunk["choices"].append({**choice, "delta": delta})
    return chunk


def _released_tool_calls(held: dict):
    for index in sorted(held):
        call = held[index]
        part = {
            "index": index,
            "id": call["id"],
            "type": "function",
            "function": {"name": call["name"], "arguments": call["arguments"]},
        }
        if call["extra_content"]:
            part["extra_content"] = call["extra_content"]
        yield {"choices": [{"index": 0, "delta": {"tool_calls": [part]}}]}
    held.clear()


def _pending_connection_text(think: Optional[Any], stop: _StopSequenceFilter, held: dict):
    """What is still held back once the reply ends: unterminated markup, a possible stop prefix,
    then the buffered tool calls."""
    reasoning, text = think.finish() if think is not None else ("", "")
    text = stop.feed(text) + stop.flush() if stop.hit is None else ""
    delta = {
        key: value for key, value in (("reasoning_content", reasoning), ("content", text)) if value
    }
    if delta:
        yield {"choices": [{"index": 0, "delta": delta}]}
    yield from _released_tool_calls(held)


async def _anthropic_events_from_openai_sse(
    lines,
    message_id: str,
    model: str,
    subject: Optional[str] = None,
    *,
    single_tool_use: bool = False,
    stop_sequences: Any = None,
    parse_thinking: bool = True,
):
    emitter = AnthropicPassthroughEmitter()
    # Always, like the Studio chat: a provider can think by default with no thinking controls sent.
    # Native thinking leads the reply, so only a leading block is read: a literal tag later in the
    # answer (or inside JSON) stays text.
    think = _ResponsesReasoningExtractor(parse_think_markers = parse_thinking, single_block = True)
    stop = _StopSequenceFilter(stop_sequences)
    recorder = _ConnectionExtrasRecorder(subject)
    dropped: set[int] = set()
    tool_blocks = 0

    def relay(event: str, extras: list) -> Optional[str]:
        nonlocal tool_blocks
        if stop.hit is not None and event.startswith("event: message_delta"):
            data = json.loads(event.partition("\ndata: ")[2])
            data["delta"].update(stop_reason = "stop_sequence", stop_sequence = stop.hit)
            return build_anthropic_sse_event(data["type"], data)
        if not (extras or single_tool_use) or not event.startswith("event: content_block"):
            return event
        data = json.loads(event.partition("\ndata: ")[2])
        index = data.get("index")
        if (
            data["type"] == "content_block_start"
            and data["content_block"].get("type") == "tool_use"
        ):
            extra = extras.pop(0) if extras else None
            # disable_parallel_tool_use: at most one tool_use, the way the local route caps it.
            if single_tool_use and tool_blocks:
                dropped.add(index)
                return None
            tool_blocks += 1
            # The emitter renames tool ids (toolu_*): file the call's extras under the id it publishes.
            recorder.call(data["content_block"].get("id"), extra)
        if index in dropped:
            return None
        shift = sum(1 for gone in dropped if gone < index)
        if not shift:
            return event
        data["index"] = index - shift
        return build_anthropic_sse_event(data["type"], data)

    def feed(chunk: dict):
        extras = [
            call.get("extra_content")
            for choice in chunk.get("choices") or []
            for call in (choice.get("delta") or {}).get("tool_calls") or []
            if isinstance(call, dict) and call.get("id")
        ]
        for event in emitter.feed_chunk(chunk):
            event = relay(event, extras)
            if event is not None:
                yield event

    held: dict[int, dict] = {}
    for event in emitter.start(message_id, model):
        yield event
    items = _sse_data_lines(lines)
    try:
        async for line in items:
            data = line[len("data:") :].strip() if line.startswith("data:") else ""
            if data == "[DONE]":
                break
            if not data:
                continue
            parsed = json.loads(data)
            if parsed.get("error"):
                yield _anthropic_connection_error_event(parsed["error"])
                return
            recorder.chunk(parsed, calls = False)
            parsed = _split_connection_text(_hold_tool_calls(parsed, held), think, stop)
            if stop.hit is not None:
                for event in feed(parsed):
                    yield event
                break
            finishes = [c for c in parsed.get("choices") or [] if c.get("finish_reason")]
            if finishes:
                # This chunk's own text goes before the held-back tail, then the finish.
                text_part = {
                    **{k: v for k, v in parsed.items() if k != "usage"},
                    "choices": [{**c, "finish_reason": None} for c in parsed["choices"]],
                }
                for event in feed(text_part):
                    yield event
                for chunk in _pending_connection_text(think, stop, held):
                    for event in feed(chunk):
                        yield event
                if stop.hit is not None:
                    break
                parsed = {
                    **parsed,
                    "choices": [
                        {
                            "index": c.get("index", 0),
                            "delta": {},
                            "finish_reason": c["finish_reason"],
                        }
                        for c in finishes
                    ],
                }
            for event in feed(parsed):
                yield event
    finally:
        await items.aclose()
    for chunk in _pending_connection_text(think, stop, held):
        for event in feed(chunk):
            yield event
    if stop.hit is not None:
        for event in feed({"choices": [{"index": 0, "delta": {}, "finish_reason": "stop"}]}):
            yield event
    for event in emitter.finish():
        event = relay(event, [])
        if event is not None:
            yield event


def _anthropic_message_from_events(events: list[str]) -> dict:
    message: dict = {}
    blocks: list[dict] = []
    partial_json: dict[int, str] = {}
    for event in events:
        data = json.loads(event.partition("\ndata: ")[2])
        if data["type"] == "error":
            status_code = next(
                (
                    code
                    for code, err_type in ANTHROPIC_TYPE_BY_STATUS.items()
                    if err_type == data["error"]["type"] and err_type != "api_error"
                ),
                502,
            )
            raise HTTPException(status_code = status_code, detail = data["error"]["message"])
        if data["type"] == "message_start":
            message = data["message"]
        elif data["type"] == "content_block_start":
            blocks.append(dict(data["content_block"]))
        elif data["type"] == "content_block_delta":
            block, delta = blocks[data["index"]], data["delta"]
            if delta["type"] == "text_delta":
                block["text"] += delta["text"]
            elif delta["type"] == "thinking_delta":
                block["thinking"] += delta["thinking"]
            elif delta["type"] == "input_json_delta":
                partial_json[data["index"]] = (
                    partial_json.get(data["index"], "") + delta["partial_json"]
                )
        elif data["type"] == "message_delta":
            message.update(data["delta"])
            message["usage"] = data["usage"]
    for index, text in partial_json.items():
        try:
            blocks[index]["input"] = json.loads(text)
        except json.JSONDecodeError:
            blocks[index]["input"] = {}
    message["content"] = blocks
    return message


async def _anthropic_messages_via_connection(
    payload: AnthropicMessagesRequest,
    request: Request,
    current_subject: str,
    provider_id: str,
    model: str,
):
    if payload.max_tokens is None:
        raise HTTPException(
            status_code = 400,
            detail = anthropic_error_body(
                "max_tokens: field required",
                status = 400,
                err_type = "invalid_request_error",
            ),
        )
    _validate_anthropic_client_tools(payload.tools)
    if _anthropic_requested_studio_tools(payload.tools) or payload.enable_tools is True:
        raise HTTPException(
            status_code = 400,
            detail = "Unsloth server tools are not available with a Connection model.",
        )
    # Keep every turn's thinking: _build_external_messages drops it for providers that must not get it,
    # and DeepSeek answers 400 when tools ride on a history without it.
    messages = anthropic_messages_to_openai(
        [m.model_dump() for m in payload.messages], payload.system, preserve_thinking = True
    )
    _restore_connection_tool_extras(current_subject, messages)
    fields = {
        "model": model,
        "provider_id": provider_id,
        "external_model": model,
        "messages": messages,
        "tools": anthropic_tools_to_openai(payload.tools or []) or None,
        "tool_choice": anthropic_tool_choice_to_openai(payload.tool_choice),
        "max_tokens": payload.max_tokens,
        "stop": payload.stop_sequences or None,
        "temperature": payload.temperature,
        "top_p": payload.top_p,
        "top_k": payload.top_k,
        "min_p": payload.min_p,
        "repetition_penalty": payload.repetition_penalty,
        "presence_penalty": payload.presence_penalty,
        "seed": payload.seed,
        "session_id": payload.session_id,
        "cancel_id": payload.cancel_id,
        "response_format": _anthropic_response_format(payload, require_llama_compatibility = False),
        "stream": True,
        "stream_options": {"include_usage": True},
    }
    reasoning = _anthropic_reasoning_args(payload)
    fields["enable_thinking"] = reasoning["enable_thinking"]
    fields["reasoning_effort"] = reasoning["reasoning_effort"]
    fields["preserve_thinking"] = reasoning.get("preserve_thinking")
    from fastapi.exceptions import RequestValidationError
    from pydantic import ValidationError

    # Messages bounds sampling looser than chat: a value chat rejects is a 400, not a 500.
    try:
        chat_payload = ChatCompletionRequest(
            **{name: value for name, value in fields.items() if value is not None}
        )
    except ValidationError as exc:
        raise RequestValidationError(exc.errors()) from None
    response = await produce_openai_chat_completions(
        chat_payload, request, current_subject, cancel_on_disconnect = True
    )
    if not isinstance(response, StreamingResponse):
        return response
    events = _anthropic_events_from_openai_sse(
        response.body_iterator,
        f"msg_{uuid.uuid4().hex[:24]}",
        payload.model,
        current_subject,
        single_tool_use = isinstance(payload.tool_choice, dict)
        and bool(payload.tool_choice.get("disable_parallel_tool_use")),
        stop_sequences = payload.stop_sequences,
        parse_thinking = chat_payload.enable_thinking is not False,
    )
    if payload.stream:
        return _sse_streaming_response(events)
    return JSONResponse(_anthropic_message_from_events([event async for event in events]))


@router.post("/messages/count_tokens")
async def anthropic_count_tokens(
    payload: AnthropicMessagesRequest,
    request: Request,
    current_subject: str = Depends(get_current_subject),
):
    """Anthropic-compatible token-counting endpoint (POST /v1/messages/count_tokens).

    Translates the Anthropic request to OpenAI form (the same translation the
    /messages handler uses), counts prompt tokens with the loaded GGUF model's
    tokenizer, or a resident MLX model's through the chat count route, and returns
    ``{"input_tokens": int}`` only. Unlike /messages, max_tokens is NOT required here.
    """
    if _connection_model_ref(payload.model) is not None:
        raise HTTPException(
            status_code = 400,
            detail = "Token counting is not available for a Connection model.",
        )
    # Reject malformed tools before the switch, like /messages, so an invalid
    # count request can't evict the loaded model.
    _validate_anthropic_client_tools(payload.tools)
    _anthropic_website_policy(payload.tools)
    # Counting compiles no output grammar, matching Anthropic's count_tokens behavior.
    _count_response_format = _anthropic_response_format(payload, require_llama_compatibility = False)
    _count_studio_tools = _anthropic_requested_studio_tools(payload.tools)
    _count_has_client_tool = any(
        (t if isinstance(t, dict) else t.model_dump()).get("input_schema") is not None
        or anthropic_schema_client_tool_kind(t) is not None
        for t in payload.tools or []
    )
    _count_openai_tool_choice = anthropic_tool_choice_to_openai(payload.tool_choice) or "auto"
    _count_schema_disables_server_tools = (
        _count_openai_tool_choice == "none" and _count_response_format is not None
    )
    _count_selects_server_tools = (
        _anthropic_selects_server_tools(payload, _count_studio_tools, _count_has_client_tool)
        and not _count_schema_disables_server_tools
    )
    from core.inference.tools import ALL_TOOLS as _ANTHROPIC_COUNT_TOOLS
    from utils.hardware import DeviceType, get_device

    _count_in_process_server_tools = (
        _select_anthropic_server_tools(
            _ANTHROPIC_COUNT_TOOLS, _count_studio_tools, payload.enabled_tools
        )
        if _count_selects_server_tools
        else []
    )
    # Only an MLX model counts in process, and only what the chat count route prices, so any
    # other non-GGUF target is refused before it loads.
    _in_process_refusal = None
    # A replayed MCP envelope is an image to a vision target, which the chat count refuses.
    _count_replay = _anthropic_chat_fields(payload, reads_images = True)["messages"]
    if _anthropic_request_has_image(payload) or (
        _messages_mention_mcp_images(_count_replay)
        and await asyncio.to_thread(_messages_have_promotable_mcp_images, _count_replay)
    ):
        _in_process_refusal = "Cannot count tokens for messages containing images."
    # Count with the requested model's tokenizer, like the sibling /messages.
    # Carry the vision guard too: an image count naming a text-only GGUF must not
    # evict a loaded vision model for a swap that can't serve the request.
    await _maybe_auto_switch_model(
        _switch_model_for_payload(payload),
        request,
        current_subject,
        require_vision = _anthropic_request_has_image(payload, tool_results = False),
        # count_tokens only tokenizes, so it must not adopt the resident model (middleware agrees).
        claim_resident = False,
        gguf_only = (
            _in_process_refusal is not None or await asyncio.to_thread(get_device) != DeviceType.MLX
        ),
        gguf_only_reason = _in_process_refusal,
    )

    llama_backend = get_llama_cpp_backend()
    if not llama_backend.is_loaded:
        _in_process_count = await _anthropic_in_process_count(
            payload,
            request,
            current_subject,
            server_tools = _count_in_process_server_tools,
        )
        if _in_process_count is not None:
            return _in_process_count
        _status, _detail = await _no_model_loaded_error(
            "No GGUF model loaded. Load a GGUF model first.",
            _switch_model_for_payload(payload),
            request,
            status = 503,
        )
        raise HTTPException(status_code = _status, detail = _detail)

    # system is folded into the messages list, so pass system=None to the counter.
    openai_messages = anthropic_messages_to_openai(
        [m.model_dump() for m in payload.messages],
        payload.system,
        preserve_thinking = _anthropic_preserve_thinking(llama_backend, payload),
        tool_result_images = llama_backend.is_vision,
    )
    # Named and judged BEFORE the sanitizer, in /v1/messages order: it folds role='tool' into user
    # on templates without tool-role support.
    openai_messages = _named_anthropic_tool_results(openai_messages)

    # Refuse promoted images: apply-template counts media markers, not projector tokens. Parse off loop.
    if (
        llama_backend.is_vision
        and _messages_mention_mcp_images(openai_messages)
        and await asyncio.to_thread(_messages_have_promotable_mcp_images, openai_messages)
    ):
        raise HTTPException(
            status_code = 400,
            detail = "Cannot count tokens for messages containing images.",
        )

    # Priced as the images really sent, not the envelope's base64; awaited since promotion is
    # heavy Pillow work.
    openai_messages = await _promote_mcp_history_images_async(
        openai_messages, vision = llama_backend.is_vision
    )

    # Apply the same sanitization as /messages, so the count matches the prompt the real request builds.
    openai_messages = _sanitize_anthropic_openai_messages(openai_messages, llama_backend)
    # /apply-template fetches remote media even though token counting only needs its marker.
    _placeholder_remote_images_for_count(openai_messages)
    # Only the client-tool passthrough is forwarded verbatim, so reproduce /messages' own
    # routing rather than "any tools": a Studio server-tool alias, or a template without
    # passthrough support, falls through to plain generation there and does carry the date.
    _count_server_tools = (
        _count_selects_server_tools
        and llama_backend.supports_tools
        and not _anthropic_request_has_image(payload, tool_results = llama_backend.is_vision)
    )
    _count_selected_server_tools = []
    if _count_server_tools:
        _count_selected_server_tools = _tools_for_search_images(
            _select_anthropic_server_tools(
                _ANTHROPIC_COUNT_TOOLS,
                _count_studio_tools,
                payload.enabled_tools,
                supports_vision = bool(getattr(llama_backend, "is_vision", False)),
            )
        )
        _count_server_tools = bool(_count_selected_server_tools)
    _count_openai_client_tools = _anthropic_client_tools_for_turn(
        [
            tool
            for tool in anthropic_tools_to_openai(payload.tools or [])
            if tool.get("function", {}).get("name") not in _count_studio_tools
        ],
        _count_openai_tool_choice,
        openai_messages,
    )
    _guard_anthropic_client_tool_catalog(
        _count_openai_client_tools,
        _count_openai_tool_choice,
        _count_server_tools,
        llama_backend,
    )
    _count_client_tools = (
        not _count_server_tools
        and bool(_count_openai_client_tools)
        and getattr(llama_backend, "supports_tool_passthrough", llama_backend.supports_tools)
    )
    openai_tools = _count_openai_client_tools if _count_client_tools else None
    if _count_client_tools:
        from core.inference.chat_template_helpers import (
            forced_tool_catalog,
            neutralize_tool_descriptions,
        )

        # Pick the forced tool from the sanitized catalog, as the passthrough body does (#7066).
        _count_safe_tools = neutralize_tool_descriptions(
            openai_tools, None, getattr(llama_backend, "markup_profile", None)
        )
        openai_tools = (
            forced_tool_catalog(_count_openai_tool_choice, _count_safe_tools) or openai_tools
        )
    else:
        openai_messages = _prepend_current_date_to_messages(
            openai_messages,
            request,
            include_api_key = _count_server_tools,
        )
    if _count_server_tools:
        openai_tools = _count_selected_server_tools
        _count_full_access = bool(getattr(payload, "bypass_permissions", False))
        if _count_full_access:
            # Same schemas /messages renders under Full access, or the count prices a different prompt.
            from core.inference.tools import apply_full_access_tool_descriptions
            openai_tools = apply_full_access_tool_descriptions(openai_tools)
        elif sys.platform == "win32":
            from core.inference.tools import apply_terminal_profile_for_request
            openai_tools = await asyncio.to_thread(
                apply_terminal_profile_for_request,
                openai_tools,
                getattr(payload, "sandbox_level", None),
            )
        _count_nudge = _build_tool_action_nudge(
            tools = openai_tools,
            model_name = _llama_public_model_id(llama_backend, payload.model),
            full_access = _count_full_access,
        )
        openai_messages = _append_to_system_message(openai_messages, _count_nudge)

    # Render with the same reasoning controls generation will use: on switchable
    # templates thinking / reasoning_effort / preserve_thinking change the
    # rendered prompt, so counting the load-time default would under- or
    # over-count the request the client is about to send.
    if _count_server_tools:
        from core.inference.tool_loop_controller import restore_replayed_tool_results
        openai_messages = await asyncio.to_thread(restore_replayed_tool_results, openai_messages)
    # Off the loop: first use probes the template.
    _reasoning_args = await _resolved_anthropic_reasoning_args_async(
        llama_backend, payload, openai_messages
    )
    try:
        count = await asyncio.to_thread(
            lambda: llama_backend.count_chat_tokens(
                openai_messages,
                None,
                openai_tools,
                strict = True,
                chat_template_kwargs = _anthropic_count_template_kwargs(
                    llama_backend, _reasoning_args
                ),
            )
        )
    except Exception:
        raise HTTPException(
            status_code = 503,
            detail = "Unable to count tokens with the loaded model tokenizer.",
        )
    # /apply-template renders an image as a marker, so charge admission's per-image allowance.
    image_parts = sum(
        isinstance(part, dict) and part.get("type") == "image_url"
        for message in openai_messages
        if isinstance(message.get("content"), list)
        for part in message["content"]
    )
    image_tokens = image_parts * _openai_llama_admission_image_tokens(llama_backend)
    return JSONResponse(content = {"input_tokens": int(count) + image_tokens})


def _set_or_prepend_system_message(
    messages: Optional[list[dict]], system_prompt: str
) -> list[dict]:
    """Return messages with a single leading system prompt, preserving multimodal parts."""
    safe_messages = messages or []
    if not system_prompt:
        return safe_messages

    # Drop old system/developer turns so the backend never sees duplicate or conflicting system prompts.
    others = [dict(msg) for msg in safe_messages if msg.get("role") not in ("system", "developer")]
    system = {"role": "system", "content": system_prompt}
    # One shared name or none: a single turn cannot answer to two.
    names = {msg.get("name") for msg in safe_messages if msg.get("role") in ("system", "developer")}
    if len(names) == 1 and (name := names.pop()):
        system["name"] = name
    return [system, *others]


def _anthropic_chat_sampling(payload) -> dict:
    """Client-set sampling fields; omitted ones stay omitted so chat applies the model's defaults."""
    return {
        name: getattr(payload, name)
        for name in (
            "temperature",
            "top_p",
            "top_k",
            "min_p",
            "repetition_penalty",
            "presence_penalty",
            "seed",
            "nudge_tool_calls",
        )
        if getattr(payload, name) is not None
    }


def _anthropic_chat_sampling_refusal(payload, messages) -> Optional[str]:
    """Why chat would reject this request's sampling fields; Messages bounds some less tightly."""
    from pydantic import ValidationError

    try:
        ChatCompletionRequest(
            messages = messages,
            max_tokens = payload.max_tokens,
            **_anthropic_chat_sampling(payload),
        )
    except ValidationError as exc:
        error = exc.errors()[0]
        field = ".".join(str(part) for part in error.get("loc", ())) or "request"
        return f"'{field}': {error.get('msg')} on a non-GGUF model."
    return None


def _in_process_model_resident() -> bool:
    orchestrator = _peek_inference_backend()
    entry = (getattr(orchestrator, "models", None) or {}).get(
        getattr(orchestrator, "active_model_name", None)
    )
    # Chat answers a TTS model with a finished clip, not a text reply.
    return isinstance(entry, dict) and not (
        entry.get("is_audio") and entry.get("audio_type") != "whisper"
    )


async def _anthropic_in_process_input_tokens(fields: dict, request, current_subject) -> int:
    """``message_start`` input tokens: the count route's total, or 0 where it cannot price one."""
    try:
        return await _anthropic_chat_count(fields, request, current_subject)
    except HTTPException:
        return 0


class _ChatToolLoopEvents:
    """Chat's tool-loop stream as the events the llama-server tool loop yields.

    Text is cumulative until each tool_end, with reasoning folded in as one leading ``<think>``
    span recorded in ``provenance`` the way that loop records it. Reasoning from a re-prompted
    turn that follows visible text has no such place, so it is dropped (thinking is optional).
    """

    def __init__(self, provenance: dict) -> None:
        self._prov = provenance
        self._text = ""
        self._wrap = None
        self._finish_reason = None
        self._usage = {}

    def _content(self) -> dict:
        return {"type": "content", "text": self._text, _WRAPPED_SO_FAR: self._prov["wrapped"]}

    def feed(self, chunk: dict) -> list:
        etype = chunk.get("type")
        if etype in ("tool_start", "tool_end", "tool_output", "tool_args"):
            events = []
            if etype == "tool_start" and self._wrap is not None:
                self._text, self._wrap = self._text + "</think>", None
                events.append(self._content())
            if etype == "tool_end":
                self._text, self._wrap = "", None
            return events + [chunk]
        if etype is not None or not chunk.get("choices"):
            self._usage = chunk.get("usage") or self._usage
            return []
        events = []
        for choice in chunk["choices"]:
            delta = choice.get("delta") or {}
            reasoning = delta.get("reasoning_content")
            if reasoning and (self._wrap is not None or not self._text):
                if self._wrap is None:
                    self._prov["wrapped"] += 1
                    self._wrap = {"len": 0}
                    self._prov.setdefault("wraps", []).append(self._wrap)
                    self._text += "<think>"
                self._text += reasoning
                self._wrap["len"] += len(reasoning)
                events.append(self._content())
            if delta.get("content"):
                if self._wrap is not None:
                    self._text, self._wrap = self._text + "</think>", None
                self._text += delta["content"]
                events.append(self._content())
            self._finish_reason = choice.get("finish_reason") or self._finish_reason
        return events

    def finish(self) -> list:
        return [{"type": "metadata", "finish_reason": self._finish_reason, "usage": self._usage}]


def _anthropic_in_process_sse(
    source: "_InProcessChatStream",
    *,
    request,
    monitor_id,
    message_id: str,
    model_name: str,
    input_tokens: int,
    disable_parallel_tool_use: bool,
    server_tools = (),
):
    """Chat's stream as Anthropic SSE, ending the way the matching llama-server stream ends."""
    from core.inference.llama_keepwarm import mark_response_failed

    if server_tools:
        provenance: dict = {"wrapped": 0}
        emitter = AnthropicStreamEmitter(parse_think = True, think_provenance = provenance)
        rules = _AnthropicToolEventRules(
            emitter, server_tools, disable_parallel_tool_use, provenance
        )
        tool_events = _ChatToolLoopEvents(provenance)

        def feed(chunk):
            # A stopped server-tool stream ends without message_stop, as on llama-server.
            if source.cancelled:
                return [], True
            # Raised, so the error event is the one a failed llama-server tool loop gets.
            error_message = _monitor_openai_error_message(chunk)
            if error_message:
                raise RuntimeError(error_message)
            return [line for event in tool_events.feed(chunk) for line in rules.feed(event)], False

        def finish():
            if source.cancelled:
                return []
            return [line for event in tool_events.finish() for line in rules.feed(event)] + (
                rules.finish()
            )
    else:
        emitter = AnthropicPassthroughEmitter(reasoning_as_thinking = True)

        def feed(chunk):
            return _anthropic_passthrough_chunk_lines(
                emitter, chunk, request, disable_parallel_tool_use
            )

        finish = emitter.finish
    # The chat handler's tracker holds cancel_id and session_id; the message id is Messages' own.
    tracker = _TrackedCancel(source.cancel_event, message_id, track_run = False)
    tracker.__enter__()

    async def _stream():
        cancelled = False
        chunks = source.chunks()
        try:
            for line in emitter.start(message_id, model_name, input_tokens):
                yield line
            while (chunk := await source.next_chunk(chunks)) is not None:
                if chunk is _LLAMA_STREAM_KEEPALIVE:
                    yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                    continue
                lines, failed = feed(chunk)
                for line in lines:
                    yield line
                if failed:
                    return
        except asyncio.CancelledError:
            cancelled = True
            source.cancel_event.set()
            raise
        except Exception as e:
            if not source.cancelled:
                logger.error("anthropic_messages in-process stream error: %s", e)
                mark_response_failed(getattr(request, "scope", None))
                event = _anthropic_stream_error_event(e, force = True)
                if event is not None:
                    yield event
                return
        finally:
            if source.cancelled:
                mark_response_failed(getattr(request, "scope", None))
            try:
                await chunks.aclose()
                await source.close(cancelled = cancelled)
            finally:
                tracker.__exit__(None, None, None)

        for line in finish():
            yield line

    async def _unstarted_cleanup() -> None:
        api_monitor.finish(monitor_id, "cancelled")
        try:
            await source.close(cancelled = True)
        finally:
            tracker.__exit__(None, None, None)

    return _sse_streaming_response(_stream(), unstarted_cleanup = _unstarted_cleanup)


async def _anthropic_in_process_tool_message(
    chat_req,
    request,
    current_subject,
    *,
    cancel_event,
    message_id,
    model_name,
    server_tools,
    disable_parallel_tool_use,
):
    """A non-streaming server-tool reply: chat's tool-loop stream reduced as llama-server's is.

    Chat's own JSON reply drops the tool calls it ran, so the stream is driven here instead.
    """
    provenance: dict = {"wrapped": 0}
    tool_events = _ChatToolLoopEvents(provenance)
    events: list = []
    source = await _InProcessChatStream.open(
        chat_req,
        request,
        current_subject,
        cancel_event = cancel_event,
        tool_names = chat_req.enabled_tools,
    )
    cancelled = False
    chunks = source.chunks()
    try:
        while (chunk := await source.next_chunk(chunks)) is not None:
            if chunk is _LLAMA_STREAM_KEEPALIVE:
                continue
            error_message = _monitor_openai_error_message(chunk)
            if error_message:
                raise _anthropic_map_generation_error(RuntimeError(error_message))
            events.extend(tool_events.feed(chunk))
    except asyncio.CancelledError:
        cancelled = True
        raise
    finally:
        await chunks.aclose()
        await source.close(cancelled = cancelled)
    response = _anthropic_tool_response_from_events(
        events + tool_events.finish(),
        message_id,
        model_name,
        disable_parallel_tool_use = disable_parallel_tool_use,
        openai_tools = server_tools,
        parse_think = True,
        think_provenance = provenance,
    )
    # A stopped run answers with what it had, as the llama-server tool path does.
    _mark_cancelled_json_response_failed(request, cancel_event)
    return response


async def _anthropic_in_process_messages(
    payload: AnthropicMessagesRequest,
    request,
    current_subject,
    server_tools = (),
    website_policy = None,
):
    """Serve /v1/messages from an in-process model (MLX, transformers) through chat."""
    backend = await asyncio.to_thread(get_inference_backend)
    entry = (getattr(backend, "models", {}) or {}).get(backend.active_model_name) or {}
    image_location = not entry.get("is_vision") and _anthropic_top_level_image_location(payload)
    if image_location:
        # Named as on llama-server, so a client can drop the image and keep the session going.
        raise HTTPException(
            status_code = 400,
            detail = f"{image_location}: Image provided but current model does not support vision.",
        )
    fields = _anthropic_chat_fields(
        payload, reads_images = bool(entry.get("is_vision")), server_tools = server_tools
    )
    refusal = server_tools and _anthropic_server_tool_refusal(
        payload, fields["tool_choice"], server_tools
    )
    if refusal:
        raise HTTPException(
            status_code = 400,
            detail = anthropic_error_body(refusal, status = 400, err_type = "invalid_request_error"),
        )
    # Validated against llama.cpp's compiler before the switch; dropped when a tool may run, as there.
    response_format = _anthropic_response_format(payload, require_llama_compatibility = False)
    if (server_tools or fields["tools"]) and fields["tool_choice"] != "none":
        response_format = None
    model_name = _orchestrator_public_model_id(backend) or payload.model
    message_id = f"msg_{uuid.uuid4().hex[:24]}"
    disable_parallel = bool(
        isinstance(payload.tool_choice, dict)
        and payload.tool_choice.get("disable_parallel_tool_use")
    )
    chat_req = ChatCompletionRequest(
        **fields,
        **_anthropic_chat_sampling(payload),
        max_tokens = payload.max_tokens,
        stop = payload.stop_sequences or None,
        parallel_tool_calls = False if disable_parallel else None,
        cancel_id = payload.cancel_id,
        session_id = payload.session_id,
        response_format = response_format,
    )
    if server_tools:
        chat_req._website_policy = website_policy

    monitor_id = None
    context_length = _monitor_context_length()
    if not getattr(getattr(request, "state", None), "skip_api_monitor", False):
        monitor_id = api_monitor.start(
            endpoint = getattr(getattr(request, "url", None), "path", "/v1/messages"),
            method = getattr(request, "method", "POST"),
            via_api_key = _request_used_api_key(request),
            model = model_name,
            prompt = _monitor_prompt_from_messages(fields["messages"]),
            context_length = context_length,
            subject = current_subject,
        )
    cancel_event = threading.Event()
    try:
        if payload.stream:
            input_tokens = await _anthropic_in_process_input_tokens(
                fields, request, current_subject
            )
            source = await _InProcessChatStream.open(
                chat_req,
                request,
                current_subject,
                cancel_event = cancel_event,
                tool_names = chat_req.enabled_tools if server_tools else None,
            )
            response = _anthropic_in_process_sse(
                source,
                request = request,
                monitor_id = monitor_id,
                message_id = message_id,
                model_name = model_name,
                input_tokens = input_tokens,
                disable_parallel_tool_use = disable_parallel,
                server_tools = server_tools,
            )
        elif server_tools:
            response = await _anthropic_in_process_tool_message(
                chat_req,
                request,
                current_subject,
                cancel_event = cancel_event,
                message_id = message_id,
                model_name = model_name,
                server_tools = server_tools,
                disable_parallel_tool_use = disable_parallel,
            )
        else:
            perf: dict = {"monitor_id": monitor_id, "context_length": context_length}
            sink_token = _monitor_perf_sink.set(perf if monitor_id else None)
            try:
                with _delegated_request_state(
                    request, skip_api_monitor = True, generation_cancel_event = cancel_event
                ):
                    result = await openai_chat_completions(chat_req, request, current_subject)
            finally:
                _monitor_perf_sink.reset(sink_token)
            # A stopped run returns what it had; the llama-server path never answers one.
            if cancel_event.is_set():
                raise asyncio.CancelledError()
            response = _anthropic_message_from_openai_completion(
                json.loads(result.body),
                message_id,
                model_name,
                openai_tools = chat_req.tools,
                allowed_tools = None,
                disable_parallel_tool_use = disable_parallel,
                response_format = response_format,
                parse_think = True,
            )
    except asyncio.CancelledError:
        cancel_event.set()
        api_monitor.finish(monitor_id, "cancelled")
        raise
    except Exception as exc:
        api_monitor.fail(monitor_id, _friendly_error(exc))
        raise
    return _monitor_anthropic_response(response, monitor_id, context_length, cancel_event)


@router.post("/messages")
@account_access.gpu_busy_route
async def anthropic_messages(
    payload: AnthropicMessagesRequest,
    request: Request,
    current_subject: str = Depends(get_current_subject),
):
    """
    Anthropic-compatible Messages API endpoint.

    Translates Anthropic message format to internal OpenAI format, runs through
    the existing agentic tool loop when tools are provided, and returns
    responses in Anthropic Messages API format (streaming SSE or non-streaming
    JSON).
    """
    _admit_tool_access(payload)
    connection = _connection_model_ref(payload.model)
    if connection is not None:
        return await _anthropic_messages_via_connection(
            payload, request, current_subject, *connection
        )
    await _route_to_extra_slot(_switch_model_for_payload(payload))
    llama_backend = get_llama_cpp_backend()

    # Default-off parity: with no automatic load possible and nothing loaded, 503
    # before any request-shape check, exactly as the pre-feature endpoint did. When
    # an automatic load can run (auto-switch or a standalone idle TTL), fall through
    # so validation runs before the reload hook gets a chance to restore the model.
    # Plain detail, not _no_model_loaded_error: that helper leaves this case unchanged.
    if (
        not llama_backend.is_loaded
        and not _in_process_model_resident()
        and not _automatic_model_load_may_run()
    ):
        _npu_model = _resident_npu_model()
        if _npu_model is not None:
            raise HTTPException(
                status_code = 400,
                detail = (
                    f"The loaded NPU model ({_npu_model.model_path}) serves "
                    "/v1/chat/completions only. Load a GGUF model to use the "
                    "Anthropic Messages API."
                ),
            )
        raise HTTPException(
            status_code = 503,
            detail = _no_model_loaded_detail("No GGUF model loaded. Load a GGUF model first."),
        )

    # max_tokens is required by Anthropic; validate before auto-switch so no load is triggered.
    if payload.max_tokens is None:
        raise HTTPException(
            status_code = 400,
            detail = anthropic_error_body(
                "max_tokens: field required",
                status = 400,
                err_type = "invalid_request_error",
            ),
        )

    # Reject malformed client tools before any model load, so an invalid request never evicts the model.
    _validate_anthropic_client_tools(payload.tools)

    _anthropic_has_image = _anthropic_request_has_image(payload)
    # Tool-result images become a note on a text-only model, so only top-level images count here.
    _anthropic_top_level_image = _anthropic_request_has_image(payload, tool_results = False)
    _anthropic_image_b64s = _anthropic_local_image_payloads(payload)
    # Anthropic's block path lets clients drop the image instead of resending it every turn.
    _anthropic_image_prefix = (
        f"{_anthropic_top_level_image_location(payload)}: " if _anthropic_top_level_image else ""
    )

    # Mixing server and client tools is unsupported; reject before the switch so it can't evict.
    requested_studio_tools = _anthropic_requested_studio_tools(payload.tools)
    website_policy = _anthropic_website_policy(payload.tools)
    _has_client_tool = any(
        (t if isinstance(t, dict) else t.model_dump()).get("input_schema") is not None
        or anthropic_schema_client_tool_kind(t) is not None
        for t in payload.tools or []
    )
    _explicit_server_tools = bool(requested_studio_tools) or (
        payload.enable_tools is True and _effective_enable_tools(payload) is not False
    )
    if _explicit_server_tools and _has_client_tool:
        raise HTTPException(
            status_code = 400,
            detail = (
                "Mixing Anthropic server tools (e.g. web_search_20250305) "
                "with custom client tools in a single request is not "
                "supported. Send them in separate requests."
            ),
        )

    # Reject ask and gated auto modes first; --enable-tools must not steal an explicit client catalog.
    _selects_server_tools = _anthropic_selects_server_tools(
        payload, requested_studio_tools, _has_client_tool
    )
    _response_format = _anthropic_response_format(payload)
    _schema_disables_server_tools = (
        _response_format is not None
        and anthropic_tool_choice_to_openai(payload.tool_choice) == "none"
    )
    _server_tools_selected_pre = (
        _selects_server_tools
        and not _anthropic_top_level_image
        and not _schema_disables_server_tools
    )
    selected_server_tools = []
    if _server_tools_selected_pre:
        from core.inference.tools import ALL_TOOLS as _ALL_TOOLS_PRE
        selected_server_tools = _tools_for_search_images(
            _select_anthropic_server_tools(
                _ALL_TOOLS_PRE, requested_studio_tools, payload.enabled_tools
            )
        )
    _server_tools_requested_pre = bool(selected_server_tools)
    if _server_tools_requested_pre:
        _perm_mode_pre = getattr(payload, "permission_mode", None)
        _confirm_opt_out_pre = getattr(payload, "confirm_tool_calls", None) is False
        _gated_tool_selected_pre = any(
            tool["function"]["name"] not in _ANTHROPIC_UNPROMPTED_SAFE_TOOLS
            for tool in selected_server_tools
        )
        # confirm_tool_calls=False opts out of the gate entirely, even under ask.
        if not _confirm_opt_out_pre and (
            _perm_mode_pre == "ask"
            or (_perm_mode_pre in ("auto", None) and _gated_tool_selected_pre)
        ):
            raise HTTPException(
                status_code = 400,
                detail = anthropic_error_body(
                    "permission_mode 'ask' has no confirmation channel for Anthropic "
                    "Messages server tools, and 'auto' (or the omitted default) cannot "
                    "gate a local 'terminal'/'python' tool here; set 'off' or 'full'.",
                    status = 400,
                    err_type = "invalid_request_error",
                ),
            )

    # What an in-process model cannot serve here is refused before a non-GGUF target loads.
    _chat_req_pre = ChatCompletionRequest(
        messages = _anthropic_chat_fields(payload, reads_images = True)["messages"]
    )
    _chat_parts = _extract_content_parts(_chat_req_pre.messages, keep_tool_images = True)
    _in_process_refusal = None
    if not _chat_parts[1]:
        _in_process_refusal = "At least one non-system message is required."
    else:
        _in_process_refusal = _anthropic_chat_sampling_refusal(payload, _chat_req_pre.messages)
    # Chat's image checks for a non-GGUF target; b64s stays what a GGUF target validates.
    _anthropic_image_preflight = None
    if _anthropic_has_image:
        _anthropic_image_preflight = {
            **_chat_image_preflight(_chat_req_pre, _chat_parts[2]),
            "b64s": _anthropic_image_b64s,
        }
    # require_vision rejects a swap to a text-only target before it runs, so an
    # image request can't evict the resident vision model only to hit the vision
    # guard (_normalize_anthropic_openai_images) below after the load.
    await _maybe_auto_switch_model(
        _switch_model_for_payload(payload),
        request,
        current_subject,
        require_vision = _anthropic_top_level_image,
        rejection_prefix = _anthropic_image_prefix,
        # The image normalization below can still 400 after this switch, so defer the claim:
        # the middleware claims on a 2xx, so a rejected request never strands a preview-owned
        # model.
        claim_resident = False,
        gguf_only = _in_process_refusal is not None,
        gguf_only_reason = _in_process_refusal,
        image_preflight = _anthropic_image_preflight,
    )
    llama_backend = get_llama_cpp_backend()
    if not llama_backend.is_loaded and _in_process_model_resident():
        if _in_process_refusal is not None:
            raise HTTPException(
                status_code = 400,
                detail = anthropic_error_body(
                    _in_process_refusal, status = 400, err_type = "invalid_request_error"
                ),
            )
        # An image anywhere keeps the llama-server route off its server-tool loop too.
        return await _anthropic_in_process_messages(
            payload,
            request,
            current_subject,
            server_tools = [] if _anthropic_has_image else selected_server_tools,
            website_policy = website_policy,
        )
    if not llama_backend.is_loaded:
        _status, _detail = await _no_model_loaded_error(
            "No GGUF model loaded. Load a GGUF model first.",
            _switch_model_for_payload(payload),
            request,
            status = 503,
        )
        raise HTTPException(status_code = _status, detail = _detail)

    # Repo id after an auto-switch, else a clean public id; never a local .gguf path or raw payload path.
    model_name = _llama_public_model_id(llama_backend, payload.model)
    message_id = f"msg_{uuid.uuid4().hex[:24]}"

    if _anthropic_top_level_image and not llama_backend.is_vision:
        raise HTTPException(
            status_code = 400,
            detail = f"{_anthropic_image_prefix}"
            "Image provided but current GGUF model does not support vision.",
        )

    # ── Translate Anthropic → OpenAI ──────────────────────────
    openai_messages = anthropic_messages_to_openai(
        [m.model_dump() for m in payload.messages],
        payload.system,
        preserve_thinking = _anthropic_preserve_thinking(llama_backend, payload),
        tool_result_images = llama_backend.is_vision,
    )
    # Strip synthetic tool history or fake calls reach llama-server; name results before the sanitizer.
    openai_messages = _named_anthropic_tool_results(openai_messages)
    _anthropic_replayed_image_parts: list = []
    openai_messages = await _promote_mcp_history_images_async(
        openai_messages,
        vision = llama_backend.is_vision,
        promoted_out = _anthropic_replayed_image_parts,
    )

    openai_messages = _sanitize_anthropic_openai_messages(openai_messages, llama_backend)

    # Promoted parts count too, or a replay-only request re-decodes PNGs on the shared loop.
    if _anthropic_has_image or _anthropic_replayed_image_parts:
        _has_image = await asyncio.to_thread(
            _normalize_anthropic_openai_images,
            openai_messages,
            llama_backend.is_vision,
        )
    else:
        _has_image = _normalize_anthropic_openai_images(
            openai_messages,
            llama_backend.is_vision,
        )

    # Omitted (None) fields get model recommendations; UNSLOTH_SAMPLING_* pins win over client values.
    from utils.inference.inference_config import resolve_effective_sampling

    _anthropic_model_id = getattr(llama_backend, "model_identifier", None) or model_name
    _anthropic_sampling = resolve_effective_sampling(
        _anthropic_model_id,
        {
            "temperature": payload.temperature,
            "top_p": payload.top_p,
            "top_k": payload.top_k,
            "min_p": payload.min_p,
            "repetition_penalty": payload.repetition_penalty,
            "presence_penalty": payload.presence_penalty,
        },
        thinking = _sampling_thinking_mode(llama_backend, payload),
    )
    temperature = _anthropic_sampling["temperature"]
    top_p = _anthropic_sampling["top_p"]
    top_k = _anthropic_sampling["top_k"]
    min_p = _anthropic_sampling["min_p"]
    repetition_penalty = _anthropic_sampling["repetition_penalty"]
    presence_penalty = _anthropic_sampling["presence_penalty"]
    stop = payload.stop_sequences or None

    # Unset or unrecognized tool_choice falls back to "auto" after translation to OpenAI format.
    openai_tool_choice = anthropic_tool_choice_to_openai(payload.tool_choice)
    if openai_tool_choice is None:
        openai_tool_choice = "auto"

    cancel_event = threading.Event()

    # ── Tool routing ──────────────────────────────────────────
    # Tool routing: enable_tools -> server-side built-ins; tools only -> client passthrough; else plain.
    # Server tools reject caller attachments but accept replayed images (check original blocks).
    openai_client_tools = _anthropic_client_tools_for_turn(
        [
            tool
            for tool in anthropic_tools_to_openai(payload.tools or [])
            if tool.get("function", {}).get("name") not in requested_studio_tools
        ],
        openai_tool_choice,
        openai_messages,
    )

    # Explicit False wins: server-tool mode needs tools enabled (--disable-tools, enable_tools=false).
    selected_server_tools = [
        tool
        for tool in selected_server_tools
        if llama_backend.is_vision or tool["function"]["name"] != "view_image"
    ]
    server_tools = (
        bool(selected_server_tools)
        and llama_backend.supports_tools
        and not _anthropic_has_image
        and not _schema_disables_server_tools
    )
    # Short-circuit: a backend whose supports_tools raises must not 500 a plain no-tools turn.
    client_tools = (
        not server_tools
        and len(openai_client_tools) > 0
        and getattr(llama_backend, "supports_tool_passthrough", llama_backend.supports_tools)
    )

    _guard_anthropic_client_tool_catalog(
        openai_client_tools, openai_tool_choice, server_tools, llama_backend
    )

    # Tool requests that cannot run tools (image, tool-less template, tool_choice none) keep the schema.
    response_format = _response_format
    if (
        response_format is not None
        and (server_tools or client_tools)
        and openai_tool_choice != "none"
    ):
        logger.warning("Ignoring Anthropic output format: callable tools cannot run under a schema")
        response_format = None

    # The client-tool passthrough forwards the caller's request verbatim; other branches compose.
    if not client_tools:
        openai_messages = _prepend_current_date_to_messages(
            openai_messages,
            request,
            include_api_key = server_tools,
        )

    # disable_parallel_tool_use caps the reply at one tool_use block; computed here for both paths.
    _disable_parallel = bool(
        isinstance(payload.tool_choice, dict)
        and payload.tool_choice.get("disable_parallel_tool_use")
    )

    monitor_id = None
    monitor_context_length = _monitor_context_length()
    request_state = getattr(request, "state", None)
    if not getattr(request_state, "skip_api_monitor", False):
        request_url = getattr(request, "url", None)
        monitor_id = api_monitor.start(
            endpoint = getattr(request_url, "path", "/v1/messages"),
            method = getattr(request, "method", "POST"),
            via_api_key = _request_used_api_key(request),
            model = model_name,
            prompt = _monitor_prompt_from_messages(openai_messages),
            context_length = monitor_context_length,
            subject = current_subject,
        )

    async def _monitored_anthropic(coro):
        try:
            response = await coro
        except _NonStreamingRequestCancelled as exc:
            api_monitor.finish(monitor_id, "cancelled")
            raise _anthropic_admission_http_exception(exc, status_code = 499)
        except asyncio.CancelledError:
            cancel_event.set()
            api_monitor.finish(monitor_id, "cancelled")
            raise
        except Exception as exc:
            api_monitor.fail(monitor_id, _friendly_error(exc))
            raise
        return _monitor_anthropic_response(
            response,
            monitor_id,
            monitor_context_length,
            cancel_event,
        )

    async def _tracked_anthropic_non_streaming(coro):
        """Registers the run with the swap gate so a swap cannot tear down llama-server mid-request."""
        _tracker = _TrackedCancel(cancel_event, model = model_name, kind = "messages")
        _tracker.__enter__()
        try:
            return await _monitored_anthropic(coro)
        finally:
            # _monitored_anthropic's bookkeeping can throw; a leaked entry 409s later swaps.
            _tracker.__exit__(None, None, None)

    # ── Admission control ─────────────────────────────────────
    # Admission: FIFO queue per base_url shared with /v1/chat/completions; streaming holds the slot
    # while the body runs, non-stream across the awaited generation.
    _anthropic_admission_mode = "anthropic_stream" if payload.stream else "anthropic_nonstream"

    async def _admitted_anthropic_stream(
        orig_body,
        reservation,
        admission_config,
        stream_lease,
        prior_cleanup = None,
    ):
        lease = stream_lease
        stream_cancelled = False
        body_started = False
        wait_started_at = None
        try:
            if lease is None:
                wait_started_at = time.monotonic()
                _llama_admission_log(
                    "queued",
                    reservation,
                    request = request,
                    mode = _anthropic_admission_mode,
                )
                async for wait_item in _openai_admission_wait_stream_chunks(
                    reservation,
                    admission_config,
                    request = request,
                    cancel_event = cancel_event,
                ):
                    if isinstance(wait_item, str):
                        yield wait_item
                        continue
                    lease = wait_item
                    break
                _llama_admission_log(
                    "granted-after-wait",
                    reservation,
                    request = request,
                    mode = _anthropic_admission_mode,
                    wait_started_at = wait_started_at,
                )
            if lease is None:
                return
            body_started = True
            async for chunk in orig_body:
                yield chunk
        except asyncio.CancelledError:
            # Must reach the monitored generator as CancelledError, not GeneratorExit, to finalize the monitor.
            stream_cancelled = True
            raise
        except LlamaAdmissionTimeout as exc:
            api_monitor.fail(monitor_id, str(exc))
            _llama_admission_log(
                "timeout",
                reservation,
                request = request,
                mode = _anthropic_admission_mode,
                wait_started_at = wait_started_at,
                level = "warning",
            )
            yield build_anthropic_sse_event(
                "error",
                anthropic_error_body(str(exc), status = 503),
            )
        except LlamaAdmissionCancelled:
            _llama_admission_log(
                "cancelled-before-upstream",
                reservation,
                request = request,
                mode = _anthropic_admission_mode,
                wait_started_at = wait_started_at,
            )
            return
        finally:
            # Closing can raise, and a lost slot never comes back: keep the release in its own finally.
            try:
                if body_started:
                    await _close_openai_admitted_stream_iterator(
                        orig_body,
                        cancelled = stream_cancelled,
                    )
                else:
                    # Gave up while queued: nothing downstream finalizes the entry or exits the tracker.
                    api_monitor.finish(monitor_id, "cancelled")
                    await _release_unstarted_anthropic_stream(orig_body, prior_cleanup)
            finally:
                if lease is not None:
                    lease.release()
                else:
                    reservation.cancel()

    # Like _gguf_admission_hold: the tool loop re-costs its reservation from this each round.
    _anthropic_admission_hold: dict = {"reservation": None}

    def _anthropic_admission_body(conversation, *, tool_loop = False):
        template_kwargs = _anthropic_count_template_kwargs(llama_backend, _reasoning_args)
        if client_tools or response_format is not None:
            # As the passthrough builds it: generation sends no parallel_tool_calls here.
            return _build_passthrough_payload(
                conversation,
                openai_tools,
                temperature,
                top_p,
                top_k,
                payload.max_tokens,
                payload.stream,
                tool_choice = openai_tool_choice,
                response_format = response_format,
                chat_template_kwargs = template_kwargs,
                backend_ctx = llama_backend.context_length,
                markup = getattr(llama_backend, "markup_profile", None),
            )
        return {
            "messages": conversation,
            "tools": openai_tools if tool_loop else None,
            "chat_template_kwargs": template_kwargs,
        }

    def _anthropic_recost(conversation) -> None:
        body = _anthropic_admission_body(conversation, tool_loop = True)
        _openai_llama_admission_recost(
            _anthropic_admission_hold["reservation"],
            body["messages"],
            request = request,
            llama_backend = llama_backend,
            payload = payload,
            output_tokens = payload.max_tokens,
            injected_tools = body.get("tools"),
            cancel_event = cancel_event,
            count_prepared_prompt = True,
            prepared_body = body,
        )

    async def _admitted_anthropic(coro, *, tool_loop: bool = False):
        try:
            body = _anthropic_admission_body(openai_messages, tool_loop = tool_loop)
            reservation, admission_config = await _reserve_counted_gguf_chat(
                request = request,
                llama_backend = llama_backend,
                payload = payload,
                tool_loop = tool_loop,
                injected_tools = body.get("tools"),
                messages = body["messages"],
                prepared_body = body,
            )
            if tool_loop:
                _anthropic_admission_hold["reservation"] = reservation
        except LlamaAdmissionQueueFull as exc:
            coro.close()
            api_monitor.fail(monitor_id, str(exc))
            _llama_admission_log(
                "queue-full",
                snapshot = getattr(exc, "snapshot", None),
                request = request,
                mode = _anthropic_admission_mode,
                level = "warning",
            )
            raise _anthropic_admission_http_exception(exc, status_code = 429)
        except BaseException:
            # Reserving never awaited the generation, so close its coroutine rather than leave it un-awaited.
            coro.close()
            raise

        if payload.stream:
            stream_lease = reservation.lease_nowait()
            # The upstream generation is deferred to body iteration, so the slot is held only while tokens flow.
            try:
                # Token counting can raise with the slot taken; cancel() releases a lease or drops the waiter.
                monitored = await _monitored_anthropic(coro)
            except BaseException:
                reservation.cancel()
                raise
            orig_body = getattr(monitored, "body_iterator", None)
            if orig_body is None:
                reservation.cancel()
                return monitored

            # Chain to the response's pre-start hook rather than clobbering it (passthrough uses it).
            prior_cleanup = getattr(monitored, "_unstarted_cleanup", None)

            async def _unstarted_cleanup() -> None:
                # The body never ran, so nothing else closes out the monitor entry.
                api_monitor.finish(monitor_id, "cancelled")
                try:
                    await _release_unstarted_anthropic_stream(orig_body, prior_cleanup)
                finally:
                    # A BaseException here is swallowed upstream, so release inside the finally.
                    reservation.cancel()

            monitored.body_iterator = _admitted_anthropic_stream(
                orig_body, reservation, admission_config, stream_lease, prior_cleanup
            )
            monitored._unstarted_cleanup = _unstarted_cleanup
            return monitored

        lease = None
        try:
            lease = await _wait_for_openai_admission_non_streaming(
                reservation,
                admission_config,
                request = request,
                cancel_event = cancel_event,
            )
            # Registered only once admitted: a queued request does not hold llama-server.
            monitored = await _tracked_anthropic_non_streaming(coro)
            return monitored
        except LlamaAdmissionTimeout as exc:
            coro.close()
            api_monitor.fail(monitor_id, str(exc))
            raise _anthropic_admission_http_exception(exc, status_code = 503)
        except LlamaAdmissionCancelled as exc:
            coro.close()
            api_monitor.finish(monitor_id, "cancelled")
            raise _anthropic_admission_http_exception(exc, status_code = 499)
        except BaseException:
            # Cancelled while queued: the unawaited generation coroutine is closed, not leaked.
            if lease is None:
                coro.close()
                api_monitor.finish(monitor_id, "cancelled")
            raise
        finally:
            if lease is not None:
                lease.release()
            else:
                reservation.cancel()

    _reasoning_args = await _resolved_anthropic_reasoning_args_async(
        llama_backend, payload, openai_messages
    )

    # ── Client-side pass-through path ─────────────────────────
    if client_tools or response_format is not None:
        openai_tools = openai_client_tools if client_tools else []

        if payload.stream:
            return await _admitted_anthropic(
                _anthropic_passthrough_stream(
                    request,
                    cancel_event,
                    llama_backend,
                    openai_messages,
                    openai_tools,
                    temperature,
                    top_p,
                    top_k,
                    payload.max_tokens,
                    message_id,
                    model_name,
                    stop = stop,
                    min_p = min_p,
                    repetition_penalty = repetition_penalty,
                    presence_penalty = presence_penalty,
                    seed = payload.seed,
                    tool_choice = openai_tool_choice,
                    session_id = payload.session_id,
                    cancel_id = payload.cancel_id,
                    disable_parallel_tool_use = _disable_parallel,
                    auto_heal_tool_calls = payload.auto_heal_tool_calls,
                    response_format = response_format,
                    parse_think = _think_parsing_expected(llama_backend, payload),
                    context_overflow = _overflow_truncation_policy(payload),
                    **_reasoning_args,
                )
            )
        return await _admitted_anthropic(
            _anthropic_passthrough_non_streaming(
                llama_backend,
                openai_messages,
                openai_tools,
                temperature,
                top_p,
                top_k,
                payload.max_tokens,
                message_id,
                model_name,
                stop = stop,
                min_p = min_p,
                repetition_penalty = repetition_penalty,
                presence_penalty = presence_penalty,
                seed = payload.seed,
                tool_choice = openai_tool_choice,
                disable_parallel_tool_use = _disable_parallel,
                auto_heal_tool_calls = payload.auto_heal_tool_calls,
                nudge_tool_calls = payload.nudge_tool_calls,
                request = request,
                cancel_event = cancel_event,
                response_format = response_format,
                parse_think = _think_parsing_expected(llama_backend, payload),
                context_overflow = _overflow_truncation_policy(payload),
                **_reasoning_args,
            )
        )

    # Counts <think> wraps the generator created, to tell genuine traces from literal markup.
    _think_prov: dict = {"wrapped": 0}

    if server_tools:
        from core.inference.tool_loop_controller import restore_replayed_tool_results

        # As the tool loop does, so the opening usage count prices what it sends.
        openai_messages = await asyncio.to_thread(restore_replayed_tool_results, openai_messages)
        from core.inference.tools import apply_full_access_tool_descriptions

        # Ask/auto or an omitted mode needing a gate are rejected before auto-switch, so no model is evicted.
        openai_tools = selected_server_tools
        # This path builds its own selection, so the Full access swap must be repeated.
        _full_access = bool(getattr(payload, "bypass_permissions", False))
        if _full_access:
            openai_tools = apply_full_access_tool_descriptions(openai_tools)
        elif sys.platform == "win32":
            from core.inference.tools import apply_terminal_profile_for_request
            openai_tools = await asyncio.to_thread(
                apply_terminal_profile_for_request,
                openai_tools,
                getattr(payload, "sandbox_level", None),
            )

        server_tool_choice = _anthropic_server_tool_choice(openai_tool_choice)
        message = _anthropic_server_tool_refusal(payload, server_tool_choice, openai_tools)
        if message:
            api_monitor.fail(monitor_id, message)
            raise HTTPException(
                status_code = 400,
                detail = anthropic_error_body(
                    message,
                    status = 400,
                    err_type = "invalid_request_error",
                ),
            )

        # Build tool-use system prompt nudge (same logic as /chat/completions)
        _nudge = _build_tool_action_nudge(
            tools = openai_tools,
            model_name = model_name,
            full_access = _full_access,
        )

        if _nudge:
            # Inject into system prompt
            if openai_messages and openai_messages[0].get("role") == "system":
                openai_messages[0]["content"] = (
                    openai_messages[0]["content"].rstrip() + "\n\n" + _nudge
                )
            else:
                openai_messages.insert(0, {"role": "system", "content": _nudge})

        # Strip stale tool-call XML via the protected display helper (think rehearsal and [TOOL_CALLS]
        # prose survive), gated on enabled tool names so documented inactive examples are kept.
        _anthropic_history_gate = _display_tool_name_gate(openai_tools)
        for _msg in openai_messages:
            if _msg.get("role") == "assistant" and isinstance(_msg.get("content"), str):
                _msg["content"] = _strip_tool_xml_for_display(
                    _msg["content"],
                    auto_heal_tool_calls = True,
                    enabled_tool_names = _anthropic_history_gate,
                ).strip()

        def _run_tool_gen():
            return llama_backend.generate_chat_completion_with_tools(
                reasoning_provenance = _think_prov,
                messages = openai_messages,
                replayed_image_parts = tuple(_anthropic_replayed_image_parts),
                tools = openai_tools,
                temperature = temperature,
                top_p = top_p,
                top_k = top_k,
                min_p = min_p,
                repetition_penalty = repetition_penalty,
                presence_penalty = presence_penalty,
                max_tokens = payload.max_tokens,
                stop = stop,
                seed = payload.seed,
                cancel_event = cancel_event,
                max_tool_iterations = 25,
                on_conversation_grew = _anthropic_recost,
                auto_heal_tool_calls = True,
                nudge_tool_calls = payload.nudge_tool_calls,
                tool_choice = server_tool_choice,
                tool_call_timeout = 300,
                session_id = payload.session_id,
                thread_id = payload.thread_id,
                # Anthropic passthrough has no rag_scope field (RAG is local-only).
                rag_scope = getattr(payload, "rag_scope", None),
                disable_parallel_tool_use = _disable_parallel,
                bypass_permissions = bool(payload.bypass_permissions),
                permission_mode = getattr(payload, "permission_mode", None),
                sandbox_level = getattr(payload, "sandbox_level", None),
                promote_reasoning_only = False,
                perf_callback = _monitor_perf_callback(
                    monitor_id,
                    llama_backend.context_length,
                ),
                replay_preserve_thinking = not _anthropic_history_has_thinking(payload),
                website_policy = website_policy,
                **_reasoning_args,
            )

        if payload.stream:
            return await _admitted_anthropic(
                _anthropic_tool_stream(
                    request,
                    cancel_event,
                    _run_tool_gen,
                    message_id,
                    model_name,
                    llama_backend = llama_backend,
                    openai_messages = openai_messages,
                    openai_tools = openai_tools,
                    disable_parallel_tool_use = _disable_parallel,
                    parse_think = _think_parsing_expected(llama_backend, payload),
                    think_provenance = _think_prov,
                    count_template_kwargs = _anthropic_count_template_kwargs(
                        llama_backend, _reasoning_args
                    ),
                ),
                # Same server-side loop the chat route runs, up to 25 rounds on one lease.
                tool_loop = True,
            )
        return await _admitted_anthropic(
            _anthropic_tool_non_streaming(
                request,
                _run_tool_gen,
                message_id,
                model_name,
                disable_parallel_tool_use = _disable_parallel,
                openai_tools = openai_tools,
                parse_think = _think_parsing_expected(llama_backend, payload),
                think_provenance = _think_prov,
                cancel_event = cancel_event,
            ),
            tool_loop = True,
        )

    # ── No-tool path ──────────────────────────────────────────
    def _run_plain_gen():
        return llama_backend.generate_chat_completion(
            reasoning_provenance = _think_prov,
            messages = openai_messages,
            temperature = temperature,
            top_p = top_p,
            top_k = top_k,
            min_p = min_p,
            repetition_penalty = repetition_penalty,
            presence_penalty = presence_penalty,
            max_tokens = payload.max_tokens,
            stop = stop,
            seed = payload.seed,
            cancel_event = cancel_event,
            promote_reasoning_only = False,
            perf_callback = _monitor_perf_callback(
                monitor_id,
                llama_backend.context_length,
            ),
            replay_preserve_thinking = not _anthropic_history_has_thinking(payload),
            **_reasoning_args,
        )

    if payload.stream:
        return await _admitted_anthropic(
            _anthropic_plain_stream(
                request,
                cancel_event,
                _run_plain_gen,
                message_id,
                model_name,
                llama_backend = llama_backend,
                openai_messages = openai_messages,
                parse_think = _think_parsing_expected(llama_backend, payload),
                think_provenance = _think_prov,
                count_template_kwargs = _anthropic_count_template_kwargs(
                    llama_backend, _reasoning_args
                ),
            )
        )
    return await _admitted_anthropic(
        _anthropic_plain_non_streaming(
            request,
            _run_plain_gen,
            message_id,
            model_name,
            parse_think = _think_parsing_expected(llama_backend, payload),
            think_provenance = _think_prov,
            cancel_event = cancel_event,
        )
    )


class _AnthropicToolEventRules:
    """What the server-tool stream does with each tool-loop event, whatever produced it."""

    def __init__(self, emitter, openai_tools, disable_parallel_tool_use, think_provenance) -> None:
        self._emitter = emitter
        # Gate the display strip on the declared tools: an inactive NAME[ARGS]{...} in a final
        # answer is prose and must survive in the delivered text.
        self._display_names = _display_tool_name_gate(openai_tools)
        self._disable_parallel_tool_use = disable_parallel_tool_use
        self._finish_reason = None
        # Response ends on a pending tool_use block rather than final text; a server tool
        # that keeps generating flips this back to False.
        self._ends_on_tool_use = False
        self._tool_blocks_emitted = 0
        self._drop_until_tool_end = False
        self._span_guard = _ReasoningSpanGuard(think_provenance)
        # Last drop-branch keepalive, seeded to stream start so a chatty tool busy past the
        # stall window still gets one though its events are dropped.
        self._last_drop_keepalive = time.monotonic()

    def feed(self, event: dict) -> list:
        etype = event.get("type")
        if etype == "heartbeat":
            # Tool-wrapper heartbeat -> SSE keepalive, checked BEFORE the drop skip:
            # a dropped tool still runs and suppresses the stall keepalive.
            return [_OPENAI_PASSTHROUGH_SSE_KEEPALIVE]
        if etype in ("tool_output", "tool_args"):
            # No Messages equivalent, but they suppress the stall keepalive: send a rate-limited
            # one instead of going silent past the ~100s proxy cap.
            _now = time.monotonic()
            if _now - self._last_drop_keepalive >= _LOCAL_TOOL_STREAM_STALL_KEEPALIVE_S:
                self._last_drop_keepalive = _now
                return [_OPENAI_PASSTHROUGH_SSE_KEEPALIVE]
            return []
        if self._drop_until_tool_end:
            # Skip through the dropped call's tool_end.
            if etype == "tool_end":
                self._drop_until_tool_end = False
            return []
        if etype == "metadata":
            _fr = event.get("finish_reason")
            if _fr is not None:
                self._finish_reason = _fr
        # Strip leaked tool XML first; the protected helper keeps <think> rehearsal and balanced
        # [TOOL_CALLS] prose, which a raw sub corrupts.
        if etype == "content":
            event = dict(event)
            event["text"] = self._span_guard.strip(
                event["text"],
                auto_heal_tool_calls = True,
                enabled_tool_names = self._display_names,
            )
        # Parallel cap by state, not id: ids may be empty.
        if etype == "tool_start":
            if self._disable_parallel_tool_use and self._tool_blocks_emitted >= 1:
                self._drop_until_tool_end = True
                return []
            self._ends_on_tool_use = True
        elif etype == "tool_end":
            self._tool_blocks_emitted += 1
            self._span_guard.tool_end()
            # Unsloth ran the tool server-side, so the response no longer ends on a pending
            # client action; otherwise stop_reason "tool_use" tells the client to run it again.
            self._ends_on_tool_use = False
        elif etype == "content" and event.get("text"):
            self._ends_on_tool_use = False
        return self._emitter.feed(event)

    def finish(self) -> list:
        stop_reason = openai_finish_to_anthropic_stop(
            self._finish_reason, had_tool_calls = self._ends_on_tool_use
        )
        return self._emitter.finish(stop_reason = stop_reason, stop_sequence = None)


async def _anthropic_tool_stream(
    request,
    cancel_event,
    run_gen,
    message_id,
    model_name,
    llama_backend = None,
    openai_messages = None,
    openai_tools = None,
    disable_parallel_tool_use = False,
    parse_think = True,
    think_provenance = None,
    count_template_kwargs = None,
):
    """Streaming response for the tool-calling path."""
    _sentinel = object()

    # Prompt-token count for message_start.usage.input_tokens. count_chat_tokens
    # makes blocking HTTP calls to llama-server, so run it off the event loop.
    # Pass the tools so tool-schema tokens are counted (the generator renders
    # them too), matching the non-stream / count_tokens / passthrough paths.
    input_tokens = 0
    if llama_backend is not None and openai_messages is not None:
        input_tokens = await asyncio.to_thread(
            lambda: llama_backend.count_chat_tokens(
                openai_messages,
                None,
                openai_tools,
                chat_template_kwargs = count_template_kwargs,
            )
        )

    async def _stream():
        from core.inference.llama_keepwarm import mark_response_failed

        # Without a tracker entry a non-forced /unload tears the server down mid-response. Entered in the
        # body so an unstarted response leaves nothing behind.
        _tracker = _TrackedCancel(cancel_event, model = model_name, kind = "messages")
        _tracker.__enter__()
        try:
            emitter = AnthropicStreamEmitter(
                parse_think = parse_think, think_provenance = think_provenance
            )
            for line in emitter.start(message_id, model_name, input_tokens = input_tokens):
                yield line
            rules = _AnthropicToolEventRules(
                emitter, openai_tools, disable_parallel_tool_use, think_provenance
            )

            # The respawn refit records the refusal from the worker thread, so open the slot out here first.
            context_refusal.open_slot()
            gen = run_gen()
            gen_step = ThreadStepper(gen).next
            _next_task = None
            # The in-loop poll fires only between events, so a mid-prefill disconnect needs a watcher.
            disconnect_watcher = asyncio.create_task(
                _await_disconnect_then_cancel(request, cancel_event)
            )
            try:
                while True:
                    if cancel_event.is_set() or await request.is_disconnected():
                        cancel_event.set()
                        # Flag failed so the middleware won't claim a preview-owned model for this stream.
                        mark_response_failed(getattr(request, "scope", None))
                        return
                    # Stall keepalive: silent backend segments must not idle the SSE stream past proxy timeouts.
                    _next_task = asyncio.create_task(gen_step(_sentinel))
                    while True:
                        _done_tasks, _ = await asyncio.wait(
                            {_next_task},
                            timeout = _LOCAL_TOOL_STREAM_STALL_KEEPALIVE_S,
                        )
                        if _done_tasks:
                            break
                        yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                    event = _next_task.result()
                    # Done; drop the reference so the finally-block drain no-ops.
                    _next_task = None
                    if event is _sentinel:
                        break
                    for line in rules.feed(event):
                        yield line
            except Exception as e:
                logger.error("anthropic_messages stream error: %s", e)
                # force=True so an unclassified failure emits an SSE error, not a clean-looking message_stop.
                _error_event = _anthropic_stream_error_event(e, force = True)
                if _error_event is not None:
                    yield _error_event
                    return
            finally:
                await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
                # Drain the next(gen) worker before closing; closing first races into 'already executing'.
                await _drain_pending_worker(_next_task, cancel_event)
                if gen is not None:
                    try:
                        await asyncio.to_thread(gen.close)
                    except (RuntimeError, ValueError):
                        pass

            for line in rules.finish():
                yield line
        finally:
            _tracker.__exit__(None, None, None)

    return _sse_streaming_response(_stream())


async def _anthropic_plain_stream(
    request,
    cancel_event,
    run_gen,
    message_id,
    model_name,
    llama_backend = None,
    openai_messages = None,
    parse_think = True,
    think_provenance = None,
    count_template_kwargs = None,
):
    """Streaming response for the no-tool path."""
    _sentinel = object()

    # count_chat_tokens makes blocking HTTP calls to llama-server, so it runs off the event loop.
    input_tokens = 0
    if llama_backend is not None and openai_messages is not None:
        input_tokens = await asyncio.to_thread(
            lambda: llama_backend.count_chat_tokens(
                openai_messages, chat_template_kwargs = count_template_kwargs
            )
        )

    async def _stream():
        from core.inference.llama_keepwarm import mark_response_failed

        # Tracked so a non-forced /unload does not tear down llama-server mid-response.
        _tracker = _TrackedCancel(cancel_event, model = model_name, kind = "messages")
        _tracker.__enter__()
        try:
            emitter = AnthropicStreamEmitter(
                parse_think = parse_think, think_provenance = think_provenance
            )
            for line in emitter.start(message_id, model_name, input_tokens = input_tokens):
                yield line

            captured_finish_reason = None

            gen = run_gen()
            gen_step = ThreadStepper(gen).next
            _next_task = None
            # Watcher cancels on disconnect since the in-loop poll only runs between chunks, not mid-prefill.
            disconnect_watcher = asyncio.create_task(
                _await_disconnect_then_cancel(request, cancel_event)
            )
            try:
                while True:
                    if cancel_event.is_set() or await request.is_disconnected():
                        cancel_event.set()
                        # Mark cancelled streams failed so the middleware does not claim a preview-owned model.
                        mark_response_failed(getattr(request, "scope", None))
                        return
                    # Stall keepalive each window while next(gen) runs in a worker.
                    _next_task = asyncio.create_task(gen_step(_sentinel))
                    while True:
                        _done_tasks, _ = await asyncio.wait(
                            {_next_task},
                            timeout = _LOCAL_TOOL_STREAM_STALL_KEEPALIVE_S,
                        )
                        if _done_tasks:
                            break
                        yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                    cumulative = _next_task.result()
                    # Done; drop the reference so the finally-block drain no-ops.
                    _next_task = None
                    if cumulative is _sentinel:
                        break
                    if isinstance(cumulative, dict):
                        if cumulative.get("type") == "metadata":
                            _fr = cumulative.get("finish_reason")
                            if _fr is not None:
                                captured_finish_reason = _fr
                            for line in emitter.feed(cumulative):
                                yield line
                        continue
                    # Plain generator yields cumulative text strings
                    for line in emitter.feed({"type": "content", "text": cumulative}):
                        yield line
            except Exception as e:
                logger.error("anthropic_messages stream error: %s", e)
                # force=True so an unclassified mid-stream failure yields an SSE error, not a clean message_stop.
                _error_event = _anthropic_stream_error_event(e, force = True)
                if _error_event is not None:
                    yield _error_event
                    return
            finally:
                await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
                # Drain a still-running next(gen) worker before closing gen, or closing races 'already executing'.
                await _drain_pending_worker(_next_task, cancel_event)
                if gen is not None:
                    try:
                        await asyncio.to_thread(gen.close)
                    except (RuntimeError, ValueError):
                        pass

            stop_reason = openai_finish_to_anthropic_stop(
                captured_finish_reason, had_tool_calls = False
            )
            for line in emitter.finish(stop_reason = stop_reason, stop_sequence = None):
                yield line
        finally:
            _tracker.__exit__(None, None, None)

    return _sse_streaming_response(_stream())


def _anthropic_map_generation_error(e: Exception) -> HTTPException:
    """Map an upstream 4xx / context-overflow generation error to a clean
    Anthropic 400 invalid_request_error. Genuine 5xx errors stay 500."""
    if _classify_llama_generation_error(e) is not None:
        return HTTPException(
            status_code = 400,
            detail = anthropic_error_body(
                _friendly_error(e),
                status = 400,
                err_type = "invalid_request_error",
            ),
        )
    return HTTPException(status_code = 500, detail = _friendly_error(e))


_WRAPPED_SO_FAR = "_wrapped_so_far"


def _collect_anthropic_events(run_gen, think_provenance = None) -> list:
    """Drains generator; upstream 4xx or context overflow becomes Anthropic 400; stamps think_provenance."""

    def _drain():
        for event in run_gen():
            if (
                think_provenance is not None
                and isinstance(event, dict)
                and event.get("type") == "content"
            ):
                # Content events are freshly built per yield, so stamping them
                # cannot leak into any shared event constant.
                event[_WRAPPED_SO_FAR] = int(think_provenance.get("wrapped", 0))
            yield event

    try:
        return list(_drain())
    except HTTPException:
        raise
    except Exception as e:
        raise _anthropic_map_generation_error(e)


def _anthropic_message_json_response(
    message_id, model_name, content_blocks, stop_reason, usage
) -> Response:
    """Assemble the terminal Anthropic non-streaming JSON response shared by the
    tool / plain / passthrough paths."""
    input_tokens, cache_read = anthropic_input_split(usage)
    return _model_json_response(
        AnthropicMessagesResponse(
            id = message_id,
            model = model_name,
            content = content_blocks,
            stop_reason = stop_reason,
            usage = AnthropicUsage(
                input_tokens = input_tokens,
                cache_read_input_tokens = cache_read,
                output_tokens = usage.get("completion_tokens", 0),
            ),
        )
    )


def _split_think_segments(text: str, wrap: Optional[dict] = None) -> list:
    """Only one leading think block is parsed; later tags are literal, unclosed one runs to end of string."""
    stripped = text.lstrip()
    if not stripped.startswith("<think>"):
        return [("text", text)] if text else []
    lead_ws = text[: len(text) - len(stripped)]
    rest = stripped[len("<think>") :]
    if wrap is not None:
        # The recorded reasoning length means a literal '</think>' inside the trace never ends it early.
        n = int(wrap.get("len", 0))
        thinking, after = rest[:n], rest[n:]
        if after.startswith("</think>"):
            after = after[len("</think>") :]
    else:
        close = rest.find("</think>")
        if close == -1:
            thinking, after = rest, ""
        else:
            thinking, after = rest[:close], rest[close + len("</think>") :]
    segments: list = []
    if lead_ws:
        segments.append(("text", lead_ws))
    if thinking:
        segments.append(("thinking", thinking))
    if after:
        segments.append(("text", after))
    return segments


def _think_markup_to_blocks(text: str, wrap: Optional[dict] = None) -> list:
    """Expand one text run into ordered thinking / text response blocks."""
    blocks: list = []
    for kind, seg in _split_think_segments(text, wrap):
        if kind == "thinking":
            if seg.strip():
                blocks.append(AnthropicResponseThinkingBlock(thinking = seg))
        elif seg.strip():
            # Whitespace only decides emptiness; delivered text stays verbatim.
            blocks.append(AnthropicResponseTextBlock(text = seg))
    return blocks


def _anthropic_tool_response_from_events(
    events,
    message_id,
    model_name,
    disable_parallel_tool_use = False,
    openai_tools = None,
    parse_think = True,
    think_provenance = None,
):
    """Deltas merge into trailing text; tool_end or empty status resets the cumulative cursor."""
    content_blocks: list = []
    tool_blocks_by_id: dict[
        str, Union[AnthropicResponseToolUseBlock, AnthropicResponseServerToolUseBlock]
    ] = {}
    usage = {}
    prev_text = ""
    captured_finish_reason = None
    # Gate the display strip on declared tools: an inactive NAME[ARGS]{...} in a final answer is prose.
    _display_names = _display_tool_name_gate(openai_tools)
    # Pending client tool_use: cleared by tool_end for server-run tools, or by trailing text.
    ends_on_tool_use = False

    _span_guard = _ReasoningSpanGuard(think_provenance)
    # Key presence means genuine reasoning; the value may be None if only the count was recorded.
    _block_wrap: dict = {}

    for event in events:
        etype = event.get("type", "")
        if etype == "content":
            # Strip leaked tool XML (protected helper keeps think rehearsal and trailing prose).
            clean = _span_guard.strip(
                event["text"],
                auto_heal_tool_calls = True,
                enabled_tool_names = _display_names,
                wrapped_so_far = event.get(_WRAPPED_SO_FAR),
            )
            new = clean[len(prev_text) :]
            prev_text = clean
            if new:
                ends_on_tool_use = False
                if content_blocks and isinstance(content_blocks[-1], AnthropicResponseTextBlock):
                    content_blocks[-1].text += new
                else:
                    content_blocks.append(AnthropicResponseTextBlock(text = new))
                    # The wrap belongs to the block that OPENS this turn's span (a client tool_use can interrupt it).
                    if _span_guard.claimed and new.startswith("<think>"):
                        _block_wrap[len(content_blocks) - 1] = _span_guard.claimed_wrap
        elif etype == "status" and not event.get("text"):
            prev_text = ""
        elif etype == "tool_start":
            tool_call_id = event["tool_call_id"]
            arguments = event.get("arguments", {})
            existing_tool_block = tool_blocks_by_id.get(tool_call_id) if tool_call_id else None
            if existing_tool_block is not None:
                if arguments or not existing_tool_block.input:
                    existing_tool_block.input = arguments
                if event.get("tool_name") and not existing_tool_block.name:
                    existing_tool_block.name = event["tool_name"]
            else:
                block_cls, id_prefix = (
                    (AnthropicResponseServerToolUseBlock, "srvtoolu_")
                    if event["tool_name"] == "web_search"
                    else (AnthropicResponseToolUseBlock, "toolu_")
                )
                tool_block = block_cls(
                    id = anthropic_tool_use_id(tool_call_id, id_prefix),
                    name = event["tool_name"],
                    input = arguments,
                )
                if tool_call_id:
                    tool_blocks_by_id[tool_call_id] = tool_block
                content_blocks.append(tool_block)
            ends_on_tool_use = True
        elif etype == "tool_end":
            prev_text = ""
            _span_guard.tool_end()
            # Text-parsed calls restart at call_0 each loop, so a later call may reuse this id; open a new block.
            search_call = tool_blocks_by_id.pop(event.get("tool_call_id"), None)
            if isinstance(search_call, AnthropicResponseServerToolUseBlock):
                content_blocks.append(
                    AnthropicResponseWebSearchToolResultBlock(
                        tool_use_id = search_call.id,
                        content = web_search_tool_result_content(
                            event.get("result", ""), search_call.input
                        ),
                    )
                )
            # Server-executed: no longer pending a client action (see above).
            ends_on_tool_use = False
        elif etype == "metadata":
            usage = event.get("usage", {})
            _fr = event.get("finish_reason")
            if _fr is not None:
                captured_finish_reason = _fr

    # With provenance use the span guard wrap for that turn, not a re-derived one; else leading-tag rule.
    if parse_think:
        _expanded: list = []
        for _i, block in enumerate(content_blocks):
            if think_provenance is None:
                if isinstance(block, AnthropicResponseTextBlock) and block.text.lstrip().startswith(
                    "<think>"
                ):
                    _expanded.extend(_think_markup_to_blocks(block.text, None))
                    continue
            elif _i in _block_wrap:
                _expanded.extend(_think_markup_to_blocks(block.text, _block_wrap[_i]))
                continue
            _expanded.append(block)
        content_blocks = _expanded

    # disable_parallel_tool_use keeps the first tool_use block and drops later ones.
    if disable_parallel_tool_use:
        _seen_tool_use = False
        _capped: list = []
        for block in content_blocks:
            if isinstance(block, AnthropicResponseToolUseBlock):
                if _seen_tool_use:
                    continue
                _seen_tool_use = True
            _capped.append(block)
        content_blocks = _capped

    # 'tool_use' only if the last tool_start had no following tool_end or trailing text.
    stop_reason = openai_finish_to_anthropic_stop(
        captured_finish_reason, had_tool_calls = ends_on_tool_use
    )

    return _anthropic_message_json_response(
        message_id, model_name, content_blocks, stop_reason, usage
    )


async def _anthropic_tool_non_streaming(
    request,
    run_gen,
    message_id,
    model_name,
    disable_parallel_tool_use = False,
    openai_tools = None,
    parse_think = True,
    think_provenance = None,
    cancel_event = None,
):
    """Generate and reduce a tool response entirely off the event loop."""

    def _drain_and_build():
        return _anthropic_tool_response_from_events(
            _collect_anthropic_events(run_gen, think_provenance),
            message_id,
            model_name,
            disable_parallel_tool_use = disable_parallel_tool_use,
            openai_tools = openai_tools,
            parse_think = parse_think,
            think_provenance = think_provenance,
        )

    disconnect_watcher = asyncio.create_task(_await_disconnect_then_cancel(request, cancel_event))
    try:
        response = await _run_blocking_generation(
            _drain_and_build,
            cancel_event,
            name = "anthropic-tool-nonstream",
            daemon = True,
        )
    finally:
        await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
    # Partial output: unmarked, keepwarm middleware treats it as clean and steals a preview's model.
    if cancel_event is not None:
        _mark_cancelled_json_response_failed(request, cancel_event)
    return response


def _anthropic_plain_response_from_events(
    events,
    message_id,
    model_name,
    parse_think = True,
    think_provenance = None,
):
    """Reduce collected plain events into one non-streaming response."""
    text_parts = []
    usage = {}
    prev_text = ""
    captured_finish_reason = None

    for cumulative in events:
        if isinstance(cumulative, dict):
            if cumulative.get("type") == "metadata":
                usage = cumulative.get("usage", {})
                _fr = cumulative.get("finish_reason")
                if _fr is not None:
                    captured_finish_reason = _fr
            continue
        new = cumulative[len(prev_text) :]
        prev_text = cumulative
        if new:
            text_parts.append(new)

    full_text = "".join(text_parts)
    # With provenance, only a leading <think> the generator wrapped is parsed; a literal one stays text.
    _wrapped = think_provenance is None or think_provenance.get("wrapped", 0) > 0
    _wrap_entries = (think_provenance or {}).get("wraps") or []
    content_blocks: list = []
    if full_text and parse_think and _wrapped:
        content_blocks = _think_markup_to_blocks(
            full_text, _wrap_entries[0] if _wrap_entries else None
        )
    elif full_text:
        content_blocks = [AnthropicResponseTextBlock(text = full_text)]

    stop_reason = openai_finish_to_anthropic_stop(captured_finish_reason, had_tool_calls = False)

    return _anthropic_message_json_response(
        message_id, model_name, content_blocks, stop_reason, usage
    )


async def _anthropic_plain_non_streaming(
    request,
    run_gen,
    message_id,
    model_name,
    parse_think = True,
    think_provenance = None,
    cancel_event = None,
):
    """Generate and reduce a plain response entirely off the event loop."""

    def _drain_and_build():
        return _anthropic_plain_response_from_events(
            _collect_anthropic_events(run_gen),
            message_id,
            model_name,
            parse_think = parse_think,
            think_provenance = think_provenance,
        )

    disconnect_watcher = asyncio.create_task(_await_disconnect_then_cancel(request, cancel_event))
    try:
        response = await _run_blocking_generation(
            _drain_and_build,
            cancel_event,
            name = "anthropic-plain-nonstream",
        )
    finally:
        await _stop_local_disconnect_cancel_watcher(disconnect_watcher)
    # A 200 built from partial output must be marked failed, or keepwarm reads it as a clean completion.
    if cancel_event is not None:
        _mark_cancelled_json_response_failed(request, cancel_event)
    return response


# =====================================================================
# Client-side tool pass-through (Anthropic-native tools field)
# =====================================================================


_JSON_SCHEMA_MAP_KEYWORDS = frozenset(
    {
        "$defs",
        "definitions",
        "dependentSchemas",
        "patternProperties",
        "properties",
    }
)
_JSON_SCHEMA_SINGLE_KEYWORDS = frozenset(
    {
        "additionalProperties",
        "contains",
        "contentSchema",
        "else",
        "if",
        "items",
        "not",
        "propertyNames",
        "then",
        "unevaluatedItems",
        "unevaluatedProperties",
    }
)
# "items" is in both sets: draft 2020-12 gives it one schema, draft-07 a tuple of them.
_JSON_SCHEMA_LIST_KEYWORDS = frozenset({"allOf", "anyOf", "items", "oneOf", "prefixItems"})
# Max bound per keyword under the 2000-rule llama.cpp budget; past it bounds compile unbounded.
_JSON_SCHEMA_REPETITION_LIMITS = {
    "maxItems": 1997,
    "maxLength": 1999,
    "minItems": 2000,
    "minLength": 1999,
}


def _is_json_number(value) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _llama_compatible_tool_schema(schema):
    """Drops unanchored patterns and repetition bounds llama.cpp rejects; anchoring would change matches."""
    if not isinstance(schema, dict):
        return schema

    compatible = dict(schema)
    pattern = compatible.get("pattern")
    if isinstance(pattern, str) and not (pattern.startswith("^") and pattern.endswith("$")):
        compatible.pop("pattern")
    for keyword, limit in _JSON_SCHEMA_REPETITION_LIMITS.items():
        bound = compatible.get(keyword)
        # An integral bound can decode to float, and llama.cpp reads one either way.
        if _is_json_number(bound) and bound > limit:
            compatible.pop(keyword)
    # min > max becomes a descending repetition that llama-grammar.cpp expands until OOM: drop both.
    for lower, upper in (("minItems", "maxItems"), ("minLength", "maxLength")):
        low, high = compatible.get(lower), compatible.get(upper)
        if _is_json_number(low) and _is_json_number(high) and low > high:
            compatible.pop(lower)
            compatible.pop(upper)

    for keyword in _JSON_SCHEMA_MAP_KEYWORDS:
        children = compatible.get(keyword)
        if isinstance(children, dict):
            compatible[keyword] = {
                key: _llama_compatible_tool_schema(value) for key, value in children.items()
            }

    for keyword in _JSON_SCHEMA_SINGLE_KEYWORDS:
        child = compatible.get(keyword)
        if isinstance(child, dict):
            compatible[keyword] = _llama_compatible_tool_schema(child)

    for keyword in _JSON_SCHEMA_LIST_KEYWORDS:
        children = compatible.get(keyword)
        if isinstance(children, list):
            compatible[keyword] = [_llama_compatible_tool_schema(value) for value in children]

    return compatible


def _llama_compatible_response_format(response_format):
    """Copy whose guided schema llama.cpp can compile; json_object and nested json_schema both feed it."""
    if not isinstance(response_format, dict):
        return response_format

    compatible = dict(response_format)
    schema = compatible.get("schema")
    if isinstance(schema, dict):
        compatible["schema"] = _llama_compatible_tool_schema(schema)
    wrapper = compatible.get("json_schema")
    if isinstance(wrapper, dict) and isinstance(wrapper.get("schema"), dict):
        compatible["json_schema"] = {
            **wrapper,
            "schema": _llama_compatible_tool_schema(wrapper["schema"]),
        }
    return compatible


def _llama_compatible_tools(openai_tools):
    if not isinstance(openai_tools, list):
        return openai_tools

    compatible_tools = []
    for tool in openai_tools:
        if not isinstance(tool, dict):
            compatible_tools.append(tool)
            continue
        function = tool.get("function")
        parameters = function.get("parameters") if isinstance(function, dict) else None
        if not isinstance(parameters, dict):
            compatible_tools.append(tool)
            continue
        compatible_tools.append(
            {
                **tool,
                "function": {
                    **function,
                    "parameters": _llama_compatible_tool_schema(parameters),
                },
            }
        )
    return compatible_tools


def _build_passthrough_payload(
    openai_messages,
    openai_tools,
    temperature,
    top_p,
    top_k,
    max_tokens,
    stream,
    stop = None,
    min_p = None,
    repetition_penalty = None,
    presence_penalty = None,
    frequency_penalty = None,
    logit_bias = None,
    tool_choice = "auto",
    response_format = None,
    chat_template_kwargs = None,
    backend_ctx = None,
    seed = None,
    stream_options = None,
    markup = None,
    thinking_budget_tokens = None,
):
    from core.inference.chat_template_helpers import (
        forced_tool_catalog,
        neutralize_control_markup_in_messages,
        neutralize_tool_descriptions,
        reconciled_tool_choice,
    )

    # Llama-server templates /v1/messages bodies itself; never use the OpenAI builder below.
    _pt_markup = markup
    body = {
        "messages": neutralize_control_markup_in_messages(openai_messages, None, _pt_markup),
        "temperature": temperature,
        "top_p": top_p,
        "top_k": top_k,
        "stream": stream,
    }
    # Tested after the rewrite: an all-injected catalog drops to empty, and [] still advertises tools.
    safe_tools = neutralize_tool_descriptions(openai_tools, None, _pt_markup)
    if safe_tools:
        # A forced tool dropped from the safe catalog falls back to 'auto', or llama-server gets raw markup.
        tool_choice = reconciled_tool_choice(tool_choice, openai_tools, safe_tools)
        # llama-server reads tool_choice only as a string and treats an object as "auto".
        forced_tools = forced_tool_catalog(tool_choice, safe_tools)
        if forced_tools:
            safe_tools, tool_choice = forced_tools, "required"
        body["tools"] = llama_grammar_tools(_llama_compatible_tools(safe_tools))
        if tool_choice is not None:
            body["tool_choice"] = tool_choice
    _apply_seeded_llama_request(body, seed)
    if stream and stream_options is not None:
        body["stream_options"] = stream_options
    body["max_tokens"] = (
        max_tokens if max_tokens is not None else (backend_ctx or _DEFAULT_MAX_TOKENS_FLOOR)
    )
    # Normalize stop like the non-passthrough path, so an empty stop string is not forwarded verbatim.
    _stop = _normalize_stop_sequences(stop)
    if _stop:
        body["stop"] = _stop
    if min_p is not None:
        body["min_p"] = min_p
    if repetition_penalty is not None:
        # llama-server's field is "repeat_penalty", not "repetition_penalty".
        body["repeat_penalty"] = repetition_penalty
    if presence_penalty is not None:
        body["presence_penalty"] = presence_penalty
    if frequency_penalty is not None:
        body["frequency_penalty"] = frequency_penalty
    if logit_bias:
        # Spec {token id: bias} object; llama-server ignores out-of-vocab ids.
        body["logit_bias"] = logit_bias
    if response_format is not None:
        # llama-server reads response_format flat at the request root (as the OpenAI SDK sends it).
        body["response_format"] = _llama_compatible_response_format(response_format)
    if chat_template_kwargs is not None:
        # Forward template overrides like enable_thinking so the Jinja template follows the caller's mode.
        body["chat_template_kwargs"] = chat_template_kwargs
    if thinking_budget_tokens is not None:
        body["thinking_budget_tokens"] = thinking_budget_tokens
    return body


def _nudge_retry_messages(
    body,
    data,
    allowed_tools,
    markup = None,
):
    """Neutralize the whole text so the prefix keeps KV cache; raw-catalog allowed_tools could return."""
    from core.inference.chat_template_helpers import neutralize_control_markup_in_messages

    # Same profile the body used: curated patterns would rewrite the prefix and miss the KV cache.
    return neutralize_control_markup_in_messages(
        [*body.get("messages", []), *nudge_messages(data, allowed_tools)], None, markup
    )


def _anthropic_passthrough_chunk_lines(
    emitter, chunk, request, disable_parallel_tool_use: bool
) -> tuple[list[str], bool]:
    """One OpenAI chat chunk -> Anthropic SSE lines; True when an in-band error ended the stream."""
    if isinstance(chunk, dict):
        error_message = _monitor_openai_error_message(chunk)
        if error_message:
            # A 200 SSE error payload has no choices, so feed_chunk would end cleanly and the
            # middleware would claim a preview-owned model: flag failed and send an error event.
            from core.inference.llama_keepwarm import mark_response_failed
            mark_response_failed(getattr(request, "scope", None))
            # The formatter recovers n_prompt_tokens/n_ctx from the payload when the message lacks them.
            return [
                _anthropic_upstream_stream_error_event(
                    error_message,
                    counts_source = _json_dumps_safe(chunk.get("error", chunk)),
                )
            ], True
    if disable_parallel_tool_use:
        _drop_parallel_tool_call_deltas(chunk)
    return emitter.feed_chunk(chunk), False


async def _anthropic_passthrough_stream(
    request,
    cancel_event,
    llama_backend,
    openai_messages,
    openai_tools,
    temperature,
    top_p,
    top_k,
    max_tokens,
    message_id,
    model_name,
    stop = None,
    min_p = None,
    repetition_penalty = None,
    presence_penalty = None,
    seed = None,
    tool_choice = "auto",
    session_id = None,
    cancel_id = None,
    disable_parallel_tool_use = False,
    auto_heal_tool_calls = None,
    response_format = None,
    enable_thinking = None,
    reasoning_effort = None,
    preserve_thinking = None,
    parse_think = True,
    thinking_budget_tokens = None,
    context_overflow = None,
):
    """Streaming client-side pass-through: forward tools to llama-server and
    translate its stream to Anthropic SSE without executing anything."""
    body = _build_passthrough_payload(
        openai_messages,
        openai_tools,
        temperature,
        top_p,
        top_k,
        max_tokens,
        True,
        stop = stop,
        min_p = min_p,
        repetition_penalty = repetition_penalty,
        presence_penalty = presence_penalty,
        seed = seed,
        tool_choice = tool_choice,
        response_format = response_format,
        chat_template_kwargs = _reasoning_template_kwargs(
            llama_backend, enable_thinking, reasoning_effort, preserve_thinking
        ),
        thinking_budget_tokens = thinking_budget_tokens,
        backend_ctx = llama_backend.context_length,
        stream_options = {"include_usage": True},
        markup = getattr(llama_backend, "markup_profile", None),
    )

    from core.inference.chat_template_helpers import (
        forced_tool_catalog,
        neutralize_tool_descriptions,
    )

    # Pick the forced tool from the sanitized catalog, as the body does.
    _count_tools = (
        forced_tool_catalog(
            tool_choice,
            neutralize_tool_descriptions(
                openai_tools, None, getattr(llama_backend, "markup_profile", None)
            ),
        )
        or openai_tools
    )

    # count_chat_tokens blocks on HTTP, so off the loop; pass tools and reasoning kwargs so the
    # count matches the rendered prompt.
    input_tokens = await asyncio.to_thread(
        lambda: llama_backend.count_chat_tokens(
            openai_messages,
            None,
            _count_tools,
            chat_template_kwargs = _reasoning_template_kwargs(
                llama_backend, enable_thinking, reasoning_effort, preserve_thinking
            ),
        )
    )

    # cancel_id mirrors the OpenAI passthrough; registered so a reload cannot yank llama-server.
    _tracker = _TrackedCancel(
        cancel_event,
        cancel_id,
        session_id,
        message_id,
        model = model_name,
        kind = "messages",
    )

    async def _stream():
        # Entered inside the body: aclose() on an unstarted generator runs nothing, so an eager entry
        # leaks and 409s every swap.
        _tracker.__enter__()
        emitter = AnthropicPassthroughEmitter(reasoning_as_thinking = parse_think)
        # Heal only against the sanitized catalog: a dropped unsafe tool must never become a tool_use.
        from core.inference.chat_template_helpers import neutralize_tool_descriptions

        _healing_tools = neutralize_tool_descriptions(
            openai_tools, None, getattr(llama_backend, "markup_profile", None)
        )
        # Gate on the reconciled choice the body carries, not the caller's; 'none' still forbids promotion.
        _allowed_tools = heal_gate(
            auto_heal_tool_calls,
            body.get("tools"),
            body.get("tool_choice"),
            response_format = body.get("response_format"),
        )
        if _allowed_tools:
            emitter.enable_healing(
                _allowed_tools,
                _healing_tools,
                disable_parallel_tool_use = disable_parallel_tool_use,
            )
        # Outside the teardown try: a disconnect here would strand the tracker; __exit__ is idempotent.
        try:
            for line in emitter.start(message_id, model_name, input_tokens = input_tokens):
                yield line
        except BaseException:
            _tracker.__exit__(None, None, None)
            raise

        # Manage the httpx client, response, AND the aiter_lines() async
        # generator MANUALLY -- no `async with`, no anonymous iterator.
        #
        # On Python 3.13 + httpcore 1.0.x, `async for raw_line in
        # resp.aiter_lines():` creates an anonymous async generator. When the
        # loop exits via `break` (or the generator is orphaned by a mid-stream
        # client disconnect), `async for` does NOT auto-close the iterator like
        # a sync `for` would. The iterator stays reachable only from the current
        # coroutine frame; once `_stream()` returns, the frame is GC'd and the
        # iterator becomes unreachable. The asyncgen finalizer then runs aclose()
        # on a LATER GC pass in a DIFFERENT asyncio task, where httpcore's
        # `HTTP11ConnectionByteStream.aclose()` enters `anyio.CancelScope.__exit__`
        # with a mismatched task and prints `RuntimeError: Attempted to exit
        # cancel scope in a different task` / `RuntimeError: async generator
        # ignored GeneratorExit` as "Exception ignored in:" unraisable warnings.
        #
        # Fix: save `resp.aiter_lines()` as `lines_iter`, and in finally
        # explicitly `await lines_iter.aclose()` BEFORE `resp.aclose()` /
        # `client.aclose()`. This closes the iterator in our own task's event
        # loop, cleaning up the httpcore byte-stream before the asyncgen
        # finalizer has anything orphaned to finalize. Each aclose is wrapped in
        # `try: ... except Exception: pass` so nested anyio cleanup noise can't
        # bubble out.
        client = _llama_stream_client()
        resp = None
        lines_iter = None
        items_iter = None
        cancel_watcher = None
        disconnect_watcher = None
        # Resolved by the route from the request field or UNSLOTH_CONTEXT_OVERFLOW; None keeps the 400.
        _truncate_budget = _OVERFLOW_TRUNCATE_MAX_RETRIES if context_overflow else 0

        def _apply_passthrough_truncation(err_text: str) -> bool:
            nonlocal _truncated_messages
            dropped = _apply_measured_overflow_truncation(body, err_text, context_overflow)
            if dropped is None:
                return False
            _truncated_messages += dropped
            _remember_passthrough_cut(
                _uncut_messages, body, context_overflow, _truncated_messages, _cut_scope
            )
            return True

        try:
            # Inside the try so a disconnect during the replay still releases the tracker.
            _uncut_messages, _cut_scope, _truncated_messages = await _prepare_passthrough_cut(
                llama_backend, body, context_overflow
            )
            upstream = _LlamaUpstream(llama_backend, "/v1/chat/completions")
            while True:
                async with aclosing(
                    upstream.stream_response(client, body, cancel_event, request)
                ) as opening:
                    async for opened in opening:
                        if opened is _LLAMA_STREAM_KEEPALIVE:
                            yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                        else:
                            resp = opened
                first_token_deadline = upstream.first_token_deadline
                if resp is None:
                    return

                if resp.status_code == 200:
                    break

                # Headers flushed, so upstream 4xx must surface as in-band Anthropic error, not silent end_turn.
                _err_bytes = await resp.aread()
                _err_text = _err_bytes.decode("utf-8", "replace")
                logger.error(
                    "anthropic passthrough upstream error: status=%s body=%s",
                    resp.status_code,
                    _err_text[:500],
                )
                # Opt-in overflow policy, as on /v1/chat/completions: shrink and retry instead of a 400.
                if (
                    _truncate_budget > 0
                    and _classify_llama_generation_error(Exception(_err_text))
                    and _apply_passthrough_truncation(_err_text)
                ):
                    _truncate_budget -= 1
                    try:
                        await resp.aclose()
                    except Exception:
                        pass
                    resp = None
                    continue
                _err_text = _err_text[:500]
                # The outer 200 stream headers are already flushed, so flag the failure: the
                # middleware must not claim a preview-owned model on a passthrough whose
                # upstream errored before any SSE.
                from core.inference.llama_keepwarm import mark_response_failed

                mark_response_failed(getattr(request, "scope", None))
                _over = bool(_classify_llama_generation_error(Exception(_err_text)))
                yield build_anthropic_sse_event(
                    "error",
                    anthropic_error_body(
                        _anthropic_upstream_error(_err_text),
                        status = 400 if _over else resp.status_code,
                    ),
                )
                return

            # Watchers unblock aiter_lines() during prefill, before in-loop checks can run.
            cancel_watcher = asyncio.create_task(_await_cancel_then_close(cancel_event, resp))
            disconnect_watcher = asyncio.create_task(
                _await_disconnect_then_close(request, resp, cancel_event)
            )
            lines_iter = resp.aiter_lines()
            items_iter = _aiter_llama_stream_items(
                lines_iter,
                cancel_event = cancel_event,
                request = request,
                first_token_deadline = first_token_deadline,
                response = resp,
                keepalive_interval_s = _openai_passthrough_stream_keepalive_interval(),
            )
            async for raw_line in items_iter:
                if raw_line is _LLAMA_STREAM_KEEPALIVE:
                    yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                    continue
                if not raw_line or not raw_line.startswith("data: "):
                    continue
                data_str = raw_line[6:]
                if data_str.strip() == "[DONE]":
                    break
                try:
                    chunk = json.loads(data_str)
                except json.JSONDecodeError:
                    continue
                lines, failed = _anthropic_passthrough_chunk_lines(
                    emitter, chunk, request, disable_parallel_tool_use
                )
                for line in lines:
                    yield line
                if failed:
                    return
        except Exception as e:
            if not cancel_event.is_set():
                logger.error("anthropic_messages passthrough stream error: %s", e)
                get_llama_cpp_backend()._maybe_recover_from_mtp_crash(e)
                # The stream already sent 200, so flag it failed or the middleware claims a preview-owned model.
                from core.inference.llama_keepwarm import mark_response_failed

                mark_response_failed(getattr(request, "scope", None))
                event = _anthropic_stream_error_event(
                    e,
                    force = True,
                )
                if event is not None:
                    yield event
                return
        finally:
            if cancel_event.is_set():
                from core.inference.llama_keepwarm import mark_response_failed
                mark_response_failed(getattr(request, "scope", None))
            # The tracker exits after the closes; teardown awaits are bounded.
            try:
                await _aclose_stream_resources(
                    watchers = (cancel_watcher, disconnect_watcher),
                    items = items_iter,
                    iterator = lines_iter,
                    resp = resp,
                    client = client,
                )
            finally:
                _release_admission(tracker = _tracker)

        for line in emitter.finish():
            yield line

    # Closing an unstarted generator is a no-op, so pass a cleanup hook or the tracker entry leaks.
    return _sse_streaming_response(
        _stream(),
        unstarted_cleanup = _tracked_cancel_unstarted_cleanup(_tracker),
    )


def _sum_passthrough_attempt_stats(first: dict, retry: dict, selected: dict) -> dict:
    """Keep selected content with the chronological attempts' aggregate stats."""
    if not all(isinstance(item, dict) for item in (first, retry, selected)):
        return selected
    if not isinstance(first.get("usage"), dict) or not isinstance(retry.get("usage"), dict):
        return selected
    aggregate = _summed_tool_loop_stats(first, retry)
    result = dict(selected)
    result["usage"] = aggregate["usage"]
    # Two attempts at one reply, not tool passes: the client gets llama-server's usage shape back.
    result["usage"].pop("context_tokens", None)
    if "timings" in aggregate:
        result["timings"] = aggregate["timings"]
    return result


def _anthropic_message_from_openai_completion(
    data: dict,
    message_id,
    model_name,
    *,
    openai_tools,
    allowed_tools,
    disable_parallel_tool_use: bool,
    response_format,
    parse_think: bool,
):
    """A non-streaming OpenAI chat completion -> the Anthropic Messages JSON response."""
    choice = (data.get("choices") or [{}])[0]
    message = choice.get("message") or {}
    finish_reason = choice.get("finish_reason")

    healing_active = bool(allowed_tools)
    healed_events = (
        heal_openai_message_events(message, allowed_tools, openai_tools) if healing_active else None
    )

    content_blocks = []
    tool_calls = []
    # Anthropic orders thinking ahead of the answer; reading only `content` drops the trace.
    reasoning = message.get("reasoning_content") or ""
    if reasoning.strip():
        if parse_think:
            content_blocks.append(AnthropicResponseThinkingBlock(thinking = reasoning))
        else:
            # Thinking effectively off: the parser shunted a literal
            # example into reasoning_content; reconstruct it as text.
            content_blocks.append(AnthropicResponseTextBlock(text = f"<think>{reasoning}</think>"))
    if healed_events:
        emitted_tool_uses = 0
        for kind, value in healed_events:
            if kind == "text":
                text = str(value).strip()
                if text:
                    content_blocks.append(AnthropicResponseTextBlock(text = text))
                continue
            if disable_parallel_tool_use and emitted_tool_uses >= 1:
                continue
            fn = value.get("function") or {}
            try:
                args = json.loads(fn.get("arguments", "{}"))
            except json.JSONDecodeError:
                args = {}
            tool_calls.append(value)
            emitted_tool_uses += 1
            content_blocks.append(
                AnthropicResponseToolUseBlock(
                    id = anthropic_tool_use_id(value.get("id")),
                    name = fn.get("name", ""),
                    input = args,
                )
            )
    else:
        text = message.get("content") or ""
        if text:
            # Keep unpromoted bytes when healing is active; legacy stripping is only for opted-out
            # or no-client-tool requests. The protected helper preserves <think> rehearsal and
            # balanced [TOOL_CALLS] prose, gated on the declared tools so an inactive
            # NAME[ARGS]{...} example is kept.
            if not healing_active and response_format is None:
                text = _strip_tool_xml_for_display(
                    text,
                    auto_heal_tool_calls = True,
                    enabled_tool_names = _display_tool_name_gate(openai_tools),
                )
            text = text.strip()
            if text:
                content_blocks.append(AnthropicResponseTextBlock(text = text))

        tool_calls = message.get("tool_calls") or []
        if disable_parallel_tool_use and len(tool_calls) > 1:
            tool_calls = tool_calls[:1]
        for tc in tool_calls:
            fn = tc.get("function") or {}
            try:
                args = json.loads(fn.get("arguments", "{}"))
            except json.JSONDecodeError:
                args = {}
            content_blocks.append(
                AnthropicResponseToolUseBlock(
                    id = anthropic_tool_use_id(tc.get("id")),
                    name = fn.get("name", ""),
                    input = args,
                )
            )

    stop_reason = openai_finish_to_anthropic_stop(finish_reason, had_tool_calls = bool(tool_calls))

    usage = data.get("usage") or {}
    return _anthropic_message_json_response(
        message_id, model_name, content_blocks, stop_reason, usage
    )


async def _anthropic_passthrough_non_streaming(
    llama_backend,
    openai_messages,
    openai_tools,
    temperature,
    top_p,
    top_k,
    max_tokens,
    message_id,
    model_name,
    stop = None,
    min_p = None,
    repetition_penalty = None,
    presence_penalty = None,
    seed = None,
    tool_choice = "auto",
    disable_parallel_tool_use = False,
    auto_heal_tool_calls = None,
    nudge_tool_calls = None,
    request: Optional[Request] = None,
    cancel_event = None,
    response_format = None,
    enable_thinking = None,
    reasoning_effort = None,
    preserve_thinking = None,
    parse_think = True,
    thinking_budget_tokens = None,
    context_overflow = None,
):
    body = _build_passthrough_payload(
        openai_messages,
        openai_tools,
        temperature,
        top_p,
        top_k,
        max_tokens,
        False,
        stop = stop,
        min_p = min_p,
        repetition_penalty = repetition_penalty,
        presence_penalty = presence_penalty,
        seed = seed,
        tool_choice = tool_choice,
        response_format = response_format,
        chat_template_kwargs = _reasoning_template_kwargs(
            llama_backend, enable_thinking, reasoning_effort, preserve_thinking
        ),
        thinking_budget_tokens = thinking_budget_tokens,
        backend_ctx = llama_backend.context_length,
        markup = getattr(llama_backend, "markup_profile", None),
    )
    _timeout = _llama_non_streaming_generation_timeout()

    async with _LlamaUpstream(
        llama_backend, "/v1/chat/completions", cancel_event = cancel_event, request = request
    ) as upstream:
        _truncate_budget = _OVERFLOW_TRUNCATE_MAX_RETRIES if context_overflow else 0
        _uncut_messages, _cut_scope, _truncated_messages = await _prepare_passthrough_cut(
            llama_backend, body, context_overflow
        )
        resp = await upstream.post(body, timeout = _timeout)
        # Opt-in overflow policy, as on /v1/chat/completions: shrink and retry instead of a 400.
        while (
            resp.status_code != 200
            and _truncate_budget > 0
            and _classify_llama_generation_error(Exception(resp.text))
        ):
            dropped = _apply_measured_overflow_truncation(body, resp.text, context_overflow)
            if dropped is None:
                break
            _truncate_budget -= 1
            _truncated_messages += dropped
            _remember_passthrough_cut(
                _uncut_messages, body, context_overflow, _truncated_messages, _cut_scope
            )
            resp = await upstream.post(body, timeout = _timeout)

        if resp.status_code != 200:
            _err_text = resp.text[:500]
            _over = bool(_classify_llama_generation_error(Exception(_err_text)))
            raise HTTPException(
                status_code = 400 if _over else resp.status_code,
                detail = _anthropic_upstream_error(_err_text),
            )

        data = resp.json()
        # Sanitized as in the streaming path, or a nudge retry names a dropped tool.
        from core.inference.chat_template_helpers import neutralize_tool_descriptions

        _healing_tools = neutralize_tool_descriptions(
            openai_tools, None, getattr(llama_backend, "markup_profile", None)
        )
        # Gate on the reconciled choice the body carries, not the caller's; 'none' still forbids promotion.
        _allowed_tools = heal_gate(
            auto_heal_tool_calls,
            body.get("tools"),
            body.get("tool_choice"),
            response_format = body.get("response_format"),
        )

        # Opt-in single-retry nudge; keep the prompt prefix intact so the KV cache is reused.
        if (
            _allowed_tools
            and nudge_enabled(nudge_tool_calls, response_format = body.get("response_format"))
            and nudge_should_retry(data, _allowed_tools, _healing_tools)
        ):
            first_data = data
            retry_body = {
                **body,
                "messages": _nudge_retry_messages(
                    body, data, _allowed_tools, getattr(llama_backend, "markup_profile", None)
                ),
            }
            try:
                retry_resp = await upstream.post(retry_body, timeout = _timeout)
                if retry_resp.status_code == 200:
                    retry_data = retry_resp.json()
                    if response_has_promotable_calls(retry_data, _allowed_tools, openai_tools):
                        data = _sum_passthrough_attempt_stats(first_data, retry_data, retry_data)
                    else:
                        data = _sum_passthrough_attempt_stats(first_data, retry_data, first_data)
            except (httpx.RequestError, ValueError) as exc:
                logger.warning("tool-call nudge retry failed; keeping original: %s", exc)

        return _anthropic_message_from_openai_completion(
            data,
            message_id,
            model_name,
            openai_tools = openai_tools,
            allowed_tools = _allowed_tools,
            disable_parallel_tool_use = disable_parallel_tool_use,
            response_format = response_format,
            parse_think = parse_think,
        )


# =====================================================================
# Client-side tool pass-through (OpenAI-native /v1/chat/completions)
# =====================================================================


def _normalize_local_assistant_message(message: dict) -> Optional[dict]:
    """Drops bare assistant sentinels; reasoning-only turn gets empty content; caller dict not mutated."""
    if message.get("role") != "assistant":
        return message
    if message.get("content") or message.get("tool_calls"):
        return message
    if message.get("reasoning_content"):
        if message.get("content") == "":
            return message
        return {**message, "content": ""}
    return None


def _drop_empty_assistant_sentinels(messages: list[dict]) -> list[dict]:
    """Drop Stop-button sentinels and normalize reasoning-only turns."""
    out: list[dict] = []
    for message in messages:
        normalized = _normalize_local_assistant_message(message)
        if normalized is not None:
            out.append(normalized)
    return out


def _merge_user_content(a: Any, b: Any) -> Any:
    """Join two user ``content`` values: strings with a blank line, else as concatenated parts."""
    if isinstance(a, str) and isinstance(b, str):
        if not a:
            return b
        if not b:
            return a
        return a + "\n\n" + b

    def _parts(c: Any) -> list:
        if c is None:
            return []
        if isinstance(c, str):
            return [{"type": "text", "text": c}] if c else []
        if isinstance(c, list):
            return list(c)
        return [{"type": "text", "text": str(c)}]

    return _parts(a) + _parts(b)


def _coalesce_consecutive_user_turns(messages: list[dict]) -> list[dict]:
    """Merges adjacent user turns only, never assistant or tool; strict templates reject two in a row."""
    out: list[dict] = []
    for m in messages:
        if m.get("role") == "user" and out and out[-1].get("role") == "user":
            prev = dict(out[-1])
            prev["content"] = _merge_user_content(prev.get("content"), m.get("content"))
            if prev.get("name") != m.get("name"):
                prev.pop("name", None)
            out[-1] = prev
            continue
        out.append(m)
    return out


def _template_supports_tools(backend) -> bool:
    """Use passthrough, not supports_tools: folding would strip tools; unreadable backend returns True."""
    try:
        for attr in ("supports_tool_passthrough", "supports_tools"):
            if hasattr(backend, attr):
                return bool(getattr(backend, attr))
        return True
    except Exception:
        return True


def _named_anthropic_tool_results(messages: list[dict]) -> list[dict]:
    """Names results by position; call ids restart per response; unnamed reads as legacy MCP history."""
    names = _mcp_resolve_tool_names(messages)
    return [
        {**message, "name": names[index]}
        if message.get("role") == "tool" and not message.get("name") and index in names
        else message
        for index, message in enumerate(messages)
    ]


def _sanitize_anthropic_openai_messages(messages: list[dict], backend) -> list[dict]:
    """Shared with the token counter so counts describe the same prompt; fold runs before coalesce."""
    messages = _strip_provider_synthetic_tool_history(_drop_empty_assistant_sentinels(messages))
    if not _template_supports_tools(backend):
        messages = fold_tool_results_into_user(messages)
    return _coalesce_consecutive_user_turns(messages)


_LOCAL_SERVER_BUILTIN_TOOL_NAMES = frozenset(
    {"web_search", "web_fetch", "code_execution", "image_generation"}
)


def _merge_stranded_local_assistant_turns(messages: list[tuple[dict, bool]]) -> list[dict]:
    """Carries a fragment stranded by removed provider tool rounds into the next assistant turn."""
    out: list[dict] = []
    pending: Optional[dict] = None

    for message, message_is_stranded in messages:
        if pending is None:
            if message_is_stranded:
                pending = message
            else:
                out.append(message)
            continue

        if message.get("role") != "assistant":
            out.append(pending)
            pending = None
            out.append(message)
            continue

        merged = dict(message)
        # One shared name or none: the fragments fold into a single turn.
        if pending.get("name") != message.get("name"):
            merged.pop("name", None)
        old_content = pending.get("content")
        new_content = merged.get("content")
        if old_content or new_content:
            merged["content"] = _merge_user_content(old_content, new_content)

        old_reasoning = pending.get("reasoning_content")
        new_reasoning = merged.get("reasoning_content")
        reasoning_parts = [
            value for value in (old_reasoning, new_reasoning) if isinstance(value, str) and value
        ]
        if reasoning_parts:
            merged["reasoning_content"] = "\n\n".join(reasoning_parts)

        if message_is_stranded:
            pending = merged
        else:
            out.append(merged)
            pending = None

    if pending is not None:
        out.append(pending)
    return out


def _strip_provider_synthetic_tool_history(messages: list[dict]) -> list[dict]:
    """Drops provider-synthetic tool calls and their tool replies so no orphan tool_call_id is sent."""
    dropped_ids: set[str] = set()
    sanitized_assistant: list[tuple[dict, bool]] = []
    for m in messages:
        if m.get("role") != "assistant":
            sanitized_assistant.append((m, False))
            continue
        tool_calls = m.get("tool_calls")
        if not isinstance(tool_calls, list) or not tool_calls:
            # Strip Gemini-only `extra_content` so it doesn't leak to llama-server after a provider switch.
            if "extra_content" in m:
                m = {k: v for k, v in m.items() if k != "extra_content"}
            sanitized_assistant.append((m, False))
            continue
        cleaned: list[dict] = []
        for tc in tool_calls:
            if not isinstance(tc, dict):
                cleaned.append(tc)
                continue
            fn = tc.get("function")
            name = ""
            if isinstance(fn, dict):
                name = (fn.get("name") or "").lower()
            if name in _LOCAL_SERVER_BUILTIN_TOOL_NAMES:
                raw_args = fn.get("arguments") if isinstance(fn, dict) else None
                args_obj: Any = None
                if isinstance(raw_args, str):
                    try:
                        args_obj = json.loads(raw_args) if raw_args else None
                    except Exception:
                        args_obj = None
                elif isinstance(raw_args, dict):
                    args_obj = raw_args
                is_synthetic = False
                if isinstance(args_obj, dict):
                    if args_obj.get("_server_tool") is True:
                        is_synthetic = True
                    google = args_obj.get("google")
                    if isinstance(google, dict) and isinstance(google.get("native_part"), dict):
                        is_synthetic = True
                if is_synthetic:
                    tc_id = tc.get("id")
                    if isinstance(tc_id, str) and tc_id:
                        dropped_ids.add(tc_id)
                    continue
            # Strip Gemini-only `extra_content` from user tool_calls too; llama-server may pass it to the model.
            if "extra_content" in tc:
                tc = {k: v for k, v in tc.items() if k != "extra_content"}
            cleaned.append(tc)
        # Drop message-level `extra_content` (Gemini thoughtSignature replay metadata) on local dispatch.
        m_clean = {k: v for k, v in m.items() if k != "extra_content"}
        if cleaned:
            m_clean["tool_calls"] = cleaned
        else:
            m_clean.pop("tool_calls", None)
        is_stranded = bool(m.get("tool_calls")) and not cleaned
        if (
            not m_clean.get("content")
            and not m_clean.get("reasoning_content")
            and not m_clean.get("tool_calls")
        ):
            continue  # assistant turn now empty, drop
        sanitized_assistant.append((m_clean, is_stranded))

    out: list[tuple[dict, bool]] = []
    for m, is_stranded in sanitized_assistant:
        if (
            m.get("role") == "tool"
            and isinstance(m.get("tool_call_id"), str)
            and m["tool_call_id"] in dropped_ids
        ):
            continue
        out.append((m, is_stranded))
    merged = _merge_stranded_local_assistant_turns(out)
    return _drop_empty_assistant_sentinels(merged)


def _splice_image_into_last_user(messages: list[dict], image_part: dict) -> None:
    """Splice an image into the last user message in place, appending a user turn when none exists."""
    for msg in reversed(messages):
        if msg.get("role") != "user":
            continue
        existing = msg.get("content")
        if isinstance(existing, str):
            msg["content"] = [{"type": "text", "text": existing}, image_part]
        elif isinstance(existing, list):
            existing.append(image_part)
        else:
            msg["content"] = [image_part]
        break
    else:
        messages.append({"role": "user", "content": [image_part]})


def _openai_messages_for_passthrough(
    payload,
    vision: bool = False,
    normalize_images: bool = True,
    promote_mcp_images: bool = True,
) -> list[dict]:
    """Keeps tool calls and results; normalize_images=False: raw bytes; image_base64 if not in thread."""
    messages = _strip_provider_synthetic_tool_history(
        _drop_empty_assistant_sentinels([m.model_dump(exclude_none = True) for m in payload.messages])
    )
    # Left for the local-template rebuild, whose flatten would otherwise drop promoted parts.
    if promote_mcp_images:
        messages = promote_mcp_history_images(messages, vision = vision)

    if normalize_images:
        _normalize_openai_image_parts_for_llama(messages)

    if not _legacy_image_is_distinct(payload):
        return messages

    if normalize_images:
        try:
            raw = base64.b64decode(payload.image_base64)
            data_url = _llama_image_data_url(raw)
        except Exception:
            raise HTTPException(
                status_code = 400,
                detail = "Failed to process image.",
            )
    else:
        # As it arrived; the media type is never read back.
        data_url = f"data:application/octet-stream;base64,{payload.image_base64}"
    image_part = {"type": "image_url", "image_url": {"url": data_url}}

    _splice_image_into_last_user(messages, image_part)

    return messages


def _flatten_content_parts_for_local_template(messages: list[dict]) -> list[dict]:
    """Local text templates raise on part lists, so only text parts are kept; GGUF keeps the parts."""
    out = []
    for msg in messages:
        content = msg.get("content")
        if isinstance(content, list):
            text_parts = [
                part.get("text", "")
                for part in content
                if isinstance(part, dict) and part.get("type") == "text"
            ]
            msg = {**msg, "content": "\n".join(text_parts) if text_parts else ""}
        out.append(msg)
    return out


def _structured_tool_history_for_local_template(messages: list[dict]) -> list[dict]:
    """Local templates only: tool_calls arguments parsed to mappings; HTTP unchanged; unparseable as-is."""
    out = []
    for msg in messages:
        tool_calls = msg.get("tool_calls")
        if isinstance(tool_calls, list) and tool_calls:
            new_calls = []
            for tc in tool_calls:
                fn = tc.get("function") if isinstance(tc, dict) else None
                args = fn.get("arguments") if isinstance(fn, dict) else None
                if isinstance(args, str):
                    try:
                        parsed = json.loads(args)
                    except (ValueError, RecursionError):
                        parsed = None
                    if isinstance(parsed, dict):
                        tc = {**tc, "function": {**fn, "arguments": parsed}}
                new_calls.append(tc)
            msg = {**msg, "tool_calls": new_calls}
        out.append(msg)
    return out


def _openai_messages_for_gguf_chat(
    payload,
    is_vision: bool,
    promoted_out: "Optional[list]" = None,
) -> tuple[list[dict], bool]:
    """Build llama-server messages for the standard GGUF chat path.

    llama-server accepts OpenAI multimodal content parts directly. Preserve all
    per-turn ``image_url`` parts so multi-image chat history keeps each image
    attached to its original turn.
    """
    from core.inference.tool_loop_controller import restore_replayed_tool_results

    # Coalesce only on the GGUF chat path (strict Jinja template); the tool path
    # reuses this via _set_or_prepend_system_message. Passthrough forwards verbatim.
    # Ids lose their minted suffix only after the synthetic pass, which drops results by id.
    messages = _coalesce_consecutive_user_turns(
        _live_tool_call_ids(
            _strip_provider_synthetic_tool_history(
                _drop_empty_assistant_sentinels(
                    restore_replayed_tool_results(
                        [m.model_dump(exclude_none = True) for m in payload.messages]
                    )
                )
            )
        )
    )
    # Distinct, not absent: a legacy image the thread lacks is real; skip only the byte-equal echo.
    if _legacy_image_is_distinct(payload):
        # The normalizer detects the MIME type from the bytes.
        image_part = {
            "type": "image_url",
            "image_url": {
                "url": f"data:image/png;base64,{payload.image_base64}",
            },
        }
        _splice_image_into_last_user(messages, image_part)
    has_image = _normalize_anthropic_openai_images(messages, is_vision)
    return (
        promote_mcp_history_images(messages, vision = is_vision, promoted_out = promoted_out),
        has_image,
    )


async def _openai_messages_for_gguf_chat_async(
    payload,
    is_vision: bool,
    promoted_out: "Optional[list]" = None,
) -> tuple[list[dict], bool]:
    # Restoring a tool result may parse its envelope or source map.
    if _request_has_image(payload) or any(
        getattr(message, "role", None) == "tool" for message in payload.messages
    ):
        return await asyncio.to_thread(
            _openai_messages_for_gguf_chat, payload, is_vision, promoted_out
        )
    return _openai_messages_for_gguf_chat(payload, is_vision, promoted_out)


def _extract_response_format(payload):
    """Reads response_format by attribute and returns None unless it is a dict."""
    rf = getattr(payload, "response_format", None)
    return rf if isinstance(rf, dict) else None


def _response_format_for_llama_server(response_format):
    """llama-server reads a json_schema schema only from ``json_schema.schema`` (tools/server/server-common.cpp:1170)."""
    if (
        isinstance(response_format, dict)
        and response_format.get("type") == "json_schema"
        # Absent means missing or null, the reading the MLX path takes, so both agree.
        and response_format.get("json_schema") is None
        and isinstance(response_format.get("schema"), dict)
    ):
        wrapped = {key: value for key, value in response_format.items() if key != "schema"}
        wrapped["json_schema"] = {"schema": response_format["schema"]}
        return wrapped
    return response_format


def _response_format_constrains_decoding(payload) -> bool:
    """Only exact text-format objects are non-constraining; any other object is kept, never dropped."""
    from core.inference.passthrough_healing import response_format_constrains_decoding
    return response_format_constrains_decoding(_extract_response_format(payload))


def _reject_unhonorable_response_format(payload) -> None:
    from core.inference.grammar_constraint import (
        ResponseFormatError,
        constraint_spec_from_response_format,
    )
    try:
        constraint_spec_from_response_format(_extract_response_format(payload))
    except ResponseFormatError as exc:
        _raise_unsupported_openai_parameter("response_format", str(exc))


def _tools_outrank_response_format(payload, tools) -> bool:
    return bool(tools) and payload.tool_choice != "none"


def _response_format_beside_tools(payload, tools):
    """The request's ``response_format``, or None while ``tools`` can still be called:
    decoding locked to the document would never emit the call."""
    if _tools_outrank_response_format(payload, tools) and _response_format_constrains_decoding(
        payload
    ):
        logger.warning("Ignoring response_format: callable tools cannot run under a schema")
        return None
    return _extract_response_format(payload)


def _build_openai_passthrough_body(
    payload,
    backend_ctx = None,
    llama_backend = None,
) -> dict:
    """Forwards only known OpenAI and llama-server fields, so Unsloth extensions never leak."""
    messages = _openai_messages_for_passthrough(
        payload, vision = bool(getattr(llama_backend, "is_vision", False))
    )
    system_prompt, _, _ = _extract_content_parts(payload.messages)
    messages = _set_or_prepend_system_message(messages, system_prompt)
    # Markup is broken in _build_passthrough_payload, shared with both /v1/messages (#7066).
    tool_choice = payload.tool_choice if payload.tool_choice is not None else "auto"
    tools = _passthrough_client_tools(payload)
    # Reasoning fields go via chat_template_kwargs, gated on template capabilities like other paths.
    tpl_kwargs = (
        llama_backend._request_reasoning_kwargs(
            payload.enable_thinking,
            payload.reasoning_effort,
            _replay_preserve_thinking(llama_backend, payload, messages),
        )
        if llama_backend is not None
        else None
    )
    response_format = _response_format_for_llama_server(
        _response_format_beside_tools(payload, tools)
    )
    body = _build_passthrough_payload(
        messages,
        tools,
        payload.temperature,
        payload.top_p,
        payload.top_k,
        # Honor max_completion_tokens on the tools/response_format passthrough too.
        _effective_openai_max_tokens(payload),
        payload.stream,
        stop = payload.stop,
        min_p = payload.min_p,
        repetition_penalty = payload.repetition_penalty,
        presence_penalty = payload.presence_penalty,
        frequency_penalty = payload.frequency_penalty,
        logit_bias = payload.logit_bias,
        tool_choice = tool_choice,
        response_format = response_format,
        chat_template_kwargs = tpl_kwargs,
        backend_ctx = backend_ctx,
        seed = payload.seed,
        stream_options = payload.stream_options,
        markup = getattr(llama_backend, "markup_profile", None),
    )
    if _continue_final_message(payload, thought = True):
        # llama-server rejects both flags set true.
        body["continue_final_message"] = True
        body["add_generation_prompt"] = False
    return body


async def _build_openai_passthrough_body_async(
    payload,
    backend_ctx = None,
    llama_backend = None,
) -> dict:
    if _request_has_image(payload) or _preserve_probe_pending(llama_backend):
        return await asyncio.to_thread(
            _build_openai_passthrough_body,
            payload,
            backend_ctx = backend_ctx,
            llama_backend = llama_backend,
        )
    return _build_openai_passthrough_body(
        payload,
        backend_ctx = backend_ctx,
        llama_backend = llama_backend,
    )


async def _openai_passthrough_stream(
    request,
    cancel_event,
    llama_backend,
    payload,
    model_name,
    completion_id,
    monitor_id: Optional[str] = None,
):
    _cancel_keys = (payload.cancel_id, payload.session_id, completion_id)
    _tracker = _TrackedCancel.for_payload(cancel_event, payload, *_cancel_keys)
    _tracker.__enter__()
    try:
        reservation, admission_config, prepared_body = await _reserve_counted_gguf_passthrough(
            request = request,
            llama_backend = llama_backend,
            payload = payload,
        )
    except LlamaAdmissionQueueFull as exc:
        _tracker.__exit__(None, None, None)
        _llama_admission_log(
            "queue-full",
            snapshot = exc.snapshot,
            request = request,
            mode = "chat_passthrough_stream",
            completion_id = completion_id,
            level = "warning",
        )
        api_monitor.fail(monitor_id, str(exc))
        raise _openai_admission_http_exception(exc, status_code = 429)
    except BaseException:
        _tracker.__exit__(None, None, None)
        raise

    lease = reservation.lease_nowait()
    if lease is not None:
        try:
            await _raise_if_openai_admission_cancelled(
                reservation,
                request = request,
                cancel_event = cancel_event,
            )
        except asyncio.CancelledError:
            api_monitor.finish(monitor_id, "cancelled")
            lease.release()
            _tracker.__exit__(None, None, None)
            raise
        except LlamaAdmissionCancelled as exc:
            lease.release()
            _tracker.__exit__(None, None, None)
            api_monitor.finish(monitor_id, "cancelled")
            raise HTTPException(
                status_code = 499,
                detail = _openai_admission_error_body(exc, status_code = 499),
            )
        return await _openai_passthrough_stream_admitted(
            request,
            cancel_event,
            llama_backend,
            payload,
            model_name,
            completion_id,
            monitor_id = monitor_id,
            admission_lease = lease,
            tracker = _tracker,
            prepared_body = prepared_body,
        )

    admission_wait_started_at = time.monotonic()
    _llama_admission_log(
        "queued",
        reservation,
        request = request,
        mode = "chat_passthrough_stream",
        completion_id = completion_id,
        level = "debug",
    )

    async def _queued_stream():
        admitted_started = False
        admitted_body_owns_cleanup = False
        admitted_response = None
        admitted_body_cancelled = False
        try:
            async for wait_item in _openai_admission_wait_stream_chunks(
                reservation,
                admission_config,
                request = request,
                cancel_event = cancel_event,
            ):
                if isinstance(wait_item, str):
                    yield wait_item
                    continue
                _llama_admission_log(
                    "granted-after-wait",
                    reservation,
                    request = request,
                    mode = "chat_passthrough_stream",
                    wait_started_at = admission_wait_started_at,
                    completion_id = completion_id,
                    level = "debug",
                )
                await _raise_if_openai_admission_cancelled(
                    reservation,
                    request = request,
                    cancel_event = cancel_event,
                )
                admitted_response = await _openai_passthrough_stream_admitted(
                    request,
                    cancel_event,
                    llama_backend,
                    payload,
                    model_name,
                    completion_id,
                    monitor_id = monitor_id,
                    admission_lease = wait_item,
                    tracker = _tracker,
                    prepared_body = prepared_body,
                )
                admitted_started = True
                iterator = admitted_response.body_iterator
                admitted_body_owns_cleanup = True
                try:
                    async for chunk in iterator:
                        yield chunk
                except asyncio.CancelledError:
                    admitted_body_cancelled = True
                    raise
                finally:
                    await _close_openai_admitted_stream_iterator(
                        iterator,
                        cancelled = admitted_body_cancelled,
                    )
                    if not admitted_body_owns_cleanup:
                        cleanup = getattr(admitted_response, "_unstarted_cleanup", None)
                        if cleanup is not None:
                            await cleanup()
                return
        except LlamaAdmissionTimeout as exc:
            _llama_admission_log(
                "timeout",
                reservation,
                request = request,
                mode = "chat_passthrough_stream",
                wait_started_at = admission_wait_started_at,
                completion_id = completion_id,
                level = "warning",
            )
            api_monitor.fail(monitor_id, str(exc))
            yield _openai_stream_error_sse(_openai_admission_error_body(exc, status_code = 503))
        except LlamaAdmissionCancelled:
            _llama_admission_log(
                "cancelled-before-upstream",
                reservation,
                request = request,
                mode = "chat_passthrough_stream",
                wait_started_at = admission_wait_started_at,
                completion_id = completion_id,
                level = "debug",
            )
            api_monitor.finish(monitor_id, "cancelled")
            return
        except asyncio.CancelledError:
            api_monitor.finish(monitor_id, "cancelled")
            raise
        except HTTPException as exc:
            status_code = getattr(exc, "status_code", 500) or 500
            detail = exc.detail
            error = (
                detail
                if isinstance(detail, dict) and "error" in detail
                else openai_error_body(str(detail), status = status_code)
            )
            api_monitor.fail(monitor_id, str(detail))
            yield _openai_stream_error_sse(error)
        finally:
            if not admitted_started:
                api_monitor.finish(monitor_id, "cancelled")
                reservation.cancel()
                _tracker.__exit__(None, None, None)

    async def _queued_unstarted_cleanup() -> None:
        api_monitor.finish(monitor_id, "cancelled")
        reservation.cancel()
        _tracker.__exit__(None, None, None)

    return _sse_streaming_response(
        _queued_stream(), unstarted_cleanup = _queued_unstarted_cleanup, monitor_id = monitor_id
    )


async def _openai_passthrough_stream_admitted(
    request,
    cancel_event,
    llama_backend,
    payload,
    model_name,
    completion_id,
    monitor_id: Optional[str] = None,
    *,
    admission_lease: LlamaAdmissionLease,
    tracker,
    prepared_body = None,
):
    """Reasoning and tool-call splitting stay with llama-server, so delta.content is not re-parsed."""
    _tracker = tracker
    upstream = _LlamaUpstream(llama_backend, "/v1/chat/completions")
    # A mid-stream error keeps HTTP 200, so flag the scope or the middleware claims a preview model.
    from core.inference.llama_keepwarm import mark_response_failed

    client = None
    resp = None
    send_task: Optional[asyncio.Task[Optional[httpx.Response]]] = None

    # Keep tracker cleanup paired if pre-header dispatch is cancelled.
    try:
        body = prepared_body
        if body is None:
            body = await _build_openai_passthrough_body_async(
                payload, backend_ctx = llama_backend.context_length, llama_backend = llama_backend
            )
        # The body builder is allowlisted, so the caller's opt-in lives in the extra fields.
        client_wants_progress = bool((payload.model_extra or {}).get("return_progress"))
        body["return_progress"] = True
        client_wants_usage = _wants_stream_usage(payload)
        upstream_stream_options = dict(body.get("stream_options") or {})
        upstream_stream_options["include_usage"] = True
        body["stream_options"] = upstream_stream_options
        # Promotes text-form calls for declared tools; off if auto_heal_tool_calls=false or tool_choice none.
        _allowed_tools = heal_gate(
            payload.auto_heal_tool_calls,
            body.get("tools"),
            body.get("tool_choice"),
            response_format = body.get("response_format"),
        )

        # Keep the pre-header window short so accepted SSE clients receive
        # immediate headers in the common timeout-reduced stall.
        client = _llama_stream_client()
        _truncate_policy = _overflow_truncation_policy(payload)
        _truncate_budget = _OVERFLOW_TRUNCATE_MAX_RETRIES if _truncate_policy else 0
        _uncut_messages, _cut_scope, _truncated_messages = await _prepare_passthrough_cut(
            llama_backend, body, _truncate_policy
        )
        _context_was_truncated = _truncated_messages > 0

        def _dispatch():
            return upstream.dispatch_stream(
                client, body, cancel_event, request, mark_cancel_on_cancel = False
            )

        def _apply_passthrough_truncation(err_text: str) -> bool:
            nonlocal _context_was_truncated, _truncated_messages
            dropped = _apply_measured_overflow_truncation(body, err_text, _truncate_policy)
            if dropped is None:
                return False
            _context_was_truncated = True
            _truncated_messages += dropped
            _remember_passthrough_cut(
                _uncut_messages, body, _truncate_policy, _truncated_messages, _cut_scope
            )
            return True

        while True:
            try:
                send_task = _dispatch()
                done, _ = await asyncio.wait(
                    {send_task},
                    timeout = _OPENAI_PASSTHROUGH_PREHEADER_STATUS_WINDOW_S,
                    return_when = asyncio.FIRST_COMPLETED,
                )
                if send_task not in done:
                    break

                # Dispatch returned quickly enough to preserve pre-header status.
                resp = await send_task
                send_task = None
            except httpx.RequestError as e:
                logger.error("openai passthrough stream: upstream unreachable: %s", e)
                api_monitor.fail(monitor_id, _friendly_error(e))
                # Nested so a cancel inside _aclose_send_task's wait cannot skip the closes.
                try:
                    await _aclose_send_task(send_task)
                finally:
                    try:
                        await _aclose_stream_resources(resp = resp, client = client)
                    finally:
                        _release_admission(admission_lease, _tracker)
                raise HTTPException(
                    status_code = 502,
                    detail = _friendly_error(e),
                )
            if resp is None and send_task is not None and not send_task.done():
                break
            if resp is None:
                if cancel_event is not None:
                    cancel_event.set()
                api_monitor.finish(monitor_id, "cancelled")
                try:
                    await _aclose_send_task(send_task)
                finally:
                    try:
                        await _aclose_stream_resources(client = client)
                    finally:
                        _release_admission(admission_lease, _tracker)
                return _SameTaskStreamingResponse(
                    iter(()),
                    media_type = "text/event-stream",
                    headers = _monitor_response_headers(
                        {
                            "Cache-Control": "no-cache",
                            "Connection": "keep-alive",
                            "X-Accel-Buffering": "no",
                        },
                        monitor_id,
                    ),
                )

            if resp.status_code == 200:
                break
            err_bytes = await resp.aread()
            err_text = err_bytes.decode("utf-8", errors = "replace")
            logger.error(
                "openai passthrough upstream error: status=%s body=%s",
                resp.status_code,
                err_text[:500],
            )
            upstream_status = resp.status_code
            try:
                await resp.aclose()
            except Exception:
                pass
            resp = None
            # Opt-in overflow policy: shrink and retry instead of a fatal 400.
            if (
                _truncate_budget > 0
                and _classify_llama_generation_error(Exception(err_text))
                and _apply_passthrough_truncation(err_text)
            ):
                _truncate_budget -= 1
                continue
            try:
                await client.aclose()
            except Exception:
                pass
            api_monitor.fail(monitor_id, err_text[:500])
            raise _openai_passthrough_error(upstream_status, err_text)

        # Keep tracker cleanup paired even if pre-header dispatch is cancelled after headers are committed.
        async def _stream():
            # Same httpx lifecycle pattern as _anthropic_passthrough_stream (aclose lines_iter on our task).
            lines_iter = None
            items_iter = None
            # Watchers unblock aiter_lines() during prefill, before in-loop cancel/disconnect checks can run.
            cancel_watcher = None
            disconnect_watcher = None

            nonlocal resp, send_task, _truncate_budget, client
            monitor_done = False
            saw_finish_reason = False
            saw_done = False
            saw_stream_error = False
            saw_stream_item = False
            saw_tool_call_delta = False
            terminal_seen = False
            last_chunk_id = completion_id
            last_chunk_model = model_name
            last_chunk_created = int(time.time())
            healer = (
                StreamToolCallHealer(_allowed_tools, body.get("tools")) if _allowed_tools else None
            )
            healed_call_index = 0

            def _synthetic_finish_line() -> str:
                healed = healer is not None and healer.healed
                finish_reason = "tool_calls" if (saw_tool_call_delta or healed) else "stop"
                chunk = ChatCompletionChunk(
                    id = last_chunk_id,
                    created = last_chunk_created,
                    model = last_chunk_model,
                    choices = [
                        ChunkChoice(
                            delta = ChoiceDelta(),
                            finish_reason = finish_reason,
                        )
                    ],
                )
                return f"data: {chunk.model_dump_json(exclude_none = True)}"

            def _healer_sse_lines(events) -> list:
                # Healer events are chunks carrying the upstream id/model/created, so clients see one completion.
                nonlocal healed_call_index
                lines = []
                for kind, value in events:
                    if kind == "text":
                        if not value:
                            continue
                        delta = {"content": value}
                    else:
                        # parallel_tool_calls=false caps healed calls too (the SSE cap only sees upstream deltas).
                        if payload.parallel_tool_calls is False and healed_call_index >= 1:
                            continue
                        delta = {
                            "tool_calls": [
                                {
                                    "index": healed_call_index,
                                    "id": value["id"],
                                    "type": "function",
                                    "function": value["function"],
                                }
                            ]
                        }
                        healed_call_index += 1
                    chunk = {
                        "id": last_chunk_id,
                        "object": "chat.completion.chunk",
                        "created": last_chunk_created,
                        "model": last_chunk_model,
                        "choices": [{"index": 0, "delta": delta, "finish_reason": None}],
                    }
                    lines.append("data: " + json.dumps(chunk, ensure_ascii = False))
                return lines

            stall_timeout_s = _openai_compat_stream_stall_timeout()

            def _terminal_read_timeout_s() -> Optional[float]:
                if terminal_seen:
                    return (
                        _OPENAI_PASSTHROUGH_TERMINAL_GRACE_S
                        if client_wants_usage
                        else _OPENAI_INTERNAL_USAGE_GRACE_S
                    )
                return stall_timeout_s

            def _heal_transform(chunk_data: dict, raw_line: str) -> list:
                """SSE lines to emit in place of one upstream line (healing on)."""
                choices = chunk_data.get("choices")
                if not (isinstance(choices, list) and choices and isinstance(choices[0], dict)):
                    return [raw_line]
                choice = choices[0]
                delta = choice.get("delta")
                delta = delta if isinstance(delta, dict) else {}
                if delta.get("tool_calls"):
                    # Grammar mode worked: flush any held text that preceded the call, then relay verbatim from here on.
                    lines = _healer_sse_lines(healer.structured_tool_call_seen())
                    if healed_call_index:
                        if payload.parallel_tool_calls is False:
                            # A healed call used the single slot; drop the native call or the client gets two.
                            del delta["tool_calls"]
                            if delta or choice.get("finish_reason") or chunk_data.get("usage"):
                                lines.append("data: " + json.dumps(chunk_data, ensure_ascii = False))
                            return lines
                        # Clients merge tool-call deltas by index, so shift native calls past the healed ones.
                        for tc in delta["tool_calls"]:
                            if isinstance(tc, dict) and isinstance(tc.get("index"), int):
                                tc["index"] += healed_call_index
                        return lines + ["data: " + json.dumps(chunk_data, ensure_ascii = False)]
                    return lines + [raw_line]
                content = delta.get("content")
                finish = choice.get("finish_reason")
                if not isinstance(content, str) or not content:
                    if not finish:
                        return [raw_line]
                    # On the finish chunk, heal the residue one last time and rewrite "stop" to "tool_calls" if healed.
                    lines = _healer_sse_lines(healer.finalize())
                    if healer.healed and finish == "stop":
                        choice["finish_reason"] = "tool_calls"
                        return lines + ["data: " + json.dumps(chunk_data, ensure_ascii = False)]
                    return lines + [raw_line]
                events = healer.feed(content)
                if finish:
                    events += healer.finalize()
                if not finish and events == [("text", content)]:
                    # Nothing held or promoted: the healer passed the chunk whole, so keep the verbatim upstream bytes.
                    return [raw_line]
                del delta["content"]
                prefix_lines = []
                if delta:
                    prefix_chunk = {k: v for k, v in chunk_data.items() if k != "usage"}
                    prefix_choice = dict(choice)
                    prefix_choice["delta"] = dict(delta)
                    prefix_choice["finish_reason"] = None
                    prefix_chunk["choices"] = [prefix_choice]
                    prefix_lines.append("data: " + json.dumps(prefix_chunk, ensure_ascii = False))
                    delta.clear()
                lines = prefix_lines + _healer_sse_lines(events)
                if delta or finish or chunk_data.get("usage"):
                    if healer.healed and finish == "stop":
                        choice["finish_reason"] = "tool_calls"
                    lines.append("data: " + json.dumps(chunk_data, ensure_ascii = False))
                return lines

            try:
                while True:
                    if send_task is not None:
                        last_keepalive_at = time.monotonic()
                        while not send_task.done():
                            # Wake often so cancel/disconnect latency stays sub-second during prefill.
                            wait_timeout = min(
                                _STREAM_DISCONNECT_POLL_TIMEOUT_S,
                                _OPENAI_PASSTHROUGH_PENDING_RESPONSE_KEEPALIVE_S,
                            )
                            done, _ = await asyncio.wait(
                                {send_task},
                                timeout = wait_timeout,
                                return_when = asyncio.FIRST_COMPLETED,
                            )
                            if send_task in done:
                                break
                            if await _preheader_cancelled(cancel_event, request):
                                api_monitor.finish(monitor_id, "cancelled")
                                return
                            # Keep proxies from treating a long prefill/header wait as a dead stream.
                            now = time.monotonic()
                            if (
                                now - last_keepalive_at
                                >= _OPENAI_PASSTHROUGH_PENDING_RESPONSE_KEEPALIVE_S
                            ):
                                last_keepalive_at = now
                                yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                        if resp is None:
                            try:
                                resp = send_task.result()
                            except httpx.RequestError as e:
                                logger.error(
                                    "openai passthrough stream: upstream unreachable: %s", e
                                )
                                api_monitor.fail(monitor_id, _friendly_error(e))
                                yield _openai_stream_error_sse(_openai_stream_error_chunk(e))
                                return
                            send_task = None

                    if resp is None:
                        api_monitor.finish(monitor_id, "cancelled")
                        return
                    if resp.status_code == 200:
                        break

                    err_bytes = await resp.aread()
                    err_text = err_bytes.decode("utf-8", errors = "replace")
                    logger.error(
                        "openai passthrough upstream error: status=%s body=%s",
                        resp.status_code,
                        err_text[:500],
                    )
                    upstream_status = resp.status_code
                    try:
                        await resp.aclose()
                    except Exception:
                        pass
                    resp = None
                    if (
                        _truncate_budget > 0
                        and _classify_llama_generation_error(Exception(err_text))
                        and _apply_passthrough_truncation(err_text)
                    ):
                        _truncate_budget -= 1
                        send_task = _dispatch()
                        continue

                    upstream_error = _openai_passthrough_error(upstream_status, err_text)
                    error_payload = (
                        upstream_error.detail
                        if isinstance(upstream_error.detail, dict)
                        else openai_error_body(
                            str(upstream_error.detail),
                            status = upstream_status,
                        )
                    )
                    api_monitor.fail(monitor_id, err_text[:500])
                    yield _openai_stream_error_sse(error_payload)
                    return

                if _context_was_truncated:
                    yield _context_truncated_sse_chunk(
                        completion_id,
                        model_name,
                        {
                            "dropped_messages": _truncated_messages,
                            "fits": True,
                        },
                    )
                cancel_watcher = asyncio.create_task(_await_cancel_then_close(cancel_event, resp))
                disconnect_watcher = asyncio.create_task(
                    _await_disconnect_then_close(request, resp, cancel_event)
                )
                lines_iter = resp.aiter_lines()
                _keepalive_s = _openai_passthrough_stream_keepalive_interval()
                items_iter = _aiter_llama_stream_items(
                    lines_iter,
                    cancel_event = cancel_event,
                    request = request,
                    first_token_deadline = upstream.first_token_deadline,
                    response = resp,
                    track_prefill_progress = True,
                    post_first_item_read_timeout_s = _terminal_read_timeout_s,
                    keepalive_interval_s = _keepalive_s,
                )
                progress_keepalive = _ProgressKeepalive(_keepalive_s)
                async for raw_line in items_iter:
                    if raw_line is _LLAMA_STREAM_KEEPALIVE:
                        yield _OPENAI_PASSTHROUGH_SSE_KEEPALIVE
                        continue
                    if not raw_line:
                        continue
                    if not raw_line.startswith("data:"):
                        continue
                    saw_stream_item = True
                    data_text = raw_line[5:].strip()
                    if data_text == "[DONE]":
                        saw_done = True
                        # Heal the residue first so the synthetic finish sees healer.healed.
                        if healer is not None and not saw_stream_error:
                            for held_line in _healer_sse_lines(healer.finalize()):
                                _monitor_openai_sse_line(
                                    monitor_id, held_line, llama_backend.context_length
                                )
                                yield held_line + "\n\n"
                        if (
                            not saw_finish_reason
                            and not saw_stream_error
                            and not cancel_event.is_set()
                        ):
                            finish_line = _synthetic_finish_line()
                            _monitor_openai_sse_line(
                                monitor_id,
                                finish_line,
                                llama_backend.context_length,
                            )
                            yield finish_line + "\n\n"
                            saw_finish_reason = True
                        _monitor_openai_sse_line(
                            monitor_id,
                            raw_line,
                            llama_backend.context_length,
                        )
                        yield raw_line + "\n\n"
                        monitor_done = True
                        break
                    raw_line, chunk_data = _normalize_openai_passthrough_sse_line_and_data(
                        raw_line,
                        cap_parallel_tool_calls = payload.parallel_tool_calls is False,
                    )
                    if chunk_data is _SSE_LINE_UNPARSED:
                        data_text = raw_line[5:].strip()
                        try:
                            chunk_data = json.loads(data_text)
                        except json.JSONDecodeError:
                            chunk_data = None
                    if isinstance(chunk_data, dict):
                        if isinstance(chunk_data.get("id"), str):
                            last_chunk_id = chunk_data["id"]
                        if isinstance(chunk_data.get("model"), str):
                            last_chunk_model = chunk_data["model"]
                        if isinstance(chunk_data.get("created"), int):
                            last_chunk_created = chunk_data["created"]
                        choices = chunk_data.get("choices")
                        if isinstance(choices, list) and choices:
                            choice = choices[0]
                            if isinstance(choice, dict):
                                if choice.get("finish_reason"):
                                    saw_finish_reason = True
                                delta = choice.get("delta")
                                if isinstance(delta, dict) and delta.get("tool_calls"):
                                    saw_tool_call_delta = True
                        # Detect errors even if skip_api_monitor returns early, else a synthetic finish fires after failure.
                        if _monitor_openai_error_message(chunk_data):
                            saw_stream_error = True
                            mark_response_failed(getattr(request, "scope", None))
                    if not client_wants_progress and _is_prefill_progress_only(chunk_data):
                        # chunk_data decodes raw_line (a data: line), so skip the monitor's re-parse.
                        _monitor_openai_sse_data(
                            monitor_id, chunk_data, llama_backend.context_length
                        )
                        if progress_keepalive.due():
                            yield _OPENAI_PREFILL_PROGRESS_SSE
                        continue
                    # With healing on, a content line may become held or promoted chunks; else it relays unchanged.
                    if (
                        healer is not None
                        and not healer.dormant
                        and isinstance(chunk_data, dict)
                        and not saw_stream_error
                    ):
                        out_lines = _heal_transform(chunk_data, raw_line)
                    else:
                        out_lines = [raw_line]
                    # Usage-only chunk before finish: emit synthetic finish first, so order is finish, usage, [DONE].
                    if (
                        isinstance(chunk_data, dict)
                        and chunk_data.get("usage")
                        and not (
                            isinstance(chunk_data.get("choices"), list) and chunk_data["choices"]
                        )
                        and not saw_finish_reason
                        and not saw_stream_error
                        and not cancel_event.is_set()
                    ):
                        if healer is not None:
                            # Residue must precede the finish it may upgrade.
                            held = _healer_sse_lines(healer.finalize())
                            for held_line in held:
                                _monitor_openai_sse_line(
                                    monitor_id, held_line, llama_backend.context_length
                                )
                                yield held_line + "\n\n"
                        finish_line = _synthetic_finish_line()
                        _monitor_openai_sse_line(
                            monitor_id, finish_line, llama_backend.context_length
                        )
                        yield finish_line + "\n\n"
                        saw_finish_reason = True
                    for out_line in out_lines:
                        monitor_event = (
                            # The healer leaves chunk_data untouched whenever it relays raw_line.
                            _monitor_openai_sse_data(
                                monitor_id, chunk_data, llama_backend.context_length
                            )
                            if out_line is raw_line and chunk_data is not None
                            else _monitor_openai_sse_line(
                                monitor_id,
                                out_line,
                                llama_backend.context_length,
                            )
                        )
                        if monitor_event == "error":
                            saw_stream_error = True
                            mark_response_failed(getattr(request, "scope", None))
                        terminal_state = (
                            _openai_passthrough_terminal_state_from_data(chunk_data)
                            if out_line is raw_line
                            else _openai_passthrough_sse_line_terminal_state(out_line)
                        )
                        # Usage is always requested for accounting but shown to the caller only by opt-in.
                        if terminal_state != "usage" or client_wants_usage:
                            yield out_line + "\n\n"
                        if monitor_event == "done":
                            monitor_done = True
                            break
                        if terminal_state == "usage":
                            done_line = _SSE_DONE_LINE
                            _monitor_openai_sse_line(
                                monitor_id,
                                done_line,
                                llama_backend.context_length,
                            )
                            yield done_line + "\n\n"
                            saw_done = True
                            monitor_done = True
                            break
                        if terminal_state == "finish":
                            terminal_seen = True
                    if monitor_done:
                        break
                if not saw_done and not saw_stream_error and not cancel_event.is_set():
                    # Synthesize a finish chunk only if none was sent; always end with [DONE] even if upstream omits it.
                    if healer is not None:
                        for held_line in _healer_sse_lines(healer.finalize()):
                            _monitor_openai_sse_line(
                                monitor_id, held_line, llama_backend.context_length
                            )
                            yield held_line + "\n\n"
                    if not saw_finish_reason:
                        finish_line = _synthetic_finish_line()
                        _monitor_openai_sse_line(
                            monitor_id,
                            finish_line,
                            llama_backend.context_length,
                        )
                        yield finish_line + "\n\n"
                    done_line = _SSE_DONE_LINE
                    _monitor_openai_sse_line(
                        monitor_id,
                        done_line,
                        llama_backend.context_length,
                    )
                    yield done_line + "\n\n"
                    monitor_done = True
                if not monitor_done:
                    api_monitor.finish(
                        monitor_id,
                        "cancelled" if cancel_event.is_set() else "completed",
                    )
            except asyncio.CancelledError:
                api_monitor.finish(monitor_id, "cancelled")
                raise
            except httpx.ReadTimeout as e:
                if terminal_seen and not saw_stream_error and not cancel_event.is_set():
                    done_line = _SSE_DONE_LINE
                    _monitor_openai_sse_line(
                        monitor_id,
                        done_line,
                        llama_backend.context_length,
                    )
                    yield done_line + "\n\n"
                    api_monitor.finish(monitor_id)
                    return
                if cancel_event.is_set():
                    api_monitor.finish(monitor_id, "cancelled")
                    return
                logger.error(
                    "openai passthrough stream %s: %s",
                    "stalled mid-response" if saw_stream_item else "timeout",
                    e,
                )
                api_monitor.fail(monitor_id, _friendly_error(e))
                get_llama_cpp_backend()._maybe_recover_from_mtp_crash(e)
                err = _openai_stream_error_chunk(e)
                yield _openai_stream_error_sse(err)
            except (httpx.RemoteProtocolError, httpx.ReadError, httpx.CloseError) as e:
                # Client cancelled or disconnected: emit nothing more, the watcher already closed the response.
                if not cancel_event.is_set():
                    api_monitor.fail(monitor_id, "Stream interrupted")
                    get_llama_cpp_backend()._maybe_recover_from_mtp_crash(e)
                    # Headers flushed and no error SSE: flag failed so a preview-owned model isn't claimed.
                    mark_response_failed(getattr(request, "scope", None))
                    raise
                api_monitor.finish(monitor_id, "cancelled")
            except HTTPException as exc:
                status_code = getattr(exc, "status_code", 500) or 500
                detail = exc.detail
                error_payload = (
                    detail
                    if isinstance(detail, dict) and "error" in detail
                    else openai_error_body(str(detail), status = status_code)
                )
                api_monitor.fail(monitor_id, str(detail))
                yield _openai_stream_error_sse(error_payload)
            except Exception as e:
                if cancel_event.is_set():
                    api_monitor.finish(monitor_id, "cancelled")
                    return
                # 200 headers already flushed; errors must go in the SSE body.
                logger.error("openai passthrough stream error: %s", e)
                api_monitor.fail(monitor_id, _friendly_error(e))
                get_llama_cpp_backend()._maybe_recover_from_mtp_crash(e)
                err = _openai_stream_error_chunk(e)
                yield _openai_stream_error_sse(err)
            finally:
                if cancel_event.is_set():
                    mark_response_failed(getattr(request, "scope", None))
                # Close upstream before releasing the slot: llama-server keeps decoding until resp closes, so an
                # early release admits a request past --parallel. The closes are bounded.
                try:
                    await _aclose_send_task(send_task)
                finally:
                    try:
                        await _aclose_stream_resources(
                            watchers = (cancel_watcher, disconnect_watcher),
                            items = items_iter,
                            iterator = lines_iter,
                            resp = resp,
                            client = client,
                        )
                    finally:
                        _release_admission(admission_lease, _tracker)

        async def _unstarted_cleanup() -> None:
            # Disconnected before the body started, so _stream()'s finally never ran: release here.
            try:
                await _aclose_send_task(send_task)
            finally:
                try:
                    await _aclose_stream_resources(resp = resp, client = client)
                finally:
                    _release_admission(admission_lease, _tracker)

        return _sse_streaming_response(
            _stream(), unstarted_cleanup = _unstarted_cleanup, monitor_id = monitor_id
        )
    except BaseException as exc:
        if isinstance(exc, asyncio.CancelledError):
            if cancel_event is not None:
                cancel_event.set()
            api_monitor.finish(monitor_id, "cancelled")
        else:
            detail = exc.detail if isinstance(exc, HTTPException) else _friendly_error(exc)
            api_monitor.fail(monitor_id, str(detail))
        try:
            await _aclose_send_task(send_task)
        finally:
            try:
                await _aclose_stream_resources(resp = resp, client = client)
            finally:
                _release_admission(admission_lease, _tracker)
        raise


async def _openai_passthrough_non_streaming(
    llama_backend,
    payload,
    model_name,
    monitor_id: Optional[str] = None,
    *,
    request: Optional[Request] = None,
    cancel_event = None,
):
    """Non-streaming pass-through guarded by local llama-server admission."""
    try:
        reservation, admission_config, prepared_body = await _reserve_counted_gguf_passthrough(
            request = request,
            llama_backend = llama_backend,
            payload = payload,
        )
    except LlamaAdmissionQueueFull as exc:
        _llama_admission_log(
            "queue-full",
            snapshot = exc.snapshot,
            request = request,
            mode = "chat_passthrough_nonstream",
            level = "warning",
        )
        api_monitor.fail(monitor_id, str(exc))
        raise _openai_admission_http_exception(exc, status_code = 429)

    lease = None
    admission_wait_started_at = None
    try:
        if reservation.lease_nowait() is None:
            admission_wait_started_at = time.monotonic()
            _llama_admission_log(
                "queued",
                reservation,
                request = request,
                mode = "chat_passthrough_nonstream",
                level = "debug",
            )
        lease = await _wait_for_openai_admission_non_streaming(
            reservation,
            admission_config,
            request = request,
            cancel_event = cancel_event,
        )
        if admission_wait_started_at is not None:
            _llama_admission_log(
                "granted-after-wait",
                reservation,
                request = request,
                mode = "chat_passthrough_nonstream",
                wait_started_at = admission_wait_started_at,
                level = "debug",
            )
        await _raise_if_openai_admission_cancelled(
            reservation,
            request = request,
            cancel_event = cancel_event,
        )
        return await _openai_passthrough_non_streaming_upstream(
            llama_backend,
            payload,
            model_name,
            monitor_id = monitor_id,
            request = request,
            cancel_event = cancel_event,
            prepared_body = prepared_body,
        )
    except LlamaAdmissionTimeout as exc:
        _llama_admission_log(
            "timeout",
            reservation,
            request = request,
            mode = "chat_passthrough_nonstream",
            wait_started_at = admission_wait_started_at,
            level = "warning",
        )
        api_monitor.fail(monitor_id, str(exc))
        raise _openai_admission_http_exception(exc, status_code = 503)
    except LlamaAdmissionCancelled as exc:
        _llama_admission_log(
            "cancelled-before-upstream",
            reservation,
            request = request,
            mode = "chat_passthrough_nonstream",
            wait_started_at = admission_wait_started_at,
            level = "debug",
        )
        api_monitor.finish(monitor_id, "cancelled")
        raise HTTPException(
            status_code = 499,
            detail = _openai_admission_error_body(exc, status_code = 499),
        )
    except _NonStreamingRequestCancelled as exc:
        api_monitor.finish(monitor_id, "cancelled")
        raise _openai_admission_http_exception(exc, status_code = 499)
    except asyncio.CancelledError:
        api_monitor.finish(monitor_id, "cancelled")
        reservation.cancel()
        raise
    finally:
        if lease is not None:
            lease.release()


async def _openai_passthrough_non_streaming_upstream(
    llama_backend,
    payload,
    model_name,
    monitor_id: Optional[str] = None,
    *,
    request: Optional[Request] = None,
    cancel_event = None,
    prepared_body = None,
):
    """Returns llama-server's JSON verbatim, so the native id, finish_reason and usage reach the client."""
    body = prepared_body
    if body is None:
        body = await _build_openai_passthrough_body_async(
            payload, backend_ctx = llama_backend.context_length, llama_backend = llama_backend
        )
    body["stream"] = False
    body.pop("stream_options", None)

    _truncate_policy = _overflow_truncation_policy(payload)
    _truncate_budget = _OVERFLOW_TRUNCATE_MAX_RETRIES if _truncate_policy else 0
    _uncut_messages, _cut_scope, _truncated_messages = await _prepare_passthrough_cut(
        llama_backend, body, _truncate_policy
    )
    _context_was_truncated = _truncated_messages > 0

    def _apply_nonstream_truncation(err_text: str) -> bool:
        nonlocal _context_was_truncated, _truncated_messages
        dropped = _apply_measured_overflow_truncation(body, err_text, _truncate_policy)
        if dropped is None:
            return False
        _context_was_truncated = True
        _truncated_messages += dropped
        _remember_passthrough_cut(
            _uncut_messages, body, _truncate_policy, _truncated_messages, _cut_scope
        )
        return True

    upstream = _LlamaUpstream(
        llama_backend, "/v1/chat/completions", cancel_event = cancel_event, request = request
    )
    async with upstream:
        while True:
            try:
                resp = await upstream.post(body, timeout = _llama_non_streaming_generation_timeout())
            except asyncio.CancelledError:
                api_monitor.finish(monitor_id, "cancelled")
                raise
            except httpx.RequestError as e:
                # Still unreachable after the one respawn post() allows. The MTP recovery
                # stays for the errors that respawn declines.
                logger.error("openai passthrough non-streaming: upstream unreachable: %s", e)
                api_monitor.fail(monitor_id, _friendly_error(e))
                get_llama_cpp_backend()._maybe_recover_from_mtp_crash(e)
                raise HTTPException(
                    status_code = 502,
                    detail = _friendly_error(e),
                )

            if resp.status_code == 200:
                break
            # Opt-in overflow policy: shrink and retry instead of a fatal 400.
            if (
                _truncate_budget > 0
                and _classify_llama_generation_error(Exception(resp.text))
                and _apply_nonstream_truncation(resp.text)
            ):
                _truncate_budget -= 1
                continue
            api_monitor.fail(monitor_id, resp.text[:500])
            raise _openai_passthrough_error(resp.status_code, resp.text)

    # The ```json fence is opt-in for the internal data-recipe path; it breaks json.loads for others.
    _guided_fence = bool((payload.model_extra or {}).get("_unsloth_guided_fence"))
    _do_fence = _guided_fence and _extract_response_format(payload) is not None
    _cap_parallel = payload.parallel_tool_calls is False
    _allowed_tools = heal_gate(
        payload.auto_heal_tool_calls,
        body.get("tools"),
        body.get("tool_choice"),
        response_format = body.get("response_format"),
    )

    try:
        data = resp.json()
    except Exception as exc:
        # Non-JSON / unparseable upstream body: relay verbatim as before.
        logger.warning(
            "openai passthrough non-streaming: response not JSON, relaying raw: %s",
            exc,
        )
        api_monitor.finish(monitor_id)
        return Response(content = resp.content, media_type = "application/json")

    # Opt-in single-retry nudge with the prompt prefix intact (KV cache reuse); the retry replaces
    # the original only when it yields a usable call.
    usage_aggregated = False
    if (
        _allowed_tools
        and nudge_enabled(payload.nudge_tool_calls, response_format = body.get("response_format"))
        and nudge_should_retry(data, _allowed_tools, body.get("tools"))
    ):
        first_data = data
        retry_body = {
            **body,
            "messages": _nudge_retry_messages(
                body, data, _allowed_tools, getattr(llama_backend, "markup_profile", None)
            ),
        }
        try:
            async with upstream:
                retry_resp = await upstream.post(
                    retry_body, timeout = _llama_non_streaming_generation_timeout()
                )
            if retry_resp.status_code == 200:
                retry_data = retry_resp.json()
                if response_has_promotable_calls(retry_data, _allowed_tools, body.get("tools")):
                    resp = retry_resp
                    data = _sum_passthrough_attempt_stats(first_data, retry_data, retry_data)
                else:
                    data = _sum_passthrough_attempt_stats(first_data, retry_data, first_data)
                usage_aggregated = data is not first_data and data is not retry_data
        except asyncio.CancelledError:
            api_monitor.finish(monitor_id, "cancelled")
            raise
        except (httpx.RequestError, ValueError) as exc:
            logger.warning("tool-call nudge retry failed; keeping original: %s", exc)

    changed = usage_aggregated
    if _context_was_truncated and isinstance(data, dict):
        data["context_truncated"] = {
            "dropped_messages": _truncated_messages,
            "fits": True,
        }
        changed = True
    for choice in data.get("choices", []):
        if not isinstance(choice, dict):
            continue
        msg = choice.get("message")
        if not isinstance(msg, dict):
            continue

        # Promote text-form tool calls (declared tools only). Truncation wins: a call cut at max_tokens
        # keeps finish_reason='length'.
        if _allowed_tools and heal_openai_message(msg, _allowed_tools, body.get("tools")):
            if choice.get("finish_reason") == "stop":
                choice["finish_reason"] = "tool_calls"
            changed = True

        # OpenAI requires content=null on a pure tool-call turn; llama-server emits content=''.
        if msg.get("tool_calls") and msg.get("content") == "":
            msg["content"] = None
            changed = True

        # Honor parallel_tool_calls=false (best-effort) by capping to one call.
        if _cap_parallel:
            _tcs = msg.get("tool_calls")
            if isinstance(_tcs, list) and len(_tcs) > 1:
                msg["tool_calls"] = _tcs[:1]
                changed = True

        # Guided-decoding fence wrap (opt-in via _unsloth_guided_fence).
        if _do_fence:
            content = msg.get("content")
            if not isinstance(content, str):
                continue
            stripped = content.strip()
            if not stripped or stripped.startswith("```"):
                continue
            msg["content"] = f"```json\n{stripped}\n```"
            changed = True

    _monitor_openai_chunk(monitor_id, data, llama_backend.context_length)
    api_monitor.finish(monitor_id)
    if not changed:
        # Nothing mutated: relay the upstream bytes verbatim, skipping a redundant parse and re-serialize.
        return Response(content = resp.content, media_type = "application/json")
    return JSONResponse(content = data)


# ──────────────────────────────────────────────────────────────────────────
# Diffusion (local text-to-image). Unsloth-only routes (not mounted under /v1); the backend is
# synchronous, so blocking calls use asyncio.to_thread.
# ──────────────────────────────────────────────────────────────────────────


def _diffusion_training_active() -> bool:
    """Whether a diffusion (SDXL) LoRA job is running. Best-effort so a load is never
    blocked just because the training service could not be imported/read."""
    try:
        from core.training.diffusion_training_service import get_diffusion_training_service
        return get_diffusion_training_service().is_active()
    except Exception:  # noqa: BLE001
        return False


@contextmanager
def _diffusion_training_admission():
    """Register under the reserve() lock so start and load cannot overlap; 409 if reserved; fails open."""
    try:
        from core.training.diffusion_training_service import get_diffusion_training_service
        service = get_diffusion_training_service()
    except Exception:  # noqa: BLE001 -- unknowable state never blocks a load
        yield
        return
    with service.gpu_load_admission():
        yield


def _training_is_active() -> bool:
    """The non-raising half of the load guard, for callers that must not take the GPU."""
    from core.training import get_training_backend

    try:
        if get_training_backend().is_training_active():
            return True
    except Exception as e:  # noqa: BLE001 -- an unreadable LLM backend is not evidence of idle
        logger.warning("Could not check training state: %s", e)
    return _diffusion_training_active()


def _unload_native_video_sharing_the_sd_cpp_tree(policy: str = "off", evicted = None) -> None:
    """An off-torch image load skips the arbiter, a native H3 model's only evictor, yet may reinstall
    the managed sd.cpp tree that model runs from. Under Always that is refused instead."""
    from core.inference import gpu_arbiter
    from core.inference.video import get_video_backend

    from core.inference.video_minimax_h3 import H3_GGUF_REPO

    video = get_video_backend()
    # engine is published at commit; a downloading H3 load shows only in _loading, from begin_load on.
    loading = getattr(video, "_loading", None)
    h3_loading = (
        loading is not None
        and loading.error is None
        and H3_GGUF_REPO in (getattr(loading, "asset_repos", None) or ())
    )
    if h3_loading or video.status().get("engine") == "sd_cpp":
        slots = gpu_arbiter.resident_slots(gpu_arbiter.VIDEO) or [{"kind": "video", "model": ""}]
        if policy == "always":
            raise gpu_arbiter.refusal_for(slots, "video")
        logger.info("Unloading the native video model: the Images load replaces its sd.cpp build")
        video.unload()
        gpu_arbiter.release(gpu_arbiter.VIDEO)
        gpu_arbiter.note_evictions(slots, evicted)


def _activate_checked(check, activate):
    """``activate()`` with ``check`` run before an engine switch unloads the active engine."""
    from core.inference.diffusion_engine_router import before_engine_switch

    token = before_engine_switch.set(check)
    try:
        return activate()
    finally:
        before_engine_switch.reset(token)


def _activate_unless_cancelled(preflight, check, activate):
    """``_activate_checked``, refused before an engine switch unloads the active engine once an unload
    cancelled this load's preflight. The preflight lock is taken at that check and held until the
    switch is done (not through an sd-cli install before it), so a cancel lands before or after it."""
    if preflight is None:
        return _activate_checked(check, activate)
    from core.inference.chat_swap_kv import raise_if_load_cancelled

    held = []

    def _check():
        if not held:
            preflight.lock.acquire()
            held.append(True)
        raise_if_load_cancelled(_DIFFUSION_LOAD_CANCELLED)
        if check is not None:
            check()

    try:
        return _activate_checked(_check, activate)
    finally:
        if held:
            preflight.lock.release()


def _guard_diffusion_load_against_training() -> None:
    """Refuses image loads during training (409): diffusion VRAM not estimable; no-op if state unreadable."""
    from core.training import get_training_backend

    try:
        llm_active = get_training_backend().is_training_active()
    except Exception as e:
        # The two probes are independent: an unreadable LLM backend must not disable the diffusion interlock below.
        logger.warning("Could not check training state for image-load guard: %s", e)
        llm_active = False
    # An SDXL LoRA trainer runs in its own subprocess on the same GPU, so an image load must be refused while one is active.
    if not llm_active and not _diffusion_training_active():
        return
    raise HTTPException(
        status_code = 409,
        detail = (
            "Can't load an image model while training is running: the diffusion "
            "pipeline would compete with the training run for GPU memory. Training "
            "was left untouched. Try again after training finishes."
        ),
    )


def _fallback_refusal_http(exc: BaseException) -> HTTPException:
    from core.inference.gpu_arbiter import MultiModelAlwaysRefusal
    from core.inference.gpu_residency import ChatLoadInFlightRefusal

    if isinstance(exc, HTTPException):
        return exc
    if isinstance(exc, account_access.GpuBusyForAnotherAccountError):
        return account_access.gpu_busy_error()
    if isinstance(exc, (MultiModelAlwaysRefusal, ChatLoadInFlightRefusal)):
        return exc.as_http_exception()
    return HTTPException(status_code = 409, detail = str(exc))


def _mlx_fallback_load_gate(request, gpu_ordinal, multi_model_mode):
    """The image-load gates, for the MLX engine's diffusers fallback (which runs inside a generation).

    Fit check refuses instead of evicting: a generation must not unload another model. No
    note_resident_account / media_load_lock: the resident record and DIFFUSION claim stay the MLX
    load's, and the lock would stall against retire_media_load."""
    from core.inference.gpu_arbiter import DIFFUSION
    from core.inference.gpu_residency import (
        ChatLoadInFlightRefusal,
        forget_media_price,
        media_fit_kwargs,
        refuse_unless_fits,
    )
    from core.inference.mlx_diffusion_routing import FallbackLoadRefusedError

    def gate(start, cancel = None):
        with ExitStack() as stack:
            try:
                account_access.require_live_account()
                _guard_diffusion_load_against_training()
                fit = media_fit_kwargs(DIFFUSION, request, gpu_ordinal, multi_model_mode)
                stack.enter_context(_diffusion_training_admission())
                refuse_unless_fits(
                    DIFFUSION,
                    policy = fit.get("policy", "off"),
                    gpu_ids = fit.get("gpu_ids"),
                    # The price is the MLX load's; this diffusers load has none.
                    need_mib = None,
                    cancel = cancel,
                )
            except (HTTPException, ChatLoadInFlightRefusal, RuntimeError) as exc:
                if cancel is not None and cancel.is_set():
                    raise
                raise FallbackLoadRefusedError(_fallback_refusal_http(exc)) from exc
            for ref in (
                request.model_path,
                request.base_repo,
                *(
                    r
                    for r in account_access.media_component_file_references(request)
                    if r and not Path(r).is_absolute()
                ),
            ):
                if ref and _repo_is_in_the_hub_cache(ref) is not True:
                    _note_load_fetched_with_a_request_token(ref, request.hf_token)
            forget_media_price(DIFFUSION, cancel)
            return start()

    return gate


def _fallback_gate_kwarg(begin_load, gate) -> dict:
    try:
        import inspect
        if "fallback_gate" in inspect.signature(begin_load).parameters:
            return {"fallback_gate": gate}
    except (TypeError, ValueError):
        pass
    return {}


async def _selected_gpu_ordinal(gpu_ids, *, allow_ranking: bool = True) -> Optional[int]:
    """The torch ordinal for a request's ``gpu_ids``, or None when there is nothing to honour.

    Physical ids have no applicator off CUDA / ROCm, which the contract says to ignore rather than
    refuse, so the resolver only runs once the target reports a CUDA device. Raises ValueError for
    a bad pick, which every caller maps to a 400.

    ``allow_ranking = False`` drops only the free-VRAM comparison, for the plan routes while a
    trainer holds the cards: the ids are still validated and translated (mask plus nvidia-smi, no
    CUDA context), so a bad pick is refused at the plan rather than tens of gigabytes later.
    """
    from core.inference import diffusion_device
    from core.inference.diffusion_device import (
        resolve_diffusion_device_target,
        resolve_selected_cuda_ordinal,
    )
    from core.inference.diffusion_memory import snapshot_upcoming_load_budget

    snapshot_upcoming_load_budget()
    if not gpu_ids:
        if not allow_ranking:
            return None
        # An auto-switch load uses the card its locality check planned against.
        from core.inference.media_locality import planned_gpu_ordinal

        pinned, ordinal = planned_gpu_ordinal()
        if pinned:
            return ordinal
        # Zero / one GPU, ROCm, Apple and CPU: nothing to rank, so no device or dtype probe either.
        possible = diffusion_device.auto_cuda_ranking_possible_cached()
        if possible is None:  # would probe: off the event loop
            possible = await asyncio.to_thread(diffusion_device.auto_cuda_ranking_possible)
        if not possible:
            return None
        device = await asyncio.to_thread(lambda: resolve_diffusion_device_target().device)
        if device != "cuda":
            return None
        # Automatic ranks the visible cards too (#8235); the current device is PCI slot 0.
        # Pinned for this request, so begin_load's own fallback reuses it (None included).
        ordinal = await asyncio.to_thread(diffusion_device.resolve_auto_cuda_ordinal)
        diffusion_device._PLANNED_ORDINAL.set(ordinal)
        return ordinal
    device = await asyncio.to_thread(lambda: resolve_diffusion_device_target().device)
    if device != "cuda":
        return None
    # Pass the keyword only when non-default, so a monkeypatched one-arg resolver still fits.
    if allow_ranking:
        return await asyncio.to_thread(resolve_selected_cuda_ordinal, gpu_ids)
    return await asyncio.to_thread(
        lambda: resolve_selected_cuda_ordinal(gpu_ids, allow_ranking = False)
    )


def _refuse_disabled_nvfp4_request(request: Any) -> None:
    """Refuses NVFP4 with 400 while UNSLOTH_NVFP4_DIFFUSION is off, ahead of any precision fallback."""
    from core.inference.diffusion_nvfp4_flag import refuse_disabled_nvfp4
    try:
        refuse_disabled_nvfp4(
            transformer_quant = getattr(request, "transformer_quant", None),
            text_encoder_quant = getattr(request, "text_encoder_quant", None),
        )
    except ValueError as exc:
        raise HTTPException(status_code = 400, detail = str(exc))


async def _refuse_disabled_nvfp4_checkpoint(request: Any) -> None:
    """400 on an NVFP4 checkpoint named as the model while the switch is off; runs after account checks"""
    from core.inference.diffusion_nvfp4_flag import (
        nvfp4_diffusion_enabled,
        refuse_disabled_nvfp4_checkpoint,
    )

    if nvfp4_diffusion_enabled():
        return
    try:
        await asyncio.to_thread(
            refuse_disabled_nvfp4_checkpoint,
            getattr(request, "model_path", None),
            getattr(request, "base_repo", None),
        )
    except ValueError as exc:
        raise HTTPException(status_code = 400, detail = str(exc))


def _component_file_kwargs(request: DiffusionLoadRequest) -> dict:
    """Empty when none, so the native engine and older callers see the same keywords as before."""
    files = getattr(request, "text_encoder_file", None)
    files = [files] if isinstance(files, str) else list(files or ())
    out: dict = {}
    if files:
        out["text_encoder_files"] = files
    vae_file = getattr(request, "vae_file", None)
    if vae_file:
        out["vae_file"] = vae_file
    return out


def _refuse_native_component_files(request: DiffusionLoadRequest) -> None:
    if _component_file_kwargs(request):
        raise HTTPException(
            status_code = 400,
            detail = "Separate text-encoder / VAE files load on the diffusers engine (a CUDA / ROCm GPU); "
            "this host routes the pick to the native engine. Omit text_encoder_file / vae_file.",
        )


def _mlx_load_blocker(request: DiffusionLoadRequest) -> Optional[str]:
    from core.inference.diffusion_engine_router import mlx_load_blocker
    return mlx_load_blocker(
        loras = request.loras,
        component_files = _component_file_kwargs(request),
        transformer_quant = request.transformer_quant,
        text_encoder_quant = request.text_encoder_quant,
    )


def _has_active_loras(loras: Any) -> bool:
    from core.inference.diffusion_engine_router import has_active_loras
    return has_active_loras(loras)


def _refuse_mlx_loras(request: DiffusionLoadRequest) -> None:
    # Zero-weight entries are dropped before loading, so only an applied adapter is refused.
    if _has_active_loras(request.loras):
        raise HTTPException(
            status_code = 400,
            detail = "LoRA adapters are not supported on the MLX engine yet.",
        )


@studio_router.post("/images/download-plan", response_model = DiffusionDownloadPlanResponse)
async def diffusion_download_plan(
    request: DiffusionLoadRequest, current_subject: str = Depends(get_current_subject)
):
    """The repos + files this pick needs, so the frontend can stage them through the Hub
    download manager (one mechanism, one panel) instead of the loader downloading inline.

    Validates the same way /images/load does, so an unloadable pick fails here rather than
    after a multi-GB download."""
    _refuse_disabled_nvfp4_request(request)
    if account_access.managed_account():
        await asyncio.to_thread(account_access.require_media_references, request)
    if account_access.managed_account():
        await asyncio.to_thread(account_access.require_model_access, request.model_path)
    if request.base_repo:
        if account_access.managed_account():
            await asyncio.to_thread(account_access.require_model_access, request.base_repo)
    if account_access.managed_account():
        request = request.model_copy(
            update = {"hf_token": account_access.account_hf_token(request.hf_token)}
        )
    await _refuse_disabled_nvfp4_checkpoint(request)
    from core.inference.diffusion import (
        get_diffusion_backend,
        split_local_checkpoint_path,
        resolve_model_kind,
    )
    from core.inference.diffusion_local_files import resolve_local_single_file
    from core.inference.diffusion_engine_router import predict_engine
    from core.inference.diffusion_hub_evidence import prefetch_for_pick
    from core.inference.sd_cpp_engine import ENGINE_MLX, ENGINE_SD_CPP
    from utils.native_path_leases import redact_native_paths

    backend = get_diffusion_backend()
    try:
        kind = resolve_model_kind(request.gguf_filename, request.model_kind)
        # Same bare-single-file-directory reinterpretation as the load route, so the plan describes the load that will actually run.
        if kind == "pipeline" and not request.gguf_filename:
            split = await asyncio.to_thread(split_local_checkpoint_path, request.model_path)
            if split is not None:
                request.model_path, request.gguf_filename = split
                kind = resolve_model_kind(split[1])
            sole = (
                None
                if split is not None
                else await asyncio.to_thread(resolve_local_single_file, request.model_path)
            )
            if sole is not None:
                request.gguf_filename = sole
                kind = resolve_model_kind(sole)
        # A Hub repo named for no family (an SDXL fine-tune) says what it is in its own model_index.json or checkpoint
        # header; fetch that small evidence first so the network-free validation below can read it.
        await asyncio.to_thread(
            prefetch_for_pick,
            request.model_path,
            request.gguf_filename,
            request.family_override,
            request.hf_token,
        )
        fam = await asyncio.to_thread(
            backend.validate_load_request,
            request.model_path,
            gguf_filename = request.gguf_filename,
            family_override = request.family_override,
            model_kind = kind,
            base_repo = request.base_repo,
            **_component_file_kwargs(request),
        )
        # The same refusal the load gives an engine pick that cannot serve this model, before anything is staged.
        from core.inference.diffusion_engine_router import refuse_engine_pick

        refuse_engine_pick(fam, engine = request.engine, model_kind = kind)
        planner = backend
        # Precision is checked BEFORE staging so an unsupported FP8 isn't downloaded then refused, but not
        # while training (an uncached probe initialises CUDA). Ranking also waits until training is idle.
        gpu_ordinal = None
        training = fam is not None and await asyncio.to_thread(_training_is_active)
        if fam is not None:
            gpu_ordinal = await _selected_gpu_ordinal(request.gpu_ids, allow_ranking = not training)
        # Plan for the engine /images/load will pick: a GGUF on a GPU-less host routes to native
        # sd.cpp, which reads different files. Card-scoped, since the failure records are per card.
        predicted = (
            predict_engine(
                fam,
                model_kind = kind,
                gpu_ordinal = gpu_ordinal,
                gguf_filename = request.gguf_filename,
                engine = request.engine,
                with_loras = _has_active_loras(request.loras),
                mlx_blocker = _mlx_load_blocker(request),
            )
            if fam is not None
            else None
        )
        if predicted == ENGINE_SD_CPP:
            _refuse_native_component_files(request)
            from core.inference.sd_cpp_backend import get_sd_cpp_backend
            planner = get_sd_cpp_backend()
        elif predicted == ENGINE_MLX:
            _refuse_native_component_files(request)
            _refuse_mlx_loras(request)
            from core.inference.mlx_diffusion_backend import get_mlx_diffusion_backend

            planner = get_mlx_diffusion_backend()
        # The native refusal is value-only (no GPU), so it runs during training too: only the diffusers probe waits.
        if fam is not None and planner is not backend:
            _assert_native_precision_unset(
                transformer_quant = request.transformer_quant,
                text_encoder_quant = request.text_encoder_quant,
            )
        if fam is not None and not training:
            if planner is backend:
                await asyncio.to_thread(
                    backend.assert_precision_available,
                    fam,
                    model_kind = kind,
                    transformer_quant = request.transformer_quant,
                    text_encoder_quant = request.text_encoder_quant,
                    # Memory mode settles offload policy before measuring; an offloaded transformer skips dense quant.
                    memory_mode = getattr(request, "memory_mode", None),
                    cpu_offload = bool(getattr(request, "cpu_offload", False)),
                    # An uncompiled torchao transformer is slower than bf16, so eager stays dense.
                    speed_mode = getattr(request, "speed_mode", None),
                    # Judged on the card this pick would load on, as the loader does.
                    gpu_ordinal = gpu_ordinal,
                    repo_id = request.model_path,
                    base_repo = request.base_repo,
                    text_encoder_files = request.supplied_text_encoder_files(),
                    gguf_filename = request.gguf_filename,
                )
        from core.inference.diffusion_memory import unified_oversize_scoped

        plan = await asyncio.to_thread(
            unified_oversize_scoped(request.allow_oversized_load, planner.download_plan),
            request.model_path,
            gpu_ordinal = gpu_ordinal,
            gguf_filename = request.gguf_filename,
            base_repo = request.base_repo,
            family_override = request.family_override,
            model_kind = kind,
            hf_token = request.hf_token,
            transformer_quant = request.transformer_quant,
            # An fp8 encoder request loads a hosted pre-cast checkpoint, so the plan must stage that file instead of the dense encoder shards.
            text_encoder_quant = request.text_encoder_quant,
            speed_mode = request.speed_mode,
            # The dense-quant prefetch decision also reads the memory policy, prequant path and adapter selection, so the plan must see the same values the load will.
            memory_mode = request.memory_mode,
            cpu_offload = request.cpu_offload,
            transformer_prequant_path = request.transformer_prequant_path,
            # Forced accumulate the checkpoint cannot bake declines the seed, else the plan stages a refused file
            transformer_quant_fast_accum = request.transformer_quant_fast_accum,
            loras = request.loras,
            **_component_file_kwargs(request),
            # Keeps the probe: a capability read, never an allocation; without it a GGUF pick reports 21 GB short
            memory_verdict = not training,
        )
        return DiffusionDownloadPlanResponse(**plan)
    except (ValueError, FileNotFoundError) as exc:
        raise HTTPException(status_code = 400, detail = redact_native_paths(str(exc)))
    except RuntimeError as exc:
        # 409 like the load route: this is a deliberate refusal, not a server fault.
        raise HTTPException(status_code = 409, detail = redact_native_paths(str(exc)))


def _assert_native_precision_unset(
    *, transformer_quant: Optional[str] = None, text_encoder_quant: Optional[str] = None
) -> None:
    """Refuses an explicit precision on sd.cpp, which ignores precision knobs; auto and none pass through."""
    from core.inference.diffusion_auto_policy import precision_fallback_allowed
    from core.inference.diffusion_nvfp4_flag import refuse_disabled_nvfp4
    from core.inference.diffusion_precision import normalize_te_quant
    from core.inference.diffusion_transformer_quant import TQ_AUTO, normalize_transformer_quant

    refuse_disabled_nvfp4(
        transformer_quant = transformer_quant, text_encoder_quant = text_encoder_quant
    )
    if precision_fallback_allowed():
        return
    pinned = normalize_transformer_quant(transformer_quant)
    te_mode = normalize_te_quant(text_encoder_quant)
    asked = []
    if pinned is not None and pinned != TQ_AUTO:
        asked.append(f"transformer_quant={pinned!r}")
    if te_mode is not None and te_mode != TQ_AUTO:
        asked.append(f"text_encoder_quant={te_mode!r}")
    if not asked:
        return
    raise RuntimeError(
        # The frontend classifies precision refusals by the phrase 'could not be used'.
        f"{' and '.join(asked)} could not be used: this pick runs on the native engine, which "
        "loads a GGUF checkpoint as it is and has no torchao quantisation path. Leave the "
        "precision on 'auto', or pick a model that loads through diffusers."
    )


_DIFFUSION_LOAD_CANCELLED = "Diffusion load was cancelled."


@studio_router.post("/images/load", response_model = DiffusionStatusResponse)
@account_access.gpu_busy_route
async def load_diffusion_model(
    request: DiffusionLoadRequest,
    current_subject: str = Depends(get_current_subject),
    via_api_key: bool = Depends(authenticated_via_api_key),
):
    # Status may be the PREVIOUS model; keep this in the route, not the gated body (keyless callers)
    from hub.utils.host_paths import (
        raised_inventory_detail,
        redact_host_paths,
        restore_inventory_handles,
    )
    from core.inference.chat_swap_kv import preparing_load

    try:
        with preparing_load("image", request.load_token):
            loaded = await load_diffusion_model_gated(request, current_subject, user_initiated = True)
    except HTTPException as exc:
        # A raising load skips both wrappers, and the inner loader doesn't know inventory handles.
        exc.detail = raised_inventory_detail(exc.detail, via_api_key = via_api_key)
        raise
    return redact_host_paths(
        restore_inventory_handles(loaded),
        via_api_key = via_api_key,
    )


async def load_diffusion_model_gated(
    request: DiffusionLoadRequest,
    current_subject: str,
    *,
    user_initiated: bool = False,
):
    """Media auto-switch awaits this so the idle unload can tell API loads from user-picked ones."""
    _refuse_disabled_nvfp4_request(request)
    if account_access.managed_account():
        await asyncio.to_thread(account_access.require_media_references, request)
    account_access.require_idle_other_accounts()
    if account_access.managed_account():
        await asyncio.to_thread(account_access.require_model_access, request.model_path)
    if request.base_repo:
        if account_access.managed_account():
            await asyncio.to_thread(account_access.require_model_access, request.base_repo)
    if account_access.managed_account():
        request = request.model_copy(
            update = {"hf_token": account_access.account_hf_token(request.hf_token)}
        )
    await _refuse_disabled_nvfp4_checkpoint(request)
    # Tested at ENTRY since begin_load returns early; the write waits, as validation can 400 first
    _media_repos_to_record = [
        ref
        for ref in (
            request.model_path,
            request.base_repo,
            # Hub-hosted text-encoder / VAE files are fetched with this request's token too.
            *(
                r
                for r in account_access.media_component_file_references(request)
                if r and not Path(r).is_absolute()
            ),
        )
        if ref and _repo_is_in_the_hub_cache(ref) is not True
    ]
    from core.inference.diffusion import (
        get_diffusion_backend,
        split_local_checkpoint_path,
        resolve_model_kind,
    )
    from core.inference.diffusion_local_files import resolve_local_single_file
    from core.inference.diffusion_device import (
        resolve_diffusion_device_target,
        resolve_selected_cuda_ordinal,
    )
    from core.inference.diffusion_engine_router import (
        active_engine_name,
        annotate_status,
        begin_load_on,
        engine_for,
        image_install_accelerator,
        loaded_state_of,
        note_engine_pick,
        off_torch_sd_cpp_device,
        predict_engine,
        select_and_activate_engine,
    )
    from core.inference.gpu_arbiter import (
        acquire_for_request,
        eviction_sink,
        MultiModelAlwaysRefusal,
        begin_media_load,
        guarded_media_begin,
        note_evictions,
        refuse_replacing_media,
        require_no_foreign_generations,
        release,
        DIFFUSION,
    )
    from core.inference.media_keepwarm import note_load_origin as note_media_load_origin
    from hub.utils.gguf import extract_quant_token
    from core.inference.sd_cpp_args import forces_cpu_backend
    from core.inference.sd_cpp_backend import (
        managed_sd_cpp_accelerator,
        preferred_accelerator,
        sd_cpp_binaries_all_cpu,
        selected_card_identity,
    )
    from core.inference.sd_cpp_engine import ENGINE_DIFFUSERS, ENGINE_MLX, ENGINE_SD_CPP
    from core.inference.diffusion_hub_evidence import prefetch_for_pick
    from utils.native_path_leases import redact_native_paths

    from core.inference import media_load_ids

    backend = get_diffusion_backend()
    try:
        # A load an unload already cancelled by its token starts nothing (checked again at admission).
        media_load_ids.refuse_cancelled("diffusion", request.load_token)
        # Resolve the load kind once (gguf / single_file / pipeline) so validation, engine selection and the load agree. A bad kind raises here, so a 400.
        kind = resolve_model_kind(request.gguf_filename, request.model_kind)
        # A local On-Device pick can be a bare single-file .safetensors directory; if it holds exactly one checkpoint, reinterpret it as a single_file load so all three paths agree.
        if kind == "pipeline" and not request.gguf_filename:
            split = await asyncio.to_thread(split_local_checkpoint_path, request.model_path)
            if split is not None:
                request.model_path, request.gguf_filename = split
                kind = resolve_model_kind(split[1])
            sole = (
                None
                if split is not None
                else await asyncio.to_thread(resolve_local_single_file, request.model_path)
            )
            if sole is not None:
                request.gguf_filename = sole
                kind = resolve_model_kind(sole)
        # A Hub repo named for no family (an SDXL fine-tune) says what it is in its own model_index.json or checkpoint
        # header; fetch that small evidence first so the network-free validation below can read it.
        await asyncio.to_thread(
            prefetch_for_pick,
            request.model_path,
            request.gguf_filename,
            request.family_override,
            request.hf_token,
            # An automatic (API auto-switch) load is cache-only, like the rest of this path.
            user_initiated,
        )
        # Validate cheaply BEFORE touching the GPU: an unloadable pick must not evict a working chat model and then 400. The family also drives engine selection.
        fam = await asyncio.to_thread(
            backend.validate_load_request,
            request.model_path,
            gguf_filename = request.gguf_filename,
            family_override = request.family_override,
            model_kind = kind,
            base_repo = request.base_repo,
            **_component_file_kwargs(request),
        )
        # An explicit engine pick that cannot serve this load is refused here, before anything is evicted.
        from core.inference.diffusion_engine_router import refuse_engine_pick

        refuse_engine_pick(fam, engine = request.engine, model_kind = kind)
        # Off-torch native shares no VRAM with training or chat; re-settled after selection (diffusers lands on torch's card).
        off_torch = await asyncio.to_thread(off_torch_sd_cpp_device)
        # Refuse while training is running: a multi-GB pipeline would compete with the training subprocess for VRAM.
        if off_torch is None:
            _guard_diffusion_load_against_training()
        # Gate on the device, not the engine name; pure resolve, so it can precede selection.
        device = await asyncio.to_thread(lambda: resolve_diffusion_device_target().device)
        needs_gpu = device != "cpu"
        # Refuse bad picks before eviction or staging; begin_load re-checks only after the arbiter takes GPU
        gpu_ordinal = await _selected_gpu_ordinal(request.gpu_ids)

        def _preflight(target):
            # Gated/unreadable-companion refusal, asked of ONE engine (they check different repos).
            return target.preflight_base_access(
                request.model_path,
                fam,
                gguf_filename = request.gguf_filename,
                model_kind = kind,
                base_repo = request.base_repo,
                hf_token = request.hf_token,
                allow_network = user_initiated,
            )

        # Last refusal before teardown: a gated companion repo. Must precede selection, which unloads the
        # current engine. Fails open on offline/transient errors.
        try:
            # Card-scoped like the activation below, or the wrong engine's preflight runs.
            pending_name = (
                predict_engine(
                    fam,
                    model_kind = kind,
                    gpu_ordinal = gpu_ordinal,
                    gguf_filename = request.gguf_filename,
                    engine = request.engine,
                    with_loras = _has_active_loras(request.loras),
                    mlx_blocker = _mlx_load_blocker(request),
                )
                if fam is not None
                else None
            )
        except Exception:  # noqa: BLE001 -- a probe failure must not refuse a loadable pick
            pending_name = None
        # MLX drives the Apple GPU itself even where torch resolved "cpu": take the arbiter.
        if pending_name == ENGINE_MLX:
            needs_gpu = True
        # So does the Vulkan sd.cpp build a CPU torch is routed to beside an AMD or Arc card,
        # unless that build has failed here and the ladder runs the CPU one instead.
        # A retained managed Vulkan build also renders on the card, whatever this load requested.
        vulkan_on_cpu_torch = (
            device == "cpu"
            and off_torch is None
            and await asyncio.to_thread(
                lambda: preferred_accelerator(image_install_accelerator("cpu"), None) == "vulkan"
                or managed_sd_cpp_accelerator() == "vulkan"
            )
        )
        if pending_name == ENGINE_SD_CPP and vulkan_on_cpu_torch:
            needs_gpu = True

        # A GPU torch whose GPU builds have all failed here runs the managed CPU bundle: no claim.
        def _runs_cpu_rung() -> bool:
            try:
                torch_backend = getattr(resolve_diffusion_device_target(), "backend", device)
                return (
                    preferred_accelerator(
                        image_install_accelerator(torch_backend),
                        selected_card_identity(gpu_ordinal),
                    )
                    == "cpu"
                    and sd_cpp_binaries_all_cpu()
                )
            except Exception:  # noqa: BLE001 -- unknown keeps the claim
                return False

        cpu_rung_on_gpu_torch = (
            device not in ("cpu", "mps")
            and off_torch is None
            and await asyncio.to_thread(_runs_cpu_rung)
        )
        if pending_name == ENGINE_SD_CPP and cpu_rung_on_gpu_torch:
            needs_gpu = False
        # Before selection: switching to diffusers would unload the resident off-torch model, then refuse.
        if off_torch is not None and pending_name != ENGINE_SD_CPP:
            _guard_diffusion_load_against_training()
        # begin_load repeats this check, but only after evicting chat and switching engines.
        if fam is not None and pending_name == ENGINE_DIFFUSERS:
            await asyncio.to_thread(
                backend.assert_precision_available,
                fam,
                model_kind = kind,
                transformer_quant = request.transformer_quant,
                text_encoder_quant = request.text_encoder_quant,
                memory_mode = getattr(request, "memory_mode", None),
                cpu_offload = bool(getattr(request, "cpu_offload", False)),
                speed_mode = getattr(request, "speed_mode", None),
                gpu_ordinal = gpu_ordinal,
                repo_id = request.model_path,
                base_repo = request.base_repo,
                local_files_only = not user_initiated,
                text_encoder_files = request.supplied_text_encoder_files(),
                gguf_filename = request.gguf_filename,
            )
        elif fam is not None and pending_name in (ENGINE_SD_CPP, ENGINE_MLX):
            # The opt-in MLX engine shares the native contract: one GGUF, no dense-quant knobs.
            _refuse_native_component_files(request)
            if pending_name == ENGINE_MLX:
                _refuse_mlx_loras(request)
            # The native engine accepts both knobs for interface parity and ignores them. It was
            # excluded from the gate above so as not to refuse loads that work today, but the
            # loads it "works" for are precisely the silent mismatch this whole change exists to
            # remove: an explicit FP8 succeeds, quantises nothing, and reports null. Refusing is
            # also what the diffusers path already does on the same CPU-only host, so leaving the
            # two engines disagreeing was the worse of the options.
            _assert_native_precision_unset(
                transformer_quant = request.transformer_quant,
                text_encoder_quant = request.text_encoder_quant,
            )
        # Refuse a speech GGUF here; the engines' own checks run only after eviction.
        from core.inference.diffusion_compat import assert_pick_is_not_speech

        await asyncio.to_thread(
            assert_pick_is_not_speech,
            request.model_path,
            request.gguf_filename,
            request.hf_token,
            user_initiated,
        )
        preflighted = None
        if pending_name is not None and (needs_gpu or pending_name != active_engine_name()):
            preflighted = engine_for(pending_name)
            await asyncio.to_thread(_preflight, preflighted)

        from utils.multi_model_settings import get_multi_model_mode

        # Read outside the arbiter lock.
        multi_model_mode = await asyncio.to_thread(get_multi_model_mode)
        media_names = (request.model_path,)
        # Before the engine switch below: on any device the load replaces the loaded image model.
        replaced_media = await asyncio.to_thread(
            refuse_replacing_media, DIFFUSION, multi_model_mode, media_names
        )
        # Every model this load unloads, as {kind, model}.
        evicted_slots: list[dict] = []
        note_evictions(replaced_media, evicted_slots)
        # begin_load signals whatever generation is running, so guard on every device, not just GPU.
        require_no_foreign_generations()
        from core.inference.chat_swap_kv import (
            preparing_load_token,
            raise_if_load_cancelled,
            run_unless_load_cancelled,
        )

        raise_if_load_cancelled(_DIFFUSION_LOAD_CANCELLED)
        preflight = preparing_load_token()
        if off_torch is not None and pending_name == ENGINE_SD_CPP:
            # Checked under the preflight lock, so a cancelled load never unloads the video model.
            await asyncio.to_thread(
                run_unless_load_cancelled,
                _DIFFUSION_LOAD_CANCELLED,
                _unload_native_video_sharing_the_sd_cpp_tree,
                multi_model_mode,
                evicted_slots,
            )
        raise_if_load_cancelled(_DIFFUSION_LOAD_CANCELLED)
        # Pick the engine for this host (diffusers on GPU, native sd.cpp otherwise), installing sd-cli if needed, BEFORE evicting chat.
        # Under Always the switch re-checks under the router's transition lock: another load may have landed meanwhile.
        engine = await asyncio.to_thread(
            _activate_unless_cancelled,
            preflight,
            functools.partial(refuse_replacing_media, DIFFUSION, multi_model_mode, media_names)
            if multi_model_mode == "always"
            else None,
            functools.partial(
                select_and_activate_engine,
                fam,
                hf_token = request.hf_token,
                model_kind = kind,
                # The ordinal resolved above: re-resolving re-ranks by free VRAM and can pick another card.
                gpu_ordinal = gpu_ordinal,
                # A fallback lands on torch's card: refuse it during training before it unloads anything.
                before_fallback = (
                    _guard_diffusion_load_against_training if off_torch is not None else None
                ),
                # Only the opt-in MLX engine reads it (to judge the GGUF quant).
                gguf_filename = request.gguf_filename,
                # The load's own engine pick (auto when absent); refused there rather than swapped.
                engine = request.engine,
                with_loras = _has_active_loras(request.loras),
                # A load option the MLX engine cannot honour keeps an auto-routed Apple Silicon load on diffusers.
                mlx_blocker = _mlx_load_blocker(request),
            ),
        )
        # predict_engine never installs, so a failed sd-cli install lands on the OTHER engine: re-preflight.
        if (needs_gpu or preflighted is not None) and engine is not preflighted:
            await asyncio.to_thread(_preflight, engine)
        # Gate on the activated engine: if predict_engine raised, pending_name stayed None and skipped arms
        activated = active_engine_name()
        if fam is not None and activated != pending_name:
            if activated in (ENGINE_SD_CPP, ENGINE_MLX):
                _refuse_native_component_files(request)
                if activated == ENGINE_MLX:
                    _refuse_mlx_loras(request)
                _assert_native_precision_unset(
                    transformer_quant = request.transformer_quant,
                    text_encoder_quant = request.text_encoder_quant,
                )
            elif activated == ENGINE_DIFFUSERS:
                await asyncio.to_thread(
                    backend.assert_precision_available,
                    fam,
                    model_kind = kind,
                    transformer_quant = request.transformer_quant,
                    text_encoder_quant = request.text_encoder_quant,
                    memory_mode = getattr(request, "memory_mode", None),
                    cpu_offload = bool(getattr(request, "cpu_offload", False)),
                    speed_mode = getattr(request, "speed_mode", None),
                    gpu_ordinal = gpu_ordinal,
                    repo_id = request.model_path,
                    base_repo = request.base_repo,
                    local_files_only = not user_initiated,
                    text_encoder_files = request.supplied_text_encoder_files(),
                    gguf_filename = request.gguf_filename,
                )
        if off_torch is not None:
            if activated == ENGINE_SD_CPP:
                needs_gpu = False
            else:
                _guard_diffusion_load_against_training()
        if device == "cpu" and off_torch is None:
            # Re-settled on what selection activated and installed: a CPU diffusers fallback, or a
            # retained CPU bundle after a failed Vulkan install, takes no GPU.
            needs_gpu = (
                activated == ENGINE_SD_CPP
                and vulkan_on_cpu_torch
                and not await asyncio.to_thread(sd_cpp_binaries_all_cpu)
            )
        if activated == ENGINE_MLX:
            needs_gpu = True
        if activated == ENGINE_SD_CPP and cpu_rung_on_gpu_torch:
            needs_gpu = False
        # sd.cpp runs a paravirtual Mac GPU on the CPU backend, so it takes no DIFFUSION claim.
        if (
            activated == ENGINE_SD_CPP
            and device == "mps"
            and await asyncio.to_thread(forces_cpu_backend, device)
        ):
            needs_gpu = False

        def _start_engine_load():
            # Recorded here: past the busy guard, arbiter and retirement check, before the worker gets the token.
            for _ref in _media_repos_to_record:
                _note_load_fetched_with_a_request_token(_ref, request.hf_token)
            # Past admission: the upsampler serves the model being replaced, and a same-owner swap runs no eviction.
            from core.inference.flux3_prompt_upsampler import stop_for_handover

            stop_for_handover()
            # Snapshotted BEFORE the worker starts: a cached load can publish before begin_load returns.
            prior_state = loaded_state_of(engine)
            # Kicks the slow load onto a background thread and returns at once (the client polls images/load-progress).
            prior_load = media_load_ids.admitting("diffusion", engine, request.load_token)
            started = engine.begin_load(
                request.model_path,
                display_repo_id = request.display_repo_id,
                # A load nobody asked for must not reach the hub.
                local_files_only = not user_initiated,
                gguf_filename = request.gguf_filename,
                base_repo = request.base_repo,
                family_override = request.family_override,
                hf_token = request.hf_token,
                cpu_offload = request.cpu_offload,
                memory_mode = request.memory_mode,
                speed_mode = request.speed_mode,
                text_encoder_quant = request.text_encoder_quant,
                transformer_quant = request.transformer_quant,
                transformer_quant_fast_accum = request.transformer_quant_fast_accum,
                transformer_prequant_path = request.transformer_prequant_path,
                attention_backend = request.attention_backend,
                transformer_cache = request.transformer_cache,
                transformer_cache_threshold = request.transformer_cache_threshold,
                model_kind = kind,
                loras = [(s.id, s.weight) for s in request.loras] if request.loras else None,
                gpu_ids = request.gpu_ids,
                # Uses the winner this route ranked and preflighted, not a card picked from VRAM that moved since.
                gpu_ordinal = gpu_ordinal,
                **_component_file_kwargs(request),
                # Only when set: the native engines take no such argument.
                **({"allow_oversized_load": True} if request.allow_oversized_load else {}),
                **_fallback_gate_kwarg(
                    engine.begin_load,
                    _mlx_fallback_load_gate(request, gpu_ordinal, multi_model_mode),
                ),
            )
            media_load_ids.admitted("diffusion", engine, request.load_token, prior_load)
            # A warm start that took the generation slot between the stop above and begin_load publishing the load would
            # bring the old model's upsampler up beside this one: cancel it now that the load is visible.
            _cancel_upsampler_warm_start()
            # Only once the engine accepted the load, committed when it lands, so a refused or failed pick never
            # relabels the resident model.
            note_engine_pick(request.engine, engine, prior_state)
            return started

        def _begin_load():
            # Under the router transition lock: begin_load on a deactivated engine leaves a resident model nothing can reach.
            def _register():
                return begin_load_on(
                    engine,
                    lambda: account_access.admit_media_load(
                        "diffusion", _start_engine_load, request.model_path
                    ),
                )

            if preflight is None:
                return _register()
            # A cancel lands before this check or after registration, where the engine unload stops it.
            with preflight.lock:
                raise_if_load_cancelled(_DIFFUSION_LOAD_CANCELLED)
                return _register()

        if needs_gpu:
            from core.inference.gpu_residency import media_fit_kwargs

            fit_kwargs = await asyncio.to_thread(
                media_fit_kwargs, DIFFUSION, request, gpu_ordinal, multi_model_mode
            )

            # Register the in-flight load UNDER the arbiter lock: otherwise a competing acquire in that gap evicts DIFFUSION before
            # the load is marked, finds nothing to cancel, and both allocate at once. The training admission wraps the same span.
            def _acquire_and_begin():
                raise_if_load_cancelled(_DIFFUSION_LOAD_CANCELLED)
                admitted = []

                def _admit():
                    if preflight is None:
                        return
                    preflight.lock.acquire()
                    admitted.append(True)
                    raise_if_load_cancelled(_DIFFUSION_LOAD_CANCELLED)

                sink_token = eviction_sink.set(evicted_slots)
                try:
                    with _diffusion_training_admission():
                        return acquire_for_request(
                            DIFFUSION,
                            guarded_media_begin(
                                DIFFUSION, multi_model_mode, media_names, _begin_load
                            ),
                            admit = _admit,
                            **fit_kwargs,
                        )
                finally:
                    if admitted:
                        preflight.lock.release()
                    eviction_sink.reset(sink_token)

            from core.inference.chat_swap_kv import acquire_then_close, save_chat_kv_before_swap

            swap = await save_chat_kv_before_swap(DIFFUSION, "image", **fit_kwargs)
            try:
                raise_if_load_cancelled(_DIFFUSION_LOAD_CANCELLED)
            except BaseException:
                swap.close()
                raise
            status_dict = await acquire_then_close(swap, _acquire_and_begin)
        else:
            # A CPU-only native load never touches the GPU, but switching FROM a previous GPU load leaves DIFFUSION marked as owner, so release (owner-guarded).
            await asyncio.to_thread(release, DIFFUSION)
            status_dict = await asyncio.to_thread(
                begin_media_load, DIFFUSION, multi_model_mode, media_names, _begin_load
            )
        # Keyed to the target: this load can still fail with the previous model resident, and
        # its origin must not be read off that model.
        note_media_load_origin(
            DIFFUSION,
            request.model_path,
            extract_quant_token(request.gguf_filename) if kind == "gguf" else None,
            user_action = user_initiated,
        )
        account_access.note_resident_components(
            "diffusion",
            request.model_path,
            request.base_repo,
            *account_access.media_adapter_references(request),
            *(r for r in account_access.media_component_file_references(request) if r),
        )
        reset_media_load_progress("image")
        status_dict = {
            **status_dict,
            "evicted": [slot["model"] for slot in evicted_slots if slot.get("model")],
            "evicted_slots": evicted_slots,
        }
        return DiffusionStatusResponse(**(await asyncio.to_thread(annotate_status, status_dict)))
    except (ValueError, FileNotFoundError) as exc:
        raise HTTPException(status_code = 400, detail = redact_native_paths(str(exc)))
    except account_access.GpuBusyForAnotherAccountError as exc:
        raise account_access.gpu_busy_error() from exc
    except MultiModelAlwaysRefusal as exc:
        raise exc.as_http_exception() from exc
    except RuntimeError as exc:
        # A load is already in progress.
        raise HTTPException(status_code = 409, detail = str(exc))


def _live_preview_kwarg(generate: Any, requested: Optional[bool]) -> dict:
    """``live_preview`` for an engine whose generate() takes it (sd.cpp's does not), else nothing."""
    try:
        import inspect
        if "live_preview" in inspect.signature(generate).parameters:
            return {"live_preview": requested}
    except (TypeError, ValueError):
        pass
    return {}


def _sampler_kwargs(generate: Any, sampler: Optional[str], schedule_type: Optional[str]) -> dict:
    """``sampler`` / ``schedule_type`` for an engine whose generate() takes them (diffusers only).

    A real choice sent to another engine is refused (ValueError -> 400) rather than ignored, so a
    recipe never records a sampler that did not run."""
    try:
        import inspect
        if "sampler" in inspect.signature(generate).parameters:
            return {"sampler": sampler, "schedule_type": schedule_type}
    except (TypeError, ValueError):
        pass
    if sampler not in (None, "default") or schedule_type not in (None, "automatic"):
        raise ValueError("Choosing a sampler is supported on the diffusers engine only.")
    return {}


def _sd_controls_kwargs(generate: Any, request: Any) -> dict:
    """``sd_controls`` (prompt weighting, CLIP skip, CFG rescale, variation seed) for an engine whose generate() takes
    them (diffusers only). A value that changes the render, sent to another engine, is refused (ValueError -> 400)
    rather than ignored, so a recipe never records a control that did not run."""
    from core.inference.diffusion_sd_controls import SdControls

    controls = SdControls(
        prompt_weighting = getattr(request, "prompt_weighting", None),
        clip_skip = getattr(request, "clip_skip", None),
        cfg_rescale = getattr(request, "cfg_rescale", None),
        variation_seed = getattr(request, "variation_seed", None),
        variation_strength = getattr(request, "variation_strength", None),
    )
    try:
        import inspect
        if "sd_controls" in inspect.signature(generate).parameters:
            return {"sd_controls": controls}
    except (TypeError, ValueError):
        pass
    if controls.requested():
        raise ValueError(
            "Prompt weighting, CLIP skip, CFG rescale and variation seeds are supported on the "
            "diffusers engine only."
        )
    if controls.prompt_weighting is False and getattr(
        getattr(generate, "__self__", None), "parses_prompt_attention", False
    ):
        # sd.cpp reads (word:1.5) itself, so the prompt would still render weighted.
        raise ValueError(
            "Turning prompt weighting off is supported on the diffusers engine only: the native "
            "sd.cpp engine always reads (word:1.2) attention syntax."
        )
    return {}


def _shift_kwargs(generate: Any, request: Any) -> dict:
    """``shift`` / ``base_shift`` / ``max_shift`` for an engine whose generate() takes them (diffusers only).

    Omitted on every engine when unset, so an older call is unchanged; a value sent to another engine
    is refused (ValueError -> 400) rather than silently ignored."""
    values = {
        "shift": getattr(request, "shift", None),
        "base_shift": getattr(request, "base_shift", None),
        "max_shift": getattr(request, "max_shift", None),
    }
    if all(v is None for v in values.values()):
        return {}
    try:
        import inspect
        if "shift" in inspect.signature(generate).parameters:
            return values
    except (TypeError, ValueError):
        pass
    raise ValueError("Shift is supported on the diffusers engine only.")


def _inpaint_mask_kwargs(generate: Any, request: Any) -> dict:
    """Inpaint mask kwargs generate() accepts; only the set ones, so an untouched request is unchanged."""
    try:
        import inspect
        params = inspect.signature(generate).parameters
    except (TypeError, ValueError):
        return {}
    out = {}
    for name in ("mask_blur", "inpaint_only_masked", "inpaint_padding"):
        value = getattr(request, name, None)
        if value is not None and name in params:
            out[name] = value
    return out


def _hires_kwargs(generate: Any, request: Any) -> dict:
    """Only the set Hires fix / upscaler kwargs; an engine that takes neither refuses (ValueError -> 400)."""
    try:
        import inspect
        params = inspect.signature(generate).parameters
    except (TypeError, ValueError):
        params = {}
    out: dict = {}
    hires = getattr(request, "hires", None)
    if hires is not None:
        if "hires" not in params:
            raise ValueError("Hires fix is not available on this image engine.")
        from core.inference.diffusion_hires import HiresParams
        out["hires"] = HiresParams(
            scale = float(hires.scale),
            denoise = float(hires.denoise),
            steps = hires.steps,
            upscaler = hires.upscaler,
            guidance = hires.guidance,
        )
    upscale_model = getattr(request, "upscale_model", None)
    if upscale_model:
        if "upscale_model" not in params:
            raise ValueError("Model upscalers are not available on this image engine.")
        out["upscale_model"] = upscale_model
    return out


# Count of finished generations still writing their PNG/gallery records; generate-progress reports active while above 0. Mutated only on the event loop, so no lock.
_diffusion_persist_active = 0


def generation_in_flight() -> bool:
    """Stays true past marker clearing while gallery records are written; else watchdog cuts a live job"""
    return _diffusion_persist_active > 0


_GENERATE_FAILURE_FALLBACK = "Image generation failed."
# Failure classes worth naming in the UI, as FIXED text: the engine's own message can embed local paths and argv, so only the class is reported.
_GENERATE_FAILURE_CLASSES: tuple[tuple[tuple[str, ...], str], ...] = (
    (
        ("out of memory", "outofmemory", "oom"),
        "The device ran out of memory. Try a smaller size, fewer steps, or a smaller batch.",
    ),
    (
        ("decoded image contains nan",),
        "The model or VAE overflowed at this resolution and precision. Try a smaller resolution or another "
        "quant of this model.",
    ),
    (
        ("sd-server connection lost", "sd-cli exited", "process exited", "ggml_abort", "signal"),
        "The native image renderer stopped unexpectedly. Switch the engine to diffusers, or see "
        "the server log for its output.",
    ),
)


def _generate_failure_detail(message: str) -> str:
    """A user-facing reason for a failed generation, built only from fixed text.

    The bare literal left a real failure undiagnosable from the UI: on a Metal host the native
    renderer aborts inside its own text encoder, and the page showed "Image generation failed."
    with nothing to act on. Naming the CLASS of failure keeps the message useful without echoing
    the engine's text, which can carry local paths and argv."""
    text = str(message or "").lower()
    for needles, detail in _GENERATE_FAILURE_CLASSES:
        if any(n in text for n in needles):
            return f"{_GENERATE_FAILURE_FALLBACK} {detail}"
    return _GENERATE_FAILURE_FALLBACK


# Keyed by account id, not account_scope(): the scope moves when the first managed account appears.
_external_image_runs: dict[str, set] = {}
_stopped_external_image_runs: set = set()


def _external_image_run_active() -> bool:
    return bool(_external_image_runs.get(current_account_id()))


def _stop_external_image_runs() -> bool:
    runs = [
        task for task in _external_image_runs.get(current_account_id()) or () if not task.done()
    ]
    for task in runs:
        _stopped_external_image_runs.add(task)
        task.cancel()
    return bool(runs)


async def _external_image_generation(
    body: DiffusionGenerateRequest, request: Request
) -> DiffusionGenerateResponse:
    from PIL import Image

    from core.inference import image_gallery
    from core.inference.llama_keepwarm import (
        untrack_current_media_request,
        untrack_current_request,
    )

    untrack_current_request(request.scope)
    untrack_current_media_request(request.scope)
    provider_id = body.provider_id.strip()
    external_model = (body.model or "").strip()
    if not external_model:
        raise HTTPException(
            status_code = 400,
            detail = "model is required when using an external image connection.",
        )
    if (
        body.init_image
        or body.reference_images
        or body.loras
        or body.controlnet
        or body.prompts
        or body.seeds
        or body.negative_prompt
        or body.mask_image
        or body.strength is not None
        or body.upscale is not None
        or body.workflow
        or body.localized_edit
        or body.sampler
        or body.schedule_type
        or body.shift is not None
        or body.base_shift is not None
        or body.max_shift is not None
        or body.mask_blur is not None
        or body.inpaint_only_masked is not None
        or body.inpaint_padding is not None
        or body.hires is not None
        or body.upscale_model
        or body.detailer is not None
    ):
        raise HTTPException(
            status_code = 400,
            detail = "An external image connection only supports text to image.",
        )

    config = await asyncio.to_thread(providers_db.get_provider, provider_id)
    if config is None:
        raise HTTPException(status_code = 404, detail = f"Provider config not found: {provider_id}")
    account_access.require_connection_model_allowed(config, external_model)
    _refuse_decision_connection(config["provider_type"], config.get("api_type"))
    if not config["is_enabled"]:
        raise HTTPException(
            status_code = 400,
            detail = f"Provider '{config['display_name']}' is disabled.",
        )
    base_url = config["base_url"] or get_base_url(config["provider_type"])
    if not base_url:
        raise HTTPException(status_code = 400, detail = "The connection has no base URL.")
    try:
        base_url = validate_provider_base_url(base_url)
    except ValueError as exc:
        raise HTTPException(status_code = 400, detail = str(exc)) from None

    async with provider_config_guard(
        provider_id, shared_by_owner = bool(config.get("shared_by_owner"))
    ):
        current = await asyncio.to_thread(providers_db.get_provider, provider_id)
        routing_fields = ("provider_type", "base_url", "is_enabled")
        if current is None or any(
            current.get(field) != config.get(field) for field in routing_fields
        ):
            raise HTTPException(
                status_code = 409,
                detail = "Provider changed while the request was starting; retry.",
            )
        account_access.require_connection_model_allowed(current, external_model)
        api_key = await asyncio.to_thread(
            resolve_provider_api_key_or_400,
            provider_id,
            None,
            allow_saved_key = not _request_has_api_key(request),
        )
        latest = await asyncio.to_thread(providers_db.get_provider, provider_id)
        if latest is None or any(
            latest.get(field) != current.get(field) for field in routing_fields
        ):
            raise HTTPException(
                status_code = 409,
                detail = "Provider changed while the request was starting; retry.",
            )

    client = ExternalProviderClient(
        provider_type = config["provider_type"],
        base_url = base_url,
        api_key = api_key,
        timeout = 600.0,
    )
    owner = current_account_id()
    task = asyncio.create_task(
        client.create_images(
            prompt = body.prompt,
            model = external_model,
            n = body.batch_size,
            size = f"{body.width}x{body.height}",
        )
    )
    _external_image_runs.setdefault(owner, set()).add(task)
    try:
        try:
            try:
                encoded = await task
            except asyncio.CancelledError:
                if task not in _stopped_external_image_runs:
                    task.cancel()
                    raise
                from core.inference.diffusion_families import DIFFUSION_CANCELLED_MSG
                raise HTTPException(status_code = 409, detail = DIFFUSION_CANCELLED_MSG) from None
            images = []
            for item in encoded:
                image = Image.open(io.BytesIO(base64.b64decode(item)))
                image.load()
                images.append(image)
        except HTTPException:
            raise
        except httpx.HTTPStatusError as exc:
            raise HTTPException(
                status_code = 502,
                detail = (
                    f"Image endpoint returned HTTP {exc.response.status_code}: {exc.response.text[:300]}"
                ),
            ) from exc
        except httpx.HTTPError as exc:
            raise log_and_http_error(
                exc,
                502,
                "Could not reach the image endpoint.",
                event = "external_images.transport_error",
                log = logger,
            ) from exc
        except Exception as exc:
            raise HTTPException(
                status_code = 502, detail = "The image endpoint did not return a usable image."
            ) from exc

        created_at = time.time()

        def _persist() -> list[dict]:
            return list(
                image_gallery.save_many(
                    (
                        image,
                        {
                            "prompt": body.prompt,
                            "width": image.width,
                            "height": image.height,
                            "steps": body.steps,
                            "guidance": body.guidance,
                            "seed": body.seed or 0,
                            "batch_index": index,
                            "batch_size": body.batch_size,
                            "model": external_model,
                            "model_kind": "connection",
                            "created_at": created_at,
                        },
                    )
                    for index, image in enumerate(images)
                )
            )

        try:
            records = await asyncio.to_thread(_persist)
        except Exception as exc:
            logger.error("diffusion.persist_failed: %s", exc)
            raise HTTPException(status_code = 500, detail = "Failed to save the generated image.")
        return DiffusionGenerateResponse(images = [GalleryImage(**r) for r in records])
    finally:
        runs = _external_image_runs.get(owner)
        if runs is not None:
            runs.discard(task)
            if not runs:
                _external_image_runs.pop(owner, None)
        _stopped_external_image_runs.discard(task)


async def _enhance_generate_prompts(backend, request: DiffusionGenerateRequest):
    """FLUX.3 prompt upsampling for one generate call (``EnhanceOutcome``). Every other family, and FLUX.3 with
    ``enhance_prompt=false``, passes its prompts through untouched. Never fails the generation: only a Stop during
    the upsampling surfaces, as the cancelled 409."""
    from core.inference import flux3_prompt_upsampler as pup
    from core.inference.diffusion_families import DIFFUSION_CANCELLED_MSG

    try:
        status = await asyncio.to_thread(backend.status)
        family = status.get("family") if status.get("loaded") else None
    except Exception as exc:  # noqa: BLE001 -- no status, no upsampling
        logger.debug("flux3.prompt_upsampler: status probe failed: %s", exc)
        status, family = {}, None
    if not pup.supports_family(family):
        return pup.EnhanceOutcome(status = None)
    # A workflow the family refuses fails in the run anyway: no upsampler start (or vision load) ahead of that 400.
    workflows = status.get("workflows") or []
    if request.workflow and workflows and request.workflow not in workflows:
        return pup.EnhanceOutcome(status = None)
    if not pup.resolve_enhance(family, request.enhance_prompt):
        return pup.EnhanceOutcome(status = pup.STATUS_OFF)
    if account_access.managed_account():
        # The run below refuses a resident model this account may not use; refuse before the sidecar works for it.
        await asyncio.to_thread(account_access.require_media_generation_access, status, "diffusion")
    references = ([request.init_image] if request.init_image else []) + list(
        request.reference_images or []
    )
    # The sidecar takes GPU memory of its own: never beside another account's chat, image or video run.
    try:
        account_access.require_idle_other_accounts()
    except (HTTPException, account_access.GpuBusyForAnotherAccountError):
        return pup.EnhanceOutcome(status = pup.STATUS_UNAVAILABLE)
    try:
        with account_access.media_generation("diffusion"):
            outcome = await asyncio.to_thread(
                pup.enhance_for_generation,
                list(request.prompts or [request.prompt]),
                family_name = family,
                enhance_prompt = request.enhance_prompt,
                reference_images = references or None,
            )
    except pup.UpsamplerCancelledError:
        raise HTTPException(status_code = 409, detail = DIFFUSION_CANCELLED_MSG)
    if outcome.status not in (None, pup.STATUS_OFF):
        # Every attempted enhancement, a fallback too: a model swapped in meanwhile retries with its own default.
        from core.inference.diffusion_families import load_identity
        outcome.load = load_identity(status.get("repo_id"), status.get("base_repo"), family)
    return outcome


@studio_router.post("/images/generate", response_model = DiffusionGenerateResponse)
@account_access.gpu_busy_route
async def generate_diffusion_image(
    request: DiffusionGenerateRequest,
    http_request: Request,
    current_subject: str = Depends(get_current_subject),
):
    if request.provider_id:
        return await _external_image_generation(request, http_request)
    return await _generate_diffusion_image_core(request)


async def _generate_diffusion_image_core(
    request: DiffusionGenerateRequest,
) -> DiffusionGenerateResponse:
    """The local-engine image run, shared by the route and the chat generate_image tool."""
    from core.inference.diffusion_segment import render_fence

    # From before the run releases the mask segmenter until it ends: a Find cannot reload SAM 3 in the gap before the
    # render takes the engine's generation slot.
    with render_fence():
        return await _generate_diffusion_image_run(request)


async def _generate_diffusion_image_run(
    request: DiffusionGenerateRequest,
) -> DiffusionGenerateResponse:
    from core.inference import image_gallery
    from core.inference.diffusion_engine_router import get_active_diffusion_engine
    from core.inference.diffusion_hires import record_fields as hires_record_fields
    from core.inference.diffusion_families import (
        DIFFUSION_CANCELLED_MSG,
        DIFFUSION_NOT_LOADED_MSG,
        DiffusionModelReplacedError,
        load_identity,
    )

    from core.inference.diffusion_conditioning import LocalizedEdit
    from core.inference.diffusion_memory import (
        IMAGE_REFUSAL_HEADER,
        IMAGE_REFUSAL_MEMORY_ESTIMATE,
        ImageActivationShortfallError,
        unified_memory_refusal_code,
    )
    from core.inference.mlx_diffusion_routing import FallbackLoadRefusedError

    backend = get_active_diffusion_engine()
    if account_access.managed_account():
        await asyncio.to_thread(account_access.require_media_adapters, request)
    # Validate before the render so an unrunnable pass never costs one.
    detailer = (
        await asyncio.to_thread(_detailer_settings, backend, request.detailer)
        if request.detailer is not None
        else None
    )
    # An edit that names no size matches Image 1 in the backend instead of the schema's 1024 square default.
    size_omitted = request.workflow == "edit" and not (
        {"width", "height"} & request.model_fields_set
    )
    localized_edit = (
        LocalizedEdit(mode = request.localized_edit.mode, image = request.localized_edit.image)
        if request.localized_edit is not None
        else None
    )
    submitted = request
    # FLUX.3 prompt upsampling runs ahead of the run, so the sidecar can leave the VRAM before the DiT denoises.
    enhancement = await _enhance_generate_prompts(backend, request)
    if enhancement.status != "applied":
        # A warm start still launching holds the engine's generation slot: a run that is not using the upsampler does
        # not wait it out.
        _cancel_upsampler_warm_start()
    # As the upsampler leaves before the DiT denoises, so does the mask segmenter (Find's SAM 3 on its keep-alive).
    await asyncio.to_thread(_release_mask_segmenter_for_render)
    result = None
    for attempt in range(2):
        request = submitted
        status = None
        expected_load = None
        if account_access.managed_account():
            status = backend.status()
            await asyncio.to_thread(
                account_access.require_media_generation_access, status, "diffusion"
            )
            if status.get("loaded"):
                expected_load = load_identity(
                    status.get("repo_id"), status.get("base_repo"), status.get("family")
                )
        # Omitted steps or guidance follow the loaded model, read again each attempt so a replacement brings its own.
        omitted = {"steps", "guidance"} - request.model_fields_set
        if omitted:
            if status is None:
                status = await asyncio.to_thread(backend.status)
            if status.get("loaded"):
                steps, guidance = await asyncio.to_thread(_image_generation_defaults, status)
                resolved = {"steps": steps, "guidance": guidance}
                request = request.model_copy(update = {key: resolved[key] for key in omitted})
                if expected_load is None:
                    expected_load = load_identity(
                        status.get("repo_id"), status.get("base_repo"), status.get("family")
                    )
            elif expected_load is None:
                # A load in flight would admit this run on its new model with the schema's values.
                # Pin to "nothing loaded" so that model is refused and the retry reads its defaults.
                expected_load = load_identity(None, None, None)
        if enhancement.load is not None:
            # Captions are written for one family: a model swapped in since then retries with fresh ones.
            expected_load = enhancement.load
        # Ahead of the run: milestones key off the previous poll, so a resumed range logs nothing.
        reset_media_generation_progress("image")
        try:
            with account_access.media_generation("diffusion"):
                result = await asyncio.to_thread(
                    backend.generate,
                    expected_load = expected_load,
                    prompt = enhancement.encoded(request.prompt),
                    negative_prompt = request.negative_prompt,
                    width = None if size_omitted else request.width,
                    height = None if size_omitted else request.height,
                    steps = request.steps,
                    guidance = request.guidance,
                    seed = request.seed,
                    batch_size = request.batch_size,
                    prompts = (
                        [enhancement.encoded(p) for p in request.prompts]
                        if request.prompts
                        else request.prompts
                    ),
                    seeds = request.seeds,
                    init_image = request.init_image,
                    mask_image = request.mask_image,
                    strength = request.strength,
                    upscale = request.upscale,
                    reference_images = request.reference_images,
                    workflow = None if request.workflow == "outpaint" else request.workflow,
                    reference_resolution = request.reference_resolution,
                    localized_edit = localized_edit,
                    # Owner only: oversized runs spill into RAM on Windows and can stall the host; env var applies to all
                    allow_oversized = request.allow_oversized
                    and not account_access.managed_account(),
                    loras = [(l.id, l.weight) for l in request.loras] if request.loras else None,
                    controlnet = (
                        (
                            request.controlnet.id,
                            request.controlnet.image,
                            request.controlnet.control_type,
                            request.controlnet.strength,
                            request.controlnet.guidance_start,
                            request.controlnet.guidance_end,
                        )
                        if request.controlnet
                        else None
                    ),
                    **_live_preview_kwarg(backend.generate, request.live_preview),
                    **_sampler_kwargs(backend.generate, request.sampler, request.schedule_type),
                    **_sd_controls_kwargs(backend.generate, request),
                    **_shift_kwargs(backend.generate, request),
                    **_inpaint_mask_kwargs(backend.generate, request),
                    **_hires_kwargs(backend.generate, request),
                )
            break
        except ImageActivationShortfallError as exc:
            # Tagged so the Images page can offer "Generate anyway".
            raise HTTPException(
                status_code = 400,
                detail = str(exc),
                headers = {IMAGE_REFUSAL_HEADER: IMAGE_REFUSAL_MEMORY_ESTIMATE},
            )
        except ValueError as exc:
            raise HTTPException(status_code = 400, detail = str(exc))
        except FallbackLoadRefusedError as exc:
            raise exc.http from exc
        except DiffusionModelReplacedError as exc:
            if attempt > 0:
                raise HTTPException(status_code = 409, detail = str(exc))
            # The caption was written for the replaced model's family.
            enhancement = await _enhance_generate_prompts(backend, request)
            continue
        except RuntimeError as exc:
            # Match these two EXACT client-state messages (409); other RuntimeErrors are failures.
            msg = str(exc)
            if msg in (DIFFUSION_NOT_LOADED_MSG, DIFFUSION_CANCELLED_MSG):
                raise HTTPException(status_code = 409, detail = msg)
            refusal = unified_memory_refusal_code(exc)
            if refusal is not None:
                raise HTTPException(
                    status_code = 400,
                    detail = msg,
                    headers = {IMAGE_REFUSAL_HEADER: refusal},
                )
            logger.error("diffusion.generate_failed: %s", exc, exc_info = True)
            raise HTTPException(status_code = 500, detail = _generate_failure_detail(msg))
        except Exception as exc:
            logger.error("diffusion.generate_failed: %s", exc, exc_info = True)
            raise HTTPException(status_code = 500, detail = _generate_failure_detail(str(exc)))

    global _diffusion_persist_active
    if detailer is not None:
        # The render's active marker is down: hold "active" through the persist so recovery never sees it finished.
        _diffusion_persist_active += 1
        try:
            with account_access.media_generation("diffusion"):
                await asyncio.to_thread(
                    _run_detailer, backend, request, result, enhancement, detailer
                )
        except BaseException:
            _diffusion_persist_active -= 1
            raise

    # Persist each image with its full recipe. BOTH engines batch with a distinct seed per image, returned in ``seeds``, so each is individually reproducible.
    created_at = time.time()
    per_image_seeds = result.get("seeds")
    # A prompts/seeds LIST drives the image count and each image's own seed, so persist those as single-image recipes keyed on that seed.
    list_driven = bool(request.prompts or request.seeds)

    def _persist() -> list[dict]:
        items = []
        for index, image in enumerate(result["images"]):
            seed = (
                per_image_seeds[index]
                if per_image_seeds and index < len(per_image_seeds)
                else result["seed"]
            )
            # A prompts-list batch records each image's OWN prompt so its recipe replays exactly.
            typed_prompt = (
                request.prompts[index]
                if request.prompts and index < len(request.prompts)
                else request.prompt
            )
            items.append(
                (
                    image,
                    {
                        "prompt": typed_prompt,
                        # The caption actually encoded (FLUX.3 prompt upsampling); replaying it with
                        # enhance_prompt=false reproduces the image.
                        "enhanced_prompt": enhancement.caption_for(typed_prompt),
                        "prompt_enhancement": enhancement.status_for(typed_prompt),
                        "negative_prompt": result.get("negative_prompt"),
                        # Persist the ACTUAL output size, not the request sliders: the conditioned workflows derive it from the upload.
                        "width": getattr(image, "width", None) or request.width,
                        "height": getattr(image, "height", None) or request.height,
                        "steps": request.steps,
                        "guidance": request.guidance,
                        "seed": seed,
                        # Base seed the batch launched with. The native engine derives per-image seeds as base + index, so restore replays from this base. A list-driven image carries its OWN seed.
                        "batch_seed": seed if list_driven else result["seed"],
                        # Position within the batch (shared timestamp), so the export filename stays unique.
                        "batch_index": index,
                        # The batch shares one seed, so reproducing a batch_index>0 image needs the original batch_size.
                        "batch_size": 1 if list_driven else request.batch_size,
                        "model": result.get("repo_id"),
                        **({"engine": result["engine"]} if result.get("engine") else {}),
                        # The BUILD the image came off, not just the repo id: a GGUF repo holds many quants, a dense load may be torchao-
                        # quantised, and a bake is not the same build as the adapter-less one. Absent on records written before this existed.
                        "model_kind": result.get("model_kind"),
                        "gguf_filename": result.get("gguf_filename"),
                        "transformer_quant": result.get("transformer_quant"),
                        # Text encoder quant changes conditioning, is often the largest part; memory mode gates torchao TE.
                        "text_encoder_quant": result.get("text_encoder_quant"),
                        "memory_mode": result.get("memory_mode"),
                        "offload_policy": result.get("offload_policy"),
                        "speed_mode": result.get("speed_mode"),
                        "attention_backend": result.get("attention_backend"),
                        "transformer_cache": result.get("transformer_cache"),
                        "cpu_offload": result.get("cpu_offload"),
                        "baked_loras": list(result.get("baked_loras") or []),
                        # The adapters APPLIED to this generation. A baked-but-disabled adapter is recorded above as part of the build instead.
                        "loras": [f"{l.id}:{l.weight:g}" for l in request.loras or []],
                        "controlnet": (
                            f"{request.controlnet.id}:{request.controlnet.control_type}:"
                            f"{request.controlnet.strength:g}"
                            # strength 0 is disabled and skipped before loading/conditioning, so do not claim a ControlNet was applied in the recipe/metadata.
                            if request.controlnet and request.controlnet.strength > 0
                            else None
                        ),
                        # Uploaded images are deliberately not persisted; the client asks for them again on restore.
                        "workflow": (
                            "outpaint"
                            if request.workflow == "outpaint"
                            and result.get("workflow") == "inpaint"
                            else result.get("workflow")
                        ),
                        "strength": request.strength,
                        "upscale": request.upscale,
                        "upscale_model": result.get("upscale_model"),
                        **hires_record_fields(result.get("hires")),
                        "controlnet_guidance": (
                            f"{request.controlnet.guidance_start:g}:{request.controlnet.guidance_end:g}"
                            if request.controlnet and request.controlnet.strength > 0
                            else None
                        ),
                        "reference_image_count": len(request.reference_images or []) or None,
                        # From the engine, not the request: an omitted resolution resolves to the family default.
                        "reference_resolution": result.get("reference_resolution"),
                        "localized_edit": result.get("localized_edit"),
                        "sampler": result.get("sampler"),
                        "schedule_type": result.get("schedule_type"),
                        "prompt_weighting": result.get("prompt_weighting"),
                        "clip_skip": result.get("clip_skip"),
                        "cfg_rescale": result.get("cfg_rescale"),
                        "variation_seed": (
                            result["variation_seeds"][index]
                            if result.get("variation_seeds")
                            and index < len(result["variation_seeds"])
                            else None
                        ),
                        "variation_strength": result.get("variation_strength"),
                        **{
                            key: result[key]
                            for key in (
                                "shift",
                                "base_shift",
                                "max_shift",
                                "embeddings",
                                "mask_blur",
                                "inpaint_only_masked",
                                "inpaint_padding",
                            )
                            if result.get(key) not in (None, [])
                        },
                        **(
                            {"detailer": result["detailer"][index]}
                            if result.get("detailer") and index < len(result["detailer"])
                            else {}
                        ),
                        "created_at": created_at,
                    },
                )
            )
        return list(image_gallery.save_many(items))

    # Hold generate-progress "active" across the persist so a reload mount probe cannot refresh the gallery before these records exist.
    _diffusion_persist_active += 1
    try:
        with account_access.media_generation("diffusion"):
            records = await asyncio.to_thread(_persist)
    except Exception as exc:
        logger.error("diffusion.persist_failed: %s", exc)
        raise HTTPException(status_code = 500, detail = "Failed to save the generated image.")
    finally:
        _diffusion_persist_active -= 2 if detailer is not None else 1

    return DiffusionGenerateResponse(images = [GalleryImage(**r) for r in records])


@studio_router.get("/images/gallery", response_model = GalleryListResponse)
async def list_gallery_images(
    limit: int = 50,
    offset: int = 0,
    archived: bool = False,
    current_subject: str = Depends(get_current_subject),
):
    from pydantic import ValidationError

    from core.inference import image_gallery

    limit = max(1, min(limit, 200))
    offset = max(0, offset)

    # Validate inside the pager so offset/limit/has_more count only valid rows (else scroll stalls).
    def _valid_gallery_image(record: dict) -> bool:
        try:
            GalleryImage(**record)
        except ValidationError:
            return False
        return True

    # Fetch one extra to learn whether more remain, without a second scan.
    records = await asyncio.to_thread(
        image_gallery.list_images,
        limit + 1,
        offset,
        valid = _valid_gallery_image,
        archived = archived,
    )
    has_more = len(records) > limit
    images = [GalleryImage(**r) for r in records[:limit]]
    return GalleryListResponse(images = images, has_more = has_more)


@studio_router.get("/images/gallery/{image_id}/file")
async def get_gallery_image_file(
    image_id: str,
    thumb: Optional[int] = None,
    current_subject: str = Depends(get_current_subject),
):
    """Serve the original PNG or a WebP thumbnail when ``thumb`` is set."""
    from core.inference import image_gallery

    # Ownership-gate the serve like delete/clear: resolve only an Unsloth-owned PNG, so a guessed stem cannot stream out a foreign file.
    path = await asyncio.to_thread(image_gallery.owned_image_path, image_id)
    if path is None:
        raise HTTPException(status_code = 404, detail = "Image not found.")
    # Immutable content (id is unique per image), so let the browser cache it.
    headers = {"Cache-Control": "private, max-age=31536000, immutable"}
    if thumb is not None:
        size = max(32, min(1024, thumb))
        try:
            data = await asyncio.to_thread(image_gallery.thumbnail, path, size)
        except Exception as exc:  # noqa: BLE001 -- fall back to the PNG
            logger.warning("Gallery thumbnail failed for %s: %s", image_id, exc)
        else:
            return Response(content = data, media_type = "image/webp", headers = headers)
    data = await asyncio.to_thread(path.read_bytes)
    return Response(content = data, media_type = "image/png", headers = headers)


@studio_router.post("/search-images/lookup")
async def lookup_search_images(
    payload: SearchImagesLookupRequest, current_subject: str = Depends(get_current_subject)
):
    # Illustrates a finished answer whose model never asked; same lookup as the tool.
    from core.inference import search_images
    from core.inference.tools import IMAGE_SEARCH_DISABLED, _image_search

    if not search_images.search_images_enabled():
        raise HTTPException(status_code = 403, detail = IMAGE_SEARCH_DISABLED)
    raw = await asyncio.to_thread(_image_search, payload.subjects, 20)
    text, images = search_images.split_images_envelope(raw)
    return {"text": text, "images": images}


@studio_router.get("/search-images/{image_id}")
async def get_search_image_thumbnail(
    image_id: str, current_subject: str = Depends(get_current_subject)
):
    # Id-only on purpose: no URL parameter, so this cannot become a generic image proxy.
    from core.inference import search_images

    # fullmatch, as the store does: `$` also matches before a trailing newline.
    if not search_images.IMAGE_ID_RE.fullmatch(image_id or ""):
        raise HTTPException(status_code = 404, detail = "Image not found.")
    data = await asyncio.to_thread(search_images.thumbnail_bytes, image_id)
    if data is None:
        raise HTTPException(status_code = 404, detail = "Image not found.")
    return Response(
        content = data,
        media_type = "image/jpeg",
        headers = {
            "Cache-Control": "private, max-age=86400",
            "X-Content-Type-Options": "nosniff",
            "Content-Disposition": f'inline; filename="{image_id}.jpg"',
        },
    )


@studio_router.post("/images/gallery/{image_id}/move", response_model = GalleryImage)
async def move_gallery_image(
    image_id: str,
    body: GalleryMoveRequest,
    current_subject: str = Depends(get_current_subject),
):
    """Move one image to just after ``after_id``. Dropping among pins pins it, elsewhere unpins it."""
    from core.inference import image_gallery

    try:
        record = await asyncio.to_thread(image_gallery.move, image_id, body.after_id)
    except KeyError:
        # The neighbour left the shelf; the client resyncs.
        raise HTTPException(status_code = 409, detail = "The gallery changed; try the move again.")
    except OSError as exc:
        logger.warning("image_gallery.move_failed: %s", exc)
        raise HTTPException(status_code = 500, detail = "Could not save the new order.")
    if record is None:
        raise HTTPException(status_code = 404, detail = "Image not found.")
    return GalleryImage(**record)


@studio_router.post("/images/gallery/{image_id}/project", response_model = GalleryProjectResponse)
async def add_gallery_image_to_project(
    image_id: str,
    body: GalleryProjectRequest,
    current_subject: str = Depends(get_current_subject),
):
    """Copy one image into a chat project's folder."""
    from core.inference import image_gallery
    from core.inference.gallery_projects import ProjectNotFound, copy_into_project

    path = await asyncio.to_thread(image_gallery.owned_image_path, image_id)
    if path is None:
        raise HTTPException(status_code = 404, detail = "Image not found.")
    try:
        result = await asyncio.to_thread(copy_into_project, path, body.project_id, "images")
    except ProjectNotFound:
        raise HTTPException(status_code = 404, detail = "Project not found.")
    except OSError as exc:
        logger.warning("image_gallery.add_to_project_failed: %s", exc)
        raise HTTPException(status_code = 500, detail = "Could not copy the image into the project.")
    return GalleryProjectResponse(**result)


@studio_router.patch("/images/gallery/{image_id}", response_model = GalleryImage)
async def update_gallery_image_flags(
    image_id: str,
    patch: GalleryFlagsPatch,
    current_subject: str = Depends(get_current_subject),
):
    """Pin/unpin or archive/restore one image. Omitted fields are left alone."""
    from core.inference import image_gallery

    try:
        record = await asyncio.to_thread(
            image_gallery.set_flags, image_id, pinned = patch.pinned, archived = patch.archived
        )
    except OSError as exc:
        # The client applied this optimistically, so a silent miss would undo on reload.
        logger.warning("image_gallery.set_flags_failed: %s", exc)
        raise HTTPException(status_code = 500, detail = "Could not save the change to this image.")
    if record is None:
        raise HTTPException(status_code = 404, detail = "Image not found.")
    return GalleryImage(**record)


@studio_router.delete("/images/gallery/{image_id}")
async def delete_gallery_image(image_id: str, current_subject: str = Depends(get_current_subject)):
    from core.inference import image_gallery

    deleted = await asyncio.to_thread(image_gallery.delete, image_id)
    if not deleted:
        raise HTTPException(status_code = 404, detail = "Image not found.")
    return {"deleted": True}


@studio_router.delete("/images/gallery")
async def clear_gallery_images(current_subject: str = Depends(get_current_subject)):
    from core.inference import image_gallery
    from core.inference.gallery_flags import FlagsUnavailable

    try:
        removed = await asyncio.to_thread(image_gallery.clear)
    except FlagsUnavailable as exc:
        # Refuse rather than delete the archive we cannot prove is archived.
        logger.warning("image_gallery.clear_blocked: %s", exc)
        raise HTTPException(
            status_code = 503,
            detail = "Could not read the gallery's pin/archive data, so clearing was stopped to "
            "avoid deleting archived images.",
        )
    return {"removed": removed}


@studio_router.get("/audio/gallery", response_model = AudioGalleryListResponse)
async def list_gallery_audio(
    limit: int = 50,
    offset: int = 0,
    before_mtime: Optional[float] = None,
    before_id: Optional[str] = None,
    before_pin: Optional[float] = None,
    archived: bool = False,
    current_subject: str = Depends(get_current_subject),
):
    from pydantic import ValidationError

    from core.inference import audio_gallery

    limit = max(1, min(limit, 200))
    offset = max(0, offset)
    if (before_mtime is None) != (before_id is None):
        raise HTTPException(status_code = 400, detail = "Incomplete audio gallery cursor.")
    before = None
    if before_mtime is not None and before_id is not None:
        # A cursor without before_pin (older clients, or an unpinned clip) takes the clip's own rank.
        if before_pin is None:
            before_pin = await asyncio.to_thread(audio_gallery.pin_rank, before_id)
        before = (before_pin, before_mtime, before_id)

    # validate inside the pager so offset, limit and has_more count over the accepted domain
    def _valid_gallery_audio(record: dict) -> bool:
        try:
            AudioGalleryItem(**record)
        except ValidationError:
            return False
        return True

    # fetch one extra to learn whether more remain, without a second scan
    entries = await asyncio.to_thread(
        audio_gallery.list_audio_page,
        limit + 1,
        offset,
        before = before,
        valid = _valid_gallery_audio,
        archived = archived,
    )
    has_more = len(entries) > limit
    visible = entries[:limit]
    audio = [AudioGalleryItem(**record) for record, _ in visible]
    next_cursor = visible[-1][1] if has_more and visible else None
    return AudioGalleryListResponse(
        audio = audio,
        has_more = has_more,
        next_before_mtime = next_cursor[1] if next_cursor else None,
        next_before_id = next_cursor[2] if next_cursor else None,
        next_before_pin = next_cursor[0] if next_cursor and next_cursor[0] > float("-inf") else None,
    )


@router.get("/audio/gallery/{audio_id}/file")
async def get_gallery_audio_file(
    audio_id: str, current_subject: str = Depends(get_current_subject)
):
    from core.inference import audio_gallery

    # ownership-gate the serve like delete/clear, so a guessed stem cannot stream out a foreign file
    path = await asyncio.to_thread(audio_gallery.owned_audio_path, audio_id)
    if path is None:
        raise HTTPException(status_code = 404, detail = "Audio not found.")
    from fastapi.responses import FileResponse

    # immutable content (id is unique per clip), so let the browser cache it
    return FileResponse(
        path,
        media_type = "audio/wav",
        headers = {"Cache-Control": "private, max-age=31536000, immutable"},
    )


@router.get("/audio/gallery/{audio_id}/signed-url")
async def get_gallery_audio_signed_url(
    audio_id: str,
    request: Request,
    current_subject: str = Depends(get_current_subject),
):
    """A key-free link to one clip (bearer-gated to mint, HMAC to use), on the mount called."""
    from auth.authentication import request_admitted_without_credential

    if request_admitted_without_credential(request):
        raise HTTPException(
            status_code = 403,
            detail = "Audio links can only be created from the Unsloth UI or with an API key.",
        )
    from core.inference import audio_gallery

    if await asyncio.to_thread(audio_gallery.owned_audio_path, audio_id) is None:
        raise HTTPException(status_code = 404, detail = "Audio not found.")
    token = _sign_audio_id(audio_id)
    return {
        "url": _v1_url(
            request, f"/api/inference/audio/gallery/{audio_id}/file-signed?token={token}"
        )
    }


@router.get("/audio/gallery/{audio_id}/file-signed")
async def get_gallery_audio_file_signed(audio_id: str, token: str = Query(...)):
    """Serve one clip gated by the HMAC token instead of the bearer. No auth dependency, so the
    token's account is bound with run_as: without it the owner's gallery would resolve."""
    from core.inference import audio_gallery

    account = media_link_account(_verify_audio_link_token(token), audio_id)
    if account is None:
        raise HTTPException(status_code = 401, detail = "Invalid or expired audio link.")
    path = await asyncio.to_thread(run_as, account, audio_gallery.owned_audio_path, audio_id)
    if path is None:
        raise HTTPException(status_code = 404, detail = "Audio not found.")
    from fastapi.responses import FileResponse

    return FileResponse(
        path,
        media_type = "audio/wav",
        headers = {"Cache-Control": "private, max-age=31536000, immutable"},
    )


