def _image_load_preparing_progress() -> Optional[DiffusionLoadProgressResponse]:
    """A load POST of the caller's still in preflight reads as starting: the engine's "ready",
    "error" or null then describes the previous load. Once the engine runs this one, its phase wins."""
    from core.inference.chat_swap_kv import load_preparing

    if not load_preparing("image"):
        return None
    from core.inference.diffusion_engine_router import get_active_diffusion_engine

    if get_active_diffusion_engine().load_progress().get("phase") in ("downloading", "finalizing"):
        return None
    return DiffusionLoadProgressResponse(phase = "downloading")


@studio_router.get("/images/load-progress", response_model = DiffusionLoadProgressResponse)
async def diffusion_load_progress(
    current_subject: str = Depends(get_current_subject),
    via_api_key: bool = Depends(authenticated_via_api_key),
):
    from core.inference.chat_swap_kv import saving_progress

    saving = saving_progress("image")
    if saving is not None:
        return DiffusionLoadProgressResponse(**saving)
    preparing = _image_load_preparing_progress()
    if preparing is not None:
        return preparing
    if account_access.resident_hidden("diffusion"):
        return account_access.hidden_resident_response()
    from core.inference.diffusion_engine_router import get_active_diffusion_engine

    if account_access.managed_account() and account_access.resident_hidden(
        "diffusion", get_active_diffusion_engine().status().get("repo_id")
    ):
        return account_access.hidden_resident_response()
    progress = get_active_diffusion_engine().load_progress()
    log_media_load_progress("image", progress.get("phase"), progress.get("fraction"))
    from hub.utils.host_paths import redact_load_progress

    return DiffusionLoadProgressResponse(**redact_load_progress(progress, via_api_key = via_api_key))


@studio_router.get("/images/generate-progress", response_model = DiffusionGenerateProgressResponse)
async def diffusion_generate_progress(current_subject: str = Depends(get_current_subject)):
    external = _external_image_run_active()

    def _hidden():
        if external:
            return DiffusionGenerateProgressResponse(active = True, target = "connection")
        return account_access.hidden_generate_progress_response(DiffusionGenerateProgressResponse)

    if account_access.managed_account() and account_access.generation_is_foreign("diffusion"):
        return _hidden()
    mine = account_access.generation_is_mine("diffusion")
    if not mine and account_access.resident_hidden("diffusion"):
        return _hidden()
    from core.inference.diffusion_engine_router import get_active_diffusion_engine

    if (
        not mine
        and account_access.managed_account()
        and account_access.resident_hidden(
            "diffusion", get_active_diffusion_engine().status().get("repo_id")
        )
    ):
        return _hidden()

    progress = get_active_diffusion_engine().generate_progress()
    log_media_generation_progress("image", progress)
    if not progress["active"]:
        from core.inference.flux3_prompt_upsampler import progress as upsampler_progress
        enhancing = upsampler_progress()
        if enhancing is not None:
            progress = {
                **progress,
                "active": True,
                "phase": "enhance",
                "message": enhancing.get("message"),
            }
    if external and not progress["active"]:
        progress = {**progress, "active": True, "target": "connection"}
    # A finished generation still persisting its gallery record counts as active, so a reload probe keeps polling.
    if _diffusion_persist_active > 0 and not progress["active"]:
        progress = {**progress, "active": True}
    return DiffusionGenerateProgressResponse(**progress)


@studio_router.post("/images/generate/cancel")
async def cancel_diffusion_generation(
    target: Optional[str] = None, current_subject: str = Depends(get_current_subject)
):
    """Stop the in-flight image generation, mirroring POST /video/generate/cancel.

    Resolved through the engine router, so it stops a diffusers denoise (at its next step
    boundary) and a native sd.cpp run (which kills the sd-cli process tree) alike. The
    generation's OWN request is what reports the outcome: it unwinds with the cancelled
    sentinel, which this module already maps to a 409. ``cancelled`` is False when nothing was
    running, so the page can settle its button back to Generate rather than wait for a
    generation that already finished. ``target=connection`` stops this account's runs on a
    saved image connection instead."""
    if target == "connection":
        return {"cancelled": _stop_external_image_runs()}
    if account_access.generation_is_foreign("diffusion"):
        return {"cancelled": False}
    mine = account_access.generation_is_mine("diffusion")
    if not mine and (
        account_access.foreign_work_active() or account_access.resident_hidden("diffusion")
    ):
        return {"cancelled": False}
    from core.inference.diffusion_engine_router import get_active_diffusion_engine

    if (
        not mine
        and account_access.managed_account()
        and account_access.resident_hidden(
            "diffusion", get_active_diffusion_engine().status().get("repo_id")
        )
    ):
        return {"cancelled": False}

    # A run still upsampling its prompt has not reached the engine yet.
    from core.inference.flux3_prompt_upsampler import cancel_active as cancel_upsampling

    # Both: another tab's request may be enhancing while this one denoises.
    upsampling = cancel_upsampling()
    # A Detailer pass between two inpaints has no denoise for the engine to stop.
    detailer = sys.modules.get("core.inference.diffusion_detailer")
    # The slot can change hands before the executor callback, so the engine rechecks under the lock.
    expected = account_access.tracked_generation_account()
    detailing = bool(detailer is not None and detailer.cancel_active(expected))
    cancel = get_active_diffusion_engine().cancel_generate
    if expected is not None:
        cancel = functools.partial(cancel, expected_account = expected)
    cancelled = await asyncio.get_running_loop().run_in_executor(_CANCEL_EXECUTOR, cancel)
    return {"cancelled": bool(cancelled or upsampling or detailing)}


