@studio_router.post("/images/segment")
@account_access.gpu_busy_route
async def mask_segment(
    request: MaskSegmentRequest, current_subject: str = Depends(get_current_subject)
):
    """A white-on-black mask (PNG data URL, source size) of what ``prompt`` names in ``image``, plus each kept
    instance's box and score. 409 when not downloaded or the image model is busy, 501 without SAM 3 support."""
    from core.inference import diffusion_segment as seg

    account_access.require_idle_other_accounts()
    # Training holds the GPU: the segmenter runs on the CPU rather than beside it. On the GPU the diffusion trainer's
    # admission is held for the call, so a start cannot free the GPU under it.
    allow_gpu = not _training_is_active()
    admission = _diffusion_training_admission() if allow_gpu else nullcontext()
    try:
        with account_access.media_generation("diffusion"), admission:
            body = await asyncio.to_thread(
                functools.partial(
                    seg.segment_image,
                    request.image,
                    request.prompt,
                    threshold = request.threshold,
                    allow_gpu = allow_gpu,
                )
            )
    except seg.SegmenterNotDownloadedError as exc:
        raise HTTPException(status_code = 409, detail = str(exc))
    except seg.SegmenterUnavailableError as exc:
        raise HTTPException(status_code = 501, detail = str(exc))
    except seg.SegmenterBusyError as exc:
        raise HTTPException(status_code = 409, detail = f"{exc} Try again when it finishes.")
    except ValueError as exc:
        raise HTTPException(status_code = 400, detail = str(exc))
    except HTTPException:
        raise
    except Exception as exc:  # noqa: BLE001
        if type(exc).__name__ == "TrainingActiveError":
            # A diffusion training start won the race for the admission.
            raise HTTPException(status_code = 409, detail = str(exc))
        logger.error("images.segment_failed: %s", exc, exc_info = True)
        raise HTTPException(status_code = 500, detail = "Making the mask failed.")
    return JSONResponse(content = body)


# ──────────────────────────────────────────────────────────────────────────

# OpenAI-compatible images API (POST /v1/images/generations). The inference router is mounted at both /api/inference and /v1, so this
# also answers /v1/images/generations for OpenAI clients. The Unsloth Image tab uses the richer /images/generate above; this is the spec shape.
# ──────────────────────────────────────────────────────────────────────────


# Dims must be in [256, 2048] on a multiple of 16; mirrors DiffusionGenerateRequest.
_IMAGE_SIZE_RE = _re.compile(r"^(\d{1,5})\s*x\s*(\d{1,5})$")
_IMAGE_DIM_MIN, _IMAGE_DIM_MAX = 256, 2048
# Sanitized 503 detail shared by the pre-check and the unload-race branch, so both "no image model" responses stay identical.
_NO_IMAGE_MODEL_MSG = "No image model loaded. Load an image model first."


def _parse_openai_image_size(size: str) -> tuple[int, int]:
    """OpenAI ``size`` -> (width, height). ``auto``/empty -> 1024x1024 (~1MP, what
    these models target). Raises ValueError with a client-facing message."""
    text = (size or "").strip().lower()
    if text in ("", "auto"):
        return 1024, 1024
    match = _IMAGE_SIZE_RE.match(text)
    if not match:
        raise ValueError("size must be 'auto' or '<width>x<height>', e.g. '1024x1024'.")
    width, height = int(match.group(1)), int(match.group(2))
    for label, value in (("width", width), ("height", height)):
        if not _IMAGE_DIM_MIN <= value <= _IMAGE_DIM_MAX:
            raise ValueError(f"size {label} must be between {_IMAGE_DIM_MIN} and {_IMAGE_DIM_MAX}.")
        if value % 16 != 0:
            raise ValueError(f"size {label} must be a multiple of 16.")
    return width, height


def _openai_image_dims(body: ImageGenerationRequest) -> tuple[int, int]:
    """(width, height) from ``size``, or from the width/height extension when sent. Raises
    ValueError with a client-facing message."""
    if body.width is None and body.height is None:
        return _parse_openai_image_size(body.size)
    if body.width is None or body.height is None:
        raise ValueError("Send width and height together, or size.")
    dims = _parse_openai_image_size(f"{body.width}x{body.height}")
    if (body.size or "").strip().lower() not in ("", "auto") and (
        _parse_openai_image_size(body.size) != dims
    ):
        raise ValueError("size and width/height disagree; send one of them.")
    return dims


# response_format=url links must be fetchable by whoever received them: a client downloads data[].url with a plain GET
# and no Authorization header, so mint a short-lived HMAC link (1h, like OpenAI) and leave the gallery route bearer-only.
_IMAGE_LINK_TTL = 3600
_IMAGE_LINK_SECRET = _secrets.token_bytes(32)


def _sign_image_id(image_id: str) -> str:
    exp = int(time.time()) + _IMAGE_LINK_TTL
    payload = f"{media_link_target(image_id)}.{exp}"
    sig = _hmac.new(_IMAGE_LINK_SECRET, payload.encode(), _hashlib.sha256).hexdigest()
    return f"{payload}.{sig}"


def _verify_image_link_token(token: str) -> Optional[str]:
    """The image id a valid, unexpired token names, else None. Gallery ids are
    ``[A-Za-z0-9_-]`` so the two dots always split id / expiry / signature."""
    try:
        image_id, exp_s, sig = token.rsplit(".", 2)
    except ValueError:
        return None
    expected = _hmac.new(
        _IMAGE_LINK_SECRET, f"{image_id}.{exp_s}".encode(), _hashlib.sha256
    ).hexdigest()
    if not _hmac.compare_digest(sig, expected):
        return None
    try:
        if int(exp_s) < int(time.time()):
            return None
    except ValueError:
        return None
    return image_id


# Audio gallery links for clients without the bearer (MCP hands them to agents): own secret, so a
# token minted for one media type never serves another. TTL is read at call time.
_AUDIO_LINK_TTL = 3600
_AUDIO_LINK_SECRET = _secrets.token_bytes(32)


def _sign_audio_id(audio_id: str) -> str:
    exp = int(time.time()) + _AUDIO_LINK_TTL
    payload = f"{media_link_target(audio_id)}.{exp}"
    sig = _hmac.new(_AUDIO_LINK_SECRET, payload.encode(), _hashlib.sha256).hexdigest()
    return f"{payload}.{sig}"


def _verify_audio_link_token(token: str) -> Optional[str]:
    """The link target a valid, unexpired audio token names, else None."""
    try:
        target, exp_s, sig = token.rsplit(".", 2)
    except ValueError:
        return None
    expected = _hmac.new(
        _AUDIO_LINK_SECRET, f"{target}.{exp_s}".encode(), _hashlib.sha256
    ).hexdigest()
    # Bytes: compare_digest raises TypeError on a non-ASCII str, a 500 where a bad link owes a 401.
    if not _hmac.compare_digest(sig.encode(), expected.encode()):
        return None
    try:
        if int(exp_s) < int(time.time()):
            return None
    except ValueError:
        return None
    return target


def _absolute_image_url(request: Request, image_id: str) -> str:
    """The absolute, directly fetchable link for one gallery image, on the request's own
    scheme+host. Signed rather than bearer-gated (see above), so a standard image client can
    download it; b64_json still avoids the round trip entirely."""
    relative = (
        f"/api/inference/images/gallery/{image_id}/file-signed?token={_sign_image_id(image_id)}"
    )
    return str(request.base_url).rstrip("/") + relative


@studio_router.get("/images/gallery/{image_id}/file-signed")
async def get_gallery_image_file_signed(image_id: str, token: str = Query(...)):
    """Serve one gallery PNG gated by the HMAC token instead of the bearer, for the
    response_format=url links a plain image client downloads. Same ownership gate as the
    authenticated route, and the token names the single image it may serve."""
    from core.inference import image_gallery

    account = media_link_account(_verify_image_link_token(token), image_id)
    if account is None:
        raise HTTPException(status_code = 401, detail = "Invalid or expired image link.")
    path = await asyncio.to_thread(run_as, account, image_gallery.owned_image_path, image_id)
    if path is None:
        raise HTTPException(status_code = 404, detail = "Image not found.")
    data = await asyncio.to_thread(path.read_bytes)
    return Response(
        content = data,
        media_type = "image/png",
        headers = {"Cache-Control": "private, max-age=31536000, immutable"},
    )


@studio_router.get("/images/gallery/{image_id}/signed-url")
async def get_gallery_image_signed_url(
    image_id: str,
    request: Request,
    current_subject: str = Depends(get_current_subject),
):
    """A key-free link to one gallery PNG (bearer-gated to mint, HMAC to use), relative like the
    video one so it works behind any proxy."""
    from auth.authentication import request_admitted_without_credential

    if request_admitted_without_credential(request):
        raise HTTPException(
            status_code = 403,
            detail = "Image links can only be created from the Unsloth UI or with an API key.",
        )
    from core.inference import image_gallery

    if await asyncio.to_thread(image_gallery.owned_image_path, image_id) is None:
        raise HTTPException(status_code = 404, detail = "Image not found.")
    token = _sign_image_id(image_id)
    return {"url": f"/api/inference/images/gallery/{image_id}/file-signed?token={token}"}


@router.post(
    "/images/generations",
    response_model = ImageGenerationResponse,
    response_model_exclude_none = True,
)
@account_access.gpu_busy_route
async def openai_image_generations(
    body: ImageGenerationRequest,
    request: Request,
    current_subject: str = Depends(get_current_subject),
    hf_token: Optional[str] = Depends(get_hf_token),
):
    """Refused before the row opens, as on /audio/speech: a request rejected before work gets no error row"""
    if body.stream:
        raise HTTPException(
            status_code = 400,
            detail = openai_error_body(
                "Streaming image generation is not supported.", status = 400, param = "stream"
            ),
        )
    if body.response_format != "b64_json":
        from auth.authentication import request_admitted_without_credential
        if request_admitted_without_credential(request):
            raise HTTPException(
                status_code = 403,
                detail = openai_error_body(
                    "URL image responses require an API key. Use response_format='b64_json' for keyless access.",
                    status = 403,
                    param = "response_format",
                ),
            )
    try:
        width, height = _openai_image_dims(body)
    except ValueError as exc:
        raise HTTPException(
            status_code = 400, detail = openai_error_body(str(exc), status = 400, param = "size")
        )
    # Wrap the whole handler: a failure would otherwise leave a raw (possibly path) label on the row.
    async with _monitored_media_request(
        request,
        model = public_model_id(body.model) or body.model,
        prompt = body.prompt,
        subject = current_subject,
    ) as monitor_id:
        return await _generate_openai_images(
            body, request, current_subject, hf_token, monitor_id, width, height
        )


def _image_generation_defaults(status: dict) -> tuple[int, float]:
    """Steps and guidance for the loaded image model: the diffusers recipe when the status reports one, else the family table (sd.cpp and MLX report none). It reads checkpoint headers, so call it off the event loop."""
    from core.inference.diffusion_content import content_variant_hint
    from core.inference.diffusion_families import default_generation_params

    defaults = status.get("generation_defaults")
    if isinstance(defaults, dict) and defaults.get("steps"):
        return int(defaults["steps"]), float(defaults["guidance"])
    # Same order as the load (FLUX.1's base is schnell).
    return default_generation_params(
        status.get("gguf_filename"),
        content_variant_hint(status.get("repo_id"), status.get("gguf_filename")),
        status.get("repo_id"),
        status.get("base_repo"),
    )


async def _batched_openai_images(
    backend: Any,
    status: dict,
    body: ImageGenerationRequest,
    width: int,
    height: int,
    steps: int,
    guidance: float,
    expected_load: Any,
) -> Optional[dict]:
    from core.inference import image_request_batching
    from core.inference.diffusion_engine_router import ENGINE_DIFFUSERS, active_engine_name
    from core.inference.diffusion_families import DIFFUSION_CANCELLED_MSG
    from core.inference.diffusion_flux3 import FLUX3_FAMILY_NAMES
    from core.inference.generation_ticket import (
        GenerationTicket,
        TicketStopEvent,
        generation_ticket,
    )

    holder = getattr(backend, "generation_holder", None)
    if (
        holder is None
        or active_engine_name() != ENGINE_DIFFUSERS
        or status.get("family") in FLUX3_FAMILY_NAMES
    ):
        return None

    ticket = GenerationTicket()
    stopped = TicketStopEvent(ticket)

    # Wait only for the generation found on arrival, so a later one taking the slot cannot starve the batch.
    arrived_behind: list = []

    def busy() -> bool:
        if stopped.is_set():
            raise RuntimeError(DIFFUSION_CANCELLED_MSG)
        try:
            current = holder()
        except Exception:  # noqa: BLE001 -- no busy signal; render individually
            return False
        if current is None:
            return False
        if not arrived_behind:
            arrived_behind.append(current)
        return current is arrived_behind[0]

    async def run_batch(prompts: list[str], seeds: list[int]) -> dict:
        with generation_ticket(ticket):
            try:
                return await asyncio.to_thread(
                    backend.generate,
                    prompt = prompts[0],
                    negative_prompt = body.negative_prompt,
                    width = width,
                    height = height,
                    steps = steps,
                    guidance = guidance,
                    prompts = prompts,
                    seeds = seeds,
                    batch_size = len(seeds),
                    expected_load = expected_load,
                )
            except Exception as exc:
                # An engine Stop sets the bound event, not ``stopped``: no member may retry alone.
                if ticket.cancelled() and not cancelled(exc):
                    raise RuntimeError(DIFFUSION_CANCELLED_MSG) from exc
                raise

    key = (
        current_account_id(),
        expected_load,
        width,
        height,
        steps,
        guidance,
        body.negative_prompt or None,
    )

    def cancelled(exc: BaseException) -> bool:
        return isinstance(exc, RuntimeError) and str(exc) == DIFFUSION_CANCELLED_MSG

    waiter = getattr(backend, "generation_waiter", None)
    with waiter(stopped) if waiter is not None else nullcontext():
        result = await image_request_batching.generate(
            key,
            body.prompt,
            body.n,
            body.seed,
            busy = busy,
            run_batch = run_batch,
            shared_outcome = cancelled,
        )
        # A Stop recorded while the batch ran is final: never fall back to rendering alone or retry.
        if result is None and stopped.is_set():
            raise RuntimeError(DIFFUSION_CANCELLED_MSG)
        return result


# Split out so the monitor row can wrap the whole handler without reindenting it.
async def _generate_openai_images(
    body: ImageGenerationRequest,
    request: Request,
    current_subject: str,
    hf_token: Optional[str],
    monitor_id: Optional[str],
    width: int,
    height: int,
):
    from core.inference import image_gallery
    from core.inference.diffusion_engine_router import get_active_diffusion_engine
    from core.inference.gpu_arbiter import DIFFUSION
    from core.inference.media_auto_switch import maybe_auto_switch_media_model

    # Before the loaded check: the requested model may be the one this brings up.
    await maybe_auto_switch_media_model(
        body.model,
        owner = DIFFUSION,
        current_subject = current_subject,
        openai_errors = True,
        hf_token = hf_token,
    )

    # Use the active engine (diffusers OR native sd.cpp), the same accessor /images/generate uses.
    backend = get_active_diffusion_engine()
    from core.inference.diffusion_memory import ImageActivationShortfallError
    from core.inference.diffusion_families import DiffusionModelReplacedError, load_identity

    # A replacement can commit between status() and generate(): pin the read to the generation and
    # re-decide from fresh state once.
    result = None
    for attempt in range(2):
        status = backend.status()
        if not status.get("loaded"):
            # Mirror /v1/completions and /v1/embeddings, which 503 when their backend is not loaded.
            raise HTTPException(status_code = 503, detail = _NO_IMAGE_MODEL_MSG)

        if account_access.managed_account():
            await asyncio.to_thread(
                account_access.require_media_generation_access, status, "diffusion"
            )

        # An edit-only model needs an input image this API cannot supply; refuse with a 400 rather than a backend 500.
        workflows = status.get("workflows") or []
        if workflows and "txt2img" not in workflows:
            raise HTTPException(
                status_code = 400,
                detail = openai_error_body(
                    "The loaded image model is edit-only (it requires an input image); "
                    "load a text-to-image model to use this endpoint.",
                    status = 400,
                    param = "model",
                ),
            )

        steps, guidance = await asyncio.to_thread(_image_generation_defaults, status)
        steps = steps if body.steps is None else body.steps
        guidance = guidance if body.guidance is None else body.guidance
        expected_load = load_identity(
            status.get("repo_id"), status.get("base_repo"), status.get("family")
        )
        reset_media_generation_progress("image")
        try:
            with account_access.media_generation("diffusion"):
                result = await _batched_openai_images(
                    backend, status, body, width, height, steps, guidance, expected_load
                )
                if result is None:
                    result = await asyncio.to_thread(
                        backend.generate,
                        prompt = body.prompt,
                        negative_prompt = body.negative_prompt,
                        width = width,
                        height = height,
                        steps = steps,
                        guidance = guidance,
                        seed = body.seed,
                        batch_size = body.n,
                        expected_load = expected_load,
                    )
            break
        except DiffusionModelReplacedError:
            if attempt > 0:
                raise HTTPException(
                    status_code = 503,
                    detail = openai_error_body(
                        "The image model was replaced while this request waited; retry with fresh parameters.",
                        status = 503,
                        param = "model",
                    ),
                )
            continue
        except Exception as exc:  # noqa: BLE001 (single boundary, sanitized envelope)
            # A RuntimeError with the model now unloaded means it was evicted mid-call (a race): 503. Every other failure is a real 500 whose raw message must not reach the client.
            if isinstance(exc, RuntimeError) and not backend.is_loaded:
                raise HTTPException(status_code = 503, detail = _NO_IMAGE_MODEL_MSG)
            # Typed: the activation refusal is written for the caller; no other ValueError text escapes.
            if isinstance(exc, ImageActivationShortfallError):
                raise HTTPException(
                    status_code = 400,
                    detail = openai_error_body(str(exc), status = 400, param = "size"),
                )
            logger.error("openai_images.generate_failed: %s", exc)
            raise HTTPException(status_code = 500, detail = _generate_failure_detail(str(exc)))

    # A local-directory load puts the host path in repo_id, and the monitor row is tunnelled.
    _served_repo = str(result.get("repo_id") or "")
    api_monitor.relabel(monitor_id, public_model_id(_served_repo) or _served_repo)
    created = int(time.time())
    want_b64 = body.response_format == "b64_json"
    # Persist each image with its full recipe, like /images/generate, so url links resolve and images show in the gallery.
    recipe = {
        **({"engine": result["engine"]} if result.get("engine") else {}),
        "prompt": body.prompt,
        "negative_prompt": result.get("negative_prompt"),
        "width": width,
        "height": height,
        "steps": steps,
        "guidance": guidance,
        # The batch shares one base seed, so restoring a batch_index>0 sibling needs the original batch_size.
        "batch_size": body.n,
        "model": result.get("repo_id"),
        # Same build record as /images/generate, so the gallery entry can name the GGUF quant and precision.
        "model_kind": result.get("model_kind"),
        "gguf_filename": result.get("gguf_filename"),
        "transformer_quant": result.get("transformer_quant"),
        "text_encoder_quant": result.get("text_encoder_quant"),
        "memory_mode": result.get("memory_mode"),
        "offload_policy": result.get("offload_policy"),
        "speed_mode": result.get("speed_mode"),
        "attention_backend": result.get("attention_backend"),
        "transformer_cache": result.get("transformer_cache"),
        "cpu_offload": result.get("cpu_offload"),
        "baked_loras": list(result.get("baked_loras") or []),
        "workflow": result.get("workflow"),
        "created_at": float(created),
    }
    per_image_seeds = result.get("seeds")

    def _persist() -> list[ImageGenerationData]:
        items: list[ImageGenerationData] = []
        saves = []
        for index, image in enumerate(result["images"]):
            seed = (
                per_image_seeds[index]
                if per_image_seeds and index < len(per_image_seeds)
                else result["seed"]
            )
            # batch_seed is the base the native engine derives per-image seeds from, so restore does not double-advance.
            saves.append(
                (
                    image,
                    {**recipe, "batch_index": index, "seed": seed, "batch_seed": result["seed"]},
                )
            )
        for record in image_gallery.save_many(saves):
            if want_b64:
                encoded = image_gallery.image_b64(record["id"])
                if encoded is None:  # vanished between write and read — fail the call
                    raise RuntimeError("generated image could not be read back for encoding")
                items.append(ImageGenerationData(b64_json = encoded))
            else:
                items.append(ImageGenerationData(url = _absolute_image_url(request, record["id"])))
        return items

    # Same counter as /images/generate: liveness reads it until these records exist.
    global _diffusion_persist_active
    _diffusion_persist_active += 1
    try:
        with account_access.media_generation("diffusion"):
            data = await asyncio.to_thread(_persist)
    except Exception as exc:  # noqa: BLE001
        logger.error("openai_images.persist_failed: %s", exc)
        raise HTTPException(status_code = 500, detail = "Failed to save the generated image.")
    finally:
        _diffusion_persist_active -= 1

    return ImageGenerationResponse(created = created, data = data)
